local config = {
  str_voice_1200501_1 = "Berhenti mengomel, bung! Kau ini sama menyebalkannya dengan pipa Connolly…",
  str_voice_1200501_2 = "Kekerasan di Umbraton punya aturan sendiri, berbeda dari \"permainan adil\" yang dimainkan orang-orang di atas. Shadow Wolf juga pernah bilang begitu. Yah, entahlah.",
  str_voice_1200501_3 = "Meski benci kekerasan, aku tidak keberatan meremuk rahang cecunguk yang menjual Blacohol kepada anak di bawah umur!",
  str_voice_1200501_4 = "Dulu aku juga sering bersikap sembrono saat di Umbraton, tapi masa-masa suram itu telah berlalu. Sekarang aku ingin membangun kembali kampung halamanku.",
  str_voice_1200501_5 = "Sharkfang Island adalah kampung halamanku, tak akan kubiarkan Eclipsite menghancurkannya.",
  str_voice_1200501_7 = "Karena sudah melewati masa sulit bersama-sama, kita ini saudara, 'kan? Apa kita perlu cari kucing untuk dibelai?",
  str_voice_1200501_8 = "Kau harus menghentikanku kalau aku bersikap impulsif! Mematahkan rahang orang itu bukan masalah besar, tapi lain perkara jika bermusuhan dengan banyak orang!",
  str_voice_1200501_9 = "Aku suka kucing, tetapi aku tidak suka kucing yang tampak seperti pria separuh baya, oke? Jadi, jangan sampai aku melakukan operasi dengan pria itu lagi.",
  str_voice_1200501_10 = "Ah! Istirahat spontan—apa aku boleh santai sedikit? Bos, ada banyak kucing di tempatku. Kalau tidak keberatan, maukah kau pergi denganku?",
  str_voice_1200501_11 = "Aku akan menyikat bulu kucing di badanku dulu, lalu aku akan tersenyum kepadamu dan bilang \"cheese\". Sudah kubilang, aku ini benar-benar pencinta damai.",
  str_voice_1200501_12 = "Masih banyak yang harus diperjuangkan dalam hidup ini…",
  str_voice_1200501_13 = "Bos, apa kau sudah lihat kucingku? Entah di mana dia sembunyi. Dia memang agak pemalu.",
  str_voice_1200501_14 = "Apa kau mau bumbu Shark Tooth Powder? Aku punya yang baru, ada banyak.",
  str_voice_1200501_15 = "Bos, ini hari ulang tahunmu? Aku akan menari dengan gergajiku untuk merayakannya!",
  str_voice_1200501_16 = "Bosan juga kalau menganggur seperti ini… Kalau saja aku punya kucing…",
  str_voice_1200501_17 = "Oh, kau lihat gigiku? Maaf, aku tak bermaksud menakutimu.",
  str_voice_1200501_18 = "Sudah saatnya kucing-kucing itu berolahraga!",
  str_voice_1200501_19 = "Enaknya makan malam pakai apa, ya? Kentang goreng atau capun?",
  str_voice_1200501_20 = "Sharkfang Island memang kecil, tapi itulah tempatku, bukan Lumopolis atau Illumina.",
  str_voice_1200501_21 = "Satu-satunya peraturan di Umbraton adalah tidak ada peraturan. Semua warganya memang berandalan…",
  str_voice_1200501_22 = "Bangun kembali Sharkfang Island!",
  str_voice_1200501_23 = "Kalau aku berjumpa dengan bos para Eclipsite, akan kusambut mereka dengan gergajiku.",
  str_voice_1200501_24 = "Kalau bukan karena Istvan, pada akhirnya Umbraton akan menjadi pusaran kekerasan.",
  str_voice_1200501_25 = "Berkat Cloudrover Guild aku bisa membangun kembali kampung halamanku, tapi bos wanita itu benar-benar pedagang yang bejat…",
  str_voice_1200501_26 = "Demi sup sayuran, jus asam, dan roti tanpa ragi favoritku!",
  str_voice_1200501_27 = "Orang-orang yang melampiaskan kekesalannya dengan kekerasan yang tak berarti adalah orang yang paling penuh kebencian. Lalu mungkin mereka menjadi Eclipsite!",
  str_voice_1200501_28 = "Wah, Benda kuno ini benar-benar bisa terbang! Hebat sekali!",
  str_voice_1200501_29 = "Wow! Bos Colossus! Ramai juga di sini! Apa bakal ada perkelahian, ya? Ah, mana mungkin, ini 'kan hari pertamaku di sini!",
  str_voice_1200501_30 = "Mudah-mudahan aku tak akan pernah menggunakan kekuatan ini.",
  str_voice_1200501_31 = "Gergajiku! Putarannya jauh lebih kencang dari sebelumnya!",
  str_voice_1200501_32 = "Cabik musuh kita!",
  str_voice_1200501_34 = "Apa ini klub pecinta kucing?",
  str_voice_1200501_35 = "Sekarang ini bisa dianggap sebagai pertahanan yang pantas.",
  str_voice_1200501_36 = "Kuharap kucing-kucing itu bisa sembunyi tepat waktu—",
  str_voice_1200501_37 = "Berputar!",
  str_voice_1200501_38 = "Hancurkan semuanya sampai berkeping-keping!",
  str_voice_1200501_39 = "Sayat!",
  str_voice_1200501_40 = "Bersiaplah untuk terluka!",
  str_voice_1200501_41 = "Heh? Siapa yang mendorongku barusan?!",
  str_voice_1200501_42 = "Sebegitu saja kemampuan mereka?",
  str_voice_1200501_43 = "Maaf, aku harus pergi. Dah!",
  str_voice_1200501_44 = "Tadinya kupikir ini jam istirahatku… Oke, oke, aku paham…",
  str_voice_1200501_45 = "Kurasa kau salah paham dengan apa yang dimaksud imut.",
  str_voice_1200501_46 = "Hei! Kau juga suka ini?! Eh, tidak, lupakan saja…",
  str_voice_1200501_47 = "Hmm… Ini terasa cukup mahal. Baiklah, akan kuterima saja sekarang.",
  str_voice_1200501_48 = "Oh! Aku bisa memberikannya pada kucingku! Terima kasih!",
  str_voice_1200501_49 = "Jangan macam-macam, ya, atau aku akan mencarimu! Terutama jangan sentuh anak-anakku atau yang lain… Jangan takut, Mimi. Sini, sama ayah!",
  str_voice_1200501_50 = "Jangan kaget kalau melihatku, ya. Banyak orang di kampung halamanku punya kepala hiu seperti aku! Namun, itu sebelum Eclipsite menerobos perbatasan… *Menghela napas*",
  str_voice_1200501_52 = "Alchemy Stars? Apa itu…",
  str_voice_1200501_53 = "Hei, bung!",
  str_voice_1200501_54 = "Aah… Selamat pagi!",
  str_voice_1200501_55 = "Jam berapa sekarang?",
  str_voice_1200501_56 = "Malam baru saja tiba!",
  str_voice_1200501_57 = "Haha! Bagus, sekarang sudah Tahun Baru lagi!",
  str_voice_1300471_1 = "Master Hiiro benar. Kau benar-benar MAU datang ke tempat seperti ini!",
  str_voice_1300471_2 = "Legion Commander pernah bilang bahwa kau adalah orang yang lembut. Tidak, Master Hiiro mana mungkin seperti itu. Aku tidak percaya… Haha… Ehem, maafkan aku…",
  str_voice_1300471_3 = "Quarkium adalah sesuatu yang semula tidak ada di dunia ini, seperti mutiara yang terdampar karena terseret ombak.",
  str_voice_1300471_4 = "Aku bisa merasakan kegelisahan dari balik pintu… Baiklah, aku akan memanfaatkannya.",
  str_voice_1300471_5 = "Apa pada akhirnya aku akan menjadikannya bagian diriku? Quarkium sudah siap, tapi aku…",
  str_voice_1300471_6 = "Kekuatan penuh yang dilepaskan Quarkium sangat hebat, tapi aku tak punya pilihan lain. Aku harus mempelajari cara menguasainya sepenuhnya.",
  str_voice_1300471_7 = "Apa yang kauharapkan? Mungkin aku bisa membantu… Kalau tidak, mungkin aku bisa minta bantuan Vivian?",
  str_voice_1300471_8 = "Aku tahu bagaimana perasaanmu sekarang, dan setelahnya, semua akan kembali seperti semula. Namun, aku tak akan pernah menyerah!",
  str_voice_1300471_9 = "Setelah kembali ke dunia ini, aku menyadari bahwa diriku sudah berubah… Cara Grand Marshal melihatku jadi agak aneh…",
  str_voice_1300471_10 = "Terkadang aku terpesona pada bima sakti. Mungkin Quarkium yang lain akan menembusnya.",
  str_voice_1300471_11 = "Aku belum pernah melakukannya, tapi akan kucoba sebaik mungkin.",
  str_voice_1300471_12 = "Sering kali penelitian dan pertempuran itu berhubungan. Ups! …Aku lupa bahwa kau tidak bisa bertarung.",
  str_voice_1300471_13 = "Jangan pegang. Kendalinya pada Quarkium sangat mudah hilang. Kalau sampai kacau gara-gara kau…",
  str_voice_1300471_14 = "Walaupun aku bukan ahlinya Colossus, tapi apa kau yakin sirkuitnya sudah terhubung dengan benar di sebelah sini?",
  str_voice_1300471_15 = "Selamat ulang tahun! Legion Commander memberitahuku soal ulang tahunmu!",
  str_voice_1300471_16 = "Apa ada penelitian lain untuk ditugaskan hari ini? Akan sempurna kalau ada hubungannya dengan Legion Commander.",
  str_voice_1300471_17 = "Baru saja bangun, ya? Atau kau memang belum tidur?",
  str_voice_1300471_18 = "Siapa pun yang masih bekerja selarut ini adalah teman baik bagi Illumina! Pergilah kalau kau tidak bekerja…",
  str_voice_1300471_19 = "Kau kemari untuk melihat bintang? Yang seperti itu tidak ada apa-apanya kalau dibandingkan dengan Quarkium milikku!",
  str_voice_1300471_20 = "Kami percaya bahwa Illumina melakukan hal yang tepat demi kemanusiaan.",
  str_voice_1300471_21 = "Rediesel Wrench… Kita tidak punya urusan dengan mereka. Setidaknya, begitulah kata Legion Commander.",
  str_voice_1300471_22 = "Jayalah Illumina!",
  str_voice_1300471_23 = "Mereka sangat berbahaya, tapi Quarkium sama sekali tidak peduli. Quarkium akan mengubur mereka semua.",
  str_voice_1300471_24 = "Maksudmu, Hiiro… Legion Commander memperlakukan anak buahnya… Aduh! Pipiku terasa panas!",
  str_voice_1300471_25 = "Vice tidak akan melakukan sesuatu yang akan membuat kita kecewa.",
  str_voice_1300471_26 = "Dia sangat tegas, tapi terkadang juga bisa lembut… Apa? Bukannya kau bertanya soal Master Hiiro?",
  str_voice_1300471_27 = "Jangan menanyakan soal Vice dan Umbraton No. 3. Legion Commander akan marah kalau sampai dia tahu.",
  str_voice_1300471_28 = "Apakah kita punya kekuatan baru yang bisa diandalkan?",
  str_voice_1300471_29 = "Apa ada sesuatu yang layak dipelajari di sini? Tidak masuk akal jika Illumina mengutusku kemari… k-kecuali Master Hiiro juga ada di sini…",
  str_voice_1300471_30 = "Aku bisa merasakan Black Nova baru!",
  str_voice_1300471_31 = "Pintu menuju Nether Sea telah terbuka.",
  str_voice_1300471_32 = "Aku akan memikul beban Quarkium. Aku akan mengendalikannya!",
  str_voice_1300471_33 = "Aku siap…",
  str_voice_1300471_34 = "Kalian semua sudah siap?",
  str_voice_1300471_35 = "Quarkium bertenaga penuh!",
  str_voice_1300471_36 = "Kekuatanku dibutuhkan sekarang!!",
  str_voice_1300471_37 = "Quarkium, berkahi teman-teman kami!",
  str_voice_1300471_38 = "Lelehkan serangan era kegelapan!",
  str_voice_1300471_39 = "Quarkium!",
  str_voice_1300471_40 = "Blacksnow!",
  str_voice_1300471_41 = "Quarkium memandu kita!",
  str_voice_1300471_42 = "Fiuh… eh, apa Master Hiiro mengawasi?",
  str_voice_1300471_43 = "Seperti dugaanku, aku gagal memenuhi harapannya…",
  str_voice_1300471_44 = "Apa orang-orang ini memilih Colossus, atau mereka yang memilihmu?",
  str_voice_1300471_45 = "Zoya suka hadiahmu. Sepertinya kau memilihnya dengan sembarangan.",
  str_voice_1300471_46 = "Aku akan memberikannya kepada Master Hiiro—dia pasti suka!",
  str_voice_1300471_47 = "Ya, kau memang orang yang baik dan murah hati.",
  str_voice_1300471_48 = "Ya, ampun, tidak kusangka… t-terima kasih.",
  str_voice_1300471_49 = "Nether Sea adalah tempat yang indah, tetapi sunyi. Kalau bukan karena Hiiro, aku mungkin akan terus berendam di sana selama-lamanya hingga mati tenggelam. Dia bak cahaya terang yang menyinari malam yang gelap, atau bagaikan bunga sakura yang mekar di tengah musim dingin…",
  str_voice_1300471_50 = "Jika memungkinkan, aku ingin menjelajahi rahasia Netherworld dengan Quarkium karena dunia tak bernyawa itu dulunya sama dengan milik kita. Mungkin nyanyian yang terdengar dari awan adalah satu-satunya petunjuk yang tersisa.",
  str_voice_1300471_52 = "Alchemy—Stars.",
  str_voice_1300471_53 = "Telah terjadi sesuatu!",
  str_voice_1300471_54 = "Selamat malam… Eh, salah, selamat pagi.",
  str_voice_1300471_55 = "Selamat siang, apa kau lihat Master Hiiro?",
  str_voice_1300471_56 = "Kali ini, selamat sore!",
  str_voice_1300471_57 = "Ya sudah. Selamat Tahun Baru!",
  str_voice_1300511_1 = [[
- Aku, kejam? Mm, penglihatan jarak dekatku kabur, tapi mungkin itu cuma karena aku ingin memakanmu.
- Cit cit cuit!]],
  str_voice_1300511_2 = "- Oh…\n- Diam. Jangan menggangguku kalau aku sedang mengecek peluruku, kalau tidak… kutembak kau nanti.\n- Cuit.",
  str_voice_1300511_3 = "Jangan bandingkan aku dengan dua badut itu. Suruh mereka pergi ke Old Capital dan lihat berapa lama mereka bisa bertahan hidup, bodoh!",
  str_voice_1300511_4 = "- Aku harus merawat sahabat terbaikku, tahu… - Sahabat terbaik?\n- Sttt, aku sedang memoles senapanku.",
  str_voice_1300511_5 = [[
- Kami butuh target untuk latihan. Mau jadi targetku?
- Namun, bagaimana kalau nanti aku terluka?
- Yah, bagaimana menurutmu?
- Dasar tidak bertanggung jawab!]],
  str_voice_1300511_7 = "Aku tidak mengamati gadis-gadis itu! Sebagai penembak profesional, mana mungkin aku terganggu oleh hal semacam itu!!",
  str_voice_1300511_8 = [[
- Namun, aku ingin berpartner dengan gadis yang lebih tinggi dariku.
- Apa kau bilang!? Cuit!]],
  str_voice_1300511_9 = "Aku penembak yang tak kenal ampun dan tak mungkin meninggalkan jejak seperti itu, tahu? Semua gara-gara pria ini.",
  str_voice_1300511_10 = "Karena kau sibuk, bagaimana kalau kami yang beres-beres?",
  str_voice_1300511_11 = "Haruskah aku tersenyum? Nanti kau takut. Eh, terserah saja, yang penting aku dibayar.",
  str_voice_1300511_12 = "Bagaimana? Aku kelihatan superkeren kalau dari samping, 'kan? Ini memang foto sempurna dari seorang Mercenary yang sabar, ya?",
  str_voice_1300511_13 = [[
- Ayo main sebuah permainan. Yang kalah akan jadi santapan saat makan malam.
- Kau bercanda, 'kan?]],
  str_voice_1300511_14 = "Dilarang merokok di sini? Memangnya kenapa? Bisa-bisa kau dikuliti dan dijadikan tas wanita kalau ikut campur, Nak.",
  str_voice_1300511_15 = "Ulang tahun? Yah, kalau begitu, selamat ulang tahun. Kau takut dengan senyuman buayaku, ya?",
  str_voice_1300511_16 = "Tugas baru?",
  str_voice_1300511_17 = "Pekerjaan yang membosankan.",
  str_voice_1300511_18 = "Kualitas udara yang buruk! Uhuk, uhuk! Cuit!",
  str_voice_1300511_19 = "Pergi sana. Sekarang Colossus ini jadi milik kami.",
  str_voice_1300511_20 = "- Berisik sekali orang-orang ini. Terkadang kau ingin menembak mereka sampai mati.\n- Eh… Cuit!",
  str_voice_1300511_21 = "Untuk granat, buatan Illumina adalah yang terbaik. Ringan dan ledakannya cukup kuat.",
  str_voice_1300511_22 = "Desperado! Serang!",
  str_voice_1300511_23 = [[
- Umpankan mereka ke sandworm.
- Dalam potongan kecil.]],
  str_voice_1300511_24 = "Semoga berhasil membujuk kami dalam waktu dekat. Lagi pula, perjalananmu untuk mengejar Sinsa masih sangat jauh.",
  str_voice_1300511_25 = [[
- Kuma dan Pengy tidak butuh senapan. Senjata mereka hanya gertakan.
- Oh! Cuit!]],
  str_voice_1300511_26 = "Pelumas berusia 10 tahun dicelupkan ke dalam endapan pistol selama 5 tahun… Lezat.",
  str_voice_1300511_27 = "Sialan, macet lagi! Kurang ajar!",
  str_voice_1300511_28 = "Bagaimana kalau kita tembak dan ledakkan para Eclipsite dengan itu!",
  str_voice_1300511_29 = "Aku Sork, ini Bekk. Kami baru saja bertaruh kapan Eclipsite akan melahapmu. Mau ikut?",
  str_voice_1300511_30 = "Akurasi meningkat!",
  str_voice_1300511_31 = "Ayo kita hias mereka dengan lubang peluru!",
  str_voice_1300511_32 = "Lagi-lagi ada target yang mudah.",
  str_voice_1300511_34 = "Orang-orang yang menjadikan ini sebagai hobi sebaiknya minggir.",
  str_voice_1300511_35 = "Target terkunci.",
  str_voice_1300511_36 = "Dalam posisi.",
  str_voice_1300511_37 = "Tembak!",
  str_voice_1300511_38 = "Masuk dari satu sisi, keluar dari sisi yang lain! Cuit!",
  str_voice_1300511_39 = "Dhuar! Dor!",
  str_voice_1300511_40 = "Giliran kita!",
  str_voice_1300511_41 = "Apa ada yang pengecut? Sekarang giliranmu untuk lari terbirit-birit.",
  str_voice_1300511_42 = [[
- Sesuai dugaan.
- Cuit, cuit!]],
  str_voice_1300511_43 = [[
- Bekk, berlindung di rahangku sekarang!
- Pergi dulu, cuit!]],
  str_voice_1300511_44 = [[
- Berikan hak kami tanpa kurang sepeser pun!
- Cuit!]],
  str_voice_1300511_45 = "Itu saja?",
  str_voice_1300511_46 = "Bagus juga! Aku suka!",
  str_voice_1300511_47 = "Wah, ini sepadan!",
  str_voice_1300511_48 = "Wow… Terima kasih! Cuit!",
  str_voice_1300511_49 = "Ada baiknya tidak perlu khawatir bakal kekurangan amunisi. Namun, kadang aku merindukan masa-masa keluyuran di gurun dan tawar-menawar dengan lintah darat… Trik tawar-menawar? Tidak ada trik sama sekali. Taruh senjatamu di konter, lalu selesai, deh.",
  str_voice_1300511_50 = [[
- Apa yang akan kaulakukan kalau ada Eclipsite datang berbondong-bondong sampai menutupi matahari?
- Tembak saja. Cuit! - Tidak, jelas-jelas seharusnya kau berharap ada lebih banyak Eclipsite, burung bodoh.]],
  str_voice_1300511_52 = [[
- Alchemy.
- Stars! Stars! Stars!]],
  str_voice_1300511_53 = "Halo, cuit!",
  str_voice_1300511_54 = "Cit cit cuit!",
  str_voice_1300511_55 = "Kau sudah bangun?",
  str_voice_1300511_56 = "Apa kau sudah tidur?",
  str_voice_1300511_57 = [[
- Tahun Baru? Yah, Selamat Tahun Baru.
- Cuit!]],
  str_voice_1300521_1 = "Ahhhh, tidaaak! Aku terlambat. Mungkin sebaiknya aku pura-pura sedang sakit. Aduh, pakai alasan apa, ya? Aku sudah pernah bilang sakit gigi…",
  str_voice_1300521_2 = "Kau kenal Eho dari Lumopolis? Kalau aku bekerja sekeras dia, semua buluku bakal rontok! Bekerja di Illumina Division jauh lebih mudah!",
  str_voice_1300521_3 = "Aku benci kalau tertangkap basah. Jangan mencariku terus, dong. Nanti aku jadi merasa bersalah, tahu?",
  str_voice_1300521_4 = "Kau bisa mengatasinya, 'kan? Aku membawa selimut. Boleh aku tidur sekarang?",
  str_voice_1300521_5 = "Aku di sini. Atau tidak. Kaukira aku di mana? Hei, berhenti memukulku!",
  str_voice_1300521_7 = "Semoga Courier Union akan bermurah hati padaku di penilaian tahun ini!",
  str_voice_1300521_8 = "Tunggu dulu, aku punya sesuatu untukmu… Wah, kok tidak ketemu. Lain kali saja, ya.",
  str_voice_1300521_9 = "Hai! Kau lagi! Aku bisa mengobrol denganmu seharian selama kau tidak kemari untuk menyuruhku bekerja!",
  str_voice_1300521_10 = "Berondong jagung yang renyah…",
  str_voice_1300521_11 = "Berhenti! Berhenti! Aku punya banyak pekerjaan! Masih ada banyak surat yang belum kubalas!",
  str_voice_1300521_12 = "Aku pergi dulu… Eh, aku datang lagi… Sekarang aku pergi sungguhan!",
  str_voice_1300521_13 = "Anu… Bos keponakan perempuan sepupuku didenda karena mendaftarkan informasi yang salah kemarin, jadi surat ini…",
  str_voice_1300521_14 = "Ah! Tiba-tiba ada urusan penting, jadi aku harus pergi. Lain kali saja, ya? Maafkan aku!",
  str_voice_1300521_15 = "Ulang tahun? Ohhh, ayo ambil cuti untuk merayakannya!",
  str_voice_1300521_16 = "Apa tadi aku tiba di sini sebelum kau!?",
  str_voice_1300521_17 = "Selop? Aduh, aku tak punya waktu untuk memakainya…",
  str_voice_1300521_18 = "Ah! Aku tidak sedang malas-malasan, kok!",
  str_voice_1300521_19 = "Wajar jika seseorang yang arogan tiba-tiba membatalkan janjinya dan tidak memberi kabar!",
  str_voice_1300521_20 = "Bebas melakukan apa saja itu mengasyikkan, tapi aku tidak akan dibayar kalau seperti itu…",
  str_voice_1300521_21 = "Illumina adalah tempat yang adil! Sepertinya semua orang di sini punya tiga mata… Tak satu pun lolos dari pengamatan mereka…",
  str_voice_1300521_22 = "Courier Union akan mengantarkan suratmu! Atau tidak…",
  str_voice_1300521_23 = "Melawan mereka itu merepotkan… Ayo kita sembunyi dan lari saja…",
  str_voice_1300521_24 = "Lady Vivian? Dia hebat sekali! Keren! Sungguh… Akan tetapi, aku tidak boleh bermalas-malasan…",
  str_voice_1300521_25 = "Pekerjaan Wendy sangat melelahkan. Tidak heran jika dia begitu energik. Kalau jadi dia, aku sudah keluar dari dulu.",
  str_voice_1300521_26 = "Aku hanya bekerja untuk mencari nafkah, jadi rasanya aku dapat untung kalau bermalas-malasan.",
  str_voice_1300521_27 = "Apa aku boleh… bekerja? Atau mengisi presensi kehadiran kerja…",
  str_voice_1300521_28 = "Itu menarik, tapi sepertinya rumit…",
  str_voice_1300521_29 = "Hai, aku Dove. Bilang saja padaku kalau kau ingin mengirim surat. Mungkin aku tidak akan langsung datang, tapi aku akan berusaha sebaik mungkin.",
  str_voice_1300521_30 = "Ohh, aku bisa terbang lebih cepat sekarang!",
  str_voice_1300521_31 = "Saatnya bekerja lagi… Kalian duluan saja, aku akan segera ke sana.",
  str_voice_1300521_32 = "L-lain kali! Pasti aku akan ke sana lain kali!",
  str_voice_1300521_34 = "Selamatkan atau kabur?",
  str_voice_1300521_35 = "Pertunjukan selalu ditutup oleh pemain terhebat!",
  str_voice_1300521_36 = "Aku tidak boleh kabur…",
  str_voice_1300521_37 = "Dove! Ayo kita pergi!",
  str_voice_1300521_38 = "Ada burung merpati dalam bayangan!",
  str_voice_1300521_39 = "M-mencapai batas!",
  str_voice_1300521_40 = "M-minggir!",
  str_voice_1300521_41 = "Gawat… Kalau jadi kapten, aku tidak boleh bermalas-malasan…",
  str_voice_1300521_42 = "Kau pasti bisa! Bertahanlah… Eh?! Sudah selesai?!",
  str_voice_1300521_43 = "Maafkan aku, kakiku… rasanya diisi timah lagi. Aku tak bisa bergerak…",
  str_voice_1300521_44 = "Aku bisa tidur siang dengan nyenyak di sana…",
  str_voice_1300521_45 = "Semoga itu adalah sesuatu untuk membantuku tidur…",
  str_voice_1300521_46 = "Petooooook! Lumayan juga!",
  str_voice_1300521_47 = "Luar biasa! Aku juga bisa melihatnya dalam mimpiku!",
  str_voice_1300521_48 = "M-mulai sekarang, aku tak akan mendadak membatalkan janji denganmu!",
  str_voice_1300521_49 = "Kemalasanku sia-sia saja… tapi bekerja keras juga tidak mengubah apa pun. Kami Pickens Family sudah tidak seperti dulu. Kalau aku dipecat, lalu… sialan, aku tidak bisa membayar uang sewa. Sebaiknya aku bekerja sedikit.",
  str_voice_1300521_50 = "Tentu saja, itu dulu! Hmm, bagaimana, ya? Aku harus tetap hidup! Namun, aku tak bisa meninggalkan mereka… tapi aku juga tak mau mati… tapi mereka…",
  str_voice_1300521_52 = "Alchemy… Stars.",
  str_voice_1300521_53 = "Kau datang?",
  str_voice_1300521_54 = "Tak kusangka aku benar-benar bangun tepat waktu hari ini!",
  str_voice_1300521_55 = "Mau bertemu? Aku tak akan mendadak membatalkannya.",
  str_voice_1300521_56 = "Mau malas-malasan bersama? Aku tak akan mendadak membatalkannya.",
  str_voice_1300521_57 = "Sumpah, aku tak akan tiba-tiba membatalkan janji denganmu di tahun baru.",
  str_voice_1300581_1 = "Seorang kesatria selalu mematuhi… mematuhi… eee… pedoman! Walau baru, aku tetaplah kesatria! Jadi, aku harus mematuhi pedoman!",
  str_voice_1300581_2 = "Dawnhealer adalah bukti kehormatan… Aku berjanji akan mempelajarinya untuk menggunakannya dengan benar dan tidak membuat baju orang lain sobek!",
  str_voice_1300581_3 = "Belajar di Academy, berlatih di Lumo Knights, melakukan presentasi misi dan promosi… Aku tak punya cukup waktu! Tak ada cara untuk mengatasinya!",
  str_voice_1300581_4 = "Mungkin aku tidak cocok bertarung, tapi aku tetap bisa melindungi semua orang! Akan kucoba untuk tidak mengenai kepala kalian!",
  str_voice_1300581_5 = "Di mana pun panji itu berdiri, jiwa menjadi tenang, mata terfokus. Jadi, aku harus menyimpannya! Tunggu! Tidak! Maksudku, aku pasti akan menjaganya tetap tegak!",
  str_voice_1300581_7 = "Mungkin kita berbeda, tapi kita sama-sama pekerja keras… I-iya, 'kan!?",
  str_voice_1300581_8 = "Percayalah, apa pun yang kita lakukan, kita pasti akan dihargai… Sesulit apa pun, pasti berharga!",
  str_voice_1300581_9 = "Berkat dukunganmu… aku jadi semangat untuk bekerja keras! Bahuku mungkin tidak lebar, tapi aku bisa memikul banyak hal!",
  str_voice_1300581_10 = "Terbuang sudah waktu yang berharga… Oh, iya! Aku juga harus berkomitmen penuh untuk beristirahat!",
  str_voice_1300581_11 = "Aku tahu! Kau ingin aku memasang panjinya di sini, 'kan? Iya, 'kan? Tidak? Tidak butuh panji?",
  str_voice_1300581_12 = "Aduh! Tolong jangan menakutiku seperti itu! Sebaiknya kau membuat surat permohonan dulu sebelum muncul lain kali!",
  str_voice_1300581_13 = "Mungkin aku memang gampang gugup, tapi kali ini, aku sudah siap. Aku tidak akan ketakutan… Mungkin!",
  str_voice_1300581_14 = "Bersungguh-sungguh, bekerja keras, dan jangan pernah menyerah! Hmm… Apakah terlalu pendek untuk sebuah moto?",
  str_voice_1300581_15 = "H-hari ini adalah hari ulang tahunmu! Biar kurayakan! Bukan masalah! Aku sudah banyak berlatih, kok!",
  str_voice_1300581_16 = "Saatnya bekerja! Ayo bekerja keras bersama!",
  str_voice_1300581_17 = "Berolahraga di pagi hari itu lebih baik. Terima kasih atas panduanmu. Aku akan berusaha maksimal!",
  str_voice_1300581_18 = "Semuanya harus berjalan sesuai rencana agar kita punya cukup energi setiap hari. Kita akan segera beristirahat!",
  str_voice_1300581_19 = "Kau luar biasa… Kau masih bisa mengikuti latihan di jam selarut ini… A-aku tidak bisa… tertidur!",
  str_voice_1300581_20 = "Suatu kehormatan bisa menjadi anggota Lumo Knights! Aku akan setia selamanya!",
  str_voice_1300581_21 = "Sayang sekali aku masih terlalu muda untuk mengikuti pertukaran terbuka antara Lumopolis dan Illumina saat itu!",
  str_voice_1300581_22 = "Demi White Night!",
  str_voice_1300581_23 = "Eclipsite adalah musuh seluruh benua. Lumopolis akan membinasakan mereka dan menjaga perdamaian!",
  str_voice_1300581_24 = "Kenapa si rambut merah itu memperlakukanku seperti anak-anak, sih? Aku ini 'kan Kesatria!",
  str_voice_1300581_25 = "Aku akan belajar dari Lady Raphael dan bersikap semangat kepada semua orang setiap hari!",
  str_voice_1300581_26 = "Aku suka bekerja keras… Kerja keras tidak akan pernah mengkhianati hasil!",
  str_voice_1300581_27 = "Yang kubenci… Aku benci pemalas dan hal-hal yang menyeramkan…",
  str_voice_1300581_28 = "Brilian! Aku bisa merasakan kebijaksanaan para pendahulu kita! Mereka pasti bekerja keras untuk membangun Colossus ini!",
  str_voice_1300581_29 = "Senang bertemu denganmu! Suatu kehormatan… aduh… bisa berada di sini… Mulai hari ini, aku akan menjadi panji yang memimpin jalanmu!",
  str_voice_1300581_30 = "Perkembangan adalah hadiah terbaik!",
  str_voice_1300581_31 = "Sekarang aku sudah layak dan mampu!",
  str_voice_1300581_32 = "Aku bisa melihat cahaya yang lebih terang pada panji!",
  str_voice_1300581_34 = "Panjinya ada padaku!",
  str_voice_1300581_35 = "Hah? Menggunakan panji? Sekarang?",
  str_voice_1300581_36 = "A-aku sudah siap!",
  str_voice_1300581_37 = "Banner of Light, lindungi kami!",
  str_voice_1300581_38 = "Ini adalah berkah fajar!",
  str_voice_1300581_39 = "Semoga berhasil!",
  str_voice_1300581_40 = "Menuju harapan!",
  str_voice_1300581_41 = "A-aku akan memimpin mereka!",
  str_voice_1300581_42 = "Oh, luar biasa! Benar-benar berhasil!",
  str_voice_1300581_43 = "Eh? A-apa aku melakukan kesalahan?",
  str_voice_1300581_44 = "Latihan dengan rajin lagi hari ini!",
  str_voice_1300581_45 = "Aku hanya agak terkejut.",
  str_voice_1300581_46 = "Bisakah aku… benar-benar menerimanya? Sungguh?",
  str_voice_1300581_47 = "Ini hadiah untukmu!",
  str_voice_1300581_48 = "A-aku benar-benar menginginkannya! Terima kasih!",
  str_voice_1300581_49 = "Aku cukup beruntung mengikuti Lady Gabriel setelah menjadi kesatria. Dia sangat baik kepadaku dan mengajariku pentingnya bekerja keras!",
  str_voice_1300581_50 = "Dalam krisis yang mengerikan itu, Lumopolis menjadi kacau. Untungnya, White Night menjawab panggilanku dan memberiku Banner of Light.",
  str_voice_1300581_51 = "Aku akan bekerja keras selagi masih bisa! Ada banyak orang yang kehilangan peluang di dunia!",
  str_voice_1300581_52 = "Al-alchemy Stars!",
  str_voice_1300581_53 = "H-halo!",
  str_voice_1300581_54 = "Selamat pagi!",
  str_voice_1300581_55 = "Selamat sore!",
  str_voice_1300581_56 = "Selamat malam!",
  str_voice_1300581_57 = "Selamat Tahun Baru!",
  str_voice_1300591_1 = "Kabarnya, diam-diam kau ini kaya raya… Eh, apa? Tidak? Dasar pembohong! Kok kau bisa keren begini padahal tidak punya uang? Lihat saja putri Lumopolis itu, dia benar-benar mengagumkan. Sungguh.",
  str_voice_1300591_2 = "Apa kau tidak takut dengan perempuan agresif? Mungkin rambutnya pirang dan dia menyebutmu imut… hiks…",
  str_voice_1300591_3 = "Kenapa Eclipsite yang kuat itu mengejarmu selama ini? Kau ini pangeran dari suatu tempat atau bagaimana, sih? Maksudku, Colossus itu bagaikan kuda putih yang kau naiki. Sungguh!",
  str_voice_1300591_4 = "Oh, serangan terberatku berasal dari… s-s-syal ini… Ya, syal, sungguh… Aduh, malah terbelit… Mengganggu saja…",
  str_voice_1300591_5 = "Jadi, bagaimana cara mendapatkan Speaker? Pasti tidak bisa dapat promosi di Courier Union kalau tidak punya Speaker. Apa tidak ada latihan untuk itu? Menangkapnya sendiri? Mana mungkin…",
  str_voice_1300591_7 = "Maaf, aku tak sengaja merusakkan kompasnya… Cadangan? Eh, itu yang kurusakkan dua hari lalu? Eh, anu, kau tidak tahu cara mengemudi? Kalau begitu, kau tidak butuh kompas. Sungguh.",
  str_voice_1300591_8 = "Kenapa banyak orang mengikutimu…? Aku hanya mengikutimu agar tahu apa istimewanya dirimu!",
  str_voice_1300591_9 = "Aku iri karena orang-orang selalu berada di dekatmu, padahal kau tak punya pengaruh sama sekali… Oke, oke, kau ini memang lebih penting. Sungguh.",
  str_voice_1300591_10 = "Kenapa kau selalu dalam bahaya dan dikelilingi oleh Eclipsite? Yakin bukan kau yang cari masalah sendiri?",
  str_voice_1300591_11 = "Tunggu, akan kucari pesanannya. Aku yakin sudah menaruhnya di kotak kemarin… Eh? Aku pelupa? Aku memang diatur begitu…",
  str_voice_1300591_12 = "Suatu hari, aku ingin… meminta seseorang terbang dan menunjukkan kepadamu sayap sungguhan… Karena aku tidak punya sayap.",
  str_voice_1300591_13 = "Bukan burung kerja! Tapi, burung gereja! Kenapa sih orang-orang tidak bisa melafalkannya? Aneh sekali kedengarannya! Sungguh!",
  str_voice_1300591_14 = "Aku hidup sendiri. Aku hidup bersama keluargaku sebelumnya, tapi tiba-tiba, kami… semua berpencar.",
  str_voice_1300591_15 = "Aku benar-benar tidak lupa, kok. Aku sudah menyiapkan hadiahnya kemarin dan… Anu, lupa membawanya.",
  str_voice_1300591_16 = "Selamat datang kembali. Tidak banyak yang bisa kulakukan sendirian, jadi aku menunggumu.",
  str_voice_1300591_17 = "Aku mungkin meninggalkan perintah pengiriman di kamar tidur… Tunggu, semalam aku tidur di mana, ya?",
  str_voice_1300591_18 = "Oh, aku hanya membuat daftar tugas dan harus bekerja cukup keras. Sungguh.",
  str_voice_1300591_19 = "Kau tidak mau istirahat? Sungguh? Namun, masih bangun dan beraktivitas di jam selarut ini benar-benar mengagumkan.",
  str_voice_1300591_20 = "Courier Union bahkan mencari orang biasa seperti aku. Rasanya aku ini sangat diberkati.",
  str_voice_1300591_21 = "Mempertahankan pekerjaan berarti bertahan dengan si penerima berambut pirang yang mengerikan itu. Pokoknya menyeramkan sekali. Sungguh.",
  str_voice_1300591_22 = "Kami selalu mengantar. Sungguh.",
  str_voice_1300591_23 = "Kau lihat rahang mereka yang menganga? Bisa melahap burung gereja dalam sekali gigit. Sungguh! *endus* Menyeramkan…",
  str_voice_1300591_24 = "Dia? Misil lonjong? Dia lebih cocok jadi bola karena cukup gendut.",
  str_voice_1300591_25 = "Sudah menjadi sifat Dove untuk mendadak membatalkan janjinya denganku. Lihat saja dia mendekut seperti merpati.",
  str_voice_1300591_26 = "Untuk sekali saja, biarkan aku tinggal di suatu tempat yang aman… Kadang aku hanya iri dengan hal-hal yang luar biasa.",
  str_voice_1300591_27 = "Aku benar-benar tidak bisa berurusan dengan hal-hal aneh. Sangat mengganggu dan menakutkan…",
  str_voice_1300591_28 = "Colossus? Kali pertama aku melihatnya. Lehernya panjang, pucat, dan tak berambut… Aneh sekali. Sungguh.",
  str_voice_1300591_29 = "Wow, kalian sungguh-sungguh mengesankan! Aku, seperti, cuma penggembira… Tunggu, jangan tinggalkan aku, ayolah!",
  str_voice_1300591_30 = "Wah, perasaan apa ini?!",
  str_voice_1300591_31 = "Anu, bagaimana, ya?",
  str_voice_1300591_32 = "Seperti evolusi?! Oh, masih cukup biasa.",
  str_voice_1300591_34 = "Iya, iya. Aku datang, sungguh.",
  str_voice_1300591_35 = "Aku AKAN berusaha, mungkin.",
  str_voice_1300591_36 = "Hei, apa kau hanya melihat-lihat?",
  str_voice_1300591_37 = "Tetap semangat, sampai jumpa… Aku tidak boleh pergi?",
  str_voice_1300591_38 = "Wow! Nyaris saja! Waktunya pergi… Aku selambat itu, ya?!",
  str_voice_1300591_39 = "Apa itu, api?",
  str_voice_1300591_40 = "Api yang sangat merepotkan!",
  str_voice_1300591_41 = "Aku yang memimpin? Sungguh? Serius, nih?",
  str_voice_1300591_42 = "Sudah selesai. Bukannya kita seharusnya mengambili rampasan sekarang?",
  str_voice_1300591_43 = "Kita kalah… Namun, tidak apa-apa, kita masih hidup!",
  str_voice_1300591_44 = "Oke, oke, aku bakal diam… Memangnya kau yakin ingin aku diam, nih? Apa kau tidak akan kesepian nanti?",
  str_voice_1300591_45 = "Wah, dari mana kau dapat itu? Rasanya sedikit aneh…",
  str_voice_1300591_46 = "Hadiah yang bagus untuk orang biasa seperti aku? Rasanya aku mau menangis…",
  str_voice_1300591_47 = "Eh… Sebenarnya, aku tidak terlalu menyukainya. Kau tahu, 'kan?",
  str_voice_1300591_48 = "Kebaikanmu pada orang biasa seperti aku membuatku tersentuh. Sungguh…",
  str_voice_1300591_49 = "Apa yang kau bilang barusan? Wow! Kau menulis profil untuk semua orang? Itu kedengaran merepotkan. Serius… Eh, jangan marah, tapi apa maksudnya entri \"Objek Rusak\" ini?",
  str_voice_1300591_50 = "Seseorang memberiku syal. Memangnya ada cara lain seekor burung gereja biasa mendapat artefak dahsyat seperti itu… Biar kuulangi, dahsyat!",
  str_voice_1300591_52 = "Lihat, Alchemy Stars!",
  str_voice_1300591_53 = "Pasti ada sesuatu. Sungguh!",
  str_voice_1300591_54 = "Selamat pagi. Sungguh!",
  str_voice_1300591_55 = "Selamat sore. Sungguh!",
  str_voice_1300591_56 = "Selamat malam. Sungguh!",
  str_voice_1300591_57 = "Selamat Tahun Baru. Sungguh!",
  str_voice_1300741_1 = "Aku hanya ingin menyendiri… kalau memungkinkan…",
  str_voice_1300741_2 = "Bahkan Matahari pun akan menggelap, runtuh, dan terlahir kembali… Lagi dan lagi.",
  str_voice_1300741_3 = "Semoga kita bisa menemukan kedamaian abadi sebelum kegelapan tiba…",
  str_voice_1300741_4 = "Kata-kata Kakak Sekar selalu menenangkanku… Seperti kata-kata yang keluar dari mulutku.",
  str_voice_1300741_5 = "Kau sudah membantuku berkembang pesat… Terima kasih. Rasanya nyaman… dan hangat.",
  str_voice_1300741_6 = "Mungkin suatu hari nanti aku bisa mencari cara untuk melupakan mimpi burukku…",
  str_voice_1300741_7 = "Kau tertarik padaku? Maaf sudah mengecewakanmu…",
  str_voice_1300741_8 = "Aku… aku tidak pantas kau perhatikan atau pedulikan… Masa laluku kelam…",
  str_voice_1300741_9 = "Terima kasih, Navigator. Seperti Sekar, aku merasa aman di dekatmu. Andai saja ini bisa begini selamanya…",
  str_voice_1300741_10 = "Mereka seperti aku… sebuah cangkang yang tertutup… dan sebuah inti yang gelap dan dingin.",
  str_voice_1300741_11 = "Aku tidak suka tempat ini… Bolehkah aku kembali ke sudutku? Namun, apa boleh buat kalau kau bersikeras…",
  str_voice_1300741_12 = "Di mana Sekar? Tidak ada apa-apa… Hanya bertanya…",
  str_voice_1300741_13 = "… Aku tidak punya pilihan waktu itu… Namun sekarang… sudah terlambat, 'kan?",
  str_voice_1300741_14 = "Mereka… selalu mengalami putaran peluruhan yang cepat… Jauh lebih energik daripada aku.",
  str_voice_1300741_15 = "… Kuharap kau bisa melupakan semua hal buruk yang terjadi hari ini… dan semoga kehangatan selalu menyertaimu.",
  str_voice_1300741_16 = "Ya. Aku masih di sini, tidak ke mana-mana.",
  str_voice_1300741_17 = "Kita bertemu lagi, setelah terang kembali.",
  str_voice_1300741_18 = "Semoga kita bisa menemukan… sudut masing-masing sebelum terang meredup.",
  str_voice_1300741_19 = "Tidak bisa tidur? Kalau kau juga dihantui mimpi buruk, berarti kita punya kesamaan.",
  str_voice_1300741_20 = "Illumina merawatku… tapi aku bisa bertarung. Aku tidak butuh simpati dan belas kasihan.",
  str_voice_1300741_21 = "Aku sendiri tidak paham. Kalau harus kujelaskan… Aku benci melihat kota putih itu.",
  str_voice_1300741_22 = "Jayalah… Illumina.",
  str_voice_1300741_23 = "Seperti makhluk-makhluk dalam mimpi burukku, kalau bisa menghancurkan mereka… kurang lebih aku bisa menebus dosa-dosaku.",
  str_voice_1300741_24 = "Sekar bertanggung jawab untuk menangani konseling psikiatri di Illumina. Dia selalu membantuku meredakan stres.",
  str_voice_1300741_25 = "Teman-teman… tidak juga, tapi Benny dan Curo adalah… rekan yang penting dalam Legion.",
  str_voice_1300741_26 = "Lebih baik sendirian… Aku lebih suka kalau merasa aman.",
  str_voice_1300741_27 = "Mimpi buruk dan masa lalu bukan milikku… Aku membencinya.",
  str_voice_1300741_28 = "Aku jadi gelisah… Mungkin karena terbang tinggi di langit.",
  str_voice_1300741_29 = "…Tentang aku? …Aku White Dwarf. Hanya itu saja. Aku… aku ingin menyendiri untuk sesaat.",
  str_voice_1300741_30 = "Aku ingin menjadi lebih kuat.",
  str_voice_1300741_31 = "… Apakah level peningkatan benar-benar ada artinya?",
  str_voice_1300741_32 = "Kau lihat yang barusan itu, Sekar?",
  str_voice_1300741_33 = "Masa lalu bukan kutukanku, tapi berkah yang membantuku berkembang.",
  str_voice_1300741_34 = "Apa yang bisa kubantu…?",
  str_voice_1300741_35 = "Aku… tidak tahan lagi…",
  str_voice_1300741_36 = "Harus… dilampiaskan!",
  str_voice_1300741_37 = "Runtuh dilahap gaya gravitasi—",
  str_voice_1300741_38 = "Tunduklah kepada gravitasi yang dahsyat!",
  str_voice_1300741_39 = "M-menyingkir dari hadapanku!",
  str_voice_1300741_40 = "Enyahlah!",
  str_voice_1300741_41 = "… Aku benar-benar tidak pandai dalam jaringan sosial.",
  str_voice_1300741_42 = "Pelampiasannya… sudah cukup…",
  str_voice_1300741_43 = "Aku tidak kesakitan lagi… Mungkinkah…",
  str_voice_1300741_44 = "Aku hanya bengong. Berhenti menatapku…",
  str_voice_1300741_45 = "Hm. Apa aku perlu berterima kasih?",
  str_voice_1300741_46 = "… Menarik.",
  str_voice_1300741_47 = "Eh… Tidak perlu…",
  str_voice_1300741_48 = "Oh, aku jadi ceria lagi…",
  str_voice_1300741_49 = "Maaf jika kemurunganku membuatmu sedih… Aku sendiri tidak bisa mengendalikannya… Ini bagaikan gangguan dalam kesadaranku.",
  str_voice_1300741_50 = "Mimpi buruk, masa lalu… bahkan kenangan yang bukan milikku… Kenapa mereka bergegas menghampiriku? Apa yang dikatakan ibuku benar?",
  str_voice_1300741_51 = "Baiklah, aku akan sangat menghargai teman-temanku di Illumina, tapi aku harus mencari sumber mimpi burukku dan kebenaran tentang kisah ibuku…",
  str_voice_1300741_52 = "Alchemy… Stars.",
  str_voice_1300741_53 = "…Anu…",
  str_voice_1300741_54 = "… Selamat pagi.",
  str_voice_1300741_55 = "… Selamat sore.",
  str_voice_1300741_56 = "… Selamat malam!",
  str_voice_1300741_57 = "Selamat… Tahun Baru.",
  str_voice_1300801_1 = "M-maukah kau duduk? Aku akan… tidak… Assistant akan membuatkanmu teh. Mau apa lagi?",
  str_voice_1300801_2 = "Aduh! Kau membuatku ketakutan! Buku? Eh, aku sedang membaca 20 Panduan Sosial untuk Anggota Illumina. Aku mendapat rekomendasi dari Chandra…",
  str_voice_1300801_3 = "Kaas, kereta kargo di Illumina… Mungkin terlihat berat dan lucu, tapi… untuk penambangan skala besar… sangat praktis.",
  str_voice_1300801_4 = "Berapa banyak… Assistant… yang kupunya? D-dua puluh tiga. Kau bisa hitung sendiri, 'kan?",
  str_voice_1300801_5 = "Ini bukan sekadar masalah kekuatan tempur… Aku… ingin meningkatkan kemampuan sosialku. Andai saja… andai aku bisa mencapai level Lilliam…",
  str_voice_1300801_6 = "Aku rindu… rumah… Aku merasa… kesepian… Namun, Assistant… sangat ramah… seperti semua orang di lab.",
  str_voice_1300801_7 = "Mereka tak bisa melihatku… Tak bisa… melihatku…",
  str_voice_1300801_8 = "Tatap mata orang lain… ambil napas dalam-dalam, tarik napas… kontak fis… fisik? Argh! Aku tidak bisa melakukannya!!",
  str_voice_1300801_9 = "Walaupun aku masih… takut… Sepertinya berkomunikasi denganmu… tidak sesulit itu.",
  str_voice_1300801_10 = "Masih ada pekerjaan… Bagaimana kalau kita bermalas-malasan sebentar… Tidak, tidak!",
  str_voice_1300801_11 = "Tolong, jangan aku, jangan aku, jangan aku… Aaaaaah, apa yang sebaiknya kulakukan sekarang?",
  str_voice_1300801_12 = "Ayo salaman… eh… dengan Assistant tentu saja!",
  str_voice_1300801_13 = "Luminite berasal dari Lumamber yang terurai. Tidak mudah menggalinya…",
  str_voice_1300801_14 = "Memprediksi perilaku orang lain atau cakupan dan topik pembicaraan itu sulit sekali. Ah…",
  str_voice_1300801_15 = "Selamat ulang tahun, selamat ulang tahun… Fiuh, aku sudah mencapai batas!",
  str_voice_1300801_16 = "K-kekerasan material mengacu pada ketahanan terhadap objek… lain… Ah, kau rupanya!",
  str_voice_1300801_17 = "S-sarapan siap! Assistant milikku sangat… pintar memasak sarapan.",
  str_voice_1300801_18 = "Saatnya m-makan malam! Apa m-menu di kantin… hari ini, ya?",
  str_voice_1300801_19 = "Saatnya tidur! Kalau tidak… nanti tubuhmu tidak akan bertambah tinggi. Aku sendiri… sudah cukup pendek.",
  str_voice_1300801_20 = "Faktanya, skema kolektivisasi Illumina… memiliki banyak keuntungan… di lingkungan saat ini.",
  str_voice_1300801_21 = "Rediesel Wrench… memiliki banyak teknik kasar, tua, dan… aneh yang… layak dipelajari.",
  str_voice_1300801_22 = "Illumina… Spe-Spero!",
  str_voice_1300801_23 = "Eclipsite! Menjauhlah dariku! Tolong, Assistant!",
  str_voice_1300801_24 = "Sebenarnya, aku tidak pandai dalam permainan… Namun, Gronru akan mengundangku.",
  str_voice_1300801_25 = "Other End itu keren sekali, 'kan? Itu milik Charon? Hah? Siapa itu?",
  str_voice_1300801_26 = "Astagaaaa… Kau juga suka model pesawat? Model terbaru dari Other End memang luar biasa.",
  str_voice_1300801_27 = "Lembap sekali! Semua Assistant punyaku bakal karatan, nih.",
  str_voice_1300801_28 = "Wooow! Colossus!!! Aku… aku harus membuat catatannya! K-keren sekali!",
  str_voice_1300801_29 = "Tidak, tidak, tidak… Kumpulkan keberanianmu, Unimet! S-senang… bertemu denganmu! Aku petugas pemeliharaan mesin Illumina #$!#%…$…",
  str_voice_1300801_30 = "Tes… berhasil!",
  str_voice_1300801_31 = "Assistant, kau akan makin terampil jika makin sering menggunakannya.",
  str_voice_1300801_32 = "Bahkan jika peluangnya sangat kecil, aku… harus berhasil.",
  str_voice_1300801_34 = "M-melapor!",
  str_voice_1300801_35 = "Kita boleh melanjutkan.",
  str_voice_1300801_36 = "Proyek telah… terkonfirmasi.",
  str_voice_1300801_37 = "Operasi yang tepat.",
  str_voice_1300801_38 = "Pekerjaan yang sempurna.",
  str_voice_1300801_39 = "Operasi… terkoordinasi.",
  str_voice_1300801_40 = "Strategi… ahli.",
  str_voice_1300801_41 = "Memimpin orang lain itu… sangat sulit.",
  str_voice_1300801_42 = "Di mana Lumamber itu? Di mana?",
  str_voice_1300801_43 = "Apa ada orang? Tolong aku… Tolong %*…&&*",
  str_voice_1300801_44 = "A-akhirnya! Sebuah m-m-momen brilian!",
  str_voice_1300801_45 = "Terima kasih…",
  str_voice_1300801_46 = "Aku menyukainya… Seharusnya aku tidak bilang… Ehem…",
  str_voice_1300801_47 = "Terima kasih banyaaak…",
  str_voice_1300801_48 = "Oh, ini…!! Ehem… Permisi.",
  str_voice_1300801_49 = "Aku sudah mencoba… berinteraksi dengan orang lain, tapi tidak… berhasil. Aku tidak paham… Aku tak punya teman, tak bisa membaca… situasi. Untungnya, aku masih punya Assistant.",
  str_voice_1300801_50 = "Mungkin… aku masih belum tahu… cara berkomunikasi dengan orang lain… Semua orang di Illumina… bilang bahwa aku tak perlu terlalu memikirkannya, dan menjadi diri sendiri saja.",
  str_voice_1300801_52 = "Alchemy Stars.",
  str_voice_1300801_53 = "Yang ini.",
  str_voice_1300801_54 = "Selamat pagi.",
  str_voice_1300801_55 = "$% Maaf, salah pencet. Anu…",
  str_voice_1300801_56 = "Ini lebih baik ketimbang bicara secara langsung…",
  str_voice_1300801_57 = "Semoga Tahun Baru… Tahun Baru… lebih seru.",
  str_voice_1300821_1 = "Biar kubantu membawa peti-peti itu. Apa isinya? Macam-macam material, ya? Lupakan saja, aku cukup kuat membawanya. Hehe!",
  str_voice_1300821_2 = "Aku pernah tak sengaja bertemu dengan Yang Mulia Ratu dan beliau berkata bahwa aku merusak penghalang sihirnya atau apalah… Apa beliau marah, ya…",
  str_voice_1300821_3 = "Kalau ingin permata, kau harus memikul beratnya… Namun, aku tak mau tanduk sebesar ini! Dulu bentuknya kecil dan imut… tapi sekarang…",
  str_voice_1300821_4 = "Tatap sinar hijau ini kalau kau ingin mengistirahatkan matamu. Oh, tunggu! Biar kuatur dulu! Sebentar, ya!",
  str_voice_1300821_5 = "Coba kuingat yang terbaik… oh, benar! Salju, pohon pinus, dan angin bulan Mei di Northland. Semoga kau bangkit dan makmur!",
  str_voice_1300821_7 = "Maaf, menanyakan berat tandukku itu tidak sopan… Oh, maaf, kau boleh lihat, tapi tolong jangan pegang, ya!",
  str_voice_1300821_8 = "Sepertinya menarik juga kalau bersamamu!… Pasti begitu! Hehe. Tidak apa-apa. Aku hanya akan memperhatikan.",
  str_voice_1300821_9 = "Aku punya bintang yang bersinar di dahiku… Kau tidak punya, ya? Sebenarnya aku ingin memberimu satu saat kita pertama kali bertemu dulu!",
  str_voice_1300821_10 = "Ini bukan tanduk, tapi ranting yang bisa dilepas. Lihat, 'kan? Hmm… Ha! Kena, deh!",
  str_voice_1300821_11 = "Posisi yang penting… Semoga lebih baik lain kali? Hah? Harus, ya? Sebaiknya aku bagaimana? Duduk atau berdiri saja? Apa sebaiknya aku… bersinar?",
  str_voice_1300821_12 = "Serpih salju yang masih segar… Mau mencicipinya? Rasanya dingin dan… Ya! Noah yang membuatnya!",
  str_voice_1300821_13 = "Kumohon… Jangan pegang tandukku… Ini berbahaya. Kita berdua bisa celaka!",
  str_voice_1300821_14 = "Bagaimana ini? Yang itu bagus, tapi yang ini juga bagus… Aku bingung!",
  str_voice_1300821_15 = "Hadiahnya adalah berkah sinar hijau yang cantik ini! Ini dia! …Kemarilah, lihat tandukku!",
  str_voice_1300821_16 = "Kau mau pergi, Petualang? Oh! Tidak apa-apa, kok. Aku akan berada di sini.",
  str_voice_1300821_17 = "Kepalaku selalu terasa berat saat aku bangun pagi… Berat sekali.",
  str_voice_1300821_18 = "Selamat datang kembali. Kau ada waktu? Aku ingin menanyakan sesuatu.",
  str_voice_1300821_19 = "Hmm… Apa kau selalu sangat energik? Bagaimana caranya bisa begitu?",
  str_voice_1300821_20 = "Tutupi harta karun untuk melindunginya dari gangguan… Benda itu akan menjadi berkilau setelah waktu yang sangat lama.",
  str_voice_1300821_21 = "Meskipun berat, kota raksasa itu bisa melayang di langit tanpa penopang… Luar biasa!",
  str_voice_1300821_22 = "Hehe… Demi Utara!",
  str_voice_1300821_23 = "Eclipsite… Mengerikan sekali. Kalau mereka mengepungmu, kau harus lari!",
  str_voice_1300821_24 = "Hati-hati, jangan sampai menabrak cermin Nepolis, nanti dia marah.",
  str_voice_1300821_25 = "Hehe… Bersama Noah itu sangat menyenangkan… Aku tidak perlu khawatir bakal terguling karena ada manusia salju mungil di dekatku!",
  str_voice_1300821_26 = "Hehe… Kau mungkin tidak tahu, tapi… aku ini penjahit yang lumayan hebat!",
  str_voice_1300821_27 = "Kau tidak bisa melakukan hal-hal terlarang! Kalau nekat, kau akan dihukum berat!",
  str_voice_1300821_28 = "Colossus ini besar sekali… bahkan lebih besar ketimbang rumahku! Dulu kau tinggal di sini sendirian? Apa kau kesepian?",
  str_voice_1300821_29 = "Kau Petualang terkenal itu, ya? Wah, kebetulan sekali! Oh, maaf! A-aku… Bagaimana cara memperkenalkan diriku, ya?",
  str_voice_1300821_30 = "Tanduknya… tumbuh? Mustahil…",
  str_voice_1300821_31 = "Batu bersinar! Oh! Itu tandukku!",
  str_voice_1300821_32 = "Lihat apa yang kutemukan! Beyllos!",
  str_voice_1300821_34 = "Aku t-tidak boleh menabrak orang lain…",
  str_voice_1300821_35 = "Anu… Aku akan bersinar!",
  str_voice_1300821_36 = "Kau boleh lihat, tapi jangan pegang, ya!",
  str_voice_1300821_37 = "Aku janji padamu! Cahaya hijau!",
  str_voice_1300821_38 = "Semoga Dewi Fortuna menyertaimu!",
  str_voice_1300821_39 = "Permata hijau!",
  str_voice_1300821_40 = "Beyllos!",
  str_voice_1300821_41 = "Apa? Ini… Hmm… Apa yang harus kulakukan sekarang…",
  str_voice_1300821_42 = "A-aku benar-benar melakukannya? Tadi itu berhasil?",
  str_voice_1300821_43 = "Aku benar-benar minta maaf… Itu bukan keahlianku…",
  str_voice_1300821_44 = "Ahhh! Jangan pegang tandukku!",
  str_voice_1300821_45 = "Mau memindahkannya? Hah? Ini sama sekali tidak berat, kok.",
  str_voice_1300821_46 = "Aku boleh memilikinya? Terima kasih!",
  str_voice_1300821_47 = "Oh, itu untukku? Kalau begitu, aku akan memindahkannya!",
  str_voice_1300821_48 = "Hehe… Begitu rupanya. Ini adalah hadiah! Aku sangat menyukainya!",
  str_voice_1300821_49 = "Biasanya tanduk tidak bisa tumbuh terus, tapi yang ini tumbuh… Bagaimana kalau tandukku makin berat…?",
  str_voice_1300821_50 = "Dulu aku tinggal di sebuah kota batu yang dikelilingi salju dan pohon pinus hijau. Aku hanya bisa melihat dunia luar setelah bertemu denganmu!",
  str_voice_1300821_52 = "Hehe. Alchemy Stars!",
  str_voice_1300821_53 = "Ah, anu… Yah…",
  str_voice_1300821_54 = "Selamat pagi, Petualang!",
  str_voice_1300821_55 = "Apa kau punya waktu?",
  str_voice_1300821_56 = "Apa kau tertarik pada tanduk yang bersinar?",
  str_voice_1300821_57 = "Hehe… Selamat Tahun Baru, ya!",
  str_voice_1400071_1 = "Aku harap aku bisa menjadi tanaman yang tumbuh di suatu tempat yang tinggi.",
  str_voice_1400071_2 = "Wah, kurasa aku memimpikan… kelinci semalam…",
  str_voice_1400071_3 = "Oh, bagaimana caranya agar hidupku damai… Mungkin sekarang memang sudah damai…?",
  str_voice_1400071_4 = "Tak ada orang yang akan menahanku lagi!",
  str_voice_1400071_5 = "Tak ada yang lebih penting daripada kebebasan… Benar, tidak ada…",
  str_voice_1400071_7 = "Aku masih belum terbiasa dengan kebaikan hatimu, tapi terima kasih…",
  str_voice_1400071_8 = "Kebaikan ini mengingatkanku pada sesuatu dari masa lalu… Sudahlah, itu hanya kisah lama yang membosankan…",
  str_voice_1400071_9 = "Senang bisa bertemu denganmu lagi. Mau cari udara segar? Angin di sore hari… Oh, maaf, aku lupa kau tidak suka bersikap sembrono.",
  str_voice_1400071_10 = "Dum di dum di dum… Ehem!",
  str_voice_1400071_11 = "Aku suka di sini. Bau udaranya segar.",
  str_voice_1400071_12 = "Siapa yang berikutnya? Aku siap mendengar.",
  str_voice_1400071_13 = "Permisi, apa kau lihat… Eh, lupakan saja. Maaf sudah mengganggumu. Akan kucari sendiri…",
  str_voice_1400071_14 = "Semoga berhasil dalam pertempuran.",
  str_voice_1400071_15 = "Ini hari ulang tahunmu? Selamat, ya.",
  str_voice_1400071_16 = "Ini berbeda dengan saat di Rediesel Wrench, tapi aku akan berusaha sebaik mungkin.",
  str_voice_1400071_17 = "Ah… Sejuk sekali anginnya…",
  str_voice_1400071_18 = "Angin telah membawamu pulang.",
  str_voice_1400071_19 = "Pemandangan di sini bagus, terutama di malam hari…",
  str_voice_1400071_20 = "Orang-orang di sini sangat berisik, tapi aku sungguh tidak keberatan karena mereka semua orang-orang baik.",
  str_voice_1400071_21 = "Di Umbraton, yang terburuk bukan orang miskinnya, tapi anak-anak yatimnya.",
  str_voice_1400071_22 = "Bebas, tanpa batas.",
  str_voice_1400071_23 = "Menyerang adalah sifat alami Eclipsite. Mereka sebenarnya adalah makhluk yang sederhana kalau dibandingkan dengan makhluk-makhluk jahat…",
  str_voice_1400071_24 = "Eh, kau pernah melihat kelinci yang minum diesel? Belum? Aku ingin tanya apa dia mau cari udara segar denganku.",
  str_voice_1400071_25 = "Sinsa adalah pemersatu Rediesel Wrench.",
  str_voice_1400071_26 = "Kalau kau melihat seekor kelinci, tolong jangan ganggu dia.",
  str_voice_1400071_27 = "Kurasa sekarang Livia sudah mampu melawan laki-laki itu tanpa bantuan siapa pun.",
  str_voice_1400071_28 = "Tempat yang sangat besar dan juga layak huni. Apalagi bisa terbang di langit, cukup meyakinkan…",
  str_voice_1400071_29 = "Dedaunan dan kelopak bunga bisa menjadi senjata yang mematikan, tapi hati manusia yang paling menyakitkan…",
  str_voice_1400071_30 = "Bilah daun bahkan lebih tajam sekarang, terima kasih sudah bertanya.",
  str_voice_1400071_31 = "Kekuatan adalah akar dari kebebasan.",
  str_voice_1400071_32 = "Bunga juga senjata.",
  str_voice_1400071_34 = "Apa dia juga anggota tim…?",
  str_voice_1400071_35 = "Clover siaga!",
  str_voice_1400071_36 = "Tunjukkan jalannya!",
  str_voice_1400071_37 = "Hancurkan target!",
  str_voice_1400071_38 = "Pedang! Menyebar!",
  str_voice_1400071_39 = "Clover! Serang!",
  str_voice_1400071_40 = "Bunga setajam silet!",
  str_voice_1400071_41 = "Aku boleh memilih tim sendiri?",
  str_voice_1400071_42 = "Target tersingkir. Tunggu sebentar, aku mau menyeka debu gelap dari daun-daunku.",
  str_voice_1400071_43 = "Mundur dulu sekarang. Jaga dirimu!",
  str_voice_1400071_44 = "Berada di sini membuat pikiranku tenang…",
  str_voice_1400071_45 = "Terima kasih atas hadiahmu.",
  str_voice_1400071_46 = "Ini sangat berharga! Bolehkah aku menyimpannya?",
  str_voice_1400071_47 = "Terima kasih. Kau sudah berusaha keras.",
  str_voice_1400071_48 = "Aku selalu menginginkannya! Jadi… bolehkah?",
  str_voice_1400071_49 = "Jangan pernah menyandera anak yatim atas nama cinta. Apa yang seharusnya jadi hati yang penuh kasih bisa berubah menjadi penjara yang dingin… Untungnya, semuanya memiliki titik balik.",
  str_voice_1400071_50 = "Ada banyak anak yatim sepertiku. Untungnya, aku bertemu dengan guruku, yang sepertinya berasal dari timur jauh…",
  str_voice_1400071_52 = "Alchemy Stars.",
  str_voice_1400071_53 = "Hei…",
  str_voice_1400071_54 = "Selamat pagi.",
  str_voice_1400071_55 = "Selamat sore.",
  str_voice_1400071_56 = "Selamat malam.",
  str_voice_1400071_57 = "S-selamat Tahun Baru.",
  str_voice_1400081_1 = "Bagaimana perasaanmu hari ini? Kau ingin memalu? Eh, aku hanya bercanda.",
  str_voice_1400081_2 = "Saat sedang bersiap, aku melakukan pemeliharaan harian di kapalmu! Seperti kata Honcho Sinsa, orang yang tidak bekerja tidak boleh makan!",
  str_voice_1400081_3 = "Bagaimana kabar Honcho Sinsa, ya? Dia selalu bertindak bodoh sehingga orang-orang mencemaskannya. Kalau aku tidak mengawasinya…",
  str_voice_1400081_4 = "Ini adalah keajaiban mesin yang mengagumkan… Saat melihat Colossus yang hebat ini mengikuti perintahmu, aku… Eh, tidak! Kau luar biasa!",
  str_voice_1400081_5 = "Aku bukan lagi kerikil yang jatuh. Di malam yang gelap itu, seseorang menerangi jalan bagiku bahkan ketika aku mencoba kabur… Sekarang giliranku untuk membantu.",
  str_voice_1400081_7 = "Kau sangat… Bagaimana caranya kau bertahan hidup selama ini?",
  str_voice_1400081_8 = "Meskipun bukan anggota Rediesel Wrench, sebenarnya kau ini cukup berbeda dari para pengecut itu. Kurasa kau hampir tidak bisa memenuhi syarat sebagai pemimpin meskipun Honcho Sinsa sedikit lebih baik darimu.",
  str_voice_1400081_9 = "Jika saat itu kau yang menyelamatkanku dan bukannya Honcho Sinsa… Mungkin… Hmm! Sudahlah!",
  str_voice_1400081_10 = "Aku harus mengganti bantalan komponen-komponen penting… dan menghitung ulang kecepatannya… Hei, kapan kau sampai kemari?",
  str_voice_1400081_11 = "Aku lebih baik dalam pekerjaan balik layar… Namun, karena kau bersikeras, sudahlah…",
  str_voice_1400081_12 = "Hei! Jangan injak perkakasku! Kaki kananmu itu, lho!",
  str_voice_1400081_13 = "Hei, apa kau sedang tidak sibuk? Bisa membantuku mengepang rambutku…? Rambutku terlalu mengembang hari ini, aku kesulitan melakukannya sendiri.",
  str_voice_1400081_14 = "Syal ini adalah hartaku yang paling berharga, jadi harus dicuci dengan hati-hati… Hei, aku tidak memintamu mencucinya!",
  str_voice_1400081_15 = "Kau ingin aku menyanyikan lagu ulang tahun untukmu? …Sebaiknya aku memberimu kotak musik saja.",
  str_voice_1400081_16 = "Wah, rupanya kau di sini. Kupikir kau tidak akan kembali.",
  str_voice_1400081_17 = "Tadinya aku akan memasangkan pencahayaan buatan untukmu, tapi sepertinya sudah tidak perlu lagi.",
  str_voice_1400081_18 = "Apa kau mau sesekali mencoba… Lupakan saja, menjadi teknisi itu juga sulit.",
  str_voice_1400081_19 = "Terkadang cahaya terang lebih mengerikan daripada malam yang gelap. Kau… Tidak apa-apa.",
  str_voice_1400081_20 = "Bukankah seharusnya mereka lebih pilih-pilih rampasan? Kenapa sih mereka selalu membawa pulang sampah…",
  str_voice_1400081_21 = "Kudengar bahwa Illumina menghargai teknologi ilmiah… Jangan salah paham, ya! Aku ini juga orang yang sangat penting di Rediesel Wrench!",
  str_voice_1400081_22 = "Istirahat dulu teriak-teriaknya.",
  str_voice_1400081_23 = "Sepertinya aku paham kenapa Eclipsite takut pada cahaya yang terang.",
  str_voice_1400081_24 = "Lihat saja Odi, kau akan tahu sendiri betapa sulitnya menjadi petugas teknis. Dia selalu marah-marah sehingga tidak bisa berpikir dengan jernih.",
  str_voice_1400081_25 = "Aku tidak memintanya menyelamatkanku. Dia sendiri yang tidak tahan untuk tidak menyelamatkanku… tapi aku cukup berterima kasih padanya.",
  str_voice_1400081_26 = "Teknik buatan tangan adalah mempelajari teknologi dan merakit berbagai bagian!",
  str_voice_1400081_27 = "Aku tidak suka orang yang tidak kompeten dan benci kalau mereka hanya bisa omong saja! Termasuk aku sendiri.",
  str_voice_1400081_28 = "Kau benar-benar tidak akan bekerja sama dengan kami? Kalau kau tak menginginkan Colossus milikmu itu, sini biar kami bawa pulang saja! Aku serius!",
  str_voice_1400081_29 = "Jangan salah paham, aku kemari untuk menguji keberanianmu tanpa sepengetahuan Honcho Sinsa!",
  str_voice_1400081_30 = "Kekuatan bertambah!",
  str_voice_1400081_31 = "Bukankah tingkat hak istimewa itu suatu fakta?",
  str_voice_1400081_32 = "Aku akan menjadi cahaya terang yang menyinari malam!",
  str_voice_1400081_34 = "Seharusnya kau memilihku sejak dulu!",
  str_voice_1400081_35 = "Lampu sorot siap!",
  str_voice_1400081_36 = "Ta-ra!",
  str_voice_1400081_37 = "Lihat sekilas cahaya terangku!",
  str_voice_1400081_38 = "Singkirkan rasa takutmu dengan cahaya!",
  str_voice_1400081_39 = "Apa sudah cukup terang?",
  str_voice_1400081_40 = "Cahayaku akan membutakanmu.",
  str_voice_1400081_41 = "Ya! Ikuti perintahku!",
  str_voice_1400081_42 = "Hihi! Lagi pula aku di sini!",
  str_voice_1400081_43 = "Jangan berdiri saja di sana, bodoh. Lari!",
  str_voice_1400081_44 = "Jangan khawatirkan tinggiku! Cemaskan saja Colossus milikmu itu! Huh!",
  str_voice_1400081_45 = "… Apa ini?",
  str_voice_1400081_46 = "Wooow! Ini luar biasa!",
  str_voice_1400081_47 = "… Semoga ini sesuatu yang berguna.",
  str_voice_1400081_48 = "Hadiah yang sungguh istimewa! Kau benar-benar mengenalku!",
  str_voice_1400081_49 = "Jangan menilaiku dari penampilanku saja. Aku dibesarkan di tempat pembuangan sampah dan bisa merakit peralatan apa saja… Oh, tempat itu bernama Loot Depot…",
  str_voice_1400081_50 = "Huft! Kalau kau tidak lebih serius, mungkin Rediesel Wrench akan mengambil alih kapal ini suatu hari! Hoi, kenapa kau menepuk kepalaku! Aku sedang serius!",
  str_voice_1400081_52 = "Alchemy Stars.",
  str_voice_1400081_53 = "Bisakah kau mendengarku…",
  str_voice_1400081_54 = "Apa kau sudah bangun?",
  str_voice_1400081_55 = "Bisakah kau kemari sebentar?",
  str_voice_1400081_56 = "Kalau kau masih terjaga…",
  str_voice_1400081_57 = "Pergilah ke tempat lain kalau kau ingin seseorang mengucapkan 'Selamat Tahun Baru' untukmu.",
  str_voice_1400161_1 = "Seluruh dunia jadi musuh ketika aku bangun, jangan bicara denganku sementara waktu.",
  str_voice_1400161_2 = "Jauhkan benda-benda berbulu itu dariku kalau memungkinkan.",
  str_voice_1400161_3 = "Entah di mana Franz. Kurasa itu yang terbaik.",
  str_voice_1400161_4 = "Seseorang mengganggu anak anjing? Antar aku ke sana. Akan kupatahkan tangannya…",
  str_voice_1400161_5 = "Kita harus memeriksa peluru dengan cermat. Peluru cenderung macet saat kita menembak orang-orang yang menyerang hewan kecil…",
  str_voice_1400161_6 = "Aku punya senjata yang lebih baik sekarang. Aku akan membidik makhluk-makhluk tercela itu—Eclipsites, pembuat kebisingan, dan penyiksa hewan-hewan kecil.",
  str_voice_1400161_7 = "Berbulu atau tidak, siapa pun yang menggangguku akan kutembak. Termasuk kau.",
  str_voice_1400161_8 = "Orang-orang ini selalu menyuruhku melakukan pengintaian sendirian. Hei, kau! Gantikan posisiku.",
  str_voice_1400161_9 = "Siapa pun yang mengganggu tidurku akan menerima perlakuan seperti layaknya Eclipsite, termasuk kau.",
  str_voice_1400161_10 = "Aku mau tidur siang. Hei, kau! Singkirkan hewan-hewan itu. Jangan ganggu tidurku.",
  str_voice_1400161_11 = "Kau ingin aku melakukan pengintaian? Baiklah. Toh aku selalu terjaga semalaman.",
  str_voice_1400161_12 = "Kau capek? Namun, kau tak boleh istirahat sekarang. Aku berjaga sepanjang waktu.",
  str_voice_1400161_13 = "Makhluk kecil yang menyebalkan ini menggosok-gosokkan tubuhnya padaku lagi! Kafka, kau harus berhenti bersikap lembek begitu…",
  str_voice_1400161_14 = "Aku perlu beristirahat sesekali. Di mana Franz? Franz! Bukannya aku sudah bilang kau harus selalu di dekatku!?",
  str_voice_1400161_15 = "Ini hari ulang tahunmu? Mau kuucapi selamat?",
  str_voice_1400161_16 = "Sekarang adalah jam-jam paling aktif para makhluk berbulu itu. Awasi mereka! Jangan sampai mereka keluyuran!",
  str_voice_1400161_17 = "Berani-beraninya kau mengganggu istirahatku! Oh… sudah pagi rupanya. Sepertinya aku bergadang lagi.",
  str_voice_1400161_18 = "Tak ada yang datang untuk giliran jaga berikutnya? Dasar pemalas! Kapan-kapan aku akan menembak mereka di tengah malam…",
  str_voice_1400161_19 = "Aku lelah sekali. Cukup. Giliran kerjaku sudah selesai. Aku mau tidur!",
  str_voice_1400161_20 = "Ya, mereka orang-orang yang baik, tapi agak gila! Hanya aku yang melakukan pengintaian. Kau lihat lingkaran gelap ini?",
  str_voice_1400161_21 = "Orang-orang Illumina itu berusaha keras untuk mendapatkan senapanku dan mempelajarinya. Memangnya aku bakal membiarkan itu terjadi? Dasar kutu buku gila!",
  str_voice_1400161_22 = "Ayo kita tunjukkan pada para pengganggu itu bagaimana rasanya dihajar.",
  str_voice_1400161_23 = "Selama ada senapanku, akan kusingkirkan para Eclipsite yang menghalangiku dan kuusir mereka selamanya.",
  str_voice_1400161_24 = "Kadal raksasa itu! Aku benci mengatakannya, tapi dia imut… Hah? Apa? Aku bilang apa barusan?",
  str_voice_1400161_25 = "Sudah lama aku tidak melihat pasangan beruang dan penguin itu. Apa mereka masih mencari pendingin udara, ya? Akan kuberi mereka beberapa komponen kalau ada kesempatan.",
  str_voice_1400161_26 = "Kendalikan dirimu, Kafka… Aku akan membelai makhluk-makhluk berbulu itu lagi nanti…",
  str_voice_1400161_27 = "Berisik sekali! Kenapa tidak ada satu pun ranjang yang tenang untuk tidur di Rediesel Desert yang besar dan luas?",
  str_voice_1400161_28 = "Besar sekali dia! Konon dia memiliki kesadaran. Kalau begitu, suruh dia melakukan pengintaian.",
  str_voice_1400161_29 = "Namaku Kafka. Aku punya tiga permintaan: Jangan utus aku ke pengintaian, beri aku apartemen studio kedap suara yang cocok untuk lajang, dan singkirkan hewan-hewan ini dariku!",
  str_voice_1400161_30 = "Lebih cepat dan tepat.",
  str_voice_1400161_31 = "Franz! Ayo!",
  str_voice_1400161_32 = "Ayo gunakan peluru yang lebih kuat!",
  str_voice_1400161_33 = "Tembak! Tembak terus!",
  str_voice_1400161_34 = "Jangan biarkan satu musuh pun lolos!",
  str_voice_1400161_35 = "Mencari musuh…",
  str_voice_1400161_36 = "Gauss Rifle! Bidik!",
  str_voice_1400161_37 = "Tembak!",
  str_voice_1400161_38 = "Tak ada tempat untuk sembunyi!",
  str_voice_1400161_39 = "Medan listrik super! Tembakan menyebar!",
  str_voice_1400161_40 = "Tembakan jarak dekat!",
  str_voice_1400161_41 = "Aku akan mengawasi mereka seperti elang.",
  str_voice_1400161_42 = "Ini mudah sekali.",
  str_voice_1400161_43 = "Menegangkan sekali. Permainanku payah…",
  str_voice_1400161_44 = "Tidak ada hewan di sini? Bagus! Ah, tapi ini membosankan juga…",
  str_voice_1400161_45 = "Hadiah untukku? Baiklah, akan kuterima.",
  str_voice_1400161_46 = "Hadiah ini kelihatan cukup bagus…",
  str_voice_1400161_47 = "Sepertinya ini sangat berharga. Terima kasih!",
  str_voice_1400161_48 = "Ini? Wow! Terima kasih banyak!",
  str_voice_1400161_49 = "Rediesel Wrench? Awalnya aku tidak ingin bergabung dengan mereka, tapi kadal raksasa itu membuatku kesulitan menolak.",
  str_voice_1400161_50 = "Ingin tahu bagaimana aku bisa mendapatkan senapan ini? Ceritanya seru, tapi sebelum itu, tolong singkirkan makhluk-makhluk kecil yang suka menempel ini dulu.",
  str_voice_1400161_51 = "Rumahku dulu berupa kastel kecil, bukan kadal raksasa ini. Kalau bukan karena Eclipsite… Hmm… Tidak usah dibahas lagi, deh. Aku mau tidur saja.",
  str_voice_1400161_52 = "Alchemy Stars!",
  str_voice_1400161_53 = "Kau di sana?",
  str_voice_1400161_54 = "Aku tahu ini masih pagi.",
  str_voice_1400161_55 = "Namun, apa kau punya waktu sebentar?",
  str_voice_1400161_56 = "Kau sedang bertugas?",
  str_voice_1400161_57 = "Seperti yang ingin kukatakan… Ehem. Selamat Tahun Baru.",
  str_voice_1400351_1 = "Layanan Courier Union tidak terbatas!",
  str_voice_1400351_2 = "Aku penasaran bagaimana caranya kau bisa membawa organ itu ke sini. Ukurannya lebih besar daripada lubang palka!",
  str_voice_1400351_3 = "Menurut Yoshi kau ini imut. Yoshi yang bilang, bukan aku! Serius!",
  str_voice_1400351_4 = "Apa? Kau menganggap bahwa Yoshi sekarang lebih kuat dariku sebelum kedudukanku naik? Aku bisa bekerja berjam-jam setiap hari, 'kan?",
  str_voice_1400351_5 = "Kau lihat cahaya yang berkedip di mataku? Artinya, aku sudah menyelesaikan semua pengiriman dan tidak perlu kerja lembur!",
  str_voice_1400351_7 = "Kata orang, Courier Union terdiri dari para penjelajah. Yang benar saja, memangnya kami punya waktu luang?!",
  str_voice_1400351_8 = "Kubawakan permen karet dari Northland ini untukmu dengan sembunyi-sembunyi! Ini dari perjalanan bisnisku. Jangan berikan pada orang lain, ya!",
  str_voice_1400351_9 = "Hidupku kuhabiskan untuk bekerja. Sebaiknya kauhabiskan juga hidupmu untuk itu! Dengan begitu, kita bisa membicarakan banyak hal!",
  str_voice_1400351_10 = [[
- Kau kelihatan sangat manis kalau sedang melamun. Eh, pernah dengar? Y-Yoshi, sebaiknya kau tidak mengatakan hal-hal aneh begitu!
- Aduh!]],
  str_voice_1400351_11 = "Meskipun aku tidak pandai dalam hal-hal semacam ini…",
  str_voice_1400351_12 = "Apa kau sudah memutuskan tugas yang bisa kaupercayakan padaku? Aku tidak bisa menunggumu seharian di sini.",
  str_voice_1400351_13 = "Selama kau tampak bersemangat, tidak ada yang peduli dengan lingkaran hitam dan mata bengkak!",
  str_voice_1400351_14 = "Tolong abaikan saja merpati pemalas itu. Tidak ada yang seperti dia di seluruh Union.",
  str_voice_1400351_15 = "Kau dapat dua ucapan selamat tahun! Yang satu dariku, yang satunya lagi dari Yoshi!",
  str_voice_1400351_16 = "Rasanya kau ini selalu sibuk, seperti Eho.",
  str_voice_1400351_17 = "Selamat malam? Oh, oh, jangan khawatir. Eho hanya menyapa Yoshi.",
  str_voice_1400351_18 = "Masih belum terlambat untuk bepergian dengan Eho.",
  str_voice_1400351_19 = "Mungkin hanya aku yang belum tidur selarut ini.",
  str_voice_1400351_20 = "Serahkan saja semua pada kami. Semua orang di Union seperti aku. KAMI SUKA KERJA LEMBUR!",
  str_voice_1400351_21 = "Terkadang Guild membaca surat orang tanpa minta izin. Bahkan para Rediesel tidak akan melakukan itu.",
  str_voice_1400351_22 = "Courier Union akan mengantarkan suratmu!",
  str_voice_1400351_23 = "Kurir tidak terlibat dalam pertempuran dengan Eclipsite kecuali mendapat perintah.",
  str_voice_1400351_24 = "Para tetua Union cukup ramah. Itu karena sebagian besar kurir tidak butuh pengawasan siapa pun.",
  str_voice_1400351_25 = "Kurir yang menganggur? Yang kau maksud pasti Dove. Cepat atau lambat dia pasti bakal dipecat kalau terus seperti itu.",
  str_voice_1400351_26 = "Yoshi bilang hazelnut cokelat sangat enak.",
  str_voice_1400351_27 = "Tolong jangan bicara kepada Dove tentang Eho, jangan sekali pun!",
  str_voice_1400351_28 = "Eho dan Yoshi bisa terbang di luar Colossus sebagai pengawal ketika cuaca sedang buruk.",
  str_voice_1400351_29 = "Ada surat untukmu, manis!",
  str_voice_1400351_30 = "Bisakah aku mempraktikkan yang baru saja kupelajari?",
  str_voice_1400351_31 = "Penglihatan jadi lebih lebar!",
  str_voice_1400351_32 = "Aku jenis orang yang mungkin membuat masalah!",
  str_voice_1400351_34 = "Wah, kerja lembur, nih!",
  str_voice_1400351_35 = "Aku siap!",
  str_voice_1400351_36 = "Jadi, aku bisa melancarkan serangan terakhir??",
  str_voice_1400351_37 = "Yoshi, ikuti aku!",
  str_voice_1400351_38 = "Guntur akan bergemuruh!",
  str_voice_1400351_39 = "Jalannya sudah aman.",
  str_voice_1400351_40 = "Singkirkan rintangan!",
  str_voice_1400351_41 = "Semua kurir terlahir sebagai pelopor!",
  str_voice_1400351_42 = "Jangan remehkan cakar dan bulu-bulu para kurir!",
  str_voice_1400351_43 = "Ini sebenarnya sudah bukan pekerjaanku—",
  str_voice_1400351_44 = "Apa pria besar itu harus mengepakkan sayapnya saat lepas landas?",
  str_voice_1400351_45 = "Namun, terima kasih, deh… Yah… Terima kasih!",
  str_voice_1400351_46 = "Wow! Aku senang sekali! Begitu juga dengan Yoshi!",
  str_voice_1400351_47 = "Kalau begitu, aku akan menerimanya dengan senang hati. Aku suka pemberianmu!",
  str_voice_1400351_48 = "Kenapa kau selalu tahu apa yang paling Yoshi sukai?",
  str_voice_1400351_49 = "Kita selalu berhasil mengirimkan pos! Tidak ada batas untuk layanan Union, dan tidak pula untukku! Silakan hubungi cabang terdekat untuk tugas yang rumit!",
  str_voice_1400351_50 = "Rekan-rekanku dan aku selalu sibuk di benua, melintasi kota-kota kuno yang gelap dan gurun yang berkilauan. Tak peduli seberapa jauh jaraknya, kami akan melakukannya untukmu!",
  str_voice_1400351_52 = "Alchemy Stars!",
  str_voice_1400351_53 = "Dengarkan aku!",
  str_voice_1400351_54 = "Sudah pagi! Sudah pagi! Bangun!",
  str_voice_1400351_55 = "Sudah tengah hari! Aduh!",
  str_voice_1400351_56 = "Dengarkan aku! Hik!",
  str_voice_1400351_57 = "Selamat Tahun Baru? Kalau aku tidak bekerja lembur…",
  str_voice_1400401_1 = "Mau coba permen meletup? Semua orang di Science Division menyukai rasa ini. Oh, maaf, aku salah beri. Ini peledak.",
  str_voice_1400401_2 = "Kau pernah melihat kembang api? Huh! Orang-orang bodoh yang berani menggangguku meledak seperti bom hidrogen.",
  str_voice_1400401_3 = "Ledakan itu romantis, tahu! Kau paham atau tidak? Yah, kau memang tidak memahami semangat seorang gadis muda!",
  str_voice_1400401_4 = "Kembang api… Indah sekali! Apa kau tidak ingin MENJADI kembang api?! Tenang saja. Aku ahli dalam bidang ini!",
  str_voice_1400401_5 = "Aku sedang berpikir untuk membuat yang baru… Tiny One bilang yang merah bagus. Kau suka ledakan warna apa?",
  str_voice_1400401_6 = "Temanku tersayang, kau menjatuhkan bom emas ini? Bom perak ini? Atau sekantong bom biasa? Yah, sebenarnya kau boleh menyimpan semuanya!",
  str_voice_1400401_7 = "Permen meletup itu hebat, 'kan? Ledakan di dalam mulut ini sama luar biasanya dengan ledakan lain!",
  str_voice_1400401_8 = "Apa ada yang ingin kauledakkan belakangan ini? Ukuran tidak penting. Mau semangka, bangunan, atau mungkin Lumopolis?",
  str_voice_1400401_9 = "Wow! Kau kok tahu-tahu bisa muncul seperti itu? Astaga! Kupikir tadi jantungku mau meledak…",
  str_voice_1400401_10 = "Kalau menganggur saja aku pasti bakal bosan. Bolehkah aku bermain dengan Tiny One?",
  str_voice_1400401_11 = "Aku datang! Akan kumulai pestanya!",
  str_voice_1400401_12 = "Es soda itu enak, es nitrogliserin juga lezat! Hmm, kelihatannya dua-duanya cocok.",
  str_voice_1400401_13 = "Cium aromanya! Bom spesial ini manis aromanya. Jangan khawatir—bomnya tidak akan meledak kalau kaucium aromanya.",
  str_voice_1400401_14 = "Bawa kacamata dan ranselmu. Kemasi barang-barangmu. Ayo bersenang-senang!",
  str_voice_1400401_15 = "Ulurkan tanganmu dan tutup matamu! Yang satu di mata kiri, yang satu lagi di mata kanan. Selamat menikmati granatnya!",
  str_voice_1400401_16 = "Kau sudah kembali ke tim! Bagaimana kalau kita nyalakan kembang api baru untuk merayakannya? Oh, sial! Kembang apinya sudah dinyalakan.",
  str_voice_1400401_17 = "Sudah bangun? Aku sudah menaruh banyak peralatan di meja samping ranjangmu. Kau tidak lihat, ya?",
  str_voice_1400401_18 = "Kau kembali tepat waktu! Mau sandworm? Sandworm ini diolah segar! Mmm… dan aromanya sedap!",
  str_voice_1400401_19 = "Mau tidur, ya? Mau kumainkan sorakan pengantar tidur? Kau bakal tidur nyenyak, lho!",
  str_voice_1400401_20 = "Di Rediesel, semua orang bisa berkendara untuk seru-seruan setiap hari dan memungut segala jenis makanan di gurun.",
  str_voice_1400401_21 = "Oh, aku mengubur sejumlah harta karun sebelum meninggalkan Illumina. Apa sudah ada yang menemukannya, ya…",
  str_voice_1400401_22 = "Ledakkan!",
  str_voice_1400401_23 = "Kau dapat bom! DHUAR! Kau dapat bom! DHUAR! Semuanya dapat bom!",
  str_voice_1400401_24 = "Honcho suka mengajak orang berkeliling untuk memungut sampah dan membawa pulang banyak bahan penelitian!",
  str_voice_1400401_25 = "Tiny One dan aku selalu memilah sampah bersama-sama… Tunggu, dia menyebutnya sebagai memilah trofi atau apa, ya?",
  str_voice_1400401_26 = "Gemerincing dan dentang logam, suara ledakan, dan Pop Rocks bermunculan!",
  str_voice_1400401_27 = "Aku tak tahan hidup tenang tanpa suara. Ayo buat keributan!",
  str_voice_1400401_28 = "Aku tahu! Kelihatannya Colossus sangat mudah dibongkar. Dengan satu bom yang diletakkan dengan baik, benda itu akan hancur.",
  str_voice_1400401_29 = "Senang bertemu denganmu! Aku Joanie Boom. Terimalah bom yang baru saja kutaruh di sakumu sebagai hadiah sambutan.",
  str_voice_1400401_30 = "Kekuatan MAKSIMAL!",
  str_voice_1400401_31 = "Formula baru!",
  str_voice_1400401_32 = "Kita bisa mengadakan pertunjukan kembang api sekarang! Wiiii! Mengasyikkan sekali!",
  str_voice_1400401_33 = "Sekarang siapa orang beruntung yang akan dilontarkan ke langit?",
  str_voice_1400401_34 = "Ayo beraksi!",
  str_voice_1400401_35 = "Kita bisa mulai hitung mundurnya sekarang!",
  str_voice_1400401_36 = "Akan kutunjukkan kembang api terbaik yang pernah ada!",
  str_voice_1400401_37 = "Ledakannya pasti dahsyat!",
  str_voice_1400401_38 = "Membara dan mekar di langit!",
  str_voice_1400401_39 = "Duarr! Siss! Duaar!",
  str_voice_1400401_40 = "Berubah jadi abu! Syalalala ♪",
  str_voice_1400401_41 = "Nih, masing-masing dapat satu bom.",
  str_voice_1400401_42 = "Bagus sekali! Ini pertunjukan kembang api yang hebat!",
  str_voice_1400401_43 = "Rambutku gosong… Hiks…",
  str_voice_1400401_44 = "Coba tebak di mana aku memegang bomnya? Duh! Tentu saja di kedua tanganku.",
  str_voice_1400401_45 = "Lumayan juga!",
  str_voice_1400401_46 = "Ini sangat mengasyikkan! Aku senang sekali!",
  str_voice_1400401_47 = "Bagus sekali! Ayo ledakkan satu lagi!",
  str_voice_1400401_48 = "Mengagumkan! Aku akan menyimpannya sekarang!",
  str_voice_1400401_49 = "Suatu kali aku hampir meledakkan markas Rediesel Wrench… Wah… Tenang! Itu tidak disengaja, kok. Namun, ternyata aku juga suka dengan hasilnya…",
  str_voice_1400401_50 = "Barang-barang yang membosankan? Teman yang menjengkelkan? Ledakkan saja mereka! Setuju, 'kan?",
  str_voice_1400401_51 = "Aku berasal dari Saltpeter Vein dan penanggung jawab atas sejumlah riset khusus. Aku bisa membantu semua orang! Sebenarnya, aku masih melakukan hal yang sama—meledakkan barang!!",
  str_voice_1400401_52 = "Alchemy Stars! Dhuar!",
  str_voice_1400401_53 = "Dhuar! Ayo keluarlah!",
  str_voice_1400401_54 = "Kau sudah melihat kembang api di dekat meja samping ranjangmu?",
  str_voice_1400401_55 = "Hei! Aku baru saja meledakkan sesuatu.",
  str_voice_1400401_56 = "Menyingkir dari sana! Cepat!",
  str_voice_1400401_57 = "Perayaan tahun baru itu intinya hanya meledakkan barang!",
  str_voice_1400411_1 = "Sudah menjadi kebiasaan profesionalku untuk bersikap penuh semangat. Kuharap kau tidak keberatan. Lewat sini.",
  str_voice_1400411_2 = "Aku selalu merasa ada yang kurang dari tembok di belakangku. Oh, aku tahu! Versi baru yang modern dari Wanita di Jembatan Gantung.",
  str_voice_1400411_3 = "Swan Lake, Royal Cathedral, Hanging Tower of Mt. Lakhbin… Mana yang harus kuperkenalkan lebih dulu?",
  str_voice_1400411_4 = "Aku tahu segala hal tentang Lumopolis. Aku mengenal baik semua lingkungan dan aku menghormati setiap jengkalnya.",
  str_voice_1400411_5 = "Rahasia seorang wanita yang elegan? Semuanya ada di koperku. Namun, kau tak bisa membukanya. Isinya rahasia seorang wanita.",
  str_voice_1400411_6 = "Aku adalah Ms. Rot sekaligus Ms. Blanc. Aku telah berjalan melintasi jalur yang terang dan melewati kegelapan sebelum fajar. Selamat datang di White Night!",
  str_voice_1400411_7 = "Ada sehelai rambut yang terlewat? Permisi, aku harus tetap tampil elegan meskipun sibuk.",
  str_voice_1400411_8 = "Ms. Rot? Rasanya aku jadi bernostalgia. Terkadang saat memikirkan masa lalu, aku merasa hidupku sangat luar biasa.",
  str_voice_1400411_9 = "Aku telah mengalami segala hal yang pernah terjadi di Lumopolis. Namun, sekarang rasanya aku cuma penonton.",
  str_voice_1400411_10 = "Kau tahu kapan harus istirahat, ya? Aku juga selalu mencari waktu untuk istirahat. Mau kopi spesial?",
  str_voice_1400411_11 = "Aku mengenal baik seluruh tempat di sini. Jadi, mana yang ingin kaukunjungi?",
  str_voice_1400411_12 = "Hmm, aroma vanilla ini membuat rasanya unik. Kopi selalu menjadi solusi.",
  str_voice_1400411_13 = "Sebagai wanita profesional, memiliki postur yang tepat dan penampilan yang anggun itu penting.",
  str_voice_1400411_14 = "Kau butuh pemandu wisata pribadi? Ada tempat yang ingin kau kunjungi di White Night?",
  str_voice_1400411_15 = "Semoga sehat sentosa di hari ulang tahunmu. Sekarang, ayo kita keluar untuk merayakan.",
  str_voice_1400411_16 = "Aku siap melayanimu hari ini! Tentu saja dengan senyumku yang paling tulus.",
  str_voice_1400411_17 = "Selamat pagi. Kau bisa berangkat kapan saja. Kami semua sudah siap.",
  str_voice_1400411_18 = "Pekerjaanku belum selesai. Tolong lewat sini.",
  str_voice_1400411_19 = "Jangan cemas. Aku akan memandumu sesekali kalau kau kesulitan.",
  str_voice_1400411_20 = "Aku telah melihat bimbingan White Night meningkat. Mulai sekarang, mengawasi negeri ini sudah cukup bagiku.",
  str_voice_1400411_21 = "Tak ada panduan dalam mencapai kebenaran. Siapa pun yang mencari kebenaran akan mengalami gejala yang seperti Aphantasia.",
  str_voice_1400411_22 = "Demi White Night.",
  str_voice_1400411_23 = "Pemandu wisata dan prajurit berjalan di jalur yang berbeda. Aku punya jalan lurus lain bagi mereka.",
  str_voice_1400411_24 = "Pengabdian Lord pada Lumopolis adalah imbalan terbaik bagi orang-orang yang sudah berjasa.",
  str_voice_1400411_25 = "Rasanya sangat terhormat bisa berbagi prestise keluarga yang sama dengan madam itu.",
  str_voice_1400411_26 = "Izinkan aku untuk memperkenalkanmu pada stabilitas dan disiplin dalam kopi dan teh kita setiap hari.",
  str_voice_1400411_27 = "Kuharap kau menjauh dari mereka yang jahat dan tentu saja, hal-hal yang mengganggu ketertiban.",
  str_voice_1400411_28 = "Aku pernah mendengar desas-desus tentang kau dan Colossus. Suatu kehormatan bisa bertemu denganmu.",
  str_voice_1400411_29 = "Kau tersesat, ya? Jangan cemas, ada aku di sini.",
  str_voice_1400411_30 = "Peta navigasi sudah diperluas.",
  str_voice_1400411_31 = "Aku adalah pemandu di bawah dinding yang tinggi.",
  str_voice_1400411_32 = "Aku adalah suar di dalam kabut.",
  str_voice_1400411_33 = "Aku adalah wajah sejati di kota kemurnian.",
  str_voice_1400411_34 = "Kau butuh pemandu atau prajurit?",
  str_voice_1400411_35 = "Mana wisatawan yang tidak patuh itu?",
  str_voice_1400411_36 = "Tanyakan apa saja padaku!",
  str_voice_1400411_37 = "Coba lihat kemari. Ini adalah pemandangan yang terkenal!",
  str_voice_1400411_38 = "Teman-teman, kita sudah sampai!",
  str_voice_1400411_39 = "Tolong taati peraturan.",
  str_voice_1400411_40 = "Tolong jangan mendorong-dorong.",
  str_voice_1400411_41 = "Kami punya panduan bagus lainnya kali ini!",
  str_voice_1400411_42 = "Aku sama sekali belum lelah.",
  str_voice_1400411_43 = "Oh—aku benar-benar minta maaf…",
  str_voice_1400411_44 = "Kami sudah menyiapkan kursi untuk semua orang di Colossus. Ada yang bisa kubantu?",
  str_voice_1400411_45 = "Ini peralatan kantor? Kau baik sekali…",
  str_voice_1400411_46 = "Ini penting untuk pemandu wisata profesional!",
  str_voice_1400411_47 = "Kau baik sekali seperti biasanya.",
  str_voice_1400411_48 = "Luar biasa! Inilah yang dibutuhkan seorang wanita elegan!",
  str_voice_1400411_49 = "Aku akan menjalankan tugasku sebagai pemandu wisata Lumopolis, tapi tolong tetap fokus, ya. Kalau tidak, kau akan ketinggalan dan tersesat.",
  str_voice_1400411_50 = "Pengetahuanku tentang Lumopolis tidak hanya berasal dari kebiasaan, tapi juga… kenangan yang tak terlupakan. Kota ini, seperti halnya dengan penduduknya, sedang berjuang untuk hidup.",
  str_voice_1400411_51 = "Aku sudah menyimpan taring lamaku. Sekarang yang kulakukan hanyalah menikmati ketenangan yang jarang kujumpai. Namun, seorang wanita sangat menjaga privasinya, jadi berjanjilah kau tidak akan mengajukan terlalu banyak pertanyaan.",
  str_voice_1400411_52 = "Alchemy Stars.",
  str_voice_1400411_53 = "Hai!",
  str_voice_1400411_54 = "Selamat pagi. Kau sudah siap?",
  str_voice_1400411_55 = "Selamat sore. Apa kau sudah istirahat?",
  str_voice_1400411_56 = "Lumopolis juga menyenangkan saat malam.",
  str_voice_1400411_57 = "Selamat Tahun Baru. Semoga tahun baru ini membawa kebaikan untukmu.",
  str_voice_1400441_1 = "Maukah kau menjelaskan kenapa pekerjaanmu belum selesai? Aku bicara kepadamu, Zoya!",
  str_voice_1400441_2 = "Tak ada toleransi jika ada terlalu banyak kesalahan pada laporan untuk Grand Marshal! Astaga, kenapa aku baru menyadarinya sekarang…",
  str_voice_1400441_3 = "Curie, ucapkan salam pada semua orang! Anak ini biasanya tidak pemalu.",
  str_voice_1400441_4 = "Formasi yang lebih baik! Jadilah lebih tangkas! Ahhh? Maafkan aku! Maksudku bukan kau!",
  str_voice_1400441_5 = "Bagi banyak orang, tenggat waktu adalah motivasi terbaik! Aku benar-benar tak mau mereka terus mengulangi kebiasaan buruk ini…",
  str_voice_1400441_6 = "Tenang saja! Meskipun pekerjaan jadi makin rumit, aku sudah lebih mahir menanganinya sekarang! Nanti juga selesai!",
  str_voice_1400441_7 = "Serahkan saja padaku. Ini bagian dari tugasku sebagai staf.",
  str_voice_1400441_8 = "Tentu… Kau mau bekerja denganku untuk rencana itu? Tidak akan lama!",
  str_voice_1400441_9 = "Illumina adalah rumahku. Aku mengenal baik segala hal yang ada di sana. Sekarang, ini juga rumahku…",
  str_voice_1400441_10 = "Bagaimana daya yang dihasilkan? Ini rute inspeksi untuk hari ini… Benar, sekarang gilirannya, dan aku masih harus membuat laporan nanti malam…",
  str_voice_1400441_11 = "Kembali pada pena, kertas, dan mesin ketik?",
  str_voice_1400441_12 = "Berusahalah! Setiap detik berharga! Aku akan melakukan yang terbaik untuk membantumu!",
  str_voice_1400441_13 = "Tertarik untuk merombak tata letak rumah? Renovasi berdampak sangat baik pada efisiensi kerja.",
  str_voice_1400441_14 = "Rencananya sudah matang, tapi harus ada yang mengerjakannya. Ini belum waktunya bersantai.",
  str_voice_1400441_15 = "Perbanyak istirahat di luar kerja. Kau harus istirahat hari ini. Oh, selamat ulang tahun, ya!",
  str_voice_1400441_16 = "Kau melihat ada yang bermalas-malasan? Pastikan kau memberitahuku, ya.",
  str_voice_1400441_17 = "Selamat pagi. Biar aku yang mengaturnya untukmu. Bukan masalah, kok.",
  str_voice_1400441_18 = "Menurut jadwal, sebentar lagi saatnya istirahat.",
  str_voice_1400441_19 = "Belum bisa istirahat… Sepertinya ada kesalahan dalam rencana. Sebaiknya kuperiksa lagi.",
  str_voice_1400441_20 = "Segala sesuatu di Illumina memang teratur. Senang rasanya kalau semua orang mengikuti rencana dan bekerja dengan giat!",
  str_voice_1400441_21 = "Dengan sifat yang kejam dan hidup tanpa tujuan begini, bagaimana mungkin Rediesel Wrench bisa bertahan…",
  str_voice_1400441_22 = "Jayalah Illumina!",
  str_voice_1400441_23 = "Tanpa rencana, mereka hanyalah sekumpulan preman yang tak punya otak.",
  str_voice_1400441_24 = "Aku harus menggandakan usahaku, baik dalam pertempuran maupun perencanaan strategis. Dengan begitu, Grand Marshal bisa mengandalkanku.",
  str_voice_1400441_25 = "Bahkan meskipun Wrath berencana untuk merebut posisi Grand Marshal, dia tak akan pernah menggunakan muslihat yang kotor!",
  str_voice_1400441_26 = "Melihat seluruh kolom di rencana itu ditandai selesai membuatku bahagia.",
  str_voice_1400441_27 = "Semua harus berjalan sesuai rencana! Semua janji harus ditepati!",
  str_voice_1400441_28 = "Sistem organisasi macam apa yang dibutuhkan untuk mengelola sesuatu yang sebesar ini…?",
  str_voice_1400441_29 = "Halo. Akulah yang bertanggung jawab atas semua detailnya. Tolong percayai kemampuan manajemen Illumina. Bagaimanapun juga, medan perang di sini sangat berbeda.",
  str_voice_1400441_30 = "Hei, apa Curie sudah berkembang?",
  str_voice_1400441_31 = "Curie, bangkit!",
  str_voice_1400441_32 = "Guntur akan bergemuruh!",
  str_voice_1400441_33 = "Petir akan menembus awan!",
  str_voice_1400441_34 = "Tolong perhatikan!",
  str_voice_1400441_35 = "Petir berdenyut dalam diriku!",
  str_voice_1400441_36 = "Rencana selesai. Siap menyerang.",
  str_voice_1400441_37 = "Menyerap petir!",
  str_voice_1400441_38 = "Guncang bumi!",
  str_voice_1400441_39 = "Hunus!",
  str_voice_1400441_40 = "Tusukan rapier! Rasakan ini!",
  str_voice_1400441_41 = "Rencanaku akan membuatmu mencapai kejayaan!",
  str_voice_1400441_42 = "Jalankan rencana, dan kejayaan akan menyertainya!",
  str_voice_1400441_43 = "Tidak mungkin sukses tanpa mengikuti rencana.",
  str_voice_1400441_44 = "Ada kabar?",
  str_voice_1400441_45 = "Imbalan atas waktu dan upayaku?",
  str_voice_1400441_46 = "Curie pasti akan menyukainya!",
  str_voice_1400441_47 = "Kelihatannya mahal… Kau yakin tidak melebihi anggaran?",
  str_voice_1400441_48 = "Wow, aku sudah lama ingin ini! Terima kasih!",
  str_voice_1400441_49 = "Undercity mungkin cukup luas untukku, tapi Curie adalah bagian dari permukaan dan langit di atasnya.",
  str_voice_1400441_50 = "Kalau bukan bagian dari Illumina, aku akan menjadi petualang pemberani yang menjelajahi gurun, negeri-negeri rahasia, dan Old Capital!",
  str_voice_1400441_51 = "Aku datang dari kota kecil di Illumina Federation, bukan Gannon City, tapi kota itu… dihancurkan…",
  str_voice_1400441_52 = "Alchemy Stars.",
  str_voice_1400441_53 = "Halo!",
  str_voice_1400441_54 = "Selamat pagi. Apa kau ada di sana?",
  str_voice_1400441_55 = "Selamat sore. Apa kau punya waktu?",
  str_voice_1400441_56 = "Selamat malam. Semoga aku tidak mengganggumu.",
  str_voice_1400441_57 = "Selamat Tahun Baru, ya!",
  str_voice_1400451_1 = "Aku percaya kepada satu-satunya kebenaran. Baik terang maupun kegelapan adalah bentuk kebenaran… Ketika kehancuran melanda, rakyat jelata akan dibimbing dari kejahatan dan dilahirkan kembali…",
  str_voice_1400451_2 = "Singkirkan kulitku yang busuk, singkirkan darahku yang kotor, singkirkan kesadaranku yang bodoh…",
  str_voice_1400451_3 = "Darahku telah menodai paku dengan warna merah, sedangkan salibku akan menghakimi musuhku… dan hatiku…",
  str_voice_1400451_4 = "Keselamatan hanya akan kuperoleh melalui penderitaan akibat kehilangan darah yang menyakitkan…",
  str_voice_1400451_5 = "Ada dosa di mana pun di dunia ini. Aku telah berdosa dan menebusnya… Apa pun perintah Master Victoria, aku harus melakukannya tanpa keberatan, syarat, atau perlawanan.",
  str_voice_1400451_6 = "Kematian adalah perubahan, bukan akhir… Rasa sakit adalah penyelamatan, bukan siksaan.",
  str_voice_1400451_7 = "Jangan takut, paku ini dipersiapkan untukku. Lihat, seperti ini…",
  str_voice_1400451_8 = "\"Ini adalah pengakuanku terhadap Truth… Karma jahat, kebodohan, dan kesombongan adalah dosaku…\" Ah, aku sedang menebus dosa-dosaku… Kau tertarik untuk bergabung denganku?",
  str_voice_1400451_9 = "Dunia ini akan jadi sempurna jika akulah satu-satunya orang yang menderita hingga sejauh ini. Namun, kau jelas-jelas mengalami keputusasaan yang sama.",
  str_voice_1400451_10 = "Tetap di sini dan diam? Bukan masalah. Aku bisa melakukan apa pun yang kauminta.",
  str_voice_1400451_11 = "Ini juga jenis latihan? Atau… bentuk hukuman?",
  str_voice_1400451_12 = "Daging dan darahku digerogoti, dan jiwaku digigit serta dicabik… Ah… Ini pertanda kebahagiaan.",
  str_voice_1400451_13 = "Aku belum menghafal doktrin yang ini… Aku harus menyalinnya 1.000 kali.",
  str_voice_1400451_14 = "Aku harus bertobat… Pact terlalu kurang ajar pada Lady Victoria, aku bahkan menyerangnya… Aku bersalah.",
  str_voice_1400451_15 = "Kelahiranku adalah wujud dosa, tapi kau adalah harta dunia ini… Selamat.",
  str_voice_1400451_16 = "Sengatan matahari terasa menyakitkan, tapi aku harus menahannya…",
  str_voice_1400451_17 = "Hai, apa kau mau dengar tentang True Order? Kenapa kau lari, sih? Oh, aku masih berdarah…",
  str_voice_1400451_18 = "Setengah dari hukuman hari ini belum dilakukan.",
  str_voice_1400451_19 = "Hanya pada saat ini, ketika direngkuh oleh kegelapan dan tenggelam dalam ketidakberartianku sendiri, aku merasa yakin.",
  str_voice_1400451_20 = "True Order adalah rumahku, tujuanku, dan… keluargaku.",
  str_voice_1400451_21 = "Aku lahir di tempat itu, tapi tidak pantas berada di sana. Itulah malapetaka hidupku.",
  str_voice_1400451_22 = "Semoga Truth memberkatimu.",
  str_voice_1400451_23 = "Kau hanya butuh sedikit darah untuk menyingkirkan Eclipsite.",
  str_voice_1400451_24 = "Lady Victoria, mohon ampuni dosa-dosaku karena aku adalah monster hina…",
  str_voice_1400451_25 = "Aku pernah bertanya kepada Faust apakah White Suitcase bisa membuatku lega. Dia memberitahuku bahwa saat itu belum waktunya.",
  str_voice_1400451_26 = "Doktrin, pengakuan, dan penebusan menenteramkanku… Yah, begitu juga dengan gula dadu…",
  str_voice_1400451_27 = "Siapa pun yang tidak mematuhi Lady Victoria harus dicabik dan dipenggal.",
  str_voice_1400451_28 = "Amat nyaman… dan mengganggu. Akan lebih baik kalau mereka membangun bilik pengakuan dosa di dalam.",
  str_voice_1400451_29 = "Aku setia kepada True Order, imanku, dan Lady Victoria. Aku telah memakukan sumpahku yang tak terpatahkan ke dalam tubuhku. Sekarang, mengakulah! Bahkan monster pun pantas mendapat penebusan.",
  str_voice_1400451_30 = "Cambuk aku, kasihanilah aku…",
  str_voice_1400451_31 = "Darahku najis. Tolong maafkan aku…",
  str_voice_1400451_32 = "Andai saja darah dari dosaku bisa membersihkan dunia ini.",
  str_voice_1400451_33 = "Ketakwaanku akan membimbingku.",
  str_voice_1400451_34 = "Baiklah.",
  str_voice_1400451_35 = "Aku siap.",
  str_voice_1400451_36 = "Sakit adalah penyelamatan dari dosa.",
  str_voice_1400451_37 = "Aku mempersembahkan seluruh jiwa ragaku…",
  str_voice_1400451_38 = "Aku mengorbankan seluruh jiwa ragaku…",
  str_voice_1400451_39 = "Mendidih…",
  str_voice_1400451_40 = "Najis, hina…",
  str_voice_1400451_41 = "Truth akan mengampuniku, 'kan?",
  str_voice_1400451_42 = "Ziarah telah menantiku… Ini adalah langkah pertama.",
  str_voice_1400451_43 = "Oh, aku hanyalah monster malang yang menyedihkan…",
  str_voice_1400451_44 = "Kau tersesat? Kalau begitu, sebaiknya kau mengakui dosa-dosamu…",
  str_voice_1400451_45 = "Aku tidak pantas…",
  str_voice_1400451_46 = "Seharusnya tidak begitu…",
  str_voice_1400451_47 = "Haruskah begitu?",
  str_voice_1400451_48 = "Terima kasih…",
  str_voice_1400451_49 = "Mereka pernah melindungiku, menghormatiku, dan mengangkatku ke altar. Mereka juga menyakitiku, membenciku, dan memaksaku masuk ke dalam jurang yang tak berujung.",
  str_voice_1400451_50 = "Eclipsite menyakiti Aurorian seperti halnya Aurorian saling menyakiti satu sama lain. Aku bukan Eclipsite maupun Aurorian. Aku hanyalah monster hina dan tak berdaya.",
  str_voice_1400451_51 = "True Order adalah satu-satunya tempat perlindunganku. Aku tak perlu mengerti atau berpikir. Aku hanya mengikuti Truth dan terus maju.",
  str_voice_1400451_52 = "Alchemy Stars.",
  str_voice_1400451_53 = "Halo…",
  str_voice_1400451_54 = "Pagi… telah tiba seperti yang dijadwalkan.",
  str_voice_1400451_55 = "Kenapa kau belum datang juga?",
  str_voice_1400451_56 = "Aku menunggu hukuman malam…",
  str_voice_1400451_57 = "Tahun Baru adalah anugerah.",
  str_voice_1400481_1 = "Apa maksud mereka dengan mengatakan bahwa orang-orang Umbraton tidak berkontribusi pada pembangunan Lumopolis? Beberapa tahun yang lalu, mereka akan menyesali kata-kata itu.",
  str_voice_1400481_2 = "Kalau takut sakit, mungkin sebaiknya kau pergi saja sekarang. Aku harus fokus untuk melindungi Robyn, jadi kau harus jaga diri.",
  str_voice_1400481_3 = "Apa kau melakukan sesuatu dengan Robyn belakangan ini? Ya, agak aneh kalau dia bicara dengan seseorang.",
  str_voice_1400481_4 = "Aku menghormati rakyat jelata karena dulu aku, dan sekarang juga masih, salah satu dari mereka. Namun, beberapa orang tidak memahaminya…",
  str_voice_1400481_5 = "Aku bukan pengembara yang sembrono dan lemah seperti dulu. Tak seorang pun bisa mengalahkanku dengan mudah sekarang.",
  str_voice_1400481_6 = "Eclipsite, bencana alam, bandit… Di dunia ini, kau tak pernah tahu kapan kau akan merasakan dinginnya pedang menyentuh lehermu. Namun, aku telah memulai perjalanan tanpa jalan pulang ini dan tak akan pernah menyesalinya.",
  str_voice_1400481_7 = "Wah, wah… Dulu aku selalu mengira kau ini orang yang paling membosankan, tapi setidaknya kau mengerti humor… tidak seperti orang-orang ini.",
  str_voice_1400481_8 = "Kau keren, tapi seorang penguasa tidak bisa menjadi raja dan penguasa bijak sekaligus. Kau hanya bisa memilih salah satu. Bagaimana kalau kau belajar dari Shadowlord kami?",
  str_voice_1400481_9 = "Bagus sekali. Pada prinsipnya, kami setuju dengan caramu melakukan sesuatu. Hmm, bahkan mungkin kita memiliki kesamaan. Kau sudah mempertimbangkan untuk bergabung dengan Umbraton?",
  str_voice_1400481_10 = "Kau suka mengguruiku, tapi lihat saja dirimu sekarang… Bukankah kau juga cuma keluyuran? Kita ini sama saja.",
  str_voice_1400481_11 = "Hah? Kenapa kau membiarkanku mengawasi tempat ini?",
  str_voice_1400481_12 = "Aku telah mengirim pakaian kotormu untuk dicuci kering. Jangan percaya pada anak baru yang tidak becus memilah pakaiannya sendiri.",
  str_voice_1400481_13 = "Hei, aku ini perempuan! Aku juga punya sopan santun, tahu…",
  str_voice_1400481_14 = "Kalau sampai terbawa emosi, cepat atau lambat pasti akan berujung pada bencana… Robyn adalah pengecualian.",
  str_voice_1400481_15 = "Selamat menikmati! Lagi pula, tak seorang pun tahu akan seperti apa ulang tahun berikutnya.",
  str_voice_1400481_16 = "Hei, Boatscrapper!",
  str_voice_1400481_17 = "Ayo bekerja! Ketepatan waktu sangat penting! Selalu tepat waktu, ya!",
  str_voice_1400481_18 = "Bagaimana dengan Robyn? Aku belum melihatnya sejak 8 menit lalu. Di mana dia? Robyn!",
  str_voice_1400481_19 = "Menurut kontrak, seharusnya tugasku sudah selesai sekarang, tapi aku harus kerja lembur. Sialan betul pemimpin Guild yang tak bermoral itu!",
  str_voice_1400481_20 = "Mangsa tidak mungkin bergabung dengan geng hanya karena penasaran, mereka akan melahapmu.",
  str_voice_1400481_21 = "Selama upahnya dibayarkan dan peraturannya diikuti… Mau Lumopolis atau Rediesel Wrench, biarkan saja…",
  str_voice_1400481_22 = "Bayangan mengawasimu.",
  str_voice_1400481_23 = "Kuharap aku bisa mencabik-cabik Eclipsite itu, tapi aku tidak boleh gegabah.",
  str_voice_1400481_24 = "Puji Robyn? Kau ini bercanda! Aku tak bisa memujinya bahkan kalau mau!",
  str_voice_1400481_25 = "Pemimpin Guild memang sangat pelit, tapi terkadang kemurahan hatinya tak mengenal batas.",
  str_voice_1400481_26 = "Apa yang aku sukai? Robyn… Apa lagi selain Robyn?",
  str_voice_1400481_27 = "Orang bodoh yang buta, orang yang tidak profesional, pengecut yang tak berani bertarung… Masing-masing dari mereka adalah mimpi buruk dengan caranya sendiri.",
  str_voice_1400481_28 = "Kita harus cari cara untuk pergi ke Umbraton… Bagaimana menurutmu, Boatscrapper? Mau buat kesepakatan?",
  str_voice_1400481_29 = "Halo, kau butuh bantuanku? Namun, hanya sebagai pekerja sementara karena aku punya pekerjaan yang layak di Guild. Ayo cepat, siapa yang ingin kausingkirkan?",
  str_voice_1400481_30 = "Aku makin mahir memanfaatkan dia.",
  str_voice_1400481_31 = "Rasanya kekuatan kembali terkumpul.",
  str_voice_1400481_32 = "Robyn! Mulai sekarang, tak seorang pun bisa menyakiti kita!",
  str_voice_1400481_33 = "Aku pasang taruhan untuk Dayna, anak muda itu pasti akan jadi pemenangnya.",
  str_voice_1400481_34 = "Bagus. Kalau begitu, aku akan bertarung di sisimu.",
  str_voice_1400481_35 = "Pedang ini telah diasah.",
  str_voice_1400481_36 = "Kesabaranku sudah lama hilang…",
  str_voice_1400481_37 = "Jangan minta ampun!",
  str_voice_1400481_38 = "Kalau kau takut, tutup saja matamu!",
  str_voice_1400481_39 = "Hanya butuh lima menit untuk menumbangkanmu.",
  str_voice_1400481_40 = "Sekarang beristirahatlah dalam damai.",
  str_voice_1400481_41 = "Bertarung! Jangan membuatku jengkel! Di mana Robyn?",
  str_voice_1400481_42 = "Aku sudah terbiasa menang seperti ini! Iya, 'kan, Robyn?",
  str_voice_1400481_43 = "Kalau lain kali terjadi seperti ini pada Robyn, aku tak akan mengampunimu…",
  str_voice_1400481_44 = "Bukan masalah! Aku akan bertahan hingga akhir!",
  str_voice_1400481_45 = "Baik, akan kuterima. Namun, kalau aneh-aneh, kuhajar kau!",
  str_voice_1400481_46 = "Kok… kau tahu? Kebetulan?",
  str_voice_1400481_47 = "Harta yang bagus… Kau punya bakat berbisnis juga, ya.",
  str_voice_1400481_48 = "Kalau ada seseorang yang benar-benar peduli padaku seperti ini, aku jadi merasa aneh…",
  str_voice_1400481_49 = "Robyn dan aku sama-sama mengalami masa perang. Namun, kejahatan brutal akibat perang yang menginjak-injak martabat dan kehidupan membuat kita jadi serakah. Itu yang perlu diwaspadai sekarang.",
  str_voice_1400481_50 = "\"Pada akhirnya kita akan menjadi seperti mereka…\" Melegakan sekali, seakan-akan rasa lapar dan prasangka benar-benar akan hilang. Hanya bocah naif yang akan percaya hal seperti itu.",
  str_voice_1400481_51 = "Balas setiap kebaikan dengan bermurah hati kepada orang yang kaucintai dan jangan tunjukkan belas kasihan kepada musuh. Robyn dan aku tidak lagi bergantung pada orang lain, tapi kami tak akan pernah melupakan apa yang telah teman dan keluarga kami lakukan untuk kami.",
  str_voice_1400481_52 = "Alchemy Stars.",
  str_voice_1400481_53 = "Boatscrapper!",
  str_voice_1400481_54 = "Pagi! Apa kau sudah bangun?",
  str_voice_1400481_55 = "Aku mencarimu tadi. Di mana semua orang?",
  str_voice_1400481_56 = "Oh! Selamat malam.",
  str_voice_1400481_57 = "Ayo rayakan Tahun Baru yang berharga ini.",
  str_voice_1400541_1 = "Minuman terbaik adalah minuman dingin gratis yang kaudapatkan dari bar favoritmu setelah seharian bekerja!",
  str_voice_1400541_2 = "Mengenakan seragam yang rapi akan menginspirasimu untuk menganggap serius pekerjaan dan misi! Itu sebabnya kau harus menyetrika seragammu setiap hari!",
  str_voice_1400541_3 = "Hidup akan memberikan banyak hal yang harus kita anggap serius. Entah berapa kali pun kita gagal, kita harus berani untuk mencoba lagi!",
  str_voice_1400541_4 = "Kalau bisa bekerja lebih keras setiap hari, kau pasti akan jadi orang yang hebat di masa depan, seperti Kapten Carleen yang teguh, bisa diandalkan, dan hampir sempurna.",
  str_voice_1400541_5 = "Kapan City Lord akan menerimaku, ya… Omong-omong, lebih baik aku memperbaiki lampu jalan yang tak sengaja kurusak saja.",
  str_voice_1400541_6 = "Ketika rasanya sudah ingin menyerah, aku kembali mendapatkan kepercayaan diri dengan melihat lampu ini. Sama sekali bukan perilaku yang aneh. Mendekatlah, pandangi cahayanya dan kau akan paham.",
  str_voice_1400541_7 = "Keseriusan adalah suatu bentuk kekesatriaan. Kau akan mendapat kehormatan jika terus berlatih. Sayang sekali para bangsawan di Lumopolis tidak memahami ini.",
  str_voice_1400541_8 = "Beberapa orang bilang bahwa aku terlalu serius, seperti penggaris busur di tanganku ini, yang kaku dan tidak fleksibel. Bagaimana menurutmu? Oh? Apa benar-benar itu masalahnya?",
  str_voice_1400541_9 = "Aku… aku tidak tahu kenapa Duke memberiku jabatan sepenting ini. Apa karena aku menggambar ulang seluruh peta itu, ya?",
  str_voice_1400541_10 = "Haha, aku hanya sedang memikirkan cara melakukan pekerjaanku—aku tidak melamun, kok!",
  str_voice_1400541_11 = "Aku tidak hanya bekerja untuk mencari nafkah—bagiku, ini adalah misi yang mulia, seperti halnya hidupku!",
  str_voice_1400541_12 = "Sebaiknya kau fokus begitu mulai bekerja. Kalau tidak, pekerjaanmu pasti akan kacau. Ayo, fokus!",
  str_voice_1400541_13 = "Bagaimana cara meningkatkan konsentrasi? Kau tahu cara yang lebih baik?",
  str_voice_1400541_14 = "Mencatat akan mengalahkan ingatan yang baik, jadi kau harus selalu membawa pena dan kertas… Tunggu, biar kuambilkan.",
  str_voice_1400541_15 = "Selamat ulang tahun! Aku… aku ingin memberimu sesuatu, tapi kantongku sedang kempis bulan ini! Lain kali pasti aku akan memberimu hadiah!",
  str_voice_1400541_16 = "Sekarang aku sedang bertugas. Kelihatannya semua baik-baik saja hari ini. Colossus cukup stabil dan tak akan jatuh dalam waktu dekat.",
  str_voice_1400541_17 = "Semangat! Ini waktunya bekerja!",
  str_voice_1400541_18 = "Lagi-lagi hari ini tenang dan berjalan lancar… Selamat, ya.",
  str_voice_1400541_19 = "Ah! Aku sedang bertugas! … Lihat mataku, aku tidak tidur, kok!",
  str_voice_1400541_20 = "Lumopolis berhasil menjadi kota terhebat di benua ini karena selalu menjunjung kekesatriaan.",
  str_voice_1400541_21 = "Kudengar bahwa Illumina telah menerapkan peraturan administratif yang efektif. Andai saja peraturan ini bisa diterapkan di Lumopolis…",
  str_voice_1400541_22 = "Demi White Night!",
  str_voice_1400541_23 = "Eclipsite adalah musuh bebuyutan. Kita harus menyingkirkan semua Eclipsite yang terlihat!",
  str_voice_1400541_24 = "Huh, kudengar bahwa Four Angels menghancurkan area perkotaan di Lumopolis lagi. Peta-petanya harus kugambar ulang… lagi… Huh…",
  str_voice_1400541_25 = "Lord menangani urusan pemerintahan dengan begitu cermat. Aku akan berusaha sebaik mungkin agar dia bisa istirahat sesekali.",
  str_voice_1400541_26 = "Aku suka orang yang serius, terutama orang-orang yang bekerja keras dan sangat fokus!",
  str_voice_1400541_27 = "Jika Lumopolis runtuh suatu hari nanti, itu pasti karena para bangsawan…",
  str_voice_1400541_28 = "Tempat ini sangat luas dan bahkan melayang di udara… Seperti Lumopolis kecil saja…",
  str_voice_1400541_29 = "Semua yang kaudapatkan dalam hidup adalah berkah. Aku Nadine, orang yang menyinari Lumopolis dengan lentera di tanganku.",
  str_voice_1400541_30 = "Cahayanya makin terang.",
  str_voice_1400541_31 = "Angkat lenteramu dan musuhmu akan berjatuhan.",
  str_voice_1400541_32 = "Cahaya lentera itu akan bersinar sepanjang malam.",
  str_voice_1400541_33 = "Akhirnya aku… bisa berjaga semalaman.",
  str_voice_1400541_34 = "Aku mengandalkanmu!",
  str_voice_1400541_35 = "Cahaya… berkumpullah…",
  str_voice_1400541_36 = "Lenteranya sudah dinyalakan.",
  str_voice_1400541_37 = "Cahaya akan berkuasa selamanya!",
  str_voice_1400541_38 = "Di bawah cahaya lentera!",
  str_voice_1400541_39 = "Tolong sembuhkan kami!",
  str_voice_1400541_40 = "Cahaya! Kalahkan musuh!",
  str_voice_1400541_41 = "Mohon ikuti lentera ini.",
  str_voice_1400541_42 = "White Night selamanya!",
  str_voice_1400541_43 = "Lenteraku meredup…",
  str_voice_1400541_44 = "Hal-hal baru untuk dipelajari harus dipelajari di tempat baru.",
  str_voice_1400541_45 = "Terima kasih banyak atas hadiahmu.",
  str_voice_1400541_46 = "Wow, aku suka ini! Terima kasih!",
  str_voice_1400541_47 = "Aku benar-benar boleh memilikinya!?",
  str_voice_1400541_48 = "Aku akan balas memberimu hadiah! Aku janji!",
  str_voice_1400541_49 = "Aku hanya orang biasa, jadi yang kumiliki hanyalah bakat orang biasa—keseriusan, kerja keras, dan konsentrasi.",
  str_voice_1400541_50 = "Seorang kesatria harus bungkam. Berita baik atau informasi negatif, semua harus selalu disimpan di dalam hati dan tidak pernah dibagikan dengan sembarangan.",
  str_voice_1400541_51 = "Bahkan ada bayangan di Lumopolis, itu sebabnya kami punya Nightwatch… Oh, itu hanya legenda—yah, mungkin saja…",
  str_voice_1400541_52 = "Alchemy Stars!",
  str_voice_1400541_53 = "Halo!",
  str_voice_1400541_54 = "Selamat pagi!",
  str_voice_1400541_55 = "Kau sibuk?",
  str_voice_1400541_56 = "Kau sudah istirahat?",
  str_voice_1400541_57 = "Selamat Tahun Baru!",
  str_voice_1400571_1 = "Aduh… Kenapa rambutku kelihatan acak-acakan, sih? Perlu usaha keras untuk merapikannya. Namun, rambutku halus sekali kalau dipegang, lho. Mau pegang?",
  str_voice_1400571_2 = "Pekerjaan departemen intelijen sangat membosankan dan ruwet sehingga terkadang bisa menyulitkan, tapi ada keuntungannya juga, lho. Seperti… Yah, aku akan memberitahumu rahasia Vice dengan imbalan ikan kering.",
  str_voice_1400571_3 = "Tidak! Aku tak mau kalau dipaksa. Aku tidak suka melakukan apa yang orang lain lakukan. Semua kucing seperti ini, 'kan?",
  str_voice_1400571_4 = "Celaka, bagaimana ini? Kelihatannya aku jadi sedikit lebih kuat lagi.",
  str_voice_1400571_5 = "Aku sangat lemah, tapi Yumi justru kebalikannya. Aku tahu Yumi telah melindungiku… meskipun kami tak bisa bertemu.",
  str_voice_1400571_6 = "Tidurlah, Philyshy. Kalau bangun nanti, kau akan melihat setumpuk ikan kering di kamar, meong. Tak akan ada Eclipsite, meong. Tak ada Eclipse, meong.",
  str_voice_1400571_7 = "Eh? Di laporan psikologiku tertulis banyak hal tentang Yumi dan kegemaranku akan tidur. Yah… Aku tahu, kok! Lagi pula aku ini kucing.",
  str_voice_1400571_8 = "Kau pikir aku bisa disuap dengan ikan kalengan murahan ini? Dan kaviar murahan semacam itu? Kau bercanda, ya?",
  str_voice_1400571_9 = "Apa Yumi baru saja keluar? Dia anak yang kesepian. Kalau kau bertemu dengannya, tolong perlakukan dia dengan baik. Aku? Kau juga bisa memperlakukanku seperti itu.",
  str_voice_1400571_10 = "Cahaya yang hangat, suhu yang nyaman, dan lingkungan yang sempurna… Aku malas sekali. Rasanya aku tidak ingin melakukan apa pun, meong.",
  str_voice_1400571_11 = "Meskipun aku tak akan menolak permintaanmu, aku tak suka berurusan dengan masalah, meong.",
  str_voice_1400571_12 = "Kau lihat topi, meong? Aduh, aku melupakannya lagi, meong!",
  str_voice_1400571_13 = "Menjaga kebersihan itu penting, meong. Jangan lupa cuci tangan dan sering-sering berkumur, meong. Dan kalau memungkinkan, jaga jarak, meong.",
  str_voice_1400571_14 = "Nih, ini teka-teki tentang keinginan, meong. Kau bisa menebak apa yang kuinginkan, meong?",
  str_voice_1400571_15 = "Oh, mau dengar lagu Selamat Ulang Tahun dariku, meong? Satu bait saja, ya. Selamat ulang tahun…",
  str_voice_1400571_16 = "Sore hari memang luar biasa! Pasti menyenangkan rasanya kalau bisa tidur siang sebentar, meong! Eh? Aku tidak bermaksud malas-malasan, meong!",
  str_voice_1400571_17 = "Apa? Apa kau belum pernah melihat kejengkelan pagi hari, meong? Si Vivian! Aku tidak percaya dia memasang 10 alarm untukku. Sialan, meong!",
  str_voice_1400571_18 = "Sudah saatnya briefing lagi, meong. Namun, aku belum melakukan apa pun, meong.",
  str_voice_1400571_19 = "Mengantuk sekali… Tak tahan lagi, meong… Nyam, nyam, banyak sekali ikannya, banyak sekali, meong…",
  str_voice_1400571_20 = "Semua orang di Illumina terlalu serius bekerja, meong. Seharusnya sesekali mereka santai sedikit, meong!",
  str_voice_1400571_21 = "Aku sangat iri dengan makhluk-makhluk bersayap, meong. Terutama dengan yang punya bulu ringan. Hihi!",
  str_voice_1400571_22 = "Jayalah Illumina, meong…",
  str_voice_1400571_23 = "Eclipsite kau bilang? Mereka itu bau, meong. Dan tidak memedulikan kebersihan diri, meong.",
  str_voice_1400571_24 = "Ssst! Pelankan suaramu. Kepala Vivian tertidur. Dia pasti kelelahan karena pekerjaan, meong.",
  str_voice_1400571_25 = "Ekor Officer Sharona… Itu memang bukan mainan, tapi aku tak tahan meong!",
  str_voice_1400571_26 = "Kau boleh mengintip sedikit, meong! Ikan kering emas legendaris, harta karunku yang berharga, meong!",
  str_voice_1400571_27 = "M-meongapa? Aku harus lari 800 meter? Mana mungkin aku kuat. Lari 100 meter saja aku hampir tak sanggup, meong.",
  str_voice_1400571_28 = "Luas sekali! Bisakah kau menyiapkan kamar untukku juga, meong? Aku ingin lantainya dilapisi selimut lembut, meong.",
  str_voice_1400571_29 = "Hah? Memperkenalkan diri? Kalau tidak usah saja bagaimana, meong? Merepotkan sekali. Aku hanya ingin tidur, meong. Kemarin aku kerja lembur dan sekarang… terlalu… capek… untuk…",
  str_voice_1400571_30 = "Meonguuu… Aku sudah jadi lebih kuat lagi!",
  str_voice_1400571_31 = "Apa ada cara lain untuk bermalas-malasan, meong?",
  str_voice_1400571_32 = "Aku ingin berjalan cepat dan mendengarkan suara lain.",
  str_voice_1400571_33 = "Tak lama mimpi indahnya mau dimulai, meong. Biarkan Philyshy tidur sebentar, ya, meong.",
  str_voice_1400571_34 = "*Huahh* Sudah mulai, meong?",
  str_voice_1400571_35 = "Tiba-tiba aku merasa sangat mengantuk.",
  str_voice_1400571_36 = "Aduh, kelopak mataku makin berat…",
  str_voice_1400571_37 = "Meong! Berhenti! Jangan bergerak. Biarkan aku istirahat, meong.",
  str_voice_1400571_38 = "Meong! Kalian semua bodoh sekali, meong.",
  str_voice_1400571_39 = "Aku akan istirahat kalau sudah selesai.",
  str_voice_1400571_40 = "Sudah selesai, meong!",
  str_voice_1400571_41 = "Oke, oke, aku paham.",
  str_voice_1400571_42 = "Hah? Mereka kalah.",
  str_voice_1400571_43 = "Ups! Kita gagal.",
  str_voice_1400571_44 = "Oh, bukankah menyenangkan kalau aku bisa tidur siang sebentar?",
  str_voice_1400571_45 = "Mm, ah, biarkan Philyshy tidur sebentar, meong.",
  str_voice_1400571_46 = "Meong? Kau juga punya hadiah untuk Yumi? Bagus sekali!",
  str_voice_1400571_47 = "Hah? Aku harus beterima kasih padamu? Baiklah… Terima kasih, ya?",
  str_voice_1400571_48 = "Meong! Kami sudah lama menginginkan ini! Kewren sekali!",
  str_voice_1400571_49 = "Jadi, bagaimana kalau aku berdoa dan bekerja keras sekuat tenaga? Apa yang bisa kucapai? Kurasa aku mau tidur saja, meong.",
  str_voice_1400571_50 = "Sebenarnya aku punya harapan kecil, meong… Dulu ada kucing yang menemaniku. Satu-satunya harapanku adalah agar dia mau kembali, meong.",
  str_voice_1400571_51 = "Selama Philyshy mau, aku akan selalu menjadi diriku, Yumi, untuk melindunginya dari penderitaan dan memenuhi harapannya… Aku bisa melakukan apa pun untuknya, kecuali menemuinya secara langsung.",
  str_voice_1400571_52 = "Alchemy Stars, meong.",
  str_voice_1400571_53 = "Meong…",
  str_voice_1400571_54 = "Hiks… Aku terjaga, meong…",
  str_voice_1400571_55 = "Ikan kering… Ikan kering…",
  str_voice_1400571_56 = "Meong! Menyebalkan sekali! Di mana kau?",
  str_voice_1400571_57 = "Waow! Benarkah ini sudah Tahun Baru, meong?",
  str_voice_1400681_1 = "Pemberani sepertiku tidak perlu menggunakan tipu muslihat bodoh seperti berpura-pura mati… Apakah melakukannya saat masih kecil juga termasuk? Tentu saja tidak!",
  str_voice_1400681_2 = "Kalau Sinsa si ceroboh ingin menangkapmu, tendang saja tempurung lututnya—hiya! Itu selalu berhasil!",
  str_voice_1400681_3 = "Hawa di gurun bisa sangat panas atau sangat dingin. Kalau tidak memakai jaket, mungkin bertahan tiga hari pun kau tak bakal sanggup, 'kan? Ck, ck, ck…",
  str_voice_1400681_4 = "Kenapa aku sangat terobsesi dengan kecepatan angin? Kaulihat sayap-sayapku yang pendek tapi kuat? Masih belum paham? Coba lihat sekali lagi. Mendekatlah!",
  str_voice_1400681_5 = "Ini tiga peralatan perjalananku—jaket ultraringan antidingin dengan insulasi panas, sepasang kacamata angin yang keren, dan jetpack canggih! Keren, 'kan?",
  str_voice_1400681_6 = "Tak penting jika perjalanannya berbahaya karena kau bisa berbalik atau kabur! Yang penting adalah kemampuan melalui satu meter pertama dan keberanian untuk menghadapi tantangan!",
  str_voice_1400681_7 = "Oh? Mau pegang sayapku? Ayo, sentuh saja kalau kau tidak takut bakal tersenggol! Tak usah takut, kemungkinan terburuknya adalah kau bakal terbanting sampai pingsan!",
  str_voice_1400681_8 = "Mendekatlah, jangan takut… Apa yang akan kulakukan padamu? Tentu saja aku bisa melakukan apa pun semauku! Kau kira kau bisa melawan? Hehe!",
  str_voice_1400681_9 = "Jangan takut. Berjalanlah dengan sombong ke arahku! Akan kuberi pelajaran orang-orang yang berani mengganggumu! Hehehe, kalau aku… yah, kita ini 'kan sudah akrab!",
  str_voice_1400681_10 = "Saking bosannya, bulu-buluku serasa mau rontok! Ayo bermain denganku! Apa? Mau bergerak atau diam saja, kok buluku tetap rontok, ya?",
  str_voice_1400681_11 = "Ah, ya, seperti yang kuduga. Matamu memang jeli! Mulai sekarang ini adalah wilayahku! Hahaha!",
  str_voice_1400681_12 = "Coba balik badan… Rupanya kau memang tidak punya bulu ekor sama sekali, ya… Kau tidak kedinginan?",
  str_voice_1400681_13 = "Tunggu sebentar, aku mau memompa jetpack dulu… Bagaimana? Tentu saja dengan meniupnya! …Tiup lalu tambahkan bahan bakar.",
  str_voice_1400681_14 = "Apa yang harus kita lakukan kalau bertemu musuh? Tentu langsung serbu saja. Kalau ada masalah, kau bisa balik badan kapan pun!",
  str_voice_1400681_15 = "Ini hari ulang tahunmu, ya? Tunggu sebentar… Lihat, bulu-buluku rontok. Ambillah, kau bisa bermain dengan itu.",
  str_voice_1400681_16 = "Oh! Akhirnya kau kembali juga! Bersemangatlah dan gerakkan tanganmu yang lemah untukku!",
  str_voice_1400681_17 = "Kau sudah bangun? Ambillah, matamu pasti akan langsung segar setelah kuberi dua… Dua apa? Pijatan lutut!",
  str_voice_1400681_18 = "Sandworm kering, kadal kering, dan cacing tanah kering yang lezat! Mau mencicipinya? Hehehe, cobalah!",
  str_voice_1400681_19 = "Tidak bisa tidur, ya? Sini, biar kukipasi! …Aku hanya mengipasimu, jangan gugup begitu.",
  str_voice_1400681_20 = "Hehe, Courier Union memang sangat hebat! Meskipun berskala kecil, mereka bisa melakukan apa saja!",
  str_voice_1400681_21 = "Cih, memangnya kenapa kalau penerimanya adalah anggota Rediesel Wrench? Bukankah mereka akan jadi tak bersemangat setelah bermain-main sebentar?",
  str_voice_1400681_22 = "Courier Union selalu berhasil mengantarkan surat!",
  str_voice_1400681_23 = "Apakah Eclipsite itu mengerikan? Hmm? Aku tak terkalahkan selama mereka punya tempurung lutut!",
  str_voice_1400681_24 = "Dove tiba-tiba membatalkan janjinya denganku lagi! Akan kucabuti semua bulunya kapan-kapan!",
  str_voice_1400681_25 = "Dia bersuara sangat keras, punya Speaker, mengantar surat dengan kecepatan ultra, dan kehilangan bulu-bulunya juga, keren—",
  str_voice_1400681_26 = "Aku suka mengumpulkan bulu, terbang secepat kilat, dan mengincar tempurung lutut!",
  str_voice_1400681_27 = "Aku—paling benci pada benda-benda berlendir! Memikirkannya menempel di buluku saja membuatku jijik!",
  str_voice_1400681_28 = "Bukankah Colossus itu Speaker? Apa bedanya? Oh, itu benda mati… Aneh sekali.",
  str_voice_1400681_29 = "Benar! Aku misil lonjong berkecepatan tinggi yang melesat di gurun, dikenal dengan julukan Light Speed Spiral, kurir imut dan pemberani, Wendy!",
  str_voice_1400681_30 = "Aku yang lebih cepat dan kuat!",
  str_voice_1400681_31 = "Wow! Aku sangat luar biasa!",
  str_voice_1400681_32 = "Angin kecil berubah menjadi topan kecil!",
  str_voice_1400681_33 = "Sekarang aku sudah siap untuk menantang benua ini!",
  str_voice_1400681_34 = "Ingin aku pelan-pelan saja?",
  str_voice_1400681_35 = "Kecepatan angin—sudah!",
  str_voice_1400681_36 = "Akan kutunjukkan padamu seperti apa kecepatan angin itu!",
  str_voice_1400681_37 = "Pendaratan kecepatan angin!",
  str_voice_1400681_38 = "Ada begitu banyak kecepatan angin, aku sampai tidak tahu namanya!",
  str_voice_1400681_39 = "Tendangan kecepatan angin!",
  str_voice_1400681_40 = "Serangan kecepatan angin!",
  str_voice_1400681_41 = "Bisakah kau mengikuti serangan kecepatan anginku?",
  str_voice_1400681_42 = "Kecepatan angin untuk kemenangan!",
  str_voice_1400681_43 = "Demi angin, aku hampir saja harus pura-pura mati!",
  str_voice_1400681_44 = "Ada yang perlu kuantar? Aku bisa mengantarnya ke mana saja.",
  str_voice_1400681_45 = "Kenapa kau memberiku ini? Mau mengirimkannya?",
  str_voice_1400681_46 = "Hehehe, sepertinya kau tahu harus bagaimana.",
  str_voice_1400681_47 = "Jadi, aku penerimanya seperti biasa?",
  str_voice_1400681_48 = "Aku sudah menerimanya! Hadiah yang aku suka! Horeeee!",
  str_voice_1400681_49 = "Mudah sekali menemukan penerima? Ada banyak orang yang tinggal di gurun. Cari mereka satu per satu… Kecuali penerimanya sudah pergi, haha.",
  str_voice_1400681_50 = "Biasanya Speaker adalah makhluk yang sudah dijinakkan. Aku belum punya… Apa aku perlu menangkap satu? Hehehe, mendekatlah, jangan takut…",
  str_voice_1400681_51 = "Pernah lihat lautan Eclipsite? Aku pernah saat masih pemula. Kau tahu, dia yang bekerja keras akan mendapatkan hasilnya. Sudah wajar aku jadi keren sekali!",
  str_voice_1400681_52 = "Alchemy Stars!",
  str_voice_1400681_53 = "Aku akan mencarimu sekarang!",
  str_voice_1400681_54 = "Kau masih mengantuk, ya?",
  str_voice_1400681_55 = "Ayo! Maju dengan kecepatan angin!",
  str_voice_1400681_56 = "Aku akan mencarimu. Jangan gugup begitu, dong.",
  str_voice_1400681_57 = "Woohoo! Selamat Tahun Baru!",
  str_voice_1400831_1 = "Menjawab pertanyaan. Menerjemahkan dan mengonversi. Menjawab. Lilliam adalah klona Lilin, bukan robot tapi pelayan.",
  str_voice_1400831_2 = "Menjawab. Kalimat No. 1 sudah diprogram. Menerjemahkan dan mengonversi… Kepribadian No. 1 lebih kaku.",
  str_voice_1400831_3 = "Menerjemahkan dan mengonversi. Tolong perlakukan No. 1 sebagai pelayan biasa dan beri dia pekerjaan. Tolong perlakukan No. 2 sebagai pelayan pemalas dan beri dia banyak pekerjaan.",
  str_voice_1400831_4 = "Pengungkapan informasi. Sebuah kepribadian terprogram ditulis di dalam Lilliam dan disimpan dalam mode pemikiran tetap. Penghapusan diizinkan menurut izin penentuan kehendak.",
  str_voice_1400831_5 = "Pengungkapan informasi. No. 1. Izin penentuan level 1. Kerahasiaan level 3. Basis data level 3. Kunci evolusi level 2.",
  str_voice_1400831_6 = [[
- Perkenalan. Lilliam No. 2. Basis data level 4. Kunci evolusi level 1.
- Menerjemahkan. Sedikit bodoh. Tidak pernah belajar.]],
  str_voice_1400831_7 = "Menerjemahkan dan mengonversi. Tolong jangan cemas. Jika No. 1 terluka, dia bisa diobati dan digantikan.",
  str_voice_1400831_8 = "Pengungkapan informasi. Begitu juga halnya dengan Lilliam. Perintah pertama adalah melindungi Lilin. Perintah kedua adalah melindungimu.",
  str_voice_1400831_9 = "Tolong jangan terkejut. No. 1 bisa menghapus kepribadian yang terprogram berdasarkan evaluasinya sendiri. Laporan lebih lanjut. No. 1 ingin berkomunikasi secara lebih mendalam denganmu.",
  str_voice_1400831_10 = "Deteksi kerentanan… Deteksi selesai. Perintah selesai. Lilliam akan melayanimu dan selalu siap sedia.",
  str_voice_1400831_11 = "Berganti status. Menerjemahkan dan mengonversi. No. 1—Pelayan Utama. Selalu siap menyambut tamu.",
  str_voice_1400831_12 = "Mata: Kosong. Jawaban: No. 1 akan merawat mata dengan baik. Jangan khawatir.",
  str_voice_1400831_13 = "No. 1 sudah selesai membersihkan kamar. Tidak ada debu yang terlewat.",
  str_voice_1400831_14 = "Penjelasan otomatis. Ada Lilliam lain selain No. 1 dan No. 2.",
  str_voice_1400831_15 = "Mengeksekusi 0522. Mendekatlah, Master. Eksekusi: Protokol ulang tahun. Selamat ulang tahun.",
  str_voice_1400831_16 = "Selamat datang kembali, Master. Penjelasan: Teh hitam sudah dihidangkan.",
  str_voice_1400831_17 = "Selamat pagi, Master. Membuat penjelasan. Sarapan sudah siap.",
  str_voice_1400831_18 = "Selamat datang kembali, Master. Bertanya: Apakah Master ingin santap malam atau pencuci mulut?",
  str_voice_1400831_19 = "Master pasti lelah. Bertanya: Apakah Master ingin mandi sekarang?",
  str_voice_1400831_20 = "Perintah selesai. Penentuan level 3 adalah melindungi Illumina. Orang yang memberi perintah—Reinhardt.",
  str_voice_1400831_21 = "Memverifikasi perintah. Selesai. Terbuka. Lilliam No. 4 akan mengikuti True Order.",
  str_voice_1400831_22 = "Demi… Kehormatan Lilin.",
  str_voice_1400831_23 = "Menjawab. Perintah penyingkiran. Prioritas level 4. Menolak perintah. Prioritas level 3.",
  str_voice_1400831_24 = "Penentuan target. Peneliti fanatik. Bahaya level 2. Jangan berdua saja dengannya.",
  str_voice_1400831_25 = "Penentuan target. Kucing putih. Kebocoran informasi berisiko sedang. Bahaya level 2.",
  str_voice_1400831_26 = "Menjawab. Lilliam menyukai kegiatan bersih-bersih dan peralatan logam yang lebih ringan.",
  str_voice_1400831_27 = "Izin penentuan level 1. Mengizinkan \"tidak suka\". Menjawab. No. 1 tidak suka kotoran.",
  str_voice_1400831_28 = "Menentukan. Sinyal koneksi terdeteksi. Pita gelombang mirip. Melacak. Gagal. Melakukan pelacakan entitas.",
  str_voice_1400831_29 = "Memverifikasi perintah. Selesai. No. 1, ganti status, pelayan. Ini pernyataan untuk Master. Lilliam akan melindungi Master.",
  str_voice_1400831_30 = "Menentukan. Peningkatan kemampuan.",
  str_voice_1400831_31 = "Memperkuat. Meningkatkan izin.",
  str_voice_1400831_32 = "Membuat pernyataan. Basis data informasi terbuka.",
  str_voice_1400831_33 = [[
- Memperkenalkan Master, Lilin.
- No. 2 melapor untuk bertugas.]],
  str_voice_1400831_34 = "Berganti status. Eksekutor.",
  str_voice_1400831_35 = "Serang. Siap.",
  str_voice_1400831_36 = "Mode aman, dinonaktifkan.",
  str_voice_1400831_37 = "Mode. Penyingkiran wilayah.",
  str_voice_1400831_38 = [[
- Perintah. Penyingkiran wilayah.
- Diterima!]],
  str_voice_1400831_39 = "Mode. Lindungi.",
  str_voice_1400831_40 = "Mode. Tolak.",
  str_voice_1400831_41 = "Berganti status. Commander.",
  str_voice_1400831_42 = "Misi tuntas. Selesai.",
  str_voice_1400831_43 = "Misi gagal. Selesai.",
  str_voice_1400831_44 = "Bertanya. Ini hari yang indah. Ada yang bisa kubantu?",
  str_voice_1400831_45 = "Menentukan. Barang biasa.",
  str_voice_1400831_46 = "Perwakilan No. 1. Menerima hadiah yang disukai.",
  str_voice_1400831_47 = "Berlebihan. Agak biasa.",
  str_voice_1400831_48 = "No. 1, Lilliam, suka hadiahmu.",
  str_voice_1400831_49 = "Membuat pernyataan. Lilliam bisa bicara dengan normal sebagai pelayan, tapi menurut survei, mode bicara No. 1 populer di kalangan pelanggan.",
  str_voice_1400831_50 = "Pengungkapan informasi. No. 1 adalah pelayan biasa saat bangun. Dia mendapati Master Lilin berada di Undercity 28, membuka perintah utama.",
  str_voice_1400831_51 = "Memperkenalkan. Fitur biasa Lilliam: Prosedur, perintah, tidak ada gangguan… Menerjemahkan: Pikiran, misi, tidak bisa menolak.",
  str_voice_1400831_52 = "Alchemy Stars.",
  str_voice_1400831_53 = "Master.",
  str_voice_1400831_54 = "Selamat pagi, Master.",
  str_voice_1400831_55 = "Master ingin minum teh sore ini?",
  str_voice_1400831_56 = "Menerjemahkan dan mengonversi. Lilliam membutuhkanmu.",
  str_voice_1400831_57 = "Selamat Tahun Baru, Master.",
  str_voice_1400861_1 = "Damage dari pedang etiket diubah menjadi obat untuk orang lain. Sungguh ironis, tapi juga sangat benar, 'kan?",
  str_voice_1400861_2 = "Kadang aku menerima permintaan dari Pranatacara Pemakaman untuk mengucapkan salam perpisahan kepada orang yang sudah meninggal dan menghibur kerabat mereka yang berduka. Orang sering bilang bahwa aku sangat cocok untuk pekerjaan ini.",
  str_voice_1400861_3 = "Ini keahlianku, jadi tolong serahkan padaku. Aku hanya perlu membuat semua orang berbaring dengan damai, 'kan?",
  str_voice_1400861_4 = "Akan kuubah dukacita menjadi kekuatan agar aku bisa melakukan apa pun untuk membantu orang-orang yang masih hidup.",
  str_voice_1400861_5 = "Bagi orang-orang yang telah dilupakan di medan perang, nama kalian tak akan terlupakan karena semua orang akan mendoakan kalian. Mereka akan berdoa untuk orang-orang yang telah meninggalkan kalian.",
  str_voice_1400861_6 = "Aku menjaga kenangan orang yang sudah wafat, mengungkapkan kesedihan mereka, memuji kebaikan mereka, dan menyanyikan kemuliaan masa lalu mereka untuk masa depan yang lebih baik!",
  str_voice_1400861_7 = "Duri yang tajam di satu sisi, sulur bunga yang tidak berbahaya di sisi yang lain. Jangan khawatir, aku akan memiringkan ujung yang tepat ke arahmu.",
  str_voice_1400861_8 = "Aku akan mengingat wajahmu, kebaikanmu, kehangatanmu, dan sifatmu yang tak akan pernah pudar. Kau akan selalu ada dalam hatiku.",
  str_voice_1400861_9 = "Aku sudah membawakanmu beberapa sulur bunga. Yang ini memiliki bunga putih yang sangat kusuka. Semoga sulur ini akan terus memberimu kehangatan di sepanjang hayatku.",
  str_voice_1400861_10 = "Ini permainan yang sederhana. Bagaimana kalau kita tebak siapa selanjutnya yang akan pergi? Sebaiknya kau berdoa kalau merasa gelisah…",
  str_voice_1400861_11 = "Aku ingin menanam sulur bunga di tempat terjauh di bawah matahari. Semoga itu akan membuat matahari menyinari bayangan, meskipun hanya sejengkal saja.",
  str_voice_1400861_12 = "Tentu saja aku akan menaruh pedang di tanganku. Demi sopan santun, aku akan berdoa sebelum menyerang.",
  str_voice_1400861_13 = "Bocah malang, aku melihatmu gemetaran. Ulurkan tanganmu kepadaku dan aku akan menghentikannya.",
  str_voice_1400861_14 = "Tidakkah menyelesaikan masalah dengan senyuman sering kali jauh lebih mudah?",
  str_voice_1400861_15 = "Ini adalah hari yang penting. Rayakan hari yang sangat penting ini selama kau masih hidup.",
  str_voice_1400861_16 = "Selamat datang kembali. Kalau kau mau, aku bisa mendoakanmu sedikit lebih lama.",
  str_voice_1400861_17 = "Selamat pagi. Aku senang bisa melihat wajahmu setelah bangun tidur.",
  str_voice_1400861_18 = "Jelajahi hidupmu yang terbatas. Rengkuh kenyataan sepuas hati sebelum kau berbaring.",
  str_voice_1400861_19 = "Tidak bisa tidur, ya? Wah, itu masalah serius. Kau butuh bantuan untuk menutup mata?",
  str_voice_1400861_20 = "Aku memaafkan segalanya dan sangat yakin bahwa White Night melambangkan cahaya. Yah, bahkan jika semua yang kudapatkan sebagai balasannya hanyalah untuk tidak dilupakan.",
  str_voice_1400861_21 = "Jangan tersinggung, tapi demi sopan santun posisi, kalimat apa yang perlu diucapkan untuk Truth?",
  str_voice_1400861_22 = "Demi White Night.",
  str_voice_1400861_23 = "Aku mendoakan para Eclipsite yang malang itu. Aku berdoa semoga mereka akan mati dengan cepat.",
  str_voice_1400861_24 = "Tolong izinkan aku mengungkapkan kesedihan hatiku dengan cara yang mudah dipahami. Maafkan aku, mereka imut sekali.",
  str_voice_1400861_25 = "\"Kuharap kau bisa mengatakan sesuatu yang berbeda dari yang kau katakan tentang ayahku di upacara pemakamanku,\" katanya dulu kepadaku.",
  str_voice_1400861_26 = "Aku suka halaman berumput setelah hujan, tunas baru yang keluar dari tanah, dan cahaya yang bersinar melalui lubang di atap.",
  str_voice_1400861_27 = "Sebenarnya, aku benci surat rahasia dan para pengkhianat.",
  str_voice_1400861_28 = "Suasananya yang khusyuk dan desainnya yang sederhana mengingatkanku pada aula peringatan… Aku merasa sangat rileks di sana.",
  str_voice_1400861_29 = "Terima kasih telah mengundangku. Tolong panggil saja aku Uriah. Tak ada prasangka dalam doaku. Lagi pula, aku harus memiliki sopan santun yang tepat untuk menunjukkan rasa hormatku terhadap hidup dan mati.",
  str_voice_1400861_30 = "Aku akan selalu berdoa.",
  str_voice_1400861_31 = "Semoga doa-doaku akan menjadi lebih kuat.",
  str_voice_1400861_32 = "Pengampunan dosa dan pemberian kepercayaan ditambahkan.",
  str_voice_1400861_33 = "Hingga pemandangan yang kuharapkan tiba.",
  str_voice_1400861_34 = "Menghadiri upacara?",
  str_voice_1400861_35 = "Tolong perhatikan.",
  str_voice_1400861_36 = "Aku ingin mengumumkan sesuatu.",
  str_voice_1400861_37 = "Ini adalah pidato.",
  str_voice_1400861_38 = "Semoga kematian menjauhimu.",
  str_voice_1400861_39 = "Berdoa.",
  str_voice_1400861_40 = "Berduka.",
  str_voice_1400861_41 = "Memimpin upacara?",
  str_voice_1400861_42 = "Selesai. Terima kasih telah hadir.",
  str_voice_1400861_43 = "Saatnya… mengucapkan selamat tinggal.",
  str_voice_1400861_44 = "Kau manis sekali. Sebagai balasannya, aku akan mengantar kepulanganmu.",
  str_voice_1400861_45 = "Apa ini akan diletakkan di depan pusaraku?",
  str_voice_1400861_46 = "Hadiah ini bagaikan anugerah.",
  str_voice_1400861_47 = "Aku akan membawanya ke tempat aku akan beristirahat dalam damai.",
  str_voice_1400861_48 = "Berkat kau, aku akan selalu mensyukuri hidup.",
  str_voice_1400861_49 = "Sulur bunga hanya bisa memikul banyaknya harapanku… Inilah sebabnya aku harus mempersenjatai diri dengan sopan santun agar bisa menoleransi dan memilih untuk memaafkan orang lain.",
  str_voice_1400861_50 = "Biar kuceritakan perbuatannya dulu. Tanpa sadar, dia pernah memegang surat yang akan mengirimnya ke medan perang.",
  str_voice_1400861_51 = "Pada hari itu, aku meratapi masa lalu dengan rasa duka yang mendalam di hatiku. Kuucapkan selamat tinggal pada penderitaan yang terkubur dan menyambut hidup baru penuh kebebasan dan kemudahan.",
  str_voice_1400861_52 = "Alchemy Stars.",
  str_voice_1400861_53 = "Halo.",
  str_voice_1400861_54 = "Selamat pagi.",
  str_voice_1400861_55 = "Ini sudah siang. Apa kabar?",
  str_voice_1400861_56 = "Selamat sore, aku membawakan beberapa kuntum bunga putih.",
  str_voice_1400861_57 = "Selamat Tahun Baru! Semoga panjang umur!",
  str_voice_1500181_1 = "Kau sudah dengar album terbaru Barbara, belum? Jelek sekali, mestinya dibakar saja. Band itu terdengar seperti sampah!",
  str_voice_1500181_2 = "Kau benar-benar ingin mengobrol denganku? Baiklah. Apa jenis musik yang kau sukai? Pikirkan matang-matang. Aku tak mau bergaul dengan orang yang seleranya payah.",
  str_voice_1500181_3 = "Penasaran dengan kekuatan ini? Ini kekuatan asli yang mudah lepas kendali, jadi orang-orang selalu jaga jarak darinya… dan itu sama sekali bukan masalah untukku! Hahahaha!",
  str_voice_1500181_4 = "Lahir seperti mentari, mati seperti badai! Takutlah akan matahari yang melebur!",
  str_voice_1500181_5 = "Tak usah banyak cakap! Ke mana tujuan kita berikutnya? Aku tak sabar ingin membakar begundal-begundal itu sampai jadi abu!",
  str_voice_1500181_6 = "Kuasai kekuatannya, jangan sampai malah jadi budaknya. Apa pun yang terjadi, akulah yang menentukan nasibku sendiri.",
  str_voice_1500181_7 = "Rupanya kau juga punya gerombolan badut lucu, ya. Mereka benar-benar mengingatkanku akan badut itu, Sinsa.",
  str_voice_1500181_8 = "Menarik… Bisa kulihat di matamu pun ada api yang terus membara. Mungkin apimu lebih ganas daripada apiku…",
  str_voice_1500181_9 = "Negeri karam ini butuh matahari baru, tapi bukan aku orangnya. Mungkin kaulah orangnya…",
  str_voice_1500181_10 = "Aku bosan! Siapa yang mengambil gitarku? Oh, lebih baik dia siap-siap kubakar…",
  str_voice_1500181_11 = "Tengah panggung? Cih. Akulah yang selalu jadi pusat perhatian.",
  str_voice_1500181_12 = "Apakah aku, si penghancur, juga bisa menjadi pelindung?",
  str_voice_1500181_13 = "Saatnya musik metal! Semuanya, ayo nikmati musik rock ini!",
  str_voice_1500181_14 = "Jangan menggangguku kalau aku sedang bermain musik!",
  str_voice_1500181_15 = "Bagaimana kalau pesta ulang tahun metal?",
  str_voice_1500181_16 = "Oh, kau pikir kau bisa mengontrolku?",
  str_voice_1500181_17 = "Huh. Kukira kau sudah selesai.",
  str_voice_1500181_18 = "Serius, nih? Kau memintaku melakukan ini?",
  str_voice_1500181_19 = "Malam hari di sini sepi sekali. Tidak bisa diterima! Butuh sedikit rock 'n' roll untuk membakar semangat!",
  str_voice_1500181_20 = "Walau mereka hanyalah sekumpulan orang aneh, konyol, dan idiot, hanya merekalah yang mau menerimaku dan musikku.",
  str_voice_1500181_21 = "Kakek-kakek di Lumopolis dan musik klasik mereka itu sama saja, monoton dan kaku.",
  str_voice_1500181_22 = "Metal selamanya!",
  str_voice_1500181_23 = "Eclipsite gosong adalah salah satu hal terbaik di dunia.",
  str_voice_1500181_24 = "Si dungu ini sendirinya juga bertingkah konyol. Mereka yang sejenis memang biasa berkumpul bersama.",
  str_voice_1500181_25 = "Jona punya selera bagus dalam hal seni bertarung dan musik. Aku suka dia!",
  str_voice_1500181_26 = "Dunia ini payah sekali karena tak banyak musik metal!",
  str_voice_1500181_27 = "Maaf, aku tak mau berbicara dengan orang yang tak suka musik metal.",
  str_voice_1500181_28 = "Pasti keren kalau bisa menggelar konser di atas kepalanya!",
  str_voice_1500181_29 = "Kaukah orangnya? Cih. Coba kautunjukkan sesuatu yang menarik untukku. Demi keselamatanmu sendiri, jangan sampai mengecewakanku, atau…",
  str_voice_1500181_30 = "Butuh… kekuatan… lebih banyak…",
  str_voice_1500181_31 = "Kalau masih ingin hidup, menjauhlah.",
  str_voice_1500181_32 = "Badai keemasan. Indah, ya?",
  str_voice_1500181_33 = "Matahari terakhir tak akan pernah terbenam!",
  str_voice_1500181_34 = "Sekarang aku boleh melakukan apa pun yang kumau?",
  str_voice_1500181_35 = "Jangan berani-berani menatap cahaya menyilaukan ini!",
  str_voice_1500181_36 = "Kau yakin mau sampai sejauh itu?",
  str_voice_1500181_37 = "Cuma butuh beberapa detik saja!",
  str_voice_1500181_38 = "Terbakarlah di bawah matahari yang membara!",
  str_voice_1500181_39 = "Di sinilah kau akan mati!",
  str_voice_1500181_40 = "Matahari! Badai!",
  str_voice_1500181_41 = "Maaf membuat kalian menunggu lama, teman-teman!",
  str_voice_1500181_42 = "Belum cukup rock! Lagi, lagi!",
  str_voice_1500181_43 = "Ha! Menarik… Musuh yang kuat.",
  str_voice_1500181_44 = "Aku hanya ingin meremukkan piano itu.",
  str_voice_1500181_45 = "Tak ada gunanya berusaha membuatku senang.",
  str_voice_1500181_46 = "Apa kau ini… penggemar paling beratku?",
  str_voice_1500181_47 = "Bagus. Bagaimana kalau tiket konser VIP untukmu?",
  str_voice_1500181_48 = "Hadiah ini membuktikan bahwa kita mungkin punya banyak kesamaan!",
  str_voice_1500181_49 = "Memangnya kenapa kalau orang-orang mengkritik musikku? Terkutuklah orang-orang tua bangka dan aturan mereka itu. Aku tak mau buang-buang waktu untuk mereka.",
  str_voice_1500181_50 = "Aku tahu apa yang diharapkan Sinsa dariku—bukan hanya api yang membakar musuh, tapi juga cahaya penuntun. Aku tak tahu, dan tak peduli, apakah aku bisa memenuhi harapannya.",
  str_voice_1500181_51 = "Kekuatan sejati adalah satu-satunya yang bisa membuat kita dihormati orang-orang Rediesel. Namun, kau sudah menunjukkan kemungkinan lain kepadaku. Mungkin saja suatu hari nanti aku bisa memenuhi harapan kakakku.",
  str_voice_1500181_52 = "Alchemy! Stars!",
  str_voice_1500181_53 = "Kau di mana?",
  str_voice_1500181_54 = "Masih tidur? Saatnya bangun!",
  str_voice_1500181_55 = "Kau sedang apa? Kalau ada waktu, kemarilah.",
  str_voice_1500181_56 = "Pertunjukkannya sudah hampir dimulai. Bergembiralah!",
  str_voice_1500181_57 = "Ada badai baru yang datang!",
  str_voice_1500701_1 = "Untuk apa aku bertempur? Pertanyaan bodoh… Tentu aku bertempur untuk diriku sendiri! Atau, apa menurutmu untuk buah emas yang tidak ada di kebun itu?",
  str_voice_1500701_2 = "Aku tak butuh senjata. Sayap dan cakarku saja sudah cukup. Biarlah lidah api di sepanjang jalan berdarahku membakar segalanya, atau aku sendiri yang maju dan menghancurkan segalanya.",
  str_voice_1500701_3 = "Mereka yang harus menanggung amarah naga harus menerimanya, demikian pula mereka yang harus menderita akan menderita. Ini bukan pembenaran untuk mengusik Shadowlord.",
  str_voice_1500701_4 = "Penghakiman? Suara mereka sendirilah yang terlalu berisik. Mereka berusaha membuatku naik pitam dengan harapan aku akan menghancurkan segalanya. Sayangnya, aku tak akan terpancing.",
  str_voice_1500701_5 = "Jangan salah paham. Kebencian yang mengalir di hatiku tak ada hubungannya dengan kebencian yang ingin kuluapkan. Lagi pula, makin besar kekuatan kita, makin buta pula diri kita.",
  str_voice_1500701_6 = "Kegelapan dan darah hanyalah ilusi karena kebencian dan kasih pun remuk menjadi debu dan naga yang kembali itu pun tenggelam di dalamnya—",
  str_voice_1500701_7 = "Satu-satunya yang mengaliri garis keturunan naga adalah kebencian, tapi aku selalu mengambil keputusan berdasarkan suasana hatiku. Sebentar lagi kau akan paham.",
  str_voice_1500701_8 = "Apa kau penasaran dengan mata kananku yang ditutup ini? Mungkin sebaiknya kulepaskan saja penutup mata ini dan membiarkanmu merasakan tercekik oleh kebencian.",
  str_voice_1500701_9 = "Kau bocah lucu, jangan berpikir tentang apa yang bisa kaulakukan untukku. Kau hanya perlu mematuhiku… atau berdebat tanpa akhir denganku.",
  str_voice_1500701_10 = "Naga tak pernah tidur. Saat kaupejamkan matamu, kau memberikan kuasa kepada orang lain untuk mengeksekusimu.",
  str_voice_1500701_11 = "Bocah dari antah berantah sepertimu sungguh ingin meminta dukunganku? Kalau begitu, lawan aku, sekarang juga.",
  str_voice_1500701_12 = "Membiarkan orang bebal menanggung beban takdir dan kutukan, hmm, kedengarannya luar biasa.",
  str_voice_1500701_13 = "Pada akhirnya kita semua akan tertelan oleh kebodohan kita sendiri. Sampai hari itu tiba, teruslah berusaha semampu kita.",
  str_voice_1500701_14 = "Ada apa? Kebetulan, suasana hatiku sedang bagus… Tidak, kau harus berusaha membuatku lebih gembira.",
  str_voice_1500701_15 = "Apa yang kauharapkan? Ucapan selamat ulang tahun? … Sungguh, kau ini bocah mungil, imut, tapi bawel.",
  str_voice_1500701_16 = "Oh—aku tahu, ada seorang bocah di sini.",
  str_voice_1500701_17 = "Hai, bocah, sini, jabat tanganku. Upaya kerasmu bisa dianggap sebagai salam yang layak, 'kan?",
  str_voice_1500701_18 = "Sepertinya kau akhirnya selalu kembali ke sisiku… Walaupun, sayangnya, aku bukan orang istimewa itu.",
  str_voice_1500701_19 = "Tak banyak orang menyedihkan yang masih terjaga selarut ini… Terus temani saja bocah itu, Sunstone.",
  str_voice_1500701_20 = "Pilihan terbaik untukku adalah kembali ke Umbraton dengan Shadowlord, jadi aku pun melakukannya.",
  str_voice_1500701_21 = "Dari antek White Night menjadi antek Illumina… Tidak, kurasa gelar di sana itu lebih keren.",
  str_voice_1500701_22 = "Sang naga mengawasimu.",
  str_voice_1500701_23 = "Kadang, aku merasa sebenarnya bukan masalah kalau kita menyelubungi diri dengan kegelapan dan menjadi musuhnya.",
  str_voice_1500701_24 = "Dia adalah orang unik yang patut dihormati. Karena itu, akan kulakukan sesuai harapannya.",
  str_voice_1500701_25 = "Bisa kaubayangkan tidak, ternyata dia berasal dari garis keturunan yang sama denganku? Dia bahkan tak tahu aku ini ada.",
  str_voice_1500701_26 = "Memangnya ada yang lebih menarik selain perlawanan dan upaya orang-orang bodoh?",
  str_voice_1500701_27 = "Aku jadi berang setiap kali memikirkan saudariku yang konyol dan tolol itu dan si biang kerok yang jadi penyebab semua ini.",
  str_voice_1500701_28 = "Maaf, aku sempat merasa ada semacam hubungan dengan naga putih ini, tapi sekarang aku hanya ingin membongkarnya.",
  str_voice_1500701_29 = "Yang perlu kauketahui adalah bahwa gambar yang terpancar di mataku adalah kampung halamanku, yang terselimuti kabut tebal. Nah, soal namaku, nanti juga kau akan tahu…",
  str_voice_1500701_30 = "Tulus, disertai kerinduan.",
  str_voice_1500701_31 = "Bagiku, garis keturunan yang hilang sama sekali tak berarti.",
  str_voice_1500701_32 = "Api naga? Tadi itu cuma desahan.",
  str_voice_1500701_33 = "Kampung halaman itu akhirnya akan jadi ladang abu.",
  str_voice_1500701_34 = "Hadapi kebencianmu.",
  str_voice_1500701_35 = "Sudah cukup.",
  str_voice_1500701_36 = "Jangan ragu. Sana.",
  str_voice_1500701_37 = "Singkirkan mereka ke neraka, Sunstone.",
  str_voice_1500701_38 = "Baiklah. Hancurkan semuanya sampai jadi debu!",
  str_voice_1500701_39 = "Merataplah!",
  str_voice_1500701_40 = "Musnahlah.",
  str_voice_1500701_41 = "Aku sudah terbebas dari kebencian, tapi masih saja aku merindukannya.",
  str_voice_1500701_42 = "Lalu kenapa kalau kita menang?",
  str_voice_1500701_43 = "Nah, kau mau melontarkan kata-kata balasan penuh amarah?",
  str_voice_1500701_44 = "Bagus, aku jadi tenang… Tidak, masih belum cukup.",
  str_voice_1500701_45 = "Apa ini? … Bahkan Sunstone pun tak mau menyentuhnya.",
  str_voice_1500701_46 = "Keraguan di wajahmu tampak lebih menggemaskan daripada hadiah ini.",
  str_voice_1500701_47 = "Sunstone, bawa hadiah dari bocah ini.",
  str_voice_1500701_48 = "Raut wajahmu saja sudah cukup untuk membuatku menyukainya.",
  str_voice_1500701_49 = "Menatapnya dua kali, aku jadi ragu apakah aku harus menampakkan diri ke hadapannya dan memberitahunya bahwa hal yang kami cari ternyata hanyalah lelucon.",
  str_voice_1500701_50 = "Membalas dendam kepada orang-orang tak bersalah sama sekali tak bisa menghapus dendam yang sudah merasuk ke dalam darahku ini, tapi orang yang harusnya menerima pembalasan dendamku sudah tak ada lagi.",
  str_voice_1500701_51 = "Darah, ingatan, pusaran dendam, dan tumpukan sejarah. Semuanya campur aduk dalam jati diri seekor naga. Benar-benar menjijikkan.",
  str_voice_1500701_52 = "Alchemy, Stars.",
  str_voice_1500701_53 = "Nak.",
  str_voice_1500701_54 = "Sudah pagi, kemarilah dan ucapkan salam untukku.",
  str_voice_1500701_55 = "Pertama-tama, beri tahu aku, kau ada di mana.",
  str_voice_1500701_56 = "Kemarilah dan temani Sunstone.",
  str_voice_1500701_57 = "Ini Tahun Baru? Sini, tunjukkan kegembiraanmu kepadaku.",
  str_voice_1500761_1 = "Tidak ada manusia yang ekstraistimewa, karena semua punya masa lalu dan rahasia. Aku suka bahwa semua orang sama. Kalau Aurorian… Apa itu?",
  str_voice_1500761_2 = "Kebohongan dan kebenaran sebenarnya tak jauh berbeda. Bahkan tak ada batasnya. Kalau kubilang \"kalimat ini bohong\", tak penting apakah itu benar atau salah.",
  str_voice_1500761_3 = "Kalau kau penasaran tentang laut dalam yang misterius, naik sajalah ke Lumopolis dan tidurlah di aulanya untuk menuju ke sana.",
  str_voice_1500761_4 = "Pelaut pemberani, jangan sampai keliru antara tentakel dan pulau kecil. Kalau kalian bahkan tak bisa membedakan mana yang salah dan mana yang benar, akan amat sangat berbahaya jadinya.",
  str_voice_1500761_5 = "Waspadai monster yang bersembunyi di kedalaman laut. Mereka menyembul ke permukaan untuk menyerang kapal yang berlayar semata agar bisa menculik beberapa pelaut yang mereka sukai.",
  str_voice_1500761_6 = "Pengamat yang berkelana sepertiku ini selalu berusaha agar tak terlibat, tapi kusadari bahwa aku selalu terlambat setiap kali ingin ikut campur… Jadi, aku harus lebih tangguh lagi.",
  str_voice_1500761_7 = "Enak 'kan kalau kita bisa langsung tahu apakah seseorang sedang berbohong atau tidak? Kalau kau bisa mengenali informasi yang benar… pasti kau tak akan bilang \"tidak\", 'kan?",
  str_voice_1500761_8 = "Aku selalu bisa menyembunyikan kebenaran dalam kebohongan dan aku selalu berharap orang yang mendengar kata-kataku bisa tahu apa yang sebenarnya kupikirkan. Kau percaya padaku, tidak? Soalnya kau kelihatan agak naif.",
  str_voice_1500761_9 = "Jangan khawatir, jangan takut. Apa pun yang terjadi, monster bertentakel menggemaskan itu berharap semua pelaut pemberani bisa melihat matahari terbit di atas lautan.",
  str_voice_1500761_10 = "Hari ini, ada acara di Umbraton. Sayang sekali kalau kau tak ke sana… Jangan-jangan, kau malah sudah berencana akan ke sana, ya?",
  str_voice_1500761_11 = "Perasaan apa ini? Sepertinya aku bisa merasakan bahwa kau percaya padaku. Apakah perasaan ini muncul karena cinta, wahai pelaut pemberani?",
  str_voice_1500761_12 = "Menyentuh tentakelnya saja sudah berbahaya, sama seperti menyentuh naga Leona, kau akan terluka karenanya.",
  str_voice_1500761_13 = "Suatu hari nanti tempat ini pun akan terbenam. Kau harus pergi dari sini bersamaku sebelum itu terjadi.",
  str_voice_1500761_14 = "Aku harus pergi. Kalau tidak, orang seram yang mengejarku itu akan menyusulku. Jangan tunggu aku—sampai jumpa.",
  str_voice_1500761_15 = "Hari ini, laut dalam akan mengabulkan harapan semua orang. Harapanku adalah tetap bersamamu. Apa harapanmu?",
  str_voice_1500761_16 = "Selamat datang kembali, pelaut pemberani. Laut dalam telah meramalkan kedatanganmu.",
  str_voice_1500761_17 = "Aku senang sekali melihatmu, tapi kau terlalu awal. Aku berencana pergi diam-diam selagi kau tak ada di sini.",
  str_voice_1500761_18 = "Semua sebaran cahaya itu akan menghilang. Bagaimana denganmu? Kau masih ingin di sini bersamaku?",
  str_voice_1500761_19 = "Sudah begini larut, kenapa kau masih di sini? Kau mau ke laut dalam bersamaku? Sekarang aku tahu…",
  str_voice_1500761_20 = "Aku bisa menemukan lebih banyak lagi hiburan di tempat yang kacau. Lagi pula, di sana banyak manusia yang kusukai.",
  str_voice_1500761_21 = "Kemunafikan adalah suatu bentuk seni. Pulau putih mungil itu memanfaatkannya, padahal tak tahu apa-apa tentang hal itu.",
  str_voice_1500761_22 = "Tentakel-tentakel itu mengawasimu.",
  str_voice_1500761_23 = "Di laut dalam sekalipun, ada hal-hal yang sama sekali tak berarti seperti debu… misalnya Eclipsite.",
  str_voice_1500761_24 = "Kok bisa, ya, pemilik anjing memercayai anjingnya yang jelas-jelas berbeda spesies dari mereka? Apa karena anjing suka menggoyang-goyangkan ekor?",
  str_voice_1500761_25 = "Kenapa naga yang marah itu selalu tampak lamban? Menarik sekali.",
  str_voice_1500761_26 = "Hari hujan yang gelap mendung, buku kuno, dan kisah-kisah dari \"An Adventurer's Voyage\"—coba tebak mana yang aku suka?",
  str_voice_1500761_27 = "Aku tak suka hal-hal yang membosankan, begitu pula kebohongan… jadi, kuberitahukan kebenarannya.",
  str_voice_1500761_28 = "Inikah yang namanya Colossus? Di laut dalam memang banyak monster, jadi mungkin ini berasal dari laut dalam.",
  str_voice_1500761_29 = "Senang bertemu denganmu. Aku seorang penipu dan… panggil saja aku Kleken. Tolong, jangan percayai kata-kataku, termasuk yang barusan kukatakan. Jangan percaya apa pun yang kukatakan.",
  str_voice_1500761_30 = "Kurasa kondisinya masih sama saja.",
  str_voice_1500761_31 = "Kebohonganku makin meyakinkan. Sayangnya, ini pun bohong.",
  str_voice_1500761_32 = "Saat kabut mengembun jadi air, fiksi menjadi kenyataan.",
  str_voice_1500761_33 = "Pintu sunyi itu terbuka, memperlihatkan kedalaman laut.",
  str_voice_1500761_34 = "Siapa yang akan kaubohongi?",
  str_voice_1500761_35 = "Kabutnya sudah cukup tebal.",
  str_voice_1500761_36 = "Apa yang kaulihat itu adalah kebenaran?",
  str_voice_1500761_37 = "Legenda kuno itu kini akan bangkit!",
  str_voice_1500761_38 = "Semoga suatu hari nanti kau bisa melihat dalamnya laut!",
  str_voice_1500761_39 = "Ssst—",
  str_voice_1500761_40 = "Sudah terlambat.",
  str_voice_1500761_41 = "Kau sepertinya… percaya kepadaku? Mengejutkan.",
  str_voice_1500761_42 = "Maaf, kami gagal.",
  str_voice_1500761_43 = "Apa raut wajahmu jadi begitu gara-gara aku…?",
  str_voice_1500761_44 = "Aku senang sekali melihatmu. Sungguh, aku berbicara setulusnya.",
  str_voice_1500761_45 = "Lebih baik kaupasrahkan saja dirimu kepadaku.",
  str_voice_1500761_46 = "Kalau kubilang aku tak suka, berarti aku bohong.",
  str_voice_1500761_47 = "Terima kasih, aku akan menjagamu.",
  str_voice_1500761_48 = "Kau benar-benar…",
  str_voice_1500761_49 = "Di Umbraton, tentakel memang biasa muncul saat hujan. Asalkan jubahmu basah dan terbuka dengan sudut 50 derajat atau lebih, tentakel akan bermunculan di sisimu.",
  str_voice_1500761_50 = "Seekor monster yang disebutkan dalam catatan kuno memiliki perasaan seperti manusia, tetapi dia jadi risau setelah pergi ke pesisir karena tak tahu cara bertahan hidup di darat.",
  str_voice_1500761_51 = "Saat amukan Wrecker menyapu negeri, monster-monster yang ditangkap tentakelnya ingin menghindari krisis, tapi tidak ada tempat lain yang bisa mereka tuju. Akhirnya, semua dilahap oleh Shadowlord.",
  str_voice_1500761_52 = "Alchemy Stars.",
  str_voice_1500761_53 = "Pelaut rupawan.",
  str_voice_1500761_54 = "Sekarang sudah terlambat, 'kan?",
  str_voice_1500761_55 = "Selamat pagi, pasti kau sudah bangun.",
  str_voice_1500761_56 = "Matahari baru saja terbit.",
  str_voice_1500761_57 = "Besok kita akan menyambut tahun baru.",
  str_voice_1500781_1 = "Tolong… jangan dekat-dekat denganku… Lebih baik begitu karena aku mungkin saja tak sengaja membuatmu pingsan… Maaf.",
  str_voice_1500781_2 = "Maaf, kurasa kau mestinya mampu mengurus dirimu sendiri… Aku tidak begitu terampil dalam hal itu… dan agak tak berguna pula nantinya.",
  str_voice_1500781_3 = "Apa… apa akhir-akhir ini kau sering bersama Dayna? Dia sangat hangat dan ramah, selalu peduli kepada orang lain… Tak apa, aku hanya ingin memastikan saja.",
  str_voice_1500781_4 = "Jadi apa pun aku nantinya, aku tak peduli kata orang tentangku… Tak penting, asalkan mereka tetap menjaga jarak denganku… Eh? Kok penampilanku masih sama saja?",
  str_voice_1500781_5 = "Aku bukan lagi bocah lemah tak berdaya seperti dulu. Kini aku… sebaiknya kau jaga jarak denganku… Jangan dekat-dekat.",
  str_voice_1500781_6 = "Aku… aku tahu aku harus mengandalkan kekuatanku sendiri untuk mengatasi kebencianku suatu hari nanti… atau mungkin sekarang.",
  str_voice_1500781_7 = "Maaf, kukira kau kasar seperti orang-orang di luar sana… Namun sebenarnya kau jauh lebih baik daripada mereka… Setidaknya kau tak dekat-dekat denganku.",
  str_voice_1500781_8 = "Yah… Kurasa kau orang yang sangat kuat dan aku yakin kau akan jadi lebih kuat. Jadi… Apa kau mau mengunjungi Dayna dan belajar darinya?",
  str_voice_1500781_9 = "Kita punya banyak kesamaan… Kurasa Dayna pun akan bilang begitu. Nah, jadi… apa kau mau berkunjung ke Umbraton?",
  str_voice_1500781_10 = "… Kau benar-benar butuh istirahat… Tak akan kubiarkan siapa pun mengusikmu… kecuali Dayna.",
  str_voice_1500781_11 = "Kau ingin aku mengawasinya? Baiklah. Tenang saja, aku sudah pernah melakukannya.",
  str_voice_1500781_12 = "Maaf, aku tak tahu cara memakai senjata tajam seperti ini, dan aku tak mampu… melakukannya saat aku berhadapan langsung dengan orang lain.",
  str_voice_1500781_13 = "… Kalau mendapatkan kekuatan… aku bisa menghabisi apa pun.",
  str_voice_1500781_14 = "Apa kau sedang senggang? Tak akan lama, kok… Sebenarnya, aku hanya ingin bertanya, apa kau tahu Dayna ada di mana?",
  str_voice_1500781_15 = "Anu, selamat ulang tahun… Maaf, aku belum sempat menyiapkan hadiah untukmu… dan aku tak sengaja malah memorak-porandakan tokonya.",
  str_voice_1500781_16 = "Aku juga bekerja paruh waktu di Guild… Beri tahu aku lebih dulu kalau kau butuh bantuan, ya.",
  str_voice_1500781_17 = "… Masih terlalu dini untuk mengontrolnya… Kusarankan kita tetap saling menjauh.",
  str_voice_1500781_18 = "Urusanku di Guild sudah selesai. Apa ada toko yang ingin kaukunjungi…? Aku dan Dayna akan menemanimu.",
  str_voice_1500781_19 = "Mungkin sebaiknya kuucapkan selamat malam saja kepadamu… persis seperti yang biasanya kudengar, heh.",
  str_voice_1500781_20 = "Di tempat seperti itu sekalipun… Pelan-pelan kami menemukan tempat yang bisa disebut rumah.",
  str_voice_1500781_21 = "Lumopolis memiliki lingkungan hidup yang lebih baik… Namun, aku dan Dayna sama sekali tak mau kembali ke sana.",
  str_voice_1500781_22 = "Bayangan mengawasimu.",
  str_voice_1500781_23 = "Akan kubunuh sendiri Eclipsite yang telah membunuh orang tuaku.",
  str_voice_1500781_24 = "Dayna sudah seperti keluarga bagiku… Aku memang tidak menyebutnya saudariku, tapi… dia lebih berarti daripada sekadar saudari bagiku.",
  str_voice_1500781_25 = "Aku berterima kasih karena Sheol sudah merawatku, tapi kuharap lain kali dia tidak sampai sedekat itu denganku… Aku jadi merasa sesak karenanya.",
  str_voice_1500781_26 = "…Yang kusukai… Yah, bolehkah… bolehkah kubilang aku suka Dayna?",
  str_voice_1500781_27 = "Aku tak suka apa pun yang tiba-tiba terlalu dekat denganku… dan aku benci Eclipsite.",
  str_voice_1500781_28 = "Colossus ini… tampak putih bersih… seperti suatu tempat yang dulu ingin kami datangi.",
  str_voice_1500781_29 = "Aku Robyn… Maaf, tolong jangan dekat-dekat denganku… karena ini baru pertama kalinya kita bertemu. Kurasa sebaiknya kita sama-sama mundur dua langkah sebelum saling memperkenalkan diri lagi.",
  str_voice_1500781_30 = "Apa aku sudah makin mendekati… targetku?",
  str_voice_1500781_31 = "Rupanya… beginilah cara pengumpulan kekuatannya.",
  str_voice_1500781_32 = "Dayna, aku jadi makin kuat…",
  str_voice_1500781_33 = "Aku tak peduli kalau harus berlumur lumpur… asalkan aku bisa memperoleh kekuatan lebih besar.",
  str_voice_1500781_34 = "Harus ada tabungnya.",
  str_voice_1500781_35 = "Pengukuran selesai.",
  str_voice_1500781_36 = "Aku bisa menunggu sebentar lagi.",
  str_voice_1500781_37 = "Aku tak bisa berhenti… walau kau memohon ampun sekalipun.",
  str_voice_1500781_38 = "Ini pengecualian. Amati baik-baik!",
  str_voice_1500781_39 = "Minggir.",
  str_voice_1500781_40 = "Menjauhlah dariku!",
  str_voice_1500781_41 = "Aku harus bertarung? …Ayo ajak Dayna.",
  str_voice_1500781_42 = "Rasa menang… Sebaiknya aku membiasakan diri dengan perasaan ini.",
  str_voice_1500781_43 = "Aku kalah… Namun… aku tak ingin Dayna tahu.",
  str_voice_1500781_44 = "Di-dia menatapku? Apa dia juga melihat Dayna?",
  str_voice_1500781_45 = "Apakah tak apa-apa kalau kuterima hadiah ini…",
  str_voice_1500781_46 = "Apa!? Ini… Kau tahu apa yang kusukai?",
  str_voice_1500781_47 = "Akan kuterima diam-diam, diam-diam.",
  str_voice_1500781_48 = "Ini… Terima kasih. Terima kasih banyak.",
  str_voice_1500781_49 = "Selama tahun-tahun itu… Mungkin karena keadaan sangat sulit, orang-orang sampai menjadi acuh tak acuh, bertarung dan menginjak satu sama lain.",
  str_voice_1500781_50 = "Kelaparan dan diskriminasi tak akan hilang hanya dengan rasa percaya yang naif. Kita semua sudah tahu ini, dan kita hanya bisa bertahan hidup dengan mengandalkan kekuatan diri sendiri…",
  str_voice_1500781_51 = "Dia telah menanggung beban kebencianku… Namun, aku harus menyelesaikannya sendiri. Aku tak mau dia terlibat dalam hal ini… Kebencian bukanlah hal baik untuk Dayna.",
  str_voice_1500781_52 = "… Alchemy Stars.",
  str_voice_1500781_53 = "Ehem, apa itu…",
  str_voice_1500781_54 = "Selamat pagi…",
  str_voice_1500781_55 = "Ehem, kebetulan sekali…",
  str_voice_1500781_56 = "Kau belum tidur?",
  str_voice_1500781_57 = "Selamat Tahun Baru. Kau mau merayakannya?",
  str_voice_1500841_1 = "Akan kuceritakan sebuah lelucon tentang penebusan dosa. Kalau kau ingin si kambing hitam didorong ke jurang atau diasingkan ke alam liar, fakta bahwa dia memang bersalah atau tidak itu tak penting. Yang penting, dia harus punya tanduk.",
  str_voice_1500841_2 = "Berkat istrinyalah Schwartz mendapatkan kesuksesannya saat ini… Hah… Meski terlihat begitu renta, sebenarnya dia belum setua itu.",
  str_voice_1500841_3 = "Iblis pertama dibakar dengan tongkat yang mampu menghanguskan iblis hingga jadi abu. Jadi, sudah sepantasnya dia menjaga gerbang neraka.",
  str_voice_1500841_4 = "Takhta tua ini bukan untuk diperebutkan, tapi ini lambang penghormatan. Setelah ditempa api, takhta ini akan menjadi sesuatu yang baru.",
  str_voice_1500841_5 = "Orang-orang yang sudah menyusun rencana dengan matang tak akan bertindak gegabah dan orang-orang yang menindas dan memanfaatkan orang-orang yang lebih rendah daripada mereka pasti punya alasan karena mereka tahu bahwa bayangan itu mengawasi mereka.",
  str_voice_1500841_6 = "Saat aku kembali ke tempat ini, legenda Umbraton sudah jadi kenyataan. Pemimpin dan bayangan itu mulai menguasai setiap jengkal di tempat ini.",
  str_voice_1500841_7 = "Keadilan yang kubela tidaklah sama dengan yang keluar dari mulutmu. Keadilan ini mungkin memang kacau, tapi tak bisa disimpangkan. Sekarang kau belum mampu memahaminya.",
  str_voice_1500841_8 = "Kau tumbuh tanpa perlindungan dari orang tuamu, sama sepertiku. Namun, suatu hari nanti, kau akan tahu bahwa terbenam dalam lumpur terasa sangat menyiksa.",
  str_voice_1500841_9 = "Kau harus meningkatkan kemampuanmu sebagai seorang Navigator. Namun, belajar dari pengalaman untuk menghindari risiko tabrakan bisa bermanfaat bagimu… Agar lebih mudah untukmu, ikuti saja aku.",
  str_voice_1500841_10 = "Jangan keras kepala begitu. Tidak, maksudku… kalau tidak sibuk, kunjungilah aku. Kita bisa bermain catur dan akan kuceritakan beberapa kisah untukmu.",
  str_voice_1500841_11 = "Aku sudah terbiasa hidup dalam bayang-bayang… Nah, sepertinya sekarang tak perlu lagi… Boleh aku duduk di sini?",
  str_voice_1500841_12 = "Setiap langkah harus sempurna, jadi kau harus memikirkannya matang-matang sebelum bertindak.",
  str_voice_1500841_13 = "Kuharap kau tahu apa yang baik untukmu. Bayangan juga mengawasimu.",
  str_voice_1500841_14 = "Celaka kalau sampai mereka tahu aku ada di sini…",
  str_voice_1500841_15 = "Ini hari ulang tahunmu? Karena ini hari istimewa, pergilah ke tempatku dan ambillah satu atau dua barang dari koleksiku.",
  str_voice_1500841_16 = "Selamat datang kembali. Karena takdir sudah memberimu tanggung jawab ini, aku yakin kau sudah siap bertindak.",
  str_voice_1500841_17 = "Bagus sekali. Kau datang tepat waktu, sama seperti bayangan yang selalu datang paling awal.",
  str_voice_1500841_18 = "Kalau lelah, duduk dan istirahatlah sebentar sebelum kita mulai.",
  str_voice_1500841_19 = "Kaum muda zaman sekarang sepertinya biasa aktif pada jam-jam seperti ini… Hmm… Mereka bersembunyi dalam gelap.",
  str_voice_1500841_20 = "Seperti yang sudah kita tahu, Umbraton bertanggung jawab menjaga separuh ketertiban Lumopolis.",
  str_voice_1500841_21 = "Bilang kepada orang-orang dari Illumina itu, tak usah lagi buang-buang waktu mereka untuk mencoba melawan aturan.",
  str_voice_1500841_22 = "Bayangan mengawasimu.",
  str_voice_1500841_23 = "Mereka adalah makhkluk yang tak mengenal kebenaran itu. Maka dari itu, kau tak perlu memberi mereka ampun saat mempertaruhkan nyawamu dalam pertempuran.",
  str_voice_1500841_24 = "Pria tua itu selalu berbuat menjengkelkan pada saat-saat tertentu, misalnya curang saat main catur.",
  str_voice_1500841_25 = "Pria pemarah itu harusnya tahu bahwa dia harus bisa mengambil keputusan dulu, barulah dia bisa mengubah situasi.",
  str_voice_1500841_26 = "Aku punya sejumlah lemari penyimpanan di ruangku, penuh dengan mahakarya.",
  str_voice_1500841_27 = "Orang-orang yang tak bisa dipercaya, lalim, dan kasar. Orang-orang seperti itu tak pantas hidup.",
  str_voice_1500841_28 = "Kudengar, Colossus adalah semacam tempat berlindung sekaligus bukti suatu misi tertentu.",
  str_voice_1500841_29 = "Buang rasa penasaranmu. Yang perlu kauketahui hanyalah bahwa aku ini bayang-bayang masa lalu yang terus menghantui Umbraton dan warga Lumopolis pastinya tak mau kalau sampai mereka harus menghadapiku.",
  str_voice_1500841_30 = "Makin besar kekuatanku, semua hal jadi terasa makin membosankan.",
  str_voice_1500841_31 = "Bagi bayangan, ini lebih dalam lagi.",
  str_voice_1500841_32 = "Seperti biasa, Umbraton akan mengampunimu.",
  str_voice_1500841_33 = "Aku akan menjadi bayangan itu…",
  str_voice_1500841_34 = "Ayo kita bekerja sama.",
  str_voice_1500841_35 = "Kalau ada konsekuensinya, memangnya kenapa?",
  str_voice_1500841_36 = "Segalanya akan berakhir!",
  str_voice_1500841_37 = "Terus saja melawan sampai kau terseret ke kuburmu!",
  str_voice_1500841_38 = "Bangkitlah sebelum kau ditelan kegelapan!",
  str_voice_1500841_39 = "Rasakan kehebatanku!",
  str_voice_1500841_40 = "Takutlah di hadapanku!",
  str_voice_1500841_41 = "Oke, biar aku yang memerintah.",
  str_voice_1500841_42 = "Kemenangan adalah milik semua orang.",
  str_voice_1500841_43 = "Tak seperti refleksi diri, kekalahan tak ada artinya.",
  str_voice_1500841_44 = "Bagus sekali! Banyak orang bisa hidup di sini dengan identitas baru.",
  str_voice_1500841_45 = "Tak usah repot-repot, toh kau tak akan mendapatkan apa pun dariku.",
  str_voice_1500841_46 = "Ya, aku bisa merasakan betapa berharganya ini.",
  str_voice_1500841_47 = "Walau sebenarnya tak perlu, aku akan mempertimbangkan untuk memberimu sesuatu sebagai balasannya.",
  str_voice_1500841_48 = "Haha! Akan kusimpan di lemariku.",
  str_voice_1500841_49 = "Bayangan kekacauan tak pernah mencerminkan apa pun. Bayangan itu hanya memperluas jaringnya ke seluruh Umbraton seperti jaring laba-laba untuk menjaga tatanan unik yang ada di Umbraton.",
  str_voice_1500841_50 = "Sebelum Lumopolis terpecah-pecah, kegelapan menguasai kota itu. Orang-orang sama sekali tak mau peduli dengan hal-hal yang tak ada hubungannya dengan mereka.",
  str_voice_1500841_51 = "Memastikan sumber dana, membantu dan mengadopsi anak-anak miskin dan yatim, dan mengajari mereka cara untuk mengubah nasib—inilah cara untuk menumbuhkan keteraturan baru dalam bayangan.",
  str_voice_1500841_52 = "Alchemy Stars.",
  str_voice_1500841_53 = "Orang yang bertanggung jawab.",
  str_voice_1500841_54 = "Ingat, bertindaklah lebih awal.",
  str_voice_1500841_55 = "Apa kau sudah benar-benar siap?",
  str_voice_1500841_56 = "Alasan di balik kegelapan rahasia ada di dalam keteraturan.",
  str_voice_1500841_57 = "Sana, rayakanlah Tahun Baru.",
  str_voice_1500881_1 = "Aku tak bisa melepas sarung tangan ini karena mungkin saja aku akan melukai orang lain… Anu, karena… tanganku dipenuhi bulu yang keras.",
  str_voice_1500881_2 = "Berhentilah memandangiku, oke? Kalaupun kau terus-menerus memandangiku, aku tak akan berubah… Aku bukan bunglon yang bisa berubah warna sebegitu mudahnya.",
  str_voice_1500881_3 = "Para anggota Rediesel Wrench sering berkumpul untuk berpesta, tapi biasanya aku hanya duduk di pojokan, kecuali… kalau aku tiba-tiba jadi bersemangat.",
  str_voice_1500881_4 = "Apa ada yang salah dengan penampilanku? … Namun, semua kadal gendut di gurun 'kan memang tampak seperti ini… Eh? Kau belum pernah dengar tentang itu?",
  str_voice_1500881_5 = "Saat aku marah, aku menggunakan kekuatan kadal gendut. Dan saat itu terjadi, aku bisa merasakan darahku mendidih dan aku jadi sangat kuat karenanya.",
  str_voice_1500881_6 = "Kumpulkan keberanianmu dan jangan takut pada kesulitan! Apa pun yang ingin kulakukan atau kucari, aku cukup menyerang dan melemparkan granat saja… Oh, maaf! Aku terlalu bersemangat.",
  str_voice_1500881_7 = "Aku bukan anak kecil lagi! …Jadi, tak apa… Aku bisa bertarung, dan aku juga punya banyak bom! Aku bahkan bisa mengendarai sepeda motor!",
  str_voice_1500881_8 = "Kau tak senang? Hmm… Bagaimana, ya… Anu, aku tahu, bagaimana kalau kupinjamkan ekorku kepadamu? …Eh? Apa kau tak tertarik?",
  str_voice_1500881_9 = "Sebenarnya, sarung tangan ini agak kurang nyaman. Suatu hari nanti, seandainya saja aku bisa… Sudahlah, bisa bersamamu seperti ini saja sudah cukup.",
  str_voice_1500881_10 = "Bolehkah kupamerkan granat hasil modifikasiku? Sebentar, biar kukeluarkan pelan-pelan. Kalau sampai sumbunya tersangkut di sarung tanganku, bisa celaka jadinya…",
  str_voice_1500881_11 = "Kalau aku tak sengaja merusak apa pun setelah aku jadi terlalu bersemangat… Maafkan aku, akan kuganti rugi!! Maukah kau menerima granatku?",
  str_voice_1500881_12 = "Huft… Sesuai dugaan, lagi-lagi aku gagal… Mungkin… Bisa tunggu sebentar? Aku mau coba lagi. Tidak akan lama, kok…",
  str_voice_1500881_13 = "Sebagian luka ini adalah akibat salahku sendiri… karena ekorku tak mau menurutiku saat aku sedang istirahat.",
  str_voice_1500881_14 = "Aku tak terlalu betah di tempat-tempat ramai… Aku jadi sangat malu kalau orang-orang memandangiku…",
  str_voice_1500881_15 = "Aku sudah memutuskan akan merayakannya untukmu hari ini! Aku sudah berusaha sebaik mungkin untuk mengumpulkan keberanianku! Semoga hari-harimu penuh sukacita!",
  str_voice_1500881_16 = "Selamat datang kembali! Aku selalu berjaga di sini dan tak pergi selangkah pun.",
  str_voice_1500881_17 = "Tunggu! Biar kupasangkan perban… Kau mau kuperban? Ini bisa mencegah cedera.",
  str_voice_1500881_18 = "J-jangan lihat! Aku masih merapikan ekorku… Jadi, anu, apa bulu-bulu kerasnya tampak aneh?",
  str_voice_1500881_19 = "Aku bisa melihat sangat jelas saat malam, jadi tak usah khawatir… Oh, ya, di sini gelap sekali.",
  str_voice_1500881_20 = "Tidak begitu sulit untuk menjadi bagian Rediesel Wrench. Kau hanya perlu, yah, tahu cara bersenang-senang.",
  str_voice_1500881_21 = "Aku sudah mendatangi banyak tempat, tapi kudengar Lumopolis ada di langit… Bagaimana caranya orang pergi ke sana…?",
  str_voice_1500881_22 = "Silakan senang-senang selagi… eh, selagi apa tadi, ya?",
  str_voice_1500881_23 = "Aku bisa melihat benda-benda hitam dengan sangat jelas. Kalau kau takut, ajak saja aku, aku akan berusaha sebaik mungkin!",
  str_voice_1500881_24 = "Sepeda motor ini baru saja diperbaiki. Aku tak boleh sampai merusaknya lagi. Tiny One pasti akan sangat marah kepadaku.",
  str_voice_1500881_25 = "Karena aku begitu kukuh ingin bergabung dengan Rediesel Wrench, bosku berjanji kepada ibuku bahwa dia akan menjagaku baik-baik.",
  str_voice_1500881_26 = "Eh? Kau… menanyakan apa yang kusukai? Aku suka hal-hal yang terlihat keren.",
  str_voice_1500881_27 = "K-kenapa sih harus ada makanan seperti dendeng kadal ini? … *Hiks* Mana bisa aku memakannya…",
  str_voice_1500881_28 = "Colossus itu benar-benar kuat! Kalau aku berusaha sedikit lebih keras lagi, apa aku bisa sepertinya?",
  str_voice_1500881_29 = "A-aku Maggie… Anu, walau aku tidak lihai dalam banyak hal, akan kukumpulkan keberanianku… untuk mengatasi mereka.",
  str_voice_1500881_30 = "Aku jadi tak sabar!",
  str_voice_1500881_31 = "Ekorku jadi gelisah…",
  str_voice_1500881_32 = "Aku sudah berubah menjadi kadal besar!",
  str_voice_1500881_33 = "Aku ingin meledakkan segalanya!",
  str_voice_1500881_34 = "Aku harus mengumpulkan keberanian!",
  str_voice_1500881_35 = "Dengan kekuatan kadal gendut!",
  str_voice_1500881_36 = "Aku sudah siap dari tadi!",
  str_voice_1500881_37 = "Ini 'kan hanya granat. Ayolah!",
  str_voice_1500881_38 = "Serang! Hantam mereka dengan granat!",
  str_voice_1500881_39 = "Tembakan datang!",
  str_voice_1500881_40 = "Ledakkan semuanya!",
  str_voice_1500881_41 = "Ngeri sekali… tapi keseruan ini membuat darahku bergejolak!",
  str_voice_1500881_42 = "Apa pertempuran sudah selesai? Aku akan menenangkan diri kalau begitu…",
  str_voice_1500881_43 = "Aku masih berani melakukannya lagi…",
  str_voice_1500881_44 = "E-ekorku bukan barang pajangan…! Tidak enak dipandang juga, sungguh.",
  str_voice_1500881_45 = "Eh… A-aku tak boleh mengambilnya, ya?",
  str_voice_1500881_46 = "Ini dia!! Ini… Bagaimana aku harus berterima kasih padamu untuk ini?",
  str_voice_1500881_47 = "Akan kuterima. Hmm… Terima kasih?",
  str_voice_1500881_48 = "Terima kasih! Ini tampak sangat keren dan hebat!",
  str_voice_1500881_49 = "Semua orang di Rediesel Wrench berpakaian sangat mencolok. Aku ingin membaur dengan mereka, jadi aku… aku mengubah semuanya. Aku bahkan tak bisa bilang betapa aku menyesalinya…",
  str_voice_1500881_50 = "Granat hasil modifikasiku biasanya tidak begitu kuat, tapi akan jadi suuuuuper kuat begitu aku menggunakannya dengan \"kekuatan kadal gendut\"!",
  str_voice_1500881_51 = "Sebenarnya aku hanya mencari ayahku, tapi sia-sia, jadi kuteruskan saja bepergian lebih jauh lagi.",
  str_voice_1500881_52 = "Alchemy… Stars?",
  str_voice_1500881_53 = "Permisi?",
  str_voice_1500881_54 = "Selamat pagi, apa kau sedang senggang?",
  str_voice_1500881_55 = "Mau bermain? Aku tak sabar lagi!",
  str_voice_1500881_56 = "Apa kau… kedinginan saat malam?",
  str_voice_1500881_57 = "Selamat Tahun Baru. Aku harus… mengatasi kelemahanku.",
  str_voice_1500901_1 = "Oh, aku suka sekali rasanya… Ayo kita ledakkan para Eclipsite… Pre-tty Li-zard Slash! Darah segar mengucur… Waspadai musuh di belakangmu!",
  str_voice_1500901_2 = "Kau menantikannya? Iya? Album baruku berjudul —Everyday - Loving the Engine Oil—. Album itu dirilis beserta sejumlah koleksi fotoku yang eksklusif—dalam balutan baju renang!",
  str_voice_1500901_3 = "Eclipsite berkeliaran. Bahaya mengintai di mana-mana. Siapkan gergaji bundar dan kunci pas! Pertempuran apa? Yang dimaksud Barbara itu konsernya!",
  str_voice_1500901_4 = "Aku sudah mementaskan lebih dari 600 lagu di acara Fiery Support selama tiga hari berturut-turut tanpa tidur sedikit pun…",
  str_voice_1500901_5 = "Menurutmu, aku menyeramkan? Oh, tidak! Aku ini idola sempurna, gadis remaja polos dan imut. Kau pasti salah sangka tentangku. Pasti begitu.",
  str_voice_1500901_6 = "Musik bisa menyembuhkan! Mimpiku adalah menjadi idola dan membawa kehangatan dan cinta bagi dunia dengan musikku!",
  str_voice_1500901_7 = "Hai, apa kau mau datang ke acara jumpa fanku? Beli saja satu albumku, nanti kau akan dapat tiket ke acara jumpa fan itu! Penggemar yang antre di barisan belakang harus hati-hati, mungkin saja kalian akan dimangsa Eclipsite.",
  str_voice_1500901_8 = "Kalau kau mau datang, akan kupastikan kau dapat tempat duduk di karavan yang paling dekat dengan panggung. Itu tempat duduk khusus untuk anggota!",
  str_voice_1500901_9 = "Bilang \"kunci pas\"! Akan kurawat foto bersamamu ini! Senyummu tak akan pernah kulupakan!",
  str_voice_1500901_10 = "Aku ingin menulis sebuah lagu untuk Rediesel Wrench. Temanya \"Gurun Liar\". Siapa yang harus kuundang sebagai tamu istimewa, ya?",
  str_voice_1500901_11 = "Kalau performaku bagus, mungkin jumlah penggemarku juga akan bertambah! Aku akan berusaha keras agar tetap menjadi penyanyi paling populer di Rediesel!",
  str_voice_1500901_12 = "Hah? Kenapa kalian berhenti bersorak? Abaikan saja para pengganggu itu. Konsernya tetap berlanjut!",
  str_voice_1500901_13 = "Aku senang sekali kalian ada di sini! Tolong pastikan kalian tetap hidup, dan kembalilah untuk konser besok!",
  str_voice_1500901_14 = "Setiap idola harus punya kemampuan manajemen ekspresi tanpa cela. Nah, senyum!",
  str_voice_1500901_15 = "Selamat ulang tahun. Selamat ulang tahun. Ayo habisi Eclipsite itu!",
  str_voice_1500901_16 = "Konsernya akan segera dimulai!",
  str_voice_1500901_17 = "Oh… Ehem— Do-re-mi-fa— Hah? Aku sedang latihan pemanasan suara!",
  str_voice_1500901_18 = "Angkat tangan kalian! Tunjukkan semangat kalian!",
  str_voice_1500901_19 = "Wuuhuu! ♪ Yang berani ganggu, silakan hadapi gergajiku!",
  str_voice_1500901_20 = "Kalian dari Rediesel Wrench memang paling keeeeeren di dunia!",
  str_voice_1500901_21 = "Hah? Ada paduan suara di Lumopolis? Ada musisi profesional juga? Jangan sampai berubah pikiran, Navigator!",
  str_voice_1500901_22 = "Rediesel Wrench! Tunjukkan kekuatanmu!",
  str_voice_1500901_23 = "Tidak ada Eclipsite di konserku! Mereka yang mengganggu konser harus diberi pelajaran.",
  str_voice_1500901_24 = "Apa ada yang datang ke konser Regina? Tak apa. Barbara. Sama sekali. Tak. Peduli.",
  str_voice_1500901_25 = "Tiny One memang partner terbaikku! Dialah yang membuat semua tata panggung, pengeras suara, dan mikrofonnya!",
  str_voice_1500901_26 = "Hidangan ikan ini sangat lezat, terutama sashimi. Sayang sekali aku jarang punya kesempatan untuk menyantapnya.",
  str_voice_1500901_27 = "Idola yang sempurna punya cinta untuk semuanya, dan Barbara tak pernah setengah-setengah! Bahkan teriakan sumbang Regina sekalipun!",
  str_voice_1500901_28 = "Di mana tempat terbaik untuk mendirikan panggung? Di geladak? Atau di jembatan? Aku saaaangat penasaran!",
  str_voice_1500901_29 = "Yoo-hoo! Inilah cinta Rediesel, kekasih yang panas, dan idola dari semua—Barbara! ♥ Tidak cukup kebisingan! Biarkan aku mendengarnya!",
  str_voice_1500901_30 = "Aku berkilau ♥ dan bersinar!",
  str_voice_1500901_31 = "Ayo isi jiwa dengan Rock 'n' Roll!",
  str_voice_1500901_32 = "Musik! Gairah! Biarkan gurun ini membara!",
  str_voice_1500901_33 = "Lagu-lagu Barbara akan selalu menyertai kalian!",
  str_voice_1500901_34 = "Gairah, keliaran, ikatan, cinta!",
  str_voice_1500901_35 = "KALIAN.SUDAH.SIAP?",
  str_voice_1500901_36 = "Musik! Rasakan iramanya!",
  str_voice_1500901_37 = "Heart Saw!",
  str_voice_1500901_38 = "Rock 'n' Roll, sayangku!",
  str_voice_1500901_39 = "Lalala… Yap-a-du-di…",
  str_voice_1500901_40 = "Jatuh cinta!",
  str_voice_1500901_41 = "Bersoraklah untukku!",
  str_voice_1500901_42 = "Lagi? Siapa takut!",
  str_voice_1500901_43 = "Berapa kali pun aku jatuh, aku akan selalu bangkit dan terus maju.",
  str_voice_1500901_44 = "Bolehkah aku menggelar konser di sini?",
  str_voice_1500901_45 = "Semua hadiah untukku harus diberikan kepada agenku.",
  str_voice_1500901_46 = "Kuterima saja hadiahmu diam-diam.",
  str_voice_1500901_47 = "Sebagai gantinya, akan kuberi kau foto dengan tanda tanganku.",
  str_voice_1500901_48 = "Tidak, idola tidak boleh punya hubungan asmara. Namun…",
  str_voice_1500901_49 = "Aku memang pernah mengalami masa-masa sulit, dan musiklah yang menyelamatkanku. Sekarang, aku juga ingin menyelamatkan semua orang dengan musik!",
  str_voice_1500901_50 = "Perjalanan untuk menjadi idola memang sulit dan penuh liku, tapi aku tak akan menyerah. Menggelar konser di atas karavan di gurun untuk mengumpulkan penggemar. Satu senyuman saja cukup untuk membuatku merasa bahagia.",
  str_voice_1500901_51 = "Berkat kerja keras dan kemampuanku yang luar biasa sebagai seorang idola, Barbara berhasil memikat banyak penggemar! Namun, si Regina itu selalu saja berusaha menyaingiku!",
  str_voice_1500901_52 = "Alchemy Stars!",
  str_voice_1500901_53 = "Hai!",
  str_voice_1500901_54 = "Selamat pagi! Tersenyumlah!",
  str_voice_1500901_55 = "Hai! Tunjukkan semangatmu padaku!",
  str_voice_1500901_56 = "Konser cinta akan segera dimulai!",
  str_voice_1500901_57 = "Selamat Tahun Baru!",
  str_voice_1600011_1 = "Memangnya mendesak? Sepertinya kau kemari bukan untuk urusan resmi… Kalau memang begitu, aku permisi duluan.",
  str_voice_1600011_2 = "Apa yang kaukatakan ini memang benar-benar penting? Kau… terlalu dekat denganku…",
  str_voice_1600011_3 = "Disiplin diri adalah prinsip hebat. Maksudku, bisakah kau tidak menyentuh cermin atau kelopak-kelopak itu?",
  str_voice_1600011_4 = "Dahulu kala, White Narcissus selalu memandangi Lake Mirror… Lho, mana bunga yang lainnya? Bunga apa itu?",
  str_voice_1600011_5 = "Bunga Northland dan cermin, dua dunia yang saling bertaut—sisi manakah yang nyata?",
  str_voice_1600011_6 = "White Narcissus kembali mekar. Kami adalah dua sosok kembar dalam cermin dan kami akan terus hidup dengan berlandaskan kisah-kisah kuno dan melanjutkan kisah kami.",
  str_voice_1600011_7 = "Kalau tidak terjadi secara alami, berarti kita berdua harus berusaha keras. Begitukah harapanmu?",
  str_voice_1600011_8 = "Kau boleh mendapatkan bantuan kecil dariku, tapi tak lebih dari itu. Puas?",
  str_voice_1600011_9 = "Seandainya kita berhasil menemukan diri kita lagi suatu hari nanti… satu-satunya harapanku adalah bahwa kau juga akan ada dalam kenanganku.",
  str_voice_1600011_10 = "Saat hari santai, langit pun tampak lebih biru dibandingkan biasanya!",
  str_voice_1600011_11 = "Dari raut wajahmu, sepertinya aku tak akan bisa menolakmu.",
  str_voice_1600011_12 = "Jaga jarakmu, jaga pula omongan dan perbuatanmu. Kalau kau bisa menjaganya, saudariku akan lebih mudah menerimamu.",
  str_voice_1600011_13 = "Jangan bilang kau ingin aku memujimu?… Biar kupikirkan dulu.",
  str_voice_1600011_14 = "Aku merasa agak resah… seperti kerikil yang jatuh ke dalam danau.",
  str_voice_1600011_15 = "Tidak ada yang spesial tentang hari ini. Kita bersikap seperti biasa dan menikmati ketenangan serta kesunyian.",
  str_voice_1600011_16 = "Hmm? Apa kau punya urusan denganku?",
  str_voice_1600011_17 = "Ah! Aku paham, kekuatanmu… kau orang yang terbiasa bangun pagi.",
  str_voice_1600011_18 = "Kudengar suaramu saat kau kembali, jadi kita tak perlu meributkannya. Itu saja.",
  str_voice_1600011_19 = "Cukup jelas bahwa kau sudah menggangguku… Jadi, istirahatlah lebih awal.",
  str_voice_1600011_20 = "Northland adalah satu-satunya tempat kami bisa bertahan hidup, terutama untuk saudariku…",
  str_voice_1600011_21 = "Sesuai perintah dari Yang Mulia Ratu, aku akan mengawasi Lumopolis baik-baik dengan cerminku.",
  str_voice_1600011_22 = "Demi Utara.",
  str_voice_1600011_23 = "Tak perlu mengomentarinya. Zat-zat biasa tapi berbahaya itu tak mungkin bisa masuk ke Northland.",
  str_voice_1600011_24 = "Dia adalah Northland itu sendiri, dan dia melindungi segala yang suci. Ini jugalah alasan aku mengaguminya.",
  str_voice_1600011_25 = "Dia memang agak bawel, tapi sang Ratu bilang itu justru hal bagus karena dia membuat suasana istana Northland lebih ceria.",
  str_voice_1600011_26 = "Bebungaan putih, waktu santai, aroma bersih segar… dan saudariku.",
  str_voice_1600011_27 = "Aku tak suka apa pun yang tak bersih. Menyebutnya saja sudah membuatku jijik.",
  str_voice_1600011_28 = "Warna putih sebersih ini sulit ditemukan. Aku tahu kau pasti merawatnya.",
  str_voice_1600011_29 = "Jangan bertingkah lancang. Jangan pula mengeluh bahwa Nikinis tidak memperingatkanmu. Ya ampun, segala hal di luar Northland memang benar-benar barbar.",
  str_voice_1600011_30 = "Aku menunggu agar bunga yang mekar lebih banyak lagi.",
  str_voice_1600011_31 = "Mana yang lebih jelas? Masa lalu atau masa depan?",
  str_voice_1600011_32 = "Takdir dua dunia akan saling bertaut!",
  str_voice_1600011_33 = "Akhirnya aku berhasil menyeberangi dimensi jauh ini.",
  str_voice_1600011_34 = "Tuntaskan saja.",
  str_voice_1600011_35 = "Bunga-bunga di Northland bermekaran.",
  str_voice_1600011_36 = "Kau tak perlu mengingatkanku.",
  str_voice_1600011_37 = "Layu dan mekar—",
  str_voice_1600011_38 = "Ini adalah bunga-bunga musim semi dari surga—",
  str_voice_1600011_39 = "Semoga damai dan tenang.",
  str_voice_1600011_40 = "Harusnya memang damai dan tenang.",
  str_voice_1600011_41 = "Kukatakan sekali saja, hanya sekali, memang beginilah cara kami di Northland.",
  str_voice_1600011_42 = "Bukankah ini hasil sempurna yang kauinginkan?",
  str_voice_1600011_43 = "Ya ampun, pakaiannya kotor.",
  str_voice_1600011_44 = "Apa kau suka White Narcissus? Kalau begitu, kau boleh memandanginya agak lama.",
  str_voice_1600011_45 = "Harusnya aku memang tak berharap apa pun darimu… Cih.",
  str_voice_1600011_46 = "Ternyata lumayan bagus, ya? Akan kuterima.",
  str_voice_1600011_47 = "Hadiah ini memang sudah bisa diduga, jadi aku tak terlalu menantikannya.",
  str_voice_1600011_48 = "Ini… Kali ini lumayan bagus. Yah, kalau begitu, terima kasih.",
  str_voice_1600011_49 = "Aku kehilangan ingatan dan rasa nostalgia sekaligus. Sejak itu, aku sama sekali tak peduli dengan dunia di luar sana.",
  str_voice_1600011_50 = "Waktu tidak akan mengembalikan bunga-bunga gugur, juga cintaku.",
  str_voice_1600011_51 = "Northland menjaga rahasia dunia ini. Ingatan White Narcissus yang terkunci akan menjadi peringatan terakhir bagi benua ini.",
  str_voice_1600011_52 = "Alchemy Stars.",
  str_voice_1600011_53 = "Hah… Di mana kau?",
  str_voice_1600011_54 = "…Selamat pagi.",
  str_voice_1600011_55 = "Kau tak perlu terlalu memikirkannya, cukup…",
  str_voice_1600011_56 = "Kalau kau mau istirahat, lupakan saja…",
  str_voice_1600011_57 = "Kalau begitu, Selamat Tahun Baru.",
  str_voice_1600041_1 = "Oi, cukup antara kita saja, ya. Coba katakan padaku, siapa yang lebih terkenal, aku atau si besar itu? Hah? Mustahil! Apa semua orang sudah buta? Padahal penguin jelas lebih imut, 'kan?",
  str_voice_1600041_2 = "Apa ada orang di sana—? Tolong!! Oh, ternyata kau! Bawakan aku sekaleng daging sekarang juga. Cepat beri Kuma makan. Kalau tidak, dia akan melahapku untuk mengganjal perutnya yang kelaparan!",
  str_voice_1600041_3 = "Cih, akan buruk jadinya kalau kau meremehkan kami. Kami ini tentara bayaran yang lumayan ternama di benua ini. Ehem, terutama sebelum terjadinya ledakan tak disengaja itu…",
  str_voice_1600041_4 = "Kenapa sih kita tak bisa membuat kolam renang di Colossus? Badan Kuma makin besar dan sudah tak muat kalau harus meringkuk di dalam kulkas untuk menyejukkan diri…",
  str_voice_1600041_5 = "- Panas sekali!\n- Ah! Aku paham sekarang! Pokoknya, bangun saja dulu! Bangun, dasar si putih bego! Ya ampun, aku pun sekarang kepanasan…",
  str_voice_1600041_6 = "- Aku bosan sekali! Apa kau mau main bisbol denganku dengan granat ini? SUPER seru, lho!\n- Baiklah, aku akan main.\n- Kau sedang apa, sih? Minggir! Tunggu—!!!",
  str_voice_1600041_7 = "Oh? Kau tertarik dengan tarian kami? Rupanya seleramu bagus juga! Kalau kau benar-benar ingin jadi muridku, mungkin sebaiknya kuajari saja kau. Hehe!",
  str_voice_1600041_8 = "Rasanya lumayan enak. Nih, cobalah.",
  str_voice_1600041_9 = "Ckck, aku tak tahu harus bagaimana menghadapimu. Mungkin akan kuizinkan kau mengelus buluku yang lebat dan lembut ini… Namun, jangan sampai arah belaianmu salah!",
  str_voice_1600041_10 = "Hoi! Kenapa kau melamun? Apa kita tinggalkan saja pekerjaan ini dan pergi ke suatu tempat untuk bersantai?",
  str_voice_1600041_11 = "Ayo cari tempat untuk tidur siang. Perut si besar ini nyaman sekali. Ikuti saja aku… Zzz…",
  str_voice_1600041_12 = "J-jangan mencolek perutku!",
  str_voice_1600041_13 = "Oh… Padahal aku hanya melompat kecil, tapi lantainya malah jadi retak.",
  str_voice_1600041_14 = "Kami tidak gendut, kami cukup makan! Ya, cukup makan! Karena tentara bayaran berpenghasilan besar!",
  str_voice_1600041_15 = "Ayo, kita adakan pesta ulang tahun! Joget! Joget!",
  str_voice_1600041_16 = "Yo! Ayo bersenang-senang bersama!",
  str_voice_1600041_17 = "Pagi ini kita sarapan apa? Apa ada es krim?",
  str_voice_1600041_18 = "Hari ini kau terlambat. Mana makanannya?",
  str_voice_1600041_19 = "Hoik! Aku ingin makan malam lagi.",
  str_voice_1600041_20 = "Aku bebas berkeliling tanpa ada yang mengatur-aturku. Sungguh menyenangkan.",
  str_voice_1600041_21 = "Saudara-saudaraku di Rediesel Wrench benar-benar tahu cara bersenang-senang! Kalau kami sudah normal suatu hari nanti, aku juga akan kongko dengan mereka!",
  str_voice_1600041_22 = "Polar!",
  str_voice_1600041_23 = "Aku tak bisa makan. Menyebalkan.",
  str_voice_1600041_24 = "Aku tak bisa memahami si Kafka itu! Aku memintanya memberi kita makanan, tapi dia malah mengusir kita! Dasar wanita!",
  str_voice_1600041_25 = "Shark Tooth Powder milik Korgon benar-benar lezat! Sayangnya, porsinya kurang banyak…",
  str_voice_1600041_26 = "Saat aku akhirnya bisa rebahan di atas sebongkah es setelah bekerja, rasanya seperti… surga.",
  str_voice_1600041_27 = "Panas sekali! Aku meleleh!",
  str_voice_1600041_28 = "Tempat ini asing dan penghuninya pun beragam, dan penyejuk udaranya membuatnya terasa sangat nyaman.",
  str_voice_1600041_29 = "Yuhuhu! Pasangan partner terkuat di benua ini hadir di sini! Biar kami saja yang tangani pertarungannya, kalian cukup siapkan makanan yang cukup untuk kami!",
  str_voice_1600041_30 = "Aku jadi makin tinggi!",
  str_voice_1600041_31 = "Aku makin kuat dan buluku makin mengilap!",
  str_voice_1600041_32 = "Rasanya luar biasa!",
  str_voice_1600041_33 = "Hehe, sekarang kita tak terkalahkan, rekan!",
  str_voice_1600041_34 = "Jangan seret kami!",
  str_voice_1600041_35 = "Kuma! Bersiap menembak!",
  str_voice_1600041_36 = "Arahkan bidikanmu dengan baik!",
  str_voice_1600041_37 = "- Ini dia!\n- Tunggu! Ah—",
  str_voice_1600041_38 = "- Ambil juga ini!\n- Aku tak peduli lagi…",
  str_voice_1600041_39 = "Aku yakin kau pasti tak menduga akan diserang tiba-tiba!",
  str_voice_1600041_40 = "Lepas landas!",
  str_voice_1600041_41 = "Kami akan bertarung duluan!",
  str_voice_1600041_42 = "Kami tak mungkin kalah!",
  str_voice_1600041_43 = "Kita gagal… Sial…",
  str_voice_1600041_44 = "Aku ingin minuman dingin.",
  str_voice_1600041_45 = "Apa ini aman dimakan?",
  str_voice_1600041_46 = "Kuma! Lihat apa yang kudapatkan!",
  str_voice_1600041_47 = "Ini berharga. Apa ada pekerjaan yang bisa kita lakukan?",
  str_voice_1600041_48 = "Hore! Kau boleh mengambil salah satu kaleng makanan kesayanganku.",
  str_voice_1600041_49 = [[
- Utara! Utara! Kau belum pernah ke sana, 'kan? Di sana sangat berbeda! Kuharap aku bisa menunjukkan pemandangan di sana kepadamu. Iya, 'kan, Kuma
- Ya.]],
  str_voice_1600041_50 = "Masa lalu tidaklah penting asalkan aku dan partnerku bisa makan sebanyak yang kami mau. Semoga perjalananku bersama Kuma tak akan pernah berakhir. Aduh, aku jadi malu sendiri dengan kata-kataku barusan… Hoi, j-jangan tertawa!",
  str_voice_1600041_51 = [[
- Kau ingin tahu seperti apa penampilanku dulu? Dulu, warna buluku tidak seperti ini, dan suaraku aneh seperti bebek.
- Sepertinya jelek.]],
  str_voice_1600041_52 = [[
- Alchemy?
- Stars!!]],
  str_voice_1600041_53 = "Yo! Aku mencarimu!",
  str_voice_1600041_54 = "Pagi! Hari ini menyenangkan!",
  str_voice_1600041_55 = "Lho, kau juga ada di sini?",
  str_voice_1600041_56 = "Jangan tidur terus! Sini, bantu aku!",
  str_voice_1600041_57 = [[
- Tahun Baru?
- Tahun ini akan menyenangkan! Selamat Tahun Baru!]],
  str_voice_1600051_1 = "Bagaimana kalau minum teh dengan teman-teman baru kita dan menikmati momen menyenangkan terakhir di hidup kita bersama-sama?",
  str_voice_1600051_2 = "Kuikatkan saja benang ke jiwamu dan kita berjoget waktu minum teh sore nanti! Ayo!",
  str_voice_1600051_3 = "Oh, sepasang cakar mekanis ini? Jangan khawatir. Ini sama sekali tidak akan melukaimu—setidaknya, sejauh ini sih belum pernah ada yang protes!",
  str_voice_1600051_4 = "Oh, jeritan merdu itu. Mereka adalah mainan dan sumber inspirasiku! Ayah dan saudariku sama-sama tak bisa memahami suara merdu mereka itu… Apa kau bisa memahaminya?",
  str_voice_1600051_5 = "Di belakang kediaman bangsawan terhormat itu, ada taman; di taman terbengkalai itu, ada makam; di dalam makam tua dan lembap itu, terbaringlah seorang wanita; dan dalam senyum wanita itu… Oh, apa yang kaulihat?",
  str_voice_1600051_6 = "Segel sarkofagus itu telah terbuka. Turuti saja hasrat dan keinginanmu. Ulurkan tanganmu sepenuh hati, dan petiklah buah-buahan manis itu…",
  str_voice_1600051_7 = "Tatapan matamu itu… Apa yang kauinginkan? Atau, jangan-jangan… Kau ingin bergabung dengan keluarga besar ini dan menjadi anggota keluarga bangsawan glamor ini?",
  str_voice_1600051_8 = "Baiklah. Kuizinkan kau mendekatiku. Namun, kalau sampai kau menggores rokku, akan kuinjak wajahmu. Boleh, 'kan?",
  str_voice_1600051_9 = "Yang di wajahmu itu rasa takut atau senang… saat kau memandang mataku? Oh, kau mau aku menebak? Nakal sekali.",
  str_voice_1600051_10 = "\"Setiap bintang dan bulan redup, laba-laba hitam bangkit dari kubur untuk memakan para penghuni neraka yang tersesat…\" Orang bodoh macam apa yang menulis sesuatu semenggelikan ini!",
  str_voice_1600051_11 = "Aku, kau ingin aku tinggal di sini? Kau tahu 'kan, aku ini digosipkan sebagai mimpi buruk dari dalam kubur?",
  str_voice_1600051_12 = "Kau barusan menyentuhku, ya? Kalau yang kausentuh itu Mia, dia mungkin sudah menangis.",
  str_voice_1600051_13 = "Aku ingin teh hitam… dan camilan… teh… dan camilan…",
  str_voice_1600051_14 = "Kalau tersenyum seperti ini, aku jadi kelihatan seperti Baba Yaga, 'kan? Hm… Yah, wajahnya memang persis wajahku, sih.",
  str_voice_1600051_15 = "Maaf, aku muncul tiba-tiba! Dia bilang, mungkin harusnya akulah yang melakukannya… tahulah maksudku, merayakan ulang tahunmu.",
  str_voice_1600051_16 = "Kau. Terlambat. Dari mana kau?",
  str_voice_1600051_17 = "Bukannya kau tahu kau TIDAK boleh menggangguku sepagi ini!?",
  str_voice_1600051_18 = "Tunggu. Kau… mengharapkan sambutan dariku? Kalau begitu… Selamat datang!",
  str_voice_1600051_19 = "Saatnya merasakan pengalaman horor yang menyenangkan. Bagaimana kalau kita lihat… Black Spider?",
  str_voice_1600051_20 = "Kaukira aku akan betah di sana? Istana putih itu? Kau pasti sudah gila…",
  str_voice_1600051_21 = "Mesin-mesin ini… Para peneliti itu pasti sepenuh hati saat membuatnya. Tentu saja, aku bersyukur atas ini.",
  str_voice_1600051_22 = "Bayangan ada di bawah sana.",
  str_voice_1600051_23 = "Eclipsite? Oh! Makhluk-makhluk itu adalah mainan untuk kusiksa.",
  str_voice_1600051_24 = "Saudariku yang malang. Kalau kami bisa bertemu langsung, aku penasaran bagaimana wajahnya. Ha!",
  str_voice_1600051_25 = "Walau dialah yang lebih banyak berhak atas tubuh ini, dia tetap mengizinkanku menggunakannya setiap kali aku mulai bawel.",
  str_voice_1600051_26 = "Apa ini? Kau mau membuat kami senang? Mana teh hitam dan camilan untuk kami?",
  str_voice_1600051_27 = "Apa pendapatmu tentangku? Menyebalkan? Apa? Kukira kau benar-benar mau membahasnya?",
  str_voice_1600051_28 = "Aku mencium suatu bau yang membuatku sebal, sepertinya dari suatu tempat di sini…",
  str_voice_1600051_29 = "Sini. Mendekatlah. Sang bangsawan tuan rumah mengundangmu untuk ikut serta dalam pesta minum teh ini. Kami bersenang-senang di pesta ini—",
  str_voice_1600051_30 = "Kau sangat tertarik kepadaku, ya?",
  str_voice_1600051_31 = "Ya, saudariku sayang. Kita bukan lagi kita yang dulu…",
  str_voice_1600051_32 = "Berlututlah di hadapanku! Agar aku bisa menyantap jiwamu!",
  str_voice_1600051_33 = "Aku akan menantimu di sarang hukuman penuh kasih, Carleen!",
  str_voice_1600051_34 = "Main denganku, yuk?",
  str_voice_1600051_35 = "Rasanya lebih enak daripada camilan…",
  str_voice_1600051_36 = "Aduh, aku jadi ngiler…",
  str_voice_1600051_37 = "Menangislah! Menjeritlah! Oh, sungguh jiwa yang merdu!",
  str_voice_1600051_38 = "Oh, aroma ketakutan sungguh membangkitkan selera!",
  str_voice_1600051_39 = "Tak ada jalan untuk lolos!",
  str_voice_1600051_40 = "Hukuman!!",
  str_voice_1600051_41 = "Taman bermain di Neraka, milikku seorang!",
  str_voice_1600051_42 = "Oh, akan kuraup kau seperti keinginanmu.",
  str_voice_1600051_43 = "Amat! Sangat! Membosankan!!!",
  str_voice_1600051_44 = "Yah… Aku sebenarnya… tidak suka karena rok ini sangat gelap.",
  str_voice_1600051_45 = "Tunjukkan ketulusan atau akan kumarahi kau.",
  str_voice_1600051_46 = "Usahamu untuk membuatku senang sungguh menggemaskan.",
  str_voice_1600051_47 = "Apa kau melakukannya untuk memancing amarahku?",
  str_voice_1600051_48 = "Kalau kau harus bersikap sangat baik… Lain kali, akan kubiarkan dia berterima kasih kepadamu.",
  str_voice_1600051_49 = "Ku… kuharap aku tak membuatmu takut. Benar, kami adalah Black Spider pemangsa jiwa yang sedang ramai dibicarakan orang-orang Lumopolis… Ini rahasia yang sangat ingin disampaikannya…",
  str_voice_1600051_50 = "Kapan terjadinya? Dulu, saat Ayahku masih menyayangiku, Ibuku masih bersamaku, adik perempuanku masih bayi yang suka menangis… dan perang belum pecah.",
  str_voice_1600051_51 = "Sebenarnya dia ingin mengubur rahasia Lumopolis bersamaku… Namun, suatu hari, rahasia itu pasti akan muncul kembali… Tunggu saja, Ayahku sayang…",
  str_voice_1600051_52 = "Al-che-my Stars.",
  str_voice_1600051_53 = "Kau, sini!",
  str_voice_1600051_54 = "Aku butuh sesuatu darimu!",
  str_voice_1600051_55 = "Apa… apa kau di sana?",
  str_voice_1600051_56 = "Kau sedang apa?",
  str_voice_1600051_57 = "Ha, Tahun Baru? Sungguh?",
  str_voice_1600101_1 = "Ada apa? Lagi-lagi sedih? Lihat! Seekor kelinci datang untuk menghiburmu. Sudah baikan sekarang?",
  str_voice_1600101_2 = "Aku merawat sebuah dunia kecil yang selama ini selalu diabaikan. Mungkin suatu hari nanti kekuatan dunia itu akan menjadi kunci yang akan menyelamatkan kita.",
  str_voice_1600101_3 = "Kau tak berhati-hati, tak bertanggung jawab pula… Kaukira kau sudah dewasa hanya karena tubuhmu makin tinggi dan wajahmu ditumbuhi berewok? Kau salah!",
  str_voice_1600101_4 = "Pocket World ini makin lama makin gelisah, menimbulkan bahaya bagi orang-orang di sekitarnya setiap kali ia terusik! Sang Ratu bilang, aku harus berusaha lebih keras dan berusaha mengendalikan kekuatan ini!",
  str_voice_1600101_5 = "Tak lama lagi, kotak permenku akan menjadi peti mati untuk musuhku. Kekuatanku sungguh ngeri! Oh, ya ampun…",
  str_voice_1600101_6 = "Akan ada lebih banyak dongeng di dunia ini, yang menjadi lebih hidup berkat mimpi semua orang! Sama seperti dunia yang baru saja dibuat ini, yang berisi perjalanan kita!",
  str_voice_1600101_7 = "Kaum Elf bekerja untuk Yang Mulia Ratu dan tugasku adalah mencatat kisah-kisah Northland. Mau mengintipnya sedikit?",
  str_voice_1600101_8 = "Aku sedang membangun sebuah pondok dari permen. Menurutmu, sebaiknya jendelanya rasa apa, ya? Ini memang kebiasaan di Northland.",
  str_voice_1600101_9 = "Apa kau meminta pendapatku?! Tadinya kupikir kau menganggapku masih bocah… Aku sangat tersentuh!",
  str_voice_1600101_10 = "Singkirkan tumpukan kayu bakar itu. Semua jenis sumber api dilarang di sini! Hah? Aku tak peduli! Pokoknya. Dilarang!",
  str_voice_1600101_11 = "Hai! Kau ke sini untuk mendengar dongeng pengantar tidur? Ada \"Little Snowman and Twelve Stars\", \"The Elf's Cottage\", \"The Dragon's Child!\", dan masih banyak lagi! Mana yang kau suka?",
  str_voice_1600101_12 = "Kau mau lihat sihir? Lihat apa yang ada di dalam sakuku… Ta-ra! Permen!",
  str_voice_1600101_13 = "Kau ingin jadi Elf seperti apa? Aku bisa menggambarkanmu sesuai keinginanmu dalam cerita ini!",
  str_voice_1600101_14 = "Pilih satu barang dari sakuku, dan berikan kepada orang yang kausayangi!",
  str_voice_1600101_15 = "Selamat ulang tahun! Kau mau manusia salju, permen, buku dongeng, atau anak pohon?",
  str_voice_1600101_16 = "Selamat datang kembali! Kau pasti lelah. Nih, permen agar kau kembali segar!",
  str_voice_1600101_17 = "Waow—Selamat pagi. Sepertinya kemarin aku bermimpi tentang kapal dari permen… Bagaimana denganmu?",
  str_voice_1600101_18 = "Ayo cari tempat hangat untuk duduk-duduk, makan permen, dan membaca cerita.",
  str_voice_1600101_19 = "Hah? Kenapa? Kau tak bisa tidur? Mau kubacakan dongeng pengantar tidur?",
  str_voice_1600101_20 = "Seperti umumnya hutan dalam dongeng, Northland didiami oleh segala jenis makhluk mitos.",
  str_voice_1600101_21 = "Hmm… Aku belum pernah pergi ke tempat lain mana pun, tapi aku tahu tentang pondok bawah tanah dalam cerita!",
  str_voice_1600101_22 = "Pondok itu dibangun saat musim dingin hampir berakhir.",
  str_voice_1600101_23 = "Dalam cerita, ada pula air laut berwarna hitam yang sedikit demi sedikit menuju kemari!",
  str_voice_1600101_24 = "Si kecil Noah sungguh menggemaskan! Dia bahkan diceritakan dalam dongeng. Aku pernah membacakannya untukmu, 'kan?",
  str_voice_1600101_25 = "Saudariku sering memandang cermin sambil diam, seperti White Narcissus di dalam cerita.",
  str_voice_1600101_26 = "Dongeng, permen, bungkus permen, rumah roti jahe buatan sendiri… Aku suka banyak hal!",
  str_voice_1600101_27 = "Hmm… Aku tak suka hal-hal yang tak bisa kugambarkan. Atau yang tak bisa kucatat, atau kubicarakan.",
  str_voice_1600101_28 = "Colossus lebih mirip dengan naga raksasa yang ada dalam dongeng. Sama sekali tidak mirip dengan naga mana pun yang pernah kutemui!",
  str_voice_1600101_29 = "Sepertinya kau baru saja mengalami banyak masalah. Apa kau keberatan kalau kujadikan tokoh protagonis dalam ceritaku? Mungkin nanti akan jadi cerita paling laris di Northland!",
  str_voice_1600101_30 = "Sakuku hampir penuh!",
  str_voice_1600101_31 = "Sudah mulai! Sudah mulai! Parade akbarnya sudah hampir dimulai!",
  str_voice_1600101_32 = "Kemarilah dan ikutlah dalam perjalanan menakjubkan ini!",
  str_voice_1600101_33 = "Harapan semua orang tertulis dalam dongeng!",
  str_voice_1600101_34 = "Bahan cerita baru!",
  str_voice_1600101_35 = "Elf! Demi kejayaan Yang Mulia Ratu!",
  str_voice_1600101_36 = "Ayo buat keributan!!",
  str_voice_1600101_37 = "Menuju dunia dongeng!",
  str_voice_1600101_38 = "Lagi-lagi, ini adalah awal mimpi yang menakjubkan!",
  str_voice_1600101_39 = "Kita harus merawat buku!",
  str_voice_1600101_40 = "Dilarang melakukan vandalisme!",
  str_voice_1600101_41 = "Berkumpullah, Elf Squad!",
  str_voice_1600101_42 = "Keren!! Bisa kumasukkan ke dalam ceritaku, nih!",
  str_voice_1600101_43 = "Aduh! Ini tak seru…",
  str_voice_1600101_44 = "Mau kuajari sedikit sihir? Pertama, coba kita munculkan sebuah kotak, lalu masukkan permen ke dalamnya.",
  str_voice_1600101_45 = "Memangnya kau lupa, ya? Aku ini seorang pencipta!",
  str_voice_1600101_46 = "Ini tak bisa kuciptakan! Terima kasih banyak!",
  str_voice_1600101_47 = "Bagaimana kalau kuciptakan sesuatu untukmu sebagai gantinya?",
  str_voice_1600101_48 = "Wow! Aku senang sekali! Terima kasih! Terima kasih! Terima kasih!",
  str_voice_1600101_49 = "Bibi Lita adalah satu-satunya keluarga yang masih kumiliki. Dia sering menceritakan kisah-kisah masa kecilku. Ceritanya sangat berbahaya. Aku nyaris saja kehilangan nyawa!",
  str_voice_1600101_50 = "Ayah dan ibuku selalu bepergian jauh. Kudengar, mereka pergi jauh. Yah, mereka berencana mendaki gunung beku berselimut salju itu. Aku penasaran, apa kira-kira mereka akan bertemu dengan peri es, ya?",
  str_voice_1600101_51 = "Bab yang tak semestinya ada dalam dongeng harusnya dihapus saja… Dongeng selalu berakhir manis, begitu pula kisah kita. Semua akan baik-baik saja!",
  str_voice_1600101_52 = "Alchemy, Stars.",
  str_voice_1600101_53 = "Halo!",
  str_voice_1600101_54 = "Oh… Selamat pagi.",
  str_voice_1600101_55 = "Aku punya permen untuk kita berdua.",
  str_voice_1600101_56 = "Yah, aku tak bisa tidur…",
  str_voice_1600101_57 = "Selamat Tahun Baru!",
  str_voice_1600111_1 = "Apa yang kuperjuangkan? Aku bertambah kuat berkat kebencian akan darah dan api, tapi sepertinya itu bukan jawaban yang kauinginkan.",
  str_voice_1600111_2 = "Azure Flame Sword milikku bertambah kuat kalau musuhku takut, tapi tidak demikian halnya dengan sayap dan sisik nagaku karena makhluk jahat tak akan pernah bisa menyentuhnya.",
  str_voice_1600111_3 = "Amarah naga mirip dengan kemampuan bertarung yang sudah dikuasai Hiiro—abadi, mematikan, dan sangat kejam. Namun, masih jauh untuk bisa menyaingi Grand Marshal…",
  str_voice_1600111_4 = "Aku akan mengadili raja kuno dan sampah kotor itu! Jangan sampai ternyata kau punya hubungan dengan mereka!",
  str_voice_1600111_5 = "Hati naga dipenuhi hasrat membunuh yang terpendam. Jangan tanya kenapa aku tak menunjukkan belas kasihan. Itulah yang akan tertulis di batu nisan orang-orang lemah.",
  str_voice_1600111_6 = "Cahaya dan bayangan menempa kedua sisi naga sejati, yang akan terus meraung dengan gagah, entah dia hidup maupun mati! Hasrat balas dendam telah bangkit—",
  str_voice_1600111_7 = "Ya, ada hal lain yang mengalir dalam darahku, selain balas dendam. Terima kasih sudah membuatku sadar tentang hal itu. Orang terakhir yang bisa melakukannya adalah Grand Marshal.",
  str_voice_1600111_8 = "Aku tahu anggapan Nemesis dan Gronru tentangku, tapi… setidaknya, aku tak mau kau beranggapan seperti mereka.",
  str_voice_1600111_9 = "Kau membawa harapan bagi hatiku yang letih ini, dan sekarang aku ingin melakukan hal yang sama untukmu. Kau pasti bisa! Rekan sebangsaku!!",
  str_voice_1600111_10 = "Bahaya akan menghantam saat kita lengah. Naga raksasa selalu membiarkan sebelah matanya terbuka sekalipun sedang tidur.",
  str_voice_1600111_11 = "Nafsu makanmu ternyata cukup besar. Semoga keberanianmu pun sama besarnya.",
  str_voice_1600111_12 = "Apa pun itu, cepatlah. Aku harus menangani urusan publik dan tidak punya banyak waktu.",
  str_voice_1600111_13 = "Apa kau sudah lupa cara menyapa orang lain? Jangan gemetaran terus, berdirilah dengan tegak!",
  str_voice_1600111_14 = "Kau mau meningkatkan kemampuanmu? Bagus sekali, aku akan menyusun rencana latihan untukmu. Datanglah ke ruanganku pukul 6 pagi besok!",
  str_voice_1600111_15 = "Aku harus mengatakan sesuatu kepada orang-orang yang pantang menyerah. Nah, kemarilah dan duduk bersamaku, rekan sebangsaku.",
  str_voice_1600111_16 = "Akhirnya kau datang juga, tepat waktu. Ayo lakukan sesuatu bersama. Kita akan pergi setelah menyusun rencana dan memutuskan kapan akan menyerang.",
  str_voice_1600111_17 = "Bagus sekali, kau harus menghargai waktu latihanmu. Jangan buang-buang waktu, ayo kita mulai sekarang juga.",
  str_voice_1600111_18 = "Tetap semangat! Ini belum saatnya istirahat!",
  str_voice_1600111_19 = "Kau butuh istirahat cukup agar bisa jadi lebih kuat. Tidurlah, aku akan berjaga di sini.",
  str_voice_1600111_20 = "Saat aku kehilangan arah, Illumina menunjukkan keyakinan baru kepadaku dan menyelamatkanku agar aku tak dilahap kebencianku.",
  str_voice_1600111_21 = "Klanku tidak punya utang apa pun pada kota apung itu. Yang ada hanyalah kekecewaan dan kebencian yang tak terlukiskan.",
  str_voice_1600111_22 = "Jayalah Illumina!",
  str_voice_1600111_23 = "Membenci dan membasmi musuh adalah fakta kehidupan yang tidak bisa dihindari.",
  str_voice_1600111_24 = "Dia berani dan kuat, dia bersikukuh dengan tekadnya, dan tak pernah goyah karenanya. Aku sama sekali bukan tandingan baginya.",
  str_voice_1600111_25 = "Aku tak bisa melihat \"tekad\" dalam dirinya. Aku penasaran, sebenarnya apa sih yang dipikirkan si kucing pemalas itu?",
  str_voice_1600111_26 = "Selain latihan… Ini emblem klanku. Ini memberiku kekuatan.",
  str_voice_1600111_27 = "Aku tak begitu peduli tentang ekor. Yang benar-benar kubenci adalah sistem yang korup dan aturan brutal.",
  str_voice_1600111_28 = "Apa kadang kau memandangi Colossus ini? Sama seperti aku yang sering memandangi emblem klanku ini.",
  str_voice_1600111_29 = "Memangnya kau belum pernah lihat Aurorian secantik aku? Baiklah, aku tak akan menyalahkanmu. Bahkan dulu pun, jumlah Aurorian yang secantik aku memang hanya sedikit. Sharona, siap melayanimu.",
  str_voice_1600111_30 = "Kemampuan pedangku jadi makin murni.",
  str_voice_1600111_31 = "Darah klan kami yang hilang kini bergejolak!",
  str_voice_1600111_32 = "Api balas dendam telah berkobar di pedang dan mataku.",
  str_voice_1600111_33 = "Bekas kastel raja yang telah tumbang itu pasti akan ditempa menjadi peti mati besi!",
  str_voice_1600111_34 = "Angkat kepalamu!",
  str_voice_1600111_35 = "Boleh aku bertarung dalam wujud asliku?",
  str_voice_1600111_36 = "Aku tak bisa menahannya lebih lama lagi…",
  str_voice_1600111_37 = "Sang naga telah menjatuhkan hukuman mati untukmu!",
  str_voice_1600111_38 = "Remuklah dalam cahaya dan bayangan—",
  str_voice_1600111_39 = "Dragon Breath!",
  str_voice_1600111_40 = "Musnahlah!",
  str_voice_1600111_41 = "Yang keberatan, bilang saja sekarang.",
  str_voice_1600111_42 = "Terjerumus dalam hidup yang hanya untuk membunuh… tapi ternyata rasanya menyenangkan.",
  str_voice_1600111_43 = "Kau… Suatu saat, akan kubalas kau… Kau harus menerima pembalasan dendamku!",
  str_voice_1600111_44 = "Aku sudah melihat upayamu. Sekarang, istirahatlah.",
  str_voice_1600111_45 = "Ini… Baiklah, terima kasih, ya.",
  str_voice_1600111_46 = "Sangat cermat dan mengagumkan! Terima kasih!! Rekan sebangsaku!!",
  str_voice_1600111_47 = "Terima kasih, lagi-lagi kau berbuat sedemikian banyak untukku.",
  str_voice_1600111_48 = "Rekan sebangsaku, akan kujaga persahabatan ini selamanya!",
  str_voice_1600111_49 = "Kalau klanku kembali, segala yang kaulihat sekarang akan bergetar dan jadi tak berarti sama sekali. Sepertinya begitu, sih. Masa lalu tak bisa diubah…",
  str_voice_1600111_50 = "Keluarga naga adalah bukti masa penuh dosa dan kekejaman, tapi sejarah White Night menolak mengakui hal ini. Aku tak tahu akan jadi seperti apa nasibku seandainya aku tak bertemu dengan Illumina dan Grand Marshal…",
  str_voice_1600111_51 = "Kata orang, api naga akan menghancurkan segalanya, termasuk ingatan dan sejarah kita. Menarik sekali. Seperti semut yang takut api, tak disangka-sangka, ternyata para pendosa ini punya kesadaran sangat mendalam tentang hal-hal ini?",
  str_voice_1600111_52 = "Alchemy Stars!",
  str_voice_1600111_53 = "Rekan sebangsaku.",
  str_voice_1600111_54 = "Waktu adalah uang. Ayo kita pergi sekarang.",
  str_voice_1600111_55 = "Waktu istirahat makan siang sudah habis. Jaga semangat kalian!",
  str_voice_1600111_56 = "Sudah larut, jadi akan kupersingkat saja.",
  str_voice_1600111_57 = "Selamat! Tahun Baru akhirnya tiba!",
  str_voice_1600191_1 = "Ramalan terwujud, kita harus membuat persembahan untuk Lord of Truth. Panggil Nails sebelum dia menyesal berlebihan lagi.",
  str_voice_1600191_2 = "Tome of Truth sebenarnya sempurna. Sayangnya, para hakim dan pengadilan tak bisa menghargainya, padahal dia setia kepada mereka.",
  str_voice_1600191_3 = "Menjual jiwa? Tidak, aku hanya mengambil jiwa-jiwa gelandangan dan mengirimkannya ke Truth Nation.",
  str_voice_1600191_4 = "Kami butuh korban lebih banyak agar bisa masuk ke Domain of Truth. Tentu saja, \"Truth\" yang kami yakini berbeda.",
  str_voice_1600191_5 = "Ketamakan atas intisari kehidupan dianggap sebagai kebajikan. Tetapi tentu saja, segala sesuatu yang berlebihan itu tidak baik.",
  str_voice_1600191_6 = "Dengar, suara yang terkubur oleh dosa akan bangkit dan terhempas kembali ke bumi bagai matahari merah. Mulai sekarang, semua orang akan diselamatkan!",
  str_voice_1600191_7 = "\"Ada juga sisi seperti itu dalam diriku\"? Apa itu bisa kuanggap pujian?",
  str_voice_1600191_8 = "Akan kutunjukkan pemandangan saat malam. Mungkin kau akan suka. Seperti biasa, jiwa muda akan merasa gembira dalam kegelapan dan mencari jalan untuk menembus batas.",
  str_voice_1600191_9 = "Suasananya jadi tegang. Inikah maumu? Tahu tidak, dinding pun punya telinga. Kalau kau tak hati-hati, tindakan ini bisa saja memancing kecemburuan.",
  str_voice_1600191_10 = "Aku tahu kau lelah. Serahkan semuanya padaku… Asalkan akhirnya bisa mengikuti langkahku, tak ada ruginya kau memakluminya untuk sementara…",
  str_voice_1600191_11 = "Sepertinya kau punya ketertarikan khusus pada makhluk-makhluk kuno… Tak apa. Tolong… luangkan waktu lebih banyak bersamaku.",
  str_voice_1600191_12 = "Aku bisa mengajarimu pelan-pelan. Namun, sebelum itu, kau harus berusaha lebih keras untuk menyenangkanku.",
  str_voice_1600191_13 = "Mau dengar tentang doktrin Truth? Kami selalu menyampaikan ajaran dengan sabar…",
  str_voice_1600191_14 = "Mau dengar sesuatu yang istimewa? Kisah tentang orang-orang abadi yang tak menua dan tak bisa mati…",
  str_voice_1600191_15 = "Kurestui kau, anak muda. Bagaimana kalau kauminum cawan berisi sari bunga yang sudah kusiapkan untukmu ini, dan hidup berdampingan denganku?",
  str_voice_1600191_16 = "Saat tengah hari, kita memang mudah merasa lesu… Tentu saja, kau tak perlu mengkhawatirkanku.",
  str_voice_1600191_17 = "Bagi sebagian makhluk, sekarang saatnya istirahat… Kau mau ikut denganku?",
  str_voice_1600191_18 = "Saat aku terbangun pelan-pelan, aku selalu merasa seakan-akan sedang menikmati secangkir… sapaanmu yang hangat.",
  str_voice_1600191_19 = "Masih terjaga padahal sudah larut. Sepertinya kau juga suka bergadang.",
  str_voice_1600191_20 = "Kau harus paham bahwa Truth adalah jalan menuju masa depan, dan bimbingan yang tepat akan menghasilkan kemantapan.",
  str_voice_1600191_21 = "Baik dan buruk adalah wajah Lumopolis yang ditampakkannya kepada orang-orang, dan Hari Penghakiman akan mengungkap kebenarannya yang menyakitkan.",
  str_voice_1600191_22 = "Semoga Truth memberkatimu.",
  str_voice_1600191_23 = "Saat memastikan bahwa mereka juga diciptakan oleh dunia ini, aku menyadari kebenaran tentang kedua belah pihak.",
  str_voice_1600191_24 = "Faust adalah penyebar kabar yang luar biasa. Di hadapan Truth, dia bukan bawahanku.",
  str_voice_1600191_25 = "Aku tak membenci orang-orang keras kepala. Bagiku, rasanya seperti bicara dengan batu, dan aku sangat menyukainya.",
  str_voice_1600191_26 = "Sari kehidupan, buku-buku kuno, dan senjata yang disebut \"Relic\"… Aku sangat menyukainya.",
  str_voice_1600191_27 = "Tak ada hal yang benar-benar kubenci karena Truth menerima segalanya tanpa membeda-bedakan.",
  str_voice_1600191_28 = "Bagiku, mereka adalah pepohonan besar yang menghubungkan akses, sekaligus esensi kuno yang dekat dengan akarnya.",
  str_voice_1600191_29 = "Semua orang punya perasaan dan kenangan sendiri-sendiri dalam darah mereka… Ah, tadi aku sangat ingin tahu seperti apa \"rasa\"-mu.",
  str_voice_1600191_30 = "Ini gairah hidup yang segar!",
  str_voice_1600191_31 = "Aku berhasil menemukannya, cara untuk menembus batas kehidupan…",
  str_voice_1600191_32 = "Aku akan jadi lebih terhormat…",
  str_voice_1600191_33 = "Dalam nama Blood Queen, akan kumasuki aula agung berwarna kemerahan itu…",
  str_voice_1600191_34 = "Truth akan berdampak lebih besar.",
  str_voice_1600191_35 = "Aku hanya butuh satu kesempatan.",
  str_voice_1600191_36 = "Ikuti bimbingannya…",
  str_voice_1600191_37 = "Crimson! Thorn! Requiem!",
  str_voice_1600191_38 = "Saksikan Mukjizat ini!",
  str_voice_1600191_39 = "Dengarkan Truth!",
  str_voice_1600191_40 = "Rasakan kehebatan Truth!!!",
  str_voice_1600191_41 = "Bergeraklah sebelum kupaksa.",
  str_voice_1600191_42 = "Kemenangan terasa begitu indah seperti hidup baru.",
  str_voice_1600191_43 = "Aku lelah. Bangunkan aku kalau kau sudah yakin.",
  str_voice_1600191_44 = "Tak ada yang bisa membuatku senang selain melihatmu masih hidup…",
  str_voice_1600191_45 = "Kau membawakanku mainan baru. Kau sungguh bijak.",
  str_voice_1600191_46 = "Kau tahu persis apa yang kusukai. Apa, kau ingin diberi imbalan?",
  str_voice_1600191_47 = "Tentu saja aku akan menerimanya. Ini pengorbanan penting darimu…",
  str_voice_1600191_48 = "Sebagai imbalannya, akan kusiapkan sesuatu yang istimewa untukmu…",
  str_voice_1600191_49 = "Jangan sampai kehormatan kemuliaan dan kilasan predator ada bersamaan… Namun, kurasa mungkin ini terlalu sulit untuk kaupahami.",
  str_voice_1600191_50 = "Bagiku, garis keturunan hanyalah petunjuk yang menuntunku ke jalan pencarian. Pasti ada makna di balik Keabadian dan Kemalangan yang dikaruniakan Truth kepadaku.",
  str_voice_1600191_51 = "Vampir? Bukan, aku bukan vampir sejak lahir. Ini karunia. Kitab-kitab hitam mengubahnya menjadi bisikan yang bergema di telinga orang-orang terpilih.",
  str_voice_1600191_52 = "Alchemy Stars.",
  str_voice_1600191_53 = "Yah…",
  str_voice_1600191_54 = "Aku harus bilang selamat pagi kepadamu, 'kan?",
  str_voice_1600191_55 = "Selamat sore. Kau harus bersantai sedikit.",
  str_voice_1600191_56 = "Mengantuk, ya?",
  str_voice_1600191_57 = "Tahun Baru ini milikmu.",
  str_voice_1600251_1 = "Cih… Kesepian jiwa dan seni sejati adalah hal yang hanya bisa dipahami segelintir orang. Semua seniman pasti kesepian dan aku tak suka bergaul dengan orang lain…",
  str_voice_1600251_2 = "Aduh, aku sangat sibuk. Mau menonton pertunjukan musik? Sudah mengundang banyak orang? Sungguh? Kalau begitu, akan kuberi pengecualian dan aku akan tampil lagi—",
  str_voice_1600251_3 = "Ada yang mengeluhkan suara berisik yang kita timbulkan? Siapa yang berani mengeluh bahwa kawan lamaku ini berisik? Pasti rakyat jelata yang seleranya payah…",
  str_voice_1600251_4 = "Lihat, aku hanya perlu berseru \"Rasakan teror kereta dari neraka!\" dan kawan lamaku akan langsung melesat keluar. Kau mau melihatnya?",
  str_voice_1600251_5 = "Kedamaian akan terus menghindariku selamanya. Ini kutukan tanpa akhir dan karnaval orang-orang yang kesepian…",
  str_voice_1600251_6 = "Fokus! Ini pertunjukanku yang paling akbar! Charon, Other End, dan jutaan jiwa yang haus akan pertunjukan penuh semangat telah kembali dari neraka!",
  str_voice_1600251_7 = "Silakan tunggu sebentar… Ini teh dan camilan kalian. Hadirin yang terhormat, silakan kembali ke tempat duduk kalian!",
  str_voice_1600251_8 = "Kau terbang sendiri begitu cepat dan begitu jauh. Kenapa kau tidak mengajakku? Kau tahu aku selalu siap menemanimu tak peduli siapa kau dan apa pekerjaanmu…",
  str_voice_1600251_9 = "Masa yang kulalui bersama Grand Marshal adalah masa paling bahagia dalam hidupku dan aku merasa aku sudah ditebus… Dan sekarang, karena aku sudah bertemu denganmu, takdirku pun kini sudah lengkap!",
  str_voice_1600251_10 = "\"Mereka yang sudah sampai di ujung takdir! Berjuanglah! Berteriaklah! Wajah kalian, yang kalut karena takut, akan menjadi…\" Hmm, bagian ini agak aneh.",
  str_voice_1600251_11 = "Sibakkan tirai malam kelam dengan penuh harap, dan aku akan menuntunmu menuju cahaya. Bolehkah aku berdiri di sini selamanya?",
  str_voice_1600251_12 = "Aku hanya butuh Other End. Teman-temanku yang lain… tanpa mereka pun, aku bisa.",
  str_voice_1600251_13 = "Orang-orang akan selalu meninggalkanku dengan berbagai alasan, turun dari keretaku saat mereka sudah sampai di tujuan…",
  str_voice_1600251_14 = "Other End sepertinya sangat menyukaimu. Kalau begitu, akan kusiapkan tempat khusus untukmu di panggung!",
  str_voice_1600251_15 = "Ini pembukaan akbar pertunjukanku, dan kaulah tokoh utamanya! Jangan malu-malu, berjogetlah! Haha!",
  str_voice_1600251_16 = "Wraith Train, siap melayanimu.",
  str_voice_1600251_17 = "Sungguh? Kau bangun sangat dini hanya untuk menyiapkan panggung megah ini khusus untukku?",
  str_voice_1600251_18 = "Kita beralih ke panggung berikutnya! Ayo! Bergabunglah dengan kami!",
  str_voice_1600251_19 = "Kau datang tepat waktu, Wraith Train sudah hampir berangkat. Naiklah kalau kau ingin pergi ke sisi lain!",
  str_voice_1600251_20 = "Takdir kita terikat dengan Illumina. Kita sudah berada di sini dua kali, dan kini tempat ini menjadi rumah kita untuk selamanya.",
  str_voice_1600251_21 = "Cita-cita hanyalah perwujudan dari kesadaran diri kita. Apa yang dipaksakan belum tentu adalah kebenaran.",
  str_voice_1600251_22 = "Jayalah—Illumina!",
  str_voice_1600251_23 = "Kami, yang telah kembali dari neraka, akan menghadapi ketakutan kami.",
  str_voice_1600251_24 = "Aku tak berani mengomentarinya karena aku memang kalah… Namun, kalau soal cara mengoperasikan kereta…",
  str_voice_1600251_25 = "Mampu melihat segala hal dengan jelas dan menempuh perjalanan sendirian tanpa ragu—itulah sifat pemimpin sejati.",
  str_voice_1600251_26 = "Panggung yang sepi, hidup bebas, dan perjalanan kereta rock n' roll. Inilah yang kusukai!",
  str_voice_1600251_27 = "Dalam hidup seorang seniman, tak ada tempat untuk orang sinting yang tak punya selera.",
  str_voice_1600251_28 = "Sama sepertiku dan Other End, Colossus ini juga partnermu, 'kan?",
  str_voice_1600251_29 = "Akulah jurumudi roh-roh jahat dan akhirat. Aku bukan tulang belulang dari neraka atau murid Bright. Aku Charon, dan aku bepergian tanpa gentar di dunia yang bersimbah darah ini.",
  str_voice_1600251_30 = "Tambah kecepatan!",
  str_voice_1600251_31 = "Kita tiba di River Styx.",
  str_voice_1600251_32 = "Kereta ke neraka sudah berangkat!",
  str_voice_1600251_33 = "Ini kereta orang-orang mati! Haha!",
  str_voice_1600251_34 = "Aku tak pernah menyangka akan mendapatkan kesempatan ini…",
  str_voice_1600251_35 = "Dengarkan peluit yang memekakkan telinga!",
  str_voice_1600251_36 = "Maju dengan kecepatan penuh!",
  str_voice_1600251_37 = "Destinasi neraka! Siap berangkat!",
  str_voice_1600251_38 = "Orang-orang mati! Minggir!",
  str_voice_1600251_39 = "Uji daya!",
  str_voice_1600251_40 = "Hellfire Signal!",
  str_voice_1600251_41 = "Arahkan lampu sorotnya kepadaku! Tokoh utama harus jadi pusat perhatian!",
  str_voice_1600251_42 = "Kami berasal dari neraka. Tak mungkin kalah.",
  str_voice_1600251_43 = "Lari! Pegang tanganku!",
  str_voice_1600251_44 = "Apa kau ingin menonton bagian berikutnya dari drama ini? Ayo, beri tahukan apa yang kauinginkan!",
  str_voice_1600251_45 = "Sepertinya terakhir kali aku mendapatkan hadiah adalah seabad lalu…",
  str_voice_1600251_46 = "Oh! Apa ini hadiah dari sahabat sepemikiran?",
  str_voice_1600251_47 = "Saling bertukar hadiah memang sangat mengharukan!",
  str_voice_1600251_48 = "Luar biasa! Ini hadiah dari sahabat baikku!",
  str_voice_1600251_49 = "Memangnya kenapa kalau kau disalahpahami dan dikucilkan oleh teman-teman lama? Hari-hari untuk menikmati anggur tanpa memedulikan orang lain jauh lebih menyenangkan!",
  str_voice_1600251_50 = "Aku tak akan pernah melupakan wajah ibuku di balik jendela… Aku bisa mengamatinya selamanya dan tak sadar bahwa waktu terus berlalu…",
  str_voice_1600251_51 = "Dulu, keluargaku memanjakanku, tapi mereka tak paham bahwa Other End juga kuanggap keluarga. Keputusan yang diambil pada saat sulit itu adalah bukti bahwa takdir menentang kami…",
  str_voice_1600251_52 = "Alchemy—Stars!",
  str_voice_1600251_53 = "Halo, teman-temanku!",
  str_voice_1600251_54 = "Pagi ini indah sekali!",
  str_voice_1600251_55 = "Tolong perhatikan!",
  str_voice_1600251_56 = "Saatnya pertunjukan!",
  str_voice_1600251_57 = "Ini… ini suara Tahun Baru!",
  str_voice_1600261_1 = "Lahir di peti yang terbakar, berkelana di negeri yang kering kerontang. Lihat kaki dan tangan yang patah itu, tiada keadilan, tiada makna.",
  str_voice_1600261_2 = "Aku melihatnya terkubur di bawah peradaban—ya, benda yang ada persis di bawah kakimu itu. Mungkin kau memang punya bakat untuk membersihkan dosa…",
  str_voice_1600261_3 = "Jangan hibur aku, aku tidak sedih. Jangan pura-pura perhatian kepadaku seperti orang-orang itu. Tolong, jangan. Biarkan aku sendirian.",
  str_voice_1600261_4 = "Kulit dan wajahku sudah pulih dan sembuh. Aku adalah bentuk kehidupan yang melawan arus. Akan tetapi, tubuhku yang pernah koyak sudah retak selamanya…",
  str_voice_1600261_5 = "Kiamat menyerangku bagai duri bambu yang menancap di bawah kukuku. Bahkan sekarang pun, rasanya masih membuat dadaku sesak, tapi kini ia mendesak keluar dari dalam…",
  str_voice_1600261_6 = "Ayah, ibu… Walau tubuhku didera luka dan nyeri, kini aku punya alasan untuk terus bertarung… Teruslah mendekapku sampai kita bertemu lagi suatu hari nanti…",
  str_voice_1600261_7 = "Mau dengar cerita lama? Cerita tentang bagaimana aku mati dan masuk ke api penyucian?",
  str_voice_1600261_8 = "Dadaku adalah sumur. Dadaku adalah penjara api yang berkobar selamanya, nyerinya sampai menusuk-nusuk tulang. Apa kau tahu apa yang terpendam di dalamnya? Apa kau ingin merobek dan mengintip ke dalamnya?",
  str_voice_1600261_9 = "Mendekatlah dan bersandar di dadaku. Kau dengar? Itu suara api masa lalu… Sekarang, menjauhlah sebelum kau juga masuk ke api penyucian.",
  str_voice_1600261_10 = "Lagi-lagi aku menjadi sosok tanpa raga. Tidak, mungkin memang hidup harusnya seperti ini. Sama seperti bibi-bibi yang suka tinggal di gua sederhana, mungkin aku memang ditakdirkan untuk meringkuk di atas sini dan berbicara dengan diriku sendiri.",
  str_voice_1600261_11 = "Aku… bukannya aku tak suka tinggal di sini. Tatapanmu tidak seperti orang-orang lain, kau tidak memancarkan aura kemunafikan yang menyengat.",
  str_voice_1600261_12 = "Senang sekali seandainya aku bisa tinggal di dalam gentong selamanya… Aku tak akan mendengar ratapan atau jeritan di luar sana.",
  str_voice_1600261_13 = "Lagi-lagi tugas membosankan… Semoga tak ada yang ditugaskan mengawasiku…",
  str_voice_1600261_14 = "Apa memang ada yang berbicara… atau aku hanya berkhayal mendengar suara?",
  str_voice_1600261_15 = "Jadi, ini hari kau terlahir kembali… Akan sakitkah rasanya? Semoga tidak sakit.",
  str_voice_1600261_16 = "Kau sudah sampai lagi di sini. Kau selalu tepat waktu, tak seperti kematian yang datang tiba-tiba.",
  str_voice_1600261_17 = "Apakah hari baru menyambutku lagi? Untuk apa aku harus mengalami semua ini…",
  str_voice_1600261_18 = "Penjara api ini sekarang sudah agak tenang… Mungkin akan ada suara lebih keras yang datang lagi.",
  str_voice_1600261_19 = "Sudah larut… Yang mengantuk, biarlah tidur. Yang masih terjaga, biarlah terjaga… Dadaku nyeri.",
  str_voice_1600261_20 = "Ini negeri yang terlahir kembali dalam api… Putih, sama seperti dalam kenanganku.",
  str_voice_1600261_21 = "Sebelum segalanya berakhir, aku ingat pernah melihat seseorang berpakaian putih panjang… Saat itu, aku tak sempat berterima kasih…",
  str_voice_1600261_22 = "Demi… White Night.",
  str_voice_1600261_23 = "Yang berasal dari neraka… harus kembali ke neraka.",
  str_voice_1600261_24 = "Aku tidak sengaja membakar gaun bibiku, dan cabang-cabang pohonnya… Dia pasti sangat sedih… Maaf…",
  str_voice_1600261_25 = "Petir dan kilat sambar-menyambar… Namun, tatapan matanya… memberitahuku bahwa semuanya baik-baik saja.",
  str_voice_1600261_26 = "Aku suka… tapi aku tak paham… Senang rasanya seandainya saja aku bisa melamun dan tak perlu memikirkan apa pun.",
  str_voice_1600261_27 = "Aku tak paham… Apa makna eksistensi? Apa… maknanya?",
  str_voice_1600261_28 = "Energi di dalam Colossus dan api pencucian di sini… sangat mirip.",
  str_voice_1600261_29 = "Aku Uriel. Aku menjalani hidup tanpa tujuan. Kau boleh mencoba memberikan tujuan untuk tubuhku, tapi jangan berharap terlalu banyak.",
  str_voice_1600261_30 = "Masih saja berusaha walau sia-sia.",
  str_voice_1600261_31 = "N-nyerinya… Makin tak terkendali…",
  str_voice_1600261_32 = "Ini kekuatan atau kutukan!?",
  str_voice_1600261_33 = "Jangan menatapku seperti itu! Ini neraka!!",
  str_voice_1600261_34 = "Semuanya, menjauhlah dariku.",
  str_voice_1600261_35 = "Kapasitas api penyucian dosa sudah penuh—",
  str_voice_1600261_36 = "Dadaku mau meledak…",
  str_voice_1600261_37 = "Kau akan bertemu ajal lagi…",
  str_voice_1600261_38 = "Memandumu ke neraka baru…",
  str_voice_1600261_39 = "Tersucikanlah—",
  str_voice_1600261_40 = "Ke kehampaan…",
  str_voice_1600261_41 = "Sayangnya, abu pun tak akan tersisa.",
  str_voice_1600261_42 = "Aku iri kepada jiwa-jiwa yang telah terbebaskan ini.",
  str_voice_1600261_43 = "Mungkinkah ada neraka lebih besar yang berisi neraka?",
  str_voice_1600261_44 = "Tidakkah kau takut dengan kekuatan api penyucian? Mengherankan…",
  str_voice_1600261_45 = "… Kenapa kau memberiku ini?",
  str_voice_1600261_46 = "Oh? Tampaknya menarik.",
  str_voice_1600261_47 = "Maaf, ini… Aku tak yakin apa aku menyukainya.",
  str_voice_1600261_48 = "Oh, kurasa… Aku suka ini. Terima kasih.",
  str_voice_1600261_49 = "Aku lahir dalam peti mati yang berkobar dan berkelana di negeri hampa ini. Kini, aku tinggal di sebuah sangkar bernama White Night.",
  str_voice_1600261_50 = "Barangkali, sebenarnya kita semua sudah mati saat perang itu pecah dan segala yang kita lihat sekarang hanyalah khayalan sebelum akhirnya jiwa kita hancur. Kalau begitu, membosankan sekali.",
  str_voice_1600261_51 = "Aku tidak pernah melihat ke belakang karena aku sudah mati satu kali, dua kali—eh, tidak terhitung lagi. Aku sudah menyatu dengan api penyucian, tidak pernah terlalu jauh dari neraka.",
  str_voice_1600261_52 = "Alchemy… Stars.",
  str_voice_1600261_53 = "Hei…",
  str_voice_1600261_54 = "Hei… Apa kau di sana?",
  str_voice_1600261_55 = "Apa… apa kau punya waktu?",
  str_voice_1600261_56 = "Sudah larut, tapi apa kau masih di sini…?",
  str_voice_1600261_57 = "Tahun Barunya… tidak ceria.",
  str_voice_1600271_1 = "Dengar panggilan hatiku? Itu tidak terhindarkan. Aku akan menjaga ikatan ini.",
  str_voice_1600271_2 = "Petir dan kilat itu membuat banyak orang takut dan mereka tak mau mendengarkan kata-kata yang terucap dari balik topengku. Namun, kau berbeda, Navigator.",
  str_voice_1600271_3 = "… Kau tak perlu meragukan kesetiaanku. Sekalipun dulu aku sudah mengkhianati banyak orang, kalau Carleen memutuskan untuk memercayaimu, aku pun tak akan pernah punya niat untuk mengkhianatimu.",
  str_voice_1600271_4 = "Aku ingat sesuatu dari masa lalu, tapi bukan kisah-kisah seperti Michael. Sekarang juga bukan saat yang tepat untuk mengobrol.",
  str_voice_1600271_5 = "Petir bergemuruh makin keras, menggema di kepala dan tubuhku. Namun, jalan di depanku sana tampak lebih jelas dan aku tak akan ragu lagi seperti sebelumnya.",
  str_voice_1600271_6 = "Aku akan menggunakan kekuatanku untuk menjaga keteraturan dan mengubah dunia dengan aturan—inilah yang penting untuk saat ini dan masa mendatang. Aku bersyukur karena kau telah menemaniku menempuh perjalanan ini hingga kini. Terima kasih.",
  str_voice_1600271_7 = "Aku paham, tak mudah membangun ikatan dengan orang yang tak bisa bicara. Akan kuhargai itu.",
  str_voice_1600271_8 = "Terima kasih atas kegigihanmu, Navigator. Maafkan aku kalau suara hatiku sering kali ragu. Ini semata akibat munculnya kenangan dari masa lalu.",
  str_voice_1600271_9 = "Aku tak sabar untuk berinteraksi lebih banyak, tapi mungkin aku tak bisa melakukannya dalam wujudku saat ini… Aku sudah sangat beruntung karena kau bisa mendengar suara bisuku, jadi tak seharusnya aku meminta lebih banyak.",
  str_voice_1600271_10 = "Apa perlu kubantu dia agar lebih ceria… Oh, maaf, aku lupa kau bisa mendengarku.",
  str_voice_1600271_11 = "Pengawasan, perbaikan, koreksi kesalahan, dan pelaksanaan. Kapan aku bisa mulai bekerja?",
  str_voice_1600271_12 = "Yang bisa mendengar suara ini hanyalah orang-orang yang bernasib sama denganku.",
  str_voice_1600271_13 = "Hmm? Tadi aku sedang meditasi dan tak melihatmu. Maaf.",
  str_voice_1600271_14 = "Memangnya kau tidak takut dekat-dekat denganku? … Atau jangan-jangan kau seperti Raphael dan tak takut tersetrum?",
  str_voice_1600271_15 = "Ini hari penting untukmu, jadi ayo kita rayakan. Kira-kira, kau mau apa?",
  str_voice_1600271_16 = "Selamat siang, Navigator. Ada perintah baru?",
  str_voice_1600271_17 = "Selamat pagi, sudah kulakukan sesuai perintahmu saat kau tidur. Ada perintah baru lagi?",
  str_voice_1600271_18 = "Navigator, jangan khawatir. Aku bersiaga dan siap menerima perintahmu sewaktu-waktu.",
  str_voice_1600271_19 = "Selamat petang, dan jangan khawatir, karena aku selalu bersiaga untuk menerima perintahmu… Aku ingat, harusnya aku bilang selamat malam.",
  str_voice_1600271_20 = "Aku akan tetap setia pada jalanku. Dari sinilah asal kesetiaanku pada Lumopolis.",
  str_voice_1600271_21 = "Aku berterima kasih karena Raphael sudah merawatku dan Illumina sudah membantuku… dalam prosesku untuk terlahir kembali.",
  str_voice_1600271_22 = "Demi White Night.",
  str_voice_1600271_23 = "Ucapkan saja perintahnya, akan kubasmi mereka semua.",
  str_voice_1600271_24 = "Sepertinya dia tak mendengarku, tapi saat itu apinya yang tanpa raga memang menghilang.",
  str_voice_1600271_25 = "Dia adalah orang Illumina yang mengejar kekuatan. Perasaan ini… familier—mungkin itulah kata yang pas untuk menggambarkannya.",
  str_voice_1600271_26 = "Kalau aku suka sesuatu, berarti hal itu menarik bagiku.",
  str_voice_1600271_27 = "Aku sudah meninggalkan segala hal yang tak kusukai. Aku tak akan pernah menengok ke belakang.",
  str_voice_1600271_28 = "Navigator, Colossus ini ibarat raksasa. Jangan mendaratkannya di sembarang tempat sesukamu.",
  str_voice_1600271_29 = "Aku Michael, penguasa petir dan kilat. Entah kau tadi dengar atau tidak, cukup begitu saja perkenalan diriku. Saatnya mulai bekerja.",
  str_voice_1600271_30 = "Ada yang berbeda dari diriku.",
  str_voice_1600271_31 = "Aku tak perlu merisaukan hal-hal yang tak penting.",
  str_voice_1600271_32 = "Petirku makin lemah.",
  str_voice_1600271_33 = "Takutlah di hadapan Michael!",
  str_voice_1600271_34 = "Akan kuakhiri dengan cepat.",
  str_voice_1600271_35 = "Petir dan kilatku sudah siap.",
  str_voice_1600271_36 = "Tuntun aku.",
  str_voice_1600271_37 = "Apa kau ingin balapan dengan petir dan kilat?",
  str_voice_1600271_38 = "Biarlah petir yang bergemuruh ini mencabik-cabikmu!",
  str_voice_1600271_39 = "Tak seorang pun bisa lolos.",
  str_voice_1600271_40 = "Dengarkan gemuruh petirnya!",
  str_voice_1600271_41 = "Ada yang bisa menyusulku?",
  str_voice_1600271_42 = "Kemenangan yang sepadan dengan kekuatanku yang mampu menghancurkan.",
  str_voice_1600271_43 = "Apa tubuh ini… tak cukup kuat?",
  str_voice_1600271_44 = "Tak banyak kesempatan untuk berkumpul lagi dengan kawan lama atau bekerja sama lagi dalam satu tim.",
  str_voice_1600271_45 = "…Eh… Yah… Baiklah…",
  str_voice_1600271_46 = "Oh, sepertinya aku suka ini…",
  str_voice_1600271_47 = "Terima kasih sudah memberiku begitu banyak hadiah.",
  str_voice_1600271_48 = "Aku suka ini. Aku suka ini. Aku mau ini. T-terima kasih…",
  str_voice_1600271_49 = "Sejak kecil, aku memang berbeda dari anggota lain dalam keluargaku. Kau mungkin pernah dengar tentang Keluarga Troy, yang merupakan simbol taktik dan pewartaan… Karena itu, aku selalu tampak berbeda.",
  str_voice_1600271_50 = "Aku naik dan memperoleh kekuatanku pada suatu hari yang diguyur hujan—bukan, lebih tepatnya, itu terjadi setelah aku dikelabui dan dikhianati. Namun, aku tak membencinya, aku hanya kecewa dengan kelemahanku sendiri.",
  str_voice_1600271_51 = "Pada akhirnya, dengan mati, aku justru terlahir kembali. Banyak orang membantuku dan aku membalas bantuan mereka dengan tindakanku. Namun, hubungan yang sudah putus tak bisa disambung lagi dan aku hanya bisa terus menempuh jalanku sendiri…",
  str_voice_1600271_52 = "Alchemy Stars.",
  str_voice_1600271_53 = "Apa kau bisa mendengarku?",
  str_voice_1600271_54 = "Selamat pagi. Aku sudah menunggumu.",
  str_voice_1600271_55 = "Selamat siang. Aku punya perintah baru.",
  str_voice_1600271_56 = "Apa kau sudah memutuskan untuk istirahat?",
  str_voice_1600271_57 = "Untuk kalian yang punya ikatan denganku, Selamat Tahun Baru.",
  str_voice_1600281_1 = "Oh, maaf, lagi-lagi aku?! Hah? Hanya salam biasa?",
  str_voice_1600281_2 = "Ahhh, kapan aku akhirnya bisa menjadi pendukung yang dipercaya semua orang tanpa syarat, ya? …Mungkin besok?!",
  str_voice_1600281_3 = "Kau mau tahu aku sedang apa? Oh, tidak penting, hanya beberapa cangkang air suci… Namun, aku tidak cukup yakin apakah khasiatnya menyembuhkan atau membuat sakit.",
  str_voice_1600281_4 = "Lihat obat baru yang berhasil kubuat! Pasti akan berguna kali ini, hah! Aku menamainya Almighty Supreme Healing Shell!",
  str_voice_1600281_5 = "Carleeeen… Di mana kau…? Kau belum memberiku tugas apa pun hari ini! Kenapa kau terus-menerus lupa, sih?!",
  str_voice_1600281_6 = "Ooh… Ini semua surat ucapan terima kasih dari orang-orang yang pernah kusembuhkan! Aku hanya mengumpulkan sebagian kecil saja selama bertahun-tahun ini, tapi aku tetap saja merasa terharu setiap kali membacanya…",
  str_voice_1600281_7 = "Eh, boleh aku minta tolong, Raphael? Jadilah sukarelawan untuk percobaan klinisku! Hoi, kenapa kau mundur?",
  str_voice_1600281_8 = "Hei… Ini lengan yang tak sengaja kupatahkan dari salah seorang pasienku dulu… Maukah kau membantuku mengembalikannya? Hihi…",
  str_voice_1600281_9 = "Apa di sini ada yang butuh perawatan medis?! Siapa? Di mana?! Raphael dan Savior #5, siap beraksi! Sekarang kalian semua aman! Sepertinya begitu, ya?",
  str_voice_1600281_10 = "Hari ini aku senggang lagi. Aku sangat penting bagi semua orang, jadi aku tak boleh mengecewakan mereka… Mungkin sebaiknya aku membakar Midnight Oil dan menyiapkan barang baru lagi.",
  str_voice_1600281_11 = "Serahkan padaku! Kurasa aku bisa menanganinya! Tidak, aku pasti bisa! Senyum kerja St. John—diaktifkan!",
  str_voice_1600281_12 = "Ada yang mencariku? Kaukah orangnya? APA KAU TERLUKA?",
  str_voice_1600281_13 = "Kalian semua sangat baik! Selalu bilang bahwa aku perlu istirahat lebih banyak…",
  str_voice_1600281_14 = "Taring-taringku bertumbuh besar… Kenapa… oh, kenapa hanya gigiku yang bertumbuh?",
  str_voice_1600281_15 = "Selamat ulang tahun! Aku sudah menyiapkan 108 Holy Water Shell, khusus untukmu! Semoga hari-harimu dipenuhi sukacita!",
  str_voice_1600281_16 = "Oh, kau sudah kembali!",
  str_voice_1600281_17 = "Selamat pagi! Hari ini aku sangat bersemangat. Lho, memangnya kau tidak bersemangat? Sini, biar kubantu!",
  str_voice_1600281_18 = "Tak apa! Aku masih bisa menerima pasien lagi! Mungkin kau? Apa kau perlu disembuhkan?",
  str_voice_1600281_19 = "Kau harus tidur lelap saat malam agar tetap bersemangat! Apa tidurmu nyenyak? Biar kubantu!",
  str_voice_1600281_20 = "Lumopolis sangat keren! Aku diterima di sini saat aku tak tahu harus pergi ke mana. Lagi pula, mereka mendukung penelitianku!",
  str_voice_1600281_21 = "Illumina juga keren! Semasa masih bersekolah di sana, aku suka bermain misil dengan semua orang!",
  str_voice_1600281_22 = "Demi White Night!",
  str_voice_1600281_23 = "Sayangnya, mereka tak bisa diselamatkan… Satu-satunya pilihan adalah membasmi mereka.",
  str_voice_1600281_24 = "Kuharap saat itu aku bisa bersamanya, walau Gabriel terus bilang bahwa dia tak peduli. Namun, tetap saja…!",
  str_voice_1600281_25 = "Akhir-akhir ini si kecil Michaela tampak lebih baik… Awalnya, dia benar-benar membuat semua orang takut.",
  str_voice_1600281_26 = "Akan kulanjutkan penelitian medisku. Akan kuteruskan eksplorasi dan eksperimenku agar suatu hari nanti aku bisa menyembuhkan semua orang!",
  str_voice_1600281_27 = "Pasien-pasien itu tak bisa diselamatkan… Hal paling menjengkelkan adalah saat aku tak mampu menyelamatkan pasien…",
  str_voice_1600281_28 = "Oh, dulu aku pernah lihat Colossus! Colossus putih milikmu ini tampak hebat!",
  str_voice_1600281_29 = "Aku Raphael! Aku akan membantumu sebisaku. Senang bertemu denganmu!",
  str_voice_1600281_30 = "Oh, ho, ho, ho!",
  str_voice_1600281_31 = "Terima kasih! Kau memang sungguh bijak!",
  str_voice_1600281_32 = "Nah, ini versi Raphael yang lebih baik!!",
  str_voice_1600281_33 = "Aku akan berusaha sebaik mungkin untuk menghormati John!!",
  str_voice_1600281_34 = "Hai, semuanya! Aku di sini!",
  str_voice_1600281_35 = "Tunggu aku! Sebentar!",
  str_voice_1600281_36 = "Eh… Oke! Sepertinya, sih!",
  str_voice_1600281_37 = "Meluncurkan semua misil! Aku tak bercanda!!",
  str_voice_1600281_38 = "Menembakkan Holy Water Shell!",
  str_voice_1600281_39 = "Wuu-huu!!",
  str_voice_1600281_40 = "Holy Water di mana-mana!",
  str_voice_1600281_41 = "Raphael menjalankan misi penting ini dengan tenang!",
  str_voice_1600281_42 = "Selama ada aku di sini, tak akan ada yang cedera! Yeah!",
  str_voice_1600281_43 = "Maaf, biar kucoba lagi! Sekali lagi saja! Boleh, yaaa!!",
  str_voice_1600281_44 = "Semoga tidak ada lagi yang mengeluh! Maaf atas semua masalah yang sudah kutimbulkan…",
  str_voice_1600281_45 = "Oh, jadi aku juga boleh menerima hadiah?",
  str_voice_1600281_46 = "Oh, menarik sekali! Terima kasih!",
  str_voice_1600281_47 = "Terima kasih banyak! Aku sangat senang!",
  str_voice_1600281_48 = "Ini…? Bolehkah aku menerimanya? Waow…",
  str_voice_1600281_49 = "Hidup sangat sulit dulu, terutama saat berkelana dengan master… Oh, maafkan aku! Aku tidak boleh menceritakan hal seperti itu kepadamu!",
  str_voice_1600281_50 = "Pernah kau dengar tentang keluarga John? Sangat terkenal. Kalau bukan karena kami, aku tidak tahu berapa banyak orang yang mati… Hah? Belum pernah dengar?!",
  str_voice_1600281_51 = "Master, aku sudah dewasa. Aku sudah bertemu banyak orang baik dan sekarang aku juga bisa menyembuhkan orang. Kini, lihatlah aku baik-baik dari atas sana…",
  str_voice_1600281_52 = "Alchemy Stars!",
  str_voice_1600281_53 = "Kau baik-baik saja?",
  str_voice_1600281_54 = "Apa kau masih terjaga?",
  str_voice_1600281_55 = "Cepat! Lihatlah!",
  str_voice_1600281_56 = "Bangun! Jangan tidur dulu!",
  str_voice_1600281_57 = "Wuu-huu! Selamat Tahun Baru!",
  str_voice_1600381_1 = "Reruntuhan area pengujian mengingatkanku akan betapa luar biasa temuan-temuan masa lalu. Aku memang pernah membuat kesalahan, tapi kegagalan adalah keberhasilan yang tertunda, 'kan?",
  str_voice_1600381_2 = "Tragedi di dunia ini sama sekali bukan urusanku. Aku pun tak mau pura-pura bersimpati. Illumina ternyata lumayan seru, 'kan?",
  str_voice_1600381_3 = "Kendaraanku adalah relik dari masa lalu, kendaraan yang hanya bisa dibangun kalau kita tak memusingkan soal proses dan biaya. Aku sungguh beruntung!",
  str_voice_1600381_4 = "Aku tidak terikat oleh peraturan! Aku mempertaruhkan hidup sebagai peneliti dan akan menemukan jawabannya!",
  str_voice_1600381_5 = "Apa kau mau menghitung kemenanganku? Tahu tidak, apa pun permainannya, skorku selalu paling tinggi.",
  str_voice_1600381_6 = "Throne adalah peninggalan zaman kuno, dan hanya mereka yang \"pertama memahami\" rahasia yang dikandungnya yang berhak menggunakannya.",
  str_voice_1600381_7 = "Kewajibanku adalah menyelesaikan pekerjaan, dan hal lain apa pun bukan urusanku, 'kan? Semua orang 'kan punya tugas sendiri-sendiri yang harus diselesaikan.",
  str_voice_1600381_8 = "Kawah raksasa di dunia ini memang menakjubkan. Kuharap aku punya waktu untuk ke sana dan melihatnya, tapi sepertinya tempat itu sudah dikuasai sekelompok gelandangan.",
  str_voice_1600381_9 = "Kita semua adalah anak-anak yang ditelantarkan peradaban… Kau benar-benar tak tahu apa pun tentang masa itu? Oh, baiklah, tidak mengherankan sih. Lagi pula, memang tak ada catatan apa pun tentang hal-hal itu yang bisa dibaca publik.",
  str_voice_1600381_10 = "Kavaleri tangguh, taktik tanpa cela, kekuatan militer sejati! Kita akan bertarung di pantai… Ckck, lagi-lagi aku kembali ke kebiasaan burukku. Aku harus ingat umurku!",
  str_voice_1600381_11 = "Sebagai peneliti, kau harus lebih cermat, luar dalam. Dengan begitu, mungkin kau akan punya perspektif berbeda.",
  str_voice_1600381_12 = "Game di sini juga lumayan bagus, misalnya mengoperasikan Colossus ini… Apa? Ini bukan game?",
  str_voice_1600381_13 = "Menakjubkan sekali bahwa, dengan pikiran jernih, kita bisa membuat dunia luar terasa asing sekaligus baru lagi.",
  str_voice_1600381_14 = "Salah satu Dungeon di \"World\" sudah diperbarui. Mau ambil tantangan ini?",
  str_voice_1600381_15 = "Ini tiketmu untuk mengikuti Emperor's Cup! Kalahkan aku, takhtaku jadi milikmu!",
  str_voice_1600381_16 = "Lihat, siapa ini—si pecundang!",
  str_voice_1600381_17 = "Berhenti bicara dan ayo suit! Ha, kau kalah!",
  str_voice_1600381_18 = "Jadi, apa sudah kauputuskan bagaimana kau akan menantangku, pecundang?",
  str_voice_1600381_19 = "Tersenyumlah. Bagi seorang peneliti, permainannya baru saja dimulai!",
  str_voice_1600381_20 = "Illumina adalah surga bagi para peneliti. Kami akan mengembangkan barang-barang yang lebih keren lagi. Lihat saja.",
  str_voice_1600381_21 = "Si Raphael yang diutus oleh Lumopolis itu memang peneliti yang lumayan bagus, tapi dia masih sangat jauh dari standarku.",
  str_voice_1600381_22 = "Jayalah Illumina!",
  str_voice_1600381_23 = "Penelitian ekstensif tentang mereka dihentikan untuk sementara ini… Lain kali, aku akan lebih hati-hati.",
  str_voice_1600381_24 = "Grand Marshal yang sekarang adalah yang terbaik. Terkadang aku merasa dia seperti bos dalam game.",
  str_voice_1600381_25 = "Pecundang! Untuk orang semuda dirinya, bualannya hebat juga. Dalam hal kemampuan mengoperasikan mesin, dia bukan tandinganku.",
  str_voice_1600381_26 = "Apa yang kusukai? Game, penelitian, mesin tua, dan takhta jawara.",
  str_voice_1600381_27 = "Aku yakin, tanpa game, dunia ini akan sangat tak menyenangkan!",
  str_voice_1600381_28 = "Teknologi mekanis, bioteknologi, teknologi Aurorian… Mungkin saja Colossus adalah ciptaan yang sempurna.",
  str_voice_1600381_29 = "Auramu mirip denganku. Apa kita pernah bertemu? Atau, apa kau pernah ikut serta dalam Emperor's Cup? Kalau begitu, kau pasti tahu siapa aku!",
  str_voice_1600381_30 = "Selesai! Fiuh!",
  str_voice_1600381_31 = "Kekuatan agung Zaman Ketakutan telah bangkit!",
  str_voice_1600381_32 = "Tak ada yang bisa menggusurku dari takhta ini!",
  str_voice_1600381_33 = "Menyesal melawanku!",
  str_voice_1600381_34 = "Selisih skor antara peringkat pertama dan kedua sangat besar!",
  str_voice_1600381_35 = "Biarkan aku senang-senang sedikit!",
  str_voice_1600381_36 = "Rekor baru akan segera dicetak!",
  str_voice_1600381_37 = "Permainan dimulai!",
  str_voice_1600381_38 = "Mau mengetuk dan mencobanya?",
  str_voice_1600381_39 = "Megashock!",
  str_voice_1600381_40 = "Mecha Skill!",
  str_voice_1600381_41 = "Game dimulai! Aku bersama Illumina!",
  str_voice_1600381_42 = "Seru sekali! Ayo, lagi, lagi!",
  str_voice_1600381_43 = "Memangnya ada aturan seperti itu? Sial…",
  str_voice_1600381_44 = "Apa akhirnya kau sudah mengambil keputusan? Bolehkah aku bermain dengan Colossus milikmu?",
  str_voice_1600381_45 = "Coba kutebak. Ini game baru atau Enhancement Card?",
  str_voice_1600381_46 = "Belum pernah kulihat hal yang begitu menarik di Illumina!",
  str_voice_1600381_47 = "Coba kutebak. Kau berhasil menyusun gameplay baru?",
  str_voice_1600381_48 = "Kau memang tahu aku suka main apa!",
  str_voice_1600381_49 = "Kekuatan ini sepertinya gagal melindungi zaman yang menciptakannya. Karena kini aku sudah menemukannya kembali, bisakah ini melindungi zaman kita?",
  str_voice_1600381_50 = "Suatu hari nanti, mungkin zaman ini pun akan runtuh seperti kerajaan-kerajaan kuno itu, tapi permainan ini akan tetap berlanjut sampai pemenangnya ditentukan.",
  str_voice_1600381_51 = "Ingatanku tentang eksperimen itu masih utuh, tapi aku tak mau membagikan pengetahuan tak berguna ini denganmu. Dari raut wajahmu yang bingung itu, aku tahu kau masih belum berpengalaman.",
  str_voice_1600381_52 = "Alchemy Stars!",
  str_voice_1600381_53 = "Ayo!",
  str_voice_1600381_54 = "Ayo! Game-nya sudah dimulai!",
  str_voice_1600381_55 = "Tepat waktu. Ayo bertempur!",
  str_voice_1600381_56 = "Jangan mengantuk!",
  str_voice_1600381_57 = "Satu tahun sudah selesai, ini tahun berikutnya!",
  str_voice_1600601_1 = "Jangan malu-malu, kemarilah dan ucapkan salam. Kami punya hulu ledak, magasin, selongsong peluru, oh, ini lengan robotik seri \"Doom\"! Hasil rancangan Divisi Teknis Rediesel Wrench. Cara membuatnya? Yah, tanyakan saja kepada Tiny One.",
  str_voice_1600601_2 = "Tak ada orang yang akan menolak uang, Nak. Ini hanya pekerjaan, dan demi kemanusiaan, aku lebih suka mengakhiri hidup orang dengan cepat. Dengan begitu, mereka tak perlu menderita berkepanjangan.",
  str_voice_1600601_3 = "Prinsipku? Membantu kaum yang lemah dan wanita, terutama anak-anak. Aku takkan pernah membidikkan senapanku kepada mereka.",
  str_voice_1600601_4 = "Baiklah, sudah saatnya sarung tangan ini dilepas—Hah! Aku hanya bercanda. Aku tak akan melepaskan borgolku. Ini favoritku.",
  str_voice_1600601_5 = "Hati-hati, Nak. Peluruku cukup cepat untuk mengirimkan orang ke kubur mereka.",
  str_voice_1600601_6 = "Baiklah! Saatnya menghajar orang. Aku bisa bilang begitu karena aku sudah berpengalaman, Nak.",
  str_voice_1600601_7 = "Aku tak suka bertarung… tapi kadang kita memang tak punya pilihan. Ckck, jangan memaksaku menyisakan satu peluru untukmu, Nak.",
  str_voice_1600601_8 = "Sebelum mati, aku ingin minum sampai mabuk dan tumbang di jalanan. Lalu, ada orang lewat dan DOR, menembakku tanpa pikir panjang, satu tembakan persis ke jantungku.",
  str_voice_1600601_9 = "Biasanya aku tak suka mencampuri urusan orang lain, tapi kau ini istimewa. Apa pun yang terjadi padamu, jangan terlalu dipikirkan. Waktu akan membuat segalanya jadi lebih mudah.",
  str_voice_1600601_10 = "Santailah—kau harus menikmati waktu luangmu sebagaimana mestinya. Urusan pekerjaanmu bisa kaupikirkan belakangan.",
  str_voice_1600601_11 = "Kalau kau mau membayar banyak—ehem, ya, akan kulakukan.",
  str_voice_1600601_12 = "Dor! Apa aku menakutimu? Haha!",
  str_voice_1600601_13 = "Demi kesopanan, sepertinya aku harus menjabat tanganmu—kau ingin menjabat tangan robotikku yang mana?",
  str_voice_1600601_14 = "Penjahat buronan? Aku sendiri pun tergiur dengan harga yang ditawarkan untuk kepalaku itu.",
  str_voice_1600601_15 = "Hei, Nak, hari ini ulang tahunmu. Menyenangkan, 'kan? Ini hari keberuntungan yang patut dirayakan.",
  str_voice_1600601_16 = "Ayo bergerak, sudah cukup lama aku tak beraksi. Coba imbangi kecepatanku, Nak.",
  str_voice_1600601_17 = "Sarapan panjang dan lezat adalah hal sempurna untuk mengawali hari yang menyenangkan, terutama kalau disertai secangkir teh.",
  str_voice_1600601_18 = "Siapa yang membuat kegaduhan itu?! Kenapa sih pencinta musik selalu aktif di jam-jam seperti ini?",
  str_voice_1600601_19 = "Kau mau minum? Pakai es, ditambahi garam, atau cukup sekotak jus saja untuk bocah ini?",
  str_voice_1600601_20 = "Rediesel Wrench adalah tempat pembuangan sampah yang berisi sekumpulan orang sinting dan berandalan. Tentu saja, aku adalah salah satu dari mereka.",
  str_voice_1600601_21 = "Lumopolis memang keren! Mereka suka menghambur-hamburkan warisan dunia kuno. Banyak yang seksi juga di Lumo Knights.",
  str_voice_1600601_22 = "Jalani hidup sebaik mungkin, dan ikuti saja arusnya.",
  str_voice_1600601_23 = "Eclipsite? Makhluk mengenaskan yang hanya bisa hidup dengan Darkflow itu harus segera dibinasakan.",
  str_voice_1600601_24 = "Regina dan Barbara? Oh, ini pilihan sulit, karena aku sama-sama suka musik rock dan gadis cantik.",
  str_voice_1600601_25 = "Brock memang idiot yang hanya punya otot tapi tak punya otak, tapi dia dianggap normal di Rediesel Wrench.",
  str_voice_1600601_26 = "Mengamati dan berjalan-jalan bisa membuat pikiranku tenang. Bagaimana dengan kaum Aurorian? Mereka tak lebih dari sekadar pasir di gurun.",
  str_voice_1600601_27 = "Suasana tegang selalu mengingatkanku akan keringat yang apek. Apa gunanya memforsir dirimu seperti itu?",
  str_voice_1600601_28 = "Ini ciptaan luar biasa. Sediakan saja suatu sudut untuk kujadikan tempat tinggal, dan aku akan terlepas dari kekurangan dan kelaparan.",
  str_voice_1600601_29 = "Jangan bergerak. Kalau tidak, peluru ini akan menembus kepalamu dalam sekejap! Aku hanya bercanda! Aku Jona, penembak biasa yang kebetulan lewat. Ucapkan selamat tinggal pada hal-hal sepele yang menjengkelkan dalam hidup ini. Mari duduk bersama dan berbincang santai.",
  str_voice_1600601_30 = "Tetap rendah hati.",
  str_voice_1600601_31 = "Satu tembakan, tepat ke targetnya!",
  str_voice_1600601_32 = "Bakatku adalah menembak.",
  str_voice_1600601_33 = "Sini, dengarlah simfoni tembakan senapan ini!",
  str_voice_1600601_34 = "Ayo hajar mereka, kawan-kawan!",
  str_voice_1600601_35 = "Siap tembak.",
  str_voice_1600601_36 = "Bidik.",
  str_voice_1600601_37 = "Makan nih pelurunya!",
  str_voice_1600601_38 = "Adios, amigo.",
  str_voice_1600601_39 = "Hal-hal baik selalu berpasangan.",
  str_voice_1600601_40 = "Tak ada yang selamat.",
  str_voice_1600601_41 = "Siapkan peti mati untuk musuh-musuhku.",
  str_voice_1600601_42 = "Hah, ini bukan apa-apa.",
  str_voice_1600601_43 = "Waspadai tembakan tak terduga.",
  str_voice_1600601_44 = "Aku hampir lupa, masih ada yang harus kukerjakan. Akan kutuntaskan ini dengan cepat.",
  str_voice_1600601_45 = "Oh? …Hmm, ini baru dan cukup menyegarkan.",
  str_voice_1600601_46 = "Terima kasih! Aku akan menghargai ini.",
  str_voice_1600601_47 = "Amunisi, gelas anggur, dan hadiahmu.",
  str_voice_1600601_48 = "Barter yang sepadan. Hadiah ini bernilai setara dengan segelas minuman dingin!",
  str_voice_1600601_49 = "Hidup? Aku tak punya ekspektasi tertentu dalam hidup… Esok hari sama saja dengan hari-hari lainnya. Aku tak peduli aku berada di mana, asalkan aku bisa makan.",
  str_voice_1600601_50 = "Hidup seorang penembak berakhir dalam duel. Jelas, senapanku selalu lebih cepat. Aku sendiri yang mengubur mentorku dan menghiasi tanah kuburnya dengan selongsong peluru.",
  str_voice_1600601_51 = "Selama ini aku selalu membiarkan nasib membawaku sesukanya dan aku menurut saja ke mana pun ia membawaku. Kalau aku harus bilang hal baik tentangnya, setidaknya aku merasakan kenyamanan hidup tertinggi di Rediesel Wrench.",
  str_voice_1600601_52 = "Alchemy Stars.",
  str_voice_1600601_53 = "Pemandu.",
  str_voice_1600601_54 = "Oh, selamat pagi.",
  str_voice_1600601_55 = "Kemarilah—saatnya beraksi.",
  str_voice_1600601_56 = "Mencicitlah agar aku tahu kau masih hidup.",
  str_voice_1600601_57 = "Duduklah. Sekarang Tahun Baru.",
  str_voice_1600771_1 = "Aku belum pernah lihat Colossus sesempurna ini. Sepertinya… takdir telah berbicara.",
  str_voice_1600771_2 = "Sejak Colossus melejit ke angkasa dan memandang makhluk hidup dari atas sana, aku tahu dunia ini sudah berubah.",
  str_voice_1600771_3 = "Takdir telah menghadirkan banyak rekan untukmu. Kau akan tetap aman sampai akhirnya takdir meninggalkanmu. Sementara ini, tak perlu khawatir.",
  str_voice_1600771_4 = "Di masa depan, aku melihat White Night terus meredup. Semoga aku salah.",
  str_voice_1600771_5 = "Ingat - Aurora adalah senjata pamungkas yang akan menghalau ancaman terbesar bagi kita.",
  str_voice_1600771_6 = "Northland adalah kawanku… dan kawanmu pula. Setelah musim dingin berakhir, musim semi akan hadir.",
  str_voice_1600771_7 = "Sepertinya sekarang kau sedang senggang. Maukah kau menceritakan masa lalumu kepadaku? Bagaimana caramu menemukan Colossus ini?",
  str_voice_1600771_8 = "Kediamanku di Northland disebut Winter Palace. Sebuah istana yang dibangun di puncak gunung. Pemandangan di sana sungguh memesona.",
  str_voice_1600771_9 = "Mungkin saja kaulah orang yang selama ini kunanti, orang yang mungkin bisa menciptakan masa depan bagi benua ini.",
  str_voice_1600771_10 = "Sebagai Northlord, aku tidak punya banyak waktu santai. Ini mengingatkanku akan sofa panjang di Winter Palace.",
  str_voice_1600771_11 = "Sementara kau mengejar takdirmu, aku bisa mengurus Colossus ini untukmu.",
  str_voice_1600771_12 = "Situasi saat ini sangat berbeda dari saat aku masih tinggal di Northland. Untungnya, aku masih bisa mengatasinya dengan mudah.",
  str_voice_1600771_13 = "Colossus ini mungkin bukan satu-satunya di dunia ini. Dia tidak sendiri, dan tidak pula… kau.",
  str_voice_1600771_14 = "Kadang… aku bisa mendengar Colossus itu berbicara. Sepertinya ia juga ingin mengungkapkan keinginannya.",
  str_voice_1600771_15 = "Aku tak ingat ulang tahunku sendiri… tapi aku tetap ingin mengucapkan selamat ulang tahun untukmu.",
  str_voice_1600771_16 = "Hari yang tenang, seperti hari-hari biasanya di Northland.",
  str_voice_1600771_17 = "Kemarilah, berjemur di bawah matahari bersamaku.",
  str_voice_1600771_18 = "Istirahat berkala akan membuatmu siap menyongsong masa depan. Minumlah secangkir teh dan istirahatlah.",
  str_voice_1600771_19 = "Aku sudah terbiasa bergadang. Memang inilah pengorbanan sebagai Queen of the North. Kau harus istirahat.",
  str_voice_1600771_20 = "Kami telah membekukan takdir kami di pegunungan tanpa akar. Mungkin saja, perubahan akan segera terjadi…",
  str_voice_1600771_21 = "Lumopolis tampak seperti Northland, tapi tanpa salju. Konservatisme adalah gunung salju mereka. Akan celaka jadinya kalau sampai ada longsoran salju.",
  str_voice_1600771_22 = "Demi Utara.",
  str_voice_1600771_23 = "Siapakah sosok yang disebut bunda oleh para Eclipsite itu?",
  str_voice_1600771_24 = "Ada alasan yang membuat sikap Nikinis sangat dingin. Kau tak tahu apa saja yang telah dilaluinya.",
  str_voice_1600771_25 = "Walau dia seorang bangsawan, Carleen tidak arogan. Dia terlahir untuk Lumopolis yang sejati.",
  str_voice_1600771_26 = "Teh dari selatan, sinar matahari saat musim dingin. Seandainya saja dunia terus seperti ini, mungkin aku pun akan bisa menikmatinya.",
  str_voice_1600771_27 = "Kecurigaan selalu menjadi musuh kita. Dibandingkan dengannya, Eclipsite sekalipun bukan apa-apa.",
  str_voice_1600771_28 = "Objek ini berasal dari masa lalu, tapi penuh dengan teknologi canggih. Pasti ada banyak rahasia yang terpendam…",
  str_voice_1600771_29 = "Akulah Northlord. Jangan terkejut. Takdir telah menuntunku ke Colossus ini agar kita bisa berjumpa.",
  str_voice_1600771_30 = "Kekuatan sejati… muncul.",
  str_voice_1600771_31 = "Es adalah pelindungku.",
  str_voice_1600771_32 = "Es juga adalah Blade of Aurora.",
  str_voice_1600771_33 = "Es Northland adalah sahabat kami.",
  str_voice_1600771_34 = "Hadapilah dengan tenang.",
  str_voice_1600771_35 = "Aurora, dikuasai…",
  str_voice_1600771_36 = "Kekuatan hawa dingin ekstrem!",
  str_voice_1600771_37 = "Ini akan berakhir saat es mencair.",
  str_voice_1600771_38 = "Yang harus terjadi, akan terjadi.",
  str_voice_1600771_39 = "Blade of Aurora.",
  str_voice_1600771_40 = "Penghakiman akhir.",
  str_voice_1600771_41 = "Ayo songsong kemenangan.",
  str_voice_1600771_42 = "Satu kemenangan lagi.",
  str_voice_1600771_43 = "Kemunduran memang kadang terjadi, tak perlu dirisaukan.",
  str_voice_1600771_44 = "Perjalananmu masih panjang. Jangan menyerah.",
  str_voice_1600771_45 = "Terima kasih, tapi mestinya kau tak perlu terlalu memikirkannya.",
  str_voice_1600771_46 = "Oh, aku memang menginginkan ini. Terima kasih.",
  str_voice_1600771_47 = "Kau sungguh memikirkannya dalam-dalam. Terima kasih.",
  str_voice_1600771_48 = "Sepertinya memang kaulah orang yang telah kupilih…",
  str_voice_1600771_49 = "Adat sopan santun di Northland adalah yang paling kuno. Duta dari negeri-negeri jauh pasti kesulitan membiasakan diri dengannya.",
  str_voice_1600771_50 = "Agar bisa menang dalam pertempuran jauh di sana, komandan harus menyusun rencana strategis. Kita harus mengandalkan kebijaksanaan karena hanya dengan itulah kita bisa mengalahkan Eclipsite.",
  str_voice_1600771_51 = "Aku memang tidak tahu segala hal dan tidak pula hebat luar biasa, tapi aku berusaha sebaik mungkin untuk melindungi rakyatku. Aku selalu berusaha dan akan selalu berusaha. Tekad kita harus teguh saat menghadapi ancaman terbesar.",
  str_voice_1600771_52 = "Alchemy Stars.",
  str_voice_1600771_53 = "Yang penuh tekad.",
  str_voice_1600771_54 = "Angin kebangkitan berembus.",
  str_voice_1600771_55 = "Jawablah aku, orang yang telah kunanti-nanti.",
  str_voice_1600771_56 = "Tidak perlu takut akan malam kelam selama ada aku di sini.",
  str_voice_1600771_57 = "Siklus musim telah genap.",
  str_voice_1600891_1 = "Bertanggung jawab berarti orang-orang yang memegang jabatan tinggi harus maju untuk melindungi rakyat. Mereka harus lebih tegas terhadap diri sendiri dan memiliki kekuatan yang sepadan dengan jabatan mereka.",
  str_voice_1600891_2 = "Aku punya jalan sendiri, aku tak akan jadi seperti dia. Musuhnya hanyalah musuh masyarakat dan hukum adalah satu-satunya keluarganya.",
  str_voice_1600891_3 = "Apakah aku tergoyahkan oleh suara-suara orang mati itu? Namun, setiap langkah yang kuambil sekarang mencerminkan tekadku dan didasarkan pada realita.",
  str_voice_1600891_4 = "Aku akan berusaha sebaik mungkin untuk merenungkan tindakan dan penyesalanku. Aku akan terus maju dengan hati penuh harapan selagi aku masih bisa merasakan sakit.",
  str_voice_1600891_5 = "Kalau kau bertanya padaku tentang bayangan yang mengambang di permukaan air keemasan itu, aku bisa bilang bahwa itu adalah sesuatu yang menungguku menunjukkan kelemahanku agar bisa menyeretku ke dalam air dan memangsaku.",
  str_voice_1600891_6 = "Aku akan mengubur mereka yang harus dikuburkan. Aku akan mengabaikan hasratku agar tak perlu lagi lari. Aku akan pergi sejauh nasib membawaku, mengikuti arah bintang-bintang fajar.",
  str_voice_1600891_7 = "Menurut hukum sidang, kau punya hak untuk naik banding, asalkan kau punya bukti yang mencukupi… Tenanglah, bukan berarti aku bilang bahwa kau telah melanggar hukum sidang.",
  str_voice_1600891_8 = "Kalau kau bersikukuh ingin membahayakan dirimu, pergilah. Aku tak akan menghentikanmu… tapi izinkan aku ikut denganmu. Akan lebih aman kalau begitu.",
  str_voice_1600891_9 = "Setiap langkah yang kauambil sekarang akan berperan dalam keselamatanmu. Jadi, teruskan saja. Tak usah mengkhawatirkan apa yang ada di depan sana, karena matahari akan terbit di belakangmu.",
  str_voice_1600891_10 = "Apa kau masih di sini? B-bolehkah aku istirahat di sini sebentar? Kurasa aku tak bisa bertahan lebih lama lagi. Aku akan istirahat sebentar saja.",
  str_voice_1600891_11 = "Jangan berharap terlalu banyak dariku karena aku tak punya banyak untuk membantu diriku sendiri. Yang kumiliki hanyalah darah dan dagingku, serta jiwa dan kenanganku.",
  str_voice_1600891_12 = "Aku hanya mau menjalankan kewajiban yang sudah kuketahui. Aku hanya perlu memutuskan apakah aku akan terus melakukannya.",
  str_voice_1600891_13 = "Tongkat ini masih terlalu panjang untukku, tapi akan tetap kupakai sampai rusak.",
  str_voice_1600891_14 = "Kau harus selalu mengingat rumahmu di dalam hatimu dan tetap membuka pikiranmu… Itu yang diajarkan kepadaku, dan aku setuju.",
  str_voice_1600891_15 = "Kelahiran tidak selalu membawa kegembiraan, tapi aku tetap membawakanmu beberapa buah apel. Semoga kau menyukainya.",
  str_voice_1600891_16 = "Kau selalu muncul di suatu tempat di dekatku, bagiku itu cukup perhatian.",
  str_voice_1600891_17 = "Selamat pagi. Aku tadi meramalkan bintang pagi di langit di atas kita hari ini.",
  str_voice_1600891_18 = "Cahaya matahari telah meredup? Akan kuterangi tempat ini… Lelucon dari Chief Judge lucu, 'kan?",
  str_voice_1600891_19 = "Kau tampak lelah. Jangan memaksakan diri untuk bekerja begitu keras kalau kau sudah lelah. Istirahatlah.",
  str_voice_1600891_20 = "Ketertiban terbit bersama dengan matahari agar kita semua bisa bertahan setelah matahari terbenam.",
  str_voice_1600891_21 = "Terlepas dari statusku, aku masih ingin tahu bagaimana kita bisa menentukan apakah kebenaran itu bukan hal yang tak berwujud atau bentuk pelarian?",
  str_voice_1600891_22 = "Demi White Night.",
  str_voice_1600891_23 = "Merasa hampa di dalam hati mungkin semacam anugerah karena dunia benar-benar berbeda begitu kau meraih kesadaranmu sendiri.",
  str_voice_1600891_24 = "Aku mengagumi Uriah karena kekuatan dan kemandiriannya, serta keberaniannya untuk melepaskan segalanya.",
  str_voice_1600891_25 = "Sikap tenang Carleen memberinya lebih banyak pilihan dalam hidup yang berbeda dariku.",
  str_voice_1600891_26 = "Aku memilih Sword of Borrowing sebagai senjataku. Aku sangat menyukainya.",
  str_voice_1600891_27 = "Aku selalu membenci orang-orang yang bersifat egois, arogan, dan angkuh.",
  str_voice_1600891_28 = "Meskipun ini adalah peninggalan masa lalu, benda ini pasti memiliki makna yang lebih berarti bagimu.",
  str_voice_1600891_29 = "Senang bertemu denganmu. Aku Irridon, Chief Judge di Lumopolis. Jika kau memiliki pengakuan yang masuk akal, biarkan mata air dan hutan yang menjawab permintaan-permintaan muncul dalam kilatan guntur yang sunyi.",
  str_voice_1600891_30 = "Aku menerima tekanan ini.",
  str_voice_1600891_31 = "Bungkus sebuah batu dan poles benda itu hingga menjadi mutiara.",
  str_voice_1600891_32 = "Guntur dan kilat akan menyambar dalam kegelapan.",
  str_voice_1600891_33 = "Aku menunggu bintang pagi.",
  str_voice_1600891_34 = "Diam.",
  str_voice_1600891_35 = "Saatnya penghakiman.",
  str_voice_1600891_36 = "Waktumu sudah habis.",
  str_voice_1600891_37 = "Ssst, pembelaanmu tidak beralasan.",
  str_voice_1600891_38 = "Guntur dan kilat akan menjadi tenang dan badai akan menjadi damai.",
  str_voice_1600891_39 = "Cabik!",
  str_voice_1600891_40 = "Ini keputusanku.",
  str_voice_1600891_41 = "T-tunggu! Aku tak bisa berjalan secepat itu.",
  str_voice_1600891_42 = "Ayo beres-beres. Saatnya pergi.",
  str_voice_1600891_43 = "Aku masih bisa lanjut…",
  str_voice_1600891_44 = "Jika waktunya memungkinkan… Hari ini, aku akan menceritakan sebuah kisah tentang hal-hal yang berada di bawah air.",
  str_voice_1600891_45 = "Walau secara pribadi menerima ini, aku masih agak kesulitan.",
  str_voice_1600891_46 = "Terima kasih. Kuterima niat baikmu.",
  str_voice_1600891_47 = "Tidak ada yang akan salah paham tentang hubungan kita.",
  str_voice_1600891_48 = "Terima kasih atas perhatian dan kebaikan hatimu seperti biasa.",
  str_voice_1600891_49 = "Biarkan semua rasa sakit, masalah, kesedihan, dan ratapanku tetap tersembunyi di bawah air. Mereka tidak akan menghalangi tindakanku meski semuanya menyebar.",
  str_voice_1600891_50 = "Aku mengunci diri dengan belenggu yang tak terhindarkan ini. Persis seperti rawa dan hutan emas, dan bayangan yang kutakuti.",
  str_voice_1600891_51 = "Karena kakiku pernah putus, untuk bisa berdiri sekali lagi, aku harus menjahitnya kembali dengan benang petir. Cara ini cukup membantu hingga aku berhasil bertahan.",
  str_voice_1600891_52 = "Alchemy Stars.",
  str_voice_1600891_53 = "Halo.",
  str_voice_1600891_54 = "Selamat pagi.",
  str_voice_1600891_55 = "Apa aku mengganggumu?",
  str_voice_1600891_56 = "Selamat malam, kuharap malam ini bulannya indah.",
  str_voice_1600891_57 = "Tahun baru telah tiba. Semoga kau bahagia.",
  str_voice_1300461_1 = "- Kenapa Colossus terburu-buru?\n- Karena Master Navigator terlambat,\n- Makanan gratisnya keburu dingin♪",
  str_voice_1300461_2 = "- Oh♪\n- Wahai Navigator yang elegan dan menakjubkan♪ - Jangan tundukkan kepalamu♪\n- Bagian botak di kepalamu - Mulai melebar♪",
  str_voice_1300461_3 = [[
- Kau datang kemari untuk bertemu dengan kami lagi. 
- Lagi!
- Lihat betapa santainya kau. 
- Kau pasti masih jomlo! Kau jomlo, ya?]],
  str_voice_1300461_4 = "- Sangat diperhatikan oleh para bangsawan, dijaga baik-baik oleh mereka!\n- Namun, tak bisa melepaskannya, \n- Oh, dasar tak tahu malu, kau sangat tak tahu malu♪",
  str_voice_1300461_5 = "- Oh! - Kalian makhluk kejam, menjijikkan! ♪\n- Musuh tercinta kami… ♪ - Kami akan menginjak-injak kalian bagaikan serangga! ♪",
  str_voice_1300461_6 = "- Mengapa begitu peduli??\n- Mengapa terburu-buru?\n- Kami hanyalah orang yang lewat♪ Pemandu mereka menuju Neraka♪",
  str_voice_1300461_7 = "- Orang-orang Dawn Academy♪ \n- Semuanya tolol♪\n- Namun, para bangsawan Lumopolis♪ \n- Bahkan lebih bodoh dari orang tolol♪",
  str_voice_1300461_8 = "- Makin tinggi kau tumbuh, - Makin bodoh pula kau♪\n- Makin tua kau, makin dungu pula kau♪ \n- Namun, janganlah resah, karena kau masih muda dan pendek♪",
  str_voice_1300461_9 = "- Oh♪\n- Para bangsawan ini membosankan♪ \n- Mereka tak sepertimu♪\n- Sangat lucu dan polos♪ \n- Jangan lupa, bodoh juga♪",
  str_voice_1300461_10 = "- Tempat yang membosankan\n- Penuh dengan bangsawan membosankan,\n- Bagaimana mereka menghabiskan waktu♪ \n- Lebih baik tidur saja♪",
  str_voice_1300461_11 = [[
- Biarkan kami bernyanyi?
- Kau terlalu memikirkannya.
- Luar biasa.]],
  str_voice_1300461_12 = [[
- Belum cukup kau mendengarkannya?
- Kau benar-benar menyukai ini?]],
  str_voice_1300461_13 = "- Jika tak ada yang kau kerjakan♪ \n- Mengapa tidak mencukur kepalamu♪\n- Cukur hingga botak♪ -\n Tidurmu akan terasa lebih sejuk♪",
  str_voice_1300461_14 = [[
- Empat kaki dari jauh.
- Dua kaki dari dekat.
- Apakah kau ini, Master Navigator? 
- Makhluk yang benar-benar berantakan!]],
  str_voice_1300461_15 = "- Sudah saatnya♪\n- Saatnya kami menyalakan lilin untukmu!",
  str_voice_1300461_16 = [[
- Kau lagi!
- Kau kembali lagi!
- Masih segar bugar.]],
  str_voice_1300461_17 = [[
- Makin pagi kau bangun.
- Makin cepat kau botak.
- Mengapa tidak beristirahat lebih lama? 
- Mengapa begitu rajin?]],
  str_voice_1300461_18 = [[
- Kau datang.
- Kau pergi.
- Namun wajahmu.
- Masih sama seperti sebelumnya!]],
  str_voice_1300461_19 = [[
- Apa yang membuatmu terjaga di malam hari?
- Apakah itu kehendak?
- Atau insomnia?]],
  str_voice_1300461_20 = "- Hanya sedikit… \n- Namun tetap saja, kami bangga!\n- Kaki kami menapak di tanah.\n- Dengan angan-angan kami yang tinggi!",
  str_voice_1300461_21 = [[
- Sudahkah mereka melihat Truth?
- Dengan mata mereka yang tertutup?]],
  str_voice_1300461_22 = "Demi White Night♪",
  str_voice_1300461_23 = "- Sampah bertemu sampah♪\n- Kodok di atas kodok♪",
  str_voice_1300461_24 = [[
- Bukankah Carleen sudah memberimu pelajaran?
- Kau belum mengerti juga, ya?
- Pelajaran itu sungguh berguna!]],
  str_voice_1300461_25 = [[
- Teman tersayang kami.
- Yang mengajari kami dengan baik.
- Untuk bersikap lembut dan baik hati.
- Serta untuk mengucapkan selamat tinggal!]],
  str_voice_1300461_26 = [[
- Jangan terlalu sombong,
- Sedikit sadar dirilah.
- Tidak bisakah kau? Tidak maukah kau?]],
  str_voice_1300461_27 = [[
- Mereka orang dewasa yang tak berguna,
- Apa mereka tidak bisa melihat diri sendiri di cermin?
- Apa mereka tidak bisa melihat diri mereka yang sebenarnya?]],
  str_voice_1300461_28 = [[
- Apakah ini Colossus milikmu?
- Sangat tinggi?
- Dan sangat pucat?]],
  str_voice_1300461_29 = [[
- Teman tersayang kami.
- Dari Lumopolis, kami mengucapkan salam.
- Manis bibir kami,
- Begitu pula dengan ucapan kami. 
- Memang nyatanya begitu!]],
  str_voice_1300461_30 = "Kita adalah kapten untuk diri kita sendiri♪",
  str_voice_1300461_31 = "Orang dewasa harus lebih sering disanjung.",
  str_voice_1300461_32 = "Hingga mereka semua lenyap♪",
  str_voice_1300461_33 = [[
- Tembus hingga ke dalam,
- Hancurkan jiwa mereka!]],
  str_voice_1300461_34 = "Ingin kami bergabung di paduan suaramu?",
  str_voice_1300461_35 = "Oh, kau tak bisa menunggu?",
  str_voice_1300461_36 = "Kalau begitu, biarkan kami bernyanyi!",
  str_voice_1300461_37 = "- Oh♪\n- Balada hitam dan putih♪",
  str_voice_1300461_38 = "- Di atas batu nisannya♪\n- Mereka membubung♪",
  str_voice_1300461_39 = "Betapa membosankan♪",
  str_voice_1300461_40 = "Betapa lucunya♪",
  str_voice_1300461_41 = "- Oh,\n- Orang bodoh yang di sana♪\n- Betapa jeleknya kau♪",
  str_voice_1300461_42 = [[
- Kau belum mengerti juga, ya?
- Pelajaran itu sungguh berguna!]],
  str_voice_1300461_43 = [[
- Pulanglah!
- Pulanglah!
- Pulang ke rumah dengan tangan kosong!]],
  str_voice_1300461_44 = [[
- Hujannya sudah berhenti?
- Apakah matahari sudah mengintip dari balik awan?
- Kau bisa berfungsi lagi?]],
  str_voice_1300461_45 = [[
- Hadiah darimu?
- Kalau ini yang kausebut hadiah.]],
  str_voice_1300461_46 = [[
- Ini baru hadiah!
- Ini hadiah!]],
  str_voice_1300461_47 = [[
- Kau memilih hadiah seperti ini?
- Sungguh?]],
  str_voice_1300461_48 = [[
- Kau sudah berusaha keras,
- Kau patut diapresiasi!]],
  str_voice_1300461_49 = "- Para bangsawan♪ \n- Bobrok♪\n- Bodoh♪ \n- Membosankan♪\n- Omong kosong mereka yang tidak ada artinya membuat semua orang mendengkur!",
  str_voice_1300461_50 = [[
- Pertempuran sengit,
- Pertunjukan taktik latih tanding yang kuat.
- Bertarung seperti ayam jantan di medan perang!]],
  str_voice_1300461_51 = [[
- Pierre selalu tersenyum, 
- Dian akan menjadi kesatria yang begitu tangguh,
- Kara adalah pelindung kami, 
- Niel membaca sepanjang hari.
- Masih tidak bisa membedakan kami?]],
  str_voice_1300461_52 = "Alchemy Stars♪",
  str_voice_1300461_53 = "Halo, Master Navigator♪",
  str_voice_1300461_54 = "- Pagi♪\n- Kau sudah bangun?\n- Masih ingin tiduran?",
  str_voice_1300461_55 = "- Sore♪\n- Ada waktu luang?",
  str_voice_1300461_56 = "- Malam♪\n- Lebih baik rawat rambutmu♪",
  str_voice_1300461_57 = "- Selamat Tahun Baru♪\n- Selamat bersenang-senang♪",
  str_voice_1300531_1 = "Oh, sialan. Bos, senyummu menembus jiwaku! Tolong keluarkan dompetmu dan tunjukkan kepada semua orang betapa beruntungnya aku bekerja untukmu, Bos!",
  str_voice_1300531_2 = "Bos tersayang, hewan-hewannya sangat menggemaskan, pasti sepadan dengan uangmu! Aku hanya berharap bisa terlahir sebagai anak anjing Bos di kehidupanku selanjutnya!",
  str_voice_1300531_3 = "Ayo lihat apa yang aku punya dalam ranselku ini! Jika barang-barang ini bukan barang yang kaucari, aku juga bisa menjual waktuku di hari ini untukmu, seharga ini saja, Bos!",
  str_voice_1300531_4 = "Temui aku jika kau butuh sesuatu. Aku bukan lagi seseorang yang tidak berdaya. Baik itu senjata maupun perisai, aku akan selalu menawarkan harga yang wajar!",
  str_voice_1300531_5 = "Seratus Nightium memutar kepalaku, seribu Nightium membuka mulutku, sepuluh ribu Nightium… Oh, aku sangat menyayangimu. Semua dengan harga yang wajar, jangan khawatir.",
  str_voice_1300531_7 = "Bos tersayang, jangan pedulikan aku yang cerewet. Ini karena aku tak bisa menahan cintaku padamu, terutama saat kau membayar!",
  str_voice_1300531_8 = "Bos, kebaikanmu benar-benar membuatku terharu. Semoga aku selalu bisa berada di sisimu, terutama saat Bos ingin membeli, membeli, dan membeli!",
  str_voice_1300531_9 = "Tidak banyak yang bisa kutawarkan kepadamu secara gratis kecuali kesetiaan abadiku. Ini yang bisa kujanjikan!",
  str_voice_1300531_10 = "Waktu adalah uang… Namun, asalkan aku selalu bersama Bosku sayang, aku tahu kau akan mengembalikan uangku!",
  str_voice_1300531_11 = "Bos tersayang, untuk seratus ribu Gold, aku akan menjadi anak anjing kecilmu. Dengan senang hati aku akan menunjukkan padamu kibasan ekorku jika aku bisa!",
  str_voice_1300531_12 = "Bos, biaya layanan, biaya pemesanan, biaya merindukanmu… Saatnya membayar!",
  str_voice_1300531_13 = "Hasil yang bagus lagi! Apa lagi yang harus kujual dan kepada siapa selanjutnya?",
  str_voice_1300531_14 = "Hm? Sepertinya ada sesuatu… apakah hewan kecil? Tidak! Itu masih uang!",
  str_voice_1300531_15 = "Bos tersayang, selamat ulang tahun! Kue, hadiah, dan berkatmu hanya menambah biaya seratus ribu Gold!",
  str_voice_1300531_16 = "Bos! Kau kembali juga! Aku sudah menyusun tagihan dengan benar saat kau pergi!",
  str_voice_1300531_17 = "Pagi, Bos! Hari yang cerah, ya. Silakan lihat tagihan kemarin.",
  str_voice_1300531_18 = "Bos, ingin makan? Camilan? Atau hiburan?",
  str_voice_1300531_19 = "Bos, kenapa kau tidak beristirahat sebentar? Nanti tagihanmu akan bertambah lagi, lho.",
  str_voice_1300531_20 = "Rediesel Wrench sangat terkenal! Pasar yang belum berkembang ini mengisi kantongku setiap hari!",
  str_voice_1300531_21 = "Para pencari kebenaran itu benar-benar tidak memahami gagasan bahwa \"apa yang gratis berharga lebih tinggi\"? Menyedihkan sekali.",
  str_voice_1300531_22 = "Bayar!",
  str_voice_1300531_23 = "Dasar gerombolan oportunis… Apakah mereka tahu kelebihan dari uang?",
  str_voice_1300531_24 = "Karena kemampuan yang baik itu sangat berharga, tentu saja aku memastikan bahwa aku memiliki hubungan yang baik dengannya!",
  str_voice_1300531_25 = "Makhluk bukan hewan yang berpura-pura menjadi hewan dengan kepala hewan? Sulit dipercaya!",
  str_voice_1300531_26 = "Biarkan aku memperkenalkan diriku. Aku suka hewan-hewan lucu, uang, dan hal-hal yang tak ternilai harganya.",
  str_voice_1300531_27 = "Permintaan pertanyaan diterima. Biarkan aku menjawab: Aku benci keserakahan.",
  str_voice_1300531_28 = "Aku bisa tahu dari mata pedagangku bahwa Colossus yang kuat ini meningkatkan derajatmu, dan harganya pasti mahal!",
  str_voice_1300531_29 = "Haha! Bos baru sudah tiba! Bos tersayang, apa yang bisa kubantu? Aku punya semua yang bisa dibeli dengan uang!",
  str_voice_1300531_30 = "Lebih banyak yang didapat!",
  str_voice_1300531_31 = "Tentu saja ini semua untuk Bosku tersayang!",
  str_voice_1300531_32 = "Kemampuan berjualan setara dengan keuntungan.",
  str_voice_1300531_34 = "Atas perintah Bos!",
  str_voice_1300531_35 = "Serangan yang sengit? Segera datang!",
  str_voice_1300531_36 = "Kau sudah menyiapkan uangnya?",
  str_voice_1300531_37 = "Bayar aku Bos, nanti kugigit siapa pun sesuai permintaanmu!",
  str_voice_1300531_38 = "Diskon serangan! Tidak ada pengembalian uang!",
  str_voice_1300531_39 = "Lihat ke sini, Bos!",
  str_voice_1300531_40 = "Nah, itu baru pedang bagus!",
  str_voice_1300531_41 = "Semua membayar, tidak ada yang kabur♪",
  str_voice_1300531_42 = "Ini tagihan untuk kemenangan!",
  str_voice_1300531_43 = "Aduh, jangan sedih, bagaimana kalau aku beri sedikit diskon…",
  str_voice_1300531_44 = "Camilan Rediesel, sate iguana… Mau beli?",
  str_voice_1300531_45 = "Mungkin kau akan memberiku sesuatu yang lebih berharga lain kali?",
  str_voice_1300531_46 = "Ini benar-benar terlalu berharga. Aku sangat berharap bisa mendapat ini lagi darimu!",
  str_voice_1300531_47 = "Senyum Bos lebih berharga dari hadiah ini.",
  str_voice_1300531_48 = "Bos, terima kasih karena selalu mengingatkanku bahwa aku tidak bisa menaruh harga pada persahabatan kita.",
  str_voice_1300531_49 = "Awas, uang bisa membangkitkan kejahatan… Namun, aku tidak seperti itu, jadi kau tak perlu khawatir saat membayarku.",
  str_voice_1300531_50 = "Pelihara saja anak anjing kalau kau kesepian. Hewan jauh lebih rumit, berbeda dengan manusia… Atau kau bisa memeliharaku saja!",
  str_voice_1300531_52 = "Alchemy Stars!",
  str_voice_1300531_53 = "Bosku tersayang!",
  str_voice_1300531_54 = "Pagi yang cerah, hanya untukmu, Bos!",
  str_voice_1300531_55 = "Sore yang indah, hanya untukmu, Bos!",
  str_voice_1300531_56 = "Malam yang tenang dan tagihanmu, hanya untukmu, Bos!",
  str_voice_1300531_57 = "Selamat Tahun Baru! Tagihannya sepuluh ribu gold!",
  str_voice_1400731_1 = [[
- Tidak bisa membedakan Patty dan Patsy? Kalau begitu, ingat ini!
- Patsy suka mencolek punggungmu!
- Patty suka menggigit tanganmu!]],
  str_voice_1400731_2 = [[
- Tak ada masalah selama kita punya makanan. 
- Tak ada yang perlu dicemaskan.
- Perasaan? Apa itu? 
- Rasanya enak?
- Cepat! Tunjukkan pada kami cara memakannya!]],
  str_voice_1400731_3 = [[
- Kami ini setan. 
- Karenanya, ada tanduk.
- Kami ini anak anjing.
- Karenanya, ada ekor.
- Kami memiliki Trident, karenanya, kami ingin menyakitimu!]],
  str_voice_1400731_4 = [[
- Hound Fire, Hound Snout. 
- Kami punya kemampuan ini karena kami adalah anjing.
- Bukankah itu wajar? 
- Oh, tentu saja, kau mana tahu, kau 'kan tak punya ekor.]],
  str_voice_1400731_5 = "- Api nera-ka berkobar, berkobar, berkobar♪\n- Api nera-ka berkobar, larilah, Puppy♪",
  str_voice_1400731_6 = [[
- Gerbang menuju Neraka terbuka. - Sebenarnya, sudah terbuka sejak lama.
- Namun, kamilah penjaga gerbangnya. - Kami tidak akan mengeluarkan apa yang tidak boleh dikeluarkan!]],
  str_voice_1400731_7 = "- Biarkan kami menyiksamu! \n- Ini tidak bisa ditawar!\n- Saat kami menyiksa Istvan…\n- Dia juga tidak banyak bicara!",
  str_voice_1400731_8 = [[
- Patty dan Patsy tidak bisa saling meninggalkan. 
- Jantung kami akan berhenti jika melakukannya.
- Bagaimana dengan Puppy? 
- Ayo buat jantung Puppy berhenti juga!]],
  str_voice_1400731_9 = "- Kau takut Neraka? - Kalau kau jatuh ke sana…\n- Panggil saja nama kami. Kami akan membuka gerbangnya dan membawamu kembali.",
  str_voice_1400731_10 = [[
- Bosan sekali.
- Apa yang harus kita lakukan untuk bersenang-senang, ya?
- Lari, Puppy, lari, kami akan datang menangkapmu! Muahaha!]],
  str_voice_1400731_11 = [[
- Apakah kami ini?
- Kau mendapatkan kesempatan lagi untuk menjawab dengan benar!
- Ya, penjaga gerbang setan! Muahaha!]],
  str_voice_1400731_12 = [[
- Ayo kita mulai petak umpetnya.
- Tiga, dua, satu!
- KAMI MENEMUKANMU! Muahahihiiiwooo!]],
  str_voice_1400731_13 = [[
- Patsy punya ekor. 
- Patty punya ekor.
- Di mana ekor Istvan? 
- Aku tak pernah melihatnya.]],
  str_voice_1400731_14 = [[
- Pertama, nyalakan Hound Fire!
- Lalu, angkat Imp's Pitchfork!
- Terakhir, kejar Puppy!]],
  str_voice_1400731_15 = [[
- Kami ingin merayakannya bersamamu hari ini!
- Bermain petak umpet? 
- Berburu harta karun?
- Menempelkan ekor pada keledai? Ayolah, ayo kita main!]],
  str_voice_1400731_16 = [[
- Hati-hati dengan anak anjing imut.
- Selamat datang!
- Dan begitu kau masuk, kami akan mengejarmu habis-habisan!]],
  str_voice_1400731_17 = [[
- Puppy datang! 
- Sudah bangun?
- Tidak bisa membedakannya tanpa ekor.
- Kasihan sekali.]],
  str_voice_1400731_18 = [[
- Lapar. - Ingin makanan lagi.
- Puppy terbuat dari daging. - Kita bisa mengunyahnya!]],
  str_voice_1400731_19 = "- Mengantuk sekali… - Puppy sudah datang!\n- Sekarang bagaimana? - Kita bermain dengan Puppy sebentar!",
  str_voice_1400731_20 = [[
- Seseorang pernah berkata, 
- Tempat itu memiliki kehidupan yang kami cari.
- Kami tidak begitu peduli tentang bagian "kehidupan", 
- Yang kami "cari" jauh lebih penting!]],
  str_voice_1400731_21 = "- Putih… \n- Melayang di langit…\n- Tempat yang bersih dengan makanan! \n- Tempat yang dituju orang itu…",
  str_voice_1400731_22 = "Anjing-anjing mengawasimu!",
  str_voice_1400731_23 = [[
- Rasa Eclipsite tidak enak.
- Mereka menakutkan jika bergerombol.
- Kalau beberapa saja sih bukan masalah, - Musnahkan mereka semua!]],
  str_voice_1400731_24 = "- Kami tak bisa memakan teman… \n- Namun kami masih bisa mengejar mereka!\n- Terutama burung gagak itu…\n- Itu baru teman yang menyenangkan untuk dikejar!",
  str_voice_1400731_25 = "- Orang yang suram itu… \n- Tentu saja suka anjing!\n- Dia mungkin tidak menunjukkan banyak emosi… \n- Namun dia pria yang baik!",
  str_voice_1400731_26 = "- Kami suka menyantap makanan, \n- Menggoda orang lain,\n- Ekor dan tanduk setan kami… \n- Oh, dan pencinta anjing!",
  str_voice_1400731_27 = [[
- Orang yang benci anjing adalah orang jahat!
- Tidak tahan dengan bau darah!]],
  str_voice_1400731_28 = "- Ini menakjubkan! \n- Sangat luas di dalam!\n- Kami bisa berlarian… \n- Bermain petak umpet…\n- Hei, kami bisa mengunyah itu tidak? \n- Aku yakin kami bisa!",
  str_voice_1400731_29 = "- Patty… \n- Patsy… \n- Puppy!\n- Siapa Puppy? \n- Puppy adalah anak anjing kami…\n- Siapa yang akan jadi anak anjing kami? Tentu saja, kau! Wiiiiii!",
  str_voice_1400731_30 = [[
- Asyiiiiikkk!
- Kekuatan kelezatan!]],
  str_voice_1400731_31 = [[
- Apinya makin besar!
- Hidung kami berfungsi lebih baik!]],
  str_voice_1400731_32 = [[
- Naikkan kekuatan setan!
- Naikkan kekuatan Neraka!]],
  str_voice_1400731_33 = [[
- Aku melihatnya!
- Gerbang menuju Neraka!
- Sudah dekat!]],
  str_voice_1400731_34 = "Serangan anjing!",
  str_voice_1400731_35 = "Ekornya naik!",
  str_voice_1400731_36 = "Kau mau lihat Pitchfork?",
  str_voice_1400731_37 = "Wahai api neraka, bakar mereka sampai kering!",
  str_voice_1400731_38 = "Buka, gerbang menuju Neraka! Terima ini, api neraka!",
  str_voice_1400731_39 = [[
- Dhuar!
- Haha!]],
  str_voice_1400731_40 = "Bakar hingga matang!",
  str_voice_1400731_41 = [[
- Biarkan para setan memandumu!
- Ayo pergi!]],
  str_voice_1400731_42 = "Lihat barang-barang yang kami temukan!",
  str_voice_1400731_43 = "- Aduh…\n- Sama sekali tidak menyenangkan!",
  str_voice_1400731_44 = "Hei, kau membawa sesuatu yang lezat untuk kami santap?",
  str_voice_1400731_45 = "- Iyuh…\n- Baunya, aduh, sangat busuk…",
  str_voice_1400731_46 = [[
- Ya!
- Aromanya benar-benar menakjubkan!]],
  str_voice_1400731_47 = [[
- Puppy membawa ini!
- Pasti suka!]],
  str_voice_1400731_48 = [[
- Ini!
- Ini!
- Sangat enak!]],
  str_voice_1400731_49 = "- Anjing sangat cocok bermain petak umpet! \n- Di mana pun kau berada…\n- Selama kau meninggalkan bau… \n- Selama kau masih hidup…\n- Kami akan menemukanmu!",
  str_voice_1400731_50 = [[
- Kau bisa mendapatkan makanan kapan saja di Umbraton! 
- Biarkan saja orang-orang Guild menangkapmu.
- Lalu mintalah makanan kepada mereka! 
- Mereka akan memberimu makanan, tanpa banyak tanya!]],
  str_voice_1400731_51 = [[
- Saat itulah kami mempelajari cara menggunakan Hound Fire. 
- Makanan matang tidak begitu membuat perut kami sakit.
- Bahkan makhluk terkecil pun bisa bertahan.
- Selama mereka memiliki kekuatan dan kemauan untuk melakukannya!]],
  str_voice_1400731_52 = [[
- Alchemy!
- Stars!!]],
  str_voice_1400731_53 = "Yo! Puppy!",
  str_voice_1400731_54 = [[
- Pagi!
- Guk!]],
  str_voice_1400731_55 = [[
- Makan siang
- Makanan tambahan!]],
  str_voice_1400731_56 = [[
- Sudah malam!
- Ayo ikut bermain!]],
  str_voice_1400731_57 = [[
- Senang!
- Tahun Anjing!]],
  str_voice_1400791_1 = "Pekerjaan pemungut cukai itu tidak berat. Aku hanya perlu mengumpulkan Nightium dan membuat catatan. Karena ahli dalam hal itu, aku bisa mengerjakannya dengan sangat cepat.",
  str_voice_1400791_2 = "Orang-orang sering berkata bahwa aku ini tak punya emosi, tapi menurutku jiwa adalah rumah bagi keyakinan seseorang. Bukankah aku sudah menjelaskan tentang keyakinanku ini kepada semua orang?",
  str_voice_1400791_3 = "Nilai sesuatu ditentukan oleh standar pengukuran. Untuk saat ini, City Lord lebih penting dari kapten penjaga. Situasi mereka akan terbalik setelah tiga tahun.",
  str_voice_1400791_4 = "Semua keluarga tua pada akhirnya akan mundur, tapi warisan dari penilaian yang adil akan terus ada… Setidaknya itulah yang tercermin dalam tindakanku.",
  str_voice_1400791_5 = "Judicial Order adalah item yang fungsinya didasarkan pada keyakinan. Dengan keyakinan seseorang sebagai patokannya, ia diukur melalui beberapa pertanyaan. Tidak ada benar atau salah, hanya tingkat kepentingan.",
  str_voice_1400791_6 = "Apakah orang yang menghakimi orang lain pernah diadili dengan dasar yang sama? Aku yakin jawabannya adalah ya. Hanya dengan begitu, keadilan sejati dapat dinilai dengan mata manusia—",
  str_voice_1400791_7 = "Aku sering mempertanyakan manfaat dari berbicara denganmu… Tak usah dihiraukan, ini hanya kebiasaanku.",
  str_voice_1400791_8 = "Aku samar-samar bisa merasakan kau punya nilai yang berbeda. Apa ini… bonus? Apa yang membuatmu berbeda dari yang lain?",
  str_voice_1400791_9 = "Terkadang, aku tiba-tiba memiliki keinginan untuk membayarmu sepuluh Nightium. Aneh tidak, sih? Namun, aku memahaminya, sama seperti aku memahami arti hadirmu untukku.",
  str_voice_1400791_10 = "Apakah kau mencemaskan waktunya? Tetaplah beristirahat. Waktu luang menenangkan jiwamu, yang akan menciptakan nilai.",
  str_voice_1400791_11 = "Kenapa kau memanggilku? Meski tidak begitu paham, aku akan menilai betapa berharganya aku bagimu.",
  str_voice_1400791_12 = "Maafkan aku, aku… Aku tak bisa menggunakan apa-apa selain timbangan.",
  str_voice_1400791_13 = "Tahukah kau bahwa tidak ada yang benar atau salah dengan sebagian besar hal di dunia ini, hanya tingkat kepentingannya?",
  str_voice_1400791_14 = "Jangan meremehkan atau melebih-lebihkan… Lebih mudah diucapkan daripada dilakukan.",
  str_voice_1400791_15 = "Setiap orang mengakui pentingnya ulang tahun. Ayo kita rayakan, rayakan dengan seratus Nightium.",
  str_voice_1400791_16 = "Selamat datang kembali. Ini adalah waktu terbaik untuk bekerja—kau akan bisa menghasilkan setidaknya sepuluh Nightium.",
  str_voice_1400791_17 = "Selamat pagi. Ada baiknya kau melakukan latihan senilai tiga Nightium—nilai yang mungkin kau dapatkan dari latihan itu akan berlipat ganda.",
  str_voice_1400791_18 = "Maukah kau meluangkan waktu untuk membuat ringkasan senilai satu Nightium setelah aktivitas seharian?",
  str_voice_1400791_19 = "Aku tidak akan memaksamu untuk beristirahat. Aktivitas apa pun yang kau pilih akan bernilai selama niatnya berasal dari kehendakmu sendiri.",
  str_voice_1400791_20 = "Timbangan ini diberikan Lumopolis untuk kami. Benda ini tidak bisa dipisahkan dari misi dan arti penting seluruh keluarga.",
  str_voice_1400791_21 = "Aku ingin mengukur nilai kebenaran yang dibicarakan orang-orang itu.",
  str_voice_1400791_22 = "Demi White Night.",
  str_voice_1400791_23 = "Sayangnya, sepuluh Eclipsite normal bahkan tidak mencapai nilai 1 Nightium.",
  str_voice_1400791_24 = "Lady Duke telah banyak membantuku, tapi dia sepertinya tidak suka kalau aku membayarnya dengan Nightium.",
  str_voice_1400791_25 = "Aku tidak paham. Apakah penilaiannya berasal dari keyakinan hebatnya?",
  str_voice_1400791_26 = "Aktivitas apa yang suka kulakukan? Yah, memeriksa timbangan, meneliti buku besar, dan mengonversi.",
  str_voice_1400791_27 = "Orang yang adil seharusnya tidak menilai sesuatu berdasarkan preferensinya sendiri… Namun, aku tidak pandai berurusan dengan hal-hal yang ambigu.",
  str_voice_1400791_28 = "Ini adalah benda langka yang tidak dapat diukur oleh Judicial Order.",
  str_voice_1400791_29 = "Senang bertemu denganmu. Aku mengukur berbagai hal, tapi nilaimu didasarkan pada kinerjamu, bukan pengukuranku.",
  str_voice_1400791_30 = "Sekarang aku bisa mengukur sesuatu dengan lebih akurat.",
  str_voice_1400791_31 = "Potensiku jadi meningkat.",
  str_voice_1400791_32 = "Ini adalah penilaian yang lebih jelas.",
  str_voice_1400791_33 = "Aku akan merebut kembali keadilan dari para dewa!",
  str_voice_1400791_34 = "Aku paham. Angkat bebannya.",
  str_voice_1400791_35 = "Kalibrasi selesai.",
  str_voice_1400791_36 = "Silakan konfirmasi pengimbang.",
  str_voice_1400791_37 = "Penilaianku akan disaksikan oleh semua orang—",
  str_voice_1400791_38 = "Terimalah penghakiman dari seluruh makhluk!",
  str_voice_1400791_39 = "Adil—",
  str_voice_1400791_40 = "Hanya saja—",
  str_voice_1400791_41 = "Untuk penilaian yang adil.",
  str_voice_1400791_42 = "Penilaian yang adil harus dilakukan.",
  str_voice_1400791_43 = "Ini akibat dari satu kesalahan kecil…",
  str_voice_1400791_44 = "Pengungkapan niat baik didasarkan pada kesetaraan. Apa yang kau inginkan sebagai imbalannya?",
  str_voice_1400791_45 = "Aku akan menerima ini karena nilainya.",
  str_voice_1400791_46 = "Terima kasih. Ini akan berharga.",
  str_voice_1400791_47 = "Mungkin nilai sentimental harus ditambahkan pada nilainya.",
  str_voice_1400791_48 = "Terima kasih. Akan kugunakan segala yang aku punya untuk membalasmu hingga lunas.",
  str_voice_1400791_49 = "Ketidakacuhan dan kepraktisan ada karena suatu alasan, mirip dengan bakat dan senjata, yang setidaknya membantuku bertahan hidup dengan lebih baik.",
  str_voice_1400791_50 = "Menggunakan akal budi sebagai kriteria untuk penilaian ini sudah diterima secara luas. Namun, kenyataannya kita tidak berani menggunakan emosi sebagai gantinya karena kita tidak bisa mengendalikannya dengan benar.",
  str_voice_1400791_51 = "Tidak terpengaruh oleh emosi membantuku membuat keputusan yang lebih adil, tapi aku sedih dengan ketidakadilan ibu ketika dia menyebutku sebagai monster tanpa emosi.",
  str_voice_1400791_52 = "Alchemy Stars.",
  str_voice_1400791_53 = "Mulai interogasi.",
  str_voice_1400791_54 = "Selamat pagi. Kau harus menjaga Nightium yang sedang kau pegang.",
  str_voice_1400791_55 = "Selamat siang. Kau memiliki kesempatan untuk meningkatkan nilaimu.",
  str_voice_1400791_56 = "Selamat malam. Silakan ambil keputusan.",
  str_voice_1400791_57 = "Selamat Tahun Baru.",
  str_voice_1400811_1 = "Kontes popularitas? Huh! Mana mungkin ada yang bisa menyaingiku dalam hal… Apa!? Aku mendapat suara paling sedikit!?",
  str_voice_1400811_2 = "Betuuul sekali! Akulah yang akan mengalahkan Sinsa dan menjadi pemimpin Rediesel Wrench! Kedudukanku saat ini? Yah… 728 kalah, 3 seri, dan 0 menang.",
  str_voice_1400811_3 = "Aku bekerja keras untuk membersihkan semua mobil konvertibel hanya demi mendapatkan gelar \"Juara Pertama Bersih-Bersih\"… dan ternyata itu hanya gelar tipuan! Meskipun begitu, aku tetap senang…",
  str_voice_1400811_4 = "172, 173… Haha! Aku mengalahkan 173 Eclipsite hari ini! Bagaimana denganmu?",
  str_voice_1400811_5 = "Memperbaiki tingkat pendidikan juga merupakan bagian penting dari menjadi lebih kuat. Begitulah yang Odi ajarkan padaku. Namun, dia menyatakan aku lulus dalam waktu kurang dari seminggu… Jangan-jangan aku ini benar-benar genius, ya?",
  str_voice_1400811_6 = "Aku sudah terbiasa dengan kegagalan, jadi itu tidak lagi merisaukanku. Berlari tanpa pikir panjang untuk menyambut tantangan dengan penuh semangat, apa pun peluangnya—itulah aku! Begitulah kehidupan Brock!",
  str_voice_1400811_7 = "Mulai hari ini dan seterusnya, kita adalah keluarga! Jangan khawatir. Aku pasti akan mendukungmu, selalu!",
  str_voice_1400811_8 = "Akan kuajarkan seperti apa laki-laki sejati itu! Dengar! Yang paling penting dalam hidup laki-laki adalah mesin turbo, pelari, dan bubuk protein!",
  str_voice_1400811_9 = "Kenapa khawatir? Kau sudah bekerja dengan baik. Pikirkan masalah esok hari saat esok hari. Hiduplah sepenuhnya di saat ini!",
  str_voice_1400811_10 = "Oh, saking bosannya sampai-sampai badanku seperti papan! Kita mulai dengan pemanasan… Hatsyiii!",
  str_voice_1400811_11 = "Tepat sekali! Aku adalah orang yang paling dapat diandalkan di seluruh Rediesel Wrench.",
  str_voice_1400811_12 = "Ya, aku takut ketinggian… tapi itu bukan masalah… Ya, aku juga sedikit takut dengan serangga!?",
  str_voice_1400811_13 = "Aku dapat satu botol cat semprot lagi! Yang ini memancarkan cahaya! Sekarang kita bisa memberi mobil-mobil konvertibel itu penampilan baru!",
  str_voice_1400811_14 = "Laki-laki sejati tidur di gurun! Namun, di kantong tidur, bukan di atas pasir!",
  str_voice_1400811_15 = "Wow! Hari ini ulang tahunmu! Sebenarnya, ini juga ulang tahun… Tunggu. Kapan ulang tahunku, sih?",
  str_voice_1400811_16 = "La-lala… Lala-la… Rediesel di pagi hari… Lumo Guards sudah berpatroli!? Kabur!",
  str_voice_1400811_17 = "Bagaimana kalau lari pagi, Navigator? Aku pelari tercepat di seluruh Rediesel Wrench. Aku bisa berlari lebih cepat dari mobilmu!",
  str_voice_1400811_18 = "Aku sangat lapar… Aku tidak mau makan malam dengan sandworm lagi… Menjijikkan.",
  str_voice_1400811_19 = "*Mendengkur* Serangan musuh!? Tidak! Aku tidak bertugas jaga hari ini!",
  str_voice_1400811_20 = "Rediesel Wrench berkembang di bawah kepemimpinan orang kedua mereka, yaitu AKU! Hoi! Namun, jangan beri tahu Sinsa bahwa aku mengatakan ini.",
  str_voice_1400811_21 = "Caravan yang bekerja untuk Lumopolis adalah domba yang harus disembelih… Itu hanya kalau aku bisa bertemu dengan mereka setiap hari!",
  str_voice_1400811_22 = "Rediesel Wrench! Kalahkan Eclipsite dan Lumopolis!",
  str_voice_1400811_23 = "Membunuh Eclipsite? Terlalu mudah!",
  str_voice_1400811_24 = "Jona, katamu? Oh, tidak. Aku baru saja teringat mimpi buruk… Arghhhhh!!!",
  str_voice_1400811_25 = "Saat aku memberi tahu Regina bahwa suara mesin turbo adalah musik terbaik, pada saat itulah hubungan kami berakhir.",
  str_voice_1400811_26 = "Lebih kuat, pria harus tumbuh lebih kuat. Latih terus ototmu! Jangan seperti ranting!",
  str_voice_1400811_27 = "Aku benci Lumo Soldier… Rambut perak, tinggi, dan ganteng… lebih ganteng dariku. Cih!",
  str_voice_1400811_28 = "Dia besar sekali! Rasanya seolah-olah dia diciptakan untukku! Hm? Dia milikmu? Tidak bisakah kau memberikannya padaku?",
  str_voice_1400811_29 = "Cepat seperti api, menyerang seperti badai, pemberontak yang lahir di turbin! Akulah Brock, siap membantumu! Odi menulis kata-kata ini untukku.",
  str_voice_1400811_30 = "Rasanya luar biasa!",
  str_voice_1400811_31 = "Saatnya untuk serius!",
  str_voice_1400811_32 = "Woooaaaah! Kekuatan mengalir dalam diriku!",
  str_voice_1400811_33 = "Maju dengan kecepatan penuh!",
  str_voice_1400811_34 = "Cepat, cepat!",
  str_voice_1400811_35 = "Sekarang saatnya!",
  str_voice_1400811_36 = "Kau harus mencoba terbang dengan bantuan tinjuku!",
  str_voice_1400811_37 = "Lepaskan!",
  str_voice_1400811_38 = "Enyahlah!",
  str_voice_1400811_39 = "Kecepatan penuh!",
  str_voice_1400811_40 = "Gear Fusion!",
  str_voice_1400811_41 = "Aku Kaptennya? Tentu saja!",
  str_voice_1400811_42 = "Aku juga sangat kuat hari ini!",
  str_voice_1400811_43 = "Huh! Aku tidak percaya… Ayo kita coba lagi!",
  str_voice_1400811_44 = "Ja-jangan sentuh itu! Oh, sial! Malah mati… Bukan pertanda baik, nih.",
  str_voice_1400811_45 = "Ehhh? Hadiah untukku?",
  str_voice_1400811_46 = "Ini keren!",
  str_voice_1400811_47 = "Ini… ini… K-kau-kau-kau… Aku-aku-aku…",
  str_voice_1400811_48 = "A-aku sangat tersentuh… Hiks…",
  str_voice_1400811_49 = "Masa laluku? Aku tak begitu ingat tentang masa laluku lagi. Tidak ada satu orang pun di Rediesel Wrench yang memiliki masa lalu, hanya masa kini.",
  str_voice_1400811_50 = "Mungkin… ada kesalahpahaman, atau penjelasan untuk semua ini. Namun, alasan itu tidak bisa menyembuhkan luka emosionalku. Kekerasan adalah jawaban untuk segalanya bagiku.",
  str_voice_1400811_51 = "Kupikir, saat aku dan kawan-kawan menjelajahi alam liar dengan mobil konvertibel Powerball, aku hanya percaya satu hal—aku tidak pernah menyesal bergabung dengan Rediesel Wrench.",
  str_voice_1400811_52 = "Alchemy Stars.",
  str_voice_1400811_53 = "Navigator.",
  str_voice_1400811_54 = "Pagi. Siap untuk berlatih?",
  str_voice_1400811_55 = "Aku akan menantang Sinsa sebentar lagi!",
  str_voice_1400811_56 = "Ada yang bagus! Mau bergabung denganku?",
  str_voice_1400811_57 = "Aku akan menang tahun depan! Eh? Ini sudah Tahun Baru, ya?",
  str_voice_1400911_1 = "Kita terperangkap dalam arus takdir, beringsut maju ke depan. Siap atau tidak, arus akan membawa kita tanpa memedulikannya.",
  str_voice_1400911_2 = "Aku benar-benar minta maaf. Seharusnya aku tidak mengatakan hal seperti itu… Hanya saja saat tidak memainkan instrumenku, aku tidak punya tempat untuk sembunyi, dan aku mulai mengingat…",
  str_voice_1400911_3 = "Terkadang, aku harus berhenti bermain di tengah penampilanku karena tiba-tiba gemetaran… Namun, kau tak pernah memarahiku. Aku sangat berterima kasih untuk itu.",
  str_voice_1400911_4 = "Bahkan saat aku mencoba untuk tidak memikirkannya, ketakutan masih mengintai dan menghantuiku dalam wujud mimpi buruk. Ketakutan itu tak pernah berhenti menggangguku…",
  str_voice_1400911_5 = "Masa lalu bagaikan benang yang menjerat pergelangan tangan dan leherku. Saat akhirnya kusadari bahwa aku harus mengurainya, aku tak bisa melakukannya karena tak tahu caranya.",
  str_voice_1400911_6 = "Aku selalu memimpikan hari saat aku jatuh ke dalam kegelapan tanpa jalan keluar. Hingga hari ini, aku masih laksana daun yang gugur, tanpa arah, dan tak tahu apakah aku harus menetap atau pergi…",
  str_voice_1400911_7 = "Jika sudah mengambil keputusan, sebaiknya kau pergi saja. Jangan menoleh ke belakang. Tinggalkan saja aku, untuk berjaga-jaga… Aku akan menyambutmu jika kau kembali…",
  str_voice_1400911_8 = "Suatu hari, aku akan menghilang. Kau akan merindukanku. Kuharap kau akan pergi dengan ratapan itu. Bahkan jika kau akan membuangnya, itu masih lebih baik daripada tidak ada yang merindukanku…",
  str_voice_1400911_9 = "Aku sangat berharap aku bisa terus makin dekat dengan impianku… Rasanya akan seperti angin sepoi-sepoi, gerimis berkabut, jalan lurus, atau jalan yang cerah. Sama sepertimu…",
  str_voice_1400911_10 = "Aku akan bermain lebih baik, jadi tetaplah di sini dan jangan pergi. Kumohon, jangan pergi secepat ini…",
  str_voice_1400911_11 = "Apa kau akan meninggalkanku? Apa kau seperti burung di antara awan atau angsa yang sedang bermigrasi… Aku berjanji tidak akan merepotkanmu… Jadi, tolong, tetaplah di sini.",
  str_voice_1400911_12 = "Saat esok tiba, awan gelap akan sirna… Semoga penderitaanmu akan berkurang.",
  str_voice_1400911_13 = "Tolong hapus air mata ini… Usap… Dan biarkan aku lupa.",
  str_voice_1400911_14 = "Aku tahu aku harus terus bermain. Selama aku tidak berhenti… mungkin, air mataku tidak akan menetes.",
  str_voice_1400911_15 = "Ulang tahun akan selalu datang sesuai yang diharapkan. Semoga cahaya yang kau lihat di hari pertama kelahiranmu menemanimu setiap saat.",
  str_voice_1400911_16 = "Selamat datang kembali. Aku harap bayangan dan suaramu bisa menetap lebih lama.",
  str_voice_1400911_17 = "Aku berharap pagi hari tidak selalu sedingin ini, tapi sehangat perasaanku ketika kau datang…",
  str_voice_1400911_18 = "Aku mendengar suara kedatanganmu, terputus-putus dan dalam cahaya yang berkedip-kedip.",
  str_voice_1400911_19 = "Maafkan aku, tapi setiap hari pada jam ini… Aku selalu merasa sulit untuk menahan keinginan itu…",
  str_voice_1400911_20 = "Sudut-sudut gelap Lumopolis menanggung luka yang tak terhitung jumlahnya.",
  str_voice_1400911_21 = "Kuharap Illumina akan membawa kedamaian. Aku juga berharap tidak akan pernah ada perang lagi.",
  str_voice_1400911_22 = "Demi White Night…",
  str_voice_1400911_23 = "Ini adalah… pikiran gelap yang menggangguku… Ini adalah trauma masa lalu yang tak akan pernah bisa sembuh.",
  str_voice_1400911_24 = "Aku bisa mendengar denyut kesakitan yang berasal dari masa lalu yang tak terlihat di masa kejayaannya…",
  str_voice_1400911_25 = "Carleen sangat kuat, dan dia bisa menghadapinya. Kuharap dia… tidak akan menyalahkan dirinya sendiri.",
  str_voice_1400911_26 = "Aku suka… sandaran, ketergantungan, perlindungan, ketenangan, dan kedamaian seperti yang aku ingat.",
  str_voice_1400911_27 = "Aku tidak ingin menghadapinya… Mimpi buruk, hawa dingin, dan labirin… yang tidak ada jalan keluarnya.",
  str_voice_1400911_28 = "Sayapnya sangat besar. Mungkin ia akan bisa membawa kesedihan pergi hingga jauh sekali…",
  str_voice_1400911_29 = "Penyesalan sudah menjadi not musik, yang sejak awal sekali, sudah diatur agar terdengar sunyi, dan seterusnya akan terus dimainkan… Senang bertemu denganmu. Aku Chloe, seorang musisi.",
  str_voice_1400911_30 = "Suara musik… mengalir semakin jauh…",
  str_voice_1400911_31 = "Aku bisa memahami apa yang diungkapkan oleh musik…",
  str_voice_1400911_32 = "Akankah aku kemudian… bisa melepaskan diri darinya?",
  str_voice_1400911_33 = "Mungkin aku akan bisa melihat sesuatu yang berbeda dari sebelumnya…",
  str_voice_1400911_34 = "Aku akan bermain… Fantasia.",
  str_voice_1400911_35 = "Lagu selanjutnya. Apa yang harus kumainkan…",
  str_voice_1400911_36 = "Menuangkan perasaan ke dalam pertunjukan…",
  str_voice_1400911_37 = "Ini adalah… suara kesedihan dari musik.",
  str_voice_1400911_38 = "Musik ini menceritakan masa lalu yang menghantui.",
  str_voice_1400911_39 = "Aku ingin menghilang…",
  str_voice_1400911_40 = "Menghilangkan kesuraman ini…",
  str_voice_1400911_41 = "Jika ada yang bisa kulakukan…",
  str_voice_1400911_42 = "Kuharap itu tidak akan hilang dalam sekejap.",
  str_voice_1400911_43 = "Jika bukan karena aku… yang mengikat semua orang…",
  str_voice_1400911_44 = "Bagaimana kalau… Aku akan memainkan musik dan menenangkan diri…",
  str_voice_1400911_45 = "Tidak dengan kata-kata… Aku tidak paham…",
  str_voice_1400911_46 = "Aku akan merawat hadiah yang tidak datang dengan mudah ini.",
  str_voice_1400911_47 = "Kau selalu memberiku sesuatu…",
  str_voice_1400911_48 = "Ini sangat berharga! Bagaimana caraku menunjukkan bahwa aku sangat menyukainya?",
  str_voice_1400911_49 = "Aku selalu berusaha melarikan diri ke dunia musik… Namun, aku tahu bahwa satu-satunya jalan keluar adalah dengan melakukan pengakuan dosa. Terang-terangan dan tidak ada yang disembunyikan…",
  str_voice_1400911_50 = "Ibu tidak cukup sehat untuk menanggung risiko kehamilan. Jika bukan gara-gara aku… dia bisa hidup dengan tenang…",
  str_voice_1400911_51 = "Aku tidak berada di sisinya saat dia menghadapi ketakutan terbesarnya. Menjelang akhir hayatnya, dia tidak pernah berhenti memanggilku…",
  str_voice_1400911_52 = "Alchemy Stars…",
  str_voice_1400911_53 = "Hei…",
  str_voice_1400911_54 = "Selamat pagi. Apa kau sudah bangun?",
  str_voice_1400911_55 = "Selamat sore. Ada beberapa hal yang kuharap bisa kau lakukan untukku…",
  str_voice_1400911_56 = "Selamat malam. Tolong jaga dirimu jangan sampai terkena flu.",
  str_voice_1400911_57 = "Semoga tak ada kesedihan untukmu di tahun baru ini!",
  str_voice_1500091_1 = "Ah… Kekuatan matahari sudah hadir. Itu adalah pintu rahasia yang dikunci oleh True Order—haruskah aku membukanya? Mungkin sesuatu yang menarik akan terjadi.",
  str_voice_1500091_2 = "Terlalu banyak kemarahan dan ketakutan yang menumpuk, menunggu dalam diam di kegelapan… Kau mau tahu lebih banyak?",
  str_voice_1500091_3 = "Suara kebenaran adalah ciuman, sungai yang mengalir, sebuah… Naskah yang diberikan Lady Victoria kepadaku sangat tidak jelas dan sulit untuk dihafal.",
  str_voice_1500091_4 = "Bisikan-bisikan itu sudah lenyap… Sekarang kita adalah satu. Mari berbagi kebahagiaan ini, dan aku akan membawakanmu kebahagiaan terhebat—",
  str_voice_1500091_5 = "Mengorbankan segalanya untuk keyakinan yang besar itu sepadan demi kedamaian batin, kewarasan, dan bahkan hidup dan jiwa kita…",
  str_voice_1500091_6 = "Truth sudah lama berhenti menyampaikan ajaran kepadaku karena aku sudah menjadi salah satu dari mereka… Ulurkan tanganmu, dan perhentian kita selanjutnya adalah surga.",
  str_voice_1500091_7 = "Aku mengagumi keyakinan dan kejujuranmu, tapi itu pasti akan goyah di hadapan kebahagiaan mutlak. Mendekatlah jika kau tak percaya—",
  str_voice_1500091_8 = "Terkadang, perbedaan antara keyakinan kita masing-masing hanya dipisahkan oleh sehelai rambut. Haha, sekian pendapatku tentang hal ini. Silakan renungkan sendiri.",
  str_voice_1500091_9 = "Jangan salah—aku tidak pernah berjuang untukmu. Hanya saja, bagiku kau adalah bentuk kesenangan juga… dan hal yang sama berlaku untuk Lady Victoria.",
  str_voice_1500091_10 = "Semoga kau bisa mendengar bisikan di bawah sinar matahari… Haha, kau menyadari kurangnya ketulusanku? Aku perlu latihan lagi.",
  str_voice_1500091_11 = "Apakah kau akhirnya bersedia mendengarkan bisikan itu denganku? Oh, menarik sekali ini!",
  str_voice_1500091_12 = "Halo, Tuan. Anda tertarik belajar tentang True Order?",
  str_voice_1500091_13 = "Omong-omong tentang klub penggemarku—semua anggotanya adalah wanita yang perhatian dan baik hati, dan aku sangat berterima kasih kepada mereka.",
  str_voice_1500091_14 = "Karena gagal membimbing lebih banyak orang untuk mengikuti kebenaran, aku selalu kesulitan tidur.",
  str_voice_1500091_15 = "Bersukacitalah. Kau baru saja terlahir kembali!",
  str_voice_1500091_16 = "Apa kau sudah memutuskan untuk bergabung dengan kami?",
  str_voice_1500091_17 = "Berdoa dari dini hari hingga senja.",
  str_voice_1500091_18 = "Jika lari dari kebenaran dunia ini, kau akan dikepung oleh kegelapan dan kekacauan bahkan jika matamu terbuka lebar.",
  str_voice_1500091_19 = "Lihat, nova menerangi langit untukmu… Bergabunglah denganku untuk menyingkirkan mimpi buruk yang kotor ini.",
  str_voice_1500091_20 = "True Order adalah kapal yang berlayar menuju surga dengan sayap yang mengucapkan selamat tinggal pada hal-hal yang tak berwujud.",
  str_voice_1500091_21 = "Makhluk-makhluk menyedihkan itu sama tidak pentingnya seperti lalat, tapi aku masih memiliki sedikit rasa hormat yang menyedihkan terhadap mereka.",
  str_voice_1500091_22 = "Semoga Truth memberkatimu.",
  str_voice_1500091_23 = "Abu dari era sebelumnya akan dibersihkan suatu hari nanti.",
  str_voice_1500091_24 = "Lady Victoria adalah perempuan paling sempurna. Mau bergabung dengan True Order?",
  str_voice_1500091_25 = "Sepertinya Nails tidak mendengar apa yang kukatakan, tapi itu tidak akan menghentikan kami untuk bekerja sama dengan bahagia.",
  str_voice_1500091_26 = "Aku sudah menyaksikan banyak hal selama perjalananku, yang membuat keyakinanku menjadi lebih kuat.",
  str_voice_1500091_27 = "Demi kebenaran, bagaimana mungkin aku tidak menyukai sesuatu? Jika harus memilih sesuatu, aku akan mengatakan segalanya selain kebenaran.",
  str_voice_1500091_28 = "Pembohong yang mengagumkan, tapi itu tidak seberapa dibandingkan dengan kebenaran.",
  str_voice_1500091_29 = "Musik yang menyenangkan dimainkan saat Kingdom of Truth runtuh. Orang-orang yang beriman akan menerima karunia keselamatan, sedangkan mereka yang tidak percaya akan berubah menjadi debu. Bergabunglah dengan kami dan raih kebahagiaan abadi…",
  str_voice_1500091_30 = "Aku akan menyampaikan ketulusanmu—",
  str_voice_1500091_31 = "Ada suara yang terdengar makin keras di kepalaku!",
  str_voice_1500091_32 = "Rekan sebangsaku yang mengejar Truth!",
  str_voice_1500091_33 = "Semua hasrat adalah sumber dosa.",
  str_voice_1500091_34 = "Tak ada yang bisa menghindarinya.",
  str_voice_1500091_35 = "Bebaskan kekuatan kuno ini!",
  str_voice_1500091_36 = "Truth mengatakan kepadaku bahwa itu sudah siap.",
  str_voice_1500091_37 = "Ini adalah mimpi buruk yang nyata.",
  str_voice_1500091_38 = "Aku akan merobek kain kenyataan.",
  str_voice_1500091_39 = "Keyakinan itu abadi.",
  str_voice_1500091_40 = "Truth adalah segalanya.",
  str_voice_1500091_41 = "Aku akan menunjukkan padamu sesuatu yang menarik…",
  str_voice_1500091_42 = "Rekan sebangsaku yang mencari Truth. Ini hanyalah permulaan…",
  str_voice_1500091_43 = "… Apa membuat frustrasi juga bagian dari rencanamu?",
  str_voice_1500091_44 = "Kau mau tahu apa isi kotak ini? Itu rahasia.",
  str_voice_1500091_45 = "Terima kasih, tapi… bahkan aku lebih baik darimu dalam mempromosikan produk.",
  str_voice_1500091_46 = "Menarik! Aku meremehkanmu tadi.",
  str_voice_1500091_47 = "Haha, kau memahamiku.",
  str_voice_1500091_48 = "Terima kasih, ini kecupan terima kasih di tanganmu.",
  str_voice_1500091_49 = "Adakah yang memberitahumu bahwa masa lalu telah dihancurkan oleh api dosa, pria-pria berbaju besi berubah menjadi kerangka, dan pedang-pedang perak dihancurkan…",
  str_voice_1500091_50 = "Lepaskan kebodohan dan kesombonganmu. Lewati ujian lava dan gurun untuk mendapatkan berkah.",
  str_voice_1500091_51 = "Aku pernah pergi ke Eternal Realm dan secara pribadi telah melihat nasib mereka yang mengkhianati Truth dan para pembangkang… Meskipun menurutku aku tak akan bernasib seperti mereka, untuk sementara aku tenggelam dalam kebaikan Lady Victoria yang luar biasa.",
  str_voice_1500091_52 = "Alchemy Stars.",
  str_voice_1500091_53 = "Temanku tersayang…",
  str_voice_1500091_54 = "Selamat pagi, temanku.",
  str_voice_1500091_55 = "Selamat sore, temanku.",
  str_voice_1500091_56 = "Selamat malam, temanku.",
  str_voice_1500091_57 = "Selamat Tahun Baru, temanku!",
  str_voice_1500421_1 = "Untuk apa rahang besi itu? Orang terakhir yang bertanya tentang itu kepalanya pecah bagaikan kenari, itu fungsinya!",
  str_voice_1500421_2 = "Kenapa kau tidak memberi Colossus nama yang feminin? Dengan begitu, kau tak akan pernah meninggalkannya sendiri di medan perang.",
  str_voice_1500421_3 = "Menurutmu aku ini konyol, ya!? Hanya Dewa yang tahu siapa lagi yang menunggu kita di masa depan. Perang selalu ada di sekitar kita!",
  str_voice_1500421_4 = "Jangan pernah membunuh orang dengan pisau kalau bisa dengan senapan. Aku akan meminta Gronru memberikan peluru penembus baju zirah nanti dan akan kuempaskan mereka ke neraka.",
  str_voice_1500421_5 = "Lebih banyak berlatih berarti akan ada lebih sedikit kematian dalam pertempuran.",
  str_voice_1500421_6 = "Kata orang, peluru bisa mengenai siapa saja. Sayang sekali peluru itu selalu menghindariku, ha!",
  str_voice_1500421_7 = "Hari ini cuacanya cerah. Kenapa kau tidak ikut pelatihan lintas alam denganku saja?",
  str_voice_1500421_8 = "Tidak ada yang akan memperlakukanmu dengan adil dan setara saat bertempur. Gunakan trik kotor apa pun yang diperlukan untuk menang! Bagaimana kalau kutunjukkan beberapa triknya?",
  str_voice_1500421_9 = "Mari kita lihat wajah pertempuranmu… Apa? Cuma itu yang kau bisa? Ha! Dasar pemula!",
  str_voice_1500421_10 = "Akhir minggu yang menyenangkan! Apa kau datang untuk bermain catur denganku? Tidak? Kalau begitu, pergilah agar aku bisa bermain sendiri.",
  str_voice_1500421_11 = "Ahha! Kau mau aku melindungimu! Atau kalau tidak, kau akan mati bosan?",
  str_voice_1500421_12 = "Kudengar keadaan kamp pemula di Illumina makin buruk. Apa instruktur latihan tidak melakukan apa-apa? Kalau begini terus, mereka akan menjadi sasaran empuk saja dalam pertempuran!",
  str_voice_1500421_13 = "Jika memang bosan, berlatihlah agar kau tidak melakukan kesalahan pada saat genting.",
  str_voice_1500421_14 = "Tentara tak ada artinya tanpa perang. Aku tentunya tak ingin jadi parasit yang tidak berkontribusi apa-apa.",
  str_voice_1500421_15 = "Kau ingin merayakan ulang tahunmu? Bagaimana dengan latihan khusus hanya untukmu? Aku janji kau akan merasa telah terlahir kembali…",
  str_voice_1500421_16 = "Terlalu sunyi di sini. Aku mau menembak sesuatu!!",
  str_voice_1500421_17 = "Bangun, pemalas! Ini bukan rumah nenekmu yang nyaman dan tenang!",
  str_voice_1500421_18 = "Sudah seharian ini aku tak melihat musuh. Aku bosan! Sana, carikan satu atau dua Eclipsite untuk kulawan!",
  str_voice_1500421_19 = "Sudah lama sejak terakhir kali aku berlatih semalaman… Mumpung kau di sini, bagaimana kalau kita melakukannya bersama?",
  str_voice_1500421_20 = "Illumina akhir-akhir ini sedang berfokus pada perdagangan. Mengirimkan akuntan ke perang adalah ide buruk. Mereka hanya menunggu dibantai.",
  str_voice_1500421_21 = "Awasi para kesatria yang ketinggalan zaman dari Lumopolis itu! Apa yang mereka pikirkan, menuntut duel dalam pertempuran?",
  str_voice_1500421_22 = "Jayalah Illumina!",
  str_voice_1500421_23 = "Dilihat dari komandannya yang buruk, perwiranya yang tidak kompeten, dan tentaranya yang mengikuti perintah tanpa tahu apa-apa, apa lagi yang bisa kauharapkan selain sekumpulan orang yang tidak karuan?",
  str_voice_1500421_24 = "Kenapa Hiiro bicara panjang lebar tentang Bushido? Bodoh! Seharusnya dalam perang, kau menyerang diam-diam!",
  str_voice_1500421_25 = "Jika ada kesempatan, aku pasti akan memberi tahu Reinhardt: Sudah cukup istirahatnya, saatnya bersiap untuk perang!",
  str_voice_1500421_26 = "Damai? Pfft! Lagi pula, orang-orang biasanya tak tahu mau ke mana, dan hanya perang yang bisa membuat mereka merasa berguna!",
  str_voice_1500421_27 = "Takdir pemungkas dari seorang prajurit adalah satu peluru yang menyasarnya. Jika tidak, hanya ada kebosanan di sela-selanya.",
  str_voice_1500421_28 = "Aku juga mau Colossus! Pasti seru menjatuhkan beberapa misil ke kubahnya!",
  str_voice_1500421_29 = "Kudengar akan ada banyak pertempuran! Aku Barton, komandan legiun Illumina Federation Army. Ayo kita buang sampah-sampah itu sekarang juga!",
  str_voice_1500421_30 = "Biarkan aku balas melawan mereka!",
  str_voice_1500421_31 = "Pedangku sudah menjadi lebih tajam.",
  str_voice_1500421_32 = "Prajurit tua tak pernah mati.",
  str_voice_1500421_33 = "Aku sendiri adalah satu legiun!",
  str_voice_1500421_34 = "Ya!",
  str_voice_1500421_35 = "Siap tembak.",
  str_voice_1500421_36 = "Saatnya berpesta!",
  str_voice_1500421_37 = "Aku akan membunuhmu dengan Army Sword milik Barton!",
  str_voice_1500421_38 = "Rasakan serangan peluru-peluruku!",
  str_voice_1500421_39 = "Sherman - Dimodifikasi!",
  str_voice_1500421_40 = "Mati kalian semua!",
  str_voice_1500421_41 = "Ikuti aku dan bunuh mereka semua!",
  str_voice_1500421_42 = "Sekelompok pecundang ini bukan tandinganku!",
  str_voice_1500421_43 = "Mundur, tapi kita akan kembali!",
  str_voice_1500421_44 = "Aku bosan. Bagaimana kalau kita main perang-perangan?",
  str_voice_1500421_45 = "Ah, terima kasih.",
  str_voice_1500421_46 = "Lumayan juga. Akan kupertimbangkan untuk menggunakannya.",
  str_voice_1500421_47 = "Ini sangat berguna. Akan kuterima.",
  str_voice_1500421_48 = "Haha! Ini sama memuaskannya dengan bertempur!",
  str_voice_1500421_49 = "Pertempuran sekarang jauh lebih mudah dibandingkan dengan beberapa tahun yang lalu… Nah, kalau itu baru perang sungguhan! Akan kuceritakan padamu kapan-kapan.",
  str_voice_1500421_50 = "Hanya perang yang bisa mengubahku menjadi komandan legiun di usiaku. Pango, di sisi lain, tidak seberuntung itu. Seseorang sudah pasti akan tertembak dalam pertempuran.",
  str_voice_1500421_51 = "Jangan meremehkan Four Angels dari Lumopolis. Gadis-gadis itu bertarung bagaikan harimau. Aku harus mencari cara untuk menetralisasi mereka…",
  str_voice_1500421_52 = "Alchemy Stars!",
  str_voice_1500421_53 = "Hei, kau di sini?",
  str_voice_1500421_54 = "Pagi!",
  str_voice_1500421_55 = "Kau punya waktu luang?",
  str_voice_1500421_56 = "Apa kau sudah tidur?",
  str_voice_1500421_57 = "Tahun Baru sudah tiba!",
  str_voice_1500751_1 = "Berengsek, aku benar-benar ingin menebas kepala orang-orang bodoh Rediesel Wrench itu! Setidaknya ganti Sandworm dengan sarapan normal!",
  str_voice_1500751_2 = "Jangan pernah meremehkan petugas teknis. Jika mau, aku bahkan bisa membalikkan tanah… Kau masih bisa terbang? Kalau begitu, aku akan mematahkan sayapmu!",
  str_voice_1500751_3 = "Apa salahnya bertubuh pendek? Mulai sok-sokan, ya? Sudah pernah lihat orang-orang bodoh yang jangkung tapi tak berotak? Markas Rediesel mana pun penuh dengan mereka!",
  str_voice_1500751_4 = "Kabelku memiliki sumber dayanya sendiri. Lihat torsinya, lipatannya lebih baik daripada Sand Kraken di luar sana.",
  str_voice_1500751_5 = "Oh, tidak. Kabel-kabelnya kusut lagi, mampus! Hmm… Kenapa kau lesu? Hah! Lihat? Sudah kubilang kau dalam masalah!",
  str_voice_1500751_6 = "Saluran komunikasi jelek siapa ini? Ya, aku meretasnya. Kau mau apa? Lacak sinyal balik ke tempatku atau diamlah!",
  str_voice_1500751_7 = "Menurutmu, dengan memiliki Colossus kau akan menjadi orang penting? Berhenti pamer. Ayo selesaikan masalahnya di luar. Aku akan mengubahnya menjadi tumpukan besi tua!",
  str_voice_1500751_8 = "Aku, tak berperasaan? Aku terus mengingatkanmu untuk mengatur waktu dan memotivasi kau untuk belajar dengan giat agar kau tidak lagi dirundung di luar sana!",
  str_voice_1500751_9 = "Aku suka kau, teman. Aku akan melatihmu cara bicara supaya kau tidak dipermalukan dalam perdebatan.",
  str_voice_1500751_10 = "Kabel sudah siap dan komunikasinya sudah diperiksa. Maafkan sikapku yang blak-blakan, semua orang di sini tak lain hanyalah… Apa-apaan… Kenapa jadi kacau lagi? Bug apa lagi kali ini?",
  str_voice_1500751_11 = "Ya, aku akan meretas semua saluran komunikasi dalam radius 16 km untukmu hari ini… Apa? Tidak perlu? Namun, aku hampir selesai mengerjakannya…",
  str_voice_1500751_12 = "Terkurung di sini mengingatkanku pada kadal lumpuh di Rediesel dan keluhan gadis konyol itu… Merepotkan sekali.",
  str_voice_1500751_13 = "Mereka bahkan tidak menggeliat sebaik kabelku… Bagaimana kalau berusaha sedikit keras lagi, kawan?",
  str_voice_1500751_14 = "Para badut di tim itu selalu merusak peralatan mereka. Tidak ada kata \"merawat\" dalam kamus mereka.",
  str_voice_1500751_15 = "Hari ini, aku akan menunjukkan kepadamu kekuatan dari seorang teknisi! Kau ingin acara ulang tahun yang seperti apa? Yang menarik atau menyenangkan?",
  str_voice_1500751_16 = "Aku tahu kau akan kembali dua menit lima belas detik yang lalu. Ini adalah teknologi komunikasi seorang genius, tahu?",
  str_voice_1500751_17 = "Bagaimana cara menghentikan Colossus payah ini? Wow, kenapa bergoyang sekarang?",
  str_voice_1500751_18 = "Ada masalah apa? Aku akan mengatasinya, mudah saja… Ups, aku tak akan melakukannya, kau saja yang lanjutkan!",
  str_voice_1500751_19 = "Kau datang tepat waktu, ada yang berceloteh di sistem komunikasi… Orang itu ingin melawanmu di Gannon City!",
  str_voice_1500751_20 = "Kenapa aku bergabung dengan Rediesel Wrench? Tidak mudah meringkas ceritanya, tapi aku sudah berada di sana untuk waktu yang lama hingga akhirnya aku menetap.",
  str_voice_1500751_21 = "Bagaimana kalau melakukan quest, mungkin seperti meretas sistem komunikasi Illumina… Apa yang perlu ditakuti? Kita hanya mencari bug di sistemnya untuk mereka.",
  str_voice_1500751_22 = "Kami Rediesel tidak pernah takut pada siapa pun!",
  str_voice_1500751_23 = "Akan kubongkar tiap Eclipsite yang terlihat hingga tak ada yang tersisa, bahkan debunya!",
  str_voice_1500751_24 = "Beri tahu Brock untuk menjauh dariku. Hanya besi tua dan kepalanya yang tidak bisa kuperbaiki.",
  str_voice_1500751_25 = "Katakan padanya untuk mencoba jika baginya dia sehebat itu! Lihatlah betapa sombongnya dia meskipun Tiny One dan aku yang mengerjakan semua perbaikan untuk Rediesel!",
  str_voice_1500751_26 = "Baik, semua instalasi berfungsi. Ambilkan aku makanan berkalori tinggi untuk mengisi kembali energiku.",
  str_voice_1500751_27 = "Bug adalah hal terparah, dan jika kau menambahkan kacamata yang hilang… Aku akan menggila.",
  str_voice_1500751_28 = "Heh, Colossus milikmu ini sama sekali bukan barang rongsokan… Semua bagian dalamnya utuh dan berfungsi sepenuhnya! Aku jadi tertarik!",
  str_voice_1500751_29 = "Mulai sekarang, tunjukkan saja namaku, Odi, kalau ada seseorang yang memutuskan untuk mengacaukan sistem komunikasimu. Namaku akan membuat mereka ketakutan!",
  str_voice_1500751_30 = "Perangkat sudah ditingkatkan, mudah sekali.",
  str_voice_1500751_31 = "Apakah itu bisa selesai dalam hitungan detik?",
  str_voice_1500751_32 = "Bukankah seperti biasa… Ditingkatkan, tentu saja!",
  str_voice_1500751_33 = "Buat dirimu berguna… Ya, itu jawaban dari buku panduan!",
  str_voice_1500751_34 = "Ayo kita serang saja.",
  str_voice_1500751_35 = "Katakan padaku, siapa yang mendapatkannya kali ini?",
  str_voice_1500751_36 = "Lalu kenapa? Langsung hajar mereka.",
  str_voice_1500751_37 = "Ups, kabelnya kacau lagi!",
  str_voice_1500751_38 = "Aku tak bisa menyalakannya! Hah? Apakah benda itu baru saja merusak dirinya sendiri?",
  str_voice_1500751_39 = "Jangan bergerak!",
  str_voice_1500751_40 = "Serangannya berhasil?",
  str_voice_1500751_41 = "Tunggu dulu, aku yang harusnya memimpin!?",
  str_voice_1500751_42 = "Hah, hanya tumpukan besi tua.",
  str_voice_1500751_43 = "Namun… Usahaku tidak berhasil, aku gagal!",
  str_voice_1500751_44 = "Hanya ini yang kau punya… Waow, jangan tiba-tiba berdiri mendekat!",
  str_voice_1500751_45 = "Aku tahu kau tak ahli dalam memilih hadiah.",
  str_voice_1500751_46 = "Aku tahu kau… ahli dalam memilih hadiah!",
  str_voice_1500751_47 = "Aku tahu kau akan memberiku benda ini.",
  str_voice_1500751_48 = "Kau sangat berbakat dan kau paling mengerti aku!",
  str_voice_1500751_49 = "Tak ada bagian mesin yang tak bisa kuperbaiki. Kalau pun ada, itu pasti besi rongsok yang tak ada gunanya sama sekali!",
  str_voice_1500751_50 = "Mobil rongsok, senjata rongsok, Rediesel rongsok… Sudah tak terhitung lagi berapa banyak rongsokan yang kuperbaiki. Serahkan saja rongsokan apa pun yang kau punya kepadaku.",
  str_voice_1500751_51 = "Aku dibesarkan dalam hal teknologi, pertukaran sipil, dan toleransi… S-siapa yang membuat masalah? Aku akan membuat mereka menyesali hari mereka dilahirkan!",
  str_voice_1500751_52 = "Alchemy Stars.",
  str_voice_1500751_53 = "Halo?",
  str_voice_1500751_54 = "Apa kau masih terjaga?",
  str_voice_1500751_55 = "Ayo mulai pembahasannya!",
  str_voice_1500751_56 = "Kau sedang di tempat tidur? Aku tak percaya!",
  str_voice_1500751_57 = "Simpan saja dan sampai jumpa tahun depan!",
  str_voice_1500921_1 = "Law adalah prinsip yang mengatur segala sesuatu di alam semesta, jadi apakah sulit untuk memahami alasanku menegakkannya? Sebenarnya sederhana, karena di situlah letak tujuan kebijaksanaan kita.",
  str_voice_1500921_2 = "Maksud dari sanggahan adalah untuk menunjukkan kesalahan cara yang dilakukan orang lain. Ini adalah kualitas unggul yang harus diterapkan secara fisik pada kesempatan tertentu, seperti mereformasi individu tertentu yang tidak memiliki penyesalan!",
  str_voice_1500921_3 = "Angka \"1\", kau bilang? Tidak, tidak, maksudku kata \"satu.\" Apa bedanya? Jangan bilang kau tidak tahu bedanya antara angka dan huruf.",
  str_voice_1500921_4 = "Secara teknis, Hunting Stone bukanlah sebuah roda, melainkan sebuah relik di suatu reruntuhan… Namun, itu tetap sebuah roda!",
  str_voice_1500921_5 = "Law adalah mercusuar yang memandumu dalam kegelapan. Mulai sekarang, lakukan pencarian jiwa dan renungkan keberadaan seperti apa yang kauinginkan!",
  str_voice_1500921_6 = "Bintang yang turun, relik masa lalu yang tak bernama, roda duri yang disebut \"Hunting Stone\"… Kejar aku dengan kegigihan seperti yang ditentukan oleh Law.",
  str_voice_1500921_7 = "Kembalikan barang-barang ke tempatnya, menurut ukuran dan urutan abjad… Tak apa, aku sudah melakukannya untukmu.",
  str_voice_1500921_8 = "Yang benar saja. Kenapa aku harus pergi denganmu hanya karena kau yang menyuruh? Aku akan ikut denganmu saat kau tidak ingin aku untuk ikut! Paham?!",
  str_voice_1500921_9 = "Tidak mudah melacakmu. Sekarang aku perlu mencari tahu kau harus diapakan… Dan aku akan memanfaatkan waktuku sebaik mungkin selama aku tinggal!",
  str_voice_1500921_10 = "Kau ikut denganku atau aku akan membawamu. Terserah kau, atau aku bisa memilihnya untukmu… Akan kuanggap diam sebagai \"Ya\"!",
  str_voice_1500921_11 = "Sebaiknya kau tidak lari di depanku atau aku akan mengejarmu karena instingku. Ya, jangan membelakangiku… Jangan terus menatapku, tapi juga jangan berpaling dariku!",
  str_voice_1500921_12 = "Tidakkah kau menganggap ini buruk? Apa hanya aku yang menganggap ini sama sekali tidak ada artinya?",
  str_voice_1500921_13 = "Kenapa aku tidak menyerah? Karena aku tidak pernah menyerah. Katakan padaku, apakah ada alasan lain?",
  str_voice_1500921_14 = "Tahu mana yang benar dan salah, tetap merendah, dengan pandangan ke masa depan!",
  str_voice_1500921_15 = "Hadiah, ucapan selamat, dan nyanyian… Aku ingin semua itu tertata rapi untuk hari ini!",
  str_voice_1500921_16 = "Karena kau sudah kembali, haruskah kita melakukan sesuatu? Maksudku, mau apa lagi kau di sini?",
  str_voice_1500921_17 = "Kau pasti punya jadwal yang lengkap! … Apa? Kau tidak punya?",
  str_voice_1500921_18 = "Aku bahkan lebih keras kepala dari yang kaubayangkan. Tunggu sampai kau ingin lari menjauh saat bertemu denganku suatu hari.",
  str_voice_1500921_19 = "Kau harus mengikuti jadwalmu, misalnya sekarang saatnya kau untuk istirahat… Hah? Bukan seperti itu?",
  str_voice_1500921_20 = "Karena sudah memutuskan untuk bergabung, aku harus mematuhinya hingga akhir. Jangan khawatir, aku akan menyelamatkanmu atas nama Truth.",
  str_voice_1500921_21 = "Kalau begitu, mari kita menuju Cloudward, pelan-pelan saja. Ini tidak sulit…",
  str_voice_1500921_22 = "Menurutku, seharusnya yang benar, \"Semoga Truth memberkatimu\"!",
  str_voice_1500921_23 = "Wow, benar-benar sulit dipercaya… Apakah kita akan membiarkan siapa pun mengambil nyawa begitu saja?",
  str_voice_1500921_24 = "Atas titah dari Supreme Being, aku di sini untuk… Apa? Kau bahkan tak tahu itu siapa?",
  str_voice_1500921_25 = "Tidak harus mewah. Komentarku yang blak-blakan saja bisa mengubah senyum pria itu menjadi kemuraman.",
  str_voice_1500921_26 = "Ketekunan… Tunggu, apa artinya \"suka\"? Barang-barang? Hobi? Keyakinan?",
  str_voice_1500921_27 = "Tidak hanya jauh dari rupawan, tapi juga tidak disiplin, tanpa tujuan, dan juga tidak termotivasi… Bagaimana aku bisa tahan dengan orang seperti itu?",
  str_voice_1500921_28 = "Tentu saja aku tahu apa itu Colossus! Itu artinya kau ini orang yang spesial, 'kan?",
  str_voice_1500921_29 = "Aku harus menyebutkan namaku hanya karena kau memintanya? Kau tidak takut aku bohong? Bagaimana kalau aku tidak mau memberitahumu? Oh, kau tidak tertarik lagi? Kalau begitu, namaku 'Pact'.",
  str_voice_1500921_30 = "Selesai. Berikutnya.",
  str_voice_1500921_31 = "Suatu hari nanti aku akan menyingkirkan Hunting Stone… Suatu hari!",
  str_voice_1500921_32 = "Law sama dengan Truth, paham?!",
  str_voice_1500921_33 = "Tidak ada yang terlalu luas hingga bisa tersesat di dalamnya.",
  str_voice_1500921_34 = "Kenapa kau ingin aku ada di sini?",
  str_voice_1500921_35 = "Aku tak pernah bilang sudah siap!",
  str_voice_1500921_36 = "Memberitahumu? Mana mungkin!",
  str_voice_1500921_37 = "Paksaan? Tidak, itu ketekunan!",
  str_voice_1500921_38 = "Patuhi Law dan jangan pernah goyah!",
  str_voice_1500921_39 = "Berhenti!",
  str_voice_1500921_40 = "Kita lihat saja hasilnya!",
  str_voice_1500921_41 = "Dengar, jangan pernah melanggar Law.",
  str_voice_1500921_42 = "Orang-orang yang melanggar Law akan dihukum!",
  str_voice_1500921_43 = "Kejar mereka dan jangan sampai lepas…",
  str_voice_1500921_44 = "Kau ingin mengobrol? Tentu saja, asal kau berjanji untuk tidak akan marah, tak peduli apa yang kukatakan.",
  str_voice_1500921_45 = "Tidak ada yang terlalu kecil atau terlalu besar.",
  str_voice_1500921_46 = "Jika harus menunjukkan bahwa aku menyukainya, bukankah itu akan, kau tahu…",
  str_voice_1500921_47 = "Terlalu… lagi pula kau tak bisa mengambil kembali hadiah…",
  str_voice_1500921_48 = "Ya, aku memang menyukainya. Bagimu ini apa?",
  str_voice_1500921_49 = "Hampir tidak bisa dihancurkan, regenerasi kuat, terus kembali di mana pun itu dibuang… Ini adalah Hunting Stone yang tangguh!",
  str_voice_1500921_50 = "Percaya pada Law yang sederhana, andalkan dan pertahankan ketertiban, patuhi tekad batinmu, bersikap tegas dan sungguh-sungguh, itulah langkah pertama menuju Truth yang agung!",
  str_voice_1500921_51 = "Untuk apa seseorang hidup dan berjuang? Aku mendapat jawabanku di suatu malam ketika aku mendongak dan melihat bintang-bintang menerangi kegelapan.",
  str_voice_1500921_52 = "Alchemy Stars!",
  str_voice_1500921_53 = "Sebuah pengingat.",
  str_voice_1500921_54 = "Kau punya waktu 3 detik untuk membalas.",
  str_voice_1500921_55 = "Kau seharusnya di sini sekarang.",
  str_voice_1500921_56 = "Hanya memastikan kau sudah di tempat tidur.",
  str_voice_1500921_57 = "Ayo, kita ucapkan bersama, \"Selamat Tahun Baru\"!",
  str_voice_1600061_1 = "Lebih sulit untuk membuat keputusan ketika ada banyak orang. Pikiran jauh lebih jernih ketika kita sendirian.",
  str_voice_1600061_2 = "Saat berdiri di tengah Hall of Justice dan Elder Council, kita harus tahu dulu posisi kita sebelum bisa mengambil tindakan yang tepat.",
  str_voice_1600061_3 = "Meskipun tidak ingin perjamuan ini berakhir lebih awal, aku lebih enggan menyia-nyiakan tengah malam yang indah ini, saat otak berada di kondisi paling jernih.",
  str_voice_1600061_4 = "Kekuasaan dibutuhkan di masa lalu dan ketertiban dibutuhkan di masa kini. Meskipun aku benci mengakuinya, ini adalah sesuatu yang dia ajarkan kepadaku.",
  str_voice_1600061_5 = "Kepercayaan penduduk Lumopolis kepadanya masih baru. Ia pasti tidak mau mengujinya dengan kekuatan, terutama di masa kekacauan ini. Aku yakin Ibu juga sependapat denganku.",
  str_voice_1600061_6 = "Black Spider? Itu hanya desas-desus membosankan yang digunakan untuk meredam rasa sakit dalam kehidupan nyata. Jika itu ada, para Guardian pasti sudah menangkapnya sejak lama.",
  str_voice_1600061_7 = "Kepercayaan biasanya menjadi tempat berkembang biaknya pengkhianatan. Namun, Yang Mulia tampaknya berbeda dari orang-orang lain di luar sana. Aku jarang salah menilai tentang orang.",
  str_voice_1600061_8 = "Makin banyak retakan pada es akan membuatnya makin rapuh, begitu pula dengan Lumopolis… Kau pasti sudah bisa mengetahuinya lebih awal.",
  str_voice_1600061_9 = "Saling mengakui dan menghormati adalah hal yang paling langka. Aku bertekad untuk membawa warisan ini ke puncak dan berharap kau akan menyaksikannya.",
  str_voice_1600061_10 = "Jika mau, masih ada misi yang harus kauselesaikan. Namun, kau sedang sangat tidak bersemangat… Argh, toh tidak ada yang menghargaimu.",
  str_voice_1600061_11 = "Tempat yang sangat indah. Kuharap wibawamu akan melengkapi keindahan tempat ini.",
  str_voice_1600061_12 = "Toleransi kini tidak mewakili kepuasan dengan keadaan saat ini.",
  str_voice_1600061_13 = "Ada yang ingin kau diskusikan denganku? Kau bisa berpikir lebih jernih dengan bantuanku…",
  str_voice_1600061_14 = "Jika kau bertemu dengan Guardian… Semoga Raphael tidak menyusahkanmu.",
  str_voice_1600061_15 = "Hari ini ulang tahunmu. Semoga kau menjadi lebih kuat.",
  str_voice_1600061_16 = "Aku sudah dapat arahan. Kapan kita bergerak?",
  str_voice_1600061_17 = "Bagus. Ayo bersiap untuk beraksi.",
  str_voice_1600061_18 = "Sebagian besar pekerjaan sudah selesai. Kita perlu menyusun laporan.",
  str_voice_1600061_19 = "Istirahatlah. Besok pasti ada banyak hal yang menunggu untuk kau selesaikan.",
  str_voice_1600061_20 = "Lumopolis akan menciptakan masa depan baru untuk benua ini. Karenanya, kami akan terus bekerja keras.",
  str_voice_1600061_21 = "Illumina, kekuatan yang melawan kegelapan, adalah kekuatan yang harus diperhitungkan.",
  str_voice_1600061_22 = "Demi White Night!",
  str_voice_1600061_23 = "Eclipsite adalah kegelapan yang berakar di dunia ini. Untuk menyelamatkan semua, mereka harus dimusnahkan.",
  str_voice_1600061_24 = "Kuharap Raphael berhenti memanggilku kakak perempuan. Aku tidak setua itu.",
  str_voice_1600061_25 = "Gabriel melakukan tugasnya, tapi dia tak begitu bersemangat. Kuharap dia akan lebih berkomitmen pada pekerjaannya.",
  str_voice_1600061_26 = "Apa yang aku suka? Sederhana saja. Seni perang, menonton kompetisi… dan suguhan susu.",
  str_voice_1600061_27 = "Aku tidak suka orang yang tidak tahu waktu. Tolong ingat itu.",
  str_voice_1600061_28 = "Colossus ini sangat lengkap dan mungkin bisa membawa… Tidak, lupakan saja.",
  str_voice_1600061_29 = "Aku Carleen de Schwartz, penjaga Lumopolis, dan putri dari Schwartz, sang City Lord. Kota indah ini tidak akan pernah mengalami lagi kekejaman masa lalu di bawah pengawasanku.",
  str_voice_1600061_30 = "Tombakku setajam biasanya!",
  str_voice_1600061_31 = "Mulai sekarang, tidak akan ada tempat bagi kegelapan untuk bersembunyi.",
  str_voice_1600061_32 = "Tombakku akan menusuk langit malam.",
  str_voice_1600061_33 = "Ikuti perintahku. Kita hanya maju ke depan!",
  str_voice_1600061_34 = "Aku siap.",
  str_voice_1600061_35 = "Serangan berikutnya akan menembus jantung.",
  str_voice_1600061_36 = "Kau tak perlu bertanya tiap saat!",
  str_voice_1600061_37 = "Kegelapan menyurut!",
  str_voice_1600061_38 = "Terima bunga es di langit yang membeku ini!",
  str_voice_1600061_39 = "Menyebarlah! Bunga es!",
  str_voice_1600061_40 = "Tusuk musuh-musuh itu!",
  str_voice_1600061_41 = "Masih ada kesempatan untuk melawan. Serang dengan kecepatan!",
  str_voice_1600061_42 = "Menang lagi, sesuai perkiraan.",
  str_voice_1600061_43 = "Jangan putus asa. Kegagalan akan menjadi pijakan kita.",
  str_voice_1600061_44 = "Jika kau di sini hanya untuk mengobrol, harap perhatikan jamnya.",
  str_voice_1600061_45 = "Kuharap kau tidak melakukan ini untuk tujuan terselubung.",
  str_voice_1600061_46 = "Siapa yang menyangka aku bisa mendapatkan yang kubutuhkan dari kau… Terima kasih.",
  str_voice_1600061_47 = "Terima kasih. Aku tahu niatmu baik.",
  str_voice_1600061_48 = "Kau selalu tahu apa yang kubutuhkan. Terima kasih.",
  str_voice_1600061_49 = "Aku sudah mencoba untuk mengenalnya… Maksudku ayahku, penguasa Lumopolis. Maaf, tapi aku belum terbiasa memanggilnya dengan sebutan itu karena beberapa kejadian di masa lalu yang tak terlupakan…",
  str_voice_1600061_50 = "Luka lama sembuh dengan perlahan. Tak ada lagi yang tertarik untuk menggali masa lalu kota ini. Terlalu banyak yang sudah terjadi selama dekade terakhir. Beberapa tragedi menimpa keluargaku, tapi tak seorang pun mau memberitahuku yang sebenarnya…",
  str_voice_1600061_51 = "Hawanya terasa dingin di malam yang tenang ini. Sekarang aku hanya bisa menghidupkan kembali masa lalu dengan melihat potret keluargaku. Konyol, ya? Tidak, ini menyedihkan. Rahasia apa yang ada di pusat kota ini?…",
  str_voice_1600061_52 = "Alchemy Stars.",
  str_voice_1600061_53 = "Permisi.",
  str_voice_1600061_54 = "Selamat pagi.",
  str_voice_1600061_55 = "Selamat sore.",
  str_voice_1600061_56 = "Meskipun terlambat.",
  str_voice_1600061_57 = "Selamat Tahun Baru.",
  str_voice_1600141_1 = "Lumopolis, tempat keyakinan kita dipertahankan, tidak akan pernah jatuh! Berapa pun banyaknya Darkover Crisis yang akan menimpa kita!",
  str_voice_1600141_2 = "Tidak ada hierarki, tidak ada tatanan sosial… Bagaimana cara mengatur tempat ini? Dengan ikatan dan pengekangan? Yah, kita tunggu dan lihat saja nanti.",
  str_voice_1600141_3 = "Lumopolis adalah nova di bawah Aurora, pelabuhan abadi. Kau tak akan pernah mengerti perasaanku padanya.",
  str_voice_1600141_4 = "Aku jadi bernostalgia karena merasakan kebaikan dan keharmonisan tempat ini. Aku rindu saat-saat damai, saat-saat bersama Joshua… saat-saat kita tidak harus selalu waspada…",
  str_voice_1600141_5 = "Anak-anakku… Jika mereka memutuskan untuk bersumpah, aku hanya berharap kalian bisa bertanggung jawab. Jika gagal, aku akan menghancurkan kalian.",
  str_voice_1600141_6 = "Terkadang penguasa tertinggi harus meluapkan amarah, tapi pada saat yang sama menunjukkan kemurahan dan kebaikan hati.",
  str_voice_1600141_7 = "Kenali dirimu sendiri dan kenali musuhmu, jangan sampai kau berakhir sebagai orang bodoh yang tak tahu apa-apa. Kau sudah makin baik, tapi perjalananmu masih panjang.",
  str_voice_1600141_8 = "Rediesel Wrench dan Illumina adalah bahaya yang tersembunyi, tapi Eclipse… Maaf, ada beberapa informasi yang belum bisa aku bagikan denganmu.",
  str_voice_1600141_9 = "Apakah Colossus ini ada di kepalamu? Tampaknya kau memiliki konstitusi yang sama persis dengannya. Betapa jahatnya takdir yang telah menarik kita semua ke dalam pusaran kekacauan ini…",
  str_voice_1600141_10 = "Pasokan, pengiriman, pengerahan pasukan, jarak pandang, rute, perencanaan… Benar-benar kacau, sesuai dugaan.",
  str_voice_1600141_11 = "Aku tak berkewajiban membantumu dengan Colossus ini. Biarkan ini menjadi kesempatan untuk memuja dan aku akan mencoba untuk menjaga kesabaranku.",
  str_voice_1600141_12 = "Kata-kata itu seperti angin, tapi juga bisa menjadi pedang yang tajam… Kenapa harus menggunakan kekuatan militer jika kau bisa mengalahkan musuhmu dengan kekuatan kata-kata?",
  str_voice_1600141_13 = "Pemenang tidak perlu menjelaskan kemenangan mereka, dan pecundang tidak perlu membuat alasan.",
  str_voice_1600141_14 = "Terkadang bentuk akhir dari kecerdasan adalah saat kau harus menyembunyikannya.",
  str_voice_1600141_15 = "Ini hari ulang tahunmu? Kalau begitu, kau boleh libur.",
  str_voice_1600141_16 = "Kata mereka kau bisa berbicara dengannya. Apakah aku juga bisa…?",
  str_voice_1600141_17 = "Selamat datang kembali, Master Colossus.",
  str_voice_1600141_18 = "Seseorang yang bisa mengendalikan makhluk raksasa seperti itu pastilah orang yang luar biasa.",
  str_voice_1600141_19 = "Tidak perlu melihat semuanya sendiri. Serahkan padaku.",
  str_voice_1600141_20 = "Apa pun yang terjadi, aku akan melindungi Lumopolis karena dia adalah bagian dari keluargaku.",
  str_voice_1600141_21 = "Seorang pembela yang baik bisa menyembunyikan kekuatannya dari musuh. Ini adalah strategi dari Illumina Federation—untuk bertahan dan melakukan serangan balasan.",
  str_voice_1600141_22 = "Demi White Night.",
  str_voice_1600141_23 = "Eclipse adalah musuh yang mengerikan, tapi pada akhirnya akan jatuh dengan kekuatan Lumopolis.",
  str_voice_1600141_24 = "Carleen harus bekerja lebih keras jika dia menginginkan bantuanku. Ini adalah takdirnya.",
  str_voice_1600141_25 = "Istvan harus tahu aku juga mengawasinya… Jadi, ada dua sekarang.",
  str_voice_1600141_26 = "Ketertiban adalah landasan peradaban dan keluarga adalah unit dasar di sini. Tidak akan ada negara tanpanya.",
  str_voice_1600141_27 = "Tidak ada yang lebih bodoh dari argumen yang tidak berguna. Tindakan tepat waktu—inilah yang meyakinkan.",
  str_voice_1600141_28 = "Besarnya Colossus ini… Mungkin kita harus menyiapkan tempat khusus untuk menampungnya.",
  str_voice_1600141_29 = "Pengenalan yang tepat adalah tanda sopan santun—aku Duke Schwartz, penguasa Lumopolis. Pasti banyak yang bisa kita bicarakan.",
  str_voice_1600141_30 = "Menarik.",
  str_voice_1600141_31 = "Demi White Night.",
  str_voice_1600141_32 = "Kau selalu diterima di Lumopolis saat kau sedang membutuhkannya.",
  str_voice_1600141_33 = "Lumopolis membimbing semua makhluk.",
  str_voice_1600141_34 = "Pergi berperanglah denganku.",
  str_voice_1600141_35 = "Aku bisa melakukannya sekali lagi—",
  str_voice_1600141_36 = "Ayo mulai!",
  str_voice_1600141_37 = "Ambil batu nisanmu!",
  str_voice_1600141_38 = "Aku akan mengguncang semua bintang!!",
  str_voice_1600141_39 = "Sovereign's Blade!",
  str_voice_1600141_40 = "Lumopolis! Tolong lindungi kami!",
  str_voice_1600141_41 = "Aku sudah lama tidak bertempur langsung!",
  str_voice_1600141_42 = "Aku komandannya! Buat apa kita kalah?",
  str_voice_1600141_43 = "Suatu hari nanti, semua kegagalan itu menjadi tanda kemenangan.",
  str_voice_1600141_44 = "Hmm… Inti ini benar-benar menarik.",
  str_voice_1600141_45 = "Terima kasih atas hadiahmu. Maafkan aku karena tidak bisa membalasnya.",
  str_voice_1600141_46 = "Hadiah yang sangat berharga… Keluarga Schwartz menerimanya.",
  str_voice_1600141_47 = "Ini… tak ternilai harganya.",
  str_voice_1600141_48 = "Aku akan mewariskannya kepada keturunanku sebagai harta keluarga.",
  str_voice_1600141_49 = "Kau mungkin tidak akan pernah mendengar seluruh cerita tentang asal-usul Lumopolis, faksi bangsawan, dan rahasia keluarga Schwartz.",
  str_voice_1600141_50 = "Aku sudah menghabiskan seluruh hidupku untuk terus berupaya menjaga kemakmuran Lumopolis… Bukan untuk diriku sendiri, tapi untuk rakyat. Percaya atau tidak.",
  str_voice_1600141_51 = "Joshua, Carleen, dan… Lupakan… Kita akan ketinggalan jika terus meratap.",
  str_voice_1600141_52 = "Alchemy Stars.",
  str_voice_1600141_53 = "Master dari Colossus.",
  str_voice_1600141_54 = "Mari kita bersyukur atas ketertiban karena pagi ini tidak akan ada tanpanya.",
  str_voice_1600141_55 = "Jadilah orang yang tekun, Order Keeper.",
  str_voice_1600141_56 = "Kau pasti masih terjaga.",
  str_voice_1600141_57 = "Simpan kata-katanya… Rayakanlah!",
  str_voice_1600291_1 = "Oh-ho… Langit yang suram tercipta untuk melamun… Namun, sulit untuk melihat matahari bahkan jika awan gelapnya terkikis.",
  str_voice_1600291_2 = "Fotosintesis sedang berlangsung… Eh, aku bukan siswa SMA, lho! Aku sudah… Ups, aku tidak bisa memberitahumu umurku. Kalau kau sampai tahu… aku harus membungkammu.",
  str_voice_1600291_3 = "Sudah selesai untuk hari ini, semua berkat bantuan polisi! Oh! Omong-omong, dia meninggalkan pesan untukku, tapi dia hanya menyumpahiku sepanjang waktu. Hahaha…",
  str_voice_1600291_4 = "Sangkar ini… dibuat lebih untuk melindungimu daripada memenjarakanku… Oh-ho, bilang apa aku ini…",
  str_voice_1600291_5 = "Tak henti-hentinya aku merasa ada seseorang yang terlihat sangat familier di sini. Oh, aku tidak membicarakanmu… Kau lebih dari sekadar familier bagiku. Ahhh… Berpikir memang bentuk latihan yang menguras tenaga…",
  str_voice_1600291_6 = "Angin, hutan, dan waktu bertiup dari masa lalu… kenanganku bangkit kembali dan terbang keluar dari penjara yang sangat bagus ini!",
  str_voice_1600291_7 = "Sepertinya kau sangat peduli padaku. Aku sudah menyerahkan semua pekerjaan yang Carleen tugaskan untukku kepada anak itu, jadi kita bisa mengobrol tanpa diganggu!",
  str_voice_1600291_8 = "Aku punya hadiah untukmu! Ini… Oh-ho, tidak ada di sini. Maaf, ingatanku jadi samar-samar—ingatanku, jadi samar-samar…",
  str_voice_1600291_9 = "Aku sudah berpikir… Tak ada salahnya kalau aku membuka sangkarnya sedikit untukmu, 'kan? Namun, bagaimana kalau kejadian itu terulang lagi… Hmm? Apa yang terjadi sebelumnya? Kok aku tiba-tiba lupa, ya.",
  str_voice_1600291_10 = "Sepertinya kau sedang bersantai. Ternyata kita kompak, ya.",
  str_voice_1600291_11 = "Oh-ho, lumayan juga di sini. Pemandangannya bagus dan suhu Sol Reactor pas—cocok sekali untuk… tidur…",
  str_voice_1600291_12 = "Hmm… Barusan Carleen memintaku melakukan apa, ya? Aku lupa.",
  str_voice_1600291_13 = "Oh-ho, apa maumu? Angin sudah memberitahuku bahwa kau akan datang.",
  str_voice_1600291_14 = "Kau bisa memberitahuku apa saja yang ingin kau katakan dan aku akan mendengarkan… Hah? Aku benar-benar akan mendengarkan.",
  str_voice_1600291_15 = "Ulang tahun… Hmm… Hmm… Kita perlu menyanyikan lagu ulang tahun, 'kan? Selamat ulang tahun♪",
  str_voice_1600291_16 = "Kau kembali! Jangan terlalu sibuk begitu.",
  str_voice_1600291_17 = "Matahari sudah terbit? Kau benar-benar pekerja keras, ya!",
  str_voice_1600291_18 = "Zzz… Oh-ho, hampir saja aku tertidur. Tak apa, 'kan? Kurasa tidak akan ada yang tahu.",
  str_voice_1600291_19 = "Zzz… Hah? Tidak apa-apa, mataku masih terbuka, kok… Aku masih… terjaga…",
  str_voice_1600291_20 = "Lumopolis memperlakukanku dengan baik saat aku pertama kali tiba di sini. Aku berterima kasih kepada mereka dan berharap mereka bisa menikmati kedamaian.",
  str_voice_1600291_21 = "Orang yang membantuku… berasal dari Illumina. Aku akan mengingatnya… Aku janji.",
  str_voice_1600291_22 = "Demi White Night!",
  str_voice_1600291_23 = "Bagaimana jika kuberi tahu kalau makhluk ini bisa membuatku ingat rasa marah? Apakah kau akan terkejut?",
  str_voice_1600291_24 = "Dia hanyalah anak nakal saat aku pertama kali tiba… Oh-ho, itu saja yang bisa kukatakan.",
  str_voice_1600291_25 = "Raphael kecil pandai dalam hal menyembuhkan dan melakukan pekerjaannya, tapi kemampuan memasaknya… Ahahah.",
  str_voice_1600291_26 = "Lebih baik tidur siang di samping Sol Reactor yang hangat, di bawah sinar matahari yang nyaman.",
  str_voice_1600291_27 = "Hmm… Bagaimana rasanya tidak menyukai? Aku tidak begitu ingat.",
  str_voice_1600291_28 = "Oh-ho, pertama kali aku melihatnya, kupikir itu sedikit mirip sangkarku.",
  str_voice_1600291_29 = "Oh-ho, jadi kau orang yang diperbincangkan itu… Aku Gabriel. Yang lain tak penting… Kita masih punya waktu yang lama bersama nantinya, sepanjang sore di musim semi…",
  str_voice_1600291_30 = "Kenapa kau harus terburu-buru?",
  str_voice_1600291_31 = "Sangkarnya… bergetar.",
  str_voice_1600291_32 = "Kenangan-kenangan tumbuh—",
  str_voice_1600291_33 = "Sangkarnya hilang…",
  str_voice_1600291_34 = "Gaduh sekali!",
  str_voice_1600291_35 = "Musim semi akan tiba.",
  str_voice_1600291_36 = "Sekarang terserah padamu, utusanku—",
  str_voice_1600291_37 = "Tumbuhlah sesukamu!",
  str_voice_1600291_38 = "Tiupkan! Angin musim semi yang segar!",
  str_voice_1600291_39 = "Oh, maaf?",
  str_voice_1600291_40 = "Tidak termaafkan!",
  str_voice_1600291_41 = "Oh-ho, kadang-kadang aku harus memimpin dengan memberikan contoh.",
  str_voice_1600291_42 = "Kebahagiaan adalah yang terpenting.",
  str_voice_1600291_43 = "Oh-ho, kita tersesat. Mau kembali untuk minum teh?",
  str_voice_1600291_44 = "Mau tidur siang bersama? Tidur terasa sangat nyaman! Kosongkan saja pikiranmu dan mengangan-anganlah…",
  str_voice_1600291_45 = "Ini untukku? Tidak, bukannya aku tidak menyukainya…",
  str_voice_1600291_46 = "Oh-ho! Ini menarik! Aku jadi lebih bersemangat sekarang.",
  str_voice_1600291_47 = "Terima kasih, ini hadiah yang bagus!",
  str_voice_1600291_48 = "Oh-ho! Hm, kok kau tahu aku paling suka yang ini?",
  str_voice_1600291_49 = "Aku mengalami perang itu, tapi tidak benar-benar tahu apa yang terjadi. Apakah itu pernah terjadi? Kurasa begitu… Kepalaku sedikit pusing sekarang.",
  str_voice_1600291_50 = "Sarangnya pernah rusak… tapi sepertinya seseorang sudah memperbaikinya. Siapa orang itu? Dia seseorang yang tidak asing, sih. Oh, aku tidak bisa mengingatnya.",
  str_voice_1600291_51 = "Jangan menoleh ke belakang. Tidak ada apa-apa di sana kecuali asap abu-abu berkabut dan tepi besi yang dingin. Mungkin kau akan membantuku mengingat semuanya suatu hari nanti…",
  str_voice_1600291_52 = "Alchemy Stars!",
  str_voice_1600291_53 = "Halo!",
  str_voice_1600291_54 = "Aku tak sengaja terbangun karena matahari!",
  str_voice_1600291_55 = "Aku suka matahari sore hari ini.",
  str_voice_1600291_56 = "Karena aku masih belum tidur…",
  str_voice_1600291_57 = "Oh-ho, Selamat Tahun Baru!",
  str_voice_1600641_1 = "Kemenangan yang adil dan jujur adalah satu-satunya cara menuju kemenangan akhir. Cepat atau lambat pengkhianat akan dikhianati.",
  str_voice_1600641_2 = "Red Baron harus dilepaskan sesekali untuk mempertahankan kondisi primanya.",
  str_voice_1600641_3 = "Berikutnya adalah pemeriksaan lengkap Colossus. Aku bisa menjadi orang yang mengeluarkan lebih banyak kekuatan darinya.",
  str_voice_1600641_4 = "Ketakutan mengusir orang yang lemah, tapi membuatku lebih kuat.",
  str_voice_1600641_5 = "Kekuasaan dan status itu harus diraih, bukan diserahkan.",
  str_voice_1600641_6 = "Kau tahu kekuatanku. Aku akan menjalankan misi yang gagal diselesaikan orang lain.",
  str_voice_1600641_7 = "Orang yang berkuasa tidak harus lebih baik dari orang lain. Yang mereka butuhkan hanyalah keberanian untuk mengambil keputusan sulit.",
  str_voice_1600641_8 = "Ambisi adalah bola api yang membakar orang yang lemah tapi membimbing orang yang kuat, seperti aku.",
  str_voice_1600641_9 = "Suatu hari aku akan menjadi Grand Marshal Illumina. Ketika saatnya tiba, wakilku adalah Reinhardt… atau kau.",
  str_voice_1600641_10 = "Tidak ada misi yang harus dilakukan? Kalau begitu, kita akan bermeditasi. Ini juga semacam pelatihan mental.",
  str_voice_1600641_11 = "Dimengerti. Akan kuterima permintaanmu agar kau mendukungku di kemudian hari.",
  str_voice_1600641_12 = "Legion Commander bisa berperilaku santai di luar, tapi harus selalu waspada di dalam.",
  str_voice_1600641_13 = "Kebocoran listrik dari Richthofen? Ah, itu disengaja. Jangan khawatir. Aku memegang kendali penuh.",
  str_voice_1600641_14 = "Memiliki senjata yang kuat tapi tidak memiliki sarana untuk menggunakannya bagaikan bayi dengan sebatang emas yang berkeliaran di jalanan yang ramai.",
  str_voice_1600641_15 = "Sekali ini saja, aku akan menggunakan Red Baron untuk memotong kue ulang tahunmu.",
  str_voice_1600641_16 = "Tetap waspada! Tetap bersemangat!",
  str_voice_1600641_17 = "Pagi! Pekerjaan sudah menunggu!",
  str_voice_1600641_18 = "Masih ada waktu sebelum jam istirahat. Ayo lanjutkan.",
  str_voice_1600641_19 = "Aku tidak lelah. Aku bisa bergadang sepanjang hari bila perlu.",
  str_voice_1600641_20 = "Jujurlah dan jujur—itulah yang diajarkan Federasi Illumina kepada saya. Itu sebabnya saya tidak punya agenda tersembunyi.",
  str_voice_1600641_21 = "Lumopolis tidak punya masa depan karena didirikan di atas keluarga-keluarga bangsawan dan garis keturunan mereka.",
  str_voice_1600641_22 = "Illumina!",
  str_voice_1600641_23 = "Eclipsite? Tak ada yang perlu ditakutkan. Mereka berfungsi sebagai dasar untuk kemajuanku.",
  str_voice_1600641_24 = "Jika ingin mengalahkan Reinhardt, kau harus mengalahkanku lebih dulu.",
  str_voice_1600641_25 = "Vivian adalah bawahan yang sempurna, tapi dia tidak cocok menjadi pemimpin.",
  str_voice_1600641_26 = "Saat kekuatan meningkat, status juga ikut naik.",
  str_voice_1600641_27 = "Orang yang merencanakan kejahatan akan dihancurkan oleh keadilan, sekalipun terlambat.",
  str_voice_1600641_28 = "Kalau saja aku bisa memiliki Colossus di legiunku… Aku akan memiliki angkatan udara.",
  str_voice_1600641_29 = "Calon Grand Marshal dari Illumina, Wrath, sudah tiba. Dukung aku, dan kau akan melihat masa depan yang cerah.",
  str_voice_1600641_30 = "Inilah kekuatan yang pantas kudapatkan.",
  str_voice_1600641_31 = "Mengaum! Richthofen!",
  str_voice_1600641_32 = "Lebih cepat! Red Baron!",
  str_voice_1600641_33 = "Tidak ada yang bisa menghalangiku!",
  str_voice_1600641_34 = "Harusnya aku yang jadi kapten.",
  str_voice_1600641_35 = "Serang! Red Baron!",
  str_voice_1600641_36 = "Overcharge! Red Baron!",
  str_voice_1600641_37 = "Mode overcharge, diaktifkan!",
  str_voice_1600641_38 = "Thunderstrike! Red Baron!",
  str_voice_1600641_39 = "Richthofen!",
  str_voice_1600641_40 = "Red Baron!",
  str_voice_1600641_41 = "Aku ditakdirkan untuk berada di posisi ini.",
  str_voice_1600641_42 = "Ini mudah sekali.",
  str_voice_1600641_43 = "Aduh, kalah oleh stres…",
  str_voice_1600641_44 = "Hmm… Bagaimana cara mengendalikan Colossus yang begitu kuat?",
  str_voice_1600641_45 = "Yah, kau tidak perlu melakukannya.",
  str_voice_1600641_46 = "Bagus. Aku akan mempertimbangkan kembali hubungan kita.",
  str_voice_1600641_47 = "Terima kasih. Aku akan mengingatnya.",
  str_voice_1600641_48 = "Kemurahan hatimu membuatku terharu. Sudah lama sekali aku tidak merasakan ini, terima kasih.",
  str_voice_1600641_49 = "Akulah Legion Commander, bukan karena ikatanku dengan Reinhardt, tapi karena jasaku di medan perang.",
  str_voice_1600641_50 = "Aku mungkin sudah melewatkan pertempuran terakhir dengan para Eclipsite, tapi aku berhasil memusnahkan semua Eclipsite yang berkeliaran! Prestasiku tidak jauh berbeda dengan tiga Legion Commander lainnya.",
  str_voice_1600641_51 = "Terkadang, aku bertanya-tanya apakah aku benar-benar bisa menggantikan Reinhardt. Dialah yang menyelamatkanku saat aku terluka parah…",
  str_voice_1600641_52 = "Alchemy Stars.",
  str_voice_1600641_53 = "Navigator, tolong jawab!",
  str_voice_1600641_54 = "Ini panggilan dari Wrath!",
  str_voice_1600641_55 = "Kau bisa mendengarku?",
  str_voice_1600641_56 = "Meminta panggilan khusus. Ganti.",
  str_voice_1600641_57 = "Sampai ke Tahun Baru!",
  str_voice_1600231_1 = "Oh… Akankah aku bisa mengumpulkan keberanian untuk menyapa orang? Hei, tidak benar-benar menyapa! Tolong berhenti menepukku!!",
  str_voice_1600231_2 = "Apakah ada sudut gelap bagiku untuk menyendiri di Colossus… Aku tidak mau ditemukan oleh siapa pun. Aku belum menyelesaikan itu…",
  str_voice_1600231_3 = "Tentu aku keberatan di sini… Apa? Oh, maaf… maafkan aku! Aku hanya berkeliaran…",
  str_voice_1600231_4 = "Semua orang bisa merasa takut… Jika suatu hari nanti aku bisa menghilangkan rasa takutku, mungkin aku bisa mengetahui rahasia Anton…",
  str_voice_1600231_5 = "Aku mendengarnya lagi, bisikan Anton! Wow! kenapa kau bersandar begitu dekat denganku? Aku tidak bermaksud memanggilmu…",
  str_voice_1600231_6 = "- Connolly.\n- Connolly yang malang dan rapuh. Jangan takut. Kau bisa mendengar kami?\n- Dengarkanlah suara kami. Kami akan menemanimu.\n- Kegelapan yang begitu… lembut. Aku tidak lagi sendirian…",
  str_voice_1600231_7 = "Kau… kau bertanya… dengan siapa… aku baru saja berbicara? Namun… mereka… mereka ada di sini…",
  str_voice_1600231_8 = "Yah… Anton juga sangat menyukainya… Sepertinya kau bisa dipercaya…",
  str_voice_1600231_9 = "Aku selalu berpikir… Jika bersamamu, aku tak akan pernah merasa takut lagi ke mana pun aku pergi. Jadi… bisakah… bisakah kau mendekat?",
  str_voice_1600231_10 = "Nadanya agak aneh… Bukan karena itu membawa perasaan buruk atau apa. Sebaliknya, itu terdengar meyakinkan. Dia tidak akan mengirim orang ke rumah sakit lagi, 'kan? Baiklah.",
  str_voice_1600231_11 = "S-semua orang bilang aku cocok untuk melakukan ini. Benarkah itu? Kenapa rasanya ada lebih banyak mata yang tertuju padaku sekarang…",
  str_voice_1600231_12 = "Aku mendapatkan… bantuan dari orang itu… Begitu pula dengan Dayna, Robyn, dan Hydrad…",
  str_voice_1600231_13 = "Kemampuan khusus Anton… adalah membuat orang tertidur. Aku tiba-tiba merasa sangat mengantuk…",
  str_voice_1600231_14 = "Ini… terlalu terang. Silau sekali… Tidak, aduh, aku harus kembali ke sudut itu…",
  str_voice_1600231_15 = "- Selamat Ulang Tahun!\n- Selamat Ulang Tahun.\n- Se-selamat Ulang Tahun… Navigator…",
  str_voice_1600231_16 = "Hei! Kau… Kau kembali?! Tak apa, tak apa…",
  str_voice_1600231_17 = [[
- Sst! Connolly masih tidur!
- Namun, ini sudah hampir waktunya untuk membuka toko. Apa benar tak apa-apa kalau tidak membangunkannya?]],
  str_voice_1600231_18 = "- Connolly, ayo main domino bersamaku!\n- Anton, aku sedang bekerja… Oh, ada pelanggan!",
  str_voice_1600231_19 = "Pesan kopi di jam-jam seperti ini? Es-Espresso? Seseorang akan kesulitan tidur malam ini…",
  str_voice_1600231_20 = "Di bawah bayangan Azurite, Umbraton adalah campuran antara ketertiban dan kekacauan… Alasan kenapa semua ada di sana.",
  str_voice_1600231_21 = "- Bosan.\n- Tidak menyenangkan.\n- Semua palsu.\n- Hmm…",
  str_voice_1600231_22 = "Bayangan mengawasi…",
  str_voice_1600231_23 = "Makhluk… menakutkan itu… Aku tidak mau melihatnya lagi. Tidak akan pernah…",
  str_voice_1600231_24 = "Dayna tidak bisa minum kopi pahit… tapi dia tetap memesannya setiap saat. Aku selalu menambahkan krim untuknya.",
  str_voice_1600231_25 = "Susu hangat ditambah tiga bongkah gula batu… Yang ini untuk Robyn. Dia selalu diam seperti anak kucing.",
  str_voice_1600231_26 = [[
- Hidangan pencuci mulut cokelat di lemari es sepertinya selalu menghilang tanpa alasan. Kok bisa begitu, ya?
- Nyam, nyam, nyam. Lezat sekali.]],
  str_voice_1600231_27 = "- Dahulu kala, ada sebuah kafe…\n- Aduh!\n- Hah? Aku tidak bercerita tentang kisah hantu!",
  str_voice_1600231_28 = "Kafenya besar sekali… Sebenarnya bisa memuat beberapa Holiday Cafe dan… begitu banyak orang…",
  str_voice_1600231_29 = "Eh, sepertinya aku tersesat! Tidak, bukan begitu. Aku Connolly. Ini Anton dan… saudaranya… Kurasa?",
  str_voice_1600231_30 = "Aku jelas tidak ada niatan untuk menjadi lebih kuat…",
  str_voice_1600231_31 = "Kau benar-benar memercayaiku…",
  str_voice_1600231_32 = "Berhantu? Tidak, tidak mungkin, akulah yang memanggilnya!",
  str_voice_1600231_33 = "Penderitaan dan kesedihan pada akhirnya akan… diredakan oleh musik.",
  str_voice_1600231_34 = "Anton, kita harus melakukannya…",
  str_voice_1600231_35 = "Aku… Aku mendengarnya!",
  str_voice_1600231_36 = "Tiup? Sekarang?!",
  str_voice_1600231_37 = "Astaga! Aku benar-benar minta maaf!",
  str_voice_1600231_38 = "Anton, perhatikan kekuatanmu!",
  str_voice_1600231_39 = "Menyeramkan sekali…",
  str_voice_1600231_40 = "Bersama dengan keluarga…",
  str_voice_1600231_41 = "Aku akan memimpin kalian semua dengan enggan!",
  str_voice_1600231_42 = "Kita benar-benar menang, nih? Sungguh sulit dipercaya…",
  str_voice_1600231_43 = "Maaf… jadi apakah aku harus kembali dan tetap berada di sudut…",
  str_voice_1600231_44 = "Maaf… Anton tidak bermaksud begitu… Aku juga tidak bermaksud begitu…",
  str_voice_1600231_45 = "… Kau… kau seharusnya tidak…",
  str_voice_1600231_46 = "Sungguh? Aku benar-benar boleh memilikinya!?",
  str_voice_1600231_47 = "Wow! Apakah semua hadiah ini untuk Connolly?",
  str_voice_1600231_48 = "Silakan… silakan k-kopinya. Untuk membalas kebaikanmu.",
  str_voice_1600231_49 = "Namanya Anton. Namanya juga Anton… Aku juga bingung pada awalnya, tapi jika kau mendengarkan dengan cermat, kau akan menyadari bahwa namanya terdengar sedikit berbeda.",
  str_voice_1600231_50 = "Aku berharap bisa melihat orang tuaku lagi dan memberi tahu mereka bahwa sekarang aku bisa mengajak Anton berbicara dengan benar. Klarinet yang kuterima sebagai hadiah ini juga sudah disimpan dengan aman…",
  str_voice_1600231_51 = "Nenek. Andai Nenek juga bisa di sini… Hah? Orang itu? Aku tidak ingin bertemu dengannya. A-aku tidak bisa melihat matanya! Dan bukan karena aku lemah. Anton juga tidak bisa! Kita semua tidak bisa!",
  str_voice_1600231_52 = "Al-Alchemy Stars.",
  str_voice_1600231_53 = "H… halo…",
  str_voice_1600231_54 = "Selamat pagi!",
  str_voice_1600231_55 = "Selamat sore! Mau minum teh sore?",
  str_voice_1600231_56 = "Aku… aku baru saja mendengar sesuatu yang menakutkan!",
  str_voice_1600231_57 = "Selamat Tahun Baru…",
  str_voice_1400321_1 = "Beri tahu aku saja jika kau mengalami masalah. Sudah tugasku untuk membantumu.",
  str_voice_1400321_2 = "Meskipun tidak membuat keputusan akhir, aku adalah anggota Hall of Justice… Tak apa, aku tak keberatan. Asalkan aku bisa bekerja demi keyakinanku.",
  str_voice_1400321_3 = "Seperti yang kusebutkan sebelumnya, tolong jangan menatap sayap tunggalku. Tatapanmu rasanya terlalu dalam dan aku tak tahu harus berbuat apa…",
  str_voice_1400321_4 = "Makin penuh bulunya, makin perlu untuk dikendalikan. Aku harus lebih berhati-hati untuk melindunginya dari bahaya.",
  str_voice_1400321_5 = "Keyakinan membuat penglihatanku lebih cerah. Hal-hal yang diabaikan oleh rakyat jelata terlihat begitu jelas bagiku.",
  str_voice_1400321_7 = "Tampaknya kau hanya melakukan hal-hal yang kauyakini, tidak terikat oleh perjanjian dan batasan itu… Aku iri dengan tekadmu.",
  str_voice_1400321_8 = "Instruksimu jelas dan sederhana, seperti yang diberikan oleh Master Pittman… Aku tidak tersinggung. Sebaliknya, aku mengagumi itu.",
  str_voice_1400321_9 = "Aku punya sedikit pertanyaan, tak perlu khawatir. Aku hanya ingin tahu apa kau akan mengundangku untuk bergabung denganmu? Maksudku, ketika semuanya sudah selesai, apa aku akan menjadi salah satu rekanmu?",
  str_voice_1400321_10 = "Tidak ada di sini juga? Aku jelas meninggalkannya di sini waktu itu…",
  str_voice_1400321_11 = "Kau berharap banyak padaku… Tak apa, aku bisa melakukannya, dan sudah pasti tidak akan mengecewakanmu!",
  str_voice_1400321_12 = "Permen dan racun itu sama.",
  str_voice_1400321_13 = "Sayap tunggalku adalah simbol misiku. Ini adalah hadiah yang diberikan keyakinanku untukku.",
  str_voice_1400321_14 = "Bagi mereka yang memiliki keyakinan, penderitaan hanya bersifat sementara.",
  str_voice_1400321_15 = "Pada hari inilah takdir membawamu ke dunia ini. Selamat ulang tahun.",
  str_voice_1400321_16 = "Selamat datang, rekan sekeyakinan.",
  str_voice_1400321_17 = "Orang-orang yang ragu pada akhirnya akan dipandu oleh keyakinan.",
  str_voice_1400321_18 = "Kau tak perlu begitu sering memeriksaku. Itu tak ada gunanya, paham?",
  str_voice_1400321_19 = "Tidak ada urutan prioritas antara terang dan gelap. Hanya orang-orang yang terjebak di antaranya yang terobsesi dengan perbedaan itu.",
  str_voice_1400321_20 = "Banyaknya jiwa yang tekun adalah alasan di balik kemakmuran Lumopolis.",
  str_voice_1400321_21 = "Tanpa keyakinan, Illumina Federation tidak akan pernah menjadi seperti sekarang.",
  str_voice_1400321_22 = "Demi White Night.",
  str_voice_1400321_23 = "Eclipse harus dihancurkan.",
  str_voice_1400321_24 = "Sebagai perwakilan dari Hall of Justice, Master Irridon terlahir untuk melindungi kehormatan Lumopolis.",
  str_voice_1400321_25 = "Hati keadilan Master Pittman bukanlah hasil dari kepribadiannya tetapi keyakinannya.",
  str_voice_1400321_26 = "Keyakinan memurnikan segalanya dan membawa kehidupan baru ke dunia.",
  str_voice_1400321_27 = "Beri tahu aku jika kau perlu seseorang untuk menangkap Defiler, dengan senang hati aku akan ikut membantu.",
  str_voice_1400321_28 = "Namun, peradaban kuno yang sudah maju pun konon lenyap karena hilangnya keyakinan…",
  str_voice_1400321_29 = "Halo. Tolong jangan terus menatap sayap tunggalku… ia sedikit malu.",
  str_voice_1400321_30 = "Aku bisa terbang ke langit yang lebih luas sekarang.",
  str_voice_1400321_31 = "Aku akan memikul lebih banyak tanggung jawab.",
  str_voice_1400321_32 = "Aku akan menjadi… juru bicara keyakinan!",
  str_voice_1400321_34 = "Pekerjaan baru?",
  str_voice_1400321_35 = "Aku akan menggunakan kekuatan keyakinanku.",
  str_voice_1400321_36 = "Awas.",
  str_voice_1400321_37 = "Gunakan kekuatan keyakinan…",
  str_voice_1400321_38 = "Menyebarlah! Berpencar!",
  str_voice_1400321_39 = "Sayap berbulu!",
  str_voice_1400321_40 = "Murnikan!",
  str_voice_1400321_41 = "Mulai penghakiman!",
  str_voice_1400321_42 = "Semuanya terjadi seperti yang diramalkan keyakinan.",
  str_voice_1400321_43 = "Ini adalah kehendak takdir…",
  str_voice_1400321_44 = "Sayapku? Tentu saja, kau boleh lihat. Namun jangan pegang.",
  str_voice_1400321_45 = "Aku tidak mau kau membuang energimu untuk ini.",
  str_voice_1400321_46 = "Ah, ini membuatku tenang. Terima kasih.",
  str_voice_1400321_47 = "Aku menghargai perhatian yang kau berikan di sini. Terima kasih atas hadiahmu.",
  str_voice_1400321_48 = "Inilah yang sudah lama aku harapkan! Diberkatilah kau!",
  str_voice_1400321_49 = "Penderitaan para pengikut sudah berakhir. Sekarang giliran para Defiler. Pittman, sudah pasti aku tidak akan menyerah bahkan jika sayap tunggalku ini masih sakit.",
  str_voice_1400321_50 = "Selama Darkover Crisis itu, aku kehilangan keluarga dan sayapku. Keyakinanlah yang membuatku bertahan hingga saat ini.",
  str_voice_1400321_52 = "Alchemy Stars.",
  str_voice_1400321_53 = "Partner dalam keyakinan.",
  str_voice_1400321_54 = "Selamat pagi. Diberkatilah kau.",
  str_voice_1400321_55 = "Keyakinan memanggilmu.",
  str_voice_1400321_56 = "Selamat malam, wahai pengabdi.",
  str_voice_1400321_57 = "Selamat Tahun Baru. Keyakinanku tetap tidak berubah tahun ini.",
  str_voice_1400851_1 = "Setiap setoran dan penarikan harus dicatat untuk menjadikannya pinjaman yang layak.",
  str_voice_1400851_2 = "Ingin melihat apa isi kotak ini? Tidak boleh.",
  str_voice_1400851_3 = "Aku tidak akan menawarkan bantuan kepada orang-orang yang lemah, dan aku tidak akan tunduk pada orang-orang yang kuat. Itu prinsipku.",
  str_voice_1400851_4 = "Pena dan kertas adalah senjataku, sama seperti pedang dan perisai seorang prajurit.",
  str_voice_1400851_5 = "Ada banyak bukti keserakahan di Marmon Box milikku. Kehidupan banyak orang juga bergantung padanya.",
  str_voice_1400851_6 = "Agar berhasil mendapatkan lebih banyak catatan, aku perlu asisten tiap saat. Ya, aku perlu burung-burung itu.",
  str_voice_1400851_7 = "Kesedihan dan kegembiraan orang-orang saling bertolak belakang. Begitu sudah mengetahuinya, kau akan memahami prinsipku.",
  str_voice_1400851_8 = "Sebagai saksi, aku harus terlihat rapi. Itu sebabnya aku membeli 30 pasang setelan ini.",
  str_voice_1400851_9 = "Kotakku menyimpan banyak rahasia, tidak hanya dari Umbraton tapi juga dari para bangsawan Lumopolis itu.",
  str_voice_1400851_10 = "Aku jarang bisa beristirahat seperti ini… Sudah lumayan lama leher dan bahuku pegal-pegal… Aku perlu dipijat.",
  str_voice_1400851_11 = "Kau mau beristirahat? Tentu saja, aku akan menjaga Colossus ini dan mendokumentasikannya.",
  str_voice_1400851_12 = "Kau pernah melihat burung-burung tersenyum?",
  str_voice_1400851_13 = "Tandukku? Kudengar tanduk ini menggambarkan keserakahan iblis, padahal yang paling serakah dari semuanya adalah keinginan manusia.",
  str_voice_1400851_14 = "Dengan penaku, aku telah menyaksikan berandalan yang paling mulia dan kesatria yang paling tercela.",
  str_voice_1400851_15 = "Aku sudah mengingat profilmu, jadi selamat ulang tahun.",
  str_voice_1400851_16 = "Hari yang tenang, hanya mendokumentasikan.",
  str_voice_1400851_17 = "Fajar adalah waktu terbaik untuk mengasah penaku.",
  str_voice_1400851_18 = "Sudah larut, tapi aku masih harus menyusun catatan hari ini. Belum saatnya untuk istirahat.",
  str_voice_1400851_19 = "Aku harus memasukkan catatan ini ke dalam Marmon Box. Kalau tidak, aku tak akan merasa tenang…",
  str_voice_1400851_20 = "Catatan yang baik bisa menghilangkan kekacauan di sekitar sini.",
  str_voice_1400851_21 = "Perbuatan jahat akan terukir dalam sejarah. Lumopolis tidak terkecuali.",
  str_voice_1400851_22 = "Aku di sini sebagai saksi.",
  str_voice_1400851_23 = "Bagaimana cara mereka membuat catatan? … Sedih sekali jika tidak ada yang bisa mereka kenang.",
  str_voice_1400851_24 = "Istvan memikul terlalu banyak beban. Dia seperti penjelmaan Umbraton, selamanya menjadi bayangan Lumopolis.",
  str_voice_1400851_25 = "Sheol mungkin licik dan selalu berubah, tapi prinsipnya sederhana, keuntungan mengalahkan segalanya.",
  str_voice_1400851_26 = "Keahlian menulis yang indah adalah hadiah terbaik dari para dewa untuk dunia.",
  str_voice_1400851_27 = "Jika seseorang tidak memiliki prinsip, apakah dia masih memiliki jiwa?",
  str_voice_1400851_28 = "Tampaknya ia memiliki kenangan dari masa lalu. Kira-kira apa kenangannya, ya?",
  str_voice_1400851_29 = "Aku menuliskan sejarah Umbraton, lengkap dengan ketertiban dan kekacauan di gang-gang gelapnya, dengan pena di atas kertas. Tertanda, Jane, Saksi.",
  str_voice_1400851_30 = "Aku sudah mencatat entri baru secara tertulis.",
  str_voice_1400851_31 = "Kesaksianku menjadi makin jelas.",
  str_voice_1400851_32 = "Marmon Box menyimpan lebih banyak catatan.",
  str_voice_1400851_33 = "Aku sudah memilih jalan dokumentasi yang tiada akhir.",
  str_voice_1400851_34 = "Aku akan menjadi saksi pertempuran.",
  str_voice_1400851_35 = "Bersiaplah untuk menyelesaikannya.",
  str_voice_1400851_36 = "Mari mulai.",
  str_voice_1400851_37 = "Mari kita akhiri semuanya!",
  str_voice_1400851_38 = "Sudah selesai, dasar kalian orang serakah!",
  str_voice_1400851_39 = "Hancurkan!",
  str_voice_1400851_40 = "Tidak ada yang boleh lari!",
  str_voice_1400851_41 = "Aku akan mendokumentasikan kinerja semua orang.",
  str_voice_1400851_42 = "Menang. Sudah terdokumentasikan.",
  str_voice_1400851_43 = "Kalau saja ini bisa tidak dimasukkan ke catatan…",
  str_voice_1400851_44 = "Aku akan mendokumentasikan kebenaran seperti yang kulihat.",
  str_voice_1400851_45 = "Aku akan mendokumentasikan hadiah ini di buku.",
  str_voice_1400851_46 = "Terima kasih, ini akan sangat membantu!",
  str_voice_1400851_47 = "Aku akan membayar ganti ruginya. Aku janji.",
  str_voice_1400851_48 = "Ini…! Aku tak bisa mengungkapkan rasa terima kasihku dalam kata-kata…",
  str_voice_1400851_49 = "Baik Istvan maupun Sheol mengundangku untuk bergabung dengan mereka, tapi aku hanya ingin menjadi pencatat sejarah Umbraton. Aku tidak berminat memerintah kota.",
  str_voice_1400851_50 = "Jika kau perhatikan, baik itu bangsawan maupun warga sipil, tiap orang memiliki sisi yang memang milik mereka dan sisi yang bukan milik mereka.",
  str_voice_1400851_51 = "Umbraton diserang oleh Eclipsite dan ibuku terbunuh karenanya. Banyak orang mengamuk pada Lumopolis, yang diam saja, tapi aku tidak menyimpan dendam pada mereka.",
  str_voice_1400851_52 = "Alchemy Stars.",
  str_voice_1400851_53 = "Apa kau di sana?",
  str_voice_1400851_54 = "Pagi.",
  str_voice_1400851_55 = "Selamat sore.",
  str_voice_1400851_56 = "Selamat malam.",
  str_voice_1400851_57 = "Selamat Tahun Baru.",
  str_voice_1600021_1 = "Di sisi lain jendela, badai hujan tampaknya telah sirna. Aku tak pernah menyangka akan menemukan kedamaian seperti ini di Colossus.",
  str_voice_1600021_2 = "Dunia ini ajaib, tapi harus ada batasan dalam hidup. Seperti kau dan Colossus ini, aku, dan katana ini.",
  str_voice_1600021_3 = "Seseorang harus bersikap tegas saat dia terjebak di antara situasi yang sulit. Namun… tidak semua orang bisa melakukannya, begitu juga denganku.",
  str_voice_1600021_4 = "Seorang petarung harus fokus pada momennya dan tidak boleh teralihkan perhatiannya. Hiiro, kau tidak boleh merasa bangga meskipun kemampuanmu meningkat.",
  str_voice_1600021_5 = "Hatiku dipenuhi dengan cerita para pahlawan telah gugur. Itu adalah kenangan dari Cloud Mountain… Aku tidak akan ragu lagi!",
  str_voice_1600021_6 = "Zakura, Sakae, kekuatan sementara ini, dan kegigihan di hadapan maut. Hanya ini yang aku punya.",
  str_voice_1600021_7 = "Dengan turunnya gerimis di musim semi dan tumbuhnya rumput segar, dunia tampaknya mulai pulih. Mau melihatnya?",
  str_voice_1600021_8 = "Kematian tidaklah menakutkan. Berkorban untuk hal yang sia-sia, itu baru menakutkan. Jadi, demi apakah kau rela berkorban?",
  str_voice_1600021_9 = "Dunia mungkin sulit dipercaya, tetapi dengan Colossus ini dan kau… Dunia tampak berbeda sekarang.",
  str_voice_1600021_10 = "Fiuh—akhirnya bisa istirahat juga. Aku akan menggunakan kesempatan ini untuk bermeditasi. Semoga tidak ada yang menggangguku…",
  str_voice_1600021_11 = "Aku merasa terhormat karena kau pilih. Semoga aku bisa memenuhi harapanmu.",
  str_voice_1600021_12 = "Sakae adalah nama pedang ini. Ia telah menemaniku selama bertahun-tahun.",
  str_voice_1600021_13 = "… Di kampung halamanku, selalu ada banyak bunga sakura yang bermekaran di saat-saat tenang.",
  str_voice_1600021_14 = "Kenapa kita tidak mencari tempat untuk duduk dan bermeditasi bersama? Meditasi bisa menghilangkan rasa lelah, yang berguna saat kita bekerja.",
  str_voice_1600021_15 = "Aku sudah menyiapkan secangkir teh panas dan beberapa bunga sakura untuk ulang tahunmu hari ini. Aku mengharapkan kebahagiaan tanpa akhir untukmu.",
  str_voice_1600021_16 = "Kau sudah kembali rupanya. Semua baik-baik saja.",
  str_voice_1600021_17 = "Latihanku untuk legiun sudah selesai. Beri tahu saja aku jika kau perlu sesuatu.",
  str_voice_1600021_18 = "Tenanglah, aku masih di sini.",
  str_voice_1600021_19 = "Saatnya untuk beristirahat. Aku masih agak lama di sini, jadi jangan hiraukan aku.",
  str_voice_1600021_20 = "Kami bersyukur kepada Illumina. Ini adalah tempat menginap yang paling sesuai bagiku dan Sakae.",
  str_voice_1600021_21 = "Kau mungkin pernah mendengarku bercerita tentang kampung halamanku. Tempat itu berada jauh di Timur melintasi benua ini.",
  str_voice_1600021_22 = "Jayalah Illumina.",
  str_voice_1600021_23 = "Aurorian dan Eclipsite terlahir untuk selalu bermusuhan. Mereka hanya bisa saling berhadapan dengan pedang.",
  str_voice_1600021_24 = "Dia mengundangku ke sini atas nama Illumina, jadi aku berutang padanya. Aku tidak akan pernah melupakan sosoknya yang kuat.",
  str_voice_1600021_25 = "Meskipun sebagian besar kontak kami adalah untuk urusan resmi, aku tentu mengagumi kemampuan perencanaannya.",
  str_voice_1600021_26 = "Meditasi, Pink Dragon, Sakae… Apakah hal-hal yang penting bagiku akan dianggap sebagai hal-hal yang aku sukai?",
  str_voice_1600021_27 = "Bukannya benci, tapi aku tidak ingin berada di antara mereka yang tidak tersadar.",
  str_voice_1600021_28 = "Kau pernah mendengar tentang naga putih yang legendaris itu? Sama seperti Colossus ini, kuharap makhluk tersebut bisa pergi jauh.",
  str_voice_1600021_29 = "Namaku Hiiro. Hidup itu sulit dipercaya. Kita memang sudah ditakdirkan untuk bertemu. Sakae dan aku akan melayanimu untuk saat ini.",
  str_voice_1600021_30 = "Sedikit lagi aku akan… mencapai tujuanku.",
  str_voice_1600021_31 = "Aku harus melawan keegoisanku sendiri.",
  str_voice_1600021_32 = "Jangan takut akan kematian, sama seperti bunga musim semi yang menyebar—",
  str_voice_1600021_33 = "Zakura, bergabunglah denganku untuk mengejar babak terakhir dalam takdir kita!",
  str_voice_1600021_34 = "Mari ubah takdir kita bersama-sama.",
  str_voice_1600021_35 = "Fokus—",
  str_voice_1600021_36 = "Siapkan pedang.",
  str_voice_1600021_37 = "Menuju ke arah kematian dan kita akan hidup—!",
  str_voice_1600021_38 = "Sakura Storm—!",
  str_voice_1600021_39 = "Fall!",
  str_voice_1600021_40 = "Light Arc!",
  str_voice_1600021_41 = "Aku tidak akan mempermalukan kalian.",
  str_voice_1600021_42 = "Pertempuran itu tentu saja diperjuangkan dengan kesadaran.",
  str_voice_1600021_43 = "… Kekalahan tidaklah memalukan.",
  str_voice_1600021_44 = "Jalan dengan sakura bermekaran di sisinya adalah jalan pulang dalam ingatanku.",
  str_voice_1600021_45 = "Terima kasih, tapi kau tidak harus melakukannya.",
  str_voice_1600021_46 = "Hadiah ini… Tolong beri tahu aku bagaimana cara membalasmu.",
  str_voice_1600021_47 = "Kau pasti memikirkannya dengan sepenuh hati. Terima kasih.",
  str_voice_1600021_48 = "Ini… oh, aku sangat menyukainya. Tidak, aku benar-benar menyukainya…",
  str_voice_1600021_49 = "Sudah jadi misiku untuk membantumu. Meskipun tinggal di Illumina dan memegang jabatan penting sebagai Legion Commander, aku tidak terlahir di sini…",
  str_voice_1600021_50 = "Meskipun aku masih muda ketika meninggalkan kampung halamanku, tidak bisa dihindari bahwa jejaknya tetap terukir dalam diriku, seperti integritasku, seperti namaku…",
  str_voice_1600021_51 = "Hidup memang tidak bisa ditebak. Sakae dan aku meninggalkan Cloud Mountain bersama-sama, tapi aku ditinggalkan untuk bergabung dengan Illumina sendirian… Sekarang karena kau sudah di sini, kuharap tidak akan ada kejutan lagi…",
  str_voice_1600021_52 = "Alchemy Stars.",
  str_voice_1600021_53 = "Halo.",
  str_voice_1600021_54 = "Selamat pagi.",
  str_voice_1600021_55 = "Permisi.",
  str_voice_1600021_56 = "Sudah larut.",
  str_voice_1600021_57 = "Selamat Tahun Baru.",
  str_voice_1500331_1 = "Sayangnya, Colossus tidak dilengkapi dengan buku panduan, jadi satu-satunya cara adalah dengan langsung turun tangan! Hm? Namun benar juga, karena… karena… Tunggu. Beri aku waktu sebentar.",
  str_voice_1500331_2 = "Jika kita mampu mengaktifkan Colossus bersama-sama, berarti itu memang takdir… jadi tidak ada alasan untuk terus menyimpan dendam karena sudah merusak Colossus… Iya, 'kan?",
  str_voice_1500331_3 = "Rencana pertempuran hari ini adalah… Hmm? Terlalu kencang? Maaf… Kupikir lebih kencang, lebih baik… Sepertinya tidak, ya?",
  str_voice_1500331_4 = "Aku tidak akan lagi memandang rendah diriku sendiri karena aku sudah memecahkan misteri dan menemukan keistimewaanku. Aku tidak akan membiarkan masa lalu terulang kembali…",
  str_voice_1500331_5 = "Kekuatanku yang tumbuh akan membawa kemenangan untukku… Bahkan jika aku memiliki mimpi buruk yang tidak bisa kusingkirkan, itu tidak akan menghentikanku untuk menjadi lebih kuat!",
  str_voice_1500331_6 = "Aku akan selalu menjaga keyakinan, yang akan bersinar terang seperti aurora saat malam!",
  str_voice_1500331_7 = "Kenapa kau tidak bisa mengaktifkan Colossus? Umumnya, menemukan cara yang benar akan menyelesaikan segalanya… Jadi, aku adalah… cara yang benar?",
  str_voice_1500331_8 = "Aku harus selalu waspada ketika menjalankan misi solo, tapi sekarang akhirnya aku punya partner! Seseorang yang tidak perlu kubayar sepeser pun! Oh… bagaimana dengan imbalan atas layananmu?",
  str_voice_1500331_9 = "Kurasa aku ingin tahu lebih banyak tentang kalian berdua karena kita sudah lama bahu-membahu. Aku benar-benar berharap yang terbaik untuk kalian berdua!",
  str_voice_1500331_10 = "Berapa banyak lagi yang tersisa dalam agendanya? Bertahanlah sedikit lagi… Kau harus istirahat. Kau pantas mendapatkannya.",
  str_voice_1500331_11 = "Serahkan saja padaku. Aku akan mengatasi semuanya! Namun, aku akan senang jika kau bisa membantuku!",
  str_voice_1500331_12 = "Butuh pertolongan? Sini, biar kubantu! Lagi pula, aku sudah menghafal seluruh isi \"Protokol Tanggap Darurat\"!",
  str_voice_1500331_13 = "Mabuk perjalanan karena terbang? Jangan khawatir! Tidur siang saja sana. Aku juga mengalami hal yang sama saat pertama kali naik Colossus.",
  str_voice_1500331_14 = "Seseorang telah menyinari duniaku, menambahkan sesuatu yang tak bisa dihancurkan.",
  str_voice_1500331_15 = "Sembunyikan, lalu matikan lampu, dan hadiahnya sudah siap… Hah? Sejak kapan kau ada di situ?",
  str_voice_1500331_16 = "Selamat datang kembali! Kerja bagus! Jadi… Aku akan istirahat dan mengambil sif berikutnya.",
  str_voice_1500331_17 = "Kau sudah bangun? Aku sudah menyelesaikan komunikasi yang terjadwal. Mari kita bahas tentang jadwal hari ini!",
  str_voice_1500331_18 = "Satu hal lagi, laporan tentang Colossus hampir siap… mungkin lebih cepat dari yang dijadwalkan…",
  str_voice_1500331_19 = "Aku tak mengira kau akan lembur sampai jam-jam seperti ini… Kau benar-benar sangat berdedikasi!",
  str_voice_1500331_20 = "Sistem yang luar biasa dengan kesempatan belajar yang setara. Aku sangat beruntung diadopsi oleh Illumina!",
  str_voice_1500331_21 = "Pengalamanku di Lumopolis sudah mengajariku banyak hal. Andai saja kau pernah ke sana!",
  str_voice_1500331_22 = "Jayalah Illumina!",
  str_voice_1500331_23 = "Setiap orang punya alasan untuk mengangkat senjata… begitu pula denganku.",
  str_voice_1500331_24 = "Walau Charon seperti belum matang, dia memiliki banyak kelebihan, seperti… eee, aku akan teruskan lagi nanti.",
  str_voice_1500331_25 = "Meskipun dia sendiri cukup membuat sakit kepala, tapi penelitiannya akan… yah, akan membuat kepalamu makin sakit.",
  str_voice_1500331_26 = "Lagu pengantar tidur dan tuts piano… Ini semua sangat canggih, ya?",
  str_voice_1500331_27 = "Aku benci kegagalan, terutama ketika… Aku hampir bisa merasakan kesuksesanku, tapi akhirnya gagal karena kenaifan.",
  str_voice_1500331_28 = "Bagi kebanyakan orang, Colossus ini mungkin terlihat seperti alat atau senjata. Namun, aku merasa ia lebih seperti teman. Iya, 'kan?",
  str_voice_1500331_29 = "Aku Vice! Kau tentu ingat aku, 'kan? Oh… syukurlah! Tadi aku sempat khawatir aku tidak meninggalkan kesan pada siapa pun!",
  str_voice_1500331_30 = "Aku bisa menjadi lebih kuat!",
  str_voice_1500331_31 = "Apakah takdir yang tak diketahui telah menungguku di depan?",
  str_voice_1500331_32 = "Berkat dan kebahagiaan terhebat benar-benar ada di sini.",
  str_voice_1500331_33 = "Maju! Menuju masa depan yang misterius!",
  str_voice_1500331_34 = "Aku akan berusaha lebih keras!",
  str_voice_1500331_35 = "Siap dan sudah siap dari tadi!",
  str_voice_1500331_36 = "Perlu buku panduannya juga?",
  str_voice_1500331_37 = "Aku tidak akan ragu-ragu!",
  str_voice_1500331_38 = "Saatnya pertempuran yang tidak berarti ini berakhir!",
  str_voice_1500331_39 = "Melacak target!",
  str_voice_1500331_40 = "Tidak pernah kalah!",
  str_voice_1500331_41 = "Memimpin? Tentu saja! Sudah pasti!",
  str_voice_1500331_42 = "Ha! Tidak pernah ragu!",
  str_voice_1500331_43 = "Ayo mundur dulu… Kita bisa berjuang di hari lain.",
  str_voice_1500331_44 = "Wah! Astaga! Apa ini, permainan serangan jantung?",
  str_voice_1500331_45 = "Hadiah untukku? Dalam rangka apa?",
  str_voice_1500331_46 = "Untuk membangun hubungan? Begitu rupanya!",
  str_voice_1500331_47 = "Terima kasih! Aku menyukainya. Sungguh!",
  str_voice_1500331_48 = "Sebaiknya kau menantikan hadiahku untukmu!",
  str_voice_1500331_49 = "Dulu, aku ingin menjadi mercusuar harapan yang bersinar, hingga mimpi itu hancur… Tak apa. Aku tidak berencana untuk menyerah meski aku kehilangan bakat dan karuniaku.",
  str_voice_1500331_50 = "Takdir mungkin kejam, tapi harapan selalu ada. Maksudku, kau sekarang di sini untukku, 'kan? Kau selalu bisa menganggapku sebagai harapan kalau kau tidak keberatan…",
  str_voice_1500331_51 = "Pernahkah kau berpikir tentang apa yang akan terjadi pada dunia ketika semua rahasia tentang kita, Eclipsite, dan seluruh langit terungkap? Apakah kau masih bisa… menjaga keyakinanmu?",
  str_voice_1500331_52 = "Alchemy Stars!",
  str_voice_1500331_53 = "Kau di sana, partner andalanku?",
  str_voice_1500331_54 = "Selamat pagi! Bagaimana keadaanmu?",
  str_voice_1500331_55 = "Kau tidak istirahat makan siang, ya?",
  str_voice_1500331_56 = "Kerja bagus!",
  str_voice_1500331_57 = "Aku tak sabar untuk bekerja sama denganmu di tahun depan!",
  str_voice_1500131_1 = "Aku suka di sini! Aku akan mengukir Colossus berukuran asli dari es! Tunggu… Sebenarnya itu agak sulit.",
  str_voice_1500131_2 = "Kita harus melindungi lingkungan! Di Northland, eksploitasi seperti ini akan dihukum berat oleh Yang Mulia Ratu!",
  str_voice_1500131_3 = "Aku akan mengukir wajah Vice di atas bola es yang besaaaar! Menurutmu dia akan marah atau terkejut?",
  str_voice_1500131_4 = "Aku belum pernah melihat es seperti ini sebelumnya… Rasanya… berbeda. Ayo buat manusia salju?",
  str_voice_1500131_5 = "Lihat! Aku bisa melihat pelangi di kristal es… Ini bukan fenomena yang bisa kita lihat setiap hari!",
  str_voice_1500131_6 = "Ayo kita pergi, manusia salju! Ke alam mimpi yang penuh warna, tempat pelangi dan sinar matahari menanti kita!",
  str_voice_1500131_7 = "Ada banyak pria yang tidak realistis di Northland, tahu tidak? Seperti… *ehem* Aku tidak bilang apa-apa!",
  str_voice_1500131_8 = "Tertarik dengan Greatsword milikku? Sini, aku akan menunjukkan bagian belakangnya. Ini juga menarik!",
  str_voice_1500131_9 = "Aku punya banyak cerita. Cerita tentang kristal es, cerita tentang kepingan salju. Berjanjilah padaku bahwa kau akan merahasiakannya, dan aku akan menceritakannya.",
  str_voice_1500131_10 = "Sekarang kita punya lebih banyak waktu luang, mau bermain dengan kristal esku? Jangan lupa untuk selalu menghangatkan dirimu!",
  str_voice_1500131_11 = "Rasanya seperti menggunakan bahan berkualitas tinggi untuk tujuan sepele, tapi aku tak keberatan. Aku akan mengawasi upayamu dalam melindungi lingkungan!",
  str_voice_1500131_12 = "Apakah peralatan di sini tahan air? Kau ingin aku menurunkan salju khusus untukmu?",
  str_voice_1500131_13 = "Bolehkah aku bermain dengan kristal es? Yang kecil-kecil saja! Aku janji tidak akan membuat masalah!",
  str_voice_1500131_14 = "Lihat, perahu es! Pohon aras es! Dan miniatur es… dirimu!",
  str_voice_1500131_15 = "Selamat ulang tahun, dan 900 bintang dariku untukmu! Senang?",
  str_voice_1500131_16 = "Yo! Mau bertualang di atas es? Kau membawa ranselmu dan aku akan membawamu!",
  str_voice_1500131_17 = "Pagi! Pagi! Bagaimana keadaanmu pagi ini? Aku merasa hebat!",
  str_voice_1500131_18 = "Ayo! Kau datang tepat waktu! Ayo menari dengan manusia-manusia salju kecil ini!",
  str_voice_1500131_19 = "Kita bisa membuat api unggun dan duduk berdekatan. Aku akan menceritakan sebuah kisah, dan kau akan menceritakan satu kisah padaku.",
  str_voice_1500131_20 = "Aku ingat pelangi yang melengkung dan hujan yang turun, serta tanah yang melunak!",
  str_voice_1500131_21 = "Mulai sekarang, aku akan pergi mengunjungi banyak tempat! Pertama Cloudward, lalu Undercity!",
  str_voice_1500131_22 = "Demi Utara!",
  str_voice_1500131_23 = "Para bajingan yang merusak lingkungan tidak bisa dimaafkan! Jangan takut! Aku tidak akan membiarkan mereka menyakitimu!",
  str_voice_1500131_24 = "Pernah mendengar tentang cerita Louise? Ceritanya luar biasa, dan sangat akurat!",
  str_voice_1500131_25 = "Tiap kali menari dengan manusia-manusia salju kecilku, aku bisa tahu bahwa dia sedikit iri.",
  str_voice_1500131_26 = "Aku suka membantu orang dan suka apa pun yang bersinar serta berkilau! Aku hanya seorang gadis sederhana.",
  str_voice_1500131_27 = "Meski tidak membenci apa pun, aku tidak bisa membiarkan tindakan yang merusak lingkungan! Mereka perlu diberi pelajaran!",
  str_voice_1500131_28 = "Ini rumahmu, 'kan? Aku bisa merasakannya… Kerinduan dan harapanmu…",
  str_voice_1500131_29 = "Dengarkan! Pohon aras sangat penting untuk Northland karena mereka membantu menahan badai salju… Walau utamanya berkat sihir Yang Mulia Ratu…",
  str_voice_1500131_30 = "Oh! Aku suka itu! Lagi! Lagi!",
  str_voice_1500131_31 = "Perjamuan salju dan sihir!",
  str_voice_1500131_32 = "Kristal es akan bermekaran!",
  str_voice_1500131_33 = "Kristal es akan bersinar dan menerangi seluruh galaksi!",
  str_voice_1500131_34 = "Mau pergi bertualang?",
  str_voice_1500131_35 = "BEKUKAN MEREKA SEMUA!",
  str_voice_1500131_36 = "Demi Alam!",
  str_voice_1500131_37 = "Elf salju dan angin!",
  str_voice_1500131_38 = "Noah ada di sini!",
  str_voice_1500131_39 = "Angin utara!",
  str_voice_1500131_40 = "Salju yang menusuk!",
  str_voice_1500131_41 = "Petualangan baru yang menakjubkan! Ayo pergi!",
  str_voice_1500131_42 = "Kita bekerja sama dengan baik!",
  str_voice_1500131_43 = "Sial… Tidak sempat menggunakan bunga es perayaan…",
  str_voice_1500131_44 = "Bintang-bintang es di langit, siapakah dirimu!",
  str_voice_1500131_45 = "Terima kasih… Namun, itu saja? Tidak ada yang lebih menarik?",
  str_voice_1500131_46 = "Oooh! Aku suka ini! Sepertinya sang Ratu juga akan menyukainya!",
  str_voice_1500131_47 = "Terima kasih! Aku akan menghargai setiap hadiah, meskipun hadiahnya biasa, selama itu dari kau!",
  str_voice_1500131_48 = "AKU SUKA! Rasa sukaku tak bisa diungkapkan dengan kata-kata!",
  str_voice_1500131_49 = "Ratu berkata bahwa aku sudah bisa mulai bepergian, maka aku pergi, dengan ranselku, dan aku bertemu dengan banyak orang baik dalam perjalananku.",
  str_voice_1500131_50 = "Dahulu kala, banyak orang telah pergi. Hari itu, bulan itu, tahun itu, di tengah munculnya pelangi.",
  str_voice_1500131_51 = "Perjalanan ini penuh dengan kebebasan, impian, senyuman, dan janji yang kubuat dengan semua orang yang sangat kucintai.",
  str_voice_1500131_52 = "Alchemy Stars!",
  str_voice_1500131_53 = "Temanku yang rupawan!",
  str_voice_1500131_54 = "Hari yang baru sudah tiba!",
  str_voice_1500131_55 = "Selamat sore! Mau ikut bertualang denganku?",
  str_voice_1500131_56 = "Kau siap?",
  str_voice_1500131_57 = "Ayo kita bepergian bersama di tahun baru berikutnya!",
  str_voice_1400611_1 = "Emosi para Aurorian sungguh menakjubkan. Mereka bagaikan Elf dengan wujud fisik.",
  str_voice_1400611_2 = "Kau ingin belajar cara menguasai emosimu? Tak perlu! Ada aku!",
  str_voice_1400611_3 = "Majulah dan ekspresikan dirimu. Aku akan menjadi pendukungmu. Terkadang, kau sama keras kepalanya seperti anak itu…",
  str_voice_1400611_4 = "Seiring dengan makin jauhnya penelitian kami tentang hal ini, mungkin suatu hari nanti kami bisa membantu anak itu…",
  str_voice_1400611_5 = "Kaum Elf ini tidak hanya dapat digunakan dalam pertempuran, tapi juga dalam membantu kita untuk sembuh dari trauma emosional…",
  str_voice_1400611_6 = "Maaf… Terkadang, emosiku juga butuh pelampiasan. Aku akan berusaha untuk tidak terlalu merepotkanmu.",
  str_voice_1400611_7 = "Hei! Ada hal baru yang ingin kau sampaikan padaku hari ini? Aku selalu ada di sini.",
  str_voice_1400611_8 = "Katakan saja apa yang ada dalam pikiranmu. Aku selalu bisa meluangkan waktu untukmu karena itu sudah bagian dari tugasku.",
  str_voice_1400611_9 = "Kemarilah. Aku bisa merasakan emosimu yang sedikit kacau. Butuh tepukan di kepala?",
  str_voice_1400611_10 = "Merasa relaks dan merasa bosan itu hampir mirip…",
  str_voice_1400611_11 = "Waktunya untuk sesi konselingmu? Kemarilah, ayo kita duduk dan berbincang.",
  str_voice_1400611_12 = "Selamat datang kembali, Navigator! Jangan ragu untuk memberitahuku tentang apa pun!",
  str_voice_1400611_13 = "Halo! Mau mengobrol?",
  str_voice_1400611_14 = "Jika kau merasa sedih, temui aku kapan saja!",
  str_voice_1400611_15 = "Selamat ulang tahun! Ini benar-benar hari yang menyenangkan!",
  str_voice_1400611_16 = "Colossus ini emosinya stabil. Serahkan saja padaku! Bukan masalah!",
  str_voice_1400611_17 = "Kau terlihat segar! Sepertinya istirahatmu cukup, ya?",
  str_voice_1400611_18 = "Emosi negatif menumpuk ketika kau terlalu banyak bekerja. Istirahatlah agar kau tetap bersemangat.",
  str_voice_1400611_19 = "Jika kau tidak bisa tidur, kemarilah dan mengobrol denganku!",
  str_voice_1400611_20 = "Kehidupan di Undercity Illumina mungkin tampak menegangkan bagi orang lain, tapi sebenarnya di sini rapi dan teratur!",
  str_voice_1400611_21 = "Kabarnya, Lumopolis punya cara unik untuk menyelesaikan masalah emosional. Itu hanya desas-desus atau bukan, ya?",
  str_voice_1400611_22 = "Jayalah Illumina!",
  str_voice_1400611_23 = "Para Eclipsite itu bajingan! Mereka hanya dipenuhi rasa dendam!",
  str_voice_1400611_24 = "Director Gronru benar-benar tahu banyak hal, bahkan berkecimpung dalam bidang psikologi.",
  str_voice_1400611_25 = "White Dwarf sangat menggemaskan! Meski mungkin lebih tua dariku, tapi dia benar-benar polos seperti anak kecil!",
  str_voice_1400611_26 = "Aku suka mendengarkan, terutama ketika orang lain mencurahkan isi hatinya padaku",
  str_voice_1400611_27 = "Emosi negatif itu tidak sehat, jadi kau harus mencari cara untuk melampiaskannya!",
  str_voice_1400611_28 = "Colossus ini juga punya emosi. Aku harus memperhatikan dan mendengarkan.",
  str_voice_1400611_29 = "Halo! Aku Chandra Sekar, psikolog dan penyembuh emosi tim ini! Senang bertemu denganmu!",
  str_voice_1400611_30 = "Emosinya makin kuat!",
  str_voice_1400611_31 = "Bahu-membahu untuk pertumbuhan bersama!",
  str_voice_1400611_32 = "Kau benar-benar tahu cara melatih kawanmu.",
  str_voice_1400611_33 = "Lepaskan emosimu! Biarkan emosi itu menggelegar bagaikan kembang api!",
  str_voice_1400611_34 = "Senang bertemu denganmu!",
  str_voice_1400611_35 = "Emosinya sudah terkumpul sepenuhnya!",
  str_voice_1400611_36 = "Sudah mulai! Sudah mulai!",
  str_voice_1400611_37 = "Keluarlah, jiwaku!",
  str_voice_1400611_38 = "Api jiwa, bersiaplah!",
  str_voice_1400611_39 = "Ayo coba!",
  str_voice_1400611_40 = "Emosi Negatif! Keluarlah!",
  str_voice_1400611_41 = "Semoga semuanya dalam suasana hati yang bahagia!",
  str_voice_1400611_42 = "Inilah aroma manis kemenangan!",
  str_voice_1400611_43 = "Omong-omong, kau bisa melampiaskan emosi negatifmu padaku!",
  str_voice_1400611_44 = "Ada sesuatu yang mengganggumu? Biarkan aku mengambilnya dan menyimpannya untukmu!",
  str_voice_1400611_45 = "Kau baik sekali! Terima kasih!",
  str_voice_1400611_46 = "Aku benar-benar menyukainya! Kau manis sekali!",
  str_voice_1400611_47 = "Kau suka memberiku hadiah, ya?",
  str_voice_1400611_48 = "Kebahagiaanku meluap-luap! Hehe!",
  str_voice_1400611_49 = "Bahkan jika masa lalu kita muram dan kelam, kita tidak boleh selalu mengambil perspektif negatif tentang kehidupan, 'kan?",
  str_voice_1400611_50 = "Gronru benar-benar menjagaku. Jika bukan karena dukungannya, penelitianku tidak akan berjalan lancar. Aku dikaruniai rekan-rekan yang paling menakjubkan.",
  str_voice_1400611_51 = "Sekarang, semua orang di Illumina adalah keluargaku, termasuk kau, Navigator! Semoga dengan bersama-sama, aku bisa menciptakan lebih banyak lagi emosi yang menakjubkan!",
  str_voice_1400611_52 = "Alchemy Stars!",
  str_voice_1400611_53 = "Hei, kau!",
  str_voice_1400611_54 = "Selamat pagi!",
  str_voice_1400611_55 = "Selamat sore!",
  str_voice_1400611_56 = "Selamat malam!",
  str_voice_1400611_57 = "Selamat Tahun Baru!",
  str_voice_1500361_1 = "Kau tampaknya bisa berbicara dengan mereka… Banyak orang berakhir dengan menjadi gila. Jangan hiraukan itu, bukan apa-apa.",
  str_voice_1500361_2 = "Katakan apa yang ingin kaukatakan, aku mendengarkan. Sebelum bos kembali, aku punya waktu luang untuk berpura-pura mendengarkanmu.",
  str_voice_1500361_3 = "Eksistensi tidak bermakna, terutama saat kau memahami maknanya. Tidak paham? Wajar. Bahkan bos pun tidak paham.",
  str_voice_1500361_4 = "Sama seperti bayangan yang tumpang tindih, kegelapan berkumpul dan menjadi lebih pekat… Benda yang terputus dan diregenerasi itu akan runtuh. Kau tak perlu tahu tentang ini.",
  str_voice_1500361_5 = "Baik itu anjing maupun serigala, atau baik itu bayangan maupun sesuatu yang nyata. Kau tidak perlu tertarik dengan ini… Cukup lihat saja.",
  str_voice_1500361_6 = "Kau melihat mereka? Mereka indah, tenang, dan ada di mana-mana. Yang ada di belakangmu itu sama, tapi benar-benar berbeda.",
  str_voice_1500361_7 = "Tak perlu khawatir jika kau meragukan kemampuanku. Aku perlu melakukan banyak hal yang lebih penting ketimbang menggunakan bayangan untuk berurusan denganmu.",
  str_voice_1500361_8 = "Hmm… Sepertinya aku mulai menghargaimu. Kau tahu tidak bahwa bayanganmu memiliki aroma sekarang? Jangan dekat-dekat, ya. Aku tidak ingin mencium baunya.",
  str_voice_1500361_9 = "Aku tidak mau mengakuinya, tapi kau mirip dengan kakakku. Kalian berdua adalah penguasa bayangan dan berjalan bebas di antara bayangan di dunia terang dan kegelapan.",
  str_voice_1500361_10 = "Wow, hmm, terserah… Aku sangat bosan… Apakah ada seseorang yang bisa mengakhiri semuanya?",
  str_voice_1500361_11 = "Tolong cari orang lain saja jika ada. Bahkan anjing-anjingku tidak ingin berada di sini.",
  str_voice_1500361_12 = "Apa lagi? Kau kemari pasti karena ada sesuatu, 'kan?",
  str_voice_1500361_13 = "Tempat ini lebih membosankan dari yang kukira… Bukankah kau penguasa tempat ini? Lakukanlah sesuatu.",
  str_voice_1500361_14 = "Menjauhlah… Bayanganku merasa gelisah. Bukan urusanku jika mereka menggigitmu.",
  str_voice_1500361_15 = "Astaga, sungguh menyebalkan… Ini benar-benar tidak berguna. Bilang saja apa maumu.",
  str_voice_1500361_16 = "Oh, kau kembali. Kupikir kau telah hilang.",
  str_voice_1500361_17 = "Kau rajin, lantas kenapa? Tidak ada urusannya denganku…",
  str_voice_1500361_18 = "Kau mau keluar atau tidak? Cepatlah, jangan membuang-buang waktu.",
  str_voice_1500361_19 = "Mengapa kau masih terjaga saat bahkan anjing-anjingku tertidur? Terserah… Aku tidak akan menunggumu… Apa lagi yang akan kau lakukan?",
  str_voice_1500361_20 = "Dulu, orang seperti aku hanya cocok untuk Umbraton. Sekarang, orang-orang seperti akulah yang seharusnya ada di Umbraton.",
  str_voice_1500361_21 = "Lumopolis… Siapa pun yang mau, bisa pergi ke sana, tetapi aku tidak tertarik.",
  str_voice_1500361_22 = "Ck, bayangan itu selalu mengawasimu.",
  str_voice_1500361_23 = "Eclipsite? Haruskah aku memedulikan mereka? Bayanganku akan mengerumuni, mengelilingi, dan menggerogoti mereka sampai mati. Tamat.",
  str_voice_1500361_24 = "Tidak tahu, tidak peduli juga. Eclipsite yang ada di Umbraton adalah seekor gurita, sesuatu yang seharusnya sudah punah berabad-abad silam.",
  str_voice_1500361_25 = "Cih, entah kenapa long worm itu begitu antusias setiap hari…",
  str_voice_1500361_26 = "Kesukaan? Hmm… Makanan pedas, anjing, dan tidak ada yang menggangguku.",
  str_voice_1500361_27 = "Aku tidak menyukai orang yang mengira mereka tahu segalanya.",
  str_voice_1500361_28 = "Ini rumahmu? Bukan masalah. Aku bermalam di tempat orang lain sebelumnya.",
  str_voice_1500361_29 = "Aku tidak menyangka kau bisa menemukanku. Rasanya merepotkan untuk memperkenalkan diri. Baca sendiri saja ini.",
  str_voice_1500361_30 = "Baik, kau diterima.",
  str_voice_1500361_31 = "Mereka berkumpul di sisi lain Light.",
  str_voice_1500361_32 = "Mereka telah turun dalam senyap.",
  str_voice_1500361_33 = "Lahap orang-orang yang kecanduan kesenangan semu!",
  str_voice_1500361_34 = "Dengarkan. Cari orang lain saja.",
  str_voice_1500361_35 = "Akulah tuanmu!",
  str_voice_1500361_36 = "Sambut warna kematian—",
  str_voice_1500361_37 = "Sebarkan cahaya!",
  str_voice_1500361_38 = "Robek Light!!",
  str_voice_1500361_39 = "Sobek!",
  str_voice_1500361_40 = "Lahap!",
  str_voice_1500361_41 = "Kapten? Yang benar saja?",
  str_voice_1500361_42 = "Mereka disebut orang lemah.",
  str_voice_1500361_43 = "Kau frustrasi? Maaf, tetapi aku tidak peduli.",
  str_voice_1500361_44 = "Sungguh merepotkan… Menyerah saja. Aku tidak akan bereaksi.",
  str_voice_1500361_45 = "Oh. Wow. Sebuah hadiah… AKU SUNGGUH menginginkan ini…",
  str_voice_1500361_46 = "… Ha! Kebetulan tebakanmu benar? Bisa dibilang aku menantikan ini.",
  str_voice_1500361_47 = "Cih, baiklah, aku akan menerimanya. OH, BETAPA BAHAGIANYA AKU.",
  str_voice_1500361_48 = "Kau tahu keinginanku, seperti biasanya.",
  str_voice_1500361_49 = "Banyak hal yang tidak begitu penting bagiku, seperti pakaian dan kerabat. Cepat atau lambat, itu semua akan pergi. Jangan coba-coba untuk menyangkal karena aku benar.",
  str_voice_1500361_50 = "Ikatan itu benar-benar konyol. Orang-orang yang menginginkanmu mengejar sesuatu yang tidak realistis menyuntikkan gagasan ini ke dalam kepalamu dan membuatmu terpenjara. Maaf, tapi aku takkan memercayainya.",
  str_voice_1500361_51 = "Aku takkan mengesampingkan kemungkinan bahwa kelak aku akan berakhir dalam situasi yang sangat klise, tetapi itu sangat tidak mungkin. Kita lihat saja nanti. Itu semua berkasnya. Berhenti mengetuk. Itu saja. Astaga!",
  str_voice_1500361_52 = "Alchemy Stars.",
  str_voice_1500361_53 = "Halo, kau di sana?",
  str_voice_1500361_54 = "Bahkan anjingku terjaga.",
  str_voice_1500361_55 = "Aku butuh bantuanmu.",
  str_voice_1500361_56 = "Kau tertidur? Aku akan menunggu dua menit.",
  str_voice_1500361_57 = "Cih, sekarang Tahun Baru. Lantas kenapa?",
  str_voice_1500121_1 = "Hei! Aku tidak selalu hanya berceramah, aku juga bisa mengobrol denganmu semalaman! Bagaimana menurutmu? Enforcer of Justice pun punya sisi ramah!",
  str_voice_1500121_2 = "Ini adalah ujian dari Splendor Illumina. Memang memusingkan. Maksudku, mau jadi apa dunia ini tanpa aku?!",
  str_voice_1500121_3 = "Aku telah melihat keadilan yang bersinar terang di dalam hatimu. Illumina memerlukan orang-orang sepertimu. Kau mengerti maksudku?",
  str_voice_1500121_4 = "Kau salah besar jika mengira itu hanya slogan semata. Ini adalah kepercayaanku, serta keyakinanku hingga kelak aku mati.",
  str_voice_1500121_5 = "Indahnya… Jika ini terus berlanjut, akan kulampaui Grand Marshal dalam tiga hari! Bagaimana bisa aku menyelamatkannya dari penghinaan saat itu terjadi…",
  str_voice_1500121_6 = "Aku akan mewujudkannya agar semua orang bisa mendengar suara yang kuat dan bergema di hati mereka! Kawan-kawanku, jalan yang cerah menanti kalian. Percaya pada Keadilan!",
  str_voice_1500121_7 = "Tidak perlu berterima kasih karena inilah kewajiban semua kawan! Aku juga berharap kau akan memperlakukan semua orang di Illumina seperti keluargamu sendiri.",
  str_voice_1500121_8 = "Tidak perlu takut selama kau menjunjung keadilan. Berdirilah di sampingku dan biarkan Illumina menyinarimu.",
  str_voice_1500121_9 = "Meski tidak punya tempat untuk ditinggali atau tidak ada seorang pun yang memahami kita, kita harus tetap menjaga keyakinan. Tentu saja, aku percaya kaulah yang mengerti.",
  str_voice_1500121_10 = "Hei, kau di sana? Hei! Keadilan membutuhkanmu—atau apakah kau bersembunyi di sudut, merencanakan sesuatu yang tidak bermoral?",
  str_voice_1500121_11 = "Baiklah! Kau ingin aku mengukir kata \"Keadilan\" di layar utama, 'kan? Aku akan memulai!",
  str_voice_1500121_12 = "Saking kerennya, sulit menjelaskan topi ini dengan kata-kata, 'kan! Kawan seperjuanganku dari timur jauh memberikannya kepadaku.",
  str_voice_1500121_13 = "Senjataku sedikit panjang? Jangan khawatir, pedang ini dulu digunakan untuk menegakkan keadilan dan rasanya pas bagiku.",
  str_voice_1500121_14 = "Kau sangat penuh semangat, dan bagaimanapun teman yang cocok untukku!",
  str_voice_1500121_15 = "Aku tahu kau telah lama bekerja keras, jadi rayakan sepenuh hatimu hari ini dan bersenang-senanglah semaumu!",
  str_voice_1500121_16 = "Selamat datang kembali, rekan keadilan!",
  str_voice_1500121_17 = "Pagi! Sudah lama aku menunggumu. Aku sudah tidak sabar memulai hari baru!",
  str_voice_1500121_18 = "Aku akan selalu menanti dan menyambut kepulanganmu, kapan pun itu, kawan!",
  str_voice_1500121_19 = "Bagus! Aku tahu kau akan mengingat kata-kataku. Kau harus berada di sini untuk membahas keadilan denganku sepanjang malam!",
  str_voice_1500121_20 = "Aku akan melakukan apa pun demi Kejayaan Illumina! Aku akan tetap waspada dan mengawasi apa pun sepanjang waktu.",
  str_voice_1500121_21 = "Bagus di luar, tapi jahat di dalam. Kita sudah paham kemunafikan kota apung itu sejak lama!",
  str_voice_1500121_22 = "Jayalah Illumina! Lindungi Gannon!",
  str_voice_1500121_23 = "Aku takkan mengampuni orang-orang yang melanggar keadilan atau Illumina! Mereka akan dibasmi!",
  str_voice_1500121_24 = "Kuat, adil, dan dengan keyakinan yang teguh pada keadilan, aku yakin tidak ada yang lebih cocok memimpin Illumina selain Grand Marshal.",
  str_voice_1500121_25 = "Dia membantuku memahami bahwa bahkan orang-orang dari tempat terpencil memiliki keadilan yang teguh. Betapa menginspirasi.",
  str_voice_1500121_26 = "Enforcer harus menghukum pembuat kesalahan dan membasmi kejahatan. Aku akan menjalankan tugasku dan memecahkan masalah orang lain!",
  str_voice_1500121_27 = "Hal-hal yang tidak aku suka? Jangan khawatir, secara pribadi aku akan menghilangkan semua yang membuatku muak!",
  str_voice_1500121_28 = "Aku meragukan Colossus sebelum menaikinya, tetapi semuanya kini berbeda karena kau ada di sini!",
  str_voice_1500121_29 = "Kau terlihat seperti orang baik. Mungkin kita bisa menjelajahi keyakinan masing-masing soal keadilan. Semoga aku takkan pernah merasa harus membunuhmu…",
  str_voice_1500121_30 = "Kehormatan abadi!",
  str_voice_1500121_31 = "Fajar baru menyingsing berkat kekuatan baru!",
  str_voice_1500121_32 = "Aku makin dekat dengan Grand Marshal!",
  str_voice_1500121_33 = "Sebuah tangan besi dan sebilah pedang tajam—sempurna!",
  str_voice_1500121_34 = "Menjunjung tinggi kebajikan dan menghukum kejahatan!",
  str_voice_1500121_35 = "Petir, menembus kegelapan…",
  str_voice_1500121_36 = "Sesalilah tindakanmu!",
  str_voice_1500121_37 = "Mundur, bajingan!",
  str_voice_1500121_38 = "Ini kesempatan terakhirmu untuk mengucapkan kata-kata terakhir!",
  str_voice_1500121_39 = "Hukuman!",
  str_voice_1500121_40 = "Keadilan sedang ditegakkan!",
  str_voice_1500121_41 = "Saatnya Enforcer of Justice bertindak!",
  str_voice_1500121_42 = "Keadilan akan selalu ada!",
  str_voice_1500121_43 = "Jangan hentikan aku! Akan kulumpuhkan mereka semua!",
  str_voice_1500121_44 = "Tidak perlu berterima kasih kepadaku. Aku hanya melakukan tugasku!",
  str_voice_1500121_45 = "Oh? Ini cukup menarik. Terima kasih.",
  str_voice_1500121_46 = "Seolah-olah kau bisa membaca pikiranku! Seperti yang diharapkan dari kawanku dalam keadilan!",
  str_voice_1500121_47 = "Apa pun nilainya dan apa pun artinya, terima kasih.",
  str_voice_1500121_48 = "Kawan, kau telah memberiku hadiah yang sangat bermakna!",
  str_voice_1500121_49 = "Bahkan kalau sendirian, kau tidak boleh meninggalkan keyakinan yang kau pegang erat di dalam hati karena itu adalah panji dan pilar—Splendor Illumina yang harus dijaga semua orang.",
  str_voice_1500121_50 = "Aku ada untuk menghancurkan kemunafikan dan kekotoran di dunia ini! Bukan masalah jika tidak ada yang memahamiku.",
  str_voice_1500121_51 = "Apa yang sebenarnya ditinggalkan oleh keluargaku? Beban apa yang harus kupikul? Tidak, aku memilih untuk menjadi diriku sendiri.",
  str_voice_1500121_52 = "Alchemy Stars!",
  str_voice_1500121_53 = "Kawan keadilan!",
  str_voice_1500121_54 = "Rencana satu hari dimulai dengan fajar!",
  str_voice_1500121_55 = "Jangan sampai lengah pada sore hari!",
  str_voice_1500121_56 = "Hari masih jauh dari kata selesai!",
  str_voice_1500121_57 = "Selamat Tahun Baru! Kita rayakan untuk keadilan!",
  str_voice_1500211_1 = "Ketika semua luka akibat tusukan mawar yang dipangkas terus-menerus mengoyak dan sembuh, perasaan cinta yang kuat mengalir keluar dari tubuhku!",
  str_voice_1500211_2 = "Aku mencintaimu, tetapi aku lebih mencintai anak itu. Dia seperti mawar yang lebat semaknya. Kuharap dia akan menyelimutiku dengan sulur berdurinya erat-erat dan tidak pernah meninggalkanku!!",
  str_voice_1500211_3 = "Kami bermain petak umpet. Mau ikut? Oh, kami kekurangan satu orang lagi… Satu lagi… Kapan mereka terlepas dari rangkulan cintaku? Anak yang manis…",
  str_voice_1500211_4 = "Taman cintaku telah tumbuh lebih besar. Jatuh ke dalam jaring cintaku layaknya kupu-kupu mengejar semburat cahaya, dan tak pernah pergi…",
  str_voice_1500211_5 = "Aku melihat cintaku mengalir dalam nadi setiap bunga. Aku akan membangun sangkar paling halus untuk mereka, sama seperti untuk anak itu.",
  str_voice_1500211_6 = "Tetaplah bersamaku, jangan pernah mengkhianatiku. Kita akan menunggu mekarnya bunga bersama di tamanku yang hangat dan berpagar!",
  str_voice_1500211_7 = "Cuaca hari ini bagus. Bolehkah aku menggenggam tanganmu? Jangan khawatir, hanya berjalan-jalan di taman. Aku takkan menjebakmu dengan manisnya cintaku…",
  str_voice_1500211_8 = "Pagarku mewakili cinta, pelukan, dan pengorbanan! Dia tidak memahami niatku. Kau? Kau mengerti, 'kan?!",
  str_voice_1500211_9 = "Sungguh cinta yang kuat! Aku takut kau adalah satu-satunya orang yang memahamiku di dunia ini, seperti cara gunung-gunung yang menjulang dan sungai-sungai mengalir beresonansi! Mendekatlah—saatnya kuberitahukan rahasia padamu…",
  str_voice_1500211_10 = "Dia terlihat letih, bak bunga liar yang kurang terawat. Aku ingin tahu ukuran sangkar apa yang lebih cocok untuknya… Hmm? Ah, aku hanya berbicara sendiri.",
  str_voice_1500211_11 = "Waktunya berkebun lagi. Aku akan mengubah tempat ini menjadi negeri yang penuh semangat, penuh pepohonan, dan sangat teduh…",
  str_voice_1500211_12 = "Oh, kau di sini rupanya. Tidak heran aku merasakan semilir angin sejak tadi.",
  str_voice_1500211_13 = "Aromamu seperti bunga, wanginya berbeda dari bunga-bungaku… Ini sangat unik.",
  str_voice_1500211_14 = "Kenapa kau selalu enggan? Karena pagarku kurang nyaman…? Hah? Aku sedang membicarakan bunga-bungaku.",
  str_voice_1500211_15 = "Terimalah cintaku pada hari yang tak terlupakan seperti hari ini! Aku akan menjadi sesuatu yang takkan pernah kau lupakan!",
  str_voice_1500211_16 = "Selamat datang kembali di taman cintaku. Aku telah menunggumu.",
  str_voice_1500211_17 = "Kau sudah bawa embun paginya? Bungaku yang cantik sudah tidak sabar untuk mekar.",
  str_voice_1500211_18 = "Ahh—selamat datang kembali! Aku tahu kau akan kembali padaku, dan ke taman yang hangat ini…",
  str_voice_1500211_19 = "Aku iri padamu… Bungaku selalu kurang bersemangat saat malam hari, tetapi kau tetap mekar.",
  str_voice_1500211_20 = "Tidak ada salahnya bagi sebuah taman, tetapi kupikir anak itu akan datang kemari juga…",
  str_voice_1500211_21 = "Taman di langit, taman di gurun, taman di salju… Di manakah gerangan anak itu?",
  str_voice_1500211_22 = "Baiklah, Jayalah Illumina!",
  str_voice_1500211_23 = "Aku harus menyingkirkan semua hama yang membahayakan bunga-bungaku yang indah…",
  str_voice_1500211_24 = "Aku akan menemukannya meski harus pergi ke ujung dunia. Lalu aku akan melindunginya dan membuatnya tetap aman.",
  str_voice_1500211_25 = "Jika kau ingin membicarakan orang lain selain anak itu… Kurasa kita bisa membicarakanmu.",
  str_voice_1500211_26 = "Bunga mawar dari semangat yang terbakar! Aku suka? Tidak… Aku sangat suka!",
  str_voice_1500211_27 = "Huh, bahkan kau takkan menoleransi mereka yang tak peka terhadap perasaan orang lain…",
  str_voice_1500211_28 = "Aku bisa merasakan bahwa Colossus dipenuhi oleh perasaanmu, sama seperti bungaku.",
  str_voice_1500211_29 = "Bibit-bibit kesayanganku, tukang kebunmu Jola ada di sini. Kalian siap untuk mekar di bawah cintaku yang penuh perhatian?",
  str_voice_1500211_30 = "Sungguh pengalaman yang berharga!",
  str_voice_1500211_31 = "Kerajaan cinta telah bersemi!",
  str_voice_1500211_32 = "Domba yang hilang akhirnya akan kembali pulang!",
  str_voice_1500211_33 = "Ini, adalah kehidupan yang benar-benar indah!!",
  str_voice_1500211_34 = "Ayo kita ke taman itu.",
  str_voice_1500211_35 = "Cintaku meluap.",
  str_voice_1500211_36 = "Oh-ho-ho!",
  str_voice_1500211_37 = "Aku akan mengorbankan segalanya untukmu—",
  str_voice_1500211_38 = "Atas nama cinta—",
  str_voice_1500211_39 = "Tumbuhlah!",
  str_voice_1500211_40 = "Mekarlah!",
  str_voice_1500211_41 = "Duduklah berjajar, bunga-bunga kesayangku…",
  str_voice_1500211_42 = "Cintaku yang kuat akan mencapaimu kelak.",
  str_voice_1500211_43 = "Ini… seperti inikah rasanya layu…",
  str_voice_1500211_44 = "Cuaca hari ini menyenangkan. Maukah kau mengunjungi kebunku?",
  str_voice_1500211_45 = "Sayang sekali aku membutuhkan lebih banyak cintamu.",
  str_voice_1500211_46 = "Eeh—! D-dari mana kau mendapatkan ini?!",
  str_voice_1500211_47 = "Apresiasi lebih besar dari cinta. Terima kasih.",
  str_voice_1500211_48 = "Oh—! Aku diselimuti oleh cintamu yang melimpah!",
  str_voice_1500211_49 = "Kau melihatnya? Di tamanku yang indah, setiap bunga memiliki namanya: Mr. William, Miss Mary… Hmm, harus kuberi nama apa lagi, ya, bunga yang berikutnya?",
  str_voice_1500211_50 = "Aku telah mengalami guncangan, kebencian, dan kesepian, tetapi kini aku tak bisa berhenti merindukannya. Satu-satunya hal yang tidak berubah adalah cinta karena cinta itu abadi.",
  str_voice_1500211_51 = "Aku telah membangun ovarium yang paling luar biasa dan hangat untuknya. Dia bisa pulang kapan saja dengan mengikuti aroma cinta dan tanganku akan terbuka lebar untuknya, terlepas dari masa lalu.",
  str_voice_1500211_52 = "Alchemy, Stars.",
  str_voice_1500211_53 = "Hai—",
  str_voice_1500211_54 = "Pagi telah tiba.",
  str_voice_1500211_55 = "Tentunya kau di sini, 'kan?",
  str_voice_1500211_56 = "Aku selalu merindukanmu saat malam hari…",
  str_voice_1500211_57 = "Satu tahun telah berlalu, tetapi cintaku tidaklah berkurang.",
  str_voice_1400171_1 = "Di mana pertarungan selanjutnya? Aku mau membuat rencana liburan dulu, siapa tahu kita tidak bisa tahan dengan panasnya!",
  str_voice_1400171_2 = "Hm? Ada yang aneh! Bersembunyi! Atau…",
  str_voice_1400171_3 = "Hiks… Aku dimarahi karena lagi-lagi menggali kabin… Aku hanya meneliti material lama untuk jaga-jaga…",
  str_voice_1400171_4 = "Aku kembali mempelajari kamuflase optik! Dengannya, kita bisa lolos dari musuh tepat di bawah hidung mereka!",
  str_voice_1400171_5 = "Coba lihat ini! Kepala bor terbaru! Wuuut! Aku hampir bisa mencium aroma tanah yang baru digali hanya dengan menyentuhnya!",
  str_voice_1400171_6 = "Dengan kekuatan seperti ini, ia akan membelah bumi seperti pisau panas menembus mentega… Mmm… Mentega… Nyammmm…",
  str_voice_1400171_7 = "Kau tidak punya konsep akan bahaya. Seperti yang telah kutekankan kepada anggota timku, perencanaan, antisipasi, dan berpikir ke depan sangatlah penting!",
  str_voice_1400171_8 = "Aku sangat merindukan kakekku. Mungkin beliau masih melindungiku, itu sebabnya aku selalu bisa lolos dengan selamat… atau karena kelinci lain itu?",
  str_voice_1400171_9 = "Jangan lupa rute pelarian yang kutunjukkan. Tidak apa-apa kalah selama kau hidup untuk bertarung di lain hari.",
  str_voice_1400171_10 = "Oke, kita akan melakukannya untuk Rencana E. Sekarang untuk Rencana F…",
  str_voice_1400171_11 = "Baiklah! Aku akan memastikan titik pintu darurat terdekat!",
  str_voice_1400171_12 = "S-suara apa itu? Oh! Rupanya kau. Untunglah. Jantungku hampir copot.",
  str_voice_1400171_13 = "Kapan peralatan pesananku akan dikirim? Sepertinya aku akan menunggu… selama 5 menit lagi!",
  str_voice_1400171_14 = "Aku merasa aman setiap kali bersamamu. Oh, tetapi aku sudah merencanakan rute pelarian kita!",
  str_voice_1400171_15 = "Selamat ulang tahun! Aku punya banyak perayaan untukmu, jadi mana yang kau suka dari A sampai J?",
  str_voice_1400171_16 = "Kau kembali! Aku sudah menemukan rute pelarian kita… Hah? Tidak jadi melarikan diri?",
  str_voice_1400171_17 = "Selamat pagi! Ayo bahas rencana baru, sesuatu yang berakhir dengan \"rute\"!",
  str_voice_1400171_18 = "Wah! Selamat datang kembali! Aku tidak melakukan sesuatu yang mencurigakan. Sama sekali tidak!",
  str_voice_1400171_19 = "Belum istirahat? Tidak bisa tidur? Merasa gamang? Aku bisa menggalikan lubang untukmu!",
  str_voice_1400171_20 = "Meski tidak ada yang suka tinggal di bawah tanah, bisa sering berlarian boleh juga!",
  str_voice_1400171_21 = "Kudengar semua orang di Illumina tinggal di sebuah gua besar. Mereka pasti punya bor listrik yang kuat!",
  str_voice_1400171_22 = "Nyaris saja tidak lolos!",
  str_voice_1400171_23 = "Mereka masih membuatku takut dan rasanya aku masih ingin melarikan diri… Namun, aku kini bisa bertahan!",
  str_voice_1400171_24 = "Rasanya malu kalau mengatakan bahwa aku sudah lupa seperti apa dia karena dia selalu memakai pelindung kepala.",
  str_voice_1400171_25 = "Si pendek orangnya cukup baik! Dia bahkan akan membantuku menyesuaikan kepala borku!",
  str_voice_1400171_26 = "Aku suka alat penggalian baru, lubang baru, dan rencana pelarian baru!",
  str_voice_1400171_27 = "Ruang tertutup itu menakutkan! Bagaimana bisa tidak ada bukaannya!",
  str_voice_1400171_28 = "Colossus sangat cepat dan luaaaar biasa! Jadi… bisakah aku mulai menggali lubang?",
  str_voice_1400171_29 = "Namaku Rabbie, ahli melarikan diri! Jangan biarkan bor besar menakutimu! Bor ini hanya digunakan untuk memastikan rute pelarian kita!",
  str_voice_1400171_30 = "Borku bahkan kini lebih kuat!",
  str_voice_1400171_31 = "Menggali adalah caranya!",
  str_voice_1400171_32 = "Hore! Borku baru saja ditingkatkan!",
  str_voice_1400171_33 = "Di mana pun, gali terus, sampai tembus!",
  str_voice_1400171_34 = "Aku akan melindungimu!",
  str_voice_1400171_35 = "Siap dan bisa!",
  str_voice_1400171_36 = "Menunggu perintahmu!",
  str_voice_1400171_37 = "Kau tidak akan lolos!",
  str_voice_1400171_38 = "Tidak ada jalan keluar bagimu!",
  str_voice_1400171_39 = "Rute dipastikan!",
  str_voice_1400171_40 = "Halangan disingkirkan!",
  str_voice_1400171_41 = "Utamakan keselamatan, semuanya!",
  str_voice_1400171_42 = "Kau tidak akan bisa lari dari ahli pelarian!",
  str_voice_1400171_43 = "Jangan panik! Ikuti aku!",
  str_voice_1400171_44 = "Aku akan memberitahumu sebuah rahasia… Aku sebenarnya sudah menyiapkan rute kabur rahasia!",
  str_voice_1400171_45 = "Hmmm… Biar kupikirkan… Jadi, bagaimana cara menggunakannya?",
  str_voice_1400171_46 = "Untukku? Sungguh? Terima kasih!",
  str_voice_1400171_47 = "Hmm! Kuharap aku bisa memanfaatkannya!",
  str_voice_1400171_48 = "Astaga! Aku selalu menginginkannya!",
  str_voice_1400171_49 = "Aturan Mundur: Satu, tahu alasan yang mendasarinya! Dua, lari seperti angin! Tiga, simpan drama untuk nanti!",
  str_voice_1400171_50 = "Pemimpin kami kuat dan aku kini memiliki banyak teman yang bisa diandalkan, jadi aku tidak lagi harus melarikan diri… Serahkan padaku, aku akan menjaga rute pelarian!",
  str_voice_1400171_51 = "Jika kau tidak bisa lari? Aku akan melindungimu seperti kakekku melindungiku, tetapi kau harus menunggu hingga aku sedikit lebih tinggi.",
  str_voice_1400171_52 = "Alchemy Stars!",
  str_voice_1400171_53 = "Tok tok, kau di sana?",
  str_voice_1400171_54 = "Selamat pagi!",
  str_voice_1400171_55 = "Mau berolahraga sebentar?",
  str_voice_1400171_56 = "Kau sudah istirahat?",
  str_voice_1400171_57 = "Selamat Tahun Lubang! Lihat hasil perbuatanku di sana?",
  str_voice_1300491_1 = "Aku bosan. Ayo latih tanding denganku, Bos. Apa? Maksudmu, wanita-wanita itu ingin mencoba? Tidak, terima kasih, aku tidak suka melawan wanita.",
  str_voice_1300491_2 = "Eclipsite tidak perlu ditakuti. Aku membunuh semua Eclipsite yang kulihat. Dulu pada masa-masa sulitku, aku… Tunggu, apa maksudmu kau mengutusku untuk bertarung di garis depan sendirian lain kali?",
  str_voice_1300491_3 = "Aku memanggilmu bos sepanjang waktu, meski entah apakah itu akan membuat Istvan marah… Lupakan, kalian berdua bisa menyelesaikannya dengan bertarung.",
  str_voice_1300491_4 = "Ayo! Siapa pun yang masih belum yakin dapat berduel denganku! Hanya saja, jangan lari sambil menangis mengadu kepada ibumu!",
  str_voice_1300491_5 = "Orang cenderung terlalu memikirkan segalanya. Satu-satunya kebenaran di dunia ini adalah apakah aku mengalahkanmu atau kau mengalahkanku.",
  str_voice_1300491_7 = "Jangan pedulikan dua pedang besar atau helm kepala macan tutulku. Aku bisa makan dengan normal dan aksesori ini tidak membuat penglihatanku kabur sama sekali. Sekarang, berhentilah mengajukan pertanyaan yang menyebalkan!",
  str_voice_1300491_8 = "Dua pedang ini tidak jelek, tapi sedikit terlalu ringan untukku. Kapan aku mendapatkan senjata yang lebih bagus, lebih tajam, dan lebih kuat, bos?",
  str_voice_1300491_9 = "Bagaimana? Kau suka helm kepala macan tutulku? Ini bukan asli, melainkan modifikasi. Hei, jangan sentuh itu! Jangan menggosoknya juga!",
  str_voice_1300491_10 = "Rasanya membosankan berdiri saja… Adakah seseorang atau sesuatu yang bisa kupukul? Jika begini terus, orang-orang Guild akan meninggalkan kita!",
  str_voice_1300491_11 = "Aku tidak punya masalah dalam menjaga, tetapi jangan pernah menggunakan istilah \"pengasuh rumah\"! Cukup!",
  str_voice_1300491_12 = "Kuulangi lagi, ya, aku ini bukan kucing besar! Berhentilah mencoba bersandar padaku sepanjang waktu!",
  str_voice_1300491_13 = "Kekerasan adalah jalan hidupku. Mana mungkin aku bertahan di Umbraton tanpanya.",
  str_voice_1300491_14 = "Ucapan bos adalah perintahku. Oh, maksudku bukan kau. Aku sedang membicarakan bosku yang di Umbraton.",
  str_voice_1300491_15 = "Kau mau aku memotong kue ulang tahun untukmu?",
  str_voice_1300491_16 = "Karena kita sedang senggang, bagaimana kalau berlatih pedang?",
  str_voice_1300491_17 = "Kadang-kadang, rasanya aku ingin mencuci helm kepala macan tutul ini, tetapi nanti ada masalah atau tidak, ya?",
  str_voice_1300491_18 = "Entahlah apakah itu ilusi atau bukan, tetapi aku merasa lebih energik!",
  str_voice_1300491_19 = "Meong… Tiba-tiba merasakan hasrat untuk melakukan itu.",
  str_voice_1300491_20 = "Seburuk apa pun Umbraton, bagi banyak orang di sanalah satu-satunya rumah.",
  str_voice_1300491_21 = "Aku akan bergabung dengan Rediesel Wrench andai aku tidak bertemu Istvan! Haha!",
  str_voice_1300491_22 = "Di mana ada cahaya, di situ ada bayangan!",
  str_voice_1300491_23 = "Hancurkan semuanya hingga berkeping-keping!",
  str_voice_1300491_24 = "Tidak akan ada Seleucid tanpa Istvan. Untuk itu saja, aku akan mengikutinya hingga ke ujung dunia.",
  str_voice_1300491_25 = "Dua orang bodoh itu? Pemula punya banyak hal untuk dipelajari…",
  str_voice_1300491_26 = "Barbeku yang lezat dapat memecahkan masalah apa pun. Jika tidak, makan satu lagi.",
  str_voice_1300491_27 = "Hadapi aku jika kau berani. Hanya pengecut yang akan mencoba menusuk seseorang dari belakang!",
  str_voice_1300491_28 = "Yang ini besar. Bisakah aku membawanya berkendara untuk seru-seruan ke Lumopolis?",
  str_voice_1300491_29 = "Kau penanggung jawab Colossus ini? Luar biasa! Aku akan memanggilmu \"bos\" mulai sekarang. Aku punya bos sungguhan, tetapi itulah caraku menunjukkan rasa hormat!",
  str_voice_1300491_30 = "Sudah waktunya untuk mengganti kedua pedang ini!",
  str_voice_1300491_31 = "Bukankah ini kesempatan sempurna untuk membunuh mereka semua!?",
  str_voice_1300491_32 = "Aku petarung nomor satu di Istvan Gang!",
  str_voice_1300491_34 = "Ikuti saja aku!",
  str_voice_1300491_35 = "Ayo maju kalau berani!",
  str_voice_1300491_36 = "Bersiaplah untuk terluka!",
  str_voice_1300491_37 = "Makan, tuh!",
  str_voice_1300491_38 = "Jangan pernah berpikir untuk melarikan diri!",
  str_voice_1300491_39 = "Tebas!",
  str_voice_1300491_40 = "Tebas lagi!",
  str_voice_1300491_41 = "Harus mengikutiku!",
  str_voice_1300491_42 = "Menang dengan mudah, Sayang!",
  str_voice_1300491_43 = "Lagi! Hei, aku bilang \"lagi\"!",
  str_voice_1300491_44 = "Membosankan. Aku butuh seseorang untuk latih tanding!",
  str_voice_1300491_45 = "Aku lebih suka kalau kau melawanku ketimbang memberikan ini kepadaku.",
  str_voice_1300491_46 = "Inilah yang kuinginkan! Hah! Kau memang mengerti aku!",
  str_voice_1300491_47 = "Tidak ada keuntungan tanpa rasa sakit! Jadi beri tahu saya — apa yang Anda ingin saya lakukan?",
  str_voice_1300491_48 = "Ini benar-benar seleraku! Aku terlalu malu untuk berterima kasih!",
  str_voice_1300491_49 = "Kepala macan tutul adalah helmku! Aku tidak sengaja memakainya dan tidak bisa melepasnya. Bos menyarankanku untuk menggunakannya sebagai gaya pribadi. Kenapa tidak? Aku jadi tampak keren jika memakainya.",
  str_voice_1300491_50 = "Sejujurnya, meski bisa melepas helmnya, aku tidak mau melakukannya. Wajahku jauh lebih menakutkan—gara-gara Eclipsite.",
  str_voice_1300491_52 = "Alchemy Stars!",
  str_voice_1300491_53 = "Lagi senggang, Bos?",
  str_voice_1300491_54 = "Pagi, Bos!",
  str_voice_1300491_55 = "Di mana kau, Bos?",
  str_voice_1300491_56 = "Bos, kau belum istirahat, ya?",
  str_voice_1300491_57 = "Selamat Tahun Baru! Ayo minum!",
  str_voice_1300221_1 = "Minyak diesel… Makin tua, makin enak baunya. Minumlah satu botol dan kau pasti ingin satu botol lagi. Minum dua, kau pasti ingin botol ketiga.",
  str_voice_1300221_2 = "Gergaji dan aku perlu mengisi bahan bakar. Di mana, ya, kita bisa mendapatkan minyak diesel?",
  str_voice_1300221_3 = "Fiuh, hampir saja. Aku hampir kehilangan headgear milikku. Jika ada yang melihat wajahku…",
  str_voice_1300221_4 = "Aku mendengar suara pengeboran yang tidak asing… Rabbie! Dia di sini…?",
  str_voice_1300221_5 = "Mungkin aku sebelumnya lemah dan kecil, tetapi kini aku minum minyak diesel, dan memiliki gergaji ini untuk membunuh mereka semua! Mereka semua!",
  str_voice_1300221_7 = "Campuran minyak diesel spesial ini rasanya sangat lezat! Mau coba? Ayo, yang benar saja? Rabbie sangat menyukainya…",
  str_voice_1300221_8 = "Hei, jangan menilaiku dari tinggi badanku! Aku bisa dengan mudah mengalahkan pria yang berkali-kali lipat lebih besar dariku! Kau bisa mengandalkanku, bukan masalah!",
  str_voice_1300221_9 = "Aneh sekali. Semuanya terlihat sangat berbeda, tetapi entah bagaimana ini mengingatkanku pada Rediesel Wrench. Mungkin saja aku… merasa betah di sini?",
  str_voice_1300221_10 = "Aku sangat mengantuk. Oh, jangan pernah coba-coba mencopot pelindung kepalaku selagi aku tidur…",
  str_voice_1300221_11 = "Hanya berdiri di sini? Sama sekali tidak ada sesuatu di dalam yang perlu digergaji?",
  str_voice_1300221_12 = "Tertarik dengan suatu benteng? Kau mau aku mengintai sebelum kita memulai? Oh… tidak akan menyerang? Sayang sekali…",
  str_voice_1300221_13 = "Sarang ini cukup lega dan ada beberapa helai selimut hangat untuk tidur. Andai saja aku bisa lebih sering bertemu Rabbie… Aaah, Rabbie… Dia… Lupakan!",
  str_voice_1300221_14 = "Di bawah headgear? Tidak ada apa-apa. Tidak ada gunanya menatapnya seperti itu. Aku tidak akan melepasnya! Lagi pula, aku telah bersumpah… demi Rabbie…",
  str_voice_1300221_15 = "Aku akan memotong kue ulang tahunnya! Menghantamnya? Baiklah!",
  str_voice_1300221_16 = "Chief, apakah kelinci populer untuk pameran sekarang?",
  str_voice_1300221_17 = "Chief! Kau dapat sesuatu?",
  str_voice_1300221_18 = "Chief! Kau kembali! Ayo lakukan sesuatu yang seru hari ini!",
  str_voice_1300221_19 = "Secangkir minyak diesel dengan taburan potongan roti kering. Makan malamku…",
  str_voice_1300221_20 = "Rediesel Wrench! Sekelompok orang gila! Namun, aku menyukai mereka, hahaha!",
  str_voice_1300221_21 = "Aku benci orang-orang bodoh dari Illumina itu, tetapi teknologi mereka sangat canggih. Kudengar mereka punya gergaji listrik yang kuat!",
  str_voice_1300221_22 = "Hormat pada Rabbie!",
  str_voice_1300221_23 = "Sekelompok orang dungu bahkan lebih dungu dariku!",
  str_voice_1300221_24 = "Bor Rabbie menembus hatiku! Jika dia tidak memercayainya, aku akan memotongnya dengan gergaji untuk membuktikannya! Oh, Rabbie…",
  str_voice_1300221_25 = "Clover dan aku mantan partner, itu saja. Namun, dia sebenarnya cukup kasihan…",
  str_voice_1300221_26 = "Sederhana saja, aku cinta Rabbie, dan bersamanya membuatku senang. Aku tidak akan membiarkan siapa pun menyakitinya!",
  str_voice_1300221_27 = "Kaki lemah di medan perang bagaikan kayu bakar basah… Benar-benar tidak berguna!",
  str_voice_1300221_28 = "Besar sekali! Jauh lebih kuat dari kadal raksasa kita…",
  str_voice_1300221_29 = "Katakan, kau ingin aku membelah siapa? Siapa pun yang meremehkanku dan gergaji akan berakhir sengsara!",
  str_voice_1300221_30 = "Rasanya darahku seperti terbakar!",
  str_voice_1300221_31 = "Berputar! Lebih cepat!",
  str_voice_1300221_32 = "Lebih banyak minyak diesel! Lebih banyak kekuatan!",
  str_voice_1300221_34 = "Aku ikut!",
  str_voice_1300221_35 = "Jangan pernah berpikir untuk kabur!",
  str_voice_1300221_36 = "Bahkan gergajiku tidak bisa menunggu ini!",
  str_voice_1300221_37 = "Gergaji hingga terbelah, gergaji!",
  str_voice_1300221_38 = "Aku akan melumat kalian semua!",
  str_voice_1300221_39 = "Ayo cicipi gergaji listrikku!",
  str_voice_1300221_40 = "Whoo-wee!!",
  str_voice_1300221_41 = "Heh-heh, aku jadi chief sekarang!",
  str_voice_1300221_42 = "Bisakah kau menemuiku sekarang, Rabbie?",
  str_voice_1300221_43 = "Semuanya, mundur! Aku akan menahan mereka!",
  str_voice_1300221_44 = "Da dam! Aku butuh lebih banyak minyak diesel! Haha!",
  str_voice_1300221_45 = "Apa gunanya ini?",
  str_voice_1300221_46 = "Untukku? Sudah lama aku mencari ini…",
  str_voice_1300221_47 = "Nilainya besar! Apa yang kauinginkan dariku, hah?",
  str_voice_1300221_48 = "Hoi, bagaimana kalau sedikit bahan bakar diesel!",
  str_voice_1300221_49 = "Aku bukan kelinci… Aku memilih menjadi kelinci demi cinta! Mungkin akan sedikit lebih nyaman kalau menjadi satu spesies dengannya. Atau mungkin aku saja yang bodoh…",
  str_voice_1300221_50 = "Orang tua… Kau sudah bertemu orang tuamu? Aku belum. Tidak… dia bukan ibuku… hanya orang yang menjualku, itu saja.",
  str_voice_1300221_52 = "Alchemy Stars!",
  str_voice_1300221_53 = "Bagaimana dengan secangkir minyak diesel?",
  str_voice_1300221_54 = "Haha! Pagi!",
  str_voice_1300221_55 = "Sudah waktunya makan siang?",
  str_voice_1300221_56 = "Aku sedikit mengantuk.",
  str_voice_1300221_57 = "Selamat Tahun Baru! Da dam!",
  str_voice_1601051_1 = "3, 2, 1! Tebak siapa? Benar, ini aku, Eve! Sedang apa kau? Ada yang bisa aku bantu?",
  str_voice_1601051_2 = "Aku mencintai saudaraku lebih dari apa pun! Jika ada yang menyakitinya… Oh, maaf soal itu, aku juga tidak akan membiarkan siapa pun menyakitimu!",
  str_voice_1601051_3 = "Ah! S-sesuatu baru saja terbang dari luar! Apakah itu seekor burung? Tidak, terlihat seperti Colossus… Oh, itu hanya kurir…",
  str_voice_1601051_4 = "Baru saja aku mendengar raungan Eclipsite… Aku jadi teringat pada kejadian saat itu… Tidak, aku tidak bisa membiarkan ketakutanku menang! Aku tidak akan takut lagi! *Uhuk-uhuk* Aku baik-baik saja sekarang, lihat? Sangat baik!",
  str_voice_1601051_5 = "Kekuatan itu… Bagaikan petir yang mengalir di pembuluh darahku, menakutkan, tapi luar biasa… Aku merasa seperti bisa melakukan apa saja! Namun, aku tahu… apa pun yang terjadi, aku tidak boleh kehilangan kendali lagi.",
  str_voice_1601051_6 = "Aku ingat betapa saudaraku menderita karena diriku… Aku tidak pernah bisa lepas dari kesalahan masa laluku dan tidak berniat untuk melakukannya… Itu sebabnya aku akan melakukan apa saja untuk meringankan bebannya, mulai dari tugas-tugasnya!",
  str_voice_1601051_7 = "Kau benar-benar baik… *Uhuk-uhuk* Jika kau sungguh-sungguh ingin berbuat sesuatu yang baik untukku, bergabunglah dengan Rediesel Wrench. Hahaha, bercanda!",
  str_voice_1601051_8 = "Baru-baru ini aku mendapat kawan yang memperlakukan aku dan teman-teman lain dengan sangat baik… Bisakah kau tebak siapa itu? Aku akan memberimu petunjuk: orang yang tahu cara mengemudikan Colossus!",
  str_voice_1601051_9 = "Meski kakakku akan selalu menjadi orang yang paling penting bagiku, kurasa kau bisa menjadi yang kedua… atau seri dengan Dawn sebagai yang terpenting kedua!",
  str_voice_1601051_10 = "Anu, a-apa kau sedang sibuk? Jika tidak… bisa kau ceritakan lebih banyak tentang dirimu? Dan mungkin… tentang dunia luar?",
  str_voice_1601051_11 = "Kau… memercayakan ini kepadaku? T-terima kasih! Aku berjanji akan melakukan yang terbaik agar tidak membuat masalah. Aku… Rasanya aku bisa melakukannya?",
  str_voice_1601051_12 = "Kuharap aku bisa duduk-duduk di Bridge sepanjang hari… Di sana sangat indah.",
  str_voice_1601051_13 = "Hmm… Banyak hal yang harus dipelajari, tetapi waktunya sedikit. Dari mana aku harus mulai?",
  str_voice_1601051_14 = "Aku benar-benar bahagia sekarang. Tidak pernah terpikirkan aku bisa hidup seperti ini.",
  str_voice_1601051_15 = "Selamat ulang tahun! Selamat ulang tahun!",
  str_voice_1601051_16 = "Kau kembali… Apakah kau melakukan sesuatu yang seru? Bisakah kau menceritakannya kepadaku?",
  str_voice_1601051_17 = "Sangat mengantuk… Kau bangun sepagi ini? Sangat melelahkan…",
  str_voice_1601051_18 = "Kakak juga sangat sibuk akhir-akhir ini… Kuharap kalian berdua cukup istirahat.",
  str_voice_1601051_19 = "Aku… Aku harus tidur sekarang. Ingatlah untuk segera tidur…",
  str_voice_1601051_20 = "Rediesel Wrench adalah yang terhebat! Ada banyak orang yang menarik di sini, dan kakakku juga!",
  str_voice_1601051_21 = "Aku mungkin tidak memiliki kenangan terindah tentang Illumina… Namun, aku tahu itu bukan salah Illumina.",
  str_voice_1601051_22 = "Apa yang selalu dibilang kakakku? Jalani hidup sepenuhnya?",
  str_voice_1601051_23 = "Aku bisa merasakan kehadiran dan raungan mereka, tapi aku tidak bersama mereka, sama sekali…!",
  str_voice_1601051_24 = "T-tunggu, Dawn! Hari ini aku sudah menyiram bunga!",
  str_voice_1601051_25 = "Kembang api Joanie memang yang terbaik! Tunggu, bukankah itu… bom?!",
  str_voice_1601051_26 = "Berkreasi, piknik, baju baru… Ini semua favoritku! Oh, dan Colossus ini juga!",
  str_voice_1601051_27 = "Siapa pun yang menyakiti kakakku adalah orang jahat… Berlaku juga untukku… Benar?",
  str_voice_1601051_28 = "Aku suka naik Colossus! Aku bisa melihat begitu banyak tempat yang luar biasa dari atas sini!",
  str_voice_1601051_29 = "Biar kucoba lagi… N-namaku Eve, aku adik perempuan Sinsa. S… *Uhuk-uhuk* Senang bertemu denganmu. Aku tahu aku pernah merepotkan semua orang… Namun, aku kini sudah lebih baik! Ta-ra! Lihat?",
  str_voice_1601051_30 = "Aku harus berhati-hati dengan kekuatanku…",
  str_voice_1601051_31 = "Aku bisa mendengar… suara-suara itu…",
  str_voice_1601051_32 = "Aku memiliki kendali yang lebih baik atas diriku sendiri, petir, dan kilat sekarang.",
  str_voice_1601051_33 = "Aku… Aku harus melindungi kakakku!",
  str_voice_1601051_34 = "A-aku bisa melakukannya!",
  str_voice_1601051_35 = "Aku baik-baik saja sekarang!",
  str_voice_1601051_36 = "Bisakah kita mulai sekarang?",
  str_voice_1601051_37 = "Raungan itu tidak asing—",
  str_voice_1601051_38 = "Menembus awan—",
  str_voice_1601051_39 = "Kilat!",
  str_voice_1601051_40 = "Percikan!",
  str_voice_1601051_41 = "Aku? Aku… Aku bisa melakukannya!",
  str_voice_1601051_42 = "Aku berhasil?!",
  str_voice_1601051_43 = "Aku gagal melindungi semua orang…",
  str_voice_1601051_44 = [[
Tempat ini indah!
Jauh lebih baik daripada tempatku dulu!]],
  str_voice_1601051_45 = "Mm… Terima kasih.",
  str_voice_1601051_46 = "Ini untukku? Aku sangat menyukainya, terima kasih!",
  str_voice_1601051_47 = "Bukan itu yang aku pikirkan… Namun, terima kasih!",
  str_voice_1601051_48 = "Kau selalu tahu persis apa keinginanku!",
  str_voice_1601051_49 = "Ketika sedang dikarantina, aku mendengar raungan Eclipsite setiap malam dan merasa takut… Namun, orang-orang di Rediesel Wrench akan selalu menghiburku dan mengingatkanku bahwa aku tidak sendirian…",
  str_voice_1601051_50 = "Kau benar-benar bodoh, Dawn… Itu hanya bunga, bagaimana bisa kau bilang itu lebih penting daripada hidupmu sendiri…",
  str_voice_1601051_51 = "Kakak laki-lakiku banyak menderita karena aku… Beban ini selalu milikku, bukan miliknya. Itulah kenapa aku akan memberikan segalanya untuk melindunginya dengan siapa saja!",
  str_voice_1601051_52 = "Alchemy Stars!",
  str_voice_1601051_53 = "Hei, kau!",
  str_voice_1601051_54 = "S-selamat pagi…",
  str_voice_1601051_55 = "Hmm… Makan siang apa nanti?",
  str_voice_1601051_56 = "Segeralah beristirahat, oke?",
  str_voice_1601051_57 = "Selamat Tahun Baru! Semoga damai dan bahagia menyertaimu sepanjang tahun!",
  str_voice_1501041_1 = "Dibandingkan keabadian, mekarnya bunga hanyalah satu momen kecil.",
  str_voice_1501041_2 = "Kau suka duduk di bawah sinar matahari? Sudah lama aku tidak melakukannya… Matahari terasa ajaib di kulitku… Meski kadang bisa mengejutkanku, kehangatannya dapat terasa menyenangkan.",
  str_voice_1501041_3 = "Jangan terlalu mencemaskanku. Pendengaranku cukup baik, dan aku sudah hafal setiap lorong dan—ADUH! Siapa yang taruh meja ini di sini?",
  str_voice_1501041_4 = "Kekuatan ini tidak pantas dipuji… Aku yakin ada bahaya yang masih belum kita ketahui. Lagi pula, ini adalah kekuatan Eclipsite.",
  str_voice_1501041_5 = "Wanita itu… Aku yakin dia telah melakukan penelitian yang lebih menakutkan dari sebelumnya. Memikirkannya saja membuatku bergidik…",
  str_voice_1501041_6 = "Pasti ada orang lain seperti aku dan Eve di dunia ini, dan begitu aku menemukan mereka… Aku akan melakukan segalanya untuk membantu mereka.",
  str_voice_1501041_7 = "Hmm, sekarang kita sudah cukup akrab untuk saling berbagi rahasia… Jadi, kenapa tidak kau mulai?",
  str_voice_1501041_8 = "Bahkan dalam mimpiku pun aku tidak mengira aku bisa memiliki kehidupan yang bebas seperti ini. Eve, Sinsa, Rediesel Wrench… Mereka semua temanku, begitu juga kau.",
  str_voice_1501041_9 = "Bunga memiliki arti khusus bagi Eve dan aku… Bunga mengingatkan kami pada saat kami harus meringkuk bersama agar hangat. Namun, kami tidak khawatir kesepian lagi… karena kami memilikimu.",
  str_voice_1501041_10 = "Kau berhenti? Aku memang tidak bisa melihat, tetapi aku bisa merasakannya.",
  str_voice_1501041_11 = "Kau bisa mengandalkanku, tetapi bisakah kau menyirami bunga Eve untukku?",
  str_voice_1501041_12 = "Ya? Aku makin akrab dengan tata letak ruangan ini.",
  str_voice_1501041_13 = "Udara di Colossus ini berbeda… Mungkin seperti inikah aroma langit?",
  str_voice_1501041_14 = "Kau di sana? Tidak heran tiba-tiba suasana menjadi ramai.",
  str_voice_1501041_15 = "Aku membuat karangan bunga ini hanya untukmu. Selamat ulang tahun.",
  str_voice_1501041_16 = "Ada rencana apa hari ini? Tidak ada? Jalan-jalan, yuk? dan mungkin berjemur di bawah sinar matahari sebentar?",
  str_voice_1501041_17 = "Selamat pagi? Pada semburat cahaya pertama fajar, matahari yang terbit membuat kegelapan malam sirna. Indah, bukan?",
  str_voice_1501041_18 = "Malam ini dingin. Jangan sampai masuk angin.",
  str_voice_1501041_19 = "Kau tidak berencana untuk bergadang semalaman, 'kan? Mengapa kau melakukannya pada dirimu sendiri?",
  str_voice_1501041_20 = "Rumah Eve adalah rumahku, dan keluarganya… adalah keluargaku.",
  str_voice_1501041_21 = "Illumina… Aku tidak punya apa-apa selain kenangan sedih tentang tempat itu.",
  str_voice_1501041_22 = "\"Jalani hidup sepenuhnya!\" Tiada hari tanpa seseorang di Rediesel Wrench yang meneriakkannya sekencang mungkin.",
  str_voice_1501041_23 = "Aku dulu mendominasi Eclipsites di Red-eye Gorge untuk sementara waktu. Cukup mengesankan, 'kan?",
  str_voice_1501041_24 = "Aku bersumpah akan selalu menghadapi matahari, seberapa pun panasnya.",
  str_voice_1501041_25 = "Aku tidak percaya Sinsa ternyata kakaknya Eve… Mereka tidak mirip!",
  str_voice_1501041_26 = "Eve menyukai bunga. Aku juga menyukainya.",
  str_voice_1501041_27 = "Suara api yang membara… selalu membuatku terkenang masa-masa menyakitkan itu.",
  str_voice_1501041_28 = "Jadi, inikah Colossus yang tahan badai? Baunya cukup keren.",
  str_voice_1501041_29 = "Kita berjumpa lagi. Mari buat beberapa aturan dasar untuk kerja sama kita: Jangan mengganggu Eve, jangan membuatnya tidak senang, dan jangan biarkan dia kelaparan. Paham?",
  str_voice_1501041_30 = "Aku menjadi lebih kuat…",
  str_voice_1501041_31 = "Aku harus mengendalikan kekuatan ini…",
  str_voice_1501041_32 = "Beberapa bunga hanya mekar sekali sepanjang hidupnya.",
  str_voice_1501041_33 = "Keabadian dalam sekejap.",
  str_voice_1501041_34 = "Dimengerti.",
  str_voice_1501041_35 = "Bunga mekar.",
  str_voice_1501041_36 = "Rebut kesempatan!",
  str_voice_1501041_37 = "Sekarang, ayo pergi!",
  str_voice_1501041_38 = "Jangan pernah lupakan momen ini.",
  str_voice_1501041_39 = "Aku datang untuk membantu!",
  str_voice_1501041_40 = "Usai sudah.",
  str_voice_1501041_41 = "Bolehkah aku melakukannya?",
  str_voice_1501041_42 = "Hasil yang tak terbantahkan.",
  str_voice_1501041_43 = "Jangan panik, ambil napas dalam-dalam.",
  str_voice_1501041_44 = "Aku ingat seharusnya aku belok kiri di sini, lalu…",
  str_voice_1501041_45 = "Terima kasih atas hadiahmu.",
  str_voice_1501041_46 = "Kau lebih perhatian dari yang kubayangkan.",
  str_voice_1501041_47 = "Aku akan menyimpannya.",
  str_voice_1501041_48 = "Pikiran kita tampaknya selaras satu sama lain.",
  str_voice_1501041_49 = "Ibuku, dan wanita itu… Yang mereka pedulikan hanyalah penelitian dan eksperimen, tetapi aku tidak akan pernah bertemu Eve andai bukan karena mereka. Mungkin inilah takdir…",
  str_voice_1501041_50 = "Aku takkan pernah melupakan hari-hari itu di laboratorium. Eve selalu ada untukku… Kebaikan dan kemurniannya membuatku merasa mungkin dunia luar tidak seburuk itu… mungkin aku bisa duduk di bawah sinar matahari lagi.",
  str_voice_1501041_51 = "Masa lalu adalah masa lalu. Kita tidak perlu lagi bertahan dari penderitaan semacam itu. Aku hanya berharap hari-hari ini takkan pernah usai… Dan aku akan melakukan apa pun yang harus kulakukan untuk mewujudkan keinginan itu.",
  str_voice_1501041_52 = "Alchemy Stars.",
  str_voice_1501041_53 = "Hai, Navigator.",
  str_voice_1501041_54 = "Matahari terbit lagi…",
  str_voice_1501041_55 = "Ingatlah untuk makan makanan sehat.",
  str_voice_1501041_56 = "Malam yang sunyi selalu membuat suasana hatiku baik.",
  str_voice_1501041_57 = "Selamat Tahun Baru! Resolusi Tahun Baruku adalah melihat Eve tersenyum lebih banyak lagi! Bagaimana denganmu? Hmm, ambisius, tetapi aku yakin kau bisa melakukannya.",
  str_voice_1401011_1 = "Ssst, lihat musuh di sana? Sebaiknya kita lari selagi bisa! Perhatikan langkahmu saat melarikan diri… Kau tahu aku bercanda, 'kan?",
  str_voice_1401011_2 = "Kau kehilangan sesuatu? Hei, jangan menatapku! Aku memang suka berkelakar, tetapi aku tidak pernah mencuri… Aku bahkan mau membantumu mencari jika itu bisa membersihkan namaku!",
  str_voice_1401011_3 = "Aku takkan pernah berkelakar di tempat kerja, tetapi aku sedang tidak bertugas sekarang, jadi… Mau tahu apa yang kulakukan?",
  str_voice_1401011_4 = "Kurasa pertarungan terakhir menimbulkan beberapa masalah… Oh, hei, kebetulan! Aku sedang memperbaiki beberapa perangkat kita, bisakah kau membantuku dan memeriksa volumenya?",
  str_voice_1401011_5 = "Terima kasih telah memercayaiku, aku akan terus berusaha keras dan melakukan yang terbaik! Untuk pekerjaanku DAN kelakarku!",
  str_voice_1401011_6 = "Seorang juru sinyal yang baik harus sabar, fokus, dan siap beradaptasi di segala situasi agar dapat berkomunikasi dengan cepat dan efektif!",
  str_voice_1401011_7 = "Kami mengganggu jam kerjamu untuk menyampaikan pesan mendesak: Seekor ulat besar telah muncul di kamar Navigator! Selain itu, jelas bukan aku yang meletakkannya di sana!",
  str_voice_1401011_8 = "Hei, Navigator? Untuk menunjukkan kepedulianku, mulai hari ini aku akan memberimu lebih banyak kejutan!",
  str_voice_1401011_9 = "Kelakar yang baik dapat memperkuat persahabatan antara dua orang, tetapi aku takkan pernah bersikap keterlaluan. Lagi pula, aku tidak mau dianggap buruk olehmu!",
  str_voice_1401011_10 = "Aku membuat teka-teki karena sangat bosan. Aku baru saja memasang jebakan untukmu. Coba tebak di mana?",
  str_voice_1401011_11 = "Baiklah! Juru sinyal Ansia, bersiaga untuk memastikan komunikasi yang tepat waktu dan akurat… Tunggu, kau tidak menyuruhku melakukannya sekarang?",
  str_voice_1401011_12 = "Ada pekerjaan singkat yang harus kukerjakan, aku akan segera kembali setelah selesai!",
  str_voice_1401011_13 = "Lewat sini! Jika kau jatuh ke dalam perangkapku, aku takkan membantumu… Oh, kau sudah jatuh.",
  str_voice_1401011_14 = "Oh, kau mau tahu apa yang tertulis pada catatan di punggungmu? Rahasia!",
  str_voice_1401011_15 = "Selamat ulang tahun! Ini hadiahmu… Haha, bercanda! Hadiahmu yang sebenarnya ada tepat di belakangmu!",
  str_voice_1401011_16 = "Bagaimana pekerjaannya? Jika membutuhkan juru sinyal, kau bisa menghubungiku kapan saja!",
  str_voice_1401011_17 = "Pagi! Ada pesan yang perlu dikirim? Lagi-lagi tidak ada?",
  str_voice_1401011_18 = "Selamat malam! Hari telah berakhir, ingatlah untuk merangkum semua yang perlu dilaporkan!",
  str_voice_1401011_19 = "Ini sudah tengah malam! Tidak akan ada yang menjawab pesanmu selarut ini… kecuali aku menggunakan salah satu teknik rahasiaku!",
  str_voice_1401011_20 = "Illumina adalah rumahku, selalu. Aku akan melakukan apa pun untuk melindunginya.",
  str_voice_1401011_21 = "Jika aku tidak ada di Illumina, aku ada di Umbraton. Di sana kelakarku lebih dihargai.",
  str_voice_1401011_22 = "Jayalah Illumina!",
  str_voice_1401011_23 = "Kelak ketika Eclipsite tidak lagi mengancam Astra… Aku tahu hari itu akan tiba.",
  str_voice_1401011_24 = "Vice sungguh luar biasa, kuat, dan dapat diandalkan… Aku ingin menjadi seperti dia!",
  str_voice_1401011_25 = "Kuberitahu sebuah rahasia, ya… Aku sangat ingin bermain dengan ekor Sharona. Aku yakin pasti akan menyenangkan!",
  str_voice_1401011_26 = "Aku suka musik metal, tahu? Iramanya, energinya… Benar-benar membuatku bersemangat!",
  str_voice_1401011_27 = "Aku tidak tahan dengan orang yang tidak profesional. Ketika sedang bekerja, kau harus bekerja keras!",
  str_voice_1401011_28 = "Walau aku tahu apa itu Colossus, tetap saja, mengagumkan!",
  str_voice_1401011_29 = "Tes! Tes! Ini Ansia yang sedang berbicara. Aku adalah juru sinyal utama Illumina dan mungkin akan menghubungimu lebih dulu karena aku belum menerima perintah kerja darimu!",
  str_voice_1401011_30 = "Naikkan volume!",
  str_voice_1401011_31 = "Pemeliharaan rutin pada peralatan komunikasi kita juga merupakan bagian dari pekerjaan!",
  str_voice_1401011_32 = "Mau tahu soal pekerjaanku sebagai juru sinyal? Ini pekerjaan yang keren!",
  str_voice_1401011_33 = "Waktunya mengirimkan sinyal ke bulan!",
  str_voice_1401011_34 = "Aku akan mengurus komunikasi!",
  str_voice_1401011_35 = "Penyiapan selesai!",
  str_voice_1401011_36 = "Gelombang sonik siaga!",
  str_voice_1401011_37 = "Supersonik!",
  str_voice_1401011_38 = "Goyangkan!",
  str_voice_1401011_39 = "Terkejut?",
  str_voice_1401011_40 = "Jangan bergerak!",
  str_voice_1401011_41 = "Kabar-kabari, ya, semuanya!",
  str_voice_1401011_42 = "Semuanya baik-baik saja!",
  str_voice_1401011_43 = "Kabur!",
  str_voice_1401011_44 = "Halo? Terdengar, tidak? Ya, aku mendengarmu dengan keras dan jelas!",
  str_voice_1401011_45 = "Hadiah? Apakah itu jack-in-the-box?",
  str_voice_1401011_46 = "Wow! Bisakah aku benar-benar memiliki ini?",
  str_voice_1401011_47 = "Sebenarnya aku mengharapkan jack-in-the-box, tahu!",
  str_voice_1401011_48 = "Terima kasih! Sekarang, izinkan aku untuk membalas budi!",
  str_voice_1401011_49 = "Meski bukan petarung, akhirnya aku menemukan sesuatu yang menjadi keunggulan—komunikasi! Sebagai juru sinyal, aku memastikan semua orang akan selalu tahu kabar terbaru!",
  str_voice_1401011_50 = "Suatu kali, aku diam-diam mengeluarkan magasin dari pistol seorang petugas Illumina. Dia marah sekali ketika menyadari bahwa magasinnya hilang. Akan tetapi, tanpa amunisi, dia tidak berdaya, jadi dia malah pergi sambil marah-marah!",
  str_voice_1401011_51 = "Aku melakukan pekerjaan pengintaian dari waktu ke waktu. Sebahaya apa pun situasinya, juru sinyal harus mengerahkan segala daya untuk memastikan pesan mencapai tujuannya dengan cepat!",
  str_voice_1401011_52 = "Alchemy Stars—!",
  str_voice_1401011_53 = "Tes, satu, dua, tiga!",
  str_voice_1401011_54 = "Kau mendapat pesan baru!",
  str_voice_1401011_55 = "Jawablah!",
  str_voice_1401011_56 = "Malam, Navigator!",
  str_voice_1401011_57 = "Selamat Tahun Baru! Semoga kau mendapatkan lebih banyak kabar baik pada tahun baru!",
  str_voice_1501001_1 = "Aku tinggal di sini hanya karena aku ingin. Tidak ada hubungannya denganmu, bocah polos.",
  str_voice_1501001_2 = "Dasar bocah polos, tetapi kau berbeda dari paramecia itu. Mungkin itu sebabnya kau bisa mengemudikan Colossus.",
  str_voice_1501001_3 = "Kadang tidak ada gunanya mencoba membicarakan hal yang masuk akal kepada orang-orang bodoh itu. Beri mereka perintah saja.",
  str_voice_1501001_4 = "Aku takkan pernah membutuhkan bantuan paramecia itu, sesulit apa pun situasinya.",
  str_voice_1501001_5 = "Bisakah kau mencium bahayanya sekarang? Mulai sekarang, kau harus berhati-hati saat mendekatiku.",
  str_voice_1501001_6 = "Kau terkejut, bocah polos? Ini adalah kekuatanku yang sebenarnya, tetapi aku sama sekali tidak peduli.",
  str_voice_1501001_7 = "Dantes Family bertanggung jawab untuk menjaga Starry Crypt sejak zaman kuno. Aku tidak punya pilihan selain mewarisi misi ini.",
  str_voice_1501001_8 = "Kekuatanku berasal dari keluargaku, tetapi apa yang aku alami sekarang… akan menjadi kekuatan berharga milikku seorang.",
  str_voice_1501001_9 = "Banyak yang bilang hidupku selamanya untuk Catacomb, tetapi kelak aku akan meninggalkannya dengan kekuatanku sendiri setelah misiku selesai.",
  str_voice_1501001_10 = "Kau sedang menganggur, bocah polos? Mau bertukar tempat? Ayo duduk di sini.",
  str_voice_1501001_11 = "Tidak bisakah kau melakukan tugasmu dengan benar, bocah polos? Baik, aku akan membantumu.",
  str_voice_1501001_12 = "Jadi, bagaimana jika mereka tahu masa laluku? Yang bisa mereka lakukan hanyalah mengeluh.",
  str_voice_1501001_13 = "Aku harap kau takkan selalu mengajukan pertanyaan macam orang bodoh itu.",
  str_voice_1501001_14 = "Jangan menempatkanku dengan orang lain. Aku suka ketenangan dan kesunyian… Walau aku tidak menyuruhmu pergi.",
  str_voice_1501001_15 = "Ulang tahun… Sudah lama sejak kali terakhir aku mendengar kata ini. Baiklah… Selamat ulang tahun, bocah polos.",
  str_voice_1501001_16 = "Berhentilah menyapaku terus-terusan. Lakukan apa yang harus kau lakukan, bocah polos.",
  str_voice_1501001_17 = "Pagi selalu sepi, tetapi akan menjadi sangat berisik saat orang-orang bodoh itu bangun.",
  str_voice_1501001_18 = "Nikmati sinar matahari siang yang menyilaukan sendirian, bocah polos. Aku mau istirahat dulu.",
  str_voice_1501001_19 = "Aku ingin menikmati malam yang damai ini, bocah polos. Jangan biarkan paramecia menggangguku.",
  str_voice_1501001_20 = "Orang-orang itu tampak ganjil, tetapi untungnya mereka tidak menggangguku.",
  str_voice_1501001_21 = "Jangan khawatir. Aku takkan memaksa mereka untuk berpikir dengan otak yang sebesar paramecium.",
  str_voice_1501001_22 = "Baiklah, semoga Truth memberkatimu.",
  str_voice_1501001_23 = "Makhluk menyedihkan yang tidak bisa memegang lilin bahkan bagi paramecia.",
  str_voice_1501001_24 = "Lady Victoria kuat, tetapi dia masih jauh dari kata mampu untuk mengintip rahasia Catacomb.",
  str_voice_1501001_25 = "Pact sama keras kepalanya seperti cincinnya yang kaku. Aku tidak seperti dia dalam hal ini.",
  str_voice_1501001_26 = "Malam yang tenang. Akan sempurna jika ada semilir angin.",
  str_voice_1501001_27 = "Ada terlalu banyak paramecia berisik di benua ini.",
  str_voice_1501001_28 = "Tubuhnya sangat besar, tetapi sangat pendiam ketika terbang. Ia memang ciptaan dari peradaban kuno.",
  str_voice_1501001_29 = "Aku Sikare, Keeper of the Crypt. Kenapa kau terkejut? Kuharap nama jabatanku tidak membuatmu takut.",
  str_voice_1501001_30 = "Inilah kekuatan sejatiku.",
  str_voice_1501001_31 = "Faria terbangun.",
  str_voice_1501001_32 = "Aku telah mengamankan kekuatan Catacomb.",
  str_voice_1501001_33 = "Mungkin… Aku bisa membebaskan diri dari ruang bawah tanah.",
  str_voice_1501001_34 = "Yang aku butuhkan adalah diriku sendiri.",
  str_voice_1501001_35 = "Tunjukan dirimu.",
  str_voice_1501001_36 = "Faria, bersiaplah.",
  str_voice_1501001_37 = "Faria, buka!",
  str_voice_1501001_38 = "Faria, lepaskan!",
  str_voice_1501001_39 = "Napas kematian.",
  str_voice_1501001_40 = "Selamat tinggal, paramecia.",
  str_voice_1501001_41 = "Aku tidak terbiasa bekerja dengan orang lain.",
  str_voice_1501001_42 = "Itu usaha terbaikmu?",
  str_voice_1501001_43 = "Aku akan menahan mereka.",
  str_voice_1501001_44 = "Kau mau lihat Catacomb yang sebenarnya, bocah polos?",
  str_voice_1501001_45 = "Aku tidak tertarik, bocah polos.",
  str_voice_1501001_46 = "Mmm, ini baru sesuai.",
  str_voice_1501001_47 = "Keluarga Dantes akan mengingat hadiahmu, bocah polos.",
  str_voice_1501001_48 = "Kau… Terima kasih.",
  str_voice_1501001_49 = "Dantes Family bukanlah bawahan dari True Order. Malahan, mereka adalah sekutu. Kau harus bisa membedakannya.",
  str_voice_1501001_50 = "Faria… Ini adalah kunci Starry Crypt. Grave Keeper adalah satu-satunya orang yang bisa mengendalikannya. Kau tidak perlu tahu banyak soal ini. Akan kujelaskan saat kurasa perlu.",
  str_voice_1501001_51 = "Sejak aku lahir, misiku adalah menjaga Catacomb ini hingga aku mati, atau… terlahir kembali.",
  str_voice_1501001_52 = "Alchemy Stars.",
  str_voice_1501001_53 = "Halo, bocah polos.",
  str_voice_1501001_54 = "Selamat pagi, bocah polos.",
  str_voice_1501001_55 = "Oh, selamat sore…",
  str_voice_1501001_56 = "Sudah larut. Selamat malam, bocah polos.",
  str_voice_1501001_57 = "Selamat Tahun Baru.",
  str_voice_1500981_1 = "Aku tidak bermaksud menambahkan cabai ke kue. Aku kira cabai itu semacam ceri panjang.",
  str_voice_1500981_2 = "Bunga hitam itu… Sangat cantik.",
  str_voice_1500981_3 = "Aku tidak memahami perkataanmu, tetapi… Kau tampak bahagia. Mungkin aku harus tertawa bersamamu.",
  str_voice_1500981_4 = "Aku tidak ingat siapa diriku, atau mengapa aku ada di sini. Satu-satunya hal yang aku tahu adalah aku punya misi untuk menyegel pohon itu.",
  str_voice_1500981_5 = "Aroma terkutuk merusak pikiran semua pengunjung, membuat mereka menjadi makhluk terobsesi, yang pada akhirnya menjadi nutrisi kita.",
  str_voice_1500981_6 = "Arwah-arwah gelisah itu melayang-layang di tepi pohon terkutuk itu, menggumamkan kata-kata yang tidak bisa kami mengerti, mencoba menghilangkan akal sehatku.",
  str_voice_1500981_7 = "Kau sedikit berbeda dari yang lain. Sudah lama aku tidak merasakan hal semacam ini.",
  str_voice_1500981_8 = "Beberapa hal memicu ingatanku, tetapi tidak ada cerita yang berakhir bahagia karena aku bahkan tidak dapat memahami diriku pada masa lalu.",
  str_voice_1500981_9 = "Kuharap kau adalah hal pertama yang kulihat setiap kali aku bangun sebagai diriku yang baru.",
  str_voice_1500981_10 = "Begitu sunyi… Seolah-olah aku terasingkan…",
  str_voice_1500981_11 = "Lakukan saja apa yang biasa kau lakukan.",
  str_voice_1500981_12 = "Betapa aku ingin menatap bunga-bunga yang bermekaran dari mayat beberapa kali lagi… Namun, Istvan tidak mengizinkanku untuk melakukannya sesuai keinginan.",
  str_voice_1500981_13 = "Jangan cemas. Aku tidak punya masalah kesehatan. Tidak akan pernah.",
  str_voice_1500981_14 = "Caelestite… Sepertinya aku punya beberapa kenangan tentang mereka… Kenangan itu terkubur di suatu tempat jauh di dalam otakku, begitu dalam sampai-sampai aku tidak bisa menjangkaunya.",
  str_voice_1500981_15 = "Selamat ulang tahun! Semoga hari-harimu dipenuhi dengan sukacita.",
  str_voice_1500981_16 = "Pastikan untuk memanfaatkan waktu terbaik hari ini…",
  str_voice_1500981_17 = "Selamat pagi. Tetap bekerja dengan baik hari ini.",
  str_voice_1500981_18 = "Kau kembali. Lupa sesuatu?",
  str_voice_1500981_19 = "Aku tidak perlu tidur. Jangan khawatir.",
  str_voice_1500981_20 = "Umbraton… Berbahaya, tetapi membuatku merasa nyaman. Rasanya itu sempurna untukku.",
  str_voice_1500981_21 = "Aku terkadang melihat orang-orang dari Illumina. Mereka tampak… ramah.",
  str_voice_1500981_22 = "Istvan telah mengawasimu…",
  str_voice_1500981_23 = "Makhluk mengerikan… Yang terpenting… Mereka tidak memiliki emosi…",
  str_voice_1500981_24 = "Istvan sangat berempati. Itulah alasan dia punya banyak pengikut.",
  str_voice_1500981_25 = "Anu… Sepertinya Kleken tidak suka mengobrol denganku.",
  str_voice_1500981_26 = "Bunga-bunga yang bermekaran dari mayat membuatku tertarik, tetapi aku tidak yakin apakah ini adalah emosi yang dialami orang-orang ketika mereka menyukai sesuatu.",
  str_voice_1500981_27 = "Aku tidak membenci apa pun. Tidak ada bedanya bagiku…",
  str_voice_1500981_28 = "Colossus… Aku agak merindukan kata ini. Akan sangat menyenangkan jika aku bisa berbicara dengan mereka…",
  str_voice_1500981_29 = "Senang bertemu denganmu… Namaku Cuscuta. Asalku dari Umbraton… Apakah ini terlalu formal?",
  str_voice_1500981_30 = "Kutukan itu makin kuat…",
  str_voice_1500981_31 = "Aku bisa bertahan…",
  str_voice_1500981_32 = "Energi kutukan akan meluap.",
  str_voice_1500981_33 = "Tubuh ini tertidur.",
  str_voice_1500981_34 = "Aku di sini.",
  str_voice_1500981_35 = "Ada nutrisi yang cukup.",
  str_voice_1500981_36 = "Aku siap jika kau siap.",
  str_voice_1500981_37 = "Ini akan mengurangi kesusahanmu.",
  str_voice_1500981_38 = "Semoga bunga-bunga yang indah mekar dari dalam dirimu.",
  str_voice_1500981_39 = "Kembali menjadi debu…",
  str_voice_1500981_40 = "Tidur dalam damai.",
  str_voice_1500981_41 = "Aku akan mencobanya.",
  str_voice_1500981_42 = "Akhirnya akan ada lautan bunga di sini.",
  str_voice_1500981_43 = "Aku perlu tubuh baru.",
  str_voice_1500981_44 = "Aku sedang melihat-lihat Colossus milikmu. Ada yang bisa kubantu?",
  str_voice_1500981_45 = "Terima kasih atas hadiahmu.",
  str_voice_1500981_46 = "Tampaknya agak istimewa.",
  str_voice_1500981_47 = "Inikah yang kau sebut… tanda hormatmu?",
  str_voice_1500981_48 = "Hatiku terasa hangat…",
  str_voice_1500981_49 = "Aku tidak ingat sudah berapa kali aku terjaga. Itu pasti sebabnya aku kehilangan begitu banyak kenangan dan emosi. Itu membuktikan bahwa aku sudah mati berkali-kali.",
  str_voice_1500981_50 = "Aku bisa menyingkirkan orang tanpa suara. Itu sebabnya Istvan menugaskanku untuk mengeksekusi orang. Aku menerimanya karena bunga yang bermekaran dari tubuh itu indah.",
  str_voice_1500981_51 = "Aku mencoba mengobrol tentang hal-hal lain dengan orang-orang, tetapi terlalu sulit. Aku bahkan tidak tahu harus berkata apa.",
  str_voice_1500981_52 = "Alchemy Stars.",
  str_voice_1500981_53 = "Halo.",
  str_voice_1500981_54 = "Selamat pagi. Hari yang baru telah dimulai.",
  str_voice_1500981_55 = "Selamat siang. Kau sedang istirahat?",
  str_voice_1500981_56 = "Mimpi indah.",
  str_voice_1500981_57 = "Selamat Tahun Baru. Kuharap kau akan mendapatkan awal yang baru seiring datangnya tahun baru.",
  str_voice_1500561_1 = "Dengar baik-baik dan bersabarlah. Setelahnya, kau bisa membunuh Eclipsite, secara solo. Hmm? Apa yang aku maksud dengan solo? Itu berarti kau melawan mereka semua sendirian! Mudah sekali.",
  str_voice_1500561_2 = "Trik menggunakan senapan adalah dengan membidik kepala mereka. Jika tembakanmu meleset, mendekatlah. Jika masih belum berhasil… Coba masukkan pistolmu ke mulutnya.",
  str_voice_1500561_3 = "Tidak usah terlalu khawatir. Itu tidak ada gunanya. Jangan sampai membebanimu begitu. Jadi… Hei, Nak, sedang apa kau di sini?! Kau tidak tahu tempat ini dipenuhi Eclipsite? Pulang sana!",
  str_voice_1500561_4 = "Senapan berburu ini milik seorang pahlawan sejati, yang napas terakhirnya dihabiskan untuk melawan Eclipsite. Darah kering ini adalah bukti keberaniannya, dan aku takkan pernah melupakannya.",
  str_voice_1500561_5 = "Aku suka badai salju. Ketika salju yang berputar-putar menutupi matahari dan langit, sebenarnya aku merasa jauh lebih aman.",
  str_voice_1500561_6 = "Pemburu yang baik selalu waspada dan menjaga matanya tetap awas. Dalam badai salju yang menyilaukan atau malam yang kelam, mereka tidak pernah tersesat.",
  str_voice_1500561_7 = "Tinggi, berat, waktu kematian… Aku mencatat setiap detail, dari jaringan yang rusak hingga luka terkecil pada mayat. Dengan begitu, kita tidak hanya mempelajari kematian… tapi juga mempelajari kehidupan.",
  str_voice_1500561_8 = "Kau harus mencoba bermeditasi di tengah badai salju saat sedang merasa stres. Tersesat dalam angin dan salju akan membantumu menjernihkan pikiran. Itu jauh lebih berguna daripada tidur.",
  str_voice_1500561_9 = "Ini hanya perhentian singkat dalam perjalanan pengembaraanku. Jujur saja rasanya aneh… Meskipun tubuhku sudah karatan, hatiku meleleh seperti es. Ini semua berkatmu, Nak.",
  str_voice_1500561_10 = "Ini hari yang indah. Hanya saja kurang badai salju yang indah… Hmm? Apakah itu aneh?",
  str_voice_1500561_11 = "Butuh bantuan? Tentu saja, kau sudah membantuku dengan catatan itu sebelumnya.",
  str_voice_1500561_12 = "Aku sesekali membuat sketsa Eclipsite untuk membuat catatan itu menarik.",
  str_voice_1500561_13 = "Penasaran dengan buku catatanku, ya? Aku menemukannya di reruntuhan juga. Kondisinya masih oke…",
  str_voice_1500561_14 = "Anjing pemburu lebih mengerikan daripada serigala, tentunya… Namun, andai kau seekor beruang, tidak banyak yang perlu ditakuti.",
  str_voice_1500561_15 = "Selamat ulang tahun, Nak. Kau akan makin bepengalaman dan dewasa seiring bertambahnya usia.",
  str_voice_1500561_16 = "Oh? Hari ini kau sedang bersemangat, ya?",
  str_voice_1500561_17 = "Selamat pagi. Rencana satu hari dimulai dengan fajar.",
  str_voice_1500561_18 = "Selamat malam. Ingatlah untuk makan malam makanan yang sehat.",
  str_voice_1500561_19 = "Bekerja selarut ini, hmm? Kau sedang mencari Eclipsite nokturnal yang langka?",
  str_voice_1500561_20 = "Kurasa Northland lebih aman daripada lokasi lainnya, tetapi kau harus berlatih sendiri untuk menahan rasa dingin yang menusuk.",
  str_voice_1500561_21 = "Illumina tidak kekurangan tentara sejati… Aku akan bergabung dengan mereka jika berkesempatan.",
  str_voice_1500561_22 = "Demi Utara.",
  str_voice_1500561_23 = "Apa yang benar-benar membuat orang-orang merinding adalah betapa miripnya Eclipsite bagi Aurorian…",
  str_voice_1500561_24 = "Louise juga suka merekam. Senang rasanya bukan hanya aku saja yang menyukainya.",
  str_voice_1500561_25 = "Sang Ratu mempertahankan Northland dengan segenap kekuatannya. Merupakan kehormatan bagiku untuk dilahirkan di sana.",
  str_voice_1500561_26 = "Andai punya buku catatan lain, aku akan menulis buku resep berisi cara memasak Eclipsite dengan benar…",
  str_voice_1500561_27 = "Jangan sampai ada yang tersisa satu gigit pun, nanti kau menyesal saat sedang sangat lapar.",
  str_voice_1500561_28 = "Tidak ada Eclipsite di Colossus, 'kan? Hebat! Meski itu bukan masalah selama ada aku.",
  str_voice_1500561_29 = "Tersesat adalah nasib seorang pengembara, dengan kesendirian sebagai satu-satunya pendamping. Maukah kau membaca buku catatanku? Aku telah menuliskan semua yang pernah kulihat di buku itu. Duduklah dan dengarkan ceritaku…",
  str_voice_1500561_30 = "Satu-satunya teman bagi pemburu adalah daya tahan!",
  str_voice_1500561_31 = "Seorang pemburu yang hebat harus bersabar.",
  str_voice_1500561_32 = "\"Mereka yang bertarung melawan monster harus waspada agar tidak menjadi monster.\"",
  str_voice_1500561_33 = "Buat keputusanmu dengan tekad bulat, bahkan jika tidak ada harapan pada akhirnya.",
  str_voice_1500561_34 = "Setelah keputusanmu bulat, jangan melihat ke belakang.",
  str_voice_1500561_35 = "Tetap tenang, tetap fokus—",
  str_voice_1500561_36 = "Siap tembak!",
  str_voice_1500561_37 = "Sekali tembak, satu musuh mati!",
  str_voice_1500561_38 = "Kau dan aku, maju!",
  str_voice_1500561_39 = "Jangan bergerak!",
  str_voice_1500561_40 = "Minggir!",
  str_voice_1500561_41 = "Ikuti aku atau kau akan terluka!",
  str_voice_1500561_42 = "Menang! Keluarkan minumannya!",
  str_voice_1500561_43 = "Pemburu yang terlalu percaya diri tidak ada bedanya dengan mangsanya…",
  str_voice_1500561_44 = "Pekerjaan pemburu tidak layak dibahas. Aku hanya menulis tentang itu di buku catatan ini, paham?",
  str_voice_1500561_45 = "Hadiah? Kau baik sekali…",
  str_voice_1500561_46 = "Oh, aku suka yang ini!",
  str_voice_1500561_47 = "Terima kasih. Aku pasti akan membalas budi.",
  str_voice_1500561_48 = "Itulah yang selalu kuinginkan…",
  str_voice_1500561_49 = "Meskipun sekarang aku sudah kuat, pada masa mudaku aku cukup kecil dan lemah. Meski demikian, aku mengikuti ayahku setiap hari berjalan di dataran yang tertutup salju. Begitulah caraku menyukai pencatatan perjalananku.",
  str_voice_1500561_50 = "Sama seperti Northland dengan badai saljunya, Rediesel Desert juga memiliki badai pasir. Seperti halnya hidup… Dan apa yang kumiliki? Senapan berburu, sebuah buku catatan, dan satu setel pakaian tua compang-camping.",
  str_voice_1500561_51 = "Louise benar, perjalanan seorang pengembara kelak akan berakhir tepat di tempat yang seharusnya. Aku selalu mengecamkannya di dalam hatiku… Namun, untuk saat ini, aku masih menikmati kehidupanku sebagai pengembara.",
  str_voice_1500561_52 = "Alchemy Stars.",
  str_voice_1500561_53 = "Apa kau di sana?",
  str_voice_1500561_54 = "Kau bangun lebih awal, Nak.",
  str_voice_1500561_55 = "Kau sudah beristirahat siang ini?",
  str_voice_1500561_56 = "Namun, apa kau punya waktu sebentar?",
  str_voice_1500561_57 = "Selamat Tahun Baru! Aku menangkap sesuatu khusus untukmu.",
  str_voice_1600931_1 = "Bolehkah aku mempelajarimu? Tenanglah, yang harus kau lakukan hanyalah merebahkan badan.",
  str_voice_1600931_2 = "Colossus memang hebat, ya? Berkatnya, aku tidak perlu lagi pusing-pusing memikirkan tempat untuk tidur siang.",
  str_voice_1600931_3 = "Bagaimana bisa peneliti ilmiah Illumina begitu muda? Bawa Vivian kemari kalau begitu.",
  str_voice_1600931_4 = "Pelayan Lilin hebat, ya? Aku ingin tahu apakah aku bisa mendapatkan pelayan juga. Dengan begitu, aku tidak perlu makan sendiri lagi.",
  str_voice_1600931_5 = "Jangan meremehkan Gronru karena tubuhnya yang mungil. Keterampilannya tidak diragukan lagi, tetapi yang lebih penting… Sosoknya bahkan lebih hebat dari yang kubayangkan!",
  str_voice_1600931_6 = "Kehadiranmu cukup menimbulkan kehebohan. Baiklah, memang sudah sewajarnya.",
  str_voice_1600931_7 = "Aku menyukaimu, Nak. Boleh aku membedahmu sedikit?",
  str_voice_1600931_8 = "Ingatlah untuk selalu tetap tenang. Dengan begitu, kau masih bisa melihat hal-hal terpenting pada saat-saat yang paling mendesak.",
  str_voice_1600931_9 = "Aku akan membangun lab baru di Colossus. Aku bisa melanjutkan penelitian biologiku di mana saja.",
  str_voice_1600931_10 = "Cuacanya sedang bagus, jadi aku mau mencari tempat untuk tidur siang.",
  str_voice_1600931_11 = "Hubungi aku kalau ada hal-hal yang menarik saja. Aku tidak suka direcoki dengan gangguan kecil.",
  str_voice_1600931_12 = "Aku penasaran dengan caramu menghabiskan 17 tahun di sini. Ceritakan padaku jika kau sedang senggang.",
  str_voice_1600931_13 = "Kau tidak punya minuman beralkohol di sini? Umbraton adalah satu-satunya tempat aku bisa mendapatkan lebih banyak miras setelah menghabiskan semua jatah.",
  str_voice_1600931_14 = "Peduli amat dengan apa yang orang lain pikirkan tentangku. Yang aku inginkan hanyalah kebahagiaan.",
  str_voice_1600931_15 = "Selamat ulang tahun, Nak. Bagaimana menurutmu? Bukankah salam ini dipenuhi perasaan?",
  str_voice_1600931_16 = "Jika ada yang datang mencariku, beri tahu bahwa aku sedang sibuk. Dah.",
  str_voice_1600931_17 = "Selamat pagi, Nak. Aku akan kembali tidur.",
  str_voice_1600931_18 = "Kita telah mencapai akhir dari hari yang penuh kedamaian. Ini adalah berita bagus.",
  str_voice_1600931_19 = "Hmm? Aku tidak pernah tahu kau pekerja keras.",
  str_voice_1600931_20 = "Illumina mungkin kuat, tetapi sedikit terlalu kaku. Bukan masalah selama itu tidak memengaruhi penelitianku.",
  str_voice_1600931_21 = "Warga Umbraton beraneka ragam. Ini adalah tempat seseorang dapat bertahan hidup hanya dengan kemampuannya.",
  str_voice_1600931_22 = "Jayalah Illumina.",
  str_voice_1600931_23 = "Makhluk yang menyedihkan, tetapi menarik. Aku sangat tertarik dengan evolusi mereka.",
  str_voice_1600931_24 = "Tidakkah menurutmu Charon itu lucu? Asalkan kalian sudah saling mengenal dengan baik.",
  str_voice_1600931_25 = "Nemesis adalah anak yang menggemaskan. Sangat layak digoda.",
  str_voice_1600931_26 = "Semua hal memiliki nilai tersendiri, dan itulah yang aku pelajari.",
  str_voice_1600931_27 = "Aku pikir mereka membuat segalanya cukup kaku di Illumina, tetapi sekarang tampaknya lebih buruk di Lumopolis.",
  str_voice_1600931_28 = "Tidak salah kalau aku menyebutnya antik, 'kan? Ini adalah sesuatu yang ingin dipelajari oleh semua ilmuwan.",
  str_voice_1600931_29 = "Tidak kusangka aku akan bertemu Caelestite hidup. Keadaan jadi makin menarik.",
  str_voice_1600931_30 = "Menjadi lebih kuat bukanlah hal yang buruk.",
  str_voice_1600931_31 = "Tempa jalanmu menuju tujuan yang lebih besar.",
  str_voice_1600931_32 = "Itu semua sepadan.",
  str_voice_1600931_33 = "Aku akan mengetahui semuanya.",
  str_voice_1600931_34 = "Jika itu maumu.",
  str_voice_1600931_35 = "Siap?",
  str_voice_1600931_36 = "Ukirkan dalam kenanganmu.",
  str_voice_1600931_37 = "Abu menjadi abu, debu menjadi debu.",
  str_voice_1600931_38 = "Saksikan akhir dari segalanya.",
  str_voice_1600931_39 = "Pedang yang tajam menembus tenggorokan!",
  str_voice_1600931_40 = "Tidak ada gunanya melawannya.",
  str_voice_1600931_41 = "Saatnya berolahraga.",
  str_voice_1600931_42 = "Sepertinya aku harus kembali dan beristirahat.",
  str_voice_1600931_43 = "Biasa saja. Tidak ada yang serius.",
  str_voice_1600931_44 = "Kau tertarik dengan penelitianku?",
  str_voice_1600931_45 = "Lumayan.",
  str_voice_1600931_46 = "Kau cukup bijaksana.",
  str_voice_1600931_47 = "Kaulah yang punya ide.",
  str_voice_1600931_48 = "Ini berguna bagiku. Terima kasih.",
  str_voice_1600931_49 = "Masih terlalu banyak hal tak terjelaskan di dunia, dan mempelajari semua itu adalah pekerjaanku sepanjang hidup.",
  str_voice_1600931_50 = "Insiden di Undercity 9 masih menghantuiku. Aku juga masih tidak bisa menghilangkan perasaan hampa yang ditimbulkannya ketika aku menyatu dengan Diving Spines.",
  str_voice_1600931_51 = "Nikmati hidup selagi bisa. Meski setuju dengan ini, aku masih mencemaskan Gannon City. Karena aku punya mata yang terus mengawasi setiap bagiannya, aku bisa relaks dan bersantai.",
  str_voice_1600931_52 = "Alchemy Stars.",
  str_voice_1600931_53 = "Halo.",
  str_voice_1600931_54 = "Sungguh pagi yang indah!",
  str_voice_1600931_55 = "Waktunya tidur siang.",
  str_voice_1600931_56 = "Sudah waktunya untuk pergi tidur.",
  str_voice_1600931_57 = "Selamat Tahun Baru. Nikmati hari ini!",
  str_voice_1600961_1 = "Karena sudah tahan air, tidak perlu cemas semua pakaian ini akan terpengaruh energi. Satu-satunya bagian yang sulit mungkin adalah rambut.",
  str_voice_1600961_2 = "Aku sedang bokek. Haruskah aku meminjam lagi dari Sheol… Namun, dia selalu bersandar ke meja sehingga membuatku kesal.",
  str_voice_1600961_3 = "Kehidupan di Umbraton keras. Aku mulai merindukan rumahku di Illumina.",
  str_voice_1600961_4 = "Aku harus menemukan Gabriel untuk menanyakan tentang kakekku…",
  str_voice_1600961_5 = "Belakangan ini aku baru sadar bahwa aku lebih jago menggunakan Murky Water. Menyeimbangkan kemampuan pengendalian itu sulit…",
  str_voice_1600961_6 = "Aku harus belajar melawan efek samping kemampuan ini. Masalahnya, tidak ada yang tahu cara kerjanya. Aku tidak bisa melakukan apa-apa selain duduk dan membiarkan kekacauan mengotori pikiranku.",
  str_voice_1600961_7 = "Kau adalah anak yang tulus. Aku bisa merasakannya.",
  str_voice_1600961_8 = "Kapan-kapan aku akan membelikanmu kopi… Kurasa kau tidak suka kopi pahit, jadi aku sudah menyiapkan gula untukmu.",
  str_voice_1600961_9 = "Kau pernah mengalami perasaan ini? Perasaan yang membuatmu merasa… bahwa kejahatan perlahan menyerang pikiran dan tubuhmu. Aku takut terlalu banyak membuang-buang waktu untuk hall sepele. Aku harus menggunakan kekuatanku dengan lebih efisien! Ah… Tidak, lupakan saja.",
  str_voice_1600961_10 = "Aku hanya ingin istirahat dengan tenang di suatu tempat.",
  str_voice_1600961_11 = "Aku? Mungkin aku mengacaukan segalanya. Sebaiknya kau mempertimbangkannya kembali…",
  str_voice_1600961_12 = "Aku merombak ruangan agar strukturnya simetris. Sekarang jauh lebih nyaman untuk ditinggali.",
  str_voice_1600961_13 = "Aku tidak menyangka Colossus seluas ini. Aku khawatir tersesat…",
  str_voice_1600961_14 = "Boleh aku memelihara kucing? Aku akan menjaganya dengan baik. Kumohon?",
  str_voice_1600961_15 = "Selamat ulang tahun. Semoga kau akan terus berusaha keras untuk tahun yang akan datang.",
  str_voice_1600961_16 = "Saatnya bekerja. Biar kuperiksa apakah aku telah ditugaskan untuk melakukan sesuatu…",
  str_voice_1600961_17 = "Selamat pagi. Jadi, kau orang yang suka bangun pagi.",
  str_voice_1600961_18 = "Waktunya hiburan. Ada rencana?",
  str_voice_1600961_19 = "Bergadang itu tidak baik. Cobalah tidur lebih awal…",
  str_voice_1600961_20 = "Aku tidak suka Umbraton, tetapi mau bagaimana lagi… Aku harus lewat sini untuk sampai ke Lumopolis.",
  str_voice_1600961_21 = "Illumina adalah tempat yang bagus. Rasanya senang melihat semua orang bekerja dengan tujuan yang sama…",
  str_voice_1600961_22 = "Aku bersama dengan Murky Water.",
  str_voice_1600961_23 = "Hal-hal ini gunanya apa, sih?",
  str_voice_1600961_24 = "Areia adalah anak yang dewasa. Dia mengesankan. Aku ingin membantunya semampuku.",
  str_voice_1600961_25 = "Jika bukan karena Sheol, mungkin aku takkan bisa bertahan hidup di Umbraton.",
  str_voice_1600961_26 = "Kucing itu lucu, terutama kucing hitam! Aku sangat menyukai matanya…",
  str_voice_1600961_27 = "Kali pertama aku tiba di Umbraton, aku bertemu banyak orang jahat yang menipuku. Aku tidak ingin melihat mereka lagi.",
  str_voice_1600961_28 = "Dengan ini… Seharusnya aku bisa keluar masuk Lumopolis sesuka hati…",
  str_voice_1600961_29 = "Hai, kau kenal Gabriel? Orang yang tinggal di Lumopolis…",
  str_voice_1600961_30 = "Kekuatan Turbid Water telah meningkat.",
  str_voice_1600961_31 = "Benih kekacauan telah bertunas.",
  str_voice_1600961_32 = "Pandanganku makin kabur.",
  str_voice_1600961_33 = "Dorongan yang sungguh tak tertahankan…",
  str_voice_1600961_34 = "Aku akan berusaha sebaik mungkin…",
  str_voice_1600961_35 = "Aku selalu siap.",
  str_voice_1600961_36 = "Jangan berlebihan…",
  str_voice_1600961_37 = "Jadilah kewalahan.",
  str_voice_1600961_38 = "Tenggelam ke dalam jurang.",
  str_voice_1600961_39 = "Aku akan membantu.",
  str_voice_1600961_40 = "Semoga ini terbukti bermanfaat.",
  str_voice_1600961_41 = "Aku tidak cocok menjadi kapten.",
  str_voice_1600961_42 = "Fiuh… Itu lebih mudah dari yang kubayangkan.",
  str_voice_1600961_43 = "Jangan terlalu putus asa, oke?",
  str_voice_1600961_44 = "Apa yang bisa aku lakukan untukmu? Aku ingin istirahat sejenak…",
  str_voice_1600961_45 = "Oh, terima kasih.",
  str_voice_1600961_46 = "Ini… Terima kasih.",
  str_voice_1600961_47 = "Terima kasih. Aku sangat bahagia.",
  str_voice_1600961_48 = "Kok kau tahu aku suka ini…",
  str_voice_1600961_49 = "Aku mengagumi kakekku, jadi aku ingin tahu kenapa beliau meninggalkan rumah untuk membantu Gabriel…",
  str_voice_1600961_50 = "Hidup itu sulit saat kali pertama aku tiba di Umbraton. Semua uangku hilang karena aku ditipu. Tidak bisa kubayangkan apa yang akan terjadi padaku andai aku tidak bertemu Sheol…",
  str_voice_1600961_51 = "Aku harus menjadi lebih kuat untuk mengendalikan kekuatanku dan mencegah indra-indraku dimakan olehnya lagi.",
  str_voice_1600961_52 = "Hmm? Alchemy… Stars?",
  str_voice_1600961_53 = "Halo.",
  str_voice_1600961_54 = "Sungguh pagi yang indah!",
  str_voice_1600961_55 = "Kau perlu istirahat makan siang?",
  str_voice_1600961_56 = "Ingatlah untuk tidur lebih awal.",
  str_voice_1600961_57 = "Selamat Tahun Baru…",
  str_voice_1401021_1 = "Ya? Kau tidak keberatan? Jika tidak ada lagi, tinggalkan aku sendiri.",
  str_voice_1401021_2 = "Colossus bukan satu-satunya benda raksasa yang terbang di langit. Lihat pulau apung itu? Perlu pesawat untuk ke sana.",
  str_voice_1401021_3 = "Aku tidak suka berhubungan dengan orang. Terlalu banyak orang yang menyebalkan… Lagi pula, kenapa aku mengungkit ini?",
  str_voice_1401021_4 = "Saat sendirian, aku memiliki lebih banyak waktu untuk berpikir, dan aku dapat memikirkan banyak hal yang biasanya tidak aku pikirkan.",
  str_voice_1401021_5 = "Kau pernah memikirkan makna kekuatan ini? Aku terkadang memikirkan semua yang kita punya, dan mereka lebih terasa seperti kutukan daripada berkat.",
  str_voice_1401021_6 = "Hidup penuh pertarungan tidak semenarik dugaanku. Mungkin karena aku tidak pernah suka berkelahi, hingga hari itu.",
  str_voice_1401021_7 = "Kau orang baik. Minatku terhadap Caelestite pun mulai bertumbuh. Namun, yang lain… Oh, bukan apa-apa. Jangan tersinggung.",
  str_voice_1401021_8 = "Aku tidak merasa yakin tentang apa pun dalam hidup, jadi aku tidak bisa memberimu saran apa pun… Lebih baik perhatikan dirimu sendiri.",
  str_voice_1401021_9 = "Aku hanya punya beberapa teman, tetapi kami semua saling memahami, dan itulah yang aku inginkan.",
  str_voice_1401021_10 = "Fiuh… betapa mudahnya hidup…",
  str_voice_1401021_11 = "Baiklah. Aku tidak tahu apa yang harus kulakukan, tetapi aku akan tetap melakukannya.",
  str_voice_1401021_12 = "Aku akan beristirahat. Jika ada sesuatu yang ingin kau bicarakan, lakukan nanti.",
  str_voice_1401021_13 = "Orang berbadan besar ini… Namanya Soroz, 'kan? Aku ingin sekali berbicara dengannya.",
  str_voice_1401021_14 = "Di sini jauh lebih tenang daripada tempat tinggalku. Aku belum benar-benar terbiasa.",
  str_voice_1401021_15 = "Selamat ulang tahun. Aku tidak memberimu apa-apa. Yang penting ucapannya, 'kan?",
  str_voice_1401021_16 = "Oh, kau di sini? Sejauh ini tidak ada apa-apa. Waktuku sangat santai.",
  str_voice_1401021_17 = "Kau benar-benar pekerja keras, tetapi kau harus ingat untuk menjaga keseimbangan antara kehidupan dan pekerjaan yang sehat.",
  str_voice_1401021_18 = "Tenanglah, kau sedang tidak bertugas.",
  str_voice_1401021_19 = "Kau ingin membuat dirimu sendiri kelelahan? Aku takkan menghentikanmu…",
  str_voice_1401021_20 = "Umbraton itu kacau, tetapi lumayan cocok untuk kita para individualis.",
  str_voice_1401021_21 = "Aku tidak suka cara para bangsawan melakukan segala sesuatu, tetapi Lumopolis menawarkan tempat untuk mereka juga.",
  str_voice_1401021_22 = "Bayangan mengawasi… segalanya.",
  str_voice_1401021_23 = "Mereka mungkin juga tidak tahu kenapa mereka berperang dengan kita.",
  str_voice_1401021_24 = "Dayna… Dia melanggar hukum. Begitulah cara dia melindungi Robyn.",
  str_voice_1401021_25 = "Aku berbicara kalau perlu, tetapi Robyn selalu diam.",
  str_voice_1401021_26 = "Apa yang aku suka? Lihat permen di mulutku? Aku suka semua pilihan rasanya.",
  str_voice_1401021_27 = "Aku tidak suka omong kosong atau kedok. Itu sebabnya aku membenci beberapa bangsawan di Lumopolis.",
  str_voice_1401021_28 = "Kupikir Colossus cuma legenda. Aku belum pernah lihat satu pun.",
  str_voice_1401021_29 = "Namaku Tessa. Sebagai catatan, penting bagi kita untuk bekerja sama, tetapi aku tetap berharap kau mengurus urusanmu sendiri sementara aku mengurus urusanku.",
  str_voice_1401021_30 = "Lumayan juga.",
  str_voice_1401021_31 = "Kekuatan ini sangat sulit dikendalikan.",
  str_voice_1401021_32 = "Jika kekuatanku lepas kendali, akan menjadi kabar buruk bagi musuh, 'kan?",
  str_voice_1401021_33 = "Petir menyambar dari tanganku, haha.",
  str_voice_1401021_34 = "Tidak ada pilihan lain.",
  str_voice_1401021_35 = "Secepat kilat.",
  str_voice_1401021_36 = "Mari kita mencobanya.",
  str_voice_1401021_37 = "Ini akan sedikit menyakitkan.",
  str_voice_1401021_38 = "Elektrolisis!",
  str_voice_1401021_39 = "Ini terlalu lemah.",
  str_voice_1401021_40 = "Biar aku saja.",
  str_voice_1401021_41 = "Hanya bertarung dengan sedikit usaha.",
  str_voice_1401021_42 = "Baiklah, aku sedikit bersemangat.",
  str_voice_1401021_43 = "Ini baru menarik.",
  str_voice_1401021_44 = "Sedang apa kau di sini? Mau kusetrum?",
  str_voice_1401021_45 = "Barang bagus. Akan kuterima.",
  str_voice_1401021_46 = "Sepertinya kau benar-benar tidak memahamiku.",
  str_voice_1401021_47 = "Aku akan mengingat kebaikanmu padaku.",
  str_voice_1401021_48 = "Sepertinya kau tahu aku suka ini…",
  str_voice_1401021_49 = "Aku tidak pernah mengira akan menggunakan kekuatanku untuk menghancurkan siapa pun, apalagi orang-orang Lumopolis. Sejujurnya, aku bahkan tidak mengerti apa yang Richard maksud dengan kebencian.",
  str_voice_1401021_50 = "Kebanyakan orang mengira aku membenci Lumopolis, tetapi itu tidak benar. Richard, yang membesarkanku, adalah orang yang membencinya, tetapi dia tidak pernah membiarkan kebenciannya memengaruhiku.",
  str_voice_1401021_51 = "Aku memang membutuhkan kekuatan ini untuk melindungi diriku sendiri, tetapi dilihat dari kekuatanku yang tumbuh, aku merasakan kekosongan yang tak terkira. Apakah akan ada akhir dari semua ini?",
  str_voice_1401021_52 = "Alchemy Stars.",
  str_voice_1401021_53 = "Hei.",
  str_voice_1401021_54 = "Pagi.",
  str_voice_1401021_55 = "Kau punya kebiasaan tidur siang?",
  str_voice_1401021_56 = "Selamat malam. Selamat tidur.",
  str_voice_1401021_57 = "Selamat Tahun Baru, semoga semua orang akan tumbuh dalam beberapa hal.",
  str_voice_1500711_1 = "Teman? Apa yang membuatmu mengira aku membutuhkannya? Meskipun aku punya seorang teman ketika masih kecil…",
  str_voice_1500711_2 = "Tentu saja ada biaya komisi. Berapa? Tergantung isinya.",
  str_voice_1500711_3 = "Menurutmu Odd Jobs itu mudah, 'kan… Aku harus selalu menjamu orang-orang aneh, seperti pria dengan anjing dan pria bertentakel.",
  str_voice_1500711_4 = "Kekuatanku pasti makin kuat, tetapi rahasia kalung ini masih jauh dari kata terungkap.",
  str_voice_1500711_5 = "Tidak ada seorang pun di Odd Jobs yang dapat bekerja sama denganmu untuk menyelamatkan dunia, jadi tidak perlu repot-repot dan berhentilah mencari.",
  str_voice_1500711_6 = "Tidak ada kesetaraan di dunia ini. Tidak ada kesetaraan selama masih ada manusia.",
  str_voice_1500711_7 = "Kau anak yang sangat aneh, tetapi aku tidak membencimu.",
  str_voice_1500711_8 = "Kau tidak seperti anak-anak nakal di Far East. Apa? Jarang-jarang aku memujimu, jadi terima saja.",
  str_voice_1500711_9 = "Tidak banyak orang di Umbraton yang bersedia menjalin hubungan dengan sesama. Setiap orang tertahan oleh satu atau lain hal, sangat sulit jadinya bagi mereka untuk memikirkan hal lain selain bertahan hidup.",
  str_voice_1500711_10 = "Kau tidak punya sesuatu untuk dikerjakan? Atau apakah kau benar-benar sibuk, Nak?",
  str_voice_1500711_11 = "Mau aku yang jaga? Baiklah. Odd Jobs melakukan segalanya, 'kan?",
  str_voice_1500711_12 = "Cukup. Kau sudah cukup banyak melihat. Atau kau mau coba ini?",
  str_voice_1500711_13 = "Karena sedang begitu senggang, kau harus melakukan pekerjaanmu sendiri.",
  str_voice_1500711_14 = "Aku harus mencari tahu rahasia kalung ini sesegera mungkin.",
  str_voice_1500711_15 = "Hari ulang tahun? Kau bisa membayarku untuk meneriakkan kata-kata itu. Kali ini gratis.",
  str_voice_1500711_16 = "Kau sedang bersemangat, Nak. Mau membantu urusanku? Kau akan dibayar, tentu saja.",
  str_voice_1500711_17 = "Berapa lama kau akan terus tidur, Nak? Kau pasti sudah berangkat kerja sekarang kalau bersama Odd Jobs!",
  str_voice_1500711_18 = "Ayo, minum denganku. Aku yang traktir. Kau bisa pesan jus. Aku tidak peduli.",
  str_voice_1500711_19 = "Kau memang luar biasa, Nak, masih bekerja keras pada jam ini. Mau minum denganku?",
  str_voice_1500711_20 = "Umbraton adalah tempat yang baik untuk mengumpulkan informasi intel, dan tidak ada seorang pun di sana yang berbicara omong kosong. Aku menyukainya.",
  str_voice_1500711_21 = "Aku akan bergabung dengan Rediesel Wrench setelah mengetahui rahasia kalung itu. Aku cukup menyukai mereka.",
  str_voice_1500711_22 = "Bayangan mengawasimu.",
  str_voice_1500711_23 = "Seonggok sampah tanpa akal. Mereka tidak layak untuk dibicarakan.",
  str_voice_1500711_24 = "Istvan sangat mahir dalam mengelola Umbraton. Di sini lumayan damai jika dia ada.",
  str_voice_1500711_25 = "Aku ingin tahu keadaan gadis kecil berambut merah muda itu. Ah, masa bodoh. Aku takkan memikirkannya.",
  str_voice_1500711_26 = "Punya miras untuk diminum sudah cukup bagiku dalam hidup ini.",
  str_voice_1500711_27 = "Ada beberapa pekerja paruh waktu di sini, tetapi aku memecat mereka karena mereka terlalu banyak omong.",
  str_voice_1500711_28 = "Pria ini terlalu besar. Aku bahkan kebingungan mencari jalan di sini. Juga ada terlalu banyak kamar yang mirip.",
  str_voice_1500711_29 = "Ada yang bisa kukerjakan, Nak? Sebaiknya jangan sesuatu yang sepele. Ada begitu banyak hal yang bisa dilakukan Odd Jobs dalam sehari, jadi aku harus sangat selektif.",
  str_voice_1500711_30 = "Lumayan.",
  str_voice_1500711_31 = "Huh, itu hanyalah permainan bocah.",
  str_voice_1500711_32 = "Aku sudah selangkah lebih dekat… untuk menemukan rahasia kalung itu.",
  str_voice_1500711_33 = "Darahku bergejolak… Sudah beberapa waktu aku tidak sebergairah ini!",
  str_voice_1500711_34 = "Oh, kita melakukan ini?",
  str_voice_1500711_35 = "Sudah waktunya.",
  str_voice_1500711_36 = "Lihat ini!",
  str_voice_1500711_37 = "Bakar mereka semua!",
  str_voice_1500711_38 = "Bakar semuanya!",
  str_voice_1500711_39 = "Usai sudah.",
  str_voice_1500711_40 = "Terlalu lambat!",
  str_voice_1500711_41 = "Aku tidak terbiasa memimpin tim.",
  str_voice_1500711_42 = "Gampang sekali.",
  str_voice_1500711_43 = "Kalah? Itu bagian dari kehidupan sehari-hari.",
  str_voice_1500711_44 = "Jika ada sesuatu yang mau kau katakan, katakan saja. Jangan buang-buang waktu.",
  str_voice_1500711_45 = "Kau mencoba menyuapku?",
  str_voice_1500711_46 = "Seleramu lumayan juga.",
  str_voice_1500711_47 = "Akan kuterima. Terima kasih.",
  str_voice_1500711_48 = "Ini—! Terima kasih, Nak.",
  str_voice_1500711_49 = "Dunia tidak terlalu bersahabat dengan mereka yang berbeda. Beberapa bahkan diperlakukan dengan buruk hanya karena penampilan mereka, tetapi di sini di Umbraton jauh lebih baik.",
  str_voice_1500711_50 = "Sampai hari ini, waktu yang aku habiskan di Far East masih terasa seperti kemarin. Ajaran guruku masih bergema di pikiranku dan ada gadis berambut merah muda yang entah bagaimana aku pedulikan.",
  str_voice_1500711_51 = "Kalung ini… adalah sesuatu yang kubawa sejak aku bisa mengingat. Ini adalah warisan dari orang tuaku, juga merupakan sumber kekuatanku. Ada begitu banyak rahasia di baliknya, tetapi tidak ada satu pun yang aku tahu.",
  str_voice_1500711_52 = "Alchemy Stars.",
  str_voice_1500711_53 = "Hei.",
  str_voice_1500711_54 = "Kau bangun lebih awal, Nak.",
  str_voice_1500711_55 = "Aku selalu mengantuk saat tengah hari.",
  str_voice_1500711_56 = "Tidurlah sekarang, Nak. Jangan bergadang.",
  str_voice_1500711_57 = "Selamat Tahun Baru, Nak. Kupon diskon ini untukmu.",
  str_voice_1500971_1 = "Menyelamatkan pasien? Itu sudah lama sekali… Plus, beberapa hal tidak layak diselamatkan.",
  str_voice_1500971_2 = "Itu adalah pisau bedah yang terbuat dari es dan salju, jadi tidak akan menyebabkan banyak rasa sakit saat ditikamkan ke tubuhmu. Mau coba?",
  str_voice_1500971_3 = "Misi apa yang telah kuselesaikan? Banyak. Jika kau ingin tahu, aku bisa mengujikannya padamu.",
  str_voice_1500971_4 = "Tujuan utama operasi? Menurutku pembedahan yang presisi.",
  str_voice_1500971_5 = "Mungkin aku akan kembali menjadi dokter setelah kegelapan di Umbraton sirna. Sebelum itu, aku harus melakukan operasi lagi, operasi untuk Umbraton.",
  str_voice_1500971_6 = "Aku pernah ingin menyelamatkan lebih banyak orang dengan pisau bedahku. Kini, aku berharap bisa menjadi pisau bedah Umbraton dan menghilangkan bagian yang busuk.",
  str_voice_1500971_7 = "Caelestite? Menarik. Bolehkah aku mempelajari tubuhmu? Aku mau tahu apakah Caelestite memiliki bagian fatal yang sama seperti Aurorian normal… Ha-ha, bercanda.",
  str_voice_1500971_8 = "Kau bisa menemuiku jika membutuhkan operasi. Aku sudah berhenti melakukan praktik pengobatan, tetapi kemampuanku lebih terasah ketimbang sebelumnya. Kenapa? Rahasia, dong.",
  str_voice_1500971_9 = "Makin banyak pasien yang aku temui, makin aku sadar betapa rapuhnya hidup ini. Oleh karena itu, aku lebih memahami cara menyembuhkan atau mengusir mereka.",
  str_voice_1500971_10 = "Mumpung kau sedang duduk-duduk saja, mau belajar sesuatu yang baru? Kau mau tahu di mana ruas tulang punggung ketiga belas?",
  str_voice_1500971_11 = "Butuh bantuanku? Tentu. Namun, sebagai catatan, aku melakukan ini hanya untuk Shadowlord.",
  str_voice_1500971_12 = "Operasi jantung? Tidak mudah untuk membangkitkan kembali seseorang dari kematian.",
  str_voice_1500971_13 = "Menyelamatkan orang tidak bertentangan dengan membunuh orang. Hanya sudut pandang keyakinannya saja yang berbeda.",
  str_voice_1500971_14 = "Sayat dari sudut terbaik… Oh, jangan khawatir. Aorta sangat rapuh, jadi kau dapat menyayatnya sesukamu.",
  str_voice_1500971_15 = "Selamat ulang tahun, Navigator. Sudahkah kau mengucapkan harapanmu?",
  str_voice_1500971_16 = "Sepertinya kau cukup istirahat. Ingatlah untuk sering mencuci tangan agar tidak jatuh sakit.",
  str_voice_1500971_17 = "Bangun pagi baik untuk kesehatan. Aku rasa hal yang sama berlaku bagi Caelestite.",
  str_voice_1500971_18 = "Waktunya makan malam. Jangan bekerja dengan perut kosong. Bisa berbahaya.",
  str_voice_1500971_19 = "Kau masih bekerja? Bergadang meningkatkan risiko kematian akibat serangan jantung. Istirahatlah sekarang.",
  str_voice_1500971_20 = "Umbraton dipenuhi gairah dan kegilaan sehingga tempat ini perlu operasi khusus.",
  str_voice_1500971_21 = "Mungkin praktik pengobatan di Lumopolis lumayan juga. Namun, mungkin bakal sedikit membosankan.",
  str_voice_1500971_22 = "Bayangan mengawasimu.",
  str_voice_1500971_23 = "Dulu aku percaya semuanya bisa diselamatkan, selain Eclipsite.",
  str_voice_1500971_24 = "Dia takkan menjadi Seleucid jika bisa memikirkan cara lain selain bertarung…",
  str_voice_1500971_25 = "Shadowlord menunjukkan padaku cara baru untuk menjalani hidup dan membawakan aku pasien baru.",
  str_voice_1500971_26 = "Api di perapian selalu membuatku tenang. Rasanya tenteram jika melihat api seperti ini di malam yang panjang.",
  str_voice_1500971_27 = "Luka, nanah, pendarahan. Sebaiknya lakukan kauterisasi jika kau tidak bisa merawatnya dengan benar.",
  str_voice_1500971_28 = "Tampaknya ada banyak luka lama di Colossus milikmu ini. Kapan kau akan membersihkannya? Aku bisa membantu.",
  str_voice_1500971_29 = "Mengapa kau bertanya? Dulu aku memang seorang dokter yang bisa melakukan operasi, tetapi aku sudah ganti profesi… Aku seorang pembunuh sekarang.",
  str_voice_1500971_30 = "Aku mungkin harus memotong sesuatu.",
  str_voice_1500971_31 = "Keahlian operasiku perlu ditingkatkan lebih lanjut.",
  str_voice_1500971_32 = "Pisau bedah ini lebih tajam dari sebelumnya.",
  str_voice_1500971_33 = "Aku tidak pernah melupakan tugas seorang dokter.",
  str_voice_1500971_34 = "Yang mana pasiennya?",
  str_voice_1500971_35 = "Bersiap untuk operasi.",
  str_voice_1500971_36 = "Silakan bersantai, pasienku.",
  str_voice_1500971_37 = "Pil akan membuktikan kemujarabannya!",
  str_voice_1500971_38 = "Lenyaplah, penyakit kronis!",
  str_voice_1500971_39 = "Membeku, pedang es.",
  str_voice_1500971_40 = "Di mana lagi yang harus aku potong?",
  str_voice_1500971_41 = "Baiklah, kali ini aku akan menjadi ahli bedah utama.",
  str_voice_1500971_42 = "Operasi berjalan dengan baik.",
  str_voice_1500971_43 = "Butuh waktu untuk mengobati penyakit kronis. Ini bukan waktu yang tepat untuk menyembuhkannya.",
  str_voice_1500971_44 = "Apa yang aku lihat? Tentu saja jantungmu.",
  str_voice_1500971_45 = "Benar. Terima kasih.",
  str_voice_1500971_46 = "Hmm? Terima kasih banyak.",
  str_voice_1500971_47 = "Terlihat bagus. Akan kuterima.",
  str_voice_1500971_48 = "Terima kasih. Aku akan merawatnya.",
  str_voice_1500971_49 = "Luka akibat Eclipsite terkadang sulit untuk diobati. Aku membutuhkan banyak usaha untuk berurusan dengannya pada waktu aku masih menjadi mahasiswa kedokteran di Lumopolis. Untungnya, aku melakukannya dengan baik.",
  str_voice_1500971_50 = "Aku menyelamatkan banyak orang dengan pisau bedahku, tetapi tidak dengan orang tuaku. Pisau bedahku kurang tajam untuk Eclipsite, jadi aku menggunakan pisau lain.",
  str_voice_1500971_51 = "Penyakit kronis Umbraton tidak bisa disembuhkan dengan cara biasa karena membutuhkan banyak pengangkatan dan penjahitan sambil menunggu harapan baru tumbuh. Sebelum itu, aku akan terus mengerjakan tugasku.",
  str_voice_1500971_52 = "Alchemy Stars.",
  str_voice_1500971_53 = "Hei.",
  str_voice_1500971_54 = "Pagi.",
  str_voice_1500971_55 = "Hei, Navigator.",
  str_voice_1500971_56 = "Selamat malam. Kau belum tidur?",
  str_voice_1500971_57 = "Selamat Tahun Baru, Navigator.",
  str_voice_1500241_1 = [[
- Siapa Caelestite?
- Mereka adalah ras yang berbeda dari Aurorian.]],
  str_voice_1500241_2 = [[
- Apakah Caelestite jago bertarung?
- Kurasa tidak.]],
  str_voice_1500241_3 = [[
- Dengarkan. Sisi garis ini adalah wilayahku
- Bodoh sekali!]],
  str_voice_1500241_4 = [[
- Sedikit lagi kau bisa kukalahkan.
- Bukan kau saja yang meningkat, kutu buku.]],
  str_voice_1500241_5 = [[
- Sejujurnya, aku tidak tertarik akan kenaikan pangkat. Biarkan aku bertarung.
- Kau harus lebih memikirkan masa depanmu.]],
  str_voice_1500241_6 = [[
- Ha-ha-ha, akulah yang terbaik!
- Kalau begitu, akulah yang terbaik dari yang terbaik.]],
  str_voice_1500241_7 = [[
- Kau tidak bisa bertarung, tetapi kau baik.
- Jangan anggap serius kata-katanya.]],
  str_voice_1500241_8 = [[
- Saatnya pertunjukan, Curo!
- Biar si Caelestite menjadi saksi kekalahanmu.]],
  str_voice_1500241_9 = "- Aku tidak ada urusan… Aduh… Apakah tidak ada yang bisa aku lakukan?\n- Berhenti berguling-guling di tempat tidur seperti orang bodoh.",
  str_voice_1500241_10 = [[
- Membosankan sekali!
- Diam saja.]],
  str_voice_1500241_11 = [[
- Apakah ada pertarungan yang harus kulakukan?
- Itu hanya tugas biasa.]],
  str_voice_1500241_12 = [[
- Jangan sentuh barang-barangku tanpa izin.
- Memang kenapa? Kau bisa memakai barang-barangku juga.]],
  str_voice_1500241_13 = [[
- Hei, menurutmu siapa yang lebih kuat di antara kami?
- Jangan melibatkan orang yang tidak ada hubungannya dengan ini.]],
  str_voice_1500241_14 = [[
- Kadang-kadang aku merasa tinggal di Colossus itu terlalu mewah.
- Mulai lagi, deh.]],
  str_voice_1500241_15 = [[
- Selamat ulang tahun!
- Hei, aku yang bilang duluan!
- Terserah.]],
  str_voice_1500241_16 = "Apa yang biasanya kau lakukan pada siang hari? Omong-omong, aku baru saja merampungkan pelatihan mandiriku.",
  str_voice_1500241_17 = "Kau bangun lebih awal, jauh lebih awal dari kutu buku itu.",
  str_voice_1500241_18 = [[
- Aku merasa sangat energik pada malam hari!
- Aku sudah menyerah menghadapi tukang bergadang ini.]],
  str_voice_1500241_19 = "Tidur berkualitas adalah salah satu kriteria untuk menjaga kesehatan yang baik, jadi sebaiknya kau pergi tidur sekarang.",
  str_voice_1500241_20 = [[
- Bagaimana perasaanku terhadap Illumina? Aku tidak merasakan apa pun tentangnya karena aku tidak tahu apa-apa tentang tempat itu.
- Persatuan adalah hal yang membuat Illumina istimewa.]],
  str_voice_1500241_21 = [[
- Aku lebih suka Umbraton ketimbang Lumopolis. Ini bukan soal aspek keindahannya.
- Untuk sekali ini, aku setuju denganmu.]],
  str_voice_1500241_22 = "Jayalah Illumina!",
  str_voice_1500241_23 = [[
- Tidak ada yang tahu dari mana asal mereka.
- Mengapa mereka mengusik Aurorian? Aku tidak mengerti.]],
  str_voice_1500241_24 = [[
- General Barton cukup gagah.
- Aku akan menjadi seperti dia!]],
  str_voice_1500241_25 = [[
- White Dwarf? Orang yang membosankan.
- Setiap orang berbeda.]],
  str_voice_1500241_26 = [[
- Aku suka bertarung dan menang!
- Aku juga suka menang.]],
  str_voice_1500241_27 = [[
- Hanya pengecut yang bertarung dengan curang!
- Mereka tidak punya harga diri untuk dibanggakan.]],
  str_voice_1500241_28 = [[
- Sungguh besar! Dia pasti kuat!
- Aku kagum melihat warisan masa lalu ini.]],
  str_voice_1500241_29 = [[
- Hai. Senang bertemu denganmu.
- Keluarkan orang yang paling kuat di sini!]],
  str_voice_1500241_30 = "Bagus. Semangat!",
  str_voice_1500241_31 = "Aku menjadi lebih kuat!",
  str_voice_1500241_32 = "Itu keputusan yang sangat masuk akal.",
  str_voice_1500241_33 = [[
- Sempurna!
- Sangat sempurna!]],
  str_voice_1500241_34 = "Diterima!",
  str_voice_1500241_35 = "Mari kita mengamuk!",
  str_voice_1500241_36 = "Pastikan kau memilih momen yang tepat.",
  str_voice_1500241_37 = "Tunjukkan keberanianmu!",
  str_voice_1500241_38 = [[
- Sudah saatnya.
- Awas!]],
  str_voice_1500241_39 = "Duar!",
  str_voice_1500241_40 = "Hahahahaha!",
  str_voice_1500241_41 = [[
- Aku kaptennya!
- Jaga perilakumu.]],
  str_voice_1500241_42 = [[
- Gampang!
- Misi selesai.]],
  str_voice_1500241_43 = [[
- Panas sekali!
- Kita beruntung masih hidup.]],
  str_voice_1500241_44 = [[
- Hmm? Kau mau menemuiku atau dia?
- Ada yang bisa aku bantu?]],
  str_voice_1500241_45 = "Terima kasih atas perhatianmu, Navigator.",
  str_voice_1500241_46 = "Ini dia! Kau mengerti aku!",
  str_voice_1500241_47 = "Lumayan juga. Akan kuterima.",
  str_voice_1500241_48 = "Aku akan merawatnya. Terima kasih.",
  str_voice_1500241_49 = [[
- Ah, tiba-tiba aku merindukan saat kali pertama bergabung dengan Illumina.
- Kau jauh lebih sulit didisiplinkan saat itu.
- Apa?!]],
  str_voice_1500241_50 = [[
- Makin banyak duel kami yang berakhir seri belakangan ini. Kalau begini terus, cepat atau lambat aku akan mengalahkanmu!
- Jangan harap, ya.]],
  str_voice_1500241_51 = [[
- Kau sering gagal merasakan bahaya di sekitarmu saat bertarung. Ini akan berujung fatal.
- Turun dari punggungku! Itu karena aku tidak bertarung sendiri!]],
  str_voice_1500241_52 = "Alchemy Stars!",
  str_voice_1500241_53 = "Hei, kau!",
  str_voice_1500241_54 = "Selamat pagi. Hari ini pun kau tampak cukup beristirahat.",
  str_voice_1500241_55 = "Aku merasa sangat mengantuk setelah makan siang!",
  str_voice_1500241_56 = "Sudah waktunya bagi prajurit yang luar biasa untuk beranjak tidur.",
  str_voice_1500241_57 = [[
- Selamat Tahun Baru!
- Harapan terbaik untuk tahun yang akan datang.
- Berhenti merebut dialogku!]],
  str_voice_1601031_1 = "Lihatlah jam pasir yang lucu ini. Ini buatanku sendiri. Bagaimana menurutmu?… Aku bisa melakukan lebih dari sekadar menginterogasi tahanan. Apakah itu sangat mengejutkan?",
  str_voice_1601031_2 = "Kau mau lihat mata di balik penutup mata ini? Tidak ada yang pernah meminta itu sebelumnya… Kau serius?",
  str_voice_1601031_3 = "Kau harus tahu bahwa aku pandai dalam membuat orang menangis. Tentu saja, maksudku ketika aku mengeksekusi orang. Memangnya apa lagi?",
  str_voice_1601031_4 = "Orang sering bilang bahwa aku memiliki pandangan berbeda tentang benar dan salah. Memangnya apa yang benar? Apakah benar-benar penting untuk membedakan antara yang baik dan yang jahat? Tak bisakah aku melakukan apa pun yang membuatku bahagia?",
  str_voice_1601031_5 = "Kukira Colossus adalah tempat yang menarik. Sepertinya di sini sedikit membosankan. Adakah orang yang perlu dieksekusi?",
  str_voice_1601031_6 = "Pupil Kananku bisa menunjukkan neraka padamu. Aku juga bisa melakukannya dengan Taijutsu.",
  str_voice_1601031_7 = "Oh… Dengan mendekatiku seperti ini, tampaknya kau tidak tahu betapa berbahayanya aku…",
  str_voice_1601031_8 = "Aku suka menyiksa orang, tetapi jangan cemas… Untukmu, aku akan sangat lembut, untuk saat ini.",
  str_voice_1601031_9 = "Karena kau begitu penasaran… Akan kutunjukkan tongkatku… Namun, hati-hati jangan sampai menyentuhnya. Aku tidak ingin melihatmu terkutuk.",
  str_voice_1601031_10 = "Aku kehilangan akalku. Aku bisa merasakannya.",
  str_voice_1601031_11 = "Kau ingin aku melakukannya… Karena kau memaksa, aku akan memintamu berdiri lebih jauh dariku. Aku akan melepas penutup mataku.",
  str_voice_1601031_12 = "Kau tahu apa yang ingin aku tanyakan… Apakah Victoria ada di sini?",
  str_voice_1601031_13 = "Ya, aku sangat suka darah, tetapi bukan berarti kamarku tidak perlu bersih dan rapi.",
  str_voice_1601031_14 = "Aku ingin tahu seperti apa keributanmu di ruang interogasi. Namun, itu tidak perlu, 'kan?",
  str_voice_1601031_15 = "Hadiah ulang tahun? Apakah kau ingin… melihat-lihat ruang interogasiku?",
  str_voice_1601031_16 = "Kau kembali… Hah? Kau ingin tahu rencanaku selanjutnya? Tentu saja, ada lebih banyak pekerjaan yang menungguku di ruang interogasi.",
  str_voice_1601031_17 = "Betapa luar biasanya… mendengar jeritan secantik itu dari ruang interogasi di pagi hari.",
  str_voice_1601031_18 = "Meski aku ingin terus bekerja, Victoria bilang, beristirahat yang cukup juga tak kalah penting.",
  str_voice_1601031_19 = "Interogasi larut malam selalu menghasilkan penemuan yang mengejutkan… Hah? Kau bangun juga?",
  str_voice_1601031_20 = "Kebenaran… Bukanlah sesuatu yang sangat kupedulikan, tetapi apa pun tujuan Victoria, itu juga tujuanku.",
  str_voice_1601031_21 = "Saat berhadapan dengan mata kananku, mereka yang berasal dari Lumopolis pun akan merintih kesakitan.",
  str_voice_1601031_22 = "Oh, baiklah, semoga Truth memberkatimu.",
  str_voice_1601031_23 = "Hal-hal itu bahkan tidak pantas dicoba. Eksekusi saja mereka.",
  str_voice_1601031_24 = "Victoria terlalu lembut dan ramah. Tidak apa-apa, serahkan kekerasan padaku.",
  str_voice_1601031_25 = "Aku harus membuat pria yang selalu ada di dekat Victoria mengalami Calamity.",
  str_voice_1601031_26 = "Darah, jeritan, seringai kesakitan… Begitu fantastis!",
  str_voice_1601031_27 = "Kenapa orang selalu berusaha mendisiplinkan aku? Victoria saja sudah cukup bagiku.",
  str_voice_1601031_28 = "Begitu banyak ruangan di sini… Boleh aku menggunakan salah satunya sebagai ruang interogasi?",
  str_voice_1601031_29 = "Merepotkan… Aku Eicy. Biasanya, aku memberi tahu orang-orang namaku hanya selama interogasi. Namun, Victoria memberitahuku bahwa memperkenalkan diri itu termasuk sopan santun…",
  str_voice_1601031_30 = "Ha… Itu saja?",
  str_voice_1601031_31 = "Tataplah ketakutan di dalam secara langsung!",
  str_voice_1601031_32 = "Hollow Gaze mengawasimu.",
  str_voice_1601031_33 = "Rasakan Abyss ini!",
  str_voice_1601031_34 = "Jeritan dan darah…",
  str_voice_1601031_35 = "Hollow Gaze!",
  str_voice_1601031_36 = "Mulai interogasi sekarang?",
  str_voice_1601031_37 = "Lihatlah langsung ke Calamity!",
  str_voice_1601031_38 = "Tidak ada yang lolos!",
  str_voice_1601031_39 = "Apakah itu menyakitkan? Berteriaklah kalau begitu!",
  str_voice_1601031_40 = "Menggigil!",
  str_voice_1601031_41 = "Kau ingin aku memimpin? Mereka akan hancur.",
  str_voice_1601031_42 = "Terimalah rasa takut ini!",
  str_voice_1601031_43 = "Maafkan aku, Victoria…",
  str_voice_1601031_44 = "Sst! Tatap mataku dan katakan apa yang telah kau lakukan.",
  str_voice_1601031_45 = "Sepertinya kau tidak terlalu mengenalku.",
  str_voice_1601031_46 = "Kok kau tahu aku suka ini…",
  str_voice_1601031_47 = "Aku tidak menyangka kau memikirkan ini. Aku terkejut…",
  str_voice_1601031_48 = "Aku tidak pernah mengira ada orang selain Victoria yang memahamiku dengan baik!",
  str_voice_1601031_49 = "Aku berasal dari garis keturunan yang terkutuk… Siapa pun yang melakukan kontak mata langsung dengan Hollow Gaze akan tenggelam dalam ketakutan dan kegilaan. Begitu pula orang tuaku, mereka kehilangan nyawa karenanya.",
  str_voice_1601031_50 = "Victoria membuatkan penutup mata ini untukku. Ini adalah barang yang digunakan untuk menghambat kekuatan terkutuk Hollow Gaze… Kau tidak tahu soal itu, 'kan?",
  str_voice_1601031_51 = "Aku tidak keberatan memiliki kekuatan ini. Aku juga tidak keberatan menjadi interogator dan eksekutor. Lagi pula, darah dan rintihan membuatku puas…",
  str_voice_1601031_52 = "Alchemy Stars.",
  str_voice_1601031_53 = "Kau sedang apa?",
  str_voice_1601031_54 = "Kau tertidur selama aku berada di ruang interogasi?",
  str_voice_1601031_55 = "Menginterogasi orang menggugah seleraku. Mau coba?",
  str_voice_1601031_56 = "Pekerjaanku hari ini sudah selesai. Selamat malam.",
  str_voice_1601031_57 = "Tahun baru. Apakah itu berarti aku mendapatkan ruang interogasi di Colossus?",
  str_voice_1500991_1 = "Aku beruntung meski terlahir dengan kutukan. Karena kutukan ini, aku terlahir untuk bisa berjalan di atas duri… Eh, kekuatanku ada hubungannya dengan duri, tahu.",
  str_voice_1500991_2 = "Rasanya pedang ajaib ini tidak berat. Aku punya duri hitam untuk berbagi bebanku… Eh? Bagaimana? Yah, anu… Aku tidak tahu cara menjelaskan ini padamu.",
  str_voice_1500991_3 = "Pedang ajaib itu dinamai seperti bulan. Kekuatannya sangat besar dan aku tidak bisa berpisah darinya, jadi itu mungkin membuatku sangat kuat juga…",
  str_voice_1500991_4 = "Bukan masalah. Aku akan menemukan cara untuk mengangkat kutukan sebelum kekuatannya menghancurkanku.",
  str_voice_1500991_5 = "Duri ini berfungsi untuk melindungi diri mereka sendiri. Apakah sama dengan pedang ajaib berduri ini? Mengapa ini disertai kutukan dan mengapa ini… memberiku kekuatan?",
  str_voice_1500991_6 = "Untuk apa aku bertarung? Untuk apa aku bertahan? Untuk apa aku memulai perjalananku? Aku mengajukan pertanyaan-pertanyaan ini pada diri sendiri lagi dan lagi. Namun, jawabannya sederhana. Aku hanya ingin terus hidup…",
  str_voice_1500991_7 = "Jangan sentuh pedang ajaib. Aku tidak mau kau mendapat masalah. Menjauhlah darinya. Aku tidak mau kau terluka.",
  str_voice_1500991_8 = "Aku bekerja maksimal saat bekerja sendiri, tetapi membentuk ikatan dengan orang lain seperti ini boleh juga…",
  str_voice_1500991_9 = "Aku tidak berani berada di dekatmu karena aku menyayangimu. Semoga kau bisa mengerti… Aku di sini, di suatu tempat yang tidak terlalu jauh darimu.",
  str_voice_1500991_10 = "13, 14, 15… Oh, aku sedang menghitung duri di tubuhku. Kadang aku melakukan ini untuk menghabiskan waktu dan memeriksa duri-duriku.",
  str_voice_1500991_11 = "Serahkan padaku. Aku bisa melakukan apa saja… Apa? Yang perlu aku lakukan adalah tinggal di sini?… Ini jauh lebih mudah daripada pekerjaanku yang biasa.",
  str_voice_1500991_12 = "Aku harus merawat pakaianku. Lagi pula, ini pakaian terakhirku… Aduh, sejak kapan ada sobekan di sini?",
  str_voice_1500991_13 = "Karena kutukan itu, duri hitam tumbuh di tubuhku. Aku berharap duri-duri ini bisa berhenti tumbuh.",
  str_voice_1500991_14 = "Duri hitam pada pedang ajaib ini dapat dipatahkan, lalu duri baru akan tumbuh. Bukankah itu luar biasa?",
  str_voice_1500991_15 = "Aku tidak tahu cara merayakan ulang tahun orang. Apakah aku… bernyanyi dan bertepuk tangan?",
  str_voice_1500991_16 = "Waktunya bekerja. Siapa yang harus kita hajar? Apakah topik ini terlalu menakutkan untuk dibicarakan?",
  str_voice_1500991_17 = "Selamat pagi. Aku cukup sehat hari ini dan bisa bekerja dengan energik. Bagaimana denganmu?",
  str_voice_1500991_18 = "Jangan terlalu memikirkan pekerjaan. Beristirahatlah. Mungkin semuanya akan menjadi lebih baik setelahnya.",
  str_voice_1500991_19 = "Malam ini akan dingin, hati-hati jangan sampai masuk angin… Oh, aku baik-baik saja. Sudah terbiasa.",
  str_voice_1500991_20 = "Umbraton itu menyenangkan. Kota ini memungkinkanku mencari nafkah sebagai tentara bayaran.",
  str_voice_1500991_21 = "Mungkin ada lebih banyak intel di True Order, tetapi entah bagaimana rasanya ini mencurigakan…",
  str_voice_1500991_22 = "Seolah-olah kau sedang diawasi atau apa?",
  str_voice_1500991_23 = "Eclipsite telah membunuh banyak orang. Aku tidak berharap kau, termasuk orang tuaku, bertemu dengan mereka.",
  str_voice_1500991_24 = "Kata Connolly, aku diperbolehkan minum kopi di kafenya. Dia mengatakannya pada seseorang sepertiku…",
  str_voice_1500991_25 = "Jane merujuk pekerjaan kepadaku. Dia juga mengajariku cara membaca kontrak tentara bayaran. Aku sangat berterima kasih padanya.",
  str_voice_1500991_26 = "Sebenarnya… Aku sangat menyukai binatang kecil, tetapi aku takut tidak sengaja melukai mereka.",
  str_voice_1500991_27 = "Meski membenci tubuhku yang terkutuk, aku tidak bisa memaksa diriku untuk membenci pedang ajaib ini…",
  str_voice_1500991_28 = "Hubunganmu dengan Colossus semacam hubunganku dengan pedang ajaib, terhubung dan bersimbiosis.",
  str_voice_1500991_29 = "Kau ingin mempekerjakan aku? Aku bisa membantu dalam pertarungan dan aku tidak meminta bayaran yang tinggi… Aku bisa menyingkirkan apa pun dalam jangkauan pedang ajaib ini untukmu.",
  str_voice_1500991_30 = "Kekuatan kutukan makin kuat…",
  str_voice_1500991_31 = "Aku mengerti. Aku harus mengangkat pedang.",
  str_voice_1500991_32 = "Suatu saat nanti, semua akan berakhir.",
  str_voice_1500991_33 = "Tidak apa-apa meski jalannya dipenuhi duri.",
  str_voice_1500991_34 = "Ingatlah untuk… menjaga jarak.",
  str_voice_1500991_35 = "Aku siap.",
  str_voice_1500991_36 = "Aku akan mengikutimu.",
  str_voice_1500991_37 = "Pinjami aku kekuatanmu, pedang ajaib.",
  str_voice_1500991_38 = "Tebas duri untuk membuka jalan ke depan!",
  str_voice_1500991_39 = "Ambil durinya.",
  str_voice_1500991_40 = "Muncullah cahaya.",
  str_voice_1500991_41 = "Apa?… Kau mau aku yang memimpin?",
  str_voice_1500991_42 = "Bagus. Kali ini kita menang.",
  str_voice_1500991_43 = "Aku hampir tidak bisa mengatasinya… Maaf…",
  str_voice_1500991_44 = "Bagiku, selain menggunakan pedangku, aktivitas lain… Oh, kurasa aku tidak keberatan mengobrol.",
  str_voice_1500991_45 = "Yah… Ini tidak dihitung sebagai gajiku, 'kan?",
  str_voice_1500991_46 = "Ini hadiah untukku?… Kau yakin aku bisa menerimanya?",
  str_voice_1500991_47 = "Anu… Aku akan memikirkan cara berterima kasih…",
  str_voice_1500991_48 = "Terima kasih! Bagus sekali hadiahnya, aku senang sekali.",
  str_voice_1500991_49 = "Mungkin beberapa orang memiliki gejala yang sama seperti yang kualami dulu. Mungkin itu sebabnya buku-buku kuno dan pedang ini diturunkan.",
  str_voice_1500991_50 = "Hewan-hewan kecil yang imut biasa datang ke kamarku dan bermain denganku ketika aku terbaring sakit. Namun, mereka tidak pernah datang setelah aku dapat pedang ajaib.",
  str_voice_1500991_51 = "Aku tahu orang tuaku tidak bisa bersamaku lagi karena kutukan itu… Namun, kami semua mencari cara untuk mengatasinya. Kelak, kami akan bertemu lagi.",
  str_voice_1500991_52 = "Alchemy Stars.",
  str_voice_1500991_53 = "Halo.",
  str_voice_1500991_54 = "Eh, kau sudah bangun?",
  str_voice_1500991_55 = "Punya waktu sebentar?",
  str_voice_1500991_56 = "Apakah aku mengganggu istirahatmu?",
  str_voice_1500991_57 = "Aku mengharapkan yang terbaik untukmu tahun ini.",
  str_voice_1300941_1 = "Semua orang di Colossus sangat ramah. Tidak ada yang keberatan aku banyak melamun…",
  str_voice_1300941_2 = "Kenapa rambutku pendek? Tidak ada alasan spesial, sih. Hanya saja aku merasa rambut seperti ini lebih mudah untuk diatur…",
  str_voice_1300941_3 = "Aku jarang bicara. Bukannya tidak mau bicara, marah, atau apa…",
  str_voice_1300941_4 = "J-jangan takut dengan uap. Uap akan melindungimu…",
  str_voice_1300941_5 = "Aku suka Staff of Spring, dan musim semi itu sendiri… Bagaimana denganmu?",
  str_voice_1300941_7 = "A-apakah kau sudah ada di sini dari tadi? Aku menghargai itu, tetapi aku sedang ingin sendiri dulu…",
  str_voice_1300941_8 = "Kau… kau tahu aku tidak bisa merasakan dingin, tetapi kau masih memedulikanku… Kau sangat baik.",
  str_voice_1300941_9 = "Maaf! Apa aku bengong? Itu karena aku merasa nyaman saat bersamamu…",
  str_voice_1300941_10 = "B-bolehkah aku tinggal di sini sendiri? Tidak apa-apa 'kan jika aku sedikit melamun di sini…",
  str_voice_1300941_11 = "A-aku? A-aku sedikit gugup menghadapi begitu banyak orang untuk kali pertama… Namun, aku akan melakukan yang terbaik.",
  str_voice_1300941_12 = "Air… Air adalah makhluk lembut yang melindungiku, sama seperti orang tuaku…",
  str_voice_1300941_13 = "Udaranya segar… Maukah kau duduk di atas salju dan melamun bersama?…",
  str_voice_1300941_14 = "Aku tidak kedinginan. Aku baik-baik saja… Namun, bagaimana rasanya… \"Kedinginan\"?",
  str_voice_1300941_15 = "Selamat ulang tahun! Semoga udara musim semi selalu menyertaimu…",
  str_voice_1300941_16 = "Baru bersiap untuk berpatroli. Aku tidak tertidur atau semacamnya…",
  str_voice_1300941_17 = "Aku bangun pagi setiap hari karena aku harus berpatroli. Namun, kau bangun pagi juga…",
  str_voice_1300941_18 = "Sebentar lagi jam istirahat, 'kan?",
  str_voice_1300941_19 = "Aku sudah terbiasa hidup seperti ini, tetapi kau harus beristirahat…",
  str_voice_1300941_20 = "Dengan hamparan salju yang luas dan sinar matahari yang hangat, ini adalah tempat yang sangat menenangkan…",
  str_voice_1300941_21 = "Seharusnya ada musim semi di kota putih besar itu, 'kan?",
  str_voice_1300941_22 = "Demi Utara…",
  str_voice_1300941_23 = "Para penyerbu yang membunuh orang tuaku yang tidak bersalah… Aku takkan pernah memaafkan mereka.",
  str_voice_1300941_24 = "Noah dan aku sering bertukar pikiran tentang gagasan terkait suhu yang membingungkan kami… Apakah itu aneh?",
  str_voice_1300941_25 = "Yang Mulia Ratu telah memberiku pilihan, jadi aku memutuskan untuk meneruskan pekerjaan orang tuaku.",
  str_voice_1300941_26 = "Musim semi yang damai, hamparan salju yang tenang, dan tempat bagiku untuk membiarkan pikiranku mengembara…",
  str_voice_1300941_27 = "Jika kau harus tahu, itu adalah tempat yang bising… Tempat-tempat ini membuatku gugup.",
  str_voice_1300941_28 = "Seputih salju… Ada terlalu banyak orang di sini, tetapi aku akan mencoba yang terbaik agar terbiasa…",
  str_voice_1300941_29 = "Aku Leah. Aku petugas patroli di Northland… Maaf, aku harus bilang apa kepada orang yang baru saja kutemui, ya?",
  str_voice_1300941_30 = "Apakah ini… kekuatan?",
  str_voice_1300941_31 = "Apakah ini… Seperti inikah rasanya \"musim semi\"?",
  str_voice_1300941_32 = "Aku bisa melindungimu dengan lebih baik dalam perjalanan.",
  str_voice_1300941_34 = "Aku sedikit gugup…",
  str_voice_1300941_35 = "Musim semi, bersiaplah!",
  str_voice_1300941_36 = "Uapnya sudah siap.",
  str_voice_1300941_37 = "Napas musim semi!",
  str_voice_1300941_38 = "Rasakan kekuatannya yang lembut…!",
  str_voice_1300941_39 = "Uap… Menyebar!",
  str_voice_1300941_40 = "Uap… Menguap!",
  str_voice_1300941_41 = "B-bolehkah?",
  str_voice_1300941_42 = "Aku… Aku berhasil!",
  str_voice_1300941_43 = "Maafkan aku karena telah membuatmu terluka…",
  str_voice_1300941_44 = "Di sana… Sedikit bising… Aku tidak terbiasa…",
  str_voice_1300941_45 = "Ini hadiah untukku… Eh, terima kasih.",
  str_voice_1300941_46 = "Aku sedikit terkejut…",
  str_voice_1300941_47 = "Sungguh hadiah yang bijaksana…",
  str_voice_1300941_48 = "Apa yang harus kukatakan ketika merasa bahagia?",
  str_voice_1300941_49 = "Aku mengambil Staff of Spring yang ditawarkan oleh Yang Mulia Ratu, lalu melanjutkan pekerjaan yang ditinggalkan oleh orang tuaku… Ini bukan tentang takdir, tapi… Ini hanya sesuatu yang harus kulakukan.",
  str_voice_1300941_50 = "Kerajaan beku Northland… Udara yang segar, sinar matahari yang lembut, dan dataran salju yang luas tempat aku akan tenggelam dalam pikiran… Itu tempat favoritku di dunia ini.",
  str_voice_1300941_51 = "Aku terbiasa berpatroli sendirian di salju. Terkadang aku mendengarkan para pengelana yang lewat membicarakan hal-hal yang telah mereka lihat dan dengar, serta seperti apa musim semi itu… Sungguh aku ingin melihatnya sendiri…",
  str_voice_1300941_52 = "Alchemy… Stars…",
  str_voice_1300941_53 = "Aku di sini…",
  str_voice_1300941_54 = "Selamat pagi…",
  str_voice_1300941_55 = "Aku baik-baik saja… Kau?",
  str_voice_1300941_56 = "Bagus. Beristirahatlah.",
  str_voice_1300941_57 = "Semoga kau beruntung di tahun depan, bocah lembut…",
  str_voice_1400951_1 = "Di sini sangat luas. Kupikir aku tak akan pernah melihat sesuatu yang lebih besar dari ini selama sisa hidupku.",
  str_voice_1400951_2 = "Orang-orang di lini bisnisku sangat memperhatikan reputasi kami, jadi kau tidak perlu khawatir.",
  str_voice_1400951_3 = "Aku membuat sendiri baju pelindung ini. Aku telah menambahkan beberapa fitur berguna ke rancanganku, khususnya fitur pencegah kebocoran aroma.",
  str_voice_1400951_4 = "Kau ingin aku memberimu sebotol ramuan di ekorku ini? Ini dapat berguna pada saat-saat genting, tetapi kau harus menanganinya dengan hati-hati.",
  str_voice_1400951_5 = "Kehidupanku sebagai tentara bayaran mulai melelahkan. Aku sudah berpikir untuk mengubah cara hidupku, tetapi masih belum tahu caranya.",
  str_voice_1400951_6 = "Bertahan hidup di dunia ini bagi orang sepertiku itu terlalu sulit. Aku hanya senang ada jauh lebih banyak orang baik di Umbraton daripada yang aku kira. Bisa dibilang aku dirawat dengan baik.",
  str_voice_1400951_7 = "Topeng? Aku tidak bisa melepasnya. Seluruh rangkaian peralatan ini adalah satu unit. Ini takkan berfungsi jika ada bagian yang hilang.",
  str_voice_1400951_8 = "Jika kau mempertimbangkan kolaborasi jangka panjang, aku bisa memberimu diskon 20%. Menawarkan diskon untuk klien lama adalah hal yang wajar.",
  str_voice_1400951_9 = "Mau ikut ke tempatku kapan-kapan? Agak kecil, tetapi cukup nyaman untuk ditinggali. Tinggal di lingkungan yang berbeda pastinya menyenangkan.",
  str_voice_1400951_10 = "Kau sedang beristirahat? Aku juga mau beristirahat.",
  str_voice_1400951_11 = "Baik. Tunggu sebentar.",
  str_voice_1400951_12 = "Aku melihat dua anak kecil menjual sesuatu di pasar gelap kali terakhir aku ke sana. Sepertinya situasi akhir-akhir ini sangat sulit bagi semua orang.",
  str_voice_1400951_13 = "Aku ingat melihat satu atau dua Caelestite saat aku masih kecil. Sayang sekali!",
  str_voice_1400951_14 = "Berhati-hatilah, atau kau akan segera menjadi sasaran di Umbraton.",
  str_voice_1400951_15 = "Selamat ulang tahun! Tumbuh dewasa adalah suatu kesenangan.",
  str_voice_1400951_16 = "Halo, Tuan. Apa yang akan kita lakukan selanjutnya?",
  str_voice_1400951_17 = "Selamat pagi. Hari yang indah dimulai dengan segelas susu.",
  str_voice_1400951_18 = "Selamat malam. Aku membarter beberapa alat dari pasar gelap. Mau lihat?",
  str_voice_1400951_19 = "Orang-orang semuda dirimu harus tidur lebih awal… Namun, tentu saja aku takkan memaksamu.",
  str_voice_1400951_20 = "Aku tidak perlu memedulikan statusku di Umbraton, jadi tinggal di sini tidak terlalu buruk.",
  str_voice_1400951_21 = "Aku pernah ke Illumina beberapa kali untuk urusan bisnis. Tampaknya kota itu berkembang pesat dan orang-orang di sana bersikap ramah.",
  str_voice_1400951_22 = "Kau ingin aku bilang apa?",
  str_voice_1400951_23 = "Aku pernah berurusan dengan hal-hal itu selama hampir dua dekade. Aku sudah terbiasa dengan mereka. Memangnya dari mana asal mereka?",
  str_voice_1400951_24 = "Tingkah Penguin dan Kuma menghibur juga kalau sedang bersama. Aku sanggup mendengarkan komedi tunggal mereka setiap hari.",
  str_voice_1400951_25 = "Korgon cukup baik. Aku sedang mencoba memutuskan apakah kelak akan pindah ke pulaunya atau tidak.",
  str_voice_1400951_26 = "Aku suka tempat yang gelap dan lembap, dan seperangkat perlengkapan ini sudah cukup memenuhi kebutuhanku.",
  str_voice_1400951_27 = "Aku masih tidak suka diganggu, apalagi saat ada di rumah.",
  str_voice_1400951_28 = "Bukankah si besar ini luar biasa? Apakah kau satu-satunya di dunia ini yang bisa mengendalikan Colossus?",
  str_voice_1400951_29 = "Halo! Aku selalu siap melayanimu.",
  str_voice_1400951_30 = "Aku menjadi lebih mahir dalam menangani urusanku.",
  str_voice_1400951_31 = "Ini terasa menyenangkan. Terima kasih.",
  str_voice_1400951_32 = "Kemudian aku bisa menerima lebih banyak komisi.",
  str_voice_1400951_33 = "Batas ditetapkan untuk dilanggar.",
  str_voice_1400951_34 = "Aku akan pergi ke sana.",
  str_voice_1400951_35 = "Aku punya rencana.",
  str_voice_1400951_36 = "Kau sudah menerimanya?",
  str_voice_1400951_37 = "Sekaranglah kesempatan kita!",
  str_voice_1400951_38 = "Kau tidak mau berkelahi menggunakan pisau.",
  str_voice_1400951_39 = "Terimalah ini.",
  str_voice_1400951_40 = "Lihat-lihat apa kau?",
  str_voice_1400951_41 = "Bagus. Ayo kita lakukan.",
  str_voice_1400951_42 = "Itu dianggap mudah.",
  str_voice_1400951_43 = "Perbedaan kekuatan kita terlalu jauh.",
  str_voice_1400951_44 = "Ada yang bisa kubantu? Bisakah kita pergi ke suatu tempat yang teduh untuk berbicara?",
  str_voice_1400951_45 = "Baik sekali kau mau melakukan ini.",
  str_voice_1400951_46 = "Barang yang bagus!",
  str_voice_1400951_47 = "Aku sangat tersanjung.",
  str_voice_1400951_48 = "Itu… Aku sangat berterima kasih.",
  str_voice_1400951_49 = "Meskipun kita semua Aurorian, ada banyak perbedaan pada kepribadian kita. Aku terganggu oleh kondisi fisikku dalam waktu yang sangat lama, tetapi kini aku sudah terbiasa.",
  str_voice_1400951_50 = "Berbicara tentang momen yang mengesankan… Yang terlintas dalam pikiranku adalah saat Umbraton dikepung. Saat itu, aku berusia 20 tahun. Aku sudah mengira bahwa aku bakal mati.",
  str_voice_1400951_51 = "Aku merasa situasi akhir-akhir ini di luar kemampuanku. Tubuhku mungkin masih muda, tetapi mentalitasku… Mungkin aku harus mempertimbangkan untuk pensiun. Tempat Korgon sepertinya pilihan yang lumayan.",
  str_voice_1400951_52 = "Alchemy Stars.",
  str_voice_1400951_53 = "Halo.",
  str_voice_1400951_54 = "Rencana satu hari dimulai dengan fajar.",
  str_voice_1400951_55 = "Selamat siang. Kau sudah makan siang?",
  str_voice_1400951_56 = "Selamat malam, Navigator!",
  str_voice_1400951_57 = "Selamat Tahun Baru! Tahun ini akan segera menjadi sangat menyenangkan.",
  str_voice_1400621_1 = "Setiap kali menatap keluar dari Colossus, aku mengagumi luasnya dunia, dan itu semua berkat Leah.",
  str_voice_1400621_2 = "Kudengar dunia ini berpuluh-puluh kali lebih besar daripada benua yang bisa kita lihat. Benarkah? Aku mau memberikan apa pun asalkan bisa melihat seluruh tempat di dunia ini.",
  str_voice_1400621_3 = "Bolehkah aku merombak kamarku? Aku terbiasa dikelilingi tumbuhan.",
  str_voice_1400621_4 = "Sulur ini mungkin berasal dari kekuatanku, tapi mereka sudah bersamaku sejak lama. Tidak ada salahnya aku menyebut mereka teman.",
  str_voice_1400621_5 = "Apa aneh menjadi kuat untuk melindungi teman-temanmu? Apa maksud senyuman kebapakan di wajahmu itu… Kau tidak jauh lebih tua dariku, 'kan?",
  str_voice_1400621_6 = "Ayahku adalah penjaga hutan yang hebat. Aku harap aku bisa melampauinya suatu hari nanti.",
  str_voice_1400621_7 = "Kurasa kita berteman sekarang karena kita sudah lama bekerja sama.",
  str_voice_1400621_8 = "Kupikir kita punya banyak kesamaan, seperti posisi kita… orang-orang di sekitar kita, dan sebagainya…",
  str_voice_1400621_9 = "Sebuah kehormatan memiliki teman sepertimu. Aku akan mengenalkanmu kepada siapa pun di Windward Forest kalau ada kesempatan.",
  str_voice_1400621_10 = "Kelopak matamu seperti bunga saat petang, seperti akan menutup. Tidurlah.",
  str_voice_1400621_11 = "Aku akan melakukan semua yang kubisa.",
  str_voice_1400621_12 = "Pedang ini? Mungkin terbuat dari kayu, tetapi setajam besi.",
  str_voice_1400621_13 = "Tolong menjauhlah saat aku menghunuskan pedang agar kau tidak terjerat sulur ini.",
  str_voice_1400621_14 = "Kamar seperti ini… Sedikit sulit untuk cepat terbiasanya dengannya. Maaf. Ini kamar yang bagus. Hanya saja, tidak ada aura alam di sini.",
  str_voice_1400621_15 = "Selamat ulang tahun. Semoga kau suka hadiahnya.",
  str_voice_1400621_16 = "Ini aktivitas sehari-hari yang paling penting. Teruslah berolahraga dan jangan bermalas-malasan.",
  str_voice_1400621_17 = "Selamat pagi. Kau terlihat… agak lelah.",
  str_voice_1400621_18 = "Selamat malam. Hutan bisa sangat berbahaya di malam hari. Sebaiknya kau jauh-jauh dari sana.",
  str_voice_1400621_19 = "Aku paham yang kau rasakan sekarang karena tidak pernah ada cukup waktu untuk melakukan semuanya. Walau begitu, istirahat sangatlah penting.",
  str_voice_1400621_20 = "Northland… Tempat yang tidak terlibat dengan urusan dunia, dan akibatnya terisolasi.",
  str_voice_1400621_21 = "Aku sudah dengar betapa orang-orang di Rediesel Wrench sangat berjiwa bebas.",
  str_voice_1400621_22 = "Demi Utara!",
  str_voice_1400621_23 = "Sekelompok makhluk yang menyedihkan dan menjijikkan. Mereka tidak seharusnya ada.",
  str_voice_1400621_24 = "Yang Mulia Ratu memiliki peran penting yang tak tertandingi. Dialah penjaga Northland.",
  str_voice_1400621_25 = "Leah… Dia teman yang sangat penting bagiku dalam banyak hal.",
  str_voice_1400621_26 = "Bagiku, teman terbaik adalah yang bisa jujur dan berterus terang kepadaku.",
  str_voice_1400621_27 = "Aku tidak ingin menghabiskan waktu bersama orang yang palsu dan munafik.",
  str_voice_1400621_28 = "Colossus memang menarik. Aku juga mau punya… Wajar 'kan aku merasa begini?",
  str_voice_1400621_29 = "Aku Sylva, penjaga hutan di Windward Forest. Senang bertemu denganmu.",
  str_voice_1400621_30 = "Kekuatan itu mulai muncul.",
  str_voice_1400621_31 = "Inilah hasil latihanku.",
  str_voice_1400621_32 = "Berjuang untuk menjadi perkasa.",
  str_voice_1400621_33 = "Aku akan melindungi siapa pun.",
  str_voice_1400621_34 = "Serahkan padaku.",
  str_voice_1400621_35 = "Aku akan melakukannya!",
  str_voice_1400621_36 = "Apa?",
  str_voice_1400621_37 = "Hutan, panggil angin.",
  str_voice_1400621_38 = "Angin, tusuk musuhku.",
  str_voice_1400621_39 = "Sulur itu.",
  str_voice_1400621_40 = "Angin pedang.",
  str_voice_1400621_41 = "Aku akan ikut berusaha.",
  str_voice_1400621_42 = "Kemenangan berharga.",
  str_voice_1400621_43 = "Pengalamanku sangat kurang…",
  str_voice_1400621_44 = "Aku tidak tahu apa yang bisa kulakukan untukmu… Bagaimana kalau kau kuberi sulur?",
  str_voice_1400621_45 = "Ini… Bolehkah aku menyimpannya?",
  str_voice_1400621_46 = "Hal ini menarik.",
  str_voice_1400621_47 = "Terima kasih… Navigator.",
  str_voice_1400621_48 = "Ehem, senang sekali punya teman sepertimu!",
  str_voice_1400621_49 = "Aku sangat meneladani ayah dan sebenarnya karena dialah aku perlahan menguasai keterampilan pedang. Namun, kepergiannya yang terlalu cepat sangat berat bagi ibuku sampai-sampai dia… Lupakan. Bukan apa-apa.",
  str_voice_1400621_50 = "Kematian dini orang tuaku membuatku sangat terpukul karena aku masih kecil waktu itu. Leah-lah yang membantuku bangkit dari trauma. Kalau bukan karena dia, aku tidak akan seperti ini sekarang.",
  str_voice_1400621_51 = "Aku selalu malu setiap topik ini dibahas. Untuk waktu lama, kupikir Leah itu laki-laki. Aku jadi ingin masuk ke dalam tanah setiap mengingat-ingat waktu yang kuhabiskan bersamanya.",
  str_voice_1400621_52 = "Alchemy Stars.",
  str_voice_1400621_53 = "Halo.",
  str_voice_1400621_54 = "Selamat pagi, Navigator.",
  str_voice_1400621_55 = "Mau makan siang denganku?",
  str_voice_1400621_56 = "Aku akan tidur. Kau?",
  str_voice_1400621_57 = "Selamat Tahun Baru. Waktu rasanya sangat cepat berlalu.",
  str_voice_1500871_1 = "Sebagai bangsawan Lumopolis, aku harus melindungi orang-orang sepertimu… Kau tidak butuh perlindunganku? Aku meremehkanmu.",
  str_voice_1500871_2 = "Kau bisa berlatih melempar dart denganku kalau sedang tidak ada kegiatan… Kenapa kau sangat bersemangat? Aku hanya memintamu memegang papan sasaran untukku.",
  str_voice_1500871_3 = "Hobiku kuno? Menurutku tidak ada salahnya suka opera tradisional. Sebagai bangsawan, aku harus menganggap serius tradisi budaya.",
  str_voice_1500871_4 = "Aku menjadikan tombak petir sebagai senjata karena aku jago menggunakan tombak, satu-satunya senjata yang sesuai dengan statusku sebagai kesatria hebat.",
  str_voice_1500871_5 = "Kau meragukan akurasi tombak petir? Jangan khawatir. Aku bisa menembus apa pun dengan dart atau tombak petir, bahkan sayap nyamuk kalau mau.",
  str_voice_1500871_6 = "Hati-hati. Petir di sekelilingku bukan cuma hiasan.",
  str_voice_1500871_7 = "Sebagai bangsawan, aku harus berperilaku pantas. Aku akan menjaga kehormatan, tetapi tidak akan merendahkan siapa pun, termasuk kau.",
  str_voice_1500871_8 = "Ada masanya aku bersikap terlalu angkuh… Namun, itu disebabkan oleh status dan kemampuanku. Berubah seketika tidaklah mudah bagiku. Mohon jangan salah paham.",
  str_voice_1500871_9 = "Entah kenapa… tapi aku merasa bisa menjadi diriku sepenuhnya di dalam jiwa saat bersamamu.",
  str_voice_1500871_10 = "Sudah jam istirahat? Sebagai prajurit hebat Lumopolis, tidak baik kalau memiliki terlalu banyak waktu luang. Namun, aku memang perlu beristirahat.",
  str_voice_1500871_11 = "Kalau harus melakukannya, aku akan memikul tanggung jawab itu. Kau hanya perlu percaya padaku.",
  str_voice_1500871_12 = "Aku mungkin terlalu banyak memikirkan status. Namun, orang memang terlahir tidak setara.",
  str_voice_1500871_13 = "Semua orang biasa yang tidak mampu mengambil keputusan matang harus diam dan menunggu dilindungi saja, 'kan?",
  str_voice_1500871_14 = "Bertempur dan berlatih adalah bagian dari keseharianku. Kau tidak perlu khawatir.",
  str_voice_1500871_15 = "Aku tentu ingat hari ini ulang tahunmu… Kau mau hadiah apa?",
  str_voice_1500871_16 = "Kau di situ rupanya. Ini jam latihan harianku. Maksudku… Aku sekarang berlatih dart.",
  str_voice_1500871_17 = "Tidak perlu mengucap salam. Membuang-buang waktu saja.",
  str_voice_1500871_18 = "Belum terlambat bagi seorang kesatria.",
  str_voice_1500871_19 = "Pola tidur yang baik sangat penting untuk menjaga kesehatan.",
  str_voice_1500871_20 = "Melindungi orang adalah kewajiban bangsawan. Inilah tatanan sosial yang harus dimiliki Lumopolis.",
  str_voice_1500871_21 = "Memangnya ada aturan seperti apa di Illumina, tempat orang sangat menjunjung teknologi?",
  str_voice_1500871_22 = "Demi White Night!",
  str_voice_1500871_23 = "Orang-orang yang mengganggu tatanan dan kedamaian Lumopolis harus disingkirkan.",
  str_voice_1500871_24 = "City Lord adalah orang yang memiliki kemampuan dan integritas, tapi… apa bermain politik keputusan yang tepat?",
  str_voice_1500871_25 = "Carleen adalah anak dari City Lord, tapi dia sedikit terlalu naif.",
  str_voice_1500871_26 = "Persisnya, opera bukan hobi karena itu bagian dari hidupku sekarang.",
  str_voice_1500871_27 = "Para bangsawan yang bersembunyi di balik gelar dan hidup dengan glamor tidak lebih dari orang bodoh yang menyombongkan diri.",
  str_voice_1500871_28 = "Colossus menyimbolkan garis keluarga dan identitasmu, serta kebanggaan dan kejayaanmu di masa depan.",
  str_voice_1500871_29 = "Senang bertemu denganmu. Namaku Beverly. Aku akan bekerja denganmu kali ini. Sebagai anggota Lumopolis Guard, sudah tanggung jawabku untuk melindungi orang biasa di sini. Tenanglah.",
  str_voice_1500871_30 = "Tidak ada batas!",
  str_voice_1500871_31 = "Bisa diperbaiki.",
  str_voice_1500871_32 = "Inilah kekuatan yang layak kudapatkan.",
  str_voice_1500871_33 = "Tombak ini akan menusuk langit malam…",
  str_voice_1500871_34 = "Selalu siaga.",
  str_voice_1500871_35 = "Tunjukkan jalannya.",
  str_voice_1500871_36 = "Kesempatan bagus!",
  str_voice_1500871_37 = "Tusuklah, tombak petir!",
  str_voice_1500871_38 = "Sempurna!",
  str_voice_1500871_39 = "Serangan terakhir!",
  str_voice_1500871_40 = "Wujudkan kedamaian!",
  str_voice_1500871_41 = "Tetaplah di belakangku!",
  str_voice_1500871_42 = "Ini misiku.",
  str_voice_1500871_43 = "Aku tidak cukup kuat…",
  str_voice_1500871_44 = "Waktunya beristirahat sebentar… Hah? Kenapa aku mengeluarkan tombak? Latihan bertarung juga bisa dianggap istirahat, 'kan?",
  str_voice_1500871_45 = "Hmm, akan kuterima.",
  str_voice_1500871_46 = "Oh, hadiah yang sempurna untukku! Terima kasih.",
  str_voice_1500871_47 = "Aku sangat menghargai pengertianmu.",
  str_voice_1500871_48 = "Terima kasih… Sepertinya aku harus lebih memperhatikanmu.",
  str_voice_1500871_49 = "Keluargaku terkemuka dan berkuasa. Kami dihormati orang biasa, jadi wajar kalau kami bersedia mati untuk melindungi mereka. Ini kebanggaan dan tanggung jawab yang dipegang keluargaku.",
  str_voice_1500871_50 = "Tidak seperti orang-orang yang disebut bangsawan, yang gaya hidupnya mewah, aku berkomitmen pada tugas dan kewajibanku untuk menjaga ketertiban dan kedamaian… Namun, bagaimana dengan mereka? Apa mereka pantas disebut bangsawan?",
  str_voice_1500871_51 = "Ayahku bilang cepat atau lambat, keangkuhan akan merugikanku. Aku sudah tahu masalah ini sejak lama, tapi keangkuhan sudah ada di dalam darahku, jadi sulit kuubah…",
  str_voice_1500871_52 = "Alchemy Stars!",
  str_voice_1500871_53 = "Aku di sini.",
  str_voice_1500871_54 = "Selamat siang.",
  str_voice_1500871_55 = "Selamat beristirahat.",
  str_voice_1500871_56 = "Semoga tidur nyenyak malam ini.",
  str_voice_1500871_57 = "Ini Tahun Baru. Buatlah permintaan.",
  str_voice_1600301_1 = "Lumopolis Caravan sudah tahu. Mereka sekarang mengirimkan peti kosong. Kita harus memantau pergerakan mereka untuk memastikan mereka membawa barang sebelum bertindak.",
  str_voice_1600301_2 = "Dengar, Naik. Lain kali, kau buang ini ke keranjang sampah. Oke?",
  str_voice_1600301_3 = "Buku? Aku sudah memberikannya kepada kawan-kawan. Aku ingin menguji mereka tentangnya! Kau menaruh beberapa majalah dengan buku-buku itu? Baiklah, aku akan mengujikannya juga!",
  str_voice_1600301_4 = "Katakan apa pun yang kau mau. Kenapa aku punya nama aneh seperti Sinsa? Namamu pun tidak terdengar wajar, kok…",
  str_voice_1600301_5 = "Mau lihat kunci pas punyaku? Aku hanya meminjamkannya kepada beberapa orang yang tepercaya… Ha? Oh, dalam hal ini, kepercayaanku tidak berhubungan dengan keadilan atau semacamnya. Aku butuh seseorang untuk memeganginya karena beratnya satu ton.",
  str_voice_1600301_6 = "\"Orang bisa bohong, tapi tinju tidak menipu. Hajar orang dan kau akan mengetahui kebenaran!\" Bagus dan mudah diingat! Rasakan, Charon!",
  str_voice_1600301_7 = "Aku suka bicara dengan suara keras. Kenapa tidak? Kau harus tertawa saat gembira dan mengumpat saat marah, 'kan?",
  str_voice_1600301_8 = "Masih belum punya rencana tempur, ya? Kita pikir sambil jalan? Hahaha, seperti yang bisa diperkirakan dari Navigator! Biarkan senjata yang menentukan strategi kita!",
  str_voice_1600301_9 = "Aku percaya kepada semua orang di Rediesel Wrench sepenuh hati. Kalau kau… Ya, kau juga bisa diandalkan! Jadi, kapan kau mau bergabung dengan kami di sini?",
  str_voice_1600301_10 = "Aku lebih suka kau mengurungku daripada menyuruhku duduk bengong di sini… Ya, aku bicara padamu!",
  str_voice_1600301_11 = "Kau… kau menyuruhku berjaga? Sial, tidak ada balapan, tidak ada pertarungan, cuma berdiri di sini? Ah, terserah sajalah, ayo.",
  str_voice_1600301_12 = "Kalau tidak bisa menyelesaikan masalah dengan tinju, cobalah meriam! Masih belum bisa? Serahkan padaku dan akan kuberi mereka sedikit pelajaran!",
  str_voice_1600301_13 = "Makan, tidur, dan jalani hidup… Masing-masing dari kita punya pertempuran sendiri, yang tidak bisa dipahami orang lain.",
  str_voice_1600301_14 = "Hoi, cepatlah, Colossus! Di mana akseleratornya? Bagaimana cara mengganti gigi?",
  str_voice_1600301_15 = "Yo! Selamat ulang tahun! Aku lupa mencari hadiah, tapi… Baiklah, pergilah keluar dan cari sesuatu yang menarik bagi Navigator kita ini!",
  str_voice_1600301_16 = "Bertempur? Cuacanya cocok sekali untuk mengayunkan lengan mecha ini!",
  str_voice_1600301_17 = "Kau tidak tidur? Aku iri sekali dengan orang yang bisa tidur di mana saja…",
  str_voice_1600301_18 = "Malam sudah tiba dan semua terlelap. Tikus-tikus merayap keluar seiring turunnya kegelapan!",
  str_voice_1600301_19 = "Tidak bisa tidur juga, ya? Ayolah, kita cari kudapan tengah malam! Aku traktir!",
  str_voice_1600301_20 = "Jangan menilai kami dari penampilan kami yang lusuh. Kau tidak akan menemukan keluarga yang lebih kompak dan bisa diandalkan daripada Rediesel Wrench!",
  str_voice_1600301_21 = "Bagaimanapun, aku tidak bisa suka dengan para petugas itu. Terlalu banyak pengalaman buruk…",
  str_voice_1600301_22 = "Jalani hidup sepenuhnya!",
  str_voice_1600301_23 = "Serangga bodoh ini mengganggu sekali dan kita bahkan tidak bisa memakan mereka! Andai saja mereka mau kembali ke tempat asalnya…",
  str_voice_1600301_24 = "Aku ingat saat dia masih bisa tersenyum lepas. Saat itu, tak seorang pun dari kita tahu bahwa kehidupan bisa sekejam ini.",
  str_voice_1600301_25 = "Beberapa dari mereka memang sangat bisa diandalkan, tapi selera musik mereka, aduh… Ehem, lupakan kata-kataku barusan.",
  str_voice_1600301_26 = "Merampok dan membalap. Itulah dua minat terbesarku dalam hidup! Dangkal? Tidak ada yang salah dengan sedikit dangkal!",
  str_voice_1600301_27 = "Pernah lihat orang sangat marah sampai menghancurkan sebuah gunung? Nah, kalau ada yang menyakiti keluargaku, kau akan mendapatkan kursi terdepan untuk melihatnya.",
  str_voice_1600301_28 = "Wah, di sini nyaman dan terang! Aku mengeklaim tempat ini atas nama Rediesel Wrench! Ada yang tidak setuju?",
  str_voice_1600301_29 = "Selamat datang di Rediesel Desert, Nak. Bisa rasakan anginnya berubah? Jangan khawatir, itu bukan badai pasir, hanya gunung bernapas.",
  str_voice_1600301_30 = "Aku sangat bersemangat!",
  str_voice_1600301_31 = "Aha! Wow, aku hebat!",
  str_voice_1600301_32 = "Lebih cepat! Aku bahkan bisa lebih cepat!",
  str_voice_1600301_33 = "Sambutlah sang Raja Gurun!",
  str_voice_1600301_34 = "Cepatlah!",
  str_voice_1600301_35 = "Darahku mendidih!",
  str_voice_1600301_36 = "Di mana pertarungannya?",
  str_voice_1600301_37 = "Kalian semua, jaga perilaku!",
  str_voice_1600301_38 = "Kau tersesat?!",
  str_voice_1600301_39 = "Hancurkan!",
  str_voice_1600301_40 = "Bersiaplah!!",
  str_voice_1600301_41 = "Ikuti aba-abaku!",
  str_voice_1600301_42 = "Bagus! Kita sudah selesai pemanasan?",
  str_voice_1600301_43 = "Hahaha! Luka adalah tanda laki-laki sejati!",
  str_voice_1600301_44 = "Colossus milikmu luar biasa… Tenagaku sampai habis untuk menahan keinginan merampoknya!",
  str_voice_1600301_45 = "Apa ini tanda bahwa kau pengertian?",
  str_voice_1600301_46 = "Hoi! Seleramu bagus juga, Nak!",
  str_voice_1600301_47 = "Ha! Ini jauh lebih bagus daripada hasil rampokan kita belakangan!",
  str_voice_1600301_48 = "Waow! Ini persis seperti yang kuinginkan! Terima kasih!!",
  str_voice_1600301_49 = "Aku… tidak berhubungan baik dengan orang-orang Illumina. Aku tidak suka membicarakan itu sekarang, tapi kau akan tahu tak lama lagi.",
  str_voice_1600301_50 = "Kau sudah terbiasa dengan gaya hidup Rediesel Wrench? Kalau belum, bukan masalah. Kami tidak terlalu peduli. Astra sangat besar, tapi juga sangat kecil. Begitu kecil sampai Rediesel Desert adalah satu-satunya tempat yang bisa kami sebut rumah!",
  str_voice_1600301_51 = "Betul, Eve adalah adik perempuanku. Kami telah melalui masa sulit yang memperkuat ikatan kami. Aku hanya berharap keberuntungan juga memihakmu, Navigator.",
  str_voice_1600301_52 = "Alchemy Stars!",
  str_voice_1600301_53 = "Kau di sana, Nak?",
  str_voice_1600301_54 = "Bangunlah, Nak!",
  str_voice_1600301_55 = "Waktunya bekerja!",
  str_voice_1600301_56 = "Tidurlah sekarang.",
  str_voice_1600301_57 = "Selamat Tahun Baru! Kita akan bekerja sangat keras, sampai six pack di perutmu pun punya six pack! Haha!",
  str_voice_1400671_1 = "Apa Colossus bisa terbang ke pantai? Kudengar kau bisa lihat ikan duyung dari tepian.",
  str_voice_1400671_2 = "Lumopolis penuh dengan bangsawan… Ada pangeran atau putri?",
  str_voice_1400671_3 = "Kau belum pernah bertemu dengan Aurorian sebelumnya, Navigator? Kau tinggal di gua, ya?",
  str_voice_1400671_4 = "Beberapa orang bilang ada penyihir jahat di hutan-hutan Northland, tapi aku tidak takut sama sekali!",
  str_voice_1400671_5 = "Winter Palace milik sang Ratu terbuat dari es dan sangat indah. Aku akan mengajakmu ke sana kapan-kapan!",
  str_voice_1400671_6 = "Konon ujung selatan adalah gurun yang tidak berpenduduk… Kapan kau akan mengajakku ke sana?",
  str_voice_1400671_7 = "Aku ingin tahu masa lalumu. Kupikir bisa menjadi cerita hebat.",
  str_voice_1400671_8 = "Knight of Spades dan Queen of Hearts adalah temanku, jadi mereka temanmu juga.",
  str_voice_1400671_9 = "Bagaimana aku menguasai Luminatics? Kurasa itu terjadi begitu saja.",
  str_voice_1400671_10 = "Ke mana kalian pergi, Kesatria Sekop dan Ratu Hati?",
  str_voice_1400671_11 = "Tunggu di sini saja? Baiklah. Kupikir dua orang itu juga suka di sini.",
  str_voice_1400671_12 = "Ada perpustakaan di dekat sini? Kuharap mereka punya buku-buku dongeng yang bagus…",
  str_voice_1400671_13 = "Beberapa orang bilang aku muncul tiba-tiba, padahal aku cuma bertubuh pendek dan tak bersuara saat berjalan.",
  str_voice_1400671_14 = "Hopscotch seru sekali, aku bisa main sepuluh hari berturut-turut!",
  str_voice_1400671_15 = "Waktunya ulang tahun! Boleh aku ambil kuenya?",
  str_voice_1400671_16 = "Tidak banyak kejadian hari ini. Bagaimana kalau kita pergi bersenang-senang?",
  str_voice_1400671_17 = "Selamat pagi. Mau berjalan-jalan di hutan?",
  str_voice_1400671_18 = "Ke mana aku harus pergi hari ini?",
  str_voice_1400671_19 = "Mengantuk sekali… Apa sudah waktunya tidur?",
  str_voice_1400671_20 = "Orang Northland sangat ramah, walau hidup sedikit terlalu membosankan di sana.",
  str_voice_1400671_21 = "Lumopolis mengingatkanku akan bangsawan. Aku ragu apakah di sana ada orang biasa.",
  str_voice_1400671_22 = "Demi Utara.",
  str_voice_1400671_23 = "Makhluk yang sangat jahat, lebih buruk dari raja jahat di dongeng-dongeng!",
  str_voice_1400671_24 = "Sylva cuma tampak dingin saja. Dia sebenarnya baik hati!",
  str_voice_1400671_25 = "Leah sangat baik hati… Terkadang terlalu baik.",
  str_voice_1400671_26 = "Kudengar ada boneka berukuran nyata di benua ini. Aku mau satu…",
  str_voice_1400671_27 = "Jangan keras-keras, aku jadi merinding!",
  str_voice_1400671_28 = "Bisa kau menyuruhnya mengajakku berkeliling? Jadi \"Alice Mengagumi Dunia\"!",
  str_voice_1400671_29 = "Ini Colossus? Hai, aku Alice, dan aku akan sering bertemu denganmu.",
  str_voice_1400671_30 = "Makin cerdas!",
  str_voice_1400671_31 = "Kian tinggi!",
  str_voice_1400671_32 = "Bisa pergi lebih jauh sekarang!",
  str_voice_1400671_33 = "Tunjukkan pemandangan yang belum pernah kulihat sebelumnya!",
  str_voice_1400671_34 = "Ikutlah denganku!",
  str_voice_1400671_35 = "Ya! Aku siap!",
  str_voice_1400671_36 = "Haruskah aku melakukannya?",
  str_voice_1400671_37 = "Ini dia!",
  str_voice_1400671_38 = "Api!",
  str_voice_1400671_39 = "Knight of Spades!",
  str_voice_1400671_40 = "Queen of Hearts!",
  str_voice_1400671_41 = "Aku jadi pemimpin?",
  str_voice_1400671_42 = "Mengesankan, semuanya!",
  str_voice_1400671_43 = "Lari, semuanya…",
  str_voice_1400671_44 = "Mau main dengan kami? Kita mulai permainan baru!",
  str_voice_1400671_45 = "Terima kasih, Navigator!",
  str_voice_1400671_46 = "Aku suka ini!",
  str_voice_1400671_47 = "Aku sudah terima hadiah baru darimu!",
  str_voice_1400671_48 = "Imut sekali, aku sampai meleleh!",
  str_voice_1400671_49 = "Telinga kelinciku sangat terkenal di kalangan penduduk desa. Kau bisa menyentuhnya kalau mau.",
  str_voice_1400671_50 = "Kalau bukan berkat Leah dan Sylva, aku mungkin masih di Northland.",
  str_voice_1400671_51 = "Jangan takut dengan dua temanku. Mereka sudah banyak membantuku.",
  str_voice_1400671_52 = "Alchemy Stars.",
  str_voice_1400671_53 = "Hai!",
  str_voice_1400671_54 = "Selamat pagi!",
  str_voice_1400671_55 = "Selamat sore.",
  str_voice_1400671_56 = "Selamat malam.",
  str_voice_1400671_57 = "Selamat Tahun Baru.",
  str_voice_1701081_1 = "Saat penderitaan berakhir, bahkan untuk api terpanas sekali pun, yang tertinggal hanyalah tanah penuh abu.",
  str_voice_1701081_2 = "Aku menerima kekuatan kegelapan untuk melindungi. Aku dulu percaya aku tidak akan berubah, sebelum akhirnya menjadi senjata tanpa emosi.",
  str_voice_1701081_3 = "Ini hukuman, karena aku tidak bisa mendapatkan, menemui, atau mewujudkan kematian, dan tidak pula menerima kehancuran.",
  str_voice_1701081_4 = "Ini penyesalan, yang membuatku harus membuka mata dan melihat semua akibatnya.",
  str_voice_1701081_5 = "Karena menghancurkan hal yang seharusnya kulindungi, aku dikutuk hidup sengsara di rawa panas untuk selamanya.",
  str_voice_1701081_6 = "Aku iri kepadanya… Dia selalu tenang… Aku selalu terbakar tanpa tujuan, mengorbankan harga diri dan keyakinanku.",
  str_voice_1701081_7 = "Aku menghabiskan hidup untuk melindungi negeriku, sebagai pemburu dan prajurit… Namun, apa hasilnya? Bagaimanapun, aku tidak lebih dari pion yang terabaikan.",
  str_voice_1701081_8 = "Pendosa tidak pantas menangis kesakitan. Mereka hanya bisa terus berjuang…",
  str_voice_1701081_9 = "Cukup… Mari bicara tentangmu. Aku ingin melupakan sejenak masa laluku.",
  str_voice_1701081_10 = "Sebuah lubang di dalam hati, disulut dengan api abadi… Apa menurutmu itu penebusan dosa?",
  str_voice_1701081_11 = "Apa yang bisa kulakukan selain bertarung? Aku hanya senjata, jadi jawabanku mungkin hanya \"tidak ada.\"",
  str_voice_1701081_12 = "Makin sering aku memikirkannya, makin dingin hatiku. Namun, makin dingin hatiku, makin panas api itu.",
  str_voice_1701081_13 = "Hari itu, aku menghancurkan semuanya--dengan amukan api.",
  str_voice_1701081_14 = "\"Jatuhlah, jatuhlah,\" aku lihat mereka berteriak… dan tertawa.",
  str_voice_1701081_15 = "Aku cukup tenang untuk bersamamu hari ini. Katakan, kau ingin aku melakukan apa.",
  str_voice_1701081_16 = "Takdir sudah cukup baik kepadaku, hingga aku bisa di sini setelah ribuan tahun.",
  str_voice_1701081_17 = "Kau bisa dengar? Tangisan di waktu fajar dari kejauhan.",
  str_voice_1701081_18 = "Kuharap akan datang waktu saat kita tidak pernah lagi harus bertempur.",
  str_voice_1701081_19 = "Istirahatlah. Kau sudah cukup banyak bertarung. Pertempuran sudah selesai.",
  str_voice_1701081_20 = "Aku masih belum mengerti… mengapa para pahlawan yang sudah berjuang demi kerajaan ditelantarkan?",
  str_voice_1701081_21 = "Aku ingin mengunjungi kota-kota yang kausebutkan, lalu melihat cara hidup penduduknya dan seberapa bahagia mereka.",
  str_voice_1701081_22 = "Kita adalah kesatria yang paling kuat.",
  str_voice_1701081_23 = "Lampu-lampu penerang telah padam, tapi aku masih punya lava pelahap segala yang cukup untuk menghancurkan mereka.",
  str_voice_1701081_24 = "Kebenaran pasti sudah ditutupi sehingga Claymore mengambil keputusan… Itulah sebabnya aku sangat marah!",
  str_voice_1701081_25 = "Si kaku Mythos itu tidak tahu kenapa aku membakarnya dan apa yang membuatku marah.",
  str_voice_1701081_26 = "Itukah yang sudah Aurorian buat untuk diri mereka? Menakjubkan.",
  str_voice_1701081_27 = "Berdiri, maju, hadapi musuh, bertempur, lalu mencari penghiburan dalam penyesalan lagi.",
  str_voice_1701081_28 = "Apa Colossus juga datang denganmu? Takdirnya punya lebih banyak harapan daripada kita…",
  str_voice_1701081_29 = "Aku tidak paham kenapa kau menyelamatkanku. Apa supaya aku bisa menebus dosa-dosaku? Ingatan akan \"Silent Hunters\" seharusnya sudah hilang sejak lama, tapi aku masih tidak bisa lari darinya…",
  str_voice_1701081_30 = "Aku belum bisa memantik apinya.",
  str_voice_1701081_34 = "Tidak, aku bisa melakukannya sendiri.",
  str_voice_1701081_35 = "Habisi semua!",
  str_voice_1701081_36 = "Hancurkan semua!",
  str_voice_1701081_37 = "Bakar semuanya!",
  str_voice_1701081_38 = "Ratapan, sedu sedan, kembali ke jurang!",
  str_voice_1701081_39 = "Lari!",
  str_voice_1701081_40 = "Teriaklah!",
  str_voice_1701081_41 = "Pergilah.",
  str_voice_1701081_42 = "Harus kumatikan… api itu…",
  str_voice_1701081_43 = "Kenapa? Kenapa gagal?",
  str_voice_1701081_44 = "Awas, jangan mendekat. Aku akan menemuimu kalau sudah tenang.",
  str_voice_1701081_45 = "Letakkan saja di sana.",
  str_voice_1701081_46 = "Aku tidak tahu apa yang bisa kutawarkan untukmu.",
  str_voice_1701081_47 = "Terima kasih atas kebaikan hatimu. Aku akan menerimanya.",
  str_voice_1701081_48 = "Aku tidak punya apa-apa untuk membalasmu, tapi… terima kasih.",
  str_voice_1701081_49 = "Aku ingat kota yang terbakar di malam musim dingin yang beku itu. Dosa yang terukir di hatiku tidak akan hilang.",
  str_voice_1701081_50 = "Mungkin takdir sudah ditetapkan saat kita memutuskan bergabung dengan proyek itu… Tidak, aku tidak akan berkata-kata lagi.",
  str_voice_1701081_51 = "Dulu aku pikir dunia akan segera hancur, tapi sekarang aku sadar dunia akan terus berputar tanpa peduli siapa yang hidup, siapa yang mati… Naif sekali.",
  str_voice_1701081_52 = "Alchemy Stars.",
  str_voice_1701081_53 = "Apa kau di sana?",
  str_voice_1701081_54 = "Pagi.",
  str_voice_1701081_55 = "Ini tengah hari.",
  str_voice_1701081_56 = "Selamat malam. Kau…",
  str_voice_1701081_57 = "Hari ini spesial, di masa lalu atau di masa sekarang.",
  str_voice_1701071_1 = "Hah? Butuh keahlianku untuk memimpin pertempuran berikutnya?",
  str_voice_1701071_2 = "Ada masalah apa? Bekerja lagi setelah latihan itu selalu baik untukmu.",
  str_voice_1701071_3 = "Aku tampak jahat? Mungkin aku tidak hanya kehilangan ingatan.",
  str_voice_1701071_4 = "Aku tidak keberatan mengamuk kalau bisa membunuh semua Eclipsite.",
  str_voice_1701071_5 = "Bukan pembawa sial, ini bukan peti sungguhan… Yah, mungkin bukan… Aku lupa.",
  str_voice_1701071_6 = "Jangan memandangiku terus. Lakukan sesuatu.",
  str_voice_1701071_7 = "Ada beberapa hal yang memang luput dari ingatanku, tapi itu tidak mengurangi kemampuanku dalam membasmi Eclipsite dengan efektif.",
  str_voice_1701071_8 = "Aku tiba-tiba ingat bertani di ladang gandum… Itu aku?",
  str_voice_1701071_9 = "Bagus kau bisa menggunakan perisai. Namun, soal pedang, belum.",
  str_voice_1701071_10 = "Karena kita tidak punya hal lain untuk dilakukan, aku akan menyanyikan lagu favoritku dari markas. Semua orang biasanya jadi bersemangat saat aku mulai bernyanyi.",
  str_voice_1701071_11 = "Mengerti. Aku akan segera datang.",
  str_voice_1701071_12 = "Menunggu perintah.",
  str_voice_1701071_13 = "Aku tampak lesu? Itu karena aku belum bertemu dengan satu pun Eclipsite.",
  str_voice_1701071_14 = "Semoga besok juga hari yang baik bersama Northwind yang menderu.",
  str_voice_1701071_15 = "Sudah lama sejak terakhir aku merayakan ulang tahun, tapi terimalah ucapan \"Selamat Ulang Tahun!\" yang tulus dariku.",
  str_voice_1701071_16 = "Tugasku sekarang adalah menjaga Colossus ini dan menghancurkan semua musuh kita, tentu selama mereka adalah Eclipsite.",
  str_voice_1701071_17 = "Pagi. Kumpulkan semua orang di Soroz untuk berlari 50 putaran… Tidak mau? Aku bisa melihat mereka dalam masalah.",
  str_voice_1701071_18 = "Waktunya sedikit bersantai, tapi jangan bergadang.",
  str_voice_1701071_19 = "Bukannya kau seharusnya tidur? Aku akan berjaga setelah ini.",
  str_voice_1701071_20 = "Aku hanya ingat bertugas bersama sesama prajurit… Maaf, aku tidak ingat yang lain.",
  str_voice_1701071_21 = "Negeri ini memiliki banyak kekuatan yang berkembang… Namun, menurutku, mereka malah makin kacau.",
  str_voice_1701071_22 = "Aku Guardian of the North.",
  str_voice_1701071_23 = "Ini musuh terbesar kita, dan semoga satu-satunya musuh bagi semua Aurorian.",
  str_voice_1701071_24 = "Friegson itu… Lupakan, aku tidak suka menilai orang lain.",
  str_voice_1701071_25 = [[
Kau mau tahu tentang Freya? Dia adalah pelatih yang hebat.
Cerdas dan sangat populer di antara para pasukan. Hanya itu yang kutahu.]],
  str_voice_1701071_26 = "Hal yang aku suka… Mungkin ada beberapa.",
  str_voice_1701071_27 = "Aku benci Eclipsite yang besar karena mereka sulit kubuat terpental jauh.",
  str_voice_1701071_28 = "Kalau ada Colossus waktu itu, banyak nyawa akan terselamatkan.",
  str_voice_1701071_29 = "Halo, salam dari Regal dari Silent Hunters. Aku selalu siap bertempur.",
  str_voice_1701071_30 = "Musim dingin yang beku bisa mengalahkan kegelapan sekali pun.",
  str_voice_1701071_34 = "Bagus. Bersiaplah untuk berburu.",
  str_voice_1701071_35 = "Ohhhh!",
  str_voice_1701071_36 = "Habisi! Habisi!",
  str_voice_1701071_37 = "Akan kubunuh kau!",
  str_voice_1701071_38 = "Tidak mungkin!",
  str_voice_1701071_39 = "Waktunya tewas!",
  str_voice_1701071_40 = "Terlalu lambat!",
  str_voice_1701071_41 = "Aku memimpin? Kau punya nyali…",
  str_voice_1701071_42 = "Huh, huh… Kita menang… Jangan khawatir…",
  str_voice_1701071_43 = "Tidak mungkin… Akan kubunuh kau… Aku harus membunuhmu!",
  str_voice_1701071_44 = "Kau ingin melihatku berdiri dengan tangan lalu melakukan push-up dengan satu jari?",
  str_voice_1701071_45 = "… Terima kasih.",
  str_voice_1701071_46 = "Terima kasih banyak.",
  str_voice_1701071_47 = "Ini pasti berguna.",
  str_voice_1701071_48 = "Terima kasih. Walau mungkin kau tidak bisa melihatnya, aku merasa senang.",
  str_voice_1701071_49 = "Kurasa aku adalah petani yang menjadi prajurit. Samar-samar aku ingat teman-temanku, tapi saat berusaha fokus, ingatanku malah makin berantakan.",
  str_voice_1701071_50 = "Aku memiliki ingatan yang kabur tentang kapan aku mendaftar masuk pasukan, menjadi petugas, dan menghadap raja… Lalu Eclipsite menyerang dan Claymore mengundangku untuk bergabung dengan Silent Hunters…",
  str_voice_1701071_51 = "Kami menyelamatkan kerajaan dari krisis, tapi kemudian malah ditolak masyarakat yang ketakutan. Lalu… Lalu… Kupikir aku lupa sesuatu yang sangat penting, sesuatu yang sangat berarti bagiku…",
  str_voice_1701071_52 = "Alchemy Stars.",
  str_voice_1701071_53 = "Halo? Halo?",
  str_voice_1701071_54 = "Pagi. Haruskah aku membunyikan bel agar semua bangun?",
  str_voice_1701071_55 = "Mulailah latihan sore kalau kau sudah selesai makan.",
  str_voice_1701071_56 = "Waktunya istirahat. Cepat matikan lampu.",
  str_voice_1701071_57 = "Selamat Tahun Baru. Apa ada orang yang bilang pedangku terlihat sedikit berbahaya…?",
  str_voice_1701091_1 = "Dahulu kala, di tengah hutan yang penuh pohon aras dan cypress, berdiri kota bernuansa putih yang terbuat dari batu. Di sana, hiduplah seorang putri yang terbalut pakaian dari kulit rusa.",
  str_voice_1701091_2 = "Dahulu kala, hidup lima pahlawan. Mereka datang ke ladang salju yang sangat dingin dan mengalahkan Eclipsite yang jahat, tetapi sang Raja… Ah, bagian ini selalu membuat Frostfire marah.",
  str_voice_1701091_3 = "Dahulu kala, turunlah malam yang gelap di kerajaan, saat lima orang pergi menuju tempat nan jauh, membeli bulan, dan mengembalikan bintang-bintang…",
  str_voice_1701091_4 = "Kau lihat teman-temanku? Satu telah dihabisi, satu dikurung, satu hilang, dan satu membawa pedang… Mereka tertinggal di sana…",
  str_voice_1701091_5 = "Kita hanya salah satu dari banyak bintang yang cahayanya menyinari orang-orang. Namun, bintang yang redup hanya bisa menerima ejekan dari mereka sendirian.",
  str_voice_1701091_6 = "Mengapa aku selalu menceritakan kisah dari dahulu kala? Kalau kau mau tahu, aku adalah orang yang hidup di masa lalu.",
  str_voice_1701091_7 = "Si pengunjung pergi ke kota batu itu. Meski sang putri berbaju kulit rusa itu mengakui bahwa rusa tersebut sangat penting, dia tidak lagi peduli.",
  str_voice_1701091_8 = "Dahulu… Pastikan aku tidak bisa pergi denganmu. Aku harus bersama bintang-bintang yang redup… Tidak, ini bukan \"pergi\" dalam arti fisik, tetapi secara emosional.",
  str_voice_1701091_9 = "Karena kau masih muda dan masih hidup saat kami sudah tiada, kaulah yang harus menceritakan kisah-kisah ini mulai sekarang… Tunggu, itu belum pasti.",
  str_voice_1701091_10 = "Oh hutan, hutanku, semoga kau mendengar masalahku… Itu lagu anak dari zaman dulu, tapi aku lupa cara menyanyikannya, jadi hanya bisa mengucapkan liriknya.",
  str_voice_1701091_11 = "Lanjutkan cerita? Oke, langsung ke beberapa tahun kemudian, saat bintang sudah redup.",
  str_voice_1701091_12 = "Kalau menjadi meteor dan jatuh, bintang dapat menghancurkan negeri yang sudah berjuang keras untuk mewujudkan kedamaian.",
  str_voice_1701091_13 = "Kelimanya sampai di sebuah persimpangan. Seseorang berkata, \"Di sinilah kita harus berpisah.\"",
  str_voice_1701091_14 = "Hari itu, aku memilih menerima serangan Claymore dan keputusannya untuk mengakhiri semua ikatan.",
  str_voice_1701091_15 = "Aku tidak punya benda spesial untukmu, kecuali sebuah hiasan kepala yang berkarat.",
  str_voice_1701091_16 = "Kurasa hanya kau dan makhluk murni lain yang mau mendekatiku.",
  str_voice_1701091_17 = "Berapa lama aku tidur? Menyambut pagi dengan cara seperti ini… benar-benar sesuatu yang harus disyukuri.",
  str_voice_1701091_18 = "Di antara akar-akar yang berpilin, jiwa tanpa hati terbangun… Kau tidak menyesal membangunkanku?",
  str_voice_1701091_19 = "Di waktu malam, di sepanjang jalan kematian yang dingin dan temaram… Inilah satu-satunya tempat kita bisa bertemu.",
  str_voice_1701091_20 = "Dahulu kala, sang raja menulis sebuah surat yang berisi perintah, \"Singkirkan dan kuburkan mereka segera.\"",
  str_voice_1701091_21 = "Negeri yang dulu gelap tidak lagi membutuhkan cahaya bintang untuk meneranginya.",
  str_voice_1701091_22 = "Kami adalah pemburu yang sangat sabar.",
  str_voice_1701091_23 = "Kami harus waspada terhadap Eclipsite. Walau kami tidak membenci mereka, menghancurkan mereka tetap pilihan yang benar.",
  str_voice_1701091_24 = "Aku mengusulkan agar Frostfire pergi. Usul itu membuatnya marah sampai membakar pakaianku.",
  str_voice_1701091_25 = "Faktanya, Regal menyebabkan lebih banyak masalah daripada Frostfire.",
  str_voice_1701091_26 = "Ini tidak pernah menjadi pilihanku, tapi meneruskan kisah-kisah kuno ini sekarang adalah tugasku.",
  str_voice_1701091_27 = "Aku tidak punya kebencian, tapi rasa apati yang kumiliki memang terkadang memengaruhi penilaianku.",
  str_voice_1701091_28 = "Kalau kau meminta pendapatku… Kau harus hati-hati dan jangan membiarkannya menjadi senjata.",
  str_voice_1701091_29 = "Siapa kau? Ah, ini cerita baru. Dahulu kala, angin bertiup menembus hutan yang tercemar, membangunkan bintang-bintang yang padam.",
  str_voice_1701091_30 = "Masih bergantung pada ini?",
  str_voice_1701091_34 = "Waktunya berburu.",
  str_voice_1701091_35 = "Malam para pemburu.",
  str_voice_1701091_36 = "Cahaya bulan, terangi buruanku.",
  str_voice_1701091_37 = "Berburu untuk merayakan hidup.",
  str_voice_1701091_38 = "Menyelami malam untuk menyambut fajar.",
  str_voice_1701091_39 = "Masuk ke hutan.",
  str_voice_1701091_40 = "Masuk ke alam liar.",
  str_voice_1701091_41 = "Habisi sebanyak mungkin musuh.",
  str_voice_1701091_42 = "Aku hanya melakukan tugas.",
  str_voice_1701091_43 = "Sekali lagi, tidak boleh ada yang lolos.",
  str_voice_1701091_44 = "Sebuah kisah dari dahulu kala… Tidak, aku tidak terlalu suka bercerita, tapi aku harus menceritakannya kepadamu.",
  str_voice_1701091_45 = "Apa ini?",
  str_voice_1701091_46 = "Mengagumkan, klasik, tetapi baru.",
  str_voice_1701091_47 = "Mungkin aku bisa ingat betapa \"niat baik\" sangat berharga.",
  str_voice_1701091_48 = "Kurasa aku harus tersenyum.",
  str_voice_1701091_49 = "Dahulu kala, kelima Bintang lenyap tanpa keriuhan, seperti kisah yang ditulis tentang kelahiran mereka… Namun, pertanyaannya tetap, \"Apa kalian cuma berempat?\"",
  str_voice_1701091_50 = "Untuk mengisi kekosongan itu, Frostfire selalu marah, Regal terus diam, Requiem tidak pernah tersenyum, Claymore menolak usulku, tapi masih mengambil pedang…",
  str_voice_1701091_51 = "Akhirnya, kerangka rusa pendongeng itu memandang ke arah si pengunjung di bawah cahaya bulan… Dia tahu, kau akan memahami semua hal tentang lima Bintang itu, dan berterima kasih.",
  str_voice_1701091_52 = "Alchemy Stars…?",
  str_voice_1701091_53 = "Dahulu kala...",
  str_voice_1701091_54 = "Ah… Selamat pagi.",
  str_voice_1701091_55 = "Sore adalah waktu yang baik.",
  str_voice_1701091_56 = "Aku bisa melihat cahaya bulan.",
  str_voice_1701091_57 = "Aku rindu hari ketika dunia membuka awal baru.",
  str_voice_1701101_1 = "Walau begitu, aku prajurit dengan banyak tanda jasa yang akan mengikuti perintahmu untuk bertempur. Bagaimanapun, jangan sampai kita terhanyut di sini!",
  str_voice_1701101_2 = "Meski sering disebut orang suci, aku tidak menerima pengakuan dan penebusan dosa. Kau harus menemui orang lain untuk itu.",
  str_voice_1701101_3 = "Hah? Di mana kau, Navigator? Oh, di sana rupanya! Kau memang pandai berbaur dengan sekitar, seperti wallflower!",
  str_voice_1701101_4 = "Kenapa Requiem? Karena aku bisa melihat arwah, seperti yang di belakangmu sekarang… Bercanda, ha-ha!",
  str_voice_1701101_5 = "Mondar-mandir di sekitarku tanpa peringatan… Kau bisa-bisa tertusuk, Navigator…",
  str_voice_1701101_6 = "Cari kesibukan sendiri sana. Jangan terus-terusan mengawasiku. Aku tidak akan ke mana-mana.",
  str_voice_1701101_7 = "Bagaimana kalau latih tanding denganku jika kau tidak punya kegiatan? Jangan melihatku seperti itu. Aku pernah membunuh seekor serigala dengan sekali tinju… Untuk menghabisimu, aku bahkan tidak akan perlu satu tinju pun, Navigator malang.",
  str_voice_1701101_8 = "Bagaimanapun caramu menghitungnya, aku belum 19 tahun… Atau kau hanya ingin sekali tahu apa yang terjadi pada orang yang mencurigaiku seperti ini?",
  str_voice_1701101_9 = "Kalau dipikir-pikir lagi, kau baik hati… Bagaimana kalau kau kupanggil \"Sayangku\" sebagai tanda terima kasih? Mau? Aku hanya bercanda!",
  str_voice_1701101_10 = "La-da-da… Aku suka kehidupan santai seperti ini. Karena kau sedang tidak ada kegiatan lain, bagaimana kalau aku menghabiskan waktu denganmu sebagai tanda kebaikan hatiku?",
  str_voice_1701101_11 = "Oke, oke! Serahkan kepada Silent Saint yang hebat dan Freya yang terkuat, \"Requiem\" dari Silent Hunters, untuk membantu Navigator yang tak berguna itu! Apa, kau akan memaksaku bekerja? Serius?",
  str_voice_1701101_12 = "Kostum minim? Yah, karena mantraku bisa memanggang Eclipsite menjadi keripik dari jauh, aku tidak perlu dipersenjatai lengkap seperti Adras!",
  str_voice_1701101_13 = "Kau mau aku memanggilmu seperti seekor kucing? Kau gila? Sekarang aku sangat khawatir dengan kesehatan mentalmu.",
  str_voice_1701101_14 = "Kalau saja aku menusuk Navigator ini karena baru saja menyentuhku, mungkin mereka akan mulai memanggilku \"Saint yang Tak Tersentuh\"… Menarik, 'kan?",
  str_voice_1701101_15 = "Selamat Ulang Tahun! Kemarilah biar aku bisa lihat sudah sebesar apa kau! Aduh, terlalu dekat! Apa-apaan kau ini? Kenapa berdiri dekat sekali denganku? Dasar orang aneh!",
  str_voice_1701101_16 = "Ada rencana untuk hari ini? Tidak ada? Sulit dipercaya… Mau saran dariku?",
  str_voice_1701101_17 = "Pagi! Kukira kau akan terus tidur sampai sore. Omong-omong, selamat pagi!",
  str_voice_1701101_18 = [[
Aku sudah memutuskan untuk menyusun jadwal bagi Navigator! Apa?
Sudah terlalu terlambat! Sial, baru saja aku mau membantu!]],
  str_voice_1701101_19 = "Oke, aku pergi sekarang. Giliranmu bertugas sekarang, Navigator… Apa? Tidak mau? Bagaimana kau bisa berkata begitu!",
  str_voice_1701101_20 = "Yang lalu biarlah berlalu! Aku banyak sekali tidur sampai masa lalu terasa sangat jauh… Namun, cukup menyenangkan menganggur di sini sambil mencari target kita berikutnya.",
  str_voice_1701101_21 = "Illumina dan Lumopolis sepertinya penuh orang bodoh… Sedangkan Northland… Pastikan kau mengajakku lain kali!",
  str_voice_1701101_22 = "Kita adalah pendamai perbatasan!",
  str_voice_1701101_23 = [[
Aku benci, sangat benci mereka.
Walau tidak terlalu peduli dengan kebajikan, aku masih ingin memukul wajah jelek mereka.]],
  str_voice_1701101_24 = "Hubungan antara Friegson dan Cynthia dulunya rumit! Kudengar Friegson pernah menyerangnya satu kali, tapi sekarang hubungan mereka sudah jauh lebih baik!",
  str_voice_1701101_25 = "Adras sangat kuat, baik itu dalam hal kemampuan bertarung maupun sihir! Tunggu, Navigator, kau iri? Kau imut juga saat begini…",
  str_voice_1701101_26 = "Kenapa aku tidak suka cokelat dan permen?! Semua orang juga menyukainya… Diam kau, jangan katakan apa pun!",
  str_voice_1701101_27 = "Aku benci Eclipsite dan kau. Ups, jangan menangis! Maafkan aku… Kalau kau mau tahu, aku memang lebih suka kau!",
  str_voice_1701101_28 = "Tidak ada pikiran kecuali hidup nyaman, maaf.",
  str_voice_1701101_29 = [[
Senang bertemu denganmu. Aku Requiem dari Silent Hunters. 
Omong-omong, serahkan semua pertarungan kepadaku 
dan jangan sampai dirimu yang kikuk itu menghalangiku.]],
  str_voice_1701101_30 = "Wow! Nah, begitu!",
  str_voice_1701101_34 = "Baiklah… Menyingkirlah dan akan kutunjukkan kepadamu!",
  str_voice_1701101_35 = "Habisi semua!",
  str_voice_1701101_36 = "Raungan petir.",
  str_voice_1701101_37 = "Dari debu menjadi debu!",
  str_voice_1701101_38 = "Matilah, bodoh!",
  str_voice_1701101_39 = "Maju terus!",
  str_voice_1701101_40 = "Ini belum berakhir!",
  str_voice_1701101_41 = "Aku berjanji untuk memenuhi harapanmu.",
  str_voice_1701101_42 = "Tentu saja. Cukup hargai aku dengan sepenuh hatimu.",
  str_voice_1701101_43 = "*Hiks* Bagaimana ini bisa terjadi? Maaf…",
  str_voice_1701101_44 = "Hah? Apa kau datang khusus untuk berterima kasih kepadaku?",
  str_voice_1701101_45 = "Hmm, bukan ide yang buruk.",
  str_voice_1701101_46 = "Ini mengejutkan. Akan kuterima!",
  str_voice_1701101_47 = "Terima kasih… Berhentilah melihatku!",
  str_voice_1701101_48 = "Oh, ini… eh, terima kasih! Aku sangat suka ini. Kau baik sekali!",
  str_voice_1701101_49 = "Coba kupikir. Aku cukup yakin… Aku terlahir di keluarga yang sempurna, jadi wajar aku tanpa cela seperti ini, 'kan?",
  str_voice_1701101_50 = "Pekerjaan sebagai pendeta militer atau petugas latihan sama-sama membosankan, harus memarahi orang yang lebih tua dariku tentang penyesalan dan kepatuhan sepanjang hari! Aku berharap orang dewasa bisa mengatur perilaku mereka sendiri!",
  str_voice_1701101_51 = "Yah, aku tidak tahu apa yang terjadi padaku. Seperti inilah aku setelah mengikuti nasihat Claymore. Masih lumayan, 'kan?",
  str_voice_1701101_52 = "Ya, Alchemy Stars!",
  str_voice_1701101_53 = "Hoi, Navigator!",
  str_voice_1701101_54 = "Hoi, kau bangun?",
  str_voice_1701101_55 = "Bangunlah, berhenti tidur!",
  str_voice_1701101_56 = "Oh, mengantuk sekali…",
  str_voice_1701101_57 = "Ini Tahun Baru! Kita libur!",
  str_voice_1601111_1 = "Jangan melihat mataku. Ini bukan penampilan yang enak dilihat…",
  str_voice_1601111_2 = "Nah, kau memang punya kemampuan itu… Mungkin kau bisa memahami rasa sakitku. Kalau iya, sepertinya itu bagus.",
  str_voice_1601111_3 = "Rupanya kau punya suatu kemampuan istimewa. Apa menurutmu kau bisa menghapus ingatanku?",
  str_voice_1601111_4 = "Jangan takut dengan kristalku. Aku tidak akan membiarkan mereka menyakitimu.",
  str_voice_1601111_5 = "Kristal yang seperti bunga ini… Dia adalah Sanguine Crystal pertama yang tumbuh di kulitku…",
  str_voice_1601111_6 = "Jangan menyentuh kristalku dalam pertempuran, atau mereka akan menjebakmu!",
  str_voice_1601111_7 = "Keyakinan? Apa pun yang kau yakini, keselamatan hanya impian…",
  str_voice_1601111_8 = "Kau mau tahu tentang masa laluku? Bahkan kalau kau tahu, apa itu akan mengubah sesuatu? Atau, apa menurutmu… kau bisa menyelamatkanku?",
  str_voice_1601111_9 = "Bisakah aku menemukan kebahagiaan seperti orang normal? Mungkin aku sudah menemukannya di sini…",
  str_voice_1601111_10 = "Awannya begitu indah… Senang rasanya sesekali tidak perlu memikirkan atau mengkhawatirkan apa pun.",
  str_voice_1601111_11 = "Kenapa kau mau aku berdiri di sini? Ah, aku menurut sajalah…",
  str_voice_1601111_12 = "Orang gagal memahami satu sama lain karena kesenangan dan kesedihan mereka sangat berbeda.",
  str_voice_1601111_13 = "Tidak… Jangan bertanya tentang keluargaku. Aku tidak punya keluarga…",
  str_voice_1601111_14 = "Kalau tidak membutuhkannya untuk bertarung, aku pasti sudah menghilangkannya dari tubuhku, entah sebahaya apa pun itu…",
  str_voice_1601111_15 = "Oh… Selamat ulang tahun.",
  str_voice_1601111_16 = "Penasaran akan seperti apa hari ini untuk kita. Karena ada kau, aku yakin pasti tidak membosankan.",
  str_voice_1601111_17 = "Matahari sangat terang… Ya, 'kan?",
  str_voice_1601111_18 = "Sudah malam? Wah…",
  str_voice_1601111_19 = "Satu hari lagi yang datang dan pergi begitu saja…",
  str_voice_1601111_20 = "Bisakah ajaran True Order menyelamatkanku? Hanya waktu yang tahu…",
  str_voice_1601111_21 = "Lumopolis telah melupakanku, dan aku tidak lagi merindukannya. Omong-omong, hanya bangsawan yang diterima di sana…",
  str_voice_1601111_22 = "Semoga Truth melindungimu…",
  str_voice_1601111_23 = "Orang-orang yang tidak beruntung di antara kita… Mereka terikat oleh rantai mereka sendiri, 'kan?",
  str_voice_1601111_24 = "Faust terkadang menakutkan, tapi tanpanya, aku pasti sudah menjadi kristal raksasa…",
  str_voice_1601111_25 = "Aku bisa merasakan rasa sakit Eicy, tapi jiwanya begitu penuh semangat sampai aku iri kepadanya…",
  str_voice_1601111_26 = "White Suitcase milik Faust ini mengagumkan, menyembuhkan sakitku. Sungguh hadiah dari surga…",
  str_voice_1601111_27 = "Walau bisa melindungiku, ia juga bisa melahapku… Kalau mungkin, aku sebaiknya menjauh darinya.",
  str_voice_1601111_28 = "Colossus? Memang layak menyandang nama itu. Namun, yang lebih penting buatku adalah Navigator yang mengendalikannya…",
  str_voice_1601111_29 = "Aku Beryl. Jangan takut dengan Sanguine Crystal milikku. Ia tidak akan melukaimu…",
  str_voice_1601111_30 = "Camellia bahkan lebih cantik.",
  str_voice_1601111_31 = "Ia menyebar.",
  str_voice_1601111_32 = "Sanguine Crystal sedang mekar sempurna…",
  str_voice_1601111_33 = "Mungkin… Aku bisa menghilangkannya?",
  str_voice_1601111_34 = "Kau mau menemaniku?",
  str_voice_1601111_35 = "Kristal-kristal itu berkumpul.",
  str_voice_1601111_36 = "Mereka datang.",
  str_voice_1601111_37 = "Field!",
  str_voice_1601111_38 = "Sanguine Crystal!",
  str_voice_1601111_39 = "Crystallus Camellias!",
  str_voice_1601111_40 = "Mekarlah!",
  str_voice_1601111_41 = "Ayo pergi bersama.",
  str_voice_1601111_42 = "Kita menang? Bagus…",
  str_voice_1601111_43 = "Hmmm… Kekalahan tetaplah kekalahan…",
  str_voice_1601111_44 = "Terima kasih atas kepedulianmu… Aku sudah merasa lebih baik sekarang.",
  str_voice_1601111_45 = "Kenapa kau memberiku ini?",
  str_voice_1601111_46 = "Jadi, kau sudah tahu aku mengincarnya…",
  str_voice_1601111_47 = "Terima kasih…",
  str_voice_1601111_48 = "Aku tidak mengira kau mengenalku begitu baik…",
  str_voice_1601111_49 = "Aku dulu bangsawan Lumopolis, tapi sekarang aku tidak pernah bisa kembali.",
  str_voice_1601111_50 = "Sebuah keluarga gila menculikku dan menanam Sanguine Crystal ini ke badanku… Aku tidak terlahir dengannya.",
  str_voice_1601111_51 = "Kalau bisa memutar balik waktu, aku lebih memilih dibunuh oleh Sanguine Crystal daripada membuat kerabatku menderita…",
  str_voice_1601111_52 = "Alchemy… Stars.",
  str_voice_1601111_53 = "Apa kau di sana?",
  str_voice_1601111_54 = "Selamat pagi.",
  str_voice_1601111_55 = "Ini tengah hari.",
  str_voice_1601111_56 = "Sepertinya sudah sedikit terlambat hari ini.",
  str_voice_1601111_57 = "Semoga aku bisa menemukan orang yang bisa memahamiku di tahun yang baru.",
  str_voice_1601111_58 = "Hmm… Kau tahu…",
  str_voice_1601111_59 = "Seperti biasa… aku berterima kasih kepadamu…",
  str_voice_1501131_1 = "Ada banyak musisi di Lumopolis, dan mereka jago memainkan segala jenis musik. Itu tidak berarti mereka paham musik, 'kan?",
  str_voice_1501131_2 = "Suara dari atas adalah yang paling surgawi, 'kan? Namun hanya aku yang bisa memainkannya. Aku harus membagikannya kepada dunia.",
  str_voice_1501131_3 = "Piano di jembatan itu sama sekali tidak jelek… Apa kau memainkan piano di Colossus selama tujuh belas tahun itu? Kudengar kau memainkan duet dengan Vice. Sepertinya kau punya selera musik yang bagus, ya?",
  str_voice_1501131_4 = "Para pelayan yang kusebut \"Holy Avatar\" diberikan kepadaku. Aku bisa meminta mereka memainkan musik untukmu sepanjang malam…",
  str_voice_1501131_5 = "Kudengar kemampuan psikis Caelestite begitu kuat. Jadi, kau bisa merasakan fluktuasi musikku, ya?",
  str_voice_1501131_6 = "Aku mendengar suara surgawi lagi—lebih indah dari musik apa pun di dunia. Suara itu akan memanduku untuk menemukan gerakan pemungkas, 'kan?",
  str_voice_1501131_7 = "Penglihatanku baik-baik saja. Aku memakai kacamata ini agar lebih merasa seperti konduktor!",
  str_voice_1501131_8 = "Kemampuan psikismu kuat… Mungkin kau juga bisa jadi konduktor yang hebat.",
  str_voice_1501131_9 = "Lihat pita di tanganku? Simpul kecil yang bagus, 'kan? Kau mau kuajari cara mengikat simpul cantik seperti ini? Aku pandai sekali melakukannya.",
  str_voice_1501131_10 = "Hmm… Kau tidak suka lagu ini? Apa kau ingin dengar \"Home\", \"Return\", atau mungkin \"Voyage\"?",
  str_voice_1501131_11 = "Nah, sepertinya ini waktu yang baik bagi Holy Avatar milikku untuk naik ke atas pentas, 'kan? Di sini terlalu sepi… Aku akan meminta mereka memainkan lagu untuk memeriahkan suasana.",
  str_voice_1501131_12 = "Ruangan di sini luar biasa. Lapang dan terang. Yang paling penting, akustiknya sangat bagus. Sempurna untuk melatih komposisiku, 'kan?",
  str_voice_1501131_13 = "Pita di tanganku? Seharusnya menempel ke tongkatku. Belitkan saja di tanganku, seperti ini.",
  str_voice_1501131_14 = "Performa tergantung pada bakat, dan konduktor tidak hanya harus paham teori musik, tapi juga memiliki kemampuan untuk mengoordinasi para musisinya. Inilah kenapa konduktor sangat langka.",
  str_voice_1501131_15 = "Ah! Aku lupa menyiapkan hadiah untukmu! Biarkan Holy Avatar milikku membawakan sebuah lagu ulang tahun untukmu!",
  str_voice_1501131_16 = "Satu lagi hari yang ceria… Holy Avatar milikku akan memainkan lagu untukmu!",
  str_voice_1501131_17 = "Apa kau bangun awal untuk menikmati cahaya matahari pagi, atau mungkin mendengarkan lagu alam yang menenangkan?",
  str_voice_1501131_18 = "Kau pasti lelah setelah bekerja keras sepanjang hari. Kau perlu beristirahat… Bagaimana kalau kau pergi ke jembatan dan bermain piano? Bersantailah, Navigator!",
  str_voice_1501131_19 = "Inspirasi datang kepadaku di tengah malam, tapi biasanya aku mulai menulis komposisi di malam hari.",
  str_voice_1501131_20 = "True Order jauh lebih baik daripada Lumopolis. Setidaknya mereka mengakui bahwa musik hadir dalam banyak wujud, 'kan?",
  str_voice_1501131_21 = "Lumopolis punya keanggunan dan tradisi, tapi tidak tahu apa-apa tentang musik…",
  str_voice_1501131_22 = "Semoga Truth memberkati kalian semua, dan semoga musik memberkati kalian juga.",
  str_voice_1501131_23 = "Kasihan… Kalau tidak tahu cara mengapresiasi musik, mereka benar-benar tidak punya harapan…",
  str_voice_1501131_24 = "Victoria tahu banyak tentang banyak hal, 'kan? Itulah alasanku memutuskan untuk mengikutinya dalam mencari gerakan pemungkas.",
  str_voice_1501131_25 = "Kalau Sikare bisa membebaskan diri dari peraturan yang kaku semacam itu, masa depannya akan terbentang tanpa batas.",
  str_voice_1501131_26 = "Pasti ada musik di daratan ini yang bisa merepresentasikan suara surgawi yang sejati. Aku tahu aku akan menemukannya suatu hari…",
  str_voice_1501131_27 = "Bukankah peraturan dan regulasi hanya bisa memberikan hasil medioker, seperti orang-orang Lumopolis yang disebut musisi itu?",
  str_voice_1501131_28 = "Kudengar benda ini dikendalikan lewat piano… Sepertinya musik memang memiliki kekuatan besar, ya?",
  str_voice_1501131_29 = "Aku akan memandumu! Mari kita bersenang-senang dalam alunan musik yang agung bersama-sama!",
  str_voice_1501131_30 = "Gerakan ini makin surgawi.",
  str_voice_1501131_31 = "Dengar! Ini suara surgawi!",
  str_voice_1501131_32 = "Komet, ikuti kata-kataku!",
  str_voice_1501131_33 = "Perhatian! Akulah Divine Conductor!",
  str_voice_1501131_34 = "Suara surgawi akan memandu kita.",
  str_voice_1501131_35 = "Gerakan… selesai.",
  str_voice_1501131_36 = "Holy Avatar! Bersiaplah untuk pertunjukan!",
  str_voice_1501131_37 = "Divine Conductor!",
  str_voice_1501131_38 = "Kekuatan surgawi, teruslah bermain!",
  str_voice_1501131_39 = "Rasakan gaung yang tak terbatas!",
  str_voice_1501131_40 = "Biarkan kekuatan surgawi ini menuntunmu!",
  str_voice_1501131_41 = "Semuanya, ikuti arahanku.",
  str_voice_1501131_42 = "Satu lagi pertunjukan yang sempurna!",
  str_voice_1501131_43 = "Holy Avatar akan melindungi kita saat mundur…",
  str_voice_1501131_44 = "Kau mau melihat caraku bekerja sebagai konduktor?",
  str_voice_1501131_45 = "Ah, terima kasih.",
  str_voice_1501131_46 = "Wow, aku suka sekali!",
  str_voice_1501131_47 = "Kau memberiku satu hadiah lagi!",
  str_voice_1501131_48 = "Izinkan aku menulis sebuah karya musik untukmu!",
  str_voice_1501131_49 = "Ada sebuah gerakan pemungkas di dunia ini. Itu merepresentasikan suara surga, dan aku tidak akan berhenti sebelum menemukannya.",
  str_voice_1501131_50 = "Pada hari itu, suara surgawi bergema di seluruh tubuhku, dan sebuah meteorit jatuh dari langit. Untuk sejenak, gerakan pemungkas berkedip di hatiku, dan aku memulai perjalanan untuk mencarinya.",
  str_voice_1501131_51 = "Lumopolis tidak pernah tahu apa itu musik. Inilah alasan aku tidak dipilih untuk bergabung dengan mereka. Jadi, aku tinggal di kampung halamanku sampai menemukan jalan sendiri.",
  str_voice_1501131_52 = "Alchemy Stars.",
  str_voice_1501131_53 = "Kau punya waktu untuk berduet?",
  str_voice_1501131_54 = "Bagaimana kalau lagu untuk membangunkanmu dari tidur?",
  str_voice_1501131_55 = "Tidak boleh ada pertunjukan di tengah hari. Beristirahatlah!",
  str_voice_1501131_56 = "Selamat malam. Musikku akan mengantarmu tidur.",
  str_voice_1501131_57 = "Selamat Tahun Baru! Siap untuk pertunjukan perayaan?",
  str_voice_1601161_1 = "Ha? Kita sedikit macet di sini… Aku tahu! Akan kutuliskan ini!",
  str_voice_1601161_2 = "Aku ingin tahu prinsip di balik Firefly. Mereka luar biasa.",
  str_voice_1601161_3 = "Gadis revolver itu tahu cara mengurus bisnis. Bagaimanapun, dialah orang yang membawaku ke Rediesel Wrench.",
  str_voice_1601161_4 = "Ada banyak jenis obeng di dunia… Pastikan kau menggunakannya dengan benar!",
  str_voice_1601161_5 = "Kesulitan hidup itu seperti baut yang sulit dilepas. Terkadang, kau hanya butuh obeng yang benar untuk membukanya.",
  str_voice_1601161_6 = "Aku banyak belajar di sini. Berkat dukunganmu, aku sekarang bisa meningkatkan peralatan mecha milikku! Namun, pertama-tama, aku butuh banyak sekali tambahan logam…",
  str_voice_1601161_7 = "Aku ingat Illumina membuat kelas khusus laki-laki untukku. Kurasa mereka takut para gadis tidak bisa berkonsentrasi! Heh…",
  str_voice_1601161_8 = "Illumina mengatur agar aku bekerja di pabrik khusus laki-laki untuk beberapa waktu… Itu periode paling membosankan dalam hidupku!",
  str_voice_1601161_9 = "Tanduk dan ekorku selalu menarik perhatian… Namun, aku tidak tahu kenapa.",
  str_voice_1601161_10 = "Kenapa kau selalu melihatku? Oh… Kau pasti ingin melihat pekerjaanku! Silakan lihat kalau mau!",
  str_voice_1601161_11 = "Tidak apa-apa kalau aku tinggal sedikit lebih lama, 'kan? Aku akhirnya berkesempatan mempelajari struktur Colossus!",
  str_voice_1601161_12 = "Colossus yang sangat besar… Teknologi di dalamnya begitu canggih—bisa menjadi bahan referensi yang sangat bagus!",
  str_voice_1601161_13 = "Aku menerima surat aneh beberapa hari lalu… Hmm, aku tidak tahu apa yang harus kulakukan dengannya.",
  str_voice_1601161_14 = "Mau lihat kotak perkakasku? Aku menamainya Allen, dan isinya penuh alat yang menarik!",
  str_voice_1601161_15 = "Hah? Hari ini kau ulang tahun!? Kalau begitu, selamat ulang tahun!",
  str_voice_1601161_16 = "Ada terlalu banyak pekerjaan reparasi hari ini! Pemeliharaan harian Colossus, tumpukan permintaan Rediesel Wrench itu… Banyak sekali!",
  str_voice_1601161_17 = "Selamat pagi! Pekerjaan reparasiku tidak membuatmu terbangun, 'kan?",
  str_voice_1601161_18 = "Sudah malam? Pekerjaan hari ini hampir selesai, tinggal beberapa hal lagi yang perlu direparasi!",
  str_voice_1601161_19 = "Skema ini sulit sekali digambar… Sepertinya aku harus bergadang semalaman.",
  str_voice_1601161_20 = "Hidup dengan Rediesel Wrench begitu bebas! Bahkan kalau tidak cocok dengan seseorang, kau bisa langsung saja mengajaknya bertarung!",
  str_voice_1601161_21 = "Daerah Undercity Illumina tidak hanya membosankan dalam hal kondisi kerja, tetapi juga dalam cara hidup mereka yang kuno! Kapan mereka akan belajar beradaptasi?",
  str_voice_1601161_22 = "Lepidoz! Keren!",
  str_voice_1601161_23 = "Eclipsite terkutuk itu perlu direparasi otaknya!",
  str_voice_1601161_24 = "Teknik gadis berkacamata itu sungguh mengesankan. Sulit dibayangkan dia mempelajari semuanya secara autodidak.",
  str_voice_1601161_25 = "Mudah sekali mendekati gadis revolver itu! Dia selalu menembak secara spontan, dan tidak pernah malu saat bertemu denganku.",
  str_voice_1601161_26 = "Mesin tidak pernah bohong, dan mereka selalu efisien. Yang ada hanyalah berfungsi atau tidak berfungsi.",
  str_voice_1601161_27 = "Huft… Andai orang lebih gamblang. Aku lelah dengan semua petunjuk dan isyarat ini setiap hari.",
  str_voice_1601161_28 = "Ini jauh lebih bagus daripada Lepidoz… Namun, cukup sulit dikendalikan.",
  str_voice_1601161_29 = "Kau Navigator, 'kan? Senang bertemu denganmu! Aku bisa memperbaiki hampir semuanya, bahkan Colossus!",
  str_voice_1601161_30 = "Ah, benda ini punya banyak sekali komponen!",
  str_voice_1601161_31 = "Waktunya meningkatkan kotak perkakasku!",
  str_voice_1601161_32 = "Berhasil!",
  str_voice_1601161_33 = "Mecha Soul! Menyala!",
  str_voice_1601161_34 = "Sekarang giliranku?",
  str_voice_1601161_35 = "Perakitan selesai!",
  str_voice_1601161_36 = "Sekarang kau, kunci pas!",
  str_voice_1601161_37 = "Machine Overload!",
  str_voice_1601161_38 = "Yak!",
  str_voice_1601161_39 = "Siap dan serang, Allen!",
  str_voice_1601161_40 = "Serang titik kelemahannya!",
  str_voice_1601161_41 = "Bukan masalah!",
  str_voice_1601161_42 = "Kalian semua luar biasa!",
  str_voice_1601161_43 = "Argh… Kunci pas milikku patah…",
  str_voice_1601161_44 = "Butuh sesuatu? Bukan masalah, tapi aku sedang sibuk sekarang jadi kau harus menunggu.",
  str_voice_1601161_45 = "Terima kasih! Aku suka sekali! Haha!",
  str_voice_1601161_46 = "Aku tidak tahu cara berterima kasih kepadamu…",
  str_voice_1601161_47 = "Kau seperti selalu punya sesuatu untukku.",
  str_voice_1601161_48 = "Terima kasih banyak! Bagaimana aku bisa membalasmu?",
  str_voice_1601161_49 = "Lepidoz sering sekali macet… Kalau aku tidak memperbaikinya dua tahun lalu, dia pasti masih tertidur di kandangnya sekarang.",
  str_voice_1601161_50 = "Aku tidak disukai oleh para laki-laki di Illumina… Aneh sekali bagaimana mereka hampir seperti mengusirku.",
  str_voice_1601161_51 = "Kurasa aku mewarisi tanduk dan ekor dari nenek moyang yang jauh. Kakek buyutku juga seperti ini, dan dia pun tidak punya banyak teman laki-laki!",
  str_voice_1601161_52 = "Alchemy Stars.",
  str_voice_1601161_53 = "Hai, kau di sana?",
  str_voice_1601161_54 = "Bangun, bangun! Ada yang perlu diperbaiki hari ini?",
  str_voice_1601161_55 = "Eh! Makan siang apa?",
  str_voice_1601161_56 = "Ah, kepalaku berputar-putar! Ayo beristirahat!",
  str_voice_1601161_57 = "Resolusi Tahun Baru? Meningkatkan progres pemanufakturan mekanisku sebesar 10 poin!",
  str_voice_1501141_1 = "Apa kau mau mencoba memakai dasi kupu-kupu? Meski hanya aksesori kecil, dasi itu cocok dengan pakaianmu sekarang.",
  str_voice_1501141_2 = "Kau familier dengan pekerjaan pemburu hadiah? Hampir sama dengan tentara bayaran, tetapi dengan lebih banyak kebebasan. Kau hanya perlu menghabisi targetmu dan menerima bayaran!",
  str_voice_1501141_3 = "Firefly kecil yang terbang ke sana kemari ini imut sekali, aku ingin menggunakan mereka sebagai target latihan. Jangan khawatir! Aku tidak akan merusak mereka.",
  str_voice_1501141_4 = "Semua orang bilang aku begitu menarik, tapi sebenarnya, itu semua karena aku minum jus.",
  str_voice_1501141_5 = "Cambukku tidak hanya memerangkap target, tetapi juga bisa membakarnya! Aku menamainya \"Karenina\". Jangan sampai kau lupa!",
  str_voice_1501141_6 = "Lihat kuda ini? Namanya Anna. Kami sudah bersama sejak kecil. Bahkan kematian tidak bisa memisahkan kami.",
  str_voice_1501141_7 = "Anna, kuda yang anggun itu, telah merasakan kematian dan terlahir kembali. Kau bisa lihat buktinya dari tanda di dahinya.",
  str_voice_1501141_8 = "Lorong-lorong Colossus cukup luas. Aku merasa tertantang untuk berlari menjelajahinya!",
  str_voice_1501141_9 = "Mau minum denganku? Tentu saja, kau boleh menyuguhkan jus untukku… Namun, kalau tidak ada, minuman lain pun boleh.",
  str_voice_1501141_10 = "Kalau tidak ada urusan penting saat ini, mari membicarakan apa yang perlu kita selesaikan dan membuat rencana sederhana. Misalnya, bagaimana kita bisa meningkatkan kemampuanmu…",
  str_voice_1501141_11 = "Eh… Kau mau aku tinggal? Kalau tidak bisa berjalan-jalan semauku, aku pasti akan gelisah…",
  str_voice_1501141_12 = "Kudengar ada bar di Rediesel Desert yang menjual minuman dengan rasa unik. Mau minum denganku kalau ada waktu luang?",
  str_voice_1501141_13 = "Kau telah mengawasiku, 'kan? Jangan senang dulu… Aku punya banyak pengagum yang menjagaku.",
  str_voice_1501141_14 = "Orang selalu mengeluh tidak ada sayembara berhadiah di Umbraton… Hah! Itu karena sudah kuselesaikan semua!",
  str_voice_1501141_15 = "Selamat ulang tahun! Apa kau mau pesta ulang tahun? Jangan khawatir, aku yang atur semua!",
  str_voice_1501141_16 = "Hari yang menyenangkan! Bagaimana kalau kau ikut berkendara denganku? Kalau kau tidak tahu caranya, aku akan mengajarimu. Berkendara adalah syarat mendasar untuk semua bangsawan.",
  str_voice_1501141_17 = "Bangun pagi adalah kebiasaan yang baik. Itu bukti kedisiplinanmu, Navigator.",
  str_voice_1501141_18 = "Makan malam dan segelas jus… Bukan untukmu, tapi untukku, Navigator. Ini yang mereka sebut \"minuman pengantar tidur\"…",
  str_voice_1501141_19 = "Ah… Lelah sekali, aku perlu istirahat. Kau tidak mengantuk?",
  str_voice_1501141_20 = "Walau True Order tidak punya banyak anggota, kami punya kemampuan rahasia yang kuat, dan bahkan bisa menghidupkan kembali orang mati…",
  str_voice_1501141_21 = "Umbraton sungguh perpaduan dari baik dan buruk. Kalau tidak begitu, tidak akan ada tempat untuknya di sana…",
  str_voice_1501141_22 = "Semoga Truth memerangkap… Oh, bukan, memberkatimu.",
  str_voice_1501141_23 = "Eclipsite? Di mataku, mereka cuma sasaran berkaki.",
  str_voice_1501141_24 = "Victoria pasti berasal dari garis keluarga yang kuat. Kalau tidak, dia tidak akan bisa menguasai Luminatics sekuat itu…",
  str_voice_1501141_25 = "Walau dia tidak terlahir di keluarga yang terkemuka, Sikare adalah bangsawan sejati, terutama dengan rasa tanggung jawabnya.",
  str_voice_1501141_26 = "Jika ada hal di dunia ini yang aku bersedia tukar dengan status kebangsawananku, itu adalah segelas jus yang enak.",
  str_voice_1501141_27 = "Setiap kali seseorang ikut campur dengan urusanku, aku selalu ingin melilitkan cambukku ke lehernya dan sedikit mengencangkannya…",
  str_voice_1501141_28 = "Dengan ukuran begitu, dia jelas bisa terbang! Aku penasaran, bagaimana kalau dia diadu balap melawan Anna!",
  str_voice_1501141_29 = "Genevieve, pemburu hadiah terhebat, siap membantumu! Apa yang bisa kulakukan untukmu, Navigator? Selama harganya cocok, aku siap mendengarkan.",
  str_voice_1501141_30 = "Cambuk, mengendorlah sedikit, ya?",
  str_voice_1501141_31 = "Sesuai perkiraan, kekuatanku telah muncul satu kali lagi!",
  str_voice_1501141_32 = "Anna, ke medan tempur!",
  str_voice_1501141_33 = "Cambuk, bakar!",
  str_voice_1501141_34 = "Perangkap musuh!",
  str_voice_1501141_35 = "Api penaklukan! Siapkan dirimu!",
  str_voice_1501141_36 = "Siap beraksi!",
  str_voice_1501141_37 = "Bakar!",
  str_voice_1501141_38 = "Menyerahlah!",
  str_voice_1501141_39 = "Rasakan apiku!",
  str_voice_1501141_40 = "Binasa dalam api!",
  str_voice_1501141_41 = "Kau mengambil pilihan yang tepat.",
  str_voice_1501141_42 = "Aku tidak berharap kurang dari itu.",
  str_voice_1501141_43 = "Aku tidak bisa memerangkap mereka…",
  str_voice_1501141_44 = "Bolehkah aku mengikatmu? Jangan khawatir. Aku janji tidak akan menyakitimu.",
  str_voice_1501141_45 = "Oh, terima kasih.",
  str_voice_1501141_46 = "Terima kasih! Bagaimana kalau kita minum nanti?",
  str_voice_1501141_47 = "Terima kasih. Aku tidak akan melupakannya.",
  str_voice_1501141_48 = "Ah! Hatiku jatuh ke perangkapmu!",
  str_voice_1501141_49 = "Petyaburg adalah salah satu dari sedikit tempat yang belum hancur karena Darkover Crisis, dan aku beruntung berkesempatan mengonfirmasi ini.",
  str_voice_1501141_50 = "Kalau Victoria tidak membangkitkan Anna-ku tersayang, aku pasti tidak akan bergabung dengan True Order.",
  str_voice_1501141_51 = "Smokey pernah mempermalukanku dan melukai para penerus keluargaku. Sebab itu, aku harus melakukan apa pun yang aku bisa untuk menaklukkan dan sepenuhnya mengalahkannya!",
  str_voice_1501141_52 = "Alchemy Stars.",
  str_voice_1501141_53 = "Permisi.",
  str_voice_1501141_54 = "Selamat pagi.",
  str_voice_1501141_55 = "Selamat sore.",
  str_voice_1501141_56 = "Malam ini panjang.",
  str_voice_1501141_57 = "Di tahun baru ini, kita harus terus membuat rencana terbaik.",
  str_voice_1601121_1 = "Apa kau tidak pernah berganti pakaian? Atau, mungkin, kau punya 300 baju yang sama persis?",
  str_voice_1601121_2 = "Berhentilah mencecarku dengan pertanyaan tentang ini, itu, dan yang lain… Kau seperti anak kecil yang tidak paham apa pun!",
  str_voice_1601121_3 = "Beberapa orang bilang sepatuku terlalu berisik saat aku berjalan… Sayang sekali! Aku sangat menyukai sepatuku!",
  str_voice_1601121_4 = "Boleh aku melontarkan bola api ke Firefly-mu? Mereka 'kan bisa memperbaiki diri…",
  str_voice_1601121_5 = "Menjatuhkan bola api dari Colossus pasti sangat menyenangkan! Terutama saat kita mengejar Eclipsite!",
  str_voice_1601121_6 = "Lihat manticore berapi ini? Cantik, 'kan?",
  str_voice_1601121_7 = "Aku dulu bertempur melawan Eclipsite bersama para bangsawan Lumopolis. Haha, kau kaget, ya?",
  str_voice_1601121_8 = "Saat aku mendengkur, selalu terasa seperti terjadi kebakaran… Jangan lupa memperingatkan Firefly itu!",
  str_voice_1601121_9 = "Aku bagian dari keluarga Manticore. Belum pernah dengar tentang kami? Lupakan.",
  str_voice_1601121_10 = "Aku bosan… Ayo kita nyalakan api. Para Firefly bisa membersihkannya nanti.",
  str_voice_1601121_11 = "Kau mau aku berdiri di sini untuk dilihat orang-orang? Kalau ada yang lewat, boleh aku bakar?",
  str_voice_1601121_12 = "Kau seperti butuh penyemangat… Bagaimana kalau kucuci wajahmu dengan api? Tidak akan terlalu sakit, kok.",
  str_voice_1601121_13 = "Latihan? Tidak, terima kasih. Percayalah, kekuatan api berasal dari dalam.",
  str_voice_1601121_14 = "Aku melihat beberapa aksesori cantik baru-baru ini di Umbraton. Bagaimana kalau kita kembali ke sana dan memesannya?",
  str_voice_1601121_15 = "Akan kunyalakan lilin ulang tahunmu!",
  str_voice_1601121_16 = "Ada rencana bertempur hari ini?",
  str_voice_1601121_17 = "Matahari, membakar mataku! Kenapa tidak ada yang menutup gorden!?",
  str_voice_1601121_18 = "Satu hari penuh lewat dan aku tidak sempat melakukan apa pun! Aku bahkan tidak melihat Eclipsite, apalagi bertarung!",
  str_voice_1601121_19 = "Aku suka malam. Rasanya tenang… tetapi juga sedikit membosankan.",
  str_voice_1601121_20 = "Umbraton penuh kebisingan, dan sering terjadi pertarungan di sana. Namun, tempat itu juga memberikan rasa bebas karena setiap jalannya membuka kesempatan.",
  str_voice_1601121_21 = "Lumopolis adalah tempat yang hanya memberikan kebahagiaan kepada segelintir bangsawan yang ketinggalan zaman.",
  str_voice_1601121_22 = "Hiduplah untuk saat ini.",
  str_voice_1601121_23 = "Menyedihkan! Bahkan tidak cukup untuk pemanasan!",
  str_voice_1601121_24 = "Kalau tidak datang ke Umbraton, aku tidak akan bertemu dengan Tessa. Dia tenang sekali! Tidak ada yang bisa membuatnya terganggu!",
  str_voice_1601121_25 = "Konflik muncul ke mana pun kau pergi, jadi kau selalu butuh seseorang yang bisa menjaga kedamaian. Di Umbraton, orang itu Istvan.",
  str_voice_1601121_26 = "Berjalan di antara hidup dan mati lebih menantang daripada apa pun di dunia ini. Itulah alasanku suka bertarung!",
  str_voice_1601121_27 = "Aku lebih memilih mati daripada harus hidup yang terikat peraturan!",
  str_voice_1601121_28 = "Aku belum pernah melihat apa pun yang sebesar ini… Bagaimana rasanya terbang di atasnya…",
  str_voice_1601121_29 = "Aku Smokey. Kau pemilik Colossus ini? Di mana aku bisa menemukan keseruan di sini, dan yang lebih penting lagi, bolehkah aku membakarnya?",
  str_voice_1601121_30 = "Nyala api membubung tinggi.",
  str_voice_1601121_31 = "Ayo kita cari sesuatu yang lebih besar lagi untuk dibakar!",
  str_voice_1601121_32 = "Inilah kekuatanku yang sebenarnya!",
  str_voice_1601121_33 = "Ikuti aku, manticore!",
  str_voice_1601121_34 = "Bakar mereka sampai kering!",
  str_voice_1601121_35 = "Lihat ini!",
  str_voice_1601121_36 = "Ayo kita bakar sesuatu!",
  str_voice_1601121_37 = "Bakar, bakar, bakar!",
  str_voice_1601121_38 = "Api! Solusi untuk semua masalah hidup!",
  str_voice_1601121_39 = "Mau ke mana kau!?",
  str_voice_1601121_40 = "Selamat malam!",
  str_voice_1601121_41 = "Baiklah! Aku bisa melakukannya!",
  str_voice_1601121_42 = "Terlalu mudah!",
  str_voice_1601121_43 = "Oh… Aku meleset.",
  str_voice_1601121_44 = "Kau kira aku asal membakar semua hal sepanjang waktu? Baiklah, mungkin iya, tapi tidak di sini!",
  str_voice_1601121_45 = "Akan kuterima!",
  str_voice_1601121_46 = "Ini lumayan juga…",
  str_voice_1601121_47 = "Kau baik sekali!",
  str_voice_1601121_48 = "Ayolah! Kau menginginkan sesuatu, 'kan?",
  str_voice_1601121_49 = "Kalau tidak terlalu banyak mendengkur, mungkin aku tidak akan bertemu Istvan…",
  str_voice_1601121_50 = "Lihat bros ini? Konon ini terbuat dari tengkorak manticore. Keluargaku mewariskannya kepadaku…",
  str_voice_1601121_51 = "Nyala api yang membakar di dalam diriku perlahan membuatku tidak bisa merasakan sakit… Jadi, itulah alasan aku sangat membutuhkan stimulasi!",
  str_voice_1601121_52 = "Alchemy Stars.",
  str_voice_1601121_53 = "Halo?",
  str_voice_1601121_54 = "Pagi!",
  str_voice_1601121_55 = "Sudah tengah hari?",
  str_voice_1601121_56 = "Selamat malam!",
  str_voice_1601121_57 = "Cuma hari biasa saja. Maksudku, apa ada yang harus dirayakan?",
  str_voice_1601121_58 = "Hoi, Navigator! Mau main api? Aku janji aku tidak akan membakarmu.",
  str_voice_1601121_59 = "Kenapa kau selalu mengirimiku banyak barang? Aku tidak mengerti…",
  str_voice_1401271_1 = "Maaf, maaf, tunggu sejenak, sebentar saja…",
  str_voice_1401271_2 = "Aku tidak menangis, hanya saja aku bermimpi tentang orang tuaku tadi malam.",
  str_voice_1401271_3 = "Banyak orang di Rediesel Desert memunguti besi tua untuk mencari nafkah. Mengumpulkan sampah kalau mau lebih kasar. Aku dulu bagian dari mereka.",
  str_voice_1401271_4 = "Bukankah aku perlu menunjukkan lebih banyak keberanian? Banyak orang bilang aku tak punya nyali.",
  str_voice_1401271_5 = "Kata ayah, memo ini berasal dari Lumopolis. Mengandung Lumina. Mungkin karena itu aku bisa mengontrolnya.",
  str_voice_1401271_6 = "Scarlet Letter itu berjudul Resurrect. Itu jugalah keinginanku… menghidupkan kembali orang tuaku.",
  str_voice_1401271_7 = "Rasanya nyaman sekali di sini, seperti di rumah.",
  str_voice_1401271_8 = "Orang tuaku punya nama… Nesludov dan Macelona.",
  str_voice_1401271_9 = "Orang tuaku tidak mati. Arwah mereka masih bersamaku… di Scarlet Letter itu.",
  str_voice_1401271_10 = "Maaf! Aku tidak bersantai, cuma bosan… Karena itulah aku bermain kertas.",
  str_voice_1401271_11 = "Boleh aku di sini? Aku menghalangi? Tidak? Bagus…",
  str_voice_1401271_12 = "Apa ada sesuatu tentang arwah di Colossus?",
  str_voice_1401271_13 = "Apa ada buku yang akhirnya bahagia selamanya di sini?",
  str_voice_1401271_14 = "Aku membersihkan Colossus dengan kertas. Aku tidak mengganggu, 'kan?",
  str_voice_1401271_15 = "Sekarang kau ulang tahun? Bolehkah aku membuatkanmu kue kertas?",
  str_voice_1401271_16 = "Banyak pekerjaan hari ini? Kalau perlu bantuan, bilang saja.",
  str_voice_1401271_17 = "Selamat pagi, Navigator. Ada yang harus kaulakukan?",
  str_voice_1401271_18 = "Aku melihat langit malam di sini tidak apa-apa, 'kan?",
  str_voice_1401271_19 = "Oh, kau harus istirahat saat membutuhkannya, Navigator.",
  str_voice_1401271_20 = "Kudengar Lady Victoria bisa memenuhi keinginan banyak orang. Itulah alasanku bergabung dengan True Order.",
  str_voice_1401271_21 = "Gurun tempat tinggalku dulu adalah wilayah Rediesel Wrench, tapi aku tidak selalu bertemu dengan mereka.",
  str_voice_1401271_22 = "Semoga Truth memberkatimu.",
  str_voice_1401271_23 = "Aku harus mewarnai kertasku merah dengan darah Eclipsite.",
  str_voice_1401271_24 = "Aku harus berterima kasih kepada Genevieve karena aku telah bergabung dengan True Order. Aku mengagumi keramahannya.",
  str_voice_1401271_25 = "Orang yang selalu tersenyum pasti berpengetahuan banyak, terutama dalam hal semangat.",
  str_voice_1401271_26 = "Oh, aku rindu sekali melihat reuni besar yang menyenangkan… Sudah sangat lama.",
  str_voice_1401271_27 = "Jadi, para ilmuwan dan rasionalitas versi mereka selalu benar?",
  str_voice_1401271_28 = "Badannya besar sekali! Dia punya jiwa, 'kan?",
  str_voice_1401271_29 = "Aku Pasolo. Kertas-kertas ini mengikutiku ke sini. Mereka tidak akan menghalangi siapa pun…",
  str_voice_1401271_30 = "Eh, kertas lebih ringan.",
  str_voice_1401271_31 = "Pusaran lembar kertas…",
  str_voice_1401271_32 = "Setumpuk kertas lebih kuat daripada zirah apa pun.",
  str_voice_1401271_33 = "Aku makin mendekati kemampuan untuk membangkitkan mereka.",
  str_voice_1401271_34 = "Izinkan aku untuk ikut bergabung…",
  str_voice_1401271_35 = "Kertas itu jadi rata.",
  str_voice_1401271_36 = "Serahkan padaku!",
  str_voice_1401271_37 = "Kekuatan tumpukan!",
  str_voice_1401271_38 = "Mereka di sini!",
  str_voice_1401271_39 = "Sayat!",
  str_voice_1401271_40 = "Tercabik-cabiklah!",
  str_voice_1401271_41 = "Aku, memimpin?",
  str_voice_1401271_42 = "Fiuh, kita menang.",
  str_voice_1401271_43 = "Mundur, semua!",
  str_voice_1401271_44 = "Mereka tidak akan menodai tempat ini…",
  str_voice_1401271_45 = "Terima kasih…!",
  str_voice_1401271_46 = "Boleh aku memiliki ini…?",
  str_voice_1401271_47 = "Bagaimana aku bisa berterima kasih…?",
  str_voice_1401271_48 = "Sudah lama sejak aku diperlakukan orang seperti ini…",
  str_voice_1401271_49 = "Lihat kulitku? Warnanya gelap karena aku menghabiskan masa kanak-kanak di Rediesel Desert.",
  str_voice_1401271_50 = "Aku tidak akan meninggalkan Rediesel Desert kalau bukan karena Eclipsite, dan orang tuaku… pasti masih hidup.",
  str_voice_1401271_51 = "Scarlet Letter itu berisi arwah orang tuaku. Terkadang, aku bahkan bisa mendengar mereka memanggil namaku.",
  str_voice_1401271_52 = "Alchemy Stars.",
  str_voice_1401271_53 = "Hei…",
  str_voice_1401271_54 = "Selamat pagi…",
  str_voice_1401271_55 = "Selamat sore.",
  str_voice_1401271_56 = "Bagaimana kalau beristirahat?",
  str_voice_1401271_57 = "Selamat Tahun Baru.",
  str_voice_1601221_1 = "Pemburu yang baik harus akurat dalam segala hal, mulai dari misi hingga hobi.",
  str_voice_1601221_2 = "Kacamataku membantuku melihat lebih jelas, dan kognisi yang lebih jelas membuahkan hasil yang lebih baik.",
  str_voice_1601221_3 = "Kau ingin lebih mengenalku? Mau tahu lebih banyak? Rahasia kemampuan menembakku? Bayar dulu, nanti aku akan memberitahumu semua yang ingin kau tahu.",
  str_voice_1601221_4 = "Ada berita lagi? Aku siap mendengar. Lebih bagus lagi kalau soal barang antik.",
  str_voice_1601221_5 = "Harta yang paling berharga sering kali adalah yang tersembunyi di dalam hati.",
  str_voice_1601221_6 = "Retakan garis rambut, enamel yang rusak, dasar yang tidak lengkap… Tak satu pun dari itu bisa menyembunyikan nilai sejati dari harta yang paling langka. Apa pun itu, mereka akan selalu menjadi keajaiban yang tak ternilai.",
  str_voice_1601221_7 = "Aku tahu segalanya. Aku sudah melihat semua yang kau lakukan dan semua kemampuanmu. Itu sebabnya aku memilih untuk hadir di sini, di antara orang-orang yang mulia dan langka sepertimu.",
  str_voice_1601221_8 = "Aku ingin berbagi beberapa hadiah hari ini kepadamu… Kurang, ya? Maaf, hanya itu yang bisa kuberikan.",
  str_voice_1601221_9 = "Aku berniat untuk membuka toko barang antik. Aku akan mempertimbangkan untuk memberimu diskon jika kau datang.",
  str_voice_1601221_10 = "Sudah 5 jam, 25 menit, 45 detik sejak aku menerima misi terakhirku. Ah… Waktu luang. Selalu tampak sedikit tidak nyata bagiku.",
  str_voice_1601221_11 = "Kau yang mengepos misi ini? Meski itu kau, kau masih harus membayarku, tetapi kau cukup membayar 97,6% dari harganya. Diskon yang mantap, 'kan?",
  str_voice_1601221_12 = "Panggil aku kapan pun kau ada tugas yang perlu diselesaikan.",
  str_voice_1601221_13 = "Maaf telah menatapmu… Aku seorang penembak jitu—sudah kebiasaan!",
  str_voice_1601221_14 = "Bisakah kau menjauhkan lilinnya? Aku tidak begitu suka api.",
  str_voice_1601221_15 = "Selamat ulang tahun! Terimalah hadiah dari koleksiku ini.",
  str_voice_1601221_16 = "Fokus! Ini adalah waktu terbaik untuk menjalankan misi.",
  str_voice_1601221_17 = "Aku akan menyapa pelangganku sekarang… andai aku punya toko…",
  str_voice_1601221_18 = "Kudengar toko Umbraton menawarkan diskon pada saat-saat seperti ini.",
  str_voice_1601221_19 = "Mendengarkan bunyi detik arloji saku pada malam yang sunyi selalu membuatku tidur nyenyak.",
  str_voice_1601221_20 = "Kau akan selalu tahu banyak hal di Umbraton. Beberapa misi rahasia bayarannya lebih banyak.",
  str_voice_1601221_21 = "Illumina Federation terasa seperti tempat yang dibangun berlandaskan keyakinan…",
  str_voice_1601221_22 = "Hera tidak pernah menutup matanya.",
  str_voice_1601221_23 = "Sudah kuduga… Tidak berguna.",
  str_voice_1601221_24 = "Kudengar Sheol mulai dari nol juga. Mungkin kami harus bicara…",
  str_voice_1601221_25 = "Eho itu lucu… Andai saja dia tidak selalu mencoba menjual sesuatu padaku.",
  str_voice_1601221_26 = "Keajaiban senyap dari jam antik, tetap berdetik meski tiada yang mendengarkan…",
  str_voice_1601221_27 = "Merah muda? Kau beruntung aku diajari sopan santun… Jangan sampai aku melihat warna ini lagi, ya.",
  str_voice_1601221_28 = "Bisakah kita perkecil? Tidak cocok dengan tokoku kalau seperti ini.",
  str_voice_1601221_29 = "Ada yang bisa kubantu? Jika itu adalah misi yang sangat berisiko dan tinggi imbalannya, Allura-lah orangnya.",
  str_voice_1601221_30 = "Terima kasih. Akan kutambahkan ke koleksiku.",
  str_voice_1601221_31 = "Selangkah lebih dekat.",
  str_voice_1601221_32 = "Keberhasilan tergantung pada perhitungan yang cermat.",
  str_voice_1601221_33 = "Sebentar lagi tujuanku tercapai.",
  str_voice_1601221_34 = "Oh, kau memilihku.",
  str_voice_1601221_35 = "Siap menilai.",
  str_voice_1601221_36 = "Hidup itu patut disyukuri.",
  str_voice_1601221_37 = "Penikmat sejati!",
  str_voice_1601221_38 = "Kau itu tidak ada apa-apanya!",
  str_voice_1601221_39 = "Sini, biar kulihat…",
  str_voice_1601221_40 = "Silakan keluar!",
  str_voice_1601221_41 = "Sebaiknya ini sepadan.",
  str_voice_1601221_42 = "Berapa banyak yang kita hasilkan?",
  str_voice_1601221_43 = "Apakah itu semua sepadan…?",
  str_voice_1601221_44 = "Berhenti menatapku, dong! Aku harus memilih, mengidentifikasi, menilai… Pokoknya aku sibuk! Namun, bukan berarti aku tidak bisa menatap harta karun sepertimu!",
  str_voice_1601221_45 = "Terima kasih. Seberapa jauh hal ini menghambatmu?",
  str_voice_1601221_46 = "Aku akan menjaganya dengan baik.",
  str_voice_1601221_47 = "Ah, perasaan yang tidak asing… Terima kasih banyak.",
  str_voice_1601221_48 = "Terima kasih. Kupikir mungkin ini bagian terbaik yang pernah kuterima.",
  str_voice_1601221_49 = "Kenapa terobsesi dengan barang antik? Nah, sebelum wafat, orang tuaku adalah kolektor, jadi itu adalah anugerah sekaligus warisan bagiku. Tidak perlu menghiburku—aku tidak lagi sedih karena mereka, kok.",
  str_voice_1601221_50 = "Tentu saja, dulu aku dipenuhi kebencian pada segala sesuatu ketika masih kecil, tapi kenyataannya adalah… orang-orang pada akhirnya akan belajar apa itu cinta seiring berjalannya hidup. Apa? Kau terkejut mendengarku mengatakan hal seperti itu?",
  str_voice_1601221_51 = "Mengingat kasih sayang mereka, membangkitkan kembali semangat hidup mereka, dan membalas kebaikan mereka yang telah membantuku adalah hal yang paling berarti bagiku. Selain menghasilkan uang.",
  str_voice_1601221_52 = "Alchemy Stars.",
  str_voice_1601221_53 = "Mau membeli sesuatu?",
  str_voice_1601221_54 = "Selamat pagi, Navigator.",
  str_voice_1601221_55 = "Kau butuh sarapan yang bergizi agar kuat menjalani pekerjaan hari ini.",
  str_voice_1601221_56 = "Malam adalah waktu terbaik untuk berbelanja.",
  str_voice_1601221_57 = "Selamat Tahun Baru! Kuharap, kelak semua impian kita akan terwujud.",
  str_voice_1601221_58 = "Bidikanku bahkan lebih tajam dari sebelumnya.",
  str_voice_1601221_59 = "Apa ambisi terbesarmu, Navigator?",
  str_voice_1601221_60 = "Kau di sana, Navigator?",
  str_voice_1601171_1 = "Jangan biarkan kegagalan hari ini membuatmu kecewa, kau pasti bisa melewatinya. Saat kau masih muda, hidup memang tidak pernah mudah. Namun, sepuluh tahun kemudian kau akan sadar itu bukan apa-apa ketika menoleh ke belakang.",
  str_voice_1601171_2 = "Ototmu sakit, ya? Kau berolahraga secara berlebihan? Aku akan membuatkanmu santapan yang lezat malam ini—agar badanmu terasa enakan.",
  str_voice_1601171_3 = "Ah… Kebodohan masa muda, lekas marah dan sok benar, mengira kau penyelamat… Namun, pada akhirnya, sepertinya itu tidak ada salahnya.",
  str_voice_1601171_4 = "Menurutmu, aku ada peningkatan? Yah, aku memang sudah berlatih secara diam-diam. Tampaknya membuahkan hasil.",
  str_voice_1601171_5 = "Jangan terlalu skeptis dengan kata-kata orang tua—aku telah melihat lebih dari yang bisa kaubayangkan. Kali terakhir seseorang menatapku begitu… Itu tepat sebelum dia bertarung dalam pertempuran akhirnya.",
  str_voice_1601171_6 = "Tidak ada yang boleh menyakiti rekan-rekanku! Aku takkan membiarkan mereka melupakannya… Biar kulubangi tengkorak tebal mereka!",
  str_voice_1601171_7 = "Buat rencana mendetail untuk taktik, bertarung dengan gagah berani dalam pertempuran. Sebagai komandan, kau harus memahami ini dengan baik. Itu saja yang harus kukatakan.",
  str_voice_1601171_8 = "Jika kau terlalu gugup dalam pertempuran, mengobrol saja dengan rekan-rekanmu sambil bercanda. Itu akan membantumu tenang dan membuatmu bertarung dan mengeluarkan potensi terbaikmu.",
  str_voice_1601171_9 = "Kau mengomandoi pasukanmu dengan baik dalam pertempuran terakhir. Aku jadi teringat pada hari-hariku dulu di Stone Force. Bahkan saat itu pun ada orang-orang sepertimu.",
  str_voice_1601171_10 = "Bersantai saja di pangkalan sepanjang waktu itu tidak sehat, lho. Namun, apa yang bisa dilakukan? Asah pisaumu, bersihkan senapanmu, lakukan squat beberapa kali.",
  str_voice_1601171_11 = "Kau memindahkanku ke sini? Baiklah, hal yang sama terjadi ketika aku pensiun. Untungnya, aku sudah terbiasa.",
  str_voice_1601171_12 = "Meski sudah pensiun, sesekali aku masih berlatih. Yang namanya pekerjaan itu tidak ada habisnya, 'kan?",
  str_voice_1601171_13 = "Istirahat yang baik memerlukan santapan yang bergizi. Kami mendapatkan makanan terbaik di bagian logistik ini.",
  str_voice_1601171_14 = "Lelah? Beristirahatlah. Itu cara tubuhmu mengatakan sudah waktunya untuk beristirahat.",
  str_voice_1601171_15 = "Selamat ulang tahun! Ini kuemu. Jangan khawatir, dulu aku ini juru masak.",
  str_voice_1601171_16 = "Meskipun memimpin Colossus, kau terlihat seperti staf di bagian logistik…",
  str_voice_1601171_17 = "Pagi akan menentukan harimu. Mulai harimu dengan rutinitas pagi yang bagus.",
  str_voice_1601171_18 = "Kalau kau makan dan bersantai saat hari telah larut, hari esokmu akan lebih baik.",
  str_voice_1601171_19 = "Tidak bisa tidur, ya? Berolahragalah lalu mandi. Bergadang semalaman bukanlah jawaban!",
  str_voice_1601171_20 = "Illumina berkembang karena setiap anggota mematuhi tugas mereka.",
  str_voice_1601171_21 = "Huh, Lumopolis. Prajurit mereka itu seperti domba, tidak ada bedanya dengan Eclipsite…",
  str_voice_1601171_22 = "Jayalah Illumina!",
  str_voice_1601171_23 = "Aku hanya ingin melihat mayat mereka bertumpuk di hadapanku.",
  str_voice_1601171_24 = "Percayalah pada Grand Marshal. Dia selalu memimpin kita menuju kemenangan.",
  str_voice_1601171_25 = "Revy… Kadang aku tidak tahu apakah dia itu laki-laki atau perempuan.",
  str_voice_1601171_26 = "Logistik itu penting! Tak ada yang bisa meningkatkan moral selain makanan yang masih panas!",
  str_voice_1601171_27 = "Rasa manja bisa mengalahkan prajurit terkuat. Sana, pergilah berolahraga!",
  str_voice_1601171_28 = "Ini sangat besar! Untung bukan aku yang mengelolanya!",
  str_voice_1601171_29 = "Tenang! Sekarang aku sudah pensiun, jadi cukup panggil aku Gram! Jangan ragu untuk bertanya kepadaku apa pun soal pertempuran dan logistik.",
  str_voice_1601171_30 = "Aku merasa seperti muda kembali.",
  str_voice_1601171_31 = "Sini, biar kutunjukkan beberapa keterampilan yang sesungguhnya!",
  str_voice_1601171_32 = "Aku akan bertarung sampai akhir yang pahit.",
  str_voice_1601171_33 = "Dewi Kemenangan tersenyum padaku!",
  str_voice_1601171_34 = "Ayo bekerja.",
  str_voice_1601171_35 = "Sekarang persiapannya sudah beres!",
  str_voice_1601171_36 = "Tunggu saat terakhir itu!",
  str_voice_1601171_37 = "Waktumu telah tiba… Sekarang!",
  str_voice_1601171_38 = "Tembak! Bakar mereka menjadi abu!",
  str_voice_1601171_39 = "Ini baru permulaan…",
  str_voice_1601171_40 = "Dan ini akhirnya!",
  str_voice_1601171_41 = "Ikuti aku, teman-teman.",
  str_voice_1601171_42 = "Eclipsite sangat lemah akhir-akhir ini.",
  str_voice_1601171_43 = "Biar kuurus yang belakang! Sekarang, pergilah!",
  str_voice_1601171_44 = "Aku telah berjuang lebih lama dari usiamu. Tidak, jangan khawatirkan aku!",
  str_voice_1601171_45 = "Hmm? Kenapa kau memberiku ini?",
  str_voice_1601171_46 = "Terima kasih. Kau sudah mengamatiku dengan baik.",
  str_voice_1601171_47 = "Ini… Hmm. Akan kuterima.",
  str_voice_1601171_48 = "Terima kasih! Aku janji akan membantumu!",
  str_voice_1601171_49 = "Terkadang menjadi petugas logistik biasa itu tidak ada salahnya. Omong-omong, ini adalah caraku mengawali karier sebagai tentara, dan itu jelas jauh lebih tidak disiplin.",
  str_voice_1601171_50 = "Stone Force… dikalahkan dalam pertempuran sengit lebih dari sepuluh tahun lalu. Ketika memikirkan rekan-rekanku yang telah gugur, kadang aku berharap aku saja yang mati daripada mereka.",
  str_voice_1601171_51 = "Melihat rekan-rekanku gugur satu demi satu, pernah terlintas dalam benakku bahwa kematian adalah jawaban untukku juga. Untungnya, kata-kata Brent memberiku harapan. Kini, aku hidup demi para pahlawan yang gugur itu.",
  str_voice_1601171_52 = "Alchemy Stars!",
  str_voice_1601171_53 = "Saudara seperjuangan.",
  str_voice_1601171_54 = "Selamat pagi. Apakah tidurmu nyenyak?",
  str_voice_1601171_55 = "Sore hari adalah waktu terbaik untuk makan sampai kenyang.",
  str_voice_1601171_56 = "Tidur malam yang nyenyak adalah cara terbaik untuk menjamin awal yang baik untuk esok hari.",
  str_voice_1601171_57 = "Selamat tahun baru! Semoga tahun depan kita bisa bertarung bersama lagi.",
  str_voice_1601171_58 = "Karena mulai sekarang aku akan ikut terbang di Colossus ini, kurasa harus ada perkenalan.",
  str_voice_1601171_59 = "Terima kasih atas hadiahmu.",
  str_voice_1601171_60 = "Bagaimana latihanmu akhir-akhir ini?",
  str_voice_1601171_61 = "Perang itu kejam…",
  str_voice_1601171_62 = "Aku ingin bertanya sesuatu.",
  str_voice_1601191_1 = "Aku suka mesin dan bisa mempelajarinya seharian, tapi belum begitu mahir. Kau tahu mekanik yang andal? Aku butuh bantuan, nih…",
  str_voice_1601191_2 = "Kau baik, dan mengepalai Colossus, kau bisa—menjadi Navigator yang baik! Panggil aku Revy, atau Revie? Revi? Terserah mau panggil apa saja!",
  str_voice_1601191_3 = "Girnya berbunyi \"klik, klik\"…? Oh, Alter-Blade milikku! Aku tadi penasaran apa yang kau bicarakan…",
  str_voice_1601191_4 = "Eclipsite… Satu tebasan membelahnya menjadi dua, dua tebasan membelahnya menjadi empat, dan tiga tebasan membelahnya menjadi delapan…",
  str_voice_1601191_5 = "Pedangku? Seperti mencabuti bulu merpati saja! Betapa ringannya! Eh, tapi aku belum pernah mencabuti bulu apa pun sebelumnya, lho…",
  str_voice_1601191_6 = "Ah! Aroma kekuatan yang manis! Apa? Aku salah omong, ya? Jika kau mengerti, itu sudah cukup.",
  str_voice_1601191_7 = "Kau kelihatan jauh lebih tua dariku, berarti kau sudah tua, sementara aku belum. Stabil? Andal? Berpengalaman dan tepercaya?",
  str_voice_1601191_8 = "Bersama Navigator, meski disalahpahami, rantai Alter-Blade tetap diam. Aneh sekali.",
  str_voice_1601191_9 = "Meski lebih muda darimu, aku sangat kuat, terutama dengan lengan mekanis ini. Sembunyi saja di belakangku saat pertarungan dimulai.",
  str_voice_1601191_10 = "Aku berniat membuat tanda pada Alter-Blade untuk setiap Eclipsite yang kutebas. Namun, terlalu banyak… Tidak bisa menghitung setinggi itu, tidak bisa menulis begitu banyak…",
  str_voice_1601191_11 = "Apa yang bisa kulakukan di sini? Baiklah… Misalnya memikirkan cara menebas Eclipsite dengan lebih baik.",
  str_voice_1601191_12 = "Kapan hujan akan turun? Bisa beri tahu aku? Hujan itu bagus, aku jadi bisa mandi gratis!",
  str_voice_1601191_13 = "Sudah pernah menebas Eclipsite? Oh, tentu saja belum… Kau 'kan Commander. Lain kali, akan kuberi tahu rasanya.",
  str_voice_1601191_14 = "Pria tua itu sungguh lihai berkelahi. Kudengar, dia telah membunuh banyak Eclipsite. Jika tidak, aku tidak punya alasan untuk berbicara dengannya. Huh!",
  str_voice_1601191_15 = "Ulang tahun…? Aku akan memberimu beberapa bola nasi pedas…",
  str_voice_1601191_16 = "Aku jadi lebih bersemangat untuk berpatroli saat melihatmu, Navigator.",
  str_voice_1601191_17 = "Selamat pagi! Aku telah persiapkan jurus baru hari ini!",
  str_voice_1601191_18 = "Kau tidak boleh berlari saat malam hari. Jika bos melihatmu, dia akan menangkap dan memarahimu, lho… Itu tidak bagus. Oh? Kau bos di antara bos? Kalau begitu, jangan khawatir.",
  str_voice_1601191_19 = "Apa? Kau tidak perlu tidur? Mau berpatroli denganku? Aku jadi terharu… Meski itu tidak perlu…",
  str_voice_1601191_20 = "Hal yang baik tentang Illumina… jika ada yang meninggal, ada banyak orang yang akan merawat anak-anaknya. Begitulah caraku dibesarkan.",
  str_voice_1601191_21 = "Kudengar orang-orang di Umbraton minta bayaran untuk melakukan apa saja. Mereka juga ingin dibayar untuk tidak melakukan apa-apa?",
  str_voice_1601191_22 = "Jayalah Illumina!",
  str_voice_1601191_23 = "Bah! Tidak cukup bagiku untuk kutebas!",
  str_voice_1601191_24 = "Vida mirip denganku. Dia senang jika ada sup untuk dimakan, aku senang jika ada Eclipsite untuk ditebas.",
  str_voice_1601191_25 = "Pria tua itu sangat suka ikut campur dan selalu cerewet seperti seorang veteran. Padahal dia itu sudah pensiun!",
  str_voice_1601191_26 = "Hari hujan dan bola nasi pedas… Rasanya tidak enak… Kau punya serbet? Pedas, pedas, pedas!",
  str_voice_1601191_27 = "Kau lihat wajah dan lenganku? Ini karena Eclipsite. Jadi, ketika melihat Eclipsite, aku harus segera menebasnya jadi satu! Oh… Maksudku, menebasnya jadi dua…",
  str_voice_1601191_28 = "Benda ini besar sekali! Aku tidak tahu Illumina punya yang seperti ini. Aku belum pernah melihat satu pun.",
  str_voice_1601191_29 = "Aku Revy. Banyak orang bilang aku kuat, mereka tidak salah. Lihat pedang besar ini. Orang bilang ini berat, tapi aku bisa mengayunkannya seperti pisau mentega. Lihat, 'kan…?",
  str_voice_1601191_30 = "Aku mau lagi.",
  str_voice_1601191_31 = "Aku siap bergemuruh laksana petir!",
  str_voice_1601191_32 = "Menjadi lebih ganas layaknya badai!",
  str_voice_1601191_33 = "Berputar! Kau harus takut padaku!",
  str_voice_1601191_34 = "Kau harus menjadikanku Kapten!",
  str_voice_1601191_35 = "Aku siap!",
  str_voice_1601191_36 = "Sudah waktunya!",
  str_voice_1601191_37 = "Serbu! Binasalah, kalian!",
  str_voice_1601191_38 = "Tidak pernah! Cukup!",
  str_voice_1601191_39 = "Pergilah mengikuti arus!",
  str_voice_1601191_40 = "Akan kuakhiri semuanya!",
  str_voice_1601191_41 = "Aku pantas melakukannya.",
  str_voice_1601191_42 = "Puji aku, puji aku!",
  str_voice_1601191_43 = "Kita akan habisi mereka lain kali!",
  str_voice_1601191_44 = "1, 2, 3, 4, 5… Siapa lagi? Lupakan mereka. Aku takkan menghitung yang sudah kukalahkan…",
  str_voice_1601191_45 = "Terima kasih, dan sama-sama!",
  str_voice_1601191_46 = "Aku boleh menerimanya? Aku jadi tersipu…",
  str_voice_1601191_47 = "Navigator! Kau terlalu baik!",
  str_voice_1601191_48 = "Aku malu! Jangan melihatku!",
  str_voice_1601191_49 = "Bekas luka di wajahku ini gara-gara aku pernah melawan Eclipsite di sekolah. Namun, anak-anak lain mengabaikanku. Kata mereka aku terlalu aneh…",
  str_voice_1601191_50 = "Ketika aku masih kecil, Eclipsite menyerbu rumahku. Orang tuaku pergi untuk menyelamatkan orang. Tetangga menyelamatkanku. Saat itulah aku kehilangan tangan kiriku.",
  str_voice_1601191_51 = "Kau lihat lenganku? Ini pemberian Illumina… karena orang tuaku meninggal melawan Eclipsite… Mereka menyelamatkan banyak orang!",
  str_voice_1601191_52 = "Alchemy Stars.",
  str_voice_1601191_53 = "Kau kembali!",
  str_voice_1601191_54 = "Selamat pagi, Navigator.",
  str_voice_1601191_55 = "Sudah makan siang?",
  str_voice_1601191_56 = "Semoga mimpimu indah.",
  str_voice_1601191_57 = "Selamat Tahun Baru! Semoga kau lebih kuat pada Tahun Baru!",
  str_voice_1601191_58 = "Aku datang!",
  str_voice_1601191_59 = "Muncul suara klik itu lagi pada pedangku…",
  str_voice_1601191_60 = "Tentu, aku pasti menjadi lebih kuat!",
  str_voice_1601191_61 = "Sedang apa kau?",
  str_voice_1601191_62 = "Kau pergi untuk memeriksa Colossus lagi, ya?",
  str_voice_1601151_1 = "Kau menanyakan arti kebebasan? Pertanyaan yang bagus. Namun, sebelum kujawab, bagaimana kalau kau cari saja jawabannya sendiri?",
  str_voice_1601151_2 = "Kumohon maafkan aku—biar kuperkenalkan mereka. Bessie adalah rusaku, Olive dan Palm adalah burungku. Mereka bukan hanya Speaker milikku, tapi juga sahabat sejatiku.",
  str_voice_1601151_3 = "Benda-benda mungil yang bersinar di tasku adalah Firefly. Namun, mereka tidak seperti yang di Colossus. Mereka sudah bersamaku sejak kami masih di Windward Forest.",
  str_voice_1601151_4 = "Waktu berjalan dan ruang bertambah luas saat kuterima takdir dengan tenang. Aku tahu bahwa pintu kebebasanku telah terbuka.",
  str_voice_1601151_5 = "Bertemu denganku mendatangkan keberuntungan…? Rumor yang seperti itu sungguh-sungguh ada, ya? Kalau memang benar, aku ingin kau beruntung.",
  str_voice_1601151_6 = "Benar, aku bisa berkomunikasi dengan hewan dan tumbuhan, seperti halnya kau bisa bertelepati dengan orang lain. Ini karunia kita.",
  str_voice_1601151_7 = "Kalau ingin bertemu denganku, sebut namaku dalam hati. Alam akan menuntunku kepadamu lagi.",
  str_voice_1601151_8 = "Aku mengajak Bessie untuk berjalan-jalan denganku dan tak disangka-sangka kami bertemu denganmu—dia sangat menyukaimu.",
  str_voice_1601151_9 = "Olive dan Palm menyanyikan lagu tentangmu. Siapa sangka kau bakal membuat mereka sangat terkesan?",
  str_voice_1601151_10 = "Cahaya yang terpancar dari matamu berbeda dengan milik Aurorian. Boleh kutebak apa yang sedang kau pikirkan?",
  str_voice_1601151_11 = "Lingkungan di sini lebih menyenangkan dari dugaanku. Aku senang bisa menerima misi dari alam. Kuharap kedatanganku takkan membuatmu kecewa.",
  str_voice_1601151_12 = "Mungkin kau tak pernah memerhatikannya, tapi kekuatan alam selalu menyertai dan menuntunmu.",
  str_voice_1601151_13 = "Angin memberi tahu awan, awan memberi tahu hujan, hujan memberi tahu tanah, dan tanah memberi tahu angin… Pada akhirnya semua akan menemukan jawabannya.",
  str_voice_1601151_14 = "Apa kabar? Ada surat dari Lumopolis?",
  str_voice_1601151_15 = "Selamat ulang tahun. Pemahaman terhadap alam akan meningkat seiring dengan bertambahnya umur.",
  str_voice_1601151_16 = "Kadang aku harus mengurus masalah darurat di Courier Union, tapi tidak ada yang terlalu sulit, kok. Bagaimana denganmu?",
  str_voice_1601151_17 = "Maaf, Olive dan Palm selalu menyanyi seperti ini saat bangun tidur. Apa mereka mengganggumu?",
  str_voice_1601151_18 = "Mau jalan-jalan? Ayo kita ajak Bessie. Kita bisa beristirahat di dalam hutan.",
  str_voice_1601151_19 = "Tak kusangka aku bertemu denganmu dalam mimpi… Mungkin kaulah yang akan memanduku untuk terus maju…",
  str_voice_1601151_20 = "Di sini, di alam, kita bebas menyampaikan cinta dan harapan sesuka hati.",
  str_voice_1601151_21 = "Kelak, aku akan kembali ke Northland… Kembali ke hutan yang hangat. Suatu hari nanti…",
  str_voice_1601151_22 = "Percayalah, Courier Union akan selalu berhasil mengantarkan surat.",
  str_voice_1601151_23 = "Kekacauan dan tata tertib… Aku yakin keduanya tidak berasal dari alam.",
  str_voice_1601151_24 = "Yang Mulia Ratu adalah utusan kekuatan alam yang membimbing jalan setiap anak yang tersesat.",
  str_voice_1601151_25 = "Manusia salju bersayap? Oh, itu pasti Tweety. Dia adalah anak yang lugu dan baik hati.",
  str_voice_1601151_26 = "Setiap makhluk di dunia ini terlahir atas kehendak alam. Semuanya indah dengan caranya masing-masing.",
  str_voice_1601151_27 = "Aku bisa merasakan kehangatan ibuku dalam mantel yang melindungiku dari hawa dingin ini.",
  str_voice_1601151_28 = "Firefly milikku dan Firefly milikmu, Caelestite dan Aurorian, Colossus dan alam… Kita hidup di dunia yang menakjubkan.",
  str_voice_1601151_29 = "Aku sudah sangat lama ingin bertemu denganmu. Nah, akhirnya kekuatan alam menuntunmu kepadaku. Senang bertemu denganmu. Namaku Naroxel.",
  str_voice_1601151_30 = "Aku bisa mendengarnya… Panggilan alam.",
  str_voice_1601151_31 = "Dengarlah nyanyian angin…",
  str_voice_1601151_32 = "Lihatlah tarian air…",
  str_voice_1601151_33 = "Rasakan aroma kebebasan…",
  str_voice_1601151_34 = "Ikuti kata hatimu.",
  str_voice_1601151_35 = "Ayo, Bessie.",
  str_voice_1601151_36 = "Aku menunggu bimbinganmu.",
  str_voice_1601151_37 = "Biar alam yang menentukan jalannya.",
  str_voice_1601151_38 = "Pergilah bersama alam!",
  str_voice_1601151_39 = "Menarilah di atas angin.",
  str_voice_1601151_40 = "Firefly Forest!",
  str_voice_1601151_41 = "Ikutlah denganku.",
  str_voice_1601151_42 = "Ini pujian alam untuk kita.",
  str_voice_1601151_43 = "Mungkin ini juga rencana alam…",
  str_voice_1601151_44 = "Kau pernah mendengar panggilan alam?",
  str_voice_1601151_45 = "Terima kasih. Kau tak perlu repot-repot.",
  str_voice_1601151_46 = "Terima kasih atas kebaikanmu. Akan kuterima.",
  str_voice_1601151_47 = "Baunya alami. Aku suka.",
  str_voice_1601151_48 = "Kau tahu persis apa yang kusukai…? Apa alam menuntunmu?",
  str_voice_1601151_49 = "Saat masih sangat kecil, aku bertemu dengan Bessie, Olive, dan Palm, serta para Firefly ini di Windward Forest. Sejak itu, kami tak pernah terpisahkan.",
  str_voice_1601151_50 = "Bessie membantuku menyadari tempat dan misiku di dunia ini. Aku harus mengikuti panduan alam dan terus melangkah ke depan untuk menyelesaikan reinkarnasiku di alam.",
  str_voice_1601151_51 = "Orang tuaku menyayangiku seperti putri kandung mereka sendiri. Meski ada banyak pakaian indah di toko-toko Lumopolis, rasanya pakaian buatan ibuku adalah yang paling nyaman.",
  str_voice_1601151_52 = "Alchemy Stars.",
  str_voice_1601151_53 = "Apa kau di sini?",
  str_voice_1601151_54 = "Mulai hari yang baru dengan alam.",
  str_voice_1601151_55 = "Ini waktu yang tepat untuk bersantai.",
  str_voice_1601151_56 = "Kita akan bertemu dalam mimpi.",
  str_voice_1601151_57 = "Tahun baru menghadirkan kehidupan baru, selalu sepadan untuk disambut.",
  str_voice_1601151_58 = "Saat merasa lelah, ke mana kau akan pergi, Navigator?",
  str_voice_1601151_59 = "Apa kau suka musik, Navigator?",
  str_voice_1601151_60 = "Terima kasih, Navigator.",
  str_voice_1601211_1 = "Duri tidak melukai siapa pun—hanya diam saja. Namun, perkataan orang justru bisa menusukmu seperti pisau yang tajam. Jadi, manakah yang lebih buruk…?",
  str_voice_1601211_2 = "Aku berpikir, maka aku ada. Jadi, kalau aku tidak berpikir, maka aku tak akan ada. Sekarang aku sedang tidak berpikir, Navigator. Kau masih bisa lihat aku?",
  str_voice_1601211_3 = "Keadilan mungkin tertunda, tapi tak pernah ingkar. Oh… Namun, kadang terlambat sekali sampai-sampai kupikir keadilan itu tidak ada…",
  str_voice_1601211_4 = "Ingin lihat koin yang menggantung di leherku? Silakan—tapi jangan coba gigit, ya.",
  str_voice_1601211_5 = "Iman memberi dukungan terkuat yang bisa dibayangkan. Oh, tapi rumah, jembatan, dan kuil juga membutuhkan fondasi batu yang sangat kokoh.",
  str_voice_1601211_6 = "Lihat gadis berambut pendek itu? Oh, aku sangat mengenalnya…",
  str_voice_1601211_7 = "Pada akhirnya penghakiman akan datang kepada semua orang. Oh, tapi bagaimana kalau orang jahat meninggal sebelum mendapat penghakiman? Apa itu berarti mereka dibiarkan begitu saja?",
  str_voice_1601211_8 = "Kata para pendeta di Lumopolis, orang-orang yang tak punya iman tak lebih baik dari monster. Namun, aku yakin setiap monster bisa mempertahankan diri…",
  str_voice_1601211_9 = "Kau pernah ke Lumopolis? Pernah lihat kebangsawanan dan kegigihan orang-orang di sana? Oh, lucu sekali…",
  str_voice_1601211_10 = "Aku lebih suka menganggur daripada sibuk. Mengkhayal… Melihat koinku, merasakan duri-durinya…",
  str_voice_1601211_11 = "Pemandangan di sini lumayan bagus. Aku jadi bisa memikirkan banyak hal… tentang cara menghadapi para bedebah Lumopolis…",
  str_voice_1601211_12 = "Semua orang setara di hadapan God of Light. Oh, hanya saja beberapa orang lebih setara dari yang lain.",
  str_voice_1601211_13 = "Bahkan duri sekalipun ditemani oleh bunga yang indah. Lihat saja sendiri…",
  str_voice_1601211_14 = "Tekadlah yang mendorong kita untuk terus maju… Namun, kalau kita sudah salah jalan sejak awal, bukankah kita justru akan makin jauh dari jalan yang benar?",
  str_voice_1601211_15 = "Selamat ulang tahun. Itu ucapan yang sudah ketinggalan zaman, tapi aku tak bisa memikirkan kata-kata lain yang lebih baik.",
  str_voice_1601211_16 = "Hari lain yang biasa telah dimulai. Oh, kalau tidak biasa, kita takkan ada di sini, 'kan?",
  str_voice_1601211_17 = "Navigator, kenapa orang selalu mengucapkan selamat pagi? Bagaimana kalau paginya tidak menyenangkan?",
  str_voice_1601211_18 = "Setelah pekerjaanku selesai, kuhabiskan malamku untuk istirahat. Orang yang bekerja lembur itu sangat menyedihkan.",
  str_voice_1601211_19 = "Keheningan malam… mungkin membantu orang untuk merenung. Oh, itu juga membantu orang untuk tertidur.",
  str_voice_1601211_20 = "Tak ada kebenaran sejati di dunia ini. Momoknya hanya ada di perkataan para pengkhianat.",
  str_voice_1601211_21 = "Kata para pendeta di Lumopolis, iman mendorong orang untuk terus maju, tapi tidak membuat perut kenyang.",
  str_voice_1601211_22 = "Semoga kebenaran memberkatimu, kalau itu ada.",
  str_voice_1601211_23 = "Jika God of Light menciptakan segalanya, apa dia juga menciptakan Eclipsite?",
  str_voice_1601211_24 = "Satu-satunya persamaanku dan Pact adalah duri kami. Itu saja.",
  str_voice_1601211_25 = "Jangan pernah menyerah—ini adalah mantra Wayne. Inilah prinsip yang dijalani, dan sumber \"kebahagiaan\"nya.",
  str_voice_1601211_26 = "Konon bunga semak duri melambangkan siksaan takdir, tapi aku yakin bunga itu mewakili ketahanan jiwa.",
  str_voice_1601211_27 = "Keyakinan yang salah cenderung menarik orang yang fanatik. Makin aneh keyakinan itu, makin kuat semangat yang dibangkitkan.",
  str_voice_1601211_28 = "Meski terlihat begitu besar dari luar, bagian dalamnya tidak terlalu luas. Namun, kemampuan terbangnya sangat menarik.",
  str_voice_1601211_29 = "Halo, aku Paloma. Takdirlah yang mempertemukan kita, tapi kalau kau memikirkannya, mungkin ini semua hanya kebetulan.",
  str_voice_1601211_30 = "Kekuatanku menolak untuk jadi makin kuat.",
  str_voice_1601211_31 = "Ada duri-duri baru… di lambangku…",
  str_voice_1601211_32 = "Jalur duri telah menampakkan dirinya padaku.",
  str_voice_1601211_33 = "Kepingan… masa laluku.",
  str_voice_1601211_34 = "Sekarang giliranku?",
  str_voice_1601211_35 = "Saatnya terlahir kembali.",
  str_voice_1601211_36 = "Kelahiran kembali telah menunggu.",
  str_voice_1601211_37 = "Hancurkan!",
  str_voice_1601211_38 = "Lepas dari masa lalu!",
  str_voice_1601211_39 = "Menggeliat dalam semak berduri…",
  str_voice_1601211_40 = "Putus asa dalam duri!",
  str_voice_1601211_41 = "Kau mau aku yang memimpin? Ikuti kata hatimu.",
  str_voice_1601211_42 = "Yah… Kita menang.",
  str_voice_1601211_43 = "Berlari seperti angin!",
  str_voice_1601211_44 = "Ini benar-benar… penting?",
  str_voice_1601211_45 = "Oh? Lumayan juga.",
  str_voice_1601211_46 = "Menarik. Sangat menarik…",
  str_voice_1601211_47 = "Anggap ini sebagai ucapan terima kasihku.",
  str_voice_1601211_48 = "Indah sekali… Ah, terima kasih!",
  str_voice_1601211_49 = "Demi White Night… Seharusnya kau tidak terkejut begitu saat mendengarku mengucapkannya. Lagi pula, dulu aku adalah biarawati. Sulit dibayangkan, 'kan?",
  str_voice_1601211_50 = "Lumopolis melindungi rakyatnya. Ah… Namun, kenapa mereka membiarkan orang tuaku mati di hadapanku? Apa inilah keadilan versi Lumopolis? Masa bodoh, deh…",
  str_voice_1601211_51 = "Semua orang iri pada kehidupan glamor para bangsawan Lumopolis… Kalau boleh memilih lagi, aku lebih suka menjadi rakyat biasa.",
  str_voice_1601211_52 = "Alchemy Stars.",
  str_voice_1601211_53 = "Hai.",
  str_voice_1601211_54 = "Selamat pagi. Hari ini kau bangun pagi.",
  str_voice_1601211_55 = "Sudah waktunya makan siang.",
  str_voice_1601211_56 = "Semoga mimpi indah.",
  str_voice_1601211_57 = "Selamat Tahun Baru. Semoga akan ada sesuatu yang benar-benar luar biasa.",
  str_voice_1601211_58 = "Halo, Navigator. Namaku Paloma.",
  str_voice_1601211_59 = "Apa kau kebetulan pernah melihat koinku?",
  str_voice_1601211_60 = "Kau sudah lihat gadis berambut pendek itu, 'kan?",
  str_voice_1601211_61 = "Permisi, tapi apa arti kata \"iman\" bagimu?",
  str_voice_1601211_62 = "Pernahkah kau melihat semak berduri mekar?",
  str_voice_1300651_1 = "Sewamat datang! Ah, tidak, ini bukan Cwoud Bwossom Hotew! Hah? Tidak penting, ya?",
  str_voice_1300651_2 = "Kau suka sawju? Ayo main pewang bowa sawju denganku! Jangan khawatiw, aku punya banyak, kok!",
  str_voice_1300651_3 = "Navigator, aku kemwai untuk mengantawkan hadiah untukmu! Oh… Tadi kutawuh di topiku! Mana, ya?",
  str_voice_1300651_4 = "Ah, maafkan aku! Kau jadi takut, ya? Bowa putih ini adalah buwung keciwku, bukan bowa sawju!",
  str_voice_1300651_5 = "Kemampuan bowa sawjuku makin hebat sekawang! Aku akan membuat manusia sawju besaw yang menyewupaimu!",
  str_voice_1300651_6 = "Kau suka bunga, Navigatow? Kawau aku sih suka sekawi. Apawagi bunga sawju dan bunga sakuwa… Cantik sekawi!",
  str_voice_1300651_7 = "Navi-Navi-Navigatow! Aku ingin mempewbaiki cawa bicawaku. Bisa bantu aku?",
  str_voice_1300651_8 = "Kawau kau punya masawah, katakan saja kepadaku. Dengan senang hati aku akan membantumu!",
  str_voice_1300651_9 = "Navigatow, kawau kau menginap di Cwoud Mountain, jangan wupa bewi tahu aku, ya! Aku akan mengambiw cuti dan menjamumu.",
  str_voice_1300651_10 = "Navigatow, kau sudah sewesai menuwis suwat? Aku akan segewa mengantawnya ke mana pun tujuannya.",
  str_voice_1300651_11 = "Aku datang! Wow! Tempat yang sempuwna untuk pewang bowa sawju!",
  str_voice_1300651_12 = "Apa katamu bawusan? Ada suwat di ekowku…? Wow, kau benaw! Tewima kasih, Navigatow!",
  str_voice_1300651_13 = "Buwungku biwang meweka mewindukan bunga sakuwa di Cwoud Mountain.",
  str_voice_1300651_14 = "Navigatow, kapan aku boweh bewendam di pemandian aiw panas di sekitaw sini?",
  str_voice_1300651_15 = "Bowa sawju ini cantik, 'kan? Ambiwwah, dan sewamat uwang tahun!",
  str_voice_1300651_16 = "Baikwah! Aku datang! Fiuh! Ini suwatmu. Towong tanda tangan di sini!",
  str_voice_1300651_17 = "Sewamat pagi! Navigatow, kau masih tiduw, ya? Aku sudah bangun, nih!",
  str_voice_1300651_18 = "Sibuk, sibuk, sewawu sibuk… Namun, kawi ini aku ingin sekawi bewendam di pemandian aiw panas.",
  str_voice_1300651_19 = "Bewum tiduw, Navigatow? Mataku sudah mau tewpejam. Sewamat… mawam… Zzzzz…",
  str_voice_1300651_20 = "Aku tidak hanya mementingkan uang—aku ingin bewajaw dawi kuwiw seniow kami yang pawing kewen!",
  str_voice_1300651_21 = "Aku suka Nortwand! Tempat itu sepewti kampung hawamanku, Cwoud Mountain.",
  str_voice_1300651_22 = "Pewcayalah, Couwiew Union sewawu bewhasil mengantawkan suwat!",
  str_voice_1300651_23 = "Ecwipsite memang mengewikan… Namun, kau boweh minta bantuanku kawau ingin mewawan meweka!",
  str_voice_1300651_24 = "Nawoxel? Wah, aku sangat kagum padanya! Semoga aku bisa jadi sepewti dia kawau sudah besaw nant!",
  str_voice_1300651_25 = "Pepi memang hebat dan sewawu menjaga kami!",
  str_voice_1300651_26 = "Bewendam di pemandian aiw panas sambiw mewempaw bowa sawju dan mewihat bunga sakuwa… Tentu saja aku bisa mewakukannya secawa bewsamaan!",
  str_voice_1300651_27 = "Mengiwim suwat ke Wediesel Wench? Sebenawnya… aku tak tahan pada tempat yang tewwawu panas.",
  str_voice_1300651_28 = "Wow! Apa buwungku akan jadi sebesaw itu, ya?",
  str_voice_1300651_29 = "Hai, Navigatow! Ingat aku tidak? Aku Tweety. Bewi tahu aku kawau kau butuh bantuan!",
  str_voice_1300651_30 = "Wow! Tak kusangka aku bisa tewbang sangat tinggi!",
  str_voice_1300651_31 = "Bowa sawju, bowa sawju, bowa sawju!",
  str_voice_1300651_32 = "Bowa sawjuku makin besaw!",
  str_voice_1300651_33 = "Aku yakin aksenku bewangsuw-angsuw hiwang!",
  str_voice_1300651_34 = "Aku kemawi untuk membantu!",
  str_voice_1300651_35 = "Bewsiapwah, manusia sawju!",
  str_voice_1300651_36 = "Aku siap bewaksi!",
  str_voice_1300651_37 = "Awas! Bowa sawjunya datang!",
  str_voice_1300651_38 = "Snowman Surge!",
  str_voice_1300651_39 = "Ayo bewpesta!",
  str_voice_1300651_40 = "Snowball Storm!",
  str_voice_1300651_41 = "Sini, biaw kucoba!",
  str_voice_1300651_42 = "Ini semua bagian dawi pekewjaan! Hihi!",
  str_voice_1300651_43 = "Kuwasa aku bisa membantu…",
  str_voice_1300651_44 = "Navi-Navi-Navigatow! Aku punya suwvei Couwiew Union untukmu! Apa kau punya waktu?",
  str_voice_1300651_45 = "Ini… benaw-benaw untukku?",
  str_voice_1300651_46 = "Wow! Aku mau puwang dan mempewwihatkannya pada Gwammy, ah!",
  str_voice_1300651_47 = "Navigatow, kau memang hebat!",
  str_voice_1300651_48 = "Wuu-huu! Ini hadiah tewbaik yang pewnah kutewima!",
  str_voice_1300651_49 = "Di timuw jauh, ada suatu tempat yang indah bewnama Cwoud Mountain dengan sewpih sawju yang menawi-nawi di udawa bewsama bunga sakuwa. Wow, aku jadi kangen rumah…",
  str_voice_1300651_50 = "Gwammy sudah mewawatku sejak aku masih keciw. Aku hawus bekewja kewas agaw bisa menjadi kuwiw hebat dan membuatnya bangga!",
  str_voice_1300651_51 = "Meski cawa bicawaku aneh, aku punya banyak teman baik di dawatan. Hah? Ya, tentu saja kau juga sawah satu teman baikku, Navigatow!",
  str_voice_1300651_52 = "Awchemy Stars!",
  str_voice_1300651_53 = "Aku datang!",
  str_voice_1300651_54 = "Semawat pagi, Navigatow!",
  str_voice_1300651_55 = "Ada suwat untuk diantaw, Navigatow?",
  str_voice_1300651_56 = "Navigatow, tiduwwah webih awaw, ya?",
  str_voice_1300651_57 = "Di tahun bawu pun mewempaw bowa sawju sewawu mengasyikkan!",
  str_voice_1300651_58 = "Kau sedang apa, Navigatow?",
  str_voice_1601261_1 = "Asalkan bebas dan setara, transaksi harus dihormati dan dilindungi. Nah… apa kau mau merundingkan akuisisiku atas Colossus?",
  str_voice_1601261_2 = "Orientasi permintaan adalah aturan yang harus selalu diingat oleh pelaku bisnis. Permintaan apa yang bisa kau penuhi? Beri tahu aku.",
  str_voice_1601261_3 = "Semua keberadaan tergantung pada aturan. Baik hukum maupun kredibilitas, di permukaan maupun di bawah tanah, itu adalah kontrak yang kau tanda tangani dengan tempat yang kau sebut rumah.",
  str_voice_1601261_4 = "Jika tak ada pilihan lain, isi kontrak bisa diubah. Namun, kau harus jujur, setia, penuh integritas, dan transparan. Kalau tidak, tak ada yang bisa membantumu.",
  str_voice_1601261_5 = "Aku tahu kau melihatnya. Berusaha tidak melihat ekor orang lain adalah tata krama mendasar bagi orang yang tahu sopan santun.",
  str_voice_1601261_6 = "Ini Frankel. Oh, yang itu juga Frankel. Mereka hantu kesayanganku. Aku bisa membedakannya, kok. Hah? Mereka bukan peliharaan yang lazim?",
  str_voice_1601261_7 = "Pemasok berjubah hitam… Itu julukanku dulu. Julukan yang kusandang sebelum diadopsi oleh Shadowlord.",
  str_voice_1601261_8 = "Aku benar-benar benci pada industri tertentu… Barang-barang yang beredar secara ilegal… Selama masih ada, aku akan mencari cara untuk memberantasnya.",
  str_voice_1601261_9 = "Akuisisi, negosiasi, pembiayaan, penjualan, pemasaran… Aku bisa melakukannya. Atau mungkin kau mau novel percintaan, seperti aku?",
  str_voice_1601261_10 = "Rute transportasi, titik kontak, dan waktu negosiasi sudah beres… Fyuh, akhirnya aku bisa istirahat. Nah, ayo kita lihat buku kesukaanku. Mau baca sama-sama?",
  str_voice_1601261_11 = "Konsultasi bisnis macam apa yang kau butuhkan? Sebelum itu, sebaiknya kita tanda tangani dulu kontrak yang sama-sama menguntungkan kedua belah pihak.",
  str_voice_1601261_12 = "Wah, coba lihat siapa yang datang. Kuharap kita bisa mencapai kesepakatan dalam perundingan hari ini.",
  str_voice_1601261_13 = "Ya, aku masih sibuk. Maafkan aku—asistenku sedang cuti. Jangan lupa membuat janji temu dulu. Ya, kau juga, Caelestite.",
  str_voice_1601261_14 = "Negosiasinya sudah selesai. Siapa yang bisa mengantar tamu terhormat kita pulang?",
  str_voice_1601261_15 = "Selamat ulang tahun! Aku akan ambil cuti untuk merayakan ulang tahunmu ini denganmu—ulang tahun seorang Caelestite pasti bisa jadi alibi yang bagus.",
  str_voice_1601261_16 = "Selamat siang, selamat bersibuk-sibuk ria. Adakah pertemuan bisnis yang harus kau hadiri?",
  str_voice_1601261_17 = "Selamat pagi. Secangkir kopi dan koran—beginilah rutinitas pagiku.",
  str_voice_1601261_18 = "Senang rasanya bisa membaca buku sebelum tidur setelah bekerja keras seharian. Jangan lupa tidur lebih awal, ya.",
  str_voice_1601261_19 = "Hmm…? Kau… belum tidur rupanya. Apa yang kulihat? Rahasia, dong!",
  str_voice_1601261_20 = "Ini adalah masyarakat kapitalis yang ideal secara global. Siapa pun yang mematuhi aturan bisa untung besar.",
  str_voice_1601261_21 = "Apa orang-orang Illumina benar-benar bisa mendapatkan keinginan mereka dengan sistem pendistribusian saja?",
  str_voice_1601261_22 = "Bayangan mengawasimu.",
  str_voice_1601261_23 = "Kemunculan mereka selalu mengganggu pasar dan menyebabkan kerugian finansial yang signifikan.",
  str_voice_1601261_24 = "Lady Sheol juga cukup terbuka dalam hal bisnis… Dia tidak bisa menahannya.",
  str_voice_1601261_25 = "Kopi buatan Connolly selalu membuatku merasa bernostalgia.",
  str_voice_1601261_26 = "Kebebasan yang diatur dan suara aliran uang… Eh… Siapa bilang aku mengoleksi novel percintaan?",
  str_voice_1601261_27 = "Pada akhirnya, rahasia busuk akan terungkap. Kalau tidak, aku akan mengusut dan membongkarnya.",
  str_voice_1601261_28 = "Kau akan dapat untung besar kalau menggunakan ini untuk tujuan transportasi. Kau tidak ingin mendirikan perusahaan transportasi sendiri?",
  str_voice_1601261_29 = "Maaf telah membuatmu menunggu lama. Aku Bethel, pemimpin Markas Umbraton Guild. Kalau ada yang ingin kau bicarakan, hubungi asistenku untuk membuat janji temu.",
  str_voice_1601261_30 = "Ini pertukaran yang adil.",
  str_voice_1601261_31 = "Ini… tangan yang tak kasat mata?",
  str_voice_1601261_32 = "Sepertinya Frankel menyukainya.",
  str_voice_1601261_33 = "Aku tak sabar… ingin melawan badai berikutnya!",
  str_voice_1601261_34 = "Semoga kita bisa bekerja sama dengan baik.",
  str_voice_1601261_35 = "Kontrak kita akan terwujud.",
  str_voice_1601261_36 = "Tolong segera tanda tangani!",
  str_voice_1601261_37 = "Ayo kita pergi, Tindall!",
  str_voice_1601261_38 = "Frankel! Perburuan dimulai!",
  str_voice_1601261_39 = "Akan kubuat kau menangis.",
  str_voice_1601261_40 = "Rasakan air matamu sendiri!",
  str_voice_1601261_41 = "Mengelola tim? Bisa, dong.",
  str_voice_1601261_42 = "Sudah kubilang kita bakal dapat untung.",
  str_voice_1601261_43 = "Fluktuasi pasar bisa… tak terduga…",
  str_voice_1601261_44 = "Hmm… Sepertinya kau sudah memakainya untuk menandatangani suatu kontrak.",
  str_voice_1601261_45 = "Aku… tak perlu membayarnya?",
  str_voice_1601261_46 = "Terima kasih. Akan kutaruh di kantor.",
  str_voice_1601261_47 = "Terima kasih. Aku akan membalas kebaikanmu.",
  str_voice_1601261_48 = "Ini… cocok sekali denganku. Kau benar-benar penulis, ya?",
  str_voice_1601261_49 = "Ibuku lahir di Lumopolis dan ayahku adalah seorang pengusaha. Hal itu menghancurkan ayahku baik secara mental maupun fisik… Itu sebabnya aku sangat membenci industri ini.",
  str_voice_1601261_50 = "Dulu beberapa orang di Umbraton menyebutku sebagai pemasok berjubah hitam. Aku bertindak bodoh saat itu dan hampir menghancurkan sistem operasi Cloudrover Guild.",
  str_voice_1601261_51 = "Aku terluka parah saat mencoba bertindak sendiri… Namun, aku beruntung karena menjadi putri angkat Istvan. Sekarang aku mengerti betapa pentingnya peraturan itu.",
  str_voice_1601261_52 = "Alchemy Stars.",
  str_voice_1601261_53 = "Hah?",
  str_voice_1601261_54 = "Tak ada gunanya bangun tidur kalau tak dapat untung.",
  str_voice_1601261_55 = "Siang ini sibuk?",
  str_voice_1601261_56 = "Toko-toko sudah tutup.",
  str_voice_1601261_57 = "Di tahun yang baru, kuharap kerja sama kita terus berlanjut seperti selama ini.",
  str_voice_1601291_1 = "Apa misi terbaru kami? Kapan akan dikirimkan? Tenang saja, aku akan segera menyelesaikannya.",
  str_voice_1601291_2 = "Tidak ada hukum untuk ditegakkan atau aturan bertahan hidup untuk dihafal di Umbraton. Yang ada hanya kredibilitas. Inilah alasanku untuk selalu tinggal di sini.",
  str_voice_1601291_3 = "Kami harus menjadi organisasi yang lebih berpengaruh agar lebih banyak orang mengenal dan percaya pada kekuatan kami… Hah? Oh, maaf. Aku tidak melihatmu di sana tadi.",
  str_voice_1601291_4 = "Kalau ada lebih banyak misi, berarti kita juga butuh lebih banyak anggota… tapi itu juga berarti lebih banyak korban. Namun, pada tahap ini, kita harus belajar memilih. Jadi, mari kita pilih untuk menerima lebih banyak misi.",
  str_voice_1601291_5 = "Kau melihat jubahku, ya? Aku melukisnya sendiri, lho. Kalau kau suka, aku bisa membuatkanmu yang seperti ini setelah menyelesaikan misi.",
  str_voice_1601291_6 = "White Flame Mercenaries bertahan di Umbraton karena kredibilitasnya. Inilah yang membedakan kami dengan organisasi dan negara yang dipandu oleh kekuatan publik.",
  str_voice_1601291_7 = "Kau… melihat topengku? Aku sudah memakainya sejak masih sangat kecil. Ini kenang-kenangan dari seniorku.",
  str_voice_1601291_8 = "Dulu aku sangat muak dengan transaksi bawah tanah… tapi aku sudah mengatasi perasaan itu. Kami mendapat banyak keuntungan jika bekerja sama dengan mereka. Apalagi banyak dari anak buahku masih mengandalkannya sebagai mata pencaharian.",
  str_voice_1601291_9 = "Bolehkah aku melukismu? Jangan meremehkan kemampuan melukisku, ya. Kadang aku bisa mencapai kesepakatan dengan geng bawah tanah melalui karya seniku.",
  str_voice_1601291_10 = "Tempat ini sangat bersih dan rapi… Bolehkah kulepaskan sebentar teman-teman kecilku di luar? Eh… Asalkan kau tidak takut, sih.",
  str_voice_1601291_11 = "Tunggu sampai kuselesaikan ini sedikit lagi, ya… Baiklah, sekarang aku bisa mengeksekusi misimu dengan sepenuh hati.",
  str_voice_1601291_12 = "Aku mematuhi peraturan Umbraton. Yah, meskipun beberapa transaksi… Sudahlah. Justru inilah sebab keberadaan skuad tentara bayaranku.",
  str_voice_1601291_13 = "Aku melihat ada benda-benda kecil beterbangan di sini… Apa kau juga suka serangga?",
  str_voice_1601291_14 = "Aku sangat berterima kasih kepada commander White Flame Mercenaries atas perhatian dan dukungannya. Aku tak akan menjadi seperti sekarang ini kalau bukan karena dia.",
  str_voice_1601291_15 = "Ini hari kelahiranmu. Aku dan White Flame Mercenaries dengan tulus mengharap yang terbaik untukmu.",
  str_voice_1601291_16 = "Kau pasti sudah bekerja dengan sangat keras… Ingat, ya, kerja dan istirahat harus seimbang. Nah, soal bersantai… bagaimana kalau kau mengamati kupu-kupuku saja?",
  str_voice_1601291_17 = "Selamat pagi. Senang melihatmu bangun pagi—jadwal tidurmu berbeda dengan kebanyakan tentara bayaran. Ini berarti tubuhmu sehat.",
  str_voice_1601291_18 = "Sudah malam… Ini saat yang tepat untuk menyelesaikan misi.",
  str_voice_1601291_19 = "Sudah larut malam. Beberapa makhluk memang tidak bisa bergadang sampai selarut ini.",
  str_voice_1601291_20 = "Umbraton adalah kota kebebasan, tapi apakah kebebasan harus punya batas? Tak ada yang tahu.",
  str_voice_1601291_21 = "Prajurit memang sangat berbeda dengan tentara bayaran. Melaksanakan perintah itu wajib, sedangkan ketaatan pada kredibilitas adalah pilihan.",
  str_voice_1601291_22 = "Bayangan… Ada di mana-mana, dan mengawasimu.",
  str_voice_1601291_23 = "Maaf, tapi Eclipsite tidak kuanggap sebagai makhluk hidup. Aku tidak merasa kasihan saat melihat mayatnya.",
  str_voice_1601291_24 = "Allura menyukai hal-hal yang berhubungan dengan waktu. Aku sudah lama mengetahuinya.",
  str_voice_1601291_25 = "Istvan… Entah menjaga keseimbangan antargeng atau komunikasi antarmanusia, banyak hal yang bisa kupelajari darinya.",
  str_voice_1601291_26 = "Seperti Aurorian, serangga adalah ciptaan alam. Semua makhluk berhak melepaskan diri dari kepompongnya dan menjadi kupu-kupu.",
  str_voice_1601291_27 = "Siapa pun yang tidak menghargai kehidupan, tidak pantas hidup.",
  str_voice_1601291_28 = "Kudengar itu campuran antara mesin dan biologi…? Sungguh struktur yang luar biasa…",
  str_voice_1601291_29 = "Halo, aku Luke. Ada yang bisa kubantu? Tenang saja, misi apa pun akan ditangani secara profesional.",
  str_voice_1601291_30 = "White Flame Mercenaries bertambah kuat.",
  str_voice_1601291_31 = "Diam-diam mereka menempel padaku.",
  str_voice_1601291_32 = "Bersatu dan makmur!",
  str_voice_1601291_33 = "Kehidupan baru… harus terus mengalir!",
  str_voice_1601291_34 = "Kami menyambut baik misi darimu.",
  str_voice_1601291_35 = "Kehidupan itu abadi!",
  str_voice_1601291_36 = "Mereka semua di bawah kendaliku!",
  str_voice_1601291_37 = "Tercekiklah di bawah kekuatan ini!",
  str_voice_1601291_38 = "Belenggu! Terbuka!",
  str_voice_1601291_39 = "Kabut kematian!",
  str_voice_1601291_40 = "Pemusnahan!",
  str_voice_1601291_41 = "Akan kuperkuat tim ini!",
  str_voice_1601291_42 = "Inilah kekuatan skuad tentara bayaran!",
  str_voice_1601291_43 = "Aku harus bekerja dengan lebih keras…",
  str_voice_1601291_44 = "Ini bisa dijadikan sebagai titik kontak tentara bayaran.",
  str_voice_1601291_45 = "Terima kasih. Akan kutaruh di mejaku.",
  str_voice_1601291_46 = "Apa pun misi yang kulakukan, akan kubawa ini.",
  str_voice_1601291_47 = "Sudah lama aku ingin yang seperti ini… Entah bagaimana aku bisa berterima kasih padamu.",
  str_voice_1601291_48 = "Aku akan menyimpannya. Izinkan aku membalas budi atas kebaikanmu.",
  str_voice_1601291_49 = "Menunggu bukanlah hal mudah, terutama kalau kau tahu bahwa orang yang kau tunggu tak akan pernah kembali. Untungnya, masa-masa itu telah berlalu. Aku tak akan memimpikan malam itu lagi.",
  str_voice_1601291_50 = "Commander bukan saja ayah yang hebat, tapi juga pemimpin yang kompeten. Dengan arahannya, akhirnya aku paham bahwa orang yang berbicara tanpa keyakinan tak akan pernah berhasil.",
  str_voice_1601291_51 = "Kau ingin tahu asal-usul kemampuanku, ya? Sederhana saja, kok—aku dan kehidupan saling menghormati satu sama lain. Aku hidup damai dengan segala bentuk kehidupan.",
  str_voice_1601291_52 = "Alchemy Stars.",
  str_voice_1601291_53 = "Halo.",
  str_voice_1601291_54 = "Pagi, aku sedang bekerja. Kau pasti juga sedang bekerja.",
  str_voice_1601291_55 = "Kalau sudah siang, cobalah rasakan aura alam.",
  str_voice_1601291_56 = "Selamat malam. Semoga seranggaku tidur di sebelahmu.",
  str_voice_1601291_57 = "Selamat Tahun Baru! Semoga semuanya berjalan makin lancar di tahun baru.",
  str_voice_1500551_1 = "Kalau kau punya masalah, kita bertemu di Hall of Justice. Prosedur bagaikan penutup mata keadilan, jadi aku tak akan berpihak kepada siapa pun.",
  str_voice_1500551_2 = "God of Light yang mahakuasa adalah pencipta segala sekaligus penyelamat semua kehidupan. Itu jelas. Tak ada yang sulit dipahami—ingat kebenaran ini.",
  str_voice_1500551_3 = "Kau ingin menghadiri salah satu pengadilanku? Maaf, tidak bisa. Kau harus mendaftar di Hall of Justice dan memverifikasi identitasmu. Begitulah peraturannya.",
  str_voice_1500551_4 = "Saat kugenggam tongkat di tanganku, kudengar suara ayahku bergema di telingaku. \"Jangan sampai dua anggota keluarga Pittman berada di medan tempur secara bersamaan,\" itu yang dia katakan dulu.",
  str_voice_1500551_5 = "Aku pernah berada di garis depan dan terluka di medan tempur. Karena itu, aku mengerti bahwa segala yang kita miliki diraih dengan pengorbanan.",
  str_voice_1500551_6 = "Hah? Lihat saja kalau kau mau. Tulang mekanis ini dibuat khusus di Illumina. Tanpa ini, aku tak akan punya lengan kiri lagi.",
  str_voice_1500551_7 = "Banyak orang ingin meraih mimpinya dengan cara-cara politis dan bukannya dengan meningkatkan kemampuan. Menurutku, kau berbeda dari mereka.",
  str_voice_1500551_8 = "Kalau dulu kau belajar di Dawn Academy saat masih kecil, kau pasti akan jadi murid yang luar biasa dan berprestasi. Namun, tentu saja belum terlambat.",
  str_voice_1500551_9 = "Chief Judge adalah orang terakhir yang sangat kukagumi. Generasi muda pasti akan mengungguli yang tua! Aku tak sabar ingin melihatmu di masa depan.",
  str_voice_1500551_10 = "Menangkap buronan adalah hobi kesukaanku. Kau juga mau coba? Hmm… Sebaiknya latih dulu fisikmu sebelum bergabung denganku.",
  str_voice_1500551_11 = "Selama ada permukaan benda untuk menaruh berkas yang kubaca, mau di mana pun aku tidak peduli. Tempat ini sangat luas. Cocok sekali denganku.",
  str_voice_1500551_12 = "Di hadapan God of Light, semua makhluk hidup itu setara. Masing-masing dari kita punya kesempatan untuk menerima karunia-Nya.",
  str_voice_1500551_13 = "Ada banyak ketidakadilan yang tercatat di bukuku. Apa saja itu? Yah, pokoknya akan kuselesaikan satu per satu.",
  str_voice_1500551_14 = "Ikutilah bimbingan God of Light. Dia akan membantumu melihat isi hatimu—bersikap baiklah kepada sesama dan dirimu sendiri.",
  str_voice_1500551_15 = "Selamat ulang tahun. God of Light memberkati semua orang yang taat hukum dengan kebahagiaan dan perlindungan.",
  str_voice_1500551_16 = "Sudah waktunya bekerja. Kalau kau ingin membicarakan sesuatu yang tak ada kaitannya dengan pekerjaan, nanti saja saat jam istirahat, ya.",
  str_voice_1500551_17 = "Selamat pagi. Kalau pikiranku sedang jernih begini, biasanya aku memilah-milah masalah yang belum selesai.",
  str_voice_1500551_18 = "Hari ini hampir berakhir. Kuharap aku punya lebih banyak waktu.",
  str_voice_1500551_19 = "Kau juga ingin bergadang, ya? Jadwal yang seperti ini terlalu berat untuk siapa pun.",
  str_voice_1500551_20 = "Laksana God of Light yang abadi, Lumopolis tak akan pernah runtuh!",
  str_voice_1500551_21 = "True Order? Dengan berani mereka menggunakan kata \"kebenaran\" untuk membingungkan semua orang. Aku takut God of Light takkan pernah memaafkan mereka.",
  str_voice_1500551_22 = "Demi White Night!",
  str_voice_1500551_23 = "Kalau melihat Eclipsite, aku pasti akan menghajarnya. Tanpa diadili pun mereka sudah dinyatakan bersalah.",
  str_voice_1500551_24 = "Dulu, tak pernah kubayangkan dia akan jadi anggota True Order…",
  str_voice_1500551_25 = "Seniorku di akademi dan seniorku di kantor… Chief Judge selalu berada di depanku.",
  str_voice_1500551_26 = "Kami punya posisi dan tugas sendiri. Ketertiban yang indah memang tak tergantikan.",
  str_voice_1500551_27 = "Tidak ada yang lebih menjijikkan daripada bertindak melampaui aturan, sistem, dan hukum.",
  str_voice_1500551_28 = "Saat ini tidak ada peraturan apa pun di Colossus… Kurasa sudah waktunya membuat peraturan.",
  str_voice_1500551_29 = "Halo, aku Wayne Pittman, hakim di Lumo Hall of Justice. God of Light telah mempertemukan kita…",
  str_voice_1500551_30 = "Ini perkembangan yang berkelanjutan.",
  str_voice_1500551_31 = "Kekuatan… mengaliri seluruh tubuhku!",
  str_voice_1500551_32 = "Guntur… menderu untukku.",
  str_voice_1500551_33 = "Kini tak ada lagi tempat untuk menyembunyikan dosa!",
  str_voice_1500551_34 = "Bagus.",
  str_voice_1500551_35 = "Lihatlah!",
  str_voice_1500551_36 = "Tetap tenang!",
  str_voice_1500551_37 = "Kunyatakan kau… bersalah!",
  str_voice_1500551_38 = "Tak bisa kabur!",
  str_voice_1500551_39 = "Eksekusi!",
  str_voice_1500551_40 = "Terimalah hukumanmu!",
  str_voice_1500551_41 = "Aku akan menilai dengan adil.",
  str_voice_1500551_42 = "Demi keadilan!",
  str_voice_1500551_43 = "Aku tidak menyelidikinya dengan cukup teliti…",
  str_voice_1500551_44 = "Aku butuh tempat yang tenang untuk berdoa.",
  str_voice_1500551_45 = "Apa ini… hadiah persahabatan?",
  str_voice_1500551_46 = "Terima kasih sudah mau repot-repot.",
  str_voice_1500551_47 = "Baiklah, kuterima. Terima kasih banyak.",
  str_voice_1500551_48 = "Sangat berguna. Aku suka ini.",
  str_voice_1500551_49 = "Saat itu, yang bisa kulakukan hanyalah berbaring di ranjang sepanjang hari. Kemudian God of Light menyelamatkanku. Dia menerangi jiwaku dengan kebenaran dan membimbingku untuk menyebarkan kebenaran itu ke seluruh negeri… meski aku belum benar-benar memenuhi kehendak-Nya.",
  str_voice_1500551_50 = "Aku takkan pernah melupakan kejadian di Umbraton malam itu. Rekan-rekanku meninggal satu per satu. Kakiku sangat lelah dan aku menangis dalam hati… Aku akan menemukan kebenaran jika itu adalah hal terakhir yang kulakukan!",
  str_voice_1500551_51 = "Aku selalu mendapatkan penemuan tak terduga saat membaca berkas. Tak hanya membantuku bekerja dengan lebih efektif, itu juga mendekatkanku pada kebenaran di balik pemberontakan. Tentu saja, melihat penilaian yang dibuat di berbagai daerah itu menarik juga.",
  str_voice_1500551_52 = "Alchemy Stars!",
  str_voice_1500551_53 = "Tolong waspadalah.",
  str_voice_1500551_54 = "Pagi!",
  str_voice_1500551_55 = "Bagaimana perkembangannya?",
  str_voice_1500551_56 = "Langitnya menjadi gelap.",
  str_voice_1500551_57 = "Patuhi hukum, sejak Tahun Baru dan seterusnya.",
  str_voice_1601231_1 = "A-Apa? Butuh bantuan? Serahkan saja semuanya padaku!",
  str_voice_1601231_2 = "Tiga potong roti panggang dan secangkir teh hitam untuk sarapan, satu hidangan lengkap ala Illumina untuk makan siang, ditambah dua puding dan sekaleng… Oh… Sepertinya nanti malam aku makan apel saja…",
  str_voice_1601231_3 = "Oh, ini? Ini seragam Sheriff Illumina! Hanya mereka yang lulus ujian magang yang bisa mengenakannya! Omong-omong… kau menatapku terlalu lama!",
  str_voice_1601231_4 = "Kode Etik Sheriff—Aturan Nomor Satu! Menjaga keamanan umum dan mencegah segala gangguan ketertiban umum! Tongkat ini bukan hanya untuk dipamerkan, tahu!",
  str_voice_1601231_5 = "Kode Etik Sheriff—Aturan Nomor Dua! Jaga ketertiban di jalanan dan tangani semua kecelakaan lalu lintas… Uh… Aturan lalu lintas Colossus? Maaf, sepertinya aku belum pernah mempelajarinya…",
  str_voice_1601231_6 = "Kode Etik Sheriff—Aturan Nomor Tiga! Saat menjalankan tugas apa pun, hormati dan lindungi martabat setiap warga… Tentu saja, Eclipsite tidak masuk hitungan!",
  str_voice_1601231_7 = "Seorang sheriff harus membantu orang lain dan menjaga keadilan. Aku juga harus membantumu dan menjagamu!",
  str_voice_1601231_8 = "Aku sangat senang bisa membantumu… bukan saja karena itu pekerjaanku!",
  str_voice_1601231_9 = "Bantu aku menyelesaikan tugas harianku untuk membantu orang! Aku masih perlu membantu satu orang lagi hari ini… Katakan saja apa yang kau butuhkan—coba pikir-pikir, Navigator!",
  str_voice_1601231_10 = "Hei, kau memanggilku, tapi tidak butuh apa-apa! Sepertinya menunggu juga bagian dari pekerjaan… Sheriff Cordy—siap beraksi!",
  str_voice_1601231_11 = "Aku ke sana! Sheriff Illumina Cordy, melapor untuk bertugas!",
  str_voice_1601231_12 = "Hei… Jangan ganggu aku dulu. Aku tidak mau tugas patroli harianku gagal!",
  str_voice_1601231_13 = "Tidak apa-apa. Aku bisa menangani tugas apa pun, besar atau kecil… Sepertinya ini berarti kau memercayaiku!",
  str_voice_1601231_14 = "Ya, aku mendengarkan! Jangan terburu-buru—santai saja.",
  str_voice_1601231_15 = "Selamat ulang tahun! Apa keinginan ulang tahunmu? Biar kubantu mewujudkannya!",
  str_voice_1601231_16 = "Ada yang bisa kubantu, Navigator? Pekerjaan seorang sheriff memang tidak ada habisnya!",
  str_voice_1601231_17 = "Selamat pagi, Navigator! Tidurmu nyenyak semalam? Sudah sarapan? Hei!? Kau kurang tidur, ya…?",
  str_voice_1601231_18 = "Selamat malam! Ini hari yang sibuk!",
  str_voice_1601231_19 = "Sudah waktunya tidur. Kenapa kau tidak… Sebentar… Ada permintaan darurat, ya!?",
  str_voice_1601231_20 = "Struktur organisasi Illumina sangat rumit. Menjaga ketertiban di sini tidak selalu mudah.",
  str_voice_1601231_21 = "Aku tidak punya masalah apa pun dengan Umbraton, tapi… Mungkin aku punya beberapa masalah dengan tempat itu…",
  str_voice_1601231_22 = "Jayalah… Illumina!",
  str_voice_1601231_23 = "Merundung yang lemah dan mengganggu ketertiban umum… bersiaplah untuk dihukum!",
  str_voice_1601231_24 = "Andai para officer itu tidak memercayaiku, aku takkan pernah berkesempatan untuk melakukan pekerjaan impianku.",
  str_voice_1601231_25 = "Sebenarnya aku tidak mau membicarakan apa pun, tapi ada beberapa hal yang aku suka darinya.",
  str_voice_1601231_26 = "Aku suka membantu orang lain dan menghitung kalori… Oh, tidak, maksudku…! Sebentar… Kau tidak mendengar itu?",
  str_voice_1601231_27 = "Kalau rencana yang sudah kita susun menjadi berantakan, rasanya menyebalkan, 'kan?",
  str_voice_1601231_28 = "Wah, sepertinya panel kontrol hari ini belum dibersihkan, ya…? Lalu, botol larutan nutrisimu benar-benar berantakan… Serahkan semua ini padaku, Navigator!",
  str_voice_1601231_29 = "Sheriff Cordy dari Illumina, siap melayanimu dengan senyuman! Ada yang bisa kubantu, Navigator?",
  str_voice_1601231_30 = "P-promosi? Itu berarti kau telah mengakui semua kerja kerasku?",
  str_voice_1601231_31 = "Kau benar-benar mengandalkanku?",
  str_voice_1601231_32 = "Terima kasih telah memercayaiku! Aku akan melakukan yang terbaik!",
  str_voice_1601231_33 = "Rasanya kemampuanku benar-benar meningkat!",
  str_voice_1601231_34 = "Sekarang, saatnya untuk pindah!",
  str_voice_1601231_35 = "M-Menunggu perintah!",
  str_voice_1601231_36 = "Waaah… Ini dia!",
  str_voice_1601231_37 = "Patuhi sheriff-mu!",
  str_voice_1601231_38 = "Tongkat ini bukan hanya untuk dipamerkan!",
  str_voice_1601231_39 = "Guntur dan api!",
  str_voice_1601231_40 = "Waktunya bertugas! Misi khusus!",
  str_voice_1601231_41 = "Illumina Sheriff, siap memimpin!",
  str_voice_1601231_42 = "Tugas selesai!",
  str_voice_1601231_43 = "Maaf… Tadinya kupikir aku bisa membantu…",
  str_voice_1601231_44 = "Illumina Sheriff, siap sedia untuk melayanimu… Aduh! Sakit…",
  str_voice_1601231_45 = "Jika kau benar-benar ingin berterima kasih, kirimkan surat kepada departemen sheriff!",
  str_voice_1601231_46 = "Apa? Ini untukku…? Sepertinya kau sudah mencurahkan pikiranmu untuk hadiah ini!",
  str_voice_1601231_47 = "Hatimu lebih berharga dari hadiah apa pun.",
  str_voice_1601231_48 = "Terima kasih! Aku sungguh menyukainya!",
  str_voice_1601231_49 = "Kau sungguh peduli? Dulu orang-orang menertawakanku… Namun, sekarang aku benar-beanr tidak peduli!",
  str_voice_1601231_50 = "Melindungi yang lemah dan menegakkan keadilan… Itulah impianku selama ini.",
  str_voice_1601231_51 = "Meski ditugaskan untuk bertarung di medan perang baru, aku akan melakukan yang terbaik… Seperti sebelumnya.",
  str_voice_1601231_52 = "Alchemy Stars!",
  str_voice_1601231_53 = "Ada yang bisa kubantu?",
  str_voice_1601231_54 = "Selamat pagi dari Illumina Sheriff!",
  str_voice_1601231_55 = "Selamat siang! Ada masalah apa?",
  str_voice_1601231_56 = "Selamat malam. Sebaiknya kau beristirahat.",
  str_voice_1601231_57 = "Selamat Tahun Baru!",
  str_voice_1500151_1 = "Kunjungilah kami jika kau ingin berinvestasi dalam karya seni sejati. Tersedia juga berbagai layanan tambahan lainnya!\nPembayaran untuk layanan tambahan ini akan disertakan dalam harga pembelian…",
  str_voice_1500151_2 = "Endus, endus… Aku mencium… Nightium!",
  str_voice_1500151_3 = [[
Kami bukan pencipta karya seni!
Kami pemasok karya seni!]],
  str_voice_1500151_4 = "Barang lamamu yang membosankan akan dihargai murah. Biar Gin mempercantik pianomu dengan percikan cat, ya?\nSepertinya itu bukan untuk dijual…",
  str_voice_1500151_5 = "Hanya mereka yang benar-benar memahami seni saja yang bisa melihat nilai lukisan tua ini. Jadi… Kau mau yang mana?\nLagi pula, tidak ada yang mau beli juga.",
  str_voice_1500151_6 = "Pakaian yang sama setiap hari… Gaya rambut standar… Mau tips untuk merapikan rambutmu?",
  str_voice_1500151_7 = "Kadang-kadang, gagasan besar dan rumit perlu diungkapkan dengan cara yang lebih sederhana dan terus terang…\nJadi, kita makan apa nanti?",
  str_voice_1500151_8 = "Apa yang terjadi kalau kami gagal mengirimkan pesanan? Itu rahasia dagang! Pokoknya, Gin adalah pemalsu ulung…\nYa, intinya memang begitu…",
  str_voice_1500151_9 = "Lolipop, lolipop apa yang berjalan di salju terlalu lama? Jawabannya, es loli… Tidak lucu, ya? Tadinya kupikir dialog baru kami sudah siap untuk dipentaskan…",
  str_voice_1500151_10 = "Kalau kau bisa tetap diam sedikit lebih lama…\nLukisan-lukisan ini tidak akan terjual dengan sendirinya…",
  str_voice_1500151_11 = "Sekarang saatnya mencari peluang bisnis baru!",
  str_voice_1500151_12 = "Hatsyiii… Gin selalu lupa memasang kembali tutupnya setelah menggunakan gel rambut…",
  str_voice_1500151_13 = "Jangan menatap kami seperti itu, dong. Kami bisa melakukan pekerjaan tentara bayaran apa pun yang kau berikan kepada kami.",
  str_voice_1500151_14 = "Mengetahui bahasa lain adalah keahlian yang berguna untuk setiap pelukis kawakan… Meong. Apa? Itu lucu, kan?",
  str_voice_1500151_15 = [[
Selamat ulang tahun! Bagaimana kalau kau undang beberapa temanmu yang kaya untuk ikut menyantap makan malam saat kau berulang tahun?
Namun, kau harus punya teman dulu.]],
  str_voice_1500151_16 = "Selain menyegarkan, lolipop pepermin juga baik untukmu. Mau coba?",
  str_voice_1500151_17 = "Eh, tunggu sebentar! Jangan menatapku! Mana gel rambutku!?",
  str_voice_1500151_18 = "Walkie!\n… Dia tidak bisa mengejar. Kita berlari terlalu cepat?",
  str_voice_1500151_19 = "Ah… Sudah sewajarnya anjing tidur pada malam hari.",
  str_voice_1500151_20 = "- Kami lebih suka bekerja sendiri. Guild-guild itu bisa sangat merepotkan untuk dihadapi… gaji agensinya saja tidak banyak.",
  str_voice_1500151_21 = "Baik itu orang kaya baru maupun bangsawan yang sok, estetika artistik mereka yang hambar selalu sangat konsisten.",
  str_voice_1500151_22 = "Bayangan itu memperhatikanmu…\nBegitu pula peluang bisnisnya!",
  str_voice_1500151_23 = "Sekelompok orang tak beradab dengan selera rendahan dan tak berkelas…\nKeberadaan mereka hanya untuk dimanfaatkan oleh orang lain.",
  str_voice_1500151_24 = "Di satu sisi… Istvan bagaikan mentor bagi kami.",
  str_voice_1500151_25 = "Tak kusangka ada wanita bangsawan bermartabat yang membantu kita!",
  str_voice_1500151_26 = "Dua, tiga, empat, lima, enam, tujuh… Menghitung angka nol di rekening kami tidak pernah membosankan!",
  str_voice_1500151_27 = "Aku benci menerima pesanan dari Rediesel Desert… Siangnya terasa panas membara, malamnya terasa sedingin es.",
  str_voice_1500151_28 = "Desain dinding ini memperluas rasa visual ruang secara esensial… Apa? Ternyata ini kamar lain?!",
  str_voice_1500151_29 = "Hachi!\nGin.\nKami adalah pedagang karya seni berbakat sekaligus tentara bayaran paruh waktu!\nMungkin maksudmu \"tentara bayaran berbakat dan pedagang karya seni paruh waktu\"…",
  str_voice_1500151_30 = "Senjata kita tampaknya semakin lama semakin kuat!",
  str_voice_1500151_31 = "Kini aku merasa terinspirasi!",
  str_voice_1500151_32 = "Penikmat sejati!",
  str_voice_1500151_33 = "Tuan memang pria yang punya selera bagus!",
  str_voice_1500151_34 = "Pesanan dikonfirmasi!",
  str_voice_1500151_35 = "Mengisi amunisi!",
  str_voice_1500151_36 = "Tenang, aku akan menjagamu.",
  str_voice_1500151_37 = "Coba ini!",
  str_voice_1500151_38 = "Tamat sudah riwayatmu!",
  str_voice_1500151_39 = "Sungguh tidak berseni…",
  str_voice_1500151_40 = "Ini baru keindahan!",
  str_voice_1500151_41 = "- Selama kita bisa melakukan ini bersama, seharusnya tidak ada masalah!",
  str_voice_1500151_42 = [[
Ini dia!
Satu pesanan kilat, langsung ke neraka!]],
  str_voice_1500151_43 = "Ayo mundur dan… jilati luka kita…",
  str_voice_1500151_44 = "Sepertinya kau membayar cukup mahal untuk benda tua besar ini!",
  str_voice_1500151_45 = "Aku lebih suka lolipop yang banyak.",
  str_voice_1500151_46 = "Rasanya sungguh luar biasa!",
  str_voice_1500151_47 = "Tidak senikmat garukan di belakang telinga.\nBaik, kemarilah…",
  str_voice_1500151_48 = "Tunggu apa lagi—aku bahkan akan memberikan layanan pengiriman khusus!\nGratis, tentu saja.",
  str_voice_1500151_49 = "Gaya rambut yang tinggi menandakan standar selera tertinggi! Tinggi rambutku bertambah 3 sentimeter lagi—apa aku sudah setinggi Gin? Belum!?\nSama sekali belum.",
  str_voice_1500151_50 = "- Aku tahu pekerjaan macam apa ini. Gin tidak hanya berbakat dalam pemalsuan… Namun, kami tak mau berhenti hingga berhasil menabung cukup Nightium.",
  str_voice_1500151_51 = "Terkadang, aku memimpikan masa lalu… Lukisan langit biru yang indah, kanvas yang membentang di seluruh dinding… Sosok ayah kami masih terbayang jelas dalam benakku.",
  str_voice_1500151_52 = [[
Alchemy!
Stars.]],
  str_voice_1500151_53 = "Hei! Kami kembali!",
  str_voice_1500151_54 = "Selamat pagi!",
  str_voice_1500151_55 = "Ayo makan! Aku ingin daging-dagingan, nih!",
  str_voice_1500151_56 = "Jalan-jalan sebelum tidur?",
  str_voice_1500151_57 = [[
Selamat Tahun Baru!
Setidaknya semoga harimu menyenangkan.]],
  str_voice_1601201_1 = "Aku tahu, kau pasti penasaran dengan kesatria raksasa yang selalu ada di sisiku. Panggil saja dia Pompey atau Knight of Light.",
  str_voice_1601201_2 = "Maaf, aku tidak terbiasa berbicara dengan orang lain. Sebaiknya kita lebih akrab nantinya, katamu? Kalau begitu, silakan, akan kuterima upaya terbaikmu",
  str_voice_1601201_3 = "Kesendirian adalah ranah tersendiri yang memiliki syarat lebih tinggi pada seseorang. Hanya dengan menyendirilah aku benar-benar bisa mengetahui keinginan terdalamku.",
  str_voice_1601201_4 = "Dunia di luar Lumopolis… Aku sudah membaca banyak buku tentangnya, tapi mungkin suatu hari nanti, aku bisa melihatnya dengan mataku sendiri.",
  str_voice_1601201_5 = "Selama kau berusaha, tidak ada buku yang tidak bisa dibaca. Paham? Hal yang paling sulit untuk dipahami adalah diri sendiri.",
  str_voice_1601201_6 = "Jadi, kau dulu sendirian… Bagaimana kau bisa mendapatkan begitu banyak teman setelahnya? Jangan salah paham, aku hanya penasaran.",
  str_voice_1601201_7 = "Abaikan kerumunan orang banyak itu, kau akan mengerti bahwa orang-orang tidak saling merasakan kesedihan dan kegembiraan masing-masing.",
  str_voice_1601201_8 = "Sebaiknya kau membaca lebih banyak studi sejarah tentang Lumopolis. Dengan begitu… kita akan memiliki lebih banyak kesamaan untuk dibicarakan.",
  str_voice_1601201_9 = "Aku membaca bahwa orang-orang yang saling membantu bisa disebut sebagai \"teman\". Jadi, apa kau akan membantuku? Yah… Aku akan membantumu kalau kau membutuhkanku.",
  str_voice_1601201_10 = "Aku tahu, menghabiskan banyak waktu untuk menyendiri di kamar bisa sangat membosankan. Saat bosan, aku meminta Pompey untuk membawaku ke atap agar bisa menatap langit dan awan.",
  str_voice_1601201_11 = "Ini tempat yang amat damai. Bolehkah aku tinggal di sini saja? Bagus. Jangan bawa orang lain ke sini.",
  str_voice_1601201_12 = "Demi White Night. Aku tahu keyakinan Lumopolis bisa menyelamatkan Aurorian… dan Caelestite.",
  str_voice_1601201_13 = "Mengumpulkan buku-buku yang hilang bagaikan menyusun puzzle. Bagiku, ini adalah permainan.",
  str_voice_1601201_14 = "Waktunya meminyaki Pompey. Hmm… sedikit polesan juga boleh sekalian.",
  str_voice_1601201_15 = "Yah… Meski tidak akan pergi ke pesta ulang tahunmu, aku akan mengucapkan selamat ulang tahun lebih dulu.",
  str_voice_1601201_16 = "Aku menemukan artikel yang luar biasa! Ini tentang… Oh, mungkin kau tidak akan tertarik.",
  str_voice_1601201_17 = "Di waktu-waktu seperti ini, awan di langit terlihat paling indah. Kau mau melihatnya?",
  str_voice_1601201_18 = "Apa? Biasanya kau makan malam hanya dengan tiga menu? Rasanya sulit dibayangkan…",
  str_voice_1601201_19 = "Dulu aku juga pernah lupa tidur karena keasyikan membaca. Apa kabarmu hari ini?",
  str_voice_1601201_20 = "Pusat dunia, puncak peradaban Aurorian… Tempat paling cocok bagiku untuk menjalani hidup.",
  str_voice_1601201_21 = "Nun jauh di utara, di bawah langit yang tersapu Aurora… Apakah anak cahaya masih tinggal di sini, siapa yang tahu?",
  str_voice_1601201_22 = "Demi White Night.",
  str_voice_1601201_23 = "Makhluk-makhluk jelek dan kotor itu? Tentu saja aku tahu siapa mereka. Mereka tidak pantas berada di dunia ini.",
  str_voice_1601201_24 = "Lord Schwartz, City Lord yang memimpin Lumopolis menuju jalan kebenaran, adalah orang yang paling aku hormati di dunia ini.",
  str_voice_1601201_25 = "Tentu saja aku tahu Yang Mulia, Carleen. Lagi pula, beliau adalah salah satu dari sedikit orang yang seumuran denganku.",
  str_voice_1601201_26 = "Aku suka membaca. Aku membaca buku, benda… bahkan Aurorian.",
  str_voice_1601201_27 = "Aktivitas berkelompok? Belum pernah coba… Namun, mungkin aku hanya akan merepotkan orang.",
  str_voice_1601201_28 = "Aku tahu yang semacam itu ada di dunia, tapi tak kusangka ukurannya lebih besar dari Pompey.",
  str_voice_1601201_29 = "Aku akan memegang teguh legenda Knight of Light… Oh, kau pasti Caelestite. Demi White Night. Hedy Bryte memberimu salam tulusnya.",
  str_voice_1601201_30 = "Aku tidak menyadari besarnya kekuatan yang aku miliki… Bagaimana kau melakukannya?",
  str_voice_1601201_31 = "Aku bisa pergi sedikit lebih jauh sekarang.",
  str_voice_1601201_32 = "Begitu, ya… jalan Knight of Light.",
  str_voice_1601201_33 = "Masa depan, akan berubah bersamaku.",
  str_voice_1601201_34 = "Hmm? Baiklah.",
  str_voice_1601201_35 = "Mari kita mulai.",
  str_voice_1601201_36 = "Akhirnya, giliranku tiba.",
  str_voice_1601201_37 = "Knight of Light, datanglah kepadaku!",
  str_voice_1601201_38 = "Tidak ada tempat untuk bersembunyi bagi kegelapan!",
  str_voice_1601201_39 = "Sini, ke sebelahku, Pompey!",
  str_voice_1601201_40 = "Rasakan cahaya kejayaan!",
  str_voice_1601201_41 = "Akan kuakhiri ini dengan cepat.",
  str_voice_1601201_42 = "Bagi Knight of Light, ini tidak ada apa-apanya.",
  str_voice_1601201_43 = "Pertarungan yang memalukan… Aku takkan menerimanya!",
  str_voice_1601201_44 = "Hmm… Hal ini perlu dipertimbangkan dengan cermat.",
  str_voice_1601201_45 = "Apa ini…? Tentu saja aku tahu ini hadiah!",
  str_voice_1601201_46 = "Hmm… Terima kasih sudah mau repot-repot.",
  str_voice_1601201_47 = "Memangnya kau harus memberikan ini kepadaku secara langsung? Tidak, tidak apa-apa…",
  str_voice_1601201_48 = "Tahu tidak? Aku sangat menyukai hadiah ini!",
  str_voice_1601201_49 = "Kebahagiaan terkadang membutakan orang. Dulu aku mengira setiap orang memiliki guru privat… Aku dulu juga berpikir bahwa setiap orang terbiasa sendirian.",
  str_voice_1601201_50 = "Monster-monster dalam mimpiku, dengan taring dan cakarnya yang tajam… Karena begitu nyata dan mengerikan, mereka seolah-olah menelan jiwaku sepenuhnya… Hanya buku yang mampu menyelamatkanku.",
  str_voice_1601201_51 = "Lagi-lagi aku bermimpi buruk. Namun, kali ini seorang kesatria berzirah putih muncul dari cahaya dan menghalau kegelapan di hadapanku.",
  str_voice_1601201_52 = "Alchemy Stars.",
  str_voice_1601201_53 = "Aku tahu…",
  str_voice_1601201_54 = "Kuucapkan selamat pagi.",
  str_voice_1601201_55 = "Kuucapkan selamat siang.",
  str_voice_1601201_56 = "Kuucapkan selamat malam.",
  str_voice_1601201_57 = "Pada Tahun Baru, semoga damai menyertaimu.",
  str_voice_1601311_1 = "Hidup tanpa ritual bagaikan menempuh perjalanan dalam gelapnya malam tanpa bintang… Membosankan, 'kan?",
  str_voice_1601311_2 = "Ssst… Nanti kelinci-kelinci di dekatku bakal ketakutan kalau suaramu terlalu keras.",
  str_voice_1601311_3 = "Sejarah menyimpan kebenaran tentang peristiwa di masa lalu dan hal-hal yang akan terjadi di masa depan.",
  str_voice_1601311_4 = "Jika setiap hari terasa sama, itu belum tentu buruk. Ketahuilah bahwa banyak dari rekan kita telah mengorbankan nyawa untuk memberikan masa depan yang stabil untuk anak cucu mereka.",
  str_voice_1601311_5 = "Oh? Ada anggota baru dalam keluarga kelinci…? Bersabarlah dan bersikap baik, kelinci kecil. Akan segera kusiapkan wortel manis untuk kalian semua.",
  str_voice_1601311_6 = "Kekuatan besar membutuhkan tanggung jawab besar. Aku tak akan lari dari tanggung jawabku atau lupa pada tujuan asliku. Keinginanku untuk melindungi Northland justru makin kuat.",
  str_voice_1601311_7 = "Tak perlu takut begitu. Tanyakan saja kepadaku kalau kau punya pertanyaan. Aku akan berusaha sebaik mungkin untuk memberimu jawaban yang memuaskan.",
  str_voice_1601311_8 = "Kadang, sifat-sifat baikmu mengingatkanku pada seorang teman lama yang sudah lama tak kujumpai… Kuharap aku bisa bertemu dengannya lagi.",
  str_voice_1601311_9 = "Menciptakan suasana ritual itu cukup sederhana. Misalnya… hari perjumpaan kita bisa dijadikan sebagai hari jadi persahabatan kita.",
  str_voice_1601311_10 = "Apa kau bosan? Aku bisa menceritakan sejarah Northland. Mungkin ceritaku bisa menghiburmu untuk sesaat.",
  str_voice_1601311_11 = "Oh? Proses janji temu yang sangat terasa seperti ritual. Haha, aku sangat senang bisa membantumu.",
  str_voice_1601311_12 = "Kadang aku bisa mendengar gunung dan sungai berbicara kepadaku. Suara mereka terdengar pelan, tapi sangat memikat.",
  str_voice_1601311_13 = "Hati-hati. Bahkan kelinci putih berbulu lembut pun juga akan menggigit kalau marah.",
  str_voice_1601311_14 = "Setiap hari biasa pun pantas dikenang.",
  str_voice_1601311_15 = "Ada mantra kuno yang sangat cocok untukmu hari ini—Selamat Ulang Tahun!",
  str_voice_1601311_16 = "Yah, memang belum ada yang berubah. Bahagia itu sederhana, 'kan?",
  str_voice_1601311_17 = "Regangkan badanmu atau tarik napas dalam-dalam… Kita bisa mengawali hari yang indah dengan ritual sederhana.",
  str_voice_1601311_18 = "Pekerjaanmu sudah selesai? Mungkin aku bisa membantumu melakukan ritual untuk membersihkan jiwamu?",
  str_voice_1601311_19 = "Oh… Kenapa kau belum tidur padahal sudah selarut ini? Jangan-jangan kau melakukan ritual terlarang, ya?",
  str_voice_1601311_20 = "Setiap hari aku merasa bersyukur karena bisa tinggal di negeri putih ini.",
  str_voice_1601311_21 = "Baik Illumina maupun Lumopolis memiliki cara bertahan sendiri-sendiri.",
  str_voice_1601311_22 = "Demi Utara.",
  str_voice_1601311_23 = "Mereka adalah makhluk menyedihkan yang memiliki kekuatan besar, tapi tak punya kemampuan untuk berpikir sendiri.",
  str_voice_1601311_24 = "Orang-orang hanya melihat seberapa kuatnya sang Ratu, tapi tak ada yang tahu pengorbanannya untuk melindungi Northland…",
  str_voice_1601311_25 = "Nikinis memang paling tahu kalau soal menghormati Yang Mulia Ratu.",
  str_voice_1601311_26 = "Iya… Itu karena aku tumbuh besar di negeri bersalju. Aku jadi lebih bisa menghargai matahari.",
  str_voice_1601311_27 = "Haha, jangan sampai aku mendengar kabar miring tentang Yang Mulia Ratu.",
  str_voice_1601311_28 = "Benda raksasa yang muncul dalam catatan sejarah. Tak kusangka aku bisa melihat yang asli.",
  str_voice_1601311_29 = "Aku Novio, penduduk Northland, dan aku sudah lama menunggumu. Hari ini cuacanya cerah. Mungkinkah ia sudah menanti kedatanganmu dan ingin menyambutmu?",
  str_voice_1601311_30 = "Oh? Rasanya sangat hangat…",
  str_voice_1601311_31 = "Api penyembuhan menyala di hatiku.",
  str_voice_1601311_32 = "Sejarah… terjadi di depan mata.",
  str_voice_1601311_33 = "Perkembangan ini patut diperingati!",
  str_voice_1601311_34 = "Ayo.",
  str_voice_1601311_35 = "Aku siap",
  str_voice_1601311_36 = "Aku sudah menunggu.",
  str_voice_1601311_37 = "Aku butuh ritual.",
  str_voice_1601311_38 = "Terra Staff, beri aku kekuatan!",
  str_voice_1601311_39 = "Aku selalu di sini.",
  str_voice_1601311_40 = "Jangan takut.",
  str_voice_1601311_41 = "Sama-sama.",
  str_voice_1601311_42 = "Ritual yang sempurna!",
  str_voice_1601311_43 = "Sebuah penyesalan yang tak boleh terulang…",
  str_voice_1601311_44 = "Aku harus lebih banyak mempelajari sejarah tempat ini.",
  str_voice_1601311_45 = "Sama-sama.",
  str_voice_1601311_46 = "Maaf merepotkanmu.",
  str_voice_1601311_47 = "Apa kau sudah mempersiapkannya sejak lama?",
  str_voice_1601311_48 = "Aku harus memikirkan baik-baik hadiah balasannya.",
  str_voice_1601311_49 = "Sejak saat itu Northland tidak berubah. Semua orang kecuali aku percaya bahwa aku adalah \"roh gunung\"…",
  str_voice_1601311_50 = "Bagaimana cara melindungi orang-orang yang penting bagi kita dan negeri yang damai ini? Bertahun-tahun lamanya aku mencari jawaban atas pertanyaan ini.",
  str_voice_1601311_51 = "Saat yang penuh ketenangan ini adalah hadiah paling berharga yang pernah kudapatkan. Sepertinya aku telah menemukan cara untuk melindungi Northland.",
  str_voice_1601311_52 = "Alchemy Stars.",
  str_voice_1601311_53 = "Oh?",
  str_voice_1601311_54 = "Ah, pagi yang indah.",
  str_voice_1601311_55 = "Kau lelah?",
  str_voice_1601311_56 = "Kalau begitu, selama malam.",
  str_voice_1601311_57 = "Semoga kau merasa bahagia dan damai di tahun ini.",
  str_voice_1501321_1 = "Hihi, kau suka tanda di leherku? Hati-hati. Jangan sentuh, ya. Nanti kau tersambar petir! Hahaha, kau benar-benar percaya?",
  str_voice_1501321_2 = "Lu la la, lu la… Hihi, suka mendengarku beryanyi, ya? Tentu saja kau harus makan permen agar suaramu merdu!",
  str_voice_1501321_3 = "Gemuk itu tidak apa-apa, kok. Menurutku sih bukan masalah. Walaupun gemuk, setiap hari aku merasa gembira.",
  str_voice_1501321_4 = "Suka atau tidak, kau tetap harus hidup. Jadi, kenapa harus menyiksa diri dengan bersedih? Iya, 'kan, orang asing?",
  str_voice_1501321_5 = "Orang asing, kenapa kau tidak bisa menggunakan Luminatics? Lalu kenapa kau bisa memberi komando pada orang lain? Tolong beri tahu aku…! Kepalaku seakan-akan mau meledak gara-gara memikirkannya.",
  str_voice_1501321_6 = "Ini takdir yang kejam. Kau harus mengurangi waktu tidur dan bermainmu saat sudah dewasa. Namun, kau juga bisa mendapat lebih banyak permen!",
  str_voice_1501321_7 = "Seleramu bagus juga, orang asing! Aku sendiri juga suka gaun merah yang kupakai ini!",
  str_voice_1501321_8 = "Pssst, kuberi tahu rahasia, ya… Aku makan sambil tidur. Apa yang aku makan? Hihi, rahasia, dong!",
  str_voice_1501321_9 = "Aku membuat keik madu penuh cinta untukmu, orang asing! Voila! Eh, sebentar. Keiknya hilang… Apa sudah aku makan, ya?",
  str_voice_1501321_10 = "Kau sedang melamun, ya, orang asing? Bagaimana kalau kita menyanyi bersama? Ehem… La la la, la la la…!",
  str_voice_1501321_11 = "Luar biasa, aku belum pernah kemari sebelumnya! Aku boleh melihat-lihat, 'kan? Iya, 'kan?",
  str_voice_1501321_12 = "Sebagian besar wilayah Northland sangat dingin. Bagaimana kau bisa menangkal hawa dingin ini tanpa permen?",
  str_voice_1501321_13 = "Jangan kira aku hanya gadis manis biasa. Aku juga bertanggung jawab untuk melindungi kampung halamanku!",
  str_voice_1501321_14 = "Wow! Aku memecahkan rekor \"Durasi Terlama Tanpa Tidur\" saking bersemangatnya!",
  str_voice_1501321_15 = "Betapa membosankannya hari ini… Hihi, bercanda, kok. Selamat ulang tahun!",
  str_voice_1501321_16 = "Jangan mau dibatasi aturan makan tiga kali sehari. Lihat aku! Aku bisa makan berkali-kali dalam sehari!",
  str_voice_1501321_17 = "Aroma apa itu? Jangan harap kau bisa membujukku turun dari ranjang dengan makanan lezat…! Yah, kau berhasil, sih.",
  str_voice_1501321_18 = "Kau dengar itu? Ranjangku yang nyaman dan empuk memanggilku!",
  str_voice_1501321_19 = "Kok kau belum tidur? Tidur sana. Kalau tidak, nanti… pertumbuhanmu terhenti.",
  str_voice_1501321_20 = "Northland memiliki madu terbaik di seluruh dunia, tanpa terkecuali!",
  str_voice_1501321_21 = "Kudengar para pedagang di Umbraton mencari nafkah tanpa memedulikan nyawa mereka. Apa itu benar?",
  str_voice_1501321_22 = "Tentu saja Demi Utara!",
  str_voice_1501321_23 = "Kalau melihat Eclipsite, pasti aku akan langsung membidik dan menembaknya. Tak perlu ditanyakan lagi!",
  str_voice_1501321_24 = "Ratu sangat lembut. Dia menyelamatkan hidupku dan mengajariku Luminatics.",
  str_voice_1501321_25 = "Nona Narcissus mungkin terlihat pendiam, tapi acara Codeword yang dia selenggarakan di Lake Mirror selalu meriah!",
  str_voice_1501321_26 = "Hmm, aku mencium aroma keik madu yang baru saja matang!",
  str_voice_1501321_27 = "Aku tak mau keluar rumah tanpa mengenakan gaun yang indah.",
  str_voice_1501321_28 = "Dalam sekejap saja Colossus sudah terbang jauh, 'kan? Keren sekali!",
  str_voice_1501321_29 = "Halo, orang asing. Kau mau mengunjungi Northland? Aku bisa memandumu ke sana! Panggil saja aku Lola!",
  str_voice_1501321_30 = "Tidurku sangat nyenyak!",
  str_voice_1501321_31 = "Hmm, nafsu makanku sudah kembali.",
  str_voice_1501321_32 = "Kita bisa pergi lebih jauh!",
  str_voice_1501321_33 = "Sekarang kita bisa menjaga Northland dengan lebih baik!",
  str_voice_1501321_34 = "Memilihku tak akan pernah salah!",
  str_voice_1501321_35 = "Benar, tidurku nyenyak!",
  str_voice_1501321_36 = "Kapan giliranku?",
  str_voice_1501321_37 = "Bangkitlah, sihir yang tertidur!",
  str_voice_1501321_38 = "Mekarlah, mawar putih liar!",
  str_voice_1501321_39 = "KETEMU!",
  str_voice_1501321_40 = "Berhentilah berlari!",
  str_voice_1501321_41 = "Hihi, seleramu bagus juga!",
  str_voice_1501321_42 = "Hihi, saatnya tidur siang yang nyenyak!",
  str_voice_1501321_43 = "Keik madunya hancur…",
  str_voice_1501321_44 = "Aku sanggup melihatnya seharian!",
  str_voice_1501321_45 = "Wow, ini untukku?",
  str_voice_1501321_46 = "Hihi, kesukaanku!",
  str_voice_1501321_47 = "Ini… donburi madu?",
  str_voice_1501321_48 = "Hiks… Kau memang paling mengerti aku…",
  str_voice_1501321_49 = "Konon, sejak kecil aku punya bakat luar biasa untuk tidur… Jangan mengejekku! Kata orang tuaku, makan dan tidur dengan mudah adalah berkah!",
  str_voice_1501321_50 = "Aku menyusuri jalan setapak hingga ke hutan seorang diri demi mencari madu yang manis. Di sana, aku menemukan semak mawar liar berwarna seputih salju.",
  str_voice_1501321_51 = "Setiap Tahun Baru, aku mengunjungi Yang Mulia Ratu di Winter Palace dengan berbekal makanan khas kampung halamanku… Tidak, itu bukan karena aku suka keluyuran!",
  str_voice_1501321_52 = "Alchemy Stars!",
  str_voice_1501321_53 = "La la la!",
  str_voice_1501321_54 = "Selamat… pagi…",
  str_voice_1501321_55 = "Oh, aromanya lezat!",
  str_voice_1501321_56 = "Aku bisa tidur lagi!",
  str_voice_1501321_57 = "Tahun baru telah tiba, bergembiralah!",
  str_voice_1601331_1 = "Benar, aku memang pelayan, tapi bukan pelayanmu!",
  str_voice_1601331_2 = "Menggendongmu? Tidak mau! Punggungku hanya untuk Kobayashi!",
  str_voice_1601331_3 = "Membosankan sekali…! Apa tak ada pekerjaan rumah tangga untukku?",
  str_voice_1601331_4 = "Ketakutan? Memangnya naga adalah sesuatu yang langka di dunia ini?",
  str_voice_1601331_5 = "Jangan dekat-dekat! Menurut instingku, aku tidak suka padamu.",
  str_voice_1601331_6 = "Apa? Kau mau berhenti? Namun, aku belum puas!",
  str_voice_1601331_7 = "Kobayashi?! Oh, sebentar. Kau rupanya.",
  str_voice_1601331_8 = "Aku terbiasa dengan dunia yang seperti ini. Ini memang bukan tempat terbaik, tapi setidaknya masih bisa ditoleransi.",
  str_voice_1601331_9 = "Selamat datang kembali! Makanannya sudah siap. Makanlah. Kalau tidak, aku bakal marah!",
  str_voice_1601331_10 = "Hoamm… Aduh, aku masih harus mencuci pakaian…",
  str_voice_1601331_11 = "Siap! Pekerjaan rumah tangga adalah keahlianku!",
  str_voice_1601331_12 = "Gaunku ini sebenarnya sisik, jadi aku tak perlu menggantinya tiap hari!",
  str_voice_1601331_13 = "Oh, aku hanya ingin sedikit meregangkan tubuh… Tenang saja, aku tak akan meratakan tempat ini.",
  str_voice_1601331_14 = "Ekorku sangat lezat! Namun, kenapa Kobayashi selalu menolak memakannya, ya?",
  str_voice_1601331_15 = "Kejutan! Aku tahu ini hari yang penting bagimu!",
  str_voice_1601331_16 = "Kau datang juga! Ada rencana untuk hari ini?",
  str_voice_1601331_17 = "Hari yang indah! Namun, pelayan harus mulai bekerja begitu fajar menyingsing!",
  str_voice_1601331_18 = "Waktu berlalu…",
  str_voice_1601331_19 = "Semoga aku memimpikan Kobayashi lagi!",
  str_voice_1601331_20 = "Kita boleh bicara semaunya di dunia ini. Teman-temanku pasti akan menyukai tempat ini!",
  str_voice_1601331_21 = "Terlepas dari dunia mana pun, selalu ada pertempuran dan korban. Betapa menyedihkan.",
  str_voice_1601331_22 = "Demi Kobayashi, taklukkan dunia baru!",
  str_voice_1601331_23 = "Apa? Ada ras yang jauh lebih lemah dan bodoh dari manusia?",
  str_voice_1601331_24 = "Fafnir? Yah, dia memang begitu.",
  str_voice_1601331_25 = "Cih, bahkan Elma saja mengekor. Dia memang tak bisa disingkirkan…",
  str_voice_1601331_26 = "Untungnya, aku sudah menyembunyikan salah satu handuk Kobayashi! Ada aroma tubuhnya! Terima kasih!",
  str_voice_1601331_27 = "Aku benci telur tanpa bagian kuningnya. Temanku, Khresug, mati gara-gara itu!",
  str_voice_1601331_28 = "Apa dia juga naga? Hei, masih hidup?",
  str_voice_1601331_29 = "Namaku Tohru, pelayan Kobayashi. Apa kau tahu di mana majikanku?",
  str_voice_1601331_30 = "Hei, aku merasa sangat bertenaga!",
  str_voice_1601331_31 = "Groar! Hihi, aku hanya coba-coba menakutimu.",
  str_voice_1601331_32 = "Kau mau lihat wujudku yang sesungguhnya?",
  str_voice_1601331_33 = "Kudengar ada yang meminta dihancurkan!",
  str_voice_1601331_34 = "Hore! Ayo!",
  str_voice_1601331_35 = "Pemanasan sudah selesai.",
  str_voice_1601331_36 = "Panas, 'kan?",
  str_voice_1601331_37 = "Menyingkirlah dari hadapanku selamanya!",
  str_voice_1601331_38 = "Terbakarlah bersama seluruh dunia!",
  str_voice_1601331_39 = "Kenapa lari?",
  str_voice_1601331_40 = "Lagi! Lagi!",
  str_voice_1601331_41 = "Aku bisa!",
  str_voice_1601331_42 = "Mudah sekali!",
  str_voice_1601331_43 = "Tidak, mustahil…",
  str_voice_1601331_44 = "Ini jauh lebih besar dari rumah Kobayashi!",
  str_voice_1601331_45 = "Oh, kado, ya? Tidak biasanya.",
  str_voice_1601331_46 = "Oh, ini bagus!",
  str_voice_1601331_47 = "Terima kasih! Namun, jangan harap aku balas memberi kado.",
  str_voice_1601331_48 = "Benar, teman! Sekarang kau temanku!",
  str_voice_1601331_49 = "Tadinya aku berniat mencari bahan-bahan di dunia lain, tapi sepertinya aku justru mengacaukan transisinya.",
  str_voice_1601331_50 = "Sudah lama sekali aku tidak bertempur! Aku ikut! Aku sudah gatal ingin bertarung lagi.",
  str_voice_1601331_51 = "Sepertinya aku mencium aroma tubuh Kanna. Ini bukan dunia yang aman. Aku mengkhawatirkannya.",
  str_voice_1601331_52 = "Alchemy Stars!",
  str_voice_1601331_53 = "Hei!",
  str_voice_1601331_54 = "Pagi!",
  str_voice_1601331_55 = "Saatnya makan siang!",
  str_voice_1601331_56 = "Hoamm… Selamat malam.",
  str_voice_1601331_57 = "Selamat tahun baru. Kobayashi tidak bekerja lembur, 'kan?",
  str_voice_1601341_1 = "Aku ingin pergi ke sekolah. Teman-teman sekolah dan pelajarannya menyenangkan.",
  str_voice_1601341_2 = "Capek sekali… Matikan…",
  str_voice_1601341_3 = "Wah, gila. Itu keren.",
  str_voice_1601341_4 = "Ini bisa dimakan? Aku ingin mencicipinya.",
  str_voice_1601341_5 = "Aku ingin kongko! Kongko!",
  str_voice_1601341_6 = "Tohru bilang, orang-orang menyebalkan itu harus disingkirkan.",
  str_voice_1601341_7 = "Orang-orang di dunia ini menarik juga.",
  str_voice_1601341_8 = "Sibuk lagi hari ini? Baik, aku paham.",
  str_voice_1601341_9 = "Kongko denganku, yuk! Jangan cari alasan. Ayolah!",
  str_voice_1601341_10 = "Satu semut kecil… Dua semut kecil…",
  str_voice_1601341_11 = "Aku mengamatimu.",
  str_voice_1601341_12 = "Aku bisa menciptakan petir. Lihat. Keren, 'kan?",
  str_voice_1601341_13 = "Lapar… Kapan aku boleh makan lagi?",
  str_voice_1601341_14 = "Aku tahu, anak-anak nakal diusir dari rumah…",
  str_voice_1601341_15 = "Selamat ulang tahun. Bolehkah aku ikut merayakannya denganmu?",
  str_voice_1601341_16 = "Ada bersenang-senang dalam jadwal hari ini. Yah, selalu ada bersenang-senang dalam jadwal setiap hari.",
  str_voice_1601341_17 = "Pagi. Hoamm… Sangat mengantuk. Selamat malam.",
  str_voice_1601341_18 = "Di sini gelap. Tohru bilang ada serangga yang bisa bercahaya di malam hari. Aku ingin menangkap beberapa. Pasti rasanya lezat.",
  str_voice_1601341_19 = "Besok kau mau mengajakku kongko di mana? Aku sudah tidak sabar!",
  str_voice_1601341_20 = "Semua orang sangat baik dan lembut. Aku suka bersama dengan mereka.",
  str_voice_1601341_21 = "Apa aku bisa menjadi teman kalian semua?",
  str_voice_1601341_22 = "Dunia-dunia baru akan ditaklukkan.",
  str_voice_1601341_23 = "Kalau makan ini, nanti sakit perut.",
  str_voice_1601341_24 = "Tohru menjagaku. Aku suka Tohru.",
  str_voice_1601341_25 = "Kata Kobayashi, Fafnir adalah Otaku. Apa artinya Otaku?",
  str_voice_1601341_26 = "Barang-barang manis, aku suka. Barang-barang cantik, aku juga suka.",
  str_voice_1601341_27 = "Rasanya membosankan kalau sendirian. Aku tak mau membosankan.",
  str_voice_1601341_28 = "Besar sekali! Bisakah dia jadi teman baruku?",
  str_voice_1601341_29 = "Aku Kanna. Aku tersesat. Dan lapar. Punya makanan? Baik, aku akan ikut denganmu.",
  str_voice_1601341_30 = "Sudah terisi ulang.",
  str_voice_1601341_31 = "Apa aku boleh memakai kekuatan yang lebih besar?",
  str_voice_1601341_32 = "Saatnya untuk serius.",
  str_voice_1601341_33 = "Aku bosan, mati saja sana.",
  str_voice_1601341_34 = "Aku akan berusaha lebih keras.",
  str_voice_1601341_35 = "Aku siap!",
  str_voice_1601341_36 = "Lihat, lihat.",
  str_voice_1601341_37 = "Kanna tak akan kalah.",
  str_voice_1601341_38 = "Tusuk, singkirkan.",
  str_voice_1601341_39 = "Datanglah petir.",
  str_voice_1601341_40 = "Kkkkkrak!",
  str_voice_1601341_41 = "Jaga sikap, teman-teman.",
  str_voice_1601341_42 = "Bagus sekali, teman-teman.",
  str_voice_1601341_43 = "Ini tidak menyenangkan…",
  str_voice_1601341_44 = "Aku senggang, nih. Sedang menunggu orang yang bisa diajak kongko.",
  str_voice_1601341_45 = "Hadiah! Aku suka hadiah!",
  str_voice_1601341_46 = "Oh, manis sekali!",
  str_voice_1601341_47 = "Terima kasih! Masih ada yang lain?",
  str_voice_1601341_48 = "Aku suka! Hadiahnya dan kau!",
  str_voice_1601341_49 = "Tersesat saat mau pulang, lalu malah masuk ke hutan.",
  str_voice_1601341_50 = "Rasanya menarik bisa menjumpai banyak makanan yang belum pernah kulihat sebelumnya.",
  str_voice_1601341_51 = "Melihat naga terbang di langit. Karena terlihat tidak asing, jadi kuikuti saja.",
  str_voice_1601341_52 = "Alchemy Stars.",
  str_voice_1601341_53 = "Halo.",
  str_voice_1601341_54 = "Selamat pagi.",
  str_voice_1601341_55 = "Selamat siang.",
  str_voice_1601341_56 = "Selamat malam.",
  str_voice_1601341_57 = "Selamat tahun baru! Sudah membuat permohonan? Permohonanku adalah… Sebentar, Kobayashi bilang aku tak boleh memberitahukannya pada orang lain.",
  str_voice_1501351_1 = "Yah, Tohru memang bisa membuka pintu antardunia. Aku sih tidak bisa. Meski tidak bersekolah di tempat yang sama, kekuatan kami jelas sebanding.",
  str_voice_1501351_2 = "Kehadiran naga akan mengacaukan tatanan dunia ini, jadi aku harus segera pulang… Tentu setelah makan sampai kenyang.",
  str_voice_1501351_3 = "Crunchy Munchy Crunch? Sandstone Rice? King Crab Tendies? Belum pernah dengar. Cepat, aku mau mencicipinya!",
  str_voice_1501351_4 = "Agar bisa membaur dengan lebih baik di dunia ini, aku harus mempelajari aturannya. Dengan kata lain, cari pekerjaan.",
  str_voice_1501351_5 = "Aku bisa belajar. Dulu aku tidak banyak berlatih menangani berkas, sih… Apa? Itu pujian?",
  str_voice_1501351_6 = "Dulu namaku adalah Seika the Miko, tapi aku tak butuh pengorbanan… lagi pula pengorbanan rasanya hambar. Keteraturan adalah sumber kekuatanku.",
  str_voice_1501351_7 = "Makanan gourmet, seperti crepe ini, adalah bagian terpenting dalam rutinitas harianku. Kau mau? Silakan mencicipi.",
  str_voice_1501351_8 = "Aku stres gara-gara pekerjaan kantor. Namun, karena sudah ada di sini, aku mau menikmati kehidupan dunia ini saja.",
  str_voice_1501351_9 = "Mengorbankan diri untuk memimpin orang lain… Kau jadi tulang punggung seperti Kobayashi. Namun, jangan memaksakan diri. Aku juga masih mampu.",
  str_voice_1501351_10 = "Anu, kenapa kau menatapku?",
  str_voice_1501351_11 = "Kita harus bekerja demi sesuap nasi meskipun masih harus dibayar ekstra jika bekerja lembur.",
  str_voice_1501351_12 = "Ini adalah keputusan yang sulit diambil! Pasta gigi rasa anggur atau stroberi…?",
  str_voice_1501351_13 = "Tetaplah waspada hingga pekerjaan selesai! Nah, kalau begitu, ayo kita cari tempat untuk memasak barbeku.",
  str_voice_1501351_14 = "Lihat-lihat apa kau? Aduh, tandukku kelihatan lagi!",
  str_voice_1501351_15 = "Besar sekali keiknya! Ini hari ulang tahunmu, ya?",
  str_voice_1501351_16 = "Perutku tak mau berhenti keroncongan… Aku jadi stres kalau lapar.",
  str_voice_1501351_17 = "Bagaimana sarapanmu tadi? Nanti makanannya jadi dingin kalau kau makan pelan-pelan.",
  str_voice_1501351_18 = "Sudah malam rupanya! Aku mau tidur lebih awal, harus bekerja besok.",
  str_voice_1501351_19 = "Belum tidur, ya? Sepertinya kau juga punya banyak pekerjaan…",
  str_voice_1501351_20 = "Keteraturan adalah kunci Harmony Faction. Kita tidak boleh mengusik dan menghancurkan tatanan yang sudah ada sebelumnya di dunia lain.",
  str_voice_1501351_21 = "Orang-orang yang disebut pengikut kekacauan itu hanya ingin membunuh dan menghancurkan… Sebaiknya jangan dekat-dekat mereka.",
  str_voice_1501351_22 = "Taklukkan… Eh, tidak, ganti jadi lindungi dunia baru!",
  str_voice_1501351_23 = "Eclipsite sama kejam dan kejinya dengan kekacauan.",
  str_voice_1501351_24 = "Tohru bertingkah semaunya, benar-benar aneh dan tak terkendali… Namun, itu juga kenapa aku iri padanya.",
  str_voice_1501351_25 = "Aku bisa ikut bertarung karena Takiya memegang dua peran ganda. Dia bekerja terlalu keras…",
  str_voice_1501351_26 = "Roti mentega langsung membuatku tak berdaya saat pertama kali mencicipinya! Cokelat mentah juga sangat menarik!",
  str_voice_1501351_27 = "Di mana-mana kacau! Aku harus segera menyeimbangkannya. Kalau tidak, aku bakal merasa terganggu seharian!",
  str_voice_1501351_28 = "Apa ada tempat untuk memasak makanan di Colossus?",
  str_voice_1501351_29 = "Elma Joui, sekarang bertugas di Jigokumeguri System Engineering Inc., senang bertemu denganmu! Apa boleh mengucapkan salam seperti itu di dunia ini?",
  str_voice_1501351_30 = "Kekuatan makanan manis!",
  str_voice_1501351_31 = "Mana terisi kembali!",
  str_voice_1501351_32 = "Berdoalah padaku!",
  str_voice_1501351_33 = "Kekuatan untuk menguasai air!",
  str_voice_1501351_34 = "Nih!",
  str_voice_1501351_35 = "Siap.",
  str_voice_1501351_36 = "Waspadalah!",
  str_voice_1501351_37 = "Bersihkan kotoran!",
  str_voice_1501351_38 = "Bertobatlah!",
  str_voice_1501351_39 = "Enyah!",
  str_voice_1501351_40 = "Orang sesat!",
  str_voice_1501351_41 = "Selesaikan masalah ini denganku!",
  str_voice_1501351_42 = "Tadinya kupikir ini mudah.",
  str_voice_1501351_43 = "Aku harus merenung…",
  str_voice_1501351_44 = "Aku boleh tinggal di sini dengan gratis?",
  str_voice_1501351_45 = "Dibayar setiap bulan.",
  str_voice_1501351_46 = "Ini bonus karena kerja lembur?",
  str_voice_1501351_47 = "Kuhargai kepedulianmu.",
  str_voice_1501351_48 = "Aku membuat amulet ini untukmu!",
  str_voice_1501351_49 = "Meski hanya perwakilan Order, kuratakan setengah dari rumah Kobayashi saat pertama kali aku ke sana, ditambah seluruh gunung juga. Oh, apa yang telah kuperbuat…",
  str_voice_1501351_50 = "Aku lahir di dalam air, tapi tak bisa berubah menjadi air. Aku hanya bisa memperkuat tekadku untuk memegang teguh tujuan…",
  str_voice_1501351_51 = "Aku iri pada orang-orang yang bisa terbang bebas. Namun, kebebasan sendiri adalah masalah yang rumit.",
  str_voice_1501351_52 = "Alchemy Stars.",
  str_voice_1501351_53 = "Kau di sana, PlayerName?",
  str_voice_1501351_54 = "Selamat pagi.",
  str_voice_1501351_55 = "Selamat siang. Bagaimana keadaanmu?",
  str_voice_1501351_56 = "Sudah malam.",
  str_voice_1501351_57 = "Selamat tahun baru! Kenyangkan perutmu dengan makanan lezat hari ini.",
  str_voice_1501361_1 = "Nama asliku sulit diucapkan, jadi panggil saja aku Lucoa… Ada apa? Kau tak mau memanggilku dengan nama itu?",
  str_voice_1501361_2 = "Aku bukan iblis! Sebenarnya, justru sebaliknya. Aku adalah dewi… Yah, pokoknya begitu.",
  str_voice_1501361_3 = "Mantan majikanku menyebutku iblis. Entah apa maksudnya. Bagaimana menurutmu?",
  str_voice_1501361_4 = "Aku tidak suka bersikap serius karena itu tidak perlu.",
  str_voice_1501361_5 = "Mempertahankan keseimbangan dunia adalah tugasku. Sepertinya sebentar lagi jam istirahatku selesai.",
  str_voice_1501361_6 = "Menyingkirkan kenangan yang tak menyenangkan dan mengubah keadaan yang tak menyenangkan. Begitulah cara hidupku dan privileseku.",
  str_voice_1501361_7 = "Nah, karena kita sudah membuat perjanjian, aku akan mendengarkanmu untuk saat ini. Namun, asal tahu saja… aku bisa mengingkarinya kapan pun!",
  str_voice_1501361_8 = "Mudah sekali bagi dewa untuk membuat makhluk fana kelabakan… Ups, maaf, aku salah bicara.",
  str_voice_1501361_9 = "Kau tidak suka dipeluk? Baiklah, akan kuingat itu.",
  str_voice_1501361_10 = "Hei, bisa dengar aku? Ada orang di rumah?",
  str_voice_1501361_11 = "Huh, baiklah. Aku akan jaga sikap untuk sementara.",
  str_voice_1501361_12 = "Menyebalkan sekali. Aku tak pernah bisa menemukan pakaian yang pas…",
  str_voice_1501361_13 = "Anak-anak juga ikut? Bagus, rasanya seperti karyawisata saja!",
  str_voice_1501361_14 = "Hah? Apa yang kulakukan setelah aku mabuk…? Jangan dengar apa kata Tohru. Dia bohong!",
  str_voice_1501361_15 = "Selamat ulang tahun! Mau hadiah apa? Aku bisa memberimu apa pun yang kau inginkan!",
  str_voice_1501361_16 = "Selamat siang. Semalam aku tidak mengganggumu, 'kan?",
  str_voice_1501361_17 = "Aduh, aku belum mau bangun…",
  str_voice_1501361_18 = "Matahari sudah terbenam. Lagi-lagi tidak melakukan apa pun hari ini. Sangat menyenangkan!",
  str_voice_1501361_19 = "Tidak mengantuk? Yah, aku bisa membacakanmu cerita pengantar tidur!",
  str_voice_1501361_20 = "Meskipun aneh, kalian semua memang anak yang baik.",
  str_voice_1501361_21 = "Dunia ini bekerja dengan caranya sendiri, jadi sebaiknya aku tak ikut campur.",
  str_voice_1501361_22 = "Dunia baru untuk ditaklukkan!",
  str_voice_1501361_23 = "Sama sepertiku, anak-anak itu terlahir untuk menjaga keseimbangan.",
  str_voice_1501361_24 = "Tohru jadi lebih rendah hati sejak bertemu Kobayashi.",
  str_voice_1501361_25 = "Apa Kanna sudah menyesuaikan diri? Kau harus selalu mengawasinya. Dia selalu penasaran pada apa pun.",
  str_voice_1501361_26 = "Kalau soal bersantai, Shouta ahlinya!",
  str_voice_1501361_27 = "Aku mencium bau alkohol! Tidak, aku sudah berusaha untuk tidak minum belakangan ini…",
  str_voice_1501361_28 = "Memiloti benda ini pasti tidak mudah.",
  str_voice_1501361_29 = "Mulai sekarang kau adalah majikanku, untuk sementara.",
  str_voice_1501361_30 = "Wah, ini makin menarik saja.",
  str_voice_1501361_31 = "Mau lebih mengenalku?",
  str_voice_1501361_32 = "Kemarilah, aku mau memberitahumu beberapa \"rahasia\".",
  str_voice_1501361_33 = "Bersiaplah untuk menghadapi dewa.",
  str_voice_1501361_34 = "Aku datang!",
  str_voice_1501361_35 = "Harus dengan cara ini?",
  str_voice_1501361_36 = "Aku tidak mahir bertarung.",
  str_voice_1501361_37 = "Ini akan sedikit menyakitkan…",
  str_voice_1501361_38 = "Kau akan melihat pencerahan.",
  str_voice_1501361_39 = "Hukum alam.",
  str_voice_1501361_40 = "Kekuatan alam semesta.",
  str_voice_1501361_41 = "Lihat ini, teman-teman!",
  str_voice_1501361_42 = "Tidak ada pujian atau sanjungan sedikit pun?",
  str_voice_1501361_43 = "Dasar ceroboh.",
  str_voice_1501361_44 = "Aku jadi mengantuk… Iya, 'kan?",
  str_voice_1501361_45 = "Terima kasih, aku akan merawatnya!",
  str_voice_1501361_46 = "Bagaimana kau bisa tahu seleraku?",
  str_voice_1501361_47 = "Apa maksudmu dengan memberiku hadiah ini?",
  str_voice_1501361_48 = "Ini hal kedua yang paling kuinginkan…!",
  str_voice_1501361_49 = "Bagaimana aku kemari? Yah, aku tahu Tohru membuka gerbang yang salah. Namun, aku mengikutinya karena penasaran.",
  str_voice_1501361_50 = "Orang-orang selalu menatapku… Memangnya penampilanku sangat mencolok, ya?",
  str_voice_1501361_51 = "Karena mendengar ada yang memanggil, aku pun datang. Namun, apa sebenarnya yang kau coba panggil saat itu?",
  str_voice_1501361_52 = "Alchemy Stars.",
  str_voice_1501361_53 = "Selamat siang.",
  str_voice_1501361_54 = "Selamat pagi.",
  str_voice_1501361_55 = "Aku boleh tidur siang sekarang?",
  str_voice_1501361_56 = "Sudah malam!",
  str_voice_1501361_57 = "Selamat tahun baru! Perayaan masa kini sangat berbeda dengan yang dulu.",
  str_voice_1401371_1 = "Kepala pelayan? Kau menghinaku, ya? Aku tak mau melayani siapa pun.",
  str_voice_1401371_2 = "Aku sedang bermain. Nanti saja.",
  str_voice_1401371_3 = "Keberanian adalah kebajikan? Kalau begitu, aku sudah menyingkirkan ratusan korban yang berbudi luhur.",
  str_voice_1401371_4 = "Ketamakan adalah sifat kedua pada manusia. Mereka hanya peduli pada pencarian, bukan apa yang mereka cari.",
  str_voice_1401371_5 = "Tidak bisa lari atau melawan. Takdir yang kejam sudah pasti terjadi… Itulah kutukannya.",
  str_voice_1401371_6 = "Basuh tubuhmu dengan darahku dan capailah keabadian. Sayangnya, tidak ada yang pantas mendapat kehormatan itu.",
  str_voice_1401371_7 = "Aku menulis buku. Kau boleh membacanya jika tertarik. Sepertinya seleramu bagus.",
  str_voice_1401371_8 = "Permainan di dunia ini lumayan juga. Hoi, cepatlah. Acaranya sudah dimulai.",
  str_voice_1401371_9 = "Ada orang yang bisa dan tak bisa kita jadikan teman. Untuk yang kedua, sekali pandang saja kita akan langsung tahu. Namun, butuh waktu untuk yang pertama.",
  str_voice_1401371_10 = "Hei, berapa lama lagi kau minta aku menunggu?",
  str_voice_1401371_11 = "Jangan suruh-suruh aku.",
  str_voice_1401371_12 = "Tentu saja aku tak suka penampilanku yang sekarang. Aku benci terlihat sama seperti kalian!",
  str_voice_1401371_13 = "Doujinshi ini untuk konvensi komik yang akan datang. Pasti akan laris manis!",
  str_voice_1401371_14 = "Permainan akan terasa bermakna jika kita sekarat. Lagi pula, tak ada yang bisa menyingkirkanku, sih.",
  str_voice_1401371_15 = "Harus semembosankan apa sih sampai-sampai kita harus merayakan hari kelahiran?",
  str_voice_1401371_16 = "Ya, hari baru, teruslah menghitung mundur hingga kita mati.",
  str_voice_1401371_17 = "Kau sangat peduli tentang waktu. Namun, siang dan malam tak ada bedanya bagiku.",
  str_voice_1401371_18 = "Makan malam? Sama sekali tidak tertarik… Eh, sebentar, apa itu kari manis?",
  str_voice_1401371_19 = "Aku tidak tidur. Silakan saja kalau kau mau.",
  str_voice_1401371_20 = "Sungguh tak bisa diandalkan. Jangan menimbulkan masalah.",
  str_voice_1401371_21 = "Asalkan aku tidak terganggu.",
  str_voice_1401371_22 = "Hancurkan dunia ini.",
  str_voice_1401371_23 = "Kau dan mereka tak ada bedanya. Namun, yang namanya sampah memang harus didaur ulang.",
  str_voice_1401371_24 = "Aku sudah lama mengenal Tohru. Kami punya cara bersikap yang sama.",
  str_voice_1401371_25 = "Aku menghargai betapa kuatnya Lucoa.",
  str_voice_1401371_26 = "Kau memang lemah, tapi harus kuakui bahwa permainanmu menarik.",
  str_voice_1401371_27 = "Basmi semua penyusup dan penjarah!",
  str_voice_1401371_28 = "Orang yang malang. Perasaan kehendak bebas yang salah dalam wadah palsu, seperti boneka.",
  str_voice_1401371_29 = "Aku Fafnir. Aku menoleransi kehadiranmu di dunia yang membosankan ini, tapi jangan buat aku marah.",
  str_voice_1401371_30 = "Sudah naik level.",
  str_voice_1401371_31 = "Aku sangat gelisah sekarang.",
  str_voice_1401371_32 = "Singkirkan, singkirkan, singkirkan.",
  str_voice_1401371_33 = "Aku tak dengar ada yang memohon.",
  str_voice_1401371_34 = "Minggir.",
  str_voice_1401371_35 = "Waktunya habis.",
  str_voice_1401371_36 = "Ritual dimulai.",
  str_voice_1401371_37 = "Takdirmu sudah ditentukan.",
  str_voice_1401371_38 = "Mengikuti laksana bayangan!",
  str_voice_1401371_39 = "Berjuanglah.",
  str_voice_1401371_40 = "Tak ada penyintas.",
  str_voice_1401371_41 = "Kalian semua, tunggu perintahku.",
  str_voice_1401371_42 = "Cih.",
  str_voice_1401371_43 = "Kenapa mereka…",
  str_voice_1401371_44 = "Berusahalah sebaik mungkin.",
  str_voice_1401371_45 = "Apa ini? Penghormatan?",
  str_voice_1401371_46 = "Hanya ini kemampuanmu?",
  str_voice_1401371_47 = "Baiklah, akan kuterima.",
  str_voice_1401371_48 = "Huh, memang itu yang kutunggu.",
  str_voice_1401371_49 = "Seseorang membuka gerbang dan menyeretku kemari. Kalau tidak salah, Tohru orangnya.",
  str_voice_1401371_50 = "Baru saja bertemu dengan beberapa orang kasar. Namun, itu tinggal sejarah, seperti mereka.",
  str_voice_1401371_51 = "Aku akan disingkirkan oleh seorang pembantai naga bernama Siegfried? Konyol sekali.",
  str_voice_1401371_52 = "Alchemy Stars.",
  str_voice_1401371_53 = "Mmm.",
  str_voice_1401371_54 = "Selamat pagi.",
  str_voice_1401371_55 = "Terang sekali.",
  str_voice_1401371_56 = "Oh, rupanya sudah malam.",
  str_voice_1401371_57 = "Ini Tahun Baru. Kau mau kukutuk?",
  str_voice_1601381_1 = "Kalau menemukan relik kuno, sebaiknya kau menyerahkannya pada Illumina Research Center. Itulah satu-satunya tempat yang mampu memperbaikinya. Namun, tentu saja, akan lebih baik kalau kau bisa menyerahkannya kepadaku.",
  str_voice_1601381_2 = "Meskipun aku percaya pada sains, itu tidak menjelaskan segalanya. Misalnya, kalau kita ingin menemukan reruntuhan yang berharga… mungkin itu hanya keberuntungan belaka.",
  str_voice_1601381_3 = "Relik kuno bisa bicara. Namun, tentu saja tidak secara harfiah! Relik kuno menyampaikan pesannya melalui jejak yang ditinggalkan.",
  str_voice_1601381_4 = "Jangan takut. Laba-laba mungilku manis, kok. Mereka banyak membantuku saat aku mempelajari reruntuhan kuno.",
  str_voice_1601381_5 = "Bagaimana caranya orang yang bisa menciptakan peradaban kuno nan agung tahu-tahu lenyap? Aku masih mencoba untuk mencari tahu.",
  str_voice_1601381_6 = "Bekerja berkaitan dengan pemecahan masalah dan hal terburuk yang bisa kita lakukan saat memecahkan masalah adalah terbawa emosi. Namun, tentu saja kita boleh menumpahkan segalanya begitu selesai bekerja.",
  str_voice_1601381_7 = "Angka \"3\" adalah bilangan ganjil dan bilangan bulat. Angka harmoni dan stabilitas, mewakili awal dan akhir, sempurna apa adanya. Karena itu, \"3\" adalah angka keberuntunganku!",
  str_voice_1601381_8 = "Apa kau benar-benar ingin tahu kenapa aku mengungkapkan proses pemikiranku? Haha, itu sebenarnya kebiasaan burukku sejak kecil. Oh, maksudmu itu bukan hal yang buruk?",
  str_voice_1601381_9 = "Sebenarnya aku tidak selalu memakai topeng. Apa itu benar-benar menarik minatmu? Omong-omong, sebaiknya kita tidak membicarakannya sekarang. Mari kita bicarakan setelah selesai bekerja saja, ya?",
  str_voice_1601381_10 = "Aku punya ide! Kalau tidak ada banyak pekerjaan, bagaimana jika kita pulang lebih cepat dan minum-minum sedikit? Dan mungkin makan sate pedas… Nyam!",
  str_voice_1601381_11 = "Terima kasih sudah mengajakku dalam tugas penelitian… Hah? Maksudmu, tidak ada tugas penelitian? Wow, sekarang sudah jarang ada tugas seperti itu!",
  str_voice_1601381_12 = "Aku tidak ingin menemukan emas, perak, atau perhiasan. Aku ingin sesuatu yang jauh lebih bernilai.",
  str_voice_1601381_13 = "Kata orang, aku tak pernah mabuk. Itu sedikit berlebihan.",
  str_voice_1601381_14 = "Laba-laba? Ahh, itu laba-laba piaraanku yang mungil.",
  str_voice_1601381_15 = "Ini hari ulang tahunmu? Aku akan ikut merayakannya setelah selesai bekerja. Jangan lupa menyisihkan satu tempat untukku, ya!",
  str_voice_1601381_16 = "Apa ada yang mengusikmu di tempat kerja? Kau boleh membicarakannya denganku. Lagi pula, tak ada masalah yang tak bisa kuselesaikan.",
  str_voice_1601381_17 = "Selamat pagi! Ini adalah saat yang tepat untuk mulai bekerja.",
  str_voice_1601381_18 = "Benar… Aku baru saja selesai bekerja. Mau minum-minum setelah ini?",
  str_voice_1601381_19 = "Orang bergadang setelah lewat tengah malam akibat salah satu dari dua alasan berikut: karena mereka memilih begitu atau karena memang harus. Kau termasuk yang mana?",
  str_voice_1601381_20 = "Tidak hanya mengajariku cara melakukan penelitian, Illumina juga memberiku kebebasan meneliti.",
  str_voice_1601381_21 = "Astaga, aku tak bisa memahami cara berpikir orang-orang Lumopolis. Bahkan kalau tak tahu cara menghargai relik pun tidak perlu menghancurkannya!",
  str_voice_1601381_22 = "Jayalah Illumina!",
  str_voice_1601381_23 = "Aku tak sudi memaafkan para Eclipsite yang menghancurkan reruntuhan kuno!",
  str_voice_1601381_24 = "Commander Gronru selalu menjadi panutanku baik dalam penelitian maupun manajemen.",
  str_voice_1601381_25 = "Terlepas dari hasil penelitiannya, aku tak pernah bisa memahami tindakan Migard.",
  str_voice_1601381_26 = "Jenis minuman fermentasi yang aku suka tidak cocok untuk anak-anak.",
  str_voice_1601381_27 = "P-permainan…? Permisi, aku baru ingat masih ada pekerjaan yang harus kuselesaikan. Silakan lanjutkan saja tanpa aku.",
  str_voice_1601381_28 = "Lihat desain aerodinamis dan teksturnya yang berkilauan… Pasti ada kisah yang menakjubkan di balik mesin terbang raksasa ini.",
  str_voice_1601381_29 = "Bentuk badan, ciri wajah, rambut, tinggi, dan gaya berpakaian… Benar, kau pasti seorang Caelestite! Aku Siobhan, dan aku sangat senang bisa mempelajarimu!",
  str_voice_1601381_30 = "Efisiensi kerjaku meningkat lagi.",
  str_voice_1601381_31 = "Aku telah melintasi waktu…",
  str_voice_1601381_32 = "Aku telah melintasi ruang…",
  str_voice_1601381_33 = "Aku telah menyaksikan segala hal yang ada di bawah langit…",
  str_voice_1601381_34 = "Dimengerti!",
  str_voice_1601381_35 = "Ayo lihat siapa yang memiliki refleks lebih bagus.",
  str_voice_1601381_36 = "Aku siap kapan pun kau siap.",
  str_voice_1601381_37 = "Waktunya habis! Rasakan ini!",
  str_voice_1601381_38 = "Jaring laba-laba!",
  str_voice_1601381_39 = "Nyam!",
  str_voice_1601381_40 = "Krauk!",
  str_voice_1601381_41 = "Baik, aku paham.",
  str_voice_1601381_42 = "Ini semua berkat komandomu yang luar biasa.",
  str_voice_1601381_43 = "Penyebab kekalahan ditemukan.",
  str_voice_1601381_44 = "Apa kau membicarakan itu? Mau kujelaskan?",
  str_voice_1601381_45 = "Apa yang kau serahkan ini relik kuno?",
  str_voice_1601381_46 = "Bisa-bisanya kau tahu apa yang kuinginkan…?",
  str_voice_1601381_47 = "Ini bukan sesuatu yang mudah didapat… Apa? Ini untukku?",
  str_voice_1601381_48 = "Caelestite memang benar-benar bisa memahami perasaan orang lain.",
  str_voice_1601381_49 = "Aku masih ingat… di ujung lubang yang dingin dan lembap itu, reruntuhan kuno pertama kali muncul di hadapanku, begitu misterius dan menggetarkan.",
  str_voice_1601381_50 = "Ulang tahunku yang paling berkesan…? Di suatu tahun saat ada banyak orang dewasa yang tak kukenal memberiku bunga. Namun, yang ingin mereka sampaikan padaku bukanlah hadiah…",
  str_voice_1601381_51 = "Aku ingin jadi seberani ayahku dan sefokus ibuku. Demi tujuan yang kucintai, bahkan kalau suatu hari aku jatuh, aku tak akan menyesal.",
  str_voice_1601381_52 = "Alchemy Stars!",
  str_voice_1601381_53 = "Halo.",
  str_voice_1601381_54 = "Saatnya bekerja.",
  str_voice_1601381_55 = "Saatnya istirahat.",
  str_voice_1601381_56 = "Apa kau masih di tempat kerja?",
  str_voice_1601381_57 = "Selamat Tahun Baru! Kurasa inilah saatnya liburan.",
  str_voice_1501391_1 = "Aku bisa mendengar bisikan dari dunia luar. Mereka tidak berasal dari dunia ini dan terus membujukku untuk membuka portal…",
  str_voice_1501391_2 = "Aku iri padamu. Kau tidak menyadari rahasia dunia dan situasimu, dan bisa menghadapi setiap hari dengan senyum riang terukir di wajahmu.",
  str_voice_1501391_3 = "Ayo, Kapten! Apa… Kau bingung, ya? Begitulah cara kaum Ancient menyebut para navigator yang memiloti mesin!",
  str_voice_1501391_4 = "Pedangku dibuat khusus dan bisa diisi dengan elemen Lumina yang berbeda untuk meningkatkan kekuatannya. Mau coba?",
  str_voice_1501391_5 = "Penduduk Lumopolis yang memuja makhluk-makhluk misterius itu secara fanatik pasti berada di bawah pengaruh mantra… Aku harus menyadarkan mereka…",
  str_voice_1501391_6 = "Kini aku telah menyatu dengan bumi dan bisa dengan lebih baik merasakan kehadiran makhluk jahat yang menyerang dunia ini.",
  str_voice_1501391_7 = "Apa kau mau tahu kebenaran tentang dunia? Kalau begitu, ikuti perjalananku yang penuh kejutan misterius…",
  str_voice_1501391_8 = "Kalau kau ingin mempelajari lebih banyak tentang Otherworld dan Realm, aku bisa meminjamimu buku-buku kuno dari koleksiku. Namun, jangan asal mencoba mantra apa pun yang ada di buku. Janji?",
  str_voice_1501391_9 = "Meskipun dunia ini tidak nyata, waktu yang kuhabiskan denganmu terasa nyata.",
  str_voice_1501391_10 = "*Hosh*… Dasar anjing angkasa sialan, kembalikan camilanku! Hah…? Rupanya hanya mimpi… Untung saja Caelestite itu tidak ada di sini. Kalau tidak, aku bakal sangat malu. Apalagi aku adalah seorang Awakened…",
  str_voice_1501391_11 = "Apa kita harus berjaga lagi? Kau pasti belum pernah mengalami kekagetan seperti saat berselimut hangat lalu tiba-tiba diterpa angin dingin… Apa? Kau bilang aku boleh berbuat semauku di sini? Kau bercanda, ya?",
  str_voice_1501391_12 = "Gula merangsang otak untuk melepas stimulan alami yang membantu kelancaran berpikir. Itu sebabnya aku selalu membawa permen.",
  str_voice_1501391_13 = "Lihat pola melingkar di latte… Ini pasti peringatan dari makhluk misterius.",
  str_voice_1501391_14 = "Tekanan udara berkurang 0,155 unit per detik. Apa Colossus sudah lepas landas?",
  str_voice_1501391_15 = "Selamat ulang tahun! Semoga kau menikmati momen damai yang tersisa di ruang ini.",
  str_voice_1501391_16 = "Kau datang! Makhluk misterius yang mengintai dari bayangan belum menyadari kehadiranmu, jadi lanjutkan saja.",
  str_voice_1501391_17 = "Tolong jangan datang sepagi ini lain kali… Aku masih mau… tidur lebih lama…",
  str_voice_1501391_18 = "Ada kekuatan jahat yang berkumpul di udara. Apa sudah waktunya…?",
  str_voice_1501391_19 = "Ilusi menjadi lebih kuat di malam hari. Kalau sampai tertidur, aku tak akan bisa melindungi Caelestite yang lemah lembut itu.",
  str_voice_1501391_20 = "Terlalu banyak ketidakpastian di Lumopolis… Di sana, kita harus selalu waspada. Kalau tidak, kita justru akan jadi target…",
  str_voice_1501391_21 = "Para siswa Illumina sangat berwawasan luas. Selain telah mempelajari relik yang tak terhitung jumlahnya, mereka pasti juga tahu banyak rahasia…",
  str_voice_1501391_22 = "Demi White Night! Benar!",
  str_voice_1501391_23 = "Eclipsite adalah ciptaan makhluk misterius, dan itu merupakan pertanda bahwa ada kekuatan misterius di sini…",
  str_voice_1501391_24 = "Presiden Florine adalah teman pertamaku sekaligus satu-satunya di Dawn Academy.",
  str_voice_1501391_25 = "Lady Uriel percaya bahwa dunia ini adalah ilusi dan suatu hari nanti akan dihancurkan. Dia pasti juga salah satu dari para Awakened.",
  str_voice_1501391_26 = "Menyenangkan bukan kalau bisa menikmati dunia sendirian?",
  str_voice_1501391_27 = "Apa yang kau baca? An Overview of Lumopolis' History… Aduh… Hanya melihat jumlah katanya saja membuatku pusing…",
  str_voice_1501391_28 = "Dengan teknologinya yang luar biasa, kaum Caelestite bisa membangun Colossus… Jangan-jangan mereka diajari oleh \"makhluk misterius\"?",
  str_voice_1501391_29 = "Halo, aku Erica. Aku tahu ada darah kuno kaum Caelestite yang mengalir di nadimu… Apakah pertemuan ini sudah digariskan sejak dulu kala? Atau apakah ini takdir?",
  str_voice_1501391_30 = "Kekuatan yang tak ada habisnya.",
  str_voice_1501391_31 = "Resonansiku dengan ilusi telah meningkat…",
  str_voice_1501391_32 = "Aku mendengar kehendak planet.",
  str_voice_1501391_33 = "Tidak ada tempat untuk sembunyi bagi makhluk dari dunia lain.",
  str_voice_1501391_34 = "Aku mau tidur lagi.",
  str_voice_1501391_35 = "Sedikit lagi…",
  str_voice_1501391_36 = "*Menghela napas* Baiklah.",
  str_voice_1501391_37 = "Lepaskan kekuatanmu, petir!",
  str_voice_1501391_38 = "Electro Flash!",
  str_voice_1501391_39 = "Berkumpullah!",
  str_voice_1501391_40 = "Revolving Beam!",
  str_voice_1501391_41 = "Jangan buat masalah.",
  str_voice_1501391_42 = "Aku mau tidur lagi.",
  str_voice_1501391_43 = "Apa aku belum sepenuhnya Awakened?",
  str_voice_1501391_44 = "Apa ini Colossus…? Sebaiknya aku bergegas merebutnya selagi si Kapten pergi…\nAhh, Kapten! Kau sudah kembali!",
  str_voice_1501391_45 = "Apa ini keahlian khusus?",
  str_voice_1501391_46 = "Tolong bawakan lebih banyak lain kali.",
  str_voice_1501391_47 = "Hadiah yang pantas untuk peradaban kuno.",
  str_voice_1501391_48 = "Ini hadiah terbaik yang pernah kuterima.",
  str_voice_1501391_49 = "Alasanku menjadi kesatria tidak serumit atau sehebat yang lain. Itu hanya karena… kakekku memaksakannya padaku, sesuatu yang semula dia harapkan pada ayahku.",
  str_voice_1501391_50 = "Dulu ayahku pernah memberiku \"buku terlarang\" yang mengubah hidupku. Karena buku itu, aku jadi tertarik pada fenomena misterius dan secara sembarangan memanggil makhluk misterius yang tidak berasal dari dunia ini…",
  str_voice_1501391_51 = "Dunia ini penuh krisis. Siapa yang tahu berapa banyak makhluk misterius yang mengawasi kita dan memiliki rencana jahat? Sebagai seorang Awakened, satu-satunya cara untuk menyelamatkan semua orang adalah dengan menyelidiki peradaban kuno dan mencari kunci solusinya…",
  str_voice_1501391_52 = "Alchemy Stars!",
  str_voice_1501391_53 = "Kapten.",
  str_voice_1501391_54 = "Tidur sebentar.",
  str_voice_1501391_55 = "Saatnya tidur siang.",
  str_voice_1501391_56 = "Saatnya bermain.",
  str_voice_1501391_57 = "Lagi-lagi tahun telah berlalu bagi Aurorian…",
  str_voice_1601401_1 = "Pedang ini lain dari yang lain, 'kan? Ini Winding Sword. Orang tuaku yang memesannya untukku dan harganya mahal sekali. Kalau kita lihat dari samping seperti ini, bentuknya mirip ular, 'kan?",
  str_voice_1601401_2 = "Dia tak bakal mau memperhatikanmu kalau kau menyebutnya ular putih kecil. Namanya Alba. Namun, sebenarnya tergantung pada suasana hati Alba sih dia mau memperhatikanmu atau tidak.",
  str_voice_1601401_3 = "Hidupku kucurahkan untuk menjalankan misi. Apa? Misi kali ini adalah mengambil cuti?",
  str_voice_1601401_4 = "Aku benci melihat orang kuat menindas yang lemah… Karenanya, aku tak akan pernah mengabaikan kejahatan semacam itu selama aku bisa melawannya.",
  str_voice_1601401_5 = "Kalau aku menerima takdirku saat itu, aku tak akan pernah bertemu denganmu… Tidak, itu bukan takdirku. God of Light adalah saksinya.",
  str_voice_1601401_6 = "Maafkan aku. Kalau Alba ketakutan, *uhuk* dia melepaskan semacam… bau-bauan. Kita akan pingsan kalau terlalu banyak menghirupnya, jadi sebaiknya kuangin-anginkan dia di luar.",
  str_voice_1601401_7 = "Orang tuaku masih berharap aku bakal melakukan sesuatu yang luar biasa. Itu sebabnya… aku tak akan pernah menyerah. Aku akan menguasai segala hal yang kulakukan.",
  str_voice_1601401_8 = "Ada sesuatu yang terasa licin dan dingin di lehermu? Ahh, jangan-jangan itu Alba? Biasanya dia tidak mau sedekat itu dengan orang lain, sih… Keluarlah, Alba…",
  str_voice_1601401_9 = "Jangan lupa memeriksa rutemu, mengemasi barangmu, dan membawa minuman serta makanan sebelum kau pergi… Eh, kenapa kau menatapku seperti itu? Maaf, aku jadi mengomel…",
  str_voice_1601401_10 = "Kalau kau tidak keberatan, bolehkah aku berlatih pedang di sini sebentar? Aku tak mau buang-buang waktu.",
  str_voice_1601401_11 = "Di sini juga ada penyelidikan, ya? Oh, rupanya berbeda… Yah, bukan masalah. Karena sudah di sini, aku berjanji akan berusaha semampuku!",
  str_voice_1601401_12 = "Kau juga suka membaca? Semoga bukan novel romansa yang membosankan.",
  str_voice_1601401_13 = "Bibirmu pecah-pecah, dan kulitmu terlihat kering. Kau lupa minum lagi, ya?",
  str_voice_1601401_14 = "Seorang kesatria sejati tak pernah menyerah sebelum bertarung. Itu pedomanku sejak kecil.",
  str_voice_1601401_15 = "Selamat ulang tahun! Bagaimana aku bisa tahu ulang tahunmu? Yah, kadang-kadang aku suka mengamati…",
  str_voice_1601401_16 = "Bukankah kita berlatih dan beristirahat agar bisa terus bekerja keras?",
  str_voice_1601401_17 = "Sebaiknya kita minum segelas air hangat setelah bangun tidur. Pokoknya harus air hangat. Kalau tidak, nanti perut kita mulas.",
  str_voice_1601401_18 = "Sebaiknya kita tidak melakukan latihan berat di jam-jam seperti ini. Dan ingat, jangan makan atau minum terlalu banyak.",
  str_voice_1601401_19 = "Pertama, berbaring di ranjang, lalu matikan perangkat hiburan. Kalau masih tidak bisa tidur, berarti kita kena insomnia.",
  str_voice_1601401_20 = "Satu-satunya tempat yang memegang teguh kehendak God of Light… Aku akan mempertahankan Lumopolis dengan segenap kekuatanku!",
  str_voice_1601401_21 = "Illumina selalu ambisius. Kuharap mereka tidak melupakan tujuan aslinya.",
  str_voice_1601401_22 = "Demi White Night!",
  str_voice_1601401_23 = "Eclipsite adalah musuh bersama semua Aurorian. Bahkan God of Light pun mengizinkan kita membasmi mereka.",
  str_voice_1601401_24 = "Kuharap Erica bisa berhenti melamun sehingga aku tidak perlu terus mencemaskannya.",
  str_voice_1601401_25 = "Hedy memang cerdas dan cekatan. Dia adalah panutanku.",
  str_voice_1601401_26 = "Aku suka menegakkan keadilan dan membela yang lemah, itu saja.",
  str_voice_1601401_27 = "Aku tidak menyukai banyak hal, dan satu-satunya yang sangat mengusikku adalah orang-orang yang menghancurkan keyakinan. Apa kedengarannya terlalu serius?",
  str_voice_1601401_28 = "Apakah Colossus juga termasuk teknologi kuno? Semoga bukan.",
  str_voice_1601401_29 = "Demi White Night! Aku Florine. Aku sudah banyak mendengar tentangmu. Namun, maaf, aku harus memastikannya dulu sebelum menyimpulkan.",
  str_voice_1601401_30 = "Kerja keras pasti akan terbayarkan.",
  str_voice_1601401_31 = "Winding Sword telah diasah.",
  str_voice_1601401_32 = "Nah, sekarang kita bisa menyelesaikannya… dengan lebih cepat!",
  str_voice_1601401_33 = "Aku sudah menunggu saat ini!",
  str_voice_1601401_34 = "Misi ini pasti akan selesai!",
  str_voice_1601401_35 = "Aku siap.",
  str_voice_1601401_36 = "Tunggu saja.",
  str_voice_1601401_37 = "Tak akan ada yang bisa lolos!",
  str_voice_1601401_38 = "Penghakiman menantimu!",
  str_voice_1601401_39 = "Razer, bangkitlah!",
  str_voice_1601401_40 = "Wrath of Razer!",
  str_voice_1601401_41 = "Aku menghargai kepercayaanmu!",
  str_voice_1601401_42 = "Ini tanggung jawabku.",
  str_voice_1601401_43 = "Tenanglah, aku tak akan menyerah…",
  str_voice_1601401_44 = "Maksudmu, kau benar-benar pemiliknya…? Tak kusangka orang sepertimu bisa memilikinya.",
  str_voice_1601401_45 = "Oh… Tidak perlu repot-repot…",
  str_voice_1601401_46 = "Wow… Aku sampai tak bisa berkata-kata…",
  str_voice_1601401_47 = "Terima kasih sudah mau repot-repot.",
  str_voice_1601401_48 = "Aku sangat menyukainya! Aku pasti akan membalas kebaikanmu!",
  str_voice_1601401_49 = "Ibuku sering linglung. Jadi, sejak masih kecil, aku sudah belajar memasak agar bisa merawatnya. Aku yakin bisa menyelesaikan pekerjaan rumah tangga apa pun tanpa masalah.",
  str_voice_1601401_50 = "Karena keluargaku tidak kaya, aku tak pernah bermimpi punya kesempatan berjalan melewati aula Dawn Academy. Namun, orang tuaku berusaha keras agar bisa membayar biaya pendidikanku…",
  str_voice_1601401_51 = "Bukan masalah kalau latar belakang kita tidak mengagumkan. Buktinya tercermin dalam kerja keras. Nyatanya, aku bisa lulus penilaian kuil dan menjadi anggota resmi Heretics Investigation Division.",
  str_voice_1601401_52 = "Alchemy Stars!",
  str_voice_1601401_53 = "Salam.",
  str_voice_1601401_54 = "Siapa yang bangun pagi, dia yang dapat rezeki.",
  str_voice_1601401_55 = "Jangan lupa minum banyak air.",
  str_voice_1601401_56 = "Jangan bergadang.",
  str_voice_1601401_57 = "Aku mau bilang sesuatu… Anu… Selamat Tahun Baru!",
  str_voice_1601411_1 = "Ayo pergi! Ke mana? Tentu saja untuk menjelajahi tempat yang tak diketahui! Jangan bilang kau sama sekali tidak tertarik.",
  str_voice_1601411_2 = "Sini, biar kuperkenalkan padamu. Ini Bently dan Lompty. Oh, kau tidak bisa membedakan keduanya, ya? Lihat ini… Bently lebih kurus dan Lompty lebih gemuk.",
  str_voice_1601411_3 = "Aneh. Di mana kutaruh tongkatku, ya? Aku yakin tadi meletakkannya di sini… Kok bisa hilang? Apa katamu? Hanya perasaanku s—Oh, ini dia! Hahaha…",
  str_voice_1601411_4 = "Jangan meremehkan tas ekspedisiku. Ada perkakas, obat-obatan, ransum makanan, air… Oh, ini Bently dan Lompty… peralatan spesialku. Heheh.",
  str_voice_1601411_5 = "Eh, aku punya ide bagus! Apa aku boleh mengikatkan mobilku ke bagian luar Colossus? Nah, dengan begitu, mobilku bisa terbang!",
  str_voice_1601411_6 = "Hahaha, hentikan…! Oh, maafkan aku. Bently dan Lompty baru saja menggelitikiku. Hei, kalian, keluar dari mantelku!",
  str_voice_1601411_7 = "Kata ibuku, aku lahir di kereta Rediesel Wrench. Menurut orang sih itu cukup keren. Bagaimana menurutmu?",
  str_voice_1601411_8 = "Aku sudah mencari ke mana-mana, dan rupanya Bently dan Lompty bersembunyi di bajumu dari tadi?! Aneh, jarang-jarang mereka merasa nyaman dengan orang lain…",
  str_voice_1601411_9 = "\"Lalala! Du bi du bi du!\" Eh, kau tahu lagu ini tidak? Oh! Kau juga penggemar Barbara, ya? Nih, ayo kita dengarkan sama-sama!",
  str_voice_1601411_10 = "Eh, anu… Kau, bicaralah padaku… Kalau terus begini, tak akan ada bedanya dengan barang antik yang terkubur…",
  str_voice_1601411_11 = "Halo! Apa aku boleh melihat-lihat? Sebentar… Aku lupa membawa peralatan ekspedisiku!",
  str_voice_1601411_12 = "Firefly di Colossus… Boleh kujadikan sebagai bola tidak? Aku sedang ingin bermain, nih…",
  str_voice_1601411_13 = "Beberapa tahun lagi, semua orang di benua ini akan mengenal Ruby—si penjelajah hebat!",
  str_voice_1601411_14 = "Aku paham bahwa penjelajahan butuh biaya. Jadi, lakukan saja misi berbayar!",
  str_voice_1601411_15 = "Hari ini ulang tahunmu? Haha, apa harapanmu? Aku akan mewujudkannya.",
  str_voice_1601411_16 = "Hmm… Suhu… Sudah! Kelembapan… Sudah! Kecepatan angin… Sudah! Cuaca hari ini bagus untuk pergi bertualang!",
  str_voice_1601411_17 = "Hei, semalam aku bermimpi cita-citaku terwujud! Bagaimana denganmu? Apa semalam mimpimu bagus?",
  str_voice_1601411_18 = "Hei, aku mencatat petualangan hari ini! Hah? Tulisan tanganku susah dibaca? Itu tidak penting!",
  str_voice_1601411_19 = "Kita jadi tidak enak dipandang kalau bergadang… Baiklah, kalau kau tidak mau tidur, aku akan pergi dulu.",
  str_voice_1601411_20 = "Kebebasan, kegembiraan, dan keluargaku… Rediesel Wrench selamanya adalah rumahku.",
  str_voice_1601411_21 = "Ada banyak reruntuhan kuno di Illumina?! Namun, kehidupan mereka terdengar membosankan.",
  str_voice_1601411_22 = "Jalani hidup sepenuhnya! Langit adalah batasnya!",
  str_voice_1601411_23 = "Para Eclipsite selalu mengganggu petualanganku. Mereka harus dibasmi!",
  str_voice_1601411_24 = "Sebenarnya… Aku sungguh-sungguh berharap Rouge punya mimpi sendiri, dan bukannya mengikutiku terus.",
  str_voice_1601411_25 = "Memangnya aneh kalau Odi adalah atasanku? Meskipun dia lebih muda dariku, pengetahuannya sangat luas.",
  str_voice_1601411_26 = "Ada banyak hal yang kusuka, tapi kalau aku hanya boleh memilih satu, aku pilih—petualangan!",
  str_voice_1601411_27 = "Asalkan aku tidak harus terjebak di rumah tanpa melakukan apa-apa, kegiatan apa pun boleh saja!",
  str_voice_1601411_28 = "Bisa terbang memang keren, tapi kita tak bisa menjelajahi setiap jengkal benua hanya dari langit…",
  str_voice_1601411_29 = "Halo. Namaku Ruby. Cita-citaku adalah menjelajahi setiap sudut peta! Kau sering menjelajah? Wah, kalau iya, ada banyak hal yang bisa kita bicarakan!",
  str_voice_1601411_30 = "Darahku mendidih!",
  str_voice_1601411_31 = "Perasaan yang luar biasa!",
  str_voice_1601411_32 = "Apa tulisan tanganku sudah lebih bagus?",
  str_voice_1601411_33 = "Cita-citaku… Sedang kuusahakan!",
  str_voice_1601411_34 = "Ada yang menarik?",
  str_voice_1601411_35 = "Aku siap kapan pun kau siap!",
  str_voice_1601411_36 = "Kau tak akan melupakanku, 'kan?",
  str_voice_1601411_37 = "Tembakan bagus!",
  str_voice_1601411_38 = "Pukulan tongkat super!",
  str_voice_1601411_39 = "Tembakan yang mengagumkan!",
  str_voice_1601411_40 = "Tepat sasaran!",
  str_voice_1601411_41 = "Nah, ini sih mudah!",
  str_voice_1601411_42 = "Mana tepuk tangannya?",
  str_voice_1601411_43 = "Satu… satu putaran lagi!",
  str_voice_1601411_44 = "Petualangan lagi?! Aku… Hah, kau tidak mau?",
  str_voice_1601411_45 = "Oh… untukku?",
  str_voice_1601411_46 = "Hahaha, kau memang memahamiku!",
  str_voice_1601411_47 = "Hei, apa harganya mahal?",
  str_voice_1601411_48 = "Aku sangat menyukainya!",
  str_voice_1601411_49 = "Aku sudah bergabung dengan Rediesel Wrench sejak dulu… Bertarung, mengemudi, berburu… Makan banyak daging dan selalu menyanyi.",
  str_voice_1601411_50 = "Hasrat saja tidak cukup untuk petualangan. Kita butuh berbagai macam pengetahuan dan latihan… Aku sendiri sudah melakukan kesalahan yang sama.",
  str_voice_1601411_51 = "Sejujurnya, saat berpamitan pada ibuku dan menyalakan mobil, aku hampir menangis. Namun, kemudian aku menyadari ada orang lain di mobil.",
  str_voice_1601411_52 = "Alchemy Stars!",
  str_voice_1601411_53 = "Hai!",
  str_voice_1601411_54 = "Selamat pagi!",
  str_voice_1601411_55 = "Hei, kau lapar?",
  str_voice_1601411_56 = "Malam!",
  str_voice_1601411_57 = "Selamat Tahun Baru! Karena ini tahun baru, ayo kita jelajahi suatu tempat yang jauh. Bagaimana?",
  str_voice_1501421_1 = "Sini, bantu aku mengumpulkan material di daftar ini sebelum pertempuran berikutnya. Kenapa, sih…? Jangan melihatku seperti itu, dong. Aku akan mengirim salinan sampel yang sudah selesai.",
  str_voice_1501421_2 = "Makanan di Colossus cukup enak. Ada makanan bergizi seimbang setiap hari dan kadang-kadang bufet… Sebaiknya kau menambah asupan daging dan lebih sering berolahraga. Nah, dengan begitu, kau bisa menghadapi Eclipsite sendirian.",
  str_voice_1501421_3 = "Kau tidak sedang bermalas-malasan, 'kan? Apa semuanya sudah selesai? Jangan membuang muka, dong… Hei!",
  str_voice_1501421_4 = "Ketika aku mendapatkan Blazing Epee untuk pertama kalinya, benda itu hanyalah tang biasa yang berukuran agak besar. Butuh waktu dua tahun bagiku untuk membuatnya jadi seperti sekarang. Luar biasa, 'kan?",
  str_voice_1501421_5 = "Ada begitu banyak jenis mesin kuno yang menarik. Kalau bisa menemukan jenis mesin baru suatu hari nanti, aku pasti akan dipuji-puji sebagai penemu hebat.",
  str_voice_1501421_6 = "Aku bisa melindungi Ruby dengan kekuatan ini. Namun, itu saja belum cukup… Aku ingin jadi lebih kuat agar dia bisa mengandalkanku…",
  str_voice_1501421_7 = "Aku hanya membantumu karena kasihan. Selain itu, sudah ada banyak teknisi andal di sini… Aku tidak berusaha akrab denganmu, kok!",
  str_voice_1501421_8 = "Kenapa kau tiba-tiba mendekatiku? Memangnya ini jarak yang wajar untuk teman? Eh, a-aku tidak bilang kita berteman!",
  str_voice_1501421_9 = "Capek, ya? Istirahatlah sesekali. Kita tidak perlu bekerja sangat keras. Kenapa menatapku begitu? Kau terkejut karena aku peduli? Aku jadi ingin tahu apa pendapatmu tentangku…",
  str_voice_1501421_10 = "Bangun, jangan tidur di sini. Setidaknya kenakan pakaian yang lebih tebal. Nanti kau masuk angin…",
  str_voice_1501421_11 = "Tetap di sini denganmu? Wah, tak kusangka bakal mendengarnya… Yah, apa boleh buat. Aku akan tetap di sini.",
  str_voice_1501421_12 = "Dari tadi tak henti-hentinya kau menatapku. Lain kali akan kuminta kau membayar.",
  str_voice_1501421_13 = "Kau lihat Ruby? Dia memang selalu suka bertualang, tapi aku khawatir dia bakal menjumpai masalah.",
  str_voice_1501421_14 = "Daging♪ Daging♪ Daging panggang yang lezat… Waow! Kau–kapan kau tiba?!",
  str_voice_1501421_15 = "Nih, ambil… Ini adalah lilin yang bisa menyanyi kalau dinyalakan. C-coba saja!",
  str_voice_1501421_16 = "Akhirnya! Kenapa lama sekali, sih? Aku tidak rindu padamu, kok! Aku hanya butuh bantuan orang lain!",
  str_voice_1501421_17 = "Yo, jarang-jarang bisa melihatmu bangun pagi. Ada peralatan yang bisa diperbaiki tidak? Aku sedang tak punya kegiatan, nih.",
  str_voice_1501421_18 = "Setelah makan malam adalah waktunya bersenang-senang. Menjaga keseimbangan antara bekerja dan bermain akan meningkatkan efisiensi seseorang.",
  str_voice_1501421_19 = "Tidur cepat dan bangun lebih awal membuat tubuh kita sehat… Namun, bukannya aku peduli, sih. Aku hanya mengingatkan.",
  str_voice_1501421_20 = "Rediesel Wrench mengizinkanku bergabung dan menerimaku tanpa syarat. Bagiku, Rediesel Wrench adalah rumah.",
  str_voice_1501421_21 = "Orang-orang Lumopolis selalu membuat kita bingung dengan gerombolan itu. Menjengkelkan sekali.",
  str_voice_1501421_22 = "Demi Ruby!",
  str_voice_1501421_23 = "Terkadang orang lebih menakutkan daripada Eclipsite. Niat jahat dari hati manusia bisa sulit untuk dipahami.",
  str_voice_1501421_24 = "Sejak aku masih kecil, Ruby selalu ada di sampingku. Tanpa dia, aku tak akan menjadi seperti ini…",
  str_voice_1501421_25 = "Jona adalah penyelamatku dan dia tetap menjagaku. Kadang dia bahkan mentraktirku makan!",
  str_voice_1501421_26 = "Yang kusukai? Pertanyaan macam apa itu? Kau bermaksud memberiku kejutan, ya?",
  str_voice_1501421_27 = "Aduh! Jangan muncul dari belakangku secara tiba-tiba begitu, dong! Jantungku serasa mau copot, tahu?!",
  str_voice_1501421_28 = "Ruby pasti girang bukan kepalang kalau dia bisa memiliki Colossus… Berapa sih harga jualnya?",
  str_voice_1501421_29 = "Aku Rouge, pencipta top dari Rediesel Wrench. Kalau mau mengadakan pesta untukku, hidangkan daging panggang terlezat, ya. Ehem, omong-omong… apa Ruby di sini?",
  str_voice_1501421_30 = "Rasanya tubuhku lebih ringan…",
  str_voice_1501421_31 = "Lebih banyak kekuatan!",
  str_voice_1501421_32 = "Aku bisa merasakan darahku mendidih!",
  str_voice_1501421_33 = "Aku bisa merasakan panasnya…",
  str_voice_1501421_34 = "Lihat aku.",
  str_voice_1501421_35 = "Target terkunci!",
  str_voice_1501421_36 = "Siap tembak!",
  str_voice_1501421_37 = "Plierblade—serang!",
  str_voice_1501421_38 = "Bidik… Siap… Tembak!",
  str_voice_1501421_39 = "Saatnya menari!",
  str_voice_1501421_40 = "Blazing Epee!",
  str_voice_1501421_41 = "Aku memang yang paling hebat!",
  str_voice_1501421_42 = "Sudah kuduga.",
  str_voice_1501421_43 = "Aku gagal…",
  str_voice_1501421_44 = "Jauhkan tanganmu dari Blazing Epee! Itu senjata yang sangat dahsyat.",
  str_voice_1501421_45 = "Hadiah untukku? Memangnya kenapa?",
  str_voice_1501421_46 = "Aku… aku tak akan tertipu oleh yang seperti itu.",
  str_voice_1501421_47 = "Kurasa tidak apa-apa. Baiklah, akan kuterima.",
  str_voice_1501421_48 = "Terima ka… Tidak, lupakan saja.",
  str_voice_1501421_49 = "Orang tua? Siapa juga yang butuh mereka? Kalau bukan karena ada hubungan darah, aku tak mungkin mau mengakui mereka. Gara-gara mereka, kenangan masa kecilku terasa suram.",
  str_voice_1501421_50 = "Aku sudah bertemu dengan juru selamatku, jadi aku tak percaya pada dewa. Ruby menyelamatkanku dari kegelapan dan menuntunku menuju cahaya. Aku rela mengorbankan apa pun demi dia…",
  str_voice_1501421_51 = "Sikap anggota Rediesel Wrench memang cukup santai, 'kan? Bahkan orang seperti aku pun merasa betah. Hanya saja… Mereka selalu mengejekku karena aku terus mengikuti Ruby…",
  str_voice_1501421_52 = "Alchemy Stars!",
  str_voice_1501421_53 = "Hei, kau.",
  str_voice_1501421_54 = "Hari ini kau bangun pagi.",
  str_voice_1501421_55 = "Sudah siang.",
  str_voice_1501421_56 = "Sudah malam.",
  str_voice_1501421_57 = "Ini Tahun Baru, dan setiap tahun baru harus dirayakan dengan hot pot! Ada begitu banyak daging di dalamnya!",
  str_voice_1601431_1 = "Selama aku masih ada di sini, tak seorang pun bisa menyerang.",
  str_voice_1601431_2 = "Selain menjalankan tugas sebagai pendeta, aku juga mahir memainkan alat musik dan menangani dokumen.",
  str_voice_1601431_3 = "Salah satu Kagura Bell milikku hilang. Kau bisa membantuku untuk mencarinya?",
  str_voice_1601431_4 = "Meditasi, berdoa, bersih-bersih… Sebenarnya, kehidupan pendeta cukup membosankan.",
  str_voice_1601431_5 = "Kami yakin ada dewa yang hidup dalam segala hal, dari gunung hingga danau, dari batu hingga kayu. Dewa-dewa ini melindungi kita setiap saat.",
  str_voice_1601431_6 = "Penghalang sihir pendeta melindungi sang pendeta dan segala hal yang dia sayangi.",
  str_voice_1601431_7 = "Apa kekuatan pembersihanku bisa mengobati lukamu?",
  str_voice_1601431_8 = "Penghalang sihirku memang bisa melawan energi jahat, tapi ada batasnya. Tolong jangan lari terlalu jauh.",
  str_voice_1601431_9 = "Kekuatan spiritualku bisa dilepaskan dengan lebih mulus saat aku di dekatmu. Inikah kekuatan spesial Caelestite atau berkah karena kita saling berempati?",
  str_voice_1601431_10 = "Oh… Navigator linglung? Kemalasan adalah salah satu jenis energi jahat. Kaubutuh mantra pembersihanku?",
  str_voice_1601431_11 = "Ahh… Pekerjaan di sini sangat berbeda dengan latihan pendeta yang kujalani.",
  str_voice_1601431_12 = "Navigator, butuh istirahat?",
  str_voice_1601431_13 = "Pelatihan pendetaku akan dimulai. Kau mau ikut?",
  str_voice_1601431_14 = "Mau tahu dewa mana yang kusembah? Yah, setiap pendeta punya rahasia.",
  str_voice_1601431_15 = "Selamat ulang tahun, Navigator! Semoga kau memiliki teman yang baik dalam perjalananmu di masa depan.",
  str_voice_1601431_16 = "Pendeta selalu siap sedia kapan saja dan di mana saja.",
  str_voice_1601431_17 = "Selamat pagi, Navigator! Aku akan membantu tugas-tugasmu hari ini.",
  str_voice_1601431_18 = "Selamat malam, Navigator! Bagaimana kabarmu hari ini?",
  str_voice_1601431_19 = "Energi jahat paling aktif saat malam. Navigator, kau mau membersihkan energi jahat denganku?",
  str_voice_1601431_20 = "Aku merindukan kota, tempat aku bisa melihat menembus awan.",
  str_voice_1601431_21 = "Lumopolis hanya menyembah satu dewa, sangat berbeda dengan agamaku.",
  str_voice_1601431_22 = "Hidup bebas adalah kemewahan.",
  str_voice_1601431_23 = "Pasang penghalang dengan tali rami di seluruh Colossus agar makhluk-makhluk itu tak bisa masuk.",
  str_voice_1601431_24 = "Kayano adalah anak yang baik. Dia tak tahu bahwa menguntit itu tidak pantas…",
  str_voice_1601431_25 = "Yao polos dan sangat manis, seperti anak anjing.",
  str_voice_1601431_26 = "Yang berkelap-kelip itu namanya Firefly? Indah sekali!",
  str_voice_1601431_27 = "Energi jahat bukan bagian dari dunia ini. Sebaiknya aku membakarnya dengan kekuatan pembersihan.",
  str_voice_1601431_28 = "Tanpa adanya energi jahat, Colossus ini benar-benar penuh cahaya. Aku sangat menyukainya.",
  str_voice_1601431_29 = "Rinne, pendeta dari Cloud Island, menjawab panggilanmu. Izinkan aku mengikutimu dan membantumu dalam perjalanan ini.",
  str_voice_1601431_30 = "Terima kasih telah memercayaiku.",
  str_voice_1601431_31 = "Sekarang aku bisa bertarung dengan leluasa…",
  str_voice_1601431_32 = "Aku bisa merasakan kekuatan spiritual yang tak tertandingi.",
  str_voice_1601431_33 = "Akan kumanfaatkan kekuatan pembersihan ini dengan baik.",
  str_voice_1601431_34 = "Percayakan saja padaku.",
  str_voice_1601431_35 = "Aku berdoa…",
  str_voice_1601431_36 = "Wahai kekuatan pembersihan…",
  str_voice_1601431_37 = "Sebarkan penghalang!",
  str_voice_1601431_38 = "Kuperintahkan seluruh selubung kabut dan bayangan untuk menghilang!",
  str_voice_1601431_39 = "Ini tak bisa ditoleransi!",
  str_voice_1601431_40 = "Pergilah, roh jahat!",
  str_voice_1601431_41 = "Semuanya, ikuti aku.",
  str_voice_1601431_42 = "Seluruh energi jahat harus disingkirkan.",
  str_voice_1601431_43 = "Aura jahat…",
  str_voice_1601431_44 = "Apa yang bisa dibantu pendeta? Tidak usah malu. Katakan saja padaku.",
  str_voice_1601431_45 = "Hadiah untukku? Kau sangat baik.",
  str_voice_1601431_46 = "Bagaimana kautahu aku suka ini?",
  str_voice_1601431_47 = "Aku merasakan hatimu…",
  str_voice_1601431_48 = "Aku akan menyimpan hadiahmu dan menaruhnya bersama dengan barang-barang kesukaanku di kotak.",
  str_voice_1601431_49 = "Kehidupan seorang pendeta cukup membosankan. Dari hari ke hari, hidupku tak akan berubah kalau bukan karena dirimu.",
  str_voice_1601431_50 = "Ketidakpercayaan seseorang pada orang lain adalah penyebab permusuhan dan konflik. Sudah menjadi tanggung jawab pendeta untuk menghilangkan kecurigaan dan kedengkian.",
  str_voice_1601431_51 = "Sejak bergabung dalam perjalananmu, hidupku terasa menyenangkan dan mengasyikkan. Ini memang tidak seaman dan sedamai di Cloud Island, tapi aku menyukainya.",
  str_voice_1601431_52 = "Alchemy Stars.",
  str_voice_1601431_53 = "Selamat siang.",
  str_voice_1601431_54 = "Pagi.",
  str_voice_1601431_55 = "Selamat siang, Navigator.",
  str_voice_1601431_56 = "Permisi.",
  str_voice_1601431_57 = "Selamat Tahun Baru, Navigator. Izinkan aku membersihkan seluruh energi jahat dan mendoakan keselamatanmu dengan Kagura Bell milikku.",
  str_voice_1501441_1 = "Jangan menatapku seperti itu. Aku jadi gugup…",
  str_voice_1501441_2 = "Kalau bukan karena Yang Mulia, aku pasti sudah mati sejak dulu. Aku sangat bersyukur.",
  str_voice_1501441_3 = "Dendam yang meliputi dunia ini… Roh-roh kesepian di sekitarku… Heheh… Sebentar. Itu bukan aku…",
  str_voice_1501441_4 = "Bagiku, mereka seperti kabut yang sangat halus, tapi tak ada yang memercayaiku.",
  str_voice_1501441_5 = "Terkadang kau mungkin mendengarku mengatakan hal-hal aneh, tapi aku tak pernah bermaksud mengatakannya. Merekalah yang ingin aku mengatakannya. Tolong percayalah.",
  str_voice_1501441_6 = "Aku sering memikirkan masa depanku. Kurasa aku ingin tetap di sini.",
  str_voice_1501441_7 = "Di sini sangat berbeda dengan tempat asalku. Rasanya membuatku santai. Aku akan lebih menikmatinya kalau lebih sepi…",
  str_voice_1501441_8 = "Kalau kau tidak keberatan, bolehkah aku menggambar sesuatu untukmu? Dulu aku pernah mempelajarinya sedikit. Aku akan berusaha semampuku.",
  str_voice_1501441_9 = "Rasanya ajaib… Kau adalah sahabat pertamaku, selain anak-anak itu. Makhluk-makhluk itu dan aku tidak sekuat yang lainnya di sini, tapi aku akan melakukan segalanya untukmu.",
  str_voice_1501441_10 = "Navigator tidak ada di sini? Yah, kurasa aku bisa agak bersantai.",
  str_voice_1501441_11 = "Bekerja di sini? Kalau tidak banyak orang yang kemari…",
  str_voice_1501441_12 = "Lingkaran gelap di bawah matamu kelihatannya makin parah saja. Kaubutuh istirahat…",
  str_voice_1501441_13 = "Navigator mau pergi? Kalau begitu, aku mau ke Lounge… Hah? Aku harus ikut?",
  str_voice_1501441_14 = "Makhluk-makhluk itu… Kumohon jangan habisi mereka. Ini untuk ritual… Jangan. Rasanya sangat menyakitkan…",
  str_voice_1501441_15 = "Selamat ulang tahun! Aku sudah menyiapkan hadiah spesial untukmu… Tidak! Tidak ada hubungannya dengan hal-hal itu!",
  str_voice_1501441_16 = "Kau bekerja seharian? Rajin sekali!",
  str_voice_1501441_17 = "Hmm… Pagi. Aku masih butuh tidur… Fiuh…",
  str_voice_1501441_18 = "Selamat malam. Apa makan malammu enak?",
  str_voice_1501441_19 = "Hmm… Fiuh… Taiyaki… Nyam… Hmm? Navigator? Kau belum tidur?",
  str_voice_1501441_20 = "Kota Koufu-jou, menjulang tinggi ke langit dan menguasai para iblis serta roh selama bertahun-tahun, tetap tak bisa lepas dari takdir… Heheheh…",
  str_voice_1501441_21 = "Apa semua anggota Rediesel Wrench memang ramah dan bebas seperti ini? Mengerikan sekali!",
  str_voice_1501441_22 = "Di kampung halamanku, aku tak punya rumah.",
  str_voice_1501441_23 = "Makhluk-makhluk mengerikan ini ada di mana-mana. Aku tak mau melawannya…",
  str_voice_1501441_24 = "Momo dan Anzu selalu menjagaku.",
  str_voice_1501441_25 = "Lady Rinne memang bangsawan sejati, sedangkan aku hanya rakyat jelata. Aku tak berani bersikap kurang ajar padanya.",
  str_voice_1501441_26 = "Kalau aku bisa tinggal sendiri, makhluk-makhluk itu tak akan bisa menyakiti orang lain.",
  str_voice_1501441_27 = "Dengan pesta dan kehidupan malamnya, Koufu-jou menampilkan kedok palsu kedamaian dan kemakmuran. Konyol dan menyedihkan… Heheh…",
  str_voice_1501441_28 = "Ada banyak ruang di Colossus… Pasti ada beberapa tempat yang lebih sepi dari yang lain.",
  str_voice_1501441_29 = "Hai, aku Kayano. Tolong jangan takut. Aku akan berusaha sebaik mungkin untuk mengendalikan makhluk-makhluk itu. Semoga kami tidak mengganggumu.",
  str_voice_1501441_30 = "Dendamnya semakin membara.",
  str_voice_1501441_31 = "Aku… lebih kuat.",
  str_voice_1501441_32 = "Aku tidak mau bertarung… Huhu…",
  str_voice_1501441_33 = "Apa yang kaunantikan?",
  str_voice_1501441_34 = "Haruskah aku pergi?",
  str_voice_1501441_35 = "Makhluk-makhluk itu… makin tak terkendali!",
  str_voice_1501441_36 = "Sulit dikendalikan… Woo!",
  str_voice_1501441_37 = "Sembunyi!",
  str_voice_1501441_38 = "Dendamnya sangat hebat… Heheh…",
  str_voice_1501441_39 = "Aku membidik di sini!",
  str_voice_1501441_40 = "Jangan lari…",
  str_voice_1501441_41 = "Woo… aku sangat payah dalam bersosialisasi.",
  str_voice_1501441_42 = "Berhasil…",
  str_voice_1501441_43 = "Maaf… Aku tak cukup kuat…",
  str_voice_1501441_44 = "Terima kasih sudah mengunjungiku. Aku senang.",
  str_voice_1501441_45 = "Ini untukku? Sungguh?",
  str_voice_1501441_46 = "Entah bagaimana cara membalas kebaikanmu…",
  str_voice_1501441_47 = "Beruntungnya aku karena kauperhatikan!",
  str_voice_1501441_48 = "Aku benar-benar… berterima kasih… Woo…",
  str_voice_1501441_49 = "Masa kanak-kanakku… Penuh hal yang membosankan dan sepele, tidak pantas didengarkan.",
  str_voice_1501441_50 = "Begitulah masa laluku. Tolong jangan membenciku.",
  str_voice_1501441_51 = "Banyak orang, termasuk kau, sudah menyelamatkanku. Izinkan aku tetap di sini…",
  str_voice_1501441_52 = "Eh… Alchemy Stars?",
  str_voice_1501441_53 = "Sebentar…",
  str_voice_1501441_54 = "Pagi. Kau sudah bangun?",
  str_voice_1501441_55 = "Hmm… Aku lapar…",
  str_voice_1501441_56 = "Navigator, kau sudah tidur?",
  str_voice_1501441_57 = "Satu tahun telah berlalu dengan sangat cepat…",
  str_voice_1600064_10 = "Masih menatapku? Mungkin aku harus membekukanmu menjadi es batu…",
  str_voice_1600064_11 = "Pemandangannya sangat indah, anginnya segar… Aku jadi teringat pada Northland… Dingin tapi menyegarkan, tidak seperti Lumopolis.",
  str_voice_1600064_16 = "Kau harus menyeimbangkan pekerjaan dan hiburan. Jangan lupa berhenti dulu untuk minum kopi atau mengobrol dengan teman.",
  str_voice_1600064_17 = "Kau bangun pagi, ya… Pertahankan. Ini bagus.",
  str_voice_1600064_18 = "Pemandangan malam di Colossus sangat bagus. Kapan-kapan aku akan mengajakmu melihat-lihat Lumopolis di malam hari.",
  str_voice_1600064_19 = "Belum tidur? Apa yang kaupikirkan? Kalau belum tahu… aku ini pendengar yang baik.",
  str_voice_1600064_35 = "Kabutnya makin pekat.",
  str_voice_1600064_36 = "Menunggu untuk dilepaskan.",
  str_voice_1600064_37 = "Akhiri pertempuran ini!",
  str_voice_1600064_38 = "Bekukan roh dengan hawa dingin yang menusuk!",
  str_voice_1600064_39 = "Frosty Gust.",
  str_voice_1600064_40 = "Snow Banquet.",
  str_voice_1600064_44 = "Jangan menatapku.",
  str_voice_1600064_58 = "Bahkan sahabat pun bisa berkelahi dan berdebat. Begitu juga dengan pasangan kekasih. Iya, 'kan?",
  str_voice_1600064_59 = "Kau harus sedikit bersantai sesekali. Nanti kau bisa gila kalau gugup terus.",
  str_voice_1600064_60 = "Terkadang mencoba hal-hal baru dan melihat segalanya dari sudut yang berbeda sangat berguna.",
  str_voice_1600064_61 = "Kira-kira seperti apa ya cara para gadis di belahan lain dunia berdandan?",
  str_voice_1600064_62 = "Kudengar Umbraton sangat terbuka dan modern. Namun, keterbukaan tanpa batasan bisa mengarah pada kerusakan moral.",
  str_voice_1600064_63 = "Saat berpatroli, kita harus bersikap bermartabat dan ramah. Namun, yang paling penting adalah memberikan rasa aman.",
  str_voice_1600064_64 = "Colossus di pagi hari terasa cukup panas.",
  str_voice_1600064_65 = "Pagi! Kau sudah bangun.",
  str_voice_1600064_66 = "Hari ini kau bangun pagi.",
  str_voice_1600064_67 = "Sepertinya ada banyak pekerjaan yang harus dilakukan hari ini…",
  str_voice_1600064_68 = "Ah… Pagi.",
  str_voice_1600064_69 = "Kaudengar sesuatu pagi ini?",
  str_voice_1600064_70 = "Ini sudah siang.",
  str_voice_1600064_71 = "Bagaimana makan siangmu tadi?",
  str_voice_1600064_72 = "Apa kau sudah makan siang?",
  str_voice_1600064_73 = "Matahari saat tengah hari memang yang terbaik!",
  str_voice_1600064_74 = "Ini saatnya tidur.",
  str_voice_1600064_75 = "Apa yang akan kaulakukan kalau tidak bisa tidur?",
  str_voice_1600064_76 = "Malam ini langitnya sangat cantik.",
  str_voice_1600064_77 = "Tidurmu nyenyak?",
  str_voice_1601451_1 = "Gulungan ninja di belakangku berisi segala macam informasi tentang ninjutsu dan latihan yang aneh. Mau lihat? Gunakan dengan sangat hati-hati, ya. Kalau tidak, bisa-bisa kau benar-benar kehilangan akal sehat.",
  str_voice_1601451_2 = "Mau tahu berapa banyak senjata yang kubawa? Sejujurnya, pertanyaanku sangat bodoh. Jangan coba-coba bertanya pada ninja lain, nanti kau menyesal.",
  str_voice_1601451_3 = "Kunai adalah nama yang bagus untuk senjata, 'kan? Kedengarannya tidak akan menimbulkan rasa sakit.",
  str_voice_1601451_4 = "Menurutmu, aku membosankan? Heh. Aku tidak keberatan. Setiap orang yang tersenyum pun sebenarnya membosankan. Iya, 'kan?",
  str_voice_1601451_5 = "Rin, Pyo, Toh, Sha, Kai, Jin, Retsu, Zai, Zen! Ingat mantra Kuji-kiri sembilan kata ini!",
  str_voice_1601451_6 = "Ada tiga pantangan dalam ninjutsu. Pertama, rasa takut. Kedua, rasa terhina. Dan ketiga, rasa khawatir. Kalau bisa mengesampingkan ketiganya, kau akan bisa melaju secepat kilat.",
  str_voice_1601451_7 = "Kau pernah dengar suara angin yang bertiup di ladang padi? Kresek, kresek… Saat masih kecil, aku sering tertidur kalau mendengarnya. Namun, masa-masa yang menyenangkan tak berlangsung lama. Iya, 'kan?",
  str_voice_1601451_8 = "Aku sangat terkesan padamu karena bisa menanggung derita sendirian di bawah tanah selama 17 tahun… Kisahmu layak ditulis di gulungan ninjaku!",
  str_voice_1601451_9 = "Mungkin aku akan tetap di sini, menjaga Cloud Island bahkan kalau penduduknya sudah hidup damai dan bahagia. Atau mungkin itu waktunya aku turut menjelajah dunia denganmu?",
  str_voice_1601451_10 = "Tenang saja, aku sudah terbiasa kesepian dan menunggu. Aku akan melapor padamu kalau ada apa-apa.",
  str_voice_1601451_11 = "Maksudmu… Sebaiknya aku tinggal di sini untuk mengawasi kalau-kalau ada musuh? Tidak perlu? Kauingin aku melakukan sesuatu yang kusuka? Permintaanmu sangat sulit dipenuhi.",
  str_voice_1601451_12 = "Tolong jangan salah sangka… Aku sembunyi dalam gelap karena merindukan terang.",
  str_voice_1601451_13 = "Aku percaya takdir. Takdirlah yang menuntunku ke jalan ninjutsu. Aku tak akan pernah menoleh ke belakang.",
  str_voice_1601451_14 = "Ada beberapa butir pil tidur di balik topi bambuku. Namun, itu bukan untuk orang yang mengidap insomnia.",
  str_voice_1601451_15 = "Ini hari ulang tahunmu? Wah, kita harus merayakannya.",
  str_voice_1601451_16 = "Sebaiknya jangan mengintip latihan ninjutsu yang kujalani kalau tidak mau bergabung dengan sekte kami.",
  str_voice_1601451_17 = "Kau sudah bangun? Tidurmu sangat nyenyak. Dari mana aku tahu? Kau tidak ingat apa pekerjaanku, ya?",
  str_voice_1601451_18 = "Ini waktunya bagi keluarga biasa untuk berkumpul dan makan bersama.",
  str_voice_1601451_19 = "Belum tidur? Kalau tidak mewaspadaiku, berarti kau harus ikut latihan ninja.",
  str_voice_1601451_20 = "Orang-orang yang berada di jalan ninjutsu tidak meminta bagian dalam sejarah.",
  str_voice_1601451_21 = "Kudengar ada tempat bernama Umbraton di seberang laut. Sepertinya kota itu menjadi tempat berkumpulnya para ninja.",
  str_voice_1601451_22 = "Tutup mulutmu. Tahan diri untuk tidak bicara.",
  str_voice_1601451_23 = "Kuharap roh mereka bisa beristirahat dalam damai.",
  str_voice_1601451_24 = "Master menyadarkanku kembali. Akan kulakukan apa pun untuk membalas budi.",
  str_voice_1601451_25 = "Meski terlahir di masa yang kacau, bisa-bisanya Yao tersenyum tulus dan polos begitu, ya?",
  str_voice_1601451_26 = "Aku suka mandi air panas. Orang-orang sepertiku tak tahan bau, baik bau yang enak maupun yang tidak enak.",
  str_voice_1601451_27 = "Perang tidak luput dari kebohongan, pengkhianatan, dan perpisahan karena kematian. Namun, perang hanya bisa diakhiri dengan senjata dan kekerasan.",
  str_voice_1601451_28 = "Dulu aku pernah mendengar cerita pendongeng jalanan tentang hewan legenda bersayap raksasa. Jangan-jangan dia.",
  str_voice_1601451_29 = "Menembus malam bersama angin. Bersembunyi dalam bayangan. Berdiam di kedalaman Cloud Mountain. Beristirahat di bawah langit berbintang. Aku Amemori, jangan segan-segan hubungi aku kalau butuh bantuan, ya.",
  str_voice_1601451_30 = "Ada lebih banyak entri di gulungan ninjaku.",
  str_voice_1601451_31 = "Kemampuan melempar senjataku makin baik.",
  str_voice_1601451_32 = "Kekuatan misterius ninjutsu!",
  str_voice_1601451_33 = "Aku juga bisa sembunyi di siang bolong.",
  str_voice_1601451_34 = "Aku tersembunyi dalam antrean.",
  str_voice_1601451_35 = "Aku siap kapan pun kau siap.",
  str_voice_1601451_36 = "Aku sudah menunggu.",
  str_voice_1601451_37 = "Ninjutsu! Terbang di tepi atap!",
  str_voice_1601451_38 = "Insight! Shadow Tracer!",
  str_voice_1601451_39 = "Ninjutsu selamanya!",
  str_voice_1601451_40 = "Pedang baja tak kenal ampun!",
  str_voice_1601451_41 = "Perintah diterima.",
  str_voice_1601451_42 = "Kemenangan kecil tidak pantas dirayakan.",
  str_voice_1601451_43 = "Tak ada salahnya bersembunyi atau melarikan diri. Tetaplah hidup agar kau bisa bertarung lagi.",
  str_voice_1601451_44 = "Coba katakan. Di mana jalan rahasia itu?",
  str_voice_1601451_45 = "Apa ini deposito untuk tugas berikutnya?",
  str_voice_1601451_46 = "Aku sangat menyukainya.",
  str_voice_1601451_47 = "Terima kasih atas kebaikanmu.",
  str_voice_1601451_48 = "Hanya masterku yang pernah memberiku hadiah berharga semacam ini.",
  str_voice_1601451_49 = "Karena terlahir di tengah keluarga petani selama masa perang di Cloud Island, aku tak tertarik pada bela diri. Yang kupedulikan hanya panen.",
  str_voice_1601451_50 = "Kulihat api jingga dan darah merah bercampur di tanah saat para prajurit itu membakar seluruh desa kami. Orang baik tak bisa hidup damai… Begitukah nasib mereka?",
  str_voice_1601451_51 = "Pedangnya yang memantulkan sinar putih dingin berkelebat di depan mataku. Aku tahu dialah satu-satunya harapanku.",
  str_voice_1601451_52 = "Alchemy Stars.",
  str_voice_1601451_53 = "Ya.",
  str_voice_1601451_54 = "Pagi.",
  str_voice_1601451_55 = "Tentu.",
  str_voice_1601451_56 = "Malam.",
  str_voice_1601451_57 = "Semoga tahun baru ini membawa panen yang melimpah.",
  str_voice_1601461_1 = "Aku bukan gadis kecil yang bodoh! Terakhir kali, orang yang menyebutku begitu bertekuk lutut di bawah tinjuku. Mau coba?",
  str_voice_1601461_2 = "Krucuuuk… Roti kukus kecil… Pangsit… Siomai… Bebek panggang… Aku rindu kalian semua! Namun, aku harus pergi untuk menegakkan keadilan dan membantu orang-orang yang malang. Sepertinya aku harus menahan keinginan makanku…",
  str_voice_1601461_3 = "Hubungi aku kalau ada masalah! Namun, tahu rasa kau nanti kalau ternyata kau yang cari gara-gara!",
  str_voice_1601461_4 = "Awas! Jepit rambutku bukan sekadar aksesori indah. Kalau tidak perlu, aku tak mau benda ini sampai mengenai penjahat. Paham, 'kan?",
  str_voice_1601461_5 = "Aku menjadi ahli bela diri agar bisa menegakkan keadilan saat diperlukan. Mau jadi apa aku kalau tidak bisa melakukannya?",
  str_voice_1601461_6 = "Ah! Lihat! Belakangan ini ototku tambah besar, 'kan? Pakaianku jadi lumayan kesempitan sekarang…",
  str_voice_1601461_7 = "Kenapa kau menatapku? Mau belajar teknik Qi, ya? Hahaha… Sulit, lo. Kau harus bisa tahan, fleksibel, dan terampil sekaligus!",
  str_voice_1601461_8 = "Suka tahu Mapo? Kurasa kau belum pernah makan tahu Mapo yang enak! Kapan-kapan aku akan memasaknya untukmu. Kau akan merasa terbakar dari dalam!",
  str_voice_1601461_9 = "Kesatria hebat biasanya pergi sendirian! Namun, kalau dua kesatria bersatu… Kedengarannya seru juga, 'kan?",
  str_voice_1601461_10 = "Karena sepertinya kau tidak punya kegiatan… Mau berolahraga denganku? Pertama, 100 push-up, lalu 500 tendangan…",
  str_voice_1601461_11 = "Kau mau aku menjaga tempat ini? Itu sih keahlianku. Tenang saja! Hah? Berbuat semauku? Tentu!",
  str_voice_1601461_12 = "Aku sedang berlatih menendang. Sini, latih tanding denganku kalau berani!",
  str_voice_1601461_13 = "Hati orang jahat lebih menakutkan daripada Eclipsite, 'kan?",
  str_voice_1601461_14 = "Kausuka pakaianku? Aku bisa mencarikanmu satu kalau kau mau.",
  str_voice_1601461_15 = "Wow! Ini hari ulang tahunmu? *Berdehem* Semoga ini jadi hari yang menyenangkan!",
  str_voice_1601461_16 = "Hari ini aman-aman saja. Aku jadi menganggur. Hah.",
  str_voice_1601461_17 = "Wah! Serius, nih? Aku baru pulang setelah lari-lari, dan kau masih tidur?",
  str_voice_1601461_18 = "Hei! Kenapa kau masih bekerja? Aku capek menunggu, tahu? Bangun. Olahraga sana!",
  str_voice_1601461_19 = "Tidur dengan domba, bangun dengan burung lark. Patuhi aturan alam dan hidup dengan umur panjang. Baiklah, aku mau tidur.",
  str_voice_1601461_20 = "Aku terlahir untuk mengembara, bukan melayani… Hah. Bertingkah seperti kesatria sejati!",
  str_voice_1601461_21 = "Sepertinya Rediesel Wrench adalah kelompok yang terhormat, tapi kudengar banyak dari anggotanya bersifat eksentrik. Benarkah itu?",
  str_voice_1601461_22 = "Moralitas dan keadilan mengalahkan segalanya!",
  str_voice_1601461_23 = "Dasar monster kelas teri… Huh… Memikirkan mereka saja membuatku mual! Namun, tinjuku bisa membereskan mereka semua!",
  str_voice_1601461_24 = "Sepertinya Amemori merasa sangat berat kalau harus tersenyum… Sayang sekali, padahal senyumnya sangat indah…",
  str_voice_1601461_25 = "Siapa orang di Umbraton yang tidak tahu Shadowlord? Aku yakin dia juga kesatria sejati.",
  str_voice_1601461_26 = "Aku sangat menyukai jepit rambut ini! Yah, kurang lebih hanya inilah satu-satunya senjataku.",
  str_voice_1601461_27 = "Di beberapa daerah, orang memasak tanpa garam! Aku harus membawa bubuk cabai sendiri.",
  str_voice_1601461_28 = "Moda transportasi terbaik untuk mengarungi samudra… Jauh lebih baik ketimbang perahu!",
  str_voice_1601461_29 = "Aku sudah mendengar banyak tentangmu. Sungguh suatu kehormatan! Namaku Yao. Terima kasih atas bantuanmu di masa depan!",
  str_voice_1601461_30 = "Biarkan udara mengalir dalam tubuhmu…",
  str_voice_1601461_31 = "Kekuatan membara di ujung jari-jariku!",
  str_voice_1601461_32 = "Otot-otot betis gemetaran!",
  str_voice_1601461_33 = "Wow! Apa semua jalan dalam tubuhku sudah terbuka?",
  str_voice_1601461_34 = "Jangan khawatir! Aku bisa menanganinya!",
  str_voice_1601461_35 = "Tarik napas dalam-dalam…",
  str_voice_1601461_36 = "Serang…",
  str_voice_1601461_37 = "Ssst… Kita hanya bisa melancarkan pukulan tepat sasaran kalau berpikir dengan tenang. Hah!",
  str_voice_1601461_38 = "Divine Nature -- Bamboo Spikes!",
  str_voice_1601461_39 = "Bangkitlah… Torrent Pine!",
  str_voice_1601461_40 = "Bangkitlah… Stone Maul!",
  str_voice_1601461_41 = "Nah, memang inilah gunanya ada kesatria!",
  str_voice_1601461_42 = "Trik kecil… tak pantas disebutkan.",
  str_voice_1601461_43 = "Huh! Aku bersumpah akan membalas dendam!",
  str_voice_1601461_44 = "Wow! Ini tempat yang tepat untuk berlatih!",
  str_voice_1601461_45 = "Wow! Untukku, nih?",
  str_voice_1601461_46 = "Tak perlu repot-repot, lo… Akan kusimpan, deh.",
  str_voice_1601461_47 = "Aww… Kau tak perlu repot-repot!",
  str_voice_1601461_48 = "Terima kasih. Aku benar-benar menyukainya!",
  str_voice_1601461_49 = "Ingatanku mulai asin seperti lautan. Air laut masuk ke dalam mulutku, hidungku, dan telingaku…",
  str_voice_1601461_50 = "Orang tua angkatku bilang aku hilang ingatan. Seperti apa aku dulu? Apa yang kulakukan? Ke mana saja aku? Tak seorang pun tahu.",
  str_voice_1601461_51 = "Tak lama, aku mulai mempelajari Qi. Yah, aku tak bisa mencegah kesatria itu terbang melintasi cakrawala. Benar, kesatria yang kumaksud adalah aku!",
  str_voice_1601461_52 = "Alchemy Stars!",
  str_voice_1601461_53 = "Woah!",
  str_voice_1601461_54 = "Saatnya olahraga pagi!",
  str_voice_1601461_55 = "Mmm… Aku lapar…",
  str_voice_1601461_56 = "Hemat kekuatan dan simpan energi!",
  str_voice_1601461_57 = "Semoga tahun baru senantiasa penuh kegembiraan!",
  str_voice_1501471_1 = [[
- Aku Momo. Aku yang bertugas di dapur.
- Aku Anzu. Aku yang mencatat keuangan.
- Kami anak kembar identik, jadi jangan sampai tertukar, ya!]],
  str_voice_1501471_2 = "- Yang lebih tua? Tentu saja aku!\n- Hei! Aku, dong!\n-… Ya jelas aku!",
  str_voice_1501471_3 = [[
- Setiap ons saja ditawar oleh Anzu. Dasar pelit!
- Momo suka melompat-lompat, seperti kera kecil!]],
  str_voice_1501471_4 = [[
- Taraa! Sajian hangat yang baru keluar dari kukusan!
- Roti daging Kaniya! Bagaimana menurutmu?]],
  str_voice_1501471_5 = [[
- Anzu, para Eclipsite buang-buang makanan!
- Momo, beri mereka pelajaran dengan roti daging spesial kita!]],
  str_voice_1501471_6 = [[
- Hari ini, apa isian rotinya?
- Kacang campur!]],
  str_voice_1501471_7 = [[
- Belakangan ini tamu kehormatan kita cukup sering kemari.
- Dia sudah jadi pelanggan tetap!]],
  str_voice_1501471_8 = [[
- Belakangan ini kau tampak lelah.
- Mau kami panggangkan kukis?
- Aku siap-siap dulu!]],
  str_voice_1501471_9 = [[
- Tamu kehormatan kita datang! Momo, siapkan hidangan terbaikmu!
- Baiklah! Kau pasti tak akan kecewa!]],
  str_voice_1501471_10 = [[
- Anzu, tamu kehormatan kita tertidur!
- Jangan sampai kita melewatkan kesempatan ini, Momo. Ayo, tambahkan wasabi ke ramennya!]],
  str_voice_1501471_11 = "- Kaniya Ramen…\n- Cabang Soroz…\n- Pembukaan akbar!",
  str_voice_1501471_12 = [[
- Mungkin kami suka bertengkar.
- Namun, kami tak pernah berpisah!]],
  str_voice_1501471_13 = [[
- Soroz sangat meriah!
- Selalu penuh orang!]],
  str_voice_1501471_14 = [[
- Ayo kita selenggarakan festival! Festival Kaniya Ramen!
- Biar lebih banyak orang merasakan ramen superlezat kita!]],
  str_voice_1501471_15 = [[
- Tamu kehormatan, selamat ulang tahun!
- Kami telah menyiapkan mi panjang umur untukmu!]],
  str_voice_1501471_16 = [[
- Belum waktunya makan?
- Masih belum?
- Aku sudah tak sabar lagi!]],
  str_voice_1501471_17 = [[
- Sarapan hari ini adalah Tonkotsu Ramen!
- Kaldu tulang sedap kami tak ada tandingannya!]],
  str_voice_1501471_18 = [[
- Makan malamnya adalah Nogulee dan kulit pangsit babi!
- Makanan lezat sangat penting agar kita bisa tidur nyenyak!]],
  str_voice_1501471_19 = [[
- Sudah larut malam!
- Kau mau camilan tengah malam?]],
  str_voice_1501471_20 = [[
- Aku dan Anzu memang sering bertengkar.
- Namun, kami tahu bahwa Kaniya Ramen adalah yang terbaik!]],
  str_voice_1501471_21 = [[
- Illumina Federation? Aku tahu, kok! Mereka tinggal di Undercity!
- Mereka suka ramen tidak, ya?]],
  str_voice_1501471_22 = "- Kaniya Ramen…\n- Yang terbaik di dunia!",
  str_voice_1501471_23 = [[
- Eclipsite? Bisa dimakan? Rasanya enak? Bagaimana cara memasaknya?
- Entahlah, ayo kita coba!]],
  str_voice_1501471_24 = [[
- Pegawai kami sering bolos kerja.
- Untuk menguntit pendeta itu!]],
  str_voice_1501471_25 = [[
- Tamu yang mengenakan congsam itu sangat ramah.
- Dia selalu siap membantu kami mengusir pembuat onar.]],
  str_voice_1501471_26 = [[
- Favoritku?
- Tentu saja Kaniya Ramen!]],
  str_voice_1501471_27 = "- Aku tidak suka makanan yang rasanya tidak enak…\n- Orang yang suka buang-buang makanan memang sangat payah!",
  str_voice_1501471_28 = [[
- Menu hari ini di Soroz?
- Ramen, ramen, dan ramen!]],
  str_voice_1501471_29 = [[
- Semangkuk ramen!
- Terima kasih sudah membeli ramen kami!]],
  str_voice_1501471_30 = "- Ramen lezat…\n- Semangkuk lagi, ya!",
  str_voice_1501471_31 = [[
- Sup yang lebih kental!
- Mi yang lebih banyak!]],
  str_voice_1501471_32 = [[
- Renovasi kedai!
- Ya!]],
  str_voice_1501471_33 = [[
- Api kompor paling besar!
- Jangan sampai hangus!]],
  str_voice_1501471_34 = "- Siap berjualan!",
  str_voice_1501471_35 = "- Ramenmu sudah siap!",
  str_voice_1501471_36 = "- Silakan nikmati selagi masih panas!",
  str_voice_1501471_37 = "- Ini dia!",
  str_voice_1501471_38 = "- Mewah…\n- Ekstra besar…\n- Kaniya Ramen!",
  str_voice_1501471_39 = "- Serangan api berkobar!",
  str_voice_1501471_40 = "- Nih, ambil pancinya!",
  str_voice_1501471_41 = "- Saatnya ramen!",
  str_voice_1501471_42 = [[
- Terima kasih sudah membeli ramen kami!
- Rekomendasikan pada teman-temanmu, ya!]],
  str_voice_1501471_43 = "- Sup mi…\n- Semua terbelah…",
  str_voice_1501471_44 = [[
- Lapor! Kami menemukan dapur!
- Hihi! Mulai sekarang, biar kami yang urus makananmu!]],
  str_voice_1501471_45 = [[
- Hadiah!
- Terima kasih!]],
  str_voice_1501471_46 = [[
- Ini sangat mahal!
- Boleh kami simpan?]],
  str_voice_1501471_47 = [[
- Kita taruh di mana?
- Di restoran, dong!]],
  str_voice_1501471_48 = [[
- Tolong terimalah kupon makan gratis ini!
- Ini adalah bentuk terima kasih dari kami!]],
  str_voice_1501471_49 = [[
- Kami tidak hanya menjual ramen!
- Ada juga roti kukus dan pangsit! Resep terbaik dari seluruh dunia!]],
  str_voice_1501471_50 = [[
- Di dalam labu ini ada rahasia untuk membuat sup terlezat!
- Mata air pegunungan?
- Anzu! Jangan membocorkan rahasiaku keras-keras begitu!]],
  str_voice_1501471_51 = [[
- Kunci dari makanan yang lezat adalah perhatian.
- Dan kasih sayang!
- Dan persahabatan yang erat!]],
  str_voice_1501471_52 = "- Alchemy—\n- Stars!",
  str_voice_1501471_53 = "- Pembukaan akbar!",
  str_voice_1501471_54 = "- Bangun! Sarapan sudah siap!",
  str_voice_1501471_55 = "- Tamu kehormatan sudah makan siang?",
  str_voice_1501471_56 = "- Mau makan malam pakai apa?",
  str_voice_1501471_57 = [[
- Selamat Tahun Baru!
- Semangkuk mi pertama di tahun baru sudah siap!
- Ini ramen boga laut!]],
  str_voice_1201631_1 = "Saatnya asah otak! Anjing apa yang berkeliling untuk melihat pameran seni? Jawabannya adalah Tourdog. Kemarikan semua potongannya…",
  str_voice_1201631_2 = "Besar sekali kapal terbang ini! Seharusnya ini disebut Airship. Kenapa Colossus, sih?",
  str_voice_1201631_3 = "Aku tak keberatan merefleksikan kenyataan dalam karyaku, tapi lebih baik kalau kucampur dengan impian. Karya yang tak ada sentuhan impiannya jelas bakal jadi biasa-biasa saja…",
  str_voice_1201631_4 = "Mengulang karya? Tidak mungkin… Baiklah, tapi aku dapat bayaran lebih, 'kan?",
  str_voice_1201631_5 = "Pelukis butuh ruang agar bisa menyelesaikan karya idealnya dengan bebas…",
  str_voice_1201631_6 = "Warna hitam yang meriah dan berwarna? … Biar kucoba.",
  str_voice_1201631_7 = "Kisahnya akan terasa sedih, penuh gairah, menyenangkan, dan epik…",
  str_voice_1201631_8 = "Dengar. Berkat pelangganku, aku jadi bisa fokus pada permainan dan kontributor tamu. Kurasa orang Lumopolis… eh, maksudku orang Umbraton, tidak sepenuhnya buta.",
  str_voice_1201631_9 = "Hawa di Northland sangat dingin, tapi Aurora yang menari-nari begitu indah… Di sanalah impianku tentang Al***my St**s dimulai.",
  str_voice_1201631_10 = "Film animasi Al***my St**s… Wah, aku butuh sketsa kasarnya dulu. Eh, bukan! Sinopsisnya dulu.",
  str_voice_1201631_11 = "Menjaga tempat ini? Ya, aku punya pengalaman seperti itu saat bekerja paruh waktu dulu. Bagus, aku jadi punya kesempatan untuk mempelajari perangkat di sini…",
  str_voice_1201631_12 = "Beberapa hari ini aku mengundang banyak kontributor.. Aku jadi hampir tak sanggup membeli mantel sekarang. Hei, pemilik kapal udara, bolehkah aku pinjam pakaian?",
  str_voice_1201631_13 = "Beberapa gambar memang sangat bagus. Hanya saja keseluruhan polanya tidak sesuai dengan proyek kami. Pasti bagus kalau kami bisa menggunakannya, tapi kami pun tak bisa memaksakannya.",
  str_voice_1201631_14 = "Beberapa orang mendatangiku untuk mencari investor… Bagaimana aku tahu? Seharusnya mereka bertanya pada wanita kaya itu, Sheol.",
  str_voice_1201631_15 = "Selamat ulang tahun. Aku tak punya keik untukmu, tapi biar kubuatkan gambarnya untukmu…",
  str_voice_1201631_16 = "Sebentar lagi, hari kerja yang sibuk akan dimulai. Kau pasti bisa.",
  str_voice_1201631_17 = "Kau bangun pagi. Rajin sekali! Sepertinya merawat kapal ini memang impianmu.",
  str_voice_1201631_18 = "Masih bekerja? Jangan lupa makan. Kesehatanmu yang paling penting.",
  str_voice_1201631_19 = "Kau sama sekali tidak tidur? Aku tak bisa menahan kantukku… Ah…",
  str_voice_1201631_20 = "Hmmm, Umbraton… memang banyak dari kami yang berselera seni tinggi, tapi beberapa orang sangat sombong.",
  str_voice_1201631_21 = "Meskipun sifat orang-orang tua di Lumopolis itu kaku, mereka memperhatikan keindahan. Lagi pula, mencari uang itu sangat penting.",
  str_voice_1201631_22 = "Orang yang cepat bertindak akan meraih kesuksesan.",
  str_voice_1201631_23 = "Kurasa pemahaman artistik kita berbeda…",
  str_voice_1201631_24 = "Meskipun kelihatannya mata duitan, sebenarnya Taki sangat peduli pada detail dan memperhatikan keindahan.",
  str_voice_1201631_25 = "Hachi dan Gin? Mereka hanya penipu busuk yang menjual lukisan. Namun, mereka juga punya barang bagus, sih…",
  str_voice_1201631_26 = "Di sini ada pelukis? Cepat, perkenalkan aku…",
  str_voice_1201631_27 = "Aku benci orang yang suka setengah-setengah kalau soal seni.",
  str_voice_1201631_28 = "Wow, ada banyak peralatan di tempat ini. Mungkin kita bisa menggunakannya untuk Al***my St**s…",
  str_voice_1201631_29 = "Kau bisa melukis? Atau kenal orang yang bisa melukis? Namaku Tourdog. Aku mencari orang yang mau bergabung dengan proyekku, Al***my St**s…",
  str_voice_1201631_30 = "Aku bisa merasakannya!",
  str_voice_1201631_31 = "Aku bisa memenuhi permintaan apa pun.",
  str_voice_1201631_32 = "Hanya butuh waktu 3 detik.",
  str_voice_1201631_33 = "Ha! Kemajuan besar!",
  str_voice_1201631_34 = "Saatnya bekerja…",
  str_voice_1201631_35 = "Sekarang aku sudah punya semua bahannya.",
  str_voice_1201631_36 = "Aku siap kapan pun kau siap.",
  str_voice_1201631_37 = "Ayo jalan!",
  str_voice_1201631_38 = "Fokus!",
  str_voice_1201631_39 = "Wow! Manis sekali!",
  str_voice_1201631_40 = "Semoga berhasil!",
  str_voice_1201631_41 = "Aku bisa melakukannya dengan caramu!",
  str_voice_1201631_42 = "Satu langkah lebih dekat dengan tujuan!",
  str_voice_1201631_43 = "Eh… Kau saja yang mengerjakan bagian enaknya…",
  str_voice_1201631_44 = "Ayo bermain Al***my St**s!",
  str_voice_1201631_45 = "Pasti luar biasa kalau ini adalah lukisan yang keren…",
  str_voice_1201631_46 = "Aku akan menyertakannya di Al***my St**s.",
  str_voice_1201631_47 = "Aku akan segera memberimu akun beta test Al***my St**s!",
  str_voice_1201631_48 = "Ohhhh! Aku merasa terinspirasi!",
  str_voice_1201631_49 = "Saat menjelajahi reruntuhan, aku tak sengaja menemukan peralatan itu. Jadi, aku memulainya di Al***my St**s.",
  str_voice_1201631_50 = "Tahun-tahun pertama pembuatan game ini terasa sangat menantang. Kurasa kemampuanku sendiri masih jauh dari kata cukup… Untungnya, aku berhasil mencari bantuan teman-teman baruku, bahkan mendatangkan investor.",
  str_voice_1201631_51 = "Karena lahir di Northland, aku jadi terinspirasi oleh Aurora. Namun, panduan game itu yang menuntunku ke Umbraton.",
  str_voice_1201631_52 = "Alchemy Stars.",
  str_voice_1201631_53 = "Tentu.",
  str_voice_1201631_54 = "Saatnya mulai melukis!",
  str_voice_1201631_55 = "Tidur siang? Aduh, aku tak punya kemewahan semacam itu!",
  str_voice_1201631_56 = "Aku hanya sedikit lembur.",
  str_voice_1201631_57 = "Selamat Tahun Baru!",
  str_voice_1601481_1 = "Kau bisa mengemudi? Kalau kau tertarik, aku bisa mengajarimu. Aku ini pengemudi veteran, tak banyak yang bisa mengalahkanku dalam balapan.",
  str_voice_1601481_2 = "Yah, sepertinya kau dekat dengan gadis-gadis dari Illumina dan Lumopolis itu. Kau memang luar biasa, ya? Hati-hati, Tuan Popularitas, jangan berbuat aneh-aneh.",
  str_voice_1601481_3 = "Aku suka sendirian. Tak ada yang melarangku dan tak ada yang kukecewakan… Kesepian? Sama sekali tidak. Ada gugusan bintang dan embusan angin yang menemaniku di alam liar.",
  str_voice_1601481_4 = "Aku bisa mengemudikan berbagai macam kendaraan, tapi kalau Colossus yang bisa terbang? Wah, baru kali ini aku melihatnya. Aku sangat ingin memilotinya… Hah? Pendaratannya agak sulit?",
  str_voice_1601481_5 = "Hei, apa kau mau menunjukkan sedikit… \"kemampuan psikis\" yang kaukuasai itu? Kau tahu yang kupikirkan sekarang? Takut? Oh, sangat membosankan.",
  str_voice_1601481_6 = "Karena mereka semua menyebutmu \"Navigator\", bagaimana kalau kau jadi navigatorku di Blazing Rally berikutnya? Milikku seorang… heheh. Wah, kau jadi tersipu-sipu!",
  str_voice_1601481_7 = "Kau tak takut mendekatiku, tidak seperti orang-orang membosankan yang hanya berani menatapku dari kejauhan. Kau pantas mendapat hadiah… Sini, mendekatlah.",
  str_voice_1601481_8 = "Aku memang pernah bilang bahwa aku suka sendirian, tapi kalau kau ingin tempat atau ruang untuk beristirahat… kursi penumpangku selalu ada untukmu.",
  str_voice_1601481_9 = "Sudah lama tak ada orang yang memanggilku dengan nama asliku, Safia… Coba katakan sekali lagi, ya? Pura-puranya aku sedang mabuk.",
  str_voice_1601481_10 = "Kau tidak benar-benar menghukumku, 'kan? Kuberi waktu tiga detik untuk memikirkan kembali posisimu.",
  str_voice_1601481_11 = "Ingin aku tetap di sini? Membosankan sekali. Bagaimana kalau kita melakukan sesuatu… yang menyenangkan bersama-sama?",
  str_voice_1601481_12 = "Orang-orang Rediesel Wrench yang berisik itu pintar menghibur. Begitu juga denganmu.",
  str_voice_1601481_13 = "Ada kabar baru? Yah, jangan disimpan sendirian! Tak ada info intel yang tak berguna di dunia ini.",
  str_voice_1601481_14 = "Apa maumu? Kau tak akan dapat apa-apa dari pelecehan… tapi kau manis juga, jadi akan kumaafkan… kali ini saja.",
  str_voice_1601481_15 = "Selamat ulang tahun! Sayangnya, aku tak punya hadiah untukmu, nih. Bagaimana kalau aku saja yang jadi hadiahnya? Aku hanya menggodamu, kok.",
  str_voice_1601481_16 = "Mau berburu info intel denganku? Investigasi langsung adalah langkah pertama dalam penjelajahan apa pun.",
  str_voice_1601481_17 = "Oh? Tak perlu menyeretmu dari ranjang, ya? Anak pintar.",
  str_voice_1601481_18 = "Yah, waktunya mencari tempat untuk bersantai. Tertarik? Sebaiknya cepat kau putuskan. Aku tak mau menunggu.",
  str_voice_1601481_19 = "Wah, aku kecewa. Tadinya aku berharap bisa melihatmu tidur pulas… Ternyata, kau belum tidur… Malam masih panjang. Paham, 'kan?",
  str_voice_1601481_20 = "Rediesel Wrench adalah keluargaku. Aku memang jarang pulang, tapi ikatan ini… membawaku lebih jauh.",
  str_voice_1601481_21 = "Masa lalu yang kualami dengan mereka… bukan sesuatu yang bisa diceritakan dengan singkat.",
  str_voice_1601481_22 = "Jalani hidup sepenuhnya? Mungkin.",
  str_voice_1601481_23 = "Eclipsite… Andai saja mereka tak pernah ada.",
  str_voice_1601481_24 = "Di antara semua anggota Rediesel Wrench, hanya Jona yang benar-benar bisa minum denganku. Roy? Dia jadi tak tahu adat kalau mabuk.",
  str_voice_1601481_25 = "Tak kusangka Roy yang dulu akan jadi tukang mengomel sekarang… Jangan jadi seperti dia, ya.",
  str_voice_1601481_26 = "Yang kusukai? Tentu saja anak laki-laki yang manis. Tenang, aku tak akan memakanmu, kok… Belum.",
  str_voice_1601481_27 = "Kudengar ada banyak peraturan di Lumopolis dan Illumina… Memikirkannya saja membuatku tercekik.",
  str_voice_1601481_28 = "Colossus raksasa yang masih dalam keadaan baik… Wah, kau pasti sangat memperhatikannya.",
  str_voice_1601481_29 = "Ah hah! Kau pasti Caelestite yang dibicarakan semua orang itu. Kuakui bahwa wajahmu imut meski namamu terdengar norak. Mendekat ke sini, ya?",
  str_voice_1601481_30 = "Lagi… lagi!",
  str_voice_1601481_31 = "Seru sekali!",
  str_voice_1601481_32 = "Seolah-olah aku mabuk setelah menenggak berbotol-botol anggur lezat…",
  str_voice_1601481_33 = "Baru kali ini aku merasa begini…",
  str_voice_1601481_34 = "Kau hanya memikirkanku sekarang?",
  str_voice_1601481_35 = "Jangan membuat aku menunggu lama.",
  str_voice_1601481_36 = "Lynx tak pernah tidur.",
  str_voice_1601481_37 = "Tembak, Cerulean Mirage!",
  str_voice_1601481_38 = "Freeze Detonator!",
  str_voice_1601481_39 = "Kau merasa kepanasan, tidak?",
  str_voice_1601481_40 = "Dinginkan!",
  str_voice_1601481_41 = "Baiklah. Sebaiknya kau membayarnya.",
  str_voice_1601481_42 = "Bagaimana kau berniat membayarku?",
  str_voice_1601481_43 = "Lagi! Jangan berhenti!",
  str_voice_1601481_44 = "Bagaimana kalau kita jalan-jalan dengan Colossus?",
  str_voice_1601481_45 = "Kau pasti juga memberikannya kepada banyak gadis cantik, 'kan? Aku tahu, kok.",
  str_voice_1601481_46 = "Kau tahu seleraku, ya… Kau berencana melakukan sesuatu denganku?",
  str_voice_1601481_47 = "Terima kasih, Anak Pintar. Sini, mendekatlah. *Cium*",
  str_voice_1601481_48 = "Kau penuh perhatian, ya. Aku akan menanggapimu dengan serius, tahu? Jangan menggoda orang dewasa.",
  str_voice_1601481_49 = "Aku sudah mulai bermain-main dengan senjata saat masih di dalam kandungan! Sayangnya, tak ada saksi mata yang bisa membuktikannya.",
  str_voice_1601481_50 = "Bisakah kaubayangkan kau menyeret langkahmu dengan perasaan putus asa di sepanjang gurun yang tak berujung, tak bisa menemukan jalan pulang… atau dirimu yang dulu?",
  str_voice_1601481_51 = "Aku tak mau sejarah itu berulang… Sekarang, Rediesel Wrench adalah rumahku dan aku akan melindunginya dengan caraku sendiri.",
  str_voice_1601481_52 = "Alchemy Stars!",
  str_voice_1601481_53 = "Hei.",
  str_voice_1601481_54 = "Pagi.",
  str_voice_1601481_55 = "Mau minum-minum denganku?",
  str_voice_1601481_56 = "Hah! Selamat malam!",
  str_voice_1601481_57 = "Selamat Tahun Baru! Mau menunjukkan peningkatan di tahun ini? Kutunggu, ya!",
  str_voice_1501491_1 = "Rahasia tentang logistik? Tak ada rahasia-rahasiaan… Kalaupun ada… mungkin sif tengah malam yang tak ada habisnya? Hah? Tidak kedengaran seperti rahasia Rediesel Wrench? Hahaha… Benar juga.",
  str_voice_1501491_2 = "Aku menyatukan Anak-anak Manis itu dengan bahan-bahan sisa. Entah kenapa bisa berhasil, aku hanya beruntung… Namanya imut? Yah, Zeta yang menamainya.",
  str_voice_1501491_3 = "Karavan di Umbraton makin pintar, jadi kami harus ganti taktik. Hah? Kau tertarik merencanakan penyergapan? Kau bisa membaca peta topografi? Sini, biar kuajari.",
  str_voice_1501491_4 = "Meskipun aku ingin membuatkanmu boneka, akan terlalu sulit kalau bonekanya berbentuk Colossus. Bagaimana kalau Eclipsite semangka saja?",
  str_voice_1501491_5 = "Kemampuan pertempuran jarak dekat? Tentu saja, tapi kau harus memperhatikan, ya? Nah, lempar pasirnya ke mata musuh, lalu lakukan serangan mendadak! Itu selalu berhasil! Curang? Yang penting menang, 'kan?",
  str_voice_1501491_6 = "Kalau dulu kau dan teman-temanmu ada di sini selama zaman perang, mungkin semuanya akan berbeda sekarang… Kau tidak paham omonganku? Jadi, seperti ini ya \"kesenjangan generasi\" yang orang bilang?",
  str_voice_1501491_7 = "Anak Muda, coba kau pertimbangkan kembali untuk bergabung dengan Rediesel Wrench, ya? Sayang sekali. Akan tetapi, pintu kami selalu terbuka untukmu.",
  str_voice_1501491_8 = "Aku orang yang terikat oleh masa lalu. Akan kuserahkan tugas menjadi pahlawan yang menyelamatkan dunia ini kepadamu. Sudah kuserahkan segalanya untuk berpegang pada yang kumiliki.",
  str_voice_1501491_9 = "Yah… Memang beginilah kalau sudah tua, 'kan? Menyesali masa lalu… Memang mustahil untuk melupakannya, tapi menciptakan kenangan baru denganmu bukanlah ide yang buruk.",
  str_voice_1501491_10 = "Hei, punya waktu untuk mengobrol, tidak? Mau dengar lebih banyak tentang Eclipsite atau belajar cara bertahan di gurun? Jangan tinggalkan aku sendirian! Aku merasa sangat kesepian!",
  str_voice_1501491_11 = "Meminta orang seperti aku untuk berdiri saja di sini? Anak-anak muda zaman sekarang memang aneh… Sudahlah. Aku akan menjagamu dan menyelesaikan masalahmu.",
  str_voice_1501491_12 = "Bertarung? Rasanya aku masih bisa, tapi punggungku… Astaga, masa-masa kejayaanku memang sudah berlalu.",
  str_voice_1501491_13 = "Mau permen? Aku punya banyak di saku. Kusarankan yang rasa kalajengking merah!",
  str_voice_1501491_14 = "Fyuh… Hm? Haha! Tidak ada apa-apa, kok. Aku hanya bermimpi buruk semalam. Itu saja.",
  str_voice_1501491_15 = "Ini hari ulang tahunmu? Luar biasa! Kita harus mengadakan pesta besar!",
  str_voice_1501491_16 = "Ini akan jadi hari yang sibuk lagi… Aku hanya ingin bersantai… Jangan terlalu memaksakan diri.",
  str_voice_1501491_17 = "Yah apa tahu! Jarang melihat anak muda bangun sepagi ini, setidaknya di tempat kami...",
  str_voice_1501491_18 = "Bagaimana kabarmu hari ini? Kau tetap harus makan dan tidur meski ada hal yang mengusik pikiranmu.",
  str_voice_1501491_19 = "Waktunya anak baik tidur. Tak bisa tidur, ya? Mau mendengar dongeng pengantar tidur?",
  str_voice_1501491_20 = "Akan kulakukan apa saja demi Rediesel Wrench.",
  str_voice_1501491_21 = "Illumina…? Aku tak begitu paham, tapi aku tahu semua rute suplainya.",
  str_voice_1501491_22 = "Jalani hidup sepenuhnya!",
  str_voice_1501491_23 = "Kenapa aku sangat memahami Eclipsite? Karena… Eh, b-bukan apa-apa.",
  str_voice_1501491_24 = "Tentu saja Azure bisa menjaga dirinya sendiri. Namun, jangan lupa menulis surat sesekali, bukan hanya mengirim informasi.",
  str_voice_1501491_25 = "Si Sinsa memang pemimpin yang baik. Selalu menerjang maju dan tak pernah menoleh ke belakang.",
  str_voice_1501491_26 = "Membuat boneka terasa seperti melakukan terapi. Itu benar! Namun, aku malu mengakuinya…",
  str_voice_1501491_27 = "Sesuatu yang kubenci? Wah, kalau sudah setua aku, nanti kau akan tahu bahwa tak banyak lagi yang bisa dibenci.",
  str_voice_1501491_28 = "Oh! Kau menjaga kondisi Colossus dengan sangat baik.",
  str_voice_1501491_29 = "Hei! Aku Roy dari Rediesel Wrench. Maafkan si kecil ini karena telah merepotkanmu. Hahah! Senang bertemu denganmu!",
  str_voice_1501491_30 = "Wah, wah, rasanya luar biasa!",
  str_voice_1501491_31 = "Akan tetapi, sebaiknya jangan berharap banyak dari pria tua seperti aku…",
  str_voice_1501491_32 = "Hmm… Rasanya aku jadi muda lagi, sedikit.",
  str_voice_1501491_33 = "Lebih banyak tanggung jawab…?",
  str_voice_1501491_34 = "Sepertinya aku harus berusaha keras.",
  str_voice_1501491_35 = "Hubungi aku kapan saja.",
  str_voice_1501491_36 = "Hei. Apa yang kaubutuhkan?",
  str_voice_1501491_37 = "Hmmm… Biar kulihat…",
  str_voice_1501491_38 = "Saatnya menambahkan glukosa.",
  str_voice_1501491_39 = "Rasakan ini!",
  str_voice_1501491_40 = "Menyeramkan sekali⁠—TIDAK!",
  str_voice_1501491_41 = "Giliranku, ya? Sungguh? Baiklah…",
  str_voice_1501491_42 = "Hei, aku sudah berusaha semampuku.",
  str_voice_1501491_43 = "Nak, kau baik-baik saja?",
  str_voice_1501491_44 = "Bagaimana kalau kumodifikasi Colossus itu dan kutambahkan beberapa fungsi baru?",
  str_voice_1501491_45 = "Iya, iya. Lain kali jangan sungkan.",
  str_voice_1501491_46 = "Oh? Ini sangat berharga. Kau yakin mau memberikannya kepadaku?",
  str_voice_1501491_47 = "Seharusnya kau memberikannya kepada orang yang kaupedulikan, tahu…?",
  str_voice_1501491_48 = "Aku akan membalas kebaikanmu. Mau apa? Kau boleh minta apa saja…",
  str_voice_1501491_49 = "Meskipun banyak menuntut dan kadang-kacang cukup nakal, sebenarnya mereka anak-anak yang baik. Aku terlalu protektif pada mereka, ya? Huh… Mungkin sedikit… Sedikit sekali.",
  str_voice_1501491_50 = "Yah, Sinsa memang benar-benar jadi pemimpin yang baik… Hei, mau baca beberapa puisi yang dia tulis saat masih kecil? Imut, lo!",
  str_voice_1501491_51 = "Alasanku bergabung dengan Rediesel Wrench? Yah, ada yang bilang, \"ayo buat keluarga besar dan bahagia bersama-sama\" seperti orang dungu… jadi aku ikut bergabung seperti orang dungu.",
  str_voice_1501491_52 = "Alchemy Stars!",
  str_voice_1501491_53 = "Bagaimana keadaan akhir-akhir ini?",
  str_voice_1501491_54 = "Pagi, anak muda!",
  str_voice_1501491_55 = "Jangan lupa makan siang!",
  str_voice_1501491_56 = "Orang harus tidur nyenyak di malam hari agar tumbuh tinggi dan kuat.",
  str_voice_1501491_57 = "Selamat Tahun Baru, Caelestite!",
  str_voice_1601501_1 = "Aku bisa jadi sangat penurut, tetapi tidak terhadap semua orang. Apakah artinya itu membuatku jadi pembangkang sekarang?",
  str_voice_1601501_2 = "Ajaib sekali bahwa air dapat mengalir dari mata. Aku menyukai air mata, tetapi orang-orang bilang padaku bahwa air mata selalu berkaitan dengan nestapa… Apakah nestapa adalah perasaan yang buruk?",
  str_voice_1601501_3 = "Ada banyak sekali ibu di dunia ini… Apakah ibuku spesial?",
  str_voice_1601501_4 = "Perutku keroncongan. Laparkah ini? Perasaan ini ajaib seolah-olah ada yang sedang berbicara dari dalam tubuhku.",
  str_voice_1601501_5 = "Apakah Navigator akan takut jika tampangku masih seperti dulu? Sekarang aku mengerti rasa takut… Aku tidak ingin menakuti siapa pun.",
  str_voice_1601501_6 = "Siapakah aku? Dari mana aku berasal? Ke mana tujuanku? Navigator, apakah pertanyaan ini akan membuat kepalamu pusing sepertiku?",
  str_voice_1601501_7 = "Navigator selalu berkata bahwa aku tidak harus menuruti semua orang. Namun, aku memilih untuk mematuhi Navigator dan ingin dia memberitahuku hal yang harus kulakukan.",
  str_voice_1601501_8 = "Kapan pun Navigator menatapku, aku akan menyentuh telingaku secara tak sadar. Betapa anehnya! Seperti mantra ajaib… Oh! Itu namanya malu, ya?",
  str_voice_1601501_9 = "Aku memperoleh perasaan selalu ingin belajar dari Navigator. Navigator, apakah ini kasih ibu?",
  str_voice_1601501_10 = "Tetap tinggal di sini. Aku dapat melakukan quest semacam ini dengan sangat baik. Aku biasa tetap tinggal di rumah dan merawat ibuku dan rumah May.",
  str_voice_1601501_11 = "Siap. Setiap perintah dari Navigator akan dipenuhi.",
  str_voice_1601501_12 = "Kadang-kadang, May muncul dalam pikiranku. Kurasa, May sedang merawat kucing putihnya. May tidak suka bulu yang kusut.",
  str_voice_1601501_13 = "… Organ tubuh mana yang paling penting, jantung atau otak?",
  str_voice_1601501_14 = "Apa yang harus kulakukan? Tanpa perintah yang harus dilaksanakan, aku tak tahu apa yang harus kulakukan.",
  str_voice_1601501_15 = "Ulang tahun adalah hari yang luar biasa. Semoga kau bahagia, Navigator.",
  str_voice_1601501_16 = "Aku sedang latihan bernapas. Hirup udara yang sejuk, lalu embuskan napas yang hangat.",
  str_voice_1601501_17 = "Saat pagi datang, dunia kembali hidup. Aku pun kembali hidup… Apakah aku salah bicara lagi?",
  str_voice_1601501_18 = "Jangan lupa gosok gigi dan mencuci mukamu. Maaf. Aku biasa mengatakan hal ini pada jam-jam seperti ini.",
  str_voice_1601501_19 = "Aku masih tak terbiasa untuk menutup mataku pada malam hari lalu tidur… Apakah kau begitu juga, Navigator?",
  str_voice_1601501_20 = "Aku adalah anggota True Order. Setiap hari aku berdoa agar memperoleh Truth.",
  str_voice_1601501_21 = "Aku mendengar kisah tentang Northland dalam buku-buku cerita. Itu, lo, buku-buku yang suka dibaca oleh bocah-bocah.",
  str_voice_1601501_22 = "Semoga Truth… memberkatimu.",
  str_voice_1601501_23 = "Banyak orang meminta tolong untuk menumpas makhluk itu. Mereka menyebutnya Eclipsite.",
  str_voice_1601501_24 = "May adalah adik perempuanku… Sebaiknya aku menjaganya langsung atau menunggu perintah ibu?",
  str_voice_1601501_25 = "Lady Victoria mengundangku ke True Order. Aku akan mendengarkan apa pun yang dikatakannya.",
  str_voice_1601501_26 = "Bagaimana rasanya menyukai sesuatu? Apakah itu akan membuatku bahagia?",
  str_voice_1601501_27 = "Aku tahu rasa ketidaksukaan. Aku dapat merasakan perasaan tersebut saat berjuang untuk menyelesaikan sebuah quest.",
  str_voice_1601501_28 = "Sebuah rumah yang besar dan sebuah kendaraan.",
  str_voice_1601501_29 = "Akhirnya! Aku sudah menunggu perintah Navigator sejak lama. Kau tak punya perintah untukku? Tak ada quest juga?",
  str_voice_1601501_30 = "Aku merasa bahagia.",
  str_voice_1601501_31 = "Rasanya begitu takut.",
  str_voice_1601501_32 = "Seperti banyak komponen telah tergantikan.",
  str_voice_1601501_33 = "Ini menyenangkan. Aku suka sekali.",
  str_voice_1601501_34 = "Baiklah. Siap.",
  str_voice_1601501_35 = "Aku siap.",
  str_voice_1601501_36 = "Aku menunggu perintahmu.",
  str_voice_1601501_37 = "Biarkan lautnya pasang.",
  str_voice_1601501_38 = "Ini domainku.",
  str_voice_1601501_39 = "Crimson Scythe sangatlah tajam.",
  str_voice_1601501_40 = "Tidak pernah meleset.",
  str_voice_1601501_41 = "Aku kaptennya. Pokoknya beres.",
  str_voice_1601501_42 = "Lapor! Aku telah menyelesaikan quest tersebut.",
  str_voice_1601501_43 = "Aku tak akan menyerah. Aku akan terus mencoba.",
  str_voice_1601501_44 = "Apakah ia punya emosi?",
  str_voice_1601501_45 = "Hadiah biasa buatku. Terima kasih.",
  str_voice_1601501_46 = "Hadiah cantik buatku. Terima kasih.",
  str_voice_1601501_47 = "Baiklah… Tak seharusnya aku mengomentari hadiah.",
  str_voice_1601501_48 = "Aku sangat menyukainya. Terima kasih, Navigator.",
  str_voice_1601501_49 = "Ibu memintaku untuk mengasuh seorang bayi bernama May… Bayi pasti menangis jika tidak ada yang mengasuhnya. Aku tak dapat mengingat apakah ada yang pernah mengasuhku dulu.",
  str_voice_1601501_50 = "Sebelumnya, kukira ibu hanyalah sebuah nama. Setelah itu, kusadari bahwa ibu adalah… ya hanya ibuku.",
  str_voice_1601501_51 = "Ibu bukanlah rumah. Begitu pula May. Kuselesaikan semua quest ini, tetapi tidak ada yang kembali. Jadi, kuganti semua komponenku sebanyak 502 kali.",
  str_voice_1601501_52 = "Alchemy… Stars.",
  str_voice_1601501_53 = "Halo.",
  str_voice_1601501_54 = "Semoga pagimu menyenangkan, Navigator.",
  str_voice_1601501_55 = "Sudah siang. Apakah kau lapar, Navigator?",
  str_voice_1601501_56 = "Selamat malam.",
  str_voice_1601501_57 = "Apakah tahun baru selalu berbeda dengan masa lalu?",
  str_voice_1601511_1 = "Domba hitamnya adalah Isaac. Bulunya yang panas mengerikan… Woy! Kau memperhatikan tidak? Aku menulis lagu anak-anak yang baru ini untuk menghangatkan hati kaum yang kurang beruntung.",
  str_voice_1601511_2 = "Kau kenal bocah-bocah di Lumopolis itu? Siapa saja nama mereka? Ayam? Kukuruyuk? Bukan! Bukan itu… Jangan sampai kulihat mereka lagi atau akan kupaksa mereka menyanyikan lagu anak-anak ciptaanku!",
  str_voice_1601511_3 = "Kenapa gagak mirip dengan meja? Kau tak tahu jawabannya? Hmm… Kenapa memangnya? Kepalaku sakit!",
  str_voice_1601511_4 = "Hoam… Aku mengantuk sekali belakangan ini. Tubuhku pasti sedang bertumbuh… Ya, aku akan tumbuh lebih tinggi daripada Navigator…",
  str_voice_1601511_5 = "Tanduk sang biri-biri tak mampu lagi menahan kekuatannya yang terus bertambah. Lewat matanya yang merah, aku telah menyaksikan semua kebohongan tersebut!",
  str_voice_1601511_6 = "Tanduk yang runcing itu merobek tirai malam. Magma panas yang menyala-nyala mengaliri tanah-tanah yang rusak. Di kedalaman kepalaku terpendam benih kebenaran!",
  str_voice_1601511_7 = "Menurutku, kau sangat menyukai Isaac. Namun, aku tak bisa melepaskannya! Dia telah menyelamatkanku! Kau tidak berniat untuk mengambilnya, 'kan?",
  str_voice_1601511_8 = "Satu ditambah satu sama dengan dua. Kau dan aku bersama lebih besar daripada dua. Rima teka-teki ini punya banyak jawaban. Ayolah. Setidaknya berikan satu jawaban untukku.",
  str_voice_1601511_9 = "Aku baik-baik saja. Tiba-tiba aku mendapatkan inspirasi! Lagu anak-anak yang baru! Terima kasih, Navigatorku sayang, untuk inspirasinya.",
  str_voice_1601511_10 = "Tik tok, waktunya kabur. Byar byur, hajar layarnya. Di ujung layar yang besar berdirilah si Navigator. Di belakang Navigator, siapa itu?",
  str_voice_1601511_11 = "Hmm? Ada daging di sini yang bisa dimakan? Apa saja deh kecuali domba… Tak ada?",
  str_voice_1601511_12 = "Yang kupunya hanyalah lagu anak-anak. Lagu anak-anak ciptaanku membuatku kaya! Ah hahahahah!",
  str_voice_1601511_13 = "Mbeek… Kenapa mukanya begitu? Ini bahasa Isaac. Untuk menghormati Isaac, ayo coba mengembik setelah kucontohkan.",
  str_voice_1601511_14 = "Aku bukan orang aneh! Duh, aduh… Mimpi buruk lagi. Semoga aku tak membuatmu takut. Hoam… Aku harus tidur lagi.",
  str_voice_1601511_15 = "Selamat ulang tahun! Mari kusiapkan pesta kembang api lengkap dengan magma!",
  str_voice_1601511_16 = "Kau sibuk apa sih setiap hari? Hmm… Membosankan… Hoam… Bagaimana kalau kunyanyikan lagu anak-anak buatmu?",
  str_voice_1601511_17 = "Hoam… Mmm, betapa enaknya tidur… Aku kurang tidur hari ini. Aku akan tidur sebentar.",
  str_voice_1601511_18 = "Ta-da! Ini saatnya makan malam yang dinanti-nanti! Malam ini kita makan daging atau daging?",
  str_voice_1601511_19 = "Ada yang belum tidur pada saat yang paling enak begini! Hoam… Ya sudahlah. Aku tak melihat apa pun.",
  str_voice_1601511_20 = "Sejumlah anggota True Order dapat memahami beberapa lagu anak-anak ciptaanku. Jauh lebih baik daripada di tempat lain.",
  str_voice_1601511_21 = "Lumopolis… Lumopolis! Apatis… Penuh perhatian! Pantas diabaikan… Biarkan aku pergi! Tidak, aku tak akan pernah kembali kemari! Tak akan pernah!",
  str_voice_1601511_22 = "Semoga Truth memberkatimu.",
  str_voice_1601511_23 = "Eclipsite dan kami saling tarik-menarik seperti dua magnet… Sudah menjadi takdir kami untuk bertemu dan menghancurkan satu sama lain. Hahahahah!",
  str_voice_1601511_24 = "Hanya Victoria yang paling mengerti aku. Ya! Aku harus menulis lagu anak-anak baru untuknya!",
  str_voice_1601511_25 = "Faust selalu tersenyum, tetapi jujur saja menurutku dia tak memahami lagu anak-anak ciptaanku sama sekali.",
  str_voice_1601511_26 = "Ah? Kau benar-benar perlu mengajukan pertanyaan ini? Aku suka lagu anak-anak. Memangnya apa lagi selain itu? Mungkin tidur.",
  str_voice_1601511_27 = "Aku sangat membenci orang-orang yang tak mau menyimak lagu anak-anak ciptaanku… Hei, jangan bilang kau termasuk orang-orang seperti itu!",
  str_voice_1601511_28 = "Hoam… Colossus? Ranjang yang bisa bergerak… Memangnya aku akan tidur lebih nyenyak? Hoam…",
  str_voice_1601511_29 = "Hey, Navigator. Hoam… Oh! Kau datang jauh-jauh ke sini untuk menyimak lagu anak-anak ciptaanku, kan? Ya, ya, ya!",
  str_voice_1601511_30 = "Kemarilah dan saksikan! Hahahah!",
  str_voice_1601511_31 = "Iya! Aku baru saja menulis lagu anak-anak baru!",
  str_voice_1601511_32 = "Perasaan yang luar biasa!",
  str_voice_1601511_33 = "Kekuatan yang tak tertahankan!",
  str_voice_1601511_34 = "Hmm? Selesai sebentar lagi?",
  str_voice_1601511_35 = "Jangan lupa bangunkan aku, oke?",
  str_voice_1601511_36 = "Aku sudah tidur.",
  str_voice_1601511_37 = "Isaac, ayo!",
  str_voice_1601511_38 = "Ini pelajaran buatmu!",
  str_voice_1601511_39 = "Magma Blast!",
  str_voice_1601511_40 = "Lahap semuanya, Magma!",
  str_voice_1601511_41 = "Kapten? Hahahah. Supaya semua orang menuruti omonganku!",
  str_voice_1601511_42 = "Aku boleh kembali tidur?",
  str_voice_1601511_43 = "Membosankan… Membosankan, membosankan, dan membosankan!",
  str_voice_1601511_44 = "Aku tersenyum kepadanya tapi dia tak membalas senyumku. Kaca ini memantulkan cahaya dengan cara yang menarik.",
  str_voice_1601511_45 = "Hoam… Hmm, akan kuterima.",
  str_voice_1601511_46 = "Wuu-huu! Terima kasih!",
  str_voice_1601511_47 = "Hmm? Tentu, akan kusimpan.",
  str_voice_1601511_48 = "Ini keren!",
  str_voice_1601511_49 = "Menurutku, orang yang tidak punya tujuan hidup adalah orang yang anehnya keterlaluan. Bukankah arti hidup sudah digariskan sejak lahir?",
  str_voice_1601511_50 = "Pria itu menjanjikanku sebuah petualangan. Hal tersebut lalu menjadi perjalanan pertamaku… Ahhhh… Lalu dia mendorongku. Aku jatuh! Jatuh!",
  str_voice_1601511_51 = "Menjalani kehidupan nomaden bukanlah hal buruk sih, tetapi Victoria sudah menyiapkan tempat tidur yang sangat nyaman buatku!",
  str_voice_1601511_52 = "Alchemy Stars…",
  str_voice_1601511_53 = "Hoahm…",
  str_voice_1601511_54 = "Pagi, dombaku.",
  str_voice_1601511_55 = "Makanan lezat sudah siap!",
  str_voice_1601511_56 = "Akhirnya, saatnya tidur…",
  str_voice_1601511_57 = "Tahun baru begitu manis. Tahun baru begitu menakjubkan. Tahun baru perlu lagu anak-anak baru!",
  str_voice_1501521_1 = "Apa lihat-lihat? Pergi sana atau kuhajar kau! Kau tidak takut? Lain kali aku harus coba cara lain…",
  str_voice_1501521_2 = "Jahitanku? Ahahah. Jahitanku berbeda-beda. Bagus kan? Silakan coba saja.",
  str_voice_1501521_3 = "Itu, di sana Beau manisku… Ah! Jangan salah paham. Aku sedang bicara dengan Beauku. Tidakkah kaulihat bola bulu yang besar ini?",
  str_voice_1501521_4 = "Bulu yang dihasilkan oleh Beauku adalah yang terbaik. Bulunya bisa dibuat menjadi benang yang paling kuat. Kau pikir dari mana aku mendapatkan benang jahitku ini?",
  str_voice_1501521_5 = "Menurutmu, aku urutan berapa di True Order? Tunggu! Aku belum siap… Jangan katakan sekarang.",
  str_voice_1501521_6 = "Tidakkah kau mengerti bahwa semua anak baik memperoleh pujian? Uhuk… Sekarang giliranmu. Apa yang akan kaukatakan? Hmm… Tampaknya kau tidak mengerti.",
  str_voice_1501521_7 = "Navigator, sudah 68 detik kau tak berbicara kepadaku. Aku di sampingmu, tetapi kau diam saja… Kau marah?",
  str_voice_1501521_8 = "Hmm… Ah, tidak. Aku sedang merenungkan masalah serius. Enaknya Beauku memanggilmu paman atau kakek, ya?",
  str_voice_1501521_9 = "Ssst… Aku punya rahasia sangat penting yang ingin kuceritakan padamu. Aku mengumpulkan banyak kumis kucing di tasku ini. Demi keberuntungan!",
  str_voice_1501521_10 = "Aku tidak pernah malas bahkan pada waktu senggangku. Navigator, janji ya! Jangan lupa bahwa aku di sini.",
  str_voice_1501521_11 = "Apakah ini quest baruku? Akankah orang-orang menyukaiku jika quest ini kuselesaikan?",
  str_voice_1501521_12 = "Mengapa pejalan kaki itu melirikku? Dia pasti punya masalah denganku…",
  str_voice_1501521_13 = "Beau, berhenti! Sayangku ini senang sekali kabur. Aku benar-benar khawatir.",
  str_voice_1501521_14 = "Si kecil itu tersenyum kepadaku… Aku harus bagaimana?",
  str_voice_1501521_15 = "Begitu banyak orang mengucapkan selamat ulang tahun kepadamu… Aku sangat iri…",
  str_voice_1501521_16 = "Beauku suka tidur pada siang hari. Bagaimana dengan Beaumu? Oh… Kau kan tidak punya anak. Sayang sekali.",
  str_voice_1501521_17 = "Beauku bangun pagi. Sebagai seorang ibu, aku harus bangun lebih pagi. Tak ada waktu untuk mengobrol. Aku harus menyiapkan sarapan untuk Beau.",
  str_voice_1501521_18 = "Jangan lupa gosok gigi dan mencuci mukamu sebelum tidur! Siapa yang mengajariku hal ini? Tidak penting.",
  str_voice_1501521_19 = "Kenapa kau sangat suka jalan-jalan pada malam hari? Persis seperti Beauku.",
  str_voice_1501521_20 = "True Order adalah rumahku dan rumah Beauku. Kebenaran selalu menjadi tempat kami tinggal.",
  str_voice_1501521_21 = "Aku dengar Lumopolis kesulitan menerima kenyataan. Aneh!",
  str_voice_1501521_22 = "Semoga Truth memberkatimu. Ahahah.",
  str_voice_1501521_23 = "Eclipsite menyerangku tiap kali melihatku. Pasti mereka membenciku… Terserah, deh. Aku lebih membenci mereka.",
  str_voice_1501521_24 = "Lenore… Dia tak lebih dari seonggok boneka tanpa perasaan. Jangan buang waktumu untuknya.",
  str_voice_1501521_25 = "Andai saja aku bisa sepopuler Genevieve… Uhuk… Anggap saja kau tak dengar apa pun!",
  str_voice_1501521_26 = "Apakah ada seseorang yang kaucintai? Aku bisa merajutkan cinta kalian berdua. Ahahah.",
  str_voice_1501521_27 = "Aah! Bulu Beau kusut lagi. Maafkan kesalahan mama. Maafkan mama!",
  str_voice_1501521_28 = "Apakah Colossus menyukaiku? Jika iya, aku juga menyukainya.",
  str_voice_1501521_29 = "Ahahah. Kukira Navigator adalah sosok yang mengesankan. Dia tak bisa lepas dari genggamanku juga. Hah? Apa? Kau datang demi aku?",
  str_voice_1501521_30 = "Aku sangat senang.",
  str_voice_1501521_31 = "Makin mendekat… Semakin mendekat!",
  str_voice_1501521_32 = "Perasaan ini… Apakah ini sungguhan?",
  str_voice_1501521_33 = "Sulurnya bermekaran.",
  str_voice_1501521_34 = "Uhuk… Kita pasti bisa.",
  str_voice_1501521_35 = "Sulurnya telah hidup kembali.",
  str_voice_1501521_36 = "Kita lilitkan atau kita ikatkan?",
  str_voice_1501521_37 = "Anak nakal, siap-siap merasakan hukuman!",
  str_voice_1501521_38 = "Setangkai bunga yang besar untukmu.",
  str_voice_1501521_39 = "Sangat menyebalkan!",
  str_voice_1501521_40 = "Selamat jalan!",
  str_voice_1501521_41 = "Aku… Aku tidak takut.",
  str_voice_1501521_42 = "Bagaimana aku tadi? Keren kan?",
  str_voice_1501521_43 = "Bukan, ini bukan salahku…",
  str_voice_1501521_44 = "Wah… Tempat ini tampak menyenangkan.",
  str_voice_1501521_45 = "Quest apa ini?",
  str_voice_1501521_46 = "Hadiah untukku?",
  str_voice_1501521_47 = "Terima kasih… Kepiting! Ini kepiting?",
  str_voice_1501521_48 = "Aku akan memasangnya di dompetku.",
  str_voice_1501521_49 = "Ibu Beau adalah May. Ibu May adalah? Aku tidak ingat wajahnya.",
  str_voice_1501521_50 = "Saat aku melihat si kecil yang malang itu, aku tersadar… Mungkin aku bukan bayi yang berharga bagi siapa pun, tetapi aku sendiri bisa punya bayi berharga!",
  str_voice_1501521_51 = "Aku tidak butuh pengakuan dari ibuku. Dukungan dari True Order adalah hal yang tulus dan suci, pasti. Hal yang selalu aku idamkan.",
  str_voice_1501521_52 = "Alchemy Stars.",
  str_voice_1501521_53 = "Ahahah!",
  str_voice_1501521_54 = "Iya, sudah hampir fajar.",
  str_voice_1501521_55 = "Setengah hari ya artinya setengah hari.",
  str_voice_1501521_56 = "Wah. Sudah malam.",
  str_voice_1501521_57 = "Jahit dan tambal. Tahun baru pun kembali tiba. Selamat Tahun Baru!",
  str_voice_1601531_1 = "Mudah untuk memulai perang, tetapi sukar mengakhirinya. Katakan padaku, PlayerName, kau siap?",
  str_voice_1601531_2 = "Tak seorang pun dapat menjamin kemenangan hingga perang benar-benar berakhir. Satu-satunya hal yang dapat kita lakukan adalah tetap bertekad.",
  str_voice_1601531_3 = "Ingat, jangan kehilangan arah. Kebenaran sering kali tersembunyi di balik tirai.",
  str_voice_1601531_4 = "Tanya aku langsung jika kau ragu dan aku akan memberimu jawabannya. Ini bukan hanya hak istimewamu saja, melainkan setiap orang Illumina.",
  str_voice_1601531_5 = "Terus lampaui batasmu dan tingkatkan diri. Hanya yang bersemangat dan punya integritas moral kuat yang akan dikagumi dan dihormati.",
  str_voice_1601531_6 = "Jangan pedulikan bekas luka itu, PlayerName. Itu adalah tanda kehormatan bagi prajurit sepertiku. Kau harus belajar bahwa luka fisik tidak ada apa-apanya dibandingkan derita mental.",
  str_voice_1601531_7 = "Aku percaya latihan militer Illumina dapat membantu keahlianmu meningkat dengan cepat. Namun, kecepatan tidak selalu menguntungkan.",
  str_voice_1601531_8 = "Kau sedang membaca buku strategi, ya? Coba kulihat... Hmm, sebagian isinya tepat, tetapi pendekatannya sudah ketinggalan zaman, itu saja menurutku. Aku senang dapat membahasnya lebih banyak nanti setelah kau selesai membacanya.",
  str_voice_1601531_9 = "Seorang prajurit harus belajar percaya pada rekan-rekannya, sementara seorang pemimpin harus mampu membedakan kejujuran dan kebohongan... Jika kau terampil dalam keduanya, mungkin kau akan mengerti hal yang kurasakan.",
  str_voice_1601531_10 = "Anak muda yang berambisi besar tidak boleh menunda atau menyia-nyiakan kesempatan.",
  str_voice_1601531_11 = "Jarang-jarang aku punya waktu luang. Kita lihat apa aktivitasmu akhir-akhir ini.",
  str_voice_1601531_12 = "Tidak ada prajurit yang tak kompeten, yang ada hanyalah jenderal yang tak punya keahlian. Aku yakin kau mengerti apa maksudku.",
  str_voice_1601531_13 = "Saat kau merasa sedih, makanlah sepuasmu! Perut adalah otak kedua, maka kita harus memperhatikannya.",
  str_voice_1601531_14 = "Para desertir dihukum berat di Illumina. Kau tahu alasannya? Karena melarikan diri bukanlah solusi. Tidak masalah jika gagal mengatasi masalah, tetapi menghindari masalah itu baru memalukan.",
  str_voice_1601531_15 = "Selamat ulang tahun! Kau setahun lebih tua sekarang, kau harus meningkatkan latihanmu juga.",
  str_voice_1601531_16 = "Lapar? Kurasa, kau masih dalam masa pertumbuhan! Makanlah risotto lebih banyak supaya makin kuat!",
  str_voice_1601531_17 = "Pagi! Aku membuatmu takut? Hal pertama yang kauucapkan setiap pagi harus nyaring dan jelas. Biar kudengar jawabanmu!",
  str_voice_1601531_18 = "Hari mulai gelap, tapi masih ada waktu untuk merampungkan pekerjaan.",
  str_voice_1601531_19 = "Lakukan hal yang benar pada waktu yang tepat. Orang yang rajin tidak harus mengorbankan waktu tidurnya.",
  str_voice_1601531_20 = "Latar belakang dan masa lalu bukanlah persoalan. Sepanjang hati sejalan dengan Illumina, setiap orang dapat menumbuhkan potensi mereka di sini.",
  str_voice_1601531_21 = "Aku tidak setuju dengan cara Lumopolis memperlakukan masyarakatnya, tetapi masih ada hal yang dapat kita pelajari dari kota itu.",
  str_voice_1601531_22 = "Demi rekan satu bangsa, tanah airku, dan Illumina yang luar biasa!",
  str_voice_1601531_23 = "Eclipsite selalu menjadi musuh kita, tapi terus terang, itu tidak pernah sesederhana yang terlihat.",
  str_voice_1601531_24 = "Obsesi Vivian dengan agenda dan penjadwalan tidak cocok untuk pertempuran meskipun itu tentunya berguna dalam hal logistik.",
  str_voice_1601531_25 = "Aku merasa tak terancam sama sekali oleh ambisi Wrath. Sebaliknya, dia selalu menjadi pengingat bagiku untuk terus maju.",
  str_voice_1601531_26 = "Aku tidak suka jamuan resmi. Untuk memuaskan selera dan jiwa, satu panci besar risotto tetap yang terbaik.",
  str_voice_1601531_27 = "Untuk semua desertir yang tidak puas, dunia tidak berutang apa pun pada kalian.",
  str_voice_1601531_28 = "Benar, Soroz kokoh dan lega, cocok untuk transportasi militer.",
  str_voice_1601531_29 = "PlayerName, kau anugerah bagi seluruh Astra. Perlihatkan padaku lebih banyak lagi hal yang kaupunya.",
  str_voice_1601531_30 = "Mana mungkin hanya itu!",
  str_voice_1601531_31 = "Kekuatan itu bukan milikku semata.",
  str_voice_1601531_32 = "Benar, jadilah kuat dan makin kuat!",
  str_voice_1601531_33 = "Tombak kesayanganku akan menyala untukku!",
  str_voice_1601531_34 = "Seorang prajurit memberi perintah pada jenderal?",
  str_voice_1601531_35 = "Waktu tak pandang bulu!",
  str_voice_1601531_36 = "Tunjukkan kemampuan komandomu kepadaku!",
  str_voice_1601531_37 = "Kau akan menyaksikan kekuatan sejati!",
  str_voice_1601531_38 = "Biarlah ini jadi akhirnya.",
  str_voice_1601531_39 = "Tembus semuanya!",
  str_voice_1601531_40 = "Ayo, tombakku!",
  str_voice_1601531_41 = "Aku memimpin pasukan? Itu keputusan yang malas tetapi bijak.",
  str_voice_1601531_42 = "Kita akan menang!",
  str_voice_1601531_43 = "Tetap bertempur dan terus maju!",
  str_voice_1601531_44 = "Tempat ini merupakan markas yang sempurna!",
  str_voice_1601531_45 = "Aku tidak tertarik dengan hadiah materi, tapi terima kasih.",
  str_voice_1601531_46 = "Ah, kau sangat perhatian.",
  str_voice_1601531_47 = "Terima kasih. Aku akan menggunakannya sebaik-baiknya.",
  str_voice_1601531_48 = "Hei, jangan kau sia-siakan semua pikiranmu untuk ini.",
  str_voice_1601531_49 = "Aku tidak jauh berbeda dari prajurit Illumina lainnya. Bertempur adalah tugasku. Sejak hari pertama aku menghadapi pertempuran, ayunan pedangku tidak dapat dihentikan oleh siapa pun.",
  str_voice_1601531_50 = "Dulu Wrath adalah teman satu kelas di sekolah, tetapi itu tidak ada kaitannya dengan kenaikan pangkatnya. Kemampuannya sudah jelas bagi siapa pun. Apakah itu menjawab pertanyaanmu?",
  str_voice_1601531_51 = "Aku mempromosikan Sharona dan Hiiro menjadi Legion Commander karena kemampuan mereka yang luar biasa. Aku tidak pelit memberikan kesempatan kepada orang lain, tapi ada lebih sedikit orang yang memanfaatkannya daripada yang kau kira.",
  str_voice_1601531_52 = "Alchemy Stars!",
  str_voice_1601531_53 = "Ayo, bersiap!",
  str_voice_1601531_54 = "Selamat pagi.",
  str_voice_1601531_55 = "Oh, hai!",
  str_voice_1601531_56 = "Selamat malam.",
  str_voice_1601531_57 = "Kau harus berupaya keras untuk memenuhi resolusi tahun barumu.",
  str_voice_1601541_1 = "Huff... Ah, bukan apa-apa. Aku hanya teringat kalau aku pernah salah menganggapmu hantu aneh saat kita pertama bertemu... Astaga, tak kusangka kejadian itu sudah lama sekali, ya.",
  str_voice_1601541_2 = "Kau masih menganggap aku aneh? Sejujurnya, aku sendiri sering kaget saat bercermin, tetapi aku dapat merasakan energi mengalir dalam diriku. Itu hal bagus untuk kita, 'kan? Ya, maksudku memang kita!",
  str_voice_1601541_3 = "Di Astra, kedamaian telah sirna. Sekarang kita tengah diseret ke dalam pusaran masalah. Jangan khawatir, PlayerName, aku akan selalu berada di sampingmu!",
  str_voice_1601541_4 = "Terkadang, kelihatannya makin aku tahu, makin aku tidak... Sebentar, barusan aku mengoceh apa? Kurasa aku makin mirip dirimu!",
  str_voice_1601541_5 = "Karena aku makin kuat, apakah itu berarti kemampuan memasakku juga meningkat? Jadi, PlayerName, kau ingin makan apa? Sebutkan saja!",
  str_voice_1601541_6 = "Tidak seperti Eclipsite, kita mengejar kekuasaan demi melindungi mereka yang membutuhkan kita. Aku percaya pada kemampuanku sendiri, jadi kumohon, percayalah padaku juga!",
  str_voice_1601541_7 = "Tak kusangka, gelap cocok dengan diriku... Bukan, ini soal pakaian! Mana yang cocok untukku, hitam atau putih?",
  str_voice_1601541_8 = "Akhir-akhir ini, aku berlatih alat musik. Apa lagi? Tentu saja piano! Bagaimana kalau kita duet bareng?",
  str_voice_1601541_9 = "Aku mungkin telah berubah. Aku menjadi lebih rakus karena ada lebih banyak orang yang harus kulindungi sekarang, termasuk kau. Jadi, aku memaklumi kerakusan ini.",
  str_voice_1601541_10 = "Baiklah, cukup istirahatnya. Aku tahu istirahat baik untukku, tetapi kita harus segera bekerja.",
  str_voice_1601541_11 = "Tentu saja aku dapat membantu, tetapi tak ada yang perlu diperbaiki di sini... Maksudmu, aku harus beristirahat di sini?",
  str_voice_1601541_12 = "Rencana yang mendetail dan latihan yang tekun pada akhirnya akan membuahkan hasil! Jadi, kapan kau akan menyerahkan rencana untuk bulan depan?",
  str_voice_1601541_13 = "Liburan? Ehem. Ya, mungkin juga, sih. Aku sendiri juga tak sabar untuk bersenang-senang, tapi kita harus menyelesaikan beberapa tugas dulu. Aku mau merapikan susunan anggaran dulu!",
  str_voice_1601541_14 = "Rencana sudah selesai? Apa? Kau membuat rencana untuk Colossus tetapi melupakan Eraveil? Jangan abaikan tugasmu, PlayerName!",
  str_voice_1601541_15 = "Selamat ulang tahun! Kuharap bisa menjadi saksi atas ucapanmu yang keras untuk satu tahun lagi, hehe.",
  str_voice_1601541_16 = "Jangan terlalu keras bekerja. Terkadang kau harus lebih bersantai. Keseimbangan antara pekerjaan dan kesenangan itu juga penting.",
  str_voice_1601541_17 = "Pagi! Ini daftar hal yang harus dilakukan hari ini. Tolong tanda tangani, PlayerName!",
  str_voice_1601541_18 = "Fiuh, akhirnya selesai! Kau masih bekerja? Ada yang bisa kubantu?",
  str_voice_1601541_19 = "Belum tidur? Masalah berat, ya? Jangan khawatir, biar kubantu.",
  str_voice_1601541_20 = "Illumina mungkin punya rahasia yang tak kuketahui, tetapi kujamin itu bukan konspirasi. Hal seperti itu tak akan pernah terjadi di Illumina!",
  str_voice_1601541_21 = "Dulu aku menganggap Rediesel Wrench hanyalah segerombolan orang putus asa. Sekarang aku tahu mereka sebenarnya orang baik.",
  str_voice_1601541_22 = "Jayalah Illumina!",
  str_voice_1601541_23 = "Aku tak terlalu suka pembantaian, tetapi tidak ada cara lain untuk menghadapi Eclipsite.",
  str_voice_1601541_24 = "Dia bukan petarung yang bagus tetapi sangat cerdas, pemberani, dan pekerja keras... Apa itu? Oh, aku sedang membahas... teman baikku.",
  str_voice_1601541_25 = "Carleen selalu cerdas, tenang, dan dewasa, tetapi baru belakangan ini aku menyadari dia sengaja menyembunyikan sisi kekanak-kanakannya.",
  str_voice_1601541_26 = "Dawn flower putih, bunga sakura merah muda, smoothie tepi laut dan kue madu di salju... Ada banyak hal yang kusuka sekarang.",
  str_voice_1601541_27 = "Hal-hal yang dulu tidak dapat kuhadapi sekarang tidak tampak seburuk itu lagi... Apakah itu berarti aku telah berkembang?",
  str_voice_1601541_28 = "Soroz sudah mulai terasa seperti rumah. Ehem, bukan hanya aku yang merasa seperti itu, 'kan?",
  str_voice_1601541_29 = "Kenapa kau menatapku seperti itu? Memangnya aku telah sangat berubah seperti itu? Jangan khawatir, aku masihlah Vice yang sama, aku janji!",
  str_voice_1601541_30 = "Kekuatan yang lebih dingin dan sunyi!",
  str_voice_1601541_31 = "Kerja lebih keras, melangkah lebih jauh!",
  str_voice_1601541_32 = "Masa depan akan menghargai kita karena keputusan kita hari ini!",
  str_voice_1601541_33 = "Potensi tersegelku akhirnya tersingkap!",
  str_voice_1601541_34 = "Aku akan bekerja lebih keras!",
  str_voice_1601541_35 = "Kirim aku!",
  str_voice_1601541_36 = "Jangan buang-buang waktu!",
  str_voice_1601541_37 = "Sekarang waktunya! Ambil itu!",
  str_voice_1601541_38 = "Sebentar lagi selesai!",
  str_voice_1601541_39 = "Aku hanya butuh satu tembakan!",
  str_voice_1601541_40 = "Serang, panah es!",
  str_voice_1601541_41 = "Seperti biasanya, kau memimpin!",
  str_voice_1601541_42 = "Pertempuran sempurna sesuai buku panduan!",
  str_voice_1601541_43 = "Tidak apa-apa, akan ada kesempatan lain!",
  str_voice_1601541_44 = "Hmm, biar kuperiksa daftar hal yang perlu dilakukan... Pemeliharaan Colossus... Belanja makanan... Perencanaan harian... Aduh, sibuk lagi hari ini!",
  str_voice_1601541_45 = "Hei, ada hadiah dari rekan lama!",
  str_voice_1601541_46 = "Dari mana kau mendapatkannya? Terima kasih banyak!",
  str_voice_1601541_47 = "Kau tak perlu semurah hati itu!",
  str_voice_1601541_48 = "Wow, aku selalu menginginkan ini... Terima kasih!",
  str_voice_1601541_49 = "Andai waktu itu aku tidak menyelamatkanmu dari bawah tanah, mungkin aku takkan berada di sini sekarang... Kita akan menjadi duo yang hebat, bukan begitu?",
  str_voice_1601541_50 = "Kenangan itu telah lenyap ke dalam jurang terdalam pikiranku... Tapi, kini kenangan itu tiba-tiba muncul kembali, menjadi perhatianku. Pikiranku kosong dan ada dengungan di telingaku... Tak bisa kupercaya aku pernah hidup seperti itu.",
  str_voice_1601541_51 = "Petualangan kita di Astra memang seru! Tapi aku tak pernah ragu kita dapat mengatasi rintangan dan bahaya. Aku ingin tahu lebih banyak tentang dunia ini bersamamu, jika boleh.",
  str_voice_1601541_52 = "Alchemy Stars!",
  str_voice_1601541_53 = "Apa kabar, PlayerName?",
  str_voice_1601541_54 = "Pagi. Kau sudah bangun?",
  str_voice_1601541_55 = "Apa kau sudah makan siang?",
  str_voice_1601541_56 = "Selamat malam. Kau pasti lelah setelah melewati hari yang panjang.",
  str_voice_1601541_57 = "Satu tahun lagi telah dimulai. Mari, kita lakukan ini bersama!",
  str_voice_1601551_1 = "Apakah aku membuatmu takut? Ada masalah apa? Orang berjalan-jalan di Colossus dengan kepala hiu atau ekor anjing setiap waktu. Dibandingkan mereka, aku sama sekali tak aneh, 'kan!",
  str_voice_1601551_2 = "Para pemula tahun ini adalah angkatan terburuk yang pernah kulatih! Anak-anak yang tumbuh pada masa damai sama sekali tidak sadar adanya potensi bahaya!",
  str_voice_1601551_3 = "Tegakkan punggung dan kepala! Tidak ada tempat aman bagi kalian dalam pertempuran, camkan itu!",
  str_voice_1601551_4 = "Aku telah mencoba banyak senjata selama bertahun-tahun, tetapi sepasang pedang yang dapat menyatu ini adalah yang terbaik.",
  str_voice_1601551_5 = "Serangan diam-diam bisa efektif, tapi akhir-akhir ini itu bukan gayaku. Tidak saat aku bisa dengan mudah mengalahkan musuh secara langsung. Mau coba?",
  str_voice_1601551_6 = "Aku sadar bahwa kita tidak dapat mengendalikan energi di dalam diri kita sampai kita dapat mengendalikan diri untuk benar-benar menjinakkannya kelak. Syukurlah, aku telah melakukannya.",
  str_voice_1601551_7 = "Kuingat kau telah berkenalan dengan beberapa prajuritku? Bagus. Oh ya, White Dwarf jarang bicara, tetapi dia tak pernah mengecewakanku dalam pertempuran.",
  str_voice_1601551_8 = "Kau satu-satunya rivalku yang layak di Wargame.",
  str_voice_1601551_9 = "Kau berbakat memimpin pasukan. Tapi jangan anggap itu sebagai pujian. Bakat alami bukan untuk dibanggakan. Aku ingin melihat kegigihan dan tekadmu untuk bertempur!",
  str_voice_1601551_10 = "Hei, aku sudah menyimulasikan tiga putaran Wargame dalam pikiran, kenapa kau begitu lama?",
  str_voice_1601551_11 = "Ha, kau sekarang mulai mendatangiku secara sukarela untuk berlatih? Peningkatanmu cukup pesat juga.",
  str_voice_1601551_12 = "Itu esai, ya? Menurutmu, menulisnya dapat membantumu memenangi pertempuran? Kusarankan kau berlari saja, setidaknya kau mungkin bisa kabur dari musuh yang kuat!",
  str_voice_1601551_13 = "Temanmu mungkin tersebar di seluruh penjuru dunia, tapi mereka tak akan membuat perjalananmu menjadi lebih mudah. Biasanya, makin banyak kenalan, berarti makin banyak masalah. Jangan bilang aku tak pernah memperingatkanmu, ya.",
  str_voice_1601551_14 = "Bagaimana aku bisa menghadapi kebosanan? Apa yang membuatmu berpikir aku bisa? Hanya saja, sangat jarang ada kesempatan buat bosan belakangan ini.",
  str_voice_1601551_15 = "Hari ini kau ulang tahun? Ayo, kita bersenang-senang di garis depan!",
  str_voice_1601551_16 = "Aduh, mengapa seorang komandan masih harus mengurusi persoalan administratif?",
  str_voice_1601551_17 = "Kau bangun lebih awal. Apakah karena kau ingin berlatih denganku? Sebenarnya kau tinggal bilang padaku...",
  str_voice_1601551_18 = "Akhirnya, waktu istirahat bagiku! Kurasa aku akan berlatih anggar dulu sebelum tidur. Mau ikut?",
  str_voice_1601551_19 = "Belum tidur? Jangan melamun saja. Ayo, berlatih tanding denganku!",
  str_voice_1601551_20 = "Aku tidak tahu apa yang direncanakan oleh para atasan, tetapi tidak ada yang dapat menghentikanku dalam pertempuran selama aku bersama Illumina.",
  str_voice_1601551_21 = "Orang-orang Rediesel Wrench terlalu banyak membuang waktu untuk hal-hal tak penting. Aku bisa memanfaatkan keterampilan mereka agar lebih berguna.",
  str_voice_1601551_22 = "Jayalah Illumina!",
  str_voice_1601551_23 = "Eclipsite hanyalah sampah tak berguna... Tapi dari mana mereka mendapatkan keberanian untuk melawan kita?",
  str_voice_1601551_24 = "Dari semua Commander, hanya Hiiro yang menarik perhatianku. Hei, maksudku dalam hal keahlian militer!",
  str_voice_1601551_25 = "Wrath suka pertarungan yang adil, tetapi memangnya ada? Naif sekali, 'kan?",
  str_voice_1601551_26 = "Lihat, aku terlahir untuk bertempur! Pertempuran adalah satu-satunya hal yang membuatku merasa hidup!",
  str_voice_1601551_27 = "Bagaimana orang bisa menghabiskan waktu seharian dengan minum teh dan membaca berita saja? Maaf, aku tak cocok dengan aktivitas begitu!",
  str_voice_1601551_28 = "Colossus milikmu tidak berubah sedikit pun. Aku tak melihat lecet sedikit pun padanya. Apakah aku perlu menggoresnya dengan pedangku?",
  str_voice_1601551_29 = "Baru beberapa hari, tapi kau sudah tidak mengenaliku? Baiklah, sampai jumpa di pertarungan berikutnya. Akan kutunjukkan wujud asliku! Kau takut, ya? Hahaha!",
  str_voice_1601551_30 = "Aku masih bisa bertumbuh kuat! Kuyakin itu!",
  str_voice_1601551_31 = "Inilah yang kumaksudkan!",
  str_voice_1601551_32 = "Aku bisa melakukan ini sepanjang hari, sepanjang malam!",
  str_voice_1601551_33 = "Siapa berikutnya?",
  str_voice_1601551_34 = "Mana pertarungannya?",
  str_voice_1601551_35 = "Hei, jangan menghalangiku!",
  str_voice_1601551_36 = "Waktunya menghabisi yang tersisa!",
  str_voice_1601551_37 = "Mendekatlah dan rasakan ini!",
  str_voice_1601551_38 = "*Meraung*",
  str_voice_1601551_39 = "Panther's Prowl!",
  str_voice_1601551_40 = "Ayo, sini!",
  str_voice_1601551_41 = "Maju, cepat lakukan!",
  str_voice_1601551_42 = "Serang dan pukul saat besinya masih panas!",
  str_voice_1601551_43 = "Bukan waktunya menyerah!",
  str_voice_1601551_44 = "Kurang latihan, ya? Mau menjajal satu atau dua putaran denganku?",
  str_voice_1601551_45 = "Kau baik hati sekali!",
  str_voice_1601551_46 = "Persis yang kubutuhkan. Terima kasih!",
  str_voice_1601551_47 = "Baiklah kalau kau memaksa!",
  str_voice_1601551_48 = "Hmm, ini barang bagus!",
  str_voice_1601551_49 = "Apakah prajurit perlu diawasi setiap waktu? Bukankah kau seharusnya mengikuti standar tinggi, ya? Aku selalu melatih diri sejak mengenakan baret ini!",
  str_voice_1601551_50 = "Mungkin kau masih bayi ketika pertama kali aku bertemu Reinhardt. Aku merindukan masa-masa itu, sebelum para Committee berengsek itu memengaruhinya.",
  str_voice_1601551_51 = "Seperti kataku, prajurit tidak boleh merasa takut dalam pertempuran. Kita harus menyerang musuh. Inilah yang membuatku berada di posisi ini sekarang!",
  str_voice_1601551_52 = "Alchemy Stars!",
  str_voice_1601551_53 = "Hei, katakan sesuatu.",
  str_voice_1601551_54 = "Pagi!",
  str_voice_1601551_55 = "Sudah siang?",
  str_voice_1601551_56 = "Selamat malam!",
  str_voice_1601551_57 = "Harapan tahun baruku adalah menghabisi semua Eclipsite!",
  str_voice_1601561_1 = "Seorang pria sejati harus mengambil inisiatif dan menyapa seorang wanita... Hei! Kau dengar tidak, sih? Seorang pria juga harus mendengarkan apa yang wanita bicarakan.",
  str_voice_1601561_2 = "Untuk minum teh sore hari ini, aku mau teh hitam melati dengan pencuci mulut scone bebas gula. Apa? Kau mau aku menyiapkannya sendiri? Bagaimana caranya... Lupakan saja, suasana hatiku sedang tidak mendukung minum teh sore.",
  str_voice_1601561_3 = "Aku sedang memegang \"parasol\", bukan \"payung\"! Bedanya apa? Oh, ayolah... Kurasa aku juga harus belajar memaafkan ketidaktahuan para rakyat jelata.",
  str_voice_1601561_4 = "Hah? Kau pikir keterampilan bertarungku telah meningkat? Tentu saja! Awas, aku akan segera menguasai Umbraton!",
  str_voice_1601561_5 = "Wahahaha, aku baru saja dapat inspirasi desain senjata baru! Sudah kubilang, aku ini genius di bidang ini!",
  str_voice_1601561_6 = "Aku seorang profesional dalam desain kostum, apresiasi permata, dan pembuatan senjata. Akan kutaklukkan bidang berikutnya sekarang! Mana yang harus kupilih... Ah, benar, studi Caelestite!",
  str_voice_1601561_7 = "Aku sudah menjadi perancang busana terkenal, tahu. Aku bisa merancangkan pakaian untukmu juga, tidak masalah. Tapi, ingat, ya, kau harus bilang \"suatu kehormatan bagiku\" dalam situasi seperti ini!",
  str_voice_1601561_8 = "Apakah kita sekarang... berteman baik? Jangan salah paham, aku tidak mau menyia-nyiakan perasaanku pada orang bodoh yang tidak mengerti perasaan orang lain...",
  str_voice_1601561_9 = "PlayerName, akankah kau merindukan orang tuamu? Bukan apa-apa. Hanya saja, tiba-tiba aku merindukan ibuku. Andai ibuku masih ada, seharusnya aku... memperkenalkanmu padanya.",
  str_voice_1601561_10 = "Mengajakku kemari, lalu mengabaikanku... Benar-benar tidak sopan! Apa? Apa aku berbuat salah... Aku tidak peduli! Aku takkan meminta maaf jika kau tidak memberikan penjelasan!",
  str_voice_1601561_11 = "Kenapa kau mengajakku ke tempat kumuh seperti ini... Eh, aku tidak membenci tempat ini, Bodoh! Karena kau mengajakku kemari, jangan sekali-sekali menoleh dariku!",
  str_voice_1601561_12 = "\"Seorang bocah laki-laki hidup kembali setelah dikubur selama 17 tahun...\" Kau sebut itu cerita horor? Inikah yang disukai rakyat jelata sekarang?",
  str_voice_1601561_13 = "Aduh, gumpalan hitam... Ini barbeku Rediesel? Bahkan anjingku tak mau makan ini, oke?! Jangan paksa aku... Ahhhhh... eh, yah, ternyata lumayan juga.",
  str_voice_1601561_14 = "Paman Istvan telah membujuk ayah untuk kembali lagi... Maksudku, ayah hanyalah seorang lelaki tua kutu buku yang tinggal di rumah setiap hari. Apakah ayah benar-benar sehebat itu?",
  str_voice_1601561_15 = "Ini adalah sisa dari pekerjaan amalku, bukan hadiah ulang tahun untukmu! Ah... S-Selamat ulang tahun.",
  str_voice_1601561_16 = "Apa yang kaulakukan? Yah, aku tidak memeriksamu! Hanya saja... Lupakan, aku tidak akan memberitahumu.",
  str_voice_1601561_17 = "Kau masih tidur? Tidak mungkin aku akan membangunkanmu... Apa? Masih tidur? Bangunlah!",
  str_voice_1601561_18 = "Sudah cukup larut, kau... masih bekerja? Tidak ada apa-apa, aku juga sibuk, aku tidak kesepian.",
  str_voice_1601561_19 = "Ahhh! Kau rupanya! Bodoh, aku hampir ketakutan setengah mati pada tengah malam! Aku kira kau hantu...",
  str_voice_1601561_20 = "Umbraton adalah wilayahku. Apa? Bukan karena ayahku telah membantuku...",
  str_voice_1601561_21 = "Lumopolis? Kenapa kau mau pergi ke sana? Andai kau benar-benar ingin pergi, aku akan mengizinkanmu tinggal di puri keluargaku barang satu atau dua hari.",
  str_voice_1601561_22 = "Aku mengawasimu!",
  str_voice_1601561_23 = "Aku tidak peduli jika itu adalah Eclipsite! Beraninya ia mengerjaiku! Ini takkan berakhir dengan baik!",
  str_voice_1601561_24 = "Ehem... Harus kuakui bahwa Bethel sama baiknya denganku. Hmm... Cepat atau lambat, aku akan sepuluh ribu kali lebih baik darinya!",
  str_voice_1601561_25 = "Sanae terlihat sangat manis saat gugup... Eh? Aku tidak pernah merundungnya! Kayaknya...",
  str_voice_1601561_26 = "Aku menyukai banyak hal, beberapa di antaranya mungkin belum pernah kaudengar.",
  str_voice_1601561_27 = "Aku takut hantu? Yang benar saja, aku ini suka cerita horor, bagaimana... Ahhhh, apa itu barusan? Hantukah?",
  str_voice_1601561_28 = "Colossus... Menakjubkan! Ehem, beri aku waktu, maka aku akan membangunnya juga!",
  str_voice_1601561_29 = "Kau PlayerName? Huh, semua orang membicarakanmu. Kukira kau akan terlihat berbeda. Aku Nina Anderson, suatu kehormatan bagimu bertemu denganku.",
  str_voice_1601561_30 = "Semuanya, lihat!",
  str_voice_1601561_31 = "Inspirasi... muncullah!",
  str_voice_1601561_32 = "Lagi-lagi senjata bagus.",
  str_voice_1601561_33 = "Aku hanya akan mengandalkan... kekuatanku sendiri!",
  str_voice_1601561_34 = "Kalau begitu, kau tidak bodoh.",
  str_voice_1601561_35 = "Siap!",
  str_voice_1601561_36 = "Berapa lama lagi aku harus menunggu?",
  str_voice_1601561_37 = "Bodoh sekali!",
  str_voice_1601561_38 = "Mari, kutunjukkan koleksiku kalau begitu.",
  str_voice_1601561_39 = "Berisik sekali!",
  str_voice_1601561_40 = "Kalian... idiot banget!",
  str_voice_1601561_41 = "Teman-teman, ikuti petunjukku, oke?",
  str_voice_1601561_42 = "Tentu saja kita akan menang. Ada aku di sini, 'kan?",
  str_voice_1601561_43 = "Tidak ada yang bisa mengalahkanku!",
  str_voice_1601561_44 = "Katakan ada tempat untuk minum teh sore di sini.",
  str_voice_1601561_45 = "Eh, seperti itukah kesukaan rakyat jelata?",
  str_voice_1601561_46 = "Kalau begitu... baiklah.",
  str_voice_1601561_47 = "Jangan sombong, aku tidak bilang aku menyukainya!",
  str_voice_1601561_48 = "Jadi, kau tahu apa yang kusuka... T-Terima kasih.",
  str_voice_1601561_49 = "Jangan meremehkanku, aku ini pewaris gelar Lumopolis. Kenapa aku tidak tinggal di Lumopolis? Itu... ceritanya panjang.",
  str_voice_1601561_50 = "Aku tidak mengerti, kenapa semua orang memuji Bethel sebagai penerus Umbraton... Aku juga elite di Dawn Academy, lo!",
  str_voice_1601561_51 = "Ayah sangat bodoh, aku selalu mengira dia orang terbaik di dunia yang memahamiku, tapi rupanya dia tidak tahu apa-apa soal apa yang kuinginkan... Lupakan saja, aku akan mendapatkan apa yang kuinginkan dengan tanganku sendiri!",
  str_voice_1601561_52 = "Alchemy Stars!",
  str_voice_1601561_53 = "PlayerName!",
  str_voice_1601561_54 = "Selamat pagi.",
  str_voice_1601561_55 = "Bukankah kau mau mengucapkan selamat siang kepadaku?",
  str_voice_1601561_56 = "Selamat malam.",
  str_voice_1601561_57 = "Selamat Tahun Baru! Semoga segala harapan menjadi kenyataan pada tahun baru ini. Harapanku adalah... rahasia!",
  str_voice_1501571_1 = "Yah... uh... seperti yang kaulihat, aku seorang pelayan. Aku bisa... mencuci pakaian. Bisa memasak, dan... jika kau mau, bisa mendongengkan beberapa cerita pengantar tidur dari Far East.",
  str_voice_1501571_2 = [[
-Apakah si PlayerName ini bisa diandalkan?
-Aku merasa seperti... Waow! Tuan Navigator? Kapan kau tiba? Ini adikku Manae...]],
  str_voice_1501571_3 = "Manae sangat memedulikanku dan dia akan selalu melindungiku... Ini semua salahku. Aku tidak berguna... Ah, tapi aku akan bekerja lebih keras! Kumohon, jangan pecat aku!",
  str_voice_1501571_4 = [[
-Sebelum bekerja di Astra... Aku tidak pernah tahu bahwa aku harus mengkhawatirkan Eclipsite.
-Ada yang bisa mengurus kompensasi kerusakan mentalku?]],
  str_voice_1501571_5 = [[
-Apakah itu ilusi... Sepertinya aku jarang jatuh akhir-akhir ini...
-Hmm, hmm, Sanae sudah dewasa.]],
  str_voice_1501571_6 = [[
-Sejak kami bertemu denganmu, Sanae menjadi lebih dewasa. Mungkin kelak, dia tidak akan membutuhkanku lagi.
-Manae... Tolong jangan bilang begitu...]],
  str_voice_1501571_7 = "Nyam-nyam, hati angsa bakarnya enak banget... Waow, kau di sini?! Yah, aku... aku tidak makan... Hanya melamun. Heheh.",
  str_voice_1501571_8 = "Tuan Navigator, aku ingin... berterima kasih! Karena... karena aku tidak pernah mempertahankan pekerjaan begitu lama.",
  str_voice_1501571_9 = "Oh, Tuan Navigator... pangeran legendaris penunggang naga putih yang menapaki awan warna-warni untuk membawaku pulang...",
  str_voice_1501571_10 = [[
-Hei, kau! Pendengaranmu bermasalah, ya?! Berapa lama kau akan membuat Sanae menunggu?
Ah... Adik, jangan bicara seperti itu pada Tuan Navigator! Ahhhh... maaf! Aku tidak keberatan menunggu... sungguh.]],
  str_voice_1501571_11 = [[
-Eh...? S... senang bisa melayanimu!
-Ehem, kita sepakati gajinya dulu.]],
  str_voice_1501571_12 = "Um... burung terbang di Colossus... apakah mereka disebut Firefly? Aku ingin tahu seperti apa rasanya jika dimakan... Hah? Aku tidak bisa memakannya? Oh maaf! Aku tidak akan mengambil makanan Tn. Navigator tanpa izin.",
  str_voice_1501571_13 = "Sebenarnya... menjadi pelayan bukanlah pekerjaan pertamaku. Dulu aku menjual koran, mengecat, dan mengangkut barang di dermaga... tapi aku tidak pernah bisa mempertahankan pekerjaan itu.",
  str_voice_1501571_14 = [[
-Fiuh... Kapan aku akan melunasi utang...
-PlayerName, mungkin sudah saatnya memberiku kenaikan gaji?]],
  str_voice_1501571_15 = [[
-Nah... Hari ini kau ultah? Selamat ulang tahun!
-Hadiah ulang tahunmu tak akan kuberi sebelum aku dapat bayaran.]],
  str_voice_1501571_16 = "Uhhh... Selamat siang. Kenapa... Kenapa kau menatapku seperti itu? Hah... Apa aku kurang bekerja keras?",
  str_voice_1501571_17 = "Uh... yah... Tuan Navigator yang terhormat, sudah waktunya bangun. Sarapan sudah... siap.",
  str_voice_1501571_18 = "Setelah seharian bekerja... k-kau pasti sangat lelah! Mau kuhangatkan segelas susu untukmu?",
  str_voice_1501571_19 = [[
-Oh... Tuan Navigator, ada yang bisa aku bantu?
-Kenapa kau kemari lagi? Waktunya pulang!]],
  str_voice_1501571_20 = [[
-Cloud Island... benar-benar tempat yang indah.
-Tapi, sisanya sulit untuk diceritakan.]],
  str_voice_1501571_21 = [[
-Terima kasih, Umbraton, karena menerimaku apa adanya...
-Hmmm, tidak semua orang baik di sini.]],
  str_voice_1501571_22 = [[
-Kerja... dapat uang... bayar utang...
-Makan enak.]],
  str_voice_1501571_23 = [[
-Eclipsite... sangat menakutkan. Mereka juga makan orang... sangat menakutkan!
-Jangan takut! Ada aku di sini.]],
  str_voice_1501571_24 = "Lady Bethel... orang yang baik! Dia telah membantuku mencarikan pekerjaan.",
  str_voice_1501571_25 = "Manae selalu di sisiku, membantuku saat aku dalam kesulitan... Jika bukan karena dia, mungkin aku tidak akan sampai sejauh ini.",
  str_voice_1501571_26 = "Eh... hal yang aku suka? Ah, yah... aku suka... aku suka... makan. Apakah itu termasuk?",
  str_voice_1501571_27 = [[
-Pembohong, berengsek, pergi dari sini!
-... Sst, Tuan Navigator bukan orang seperti itu... Kurasa.]],
  str_voice_1501571_28 = [[
-Colossus... bisa terbang ke Cloud Island dengan cepat?
-Sekarang belum waktunya untuk kembali.]],
  str_voice_1501571_29 = "Aduh! Sakit... Eh? Maaf. Aku tidak bermaksud menjatuhkanmu! A-aku... Sanae. Mau kubawa kau ke klinik?",
  str_voice_1501571_30 = "Kali ini... pasti berhasil...",
  str_voice_1501571_31 = "Kekuatannya... beruap seperti nasi panas nikmat.",
  str_voice_1501571_32 = "Aku tidak perlu kelaparan lagi...",
  str_voice_1501571_33 = "Saudari seperjuangan!",
  str_voice_1501571_34 = "Ahhh... A-Aku?",
  str_voice_1501571_35 = "Waaah, harusnya ini cukup...",
  str_voice_1501571_36 = "Oh, itu, aku...",
  str_voice_1501571_37 = "Kumohon, Manae!",
  str_voice_1501571_38 = "Hei, menyingkir dariku!",
  str_voice_1501571_39 = "Yeaargh!",
  str_voice_1501571_40 = "Mau kabur? Mana mungkin!",
  str_voice_1501571_41 = "Apa yang harus kulakukan...?",
  str_voice_1501571_42 = "Fiuh... Akhirnya kita menang...",
  str_voice_1501571_43 = "Oh, tidak... Aku akan didenda...",
  str_voice_1501571_44 = [[
-Apakah ada lowongan pekerjaan di sini?
-Pekerjaan yang dibayar.]],
  str_voice_1501571_45 = [[
-Apakah ini... untukku?
-Hati-hati dengan penipuan.]],
  str_voice_1501571_46 = [[
-Terima kasih...
-Kau sangat murah hati.]],
  str_voice_1501571_47 = [[
-Kau begitu baik padaku...
-Simpan pikiran kotormu untuk dirimu sendiri.]],
  str_voice_1501571_48 = [[
-Aku menyayangimu! Kau favoritku!
-Jangan konyol. Yang dia maksud itu hadiahnya.]],
  str_voice_1501571_49 = "Saat putus asa... Aku bertemu dengan seorang gadis berambut merah muda. Tanpa dia, aku takkan pernah bisa naik kapal ke Astra...",
  str_voice_1501571_50 = [[
-Saat ibu dan ayah pergi... Paman Hansuke merawatku.
-Dia berengsek! Sudah sepantasnya dia dipenjara.]],
  str_voice_1501571_51 = [[
-Manae adalah saudari kembarku... Hah? Bukankah kami itu mirip?
-Ada apa dengan matamu?]],
  str_voice_1501571_52 = "Alchemy Stars!",
  str_voice_1501571_53 = "Ahhhhhhhhhhhh!",
  str_voice_1501571_54 = "S-Selamat pagi.",
  str_voice_1501571_55 = "Oh... Selamat siang!",
  str_voice_1501571_56 = "Selamat malam...",
  str_voice_1501571_57 = "Selamat Tahun Baru... Uh? Bilang apa lagi? Ahhh...",
  str_voice_1601581_1 = "Tempat ini benar-benar luar biasa...",
  str_voice_1601581_2 = "Oke, bersiap-siap untuk pergi ke luar.",
  str_voice_1601581_3 = "Waktu untuk konferensi strategi?",
  str_voice_1601581_4 = "Hmm...",
  str_voice_1601581_5 = "Jangan ragu untuk memberi tahu saya ketika Anda mengalami masalah.",
  str_voice_1601581_6 = "Apa berikutnya?",
  str_voice_1601581_7 = "Senang bertemu dengan Anda.",
  str_voice_1601581_8 = "Dunia ini... sangat menarik.",
  str_voice_1601581_9 = "Aku mulai merindukan secangkir kopi yang enak...",
  str_voice_1601581_10 = "Baiklah, mari kita mulai.",
  str_voice_1601581_11 = "Diterima. Saya mengerti.",
  str_voice_1601581_12 = "Bagi saya, tidak masalah di mana saya tinggal. Tidak pernah ada banyak perbedaan.. Hmmm, anggap saja sebagai mematuhi adat istiadat setempat.",
  str_voice_1601581_13 = "Siap?",
  str_voice_1601581_14 = "Keputusan terserah Anda.",
  str_voice_1601581_15 = "Selamat ulang tahun.",
  str_voice_1601581_16 = "Tidak masalah, saya siap.",
  str_voice_1601581_17 = "Selamat pagi.",
  str_voice_1601581_18 = "Perlu lebih banyak upaya ke dalamnya.",
  str_voice_1601581_19 = "Mari kita tutup mata hari ini.",
  str_voice_1601581_20 = "Sehat...",
  str_voice_1601581_21 = "Bagaimana saya harus menempatkan ini ...",
  str_voice_1601581_22 = "Waktu pertunjukan!",
  str_voice_1601581_23 = [[
gerhana...
adalah musuh yang akan kita kalahkan di sini ...]],
  str_voice_1601581_24 = "Bagus sekali...",
  str_voice_1601581_25 = "Bravo.",
  str_voice_1601581_26 = [[
Hal favorit?
Jika saya harus memilih, saya akan mengatakan "Semuanya."]],
  str_voice_1601581_27 = [[
Apa yang paling saya tidak suka?
Bisakah saya pergi dengan "Itu tergantung"?]],
  str_voice_1601581_28 = "Colossus memang tempat yang aneh.",
  str_voice_1601581_29 = "Kode Nama Joker. Aku di sini untuk mengambil hatimu.",
  str_voice_1601581_30 = "Tidak buruk.",
  str_voice_1601581_31 = "Tentu.",
  str_voice_1601581_32 = "Saya pikir saya menjadi lebih kuat.",
  str_voice_1601581_33 = "Ayo, Arsen!",
  str_voice_1601581_34 = "Ayo pergi!",
  str_voice_1601581_35 = "Ini dia!",
  str_voice_1601581_36 = "Aku akan mengambilnya!",
  str_voice_1601581_37 = "Ambil itu!",
  str_voice_1601581_38 = "Ini dia!",
  str_voice_1601581_39 = "Menyerah!",
  str_voice_1601581_40 = "Sekakmat!",
  str_voice_1601581_41 = "Aku punya ini.",
  str_voice_1601581_42 = "Ikuti rencananya.",
  str_voice_1601581_43 = "Gagal di sini...",
  str_voice_1601581_44 = "Ada apa?",
  str_voice_1601581_45 = "Aku akan menghargainya.",
  str_voice_1601581_46 = "Lalu... aku akan menerimanya.",
  str_voice_1601581_47 = "Terima kasih.",
  str_voice_1601581_48 = "Terima kasih... Tidak, buat itu—aku merasa terhormat.",
  str_voice_1601581_49 = "Jika Anda tiba di tempat yang tidak dikenal, Anda tidak akan dapat membantu memikirkan \"hari itu\" juga ...",
  str_voice_1601581_50 = "Kami melanjutkan hanya ketika kami mencapai konsensus dengan suara bulat.",
  str_voice_1601581_51 = "Saya memiliki nama asli, tetapi karena Anda melihat saya apa adanya sekarang, panggil saja saya dengan nama kode saya.",
  str_voice_1601581_52 = "Bintang Alkimia!",
  str_voice_1601581_57 = "Selamat Tahun Baru.",
  str_voice_1601581_58 = "Ini sudah berakhir!",
  str_voice_1601591_1 = "Untuk memahami dunia ini, lebih baik belajar dari penduduk setempat.",
  str_voice_1601591_2 = "Saya pikir itu cara saya berpakaian yang menyebabkan orang lain di dunia ini salah mengira saya untuk tipe agresif.",
  str_voice_1601591_3 = "Saya ingin tahu tentang bagaimana orang-orang di sini hidup.",
  str_voice_1601591_4 = "Seseorang harus mengamati situasi dengan cermat sebelum bertindak dengan kepekaan.",
  str_voice_1601591_5 = "Begitu ada tujuan, seseorang harus terus bergerak menuju tujuan itu! Ya, seseorang harus menguasainya sendiri.",
  str_voice_1601591_6 = "Meskipun kami memiliki tujuan yang berbeda, kami berbagi dorongan yang sama untuk mencapainya.",
  str_voice_1601591_7 = "Bangkitkan semangatmu, partner!",
  str_voice_1601591_8 = "Jika Anda menemukan sesuatu yang tidak Anda mengerti, ubah semua pengalaman Anda menjadi pengetahuan setelah mencari tahu!",
  str_voice_1601591_9 = "Aku bahkan lebih tertarik dengan dunia ini sekarang. Misalnya... yah, apakah ada yang menyerupai sekolah?",
  str_voice_1601591_10 = "Maafkan saya, saya sedang berpikir keras.",
  str_voice_1601591_11 = "Diterima!",
  str_voice_1601591_12 = "Colossus ini benar-benar memiliki segalanya...",
  str_voice_1601591_13 = "Aku ingin tahu apakah adikku makan dengan benar.",
  str_voice_1601591_14 = "Pasti tugas membersihkan semua ruang yang berlebihan ini.",
  str_voice_1601591_15 = "Selamat ulang tahun! Meskipun aku berada di dunia lain, mengucapkan selamat ulang tahun kepada seseorang tetap membuatku bahagia!",
  str_voice_1601591_16 = "Baik itu dalam pertempuran atau dalam kehidupan, informasi selalu penting!",
  str_voice_1601591_17 = "Selamat pagi. Ini adalah hari yang baru.",
  str_voice_1601591_18 = "Saya tahu mudah untuk tertidur sekarang, tetapi harap tetap waspada. Bagaimana dengan secangkir kopi?",
  str_voice_1601591_19 = "Sudah larut... Waktunya tidur.",
  str_voice_1601591_20 = "Anda harus istirahat. Ingin memiliki beberapa makanan penutup dengan saya?",
  str_voice_1601591_21 = "Dunia ini dan dunia kita memiliki banyak kesamaan.",
  str_voice_1601591_22 = "Oke, saatnya bekerja!",
  str_voice_1601591_23 = "Rasanya seperti saya pernah melihat Eclipsites dalam mimpi saya sebelumnya.",
  str_voice_1601591_24 = "Joker adalah pemimpin yang bisa diandalkan! Ya, bisa dibilang dia penting bagi kami.",
  str_voice_1601591_25 = "Bagi kami, Pencuri Hantu adalah tempat kami berada.",
  str_voice_1601591_26 = "Saya ingin pergi bepergian ke suatu tempat yang jauh! Tapi tidak sampai aku selesai dengan ujian.",
  str_voice_1601591_27 = "Tidak suka? Nah, daripada menggunakan itu sebagai alasan untuk menghindari sesuatu, saya lebih memilih untuk fokus pada bagian yang baik. Bukankah itu pendekatan yang positif?",
  str_voice_1601591_28 = "Penasaran, teknologi apa yang digunakan untuk membangun Colossus?",
  str_voice_1601591_29 = "Aku Ratu, senang bertemu denganmu. Beri tahu saya bagaimana saya bisa membantu.",
  str_voice_1601591_30 = "Apakah saya menjadi lebih kuat?",
  str_voice_1601591_31 = "Kami tim yang hebat!",
  str_voice_1601591_32 = "Ya, semuanya berjalan baik!",
  str_voice_1601591_33 = "Ayo lakukan ini, Johanna!",
  str_voice_1601591_34 = "Saya akan memenuhi harapan Anda!",
  str_voice_1601591_35 = "Selalu siap!",
  str_voice_1601591_36 = "Tidak memegang dilarang!",
  str_voice_1601591_37 = "Bangun!",
  str_voice_1601591_38 = "Penghakiman Tinju Besi!",
  str_voice_1601591_39 = "Sekarang!",
  str_voice_1601591_40 = "Aku akan menanganinya!",
  str_voice_1601591_41 = "Apakah giliran saya?",
  str_voice_1601591_42 = "Nah, mari kita lanjutkan!",
  str_voice_1601591_43 = "Ini tidak bisa menjadi akhir...",
  str_voice_1601591_44 = "Colossus sangat menarik, baik dari perspektif sejarah atau arsitektur.",
  str_voice_1601591_45 = "Tidak buruk...",
  str_voice_1601591_46 = "Untuk saya?",
  str_voice_1601591_47 = "Terima kasih! Saya sangat senang.",
  str_voice_1601591_48 = "aku bisa memilikinya...? Terima kasih, saya sangat senang!",
  str_voice_1601591_49 = "Seperti yang diharapkan, hal-hal yang tidak ditemukan di buku pelajaran benar-benar mengasyikkan!",
  str_voice_1601591_50 = "\"Caelestit Terakhir\"? Saya tidak tahu mengapa itu mengingatkan saya pada bank ...",
  str_voice_1601591_51 = "Colossus seperti sesuatu yang keluar dari game... Hmm, game... game... judi... Sae...!",
  str_voice_1601591_52 = "Bintang Alkimia!",
  str_voice_1601591_57 = "Selamat Tahun Baru! Wujudkan resolusi Anda!",
  str_voice_1601591_58 = "Tidak pernah memaafkan!",
  str_voice_1501601_1 = "Apa? Oh, kamu juga jalan-jalan?",
  str_voice_1501601_2 = [[
Apakah ini Colossus?
Merupakan pengalaman unik untuk melihat daratan dari langit.]],
  str_voice_1501601_3 = "Tidak ada biaya lalu lintas yang perlu dikhawatirkan di dunia ini... Bagus.",
  str_voice_1501601_4 = [[
Air di dunia ini rasanya enak...
Setara dengan air keran di duniaku.]],
  str_voice_1501601_5 = "Teh rumput laut dan makanan penutup masih merupakan kombinasi terbaik.",
  str_voice_1501601_6 = [[
Ketika saya duduk, ekor di pakaian saya
sepertinya menghalangi...]],
  str_voice_1501601_7 = "Anda menyebut diri Anda Caelestit Terakhir akan sama dengan saya menyebut diri saya Bintang Masa Depan Nihonga.",
  str_voice_1501601_8 = "Colossus sangat luas, saya bahkan ingin meminjamkan kamar dari Anda sebagai studio saya.",
  str_voice_1501601_9 = "Dunia ini memiliki begitu banyak hal yang belum pernah saya lihat sebelumnya, inspirasi mengalir begitu saja!",
  str_voice_1501601_10 = "Desain interior di sini... Apakah sesuai dengan keinginan Anda?",
  str_voice_1501601_11 = "Serahkan padaku!",
  str_voice_1501601_12 = "Aku mencintai dunia ini. Saya harap saya bisa merekam semuanya di kanvas saya.",
  str_voice_1501601_13 = [[
Colossus benar-benar memiliki segalanya...
Keberatan menunjukkan saya berkeliling nanti?]],
  str_voice_1501601_14 = "Makanan gratis? Itu luar biasa!",
  str_voice_1501601_15 = [[
Selamat ulang tahun.
Saya berharap hidup untuk Anda penuh dengan kemegahan
di tahun mendatang.]],
  str_voice_1501601_16 = "Pengalaman saya di sini akan menjadi inspirasi untuk gambar saya.",
  str_voice_1501601_17 = [[
Selamat pagi. Sudah hampir waktunya sarapan, kan?
Saya ingin mencicipi makanan di sini dulu.]],
  str_voice_1501601_18 = [[
Apakah Anda sedang jalan-jalan malam? Itu ide yang bagus.
Keberatan jika saya bergabung?]],
  str_voice_1501601_19 = [[
Masih naik? Apa yang aneh.
Meskipun hal yang sama berlaku untuk saya.]],
  str_voice_1501601_20 = "Saya ingin menjelajahi misteri dunia ini juga, jadi ayo pergi!",
  str_voice_1501601_21 = [[
Taila, telinga kucing, tanduk naga...
Pencipta dunia ini
pasti punya rasa.]],
  str_voice_1501601_22 = "Ayo, izinkan saya menunjukkan pertunjukan paling estetis yang pernah Anda lihat.",
  str_voice_1501601_23 = [[
Angka-angka gerhana...
Tidak ada nilai artistik di dalamnya sama sekali.]],
  str_voice_1501601_24 = "Joker adalah pemimpin yang dapat dipercaya.",
  str_voice_1501601_25 = "Memiliki sekutu bukanlah hal yang buruk.",
  str_voice_1501601_26 = "Berjalan cukup menyenangkan. Anda menghemat banyak biaya lalu lintas.",
  str_voice_1501601_27 = [[
ketidaksukaanku...?
Saya tidak ingin berhubungan dengan siapa pun yang tidak mengerti seni.]],
  str_voice_1501601_28 = "Saya bisa merasakan keindahan dari luar Colossus ini.",
  str_voice_1501601_29 = [[
Ini adalah Rubah dari Pencuri Hantu Hati.
Anda membutuhkan saya, kan?]],
  str_voice_1501601_30 = "Aplikasi blade dan brush memiliki beberapa kesamaan.",
  str_voice_1501601_31 = "Saya menjadi lebih kuat, rasanya.",
  str_voice_1501601_32 = "Ini berjalan dengan baik. Teruskan.",
  str_voice_1501601_33 = "Dorong mereka kembali, Goemon!",
  str_voice_1501601_34 = "Saatnya aku bersinar.",
  str_voice_1501601_35 = "Serahkan ini padaku.",
  str_voice_1501601_36 = "Tidak ada tempat bagi Anda untuk lari.",
  str_voice_1501601_37 = "Saatnya bangun!",
  str_voice_1501601_38 = "Dia adalah aku yang lain!",
  str_voice_1501601_39 = "Sebuah pembukaan!",
  str_voice_1501601_40 = "Potong!",
  str_voice_1501601_41 = "Potong-potong!",
  str_voice_1501601_42 = "Sempurna. Sekarang ke kemenangan berikutnya.",
  str_voice_1501601_43 = "Maaf kau harus melihatku seperti ini...",
  str_voice_1501601_44 = "Apa yang saya lakukan? Mengamati Aurora.",
  str_voice_1501601_45 = "Ini untukku? Aku akan mengambilnya.",
  str_voice_1501601_46 = [[
Hadiah untukku?
Oh, betapa indahnya!]],
  str_voice_1501601_47 = "Apa kamu yakin? Ini hadiah yang sangat bagus... Aku akan menghargainya.",
  str_voice_1501601_48 = [[
Hebat, benar-benar hebat!
Anda benar-benar tahu apa yang saya suka!]],
  str_voice_1501601_49 = "Selama saya bisa menggambar dan melukis, saya tidak peduli di mana saya berada.",
  str_voice_1501601_50 = [[
Akhir-akhir ini saya suka mendonor darah.
Ya, itu hobi baruku.]],
  str_voice_1501601_51 = "Saya yakin supermarket sedang mengadakan obral hari ini... Oh, tunggu, saya di dunia lain...",
  str_voice_1501601_52 = "Bintang Alkimia!",
  str_voice_1501601_57 = [[
Selamat Tahun Baru.
Tidak buruk juga merayakannya di dunia asing.]],
  str_voice_1501601_58 = "Ini akan segera berakhir!",
  str_voice_1501611_1 = "Ayo lakukan yang terbaik hari ini juga!",
  str_voice_1501611_2 = "Vice membuat hidangan aneh untuk kami. Saya memang keberatan dengan rasanya, tetapi saya lebih khawatir apakah mereka bisa membuat saya kenyang.",
  str_voice_1501611_3 = "Ngomong-ngomong, apakah Anda tahu apa itu senam ritmik?",
  str_voice_1501611_4 = "Saya harap Anda dapat memberi tahu saya lebih banyak tentang dunia ini.",
  str_voice_1501611_5 = "Semua orang di sini juga memiliki tugas dan tugas mereka sendiri, saya kira.",
  str_voice_1501611_6 = "Anda harus melakukan peregangan dengan benar sebelum bertanding. Apakah Anda ingin saya menunjukkan caranya?",
  str_voice_1501611_7 = "Saya sangat senang bahwa saya memenuhi harapan orang lain, tetapi saya juga merasakan tekanan.",
  str_voice_1501611_8 = "Jadi ini disebut Colossus... Sungguh menakjubkan betapa banyak benda di dalamnya!",
  str_voice_1501611_9 = [[
Apa yang saya lakukan...?
Jika saya harus mengatakan, zonasi!]],
  str_voice_1501611_10 = [[
Olahraga juga menjernihkan pikiran Anda.
Apakah Anda ingin melakukan peregangan bersama?]],
  str_voice_1501611_11 = "Saya akan berusaha untuk menjadi aset bagi Anda!",
  str_voice_1501611_12 = [[
Ada dua perut: satu untuk pencuci mulut dan satu untuk makanan pembuka.
Itu tetap menjadi fakta di dunia mana pun Anda berada.]],
  str_voice_1501611_13 = "Apa yang saya lihat di sini mungkin bisa menjadi inspirasi untuk penampilan saya.",
  str_voice_1501611_14 = "Jangan lupa untuk tetap terhidrasi saat latihan.",
  str_voice_1501611_15 = "Selamat ulang tahun!",
  str_voice_1501611_16 = "Minum teh dan istirahat.",
  str_voice_1501611_17 = "Selamat pagi! Ingin berolahraga dengan saya?",
  str_voice_1501611_18 = "Anda mengalami hari yang panjang. Silakan istirahat dengan baik.",
  str_voice_1501611_19 = [[
Itu buruk untuk begadang.
Aku juga harus tidur.]],
  str_voice_1501611_20 = "Saya menghargai usahanya!",
  str_voice_1501611_21 = "Aku benar-benar serius dalam pertempuran dan habis-habisan!",
  str_voice_1501611_22 = "Pergi pergi!",
  str_voice_1501611_23 = [[
gerhana...
Mereka terlihat gila...]],
  str_voice_1501611_24 = "Saya akan berusaha untuk menjadi aset bagi semua orang!",
  str_voice_1501611_25 = "Mona bisa berubah menjadi mobil! Apakah itu umum di dunia ini?",
  str_voice_1501611_26 = [[
suka saya?
Makanan enak, tentu saja! Tapi saya harus mengendalikan diri sebelum kompetisi besar...]],
  str_voice_1501611_27 = [[
Tidak suka?
Mungkin jatuh ke dalam keterpurukan.]],
  str_voice_1501611_28 = [[
Anda dapat berkomunikasi dengan Colossus?
Kedengarannya agak sulit dipercaya.]],
  str_voice_1501611_29 = [[
Nama kode saya adalah Violet.
Saya akan berusaha untuk memperbaiki diri demi semua orang.]],
  str_voice_1501611_30 = "Saya merasa lebih kuat!",
  str_voice_1501611_31 = "Saya akan memenuhi harapan Anda!",
  str_voice_1501611_32 = "Saya akan memberikan semuanya!",
  str_voice_1501611_33 = "Menari, Cendrillon!",
  str_voice_1501611_34 = "Mari kita lakukan!",
  str_voice_1501611_35 = "Aku punya ini!",
  str_voice_1501611_36 = "Sama seperti kupu-kupu!",
  str_voice_1501611_37 = "Raih kemenangan dengan tangan!",
  str_voice_1501611_38 = "Menari, Persona!",
  str_voice_1501611_39 = "Konsentrat!",
  str_voice_1501611_40 = "Waktu untuk mencerminkan!",
  str_voice_1501611_41 = "Siap!",
  str_voice_1501611_42 = "Akhir yang spektakuler!",
  str_voice_1501611_43 = "aku tidak bisa gagal...",
  str_voice_1501611_44 = "Bisakah kita mengadakan perayaan di Colossus?",
  str_voice_1501611_45 = "Aku akan mengambilnya!",
  str_voice_1501611_46 = "Hadiah untukku? Aku sangat bahagia!",
  str_voice_1501611_47 = "Terima kasih!",
  str_voice_1501611_48 = "Bisakah saya benar-benar menerima hadiah yang begitu bagus?",
  str_voice_1501611_49 = "Aku akan melakukan apapun untuk mewujudkan mimpi itu!",
  str_voice_1501611_50 = "Saya sendiri adalah satu-satunya yang dapat membuat keputusan!",
  str_voice_1501611_51 = "Aku akan berbaris maju dengan Cendrillon... Bersama-sama, sebagai satu!",
  str_voice_1501611_52 = "Bintang Alkimia.",
  str_voice_1501611_57 = [[
Selamat Tahun Baru!
Tetap semangat untuk tahun ini juga!]],
  str_voice_1501611_58 = "Nilai sempurna!",
  str_voice_1501621_1 = "Aku bukan kucing! saya Mona!",
  str_voice_1501621_2 = "Saya pikir tempat ini luar biasa.",
  str_voice_1501621_3 = "Saya belum cukup akrab dengan dunia ini, jadi saya akan menyerahkan navigasi kepada Anda.",
  str_voice_1501621_4 = "Menjaga identitas kita tetap anonim adalah cara pencuri hantu melakukan sesuatu.",
  str_voice_1501621_5 = "Saya berharap dapat bekerja sama dengan Anda!",
  str_voice_1501621_6 = "Baiklah, kalau begitu, ayo pergi!",
  str_voice_1501621_7 = "Sebagai Pencuri Hantu, saya harus mempertahankan mentalitas \"Bantu yang lemah, jangan takut pada mereka yang berkuasa\".",
  str_voice_1501621_8 = "Anda perlu berlatih lebih keras jika Anda ingin menjadi perkasa seperti saya!",
  str_voice_1501621_9 = [[
Meow, pernak-pernik mengkilap!
Apa? Itu hanya sebuah mimpi?]],
  str_voice_1501621_10 = "Aku akan tidur siang jika kau terus menepisku.",
  str_voice_1501621_11 = "Oh, apakah giliranku sekarang?",
  str_voice_1501621_12 = [[
Saya berjanji saya akan melakukannya dengan sangat baik kali ini, jadi siapkan hadiah saya.
Sashimi tuna besar yang gemuk bisa digunakan.]],
  str_voice_1501621_13 = "Saya menjadi bersemangat ketika saya menyadari bahwa saya sedang terbang di langit sekarang.",
  str_voice_1501621_14 = "Senang rasanya bisa merasakan budaya yang berbeda dan memperluas wawasan saya. Itu juga membuatku lebih menawan.",
  str_voice_1501621_15 = "Selamat ulang tahun! Saya berharap untuk terus berada dalam perawatan Anda!",
  str_voice_1501621_16 = "Meong! Saya baik-baik saja seperti biasa!",
  str_voice_1501621_17 = "Bagaimana Anda tidur? Kalau begitu, mari kita bekerja keras hari ini juga!",
  str_voice_1501621_18 = "Hari pasti berlalu dengan cepat. Apakah masih ada yang harus dilakukan?",
  str_voice_1501621_19 = "Ayo tidur dulu!",
  str_voice_1501621_20 = "Pencuri Phantom akan selalu menyelesaikan pekerjaan dengan anggun, tidak peduli kapan.",
  str_voice_1501621_21 = "Yap, tepat di gang saya!",
  str_voice_1501621_22 = "Biarkan pertempuran dimulai!",
  str_voice_1501621_23 = "Eclipsites... Penyelidikan menyeluruh akan diperlukan.",
  str_voice_1501621_24 = "Saya melatih Pencuri Phantom sendiri, tidak ada pekerjaan yang tidak bisa mereka lakukan!",
  str_voice_1501621_25 = [[
Pencuri Phantom itu keren? Yah jelas.
Saya memilih mereka semua, setelah semua.]],
  str_voice_1501621_26 = [[
Suka?
Dengan asumsi Anda sedang berbicara tentang orang, bagaimana saya harus menempatkan ini ...? Ada beberapa...]],
  str_voice_1501621_27 = "Tidak suka? Bagaimana dengan orang yang mengejek orang lain karena bekerja keras?",
  str_voice_1501621_28 = "Bagaimana cara terbang sebesar Colossus?",
  str_voice_1501621_29 = "Seharusnya menjadi kehormatan bagimu untuk bertemu denganku!",
  str_voice_1501621_30 = "Saya melihat pesona saya telah diperkuat bahkan lebih!",
  str_voice_1501621_31 = "Ini adalah seberapa kuat saya!",
  str_voice_1501621_32 = "Serahkan padaku!",
  str_voice_1501621_33 = "Serang, Zorro!",
  str_voice_1501621_34 = "Giliran saya!",
  str_voice_1501621_35 = "Saya siap!",
  str_voice_1501621_36 = "Sudah terlambat untuk menyesal!",
  str_voice_1501621_37 = "Keluarlah, Persona-ku!",
  str_voice_1501621_38 = "Saksikan tekad saya!",
  str_voice_1501621_39 = "Bangun!",
  str_voice_1501621_40 = "Selamat tinggal untuk selamanya!",
  str_voice_1501621_41 = "Saya akan memberikan perintah saya!",
  str_voice_1501621_42 = "Bravo, semuanya!",
  str_voice_1501621_43 = "Apakah ini akhirnya...",
  str_voice_1501621_44 = "Hei, bisakah Colossus berubah sepertiku?",
  str_voice_1501621_45 = "Oh terima kasih.",
  str_voice_1501621_46 = "Untuk saya? Terima kasih!",
  str_voice_1501621_47 = "Betulkah? Terima kasih. Aku sangat bahagia!",
  str_voice_1501621_48 = "Saya dapat memiliki ini? Ya!",
  str_voice_1501621_49 = "Ketika semua ini selesai, saya ingin mengadakan pesta kemenangan.",
  str_voice_1501621_50 = "Ingatanku kabur, tapi aku akan membiarkan tindakanku berbicara sendiri! Itu sebabnya aku ace!",
  str_voice_1501621_51 = "Tidak tahu kapan saya mulai dikelilingi oleh orang-orang sepanjang waktu. Itu sesuatu yang tidak bisa saya bayangkan ketika saya sendirian.",
  str_voice_1501621_52 = "Bintang Alkimia!",
  str_voice_1501621_57 = "Selamat Tahun Baru! Resolusi saya adalah untuk melatih Anda keras di tahun baru, jadi bersiaplah!",
  str_voice_1501621_58 = "Pembersihan selesai!",
  str_voice_1601641_1 = "Saya senang saya berkelana di luar Lumopolis. Jika saya puas menjadi putri Tuan Kota dan hanya berpatroli di dalam Lumopolis, saya khawatir saya tidak akan menemukan sisi diri saya ini.",
  str_voice_1601641_2 = "Sia-sia untuk merenungkan kebaikan dan kejahatan pedang karena tanganlah yang memegang pedang yang menentukan apakah pedang itu berbahaya.",
  str_voice_1601641_3 = "Astra harus dimiliki, dikelola, dan dibangun bersama oleh semua ras beradab, termasuk Aurorian dan Caelestit.",
  str_voice_1601641_4 = "Bertindak secara bertanggung jawab tidak peduli seberapa sepele masalah tersebut. Jangan melewati batas tidak peduli seberapa sepele tindakannya.",
  str_voice_1601641_5 = "Ada kalanya tekad yang kuat sudah cukup untuk mengendalikan kekuatan sendiri dan mengubah kenyataan. Ini adalah arti dari \"pikiran di atas materi\".",
  str_voice_1601641_6 = "Jalannya panjang dan sulit, tetapi kita tidak boleh menyerah. Jalan di depan diselimuti kabut, tetapi kita harus menjaga mata kita tetap jernih.",
  str_voice_1601641_7 = "Cahaya dapat digunakan sebagai perisai, seperti yang dimiliki Lumopolis. Mungkin suatu hari, cahaya yang kumiliki akan menjadi perisai untuk melindungi semua orang, dan kau...",
  str_voice_1601641_8 = "Garis keturunan dapat menentukan kekuatan seseorang, tetapi apakah itu ukuran kerendahan dan keluhuran? Apakah itu memberi seseorang hak untuk menguasai orang lain? Saya pikir tidak.",
  str_voice_1601641_9 = "Saya sering bertanya-tanya apakah kita bisa bertemu lebih awal dan jika Anda seorang Aurorian, bagaimana jadinya.",
  str_voice_1601641_10 = "Sangat santai... Di sela-sela perjalanan panjang, saya kadang-kadang istirahat, kesurupan, atau mengingat hari-hari saya berpatroli di Lumopolis.",
  str_voice_1601641_11 = "Saya akan menjaga tempat ini seolah-olah itu Lumopolis, karena Colossus adalah rumah Anda, dan kami adalah mitra.",
  str_voice_1601641_12 = "Jamur yang dikenal sebagai pembusukan telah mencemari Lumopolis dan tidak dapat dikeluarkan kecuali sumbernya ditemukan.",
  str_voice_1601641_13 = "Masa depan Lumopolis adalah masa depan semua Aurorian. Peradaban, kemakmuran, kelimpahan, dan warisan telah bertahan selama ribuan tahun dan tidak akan pernah binasa.",
  str_voice_1601641_14 = "Garis keturunan pahlawan itu penting, tetapi keputusan mereka di saat krisis lebih penting. Keturunan pahlawan mungkin pengecut, sedangkan keturunan tanpa nama mungkin pejuang.",
  str_voice_1601641_15 = "Saya berharap bahwa kami masih dapat merayakan kelahiran Anda pada hari ini tahun depan.",
  str_voice_1601641_16 = "Jika Anda ingin berurusan dengan urusan pemerintahan, Anda harus menarik seutas benang dari masalah yang kompleks dan mengikutinya sampai tuntas, dan kemudian Anda akan menemukan kekacauan itu terurai.",
  str_voice_1601641_17 = "Jika Anda diberkati dengan sinar matahari menyinari tempat tidur Anda ketika Anda bangun di pagi hari, Anda akan berada dalam suasana hati yang baik sepanjang hari.",
  str_voice_1601641_18 = "Anda pasti kelelahan setelah seharian bekerja. Bagaimana kalau istirahat dengan mendengarkan musik klasik?",
  str_voice_1601641_19 = "Bekerja di tengah malam dengan kue santan stroberi menciptakan suasana yang istimewa.",
  str_voice_1601641_20 = "Lumopolis kuno dan stabil, tetapi kecerahan kepuasan membuat bayang-bayang tumbuh lebih lama.",
  str_voice_1601641_21 = "Menjadi terlalu rasional akan menyebabkan Anda kehilangan kontak dengan emosi Anda. Aku takut jika Illumina melangkah terlalu jauh ke jalan ini, mereka akan menjadi mesin yang tidak berperasaan.",
  str_voice_1601641_22 = "White Night up high, tolong bersinar ke depan.",
  str_voice_1601641_23 = "Terang dan gelap tidak bercampur; ketika yang satu berkurang, yang lain bertambah.",
  str_voice_1601641_24 = "Sebagai Penguasa Kota, tanggung jawab Schwartz begitu luas dan kompleks sehingga saya khawatir dia terkadang harus berkompromi.",
  str_voice_1601641_25 = "Vice hanyalah seorang siswa sederhana dari negara yang berbeda pada masa itu; Aku tidak pernah terlalu memperhatikannya saat kami sekelas. Tapi reputasinya mungkin akan melebihi reputasiku di masa depan.",
  str_voice_1601641_26 = "Tanpa ketertiban umum, peradaban akan runtuh, membawa konsekuensi yang jauh lebih buruk daripada bencana.",
  str_voice_1601641_27 = "Yang menakutkan bukanlah kurangnya kemampuan yang kuat, tetapi kurangnya tanggung jawab dan prinsip untuk menandinginya. Kedua sifat itu tidak bisa ada tanpa yang lain; jika tidak, bencana tidak bisa dihindari.",
  str_voice_1601641_28 = "Mungkin suatu hari, baik Lumopolis dan Colossus akan menjadi simbol Aurorian.",
  str_voice_1601641_29 = "Carleen de Schwartz di sini. Tidak perlu khawatir tentang saya; Frost tidak meninggalkanku. Hanya saja saya telah memilih Flame untuk sementara waktu.",
  str_voice_1601641_30 = "Menjadi lebih bersinar!",
  str_voice_1601641_31 = "Nyalakan tombaknya!",
  str_voice_1601641_32 = "Kemuliaan adalah milik kita.",
  str_voice_1601641_33 = "Cahaya beristirahat dengan jiwa.",
  str_voice_1601641_34 = "Tombak saya milik Anda.",
  str_voice_1601641_35 = "Siap menyerang.",
  str_voice_1601641_36 = "Serangan untuk mengatasi.",
  str_voice_1601641_37 = "May cahaya bersinar!",
  str_voice_1601641_38 = "Tidak ada bayangan di bawah tombak!",
  str_voice_1601641_39 = "May musuh lenyap.",
  str_voice_1601641_40 = "Belas kasihan tidak perlu.",
  str_voice_1601641_41 = "Anda membuat pilihan yang bijaksana.",
  str_voice_1601641_42 = "Memimpin pasukan menuju kemenangan adalah tanggung jawab kapten.",
  str_voice_1601641_43 = "Lebih baik mundur daripada kalah dalam pertempuran.",
  str_voice_1601641_44 = "Kemampuan terbang Colossus memang luar biasa, dan jika kita menggunakannya untuk berpatroli di wilayah itu...",
  str_voice_1601641_45 = "Terima kasih atas kemurahan hati Anda.",
  str_voice_1601641_46 = "Kau mengerti aku.",
  str_voice_1601641_47 = "Saya mengerti niat baik Anda.",
  str_voice_1601641_48 = "White Night up high, aku tidak akan pernah melupakan hadiahmu.",
  str_voice_1601641_49 = "Lumina luar biasa. Saya pikir saya hanya bisa mengendalikan es, saya tidak pernah membayangkan diri saya menggunakan tombak menyala dalam pertempuran.",
  str_voice_1601641_50 = "Tidak ada elitisme dalam darah seseorang, dan dengan demikian menggunakannya untuk menunjuk inferioritas dan superioritas adalah tidak masuk akal. Keunggulan dibangun secara alami oleh mereka yang mampu mendapatkan kepercayaan publik.",
  str_voice_1601641_51 = "Terkadang dalam mimpiku, kegelapan menutupi cahaya di mata semua orang, namun aku terus berjalan dengan obor yang terangkat.",
  str_voice_1601641_52 = "Alchemy Stars.",
  str_voice_1601641_53 = "Teman Seperjalanan.",
  str_voice_1601641_54 = "Hari baru telah dimulai.",
  str_voice_1601641_55 = "Sekarang sudah siang.",
  str_voice_1601641_56 = "Hari akan segera berakhir.",
  str_voice_1601641_57 = "Saya merasa terhormat berada di sini bersama Anda dan berharap kita dapat terus maju bersama di tahun mendatang.",
  str_voice_1501651_1 = "Drive adalah dasar dari mekanisme dinamis, dan harus memperhitungkan bahan energi, rasio konversi, struktur, dan transmisi. Oh, semuanya begitu rumit.",
  str_voice_1501651_2 = "Saya bertanya-tanya apakah ada ilmuwan Caelestit karena saya tidak yakin bagaimana mempertahankan Colossus yang luar biasa ini. C-Ce... Apa aku mengatakan sesuatu yang seharusnya tidak kukatakan?",
  str_voice_1501651_3 = "Banyak hal Caelestit yang misterius. Saya mencoba sepanjang siang dan malam untuk menggambar tampilan depan Firefly, tetapi saya gagal ...",
  str_voice_1501651_4 = "Merancang desain adalah bentuk seni! Vice benar. Dan itu lebih unggul daripada menggambar karena hanya mengandalkan presisi.",
  str_voice_1501651_5 = "Mecha dinamis berguna tidak hanya dalam pertempuran, tetapi juga dalam eksplorasi, penggalian, dan konstruksi. Mereka akan menjadi mesin penting di masa depan Federasi Illumina.",
  str_voice_1501651_6 = "Navigator, saya sampai pada kesimpulan baru mengenai desain cetak biru saya! Perhitunganku sebelumnya salah, tapi kali ini semuanya tampak baik-baik saja dan keren, jadi setelan mecha dinamis yang sempurna akan segera...",
  str_voice_1501651_7 = "Apakah Anda ingin membuat sketsa desain? Saya memiliki kompas dan penggaris, keduanya adalah pusaka keluarga. Aku tidak pernah membiarkan siapa pun meminjamnya... Bahkan tidak Vice.",
  str_voice_1501651_8 = "Navigator, bukankah seharusnya Colossus menjalani beberapa perbaikan besar? Atau mungkin satu atau dua pembaruan? Jangan khawatir, saya akan memberi Anda banyak bantuan teknik.",
  str_voice_1501651_9 = "C-Ce... Setelan mecha dinamis ini sepertinya tidak akan bertahan lebih lama. Bisakah Anda memperbaikinya menggunakan teknologi Caelestite?",
  str_voice_1501651_10 = "Bagaimana kalau duduk di mecha dan tidur siang? Tidak ada orang lain di sini. Um, C-Ce... Aku tidak malas!",
  str_voice_1501651_11 = "Anda dapat menyerahkan masalah teknik kepada saya, tetapi saya hanya dapat bertindak sebagai asisten di bidang lain. Saya bahkan tidak bisa memberi saran. Apakah ini benar-benar baik-baik saja?",
  str_voice_1501651_12 = "Saya mendengar bahwa Anda telah mengunjungi banyak tempat, apakah Anda menemukan sesuatu yang baru dan menarik? Seperti bijih hijau dari Northland atau darah cacing pasir dari Rediesel Desert?",
  str_voice_1501651_13 = "Ilmuwan adalah yang paling penting. Mereka adalah jiwa dari sebuah organisasi, seperti mesin dari unit mech!",
  str_voice_1501651_14 = "Siapa yang menemukan lari jarak jauh dan berenang? Hal-hal ini harus dilenyapkan dari keberadaan, seperti kesalahan dalam rancangan desain!",
  str_voice_1501651_15 = "Saya percaya ulang tahun melibatkan hadiah. Apa yang kamu inginkan? Bagaimana dengan model mecha dinamis?",
  str_voice_1501651_16 = "Navigator, sudahkah Anda membuat jadwal untuk hari ini? Jika tidak, hal-hal yang mungkin keluar dari tangan.",
  str_voice_1501651_17 = "Anda bangun pagi. Apakah Anda ingin menyetel Colossus?",
  str_voice_1501651_18 = "Terkadang istirahat diperlukan, seperti berbaring di tempat tidur gantung untuk sementara waktu.",
  str_voice_1501651_19 = "Tengah malam adalah waktu yang ideal untuk membuat perhitungan dan membuat sketsa desain! Tentu saja, akan lebih baik dengan inspirasi.",
  str_voice_1501651_20 = "Illumina telah mengumpulkan semua ilmuwan top Astra, dan saya beruntung mendapatkan bimbingan mereka.",
  str_voice_1501651_21 = "Beberapa pengrajin Rediesel Wrench membingungkan. Mereka tidak memiliki pengetahuan konkret tentang sains, tetapi mereka dapat memperbaiki hal-hal hanya berdasarkan pengalaman.",
  str_voice_1501651_22 = "Kemegahan Illumina! Saya harus menyelesaikan mekanisme dinamis itu!",
  str_voice_1501651_23 = "Struktur tubuh Eclipsites menyerupai beberapa jenis mesin canggih, saya bertanya-tanya siapa yang menciptakannya...",
  str_voice_1501651_24 = "Tanpa Petugas Teknis Gronru, Saya masih terjebak merancang desain, tidak dapat membuat kepala atau ekor dari mecha dinamis ini.",
  str_voice_1501651_25 = "Ketua Charon adalah seorang jenius dalam hal memimpin dan mengendalikan kereta api, tetapi dalam kehidupan sehari-hari... Ahem, yah, tidak apa-apa jika kamu sudah terbiasa.",
  str_voice_1501651_26 = "Bahkan jika saya memiliki IQ sepuluh kali lipat, saya masih tidak akan dapat menemukan sesuatu yang senyaman tempat tidur gantung! Jika saya tidak harus mengerjakan unit mecha, saya akan berbaring di dalamnya selama 20 jam sehari jika saya bisa.",
  str_voice_1501651_27 = "Mereka yang mengejek orang lain di depan umum harus dimasukkan ke dalam tungku sendok.",
  str_voice_1501651_28 = "Struktur, sistem, dan komponennya jauh melampaui kemampuan teknologi saat ini. Saya bertanya-tanya tentang para genius di balik desain seperti itu ...",
  str_voice_1501651_29 = "Saya mungkin bertanggung jawab atas penggalian terowongan, tetapi saya sebenarnya seorang insinyur! Mekanisme dinamis ini adalah kreasi saya, tetapi masih merupakan prototipe yang belum selesai. Jangan menyentuhnya! Omong-omong, nama saya Ciel.",
  str_voice_1501651_30 = "Kekuatan teknologi saya telah tumbuh lebih kuat.",
  str_voice_1501651_31 = "Sistem diperbarui.",
  str_voice_1501651_32 = "Kerangka ditambal.",
  str_voice_1501651_33 = "Saya merasa penuh kekuatan dan energi.",
  str_voice_1501651_34 = "Apakah Anda memerlukan bantuan untuk menggali terowongan?",
  str_voice_1501651_35 = "Styx, bersiaplah.",
  str_voice_1501651_36 = "Panah surya dalam keadaan siaga.",
  str_voice_1501651_37 = "Panah surya, lepaskan!",
  str_voice_1501651_38 = "Panah surya, mandi!",
  str_voice_1501651_39 = "Tidak ada jalan buntu! Api!",
  str_voice_1501651_40 = "Penuh! Api!",
  str_voice_1501651_41 = "Biarkan saya menjadi mesin tim!",
  str_voice_1501651_42 = "Semudah mengencangkan sekrup!",
  str_voice_1501651_43 = "Saya telah menggali terowongan pelarian ...",
  str_voice_1501651_44 = "Struktur Colossus ini sangat unik. Saya harus mengukur dan mempelajarinya secara detail.",
  str_voice_1501651_45 = "Aku akan meletakkannya di kamarku.",
  str_voice_1501651_46 = "Wow! Ini? Aku akan mengambilnya!",
  str_voice_1501651_47 = "Terima kasih. Bagaimana saya bisa membalas budi?",
  str_voice_1501651_48 = "Besar! Bagaimana kalau saya membuat setelan mecha dinamis untuk Anda juga?",
  str_voice_1501651_49 = "Mekanisme dinamis pada kaki tidak cocok dengan set saat ini; itu adalah hasil dari proyek yang gagal.",
  str_voice_1501651_50 = "Orang tua saya adalah pekerja biasa, tetapi mereka mendorong saya untuk menjadi seorang insinyur. Ternyata, mereka membuat pilihan yang tepat.",
  str_voice_1501651_51 = "Jika saya tidak memiliki kecenderungan untuk bermain-main, saya mungkin sudah menyelesaikan setelan mecha dinamis yang sempurna sekarang.",
  str_voice_1501651_52 = "Alchemy Stars.",
  str_voice_1501651_53 = "Anda di sini, kan?",
  str_voice_1501651_54 = "Pagi adalah waktu terbaik untuk bersiap-siap!",
  str_voice_1501651_55 = "Bahkan mesin perlu tidur siang setelah makan siang.",
  str_voice_1501651_56 = "Pekerjaan dapat ditunda sejenak.",
  str_voice_1501651_57 = "Tahun baru lagi... Aku harus bergegas dengan desain mecha yang dinamis.",
  str_voice_1601661_1 = "Hmph, tunggu saja! Ketika Kyllo dan aku menjadi lebih kuat suatu hari nanti, kami akan membalas dendam pada semua orang yang meremehkanku!",
  str_voice_1601661_2 = "Hah? Anda ingin tahu apa yang dibicarakan kucing liar ketika mereka berkumpul di malam hari? Lebih baik tidak tahu. Ini menyangkut menyalip Astra setelah semua ...",
  str_voice_1601661_3 = "\"Jamur Kakao Beracun. Binatang buas yang menyerupai jamur. Mereka memasuki keadaan ilusi yang nyaman setelah makan cokelat, dan menyerang toko makanan penutup di kota secara berkelompok.\" Saya yakin Guru mengarangnya.",
  str_voice_1601661_4 = "Kulit saya menjadi jauh lebih halus dari sebelumnya, semuanya lembut dan melenting sekarang. Tapi kamu tidak perlu iri padaku, PlayerName. Saya akan membagikan produk perawatan kulit saya kepada Anda. Itu dibuat dari sekresi Kyllo.",
  str_voice_1601661_5 = "Peringatan! Waspada penuh! Saya mendeteksi sinyal berbahaya! Binatang ajaib mendekat. Itu di belakangku— Ah, itu PlayerName.",
  str_voice_1601661_6 = "Kyllo berwarna biru dan putih saat tenang, dan berubah menjadi hitam dan merah saat dipicu. Namun, saya pernah melihatnya berubah menjadi warna pelangi yang berkilau seperti lampu neon. Apa artinya? Atau aku sedang bermimpi?",
  str_voice_1601661_7 = "Kyllo mengibaskan punggungnya dan kemudian melompat beberapa kali. Apa yang coba dia katakan? Apakah itu marah padaku?",
  str_voice_1601661_8 = "Ahhhh, aku sangat ceroboh. Jadi penguin dan beruang kutub sebenarnya adalah Aurorian?! Dan buaya itu... Kurasa penjelajahanku terhadap binatang yang menakjubkan baru saja dimulai...",
  str_voice_1601661_9 = "Sangat menyedihkan bahwa Anda sendirian, PlayerName. Bagaimana kalau... Aku mengadopsimu? Saya seorang master yang sangat bertanggung jawab dan saya akan menjaga Anda dengan sangat baik.",
  str_voice_1601661_10 = "Ahhhh, Kyllo bodoh, dan bodoh PlayerName! Berhenti menatapku!!",
  str_voice_1601661_11 = "Membuat seorang gadis cantik bekerja sebagai pelayan dan berdiri di sini sepanjang hari tersenyum pada pelanggan. Apa yang murah untuk Anda, master. Anda sebaiknya memberi saya lebih banyak uang saku untuk ini.",
  str_voice_1601661_12 = "Saya membenci orang yang memandang rendah saya, dan saya lebih membenci mereka yang memandang rendah tuan saya!",
  str_voice_1601661_13 = "Wah!!! K-kenapa kau membuatku takut seperti itu?",
  str_voice_1601661_14 = "Aku tahu betapa manisnya aku. Bisakah kamu berhenti menepuk kepalaku sekarang?",
  str_voice_1601661_15 = "Selamat ulang tahun untuk... Ini hari lahirmu?! Saya perlu merekamnya di \"Petualangan Extrozoologist.\"",
  str_voice_1601661_16 = "Selamat pagi, selamat siang, dan selamat malam. Di sana, saya telah menyapa Anda sepanjang hari!",
  str_voice_1601661_17 = "Ini terlalu dini sekarang. Saya harus kembali tidur lebih banyak, atau saya tidak bisa tumbuh tinggi.",
  str_voice_1601661_18 = "Waktu makan malam! Apakah Anda suka rumput laut? Saya bisa memberi Anda beberapa.",
  str_voice_1601661_19 = "Haa... choo! Menguap saya hanya berubah menjadi bersin. Ngh...",
  str_voice_1601661_20 = "Kami adalah tim khusus, profesional, dan andal yang didedikasikan untuk penelitian dan perlindungan binatang yang menakjubkan.",
  str_voice_1601661_21 = "Maaf, saya hanya menyukai binatang ajaib dan tidak tertarik pada Aurorian.",
  str_voice_1601661_22 = "Tangkap, kembangkan, dan gratis!",
  str_voice_1601661_23 = "Bagaimana Eclipsites bereproduksi? Populasi mereka tidak pernah menyusut. Mungkinkah mereka bereproduksi secara aseksual?",
  str_voice_1601661_24 = "Seorang pria paruh baya tanpa pekerjaan, kehidupan, atau kehadiran apa pun. Guru adalah pembohong total dan lengkap!",
  str_voice_1601661_25 = "Meskipun seniorku adalah gurita yang aneh, dia wanita yang baik.",
  str_voice_1601661_26 = "Saya suka kaca berkilau, permen, dan permata, tetapi yang paling saya sukai adalah binatang yang menakjubkan.",
  str_voice_1601661_27 = "Hai! PlayerName! Jangan kau abaikan aku!",
  str_voice_1601661_28 = "Saya ingin menambahkan ruang inkubasi, pembibitan, ruang pelatihan, dan kuburan untuk binatang buas yang menakjubkan di Colossus.",
  str_voice_1601661_29 = "Betul sekali. Saya adalah penangan legendaris dari binatang ajaib, dan ini adalah mitra saya Kyllo. Hmph, kamu takut belum?",
  str_voice_1601661_30 = "Aku menjadi lebih kuat! Tapi Kyllo tampaknya sama.",
  str_voice_1601661_31 = "Kulit saya terasa luar biasa!",
  str_voice_1601661_32 = "Ooh, indera spidey saya kesemutan!",
  str_voice_1601661_33 = "Transformasi dan kelahiran kembali! Berkembang, Fia!",
  str_voice_1601661_34 = "Hah? Bukankah ini seharusnya tim enam orang?",
  str_voice_1601661_35 = "Siap siap siap!",
  str_voice_1601661_36 = "Kena kau!",
  str_voice_1601661_37 = "Pergi, Kylo. Rencana A!",
  str_voice_1601661_38 = "Kyllo, perubahan rencana. Rencana B!",
  str_voice_1601661_39 = "Ayo bantu!",
  str_voice_1601661_40 = "Kekuatan persahabatan!",
  str_voice_1601661_41 = "Hehe, tentu saja aku harus menjadi kapten!",
  str_voice_1601661_42 = "Operasi sukses!",
  str_voice_1601661_43 = "Aku benci perasaan ini!!",
  str_voice_1601661_44 = "Tekstur ini... Apakah berat Kyllo bertambah?",
  str_voice_1601661_45 = "Bisakah saya benar-benar memiliki ini?",
  str_voice_1601661_46 = "Hmm. PlayerName, jangan bilang kamu suka...",
  str_voice_1601661_47 = "Wow! Ini hadiah!",
  str_voice_1601661_48 = "Uwahhhhh!! Kamu sangat baik padaku!",
  str_voice_1601661_49 = "Saya masih ingat kata-kata yang tertulis di halaman judul \"1.001 Makhluk Fantastis\": \"Untuk semua yang kesepian dan tak berdaya. Jangan terjebak oleh pikiran negatif Anda. Buka mata Anda dan lihat dunia luar. Ada banyak makhluk yang tak terhitung jumlahnya. di luar sana sama sepertimu, namun agak berbeda.\"",
  str_voice_1601661_50 = "Ugh! Guru adalah pria paling tidak bisa diandalkan yang pernah saya temui, dan senior saya juga wanita yang aneh. Apakah karena tidak ada orang normal yang ingin menjadi ahli ekstrozoologi? Apakah saya salah memilih karir...",
  str_voice_1601661_51 = "\"Hormati kebiasaan dan keinginan binatang yang menakjubkan, dan jangan memaksakan ide Anda sendiri pada mereka.\" Seseorang harus sepenuhnya memahami hal ini agar dapat bergaul dengan baik dengan mereka. Saya tidak memahami poin ini sampai saat ini.",
  str_voice_1601661_52 = "Bintang Alkimia",
  str_voice_1601661_53 = "saya Fia!",
  str_voice_1601661_54 = "Pagi.",
  str_voice_1601661_55 = "Siang, siang!",
  str_voice_1601661_56 = "Bagus—*menguap* malam.",
  str_voice_1601661_57 = "Ini tahun baru! Tahun baru! Selamat Tahun Baru!!",
  str_voice_1601671_1 = "Visual yang luar biasa dapat menarik seseorang ke dalam jurang emosi yang intens. Yang lebih menarik dan menggiurkan adalah bahwa visi semacam itu memungkinkan kita untuk membuat hubungan antara semua yang kita ketahui...",
  str_voice_1601671_2 = "Suara gelembung pecah saat bertemu sisi kapal. Suara angin menipu bertiup melalui celah-celah lambung kapal. Suara keajaiban yang harus dikorbankan, melonjak ke atas ke arahku, memberi isyarat untuk dibuka.",
  str_voice_1601671_3 = "Saya akrab dengan aroma putus asa karena saya pernah menjadi salah satu dari mereka.",
  str_voice_1601671_4 = "Kartu selektif menemukan arah di antara segudang pikiran tanpa arah, dan orang bodoh yang vulgar adalah mereka yang tidak tahan dengan tangan yang telah mereka tangani.",
  str_voice_1601671_5 = "Hal-hal memanas. Tangan ini akan membuat musuh gemetar.",
  str_voice_1601671_6 = "Hiruk-pikuk musik kemarahan, kartu-kartu mengilap bergoyang-goyang. Heh, emas benar-benar bau.",
  str_voice_1601671_7 = "Keajaiban yang kita sebut sulap, pada dasarnya, adalah pertaruhan antara pesulap dan alat peraganya. Anda harus memaksa otot Anda untuk mengingat gerakan yang benar... Aku memakai kaus kaki saya dalam ke luar.",
  str_voice_1601671_8 = "Perasaan aneh apa ini? Menjadi lebih sulit untuk mempertahankan wajah poker, dan keringat tampaknya terbentuk di punggungku... Begitu. Pasti ada banyak musuh di dekatnya.",
  str_voice_1601671_9 = "Maaf, aku berkeringat. Berdiri sederhana di sini menatap Anda telah menyebabkan saya untuk mengungkapkan tangan saya.",
  str_voice_1601671_10 = "Saya tidak menikmati zonasi. Pikiran-pikiran yang mengganggu berjalan dengan bebas di kepalaku, bergerak menuju kenangan saat-saat yang telah kukerjakan dengan keras untuk ditinggalkan.",
  str_voice_1601671_11 = "Tempat berteduh ini begitu tenang, membuat orang merasa tidak nyaman. Mungkin saya harus memenggal kepala saya... tidak, tidak ada yang bisa melepaskan kepala mereka.",
  str_voice_1601671_12 = "Saya tidak peduli untuk hal-hal tipis selain sihir. Mereka mengejek saya, karena saya mengolok-olok mereka.",
  str_voice_1601671_13 = "Pertunjukan sulap adalah saran flamboyan yang didasarkan pada keterampilan teknis dan efek visual yang memukau. Bahasa? Terlalu banyak fokus pada bahasa akan membingungkan penonton dan mengarahkan mereka ke lorong gelap ketidakjelasan.",
  str_voice_1601671_14 = "Berjalannya waktu membuat Anda marah pada ketidakberdayaan Anda, sementara Kebenaran dan hanya Kebenaran dapat memberi Anda semua makna yang Anda dambakan... Byline seperti itu pasti akan memenuhi misi Victoria, bukan?",
  str_voice_1601671_15 = "Selamat ulang tahun. Penampilan apa yang ingin Anda lihat hari ini?",
  str_voice_1601671_16 = "Hari ini, saya akan menceburkan diri ke dunia sihir aneh yang penuh dengan misteri dan absurditas.",
  str_voice_1601671_17 = "Kopi hitam memang yang terbaik, asalkan saya bisa memegang cangkir saya dengan mantap.",
  str_voice_1601671_18 = "Untuk inspirasi yang berkibar di luar jangkauan... maukah kau menyerah padaku dan mengalir ke pikiranku sekarang?",
  str_voice_1601671_19 = "Namun satu malam lagi diselamatkan oleh sihir. Haruskah kita pergi tidur?",
  str_voice_1601671_20 = "Baik reputasi saya dan kartu saya diberikan kepada saya oleh wanita itu.",
  str_voice_1601671_21 = "Tahukah Anda tempat mana di dunia ini yang memiliki budaya kuliner paling maju? Saya ingin mengunjunginya, mungkin.",
  str_voice_1601671_22 = "Semoga Truth memberkatimu.",
  str_voice_1601671_23 = "Aku benci semua makhluk biologis yang tidak memiliki keindahan... Mungkin mereka sama sekali bukan makhluk biologis.",
  str_voice_1601671_24 = "Rainbow telah menanggung beban yang tidak bisa saya tangani.",
  str_voice_1601671_25 = "Kami pernah saling mempercayakan air mata dan tawa kami, hingga tanggung jawab menjadikan kami tawanan.",
  str_voice_1601671_26 = "Saya tidak keberatan tampil untuk anak-anak. Mereka membuatku merasa nyaman.",
  str_voice_1601671_27 = "Menambah berat badan akan mengurangi fleksibilitas penampilan saya, dan semua alat peraga saya harus dibuat ulang menjadi ukuran yang lebih besar.",
  str_voice_1601671_28 = "Itu bisa terbang, tetapi tidak bisa mengapung.",
  str_voice_1601671_29 = "Hadirin yang terhormat, salam. Saya Jeno si penyihir dan kapten Zamrud. Harap tetap disini, karena pertemuan ini hanyalah prolog dari pertunjukan yang akan datang.",
  str_voice_1601671_30 = "Trik yang bagus.",
  str_voice_1601671_31 = "Menggantinya untuk sesuatu yang baru.",
  str_voice_1601671_32 = "Kartu Asal yang Diberkati.",
  str_voice_1601671_33 = "Apakah ini batas atas?",
  str_voice_1601671_34 = "Aku mengerti.",
  str_voice_1601671_35 = "Alat peraga siap.",
  str_voice_1601671_36 = "Apakah Anda ingin melihat trik sulap?",
  str_voice_1601671_37 = "Lihat aku!",
  str_voice_1601671_38 = "Pertunjukan yang bagus!",
  str_voice_1601671_39 = "Bersoraklah untukku!",
  str_voice_1601671_40 = "Rasakan gemuruhnya!",
  str_voice_1601671_41 = "Antisipasi Anda dihargai.",
  str_voice_1601671_42 = "Performa standar saja.",
  str_voice_1601671_43 = "Apakah saya menambah berat badan ...",
  str_voice_1601671_44 = "Colossus ini dapat dianggap sebagai keajaiban, tetapi masih ada keajaiban yang lebih dekat dengan Anda.",
  str_voice_1601671_45 = "Sebuah hadiah? Terima kasih.",
  str_voice_1601671_46 = "Hadiah yang murah hati ini ...",
  str_voice_1601671_47 = "Saya merasa gugup.",
  str_voice_1601671_48 = "Ada yang bisa kubantu?",
  str_voice_1601671_49 = "Aku biasa naik ombak dan melihat matahari terbit bersama Elvis... Dia juga akan menyeretku keluar rumah untuk bertemu teman baru. Kami dulu melakukan hal-hal itu bersama-sama, pada suatu waktu.",
  str_voice_1601671_50 = "Orang tua saya membawa saya untuk tinggal di Zamrud, untuk melarikan diri dari Krisis Kegelapan, tetapi itu bukan milik saya pada waktu itu.",
  str_voice_1601671_51 = "Saya meninggalkan Zamrud untuk berkeliling benua tanpa memberi tahu orang tua saya atau pria yang mengajari saya sihir, dan akhirnya bertemu wanita itu.",
  str_voice_1601671_52 = "Alchemy Stars.",
  str_voice_1601671_53 = "Penonton tersayang.",
  str_voice_1601671_54 = "Saatnya bangun dari mimpimu.",
  str_voice_1601671_55 = "Selamat siang, saya harus bersiap-siap untuk penampilan saya.",
  str_voice_1601671_56 = "Semua tenang. Pergi tidur.",
  str_voice_1601671_57 = "Selamat Tahun Baru! Saya berharap bahwa saya dapat mencapai potensi terbesar saya, dan kemudian membuat terobosan.",
  str_voice_1501681_1 = "Salam, hadirin yang terhormat. Biarkan aku mendengar suaramu! Oh? Kenapa aku tidak mendengar apa-apa? Ada yang suka mandi air dingin? Azure Blaster di tanganku mungkin bisa membantu.",
  str_voice_1501681_2 = "Astaga. Apakah Anda mengerutkan kening? Ayo bermain air denganku jika kamu merasa sedih! Ayo. Bayangkan... bahwa ini adalah laut yang luas dan kita terombang-ambing saat kita mengapung di atas ombak...",
  str_voice_1501681_3 = "Saya pernah mengikuti les vokal! Jenis untuk membuat suara Anda lebih jelas dan lebih manis. Hee hee, saya melakukannya untuk memastikan bahwa semua pengunjung yang menghadiri pertunjukan kami dapat mendengar kata-kata saya dengan jelas.",
  str_voice_1501681_4 = "Aku tidak bisa mengendalikan diriku! Saya ingin meledakkan seluruh dunia dengan air dan memberikan semua kesejukan yang menyegarkan yang saya bisa!",
  str_voice_1501681_5 = "Wah! Saya merasa telah membuat banyak kapal! Bukan hanya kapal raksasa seperti Zamrud, tapi juga kapal besi, kapal penangkap ikan, kapal pelaut... Hehe, saya hanya berbicara tentang model saja.",
  str_voice_1501681_6 = "Saya Rainbow, kepala penjaga Zamrud. Saya selalu siap untuk bergerak! Anda dapat mengandalkan saya untuk menyelam, mencari ikan, dan memelihara Zamrud setiap hari! Tolong beri perintah Anda!",
  str_voice_1501681_7 = "Penonton yang terhormat, saatnya istirahat! Perhatikan sekarang. Bagus! Saya melihat mata Anda yang penuh harap dan senyum santai!",
  str_voice_1501681_8 = "Anda ingin tiket masuk gratis? S-pasti!! Biarkan saya menghitung gaji saya bulan ini. Jika saya harus mengganti tiket Anda... Hmm! K-Kamu tidak mendengar apa-apa!!",
  str_voice_1501681_9 = "Apakah hubungan kita seperti yang kupikirkan? K-Kamu harus berbicara seperti ini kepada semua orang, kan?",
  str_voice_1501681_10 = "Tidak ada tepuk tangan? Yah, bahkan aku akan merasa kesepian jika kamu tidak mau bekerja sama.",
  str_voice_1501681_11 = "Tidak ada lagi pemanasan dan pengumuman panggung yang sederhana? A-Apakah saya akhirnya diizinkan untuk memberikan kinerja yang nyata dan lengkap!? Wow... Kau sangat baik padaku!!",
  str_voice_1501681_12 = "Hal-hal menjadi sangat sibuk di sirkus saat hujan. Kita harus menyingkirkan semua alat peraga dan kemudian menangani pengeras suara yang basah... Omong-omong, aku cukup baik dalam memperbaiki hal-hal itu!",
  str_voice_1501681_13 = "Semua orang hanya mengatakan saya populer untuk membuat saya bahagia! Aku tidak akan pernah melompat kapal. Saya ingin tinggal dengan sirkus untuk belajar lebih banyak dari insinyur kelautan!",
  str_voice_1501681_14 = "Saya baru saja memperbaiki ember air. Bagaimana dengan itu? Apakah itu terlihat bagus? Hee hee. Aku pikir juga begitu! Tapi masih bocor kemana-mana...",
  str_voice_1501681_15 = "Selamat ulang tahun!! Saya akan menemani Anda hari ini tidak peduli apa yang ingin Anda lakukan!",
  str_voice_1501681_16 = "Hai! Maukah kamu menangkap ikan denganku hari ini? Dengan jaring? Tidak! Menangkap ikan dengan tangan kosong jauh lebih menyenangkan!",
  str_voice_1501681_17 = "Pagi! Saya pikir saya baru saja melihat kapal laut yang sangat mengagumkan! Hm? Oh, itu Kurir kecil?",
  str_voice_1501681_18 = "Tidak ada pertunjukan hari ini. Apa yang harus saya lakukan? Jadwalkan malam saya? Tidak perlu. Kami hanya akan mengikuti arus.",
  str_voice_1501681_19 = "Mengapa Anda masih terbangun? Apakah Anda menunggu saya untuk meminta Anda tidur? Baiklah, pergi tidur kalau begitu!",
  str_voice_1501681_20 = "Zamrud adalah yang terbaik! Diikuti oleh kapal yang akan saya buat di masa depan! Oh, aku lupa Soroz...",
  str_voice_1501681_21 = "Illuminans sepertinya selalu membawa gadget yang menarik. Saya ingin pergi ke sana suatu hari nanti!",
  str_voice_1501681_22 = "Aku akan selalu melindungimu!",
  str_voice_1501681_23 = "Berapa banyak lagi musuh seperti ini yang harus saya kalahkan?",
  str_voice_1501681_24 = "Ringmaster Jeno mungkin terlihat dingin dan acuh tak acuh, tetapi jika Anda berbicara dengannya sedikit lebih... Hee hee hee.",
  str_voice_1501681_25 = "Aku akan menjadi insinyur kelautan yang hebat seperti tuanku suatu hari nanti... Benar?",
  str_voice_1501681_26 = "Saya sangat menikmati hidup saya sekarang! Saya suka air dan sirkus, dan saya suka individu yang ingin tahu seperti sekarang!",
  str_voice_1501681_27 = "Jika ada, saya benci iklim kering... Dan saya tidak terlalu suka orang yang membosankan.",
  str_voice_1501681_28 = "S-Soroz Kapal Raksasa!! Sigh... Kenapa aku tidak terlahir sebagai Caelestit? Maka saya akan bisa berbicara dengannya ...",
  str_voice_1501681_29 = "Hai! Bagaimana keadaannya? Aku Rainbow, satu-satunya penjaga Zamrud yang ditunjuk! Anggota baru sirkus? Itu hanya pekerjaan paruh waktu saya!",
  str_voice_1501681_30 = "Guyuran!",
  str_voice_1501681_31 = "Tekanan air naik!",
  str_voice_1501681_32 = "Air mancur panas!",
  str_voice_1501681_33 = "Gelombang besar!",
  str_voice_1501681_34 = "Saya telah bergabung dengan formasi kapal perang!",
  str_voice_1501681_35 = "Saya selalu siap!",
  str_voice_1501681_36 = "Biarkan aku keluar!",
  str_voice_1501681_37 = "Ini dia Rainbow!",
  str_voice_1501681_38 = "Meledak! Percikan air!",
  str_voice_1501681_39 = "Tekanan naik!",
  str_voice_1501681_40 = "Ledakan tekanan!",
  str_voice_1501681_41 = "Ah! Mengerti!",
  str_voice_1501681_42 = "Betapa beruntung!",
  str_voice_1501681_43 = "aku tidak akan pernah menyerah...",
  str_voice_1501681_44 = "Colossus terasa agak kering. Haruskah saya meledakkan air?",
  str_voice_1501681_45 = "Akan kuterima!",
  str_voice_1501681_46 = "Hee hee, aku akan memasukkannya ke dalam sakuku.",
  str_voice_1501681_47 = "Apakah ... Anda mengungkapkan niat baik terhadap saya?",
  str_voice_1501681_48 = "Ca-Bisakah saya mengambil hadiah ini?",
  str_voice_1501681_49 = "Saya praktis dibesarkan di dalam air. Saya biasa mengikuti orang tua saya ke laut untuk menangkap ikan ketika saya masih muda dan berlari-lari sambil memegang pistol air buatan ayah saya ini. Ha ha ha.",
  str_voice_1501681_50 = "Plank No. 1 dan Fishing Rod No. 2 adalah teman saya ketika saya tinggal di laut sendirian. Saya tidak tahu apa yang akan saya lakukan tanpa mereka selama periode tepat setelah kehilangan orang tua saya.",
  str_voice_1501681_51 = "Mantan kapten Circus adalah penyelamatku! Sayang. Aku benar-benar tidak bisa mempelajari trik sulap itu. Bahkan dia tidak bisa berbuat apa-apa terhadapku.",
  str_voice_1501681_52 = "Bintang Alkimia!!",
  str_voice_1501681_53 = "Mengapa halo, penonton kecil!",
  str_voice_1501681_54 = "Pagi! Ini adalah waktu terbaik untuk menangkap ikan!",
  str_voice_1501681_55 = "Selamat sore! Panas sekali hari ini!",
  str_voice_1501681_56 = "Saya memiliki pertunjukan malam ini!",
  str_voice_1501681_57 = "Selamat Tahun Baru! Saya akan terus memberikan pertunjukan sambil bekerja keras untuk mencapai tujuan saya menjadi insinyur kelautan tahun ini!",
  str_voice_1600384_10 = "Apa yang kamu lakukan? Jika ini terus berlanjut, aku akan bosan. PlayerName, lihat ke sini!",
  str_voice_1600384_11 = "Hah? Apakah kita memainkan semacam permainan berpura-pura akuarium? Saya memainkan ikan akuarium dan Anda bermain sebagai pengunjung di sisi lain kaca... Hee hee. Kedengarannya cukup menarik!",
  str_voice_1600384_16 = "Saatnya untuk menyelidiki strategi potensial. Hmm. Anda *di sini* untuk bermain-main dengan saya, bukan?",
  str_voice_1600384_17 = [[
Sialan. Saya menghabiskan sepanjang malam dan hampir melewati permainan!!
Tapi saya harus pergi ke lab penelitian dan membagikan hasil penelitian yang saya dapatkan kemarin sore...]],
  str_voice_1600384_18 = "Saya mencoba memasak hidangan yang disebutkan dalam game. Ahem, untuk hasilnya... Aku akan meninggalkan hal-hal itu di dunia game.",
  str_voice_1600384_19 = "Kamu masih online juga? Wow! Ini adalah waktu yang tepat untuk meningkatkan peringkat!",
  str_voice_1600384_35 = "Gronru baru!",
  str_voice_1600384_36 = "Aku datang!",
  str_voice_1600384_37 = "Ketuk tombol ini untuk melepaskan keterampilan pamungkas!",
  str_voice_1600384_38 = "Level—tertinggi—!",
  str_voice_1600384_39 = "Anda akan turun!",
  str_voice_1600384_40 = "Kamu kalah!",
  str_voice_1600384_44 = "Anda suka kulit baru saya? Hee hee. Terima kasih.",
  str_voice_1600384_58 = "Ikan mengikuti Anda seperti sidekicks mengikuti protagonis dalam permainan. Hah? Jadi kamu partnernya dan aku protagonisnya kali ini?",
  str_voice_1600384_59 = "Bisakah kamu lebih dekat? Lebih dekat, lebih dekat... Awas! Itu yang paling dekat yang bisa Anda dapatkan, atau kita mungkin bertukar posisi. Tertarik untuk melihat seperti apa rasanya di sini?",
  str_voice_1600384_60 = "Tidak peduli seberapa sulit permainannya, Anda akan berhasil melewatinya setelah beberapa kali mencoba. Jika seseorang bersedia menghabiskan lebih banyak waktu, mereka mendapatkan \"Hadiah Sempurna\" itu dengan cukup mudah... Anda tidak berpikir itu semudah itu? Yah, itu masih jauh lebih mudah daripada hal-hal di dunia nyata, bukan?",
  str_voice_1600384_61 = "Meskipun pakaian ini terlalu banyak mengekspos kulit saya, saya pikir jika saya memakainya ke lab penelitian, orang pertama yang tersipu saat melihatnya adalah Unimet.",
  str_voice_1600384_62 = "Bagi saya, melakukan riset sama mudahnya dengan bermain game karena kedua hal tersebut memiliki solusi yang konkrit. Betul sekali. Pertanyaan dengan jawaban selalu lebih mudah untuk ditangani.",
  str_voice_1600384_63 = "Terkadang saya kembali ke permainan yang sudah saya selesaikan sejak lama... Mungkin karena saya tidak bisa melepaskan semua usaha yang saya lakukan untuk menyelesaikannya atau emosi yang saya investasikan di dalamnya.",
  str_voice_1600384_64 = "Pagi…",
  str_voice_1600384_65 = "Selamat pagi! Apakah kamu suka laut?",
  str_voice_1600384_66 = "Pagi! Aku akan pergi ke tempat pengujian dengan Siobhan hari ini!",
  str_voice_1600384_67 = "Pagi! Saya sudah mulai bekerja.",
  str_voice_1600384_68 = "Tinggalkan pesan jika Anda butuh sesuatu! Jika saya tidak menjawab, itu berarti saya sedang bekerja.",
  str_voice_1600384_69 = "Coba tebak aku makan siang apa?",
  str_voice_1600384_70 = "Hai! Selamat sore! Saya mencoba game dari genre baru hari ini!",
  str_voice_1600384_71 = "Saya perlu istirahat dengan baik siang ini.",
  str_voice_1600384_72 = "Apa yang harus saya lakukan saat istirahat siang hari ini?",
  str_voice_1600384_73 = "Kali ini lagi!",
  str_voice_1600384_74 = "Hee hee. Saya memiliki makan malam yang luar biasa!",
  str_voice_1600384_75 = "Sial, sial, sial, kacaukan ini! Aku tersesat!",
  str_voice_1600384_76 = "*mengendus* ... Plot game yang saya selesaikan hari ini sangat menyentuh ...",
  str_voice_1600384_77 = "Apa yang Anda pikirkan sebelum tidur setiap malam?",
  str_voice_1501301_1 = "Ada kasus di mana penggugat dan keluarganya dijatuhi hukuman pengasingan, semua karena bersendawa di depan hakim saat mengajukan kasusnya. Dia meninggal di pengasingan, yang membuka penyelidikan pada hakim. Saya bertanya-tanya berapa banyak orang yang meninggal karena satu sendawa?",
  str_voice_1501301_2 = "Banyaknya sel yang tersedia mempengaruhi berat ringannya putusan hakim. Meskipun hal itu menimbulkan masalah bagi pelaksanaan keadilan, setidaknya salah satu pihak pergi dengan perasaan puas.",
  str_voice_1501301_3 = "Apakah Caelestites menggunakan kemampuan psikis mereka ketika menghukum orang lain? Atau apakah mereka menggunakannya untuk membela diri saat diadili? Meskipun, jika semuanya terjadi di dalam pikiran seseorang, tidak perlu kata-kata.",
  str_voice_1501301_4 = "Jika kunang-kunang Anda ditemukan sebagai makhluk hidup, bukankah itu membuat Anda bersalah karena memperbudak mereka? Anda akan melanggar hukum! Ke pengadilan, sekarang!",
  str_voice_1501301_5 = "Tidak terbiasa dengan hukum? Tidak apa-apa, saya bisa membacakan apa pun yang perlu Anda ketahui. Tetapi apakah itu akan berguna atau tidak sepenuhnya terserah Anda.",
  str_voice_1501301_6 = "Apa itu? Anda pikir beberapa undang-undang kita sama sekali tidak praktis? Mengapa, itu sangat normal, mengingat orang-orang di Lumopolis hanya peduli dengan menulis undang-undang, bukan menegakkannya.",
  str_voice_1501301_7 = "Jika Anda perlu mengadakan persidangan di atas Colossus, saya dapat mengisi hampir semua peran yang Anda butuhkan: hakim, jaksa, dan pengacara! Aku bisa memastikan kamu selalu menang. Oh, tapi saya akan menyerahkan penuntutan kepada Anda, tentu saja.",
  str_voice_1501301_8 = "Pernahkah Anda memperhatikan bahwa semakin bagus judulnya, semakin salah kedengarannya? Misalnya, \"bangsawan yang dermawan\", \"ksatria setia\"... atau \"Lumopolis, jantung peradaban.\"",
  str_voice_1501301_9 = "Setelah melihat semua rahasia jahatnya yang tersembunyi di balik bayang-bayang, terkadang saya berharap Lumopolis akan jatuh dari menara gadingnya dan menabrak dunia di bawahnya.",
  str_voice_1501301_10 = "Bagaimana Anda terikat dengan Colossus ini? Dengan warisan atau melalui kontrak yang mengikat secara hukum? Apakah Fireflies secara individual dilindungi sebagai hasilnya? Ugh, begitu banyak pertanyaan... Mungkin aku harus mendendamu dan meneleponnya sehari?",
  str_voice_1501301_11 = "Anda membutuhkan saya untuk memimpin persidangan di sini? Tidak ada kesempatan! Oh... kau tidak butuh apa-apa sekarang? Besar! Sekarang saya bisa memikirkan beberapa hukum baru untuk Colossus...",
  str_voice_1501301_12 = "Jika kita ingin memutuskan hukum di atas Colossus, kita harus meluruskannya terlebih dahulu. Apakah itu dianggap sebagai makhluk hidup atau wilayah? Itu cukup penting, lho!",
  str_voice_1501301_13 = "Kasus yang paling saya banggakan adalah ketika saya membantu pasangan yang bertengkar menyelamatkan pernikahan mereka dari perceraian yang tergesa-gesa. Tetapi karena membuang-buang waktu, saya tetap membuat kedua belah pihak membayar denda yang besar.",
  str_voice_1501301_14 = "Mustahil bagi hukum untuk menjelaskan setiap situasi yang mungkin terjadi, itulah sebabnya kami mengandalkan preseden atau ide-ide kami sendiri untuk memberikan penilaian pada waktu-waktu tertentu. Ini adalah bagian dari bagaimana Lumopolis mengikuti perkembangan zaman.",
  str_voice_1501301_15 = "Karena usia Anda belum terdaftar dalam catatan resmi Lumopolis, Anda dapat berpura-pura menjadi semuda yang Anda inginkan selama sisa hidup Anda. Apa pun itu, saya mengucapkan selamat ulang tahun kepada Anda.",
  str_voice_1501301_16 = "Hujan atau cerah, itu selalu hari yang baik untuk percobaan! Sebenarnya, saya baru saja memikirkan—maksud saya, ingat—sebuah pasal hukum baru dan ingin mengujinya.",
  str_voice_1501301_17 = "Ini sedikit lebih awal untuk percobaan, bukan begitu? Jika Anda sudah menyiapkan bahan, Anda bisa pergi. Aku sedang istirahat hari ini.",
  str_voice_1501301_18 = "Pencobaan yang benar dan kesimpulan yang benar adalah hebat dan semuanya... Tapi tidak ada yang lebih benar daripada secangkir kopi hitam panas di malam hari!",
  str_voice_1501301_19 = "aku kalah. Aku bahkan mulai memikirkan bagaimana menciptakan keadilan dan kesetaraan melalui hukum... Sepertinya aku perlu istirahat.",
  str_voice_1501301_20 = "Penduduk Lumopolis berjuang dan bekerja keras untuk kota mereka, sementara para bangsawan duduk di singgasana mereka, memanjakan diri secara berlebihan.",
  str_voice_1501301_21 = "Tempat tanpa pesanan yang hanya cocok untuk hewan. Tapi setidaknya majalah mereka tidak terlalu buruk!",
  str_voice_1501301_22 = "Malam Putih di atas! Hidup Lumopolis, terpujilah para bangsawan, karena itu akan membawa kita menuju kemakmuran! Bah.",
  str_voice_1501301_23 = "Makhluk yang tidak bisa memahami hukum sangat menyedihkan. Dikutuk menjadi terdakwa dan tidak pernah dituntut.",
  str_voice_1501301_24 = "Haruskah saya menemui ajal saya, setidaknya saya bisa mempercayai Hakim Ketua Irridon. Dia... berbeda.",
  str_voice_1501301_25 = "Saya melihat diri saya di masa lalu setiap kali saya melihat Keating... Pikir saya harus bekerja sama dengan mereka? Dengan saya sebagai pemimpin tim, kita bisa membawa keadilan ke seluruh dunia!",
  str_voice_1501301_26 = "Suara dentuman palu adalah suara keadilan itu sendiri... Dan itu terdengar sangat indah ketika Anda menjatuhkannya ke kepala seseorang!",
  str_voice_1501301_27 = "Saya hanya memiliki satu hal untuk dikatakan kepada orang-orang yang memahami hukum, tetapi puas hanya membicarakannya alih-alih menegakkannya: \"Tolong akhiri hidup Anda dengan sepatutnya.\"",
  str_voice_1501301_28 = "Soroz melanggar Pasal 1 Undang-Undang Langit Cerah Lumopolis, yang baru saja saya tulis sendiri. Maaf, tapi saya harus menyita Colossus Anda.",
  str_voice_1501301_29 = "Melestarikan keadilan dan hukum datang dengan harga, dan untuk membayar harga itu... selalu yang terbaik untuk memulai dengan orang lain! Itu sebabnya saya di sini—untuk memastikan Anda bukan salah satu dari mereka!",
  str_voice_1501301_30 = "Saatnya undang-undang baru!",
  str_voice_1501301_31 = "Penilaian saya tidak pernah salah.",
  str_voice_1501301_32 = "Putusan yang cepat.",
  str_voice_1501301_33 = "saya hukum.",
  str_voice_1501301_34 = "Aku akan menjadi saksimu.",
  str_voice_1501301_35 = "Siapkan untuk persidangan.",
  str_voice_1501301_36 = "Keberatan!",
  str_voice_1501301_37 = "Duduklah!",
  str_voice_1501301_38 = "Semua bangkit!",
  str_voice_1501301_39 = "Pengadilan sedang berlangsung!",
  str_voice_1501301_40 = "Memesan!",
  str_voice_1501301_41 = "Saya akan memimpin sebagai hakim.",
  str_voice_1501301_42 = "Keadilan dilayani.",
  str_voice_1501301_43 = "Pengadilan ditunda.",
  str_voice_1501301_44 = "Pesan, pesan! Saya akan mengadakan sidang di sini segera!",
  str_voice_1501301_45 = "Anda ingin menyuap saya ... dengan ini?",
  str_voice_1501301_46 = "Ah... Aku punya Anda tertutup.",
  str_voice_1501301_47 = "Suap adalah ilegal, ingat itu lain kali!",
  str_voice_1501301_48 = "Anda mendapat dukungan hakim ini!",
  str_voice_1501301_49 = "Saya menghafal seluruh kitab undang-undang ketika saya baru berusia 5 tahun. Begitulah cara saya bisa mulai sekolah begitu awal.",
  str_voice_1501301_50 = "Saat itu, mereka mengatakan saya adalah anak ajaib, atau pengacara masa depan paling menakutkan yang pernah mereka lihat.",
  str_voice_1501301_51 = "Dulu saya adalah orang yang tahu benar dan salah, tapi setelah hari itu... Saya memilih untuk menutup mata dan menutup telinga. Keluar dari akal pikiran.",
  str_voice_1501301_52 = "Alchemy Stars.",
  str_voice_1501301_53 = "Bersaksi!",
  str_voice_1501301_54 = "Pengadilan segera dibuka. Selamat pagi.",
  str_voice_1501301_55 = "Pengadilan sedang reses. Selamat sore.",
  str_voice_1501301_56 = "Pengadilan ditunda. Selamat malam.",
  str_voice_1501301_57 = "Tahun baru memberi saya peluang baru untuk melayani keadilan bagi Anda.",
  str_voice_1601701_1 = "Senyummu mengingatkanku pada anak tertentu. Jadi jika Anda bisa, tersenyumlah sebanyak mungkin, karena saya telah bersumpah untuk melakukan segala daya saya untuk melindungi senyum itu.",
  str_voice_1601701_2 = "Bahkan medan perang yang paling brutal pun akan berkembang dengan kehidupan baru suatu hari nanti. Gereja tua kami yang rusak tidak terkecuali.",
  str_voice_1601701_3 = "Orang biasanya menaruh harapan mereka di masa depan. Tapi bagaimana jika tidak ada masa depan bagi kita?",
  str_voice_1601701_4 = "Perdamaian melalui kompromi bukanlah perdamaian sama sekali. Hanya perdamaian yang dimenangkan melalui perjuangan yang bertahan.",
  str_voice_1601701_5 = "Hanya dengan hidup jauh di dalam bayang-bayang perang, seseorang dapat benar-benar memahami bobot dan kekejamannya.",
  str_voice_1601701_6 = "Meskipun saya membenci orang yang tidak tahu malu tanpa iman atau hati nurani, saya tahu jauh di lubuk hati bahwa saya tidak berbeda dari mereka.",
  str_voice_1601701_7 = "PlayerName, mungkin keberadaan Anda adalah mercusuar harapan bagi semua Aurorian.",
  str_voice_1601701_8 = "Jika keadaan berjalan serba salah, percayalah pada apa yang ditakdirkan untuk Anda. Dan jika semuanya berjalan sesuai rencana, jangan lupakan saat-saat ketika Anda berjalan melewati kegelapan.",
  str_voice_1601701_9 = "Hargai saat-saat damai yang berharga ini. Nikmati, nikmati, dan hargai... bersama kami.",
  str_voice_1601701_10 = "Untuk tentara bayaran, relaksasi bisa mengakibatkan kematian... Perlu aku menembakkan beberapa peluru di atas kepalamu untuk membangunkanmu?",
  str_voice_1601701_11 = "Anda membutuhkan saya untuk melakukan ini? Heheheh... Sepertinya kamu bergantung padaku seperti anak-anak.",
  str_voice_1601701_12 = "Hmm? Apakah Anda perlu memberi tahu saya sesuatu? Jangan khawatir, aku akan selalu di sini untuk mendengarkan.",
  str_voice_1601701_13 = "Kami mungkin telah kehilangan keluarga kami di masa lalu, tetapi masa depan masih panjang, dan kami akan mendapatkan kesempatan untuk membentuk keluarga baru.",
  str_voice_1601701_14 = "Apa hubungan Anda dengan Colossus? Apakah Anda keluarga, atau mungkin teman dekat? Menjadi teman dekat seseorang mungkin berbahaya...",
  str_voice_1601701_15 = "Selamat ulang tahun, PlayerName. Anak-anak meminta saya untuk menyampaikan pesan dari mereka: \"Selamat ulang tahun, dan kami berharap kami bisa bermain bersama selamanya!\"",
  str_voice_1601701_16 = "Anda benar-benar membuat saya menunggu... Anda tidak ingin membuat kesan buruk pada orang lain, bukan?",
  str_voice_1601701_17 = "Apakah kamu baru bangun? Atau tidak pernah pergi?",
  str_voice_1601701_18 = "Kerja bagus hari ini! Apakah Anda membutuhkan segelas susu hangat untuk membantu Anda bersantai?",
  str_voice_1601701_19 = "Pergi istirahat. Kami memiliki semua waktu di dunia.",
  str_voice_1601701_20 = "\"Survival of the fittest\" adalah cara dunia bekerja untuk orang dewasa, tetapi anak-anak layak untuk hidup dan bermain seperti anak-anak yang tidak bersalah.",
  str_voice_1601701_21 = "Umbraton? Saya kira saya tidak keberatan berbelanja beberapa mode terbaru, jika saya mendapat kesempatan.",
  str_voice_1601701_22 = "Berpikir dua kali sebelum memprovokasi murka Darah Raven.",
  str_voice_1601701_23 = "Makhluk tak beriman seperti Eclipsites tidak punya tempat di dunia ini.",
  str_voice_1601701_24 = "Casta adalah anak yang baik. Aku hanya berharap dia tidak menanggung begitu banyak sendirian...",
  str_voice_1601701_25 = "Kita akan bertemu lagi suatu hari nanti, Antares. Aku tahu kita akan melakukannya.",
  str_voice_1601701_26 = "Kudengar kau membawa baju baru dari Umbraton! Aku yakin mereka akan cocok untukku...",
  str_voice_1601701_27 = "Jauhkan hal-hal itu dariku. Anda akan melakukannya dengan baik untuk menjauh sendiri.",
  str_voice_1601701_28 = "Pasti sulit, membesarkan Colossusmu untuk tumbuh sebesar ini... Tunggu, maksudmu itu membesarkanmu?",
  str_voice_1601701_29 = "Orang tidak perlu menyembah cahaya. Anda bisa menjadi cahaya Anda sendiri, selama Anda berjuang untuk hal yang benar.",
  str_voice_1601701_30 = "Ini terasa agak bagus!",
  str_voice_1601701_31 = "Wah, saya merasa jauh lebih gesit!",
  str_voice_1601701_32 = "Ada yang berbeda sekarang, ya?",
  str_voice_1601701_33 = "Pertempuran adalah milikku!",
  str_voice_1601701_34 = "Pilihan bagus!",
  str_voice_1601701_35 = "Apa lagi yang kautunggu?",
  str_voice_1601701_36 = "Tak bisa kabur!",
  str_voice_1601701_37 = "Aku tidak membuang-buang amunisi untukmu.",
  str_voice_1601701_38 = "Nasib buruk, menabrak saya.",
  str_voice_1601701_39 = "Shock dan marah!",
  str_voice_1601701_40 = "Aku tak terkalahkan!",
  str_voice_1601701_41 = "Saya akan membawa Anda ke kemenangan lain!",
  str_voice_1601701_42 = "Heh, tidak ada apa-apa selain permainan anak-anak!",
  str_voice_1601701_43 = "Ugh... Kurasa aku sudah lunak.",
  str_voice_1601701_44 = "Hmm? Anda harus memiliki sesuatu untuk dikatakan, karena Anda menatapku seperti itu.",
  str_voice_1601701_45 = "Apakah ini untukku? Eh, maksudku... Terima kasih.",
  str_voice_1601701_46 = "Menarik... Saya tidak akan melupakan ini.",
  str_voice_1601701_47 = "Oh, Anda seharusnya tidak melakukannya! Terima kasih.",
  str_voice_1601701_48 = "Saya tidak sabar untuk menunjukkan ini kepada anak-anak!",
  str_voice_1601701_49 = "Semua moral dan etika telah mati dalam Euforia untuk waktu yang sangat lama sekarang, tetapi setidaknya, saya ingin gereja ini mempertahankan perasaan tentang seperti apa dunia yang layak itu.",
  str_voice_1601701_50 = "Saya terus-menerus membuat keputusan untuk anak-anak karena saya tidak ingin salah satu dari mereka mengikuti jejak saya.",
  str_voice_1601701_51 = "Antares, teman terdekatku... Persahabatannya memberiku kebahagiaan seumur hidup, dan kematiannya dengan tanganku sendiri meninggalkan kesedihan seumur hidupku.",
  str_voice_1601701_52 = "Alchemy Stars.",
  str_voice_1601701_53 = "Kita bertemu lagi!",
  str_voice_1601701_54 = "Anda tampaknya dalam suasana hati yang baik hari ini.",
  str_voice_1601701_55 = "Apakah Anda selalu begitu energik sepanjang hari?",
  str_voice_1601701_56 = "Ini sudah larut. Anak-anak yang begadang tidak akan tumbuh lebih tinggi.",
  str_voice_1601701_57 = "Selamat Tahun Baru, PlayerName. Saya harap kita bisa merayakan hari ini bersama setahun dari sekarang juga.",
  str_voice_1501711_1 = "Sejujurnya, saya merasa nyaman tinggal di Euphoria karena tidak perlu memikirkan apa pun kecuali bertahan hidup.",
  str_voice_1501711_2 = "Oh, Anda tidak perlu mewaspadai saya. Saya hanya menarik sesuatu seperti itu dengan Nekoyashiki. Selain itu, tujuan saya adalah sempurna.",
  str_voice_1501711_3 = "Berjuang adalah untuk menjaga orang-orang dan tempat-tempat yang Anda cintai agar tidak diambil dari Anda.",
  str_voice_1501711_4 = "Menarik senjata Anda terlalu lambat sama dengan menyerahkan hidup Anda kepada musuh. Percayalah, aku tidak akan pernah membiarkan itu terjadi.",
  str_voice_1501711_5 = "Pekerjaan ini benar-benar meningkatkan keterampilan saya sebagai tentara bayaran, jadi terima kasih untuk itu. Sepertinya Lady Luck belum menyerah padaku.",
  str_voice_1501711_6 = "Tidak peduli kehidupan seperti apa yang saya jalani di masa depan, saya tidak akan pernah melupakan perasaan pertempuran — perasaan hidup.",
  str_voice_1501711_7 = "Saya memiliki keyakinan penuh pada keberuntungan saya, karena saya selalu bisa melihat Anda di sekitar.",
  str_voice_1501711_8 = "Kau bisa... merasakan kepercayaanku padamu? Fantastis.",
  str_voice_1501711_9 = "Sebatang coklat... untukku? Anda DO ingat bahwa saya bersumpah hal itu, kan? Terima kasih!",
  str_voice_1501711_10 = "Kedamaian semacam ini dapat membuat seseorang menjadi malas, dan kemalasan menyebabkan rasa puas diri, yang membuat seseorang menjadi lemah. Yakinlah, itu tidak akan pernah terjadi padaku.",
  str_voice_1501711_11 = "Aku hanya harus membuatmu tetap aman, kan? Jangan khawatir, melindungi orang lain adalah keahlianku! Hmm? Apakah saya salah memahami sesuatu?",
  str_voice_1501711_12 = "Kehilangan kaki kananku tidak semuanya buruk, kau tahu? Setidaknya sekarang, setiap langkah yang saya ambil benar-benar dipikirkan.",
  str_voice_1501711_13 = "Pollux? Saya tidak perlu terus mengawasinya. Hati kita terhubung, jadi kita tahu apa yang terjadi satu sama lain lebih baik daripada orang lain.",
  str_voice_1501711_14 = "Aku merasa bisa melakukan apa saja setiap kali aku bersamamu. Apakah seperti ini rasanya dipercaya?",
  str_voice_1501711_15 = "Selamat ulang tahun. Aku punya sesuatu untukmu. Eh, saya tidak akan terlalu bersemangat tentang hal itu, meskipun.",
  str_voice_1501711_16 = "Apakah kamu sudah makan? Saya harus menjaga gula darah saya tetap tinggi sebelum berperang, atau itu bisa berarti masalah.",
  str_voice_1501711_17 = "Aku sudah sangat terbiasa dengan langit mendung. Akankah saya akhirnya memiliki kesempatan untuk melihat matahari juga?",
  str_voice_1501711_18 = "Aku tidak mengganggumu, kan? Maaf, kaki palsu baru saya masih patah.",
  str_voice_1501711_19 = "Jangan khawatir, aku masih di sini. Aku akan tetap dalam pandanganmu sampai pagi tiba.",
  str_voice_1501711_20 = "Dengan hanya dua orang, Raven's Blood berhasil mengukir wilayah mereka sendiri di Euphoria. Cukup mengesankan, ya?",
  str_voice_1501711_21 = "Pria Corax dari Umbraton itu tampaknya cukup bisa diandalkan. Saya kira mungkin ada beberapa manfaat untuk tempat itu, setelah semua.",
  str_voice_1501711_22 = "Berpikir dua kali sebelum memprovokasi murka Darah Raven.",
  str_voice_1501711_23 = "Eh, hal-hal ini tidak jauh berbeda dengan target di tempat syuting taman hiburan.",
  str_voice_1501711_24 = "Kami berhenti membutuhkan kata-kata untuk menggambarkan hubungan kami sejak lama. Yang perlu dikatakan adalah bahwa aku akan selalu berdiri di sisinya.",
  str_voice_1501711_25 = "Dia mungkin tidak mengakuinya, tetapi jelas bagi saya bahwa dia telah melakukan banyak hal untuk kami. Jangan bilang padanya aku bilang begitu!",
  str_voice_1501711_26 = "Jika Anda benar-benar mempercayai saya sebanyak ini, maka... Saya tidak membutuhkan pembayaran apapun dari Anda.",
  str_voice_1501711_27 = "Tugas yang rumit... Saya melakukannya saat diminta, tapi bukan karena saya mau.",
  str_voice_1501711_28 = "Untuk sesuatu yang sebesar Colossus ini terbang melintasi langit dengan begitu bebas... Aku tidak bisa mengatakan bahwa aku tidak cemburu.",
  str_voice_1501711_29 = "Saya bukan profesional, tetapi Anda tidak akan kecewa dengan keterampilan saya. Hal pertama yang pertama: Anda lebih baik membayar saya untuk nilai keterampilan saya.",
  str_voice_1501711_30 = "Mm, ini terasa luar biasa.",
  str_voice_1501711_31 = "Sudah kubilang keahlianku adalah yang sebenarnya.",
  str_voice_1501711_32 = "Mari kita bicara tentang kenaikan gaji, ya?",
  str_voice_1501711_33 = "Kemenangan terjamin.",
  str_voice_1501711_34 = "Anda... ingin saya bekerja dalam tim?",
  str_voice_1501711_35 = "Posisi terbaik dijamin.",
  str_voice_1501711_36 = "Menunggu perintahmu.",
  str_voice_1501711_37 = "Pedang ini bukan hanya untuk pertunjukan.",
  str_voice_1501711_38 = "Aku benci target bergerak.",
  str_voice_1501711_39 = "Sebuah tembakan yang sempurna.",
  str_voice_1501711_40 = "Hancurkan mereka semua!",
  str_voice_1501711_41 = "Mari berimprovisasi dan beradaptasi.",
  str_voice_1501711_42 = "Seperti yang saya harapkan.",
  str_voice_1501711_43 = "Lady Luck sedang berlibur...",
  str_voice_1501711_44 = "Sepertinya Lady Luck memperhatikanku hari ini.",
  str_voice_1501711_45 = "Apakah ini bonus saya? Terima kasih.",
  str_voice_1501711_46 = "Anak-anak akan menyukai ini. Terima kasih.",
  str_voice_1501711_47 = "Apakah Lady Luck memberitahu Anda ini adalah favorit saya?",
  str_voice_1501711_48 = "Ini membuat saya sangat mengantisipasi hadiah Anda berikutnya. Tidak ada tekanan, tentu saja.",
  str_voice_1501711_49 = "Pollux bagi saya lebih dari seorang teman atau anggota keluarga untuk waktu yang lama. Saya tidak pernah memiliki keinginan untuk menjadi pahlawan, tetapi saya akan melakukan apa saja untuk melindunginya ... bahkan menjadi penjahat.",
  str_voice_1501711_50 = "Pada awalnya, saya tidak menyadari betapa beruntungnya saya. Tapi itu mungkin bukan hal yang buruk. Begitu Anda mulai mengandalkan nasib baik semacam ini, Anda segera mengetahui bahwa itu selalu disertai dengan kemalangan dalam ukuran yang sama.",
  str_voice_1501711_51 = "Mereka mengatakan mudah bagi orang untuk kecanduan pahitnya kesulitan, dan saya tidak berbeda. Kehidupan perselisihan cocok untukku. Oh, tapi untuk rokok, Pollux dan aku sudah lama melarangnya.",
  str_voice_1501711_52 = "Alchemy Stars.",
  str_voice_1501711_53 = "Kau di sana?",
  str_voice_1501711_54 = "Ingatlah untuk tidak melewatkan sarapan.",
  str_voice_1501711_55 = "Matahari siang terlalu terang.",
  str_voice_1501711_56 = "Hari damai lainnya. Selamat malam.",
  str_voice_1501711_57 = "Selamat Tahun Baru. Sepertinya kita berhasil melewati satu tahun lagi dengan aman.",
  str_voice_1601721_1 = "Sebagai seorang aktris, salah satu hal terpenting untuk dipelajari adalah mengelola citra Anda. Jadi melewatkan beberapa kali makan di sana-sini ketika saya kehabisan uang benar-benar baik-baik saja! Ini pada dasarnya diet!",
  str_voice_1601721_2 = "Jika saya mendapat kesempatan, saya ingin tinggal di dekat laut. Makanan laut di sana sangat murah. Pikirkan semua kepiting yang bisa Anda dapatkan hanya dengan beberapa Nightium... yum!",
  str_voice_1601721_3 = "Apakah kita akan jalan-jalan? Biarkan aku mengambil kacamata hitam dan topiku kalau-kalau kita bertemu paparazzi... Aku tidak ingin melihat diriku di halaman depan majalah gosip karena berjalan-jalan dengan Caelestite.",
  str_voice_1601721_4 = "Wow, seperti yang diharapkan dari diri saya sendiri, pemotretan adegan luar biasa lainnya! Keseluruhan storyboard juga bagus. Film ini akan melakukannya dengan baik. Biarkan saya menandatangani rekaman itu terlebih dahulu!",
  str_voice_1601721_5 = "Ayo kita foto bersama! Oh, kau terlihat agak kaku. Berfoto dengan calon selebriti adalah kesempatan sekali seumur hidup, lho. Mari kita coba senyum itu lagi!",
  str_voice_1601721_6 = "Anda harus terus berinvestasi dalam bisnis ini. Anda tidak dapat memotong sudut ketika datang ke wajah Anda. Orang pintar tahu apa yang saya bicarakan!",
  str_voice_1601721_7 = "Saya tidak percaya butuh waktu selama ini untuk menyadari bahwa saya juga bisa menjadi sutradara yang hebat. Saya tidak sabar untuk mengarahkan film yang dibintangi sendiri!",
  str_voice_1601721_8 = "Ingin pergi menonton film bersama? Aku sedang berpikir horor. Jangan khawatir, saya sudah melihat semuanya. Aku akan memberitahumu sebelumnya jika sesuatu yang menakutkan akan terjadi.",
  str_voice_1601721_9 = "Aku baru menyadari sesuatu... kau sebenarnya orang yang cukup tampan. Mau bikin film bareng? Dengan penampilanmu dan bakat alamiku, kita bisa sukses besar!",
  str_voice_1601721_10 = "Anda tampaknya sangat sibuk. Saya akan melatih dialog saya sementara saya menemani Anda. Tunggu... Pasti ada kesalahan. Saya jelas seorang aktris yang dikreditkan, jadi mengapa saya hanya memiliki satu baris?",
  str_voice_1601721_11 = "Apa lokasi yang bagus. Aku akan mengingatnya. Kita bisa syuting di sini suatu hari nanti.",
  str_voice_1601721_12 = "Mau belanja bareng? Tinggalkan tawar-menawar kepada saya. Saya hanya menghabiskan sekitar 200 Nightium untuk Cellulo, Anda tahu?",
  str_voice_1601721_13 = "Anda tahu apa yang enak dan membuat Anda kenyang seperti tidak ada yang lain? Jagung meletus. Saya benar-benar bangkrut ketika saya datang ke Umbraton. Saya sering makan ember popcorn sisa orang lain di bioskop untuk mencegah rasa lapar.",
  str_voice_1601721_14 = "Tidak ada yang salah dengan bermain ekstra! Bahkan jika Anda hanya memiliki satu adegan atau satu baris, itu masih merupakan pertunjukan yang sama. Saya selalu mengambil setiap peran dengan sangat serius.",
  str_voice_1601721_15 = "Aku menghabiskan banyak waktu untuk syuting proyek spesial ini untuk ulang tahunmu! Matikan lampunya, dan mari kita tonton bersama!",
  str_voice_1601721_16 = "*Menguap* Itu kamu ya? Ingin secangkir kopi? Aku terjaga semalaman lagi untuk melatih dialogku.",
  str_voice_1601721_17 = "Anda bangun pagi. Saya harap Anda tidak keberatan jika saya mendapatkan beberapa jam lagi tidur cantik ...",
  str_voice_1601721_18 = "Aku menuju keluar sekarang. Tidak banyak paparazzi pada jam ini.",
  str_voice_1601721_19 = "Wow, apakah kamu tidur larut malam juga? Besar! Latih beberapa baris saya dengan saya!",
  str_voice_1601721_20 = "Umbraton's Alleywood adalah tempat sekelompok aktor dan sutradara memulai karir mereka!",
  str_voice_1601721_21 = "Anda tahu, ada sesuatu yang agak memesona tentang Gurun Rediesel. Saya ingin sekali membuat film dokumenter dengan orang-orang di sana suatu hari nanti!",
  str_voice_1601721_22 = "Aku melihatmu melalui lensa kamera.",
  str_voice_1601721_23 = "Seseorang harus benar-benar mencari cara untuk memasukkan Eclipsites ke dalam film—dengan segala bentuknya.",
  str_voice_1601721_24 = "Pak Kleken sering menggunakan koneksinya untuk menjebak saya dengan gigs kecil-kecilan. Mereka tidak membayar banyak, tapi saya tetap bersyukur.",
  str_voice_1601721_25 = "Dayna adalah orang pertama yang mengenali saya sebagai ekstra yang diledakkan dalam film, \"The Battle of Umbraton\"!",
  str_voice_1601721_26 = "Dunia terlihat sangat berbeda melalui lensa kamera.",
  str_voice_1601721_27 = "Paparazzi benar-benar menyebalkan! Seorang penggemar dari orang yang sebelumnya dikabarkan bersamaku melemparkan lebih dari sepuluh telur ke arahku!",
  str_voice_1601721_28 = "Wow! B-Bisakah aku benar-benar tinggal di... tempat yang begitu spektakuler?",
  str_voice_1601721_29 = "Saya Lilica, sutradara-pemain luar biasa Umbraton! Magnum opus saya masih dalam proses, tapi saya bisa memberi Anda tanda tangan terlebih dahulu.",
  str_voice_1601721_30 = "Saya benar-benar merasakan inspirasi!",
  str_voice_1601721_31 = "Itu selalu merupakan ide yang baik untuk berinvestasi pada saya.",
  str_voice_1601721_32 = "Tunggu saja! Aku ditakdirkan untuk menjadi bintang.",
  str_voice_1601721_33 = "Keanggunan sangat penting bagi seorang aktris!",
  str_voice_1601721_34 = "Wow. Ini sangat cerah!",
  str_voice_1601721_35 = "Kamera, siap!",
  str_voice_1601721_36 = "Apakah Anda selesai berpose?",
  str_voice_1601721_37 = "Ooh! Sedikit overexposed, menurutku!",
  str_voice_1601721_38 = "Tindakan!",
  str_voice_1601721_39 = "Pergi, Selulo!",
  str_voice_1601721_40 = "Memotong! Ambil kembali bidikan ini!",
  str_voice_1601721_41 = "Saatnya saya untuk bersinar!",
  str_voice_1601721_42 = "Tidak ada kentang rebus hari ini. Mari kita rayakan!",
  str_voice_1601721_43 = "Jangan khawatir. Setidaknya kita tidak bangkrut.",
  str_voice_1601721_44 = "Saya mengevaluasi Colossus melalui lensa kamera saya. Ada banyak lokasi syuting yang bagus!",
  str_voice_1601721_45 = "Aku hanya tidak tahu harus berkata apa. Di sini, minta tanda tangan!",
  str_voice_1601721_46 = "Bagaimana Anda tahu saya menabung untuk ini?!",
  str_voice_1601721_47 = "Anda pasti tahu bagaimana menyenangkan seorang wanita!",
  str_voice_1601721_48 = "Saya tidak akan melupakan Anda ketika saya menjadi kaya di masa depan.",
  str_voice_1601721_49 = "Makanan laut sangat mahal saat tumbuh dewasa. Orang tua saya hanya mampu membelinya pada hari ulang tahun saya. Setelah saya dibayar untuk peran ini, saya akan mentraktir mereka ke perjamuan seafood besar di Umbraton!",
  str_voice_1601721_50 = "Ini adalah kamera yang diberikan orang tua saya ketika saya masih kecil. Saya tahu ini sudah tua, tetapi ada sesuatu yang luar biasa dari tekstur vintage yang ditangkapnya. Saya suka menggunakannya untuk memotret hal-hal sehari-hari. Sayang rol filmnya mahal.",
  str_voice_1601721_51 = "Saya telah menjadi tambahan, dimakan di pinggir jalan, terkena serangan panas karena berpakaian dengan kostum yang berat; Aku bahkan pernah tertiup ke langit sebelumnya. Tapi membuat film membuat saya bahagia, jadi saya tidak pernah menganggapnya sebagai kerja keras.",
  str_voice_1601721_52 = "Alchemy Stars.",
  str_voice_1601721_53 = "Ada apa?",
  str_voice_1601721_54 = "Menguap—aku masih mengantuk.",
  str_voice_1601721_55 = "Aku terbangun sangat lapar. Apa yang harus kumakan?",
  str_voice_1601721_56 = "Hari baru baru saja dimulai!",
  str_voice_1601721_57 = "Bagaimana kalau kita mengumpulkan semua orang untuk video Tahun Baru?",
  str_voice_1601731_1 = "Saya hanya ingin tahu apa yang Anda sukai dalam hal bunga? Saya mendapat beberapa tips dari seorang pedagang dari Cloud Island, dan jika Anda tidak keberatan, saya ingin mendekorasi ulang meja makan dengan beberapa bunga yang baru dipetik.",
  str_voice_1601731_2 = "Meskipun saya sangat menghargai Anda, hal yang sama tidak dapat dikatakan untuk tuan saya yang menuntut. Dia akan mengatakan Anda masih harus banyak belajar. Tapi jangan khawatir—saya akan membantu.",
  str_voice_1601731_3 = "Saya bukan pembaca pikiran. Saya hanya mengantisipasi apa yang dibutuhkan tuan saya dan tamu mereka, kemudian membuat pengaturan yang cermat untuk mereka. Ini adalah persyaratan dasar seorang kepala pelayan yang melayani keluarga Andersen.",
  str_voice_1601731_4 = "Jauh lebih tenang sekarang karena saya menyingkirkan Eclipsites di dekatnya. Bagaimana perasaan Anda tentang menemani saya berjalan-jalan santai?",
  str_voice_1601731_5 = "Jadwal yang ketat sangat penting. Waktu yang hilang tidak dapat diperoleh kembali, jadi mengkalibrasi arloji saku saya adalah salah satu hal pertama yang saya lakukan di pagi hari.",
  str_voice_1601731_6 = "Kendali seseorang atas suatu situasi—baik di medan perang atau dalam bisnis—sebagian besar bergantung pada pengalaman. Anda memiliki bakat asli. Saya akan dengan senang hati membagikan apa yang telah saya pelajari.",
  str_voice_1601731_7 = "Sebentar, bajumu sobek... Mungkin kelihatannya tidak banyak, tapi kita hanya bisa mengurus hal-hal besar ketika kita mengurus hal-hal kecil terlebih dahulu. Aku akan menjahitnya dalam waktu singkat.",
  str_voice_1601731_8 = "Saya memutuskan untuk memasak makanan karena saya memiliki waktu luang. Apakah itu sesuai dengan selera Anda? Oh, ada titik mentega di sudut mulutmu. Biarkan aku menghapusnya.",
  str_voice_1601731_9 = "Seorang pria harus tahu bagaimana menari, dan saya berharap banyak dari seorang teman Nina. Sehat? Apa yang kamu tunggu? Di Sini. Tangan di pinggangku. Mari kita mulai.",
  str_voice_1601731_10 = "Di sini dingin, dan aku tidak ingin kamu masuk angin. Jika Anda tidak keberatan, saya akan membawa Anda kembali ke kamar Anda. Saya sudah menyiapkan tempat tidur Anda dengan seprai segar dan menempatkan penyegar aromatik.",
  str_voice_1601731_11 = "Terima kasih atas undangan Anda yang baik, tetapi saya baru saja melihat debu saat menyeka pegangan tangan dengan sapu tangan saya. Izinkan saya untuk membersihkan tempat itu terlebih dahulu.",
  str_voice_1601731_12 = "Anda benar-benar agak rawan cedera. Silahkan. Duduklah sementara aku membersihkan lukamu.",
  str_voice_1601731_13 = "Hah? Maaf, saya tidak cukup menangkap itu. Tolong jangan salah mengartikan kondisi kelelahan saya saat ini. Saya hanya mengambil sedikit waktu luang yang langka ini untuk beristirahat sebentar. Aku minta maaf karena membuatmu khawatir.",
  str_voice_1601731_14 = "Sebagai kepala pelayan keluarga Andersen, saya menganggapnya sebagai misi hidup saya untuk selalu meningkatkan diri lebih jauh ke arah kesempurnaan, dan saya jauh dari itu.",
  str_voice_1601731_15 = "Selamat ulang tahun! Saya telah menyiapkan pesta malam untuk menghormati ulang tahun Anda, di mana semua teman dekat Anda telah diundang. Jika Anda tidak keberatan, mari kita kenakan pakaian yang lebih cocok untuk Anda.",
  str_voice_1601731_16 = "Saya mengerti Anda sibuk, tetapi saya harus mengingatkan Anda tentang pentingnya waktu makan yang teratur. Jaga dirimu.",
  str_voice_1601731_17 = "Apakah Anda ingin mencoba kue keju blueberry dan raspberry atau souffle vanila untuk teh pagi?",
  str_voice_1601731_18 = "Bolehkah saya merekomendasikan mandi, mengingat Anda agak lelah? Saya sudah mengambil kebebasan menjalankan air panas.",
  str_voice_1601731_19 = "Pentingnya istirahat yang tepat tidak dapat dilebih-lebihkan. Anda mungkin mendapati diri Anda dua kali lipat lebih produktif di siang hari jika Anda memenuhi kebutuhan Anda sekarang.",
  str_voice_1601731_20 = "Hal-hal yang telah saya lakukan untuk tuan saya yang terhormat bahkan tidak mendekati membayar kembali hutang budi yang saya miliki.",
  str_voice_1601731_21 = "Tidak ada bahaya yang akan menimpa Guru atau Nona Nina dalam pengawasan saya—baik di Umbraton, Lumopolis, atau di mana pun.",
  str_voice_1601731_22 = "Semua yang berani berkomplot melawan Andersen akan binasa di depan mataku.",
  str_voice_1601731_23 = "Aku tidak tahan dengan keberadaan makhluk kotor seperti Eclipsites di dunia.",
  str_voice_1601731_24 = "Hati Nona Nina murni dan baik, dan aku akan menjaga hidupnya dengan milikku.",
  str_voice_1601731_25 = "Meskipun kurangnya koordinasi Sanae terkadang menjadi perhatian, Nona Nina sangat menyukainya.",
  str_voice_1601731_26 = "Apakah ada yang lebih menggembirakan daripada perasaan bahwa segala sesuatunya rapi, rapi, dan teratur?",
  str_voice_1601731_27 = "Bagaimana beberapa orang bisa mentolerir kekacauan seperti itu di kamar mereka? Saya tidak bisa mengerti.",
  str_voice_1601731_28 = "Colossus benar-benar telah diatur dengan cara yang megah. Kecuali dengan kerumunan konstan datang dan pergi, itu benar-benar perlu dibersihkan secara teratur.",
  str_voice_1601731_29 = "Suatu kehormatan bertemu denganmu. Saya Minos, dan meskipun saya akan tetap menjadi pelayan eksklusif keluarga Andersen, yakinlah bahwa saya akan melakukan yang terbaik untuk membantu Anda.",
  str_voice_1601731_30 = "Latihan memupuk bakat.",
  str_voice_1601731_31 = "Aku masih harus pergi sejauh ini.",
  str_voice_1601731_32 = "Perasaan yang agak baru, harus saya katakan.",
  str_voice_1601731_33 = "Saya akan melakukan yang terbaik untuk membayar kepercayaan Anda.",
  str_voice_1601731_34 = "Aku mengerti.",
  str_voice_1601731_35 = "Saya menunggu perintah Anda.",
  str_voice_1601731_36 = "Haruskah saya membawa tangkapan kami?",
  str_voice_1601731_37 = "Mari kita selesaikan ini dengan cepat.",
  str_voice_1601731_38 = "Jangan takut. Saya akan menidurkan Anda dengan menggunakan metode yang paling lembut.",
  str_voice_1601731_39 = "Waktu untuk menghilang.",
  str_voice_1601731_40 = "Kotor.",
  str_voice_1601731_41 = "Yakinlah, serahkan tugas itu padaku.",
  str_voice_1601731_42 = "Untung aku tidak mengotori pakaianku.",
  str_voice_1601731_43 = "Saya minta maaf. Saya sangat salah perhitungan.",
  str_voice_1601731_44 = "Saya benar-benar membersihkan gelas minum di bar, jadi Anda tidak perlu khawatir menggunakannya.",
  str_voice_1601731_45 = "Ini sangat memikirkan Anda.",
  str_voice_1601731_46 = "Aku tidak percaya... Aku akan sangat menghargai ini.",
  str_voice_1601731_47 = "Anda murah hati untuk suatu kesalahan.",
  str_voice_1601731_48 = "Anda telah menemukan preferensi saya begitu cepat.",
  str_voice_1601731_49 = "Tanduk di kepala saya tidak putus dengan sendirinya, tetapi sebagai hasil dari mentor saya ... Tidak apa-apa. Itu di masa lalu. Biarkan masa lalu tetap berlalu. Maukah Anda menyegarkan diri dengan teh mint dan jeruk nipis?",
  str_voice_1601731_50 = "Seseorang harus selalu menjaga penampilan dengan baik. Saya ingat bagaimana saya pernah gagal untuk sepenuhnya menghilangkan beberapa noda darah dari diri saya sendiri dan membuat Nona Nina ketakutan sehingga dia menolak untuk mendekati saya untuk waktu yang sangat lama. Itu benar-benar menghancurkan hatiku.",
  str_voice_1601731_51 = "Sebenarnya tidak ada banyak hal untuk menjadi kepala pelayan—selain menyetrika, membersihkan, membuat makanan, menjamu tamu; menghilangkan Eclipsites terdekat, penyerang potensial, pembuat onar usil; serta tindakan intimidasi sesekali terhadap pertanda niat buruk.",
  str_voice_1601731_52 = "Alchemy Stars.",
  str_voice_1601731_53 = "Ada apa?",
  str_voice_1601731_54 = "Teh pagi sudah siap.",
  str_voice_1601731_55 = "Apa yang Anda inginkan untuk makan siang?",
  str_voice_1601731_56 = "Saatnya istirahat sekarang.",
  str_voice_1601731_57 = "Selamat Tahun Baru! Saya harus pergi mempersiapkan perjamuan Tahun Baru sekarang.",
  str_voice_1401691_1 = [[
Selamat datang pak! Tuan, selamat datang!
Tidak tidak tidak. "Selamat datang pak!" terdengar sedikit lebih baik...
Uh, aku masih mencari tahu kata kunci penerimaan misi.]],
  str_voice_1401691_2 = "Hei-o! Mataku sendiri menembus tabir malam dan tidak ada orang lain yang bisa mencapai ketinggianku. Saya tidak bisa melakukan apa pun yang orang lain bisa lakukan! ... Oh tidak, aku salah menyanyikannya.",
  str_voice_1401691_3 = "Swashbuckling adalah pekerjaan paling keren. Menjadi Tuan Kota? Terlalu tirani. Menjadi Raja Bayangan? Terlalu menakutkan. Menjadi seorang ratu? Terlalu fantastis. Menjadi seorang putri? Terlalu melelahkan. Apakah saya mengenal mereka? Tentu saja tidak! Tapi saya dapat memberitahu Anda swashbucklers adalah yang terbaik.",
  str_voice_1401691_4 = "Apakah saya lebih dekat untuk mencapai karir impian saya sebagai seorang petualang? Ya! Anda telah membantu saya melangkah lebih jauh di sepanjang jalan itu.",
  str_voice_1401691_5 = "Anda ingin tahu cara mencapai guild? Cara tercepat adalah saat burung gagak terbang. Jalan lurus ke depan. Lihat dinding itu? Pergi di atasnya. Oh, Anda ingin berkeliling? Saya minta maaf. Tumpuk saja beberapa peti jika Anda agak pendek.",
  str_voice_1401691_6 = "Si pemberani yang gagah itu menghilang ke dalam malam, tidak meninggalkan jejak di jalan-jalan kota kuno yang diterangi cahaya bulan... Yang tersisa hanyalah isak tangis dari penduduk miskin yang hidupnya baru saja diselamatkan. Hmm, bisakah suatu hari saya mencapai ini juga? Oh? Kita sudah melakukannya bersama?",
  str_voice_1401691_7 = "Apakah ada yang salah dengan ujung rambut saya? Warnanya memudar ya? Oh tidak. Saya baru tahu bahwa pewarna rambut itu buruk! Tunggu, ujung rambutku hitam seperti biasanya. Lalu kenapa kau menatapku?",
  str_voice_1401691_8 = "Ada terlalu banyak gadis yang lebih tua dan keren. Saya harus banyak belajar dari mereka. Dan Anda sendiri cukup keren, Caelestite, karena berani menghadapi bahaya dunia.",
  str_voice_1401691_9 = "Apakah Anda ingin saya membantu Anda membentuk otot, meminjamkan komik jagoan saya, atau meningkatkan selera mode Anda...? Tak satu pun dari itu? Baik. Aku akan tetap melakukan yang terbaik untuk melindungimu—walaupun bayarannya akan menyenangkan.",
  str_voice_1401691_10 = "Aku sangat sibuk, kau tahu. Saya melewatkan kelas pagi ini untuk membaca buku komik dan kemudian lagi di sore hari untuk memeriksa misi baru. Malam ini saya melakukan kursus pelatihan khusus dengan seorang teman perempuan saya yang lebih tua yang sangat mengesankan. Saya kagum pada kenyataan bahwa saya bahkan bisa berdiri di sini dengan begitu sabar sekarang.",
  str_voice_1401691_11 = "Berdiri penjaga adalah tugas yang mudah bagi saya. Jangan bilang kau ingin aku berdiri di sini dan mengamatimu? Baiklah, biarkan aku melihat kesamaan apa yang kamu miliki dengan para swashbucklers...",
  str_voice_1401691_12 = "Ketika saya menurunkan pinggiran topi saya, itu berarti saya akan bertindak! Waspadalah terhadap lingkungan Anda, karena saya mungkin muncul di sebelah Anda kapan saja.",
  str_voice_1401691_13 = "Saya hanya bisa menemukan pekerjaan di dermaga ketika saya mulai. Mereka tidak pernah membenci kekuatan saya yang luar biasa! Tapi aku sudah terbiasa mengambil piring dan cangkir kopi yang rapuh.",
  str_voice_1401691_14 = "Tidak ada yang ingin menugaskan saya apa pun? Ssst! Di mana Anda mendengar omong kosong itu? Aku yakin itu hanya salah paham! Saya telah menerima banyak misi. Anda tahu, \"hancurkan produk kadaluarsa,\" \"kirim 30 peti bir sekaligus ke Spearows,\" hal semacam itu!",
  str_voice_1401691_15 = "Selamat ulang tahun! Super Sadie Swashbuckler 666 secara mental menyalurkan keberuntungan dan keberuntungan dengan cara Anda.",
  str_voice_1401691_16 = "Ssst! Tidak ada lagi salam. Pergilah ke sini dan kecilkan suaramu. Aku tidak ingin ada yang tahu kita bolos kelas.",
  str_voice_1401691_17 = "Selamat pagi! Mari kita semua menjadi dewasa dan bangun pagi-pagi sekali dan tidur larut malam.",
  str_voice_1401691_18 = "Ingatlah untuk makan dengan baik. Saya diberitahu sayuran membangun otot. Surga, tolong aku. Saya tidak tahan sayuran.",
  str_voice_1401691_19 = "Sang jagoan memiliki sesuatu untuk dikatakan tentang keseimbangan kehidupan kerja Anda: tidurlah lebih banyak! Ah, siapa yang aku bercanda? Saya membuat itu.",
  str_voice_1401691_20 = "Tempat yang sangat baik untuk swashbucklers seperti saya.",
  str_voice_1401691_21 = "Lumopolis? Tidak apa-apa, kurasa. Mereka tidak merilis cukup banyak komik swashbuckler baru di sana.",
  str_voice_1401691_22 = "Bayangan swashbuckler sedang mengawasi Anda!",
  str_voice_1401691_23 = "Andai saja ada banyak buku komik sebanyak Eclipsites. Kecuali, eh, buku komik itu bagus dan Eclipsites itu buruk.",
  str_voice_1401691_24 = "Allura adalah wanita yang luar biasa dan mengajari saya banyak hal tentang menjadi petualang muda yang berani. Aku benar-benar mengaguminya.",
  str_voice_1401691_25 = "Areia adalah orang yang memberi saya tongkat baseball Coolster, dan mengajari saya banyak hal tentang menjadi pahlawan yang gagah. Saya sangat menghormatinya.",
  str_voice_1401691_26 = "Hal favorit? Buku komik, fashion, aksesoris berkilauan, teman-teman lamaku... meskipun itu bukan \"sesuatu\" itu sendiri.",
  str_voice_1401691_27 = "Aku benci ketika orang memperlakukanku seperti aku bodoh—bahkan jika aku melakukan hal bodoh! Juga, warna pink, sayuran, dan hari hujan.",
  str_voice_1401691_28 = "Anda tahu apa yang membuat Colossus lebih keren? Jika saya bisa menggunakannya sebagai senjata swashbuckler atau sebagai alat transportasi swashbuckler khusus.",
  str_voice_1401691_29 = "Sampaikan salam untuk Super Sadie Swashbuckler 666, swashbuckler No. 1 masa depan di seluruh Umbraton! Mengapa masa depan? Saya akan memberitahumu nanti.",
  str_voice_1401691_30 = "Saya mendapatkan kendali atas kekuatan saya!",
  str_voice_1401691_31 = "Coolster tumbuh lebih cepat setiap hari!",
  str_voice_1401691_32 = "Apa aku lebih keren sekarang?",
  str_voice_1401691_33 = "Aku akan menjadi seorang swashbuckler nyata!",
  str_voice_1401691_34 = "Apakah saya benar-benar harus bekerja dengan orang lain? Baik.",
  str_voice_1401691_35 = "Coolster tidak bisa menunggu lagi!",
  str_voice_1401691_36 = "Sekarang? Maksudmu sekarang?",
  str_voice_1401691_37 = "Super Sadie Swashbuckler 666, siap menyerang!",
  str_voice_1401691_38 = "Biarkan gairah saya terbakar!",
  str_voice_1401691_39 = "Ayunan tingkat!",
  str_voice_1401691_40 = "Bukk!",
  str_voice_1401691_41 = "Saya akan sama baiknya dengan senior saya!",
  str_voice_1401691_42 = "Bisakah Anda memuji saya?",
  str_voice_1401691_43 = "Apakah ini yang terjadi jika Anda tidak belajar ...?",
  str_voice_1401691_44 = "Saya berada di atas seekor burung besar yang terbang jauh dan luas, dikemudikan oleh pemandu kecil yang ramah.",
  str_voice_1401691_45 = "Terima kasih.",
  str_voice_1401691_46 = "Tidak mungkin! Anda sebenarnya ...",
  str_voice_1401691_47 = "Terima kasih! Aku menyukainya! Saya sangat menyukainya!",
  str_voice_1401691_48 = "D-Apakah Anda ingin menjadi swashbucklers dengan saya?",
  str_voice_1401691_49 = "Orang tua saya bekerja di Lumopolis. Mereka sepertinya suka di sana. Saya tidak bisa memberi tahu Anda banyak tentang tempat itu karena saya tidak ingat banyak dari ketika saya tinggal di sana sebagai seorang anak kecil.",
  str_voice_1401691_50 = "Apa yang membuat saya pertama kali ingin menjadi seorang swashbuckler? Ceritanya dimulai dari masa lalu ketika saya pernah bolos kelas dan Nona Allura menarik saya ke samping untuk percakapan tajam tentang perilaku saya. Yup, swashbucklers tidak bisa berperilaku buruk, Anda tahu.",
  str_voice_1401691_51 = "Langkah pertama untuk menjadi seorang swashbuckler? Belajar bagaimana mengontrol kekuatan Anda dan membangun kepercayaan dengan rekan-rekan Anda. Itulah yang diajarkan Areia padaku. Dia sangat keren.",
  str_voice_1401691_52 = "Alchemy Stars.",
  str_voice_1401691_53 = "Hei.",
  str_voice_1401691_54 = "Apakah kamu sudah bangun? Aku mencoba menyelinap keluar dari sini.",
  str_voice_1401691_55 = "Siang hari bukanlah waktu terbaik untuk swashbuckling.",
  str_voice_1401691_56 = "Saya ingin membaca komik saya, tetapi saya juga sangat lelah ...",
  str_voice_1401691_57 = "Selamat Tahun Baru! Apakah menurut Anda saya memiliki peluang yang cukup bagus untuk menjadi seorang jagoan yang sukses tahun ini?",
  str_voice_1600254_10 = "Ada apa dengan kesunyian? Apakah Anda begitu terpesona oleh kemampuan akting saya sehingga Anda lupa untuk bertepuk tangan?",
  str_voice_1600254_11 = "Ingin saya melakukan drama hanya untuk Anda? Meredupkan. Uh, tunggu... tinggalkan dua lampu sorot—satu pada saya dan satu lagi, tentu saja, pada satu-satunya penonton saya.",
  str_voice_1600254_16 = "Yang baik dan yang jahat bisa sama-sama artistik. Mana yang lebih Anda sukai hari ini?",
  str_voice_1600254_17 = "Kostum, makeup, presentasi? Sempurna! Lampu? Kami tidak membutuhkan lampu ketika kami memiliki matahari pagi alami yang paling indah!",
  str_voice_1600254_18 = "Selamat sore temanku! Harap dicatat, juru kamera masih merekam.",
  str_voice_1600254_19 = "Ayo! Biarkan diri Anda jatuh ke dalam malam yang sunyi dan pekat ini, dan Anda pasti akan mendapatkan inspirasi yang Anda butuhkan.",
  str_voice_1600254_35 = "Kamera, siap.",
  str_voice_1600254_36 = "Lampu pada saya!",
  str_voice_1600254_37 = "Mari kita mengaum dan menghidupkan tempat ini!",
  str_voice_1600254_38 = "Inilah klimaksnya!",
  str_voice_1600254_39 = "Rentang akting yang sempurna adalah milikku untuk diperintahkan.",
  str_voice_1600254_40 = "Tidak, ini skrip Anda!",
  str_voice_1600254_44 = "Hmm? Anda pasti menginginkan salah satu poster saya yang ditandatangani, bukan?",
  str_voice_1600254_58 = "Saya hanya memakai pakaian malam yang cantik dan dirancang khusus ini untuk acara paling formal dan bergengsi ketika saya menjadi seorang aktor. Tentu saja, ada pengecualian, seperti sekarang.",
  str_voice_1600254_59 = "Manakah dari proyek saya yang akan kita tonton hari ini? Sebetulnya pilihannya sulit jadi...mari kita tonton semuanya!",
  str_voice_1600254_60 = "Banyak cerita yang ingin kau ceritakan... PlayerName, mari ubah kisah hidup Anda menjadi sandiwara! Kita bisa mengendarai Other End dan melakukannya di seluruh dunia!",
  str_voice_1600254_61 = "\"Satu-satunya hal yang lebih buruk daripada dibicarakan adalah tidak dibicarakan...\" Apa artinya bertahan hidup bagi seorang seniman kecuali untuk menghindari penghinaan yang mengerikan dari ketidakpedulian populer?",
  str_voice_1600254_62 = "Seorang seniman berbakat dapat membuat sesuatu yang luar biasa dari naskah yang paling biasa. Tidak percaya padaku? Baiklah, saya akan tunjukkan.",
  str_voice_1600254_63 = "PlayerName, pemirsa yang mengerti saya tidak seperti yang lain, senang Anda ada di sini! Sekarang mari kita ulas filmografi jenius seni pertunjukan, Charon the Acheron Ferryman!",
  str_voice_1600254_64 = "Selamat pagi, teman dan pendukung tersayang saya!",
  str_voice_1600254_65 = "Tidur di pagi yang mengantuk selalu membawa mimpi yang paling aneh.",
  str_voice_1600254_66 = "Pagi hari sama indahnya dengan hari yang penuh dengan pekerjaan seperti pada hari yang penuh dengan istirahat!",
  str_voice_1600254_67 = "Babak 1, Adegan 1!",
  str_voice_1600254_68 = "Selamat malam, teman.",
  str_voice_1600254_69 = "Saya sangat suka menonton ulang film saya di malam hari.",
  str_voice_1600254_70 = "Mengapa inspirasi begitu menghindari saya...?",
  str_voice_1600254_71 = "\"Selamat malam, anak mudaku sayang.\"",
  str_voice_1600254_72 = "Hai! Anda seharusnya tidak menjadi orang yang mengucapkan selamat malam kepada saya!",
  str_voice_1600254_73 = "Sudut kamera saya yang paling bagus? Semua 360 derajat.",
  str_voice_1600254_74 = "Lihat apa yang kita miliki di sini. Aku yang sempurna, dan kamu yang hampir sempurna.",
  str_voice_1600254_75 = "Ada yang namanya terlalu karismatik, mungkin.",
  str_voice_1600254_76 = "Saya ingin, jika mungkin, tidak menutup tirai keterlibatan saya dalam hidup Anda.",
  str_voice_1600254_77 = "Dunia yang luar biasa tidak membutuhkan pengertian dari mereka yang biasa-biasa saja.",
  str_voice_1601751_1 = "Saya melihat Anda sedang menatap, PlayerName. Mereka tidak terluka. Perban dan prostetik ini adalah peralatan yang diperlukan untuk cyborg tempur dan bukan akibat terluka dalam pertempuran.",
  str_voice_1601751_2 = "Sensasi pop rock berderak di mulut saya cukup menggembirakan. Saya kira inilah yang Anda maksud ketika Anda berbicara tentang \"perasaan,\" PlayerName.",
  str_voice_1601751_3 = "Satu-satunya musuh yang tidak pernah bisa saya kalahkan adalah rasa kantuk yang luar biasa ini... Tapi seperti yang selalu dikatakan Yingel, \"Berjuang keras, istirahat keras.\" Menguap...",
  str_voice_1601751_4 = "Sendi kaki saya mungkin berderit seolah-olah membutuhkan minyak, tetapi begitu saya memasukkannya dengan Luminatics, saya dapat melompat melintasi jarak yang sangat jauh seolah-olah itu adalah pegas yang kuat.",
  str_voice_1601751_5 = "Kubus sama pentingnya bagi saya seperti kunang-kunang bagi Anda, PlayerName. Apakah kamu mengerti?",
  str_voice_1601751_6 = "Yang memiliki roda gigi jam di punggungnya adalah \"01\", yang bersayap adalah \"10\", dan yang memiliki lingkaran cahaya di kepalanya adalah \"11\". Sebenarnya cukup mudah untuk membedakan Cubes, bukan begitu?",
  str_voice_1601751_7 = "Saya mengerti bahwa pelatihan terkadang kejam, karena diskualifikasi dan bahkan kematian adalah hasil kekalahan yang tak terhindarkan. Tetapi hal-hal ini tidak akan pernah terjadi selama saya berada di medan perang.",
  str_voice_1601751_8 = "Halo, PlayerName... Tampaknya Anda tidak mendengar saya. Kalau begitu... BISAKAH ANDA MENDENGAR SAYA SEKARANG?",
  str_voice_1601751_9 = "Bisakah Anda membantu saya melihat sesuatu? Tampaknya perban saya tersangkut di persendian kaki saya...",
  str_voice_1601751_10 = "Fiuh... aku mengerti. Tugas saya sekarang adalah mendapatkan kembali kekuatan saya.",
  str_voice_1601751_11 = "Silakan menikmati mengerjakan tugas Anda saat ini, PlayerName. Anda dapat menyerahkan hal-hal mendesak seperti pelatihan khusus dan tugas shift kepada saya.",
  str_voice_1601751_12 = "Saya mendeteksi bahwa Anda sedang istirahat. Silakan bergabung dengan saya di simulator untuk pelatihan sehingga kami dapat merasakan sensasi pertempuran.",
  str_voice_1601751_13 = "Anda mengatakan ingin mengajari Cubes saya cara memainkan musik? Tapi saya tidak percaya kita bisa menemukan peralatan yang tepat untuk melakukannya di Illumina... Maaf? Anda ingin menggunakan panel kontrol pada Colossus untuk mengajar mereka? Saya mengerti.",
  str_voice_1601751_14 = "Saya mudah lelah, tetapi istirahat singkat di ruang stasis saya adalah semua yang saya butuhkan untuk mendapatkan kembali kekuatan saya. Tolong beri saya sedikit waktu lagi.",
  str_voice_1601751_15 = "Selamat ulang tahun, PlayerName.",
  str_voice_1601751_16 = "Syukurlah kau masih hidup dan sehat... Hmm? Apakah sesuatu yang saya katakan mengganggu Anda?",
  str_voice_1601751_17 = "Aroma hujan menggantung di udara, dan tujuh kunang-kunang terbang begitu saja... Maksudku, selamat pagi.",
  str_voice_1601751_18 = "Pernahkah Anda memperhatikan sesuatu yang unik tentang kulit saya? Saat matahari terbenam, seluruh tubuhku mulai bersinar dengan cahaya redup.",
  str_voice_1601751_19 = "Tidak bisa tidur? Anda dipersilakan untuk mencoba tidur di ruang stasis saya... Tapi saya rasa kami berdua tidak akan muat di dalam.",
  str_voice_1601751_20 = "Saya adalah anak dari seluruh Illumina. Untuk melayani Illumina adalah tujuan saya.",
  str_voice_1601751_21 = "Sebuah kota mengambang di langit? Kedengarannya agak berbeda dari yang dijelaskan oleh terminal Sean. Anda harus membawa saya ke sana agar saya dapat memverifikasinya.",
  str_voice_1601751_22 = "Jayalah Illumina.",
  str_voice_1601751_23 = "Memerangi Eclipsites hanyalah proses rutin, karena hasilnya selalu sama.",
  str_voice_1601751_24 = "Kepribadian Yingel tidak berbeda dengan ayah saya, tetapi saya tahu bahwa Yingel mampu merasakan banyak emosi.",
  str_voice_1601751_25 = "Sean berbeda dariku. Mungkin ditempatkan di zona perang akan mengeluarkan kekuatan penuhnya?",
  str_voice_1601751_26 = "Tolong beri saya lebih banyak batu pop sebagai hadiah saya untuk mencapai kemenangan.",
  str_voice_1601751_27 = "Maaf, lebih sulit bagiku untuk mengangkat semangatku saat hujan. Kakiku terasa jauh lebih berat.",
  str_voice_1601751_28 = "Anda menghabiskan tujuh belas tahun tidur di sini? Begitu... Jadi Colossus sebenarnya hanyalah ruang stasis yang sangat besar.",
  str_voice_1601751_29 = "Memerangi Cyborg Axelia, melapor untuk bertugas. Jika bertarung adalah pilihan terakhirmu, izinkan aku menjadi senjatamu yang paling ampuh.",
  str_voice_1601751_30 = "Saya benar-benar mengerti sekarang.",
  str_voice_1601751_31 = "Pelatihan sederhana, tidak lebih.",
  str_voice_1601751_32 = "Dengan latihan datanglah kekuatan.",
  str_voice_1601751_33 = "Silakan menguji kekuatan saya dalam pertempuran nyata.",
  str_voice_1601751_34 = "Siap, laksanakan.",
  str_voice_1601751_35 = "Axelia, siaga.",
  str_voice_1601751_36 = "Tiga dua satu...",
  str_voice_1601751_37 = "Maaf atas keterlambatannya.",
  str_voice_1601751_38 = "Serahkan padaku.",
  str_voice_1601751_39 = "Aku akan melindungi siapa pun.",
  str_voice_1601751_40 = "Ini belum selesai.",
  str_voice_1601751_41 = "Sama seperti dalam pelatihan.",
  str_voice_1601751_42 = "Kemenangan adalah satu-satunya hasil yang mungkin.",
  str_voice_1601751_43 = "*Batuk* Pengalaman yang belum pernah terjadi sebelumnya...",
  str_voice_1601751_44 = "Mulai tugas jaga... Tidak ada bahaya yang terdeteksi di area tersebut.",
  str_voice_1601751_45 = "Tolong letakkan di sana.",
  str_voice_1601751_46 = "Apakah ini cara menjalin hubungan baik?",
  str_voice_1601751_47 = "Singkirkan ini baik-baik, Cubes.",
  str_voice_1601751_48 = "Aku akan mengurus ini dengan baik.",
  str_voice_1601751_49 = "Itu adalah Program Fosfer yang memberi saya pemahaman saya tentang dunia. Adapun \"orang tua asli\" saya ... Maaf, tapi saya tidak punya file memori di dalamnya.",
  str_voice_1601751_50 = "Ketika kulit saya terkoyak, saya mengalami kematian dalam wujud aslinya. Menurut pendapat saya, orang yang memberi saya hidup adalah orang tua saya, terlepas dari berapa kali saya dilahirkan kembali.",
  str_voice_1601751_51 = "Kubus diberikan kepadaku oleh Algol sebagai hadiah. Mereka tidak hanya membantu saya dalam kehidupan sehari-hari, mereka juga membantu saya dalam pertempuran.",
  str_voice_1601751_52 = "Alchemy Stars.",
  str_voice_1601751_53 = "Menguap...",
  str_voice_1601751_54 = "Selamat pagi.",
  str_voice_1601751_55 = "Selamat sore.",
  str_voice_1601751_56 = "Tidur nyenyak.",
  str_voice_1601751_57 = "Menguap... Selamat Tahun Baru.",
  str_voice_1501761_1 = "Andai saja saya bisa seperti Pak John dan memimpin tim medis ahli yang membantu orang-orang di seluruh Astra. Masih banyak orang yang menderita di dunia yang membutuhkan perawatan!",
  str_voice_1501761_2 = "Menyisir rambut Lady Raphael selalu menyita banyak waktu... Jangan menatapku seperti itu! Saya tidak pernah mengatakan saya tidak menikmatinya!",
  str_voice_1501761_3 = "Bahkan jika peluang pasien untuk bertahan hidup tipis, saya menolak untuk menyerah pada mereka! Sama seperti para dokter yang menolak untuk menyerah pada saya.",
  str_voice_1501761_4 = "Saya ingin menyelamatkan semua pasien saya dari rasa sakit penyakit mereka. Tapi untuk mewujudkan tujuan itu, saya harus tetap bekerja sekeras mungkin.",
  str_voice_1501761_5 = "Pelatihan Fisik dan Luminatik penting untuk kesehatan, tetapi Anda tidak boleh mengabaikan pelatihan pikiran Anda.",
  str_voice_1501761_6 = "Saya telah bekerja sangat keras selama ini untuk mengantisipasi kesempatan seperti ini, untuk mewujudkan potensi penuh saya! Terima kasih telah mempercayai saya; Aku tidak akan mengecewakanmu!",
  str_voice_1501761_7 = "Sekarang kita berteman, saya juga memiliki tanggung jawab untuk memastikan bahwa Anda selalu dalam keadaan sehat! Jika Anda pernah merasa kurang sehat, jangan ragu untuk memberi tahu saya, oke?",
  str_voice_1501761_8 = "\"Seimbangkan kerja dan istirahat,\" katamu? Sigh... Meskipun saya terus-menerus mengatakan hal yang sama kepada orang lain, terkadang saya kesulitan mengikuti saran saya sendiri. Terima kasih atas pengingatnya. Saya akan mencoba meluangkan lebih banyak waktu untuk istirahat.",
  str_voice_1501761_9 = "Jadi saya mendapat banyak istirahat, seperti yang Anda sarankan ... dan sekarang efisiensi kerja saya sangat tinggi! Ini bekerja jauh lebih baik daripada begadang, jadi terima kasih atas tipnya!",
  str_voice_1501761_10 = "Pergi untuk beristirahat? Bagus, kalau begitu aku akan mempelajari beberapa buku kedokteranku. Waktu saya sangat berharga bagi saya, jadi saya harus menghitung setiap detik!",
  str_voice_1501761_11 = "Apakah seseorang membutuhkan perhatian medis di sini ?! Apa itu? Anda hanya perlu saya berdiri di sini? Saya kira... Tapi bagaimana ini bisa meningkatkan keterampilan saya sebagai dokter?",
  str_voice_1501761_12 = "Pastikan untuk menghadiri pemeriksaan medis rutin! Semakin cepat Anda menemukan masalah kesehatan, semakin mudah untuk diobati!",
  str_voice_1501761_13 = "Apa yang membuat Lady Raphael percaya dia bisa memperbaiki Fireflies yang rusak itu dengan Holy Water Shell-nya...? Maaf, saya akan segera membersihkannya.",
  str_voice_1501761_14 = "Pertarungan kita selanjutnya akan berjalan lebih mulus, karena aku selalu meningkatkan diri!",
  str_voice_1501761_15 = "Selamat ulang tahun! Harap terima paket persediaan medis ini; Anda tidak pernah tahu kapan Anda harus memberikan pertolongan pertama!",
  str_voice_1501761_16 = "Selalu waspadai kondisi kesehatan tubuh Anda. Lagi pula, itu satu-satunya yang Anda punya!",
  str_voice_1501761_17 = "Selamat pagi! Jika Anda memiliki misi yang harus dilakukan hari ini, tolong bawa saya. Saya tahu saya bisa sangat berguna bagi tim!",
  str_voice_1501761_18 = "Selamat malam! Anda sibuk sepanjang hari juga, ya? Hidung saya terkubur dalam teks medis saya sejak pagi!",
  str_voice_1501761_19 = "Sudah larut. Anda harus segera beristirahat. Saya? Aku tidak lelah sama sekali! Lagipula, masih ada waktu untukku berlatih Luminatics!",
  str_voice_1501761_20 = "Lumopolis adalah kampung halaman saya, sekaligus sumber dari semua keahlian medis saya. Itu adalah tempat yang selalu mendukung saya dan tujuan saya.",
  str_voice_1501761_21 = "Orang-orang di Umbraton adalah sesuatu yang lain. Setiap kali saya pergi ke sana, jalanan dipenuhi dengan memar dan berdarah berkat semua pertempuran!",
  str_voice_1501761_22 = "Demi White Night!",
  str_voice_1501761_23 = "Cara terbaik untuk merawat Eclipsites... adalah tanpa ampun!",
  str_voice_1501761_24 = "Lady Raphael kadang-kadang terlihat agak sembrono, tetapi saya yakinkan Anda bahwa dia adalah dokter yang hebat!",
  str_voice_1501761_25 = "Lady Carleen pasti telah melalui banyak hal untuk menjadi sekuat dia sekarang. Dia petarung sejati, bukan?",
  str_voice_1501761_26 = "Memberi makan burung, menyiram tanaman, membersihkan kamar... Ini hanya beberapa hobi yang disarankan Lady Raphael untuk saya lakukan!",
  str_voice_1501761_27 = "Saya tidak tahan dengan kehidupan yang membosankan dan berpuas diri. Itu melemahkan ambisi seseorang dan merampas motivasi mereka untuk memperbaiki diri.",
  str_voice_1501761_28 = "Colossus tampaknya adalah makhluk hidup... Artinya bisa sakit atau terluka, sama seperti kita semua. Ketika itu terjadi, bagaimana cara mengobatinya?",
  str_voice_1501761_29 = "Saya Beretta, petugas medis lapangan, dan saya diperintahkan untuk memberikan dukungan. Apakah Anda bertanggung jawab atas Colossus ini? Apakah ada yang terluka? Bawa saya ke mereka, dan saya akan segera mentraktir mereka!",
  str_voice_1501761_30 = "Setiap kemajuan adalah berita yang luar biasa!",
  str_voice_1501761_31 = "Hebat, saatnya bekerja lebih keras lagi!",
  str_voice_1501761_32 = "Serahkan saja semuanya padaku!",
  str_voice_1501761_33 = "Saya pasti akan membalas kepercayaan Anda pada saya.",
  str_voice_1501761_34 = "Akan kucoba semampuku!",
  str_voice_1501761_35 = "Persiapan selesai!",
  str_voice_1501761_36 = "Peralatan medis sudah disterilkan dan siap digunakan!",
  str_voice_1501761_37 = "Bersinar, Borealis Plume!",
  str_voice_1501761_38 = "Semua kerja keras saya adalah untuk saat ini!",
  str_voice_1501761_39 = "Ini hanya tusukan kecil, jangan bergerak!",
  str_voice_1501761_40 = "Ini adalah bagian penting dari perawatan Anda!",
  str_voice_1501761_41 = "Baiklah, serahkan padaku!",
  str_voice_1501761_42 = "Ya! Kemenangan!",
  str_voice_1501761_43 = "Saya tidak takut gagal atau apapun... tapi tetap saja sakit.",
  str_voice_1501761_44 = "Saya harap keterampilan tempur dan keahlian medis saya dapat terus meningkat seperti ini setiap hari!",
  str_voice_1501761_45 = "Dapatkah saya menggunakan ini untuk meningkatkan keterampilan medis saya...?",
  str_voice_1501761_46 = "Aku menyukainya! Terima kasih banyak!",
  str_voice_1501761_47 = "Ini pasti dimanfaatkan dengan baik!",
  str_voice_1501761_48 = "Anda benar-benar tahu apa yang saya suka, Navigator! Terima kasih banyak!",
  str_voice_1501761_49 = "Sebagai petugas medis lapangan, tugas saya tidak hanya untuk mendukung sekutu saya, tetapi juga untuk mengurangi risiko terkait pertempuran lainnya sebanyak mungkin. Untuk melakukan tugasku sebaik mungkin, aku harus bekerja tanpa henti dan terus meningkatkan diri!",
  str_voice_1501761_50 = "Dulu saya sakit parah, tetapi tim medis yang dipimpin oleh Pak John menyelamatkan hidup saya. Bekas luka berbentuk salib di dahi saya bukan hanya suvenir dari operasi itu; itu bukti keahlian dan kebaikan para dokter yang menyelamatkan saya.",
  str_voice_1501761_51 = "Meskipun saya sering dikirim ke tempat mana pun yang membutuhkan bantuan saya, saya secara sukarela memilih untuk menjaga Lady Raphael. Dia dokter yang sangat berbakat, dan saya tahu saya bisa belajar banyak hanya dengan berada di sisinya.",
  str_voice_1501761_52 = "Alchemy Stars.",
  str_voice_1501761_53 = "Hei!",
  str_voice_1501761_54 = "Hari baru harus selalu dimulai dengan senam pagi!",
  str_voice_1501761_55 = "Selamat sore! Apakah Anda makan siang yang enak dan sehat?",
  str_voice_1501761_56 = "Masih terjaga, ya?",
  str_voice_1501761_57 = "Selamat Tahun Baru! Saya mengambil cuti setengah hari untuk menelepon di tahun baru! Mengapa hanya setengah hari? Jadi saya bisa menggunakan separuh lainnya untuk mengejar semua pelatihan saya untuk hari itu, tentu saja!",
  str_voice_1601771_1 = "Hm, apakah kamu menatapku? Hah, izinkan saya untuk menunjukkan kepada Anda seperti apa idola yang sebenarnya! *batuk* Tunggu sebentar, saya perlu minum sedikit obat batuk dulu untuk melindungi tenggorokan saya.",
  str_voice_1601771_2 = "Tebak berapa lama waktu yang saya butuhkan untuk tampil sehebat ini setiap hari. Setengah jam? Apakah kamu sedang bercanda!? Setengah jam hampir tidak cukup bagiku untuk menata rambutku!",
  str_voice_1601771_3 = "Kami benar-benar memiliki selera gaya yang sama! Saya rasa mikrofon khusus saya juga sangat unik! Ingin mencobanya? Oh, tapi ini emas murni... Bisakah kau mengangkatnya?",
  str_voice_1601771_4 = "Ah-ah-ah! Oooh, ooh! Sangat menarik. Saya pikir jangkauan vokal saya meningkat dengan bantuan Anda, PlayerName!",
  str_voice_1601771_5 = "Langkah kakiku terasa lebih ringan, seperti menyatu dengan musik. Sungguh sensasi yang indah dan harmonis! PlayerName, maukah kamu berdansa denganku?",
  str_voice_1601771_6 = "Perasaan ini... Ya! Terima kasih, PlayerName! Pertunjukan malam saya akan jauh lebih lancar sekarang!",
  str_voice_1601771_7 = "Izinkan saya memberi tahu Anda sebuah rahasia! Jika seseorang menodongkan pistol ke arah Anda, selama Anda menghitung dalam hati dalam hati dan melewatkan tujuh angka, peluru tidak akan pernah mengenai Anda! Itu benar!",
  str_voice_1601771_8 = "Ada pita di tumit sepatuku, pita menghiasi bagian depan pakaianku, dan pita di ujung rokku... Aku... Aku sangat suka pita! Apakah kamu juga menyukai mereka, PlayerName?",
  str_voice_1601771_9 = "Jika Anda ingin... Oh, tidak! Maksud saya... jika Anda bebas, Anda dapat melihat bagian atas rambut saya. Itu bentuk hati!",
  str_voice_1601771_10 = "Begitu... Jadi, seperti inilah rasanya kesepian. Saya jarang menemukan diri saya dalam keadaan seperti itu. Tapi menarik untuk mengalami keheningan yang luar biasa secara langsung sesekali.",
  str_voice_1601771_11 = "Bahkan jika aku berdiri di sini sendirian... Bahkan jika aku berdiri di sini sendirian, aku akan tetap berteriak ke semua orang di hadapanku—Aku menyukai dunia ini! Saya suka semua orang! Aku... aku menyukai diriku sendiri, karena aku bisa membawa kebahagiaan dan kegembiraan bagi semua orang!",
  str_voice_1601771_12 = "Apakah Anda memperhatikan peluru di rambut saya? Tentu, desainnya cantik di luar sana, tetapi sangat membantu saya. Setiap kali saya membuangnya, jatuh ke tanah menghadap ke arah yang benar. Saya pikir itu memberi tahu saya bahwa kita juga harus menghadapi hidup secara positif setiap hari.",
  str_voice_1601771_13 = "Sungguh luar biasa berada di atas panggung dengan begitu banyak orang menonton saya! Mereka memberi saya begitu banyak keberanian dan kekuatan, seperti... seperti teman kecil saya yang spesial!",
  str_voice_1601771_14 = "Marshmallow! Oh Marshmallow! Hah? Tidak, saya tidak ingin makan marshmallow! Marshmallow adalah nama anjing putih kecil di sampingku ini! Hehe, persis seperti anjing dari iklan yang saya sukai ketika saya masih kecil!",
  str_voice_1601771_15 = "Saya harap Anda memiliki hari ulang tahun yang bahagia ... tetapi saya juga berharap Anda bahagia setiap hari!",
  str_voice_1601771_16 = "Hai hai! Maukah Anda datang ke pertunjukan saya malam ini? Ya! Anggap ini undangan resmi!",
  str_voice_1601771_17 = "Selamat pagi! Saya sudah memulai pelatihan suara saya untuk hari ini! Saya harap saya bisa menyebarkan keceriaan kepada semua orang dengan lagu yang indah!",
  str_voice_1601771_18 = "Aku sedikit lelah sekarang... tapi semua orang berteriak \"encore,\" jadi... aku bisa lanjut!",
  str_voice_1601771_19 = "Izinkan saya memberi tahu Anda sebuah rahasia... Alasan saya selalu keluar di malam hari adalah karena saya... Saya ingin menjadi pahlawan yang dapat dikagumi oleh anak-anak!",
  str_voice_1601771_20 = "Sebagian besar acara saya diadakan di Umbraton, jadi terkadang saya suka pergi ke tempat lain agar lebih banyak orang mendengar penampilan saya secara langsung.",
  str_voice_1601771_21 = "Lumopolis? Musisi di sana dan idola seperti dua spesies berbeda! Sama sekali!",
  str_voice_1601771_22 = "Lagu dan warna yang mempesona mengawasi Anda!",
  str_voice_1601771_23 = "Siapa pun yang tidak menghargai keindahan dan hanya tahu cara menghancurkan sesuatu akan meminta saya untuk menjawabnya!",
  str_voice_1601771_24 = "Brandy adalah gadis yang sangat berdedikasi dan profesional!",
  str_voice_1601771_25 = "Lady Sheol benar-benar pintar! Saya selalu merasa bisa belajar banyak hal berbeda dari cara dia berpikir tentang berbagai hal.",
  str_voice_1601771_26 = "Hah? Lencana saya? Heheh, itu semua penghargaan yang saya menangkan.",
  str_voice_1601771_27 = "Saatnya menimbang diri setelah makan pare selama seminggu penuh... Ah! Berat badan saya tidak berubah sedikit pun!",
  str_voice_1601771_28 = "Hmm, aku tahu. Soroz seperti Marshmallow Anda, bukan?",
  str_voice_1601771_29 = "Hai! Saya Goldie! kamu PlayerName, Baik? Saya senang bertemu dengan Anda di dunia yang berkilauan, cantik, dan lembut ini!",
  str_voice_1601771_30 = "Wow! Luar biasa!",
  str_voice_1601771_31 = "Aku merasa seperti aku akan terbang!",
  str_voice_1601771_32 = "La-la-la!",
  str_voice_1601771_33 = "Sekarang aku bahkan lebih hebat!",
  str_voice_1601771_34 = "Aku mengerti!",
  str_voice_1601771_35 = "Persiapan selesai!",
  str_voice_1601771_36 = "Baik untuk pergi!",
  str_voice_1601771_37 = "Suaraku penuh energi!",
  str_voice_1601771_38 = "Catatan tertinggi!",
  str_voice_1601771_39 = "Mekar!",
  str_voice_1601771_40 = "Bersinar!",
  str_voice_1601771_41 = "Berikan semuanya!",
  str_voice_1601771_42 = "Aku sangat bahagia!",
  str_voice_1601771_43 = "Jangan... Jangan berkecil hati!",
  str_voice_1601771_44 = "Di mana pun saya berada, saya dapat menciptakan mimpi baru!",
  str_voice_1601771_45 = "Apa... Aku sangat senang!",
  str_voice_1601771_46 = "Aku akan membayarmu dengan penampilan spesial!",
  str_voice_1601771_47 = "Perasaan syukur ini... Luar biasa!",
  str_voice_1601771_48 = "Hadiah darimu... Aku akan menghargainya sepanjang hidupku!",
  str_voice_1601771_49 = "Saya lahir di keluarga yang sangat biasa. Ketika saya masih muda, saya pikir semua bintang yang saya lihat di TV ada di dunia lain... dan anjing marshmallow di iklan itu juga.",
  str_voice_1601771_50 = "Hari itu aku disandera? Itu tidak semuanya buruk... Aku menjadi sedikit sesak setelah itu, tapi aku juga memperoleh kemampuan yang luar biasa.",
  str_voice_1601771_51 = "Heehee! Apakah Anda suka melihat saya di atas panggung? Terima kasih banyak! Saya menyukai orang yang berada di atas panggung, tetapi saya juga menyukai orang yang berada di luar panggung.",
  str_voice_1601771_52 = "Alchemy Stars!",
  str_voice_1601771_53 = "Hai!",
  str_voice_1601771_54 = "Selamat pagi! Apa yang kamu lakukan?",
  str_voice_1601771_55 = "Selamat sore! Ingatlah untuk tetap terhidrasi!",
  str_voice_1601771_56 = "Jika Anda ingin menjaga suara Anda dalam kondisi prima, ingatlah untuk tidur lebih awal!",
  str_voice_1601771_57 = "Selamat Tahun Baru! Saya seharusnya bisa belajar lebih banyak langkah menari tahun ini, bukan?",
  str_voice_1601781_1 = "*Menguap* Dimana Fia? Di mana murid kecilku yang lucu? Saya butuh pijat bahu! Saya kira tidur tengkurap tidak baik untuk leher dan bahu saya... Ow, ow, ow...",
  str_voice_1601781_2 = "Maaf tentang itu, PlayerName. Hewan yang luar biasa sering ditumpahkan, saya harap Anda tidak alergi atau apa pun. Aku akan meminta Fia untuk membersihkannya. Apa? Anda akan melakukannya? Anda baik sekali! Anda bisa mulai dengan menyekop kotoran dari pasir...",
  str_voice_1601781_3 = "Tidak sopan menanyakan usia siapa pun, jadi yang perlu Anda ingat adalah bahwa saya selalu delapan belas tahun. Tapi Anda bisa bertanya kepada saya tentang hal-hal lain, seperti sekresi binatang ajaib mana yang terbaik untuk kulit Anda.",
  str_voice_1601781_4 = "Saya secara khusus membuat mainan ini dari bulu Lutumi Owl yang jatuh sesuai dengan selera binatang yang menakjubkan. Bola Bulu Kecil menyukainya! Beraninya Fia menyebutku pelit karena hemat?",
  str_voice_1601781_5 = "Saya mengerti bahwa orang memiliki ide dan sikap yang berbeda terhadap binatang yang menakjubkan, tetapi saya berharap buku saya dapat membuat lebih banyak orang jatuh cinta pada makhluk kecil ini dan memahami cara mereka.",
  str_voice_1601781_6 = "Perjalanan saya belum berakhir. Saya yakin ada binatang menakjubkan yang belum saya lihat. Saya ingin menyaksikan mereka dengan mata kepala sendiri.",
  str_voice_1601781_7 = "Saya dapat melihat bahwa Anda juga tertarik pada binatang yang menakjubkan. Nah, mengapa Anda tidak menjadi murid saya? Saya akan memiliki servis lain ... Maksud saya, siswa.",
  str_voice_1601781_8 = "Jika Anda juga menyukai binatang yang menakjubkan, apakah Anda ingin melakukan perjalanan melalui Astra dengan saya lain kali? Saya akan menghargai Anda sebagai asisten dalam buku saya. Jangan khawatir, ini bukan seolah-olah saya mengharapkan tenaga kerja gratis atau transportasi atau semacamnya...",
  str_voice_1601781_9 = "Salah satu kerabat Anda, seorang gadis, pernah membantu saya belajar berkomunikasi dengan binatang buas yang menakjubkan. Kadang-kadang Anda mengingatkan saya padanya ... Saya ingin tahu apakah Anda berdua berhubungan?",
  str_voice_1601781_10 = "Ngantuk? Ayo berbaring bersamaku di Little Furball. Tidak masalah.",
  str_voice_1601781_11 = "Saya hanya harus duduk di sini dan berjaga-jaga, bukan? Sementara itu, saya akan menyikat anak-anak kecil ini.",
  str_voice_1601781_12 = "Ah-choo! Saya sering bersin akhir-akhir ini. Mungkin beberapa wanita muda di luar sana merindukanku?",
  str_voice_1601781_13 = "Dengan wajah sepertiku, idola akan kehilangan pekerjaan jika aku bisa menyanyi, menari, atau berakting! Mereka harus berterima kasih kepada saya karena telah menjadi seorang pertapa.",
  str_voice_1601781_14 = "Kekuatan karakter? Itu sesuatu untuk Anda anak muda renungkan. Bagi orang tua seperti saya, menghadapi kenyataan adalah cara kita bertahan hidup.",
  str_voice_1601781_15 = "Anda tidak suka hadiah saya? Itu adalah gigi bayi dari Kelinci Peko! Ini sangat langka!",
  str_voice_1601781_16 = "Hei kamu, apakah kamu sudah melihat naskahku? Semoga tidak ada anak kecil yang memakannya...",
  str_voice_1601781_17 = "Anda bangun lebih awal. Pasti menyenangkan menjadi begitu muda dan penuh vitalitas.",
  str_voice_1601781_18 = "Aku lapar... Apa kamu melihat Fia? Mengapa magang saya belum datang dengan makanan saya?",
  str_voice_1601781_19 = "Ayo, izinkan saya membawa Anda keluar dan menunjukkan kepada Anda beberapa binatang malam yang menakjubkan di dunia.",
  str_voice_1601781_20 = "Ahli ekstrozoologi adalah kelompok yang aneh, tetapi kita semua mencintai binatang.",
  str_voice_1601781_21 = "Penguasa yang cerdas tahu betapa pentingnya lingkungan dan ekologi bagi pembangunan.",
  str_voice_1601781_22 = "Tugas saya adalah menemukan binatang buas yang menakjubkan dan mempelajari rahasia mereka.",
  str_voice_1601781_23 = "Eclipsite jelek dan membosankan, jadi saya tidak tertarik.",
  str_voice_1601781_24 = "Aku sedih disalahpahami oleh murid favoritku, yang menyebutku pembohong setiap hari... *Hiks*",
  str_voice_1601781_25 = "Shira adalah anak yang kuat. Dia akan mengambil mantel untuk melindungi binatang yang menakjubkan!",
  str_voice_1601781_26 = "Alkohol menginspirasi sastra dan seni. Beberapa minuman selalu membantu membuat jus kreatif mengalir!",
  str_voice_1601781_27 = "Ahhhh! Siapa yang memindahkan buku-bukuku?! Mereka rusak!",
  str_voice_1601781_28 = "Bisakah saya meminjam rumah kaca? Beberapa binatang menakjubkan membutuhkan lingkungan yang lebih hangat untuk bertahan hidup.",
  str_voice_1601781_29 = "Memahami binatang yang menakjubkan adalah salah satu dari banyak cara untuk belajar tentang dunia ini. Ingin melihat pemandangan luar biasa dari makhluk yang belum pernah Anda lihat sebelumnya?",
  str_voice_1601781_30 = "Saya pikir makhluk kecil ini telah menyukai Anda.",
  str_voice_1601781_31 = "Jangan melibatkanku dalam hal yang rumit!",
  str_voice_1601781_32 = "Nikmat sulit untuk dikembalikan.",
  str_voice_1601781_33 = "Pikiran kita harus menjadi satu untuk mewujudkan potensi kita.",
  str_voice_1601781_34 = "Aku tak bisa berbuat banyak.",
  str_voice_1601781_35 = "Giliranmu.",
  str_voice_1601781_36 = "Bola Bulu Kecil, selamatkan aku!",
  str_voice_1601781_37 = "Bola Bulu Kecil, serangan cakar!",
  str_voice_1601781_38 = "* Menguap * Kalian punya ini.",
  str_voice_1601781_39 = "Saya lelah.",
  str_voice_1601781_40 = "Mengapa ini belum berakhir?",
  str_voice_1601781_41 = "Kasihanilah.",
  str_voice_1601781_42 = "Aku baik seperti dulu...",
  str_voice_1601781_43 = "Saya menyerah!",
  str_voice_1601781_44 = "Apakah Anda membutuhkan Burung Hantu Lutumi untuk membuat Anda tertidur? Jika Anda menderita insomnia kronis, layanan hipnosis tidur yang diperpanjang juga tersedia.",
  str_voice_1601781_45 = "Datanglah lain kali!",
  str_voice_1601781_46 = "Anda orang muda yang baik hati.",
  str_voice_1601781_47 = "Saya akan dengan senang hati menerimanya.",
  str_voice_1601781_48 = "* Hiks * Aku sangat terharu aku bisa mulai menangis detik ini.",
  str_voice_1601781_49 = "Saya menjadi binatang yang luar biasa ketika saya masih muda, tetapi karena bisnis keluarga saya, saya telah melakukan hal-hal di masa lalu yang merugikan mereka. Bekas luka saya dan satu sayap yang tersisa adalah harga yang saya bayar untuk pelanggaran itu.",
  str_voice_1601781_50 = "Binatang buas yang menakjubkan adalah makhluk yang sederhana dan tidak bersalah tanpa tipu daya yang rentan terhadap Aurorian. Saya menyelamatkan Little Furball, dan ia memutuskan untuk bepergian bersama saya saat saya menjelajahi Astra, melindungi saya di sepanjang jalan. Tidak seperti dua murid yang meneriakiku dan menggertakku sepanjang hari... huh.",
  str_voice_1601781_51 = "Bukannya aku tidak mempercayaimu. Hanya saja saya bahkan tidak tahu banyak tentang garis keturunan saya. Saya hanya membaca tentang Ouroboros di buku-buku kuno, dan saya masih mencoba mencari tahu bagaimana saya terhubung dengannya. Jika Anda sangat tertarik dengan saya, mau membantu saya mencari petunjuk?",
  str_voice_1601781_52 = "Alchemy Stars.",
  str_voice_1601781_53 = "Hei!",
  str_voice_1601781_54 = "Anda bangun pagi.",
  str_voice_1601781_55 = "Ingin tidur siang bersama?",
  str_voice_1601781_56 = "Tidur lebih awal adalah kunci awet muda.",
  str_voice_1601781_57 = "Selamat Tahun Baru! Saya membuat sarung tangan dari bulu Little Furball untuk Anda dan kedua murid saya.",
  str_voice_1601781_58 = "Aku akan menunggumu di depan, Fia.",
  str_voice_1601781_59 = "Saya seorang guru yang sangat baik, bukan?",
  str_voice_1501801_1 = "Mengumpulkan info sangat penting. Burung pipit topi saya Blanche bertanggung jawab atas Lumopolis, merpati abu-abu saya Cinder bertanggung jawab atas Lumopolis Bawah, dan Shadow tikus saya bertanggung jawab atas Umbraton.",
  str_voice_1501801_2 = "Anda pikir perlengkapan saya terlihat berat? Ah, terima kasih, tapi aku bisa mengurusnya sendiri. Jika Anda ingin menjadi reporter independen, ini semua adalah sekutu yang sangat diperlukan di lapangan.",
  str_voice_1501801_3 = "Aku tahu apa yang kamu maksud tadi—kamu tidak suka di sini, kan? Anda memiliki banyak ide yang belum direalisasikan, bukan? Hah? Apakah Anda menyangkalnya? Betulkah? Saya tidak percaya Anda.",
  str_voice_1501801_4 = "Wow, tiba-tiba saya merasa tas saya jadi lebih ringan! Ini seharusnya membuat segalanya lebih mudah... Terima kasih, PlayerName.",
  str_voice_1501801_5 = "Blanche menemukan motifnya, Cinder menemukan senjata pembunuhnya, dan Shadow menemukan saksinya... Yup! Aku sudah tahu siapa pembunuhnya! Laporan eksklusif akan segera keluar!",
  str_voice_1501801_6 = "Wow, kecepatan menulis saya sudah sangat tinggi! Saya perlu memberi tahu editor saya tentang ini segera. Hei, mungkin aku bisa segera menjadi staf penulis!",
  str_voice_1501801_7 = "Ini adalah pertama kalinya ada orang yang mengatakan kata-kata baik seperti itu kepadaku. Anda tidak mencoba menyuap saya, kan? Meski begitu, saya tidak akan berhenti melaporkan dengan jujur tentang semua petualangan Anda!",
  str_voice_1501801_8 = "Saya ingin menulis fitur eksklusif tentang Anda. Erm... Maksudku, itu yang diminta oleh editorku... Aku sendiri baru mengetahuinya.",
  str_voice_1501801_9 = "Kamu... Um, sebenarnya aku... Bernafas, Brandy. Sebenarnya, saya hanya ingin bertanya, apakah kita boleh melakukan ini? Seorang jurnalis dan orang yang diwawancarainya?",
  str_voice_1501801_10 = "Saya akan menuliskan semua yang Anda lakukan dalam pandangan saya. Apakah kamu takut? Ahahaha—Tidak, saya tidak tertawa.",
  str_voice_1501801_11 = "Baiklah, ini kesempatan langka! Tidak ada yang mengganggu saya, dan editor saya tidak mempermasalahkan tenggat waktu ... Sudah waktunya untuk menyelesaikan semua pekerjaan saya dari minggu lalu!",
  str_voice_1501801_12 = "Seorang reporter kelas satu tidak pernah goyah sedetik pun, bahkan di tengah zona perang.",
  str_voice_1501801_13 = "Penasaran dengan tas saya? Ada segala macam petunjuk dan sumber daya berharga di dalamnya—harta tak ternilai yang harus dibanggakan oleh seorang jurnalis. Hah? Anda hanya ingin tahu tentang tampilannya !?",
  str_voice_1501801_14 = "Dengar, saat kau mengejar petunjuk dan penyamaranmu akan terbongkar, lakukan saja apa yang kulakukan—turunkan pinggiran topimu, kenakan kacamata hitam, dan kancingkan mantelmu.",
  str_voice_1501801_15 = "Selamat ulang tahun! Kamu pasti sangat senang hari ini, kan? Hadiah apa yang Anda terima, dan dari siapa?",
  str_voice_1501801_16 = "Apakah orang yang diwawancarai itu mengatakan yang sebenarnya? Sudahkah saya memeriksa semua fakta? Oh! Hai, saya bekerja keras, seperti biasa!",
  str_voice_1501801_17 = "Burung saya pergi makan remah roti di jalan setiap pagi. Tapi kenapa mereka selalu memilih jalan ini? Ini perlu diselidiki...",
  str_voice_1501801_18 = "Selamat malam. Aku sedang mempersiapkan syuting besok. Film: periksa, penutup lensa: periksa, bola lampu: periksa ...",
  str_voice_1501801_19 = "Saya rasa Anda tidak akan pernah bergumul dengan sesuatu seperti gagal melewati masa percobaan, bukan? Yah, bagaimanapun juga, kamu harus istirahat.",
  str_voice_1501801_20 = "Umbraton memiliki sesuatu untuk memuaskan semua selera, apakah itu masalah sosial yang Anda sukai atau hal lain yang menjadi minat Aurorian.",
  str_voice_1501801_21 = "Lumopolis... Saya tidak tahu apakah mereka memiliki wartawan di sana.",
  str_voice_1501801_22 = "Blanche, Cinder, dan Shadow memperhatikanmu!",
  str_voice_1501801_23 = "Mereka tampaknya tidak terlalu layak diberitakan.",
  str_voice_1501801_24 = "Vic adalah seseorang yang sangat ingin saya wawancarai... Suatu hari nanti!",
  str_voice_1501801_25 = "Lilica sama sepertiku! Kami berdua berjuang untuk mengejar impian kami.",
  str_voice_1501801_26 = "Benarkah Vice dan Carleen memiliki kecenderungan terhadap hal yang berbeda saat mereka masih sekolah? Hmph. Baiklah, aku akan berhenti bertanya.",
  str_voice_1501801_27 = "Saya benar-benar tidak mengerti apa yang dipikirkan para pemimpin itu... Mereka tampaknya hidup di dunia yang benar-benar berbeda yang terpisah dari kenyataan, dan mereka tidak memberi makan generasi muda selain kebohongan!",
  str_voice_1501801_28 = "Bisakah Soroz hanya berkomunikasi dengan Anda? Oh... Bisakah Anda membantu saya? Anda lihat, saya ingin Anda membantu menerjemahkan untuk kami sehingga saya dapat mewawancarainya. Bagaimana kau tahu aku akan bertanya?",
  str_voice_1501801_29 = "Saya Brandy, reporter magang dari The Daily Scoop. kamu PlayerName? Hebat, akhirnya aku bisa bertemu denganmu! Anda adalah harta karun terbesar dari berita utama di seluruh Astra!",
  str_voice_1501801_30 = "Saya bisa menulis lebih cepat sekarang!",
  str_voice_1501801_31 = "Pikiranku terasa sangat jernih!",
  str_voice_1501801_32 = "Saya mengerti semuanya sekarang!",
  str_voice_1501801_33 = "A-Apakah saya akhirnya full-timer?",
  str_voice_1501801_34 = "Saya perlu menuliskan ini semua.",
  str_voice_1501801_35 = "Inspirasi saya mengalir!",
  str_voice_1501801_36 = "Apakah kamu siap untuk ini?",
  str_voice_1501801_37 = "Ini adalah perasaan pertempuran!",
  str_voice_1501801_38 = "Sebenarnya, kekuatan!",
  str_voice_1501801_39 = "Kamera siap!",
  str_voice_1501801_40 = "TINDAKAN!",
  str_voice_1501801_41 = "Biar aku saja.",
  str_voice_1501801_42 = "Haha, aku tahu itu!",
  str_voice_1501801_43 = "Maaf...",
  str_voice_1501801_44 = "Ha! Ada cerita di sini di suatu tempat...",
  str_voice_1501801_45 = "Terima kasih! Aku menyukainya!",
  str_voice_1501801_46 = "Wow! Aku akan memasukkannya ke dalam tasku!",
  str_voice_1501801_47 = "Tunggu, aku sedikit malu...",
  str_voice_1501801_48 = "*Menangis* PlayerName...",
  str_voice_1501801_49 = "Saya pertama kali masuk ke koran dan majalah ketika saya masih kecil. Meskipun saya hanya tertarik pada kolom gosip saat itu, saya belajar membaca dan menulis dari tabloid.",
  str_voice_1501801_50 = "Perang membuat saya sadar bahwa hidup ini lebih dari sekadar gosip. Bahkan saya tidak tahu bagaimana saya akan benar-benar mendefinisikan berita... Bisakah tragedi yang berulang setiap hari benar-benar disebut demikian?",
  str_voice_1501801_51 = "Orang tua saya ingin saya belajar perdagangan, tetapi saya pikir wawancara dan menulis adalah keterampilan yang akan saya asah sepanjang hidup saya. Hmm... Akan lebih baik jika saya bisa menjadi karyawan penuh waktu di pekerjaan saya saat ini.",
  str_voice_1501801_52 = "Alchemy Stars!",
  str_voice_1501801_53 = "Halo, saya Brandy.",
  str_voice_1501801_54 = "Selamat pagi. Aku sudah sampai di mejaku.",
  str_voice_1501801_55 = "Selamat sore! Mari gunakan kesempatan ini untuk makan sesuatu!",
  str_voice_1501801_56 = "Ya, saya belum menyelesaikan draf hari ini.",
  str_voice_1501801_57 = "Selamat Tahun Baru, PlayerName. Meskipun berita tahun lalu tidak semuanya baik, selama saya mencatat semuanya dengan jujur dan seseorang memperhatikannya ... Saya tahu tahun depan akan lebih baik.",
  str_voice_1600773_1 = "Pernahkah Anda memperhatikan bahwa di mana melodi mengalir, pemandangan yang paling sepele dan tidak penting pun mulai bersinar seperti berlian yang mempesona di bawah sinar matahari?",
  str_voice_1600773_2 = "Apa yang membuat lagu bagus? Melodi yang elegan, atau lirik yang indah? Caelestite, ini semua tentang hati.",
  str_voice_1600773_3 = "Kehidupan setiap orang seperti lagu yang unik. Oh? Anda ingin tahu bagaimana lagu hidup saya terdengar? Mungkin Anda bisa menjawabnya untuk saya.",
  str_voice_1600773_10 = "Ayo, jangan sampai kita membuang waktu dengan melamun. Duduklah di depan piano ini, dan kita akan menggunakan musik untuk berbicara tentang masa depan.",
  str_voice_1600773_11 = "Seperti apa hari bagi seorang penyanyi wanita? Mungkin mengenakan pakaian ini akan membantu Anda memahami. Hmm? Anda menyebut ini... cosplay? Kalau begitu, ini berarti kamu adalah penggemarku, kan?",
  str_voice_1600773_12 = "Apakah Anda mematahkan senar gitar, piano Anda tidak selaras, atau drum Anda tertusuk, percayalah bahwa musik merdu tidak pernah mati.",
  str_voice_1600773_13 = "Hanya musik yang Anda mainkan yang dapat membangunkan Colossus yang sedang tidur. Tidak, bukan hanya Colossus... Hmmm, apakah masih terlalu dini untuk membicarakan hal ini?",
  str_voice_1600773_14 = "Anda mendeteksi kesedihan dalam nyanyian saya? Sering dikatakan bahwa emosi kami tercermin dalam lagu kami, dan sekarang saya melihat bahwa itu benar... Ssst, tolong jaga ini di antara kami.",
  str_voice_1600773_16 = "Lagu-lagu penyanyi nakal terdengar di lapangan salju yang kosong. Dengarkan suara mereka yang bahkan melelehkan salju.",
  str_voice_1600773_17 = "Hmm? Anda sudah bangun. Aku tahu itu. Musik yang lembut lebih efektif untuk membangunkan orang.",
  str_voice_1600773_18 = "Saat malam tiba di Northland, setiap keluarga menyanyikan balada yang sama...♪",
  str_voice_1600773_19 = "Kenapa kamu masih bangun? Baik, jika Anda bersikeras menjadi penonton larut malam saya.",
  str_voice_1600773_35 = "Band Northland sudah siap.",
  str_voice_1600773_36 = "Saatnya memulai pertunjukan.",
  str_voice_1600773_37 = "Lagu ini didedikasikan untuk semua Aurorian.",
  str_voice_1600773_38 = "Tanamkan melodi ini di hatimu.",
  str_voice_1600773_39 = "Petik kuncinya!",
  str_voice_1600773_40 = "Suara gletser!",
  str_voice_1600773_44 = "Pendengar, mari sebarkan harapan melalui lagu.",
  str_voice_1600773_58 = "Pagi, aku sudah menunggumu.",
  str_voice_1600773_59 = "Secangkir teh untuk memulai hari yang damai...",
  str_voice_1600773_60 = "Apakah Anda mendengar kicauan burung pagi ini?",
  str_voice_1600773_61 = "Apakah Anda ditelan oleh mimpi Anda tadi malam?",
  str_voice_1600773_62 = "Pagi berlalu dalam sekejap mata. Manfaatkan sebaik-baiknya.",
  str_voice_1600773_63 = "\"Kristal es berkilau cemerlang di bawah sinar matahari pagi ...\"",
  str_voice_1600773_64 = "Ini hari yang baru. Kehidupan seperti apa yang akan saya alami hari ini?",
  str_voice_1600773_65 = "Selamat siang, pendengarku.",
  str_voice_1600773_66 = "Setengah dari hari ini telah kita lewati. Bagaimana perasaanmu?",
  str_voice_1600773_67 = "Ingat, Northland akan selalu menjadi rumahmu.",
  str_voice_1600773_68 = "Saat waktunya tiba, kau akan tahu.",
  str_voice_1600773_69 = "Bagian dari dirimu berserakan di pecahan masa depan.",
  str_voice_1600773_70 = "Balas dendam bukanlah alasan untuk bertarung.",
  str_voice_1600773_71 = "Jika Anda benar-benar ingin menginjakkan kaki di medan perang, pertama-tama Anda harus menemukan sesuatu yang ingin Anda lindungi.",
  str_voice_1601781_99 = "Saya berlatih rebana untuk waktu yang lama sehingga saya bisa menguasainya. Saya harap saya tidak mengecewakan semua orang!",
  str_voice_1601031_99 = "Bagaimana lagu konser terdengar lebih baik daripada teriakan di ruang interogasi?",
  str_voice_1601481_99 = "Bagaimana Anda akan membayar saya setelah pertunjukan?",
  str_voice_1601161_99 = "Bolehkah saya membawa beberapa bagian Wandering Colossus sebagai kenang-kenangan setelah pertunjukan?",
  str_voice_1600021_99 = "Bagi saya, pentas juga merupakan salah satu jenis latihan yang bisa mengasah temperamen saya.",
  str_voice_1601771_99 = "Saya harap nyanyian saya memberikan inspirasi dan kekuatan kepada semua orang!",
  str_voice_1601811_1 = "Saya telah pergi ke laut dengan Lin Guildmaster beberapa kali. Sangat indah di luar sana di atas ombak. Anda bisa mengesampingkan pikiran Anda dan menikmati pemandangan dengan sepenuh hati.",
  str_voice_1601811_2 = "Ketiga kucing ini telah bersama saya selama bertahun-tahun. Mereka adalah bagian dari diriku—kami tidak dapat dipisahkan.",
  str_voice_1601811_3 = "Jika Anda suka, teman muda, dengan senang hati saya akan memberi tahu Anda lebih banyak tentang sejarah, adat istiadat, dan tradisi Longzhou.",
  str_voice_1601811_4 = "Kesulitan apa pun dalam hidup adalah perjalanan yang berharga dengan teman-teman seperti Anda di belakangnya.",
  str_voice_1601811_5 = "Di paruh pertama hidup saya, saya tak terbendung dan heroik, sedangkan di paruh kedua, saya melayang seperti rumput bebek. Tapi bagaimana dengan itu? Tidak ada yang bisa memutuskan di mana saya harus tinggal, dan tidak ada yang bisa mengganggu ketenangan pikiran saya.",
  str_voice_1601811_6 = "Baiklah baiklah! Kemasyhuran hanyalah debu yang tertiup angin—aku belum tua, dan aku masih bisa memerintahkan api merah di tanganku untuk melenyapkan semua kejahatan!",
  str_voice_1601811_7 = "Anda berada di puncak kehidupan, teman muda. Itu mengingatkanku pada masa lalu... Bagaimana kalau kita jalan-jalan dan mengobrol?",
  str_voice_1601811_8 = "Saya mendapat banyak manfaat karena bertemu dengan Anda, teman muda—melihat luasnya dunia, di balik petak langit yang terbentang di atas Longzhou.",
  str_voice_1601811_9 = "Ketika saya masih muda, saya sama seperti Anda. Saya harap Anda dapat terus maju ke masa depan dan mengejar bintang-bintang.",
  str_voice_1601811_10 = "Selama bertahun-tahun bepergian, saya telah mengembara dunia untuk waktu yang lama, jadi saya tidak bisa tidak merindukan kampung halaman saya ...",
  str_voice_1601811_11 = "Merupakan suatu kehormatan untuk mendapatkan kepercayaan Anda, teman saya.",
  str_voice_1601811_12 = "Saat angin bertiup, selalu mengingatkanku pada musim gugur di kampung halamanku.",
  str_voice_1601811_13 = "Anda bisa bermain dengan kucing saya kapan pun Anda mau. Mereka disebut Yixin, Yimeng, dan Yinuo. Jangan khawatir, mereka tahu kamu adalah temanku dan tidak akan menyakitimu.",
  str_voice_1601811_14 = "Kursi roda saya tampaknya membuat suara-suara aneh baru-baru ini. Mungkin itu imajinasiku? Sejujurnya, saya tidak bisa terbiasa dengan itu.",
  str_voice_1601811_15 = "Sungguh hari yang baik. Saya berharap Anda sehat dan sukses dalam segala hal yang Anda perjuangkan.",
  str_voice_1601811_16 = "Ketika Anda bingung tentang sesuatu, tutup mata Anda dan renungkan sejenak.",
  str_voice_1601811_17 = "Mandi di pagi hari menenangkan pikiran seseorang.",
  str_voice_1601811_18 = "Belajar bersantai setelah seharian bekerja juga merupakan cara yang baik untuk meningkatkan efisiensi.",
  str_voice_1601811_19 = "Saat semuanya hening, Anda bisa menjernihkan pikiran.",
  str_voice_1601811_20 = "Tidak peduli berapa banyak yang saya alami, saya akan selalu mencintai tanah tempat saya berasal.",
  str_voice_1601811_21 = "Astra memiliki begitu banyak pemandangan yang belum saya lihat. Ini benar-benar tempat yang ajaib.",
  str_voice_1601811_22 = "Bahkan jika kita harus melakukan perjalanan ribuan mil, kita akan mempertahankan pegunungan dan sungai di Longzhou!",
  str_voice_1601811_23 = "Di mana ada cahaya, di situ juga ada kegelapan.",
  str_voice_1601811_24 = "Meskipun Lin Guildmaster terlihat tenang sekarang, dia sangat menderita ketika dia masih muda karena kecerobohannya.",
  str_voice_1601811_25 = "Liqing si kucing-kucing? Asyik bermesraan dengannya. Mungkin saya seharusnya tidak mengatakan itu tentang dokter saya ...",
  str_voice_1601811_26 = "Porselen yang diproduksi di Longzhou sangat indah. Itu salah satu hal favorit saya.",
  str_voice_1601811_27 = "Mungkin karena pengalaman saya di laut, tapi melihat ikan membawa kembali kenangan yang tidak menyenangkan.",
  str_voice_1601811_28 = "Itu adalah ... entitas yang menakjubkan.",
  str_voice_1601811_29 = "Saya dulu adalah Zhong Xu, Jenderal Agung Kekaisaran Zhao di Longzhou, tetapi sekarang saya hanya seorang pengembara yang menyendiri. Mari kita tidak berbicara tentang masa lalu. Mulai sekarang, aku akan menemanimu.",
  str_voice_1601811_30 = "Api berkobar di dalam hatiku.",
  str_voice_1601811_31 = "Kekuatan saya telah kembali.",
  str_voice_1601811_32 = "Bagus sekali! Memang luar biasa!",
  str_voice_1601811_33 = "Keberanian, begitu saja!",
  str_voice_1601811_34 = "Saya telah menunggu lama.",
  str_voice_1601811_35 = "Siap untuk berangkat.",
  str_voice_1601811_36 = "Saya merasa dalam performa terbaik.",
  str_voice_1601811_37 = "Sekarang! Tewas!",
  str_voice_1601811_38 = "Api akan membara semuanya menjadi abu!",
  str_voice_1601811_39 = "Yixin, giliranmu!",
  str_voice_1601811_40 = "Medan perang itu kejam.",
  str_voice_1601811_41 = "Saya akan memenuhi harapan Anda.",
  str_voice_1601811_42 = "Kemenangan sudah dekat.",
  str_voice_1601811_43 = "Dimana ada kehidupan disana ada harapan. Jangan pernah menyerah.",
  str_voice_1601811_44 = "Jangan khawatirkan aku. Saya suka disini.",
  str_voice_1601811_45 = "Saya menghargai kebaikan Anda, teman muda.",
  str_voice_1601811_46 = "Saya berterima kasih atas perhatian Anda, teman muda.",
  str_voice_1601811_47 = "Hadiah paling mewah; kamu cukup murah hati.",
  str_voice_1601811_48 = "Saya terima, dengan sangat bahagia.",
  str_voice_1601811_49 = "Saya biasa bertempur di garis depan untuk membawa kejayaan bagi bangsa, memimpin pasukan saya di seluruh benua untuk menenangkan keributan. Melihat ke belakang, saya masih sangat muda dan penuh kehidupan...",
  str_voice_1601811_50 = "Dalam perjalanan ke Ji, saya menyelamatkan karavan keluarga Lin yang dijarah dan berkenalan dengan Lin Guildmaster. Kami sekarang sudah saling kenal selama lebih dari sepuluh tahun.",
  str_voice_1601811_51 = "Ketika saya meninggalkan Yangjing, saya tidak membawa banyak barang, hanya tiga kucing kecil Dragon Li ini. Selama saya membawa pemikiran bangsa saya di hati saya, saya tidak akan mengingini kepuasan di mana pun di dunia ini, tidak peduli seberapa besar itu.",
  str_voice_1601811_52 = "Alchemy Stars.",
  str_voice_1601811_53 = "Halo, teman muda.",
  str_voice_1601811_54 = "Cahaya fajar mulai menyinari.",
  str_voice_1601811_55 = "Ini adalah waktu siang hari ketika matahari bersinar paling terang.",
  str_voice_1601811_56 = "Ini sangat terlambat, teman muda.",
  str_voice_1601811_57 = "Tahun Baru telah tiba. Saya berharap Anda baik-baik saja.",
  str_voice_1601821_1 = "Anda ingin tahu apa yang ada di depan? Ini adalah arus bawah, karang yang berbahaya, tsunami yang akan menelan segalanya. Tapi saya memilih jalan ini sendiri dan akan mengikutinya sampai akhir.",
  str_voice_1601821_2 = "Pembuatan kapal bukanlah hal yang mudah. Ini membutuhkan kerja sama sistematis dari galangan kapal, pelabuhan, dan rimbawan. Anda memerintahkan orang untuk berperang, yang juga membutuhkan koordinasi antara berbagai kelompok. Itu juga tidak mudah.",
  str_voice_1601821_3 = "Tidak perlu salam basi, saya tidak peduli dengan mereka. Aku datang kepadamu untuk menjalin persahabatan.",
  str_voice_1601821_4 = "Beri minyak pada dayungnya, dan perahu dapat mendayung lebih cepat. Berikan navigator peta bahari, dan sebuah kapal dapat menemukan jalannya.",
  str_voice_1601821_5 = "Saya tidak tahu Anda memiliki konstitusi yang kuat. Sangat mengesankan bahwa Anda tidak mabuk laut dan muntah dalam badai sekeras yang kami temui tadi. Aku akan mengajakmu ke lomba perahu besok, itu pasti lebih seru. Hmm? Mengapa kamu melarikan diri?",
  str_voice_1601821_6 = "Anda terluka. Hmm, disana. Kau pikir aku terlalu dingin? Lalu lepas pakaianmu. Saya baru saja selesai bekerja di bawah sinar matahari, dan tangan saya hangat. Mereka cukup panas untuk membantu mengoleskan salep pada Anda.",
  str_voice_1601821_7 = "Ketika Anda bebas, saya akan membawa Anda ke laut untuk berburu ikan paus bertanduk yang legendaris. Anda ingin pergi sekarang? Tidak, saya harus mengirim perahu untuk mencari tahu terlebih dahulu. Saya akan menghubungi Anda setelah saya membuat pengaturan.",
  str_voice_1601821_8 = "Anda membebaskan ikan peliharaan saya? Maka Anda dapat menggantinya dengan menjadi hewan peliharaan baru saya.",
  str_voice_1601821_9 = "Saya terlihat tidak biasa? Itu mungkin karena aku baru saja menegur beberapa bawahanku, bodoh. Jangan pergi. Anda bukan salah satu bawahan saya! Jangan pedulikan aku, hanya... berdiri di sana. Disampingku.",
  str_voice_1601821_10 = "Ketika Anda menaiki kapal saya, Anda harus mematuhi perintah saya, atau Anda akan berjalan di papan.",
  str_voice_1601821_11 = "Mereka mengatakan bahwa jika Anda ingin berterima kasih kepada orang lain, Anda harus membalas kebaikan dengan senyuman. Terima kasih telah mengundang saya. *Senyum*",
  str_voice_1601821_12 = "Semua orang mengatakan bahwa laut bergolak dan kejam, tetapi menghadapi laut jauh lebih mudah daripada menghadapi manusia.",
  str_voice_1601821_13 = "Meski ada cara yang lebih cepat... Lupakan saja. Jika Anda ingin menangkap ikan besar, Anda harus bersabar.",
  str_voice_1601821_14 = "Anda telah sedikit turun baru-baru ini. Apakah Anda ingin saya menghibur Anda? Oh, jangan sedih. Aku jelas menganggapmu temanku, tapi aku tidak bisa memaksakan diri untuk mengatakan basa-basi yang membosankan itu.",
  str_voice_1601821_15 = "Saya berharap Anda hidup selama monster laut.",
  str_voice_1601821_16 = "Apakah kamu bosan? Yah, aku tidak.",
  str_voice_1601821_17 = "Ingin melihat laut di pagi hari?",
  str_voice_1601821_18 = "Keindahan dunia mirip dengan matahari terbenam di atas lautan.",
  str_voice_1601821_19 = "Jangan keluar di malam hari. Jika Anda mengalami Eclipsite, Anda akan selesai.",
  str_voice_1601821_20 = "Kerajaan Ji memiliki kondisi transportasi laut yang unik. Karena itu kami berhasil mengembangkan industri perdagangan yang maju.",
  str_voice_1601821_21 = "Astra adalah rumah bagi spesialisasi unik yang tak terhitung jumlahnya. Saya percaya kedua benua bisa mendapatkan keuntungan dari perdagangan reguler dan pertukaran budaya.",
  str_voice_1601821_22 = "Berkeliling dunia dan berinteraksi dengan banyak negara adalah tujuan dari guild kami.",
  str_voice_1601821_23 = "Mereka sama menjijikkannya dengan karang yang paling berlendir.",
  str_voice_1601821_24 = "Saya diadopsi oleh tetua keluarga Lin. Dia adalah mentor saya, juga keluarga saya. Suatu hari, saya harus menunjukkan kepadanya sepenuhnya rasa terima kasih saya.",
  str_voice_1601821_25 = "Keluarga saya? Ibu meninggal, dan Ayah melarikan diri. Apalagi yang ingin kamu ketahui? Saya tidak marah. Sungguh, aku tidak. Saya berjanji.",
  str_voice_1601821_26 = "Mie siput sungai... Enak.",
  str_voice_1601821_27 = "Saya tidak terbiasa dengan makanan manis dan berminyak atau makanan kering.",
  str_voice_1601821_28 = "Apakah Anda pikir Colossus ini bisa berlayar di laut?",
  str_voice_1601821_29 = "Saya Mu Yuebai, kapten Shadowind. Kecuali Anda membutuhkan sesuatu, jangan datang mengganggu saya.",
  str_voice_1601821_30 = "Persis seperti ikan di dalam air.",
  str_voice_1601821_31 = "Langit cerah, jalur cerah.",
  str_voice_1601821_32 = "Saya bisa melakukan lebih baik lagi.",
  str_voice_1601821_33 = "Semoga kita berlayar dengan angin kencang dan memecahkan ombak.",
  str_voice_1601821_34 = "Roger.",
  str_voice_1601821_35 = "Air pasang naik.",
  str_voice_1601821_36 = "Air pasang.",
  str_voice_1601821_37 = "Torrent, sapu masuk!",
  str_voice_1601821_38 = "Laut tidak terbatas dan berisi semua dalam genggamannya.",
  str_voice_1601821_39 = "Tetap di jalur.",
  str_voice_1601821_40 = "Cuci bersih dunia.",
  str_voice_1601821_41 = "Saya tidak akan mengecewakan.",
  str_voice_1601821_42 = "Bulan telah terbit di atas laut.",
  str_voice_1601821_43 = "Aku tidak tahu bagaimana menghiburmu.",
  str_voice_1601821_44 = "Struktur Colossus ini mirip dengan kapal. Saya ingin mempelajarinya dengan cermat.",
  str_voice_1601821_45 = "Kenapa hadiahnya? Ini sangat mendasar.",
  str_voice_1601821_46 = "Sangat bagus. Terima kasih.",
  str_voice_1601821_47 = "Oh... Tidak apa-apa, kurasa.",
  str_voice_1601821_48 = "Terima kasih banyak. Ini sangat menyenangkan bagi saya.",
  str_voice_1601821_49 = "Saya lahir dengan ekor serpentfish. Kebanyakan orang merasa takut saat melihatnya. Oh? Anda tidak takut, tetapi hanya ingin tahu?",
  str_voice_1601821_50 = "Belati Tulang Leluhur ini diberikan kepadaku oleh sesepuh Keluarga Lin dua kali — sekali ketika aku lahir dan sekali ketika ayahku pergi.",
  str_voice_1601821_51 = "Nama keluarga saya adalah Lin, tetapi kemudian saya mengubahnya menjadi Mu. Mengapa? Bagaimanapun, izinkan saya menunjukkan Shadowind terlebih dahulu. Saya meningkatkan sistem tenaganya baru-baru ini...",
  str_voice_1601821_52 = "Alchemy Stars.",
  str_voice_1601821_53 = "Cuacanya bagus, cocok untuk berlayar.",
  str_voice_1601821_54 = "Ini dia. Aku akan pergi sarapan sekarang. Selamat tinggal.",
  str_voice_1601821_55 = "Siang ini panas sekali. Aku akan mandi. Selamat tinggal.",
  str_voice_1601821_56 = "Sudah larut... Aku akan tidur sekarang. Selamat tinggal.",
  str_voice_1601821_57 = "Selamat Tahun Baru.",
  str_voice_1501831_1 = "Jangan tepuk kepalaku! Bagaimana Anda bisa begitu kasar kepada senior Anda !? Berapa umur saya? Dua belas tahun... tapi aku masih seniormu!",
  str_voice_1501831_2 = "Anda masih tumbuh. Ambil ini sekali sehari untuk melengkapi nutrisi Anda. Uang? Aku tidak tertarik dengan hal semacam itu! Sebutkan uang lagi, dan saya akan marah!",
  str_voice_1501831_3 = "anak kucing ini? Tinytail bukan hanya seekor kucing, dia adalah saudaraku. Dia pemalas dan pelahap, jadi dia belum bisa berevolusi menjadi bentuk Aurorian setelah sekian lama—Aduh aduh! Oke, saya tidak akan memanggil Anda dengan nama panggilan Anda!",
  str_voice_1501831_4 = "Saya merasa sangat ringan! Ya! Sekarang saya bisa melompat ke konter. Biarkan saya melihat apa yang kita miliki di sini ...",
  str_voice_1501831_5 = "Saya membaca lima buku baru hari ini, dan saya ingat semua yang ada di dalamnya. Aku pintar, benar! Hmm... Tapi kau juga harus berterima kasih untuk ini.",
  str_voice_1501831_6 = "Wah... hm! Dengan pendengaran dan penglihatan yang tajam, saya tiba-tiba merasa seperti bisa mencicipi semua jenis herbal sekaligus, dan menulis resep baru yang tak terhitung jumlahnya! Anda harus menguji obat saya nanti!",
  str_voice_1501831_7 = "Saya menemukan buah yang sangat enak tempo hari. Anda bisa mencobanya... Ah, Tinytail! Kenapa kamu memakan semuanya!?",
  str_voice_1501831_8 = "Ingin menyentuh ekorku? Hmm... Kurasa tidak apa-apa... Aku akan membuat pengecualian, hanya untukmu!",
  str_voice_1501831_9 = "Sebenarnya, banyak orang tidak menyukai kami fiendlings. Mereka pikir kami biadab dan inferior. Tetapi, PlayerName, saat aku bersamamu... Tidak, tidak, tidak! Sudahlah!",
  str_voice_1501831_10 = "Ughhhh. Membosankan berada di dalam sepanjang waktu! Bawa saya keluar untuk menemukan ramuan baru!",
  str_voice_1501831_11 = "Aku disini! Apa yang salah? Hah? Anda tidak sakit? Saya seorang dokter yang sangat sibuk! Jangan panggil aku tanpa alasan... Kamu memberiku makanan ringan? Yah, aku kira itu bisa diterima...",
  str_voice_1501831_12 = "Mengapa Anda makan junk food ini lagi? Aku akan mengambilnya! ... Mereka agak lezat! Aku sudah dewasa! Tidak apa-apa bagi saya untuk mengambil beberapa gigitan!",
  str_voice_1501831_13 = "Aku sangat berpengetahuan, bukan? Obat saya bekerja, bukan? Anda tahu barang-barang Anda! Ehem... Ketenaran, kekayaan, dan prestise adalah hal-hal yang tidak penting... tapi memujiku sedikit lagi tidak ada salahnya.",
  str_voice_1501831_14 = "Penasaran dengan timbangan herbalis saya? Anda tidak bisa menyentuhnya kapan pun Anda mau! Ini adalah item penting untuk mengeluarkan obat, dan harus selalu akurat dan bersih.",
  str_voice_1501831_15 = "Selamat ulang tahun! Hari ini, Anda bisa menggosok perut Tinytail. Saya memberi Anda izin sebagai gantinya.",
  str_voice_1501831_16 = "Ah, sore ini sangat cerah. Saya mengantuk...",
  str_voice_1501831_17 = "Sibuk, sibuk, sibuk... Ini dia! Tolong bantu saya memindahkan herbal ke sana. Jangan malas!",
  str_voice_1501831_18 = "Kamu sangat rajin, bekerja pada jam ini.. Tapi jangan begadang.",
  str_voice_1501831_19 = "Wow! Kenapa kamu masih bangun !? Biarkan saya membantu Anda menyelesaikan pekerjaan Anda. Tidurlah, sekarang!",
  str_voice_1501831_20 = "Seperti yang Guru Bu katakan, \"Jangan percaya pada dokter yang tidak memiliki kebajikan. Dan jangan percaya pada dokter yang tidak memiliki kejujuran, karena tanpa kejujuran, tidak ada kredibilitas.\"",
  str_voice_1501831_21 = "Orang-orang Lumopolis berpakaian sangat aneh, seolah-olah mereka semua bersinar terang.",
  str_voice_1501831_22 = "Sembuhkan yang terluka, selamatkan yang sekarat!",
  str_voice_1501831_23 = "Gerhana di dalam air jauh lebih mengerikan daripada yang ada di darat! Kejadian itu membuatku sangat takut, aku trauma...",
  str_voice_1501831_24 = "Zhong Xu hanyalah orang tua berkabut, tapi percayalah padaku. Dia tabah di luar, hangat di dalam.",
  str_voice_1501831_25 = "Guru tidak menyetujui saya berkeliling memberitahu semua orang yang saya lihat... tapi saya murid Bucunzi! Dokter terbaik di dunia!",
  str_voice_1501831_26 = "Apakah itu beras yang saya cium...? Hmm, coba saya lihat!",
  str_voice_1501831_27 = "Hanya anak kecil yang memiliki makanan yang mereka benci. A-Apa-apaan ini? Kenapa kau membawakanku sepiring paprika hijau!?",
  str_voice_1501831_28 = "Bagaimana saya bisa menyembuhkan Soroz? Mekanika.... Sistem... Hmm... Saya tidak mengerti sama sekali!",
  str_voice_1501831_29 = "Hmph! Anda harus memiliki bakat untuk menemukan diri Anda seorang dokter terkenal seperti saya. Saya Liqing, dan saya di sini untuk menyembuhkan apa yang membuat Anda sakit!",
  str_voice_1501831_30 = "Apakah saya tumbuh sedikit lebih tinggi ...?",
  str_voice_1501831_31 = "Hah? Indera penciuman saya telah meningkat!",
  str_voice_1501831_32 = "Selera saya telah tumbuh lebih tajam!",
  str_voice_1501831_33 = "Saya pikir saya masih tumbuh lebih tinggi!",
  str_voice_1501831_34 = "Serahkan padaku!",
  str_voice_1501831_35 = "Pertandingan yang sempurna!",
  str_voice_1501831_36 = "Obat pamungkas!",
  str_voice_1501831_37 = "Telan ini!",
  str_voice_1501831_38 = "Hanya yang terbaik dari alam!",
  str_voice_1501831_39 = "Tujuan-!",
  str_voice_1501831_40 = "Ambil obat mu!",
  str_voice_1501831_41 = "Tetap semangat, semuanya!",
  str_voice_1501831_42 = "Hmph! Tidak bisa dihindari!",
  str_voice_1501831_43 = "Aduh, aduh, aduh...",
  str_voice_1501831_44 = "Astaga! Kamu menakuti saya!",
  str_voice_1501831_45 = "Apakah itu sesuatu yang enak?",
  str_voice_1501831_46 = "Kamu punya selera yang bagus!",
  str_voice_1501831_47 = "Apakah ini untukku, lagi? B-Betapa memalukan...",
  str_voice_1501831_48 = "Bagaimana kau tahu aku menyukai ini...?",
  str_voice_1501831_49 = "Tidak seperti fiendlings biasa, saya mengambil pil Master Bu secara tidak sengaja, dan kemudian saya menjadi seorang Aurorian secara tidak sengaja. Saya beruntung. Aku bisa saja mati!",
  str_voice_1501831_50 = "Untuk membayar obat yang saya makan, saya menjadi murid Guru. Namun lambat laun, saya juga mulai memahami kebahagiaan dan tanggung jawab sebagai seorang dokter.",
  str_voice_1501831_51 = "Tapi masa-masa indah itu tidak berlangsung lama. Kebenaran saya menyelinap menuruni gunung segera ditemukan. Guru bisa sangat kejam saat mendisiplinkan muridnya! Tapi saya juga punya mimpi yang tidak bisa saya tinggalkan.",
  str_voice_1501831_52 = "Alchemy Stars!",
  str_voice_1501831_53 = "Hei!",
  str_voice_1501831_54 = "Rencana sehari dimulai saat fajar!",
  str_voice_1501831_55 = "Tidak ada yang menjamin hari yang produktif seperti perut kenyang!",
  str_voice_1501831_56 = "Yaaaawn... sudah lewat jam tidurku...",
  str_voice_1501831_57 = "Selamat Tahun Baru! Anda harus terus tumbuh lebih kuat dan menjadi dewasa dan dapat diandalkan seperti saya!",
  str_voice_1601841_1 = "Salah satu dari anak-anak mencari saya? Apa pun yang mereka inginkan, beri tahu mereka bahwa mereka sendirian. Jangan khawatir, saya percaya mereka. Ini bukan masalah besar, tidak perlu stres!",
  str_voice_1601841_2 = "... Hah? Apa itu tadi? Saya tersesat dalam buku ini dan tidak mendengar Anda. Silakan, saya akan mendengarkan Anda saat membaca. Uh-huh... Yap... Aku berjanji akan mendengarkan.",
  str_voice_1601841_3 = "Jadi, Anda menyiapkan semua sumber daya ini di sini untuk kami gunakan secara gratis? Kamu orang yang hebat, Caelestite kecil... Atau mungkin aku malah harus mengatakan bahwa kami semua suka memanfaatkanmu terlalu banyak.",
  str_voice_1601841_4 = "Saya suka pengalaman baru. Bepergian, membaca, menjelajahi yang tidak diketahui, filosofi - pengalaman segar dan merangsang membuat saya merasa hidup. Di sisi lain, kebosanan seperti kematian yang hidup.",
  str_voice_1601841_5 = "Saya pergi ke Eraveil sekali sebelum Anda mulai membangunnya kembali. Kebingungan, kehancuran, keheningan yang mematikan... kehancuran. Itu membuat saya bertanya-tanya — apa gunanya kemajuan?",
  str_voice_1601841_6 = "Python Suci telah memberi saya perasaan aneh baru-baru ini. Bagaimana saya bisa menjelaskannya...? Hmm. Biarkan saya menjadi sangat serius untuk sekali ini. Perasaan bahwa perjalanan kami di sini tidak sia-sia.",
  str_voice_1601841_7 = "Saya menghargai sikap netral Anda dan Anda tidak mendukung ideologi faksi tertentu. Kekacauan, kelas, despotisme, konservatisme... Tidak perlu mengesampingkan diri sendiri dengan gegabah.",
  str_voice_1601841_8 = "Anda tidak selalu harus berperan aktif dalam drama di sekitar Anda. Cobalah duduk santai dan nikmati keseruan menontonnya bersama saya. Anda tidak tahu betapa lucunya drama kehidupan itu. Aku tahu kau pasti menyukainya.",
  str_voice_1601841_9 = "Ayo, beri tahu saya apa yang Anda lihat dan dengar baru-baru ini. Anda belum melakukan apa-apa akhir-akhir ini? Hidup terasa membosankan? Jangan katakan itu. Saya suka anekdot kecil Anda.",
  str_voice_1601841_10 = "Hmm... aku bosan membaca buku. Bawa saya ke suatu tempat untuk melakukan sesuatu yang menarik.",
  str_voice_1601841_11 = "Kau ingin aku tinggal di sini? Baiklah. Maka saya akan melanjutkan membaca ... Bekerja? Ya, ya, saya akan mengawasi hal-hal.",
  str_voice_1601841_12 = "Saya tidak terlihat seperti saya dari Rediesel Wrench? Saya setuju dengan Anda di sana. Saya belum menemukan faksi yang benar-benar cocok untuk saya. Dan saya suka seperti itu.",
  str_voice_1601841_13 = "Saya memiliki lidah yang tajam kadang-kadang? Hmm... Siapa yang tahu? Tajam atau lembut, suaraku hanya berulang saat ada gema di ruangan itu. Hati-hati pendengar...",
  str_voice_1601841_14 = "Hubungan... Saya tidak terlalu peduli dengan mereka. Tapi saya merasa sedikit sedih ketika menjumpai surat-surat yang tidak ada penerimanya yang hanya bisa dibuang begitu saja.",
  str_voice_1601841_15 = "Ini hari ulang tahunmu, jadi... Semoga masa depanmu bebas dari kebingungan.",
  str_voice_1601841_16 = "Kamu sangat rajin. Biarkan saya mengamati bagaimana Anda bekerja.",
  str_voice_1601841_17 = "Selamat pagi. Elang baru saja kembali. Jika ada berita menarik, saya pasti akan membaginya dengan Anda.",
  str_voice_1601841_18 = "Selamat malam. Hari lain telah berlalu dalam sekejap mata. Bagaimana waktu berlalu.",
  str_voice_1601841_19 = "... Hah? Caelestite kecil, kau masih di sini? Waktu yang tepat! Saat semua orang tertidur, mari kita bersenang-senang.",
  str_voice_1601841_20 = "Dibandingkan dengan faksi lain, Courier Union benar-benar tempat yang nyaman.",
  str_voice_1601841_21 = "Terkadang, saya sangat berharap orang-orang dari Rediesel Wrench akan berpikir sebelum bertindak.",
  str_voice_1601841_22 = "Serikat Kurir, selalu mengirimkan... sebagian besar waktu.",
  str_voice_1601841_23 = "Eclipsites... Dari mana asalnya, dan apa tujuannya?",
  str_voice_1601841_24 = "Kya adalah gadis kecil yang sederhana dan cantik. Saya sangat menyukainya! Dan dia sangat bagus dalam pekerjaannya.",
  str_voice_1601841_25 = "Jangan khawatir. Jika langit runtuh besok, selama Naroxel masih berdiri, kita akan baik-baik saja.",
  str_voice_1601841_26 = "Saya suka membaca sambil mengunyah camilan hati yang enak.",
  str_voice_1601841_27 = "Jangan sia-siakan hidup Anda dengan melakukan pekerjaan yang membosankan. Jika Anda melakukannya, Anda sendiri akhirnya akan bosan.",
  str_voice_1601841_28 = "Colossus ini berbeda dengan yang ada di Rediesel Wrench. Budaya caelestite benar-benar indah mendalam...",
  str_voice_1601841_29 = "Saya Jeriah. Anda dapat memotong formalitas dengan saya. Anda khawatir tentang dua teman saya? Jangan takut — seperti saya, mereka lebih suka menjelajahi hal-hal baru daripada berkelahi.",
  str_voice_1601841_30 = "Mmm, ini terasa luar biasa.",
  str_voice_1601841_31 = "Sepertinya saya menjadi lebih kuat.",
  str_voice_1601841_32 = "Pikiran batin saya adalah zen.",
  str_voice_1601841_33 = "Saya merasakan pengetahuan mengalir ke dalam pikiran saya.",
  str_voice_1601841_34 = "Baiklah…",
  str_voice_1601841_35 = "Grimoire!",
  str_voice_1601841_36 = "Kapanpun kau siap.",
  str_voice_1601841_37 = "Pembicara!",
  str_voice_1601841_38 = "Cahaya ilusi!",
  str_voice_1601841_39 = "Elang!",
  str_voice_1601841_40 = "Python Suci!",
  str_voice_1601841_41 = "Aku? Kapten?",
  str_voice_1601841_42 = "Ini membosankan.",
  str_voice_1601841_43 = "Sekarang, ini menarik...",
  str_voice_1601841_44 = "Hmm... Bisakah itu melakukan sesuatu yang menarik?",
  str_voice_1601841_45 = "Terima kasih.",
  str_voice_1601841_46 = "Boleh juga.",
  str_voice_1601841_47 = "Biar kulihat!",
  str_voice_1601841_48 = "Ini sangat spesial... Apa yang kamu inginkan sebagai balasannya?",
  str_voice_1601841_49 = "Saya lahir di Rediesel Wrench, dan orang tua saya adalah... orang yang sangat liberal. Saya berterima kasih atas toleransi mereka yang berkelanjutan meskipun kepribadian saya sangat bertolak belakang.",
  str_voice_1601841_50 = "Bakat saya untuk Luminatics muncul secara tidak sengaja. Orang tua saya mulai menyadari bahwa terjebak di gurun menahan saya, jadi ketika waktunya sudah matang, saya berangkat untuk bepergian.",
  str_voice_1601841_51 = "Awalnya, saya suka bepergian, tetapi semakin saya melihat, semakin bingung saya jadinya... Saya mulai bertanya-tanya, \"Apa gunanya hidup?\"",
  str_voice_1601841_52 = "Alchemy Stars.",
  str_voice_1601841_53 = "Halo.",
  str_voice_1601841_54 = "Ini waktu yang tepat untuk membaca buku.",
  str_voice_1601841_55 = "Saatnya istirahat.",
  str_voice_1601841_56 = "Bulan keluar.",
  str_voice_1601841_57 = "Pengetahuan tidak hanya terakumulasi secara alami seiring bertambahnya usia. Jangan lupa bahwa jalan yang Anda lalui berada di bawah kedua kaki Anda sendiri.",
  str_voice_1501851_1 = "Apa yang kamu pegang? Kelihatannya sangat istimewa... Ahem, tapi sebagai kurir yang telah melakukan perjalanan ke seluruh benua, saya sudah melihat semuanya.",
  str_voice_1501851_2 = "Jalan itu sangat dekat, tapi tidak ada catatannya di peta Union, jadi aku tidak bisa menggunakannya. Hmm... tapi kami sudah berputar-putar. Mungkin aku harus mendengarkanmu sekali ini saja.",
  str_voice_1501851_3 = "Apakah ini tempat diadakannya pasar tahunan? Aku benar-benar ingin melihatnya... Tidak! Saya harus mengirimkan surat-surat ini bahkan tanpa penundaan sesaat pun!",
  str_voice_1501851_4 = "Saya anggota Serikat Kurir, yang berarti saya selalu berdiri di atas kedua kaki saya sendiri, bahkan jika saya jatuh... Aduh! Tidak, jangan bantu aku... Aku bisa bangun sendiri.",
  str_voice_1501851_5 = "Dari sudut pandang sejarah, reruntuhan juga seperti kurir yang mengirimkan informasi tentang peradaban dan budaya kuno kepada kita. Jangan meremehkan saya! Saya telah membaca bagian yang adil dari buku-buku besar saya.",
  str_voice_1501851_6 = "Saya mendengar bahwa sebelum Courier Union didirikan, orang Aurorian mengirimkan surat dengan menunggang kuda atau berlari dengan berjalan kaki. Itu pasti sangat sulit...",
  str_voice_1501851_7 = "Rediesel ikan kaleng goreng asin dengan saus sambal? Apa orang benar-benar memakannya!? Yah, saya pasti tidak akan! Anda sangat merekomendasikannya? Hmm... Kurasa aku akan mencoba satu gigitan saja...",
  str_voice_1501851_8 = "Jika sesuatu yang baik terjadi pada saya, dapatkah saya menulis surat kepada Anda? Saya ingin menularkan senyum di wajah saya kepada Anda, hehe.",
  str_voice_1501851_9 = "Menulis adalah bentuk komunikasi yang sangat romantis. Jadi... bisakah kau menulis surat untukku? Anda dapat menulis apapun yang Anda suka.",
  str_voice_1501851_10 = "Saya berharap saya memiliki ingatan yang sempurna... Jika saya melakukannya, saya tidak akan membuat kesalahan konyol. Aku tidak mengirim sesuatu hari ini ke alamat yang salah! Maksudku, aku mendapatkan kembali surat itu sebelum terlambat!",
  str_voice_1501851_11 = "Ada berita yang Anda ingin saya sampaikan? Saya akan memastikan saya mengirimkannya tepat waktu!",
  str_voice_1501851_12 = "Beri aku suratmu, dan yakinlah, aku tidak akan kehilangannya! Tapi suratmu... Tidak, aku tidak akan mengintip, sungguh... Hmm...",
  str_voice_1501851_13 = "Saya berada di posisi terakhir dalam peringkat pengiriman bulan ini... PlayerName, mau kirim surat? Saya bahkan akan membayar ongkos kirimnya—berikan saja kepada saya!",
  str_voice_1501851_14 = "Peta Persatuan mengatakan jalan lurus, tapi ada tembok di depan dan jalan di kiri. Apa yang harus saya lakukan? Aku bisa... memanjat tembok?",
  str_voice_1501851_15 = "Selamat ulang tahun! Izinkan saya menyampaikan semua harapan dan hadiah terbaik Anda secara pribadi!",
  str_voice_1501851_16 = "Saya membawakan Anda salam dari pegunungan yang jauh dan angin sepoi-sepoi.",
  str_voice_1501851_17 = "Ingin mengirimkan beberapa surat dengan saya?",
  str_voice_1501851_18 = "Apakah menerima surat dari teman yang sudah lama tidak kamu temui membuatmu bahagia?",
  str_voice_1501851_19 = "Tolong izinkan saya memberikan bintang-bintang indah ke dalam mimpi Anda.",
  str_voice_1501851_20 = "Serikat Kurir adalah organisasi yang hebat dan jembatan komunikasi yang penting bagi orang-orang.",
  str_voice_1501851_21 = "Setiap tempat memiliki karakter uniknya masing-masing. Saya berharap suatu hari dapat menjelajahi setiap inci dari seluruh benua.",
  str_voice_1501851_22 = "Serikat Kurir—aman, tepat waktu, dan rahasia.",
  str_voice_1501851_23 = "Bahkan jika Eclipsites ingin mengirim surat, saya tidak akan mengirimkannya untuk mereka.",
  str_voice_1501851_24 = "Saya tidak tahu bagaimana seseorang seperti Dove berhasil masuk ke Courier Union... Setiap kali saya melihatnya, dia bermalas-malasan bahkan tanpa sedikit pun urgensi yang seharusnya dimiliki oleh kurir yang tepat.",
  str_voice_1501851_25 = "Naroxel adalah senior dan manajer yang terhormat. Dia panutan saya!",
  str_voice_1501851_26 = "Tepat waktu adalah kebajikan terbesar.",
  str_voice_1501851_27 = "Hmph... Terlambat lagi... Bisakah kau tidak seperti itu?",
  str_voice_1501851_28 = "Tidak mudah mengirim surat ke sini sama sekali!",
  str_voice_1501851_29 = "Halo! Kurir Kya di sini, membawakan surat terbaru Anda! Silakan periksa dengan hati-hati!",
  str_voice_1501851_30 = "Pesan diterima.",
  str_voice_1501851_31 = "Harus berlari lebih cepat!",
  str_voice_1501851_32 = "Saya melihat semua, saya mendengar semua.",
  str_voice_1501851_33 = "Pengiriman sukses lainnya!",
  str_voice_1501851_34 = "Aku di sini!",
  str_voice_1501851_35 = "Aku siap.",
  str_voice_1501851_36 = "Menunggu instruksi.",
  str_voice_1501851_37 = "Pengiriman udara!",
  str_voice_1501851_38 = "Anda punya surat!",
  str_voice_1501851_39 = "Jangan lupa tanda tangan!",
  str_voice_1501851_40 = "Serangan disampaikan!",
  str_voice_1501851_41 = "Saya akan menangani ini!",
  str_voice_1501851_42 = "Saya ingin mengirimkan kegembiraan ini kepada semua orang!",
  str_voice_1501851_43 = "* Sniffle * Saya harap tidak ada yang tahu tentang ini.",
  str_voice_1501851_44 = "Memeriksa peta... Harus mengingat setiap inci dari benda ini.",
  str_voice_1501851_45 = "Erm... Terima kasih.",
  str_voice_1501851_46 = "Dapatkah saya memilikinya? Aku benar-benar menyukainya!",
  str_voice_1501851_47 = "Tertanda!",
  str_voice_1501851_48 = "Hadiah yang luar biasa! Terima kasih banyak!",
  str_voice_1501851_49 = "Saya berasal dari desa terpencil bernama Faar yang begitu... yah, jauh, sehingga jarang dikunjungi orang. Ketika saya masih kecil, dunia hanya sebesar Faar di mata saya.",
  str_voice_1501851_50 = "Emerald adalah guruku. Dia mengilhami saya untuk bergabung dengan Serikat Kurir dan menjadi kurir.",
  str_voice_1501851_51 = "Pengalaman saya yang paling berkesan sejauh ini... adalah ketika saya bertemu dengan sekelompok anak yang dikelilingi oleh Eclipsites saat saya sedang dalam pengiriman!",
  str_voice_1501851_52 = "Alchemy Stars.",
  str_voice_1501851_53 = "Ding dong!",
  str_voice_1501851_54 = "Pagi yang cerah dan indah.",
  str_voice_1501851_55 = "Mengapa Anda tidak istirahat sore ini?",
  str_voice_1501851_56 = "Catat kejadian hari ini sebelum tidur.",
  str_voice_1501851_57 = "Tahun Baru adalah waktu tersibuk bagi saya, tetapi saya juga dengan senang hati menyampaikan berkah semua orang kepada mereka!",
  str_voice_1601861_1 = "Hari yang indah! Saya akan keluar jalan-jalan dan tidur siang ketika saya kembali. Tapi kursi santai ini terlalu nyaman. Hmm, saya akan melewatkan jalan-jalan dan langsung tidur siang.",
  str_voice_1601861_2 = "Saya perlu menyelesaikan pekerjaan saya secara efisien saat saya bangun.",
  str_voice_1601861_3 = "mau tahu sebuah rahasia? Saya kidal. Tapi saya selalu menggunakan tangan kanan saya kapan pun saya bisa, untuk menghindari menyakiti siapa pun secara tidak sengaja.",
  str_voice_1601861_4 = "Saya merasa penuh energi! Aku ingin tahu apakah itu karena aku sudah dewasa.",
  str_voice_1601861_5 = "Pekerjaan di Balai Kehakiman itu sulit, tetapi saya jauh lebih baik daripada sebelumnya. Lagi pula, saya tidak bisa membiarkan diri saya menjadi beban bagi rekan-rekan saya, bukan?",
  str_voice_1601861_6 = "Tangan Ilahi menjadi lebih kuat. Aku harus lebih berhati-hati saat menggunakan tangan kiriku.",
  str_voice_1601861_7 = "Anda adalah orang yang sangat baik, PlayerName. Anda akan memberi tahu saya jika Anda membutuhkan sesuatu, bukan?",
  str_voice_1601861_8 = "Oh, apakah Anda ingin mencoba kursi malas saya? Keluarga saya membuatnya untuk saya. Ini sangat lembut dan nyaman.",
  str_voice_1601861_9 = "Aku sangat senang bisa berkenalan denganmu, PlayerName. Dan karena Anda adalah teman tepercaya saya, keluarga Campbell akan selalu mendukung Anda.",
  str_voice_1601861_10 = "Jika Anda pernah bosan, cobalah tidur siang untuk menghabiskan waktu.",
  str_voice_1601861_11 = "Anda tidak takut saya tertidur tiba-tiba?",
  str_voice_1601861_12 = "Saya suka makanan manis, tapi tidak bisa tidur jika terlalu banyak. Anda juga, pastikan untuk memperhatikan asupan gula Anda. Anda tidak ingin menjadi Caelestite berukuran super.",
  str_voice_1601861_13 = "Hah? Di mana buku catatanku? Saya selalu mencatat waktu saya bangun di dalamnya setiap hari. Ini menghemat banyak masalah.",
  str_voice_1601861_14 = "Mimpiku tidak pernah bertahan lama, tapi aku selalu mengingatnya dengan jelas. Saya akan menuliskannya di buku catatan saya jika cukup menarik.",
  str_voice_1601861_15 = "Selamat ulang tahun, PlayerName.",
  str_voice_1601861_16 = "Senang bertemu denganmu.",
  str_voice_1601861_17 = "Senang sekali bisa melihatmu hal pertama setelah bangun tidur.",
  str_voice_1601861_18 = "Saya suka periode tepat setelah matahari terbenam. Ini waktu yang tepat untuk menikmati ketenangan.",
  str_voice_1601861_19 = "Ini sudah sangat malam... Biasanya aku akan tidur jam segini. Apa yang akan kamu lakukan?",
  str_voice_1601861_20 = "Saya yakin adat dan tradisi Lumopolis akan diwariskan dari generasi ke generasi.",
  str_voice_1601861_21 = "Kehidupan anggota Rediesel Wrench seperti sesuatu dari halaman cerita petualangan, bukan?",
  str_voice_1601861_22 = "Demi White Night.",
  str_voice_1601861_23 = "Saya pernah bertemu Eclipsite kecil yang lucu dan tidak berbahaya sebelumnya. Dia tampaknya menjadi salah satu yang spesial.",
  str_voice_1601861_24 = "Leyn... Saya sangat berterima kasih padanya. Semua orang kesal dengan saya karena kondisi saya, tetapi dia banyak membantu saya.",
  str_voice_1601861_25 = "Matthieu tampaknya berpikir saya menyebabkan masalah orang lain. Tapi aku akan terus bekerja keras.",
  str_voice_1601861_26 = "Hobi apa yang saya miliki... Yah, saya suka membaca buku. Misteri, terutama.",
  str_voice_1601861_27 = "Aku benci dibangunkan dari tidur. Itu berarti saya perlu mencari waktu untuk tidur nanti.",
  str_voice_1601861_28 = "Colossus yang sangat besar... Kupikir ini hanya sesuatu yang hanya bisa kuimpikan.",
  str_voice_1601861_29 = "Aku sangat senang kita menjadi teman. Tapi apakah itu mengganggu Anda bahwa saya hanya bangun selama empat jam sehari?",
  str_voice_1601861_30 = "Tangan Ilahi saya mempesona dengan kecemerlangannya.",
  str_voice_1601861_31 = "Kekuatan melonjak melalui tubuhku.",
  str_voice_1601861_32 = "Sekarang saya bisa melawan kantuk dengan lebih baik.",
  str_voice_1601861_33 = "Tangan Ilahi lebih kuat dari sebelumnya.",
  str_voice_1601861_34 = "Aku berjanji tidak akan tertidur.",
  str_voice_1601861_35 = "Pinggiran cahaya suci.",
  str_voice_1601861_36 = "Cahaya suci akan memadamkan semua kejahatan.",
  str_voice_1601861_37 = "Kemegahan ilahi!",
  str_voice_1601861_38 = "Tidak ada tempat untuk bersembunyi di bawah cahaya!",
  str_voice_1601861_39 = "Cahaya suci, mengalir!",
  str_voice_1601861_40 = "Cahaya suci, bersinar!",
  str_voice_1601861_41 = "Terima kasih telah mempercayai saya.",
  str_voice_1601861_42 = "Tangan Ilahi akan menyapu rintangan ke samping.",
  str_voice_1601861_43 = "Saya masih tidak bisa mengendalikan Tangan Ilahi.",
  str_voice_1601861_44 = "Hah? Apakah Anda membutuhkan saya untuk sesuatu? Dan jangan lihat aku seperti itu, aku sudah bangun!",
  str_voice_1601861_45 = "Terima kasih, PlayerName!",
  str_voice_1601861_46 = "Hadiah yang luar biasa.",
  str_voice_1601861_47 = "Saya menghargai pemikiran itu.",
  str_voice_1601861_48 = "Kamu ingat! Oh, aku sangat tersentuh.",
  str_voice_1601861_49 = "Sebagai pewaris keluarga, saya memiliki Tangan Ilahi dan gelar. Saya tidak menderita narkolepsi ketika saya masih kecil dan semua orang mengira saya normal.",
  str_voice_1601861_50 = "Dokter tidak bisa menyembuhkan narkolepsi saya. Tapi saya bisa tetap terjaga selama empat jam setiap hari, jadi saya hanya perlu menyelesaikan semuanya dalam empat jam itu. Ini benar-benar bukan masalah besar.",
  str_voice_1601861_51 = "Kalau saja aku bisa memelihara Eclipsite kecil itu sebagai hewan peliharaan... Tapi kurasa itu tidak akan mungkin terjadi di sini di Lumopolis. Oh well, itu pemikiran yang bagus.",
  str_voice_1601861_52 = "Alchemy Stars.",
  str_voice_1601861_53 = "Halo!",
  str_voice_1601861_54 = "Selamat pagi.",
  str_voice_1601861_55 = "Ah, ini sudah siang.",
  str_voice_1601861_56 = "Selamat malam.",
  str_voice_1601861_57 = "Selamat tahun baru, PlayerName!",
  str_voice_1601891_1 = "Banyak orang mencemooh ide keadilan. Tapi itu bukan sesuatu yang bisa ditertawakan. Setidaknya untuk juri Lumopolis, itu harus menjadi satu-satunya standar kami.",
  str_voice_1601891_2 = "Saya lebih mementingkan apa yang ada di dalamnya, atau apa yang praktis, daripada penampilan. Orang-orang selalu mengamati dan menuding cara saya berpakaian dan senjata saya, menuduh saya terlihat seperti seseorang dari Illumina. Bagaimana menurutmu?",
  str_voice_1601891_3 = "Sebagian besar ketidakbahagiaan dunia berasal dari ketidakadilan. Saya tahu bahwa saya tidak dapat mengubah fakta itu. Tapi saya akan melakukan semua yang saya bisa untuk membasmi ketidakadilan di mana saya melihatnya.",
  str_voice_1601891_4 = "Jika memungkinkan, saya lebih suka tidak bekerja dengan orang lain. Tidak, bukan karena aku tidak menyukai teman-temanmu. Saya hanya bekerja lebih efisien sendirian.",
  str_voice_1601891_5 = "Jika saya ingin keras pada orang lain, saya harus keras pada diri saya sendiri. Menegakkan keadilan membutuhkan kesediaan untuk menghukum diri kita sendiri atas kesalahan kita tanpa belas kasihan. Saya harap Anda akan membimbing saya kapan pun memungkinkan.",
  str_voice_1601891_6 = "Maafkan aku telah menyesatkanmu. Saya tidak ingin bekerja dengan orang lain karena kegagalan saya sendiri. Sekarang saya akhirnya memiliki keberanian untuk mengakuinya.",
  str_voice_1601891_7 = "Jika Anda lelah, saya bisa membuatkan Anda sepoci teh beraroma dan makanan penutup. Saya menanam bunga dan buah sendiri... Maaf, saya terlalu bersemangat membicarakan tanaman saya.",
  str_voice_1601891_8 = "Orang-orang selalu mengatakan saya harus berbicara lebih santai dengan teman-teman saya. Ahem... B-Bagaimana kabarmu, sesama hakim—tidak, aku tidak bisa melakukannya. Lupakan aku berbicara.",
  str_voice_1601891_9 = "SAYA, Leyn, dengan ini bersumpah untuk melayani di sisi Anda sebagai ksatria Anda. Saya akan mengikuti setiap perintah Anda selama itu tidak bertentangan dengan keadilan. Saya memberikan kepada Anda kesetiaan saya sepenuhnya — Oh, terlalu serius? M-Maaf. Saya tidak tahu bagaimana menjadi cara lain ...",
  str_voice_1601891_10 = "Apa kau tidur? Mana selimutnya... ah, itu dia. Oh, maaf membangunkanmu. Tetapi jika Anda benar-benar lelah, Anda bisa tidur siang. Tidak apa-apa.",
  str_voice_1601891_11 = "Leyn, melapor untuk bertugas. Jika Anda butuh sesuatu, katakan saja. Oh, kamu hanya ingin mengobrol denganku? Nah, jika itu yang Anda inginkan, jadilah itu.",
  str_voice_1601891_12 = "Dalam upaya memperluas wawasan saya, saya telah membaca novel detektif dan juga berkas kasus. Novel detektif akhir-akhir ini semakin tidak masuk akal... tapi sangat menyenangkan.",
  str_voice_1601891_13 = "Saya sangat menyesal. Kau sedang ditatap karena kau berjalan-jalan denganku. Ada yang bilang aku populer di kalangan wanita, tapi aku tidak menyukainya. Saya minta maaf atas masalah ekstra.",
  str_voice_1601891_14 = "Maafkan saya jika saya melangkahi, tetapi saya memiliki beberapa pemikiran yang ingin saya ungkapkan. Tenang, itu tidak ada hubungannya dengan pekerjaan saya sebagai juri. Hanya saja, sebagai ksatria Anda, saya ingin Anda mengurangi camilan di antara waktu makan.",
  str_voice_1601891_15 = "Selamat ulang tahun! May Saya bertanya apakah Anda suka kue? Jika tidak, saya dapat mengubahnya menjadi sesuatu yang lain.",
  str_voice_1601891_16 = "Halo, dan selamat datang kembali! Tidak ada waktu untuk disia-siakan, jadi tolong beri saya tugas.",
  str_voice_1601891_17 = "Selamat pagi. Orang-orang berada dalam kondisi terbaiknya di pagi hari, jadi inilah saat yang tepat untuk mengerjakan tugas yang sulit.",
  str_voice_1601891_18 = "Ini sudah malam, kamu harus bersiap-siap untuk tidur. Saya dapat mengambil pekerjaan apa pun yang Anda tinggalkan.",
  str_voice_1601891_19 = "Wah, kamu masih bangun? Jika Anda memiliki tugas mendesak untuk diurus, saya siap membantu.",
  str_voice_1601891_20 = "Saya seorang hakim, jadi saya tidak bisa mengkritik Lumopolis, karena membantunya berkembang adalah bagian dari pekerjaan saya.",
  str_voice_1601891_21 = "Saya mengagumi kepraktisan Illumina. Tapi saya tidak setuju dengan penekanan mereka pada disiplin di atas keadilan.",
  str_voice_1601891_22 = "Demi White Night!",
  str_voice_1601891_23 = "Eclipsites tampaknya ada hanya untuk menyerang Aurorian. Itu membuat mereka musuhku.",
  str_voice_1601891_24 = "Tina butuh banyak tidur, tapi dia mengerjakan pekerjaannya dengan serius. Itu cukup baik untukku.",
  str_voice_1601891_25 = "Brock... Saya sangat berterima kasih padanya, tetapi saya juga sangat tidak ingin melihatnya lagi.",
  str_voice_1601891_26 = "Ketika saya bebas, saya suka menyirami bunga saya, memperbaiki jam antik, membuat makanan enak... Ah, saat-saat bahagia.",
  str_voice_1601891_27 = "Saya tidak tahan dengan ketidakadilan... atau cabai yang bersembunyi di salad.",
  str_voice_1601891_28 = "Colossus adalah konstruksi misterius... Meskipun menurutku itu seperti anggota keluarga bagimu.",
  str_voice_1601891_29 = "Selamat tinggal. Saya Leyn, seorang hakim Lumopolis. Saya akan terus memperjuangkan keadilan bahkan di sini. Saya harap Anda akan memaafkan jika saya menyebabkan pelanggaran.",
  str_voice_1601891_30 = "Selangkah demi selangkah.",
  str_voice_1601891_31 = "Kerja keras terbayar.",
  str_voice_1601891_32 = "Saya tahu bagaimana membuat kemajuan sekarang!",
  str_voice_1601891_33 = "Ini di sini, adalah tekad saya.",
  str_voice_1601891_34 = "Aku paham.",
  str_voice_1601891_35 = "Saya selalu siap.",
  str_voice_1601891_36 = "Untukmu, untuk keadilan.",
  str_voice_1601891_37 = "Ini semua yang saya punya!",
  str_voice_1601891_38 = "Robek kegelapan!",
  str_voice_1601891_39 = "Tidak ada jalan keluar!",
  str_voice_1601891_40 = "Terimalah hukumanmu!",
  str_voice_1601891_41 = "Serahkan ini padaku.",
  str_voice_1601891_42 = "Kita menang! Silakan periksa rampasannya.",
  str_voice_1601891_43 = "Kembali! Aku akan memegang bagian belakang!",
  str_voice_1601891_44 = "Saya siaga. Apakah Anda punya pesanan?",
  str_voice_1601891_45 = "Anda tidak harus...",
  str_voice_1601891_46 = "O-Oke. Terima kasih...",
  str_voice_1601891_47 = "Hadiah lain? Ini terlalu banyak...",
  str_voice_1601891_48 = "Terima kasih... Terima kasih.",
  str_voice_1601891_49 = "Masa kecilku... tidak bahagia. Saya masih tidak tahu bagaimana menghadapi orang tua saya. Jadi saya melarikan diri dan bergabung dengan tentara. Ketika sampai pada itu, saya benar-benar hanyalah seorang pengecut.",
  str_voice_1601891_50 = "Saya menyukai kehidupan tentara, tetapi menemukan semua politik dan hubungan sulit dinavigasi. Dan saat itu, saya tidak memiliki kepercayaan diri untuk mengubah banyak hal. Mungkin saya beruntung bisa bertemu Brock.",
  str_voice_1601891_51 = "Dulu Brock yang membantu saya mengubah cara berpikir saya, menjadi lebih proaktif. Saya bekerja keras untuk menjadi hakim, dan kemudian bermitra dengan Tina. Dan tentu saja, saya juga di sini untuk menemani Anda dalam perjalanan.",
  str_voice_1601891_52 = "Alchemy Stars!",
  str_voice_1601891_53 = "Halo.",
  str_voice_1601891_54 = "Selamat pagi.",
  str_voice_1601891_55 = "Selamat sore.",
  str_voice_1601891_56 = "Selamat malam.",
  str_voice_1601891_57 = "Selamat tahun baru! Saya berharap untuk terus berada dalam perawatan Anda di tahun mendatang. Siapa yang mengira aku akan mengatakan hal seperti itu?",
  str_voice_1501901_1 = "Apa yang kamu kenakan di dunia ini? Lupakan saja, aku tidak bisa berharap terlalu banyak darimu. Rasa adalah kombinasi dari alam dan pengasuhan, dan jelas Anda tidak memiliki keduanya.",
  str_voice_1501901_2 = "Saya tidak meneruskan pekerjaan saya ke Pittman karena kemalasan. Itu karena aku tidak bisa mematuhi tugas-tugas yang melelahkan itu. Waktu saya lebih baik dihabiskan untuk belajar dan refleksi.",
  str_voice_1501901_3 = "Tentu saja saya tidak membenci orang biasa. Heheh... tapi aku tidak bisa menyukai semua orang, bukan? Menyukai semua orang sama dengan tidak menyukai siapa pun.",
  str_voice_1501901_4 = "Bahkan seorang bangsawan pun tidak akan mendapatkan persetujuan saya jika mereka tidak kompeten. Saya hanya menyukai mereka yang memiliki kemampuan asli. Selama mereka bukan orang biasa, tentu saja.",
  str_voice_1501901_5 = "Saya suka hal-hal yang indah. Semua orang bilang kecantikan tidak sepenting bakat, tapi aku cukup beruntung memiliki keduanya.",
  str_voice_1501901_6 = "Jujur saya percaya bahwa mencapai kesuksesan melalui kerja keras adalah hal yang paling mulia. Betapa malangnya saya bisa sukses meski tanpa kerja keras.",
  str_voice_1501901_7 = "Anehnya, saya menemukan diri saya berpikir Anda memiliki selera yang baik. Aku pasti mengalami sesuatu yang memengaruhi kecerdasanku.",
  str_voice_1501901_8 = "Anda punya terlalu banyak pekerjaan dan Anda tidak bisa menyelesaikannya? Di sini, saya akan menunjukkan kepada Anda apa yang harus dilakukan. Lihatlah jauh ke dalam diri Anda dan tanyakan: kepada siapa saya dapat membuang pekerjaan ini?",
  str_voice_1501901_9 = "Siapa yang memberitahumu aku mengenakan pakaian perempuan saat kecil? J-Jangan berani mengungkit itu lagi! Anda benar-benar ingin tahu? Itu semua karena ibuku... kau tahu maksudku...",
  str_voice_1501901_10 = "Kita bertemu lagi, aku sangat gembira. ...Apa? Apakah senyumku terlalu palsu?",
  str_voice_1501901_11 = "Anda hanya ingin melihat saya sepanjang waktu, ya? Tch, jika Anda harus. Ayo, manjakan matamu dengan wajah muliaku.",
  str_voice_1501901_12 = "Saya tidak bisa mengatakan dengan pasti apakah uang bisa membeli kebahagiaan. Tapi saya punya uang dan saya bahagia.",
  str_voice_1501901_13 = "Jalan menuju sukses itu sulit, membutuhkan kemajuan selangkah demi selangkah—untuk Anda, maksud saya. Saya naik kereta.",
  str_voice_1501901_14 = "Hei, aku sedang berbicara denganmu. Anda harus merasa terhormat. Balas, sekarang.",
  str_voice_1501901_15 = "Jadi orang Caelest punya hari ulang tahun juga? Betapa menariknya... maka saya memberi Anda kehormatan atas ucapan selamat saya.",
  str_voice_1501901_16 = "Panas sekali! Kami para bangsawan tidak boleh mencium bau keringat. Aku akan mandi.",
  str_voice_1501901_17 = "Menikmati aroma tetesan embun di pagi hari baik untuk pikiran. Bukan berarti Anda akan mengerti.",
  str_voice_1501901_18 = "Harta sejati akan bersinar bahkan dalam kegelapan. Tidak heran aku tidak bisa melihatmu di malam hari.",
  str_voice_1501901_19 = "Beraninya kamu tidak bisa tidur pada waktu yang sama denganku? Aku benci gagasan kita memiliki kesamaan!",
  str_voice_1501901_20 = "Para bangsawan mewujudkan keadilan, Lumopolis mendominasi dunia.",
  str_voice_1501901_21 = "Apa? Faksi lain ada di dunia ini selain para bangsawan?",
  str_voice_1501901_22 = "Demi White Night!",
  str_voice_1501901_23 = "Seribu mandi tidak bisa membersihkan bau Eclipsite.",
  str_voice_1501901_24 = "Saya tidak akan mengatakan itu Irridon adalah teman yang baik, tapi dia salah satu dari sedikit orang yang layak saya hormati.",
  str_voice_1501901_25 = "Pittman antusias, memiliki rasa keadilan yang kuat, dan sangat berguna bagi saya.",
  str_voice_1501901_26 = "Bahkan objek yang paling biasa pun menjadi lebih menarik saat dihias dengan permata hijau.",
  str_voice_1501901_27 = "Aduh, kotor. Disinfeksi benda ini!",
  str_voice_1501901_28 = "Ini adalah tempat yang indah. Untuk tetap seperti itu, saya dengan ini melarang orang biasa untuk masuk.",
  str_voice_1501901_29 = "Saya Matthieu, hakim termuda dalam sejarah. Saya memiliki selera terbaik dan bakat tanpa dasar. Sembahlah aku jika kamu mau, tapi jangan berharap kita akan menjadi teman.",
  str_voice_1501901_30 = "Saya kuat.",
  str_voice_1501901_31 = "Permata berkilau.",
  str_voice_1501901_32 = "Namun lebih indah.",
  str_voice_1501901_33 = "Aku adalah cahaya!",
  str_voice_1501901_34 = "Anda mungkin bersorak.",
  str_voice_1501901_35 = "Cahaya telah turun.",
  str_voice_1501901_36 = "Lihatlah kemuliaan keluargaku.",
  str_voice_1501901_37 = "Cahaya suci!",
  str_voice_1501901_38 = "Rasakan retakan cambuk!",
  str_voice_1501901_39 = "Saya menemukan Anda bersalah!",
  str_voice_1501901_40 = "Tunduk pada hukum!",
  str_voice_1501901_41 = "Aku dibutuhkan lagi?",
  str_voice_1501901_42 = "Saya terbiasa dengan kemenangan.",
  str_voice_1501901_43 = "Mustahil…",
  str_voice_1501901_44 = "Colossus itu luar biasa. Akan lebih baik jika hanya bangsawan yang tinggal di dalamnya.",
  str_voice_1501901_45 = "Anda menyebut ini hadiah?",
  str_voice_1501901_46 = "Aku meremehkanmu.",
  str_voice_1501901_47 = "Rasa yang luar biasa.",
  str_voice_1501901_48 = "Saya akan menerimanya.",
  str_voice_1501901_49 = "Keluarga saya merancang pakaian mewah. Pakaian membuat pria, kata mereka, dan pria yang lebih biasa, semakin benar. Anda adalah contoh.",
  str_voice_1501901_50 = "Itu benar, saya adalah Dawn Keajaiban anak akademi yang legendaris. Saya menjadi asisten guru pada usia sepuluh tahun dan menjadi juri termuda pada usia lima belas tahun. Jangan ragu untuk bersorak dan bertepuk tangan.",
  str_voice_1501901_51 = "Kerja, yah, tidak ada yang menantangku. Satu-satunya hal yang mengganggu adalah pasangan saya itu ...",
  str_voice_1501901_52 = "Alchemy Stars.",
  str_voice_1501901_53 = "Hei!",
  str_voice_1501901_54 = "Sungguh hari yang sempurna untuk tidak bekerja sama sekali.",
  str_voice_1501901_55 = "Tidak berkeringat hari ini.",
  str_voice_1501901_56 = "Tidak ada yang lebih baik daripada mandi.",
  str_voice_1501901_57 = "Anehnya, perayaan tahun baru bahkan membuat Anda tampak lebih tampan.",
  str_voice_1601484_10 = "Menguap... aku lelah. Aku akan tidur siang. Jika ada klien yang datang, datang dan jemput aku. Dan jika aku menangkapmu bermalas-malasan... kau tahu apa yang akan terjadi.",
  str_voice_1601484_11 = "Orang tua saya pernah memberi tahu saya bahwa pemburu yang baik unggul dalam kamuflase dan kesabaran. Itu sebabnya saya harus berpakaian seperti ini dan menunggu di sini. Tapi itu membosankan.",
  str_voice_1601484_16 = "Klien kami hampir tiba. Fokus, atau aku tidak akan bertanggung jawab jika peluru menyerempet pipimu.",
  str_voice_1601484_17 = "Bagaimana saya harus menghukum Anda karena terlambat? Hmm... Mungkin aku harus menggunakanmu sebagai kursi?",
  str_voice_1601484_18 = "Oke, saatnya mengakhiri hari ini. Mengapa Anda terburu-buru? Punya kencan panas menunggumu?",
  str_voice_1601484_19 = "Saya, apa yang Anda lakukan di sini saat ini? Apakah Anda datang menemui saya?",
  str_voice_1601484_35 = "Anda tahu apa yang harus dilakukan, bukan?",
  str_voice_1601484_36 = "Hati-hati, sungguh-sungguh...",
  str_voice_1601484_37 = "Blokade di tempat!",
  str_voice_1601484_38 = "Tidak ada jalan keluar!",
  str_voice_1601484_39 = "Jangan bergerak.",
  str_voice_1601484_40 = "Ini tidak akan sakit.",
  str_voice_1601484_44 = "Pergilah bersamaku di pekerjaanku selanjutnya.",
  str_voice_1601484_1 = "Saya tidak suka menghabiskan waktu terlalu lama di satu tempat. Jadi agensi ini, hanya untuk bersenang-senang.",
  str_voice_1601484_2 = "Semakin banyak saya minum, semakin baik tembakan saya. Ingin melihat sendiri? Hebat, berdiri di sana dan taruh kaleng ini di kepalamu.",
  str_voice_1601484_3 = "Senjata ini tidak sebagus Eye of the Lynx, tapi tidak buruk. Saya akan membiarkan Anda bermain dengannya ketika saya selesai di sini. Apakah kamu tidak mau?",
  str_voice_1601484_12 = "Bagian atas ini agak ketat, jadi saya membuka beberapa kancing. Apa? Mengapa tidak? Ayo, jelaskan dengan hati-hati, atau bagaimana saya bisa mengerti?",
  str_voice_1601484_13 = "Saat bertukar intel, Anda perlu mengetahui nilai dari apa yang Anda miliki. Tentu saja, memiliki senjata membantu.",
  str_voice_1601484_14 = "Hmm. Oke, Anda tahu cara memenangkan hati saya. Anda hampir tidak memenuhi syarat untuk melayani sebagai asisten saya. Jika Anda berusaha lebih keras, saya bahkan mungkin akan membalas Anda.",
  str_voice_1601484_58 = "Waktunya bangun! Itu terlambat!",
  str_voice_1601484_59 = "Mau pergi jalan-jalan?",
  str_voice_1601484_60 = "Pekerjaan di agensi secara mengejutkan menghibur.",
  str_voice_1601484_61 = "Apa yang harus kita makan untuk makan siang?",
  str_voice_1601484_62 = "Siang yang panas.",
  str_voice_1601484_63 = "Saya bosan. Sesuatu yang menarik terjadi?",
  str_voice_1601484_64 = "Kenapa kita tidak minum?",
  str_voice_1601484_65 = "Apakah kamu masih terjaga, Caelestite kecil?",
  str_voice_1601484_66 = "Malam. Apa yang sedang kamu pikirkan?",
  str_voice_1601484_67 = "Saya melakukan segalanya dengan cara saya sendiri, bahkan bekerja. Hidup membosankan sebaliknya.",
  str_voice_1601484_68 = "Minuman kecil membuat segalanya lebih baik.",
  str_voice_1601484_69 = "Heheh. Tentunya Anda tahan sedikit menggoda?",
  str_voice_1601484_70 = "Saya hanya punya satu tujuan: melindungi keluarga yang saya temukan.",
  str_voice_1601484_71 = "Astaga. Aku pikir aku mungkin jatuh cinta padamu.",
  str_voice_1601911_1 = "Kadang-kadang potongan ingatan sekilas melintas di benak saya, bertahan hanya selama beberapa detik — tidak mungkin untuk dipahami, apalagi dipertahankan. Seperti kembang api, mereka melambung dan meledak, lalu menghilang tanpa jejak.",
  str_voice_1601911_2 = "Aku bukan anjing liar! Aku bukan monster! Saya — Maaf, saya baru saja mengalami mimpi buruk.",
  str_voice_1601911_3 = "Saya sengaja bersembunyi di sudut di pesta, sebagian besar karena kemalasan — bersosialisasi itu membosankan. Tapi aku tahu ada seseorang yang tertarik padamu. Apakah kamu tidak menyadarinya? Lupakan saja, Anda akan merasakannya sendiri, pada akhirnya.",
  str_voice_1601911_4 = "Saya membutuhkan kekuatan mental untuk mengendalikan api saya dengan benar. Anda mampu mengarahkan semua orang dalam pertempuran sepanjang waktu, saya membayangkan pikiran Anda pasti sangat kuat.",
  str_voice_1601911_5 = "Dunia ini menyimpan terlalu banyak kedengkian. Saya telah melihat dan mengalami begitu banyak hal yang tidak dapat dipercaya—hal-hal yang mengajari saya bahwa dunia memiliki bagian kegelapan yang adil.",
  str_voice_1601911_6 = "Tentu, beberapa ingatan memang menyakitkan, tetapi saya tidak terburu-buru untuk melupakannya. Jika Anda menyatukan potongan-potongan itu dan mencari akal di tengah kekacauan, Anda mungkin menemukan jawaban yang Anda cari.",
  str_voice_1601911_7 = "Bahkan jika saya terlihat berbeda dari kebanyakan orang, saya memikirkan dan merasakan hal yang sama seperti orang lain. Saya percaya bahwa mungkin Anda dapat memahami saya karena Anda dan saya memiliki aroma yang sama.",
  str_voice_1601911_8 = "Aku punya hadiah untukmu. Saya membuat sendiri lampu yang lambat menyala ini—hanya ada sedikit kayu bakar di dalamnya, tetapi saya harap lampu ini dapat memberi Anda sedikit cahaya dan kehangatan dalam kegelapan.",
  str_voice_1601911_9 = "Jangan khawatir, telingaku sudah sembuh, kamu bisa menyentuhnya... Tidak apa-apa, aku cukup suka disentuh olehmu.",
  str_voice_1601911_10 = "Aku merasa sedikit bosan hari ini. Mengapa kita tidak bermain petak umpet? Apakah Anda tahu cara bermain? Aku bisa mengajarimu, jika kau mau. Oh, kau tahu? Itu luar biasa! Saya juga baru belajar kemarin.",
  str_voice_1601911_11 = "Apa pun yang Anda butuhkan untuk keluar dan lakukan, ketahuilah bahwa saya akan ada di sana untuk melindungi Anda. Di mana pun atau kapan pun, aku akan selalu ada, setiamu Hati.",
  str_voice_1601911_12 = "Aku terbiasa melakukan sesuatu sendiri, tapi setelah bertemu denganmu, aku merasa punya pasangan juga tidak terlalu buruk. Memiliki Anda membantu saya keluar tidak merasa terlalu mengganggu.",
  str_voice_1601911_13 = "Seorang anak yang hilang menyalakan api untuk mencari ingatan yang hilang, tetapi tidak menyadari bahwa nyala api yang paling redup pun dapat menyalakan api yang membakar dunia.",
  str_voice_1601911_14 = "Saya percaya pada intuisi saya sendiri lebih dari saya percaya pada aturan masyarakat. Aturan selalu memperumit masalah, itulah mengapa saya yakin naluri dapat membantu kita menemukan jawaban lebih cepat.",
  str_voice_1601911_15 = "Selamat ulang tahun! Bagaimana kalau kita mengadakan barbekyu besar berisi daging?",
  str_voice_1601911_16 = "Jika ada sesuatu yang ingin Anda lakukan, silakan saja dan lakukan. Jangan bertele-tele.",
  str_voice_1601911_17 = "Cobalah bangun pagi dan berjemur di bawah sinar matahari. Itu akan membuat seluruh tubuh Anda terasa begitu hangat dan nyaman.",
  str_voice_1601911_18 = "Apakah Anda memiliki rebusan untuk makan malam? Makan lebih banyak daging dan Anda akan memiliki lebih banyak kekuatan untuk menghadapi kehidupan secara langsung.",
  str_voice_1601911_19 = "Mari habiskan malam yang damai dengan duduk di dekat perapian.",
  str_voice_1601911_20 = "Umbraton adalah tempat yang sangat kompleks. Meskipun sering terlihat seperti hanya diisi dengan sudut-sudut gelap, terkadang ada juga sinar cahaya.",
  str_voice_1601911_21 = "Lumopolis adalah tempat tergelap di dunia. Saya membencinya.",
  str_voice_1601911_22 = "Bayangan mengawasimu.",
  str_voice_1601911_23 = "Eclipsites sama menjijikkannya dengan para bangsawan Lumopolis.",
  str_voice_1601911_24 = "Grimme selalu mengoceh tentang ini atau itu, tapi mereka tidak buruk karena mereka mau mengobrol dengan siapa pun.",
  str_voice_1601911_25 = "Saya kira Anda bisa mengatakannya Istvan seperti wali saya. Tanpa dia, saya mungkin tidak akan menjadi seperti sekarang ini.",
  str_voice_1601911_26 = "Apakah Anda punya surat kabar baru? Saya sudah memecahkan semua teka-teki yang satu ini!",
  str_voice_1601911_27 = "Bolehkah saya melewatkan sayuran hari ini? Terutama kubis merah—sangat menjijikan...",
  str_voice_1601911_28 = "Jadi, ternyata memang ada tempat di dunia yang penuh cahaya dan kehangatan...",
  str_voice_1601911_29 = "Jangan biarkan penampilanku membuatmu takut. Jangan menjauhiku hanya karena penampilanku. Aku hanyalah seorang Aurorian biasa—namaku Hati. Jika tidak apa-apa denganmu, mari berteman.",
  str_voice_1601911_30 = "Menyala!",
  str_voice_1601911_31 = "Aku lebih kuat sekarang!",
  str_voice_1601911_32 = "Biarkan semuanya terbakar.",
  str_voice_1601911_33 = "Api biru menyala selamanya.",
  str_voice_1601911_34 = "Kamu dapat mempercayaiku.",
  str_voice_1601911_35 = "Api biru berkedip-kedip.",
  str_voice_1601911_36 = "Anda ingin dicabik-cabik?",
  str_voice_1601911_37 = "Api menyebar!",
  str_voice_1601911_38 = "Ini dia!",
  str_voice_1601911_39 = "Jiwa berkobar biru!",
  str_voice_1601911_40 = "Hancurkan dan bakar!",
  str_voice_1601911_41 = "Kau pasti bisa!",
  str_voice_1601911_42 = "Aroma manis kemenangan!",
  str_voice_1601911_43 = "Ini... menyebalkan.",
  str_voice_1601911_44 = "Saya mendapatkan perasaan ini, seperti tidak ada hal buruk yang bisa terjadi di sini, hanya hal-hal baik.",
  str_voice_1601911_45 = "Mm, Anda bisa meninggalkannya di sini.",
  str_voice_1601911_46 = "Hadiah yang luar biasa.",
  str_voice_1601911_47 = "Saya harus mengatakan ... terima kasih.",
  str_voice_1601911_48 = "Ini hadiah yang luar biasa, terima kasih.",
  str_voice_1601911_49 = "Saya tidak pernah bertemu ayah saya... Dia meninggal sebelum saya lahir, hanya menyisakan liontin ini, satu-satunya kenang-kenangan saya tentang dia.",
  str_voice_1601911_50 = "Saya ingat ibu saya selalu sangat cemas dan sibuk, dan saya selalu berusaha mendapatkan lebih banyak perhatian darinya. Melihat ke belakang sekarang, aku sangat kekanak-kanakan. Aku bertaruh semua orang dewasa tidak tahan denganku...",
  str_voice_1601911_51 = "Saya tidak punya banyak teman. Mungkin karena penampilanku. Saya tidak pernah mencoba melakukan hal buruk kepada siapa pun, tetapi nasib buruk sepertinya mengikuti saya.",
  str_voice_1601911_52 = "Alchemy Stars.",
  str_voice_1601911_53 = "Anda di sini juga, ya?",
  str_voice_1601911_54 = "Gores, garuk... Hei, bangun.",
  str_voice_1601911_55 = "Bisakah kita makan sup daging untuk makan siang?",
  str_voice_1601911_56 = "Apakah Anda memiliki makan malam yang baik?",
  str_voice_1601911_57 = "Saya berharap sesuatu yang benar-benar berkesan terjadi di tahun baru.",
  str_voice_1501931_1 = "Hmm-hmm-hmm! Melodi dadakan memang yang paling indah dan tak terkekang dari semuanya. Tidak peduli berapa kali dinyanyikan, melodi yang ditulis pada partitur musik selalu sama.",
  str_voice_1501931_2 = "Berkat tombak inilah saya bisa menghukum penjahat dengan teguh.",
  str_voice_1501931_3 = "Keluarga saya memiliki manor di seluruh dunia. Apakah Anda ingin pergi berlibur dengan saya? Ah... tapi hanya setelah masa percobaanku berakhir, tentu saja!",
  str_voice_1501931_4 = "Saya harus merawat tombak ini secara khusus agar dapat menjaga ketajamannya setiap saat.",
  str_voice_1501931_5 = "Air dapat menciptakan musik yang paling indah. Dalam suara jernih dari alirannya yang lembut, semua keraguan menghilang.",
  str_voice_1501931_6 = "Bernyanyi di tengah air pasang! Biarkan kekuatannya yang melonjak membimbing setiap orang percaya yang bebas ke sisi lain dari gelombang baru!",
  str_voice_1501931_7 = "Saya bisa memainkan banyak instrumen, tapi... hanya sebagai seorang amatir. Mana yang menurut Anda lebih cocok untuk saya, kehidupan seorang musisi atau hakim?",
  str_voice_1501931_8 = "Saya mengagumi gaya hidup Anda, hidup bebas dan tak terkekang. Mungkin suatu hari, saya bisa melakukan perjalanan ke penjuru dunia seperti Anda.",
  str_voice_1501931_9 = "Saya sangat mencintai dan menghormati orang tua saya, tetapi itu tidak berarti saya bersedia menjalani kehidupan yang mereka atur untuk saya. Setidaknya untuk saat ini, saya belum menyesali pilihan saya.",
  str_voice_1501931_10 = "Hmm, tiba-tiba aku tidak ada hubungannya, dan secara mengejutkan merasa... bingung.",
  str_voice_1501931_11 = "Anda memiliki tugas baru untuk saya? Hah? Anda hanya ingin saya tinggal di sini? Hehe, kurasa berada di dekatmu juga merupakan pekerjaan yang penting!",
  str_voice_1501931_12 = "Meskipun saya menangani kasus-kasus yang saya tangani sesuai dengan pedoman yang ditemukan di buku-buku yang paling dapat diandalkan, saya tidak dapat menyelesaikan setiap masalah. Memang, sepertinya saya masih harus banyak belajar!",
  str_voice_1501931_13 = "Kalau dipikir-pikir, aku sudah lama tidak menonton musikal. Kira-kira, apakah ada produksi baru yang populer akhir-akhir ini?",
  str_voice_1501931_14 = "Kenapa kau menatapku? Apa pakaianku terlalu berantakan...? Hmm, sepertinya tidak ada masalah. Mungkin saya benar-benar terlalu tegang, tolong, jangan pedulikan saya.",
  str_voice_1501931_15 = "Selamat ulang tahun! Saya sendiri yang membuat melodinya... Apakah Anda menyukainya?",
  str_voice_1501931_16 = "Apakah Anda membutuhkan bantuan saya? Saya harus menyelesaikan kasus ini terlebih dahulu. Silakan tunggu beberapa saat!",
  str_voice_1501931_17 = "Bersiaplah untuk hari yang baru! Matahari bersinar di kepala Anda! Jika Anda tidak bangun sekarang, seekor burung dapat membuat sarang di atasnya!",
  str_voice_1501931_18 = "Ah, ini adalah waktu paling santai hari ini. May Saya memainkan musik untuk Anda?",
  str_voice_1501931_19 = "Ini sangat terlambat! Apakah ada sesuatu yang mendesak yang ingin Anda tanyakan kepada saya? Hmm? Maksudmu... kau hanya lapar?",
  str_voice_1501931_20 = "Beberapa bangsawan Lumopolis percaya bahwa mereka tidak boleh berinteraksi dengan rakyat jelata. Namun, saya yakin ini adalah ide yang sepenuhnya arogan.",
  str_voice_1501931_21 = "Umbraton sangat berbeda dari Lumopolis, tapi saya rasa saya menyukainya.",
  str_voice_1501931_22 = "Demi White Night.",
  str_voice_1501931_23 = "The Eclipsites adalah lambang kekacauan. Mereka semua telah melakukan beberapa bentuk kekejaman.",
  str_voice_1501931_24 = "Zenas mengajariku cara bertarung. Sebagai seorang instruktur, dia tidak dapat disangkal adalah orang yang patut dikagumi.",
  str_voice_1501931_25 = "Matthieu terkadang mengarahkan pandangannya ke arahku secara tiba-tiba. Mungkinkah melodi yang kunyanyikan memiliki efek yang begitu mendalam padanya?",
  str_voice_1501931_26 = "Saya suka benda berbentuk persegi—bisa ditumpuk dengan sangat rapi, dan sensasi ini sangat menenangkan!",
  str_voice_1501931_27 = "Penjahat adalah makhluk paling menjijikkan di dunia, dan itulah mengapa saya ingin bertindak atas nama keadilan.",
  str_voice_1501931_28 = "Colossus memang spektakuler, tetapi tidakkah orang merasa kesepian berada di sini sendirian?",
  str_voice_1501931_29 = "Nama saya adalah Kristen, dan sebagai hakim percobaan, saya sedang dalam proses mempelajari metode kerja yang lebih efektif setiap hari. Tentu saja, jika ada kasus yang tidak terduga muncul, Anda juga dapat meminta bantuan saya.",
  str_voice_1501931_30 = "Apakah Anda berharap saya menjadi lebih kuat?",
  str_voice_1501931_31 = "Arus bawah meningkat.",
  str_voice_1501931_32 = "Fajar akhirnya akan datang—",
  str_voice_1501931_33 = "Biarkan torrent membawa Anda!",
  str_voice_1501931_34 = "Siap dan menunggu!",
  str_voice_1501931_35 = "Tombak saya dipoles dan siap.",
  str_voice_1501931_36 = "Ingin menguji kekuatan tombakku?",
  str_voice_1501931_37 = "Melawan arus!",
  str_voice_1501931_38 = "Jerami melolong, mengalir!",
  str_voice_1501931_39 = "Menari dengan ombak!",
  str_voice_1501931_40 = "Lonjakan!",
  str_voice_1501931_41 = "Air akan menghilangkan semua rintangan.",
  str_voice_1501931_42 = "Keadilan berkuasa penuh kemenangan!",
  str_voice_1501931_43 = "Aku sudah sedikit libur, baru-baru ini...",
  str_voice_1501931_44 = "Tolong bagikan beberapa cerita menarik tentang Colossus dengan saya! Saya akan mendengarkan dengan cermat setiap kata!",
  str_voice_1501931_45 = "Terima kasih. Ini adalah hadiah yang sangat bagus.",
  str_voice_1501931_46 = "Persis seperti yang saya inginkan. Terima kasih.",
  str_voice_1501931_47 = "Hadiah ini benar-benar dari hati. Saya akan selalu menghargainya.",
  str_voice_1501931_48 = "Aku menyukainya! Bagaimana saya bisa berterima kasih?",
  str_voice_1501931_49 = "Pelatih vokal saya percaya bahwa saya dikaruniai suara yang bagus dan pasti akan menjadi penyanyi terkenal suatu hari nanti. Namun, saya tidak tahan dengan latihan yang kaku seperti itu, saya juga tidak menikmati lagu yang diulang-ulang.",
  str_voice_1501931_50 = "Ketika saya di akademi, saya sering menyelesaikan konflik antara teman sekelas saya. Lambat laun, saya menjadi \"perantara\" di mata semua orang.",
  str_voice_1501931_51 = "Setelah lulus, saya berhasil menjadi hakim percobaan. Meskipun pekerjaannya lebih sulit dari yang saya harapkan, saya akan terus bekerja keras!",
  str_voice_1501931_52 = "Alchemy Stars!",
  str_voice_1501931_53 = "Halo!",
  str_voice_1501931_54 = "Selamat pagi! Bagaimana tidurmu tadi malam?",
  str_voice_1501931_55 = "Selamat siang. Ini hari yang menyenangkan, bukan?",
  str_voice_1501931_56 = "Pekerjaan hari ini akhirnya selesai!",
  str_voice_1501931_57 = "Selamat tahun baru. Saya berharap kita semua dapat menuai hasil yang lebih besar lagi di tahun mendatang.",
  str_voice_1601921_1 = "Gunakan pedangmu untuk memperluas perbatasan, gunakan tanganmu untuk menghibur hati orang-orang. Sayangnya, beberapa percaya sebaliknya.",
  str_voice_1601921_2 = "Saya terbiasa memakai panji pasukan kami ke medan perang. Selama para kesatriaku masih bisa melihatku berdiri di medan perang, mereka tahu bahwa kemenangan sudah dekat.",
  str_voice_1601921_3 = "Colossus benar-benar luar biasa. Mungkin ia pantas mendapatkan panjinya sendiri untuk menunjukkan kepada dunia kemuliaan dan kekuatannya.",
  str_voice_1601921_4 = "Jika Anda memiliki pertanyaan tentang kehidupan di medan perang, jangan ragu untuk bertanya kepada saya. Seseorang tidak boleh takut untuk menerima bimbingan—untuk tumbuh, Anda membutuhkan seorang mentor yang melihat potensi sejati Anda.",
  str_voice_1601921_5 = "Sekedar mengingatkan untuk mengecek persediaan di Colossus secara rutin. Anda tidak pernah tahu apa yang bisa terjadi.",
  str_voice_1601921_6 = "Tujuan saya selalu jelas. Saya ingin menjadi ksatria teladan yang melindungi rakyat dan memperjuangkan perdamaian.",
  str_voice_1601921_7 = "Bangun dengan leher kaku? Biarkan aku membantumu. Baiklah, selesai. Jangan khawatir tentang itu! Aku bahkan telah menghisap racun dari luka teman-temanku lebih dari satu kali!",
  str_voice_1601921_8 = "Ah, mata yang polos... Kamu terlihat seperti beberapa anak buahku, yang tentu saja membuatku ingin melindungimu. Namun, saya tidak akan melakukannya, karena Anda harus tumbuh sendiri. Hati-Hati! Jaga matamu di jalan!",
  str_voice_1601921_9 = "Jika saya membuat kesalahan, tolong beritahu saya terus terang. Tidak ada yang harus tabu di antara teman. Hanya melalui komunikasi yang jujur persahabatan kita bisa menjadi lebih kuat.",
  str_voice_1601921_10 = "Saat menghadapi kesulitan, jangan ragu untuk mencari bantuan saya. Saya memiliki banyak kebijaksanaan dan keberanian.",
  str_voice_1601921_11 = "Anda ingin menempatkan saya di sini? Tidak masalah! Percayalah, tidak ada satu kesalahan pun yang akan dibuat.",
  str_voice_1601921_12 = "Masalah apa yang menimpa Anda? Saya akan melakukan yang terbaik untuk membantu Anda menyelesaikannya. Oh, bajumu robek. Serahkan padaku. Saya sering membantu menjahit pakaian ksatria saya.",
  str_voice_1601921_13 = "Mempelajari keterampilan baru adalah hal yang terpuji. Jangan pernah takut untuk gagal. Selama Anda bertekad dan terus gigih, Anda pasti akan berhasil.",
  str_voice_1601921_14 = "Kemenangan tidak sulit diraih. Raih kelemahan musuh Anda dan gunakan untuk melawan mereka.",
  str_voice_1601921_15 = "May masa depan Anda dipenuhi dengan kreativitas dan keajaiban.",
  str_voice_1601921_16 = "Bagaimana pekerjaan hari ini berkembang? Apakah Anda membutuhkan bantuan saya?",
  str_voice_1601921_17 = "Sudahkah Anda mengatur rencana Anda untuk hari ini? Saya harap Anda memiliki segalanya di bawah kendali.",
  str_voice_1601921_18 = "Sudahkah Anda menyelesaikan semuanya untuk hari ini?",
  str_voice_1601921_19 = "Itu terlambat. Istirahatlah dengan baik, dan jangan biarkan kelelahan memengaruhi efisiensi Anda.",
  str_voice_1601921_20 = "Lumopolis dijadwalkan untuk beberapa perubahan.",
  str_voice_1601921_21 = "Illumina memiliki beberapa tentara yang mungkin cukup baik untuk bergabung dengan Ironthorn Knights.",
  str_voice_1601921_22 = "Ksatria Ironthorn!",
  str_voice_1601921_23 = "Berjuang untuk memusnahkan semua Eclipsites, sampai nafas terakhirmu.",
  str_voice_1601921_24 = "Joseph adalah teladan belas kasih dan toleransi dan merupakan jembatan penting antara Benteng Lumo dan rakyat jelata.",
  str_voice_1601921_25 = "Wanita Carleen berbeda dari para bangsawan yang rusak itu. Suatu hari, cahayanya yang murni dan benar akan menyinari Lumopolis.",
  str_voice_1601921_26 = "Senjata yang andal membuat semua perbedaan dalam pertempuran.",
  str_voice_1601921_27 = "Mata serakah memandang dunia hanya pada nilai permukaan, dan buta terhadap keindahan yang ada di dalamnya.",
  str_voice_1601921_28 = "Luar biasa dan indah, ini adalah karya keajaiban.",
  str_voice_1601921_29 = "Kapten Leo dari Ironthorn Knights, atas perintah Anda. Dalam pertempuran, ketenangan dan ketegasan adalah kunci kemenangan. Saya harap Anda tidak akan mengecewakan saya.",
  str_voice_1601921_30 = "Potensi tanpa batas.",
  str_voice_1601921_31 = "Jangan pernah menyerah.",
  str_voice_1601921_32 = "Jangan pernah ragu.",
  str_voice_1601921_33 = "Saya tidak bisa dihancurkan.",
  str_voice_1601921_34 = "Menyerang.",
  str_voice_1601921_35 = "Bersiap untuk bertempur.",
  str_voice_1601921_36 = "Aku siap kapan pun kau siap.",
  str_voice_1601921_37 = "Pukulan mematikan!",
  str_voice_1601921_38 = "Pedangku seperti kilat!",
  str_voice_1601921_39 = "Muatan kekuatan penuh!",
  str_voice_1601921_40 = "Dominasi total!",
  str_voice_1601921_41 = "Ikuti perintah saya.",
  str_voice_1601921_42 = "Pertempuran yang memuaskan.",
  str_voice_1601921_43 = "Tetap tenang.",
  str_voice_1601921_44 = "Saya ingin melindungi tempat ini.",
  str_voice_1601921_45 = "Permainan yang bagus.",
  str_voice_1601921_46 = "Anda punya selera.",
  str_voice_1601921_47 = "Terima kasih atas hadiahmu.",
  str_voice_1601921_48 = "Anda mengenal saya dengan baik.",
  str_voice_1601921_49 = "Meskipun saya pernah menjadi anggota bangsawan Lumopolis, pada kenyataannya, saya tidak pernah menjadi bangsawan sejati, bahkan sebelum saya dibuang.",
  str_voice_1601921_50 = "Setelah keluargaku jatuh ke dalam kehancuran, aku dibuang ke Twilight, dan menjadi orang biasa tanpa nama di kota perbatasan.",
  str_voice_1601921_51 = "Saya membentuk Ironthorn Knights sendiri, menyerap sebagian besar ksatria ekspedisi di Twilight. Setelah mengalahkan gerombolan Eclipsite beberapa kali, reputasi Ironthorn Knights menyebar ke seluruh kota.",
  str_voice_1601921_52 = "Alchemy Stars.",
  str_voice_1601921_53 = "Halo.",
  str_voice_1601921_54 = "Maafkan kedatangan saya yang terlambat.",
  str_voice_1601921_55 = "Apakah semuanya berjalan dengan baik?",
  str_voice_1601921_56 = "Pastikan untuk beristirahat lebih awal.",
  str_voice_1601921_57 = "Selamat tahun baru! Mari sambut masa depan bersama, maju dengan keberanian dan keyakinan tak terbatas.",
  str_voice_1601991_1 = "Saya menghabiskan sebagian besar waktu saya di ruang perang, karena pekerjaan saya. Namun, setelah berada di lingkungan yang membosankan dan terbatas begitu lama, seseorang tidak bisa tidak merindukan langit biru yang cerah.",
  str_voice_1601991_2 = "Biasanya ketika saya sendirian, saya memainkan skenario permainan di kepala saya. Terkadang lawannya adalah orang asing, dan terkadang saya sendiri.",
  str_voice_1601991_3 = "Aoha adalah penangkap lalat yang dengan patuh terbang ke ujung jariku seperti ini, penuh kebijaksanaan dan kebaikan. Itu telah berada di sisiku selama bertahun-tahun.",
  str_voice_1601991_4 = "Saya tidak menyiapkan senapan sniper saya tanpa alasan yang jelas, tetapi ketika saya mengarahkannya ke musuh saya, saya selalu mencapai target.",
  str_voice_1601991_5 = "Sebuah rencana seperti permainan catur, di mana setiap gerakan mempengaruhi pelaksanaan langkah selanjutnya. Oleh karena itu, rencana yang baik harus selalu menyisakan ruang untuk kesalahan.",
  str_voice_1601991_6 = "Anda harus memfokuskan seluruh tubuh Anda saat memotret. Berhati-hatilah untuk tidak bernapas, karena dapat memengaruhi bidikan Anda. Setelah Anda memahami ini, Anda juga bisa menjadi penembak jitu yang layak.",
  str_voice_1601991_7 = "Anda ingin tahu apakah bekerja untuk Komite itu monoton dan membosankan? Banyak orang berpikir demikian, tetapi menyusun strategi selalu menarik bagi saya.",
  str_voice_1601991_8 = "Terkadang aku merasa Aoha sama sepertiku. Ketaatan dan kelemahannya hanyalah topeng; keberanian dan tekad berdetak di dalam hati mungilnya.",
  str_voice_1601991_9 = "Masa lalu kita sangat mirip. Sebagai individu yang relatif kesepian dengan tanggung jawab yang tak ada habisnya, saya mengerti bagaimana perasaan Anda. Saya bersedia mendengarkan jika Anda membutuhkan seseorang untuk diajak bicara.",
  str_voice_1601991_10 = "Apa kau lelah? Melepaskan sesekali dapat membantu mengubah pola pikir Anda, tetapi jika Anda merasa lelah, Anda harus benar-benar beristirahat dengan baik.",
  str_voice_1601991_11 = "Bisa melihat pemandangan yang sama seperti Anda cukup bagus.",
  str_voice_1601991_12 = "Krisis hanya memberi kita kesempatan untuk berkumpul kembali. Kita hanya perlu menenangkan diri dan mencari sumber masalahnya.",
  str_voice_1601991_13 = "Setiap orang memiliki prinsip mereka sendiri yang mereka jalani, dan prinsip saya adalah fokus pada gambaran yang lebih besar. Ketika beberapa variabel perlu ditimbang, saya akan selalu melihat situasinya secara keseluruhan.",
  str_voice_1601991_14 = "Serangan balik dan pertahanan musuh menyampaikan informasi berharga tentang kebiasaan mereka, sehingga setiap serangan memiliki arti.",
  str_voice_1601991_15 = "Jika Anda memiliki ucapan selamat ulang tahun, jangan ucapkan dengan lantang. Bagaimanapun, selamat ulang tahun!",
  str_voice_1601991_16 = "Apa yang bisa saya lakukan untuk Anda? Atau mungkin saya harus mengatakan... senang melihat Anda.",
  str_voice_1601991_17 = "Selamat pagi. Aku baru saja selesai berpakaian. Bagaimana penampilanku hari ini?",
  str_voice_1601991_18 = "Saat senja, matahari terbenam berwarna pink muda memenuhi langit malam. Apakah Anda ingin berjalan-jalan dengan saya?",
  str_voice_1601991_19 = "Sudah larut, tapi entah kenapa, aku masih terjaga.",
  str_voice_1601991_20 = "Semua teknologi baru Illumina hadir untuk melindungi manusia.",
  str_voice_1601991_21 = "Kunci Rediesel terlalu longgar. Mereka harus mementingkan pengaturan diri sendiri.",
  str_voice_1601991_22 = "Jayalah Illumina.",
  str_voice_1601991_23 = "Selama ada orang yang menderita di bawah penindasan Eclipsites, saya akan selalu berusaha untuk bekerja lebih keras.",
  str_voice_1601991_24 = "Axelia adalah seorang anak yang dibesarkan diabaikan. Ini membuatnya sulit untuk memahami emosi yang sebenarnya.",
  str_voice_1601991_25 = "Naif bukanlah hal yang buruk. Dalam kasus Sean, setidaknya, itu tampaknya merupakan sifat yang sangat menggemaskan.",
  str_voice_1601991_26 = "Saya suka keju manis dan susu segar. Um ... apakah itu terlalu mendasar?",
  str_voice_1601991_27 = "Aku benci rasa air bersoda di tenggorokanku. Terkadang membuatku cegukan seperti orang gila.",
  str_voice_1601991_28 = "Keberadaan Colossi membuktikan potensi teknologi yang tak terbayangkan. Tidakkah Anda setuju bahwa ini adalah sesuatu yang layak untuk direnungkan?",
  str_voice_1601991_29 = "Saya Yingel. Sebagai Chief Intelligence Officer Illumina's Science Council, saya dapat memberi Anda strategi medan perang, asalkan Anda menganggap saya sebagai rekan yang dapat dipercaya.",
  str_voice_1601991_30 = "Ini juga bagian dari rencanaku.",
  str_voice_1601991_31 = "Hmm... Pistolnya mungkin meledak, hati-hati.",
  str_voice_1601991_32 = "Apakah amunisi ini telah dimodifikasi?",
  str_voice_1601991_33 = "Tidak perlu ragu lagi.",
  str_voice_1601991_34 = "Aku disini.",
  str_voice_1601991_35 = "Amunisi dimuat.",
  str_voice_1601991_36 = "Target terkunci.",
  str_voice_1601991_37 = "Tembakan yang indah!",
  str_voice_1601991_38 = "Pemogokan sempurna!",
  str_voice_1601991_39 = "Biarkan peluru terbang!",
  str_voice_1601991_40 = "Presisi sempurna!",
  str_voice_1601991_41 = "Saya sangat pandai memberi perintah.",
  str_voice_1601991_42 = "Itu semua adalah bagian dari rencana.",
  str_voice_1601991_43 = "Aku harus menyusun rencana baru...",
  str_voice_1601991_44 = "Saya akan memastikan Aoha terbang dengan hati-hati. Saya tidak ingin menimbulkan masalah pada Colossus Anda.",
  str_voice_1601991_45 = "Apakah ini untukku? Terima kasih.",
  str_voice_1601991_46 = "Saya sangat suka ketika Anda membuat keributan tentang saya.",
  str_voice_1601991_47 = "Saya melihat ini sebagai bukti persetujuan Anda.",
  str_voice_1601991_48 = "Saya akan menghargai ini bersama dengan rampasan lainnya.",
  str_voice_1601991_49 = "Ketika saya berumur empat tahun, orang tua saya mempercayakan saya kepada Profesor Ulysses sebelum berangkat ke medan perang. Tak lama kemudian, datang kabar buruk bahwa mereka telah mengorbankan nyawa mereka untuk Illumina.",
  str_voice_1601991_50 = "Saya pernah menerima banyak pujian, tapi itu bukan karena kemampuan saya diakui. Mereka hanya berharap saya bisa bertanggung jawab atas masa depan Illumina.",
  str_voice_1601991_51 = "Sebagai hadiah karena telah lulus ujian, profesor memberi saya penangkap lalat yang saya beri nama Aoha. Saya tahu itu bukan hanya hadiah yang tidak bersalah. Itu juga berfungsi sebagai pengingat yang hati-hati ...",
  str_voice_1601991_52 = "Alchemy Stars.",
  str_voice_1601991_53 = "Halo.",
  str_voice_1601991_54 = "Selamat pagi. Apakah tidurmu nyenyak?",
  str_voice_1601991_55 = "Selamat sore, PlayerName.",
  str_voice_1601991_56 = "Ah, ini sudah sore.",
  str_voice_1601991_57 = "Selamat tahun baru! Saya harap saya bisa melihat Anda saat ini tahun depan juga.",
  str_voice_1502001_1 = "Semua makhluk hidup membawa banyak informasi tentang diri mereka sendiri. Dengan kecerdasan yang memadai, seseorang dapat menganalisis pola dan motivasi perilaku makhluk dan bahkan membuat prediksi sampai batas tertentu.",
  str_voice_1502001_2 = "Hah... Hmm? Apakah Anda menelepon saya? Tidak, saya tidak tidur, saya hanya mengamati Anda dan yang lainnya di Colossus ini.",
  str_voice_1502001_3 = "Caelestites memiliki kemampuan psikis yang tidak dimiliki oleh Aurorian. Kemampuan tersebut tidak hanya berguna dalam pertempuran, tetapi juga tampaknya memberikan keuntungan yang signifikan dalam mengumpulkan intelijen.",
  str_voice_1502001_4 = "Jangan biarkan pengetahuan yang ada menyesatkan Anda — sebagai seorang perwira intelijen, saya jarang berpartisipasi dalam pertempuran, tetapi itu tidak berarti saya tidak pandai dalam hal itu.",
  str_voice_1502001_5 = "Seorang petugas intelijen harus berusaha untuk menghindari pertempuran yang tidak perlu jika memungkinkan, tetapi jika itu adalah perintah Anda, saya tidak akan menolak.",
  str_voice_1502001_6 = "Saya kira Anda menyadari kemampuan dan keterbatasan saya... Jadi, tolong beri saya perintah apa pun yang Anda inginkan, dan saya akan memberi Anda kecerdasan yang akan membawa kita menuju kemenangan.",
  str_voice_1502001_7 = "Kabar angin tidak dapat digunakan sebagai kecerdasan. Informasi perlu diverifikasi... Misalnya, saya baru mulai memahami orang seperti apa Anda setelah mengenal Anda.",
  str_voice_1502001_8 = "Di medan perang, baik senjata maupun intel tidak lebih penting daripada kepercayaan. Dulu, sebagai pramuka, saya bertindak sendiri dan tidak mengerti arti kepercayaan, tapi sekarang, semuanya berbeda.",
  str_voice_1502001_9 = "Apakah Anda ingin melihat buku catatan saya? Um... Anda hanya dapat melihat bagian yang tidak melibatkan informasi rahasia Illumina, dan Anda tidak dapat mengungkapkan isi catatan saya kepada pihak luar. Anda juga tidak boleh mencorat-coretnya.",
  str_voice_1502001_10 = "Apakah kamu belum istirahat, PlayerName? Kalau begitu, izinkan saya menggunakan waktu luang ini untuk mengatur kecerdasan yang baru saja saya kumpulkan.",
  str_voice_1502001_11 = "Anda mencari bantuan saya... Saya tidak memiliki banyak pengalaman, tetapi jika Anda dapat memberi saya beberapa informasi mendetail mengenai tugas ini, saya pasti akan mencoba yang terbaik.",
  str_voice_1502001_12 = "Ini adalah ikan peliharaan saya, Bubble, yang saya temukan di rawa dekat Dark Zone. Anda dapat menyentuhnya jika Anda mau. Yakinlah, itu hanya makhluk biasa dan sama sekali tidak berbahaya.",
  str_voice_1502001_13 = "Tolong jangan mengutak-atik buku catatan saya. Ini bukan hanya alat untuk merekam intelijen, tetapi juga senjata.",
  str_voice_1502001_14 = "Setiap tindakan meninggalkan jejak. Tidak peduli bagaimana Anda mencoba untuk menutupinya, kecerdasan tidak menghilang begitu saja. Sedikit pengamatan yang cermat, dan semuanya terungkap.",
  str_voice_1502001_15 = "Menurut kecerdasanku, hari ini adalah hari ulang tahunmu. Selamat ulang tahun. Setiap orang yang mengetahui informasi ini juga harus menunggu Anda dengan berkah hangat.",
  str_voice_1502001_16 = "Selamat Datang kembali. Intelijen telah diatur dan jadwal kerja telah diatur. Silakan lihat.",
  str_voice_1502001_17 = "Selamat pagi. Tampaknya Anda adalah seseorang yang tidak bisa hidup tanpa bekerja.",
  str_voice_1502001_18 = "Selamat malam. Ini hampir waktu istirahat, jadi tidak perlu memaksakan diri untuk terus bekerja, dan tidak ada alasan mengapa Anda tidak boleh bersantai sesekali.",
  str_voice_1502001_19 = "Ini sangat larut... Apakah kamu belum tidur?",
  str_voice_1502001_20 = "Federasi Illumina adalah tempat yang ada untuk kebahagiaan semua orang. Setidaknya itulah yang saya yakini.",
  str_voice_1502001_21 = "Northland juga dekat dengan Dark Zone, tetapi memiliki pegunungan dan Beacon yang melindunginya. Kedamaian dan kenyamanan seperti itu benar-benar membuat iri.",
  str_voice_1502001_22 = "Jayalah Illumina.",
  str_voice_1502001_23 = "Di mana pun Anda berada, Eclipsites adalah makhluk yang membawa masalah dan bahaya. Tolong hati-hati.",
  str_voice_1502001_24 = "Grand Marshal adalah pemimpin yang andal. Ini adalah kesimpulan yang saya ambil setelah pengamatan yang cermat.",
  str_voice_1502001_25 = "Saya kadang-kadang mendapati diri saya terpaksa mengeluh kepada Komandan Barton. Saya berharap dia akan sedikit lebih tenang.",
  str_voice_1502001_26 = "Saya suka memelihara ikan—apakah itu mengejutkan Anda? Lihat, inilah yang terjadi jika Anda kekurangan intel.",
  str_voice_1502001_27 = "Keyakinan buta bukanlah hal yang baik. Itu dapat mempengaruhi keputusan komandan.",
  str_voice_1502001_28 = "Kecerdasan pada Colossi di Illumina langka... Apakah Anda mengizinkan saya untuk melihat-lihat?",
  str_voice_1502001_29 = "Seorang Caelestite, menerbangkan Colossus... kau memang orangnya. Anatoli, Petugas Intelijen Federasi Illumina, dengan senang hati membantu Anda. Silakan berikan perintah Anda.",
  str_voice_1502001_30 = "Mengumpulkan pengalaman tempur juga merupakan cara untuk mengumpulkan intelijen.",
  str_voice_1502001_31 = "Akurasi intelijen ditingkatkan.",
  str_voice_1502001_32 = "Rencana pertempuran baru telah disusun.",
  str_voice_1502001_33 = "Rencana siap dieksekusi.",
  str_voice_1502001_34 = "Aku mengerti.",
  str_voice_1502001_35 = "Taktik baru direncanakan dengan sukses.",
  str_voice_1502001_36 = "Aku siap kapan pun kau siap.",
  str_voice_1502001_37 = "Mengganggu formasi musuh.",
  str_voice_1502001_38 = "Cahaya laten, bersembunyi di bayang-bayang.",
  str_voice_1502001_39 = "Titik lemah terletak.",
  str_voice_1502001_40 = "Sekarang kesempatan kita.",
  str_voice_1502001_41 = "Siap, laksanakan.",
  str_voice_1502001_42 = "Kemenangan yang tak terelakkan.",
  str_voice_1502001_43 = "Kecerdasan kita cacat... Mundur untuk saat ini.",
  str_voice_1502001_44 = "Jangan khawatir tentang saya, saya hanya mengamati yang lain dan mengumpulkan intelijen.",
  str_voice_1502001_45 = "Terima kasih atas hadiahmu.",
  str_voice_1502001_46 = "Sudahkah Anda ... secara khusus mempelajari preferensi saya?",
  str_voice_1502001_47 = "Saat Anda memilih hadiah untuk orang lain, barang yang Anda pilih juga mencerminkan selera dan preferensi Anda sendiri.",
  str_voice_1502001_48 = "Terima kasih, saya sangat suka hadiah ini.",
  str_voice_1502001_49 = "Tidak ada yang terlahir sebagai perwira intelijen. Saya mulai sebagai pramuka, mengumpulkan pengalaman dan mengasah diri hingga akhirnya menjadi diri saya yang sekarang.",
  str_voice_1502001_50 = "Memelihara ikan peliharaan adalah tugas yang memakan waktu yang membutuhkan pemberian makan teratur, membersihkan ganggang hijau dari tangki, dan terus memperhatikan kesehatan ikan... Namun, Gelembung selalu sangat sehat, mungkin karena hidup di Malam Abadi sebelumnya.",
  str_voice_1502001_51 = "Mempercayai seseorang berarti Anda bersedia mempercayakan keselamatan Anda dan bahkan hidup Anda kepada orang lain. Tidak masalah apakah Anda seorang prajurit biasa atau seorang perwira intelijen.",
  str_voice_1502001_52 = "Alchemy Stars.",
  str_voice_1502001_53 = "Halo, PlayerName.",
  str_voice_1502001_54 = "Selamat pagi.",
  str_voice_1502001_55 = "Siang.",
  str_voice_1502001_56 = "Hari mulai gelap...",
  str_voice_1502001_57 = "Selamat tahun baru, PlayerName. Di tahun baru, izinkan saya mengumpulkan intelijen untuk Anda dan memberikan bantuan pada Colossus.",
  str_voice_1602011_1 = "Aku... Aku sudah lama tidak mengenakan gaun dengan warna seperti itu. Apakah itu terlihat bagus untukku? Heheh, ini sedikit memalukan.",
  str_voice_1602011_2 = "Tidak perlu mengambil nyawa lawan dalam pertempuran, kan? Ya, saya mengerti hanya seorang pejuang hebat yang memiliki hak istimewa untuk memilih kasih sayang, dan saya jauh dari itu...",
  str_voice_1602011_3 = "Wow, jalanan begitu ramai. Apa yang mereka lakukan? Saya akan memprioritaskan menyelesaikan tugas saya! Tapi kuharap matahari masih terbit saat aku selesai...",
  str_voice_1602011_4 = "Ketika saya masih kecil, saya merasa sedih dan tidak berdaya tidak peduli seberapa keras saya mencoba ... Sekarang, saya hanya berjuang untuk tujuan saya sendiri, dan itu jauh lebih mudah di pikiran saya.",
  str_voice_1602011_5 = "Judul adalah hal yang luar biasa. Mereka dapat membelenggu Anda atau memberi Anda kekuatan tanpa batas. Tetapi Anda tidak harus terpaku pada mereka ...",
  str_voice_1602011_6 = "Jika dulu aku seberani sekarang... Tidak, percuma merenungkan hal ini. Yang penting adalah melindungi apa yang Anda hargai sekarang, bukan?",
  str_voice_1602011_7 = "Aku berbeda dari sebelumnya. Saya tidak merasa rendah diri, atau tidak mampu mengendalikan diri... Itu benar! Jadi, keberatan mempercayaiku sedikit lagi?",
  str_voice_1602011_8 = "Tolong jangan menjamin saya keluar sepanjang waktu. Tidak, itu tidak merepotkan. Hanya saja... Kurasa aku harus melindungimu.",
  str_voice_1602011_9 = "Izinkan saya memberi tahu Anda sebuah rahasia: Tangan saya terkadang gemetar dalam pertempuran. Keberatan meminjamkan saya sedikit keberanian? Oh, tanganmu benar-benar hangat...",
  str_voice_1602011_10 = "Pilih buket mawar ♪ untuk ayah dan ibu tersayang ♪... Oh, maaf! Terlalu sepi di sekitar sini dan aku biasanya... Hah, ternyata aku masih sendiri...",
  str_voice_1602011_11 = "Jangan khawatir, tarik napas dalam-dalam... Tarik napas, hembuskan... Ehem, tidak masalah, saya bisa menangani pekerjaan itu. Saya mengerti!",
  str_voice_1602011_12 = "Terlepas dari apa yang orang lain katakan, saya akan selalu menjadi saudara perempuan Carleen, serta ... putri Joshua. Tidak ada kehormatan yang membosankan yang dapat memutuskan ikatan keluarga.",
  str_voice_1602011_13 = "Saya punya... seorang teman, bernama Baba Yaga yang dulunya agak brutal, tapi sekarang tidak lagi. Tolong jangan panik jika Anda mendapat kesempatan untuk bertemu dengannya, oke?",
  str_voice_1602011_14 = "Lututku tergores saat latihan dan sakit... Apa? Tidak, itu hanya luka daging! Saya memiliki air mata di mata saya? *terisak* Tidak, aku tidak...",
  str_voice_1602011_15 = "Selamat ulang tahun. Senang rasanya bisa tumbuh dewasa.",
  str_voice_1602011_16 = "Anda harus keluar kapan pun Anda bebas. Jalanan cantik di siang hari.",
  str_voice_1602011_17 = "Selamat pagi, dan betapa indahnya pagi ini. Peduli teh pagi?",
  str_voice_1602011_18 = "Hari mulai gelap... Tidak apa-apa, aku sudah terbiasa dengan kegelapan.",
  str_voice_1602011_19 = "Masih sibuk selarut ini? Saya kira itu sama untuk semua orang dengan kewajiban vital.",
  str_voice_1602011_20 = "Bahkan jika saya hanya bisa melihat rumah saya dari jauh, saya akan tetap mempertahankannya dengan sekuat tenaga.",
  str_voice_1602011_21 = "Umbraton adalah tempat yang bagus. Orang-orang dari Lumopolis harus lebih sering berkunjung.",
  str_voice_1602011_22 = "Malam Putih di atas... Haha, itu membawa kembali kenangan.",
  str_voice_1602011_23 = "Anda membenci Eclipsites? Lalu, bagaimana dengan Eclipsites yang berubah menjadi Aurorian?",
  str_voice_1602011_24 = "Carleen dan Ibu... Aku berharap kita selalu bisa—tidak, tidak apa-apa.",
  str_voice_1602011_25 = "Itu Schwartz nama tidak cukup penting bagiku untuk tetap hidup dalam bayangannya.",
  str_voice_1602011_26 = "Menikmati secangkir Teh Hitam Knight di sebuah kafe kecil sendirian di sore hari... sungguh sempurna.",
  str_voice_1602011_27 = "Tidak apa-apa, saya bisa menangani banyak hal sendiri tanpa mengganggu orang lain...",
  str_voice_1602011_28 = "Di sini sangat ramai... dan ada orang yang ingin kutemui dan ada yang tidak.",
  str_voice_1602011_29 = "Halo. Biarkan saya melihat bagaimana saya harus memperkenalkan diri... Veronica? Tidak, panggil saja aku Mia. Mia harus dilakukan.",
  str_voice_1602011_30 = "Harus tetap latihan...",
  str_voice_1602011_31 = "Saya pikir saya sudah menguasainya!",
  str_voice_1602011_32 = "Aku seorang ksatria... Aku tidak lemah!",
  str_voice_1602011_33 = "Andai saja aku memiliki kekuatan seperti itu lebih cepat...",
  str_voice_1602011_34 = "Aku akan terus melakukan yang terbaik...!",
  str_voice_1602011_35 = "Aku siap!",
  str_voice_1602011_36 = "Tolong jangan takut...",
  str_voice_1602011_37 = "Temui kekuatanku!",
  str_voice_1602011_38 = "Temui diriku yang sebenarnya!",
  str_voice_1602011_39 = "Rasakan ini!",
  str_voice_1602011_40 = "Jangan menahan apa pun!",
  str_voice_1602011_41 = "Semuanya... ikuti aku!",
  str_voice_1602011_42 = "K-Kami menang... Kami menang!",
  str_voice_1602011_43 = "Mendesah. Masih belum cukup baik...",
  str_voice_1602011_44 = "Salam. Bagaimana kabarmu akhir-akhir ini? Heheh, aku sudah lama tidak mengatakannya.",
  str_voice_1602011_45 = "Terima kasih.",
  str_voice_1602011_46 = "Hei, apa ini...",
  str_voice_1602011_47 = "Ada apa lagi kali ini?",
  str_voice_1602011_48 = "Hanya kamu yang sangat mengenalku...",
  str_voice_1602011_49 = "\"Veronica,\" putri sulung Penguasa Kota Lumopolis... dan cacat di House Schwartz. Itulah sejarah yang diwakili oleh gaun ini.",
  str_voice_1602011_50 = "\"Baba Yaga\", laba-laba hitam yang mirip hantu. Dia tidak mati tetapi bergabung dengan Mia untuk menjadi diriku yang kamu lihat sekarang.",
  str_voice_1602011_51 = "Aku masih Mia... dan hanya bisa Mia. Tapi itu bukan alias yang orang lain berikan padaku. Ini adalah jalan yang saya pilih untuk diri saya sendiri.",
  str_voice_1602011_52 = "Alchemy Stars.",
  str_voice_1602011_53 = "Permisi...",
  str_voice_1602011_54 = "Teh hitamnya wangi banget...",
  str_voice_1602011_55 = "Selamat siang. Aku tidak mengganggu, kan...?",
  str_voice_1602011_56 = "Hmm selamat sore...",
  str_voice_1602011_57 = "Selamat tahun baru. Hargai dengan menghabiskan waktu bersama orang-orang tersayang.",
  str_voice_1602021_1 = "Sedang hujan. Putri sulung saya menyukai hujan dan cara tetesan air hujan membuat bunga ungu memantul ke atas dan ke bawah. ...Dia sulit dimengerti.",
  str_voice_1602021_2 = "Saat saya melihat Lumopolis yang luas, saya bertanya pada diri sendiri apakah saya pantas memimpin rakyatnya. Saya harus terus memotivasi diri saya sendiri untuk memerintah tanah yang melambangkan kesucian ini.",
  str_voice_1602021_3 = "Saya sebenarnya seorang pembicara yang baik, meskipun tidak banyak yang memiliki kesempatan untuk berbicara dengan saya. Anda, bagaimanapun, adalah salah satu pengecualian.",
  str_voice_1602021_4 = "Gerhana membawa kegelapan, tapi fajar sudah dekat. Kami akan menghancurkan mereka sampai tidak ada yang tersisa.",
  str_voice_1602021_5 = "Perang sedang mencapai puncaknya. Semakin dekat kita dengan kemenangan, semakin sedikit kita bisa berpuas diri.",
  str_voice_1602021_6 = "Kekuatan adalah inti dari menjadi seorang pemimpin. Saya akan menerapkan kekuatan itu untuk memimpin semua orang menuju kemenangan dalam perang.",
  str_voice_1602021_7 = "Sebagai seorang penguasa, perlu untuk tetap berpikiran jernih dalam kekacauan.",
  str_voice_1602021_8 = "Saya lebih suka membaca teks sejarah. Saya bersedia menghabiskan beberapa jam waktu luang saya untuk membaca karya klasik tertentu yang terkenal.",
  str_voice_1602021_9 = "Beberapa orang berpikir saya terlalu menuntut anak-anak saya, tetapi masa depan adalah jalan yang panjang, oleh karena itu sangat berharga jika itu akan membantu mereka menghindari kesalahan.",
  str_voice_1602021_10 = "Seseorang tidak dapat mencapai sesuatu yang signifikan dengan sikap santai dan angkuh seperti itu. Jika saya tidak bertanggung jawab seperti Anda, banyak perselingkuhan di Lumopolis akan berantakan.",
  str_voice_1602021_11 = "Apakah waktu dan perhatian saya benar-benar diperlukan untuk hal-hal sepele seperti itu?",
  str_voice_1602021_12 = "Meski masih sangat muda, Carleen telah menunjukkan kepintaran yang jauh melampaui usianya. Meskipun dia mungkin tidak menyadarinya, sebagai seorang ayah, saya bangga padanya.",
  str_voice_1602021_13 = "Menyerang, tentu saja, lebih penting daripada bertahan. Pelanggaran yang kuat dapat mengalahkan musuh yang pemalu dan mengungkap lebih banyak kerentanan.",
  str_voice_1602021_14 = "Sayangnya, semua yang mendambakan tahta menemui—atau akan menemui—pemusnahan pada akhirnya tanpa kecuali, seperti kejayaan House. Schwartz akan bertahan selamanya.",
  str_voice_1602021_15 = "Selamat ulang tahun. Berkat ini datang dari saya dan Lumopolis.",
  str_voice_1602021_16 = "Anda disana. Ingatlah untuk lebih sering berpatroli di wilayah Anda.",
  str_voice_1602021_17 = "Anda cukup awal untuk menikmati teh bersama saya.",
  str_voice_1602021_18 = "Regangkan tubuh Anda dan rilekskan pikiran Anda untuk meningkatkan produktivitas Anda.",
  str_voice_1602021_19 = "Ini biasanya ketika saya meninjau agenda saya untuk besok.",
  str_voice_1602021_20 = "Di bawah kepemimpinan saya, Lumopolis akan meraih masa depan yang lebih sejahtera dan cerah.",
  str_voice_1602021_21 = "Tidak diragukan lagi, stabilitas dan kemakmuran di Umbraton bermanfaat bagi Lumopolis.",
  str_voice_1602021_22 = "Demi White Night.",
  str_voice_1602021_23 = "Eclipsites menyerang di mana-mana dalam jumlah besar. Seorang dalang tersembunyi tentu berada di balik plot tersebut.",
  str_voice_1602021_24 = "Joshua yang membuatku seperti ini, dan bukan fakta bahwa aku memilihnya.",
  str_voice_1602021_25 = "Selama Veronica dapat dibimbing menuju jalan yang benar, dia akan membuat perbedaan.",
  str_voice_1602021_26 = "Semua orang Aurorian harus menyukai sinar matahari. Itu sebabnya saya suka hari yang cerah.",
  str_voice_1602021_27 = "Memberikan apa yang disebut kasih sayang kepada musuh dalam pertempuran sama dengan tidak menunjukkan belas kasihan kepada diri sendiri, bukan?",
  str_voice_1602021_28 = "Izinkan saya menempatkan buku-buku sejarah di Colossus untuk membantu Anda memahami sejarah Lumopolis.",
  str_voice_1602021_29 = "Kami Schwartze menghormati setiap orang yang menunjukkan kebijaksanaan dan akal. Karena Anda terbukti luar biasa, Anda berhak berbicara dengan saya.",
  str_voice_1602021_30 = "Kekuasaan datang dengan otoritas.",
  str_voice_1602021_31 = "Menantikan fajar.",
  str_voice_1602021_32 = "Ini adalah fajar.",
  str_voice_1602021_33 = "Kebenaran akan membimbing Lumopolis!",
  str_voice_1602021_34 = "Keputusan yang benar.",
  str_voice_1602021_35 = "Siap untuk berangkat!",
  str_voice_1602021_36 = "Apa lagi yang kautunggu?",
  str_voice_1602021_37 = "Malam dan hari yang fana tanpa akhir!",
  str_voice_1602021_38 = "Aurora Aeterna di bawah Cahaya!",
  str_voice_1602021_39 = "Cahaya Malam Putih!",
  str_voice_1602021_40 = "Tebasan penguasa!",
  str_voice_1602021_41 = "Saya akan memimpin pawai!",
  str_voice_1602021_42 = "Kemenangan itu pasti dan diharapkan.",
  str_voice_1602021_43 = "Aku mengampuni mereka kali ini.",
  str_voice_1602021_44 = "Jangan remehkan tanah kecil ini, karena cahaya abadi dan masa depan akan terungkap di sini.",
  str_voice_1602021_45 = "Yah, aku akan menerimanya.",
  str_voice_1602021_46 = "Apa yang Anda inginkan sebagai imbalan?",
  str_voice_1602021_47 = "Saya akan menghargai ini.",
  str_voice_1602021_48 = "Saya memiliki harta yang tak terhitung jumlahnya, tetapi hadiah ini unik.",
  str_voice_1602021_49 = "Joshua berasal dari akar sipil, jadi House Schwartz melarang pernikahan kami. Namun, saya memutuskan dialah orangnya dan bersedia melakukan upaya apa pun.",
  str_voice_1602021_50 = "Menjadi seorang ayah lebih berdampak bagi saya daripada menjadi seorang gubernur nanti. Saat itulah saya mulai menyadari arti sebenarnya dari tanggung jawab.",
  str_voice_1602021_51 = "Ancaman Eclipsites menghancurkan kedamaian yang pernah kita miliki. Untuk Lumopolis, untuk orang-orang yang tidak berdaya, untuk keluargaku, aku harus berbaris ke medan perang.",
  str_voice_1602021_52 = "Alchemy Stars!",
  str_voice_1602021_53 = "Apa kabarmu?",
  str_voice_1602021_54 = "Fajar akan membersihkan semuanya.",
  str_voice_1602021_55 = "Ini tengah hari. Waktunya istirahat.",
  str_voice_1602021_56 = "Hari semakin larut.",
  str_voice_1602021_57 = "Jangan ragu untuk mengunjungi Lumopolis di tahun baru.",
  str_voice_1502031_1 = "Berdasarkan tanggapan Anda terhadap ramalan, saya yakin Anda adalah seseorang yang akan tertawa saat bahagia, tidur saat lelah, dan perut keroncongan saat lapar! Apa? Maksudmu semua orang seperti itu?",
  str_voice_1502031_2 = "Skema warna agak polos pada Colossus. Bagaimana kalau kita melukis beberapa pola warna-warni? Mengapa tidak? Ini bukan grafiti, saya janji!",
  str_voice_1502031_3 = "Hei, apa yang kamu lakukan? Apa itu, suaraku yang keras membuatmu takut? Bagaimana bisa? Apakah Anda melakukan sesuatu secara rahasia? Heehee, aku tidak akan memberitahu!",
  str_voice_1502031_4 = "Anda terlihat lelah, apakah Anda mengalami malam yang sulit? Bagaimana kalau saya ceritakan sebuah cerita? \"Gua Misterius yang Menelan Orang Seutuhnya\" akan membuat Anda bersemangat dalam sekejap!",
  str_voice_1502031_5 = "Untuk menjadi toleran seperti Jeriah, sekuat Bethlehem, secerdas Ibu—itu sangat mudah!",
  str_voice_1502031_6 = "Game apa yang kamu mainkan? Apakah itu sulit? Saya ingin mencoba. Seharusnya tidak ada masalah dengan kita berdua!",
  str_voice_1502031_7 = "Pasar akan sangat padat akhir pekan ini dengan banyak barang. Aku benar-benar ingin pergi! Ayo pergi saat kamu bebas!",
  str_voice_1502031_8 = "Seseorang mengundang saya ke acara kumpul-kumpul kemarin, tetapi saya tidak pergi karena Anda tidak akan hadir. Meskipun aku menyukai ide berpesta, tidak menyenangkan tanpamu.",
  str_voice_1502031_9 = "Saya sangat sibuk membuat dreamcatcher akhir-akhir ini. Seharusnya, itu bisa menangkap mimpi indah. Saya menggunakan banyak utas dengan warna berbeda juga! Saya akan memberikannya kepada Anda ketika saya selesai!",
  str_voice_1502031_10 = "Bacaan Anda tidak berhasil terakhir kali, jadi saya memutuskan untuk memberi Anda bacaan gratis kali ini. Apa, kamu tidak menginginkannya? Tapi kali ini pasti akan berhasil!",
  str_voice_1502031_11 = "Hai, aku di sini untuk hang out! Saya akan menceritakan sebuah kisah jika suasana hati Anda sedang buruk!",
  str_voice_1502031_12 = "Saya baru saja makan salad buah super enak di Cafe. Stroberi merah, jeruk keprok, nanas kuning... Rasanya seperti palet pelukis!",
  str_voice_1502031_13 = "Apakah Anda kehilangan pena? Biarkan aku meramal... Uh, seharusnya ada di lemari di barat daya! Apa, masih tidak dapat menemukannya?",
  str_voice_1502031_14 = "Benda berwarna apa yang terakhir kali kita lihat di pasar? Oh, benar, balon. Mereka sangat cantik.",
  str_voice_1502031_15 = "Wah, ini hari ulang tahunmu! Mari kita mengadakan pesta super besar!",
  str_voice_1502031_16 = "Ada hal menarik yang terjadi padamu hari ini? Pastikan untuk memberi tahu saya!",
  str_voice_1502031_17 = "Selamat pagi! Punya tugas penting untuk hari itu? Biarkan saya melakukan pembacaan untuk Anda!",
  str_voice_1502031_18 = "Hei, di luar gelap. Mari kita lihat pemandangan di malam hari.",
  str_voice_1502031_19 = "Buku ramalan saya menunjukkan bahwa roh lebih aktif di malam hari, jadi saya memutuskan untuk begadang semalaman!",
  str_voice_1502031_20 = "Northland mungkin sedikit dingin, tapi seperti mimpi, seperti dongeng.",
  str_voice_1502031_21 = "Lumopolis cantik, tapi terasa pengap juga, seperti buku pelajaran yang membosankan.",
  str_voice_1502031_22 = "Demi Utara.",
  str_voice_1502031_23 = "Ayo, kita harus membaca tentang cara menghindari Eclipsites sama sekali.",
  str_voice_1502031_24 = "Merindukan Jeriah sangat keren, toleran, dan kuat. Apa yang bisa saya lakukan untuk menjadi seperti dia?",
  str_voice_1502031_25 = "Ratu Bethlehem sangat mengesankan dan indah. Aku tidak bisa berpaling setiap kali aku melihatnya.",
  str_voice_1502031_26 = "Saya telah mengarang beberapa kisah baru yang menarik. Mau mendengar?",
  str_voice_1502031_27 = "Mengapa orang-orang membuatku takut? Itu mengganggu. Saya tidak akan pernah membuat hantu siapa pun kecuali saya salah waktu ... heehee.",
  str_voice_1502031_28 = "Kalau saja Colossus lebih besar untuk menampung semua orang, kami akan mengadakan pesta sungguhan!",
  str_voice_1502031_29 = "Bola kristal bersinar sebagai teka-teki Jakine, Master Ramalan, masuk. Apa yang akan terjadi dengan pertemuan itu? Pantau terus!",
  str_voice_1502031_30 = "Hai!",
  str_voice_1502031_31 = "Aku baik-baik saja!",
  str_voice_1502031_32 = "Saya luar biasa!",
  str_voice_1502031_33 = "Saya sangat luar biasa!",
  str_voice_1502031_34 = "Halo semuanya!",
  str_voice_1502031_35 = "Siap untuk memulai ramalan.",
  str_voice_1502031_36 = "Waktu untuk ramalan.",
  str_voice_1502031_37 = "Bola kristal!",
  str_voice_1502031_38 = "Tercakup!",
  str_voice_1502031_39 = "Nubuat terpenuhi.",
  str_voice_1502031_40 = "Rasakan masa depan.",
  str_voice_1502031_41 = "Bisa!",
  str_voice_1502031_42 = "Ramalan yang sukses!",
  str_voice_1502031_43 = "Ramalan gagal...",
  str_voice_1502031_44 = "Ramalan semakin akurat semakin dekat saya ke langit, bukan?",
  str_voice_1502031_45 = "Ooh! Terima kasih!",
  str_voice_1502031_46 = "Wow, hadiah ini luar biasa!",
  str_voice_1502031_47 = "Baiklah, hadiah lain!",
  str_voice_1502031_48 = "Luar biasa! Aku menyukainya!",
  str_voice_1502031_49 = "Ibuku juga ahli ramalan, dan dia saus yang luar biasa! Ini, uh, buku ramalan... Dia meninggalkanku dengan ini.",
  str_voice_1502031_50 = "Merindukan Jeriah adalah guru saya. Lihat, bukankah Whisper terlihat seperti orang mati untuk Python Suci Nona Jeriah? Itu tidak...?",
  str_voice_1502031_51 = "Tempat yang ingin saya kunjungi? Sebelumnya, ada Lake Mirror, Northland Pine, dan World's Spine... Mereka tidak ramai, tapi saya bisa menjelajahi rahasia Luminatics di sana.",
  str_voice_1502031_52 = "Alchemy Stars.",
  str_voice_1502031_53 = "Hai!",
  str_voice_1502031_54 = "Selamat pagi!",
  str_voice_1502031_55 = "Siang hari adalah waktu tersibuk.",
  str_voice_1502031_56 = "Ayo, waktunya tidur.",
  str_voice_1502031_57 = "Ini waktu paling hidup dan paling bahagia tahun ini lagi. Mari menari dan tertawa dengan gembira!",
  str_voice_1602041_1 = "Saya akan merindukan teh hitam Lumopolis, itu sudah pasti. Tapi siapa yang tahu? Mungkin saya akan menemukan teh lain yang sama enaknya di tempat lain. Tidak sabar untuk melihat apa yang ada di luar sana.",
  str_voice_1602041_2 = "Cuaca basah membuat semuanya lengket. Itu sebabnya saya lebih suka cuaca cerah—membuat segalanya tampak teratur.",
  str_voice_1602041_3 = "Anak itu, yang kau panggil Mia. Dia tidak terlalu mahir mengungkapkan perasaannya, tapi dia sepertinya selalu membuka hatinya untukmu.",
  str_voice_1602041_4 = "Pedang yang luar biasa, bukan begitu? Ini bukan hanya untuk pertunjukan. Saya akan memegangnya erat-erat dan membela sebanyak mungkin orang.",
  str_voice_1602041_5 = "Apakah Anda pikir ilmu pedang saya telah meningkat? Haha, saya pikir saya mulai mendapatkan kembali gairah yang pernah saya miliki. Lagi pula, saya bahkan pernah setara dengan seseorang tertentu ...",
  str_voice_1602041_6 = "Harapan saya, dari dahulu hingga sekarang, selalu melindungi semua orang. Bukan hanya keluarga saya, dan bukan hanya teman-teman dari kampung halaman saya ...",
  str_voice_1602041_7 = "Beberapa musik ringan yang menenangkan dapat menciptakan suasana yang harmonis. Bagaimana kalau memainkan beberapa lagu lain kali kita kedatangan tamu?",
  str_voice_1602041_8 = "Yang paling saya suka adalah melihat orang tersenyum. Anda juga perlu lebih banyak tersenyum, PlayerName. Anak-anak yang suka tertawa akan menikmati keberuntungan yang lebih besar dalam hidup.",
  str_voice_1602041_9 = "Dunia luar memang berbeda dari Lumopolis dalam banyak hal. Di mana saya harus menetapkan tujuan saya selanjutnya? Apakah Anda punya saran bagus, PlayerName?",
  str_voice_1602041_10 = "Minumlah segelas air madu—itu sangat manjur untuk menghilangkan kepenatan sehingga Anda benar-benar tidak mampu untuk tidak meminumnya. Anak yang baik harus selalu mendengarkan kebijaksanaan orang tua mereka.",
  str_voice_1602041_11 = "Meskipun saya tidak bungkuk dalam mengatur hal-hal penting, sehubungan dengan Colossus ini... Yah, saya belum punya banyak pengalaman. Tapi karena ini adalah permintaanmu, sebagai sesepuhmu, aku akan melakukan yang terbaik.",
  str_voice_1602041_12 = "Meskipun kadang-kadang dunia tampak begitu miskin, selalu ada orang yang berusaha menjadikannya tempat yang lebih baik, dan saya yakin Anda adalah salah satunya.",
  str_voice_1602041_13 = "Yang sangat diharapkan seorang ibu adalah melihat anak-anaknya meninggalkan sarang dan terbang ke langit yang lebih luas. Anda telah melakukan hal itu. Aku bangga padamu, dan aku tahu ibumu juga akan begitu.",
  str_voice_1602041_14 = "Masa lalu seperti sebuah perjalanan yang indah. Saya berhenti di stasiun tertentu di sepanjang jalan, dan setelah menikmati pemandangan, tibalah waktunya untuk melanjutkan perjalanan.",
  str_voice_1602041_15 = "PlayerName, saya yakin Anda akan menjadi lebih tampan seiring berjalannya waktu. Selamat ulang tahun!",
  str_voice_1602041_16 = "Pertahankan dagu Anda dan bekerja keras!",
  str_voice_1602041_17 = "Selamat pagi! Sudah sarapan belum?",
  str_voice_1602041_18 = "Jangan minum teh larut malam. Anda mungkin tidak bisa tidur.",
  str_voice_1602041_19 = "Ini sudah malam, kamu pasti lelah. Jaga dirimu baik-baik.",
  str_voice_1602041_20 = "Saya sangat mencintai semua orang di Lumopolis, itulah mengapa saya memilih ... untuk pergi sekarang.",
  str_voice_1602041_21 = "Rediesel Wrench... sepertinya tempat yang sangat menarik!",
  str_voice_1602041_22 = "Demi White Night.",
  str_voice_1602041_23 = "Saya membenci perbuatan sembrono dan jahat lebih dari saya membenci Eclipsites.",
  str_voice_1602041_24 = "Dia juga telah banyak berubah selama bertahun-tahun. Waktu telah meninggalkan bekas luka yang dalam padanya...",
  str_voice_1602041_25 = "Carleen sekarang bisa mengurus dirinya sendiri... Dia lebih kuat dari yang pernah kubayangkan. Ini membuatku sangat lega.",
  str_voice_1602041_26 = "Saya suka mengatur kamar. Lingkungan yang teratur dapat menyembuhkan jiwa.",
  str_voice_1602041_27 = "Apa yang saya tidak suka...? Jika Anda benar-benar harus tahu, itu ketumbar. Baunya sangat aneh.",
  str_voice_1602041_28 = "Meskipun Colossus memang spektakuler, menambahkan beberapa dekorasi yang hangat dapat memberikan suasana yang lebih hidup.",
  str_voice_1602041_29 = "Ssst, tolong jangan panggil aku Lady Joshua lagi. Bukankah kita sepakat untuk merahasiakan itu? Mulai sekarang, panggil saja aku Joshua, bukan?",
  str_voice_1602041_30 = "Aku menjadi lebih kuat!",
  str_voice_1602041_31 = "Aku merasa seperti telah mengingat sesuatu.",
  str_voice_1602041_32 = "Kekuatan dalam diriku melonjak...",
  str_voice_1602041_33 = "Pedang ada untuk melindungi semua orang!",
  str_voice_1602041_34 = "Kita bisa melakukan ini, bersama-sama.",
  str_voice_1602041_35 = "Cahaya pedang menghiasi kami.",
  str_voice_1602041_36 = "Cahaya perhitungan!",
  str_voice_1602041_37 = "Ajaran suci, beri aku bimbingan!",
  str_voice_1602041_38 = "Cahaya penuntun suci... Pembelahan yang mulia!",
  str_voice_1602041_39 = "Pisau bercahaya!",
  str_voice_1602041_40 = "Tarian Lucent!",
  str_voice_1602041_41 = "Izinkan saya untuk memimpin jalan.",
  str_voice_1602041_42 = "Berikan dan Anda akan menerima.",
  str_voice_1602041_43 = "Mari coba lagi.",
  str_voice_1602041_44 = "Peregangan seperti ini sesekali dapat membantu merilekskan tubuh dan pikiran Anda!",
  str_voice_1602041_45 = "Kalau begitu... Aku akan menerimanya.",
  str_voice_1602041_46 = "Ini adalah hadiah yang sangat bijaksana.",
  str_voice_1602041_47 = "Hadiah yang begitu indah.",
  str_voice_1602041_48 = "Hadiah ini... sangat tidak terduga!",
  str_voice_1602041_49 = "Cita-cita besar memberiku keberanian untuk menggapai langit. Hanya penakut yang tersisa—aku tidak punya keinginan untuk menuruti keraguan diri.",
  str_voice_1602041_50 = "Kebanyakan orang meremehkan cinta antara bangsawan dan rakyat jelata. Saya tidak ingin dia menghadapi lebih banyak perlawanan dalam pemerintahannya di masa depan karena hal ini.",
  str_voice_1602041_51 = "Jika diberi kesempatan, saya berharap untuk mengunjungi makamnya. Lagi pula, sepertinya ada benang tak terlihat di antara kita... Ya, itu adalah benang takdir yang menghubungkan kita.",
  str_voice_1602041_52 = "Alchemy Stars.",
  str_voice_1602041_53 = "Halo!",
  str_voice_1602041_54 = "Selamat pagi!",
  str_voice_1602041_55 = "Selamat sore.",
  str_voice_1602041_56 = "Sudah larut!",
  str_voice_1602041_57 = "Selamat tahun baru. Bekerja keras tahun ini seperti yang Anda lakukan di tahun lalu!",
  str_voice_1502051_1 = "Menemukan tempat terbakar sinar matahari di Gurun Rediesel? Anda perlu merawat kulit Anda dengan lebih baik. Biarkan saya membawa Anda ke spa bagus yang saya tahu.",
  str_voice_1502051_2 = "Untuk menjadi panduan online 24 jam, saya telah berkembang melampaui kebutuhan tidur dan dapat melayani Anda kapan saja.",
  str_voice_1502051_3 = "Arti kebersamaan? Kapan pun Anda membutuhkan saya, saya akan ada untuk Anda sesegera mungkin.",
  str_voice_1502051_4 = "Apakah Anda ingin menghadiri pesta dansa? Menari denganmu seharusnya cukup menyenangkan, tapi sebelum itu, aku harus menyiapkan baju baru.",
  str_voice_1502051_5 = "Fluktuasi emosi mungkin dapat memengaruhi tugas perwalian saya, tetapi teh dapat membantu menstabilkan suasana hati saya. Ini, aku juga membuat cangkir untukmu.",
  str_voice_1502051_6 = "Kota di malam hari selalu menyimpan bahaya tersembunyi, tetapi Anda tidak perlu khawatir—misi saya adalah membuat Anda tetap aman.",
  str_voice_1502051_7 = "Setiap momen di Lumopolis menyimpan keindahan yang begitu unik. Tolong izinkan saya menemani Anda dalam perjalanan Anda berikutnya ke sana.",
  str_voice_1502051_8 = "Menyelesaikan tugas dengan sempurna adalah satu-satunya aturan yang saya jalani, yang berarti saya harus tetap tenang setiap saat, bahkan saat bersama Anda.",
  str_voice_1502051_9 = "Jika saya hanya bisa memakai satu pakaian untuk tidur, saya akan memilih parfum. Kenapa kamu terlihat sangat terkejut? Apakah Anda terkejut dengan jawaban saya, atau apakah Anda tidak menyukai wewangian saya hari ini?",
  str_voice_1502051_10 = "Anak laki-laki juga harus memperhatikan penampilan mereka. Saya dapat membantu Anda memilih pakaian yang sempurna, jika Anda mau.",
  str_voice_1502051_11 = "Melindungi Anda sepanjang perjalanan Anda adalah tanggung jawab dan kehormatan saya, dan saya akan melayani Anda dengan setiap ons keberadaan saya.",
  str_voice_1502051_12 = "Apakah Anda ingin mendengar rumor terbaru? Saya mengetahui rahasia saluran informasi eksklusif, Anda tahu.",
  str_voice_1502051_13 = "Sebagai pemandu, saya akan selalu berada di sisi Anda untuk memastikan Anda tiba dengan selamat di tempat tujuan.",
  str_voice_1502051_14 = "Setiap kali Anda mengenakan pakaian baru, rasanya seperti Anda dilahirkan kembali. Semuanya benar-benar baru, dan Anda bisa melupakan semua yang terjadi di masa lalu.",
  str_voice_1502051_15 = "Oh, untuk menjadi muda dan tetap bersemangat di hari ulang tahunmu... Aku harap kamu tetap muda selamanya.",
  str_voice_1502051_16 = "Apakah Anda tidak membutuhkan saya untuk menemani Anda hari ini? Tentu saja aku mengkhawatirkanmu. Anda memberi saya kesan bahwa Anda sering tersesat.",
  str_voice_1502051_17 = "Hari baru telah dimulai. Apakah Anda punya rencana untuk hari ini? Nah, saya sudah menyiapkan jadwal jalan-jalan untuk Anda.",
  str_voice_1502051_18 = "Saya tidak berencana untuk tidur dalam waktu dekat, ini masih terhitung awal bagi saya. Lagi pula, ini belum fajar.",
  str_voice_1502051_19 = "Malam hari adalah waktu yang paling indah. Apakah Anda menikmati menyelesaikan misi di malam hari seperti saya?",
  str_voice_1502051_20 = "Beberapa orang mengatakan bahwa Lumopolis adalah sarang korupsi yang tersembunyi di balik selubung kesucian, tetapi bagaimanapun juga, saya harus mempertahankannya sampai akhir.",
  str_voice_1502051_21 = "Umbraton adalah tempat yang menarik. Meski terlihat kacau, pada kenyataannya, ia memiliki aturan dan tatanannya sendiri.",
  str_voice_1502051_22 = "Demi White Night.",
  str_voice_1502051_23 = "Eclipsites yang pernah mengakhiri hidup saya... Kali ini, saya tidak akan membiarkan mereka pergi dengan hidup mereka.",
  str_voice_1502051_24 = "Anda benar-benar ingin tahu apa keinginan saya? Selain menjaga Lumopolis, yang kuinginkan hanyalah menemukannya.",
  str_voice_1502051_25 = "Nadine adalah anak yang sangat rajin. Nyatanya, pendekatannya yang sungguh-sungguh terhadap pekerjaan sangat mirip dengan saya.",
  str_voice_1502051_26 = "Jalan-jalan di malam hari, menghirup aroma kopi dan teh, adalah cara favorit saya untuk melepas penat.",
  str_voice_1502051_27 = "Mereka yang menolak ketertiban tidak akan membawa apa-apa selain masalah sepanjang perjalanan kita.",
  str_voice_1502051_28 = "Tidak mudah membimbing orang sebesar itu ke arah yang benar.",
  str_voice_1502051_29 = "Halo saya Ms. Blanc, panduan tepercaya Anda. Anda juga bisa memanggil saya Penjaga Lumopolis. Saya akan melakukan tugas apa pun yang Anda berikan kepada saya dengan sempurna, untuk memastikan bahwa setiap kebutuhan Anda terpenuhi.",
  str_voice_1502051_30 = "Luar biasa.",
  str_voice_1502051_31 = "Semprotkan parfum.",
  str_voice_1502051_32 = "Kenakan gaun.",
  str_voice_1502051_33 = "Menghadiri bola.",
  str_voice_1502051_34 = "Semuanya di sini?",
  str_voice_1502051_35 = "Misi terselesaikan.",
  str_voice_1502051_36 = "Pelindung malam!",
  str_voice_1502051_37 = "Sebuah hadiah, untuk mengenang pertemuan pertama kita.",
  str_voice_1502051_38 = "Saya berdedikasi untuk melayani Anda.",
  str_voice_1502051_39 = "Kombinasi yang sempurna.",
  str_voice_1502051_40 = "Aliansi yang tangguh.",
  str_voice_1502051_41 = "Semuanya, tolong ikuti saya.",
  str_voice_1502051_42 = "Sebuah perjalanan santai.",
  str_voice_1502051_43 = "aku merasa sedikit lelah...",
  str_voice_1502051_44 = "Saya bisa duduk di sini dan menikmati pemandangan indah sepanjang malam.",
  str_voice_1502051_45 = "Terima kasih atas pengakuan Anda.",
  str_voice_1502051_46 = "Inilah yang saya inginkan.",
  str_voice_1502051_47 = "Kebaikanmu tak ternilai harganya.",
  str_voice_1502051_48 = "Kamu punya selera yang bagus. Ini cocok untukku.",
  str_voice_1502051_49 = "Cara terbaik untuk menunjukkan kesuksesan Anda seiring bertambahnya usia adalah dengan tidak memiliki lemari pakaian baru, tetapi tetap dapat mengenakan pakaian lama lebih dari satu dekade yang lalu, yang berarti Anda telah mempertahankan sosok awet muda Anda.",
  str_voice_1502051_50 = "Mengapa saya menyebut diri saya Penjaga Lumopolis? Ini bukan sekadar sesuatu yang saya sebut diri saya—ini adalah penunjukan takdir.",
  str_voice_1502051_51 = "Aku baik-baik saja, aku hanya memastikan riasanku tidak luntur... Ya, aku memastikannya dari pantulan di mata Eclipsites.",
  str_voice_1502051_52 = "Alchemy Stars.",
  str_voice_1502051_53 = "Halo.",
  str_voice_1502051_54 = "Teh atau kopi?",
  str_voice_1502051_55 = "Ke mana Anda ingin pergi hari ini?",
  str_voice_1502051_56 = "Jika Anda tidak bisa tidur, Anda selalu bisa datang dan melihat saya.",
  str_voice_1502051_57 = "Selamat telah mencapai Tahun Baru! Saya harap Anda berhasil menyelesaikan semua misi Anda di masa depan.",
  str_voice_1602061_1 = "Hai! Aku membawakan kamu buah—sepertinya ini jenis baru yang dikembangkan. Aku tidak yakin rasanya enak atau tidak, tapi silakan coba selagi segar!",
  str_voice_1602061_2 = "Jangan pernah berhenti mengejar impianmu! EveSetiap orang memiliki impian mereka sendiri, tetapi hanya mereka yang memiliki keberanian untuk mencapainya yang akan menang di hari itu!",
  str_voice_1602061_3 = "Ah, kopinya di sini benar-benar enak sekali! Saya suka mencoba berbagai rasa dari tempat yang berbeda. Rasanya seperti hidup penuh dengan kebaruan dan keseruan yang tak ada habisnya!",
  str_voice_1602061_4 = "Saya benar-benar merasa bahwa menjadi seorang pengusaha itu sangat menarik. Meskipun, tentu saja, seseorang mungkin menghadapi kesulitan dan hambatan yang tak ada habisnya, rasa pencapaian dan kebebasan yang didapat itu tak ada duanya!",
  str_voice_1602061_5 = "Fiuh, aku sedikit lelah... Tuangkan aku segelas jus, ya? Aku belum pernah mencicipi varian ini sebelumnya, dan aku sangat suka menikmati sensasi baru!",
  str_voice_1602061_6 = "Bagaimana cara saya menjalankan bisnis yang besar seperti ini? Filosofi bisnis saya sangat sederhana: jika Anda akan melakukan sesuatu, lakukan dengan benar. Tidak ada gunanya menyerah pada sesuatu setengah jalan.",
  str_voice_1602061_7 = "Halo! Sepertinya kamu sedang murung akhir-akhir ini... Ada apa? Apakah ada yang menolak kamu? Jangan terlalu khawatir tentang pendapat orang lain, jadilah diri sendiri!",
  str_voice_1602061_8 = "Cuaca hari ini sangat luar biasa! Kenapa kita tidak keluar dan menjelajahi sedikit? Kita mungkin menemukan sesuatu yang baru! Aku baru saja melihat kamu dan ingin mengajakmu keluar...",
  str_voice_1602061_9 = "Erm, apakah aku baru saja tertidur? Aku begadang membaca laporan semalam... Ah! Apakah jas ini milikmu? Kamu menaruhnya di atasku semalam? Hmmm—Tidak, tentu saja aku tidak merona!",
  str_voice_1602061_10 = "Ketika berbicara tentang modal, saya pikir itu seperti pedang bermata dua. Jika Anda ingin memanfaatkannya sebaik mungkin, Anda perlu memahami bagaimana cara menggunakannya.",
  str_voice_1602061_11 = "Kamu ingin saya tinggal? Tentu, saya tidak sering datang ke sini. Evesemuanya di sini terasa segar, dan udaranya sangat menyegarkan, yang sebenarnya sangat membantu bagi saya saat perlu mengambil keputusan bisnis yang penting.",
  str_voice_1602061_12 = "Modal adalah dasar dari semua usaha! Hanya dengan modal yang cukup, kita dapat menciptakan lebih banyak peluang untuk diri kita sendiri!",
  str_voice_1602061_13 = "Mencoba hal baru dan mempelajari adat istiadat serta tradisi tempat yang berbeda dapat membantu kita memahami dunia dengan lebih baik.",
  str_voice_1602061_14 = "Ceritakan sesuatu yang menarik yang terjadi pada kamu hari ini, maukah kamu? Saya benar-benar ingin melihat dunia melalui mata kamu—mungkin itu akan memberi saya inspirasi bisnis yang baru!",
  str_voice_1602061_15 = "Hai! Selamat ulang tahun, sahabat! Apa yang kamu harapkan untuk tahun ini?",
  str_voice_1602061_16 = "Bagaimana dengan hidangan kreatif untuk makan malam hari ini? Ayo, beri kuncup rasa Anda sebuah petualangan!",
  str_voice_1602061_17 = "Selamat pagi! Hari ini adalah hari yang lain! Mari jelajahi peluang baru dan kemungkinan tak terbatas yang ditawarkannya, bersama-sama!",
  str_voice_1602061_18 = "Kamu sudah bekerja seharian, kasihan kamu. Istirahat yang baik dan santai sedikit, ya?",
  str_voice_1602061_19 = "Sudah malam... Aku akan istirahat sekarang, jika tidak, aku tidak akan punya energi untuk menghadapi pekerjaan sepanjang hari besok.",
  str_voice_1602061_20 = "Umbraton adalah tempat yang penuh dengan peluang dan tantangan, tetapi sayangnya, ibu saya tinggal di sana...",
  str_voice_1602061_21 = "Illumina sangat hebat—semua teknologi dan inovasi itu sangat cocok untuk seorang pengusaha seperti aku.",
  str_voice_1602061_22 = "Bayangan mengawasimu.",
  str_voice_1602061_23 = "Setiap Eclipsite yang mencoba mengacaukan bisnisku akan mendapatkan jawaban dariku!",
  str_voice_1602061_24 = "Sinsa memang orang yang hebat... Mungkin saya harus mempertimbangkan untuk berinvestasi dalam lebih banyak proyek di Gurun Rediesel...",
  str_voice_1602061_25 = "Bopper adalah asisten kecil yang dapat diandalkan. Sejujurnya, saya terkejut melihat Aurorian yang begitu sungguh-sungguh dan jujur di Gurun Rediesel.",
  str_voice_1602061_26 = "Saya sangat menyukai perdagangan, dengan semua variabel dan tantangannya... Hanya dalam variabel-variabel tersebut Anda dapat menemukan peluang bisnis.",
  str_voice_1602061_27 = "Saya benar-benar tidak tahan dengan orang yang selalu bersikeras hidup dalam aturan dan peraturan yang kaku. Maksud saya, ayolah... Membosankan!",
  str_voice_1602061_28 = "Jadi, ini adalah aset paling berharga Anda, ya? Oh? Colossus adalah keluarga Anda?! Konsep yang aneh...",
  str_voice_1602061_29 = "Heya! Aku Lorelei, pengusaha luar biasa! Aku selalu mencari peluang bisnis, jadi tentu saja aku sangat menantikan untuk bekerja sama denganmu!",
  str_voice_1602061_30 = "Terima kasih atas investasi Anda.",
  str_voice_1602061_31 = "Permainan dimulai.",
  str_voice_1602061_32 = "Tetap kompetitif.",
  str_voice_1602061_33 = "Kilatan api!",
  str_voice_1602061_34 = "Senang berbisnis dengan Anda.",
  str_voice_1602061_35 = "Kesempatan mengetuk!",
  str_voice_1602061_36 = "Tak ada usaha, tak ada hasil!",
  str_voice_1602061_37 = "Terbuka untuk bisnis!",
  str_voice_1602061_38 = "Modal adalah kekuatan!",
  str_voice_1602061_39 = "Kekuatan pasar!",
  str_voice_1602061_40 = "Menghasilkan uang!",
  str_voice_1602061_41 = "Bekerja bersama saya dan kamu bisa menerima keuntungan bersama!",
  str_voice_1602061_42 = "Itulah yang saya sebut pengembalian yang baik dari investasi.",
  str_voice_1602061_43 = "Pasar itu binatang yang sukar ditebak...",
  str_voice_1602061_44 = "Bisakah saya santai dan membaca laporan bisnis harian saya di sini?",
  str_voice_1602061_45 = "Mau mulai sesuatu dengan saya?",
  str_voice_1602061_46 = "Kamu sangat pandai menarik perhatian orang.",
  str_voice_1602061_47 = "Terima kasih selalu memikirkan aku.",
  str_voice_1602061_48 = "Terima kasih, aku benar-benar menyukainya!",
  str_voice_1602061_49 = "Kredibilitas adalah pondasi kerja sama, dan saya senang berbagi detail tentang asal-usul dan latar belakang saya dengan Anda. Ini adalah satu-satunya cara kita dapat membangun kemitraan yang stabil berdasarkan kepercayaan bersama!",
  str_voice_1602061_50 = "Maaf banget ya tentang semua yang udah kamu alami, tapi kadang aku iri sama kamu yang tumbuh besar sendiri dan benar-benar bebas.",
  str_voice_1602061_51 = "Alihkan dari menyebut saya sebagai pengusaha, lebih baik gunakan gelar yang saya inginkan—Pengejar Mimpi. Saya ingin membuat jejak di dunia ini dan mencapai impian saya melalui kerja keras saya sendiri.",
  str_voice_1602061_52 = "Alchemy Stars.",
  str_voice_1602061_53 = "Halo.",
  str_voice_1602061_54 = "Selamat pagi! Apa rencanamu untuk hari ini?",
  str_voice_1602061_55 = "Apakah pekerjaan berjalan lancar?",
  str_voice_1602061_56 = "Masih naik?",
  str_voice_1602061_57 = "Di tahun baru ini, semoga kamu bisa mencoba lebih banyak hal baru yang kamu minati dan menikmati kehidupan penuh kebebasan setiap hari!",
  str_voice_1602071_1 = "Ayo, teman, kamu terlalu tegang! Hidup itu singkat, jadi jangan terlalu khawatir dengan hal-hal kecil! Energi, semangat, dan gadis-gadis cantik— itulah yang menjadi inti hidup!",
  str_voice_1602071_2 = "Selain menjadi rumah bagi masakan lezat, restoran mewah juga merupakan tempat yang sempurna untuk bertemu wanita tua yang menawan. Dua poin ini saja membuat mereka tempat yang sangat layak untuk dikunjungi, menurut saya.",
  str_voice_1602071_3 = "Sungguh menyakitkan! Kemarin saya meninggalkan sebotol vermouth di sini, jadi mengapa sekarang hilang? Apa yang sebenarnya terjadi... Tunggu—apakah saya meminumnya semua? Maymungkin itulah mengapa kepala saya sangat sakit...",
  str_voice_1602071_4 = "Tentu saja, setiap orang memiliki masa lalu, dan dalam kasus saya... mungkin kata \"penebusan\" adalah kata yang paling tepat untuk menggambarkan sikap saya terhadap semua yang telah saya alami.",
  str_voice_1602071_5 = "Seorang pria selalu perlu mencapai titik balik untuk mengalami pertumbuhan sejati. Hal itu bisa datang dalam bentuk peristiwa yang tak terlupakan, atau... bisa jadi karena cinta yang dikejar sia-sia.",
  str_voice_1602071_6 = "Even seekor capung bisa merindukan langit dan matahari. Setelah bertemu dengan kamu, hati saya merasa sedikit gelisah, tapi jangan salah paham, saya tidak merasa kamu begitu menarik.",
  str_voice_1602071_7 = "Even jika mereka dua puluh tahun lebih tua daripada saya, ada banyak sekali wanita dewasa di luar sana, masing-masing penuh dengan pengalaman dan pesona. Tertarik untuk berkencan dengan salah satunya? Sudah cukup—ikut denganku dan kita akan mencari wanita-wanita tersebut!",
  str_voice_1602071_8 = "Hmm... Kamu berbau seperti anak kecil yang berkeringat. Ambil saja botol parfum ini dan cobalah. Tidak perlu berterima kasih, tentu.",
  str_voice_1602071_9 = "Saya tidak pantas untuk dicintai... dan saya juga tidak mampu mencintai sepenuhnya. Orang bilang saya tidak menganggap hidup dengan serius... Tentu saja, saya setuju sepenuhnya dengan mereka.",
  str_voice_1602071_10 = "Apa yang kamu lakukan berdiri di sini seperti orang bodoh? Tidak ada yang mengajakmu kencan? Wah, itu sungguh disayangkan. Ingin belajar sesuatu tentang manajemen waktu, cukup amati Sang Guru dalam aksi.",
  str_voice_1602071_11 = "Aku akan membutuhkan Anda untuk membayar saya gaji per jam. Ya, 10.000 Nightium per jam, itulah harga persahabatan. Erm... sepertinya situasi keuanganmu sedang tidak baik, jadi kurasa aku akan membantumu untuk saat ini.",
  str_voice_1602071_12 = "Hei, tidak tahukah kamu itu tidak sopan memperlakukan saya seperti pamanmu atau semacamnya?! Kenapa tidak kamu panggil saya Big Cena? Kamu pikir itu terdengar buruk? Yah, itu membuat saya sedih, Nak. Panggil saja saya Cena, lalu.",
  str_voice_1602071_13 = "Banyak fasilitas di resor ini dirancang dengan hati-hati oleh saya sendiri untuk memastikan setiap tamu menikmati pengalaman yang unik dan tak terlupakan...",
  str_voice_1602071_14 = "Kamu mengejutkanku! Bisakah kamu membuat sedikit suara saat menyelinap ke arahku? Saya baru saja berpikir tentang cara mengubah ruangan tua yang membosankan ini menjadi sesuatu yang luar biasa.",
  str_voice_1602071_15 = "Selamat ulang tahun! Semoga kamu menjadi pria bertanggung jawab yang berkarakter di tahun baru ini.",
  str_voice_1602071_16 = "Kenapa kau menatapku? Apakah rambutku berantakan? Maymungkin aku harus mencari tukang cukur untuk merapikan rambutku...",
  str_voice_1602071_17 = "Saya merekomendasikan kamu mencoba eggs Benedict untuk sarapan. Ini bergizi dan lezat!",
  str_voice_1602071_18 = "Malam masih muda! Aku harus segera pergi kencan!",
  str_voice_1602071_19 = "Orang muda jangan bekerja terlalu keras! Ayo habiskan malam bersama-sama!",
  str_voice_1602071_20 = "Setelah bepergian ke seluruh benua, saya tetap memutuskan untuk kembali ke kampung halaman saya. Itulah saatnya saya bertemu dengan mereka—Rediesel Wrench.",
  str_voice_1602071_21 = "Saya menghabiskan waktu yang lama di Lumopolis dan banyak orang baik hati yang merawat saya di sana.",
  str_voice_1602071_22 = "Hiduplah dalam momen sekarang.",
  str_voice_1602071_23 = "Eclipsite mungkin tidak cerdas, tetapi mereka sangat kuat.",
  str_voice_1602071_24 = "Sinsa bukanlah orang yang teliti, tapi kami masih bisa akrab.",
  str_voice_1602071_25 = "Kamu ingin tahu apa hubungan antara aku dan Bopper? Aku rasa bisa dibilang dia seperti anak perempuan bagiku, ha.",
  str_voice_1602071_26 = "Saya suka mencoba parfum baru, meskipun kadang hasilnya bisa bagus dan tidak. Tapi itu bagian dari kesenangannya.",
  str_voice_1602071_27 = "Pria yang bahkan tidak berusaha tampil baik membuatku muak.",
  str_voice_1602071_28 = "Soroz dan saya adalah burung sejenis. Bagaimanapun, kami berdua bisa terbang.",
  str_voice_1602071_29 = "Selamat datang di resor saya. Sebagai pengurus di sini, tugas saya adalah memastikan Anda menikmati waktu yang baik. Oh, hampir saja saya lupa memperkenalkan diri... Anda bisa memanggil saya Cena.",
  str_voice_1602071_30 = "Kita semua butuh ruang untuk bernapas.",
  str_voice_1602071_31 = "Aliran sungai di kampung halaman tiba-tiba terlintas di benak...",
  str_voice_1602071_32 = "Sungai kering mengalir lagi.",
  str_voice_1602071_33 = "Di aliran sungai perak, capung-capung menari sepanjang hari—",
  str_voice_1602071_34 = "Percayalah padaku.",
  str_voice_1602071_35 = "Mereka bersama aku.",
  str_voice_1602071_36 = "Tidak ada yang bisa menghentikanku.",
  str_voice_1602071_37 = "Maylalat, bangun dari mimpi kalian! Riak muncul!",
  str_voice_1602071_38 = "Menari, capung, menari! Lepaskan semuanya!",
  str_voice_1602071_39 = "Selalu ada sisi positif!",
  str_voice_1602071_40 = "Saya tidak melewatkan satu irama pun!",
  str_voice_1602071_41 = "Saya hampir tidak sabar.",
  str_voice_1602071_42 = "Itu baru pemanasan.",
  str_voice_1602071_43 = "Kurasa aku minum terlalu banyak semalam...",
  str_voice_1602071_44 = "Seorang pria sejati harus selalu memperhatikan penampilannya, bahkan di rumah.",
  str_voice_1602071_45 = "Terima kasih sudah repot-repot.",
  str_voice_1602071_46 = "Wow, kamu benar-benar mengerti apa yang aku maksud.",
  str_voice_1602071_47 = "Apakah ada yang perlu saya bantu untuk kamu?",
  str_voice_1602071_48 = "Bagaimana kalau saya beri kamu beberapa tips kencan sebagai balasannya?",
  str_voice_1602071_49 = "Saya lahir di sebuah desa di Lembah Denuo, dan sekarang saya kembali ke sini untuk mengelola sebuah resor... Sepertinya hidup memang begitu kadang-kadang.",
  str_voice_1602071_50 = "Saya tinggal di Lumopolis selama bertahun-tahun dan secara bertahap terpengaruh oleh budaya dan aturan etika sosialnya. Mungkin itu sebabnya kamu pikir saya terlihat sedikit berbeda dari monyet Rediesel Wrench yang biasa.",
  str_voice_1602071_51 = "Kamu ingin tahu mengapa aku kembali ke sini? Aku rasa aku hanya merasa bosan setelah menjelajahi hampir seluruh benua Astra dan merasa muak dengan mengikuti arus.",
  str_voice_1602071_52 = "Alchemy Stars.",
  str_voice_1602071_53 = "Hai.",
  str_voice_1602071_54 = "Selamat pagi.",
  str_voice_1602071_55 = "Selamat sore.",
  str_voice_1602071_56 = "Tidak ada tanggal malam ini?",
  str_voice_1602071_57 = "Selamat Tahun Baru! Di hari spesial seperti ini, bagaimana kalau kamu datang dan bersenang-senang bersama saya?",
  str_voice_1502081_1 = "Lihat, semua orang cukup ikuti rencananya, oke? Jangan terlalu impulsif... ya? Apakah ada yang bisa mendengar aku?! Halo...?!",
  str_voice_1502081_2 = "EveSetiap orang selalu menatap ekor saya—ada yang bahkan bilang ingin membuat hidangan kadal dari ekor saya, dan mereka semua berkata, \"Ekor kadal kan tumbuh lagi setelah dipotong, 'kan?\" Saya agak panik dan lari, tapi mereka semua tertawa... Itu terlalu jauh, 'kan?!",
  str_voice_1502081_3 = "Sudahkah kamu melihat bunga yang Eve kirimkan untukku? Ingat pot tanaman yang ada di ambang jendela? Acho! Maaf, demam hayku baru-baru ini kambuh...",
  str_voice_1502081_4 = "Kadal Raksasa itu teman terbaikku, dia melakukan apa yang kubilang. Apakah teman besarmu burung yang baik? Jika dia tidak merasa baik, mungkin dia perlu diperiksa dengan seksama...",
  str_voice_1502081_5 = "Kamu perlu berhati-hati dengan pasir hisap di gurun. Tentu, bersama saya, kamu akan selalu aman, tetapi kamu mungkin menemukan dirimu dalam bahaya jika sendirian!",
  str_voice_1502081_6 = "Perangkap Guardian memang sangat kuat. Ya, kamu bisa menggunakannya dengan Eclipsites jahat itu, tetapi mereka bahkan lebih baik untuk menghadapi orang-orang jahat...",
  str_voice_1502081_7 = "PlayerName, kamu selalu mendengarkan semua yang ingin aku sampaikan tanpa mencoba menyela... Jadi, kamu dan aku sudah seperti sahabat baik!",
  str_voice_1502081_8 = "Aku juga bisa marah, tahu? Seperti saat orang mencuri camilanku, mengerjai aku, mencoba mengacaukan Rediesel Wrench, atau... mengabaikan aku sama sekali...",
  str_voice_1502081_9 = "Jangan menuduh saya berjalan terlalu pelan... Lihat, ekor saya sangat besar. Jika saya tidak hati-hati, saya bisa menabrak sesuatu!",
  str_voice_1502081_10 = "Jangan sedih, sekarang. Hei, apa kau... tidur? Hmm... sepertinya aku juga agak mengantuk. Mari istirahat... bersama...",
  str_voice_1502081_11 = "PlayerName, kamu ingin aku tetap di sini agar kamu bisa melihatku kapanpun, kan? Aku sangat senang...",
  str_voice_1502081_12 = "Jangan pernah mencoba untuk menggoda saya dengan kue kadal... Itu adalah satu hal yang tidak bisa saya tahan.",
  str_voice_1502081_13 = "Saya perlu meningkatkan kecepatan menulis rencana saya... Saya tahu suatu hari nanti, setiap orang akan mengikuti rencana saya dengan sempurna, dan kita akan memiliki lebih sedikit masalah di sini!",
  str_voice_1502081_14 = "B-Bos! Di mana kebakarannya?! Saya bawa tabung pemadam... Oh! Rupanya aku hanya bermimpi... Aku tidak menakutimu, kan?",
  str_voice_1502081_15 = "Selamat ulang tahun! Aku membuatkan kamu kue rasa kadal ini! Ingat untuk memakannya selagi masih enak!",
  str_voice_1502081_16 = "Hah? Kamu tidak melihat itu baru saja... kan? Tidak mungkin! Tentu saja aku tidak mencuri sebat!",
  str_voice_1502081_17 = "Selamat pagi! Saya sedang bekerja pada jadwal baru untukmu! Tunggu sebentar—segera akan siap!",
  str_voice_1502081_18 = "Selamat malam. Kamu ingin tahu apa yang sedang aku lakukan? Aku hanya menulis di diaryku... Hei! J-Jangan mengintip!",
  str_voice_1502081_19 = "Hmm... Kenapa kamu belum tidur? Yah, karena kamu tidak merasa lelah, aku akan menghabiskan waktu bersamamu untuk sementara.",
  str_voice_1502081_20 = "Di hatiku, Rediesel Wrench adalah rumahku.",
  str_voice_1502081_21 = "Saya dengar di Northland sangat dingin... Saya ingin tahu apakah suatu saat nanti saya akan mendapatkan kesempatan untuk melihatnya sendiri?",
  str_voice_1502081_22 = "Hiduplah sepenuhnya, tetapi dengan penuh kesederhanaan...",
  str_voice_1502081_23 = "Eclipsites adalah makhluk paling mengerikan di seluruh dunia! Aku berharap aku bisa... menghancurkan mereka semua!",
  str_voice_1502081_24 = "Lorelei adalah bos yang hebat! Saya sangat bersyukur atas perhatiannya terhadap saya di taman hiburan...",
  str_voice_1502081_25 = "Sinsa adalah bos yang paling berani dan paling setia di seluruh dunia! D-Dia benar-benar panutan saya!",
  str_voice_1502081_26 = "Cacing goreng Rediesel adalah makanan terlezat di seluruh dunia! Saya tidak akan pernah bosan mengunyah cacing kecil yang menggeliat itu!",
  str_voice_1502081_27 = "Aku benci diabaikan, tapi setiap orang tetap mengabaikanku sama saja...",
  str_voice_1502081_28 = "Hmm... Ini terlihat sangat berbeda dari Kadal Raksasa, tapi sungguh pemandangan yang menakjubkan, Bocah Laki-Laki!",
  str_voice_1502081_29 = "Aku adalah ahli taktik utama di Rediesel Wrench—Bopper! Namun... tidak ada yang benar-benar mendengarkan aku... Oh, aku dengar kamu bisa mengendalikan elang raksasa... Apakah ini elang besar di sini?",
  str_voice_1502081_30 = "Kita perlu lebih hati-hati.",
  str_voice_1502081_31 = "Pasir hisap! Berubah menjadi emas...",
  str_voice_1502081_32 = "Perangkap Guardian telah dimodifikasi dan siap untuk digunakan.",
  str_voice_1502081_33 = "Kami membuat kemajuan, Kadal Raksasa!",
  str_voice_1502081_34 = "A-aku akan berusaha sebaik mungkin!",
  str_voice_1502081_35 = "Aku disini.",
  str_voice_1502081_36 = "Ah! Angin di gurun...",
  str_voice_1502081_37 = "Menari, pasir yang mengalir!",
  str_voice_1502081_38 = "Pasir berputar... Kibaskan badai!",
  str_voice_1502081_39 = "Bersinarlah, pasir emas!",
  str_voice_1502081_40 = "Berkat pasir!",
  str_voice_1502081_41 = "Everyone, ingat untuk selalu memperhatikan saya...",
  str_voice_1502081_42 = "Ini adalah kekuatan dari seorang Guardian.",
  str_voice_1502081_43 = "Lain kali, saya akan merencanakan segala sesuatu dengan lebih hati-hati.",
  str_voice_1502081_44 = "Perut elang besar ini sangat besar... Bisa menampung begitu banyak kamar.",
  str_voice_1502081_45 = "Terima kasih... untuk hadiahnya.",
  str_voice_1502081_46 = "*Menangis* Kamu... ingat apa yang aku suka?",
  str_voice_1502081_47 = "Saya perlu mulai merencanakan apa yang akan saya berikan sebagai balasan untuk kamu...",
  str_voice_1502081_48 = "PlayerName... kamu yang terbaik!",
  str_voice_1502081_49 = "Saya tidak ingat bagaimana wajah orang tua saya, atau apapun tentang masa lalu saya, tapi tidak apa-apa. EveSetiap orang di Rediesel Wrench adalah keluarga saya, dan mereka adalah yang terbaik!",
  str_voice_1502081_50 = "Kamu penasaran tentang mata kanan saya, bukan? Nah, saat saya masih anak-anak, Rediesel Wrench diserang oleh Eclipsite, dan saya terluka dalam serangan itu.",
  str_voice_1502081_51 = "Saya bukan maskot! Jangan dengarkan omongan mereka, saya adalah perwira taktis yang terlatih! Meskipun tidak seperti orang-orang yang sering mengikuti rencana saya...",
  str_voice_1502081_52 = "Alchemy Stars.",
  str_voice_1502081_53 = "Halo!",
  str_voice_1502081_54 = "Selamat pagi…",
  str_voice_1502081_55 = "Selamat sore.",
  str_voice_1502081_56 = "Selamat malam, PlayerName.",
  str_voice_1502081_57 = "Selamat Tahun Baru! Aku tahu hal-hal baik akan datang untuk kita!",
  str_voice_1601214_10 = "Kejujuran adalah kebajikan, tetapi terkadang bisa disalahartikan sebagai kekejaman. Saya lebih memilih jujur dan menyinggung perasaan orang daripada menjadi orang yang munafik dan selalu mencari muka.",
  str_voice_1601214_11 = "Beberapa orang adalah pendosa munafik yang mengklaim moralitas, tetapi melakukan perbuatan lebih buruk daripada iblis yang jahat, bukan? Kamu setuju? Saya sangat menyukainya ketika orang-orang bodoh seperti itu terbongkar apa adanya.",
  str_voice_1601214_16 = "Duri ter-tajam menjaga bunga yang sangat indah. Inilah hakikat kehidupan, di mana rasa sakit dan keindahan hidup berdampingan.",
  str_voice_1601214_17 = "Para penganut itu tenggelam dalam keyakinan palsu mereka pada Tuhan Terang, seperti pengungsi yang putus asa dari kenyataan, mencari cahaya yang tidak ada dalam kegelapan...",
  str_voice_1601214_18 = "Kamu ingin menjebakku di sini seperti hewan peliharaan kecil? Aku bukan burung yang bisa dengan mudah dikurung lama-lama, tapi pemandangan di sini sangat bagus... Mungkin aku akan melihat-lihat saja.",
  str_voice_1601214_19 = "Saya menemukan bahwa kamu sangat menikmati membantu teman-temanmu, yang memang merupakan kualitas yang patut dicontoh, tetapi terkadang kamu juga perlu bertanya pada diri sendiri apakah mereka benar-benar layak untuk dibantu.",
  str_voice_1601214_35 = "Jika kamu tidak bisa mentolerir kepura-puraan dan selalu merasa khawatir tentang tidak benar-benar merasa diterima, itu hanya karena hatimu terlalu tulus, sayang.",
  str_voice_1601214_36 = "Orang yang perkataannya tidak sejalan dengan tindakannya adalah yang paling menakutkan, karena mereka tidak jujur dan tidak dapat dipercaya.",
  str_voice_1601214_37 = "Apakah kamu memiliki rencana untuk hari ini? Atau kamu hanya berencana untuk membiarkan waktu berlalu seperti biasa?",
  str_voice_1601214_38 = "Hari ini akan menjadi hari yang sulit, karena semak-semak mekar penuh. Ini, sayangku, menandakan bahwa siksaan takdir sudah dekat.",
  str_voice_1601214_39 = "Sudah makan malam belum? Bahkan puasa fanatik sekalipun tidak akan membuat imanmu berbuah.",
  str_voice_1601214_40 = "Apakah karena pikiranmu terganggu oleh kepercayaan dan ideologi palsu sehingga kamu enggan tidur?",
  str_voice_1601214_44 = "Penghakiman telah tiba.",
  str_voice_1601214_58 = "Kembali ke apa yang kamu tahu.",
  str_voice_1601214_59 = "Bongkar semua kepura-puraan!",
  str_voice_1601214_60 = "Iman tidak akan pernah hilang.",
  str_voice_1601214_61 = "Duri-duri sedang mekar.",
  str_voice_1601214_62 = "Mari bersenang-senang...",
  str_voice_1601214_63 = "Saya terkejut tidak ada yang menyembah Colossus ini!",
  str_voice_1601214_64 = "Selamat pagi, Navigator.",
  str_voice_1601214_65 = "Udara pagi selalu membuat saya merasa begitu bebas.",
  str_voice_1601214_66 = "Aku akan menggantimu, Navigator.",
  str_voice_1601214_67 = "Selamat pagi. Ada rencana hari ini?",
  str_voice_1601214_68 = "Aku dengar kamu baru saja mulai berolahraga di pagi hari?",
  str_voice_1601214_69 = "Maaf jika saya menimbulkan gangguan, Navigator.",
  str_voice_1601214_70 = "Sarapan hari ini memiliki nuansa Lumopolis sedikit.",
  str_voice_1601214_71 = "Apakah kamu tenggelam dalam keputusasaan di malam hari?",
  str_voice_1601214_72 = "Kegelapan dan keheningan menyelimuti tanah.",
  str_voice_1601214_73 = "Apakah Anda pernah melihat briar mekar penuh?",
  str_voice_1601214_74 = "Pengetahuan sejati adalah anak dari kegelapan dan keheningan.",
  str_voice_1601214_75 = "Saya bebas melakukan apa pun yang saya inginkan dan bergabung dengan grup apa pun yang saya anggap cocok.",
  str_voice_1601214_76 = "Langit gelap, korona merah.",
  str_voice_1601214_77 = "Jika kamu mencari bimbingan... apakah kamu ingin tahu lebih banyak tentang duri-duri di tanganku?",
  str_voice_1601054_10 = "Ada rencana hari ini? Cuaca di luar tampak cerah—kenapa kita tidak pergi ke luar dan bersenang-senang?",
  str_voice_1601054_11 = "EveSetiap orang di Rediesel Wrench terasa seperti keluarga bagiku... Hehe, kamu juga memberikan perasaan itu, Navigator.",
  str_voice_1601054_16 = "Dunia ini sangat luas—kamu tidak bisa membuang waktu dengan kepala di awan! Kemana kita akan pergi selanjutnya? Saya selalu ingin pergi ke Northland.",
  str_voice_1601054_17 = "Aku tidak tahu apa yang sedang dilakukan oleh saudaraku dan semua orang di Rediesel Wrench saat ini... Hmn! Aku harus lebih bersemangat dan bekerja keras untuk membantu kamu, Navigator.",
  str_voice_1601054_18 = "Hmm? Apakah Anda mencari saya? Saya sudah menyiapkan semua barang untuk piknik... Kapan kita berangkat?",
  str_voice_1601054_19 = "Pada akhirnya, tuan putri terbangun dari mimpi buruknya, dan pangeran serta semua orang yang dicintainya ada di sampingnya... Ya! Saya sangat suka akhir cerita ini!",
  str_voice_1601054_35 = "Yah, aku masih seorang gadis, tahu! Tentu saja aku suka berbagai jenis pakaian cantik! Jadi, Navigator... ada saran?",
  str_voice_1601054_36 = "Rumput ini beraroma sangat wangi, matahari terasa hangat... Ah... Aku merasa seperti hampir tertidur.",
  str_voice_1601054_37 = "Aku sudah menunggu kamu untuk waktu yang lama, Navigator! Kita akan bermain di mana hari ini?",
  str_voice_1601054_38 = "*Menguap* Maaf, rasanya aku baru saja bangun tidur... Kakakku bilang kalau aku tidak tidur dengan nyenyak, aku tidak akan bertambah tinggi...",
  str_voice_1601054_39 = "Selamat malam! Hari ini adalah hari yang sibuk. Saya membuatkan Anda secangkir teh, Navigator! Minum itu!",
  str_voice_1601054_40 = "Yaaaaawn... Navigator, apakah kamu pernah menghitung domba saat tidak bisa tidur? Bagaimana dengan menghitung firefly...? Satu firefly... dua firefly... tiga firefly... empat firefly...",
  str_voice_1601054_44 = "Aku siap kapan pun kau siap.",
  str_voice_1601054_58 = "Ayo kita lakukan!",
  str_voice_1601054_59 = "Saya harus melindungi semua orang!",
  str_voice_1601054_60 = "Hilangkan ancamannya!",
  str_voice_1601054_61 = "Ini mungkin sakit!",
  str_voice_1601054_62 = "Kamu tidak diundang!",
  str_voice_1601054_63 = "Aku membawa bunga-bunga yang sangat cantik. Kamu bisa meletakkannya di sekitar Colossus untuk membuatnya terlihat lebih indah.",
  str_voice_1601054_64 = "Mau main keluar?",
  str_voice_1601054_65 = "Apakah kamu yakin tidak ingin mempertimbangkan lagi untuk bergabung dengan Rediesel Wrench?!",
  str_voice_1601054_66 = "Saya sangat bahagia karena saya memiliki saudara, kamu, dan setiap orang di sisi saya selalu.",
  str_voice_1601054_67 = "Tidak bisa buang waktu lagi! Masih banyak tempat yang ingin saya kunjungi bersama kamu, Navigator!",
  str_voice_1601054_68 = "Saya membutuhkan bantuan Anda lagi hari ini, Navigator!",
  str_voice_1601054_69 = "Eee… sebenarnya, baru-baru ini aku belajar memasak. Maymungkin kamu bisa mencoba makanan yang aku buat saat kamu punya waktu?",
  str_voice_1601054_70 = "Belakangan ini saya tidak kehilangan kendali atas kekuatan saya, dan semua berkat kamu, Navigator!",
  str_voice_1601054_71 = "Piknik bersama kamu itu sungguh terbaik, Navigator!",
  str_voice_1601054_72 = "Saudaraku selalu bilang kita perlu \"hidup sepenuhnya,\" jadi mari kita istirahat sejenak dari pekerjaan dan pergi keluar untuk bermain!",
  str_voice_1601054_73 = "Kamu suka teh atau kopi, Navigator? Aku akan membuatkan untukmu sebelum piknik berikutnya.",
  str_voice_1601054_74 = "Hmm? Navigator, ke mana semangatmu hari ini...? Maukah kamu aku ceritakan sebuah kisah yang kudengar dari saudaraku?",
  str_voice_1602091_1 = "Grand Marshal dari Federasi Illumina... Ini memang posisi yang seharusnya aku miliki sejak awal.",
  str_voice_1602091_2 = "Merenungkan diri tidak berarti menjadi tunduk. Hanya aku yang bisa menundukkan diriku sendiri.",
  str_voice_1602091_3 = "Jika kamu ingin bergabung dengan legiunku, tunjukkan seberapa banyak pengetahuanmu tentang pertempuran.",
  str_voice_1602091_4 = "Menjadi diri yang baru sama sekali tidak semudah mengganti seragam, tetapi benar-benar menghapus semua jejak diri saya di masa lalu.",
  str_voice_1602091_5 = "Perubahan pada Red Baron tidaklah mengherankan. Ini adalah pengingat bagi mereka yang memiliki niat jahat bahwa keadilan tidak ada hubungannya dengan bentuk.",
  str_voice_1602091_6 = "Kekuatan mengalir dalam diriku seperti badai petir. Apakah kamu siap membuat gelombang bersamaku?",
  str_voice_1602091_7 = "Aku agak mengerti Reinhardt sekarang. Kamu memiliki potensi yang luar biasa. Tunjukkan padaku apa lagi yang kamu miliki yang belum aku ketahui... Ahem, maksudku, mengenai kehebatanmu.",
  str_voice_1602091_8 = "Kamu bisa mendekat kepadaku. Red Baron hanya menargetkan musuh. Kamu, di sisi lain, adalah seorang teman.",
  str_voice_1602091_9 = "Terima kasih sudah menyembuhkanku, tapi tolong jangan biarkan bawahan saya tahu tentang ini. Simpan rahasia ini hanya antara kamu dan aku, ya?",
  str_voice_1602091_10 = "Masih banyak hal yang tidak bisa saya pahami, tetapi saya sudah terbiasa dengan masalah dan krisis yang datang bersama posisi ini.",
  str_voice_1602091_11 = "Kamu ingin berbicara denganku? Nah, ini bukan lagi Commander Wrath yang dulu di depanmu, jadi saya sarankan kamu memilih kata-kata dengan hati-hati.",
  str_voice_1602091_12 = "Jangan khawatir tentang aku. Misi dengan tingkat kesulitan seperti ini hanya berarti mereka belum tahu apa yang bisa aku lakukan.",
  str_voice_1602091_13 = "Legiun yang aku pimpin hanyalah puncak gunung es militer Illumina. Aku akan meraih kemenangan yang meyakinkan atas lawan yang sombong.",
  str_voice_1602091_14 = "Saya tidak berpikir memiliki sikap serius itu masalah. Jika kamu memimpin pasukan besar, saya bayangkan kamu akan terlihat lebih serius.",
  str_voice_1602091_15 = "Setahun lebih tua, tapi apakah kamu sudah bertambah dewasa demi kepentingan orang-orang di sekitarmu?",
  str_voice_1602091_16 = "Tak usah formalitas, cukup panggil saja aku dengan nama.",
  str_voice_1602091_17 = "Oh, betapa cepatnya waktu berlalu... Aku telah merenungkan situasi ini, dan ternyata sudah fajar.",
  str_voice_1602091_18 = "Mengapa aku tidak melihatmu di lapangan hari ini? Kamu harus berlatih keras untuk mencapai levelku.",
  str_voice_1602091_19 = "Istirahat? Maaf, sekarang bukan waktunya untuk itu.",
  str_voice_1602091_20 = "Seharusnya aku mengantisipasi dahaga kekuasaan dan ambisi yang terus meningkat dari hierarki ini.",
  str_voice_1602091_21 = "Kota apung itu murni melayani bangsawan yang kuno, yang mana aku tidak pernah peduli.",
  str_voice_1602091_22 = "Jayalah Illumina!",
  str_voice_1602091_23 = "Aku akan memberantas setiap kumpulan terakhir dari para bawahan menjijikkan yang merayap.",
  str_voice_1602091_24 = "Untuk mengalahkan Reinhardt, aku harus mengatasi setiap rintangan di jalanku.",
  str_voice_1602091_25 = "\"Hanya Hiiro yang mampu melakukan itu.\" Itulah yang dikatakan semua orang yang bekerja dengannya.",
  str_voice_1602091_26 = "Kampanye yang gigih bukan untuk pensiun santai suatu hari nanti, tetapi untuk mengasah diri dalam prosesnya.",
  str_voice_1602091_27 = "Aku akan membuat mereka yang mengkhianatiku menderita sebelum aku mati.",
  str_voice_1602091_28 = "Legiun ke-4 membutuhkan unit udara. Apakah teman Anda tertarik untuk memimpinnya?",
  str_voice_1602091_29 = "Saya, Wrath, adalah Grand Marshal baru Federasi Illumina. Meskipun saya tidak bisa mengatakan bahwa saya akan bertahan lama dalam posisi ini, saya tetap harus formal saat memperkenalkan diri.",
  str_voice_1602091_30 = "Aku merasa energi tanpa batas!",
  str_voice_1602091_31 = "Ini aku, saksikan kekuatan tak terkalahkanku!",
  str_voice_1602091_32 = "Peningkatan lebih lanjut adalah satu-satunya pilihan!",
  str_voice_1602091_33 = "Kekuatan sejatiku melampaui ini!",
  str_voice_1602091_34 = "Kamu punya pertimbangan yang baik.",
  str_voice_1602091_35 = "May guntur lepaskan!",
  str_voice_1602091_36 = "Sekarang saatnya!",
  str_voice_1602091_37 = "Tombak petir, tusuk!",
  str_voice_1602091_38 = "Rasakan kekuatan guntur!",
  str_voice_1602091_39 = "Aku tak bisa dikalahkan!",
  str_voice_1602091_40 = "Serang!",
  str_voice_1602091_41 = "Legiun perkasa, tunggu perintahku!",
  str_voice_1602091_42 = "Ini hanya setara dengan latihan harian kita.",
  str_voice_1602091_43 = "Fokus dan coba lagi.",
  str_voice_1602091_44 = "Apakah kamu keberatan jika aku melatih prajuritku di sini? Sayang sekali jika membuang-buang ruang luas ini.",
  str_voice_1602091_45 = "Terima kasih, anak buahku akan membutuhkannya.",
  str_voice_1602091_46 = "Hmm... Ceritakan, bagaimana kamu bisa menemukan ini?",
  str_voice_1602091_47 = "Kamu memang sangat bijaksana. Terima kasih.",
  str_voice_1602091_48 = "Terima kasih! Aku tak menyangka kau bisa seperhatian ini.",
  str_voice_1602091_49 = "Tak pernah terpikirkan untuk mencapai posisi Grand Marshal dengan cara seperti ini. Namun jika hanya berdasarkan prestasi, saya pasti layak!",
  str_voice_1602091_50 = "Aku tidak setuju dengan cara Reinhardt menyembunyikan masalah. Namun, mengingat situasinya, aku percaya ambisi pribadi tidak relevan dibandingkan dengan masa depan Illumina.",
  str_voice_1602091_51 = "Meskipun terjepit dan tidak memiliki tempat untuk berlindung, saya tidak akan pernah mentolerir perilaku yang merugikan sesama Illuminan. Semua Aurorian memiliki hak untuk hidup.",
  str_voice_1602091_52 = "Alchemy Stars.",
  str_voice_1602091_53 = "Jawab jika kamu menyalin.",
  str_voice_1602091_54 = "Kamu sudah bangun? Siap untuk latihan pagi.",
  str_voice_1602091_55 = "Kamu tidak bisa menatap terminal terus-menerus.",
  str_voice_1602091_56 = "Jangan lupa latihan besok pagi.",
  str_voice_1602091_57 = "Selamat Tahun Baru.",
  str_voice_1502101_1 = "Demi White Night. Semoga hari Anda damai dan tanpa kejadian buruk.",
  str_voice_1502101_2 = "Jangan anggap saya sebagai gadis suci saat saya hanya biasa saja. Silakan kunjungi toko kelontong dan penjahit saya di pasar saat waktu luang Anda.",
  str_voice_1502101_3 = "Sebagai anak dari Dewa Cahaya, saya berkewajiban melindungi sesama Aurorian dari Eclipsites. Apa tugas Anda?",
  str_voice_1502101_4 = "Terima kasih kepada Dewa Cahaya yang maha agung karena telah memberikan kekuatan padaku untuk menghentikan kegelapan.",
  str_voice_1502101_5 = "Untuk menyelamatkan lebih banyak Aurorian, aku harus menjadi lebih kuat.",
  str_voice_1502101_6 = "Aku akan berdiri di barisan terdepan pasukan Aurorian dan berusaha sebaik mungkin untuk membimbing mereka.",
  str_voice_1502101_7 = "Saya melihat harapan bagi Aurorian dalam diri kamu... Tidak, ubah itu menjadi harapan untuk semua makhluk hidup.",
  str_voice_1502101_8 = "Mau berdoa bersamaku? Ini hanya kebiasaan pribadi. Aku berharap bisa berbagi keyakinanku denganmu saat matahari terbit atau terbenam.",
  str_voice_1502101_9 = "Mm... maafkan saya jika mengatakan sesuatu yang mungkin tidak pantas. Namun, kerja sama kita di medan perang meyakinkan saya bahwa Anda adalah anugerah Tuhan.",
  str_voice_1502101_10 = "Maaf membuatmu menunggu. Aku sedang menceritakan sebuah cerita kepada beberapa anak-anak. Bisa ulangi permintaanmu lagi?",
  str_voice_1502101_11 = "Aku juga seorang prajurit, dan aku harus mengorbankan hidupku untuk tanah ini yang melindungiku.",
  str_voice_1502101_12 = "Sejak saat Eclipsites menyerang Twilight, pilihan satu-satunya bagi kita adalah terjun ke medan perang dan tidak pernah mundur.",
  str_voice_1502101_13 = "Aurorian memiliki hak untuk hidup. Dalam ajaran Dewa Cahaya, tidak ada kematian yang tidak dikehendaki yang diizinkan.",
  str_voice_1502101_14 = "Meskipun lahir di tanah yang terlupakan, para dewa masih bisa mendengar doa kita, karena saya yakin teguh bahwa Dewa Cahaya selalu bersama saya.",
  str_voice_1502101_15 = "Selamat ulang tahun, semoga Dewa Cahaya memberkati kamu.",
  str_voice_1502101_16 = "Sangat senang bertemu denganmu. Menurutmu, mana yang harus kulakukan terlebih dahulu, meningkatkan kemampuan berpedang atau berdoa?",
  str_voice_1502101_17 = "Selamat pagi, semoga Dewa Cahaya melindungi Astra. Bagaimana kalau ikut denganku ke pasar?",
  str_voice_1502101_18 = "Sebagai orang yang saleh, Anda pasti mendengar suara Tuhan dalam pekerjaan sehari-hari Anda.",
  str_voice_1502101_19 = "Masih bangun? Cobalah berdoa di saat larut malam ketika suasana hening. Anda mungkin akan mendengar wahyu dengan lebih jelas.",
  str_voice_1502101_20 = "Secara teknis, saya berasal dari Lumopolis, tetapi orang-orang di Twilight tidak peduli tentang latar belakang satu sama lain.",
  str_voice_1502101_21 = "Para pejuang Illuminan memiliki tujuan yang sama dengan kita: melawan Eclipsites sampai napas terakhir kita.",
  str_voice_1502101_22 = "Demi White Night.",
  str_voice_1502101_23 = "Mereka yang menginjak-injak Aurorian akan dihakimi oleh Dewa Cahaya.",
  str_voice_1502101_24 = "Leo dulunya adalah pria yang sombong dan angkuh. Namun sejak menjadi kapten, fokus utamanya adalah melindungi Twilight.",
  str_voice_1502101_25 = "Joseph adalah seorang pria yang taat. Saya memiliki banyak hal untuk dipelajari darinya tentang gereja.",
  str_voice_1502101_26 = "Ini adalah keinginan terbesar saya agar semua penduduk Twilight menikmati kehidupan yang bahagia dan sejahtera.",
  str_voice_1502101_27 = "Cahaya adalah sumber segalanya. Pendosa yang mencemarkan Dewa Cahaya akan dihapuskan saat cahaya kembali.",
  str_voice_1502101_28 = "Maaf atas permintaan ini, tapi apakah ada ruangan kosong di Colossus untuk saya melaksanakan sholat subuh?",
  str_voice_1502101_29 = "Dewa Cahaya mengalahkan kegelapan, dan orang-orang cahaya akan bersinar selamanya. Saya Joselyne, pelayan cahaya.",
  str_voice_1502101_30 = "God of Light yang abadi!",
  str_voice_1502101_31 = "Aku tak takut apa-apa.",
  str_voice_1502101_32 = "Aku akan menembus kegelapan.",
  str_voice_1502101_33 = "Saya berdedikasi untuk misi suci saya!",
  str_voice_1502101_34 = "Aku tidak takut mati.",
  str_voice_1502101_35 = "Bidik kegelapan!",
  str_voice_1502101_36 = "May semoga Dewa Cahaya memberkati kita!",
  str_voice_1502101_37 = "Oh, Dewa Cahaya, tolong bimbing aku dalam pertempuran!",
  str_voice_1502101_38 = "Aku akan memandu kedatangan cahaya!",
  str_voice_1502101_39 = "Tanpa ampun!",
  str_voice_1502101_40 = "Jangan menahan apa pun!",
  str_voice_1502101_41 = "Ya, aku terbiasa memimpin di garis depan!",
  str_voice_1502101_42 = "Dewa Cahaya menerangi kita.",
  str_voice_1502101_43 = "Kemunduran sementara tidak akan menghentikan kita untuk terus maju.",
  str_voice_1502101_44 = "Anak-anak yatim pasti akan menyukai tempat ini. Jangan khawatir, mereka semua anak-anak yang baik.",
  str_voice_1502101_45 = "Terima kasih. May semoga rahmat Tuhan bersama Anda.",
  str_voice_1502101_46 = "Sungguh kejutan menerima hadiah ini!",
  str_voice_1502101_47 = "Kuhargai kepedulianmu. Apakah ada yang bisa kulakukan untukmu?",
  str_voice_1502101_48 = "Terima kasih, ini hadiah terbaik yang pernah kuterima sejauh ini!",
  str_voice_1502101_49 = "Lahir di perbatasan Astra, saya mengerti pentingnya menyelamatkan Aurorian. Bahkan ketika menghadapi Eclipsite di lingkungan yang berbahaya, umat Dewa Cahaya tidak akan pernah mundur.",
  str_voice_1502101_50 = "Anak-anak yang lahir di Twilight dulu seperti saya, berpikir bahwa kota kecil itu adalah seluruh dunia. Saya akan berusaha sebaik mungkin untuk melindungi dunia mereka.",
  str_voice_1502101_51 = "Illumina, Lumopolis... Banyak yang saling menentang hanya karena mereka terlahir di faksi yang berbeda. Namun, selain Eclipsite, tidak ada musuh yang sebenarnya.",
  str_voice_1502101_52 = "Alchemy Stars.",
  str_voice_1502101_53 = "Halo.",
  str_voice_1502101_54 = "Pagi. Aku sudah berdoa untukmu.",
  str_voice_1502101_55 = "Selamat siang. May tetaplah berani hari ini.",
  str_voice_1502101_56 = "Selamat malam. Cahaya Tuhan tidak pernah pergi.",
  str_voice_1502101_57 = "Selamat Tahun Baru, semoga Dewa Cahaya bersama Anda.",
  str_voice_1600894_10 = "Masih ingat apa yang terjadi? Jangan khawatir, ambil waktu sebentar, aku akan selalu di sini.",
  str_voice_1600894_11 = "Tenanglah dan ceritakan apa yang terjadi, PlayerName. Aku tidak akan berhenti sampai keadilan ditegakkan.",
  str_voice_1600894_16 = "Tolong fokus pada pekerjaanmu. Maaf, saya tidak seharusnya memaksakan kebiasaan kerja saya pada orang lain.",
  str_voice_1600894_17 = "Kesejukan fajar selalu begitu menenangkan. Saatnya untuk bekerja.",
  str_voice_1600894_18 = "Istirahat? Hmm, apa yang harus kulakukan selain bekerja? Ada saran, PlayerName?",
  str_voice_1600894_19 = "Hanya penjahat dan agen keadilan yang aktif pada jam-jam seperti ini. Oh... kamu hanya tidak bisa tidur?",
  str_voice_1600894_35 = "Investigasi selesai.",
  str_voice_1600894_36 = "Maju!",
  str_voice_1600894_37 = "Perlawanan sia-sia!",
  str_voice_1600894_38 = "Ini peringatan terakhirmu!",
  str_voice_1600894_39 = "Eksekusi!",
  str_voice_1600894_40 = "Ini berakhir di sini!",
  str_voice_1600894_44 = "Tolong tempelkan aturan di tempat yang mudah dilihat. Saya tidak ingin tempat ini menjadi tanah tanpa hukum.",
  str_voice_1600894_1 = "Khawatir tentang ketajaman pedangku? Jangan takut, aku hanya menggunakannya untuk melindungi yang lemah dan tak berdaya. Ah, tapi aku tidak bilang kamu lemah atau tak berdaya...",
  str_voice_1600894_2 = "Pakaian ini mengingatkanku untuk selalu bangga melayani orang lain dan mengejar keadilan. Apakah kamu ingin bergabung denganku dalam usaha tersebut?",
  str_voice_1600894_3 = "Maafkan saya jika bekas luka di kaki saya menakutkan Anda. Apa? Anda bilang itu tanda kepercayaan saya pada keadilan? Saya... Saya merasa tersanjung, sungguh...",
  str_voice_1600894_12 = "Satu-satunya orang yang bisa mengalahkan diriku adalah diriku sendiri... Kau yang mengajarkanku itu, PlayerName.",
  str_voice_1600894_13 = "Jika bukan karena kamu, mungkin saya masih terjebak dalam mimpi buruk kebohongan itu. Terima kasih telah membantu saya mendapatkan kembali diri yang sebenarnya.",
  str_voice_1600894_14 = "Tempat yang ingin saya kunjungi? Hmm... Saya pernah mendengar cerita tentang tanah tanpa hukum di mana hukum rimba berkuasa mutlak. Saya tertarik untuk melihat salah satu tempat seperti itu sendiri.",
  str_voice_1600894_58 = "Balai Kehakiman berada di atas hal-hal seperti kemenangan atau kekalahan.",
  str_voice_1600894_59 = "Perbaiki perilaku yang melanggar hukum, dan jangan pernah menengok ke belakang.",
  str_voice_1600894_60 = "Menilai dia... berarti menilai diri saya sendiri.",
  str_voice_1600894_61 = "Kamu mengekspresikan emosimu dengan begitu terbuka... Maksudku, aku sedikit iri dengan itu.",
  str_voice_1600894_62 = "Katakan padaku, apa jenis-jenis hukum yang dimiliki Caelestites?",
  str_voice_1600894_63 = "Saya tahu betul bahwa ayah bukanlah orang yang ingin saya lawan.",
  str_voice_1600894_64 = "\"Keadilan ditentukan oleh pemenang\"? Tidak, seharusnya tidak seperti itu...",
  str_voice_1600894_65 = "Dulu aku percaya bahwa kebahagiaan adalah sebuah kejahatan.",
  str_voice_1600894_66 = "Mungkin sudah saatnya bagi saya untuk mencari hobi.",
  str_voice_1600894_67 = "Terkadang, apa yang melindungi kamu juga yang menghambatmu.",
  str_voice_1600894_68 = "Baiklah, mari kita jalan-jalan. May Aku tanya, kamu akan membawaku kemana?",
  str_voice_1602111_1 = "Apakah kamu mencariku? Jangan khawatir. Aku belum pergi, atau sakit, atau dimakan oleh Eclipsite. A-aku baik-baik saja, terima kasih sudah menanyakan...",
  str_voice_1602111_2 = "Apakah kamu sendirian di Bridge hari ini? Apakah kamu sibuk dengan Soroz? Oh, jangan pedulikan aku. Aku hanya datang untuk memeriksa keadaanmu.",
  str_voice_1602111_3 = "Kamu benar, dunia luar jauh lebih besar daripada yang pernah bisa kubayangkan. Aku bisa tahu hanya dengan berdiri di sini.",
  str_voice_1602111_4 = "Ketika kamu menggunakan kekuatanmu, apakah esku terasa dingin dan tak kenal ampun seperti badai salju di Northland?",
  str_voice_1602111_5 = "Aku ingin memiliki kekuatan untuk melindungi orang-orang yang kucintai, menyembuhkan dan menghangatkan mereka dengan kekuatanku. Tapi aurora di atas, mengapa kekuatanku harus begitu dingin?",
  str_voice_1602111_6 = "Kalau saja aku tidak ceroboh malam itu, mungkin aku takkan memiliki kekuatan seperti ini atau melewatkan kesempatan bersama saudaraku... tapi aku juga takkan bertemu dengan kalian semua.",
  str_voice_1602111_7 = "Saya selalu membayar hutang saya, jadi saya lebih dari bersedia untuk berkontribusi di atas Colossus. Saya bisa membantu membersihkan, menjaga, dan mungkin bahkan memasak... kurasa.",
  str_voice_1602111_8 = "Bisakah kamu beritahu semua orang bahwa saya telah menyiapkan beberapa minuman menyegarkan untuk mereka? Kenapa kamu melihatku seperti itu? Tidak semua yang kusentuh berubah menjadi bencana, tahu.",
  str_voice_1602111_9 = "Aku bahkan tidak menyadari bahwa kita telah bepergian bersama untuk waktu yang cukup lama. Aku agak tidak terlalu bersemangat untuk kembali ke Northland lagi—aku terus menantikan petualangan kita berikutnya. Jujur saja, sejak kapan aku menjadi orang seperti ini?",
  str_voice_1602111_10 = "Apakah kamu benar-benar tidur? Mungkin aku harus mencubitmu sedikit, hanya untuk memastikan... AH! J-Jangan membuka matamu begitu tiba-tiba!",
  str_voice_1602111_11 = "Kamu ingin teman ngobrol? Apa maksudmu, aku \"tampak bersemangat\"?! Aku tidak tahu apa yang kamu bicarakan!",
  str_voice_1602111_12 = "Aku tidak takut sendirian, jadi kamu tidak perlu mengunjungi aku hanya karena kamu pikir aku kesepian. Aku baik-baik saja sendiri.",
  str_voice_1602111_13 = "Apakah kita akan pergi ke tempat yang panas? Biarkan aku menyiapkan beberapa es untuk perjalanan! Sengatan panas adalah kondisi kesehatan yang serius, lho.",
  str_voice_1602111_14 = "Kamu tidak perlu menyiapkan pakaian apa pun untukku. Dari semua orang di Colossus, mungkin aku yang paling tidak terganggu oleh cuaca dingin... B-Berhenti bercanda tentang es lilin!",
  str_voice_1602111_15 = "Aku gagal mencari tahu cara membuat Boneka Windelion, jadi aku membawakanmu hadiah dari Northland sebagai gantinya... Selamat ulang tahun.",
  str_voice_1602111_16 = "Kamu selalu berlarian kesana kemari, berbicara dengan semua Aurorian di kapal. Menjadi Navigator pasti pekerjaan yang berat.",
  str_voice_1602111_17 = "Selamat pagi. Kamu tidak begadang semalam, 'kan? Aku yakin kamu punya banyak pekerjaan, jadi semangat!",
  str_voice_1602111_18 = "Aku datang untuk menanyakan apakah kamu ingin makan bersama, tapi melihat betapa sibuknya kamu... Biar aku bantu saja!",
  str_voice_1602111_19 = "Masih bangun? Ini sudah jauh lewat jam tidurku... Selamat malam... Zzzzz",
  str_voice_1602111_20 = "Tinggal di Northland seperti tinggal sejauh mungkin dari dunia luar. Damai, nyata, namun juga sangat sepi.",
  str_voice_1602111_21 = "Saat kecil, aku bermimpi pergi ke Lumopolis dan hidup seperti seorang tuan putri.",
  str_voice_1602111_22 = "Uhuk... Demi Utara.",
  str_voice_1602111_23 = "Aku juga ingin hidup di dunia tanpa Eclipsites jika bisa... Tapi kita semua tahu itu mustahil, itulah sebabnya aku harus terus menjalankan tugas-tugasku.",
  str_voice_1602111_24 = "Aku tahu No. 33 tidak akan pernah bisa menggantikan adikku, tapi aku tetap ingin menjadi adik perempuannya...",
  str_voice_1602111_25 = "Teman? Hmm... Aku akan bilang Pak Antony sangat bisa diandalkan. Aku sadar aku tidak punya banyak teman sekarang, kamu tidak perlu mengingatkanku.",
  str_voice_1602111_26 = "Aku akan membicarakan hal-hal yang aku suka ketika aku menjadi sebaik dan sekuat kakakku.",
  str_voice_1602111_27 = "Ada banyak hal yang tidak kusukai. Eclipsites, ulat, simpul di rambutku, dan lainnya... Tapi yang paling kubenci adalah kesendirian.",
  str_voice_1602111_28 = "Colossus adalah makhluk yang memiliki kesadaran, bukan? Apakah itu membuatnya menjadi keluargamu? Haruskah saya memperkenalkan diri dengan benar?",
  str_voice_1602111_29 = "Terima kasih telah membebaskan saya dari es dingin Northland... Izinkan saya memperkenalkan diri lagi. Saya Zarya, dan saya berdoa agar Aurora terus membimbing jalan kita!",
  str_voice_1602111_30 = "Rambutku, kembali bersinar lagi.",
  str_voice_1602111_31 = "Aku akan menguasai cahaya di dalam diri.",
  str_voice_1602111_32 = "Kekuatan es ada di tanganku.",
  str_voice_1602111_33 = "Aku akan menjadi prajurit seperti kakakku sebelumnya!",
  str_voice_1602111_34 = "Apa yang bisa saya bantu?",
  str_voice_1602111_35 = "Haruskah aku menyerang sekarang?",
  str_voice_1602111_36 = "May semoga Aurora membimbing kita!",
  str_voice_1602111_37 = "Biarkan hujan es batang!",
  str_voice_1602111_38 = "Ayo beri warna pada salju!",
  str_voice_1602111_39 = "Bersinar, embun beku!",
  str_voice_1602111_40 = "Aku tak akan pernah menyerah!",
  str_voice_1602111_41 = "Baiklah. Aku tidak akan kalah.",
  str_voice_1602111_42 = "Syukurlah aku tidak merusak hal-hal lagi.",
  str_voice_1602111_43 = "A-Aku belum kalah!",
  str_voice_1602111_44 = "Sepertinya kita telah mengambil beberapa penumpang lagi. Semoga sukses, PlayerName!",
  str_voice_1602111_45 = "Apakah semua orang luar suka dengan hal seperti ini?",
  str_voice_1602111_46 = "Untukku? Aku terkejut kamu ingat...",
  str_voice_1602111_47 = "Sejujurnya, aku sudah cukup puas hanya dengan mengobrol.",
  str_voice_1602111_48 = "A-Aku sama sekali tidak tersentuh!",
  str_voice_1602111_49 = "Ibu saya meninggal saat saya masih kecil, dan ayah saya sangat tidak menyukai saya. Saudara perempuan saya adalah orang yang paling penting dalam hidup saya, itulah sebabnya saya bersedia melakukan apa saja untuk menemukannya.",
  str_voice_1602111_50 = "Sejak kecil, aku tidak bisa mengendalikan kekuatanku... Setiap anak di Northland bermimpi untuk menguasai sihir seperti Aurorian dalam cerita kami, tetapi tidak ada yang lebih buruk dalam menguasai Luminatics daripada aku.",
  str_voice_1602111_51 = "Aku menghabiskan lebih dari seabad tidur di dalam es... Kalau bukan karena kamu dan Pak Antony, mungkin aku akan tetap di sana untuk selama-lamanya.",
  str_voice_1602111_52 = "Alchemy Stars.",
  str_voice_1602111_53 = "Di mana kau?",
  str_voice_1602111_54 = "Selamat pagi! Rasanya hangat sekali di sini pagi ini...",
  str_voice_1602111_55 = "Menurutmu agak panas, ya?",
  str_voice_1602111_56 = "Selamat malam. May semoga Cahaya melindungi kamu.",
  str_voice_1602111_57 = "Mungkin aku sudah mengumpulkan terlalu banyak harapan Tahun Baru, tapi aku punya banyak harapan. Bagaimana dengan kamu? Maukah kamu berbagi harapan terdalam dan paling tulus dengan ku?",
  str_voice_1602121_1 = "Aku tak bisa berterima kasih cukup untuk ini! Aku tak pernah menyangka bisa hidup di artefak teknologi kuno seperti ini!",
  str_voice_1602121_2 = "Catatan Observasi Colossus #312: Observasi hari ini fokus pada Firefly yang selalu menarik... Hmm? Kapan kamu muncul di belakangku? Aku bahkan tidak menyadari keberadaanmu!",
  str_voice_1602121_3 = "Jangan khawatir. Dengan kebaikan hati dan dedikasimu, aku yakin kamu akan mewarisi pengetahuan kaum Caelestite, mewujudkan impian mereka, dan melampaui harapan mereka.",
  str_voice_1602121_4 = "Aurorian mengambil kekuatan dari cahaya, jadi apa yang mungkin diindikasikan? Apakah kita anak-anak matahari? Apakah ini mengimplikasikan bahwa semua orang lain hidup dalam kegelapan?",
  str_voice_1602121_5 = "Apakah itu kata-kata dalam buku atau artefak di tanah, semuanya menunjukkan perubahan besar yang telah dialami dunia kita...",
  str_voice_1602121_6 = "Tanah di bawah kaki kita terus berubah, tetapi bintang? Bintang jarang berubah, dan itulah yang membuat astronomi semakin menarik bagiku!",
  str_voice_1602121_7 = "Maaf, bisakah saya minta sedikit waktu Anda? Saya telah membaca berkas Soroz tentang sejarah Caelestites, dan saya ingin menanyakan sesuatu kepada Anda...",
  str_voice_1602121_8 = "Posisi... Sudut... Gaya pasang surut... Formula baru... Huh? Oh, maaf. Kayaknya aku kehilangan fokus. Tadi pertanyaanmu apa ya?",
  str_voice_1602121_9 = "Langit yang cerah dan indah! Terima kasih telah membawa kami ke sini dan menunjukkan puncak Colossus!",
  str_voice_1602121_10 = "Sekarang jika saya mengatur sudut rotasi, bintang-bintang di atas harusnya... Ah! M-Maaf, saya tidak bermaksud menumpahkan air di mana-mana!",
  str_voice_1602121_11 = "Catatan hari ini: cuaca cerah dengan angin barat daya, hari yang sempurna untuk berangkat! Jangan khawatir, aku akan berusaha sebaik mungkin untuk mendukungmu.",
  str_voice_1602121_12 = "Buku adalah salah satu hal terpenting di dunia. Bahkan cerita anak-anak pun bisa menyimpan potongan sejarah yang penting jika Anda tahu di mana harus mencarinya.",
  str_voice_1602121_13 = "Maaf, sepertinya saya belum pernah mendengar ini sebelumnya. Kayaknya memang sudah waktunya untuk mendapatkan pendidikan formal, ya.",
  str_voice_1602121_14 = "Maaf, aku terus gagal untuk memperhatikan kamu. Sebagai teman, aku harus lebih baik... Aku perlu mencari cara untuk menghentikan kebiasaan burukku ini...",
  str_voice_1602121_15 = "Maaf, aku hampir lupa kalau hari ini ulang tahunmu! Jadi, eh... Mau hadiah apa? Silakan, sebutkan apa pun yang kamu inginkan!",
  str_voice_1602121_16 = "Oh tidak, apakah sudah lewat jam makan siang? Maaf, aku selalu lupa! Jangan khawatir mengingatkanku lain kali, ya?",
  str_voice_1602121_17 = "Selamat pagi... Maaf jika aku terlihat agak lelah, aku begadang semalaman memikirkan sesuatu...",
  str_voice_1602121_18 = "Akhirnya gelap di luar! Saya sudah menantikan untuk melakukan penelitian astronomi sepanjang hari ini. Aku akan memberi tahu kamu jika aku menemukan sesuatu yang menarik!",
  str_voice_1602121_19 = "Ada sesuatu yang berbeda tentang bintang itu... Apakah ada awan yang menghalangi? Oh, hai! Kesulitan tidur juga, ya?",
  str_voice_1602121_20 = "Mungkin tidak se-menarik Lumopolis atau Federasi Illumina, tetapi saya yakin bahwa kebenaran tentang dunia kita tersembunyi di suatu tempat di Northland!",
  str_voice_1602121_21 = "True Order membahas banyak topik menarik. Aku hanya berharap tahu apa yang mereka katakan...",
  str_voice_1602121_22 = "Demi Utara!",
  str_voice_1602121_23 = "Kapan Eclipsites pertama kali muncul di dunia kita? Apakah mereka lahir secara alami di dalamnya, atau...?",
  str_voice_1602121_24 = "Nona Zarya mungkin terdengar sedikit keras kepala saat berbicara, tetapi aku tahu dia hanya tulus.",
  str_voice_1602121_25 = "Jika No. 33 tidak mau membahas masa lalunya, saya harus menghormati privasinya, tidak peduli seberapa penasaran saya.",
  str_voice_1602121_26 = "Setiap pengetahuan yang memperluas wawasan kita adalah pengetahuan yang berharga, dan tidak ada yang memperluas wawasan seperti astronomi.",
  str_voice_1602121_27 = "Tahu, aku tidak bisa bilang aku sangat membenci orang yang tidak suka belajar atau bahkan menghancurkan buku. Aku hanya merasa itu adalah tragedi.",
  str_voice_1602121_28 = "Colossus ini adalah harta karun pengetahuan yang sangat besar! Sebuah peninggalan sejarah yang hidup!",
  str_voice_1602121_29 = "Kamu benar-benar bersedia membiarkan saya, seorang sarjana rakyat yang tidak dikenal, naik ke Colossus untuk mengamati dan mencatat fungsinya? Saya... Saya sangat berterima kasih!",
  str_voice_1602121_30 = "Sepertinya aku baru saja mempelajari sesuatu yang baru.",
  str_voice_1602121_31 = "Geografi berfungsi sebagai pondasi yang kuat.",
  str_voice_1602121_32 = "Ilmu botani juga memiliki banyak kegunaan.",
  str_voice_1602121_33 = "Rahasia tak terbatas tersembunyi di antara bintang-bintang.",
  str_voice_1602121_34 = "Kita akan menjelajahi tempat apa hari ini?",
  str_voice_1602121_35 = "Pohon-pohon menuntun jalanku.",
  str_voice_1602121_36 = "Ketahui prinsip-prinsip energi!",
  str_voice_1602121_37 = "Mengaktifkan teknik darurat! Kita harus baik-baik saja... Saya pikir!",
  str_voice_1602121_38 = "Mengaktifkan teknik darurat! Kita pasti akan baik-baik saja!",
  str_voice_1602121_39 = "Serangan terhadap lingkungan!",
  str_voice_1602121_40 = "Penyerapan energi!",
  str_voice_1602121_41 = "Yakin? Baiklah, ikuti aku, semuanya!",
  str_voice_1602121_42 = "Fiuh, lega rasanya ternyata hanya terlihat berbahaya.",
  str_voice_1602121_43 = "Ini hanya goresan. Aku akan baik-baik saja.",
  str_voice_1602121_44 = "Aku hanya ingin melihat lebih dekat patch-patch Colossus ini...",
  str_voice_1602121_45 = "...Apa? Hadiah?",
  str_voice_1602121_46 = "Terima kasih! Ini akan sangat membantu saya!",
  str_voice_1602121_47 = "Kamu benar-benar tahu cara memanjakan teman-temanmu, ya?",
  str_voice_1602121_48 = "Wow, terima kasih! Aku selalu ingin memeriksa salah satu dari ini!",
  str_voice_1602121_49 = "Selama ini aku selalu ingin menghadiri akademi formal untuk melanjutkan studiku. Sayangnya, beberapa upaya terakhirku untuk masuk gagal total.",
  str_voice_1602121_50 = "Ketika aku meninggalkan Northland untuk menjelajahi dunia untuk sementara waktu, aku bertemu beberapa orang yang memiliki pemikiran yang sama dan berbagi keinginan untuk menambah pengetahuan. Sayangnya, jalan yang kami pilih untuk diri kami akhirnya membuat kami terpisah satu sama lain.",
  str_voice_1602121_51 = "Saya tidak keberatan dengan khotbah dan pandangan dari Lumopolis atau True Order. Menurut saya, semua yang mereka sampaikan adalah bagian dari kebenaran dunia kita.",
  str_voice_1602121_52 = "Alchemy Stars.",
  str_voice_1602121_53 = "Tes, tes.",
  str_voice_1602121_54 = "Uh-oh, sudah saatnya mengucapkan selamat pagi!",
  str_voice_1602121_55 = "Apakah kamu bebas sekarang? Saya ingin menunjukkan penemuan terbaru saya!",
  str_voice_1602121_56 = "Saya harap pengamatan malam ini berjalan dengan baik.",
  str_voice_1602121_57 = "Tahun baru lagi, ya? Aku ingin tahu apakah kita akan menemukan penemuan luar biasa tentang dunia kita tahun ini?",
  str_voice_1502131_1 = "Kamu sudah menghabiskan setengah hari di dalam Colossus. Untuk memastikan penyerapan sinar matahari yang cukup, stimulasi otot, dan relaksasi saraf optik, kegiatan di luar ruangan sangat disarankan.",
  str_voice_1502131_2 = "Kamu ingin menolak program kesehatan dan latihan yang telah aku rancang untukmu? Baiklah, aku akan melaporkan keputusanmu kepada Miss Vice sebentar lagi.",
  str_voice_1502131_3 = "Tolong jangan biarkan tabrakan tidak sengaja kita mengganggu Anda. Lapisan luar saya tahan terhadap sebagian besar kontaminan asing, termasuk kopi yang Anda tumpahkan.",
  str_voice_1502131_4 = "Mohon maaf, tetapi drive penyimpanan eksternal saya tidak mengandung data tentang penciptaan saya. Oleh karena itu, saya tidak dapat mengingat detail tentang kelahiran atau modifikasi saya selanjutnya.",
  str_voice_1502131_5 = "Sekarang saya ingat alasan modifikasi saya. Untuk memenuhi misi saya, saya memerlukan tubuh yang mampu mentransmisikan dan mengkonversi Lumina seefisien mungkin.",
  str_voice_1502131_6 = "Durasi misi saya jauh melampaui pemahaman Aurorian biasa, dan demikian pula, tubuh yang melayani misi ini telah menyaksikan banyak kehidupan Aurorian. Dan di masa depan... hal itu akan terus berlanjut.",
  str_voice_1502131_7 = "Kamu tampak sangat tertarik dengan penampilan luar saya. Sebenarnya, ini hanyalah bentuk dasar saya; saya bisa memilih dari banyak bentuk lain tergantung pada lingkungan dan situasi yang ada.",
  str_voice_1502131_8 = "Ketika aku memutuskan untuk bergabung dengan kalian di Colossus, aku memiliki kekhawatiran. Lebih spesifik, aku tidak yakin apakah Aurorian lainnya akan menerima penampilan luarku.",
  str_voice_1502131_9 = "Terima kasih sudah membantu membersihkan permukaan luarku. Sebagai balasannya, izinkan aku membersihkan milikmu juga... Ada masalah?",
  str_voice_1502131_10 = "Sedang siaga... Silakan nikmati waktu siaga Anda sendiri, juga.",
  str_voice_1502131_11 = "Mengerti. Saya akan menggunakan keahlian teknis saya untuk membantu Anda menjalani hari yang sempurna. Silakan pilih item yang ingin diselesaikan dari daftar tugas Miss Vice: Misi Umbraton, Pemeliharaan Colossus, Komunikasi Lumopolis.",
  str_voice_1502131_12 = "Identitasku, misiku, dan segala hal yang terkait dengannya harus tetap dirahasiakan. Namun, saya percaya bahwa pilihanmu tidak akan membahayakan saya.",
  str_voice_1502131_13 = "Melihat seseorang yang terjepit oleh pekerjaan yang tak kunjung selesai adalah sesuatu yang bahkan aku temukan tak tertahankan... Tolong ingat untuk beristirahat sesekali.",
  str_voice_1502131_14 = "Meskipun tahu bahwa ada Aurorian lain seperti diriku di dunia ini, dengan misi yang serupa bahkan tubuh yang mirip, aku tetap tidak dapat memahami perubahan yang mereka alami. Apakah ini artinya merasa kesepian...?",
  str_voice_1502131_15 = "Selamat ulang tahun. Frasa ini tidak ada dalam file ingatan saya—sampai baru-baru ini saya mempelajarinya sendiri.",
  str_voice_1502131_16 = "Silakan menikmati waktu makan Anda. Tidak seperti kebanyakan Aurorian, saya tidak memerlukan asupan makanan.",
  str_voice_1502131_17 = "Tolong ingat untuk bangun pada waktu yang wajar agar saya dapat merencanakan sisa hari Anda dengan baik.",
  str_voice_1502131_18 = "Mohon kembali ke Colossus sesegera mungkin agar kita dapat meninjau tugas-tugas yang menumpuk selama Anda tidak ada.",
  str_voice_1502131_19 = "Semoga malam tidurmu menyenangkan dan nyenyak. Tidak seperti kebanyakan Aurorian, aku tidak memerlukan tidur.",
  str_voice_1502131_20 = "Yang bertanggung jawab atas modifikasi saya tidak meninggalkan rincian tentang identitas mereka, bahkan tidak ada nama. Tapi daripada mengusut asal-usul saya, saya lebih ingin mempelajari lebih lanjut tentang masa depan.",
  str_voice_1502131_21 = "Seseorang pernah memperingatkan saya untuk waspada terhadap mata-mata Federasi Illumina...",
  str_voice_1502131_22 = "Misi baru menunggu di depan sana.",
  str_voice_1502131_23 = "File memori saya berisi catatan yang berkaitan dengan Eclipsites, yang berarti keberadaan mereka di dunia ini merentang jauh ke masa lalu yang jauh.",
  str_voice_1502131_24 = "Master Novio adalah atasan langsung saya, atau seperti kebanyakan Aurorian menyebutnya, \"orang tua\" saya. Apakah itu deskripsi yang akurat?",
  str_voice_1502131_25 = "Saya bertanggung jawab penuh atas semua yang terjadi pada Nona Zarya. Sayangnya, saya tidak tahu bagaimana cara meresapi perasaannya.",
  str_voice_1502131_26 = "Di masa lalu, aku tidak punya kesukaan atau ketidaksukaan, karena misi adalah satu-satunya hal yang penting bagiku. Tapi sekarang, aku tidak begitu yakin...",
  str_voice_1502131_27 = "Aku tidak suka pekerjaan yang tidak memiliki akhir yang jelas. Situasi seperti itu jarang membaik.",
  str_voice_1502131_28 = "File ingatan saya pernah berisi catatan tentang Colossi, tetapi untuk menjaga sebagian besar data saya, catatan-catatan itu harus dihapus.",
  str_voice_1502131_29 = "Saya No. 33, penjaga reruntuhan kuno Northland. Sesuai kesepakatan, saya datang untuk memberikan bantuan.",
  str_voice_1502131_30 = "Upgrade selesai.",
  str_voice_1502131_31 = "Data pertempuran diperbarui.",
  str_voice_1502131_32 = "Iterasi data senjata selesai.",
  str_voice_1502131_33 = "Berkas penyimpanan eksternal sepenuhnya ditingkatkan.",
  str_voice_1502131_34 = "No. 33, siap untuk pertempuran.",
  str_voice_1502131_35 = "Musuh terdeteksi.",
  str_voice_1502131_36 = "Mempersiapkan modifikasi.",
  str_voice_1502131_37 = "Modifikasi selesai. Tembak saat siap.",
  str_voice_1502131_38 = "Rencana optimal terhitung. Eksekusi!",
  str_voice_1502131_39 = "Menembakkan senjata.",
  str_voice_1502131_40 = "Perintah: Hancurkan.",
  str_voice_1502131_41 = "Saya akan bertanggung jawab penuh.",
  str_voice_1502131_42 = "Misi terselesaikan.",
  str_voice_1502131_43 = "Meminta analisis kerusakan.",
  str_voice_1502131_44 = "Suhu normal, sinar matahari normal, cuaca normal. Lokasi ini cocok untuk tidur siangmu berikutnya, PlayerName.",
  str_voice_1502131_45 = "Terima kasih atas dukungan materi Anda.",
  str_voice_1502131_46 = "Terima kasih. Aku akan menyimpan ini di file ingatanku.",
  str_voice_1502131_47 = "Saya bisa belajar banyak dari kamu mengenai etika Aurorian.",
  str_voice_1502131_48 = "Bagaimana Anda berhasil mendekripsi data preferensi saya?",
  str_voice_1502131_49 = "Memang, meskipun tubuh fisikku mengalami perubahan yang signifikan, aku masih tidak dapat disangkal sebagai seorang Aurorian. Evolusi memberiku hak istimewa ini.",
  str_voice_1502131_50 = "Teknologi di bawah permukaan Northland sangat penting untuk keamanan kerajaan dan setiap Aurorian di dunia. Karena alasan ini, saya dilahirkan: seorang penjaga yang dimodifikasi untuk melindungi mesin kuno ini.",
  str_voice_1502131_51 = "Perhitungan awal saya menentukan bahwa saya bisa melanjutkan misi sampai waktu membuat saya dan mesin-mesin ini usang. Namun, akhirnya terjadi kesalahan; kesalahan yang berasal dari pikiran saya, bukan tubuh saya.",
  str_voice_1502131_52 = "Alchemy Stars.",
  str_voice_1502131_53 = "Halo.",
  str_voice_1502131_54 = "Selamat pagi. Mau tahu jam berapa sekarang?",
  str_voice_1502131_55 = "Selamat siang. Aku telah memperbarui beberapa resep milikmu.",
  str_voice_1502131_56 = "Selamat malam. Sekarang menyiapkan lagu pengantar tidur.",
  str_voice_1502131_57 = "Kalender di basis data saya sudah lama kedaluwarsa, tetapi saya bersedia untuk beradaptasi dengan yang baru, dan untuk belajar lebih banyak tentang dunia ini bersama kamu.",
  str_voice_1601881_1 = "Bukan rahasia lagi bahwa semua orang menganggap \"Putri Zhuohua\" hanya sebagai sandera, tetapi \"sandera\" adalah kata yang buruk. Saya lebih suka menganggap diri saya sebagai seorang siswa pertukaran pelajar asing.",
  str_voice_1601881_2 = "Kenapa kamu menatapku seperti itu? Apakah aku mengaplikasikan rouge terlalu banyak pagi ini?",
  str_voice_1601881_3 = "Longzhou dikuasai oleh Kekaisaran Zhao dan delapan kerajaan vasalnya. Meskipun para pemimpinnya tampak bersatu, ada arus bawah yang kuat mengamuk tepat di bawah permukaan... Andai saja saya tidak meninggalkan Kerajaan Ye, saya tidak akan pernah mengetahui hal ini.",
  str_voice_1601881_4 = "Sejujurnya, saya cukup iri pada para idealis pengembara yang hanya menjelajahi dunia. Andai suatu hari semua kewajiban saya terpenuhi, saya ingin hidup sebebas mereka.",
  str_voice_1601881_5 = "Adik perempuanku baru berusia dua tahun saat aku meninggalkan Ye. Dari apa yang Jiu ceritakan, dia sudah mulai belajar menari... Betapa aku ingin melihat penampilannya dengan mataku sendiri.",
  str_voice_1601881_6 = "Menyesuaikan hukum dengan kondisi lokal sangat penting dalam hal tata kelola. Apa yang berhasil di satu negara mungkin tidak seefektif di negara lain. Tolong jangan salah paham—saya mempelajari hal-hal ini dengan harapan suatu hari nanti saya akan bermanfaat bagi paman saya... atau kakak perempuan saya.",
  str_voice_1601881_7 = "\"Pangeran Mahkota Ji ingin menikahi Putri Zhuohua dari Ye.\" Jadi, bahkan kamu juga pernah mendengar tentang ini? Huh, satu tidak ingin menjadi kejam, namun ada saat-saat...",
  str_voice_1601881_8 = "Firefly-mu benar-benar makhluk yang menarik. Mereka mengingatkanku pada Clockwork Birds, mainan favoritku saat masih muda di Ye. Jika suatu saat aku menemukan kayu rosewood yang cocok, pasti akan kubuatkan satu untukmu.",
  str_voice_1601881_9 = "Semua pembicaraanku tentang Ye pasti terdengar sangat monoton bagi kamu sekarang... Hmm, tidak? Oh, begitu... Mungkin suatu hari nanti aku bisa mengajakmu berkunjung ke kampung halamanku.",
  str_voice_1601881_10 = "Silakan melanjutkan kegiatanmu seperti biasa, PlayerName. Aku akan tinggal di sini untuk mengagumi bunga-bunga dan tidak akan pergi ke mana pun tanpa izinmu.",
  str_voice_1601881_11 = "Terima kasih atas undangan yang baik ini, PlayerName. Sejujurnya, aku selalu ingin datang, tetapi tidak pernah menemukan kata-kata untuk mengatakannya. Oh tidak, sepertinya aku lupa membawa makeup...",
  str_voice_1601881_12 = "Kebanyakan orang percaya bahwa takdir kita ditentukan oleh surga, tapi aku tidak setuju.",
  str_voice_1601881_13 = "Pernahkah kamu mendengar tentang seorang pria bernama Bucunzi? Dia adalah seorang jenius dalam bidang pengobatan, seorang bijak berambut putih yang berpakaian serba putih. Tidak? Tidak apa-apa. Saya sudah cukup terbiasa dengan jawaban seperti itu.",
  str_voice_1601881_14 = "Bulan semalam bersinar seperti piring perak murni di tengah latar belakang bintang yang tak terhitung jumlahnya, tetapi itu tidak bisa dibandingkan dengan melihatnya dari kenyamanan tanah airku. Katakan padaku, PlayerName... kapan aku bisa kembali ke rumah lagi?",
  str_voice_1601881_15 = "May semoga kamu hidup hingga seratus tahun, PlayerName. Selamat ulang tahun.",
  str_voice_1601881_16 = "Caeles... Ah, maafkan saya. Apakah kamu sibuk? Aku tidak bermaksud mengganggumu... Hah? Tidak apa-apa?",
  str_voice_1601881_17 = "Bangun pagi bukan juga merupakan kebajikan di Astra?",
  str_voice_1601881_18 = "Angin malam ini sejuk, sempurna untuk berjalan-jalan. Mau ikut bersama saya? Hah? Di Astra, kalian menyebutnya \"kencan\"?",
  str_voice_1601881_19 = "Meskipun malam yang dingin panjang, kamu belum beristirahat, PlayerName. Pergi tidur sebelum ayam berkokok.",
  str_voice_1601881_20 = "Ye memiliki banyak pengrajin terampil. Apapun yang bisa kamu pikirkan, mereka bisa membuatnya.",
  str_voice_1601881_21 = "Saya pernah membaca di sebuah buku bahwa Umbraton adalah tempat paling berpikiran terbuka di Astra, yang menerima keberagaman. Ini terdengar mirip dengan rumah saya.",
  str_voice_1601881_22 = "Inklusivitas adalah pondasi yang menjadi dasar pendirian Ye.",
  str_voice_1601881_23 = "Mengapa Eclipsite, makhluk yang lahir untuk niat jahat, harus ada...?",
  str_voice_1601881_24 = "Jiu adalah karakter yang kompleks. Diamnya menyimpan banyak rahasia.",
  str_voice_1601881_25 = "Paman saya memperlakukan saya dengan baik, tapi saya rasa dia bukan lagi paman yang saya kenal saat saya masih muda.",
  str_voice_1601881_26 = "Ada ribuan bunga di dunia ini, tapi aku hanya mencintai bunga apel kecil.",
  str_voice_1601881_27 = "Kita menentukan takdir kita sendiri. Mengapa menyerahkannya pada tangan peramal yang tidak jujur?",
  str_voice_1601881_28 = "Bagaimana kamu membuat Colossus ini? Aku sangat ingin para pengrajin Ye kami membuat satu.",
  str_voice_1601881_29 = "Apakah kamu PlayerName? Aku mengenalmu; apa yang tidak diketahui? Cukup membuka buku tentang Astra untuk membaca kisahmu. Aku Putri Zhuohua dari Raja Ye— Tidak apa-apa, panggil saja aku Dantang.",
  str_voice_1601881_30 = "Nasibku adalah milikku sendiri!",
  str_voice_1601881_31 = "Halus, seperti semburat aroma.",
  str_voice_1601881_32 = "Simfoni yang luar biasa.",
  str_voice_1601881_33 = "Apakah kamu orang yang membuatku lebih kuat?",
  str_voice_1601881_34 = "Saya akan mengindahkan perintah.",
  str_voice_1601881_35 = "Saatnya bunga mekar.",
  str_voice_1601881_36 = "Waktu terbaik untuk menikmati bunga.",
  str_voice_1601881_37 = "Biarkan kelopak jatuh dengan lembut.",
  str_voice_1601881_38 = "Kembang apel hias yang sarat dengan perasaan.",
  str_voice_1601881_39 = "Berpencar dalam angin.",
  str_voice_1601881_40 = "Bunga, di mana-mana!",
  str_voice_1601881_41 = "Baiklah. Aku tak akan menolak.",
  str_voice_1601881_42 = "Tunggu, aku harus mengaplikasikan riasan wajahku lagi.",
  str_voice_1601881_43 = "Bunga gugur, untuk yang terkalahkan...",
  str_voice_1601881_44 = "Aku tidak pernah membayangkan bagian dalam Colossus bisa begitu memikat...",
  str_voice_1601881_45 = "Apa ini, PlayerName?",
  str_voice_1601881_46 = "Aku cukup suka ini. Terima kasih.",
  str_voice_1601881_47 = "Betapa bijaksananya Anda.",
  str_voice_1601881_48 = "Hari ini aku menerima hadiahmu, suatu hari nanti aku akan membalas budi.",
  str_voice_1601881_49 = "Ayahku tidak pernah memperlakukanku istimewa saat aku kecil karena pernah ada peramal yang mengatakan bahwa aku lahir di hari yang tidak baik dan ditakdirkan untuk hidup penuh kesialan.",
  str_voice_1601881_50 = "Suatu hari, penyakit parah mulai merenggut nyawa banyak orang di kerajaanku. Satu per satu, mereka meninggal di tempat tidur mereka. Aku sendiri pulih hanya dalam waktu tiga hari. Gosip menyebar bahwa aku adalah bintang hitam malapetaka, terkutuk untuk hidup lebih lama dari keluargaku dan melanjutkan hidup sendirian.",
  str_voice_1601881_51 = "Ketika paman saya naik takhta, dia mengasingkan saya ke Ji. Tak lama kemudian, Kerajaan Ye mulai mengalami kemakmuran yang belum pernah terjadi sebelumnya, yang bahkan ayah saya tidak bisa berikan... Mungkin memang benar saya yang membawa kesialan sepanjang waktu?",
  str_voice_1601881_52 = "Alchemy Stars.",
  str_voice_1601881_53 = "Kamu di sana? PlayerName?",
  str_voice_1601881_54 = "Selamat pagi, PlayerName.",
  str_voice_1601881_55 = "Selamat siang.",
  str_voice_1601881_56 = "Sudah makan malam?",
  str_voice_1601881_57 = "Semoga tahun ini paling bahagia, PlayerName. Setiap hari, kita semakin dekat dengan mekarnya bunga di ulang tahun ke-100 Anda.",
  str_voice_1502151_1 = "Rebec—Oh, itu kamu. Ada apa? Jika kamu akan meminta bantuan untuk mengumpulkan utang... Hah, bukan itu alasanmu di sini? Jadi apa sebenarnya yang kamu inginkan?",
  str_voice_1502151_2 = "Pertama-tama, saya bukan tipe orang yang menghargai uang lebih dari segalanya. Kedua, Anda harus membayar uang muka penuh jika ingin mempekerjakan saya untuk suatu pekerjaan. Tapi untuk Anda, saya akan mengurangi tarif saya sebesar 20 persen.",
  str_voice_1502151_3 = "Kisahku sebelum aku bertemu kembali dengan Rebecca? Kamu memang suka ikut campur, ya? Aku tidak ingin mengingat hal-hal seperti itu.",
  str_voice_1502151_4 = "Saya tidak keberatan bekerja, karena bekerja menghasilkan uang. Kamu tidak boleh memberitahu Rebecca tentang pekerjaan gelap yang saya ambil! Saya mohon!",
  str_voice_1502151_5 = "Jika kamu mengalami masalah dengan sesuatu, jangan ragu untuk menemui saya. Mungkin saya tidak bisa membantu, tapi setidaknya saya bisa mendengarkan keluhanmu.",
  str_voice_1502151_6 = "Tak ada yang berani mengganggu Rebecca selama aku di sini! Dia butuh ketenangan untuk pulih sekarang, jadi jika kalian punya sesuatu untuk dikatakan padanya, kalian harus melalui aku dulu!",
  str_voice_1502151_7 = "Kamu ingin tahu tentang masa kecil Rebecca? Ha, semoga berhasil mendapatkan sesuatu dariku! Tapi jika kamu kebetulan tahu beberapa rahasianya... Mungkin aku tertarik untuk melakukan sedikit pertukaran.",
  str_voice_1502151_8 = "Aku ingin menjadi kakak yang pantas—bukan untuk menebus kesalahan, tapi hanya karena itu.\nSuatu hari, aku ingin mendengar Rebecca memanggilku kakaknya lagi dan benar-benar merasakannya.",
  str_voice_1502151_9 = "Pokoknya, jika kamu kebetulan TANPA DISADARI mengambil foto Rebecca, aku akan membayar kamu banyak! Mengerti maksudku? Oh, dan satu hal lagi: jangan berani-berani memberitahunya tentang ini!",
  str_voice_1502151_10 = [[
Dia menghindariku lagi... Apa yang salah dengan diriku? Apakah aku tidak cukup tulus dalam hal ini?
Atau mungkin aku harus mengejutkannya...]],
  str_voice_1502151_11 = [[
Baiklah, tunjukkan padaku si pecundang sedih yang berutang padamu!
Apa? Tidak ada yang berutang padamu? Kenapa tidak bilang dari tadi?!]],
  str_voice_1502151_12 = "Aku ingin sekali bertarung.\nOh hei, kamu datang di saat yang tepat!\nJangan khawatir, aku hanya ingin berlatih teknik ekstorsi, tidak ada yang berbahaya atau—Hei, kembali ke sini!",
  str_voice_1502151_13 = [[
Mengapa aku belum menyerah menjadi penagih utang?
Pertanyaan yang bagus! Jelas, itu karena aku ingin Rebecca menjalani hidup yang baik! Dia sudah mengalami banyak hal... Sebagai kakak perempuannya, ini adalah hal terkecil yang bisa aku lakukan.]],
  str_voice_1502151_14 = "Kamu akan membayar saya untuk bekerja sebagai pengawal atau sekretaris, kan? Hei, jangan melihat saya seperti itu! Saya tidak mencoba memanfaatkan kamu atau apa pun, tetapi saya masih harus memberi makan Rebecca tahu! Saya bahkan akan menerima gaji yang lebih rendah... Ayo, ini adalah kesepakatan yang bagus!",
  str_voice_1502151_15 = "... Aku sudah lama lupa apa yang harus kulakukan untuk ulang tahun, tapi beri tahu saja jika kamu ingin sesuatu!",
  str_voice_1502151_16 = "Yahoo! Bagaimana dengan pekerjaanmu? Pekerjaanku baik-baik saja, seperti yang aku harapkan!",
  str_voice_1502151_17 = "Kamu bangun sangat pagi! Karena kita di sini, kenapa tidak ikut denganku untuk melihat Rebecca?",
  str_voice_1502151_18 = "Wow, kamu tidak melewatkan makan malam, kan? Nah, ambil saja beberapa dari milikku.",
  str_voice_1502151_19 = "Heheh, beberapa pekerjaan memang hanya bisa dilakukan pada jam-jam seperti ini. Percayalah, saya tahu semua tentang itu!",
  str_voice_1502151_20 = "Dunia memang perlu sedikit kekacauan, itulah bagaimana seseorang seperti aku mendapatkan pekerjaan—Hei, itu membuatku terdengar seperti penjahat.",
  str_voice_1502151_21 = "Mereka bilang Lumopolis adalah tempat paling aman di dunia. Aku berpikir untuk mencari Rebecca tempat tinggal di sana.",
  str_voice_1502151_22 = "Rebecca nomor satu di dunia! Tak ada tandingannya!",
  str_voice_1502151_23 = "Jika melunasi hutang adalah bagian alami dari dunia kita, maka membunuh Eclipsite juga demikian.",
  str_voice_1502151_24 = "Meskipun Sheol suka berlagak seolah-olah dia tahu segalanya, saya merasa suatu hari nanti dia akan mengalami kekalahan besar.",
  str_voice_1502151_25 = "Sepertinya Rebecca masih kesulitan untuk melepaskan diri. Serius, tidak perlu malu-malu seperti itu!",
  str_voice_1502151_26 = "Rebecca, Rebecca, Rebecca! Hihihi...",
  str_voice_1502151_27 = "Satu-satunya hal di dunia ini yang tak bisa kubayangkan adalah dibenci oleh Rebecca.",
  str_voice_1502151_28 = "Bisakah aku meminjam Colossus sebentar? Menagih hutang pasti lebih mudah dengan bantuan si raksasa ini!",
  str_voice_1502151_29 = "Hei! Namaku Isa, dan aku adalah penagih hutang profesional sekaligus asisten medis Rebecca. Aku bisa membantu kamu menangani hutang dengan cepat dan mudah. Asalkan kamu adalah kreditur, tentu saja.",
  str_voice_1502151_30 = "Ohhh, aku merasa hebat!",
  str_voice_1502151_31 = "Sekarang aku bisa mengerjakan lebih banyak pekerjaan.",
  str_voice_1502151_32 = "Menuju hidup yang penuh dan bahagia!",
  str_voice_1502151_33 = "Aku tak akan salah dikenali sebagai adik perempuan lagi!",
  str_voice_1502151_34 = "Waktunya bekerja.",
  str_voice_1502151_35 = "Siap untuk pelajaran?",
  str_voice_1502151_36 = "Mulai dari mana, ya?",
  str_voice_1502151_37 = "Mari mulai dari sini!",
  str_voice_1502151_38 = "Mau coba ini?",
  str_voice_1502151_39 = "Apa jawabanmu?",
  str_voice_1502151_40 = "Ayo bekerja sama!",
  str_voice_1502151_41 = "Hai, sekarang bayar.",
  str_voice_1502151_42 = "Hutang lainnya berhasil ditagih!",
  str_voice_1502151_43 = "Oof! Aku lupa ketertarikannya!",
  str_voice_1502151_44 = "Waktu istirahat! Tidak ada yang lebih baik dari foto Rebecca untuk membuatku semangat!\n... Aaaah—!!",
  str_voice_1502151_45 = "Jadi, siapa yang berutang uang padamu?",
  str_voice_1502151_46 = "Untukku? Terima kasih!",
  str_voice_1502151_47 = "Wow... Aku nggak akan menolak itu!",
  str_voice_1502151_48 = "Ohh! Kamu benar-benar mengerti aku, lho!",
  str_voice_1502151_49 = [[
Rebecca dan saya adalah bukti nyata bahwa orang benar-benar dapat dipengaruhi oleh lingkungan sekitar mereka. Meskipun begitu, saya pikir bagian terdalam dari jiwa kita akan selalu sama, tidak peduli apa yang terjadi.
Apa pendapat kamu?]],
  str_voice_1502151_50 = [[
Aku memang tidak pantas jadi kakak perempuan. Aku tahu itu lebih dari siapa pun, tapi aku benar-benar tidak ingin mengakuinya.
Tidak bisa diterima! Bagaimana mungkin aku bisa kalah dengan orang itu?]],
  str_voice_1502151_51 = [[
Berkat kamu, aku tidak mengulangi kesalahan yang sama seperti sebelumnya. Terima kasih karena tidak pernah menyerah, dan telah menyelamatkan Rebecca.
... Terima kasih.]],
  str_voice_1502151_52 = "Alchemy Stars.",
  str_voice_1502151_53 = "Halo!",
  str_voice_1502151_54 = "Anda sudah bangun?",
  str_voice_1502151_55 = "Sedikit kemalasan tak pernah merugikan!",
  str_voice_1502151_56 = "Aku masih bangun. Bagaimana dengan kamu?",
  str_voice_1502151_57 = "Selamat Tahun Baru! Lupakan semua tentang pekerjaan hari ini dan nikmati saja! Saya sudah membuat teh dan kue beras, jadi ayo bergaul dengan Rebecca!",
  str_voice_1602141_1 = "Bisakah racun saya tidak mengganggumu, bukan? Jangan khawatir, itu benar-benar aman... Untuk saat ini.",
  str_voice_1602141_2 = "Ketika kabut beracun menutupi langit, bahkan bernapas menjadi di luar harapan kita... Dan saat itu aku sangat tak berdaya...",
  str_voice_1602141_3 = "Dia pasti mengalami banyak kesakitan dan pengkhianatan setelah kabur dari rumah. Tapi jangan khawatir, aku akan menjaganya dengan baik... Aku bersumpah.",
  str_voice_1602141_4 = "Tugas seorang dokter adalah mengobati pasien, tapi bohong jika aku bilang aku tidak menikmatinya juga. Meski begitu, aku lebih suka jika lebih sedikit orang yang sakit, heheh.",
  str_voice_1602141_5 = [[
Apakah kekuatanku ini kutukan atau anugerah dari langit?
Aku tidak yakin, tapi aku hanya berharap aku bisa menggunakannya untuk melakukan hal yang benar.]],
  str_voice_1602141_6 = "Urgh... Jangan khawatir, aku tidak akan mengulangi kesalahan yang sama seperti sebelumnya. Hanya saja, rasa sakit ini tak bisa dihindari. Mungkin butuh bertahun-tahun atau bahkan puluhan tahun sebelum tubuhku bisa sembuh...",
  str_voice_1602141_7 = "Dulu saya sering bermimpi tentang saat keluarga saya diserang, tetapi sudah lama sekali saya tidak bermimpi tentang itu lagi.",
  str_voice_1602141_8 = [[
Bagiku, kamu juga seperti keluarga. Tidak masalah kan jika aku mengatakan itu?
Tidak apa-apa jika kamu tidak ingin menjawab...]],
  str_voice_1602141_9 = "Hanya setelah mengalami tragedi, rasa sakit, dan perpisahan, kita dapat benar-benar menghargai nilai kehidupan yang damai... Itulah mengapa aku sangat menghargai setiap momen dalam hidupku saat ini.",
  str_voice_1602141_10 = [[
Terima kasih karena selalu ada di sisiku... Dan jangan khawatir, aku sudah jauh lebih baik sekarang.
Juga, aku sangat merindukanmu.]],
  str_voice_1602141_11 = "Maukah kamu menggenggam tanganku satu kali lagi? Terima kasih...",
  str_voice_1602141_12 = "Masih ada sisa racun berlebih di tubuhku... Tapi jangan khawatir, itu hanya menyakitkan aku saja...",
  str_voice_1602141_13 = "Aku membuka praktik baru dekat Umbraton... Ya, namanya sama. Mau mampir?",
  str_voice_1602141_14 = "Bagaimana tepatnya orang-orang Umbraton diuntungkan? Setiap orang diperlakukan seperti angka, dan keluarga menjadi alat untuk memamerkan kekuatan... Saya tidak mengerti, benar-benar tidak...",
  str_voice_1602141_15 = "Hari ini ulang tahunmu? Maaf, aku lupa untuk menyiapkan hadiah... Tapi belum terlambat, 'kan?",
  str_voice_1602141_16 = "Aku sudah menunggumu selama ini...",
  str_voice_1602141_17 = "Aku tidak tahu... sinar matahari pagi bisa sehangat ini...",
  str_voice_1602141_18 = "Kunjungan ke rumah selesai... Sekarang saatnya untuk konsultasi pribadi.",
  str_voice_1602141_19 = "Sudah larut... Tapi kali ini \"cahaya\" itu tak akan pudar.",
  str_voice_1602141_20 = "Yang penting bukan di mana kamu tinggal, tapi dengan siapa kamu memilih untuk menghabiskan hidupmu, 'kan?",
  str_voice_1602141_21 = "Umbraton... Aku masih belum bisa mengerti peraturannya... dan aku juga tidak ingin tahu.",
  str_voice_1602141_22 = "Tak peduli seberapa gelap situasinya, akan selalu ada secercah cahaya yang tersembunyi di balik bayangan.",
  str_voice_1602141_23 = "Makhluk berpikiran sederhana itu tidak akan pernah se-menakutkan seperti hati manusia...",
  str_voice_1602141_24 = "Dia adalah tipe pebisnis yang spesial, dan sulit untuk membaca pikirannya. Juga, saya... benar-benar tidak suka cara dia menatap saya.",
  str_voice_1602141_25 = "Sebagai adiknya, yang aku inginkan hanyalah agar Isa memiliki kehidupan yang sedikit lebih stabil.",
  str_voice_1602141_26 = "Menurut pandangan saya, tidak ada yang lebih berharga daripada sebuah keluarga yang hidup bersama dengan aman dan damai.",
  str_voice_1602141_27 = [[
Apa yang tidak aku suka? Banyak hal, sebenarnya...
Tidak terlihat begitu menurutmu? Mungkin kamu hanya memiliki kesan yang terlalu baik tentang diriku?]],
  str_voice_1602141_28 = "Sudah jelas bagiku bahwa kamu benar-benar menghargai Soroz sebagai anggota keluargamu. Sungguh menyenangkan melihatnya...",
  str_voice_1602141_29 = "Akhirnya, kita bertemu lagi... Mari kita buat janji baru kali ini, yang tak bisa kita langgar.",
  str_voice_1602141_30 = "Tidak ada efek samping yang terlihat.",
  str_voice_1602141_31 = "Tak ada lagi rasa sakit...",
  str_voice_1602141_32 = "Aku berjanji kamu akan sembuh dengan baik.",
  str_voice_1602141_33 = "Tidak ada keberatan? Ayo kita mulai.",
  str_voice_1602141_34 = "Waktunya berkunjung ke rumah?",
  str_voice_1602141_35 = "Menyerah saja...",
  str_voice_1602141_36 = "Aku tidak akan membiarkanmu menyakiti mereka...",
  str_voice_1602141_37 = "Menyebar...",
  str_voice_1602141_38 = "Ini seharusnya berhasil dalam waktu singkat.",
  str_voice_1602141_39 = "Jangan melawannya...",
  str_voice_1602141_40 = "Nyerinya akan segera hilang...",
  str_voice_1602141_41 = "Jika itu untuk melindungi keluargaku...",
  str_voice_1602141_42 = "Fiuh! Ada yang terluka?",
  str_voice_1602141_43 = "Lanjutkan saja tanpa aku...",
  str_voice_1602141_44 = "Apakah ada tempat untuk menyimpan spesimen racun tambahan? Lebih disukai di tempat yang tidak ada orang.",
  str_voice_1602141_45 = "Sudah lama aku tidak mendapat hadiah. Terima kasih.",
  str_voice_1602141_46 = "Ini... untukku? Bisakah aku benar-benar memiliki ini?",
  str_voice_1602141_47 = "Aku mulai terbiasa dengan kebaikan hatimu...",
  str_voice_1602141_48 = "Terima kasih. Aku akan... selalu menghargai ini.",
  str_voice_1602141_49 = "Aku yakin kamu tahu, tapi aku kehilangan keluargaku sudah lama. Terkadang aku bertanya-tanya bagaimana hidupku jika hal itu tidak pernah terjadi.",
  str_voice_1602141_50 = "Keluarga mungkin dulu hanya menjadi pikiran singkat di hati Anda, tetapi sekarang sepertinya Anda memiliki banyak orang di sisi Anda yang layak disebut sebagai keluarga.",
  str_voice_1602141_51 = [[
Saya hampir membuat kesalahan besar.
Namun meskipun begitu, kamu dan adikku tidak pernah menyerah padaku. Andai saja aku tahu cara yang tepat untuk mengungkapkan rasa terima kasihku. Untuk saat ini, ini harus cukup:
Terima kasih.]],
  str_voice_1602141_52 = "Alchemy… Stars?",
  str_voice_1602141_53 = "Halo.",
  str_voice_1602141_54 = "Semoga semuanya berjalan lancar hari ini.",
  str_voice_1602141_55 = "Kira-kira waktunya istirahat, ya?",
  str_voice_1602141_56 = "Hampir waktunya tidur, kamu harus istirahat.",
  str_voice_1602141_57 = [[
Selamat Tahun Baru. Satu tahun berlalu begitu cepat sehingga saya hampir tidak menyadarinya.
Harapan saya untuk tahun baru? Tentu saja, itu adalah untuk mempertahankan kehidupan damai saat ini sepanjang mungkin.]],
  str_voice_1600234_1 = "Hai, ingat aku? Aku Connolly, senang bertemu lagi... Hei, aku berhasil mengeluarkannya!",
  str_voice_1600234_2 = "Apakah ini terlihat bagus untukku...? \"Sangat bagus,\" katamu? Wah, terima kasih...",
  str_voice_1600234_3 = "Anton mengatakan pesta teh sudah siap, tapi apakah ada yang akan datang? Apakah PlayerName akan datang...",
  str_voice_1600234_4 = "*Bersenandung*",
  str_voice_1600234_5 = "T-Terima kasih sudah datang. Saya punya camilan dan kopi untuk kamu, jika kamu tidak keberatan...",
  str_voice_1600234_6 = "Aku punya melodi baru di benakku setelah bangun dari mimpi... Bolehkah aku memainkannya untukmu saat aku siap?",
  str_voice_1600234_7 = "Aku bermimpi bahwa Anton dulunya lebih kuat lagi... Tapi aku merasa cukup bahagia dengan keadaan sekarang karena kehadiran mereka sangat berharga bagiku.",
  str_voice_1600234_8 = "Tentang apa Anton dan aku berbicara? Yah, tentang aku dan kamu... Tunggu, seharusnya aku tidak memberitahumu itu...",
  str_voice_1600234_9 = "Maaf, tapi aku ingin berlatih melodi baru. Apakah itu akan mengganggumu? Hah?! Tidak, kamu tidak perlu meluangkan waktu hanya untuk mendengarkannya!",
  str_voice_1600234_10 = "Selamat pagi, ingin kopi? Ada teh hitam juga lho.",
  str_voice_1600234_11 = "Waktunya sudah lewat, tapi jika kamu mau, aku dengan senang hati akan membuatkan teh sore untukmu...",
  str_voice_1600234_12 = "Lihatlah birunya langit malam yang tak berdasar. Itu seperti dasar samudra. Tanpamu, aku yakin aku tidak bisa menghadapinya sendiri...",
  str_voice_1600234_13 = "Permisi, tapi aku siap untuk bermain...",
  str_voice_1600234_14 = "Siap, Anton?",
  str_voice_1600234_15 = "Semoga ini tidak mengganggu siapa pun.",
  str_voice_1600234_16 = "Terima kasih semua sudah mendengarkan aku bermain.",
  str_voice_1600234_17 = "Suara samudra!",
  str_voice_1600234_18 = "Lagu Aqua!",
  str_voice_1600234_19 = "Tunggu! Kau berlari terlalu cepat, Anton... Sepatuku!",
  str_voice_1600234_20 = "Laut tahu cara bermain dan mendengarkan.",
  str_voice_1600234_21 = "Apakah Anton punya teman? Di laut atau di tempat lain?",
  str_voice_1600234_22 = "Sungguh menakjubkan bagaimana musik bisa menyampaikan begitu banyak hal.",
  str_voice_1600234_23 = "Ikan-ikan semua mendengarkan, tapi kadang-kadang saya masih ingin penonton yang berbeda...",
  str_voice_1600234_24 = "Klarinetku...! Oh, untung saja aku tidak kehilangannya.",
  str_voice_1600234_25 = "Ehem, t-tolong izinkan saya untuk melakukan pertunjukan solo.",
  str_voice_1600234_26 = "Pakaian ini bagus untuk menari? Tapi, bisakah aku menari...?",
  str_voice_1600234_27 = "Oh tidak, menjadi tuan rumah pesta teh jauh lebih melelahkan daripada menjadi pelayan kafe...",
  str_voice_1600234_28 = "Aku ingin kabur, tapi sulit untuk sembunyi dengan kostum ini!",
  str_voice_1600234_29 = "Meskipun hanya mimpi, pelajaran yang saya dapat darinya bukan ilusi, 'kan?",
  str_voice_1600234_30 = "Terima kasih telah datang ke pesta teh Anton dan saya.",
  str_voice_1600234_31 = "Oh, kenapa harus aku...?",
  str_voice_1600234_32 = "Sungguh konyol bagiku menjadi ratu!",
  str_voice_1600234_33 = "Aku perlu bersembunyi, berlindung dalam kegelapan yang akrab...",
  str_voice_1600234_34 = "Musik memiliki kekuatan... dan saya ingin mereka mendengar kemarahan saya!",
  str_voice_1600234_35 = "Tak ada yang memperhatikanku, tak ada yang memperhatikanku...",
  str_voice_1600234_36 = "Huft, huft...",
  str_voice_1600234_37 = "Hah?",
  str_voice_1602161_1 = "Cinta universal dan perdamaian adalah dua prinsip yang paling erat dianut oleh para pengrajin terampil Kerajaan Ye. Rakyat kami diajarkan untuk saling mencintai dan membantu, serta tidak saling menyakiti. Filosofi yang cukup sederhana, bukan? Bahkan hanya dengan dua orang, seharusnya tidak sulit untuk mengikutinya.",
  str_voice_1602161_2 = "Apa yang ingin kamu lihat aku buat hari ini? Seekor banteng tembaga yang mengeluarkan api, atau kalajengking penggali? Atau mungkin layang-layang yang bisa naik dan turun dengan sendirinya?",
  str_voice_1602161_3 = "Kamu ingin belajar cara membuat burung mekanik? Heheh, tidakkah kamu pikir seseorang dengan bakat luar biasa seperti dirimu akan membuang-buang waktu untuk benda kecil seperti itu?",
  str_voice_1602161_4 = "Apakah kamu juga tertarik dengan Payung Anehku? Yah, aku tidak menyalahkanmu! Ini adalah penemuan terhebatku: senjata yang dapat beralih dengan mulus antara kemampuan ofensif dan defensifnya!",
  str_voice_1602161_5 = "Meskipun sebagian besar studi saya berkisar pada mesin, minat saya juga meluas ke dunia makhluk hidup. Bahkan, bisa dikatakan bahwa semua makhluk hidup adalah inspirasi di balik penemuan-penemuan saya.",
  str_voice_1602161_6 = "Orang sering melihatku sebagai penemu eksentrik, dan mengatakan bahwa tindakan, sikap, dan cara berpikirku tidaklah normal... tapi menurutmu bagaimana, Caelestite?",
  str_voice_1602161_7 = "Maukah kamu berjalan-jalan bersamaku? Selama aku membawa payung, kamu tidak perlu khawatir tentang apapun, mulai dari cuaca hingga Eclipsite.",
  str_voice_1602161_8 = "Saya mengerti bahwa Caelestites memiliki beberapa keyakinan yang mirip dengan orang-orang dari kaumku. Apakah Anda tertarik untuk mengunjungi Ye untuk pertukaran budaya?",
  str_voice_1602161_9 = "Selama Anda berada di Longzhou, dengan senang hati saya akan menemani Anda ke mana pun Anda pergi. Selalu ada tempat untuk Anda di bawah payung saya, di mana Anda dapat berlindung dari angin, hujan, dan salju.",
  str_voice_1602161_10 = "...itulah mengapa saya merancang sebuah alat untuk membantu kebiasaan merawat diri... Hmm? Apakah kamu tertidur?",
  str_voice_1602161_11 = "Aku menghabiskan banyak waktu dan usaha untuk membuat pelayan mekanik ini. Dia bisa berjaga, mengangkat air, melakukan pekerjaan-pekerjaan aneh, dan bahkan berbicara dengan menyenangkan. Memang, dia tidak akan pernah bisa menggantikan diriku!",
  str_voice_1602161_12 = "Jika memungkinkan, saya ingin meningkatkan kehidupan sehari-hari setiap rumah tangga di Ye dengan mesin-mesin saya.",
  str_voice_1602161_13 = "Pengunjung dari kerajaan vasal lain selalu mengatakan bahwa Ye terlalu terobsesi dengan barang-barang asing. Menurut pendapat saya, meneliti ide-ide baru jauh lebih bermanfaat daripada terjebak dalam persaingan kekuasaan kuno di negeri kita.",
  str_voice_1602161_14 = "Senjata magis, artefak kuno, senjata ilahi... Di Longzhou, peninggalan kuno ini dikenal dengan banyak nama, dan banyak mekanisme besar yang tidak dapat diaktifkan tanpa mereka.",
  str_voice_1602161_15 = "Tebak apa yang aku punya untukmu hari ini? Apakah itu burung jam mekanik yang sangat rumit, atau semacam patung yang rumit? Tidak ada di antara keduanya! Untuk ulang tahunmu... Aku membawakanmu pelindung dada yang sangat bagus!",
  str_voice_1602161_16 = "Masih sibuk? Jika butuh bantuan, hubungi saja aku, atau burung clockwork-ku.",
  str_voice_1602161_17 = "Tahu nggak... daripada merancang mesin untuk membangunkanmu, kenapa tidak merancang sesuatu untuk mengerjakan pekerjaanmu?",
  str_voice_1602161_18 = "Ahh... Ini hari yang panjang penuh pekerjaan, ya? Mau pergi jalan-jalan sebentar?",
  str_voice_1602161_19 = "Sekali lagi, waktu tidur kita menyelinap sebelum kita puas bersenang-senang. Sungguh sayang.",
  str_voice_1602161_20 = "Kerajaan Ye didirikan berdasarkan konsep cinta universal dan keterampilan kerajinan tangan. Ini adalah tanah yang dijanjikan bagi semua pengrajin terhebat Longzhou, dan saya bangga menyebutnya rumah saya.",
  str_voice_1602161_21 = "Katakanlah... Bisakah kamu menggunakan koneksi kamu untuk memperkenalkan saya kepada beberapa peneliti terbaik Illumina?",
  str_voice_1602161_22 = "Untuk seorang pengrajin sejati, tidak ada yang mustahil!",
  str_voice_1602161_23 = "Saya sangat tertarik dengan cara Astra menangani Eclipsites. Terlepas dari kemampuan, kita harus terus belajar dari berbagai pengalaman agar dapat menghadapi musuh dengan tepat.",
  str_voice_1602161_24 = "Oh, tidak, aku tak akan pernah mengajari Tuan Putri Dantang tentang seni mesin. Hal terakhir yang kubutuhkan adalah orang-orang menuduhku menjerumuskan anggota keluarga kerajaan ke jalan yang salah.",
  str_voice_1602161_25 = "Aku mengagumi Nona Jiu karena mengasah kemampuannya meskipun menghadapi banyak kesulitan dalam hidup. Aku hanya berharap dia tidak terlibat dalam konspirasi lagi.",
  str_voice_1602161_26 = "Hahaha, mereka bilang saya hanya peduli pada mesin, tetapi sebenarnya saya memiliki banyak minat lain. Saya menikmati puisi dan keterampilan pedang, serta semua hal kecil dalam hidup!",
  str_voice_1602161_27 = "Tidak peduli seberapa canggih mesin itu, itu tetap hanya mesin. Mesin tidak akan menyakiti siapa pun kecuali digunakan oleh mereka yang memiliki niat jahat.",
  str_voice_1602161_28 = "Di awal mula ada \"Kun\" dan \"Peng,\" dua makhluk raksasa yang diberi jiwa oleh langit di atas... Ah, maafkan saya. Tiba-tiba saya teringat mitos dari teks kuno kita barusan.",
  str_voice_1602161_29 = "Ah, jadi ini Colossus-mu? ...Tidak perlu terlalu sopan! Kau bisa memanggilku Xuan Ji. Kau tidak keberatan jika aku mengutak-atik beberapa penemuan ku di sini, 'kan?",
  str_voice_1602161_30 = "Teknologi hebat memerlukan keterampilan yang hebat!",
  str_voice_1602161_31 = "Payung besarku sudah siap dan siap digunakan!",
  str_voice_1602161_32 = "Semuanya terhubung dengan sempurna!",
  str_voice_1602161_33 = "Payung besarku bisa menghadapi apa saja!",
  str_voice_1602161_34 = "Ada teknik menarik?",
  str_voice_1602161_35 = "Siap menarik pelatuk!",
  str_voice_1602161_36 = "Badai petir di bawah payung besarku.",
  str_voice_1602161_37 = "Capung, meluncur!",
  str_voice_1602161_38 = "Sebuah sambaran petir yang kuat dengan sekali tekan tombol!",
  str_voice_1602161_39 = "Serangan rantai!",
  str_voice_1602161_40 = "Aktivasi penuh!",
  str_voice_1602161_41 = "Mesin hebat memerlukan tangan yang cakap!",
  str_voice_1602161_42 = "Teknik hebat memerlukan pikiran yang cerdik!",
  str_voice_1602161_43 = "Jangan khawatir, ini hanya hambatan kecil.",
  str_voice_1602161_44 = "Aku akan mengungkap rahasia mesin legendaris dari masa lalu.",
  str_voice_1602161_45 = "Aku tidak pilih-pilih, apapun cocok untukku.",
  str_voice_1602161_46 = "Bagus! Mari kita berteman!",
  str_voice_1602161_47 = "Senang tahu kamu sangat peduli padaku.",
  str_voice_1602161_48 = "Aku harus mencari hadiah ucapan terima kasih yang lebih baik lagi.",
  str_voice_1602161_49 = "Sekolah keahlian yang saya ikuti bernama \"Qianyun,\" dan kebalikannya adalah sekolah \"Dikun.\" Satu unggul dalam tindakan, sementara yang lain unggul dalam ketidakaktifan, tetapi saya percaya bahwa menggabungkan pengetahuan dari kedua sekolah adalah cara terbaik untuk mencapai kemajuan yang sebenarnya.",
  str_voice_1602161_50 = "Saya ingin menciptakan dunia di mana semua pekerjaan ditangani oleh mesin yang tak hidup. Dengan begitu, kita sebagai makhluk hidup dapat fokus pada saling mencintai dan toleransi tanpa hambatan.",
  str_voice_1602161_51 = "Sesuatu yang mengerikan sedang terjadi di Kerajaan Ye yang tampaknya damai, sebuah konspirasi yang berasal dari tempat yang jauh lebih berpengaruh. Akibatnya, saya mengundurkan diri sebagai penasihat dan mulai mencari sumber konflik di kerajaan saya.",
  str_voice_1602161_52 = "Alchemy Stars.",
  str_voice_1602161_53 = "Halo!",
  str_voice_1602161_54 = "Pagi!",
  str_voice_1602161_55 = "Ada yang menarik hari ini?",
  str_voice_1602161_56 = "Oke, saatnya tidur sekarang.",
  str_voice_1602161_57 = "Aku membuat prototipe jam–yang mencatat setiap momen penting dari tahun lalu. Karena kamu bilang tidak ingin melupakan apapun, biarkan jam ini mengingatnya untukmu. Aku menantikan hari-hari bersama kita di masa depan!",
  str_voice_1501871_1 = "Metode peramalan saya diciptakan oleh saya sendiri. Saya menyebutnya Ramalan Hexagram Surgawi. Ini memerlukan penggunaan 25 batang: 12 mewakili \"yin,\" 12 mewakili \"yang,\" dan satu terakhir mewakili keduanya. Dengan meletakkannya di silinder ini dan kemudian melemparkannya keluar, saya dapat memprediksi berbagai hal yang akan datang.",
  str_voice_1501871_2 = [[
- Kurma yang berasal dari pohon-pohon kuno sangat lezat.
- Seringkali orang bertanya-tanya, berapa banyak biji yang bisa dibeli dengan sebatang emas?
- Wah, Squawk dan Jabber, kalian berdua merasa sangat halus, ya? Jangan tanya, aku tidak punya uang. Kalau kalian lapar, pergi ke luar dan makan rumput sendiri.]],
  str_voice_1501871_3 = "Maukah kamu mendengar kisah yang luar biasa? Ahem. Putra kelima Raja Naga, yang mereka sebut \"Suan Ni,\" dikenal sebagai pribadi yang tenang. Namun suatu hari, dia terlibat pertengkaran dengan menteri-menteri tingkat tinggi istana kekaisaran di depan umum, bahkan sampai terjadi kekerasan!",
  str_voice_1501871_4 = "Menjadi penonton yang berharga bukanlah hal yang mudah. Hanya menyaksikan peristiwa terungkap sangat tidak memuaskan, sementara terlibat di dalamnya membuat sulit untuk melepaskan diri. Hal ini bisa diibaratkan dengan menyeberangi sungai di atas jembatan yang terbuat dari satu papan kayu.",
  str_voice_1501871_5 = "\"Orang Terkaya Ketiga\"? \"Penguasa Tongkat\"? \"Si Miskin Bijaksana\"? Ya, aku pernah mendengar tentang mereka, tetapi aku tidak bisa mengatakan bahwa aku mengenal mereka dengan baik!",
  str_voice_1501871_6 = "Ramalanku tidak pernah membahas tentang takdir, melainkan urusan orang-orang biasa. Takdir mengatur hal-hal seperti hidup dan mati; meramalkan kejadian sehari-hari yang rumit, bagaimanapun, jauh lebih menghibur.",
  str_voice_1501871_7 = "Aku belum pernah se-miskin ini sepanjang hidupku! Lihat saja aku! Pakaian penuh lubang, sepatu tanpa sol... bahkan topi ku sudah dicabik-cabik oleh burung-burung ini! Pasti kamu punya beberapa koin untuk berbagi?",
  str_voice_1501871_8 = "Oh, ternyata... Hexagram Anda cukup aneh; saya melihat kucing, hewan yang sering ditemukan di ruang antara yin dan yang, namun tidak ada dalam zodiak. Anda, Caelestite, bukan yin maupun yang, masa depan Anda tersembunyi di balik kabut pilihan Anda. Eh, mendengar sisanya akan dikenakan biaya tambahan, btw.",
  str_voice_1501871_9 = "Raja Naga memiliki sembilan putra, yang masing-masing sangat berbeda satu sama lain. Siapa yang bisa mengatakan siapa yang asli dan siapa yang palsu? Pada akhirnya, setiap orang adalah satu bagian palsu dan satu bagian asli.",
  str_voice_1501871_10 = "Ramalan hanya membutuhkan seseorang untuk menentukan dengan tepat emosi, status, dan niat mereka yang mendekat. Itu saja sudah membuat setengah dari peramalan.",
  str_voice_1501871_11 = "Maukah kamu keberuntunganmu diramal? Aku tidak akan menunda permintaan darimu. Bisakah kamu temukan tempat duduk dulu? Ramalanku selalu lebih akurat saat aku duduk.",
  str_voice_1501871_12 = "Dalam melayani tuan, seseorang harus menyediakan waktu untuk bersantai. Tetapi jika tuan yang Anda layani adalah diri Anda sendiri, maka Anda memiliki seluruh waktu di dunia.",
  str_voice_1501871_13 = "Ada pepatah lama yang berbunyi, \"Seseorang tidak tahu panjangnya perjalanan hingga melaluinya; seseorang tidak mengenal dirinya sendiri, hingga kesulitan memaksa untuk membuat pilihan.\"",
  str_voice_1501871_14 = "Kamu ingin tahu darimana asalnya? Dia datang dari kediaman roh-roh langit di antara awan, berbalut kabut pagi, sebuah siluet yang berkelip.",
  str_voice_1501871_15 = "Oh, hari bahagia! Semoga sukses dalam segala hal, dan semoga semua keinginanmu menjadi kenyataan!",
  str_voice_1501871_16 = "Aduh! Aku ingin menyapa, tapi berkumur dengan air gula malah bikin gigiku sakit...",
  str_voice_1501871_17 = [[
"Bangun!"
Berhenti berteriak! Ini terlalu pagi, aku masih tidur...]],
  str_voice_1501871_18 = "Malam ini kering, jangan biarkan percikan lilin terbang. Tutup pintu, tutup jendela, karena hanya di luar angin akan bertiup.",
  str_voice_1501871_19 = "Lakukan kebaikan di siang hari, dan keberuntungan akan datang pada malam hari.",
  str_voice_1501871_20 = "Ketika mahkota jatuh, lebih baik melarikan diri dengan cepat daripada tertindas oleh reruntuhan.",
  str_voice_1501871_21 = "Dunia ini luas, dan berlimpah kekayaannya!",
  str_voice_1501871_22 = "Dunia yang luas ini menyimpan banyak rahasia. Ayo, mari kita lihat apa yang telah takdir siapkan untukmu!",
  str_voice_1501871_23 = "Eclipsite? Betapa kejinya.",
  str_voice_1501871_24 = "Saya punya seorang teman yang sangat menikmati memancing sendirian di sungai yang dingin dan mengalir dengan mengenakan mantel jerami dan topi bambu, seringkali berdiri seperti bangau.",
  str_voice_1501871_25 = "Tikus Yang dan Tikus Yin—dua kacang dalam satu polong. Mungkin kalian pikir aku sedang meramal, tapi sebenarnya, ini harus dipahami sebagai sebuah ejekan.",
  str_voice_1501871_26 = "Patung gula yang dibuat ayah benar-benar yang terbaik. Sangat jernih, halus, dan bentuknya cerdas.",
  str_voice_1501871_27 = "Tsk... Jalak tidak bisa bisu, tapi saat mereka bicara terlalu banyak, ugh.",
  str_voice_1501871_28 = "Colossus ini memang benda langka. Kamu bisa menjualnya dengan harga yang sangat tinggi!",
  str_voice_1501871_29 = "Saya Li Tianxian, tanyakan padaku tentang dunia, tanyakan tentang hidupmu. Tanyakan tentang gosip pengadilan, tanyakan tentang tetanggamu. Ramalan saya menunjukkan semuanya.",
  str_voice_1501871_30 = "Jaminan uang kembali jika ramalan saya tidak akurat.",
  str_voice_1501871_31 = "Aku tidak lebih dari seorang pengamat, mengamati seluruh dunia yang ada di pandanganku.",
  str_voice_1501871_32 = "Semua dunia ini panggung, jutaan orang, jutaan peran.",
  str_voice_1501871_33 = "Takdir seringkali sudah ditetapkan, namun di tangan manusia terdapat pilihan.",
  str_voice_1501871_34 = "Apakah kita semua berada di pihak yang sama?",
  str_voice_1501871_35 = "Mari kita baca keberuntungan Anda.",
  str_voice_1501871_36 = "Ilahi.",
  str_voice_1501871_37 = "Lihatlah teka-teki semesta yang tak terbatas!",
  str_voice_1501871_38 = "Lihatlah tongkat-tongkat ini, genggamlah takdirmu.",
  str_voice_1501871_39 = "Semua adalah satu.",
  str_voice_1501871_40 = "Satu sudah cukup.",
  str_voice_1501871_41 = "Biar aku yang memimpin jalan.",
  str_voice_1501871_42 = "Kemenangan yang baik!",
  str_voice_1501871_43 = "Di mana keberuntungan ada, di situ juga kemalangan ada.",
  str_voice_1501871_44 = "Semua gosip ini... Lebih buruk daripada kedua burung itu!",
  str_voice_1501871_45 = "Tidak ada perbuatan baik yang tak mendapat balasan...",
  str_voice_1501871_46 = "Hadiah yang luar biasa. Terima kasih!",
  str_voice_1501871_47 = "Aku hampir malu untuk mengambilnya!",
  str_voice_1501871_48 = "Ini sepadan dengan beratnya dalam emas!",
  str_voice_1501871_49 = "Suatu kali, datang seorang gadis dari awan yang memberiku \"Gulir Kenaikan Ilahi.\" Apakah itu pemberian mujur dari langit, atau pemalsuan rumit yang dimaksudkan untuk menipuku? Ataukah itu hanya gulungan kertas toilet yang mewah?",
  str_voice_1501871_50 = "Mereka bilang jalak itu fasih dan gigih. Jangan meremehkan burung-burung yang ada di sekitar saya—mereka tahu lebih banyak dari yang Anda kira.",
  str_voice_1501871_51 = [[
- "Dia pembohong, kadang dia menyamar sebagai pria tua."
- "Kadang dia menyamar sebagai wanita."
- Hmph! Burung-burung bodoh, berhenti bergosip tentang saya! Saya adalah siapa saya dan saya tidak malu akan hal itu!]],
  str_voice_1501871_52 = "Alchemy Stars.",
  str_voice_1501871_53 = "Halo!",
  str_voice_1501871_54 = "Selamat pagi!",
  str_voice_1501871_55 = "Sudah makan belum, teman?",
  str_voice_1501871_56 = "Selamat malam.",
  str_voice_1501871_57 = "Semoga May tahunmu diberkati dan dipenuhi dengan momen-momen kebahagiaan.",
  str_voice_1602181_1 = "Aku telah menyiapkan daftar diskon khusus untukmu. Mau lihat, kan? Oh, dan ada hadiah kecil di belakang untukmu, karena kamu adalah pelanggan spesialku.",
  str_voice_1602181_2 = "Nightium di tangan saya? Kamu sangat tajam penglihatannya. Ini memiliki nilai yang sangat penting bagi saya... Tidak apa-apa. Karena kamu tampak sangat penasaran tentang itu, saya akan memberikannya kepada kamu.",
  str_voice_1602181_3 = "Aku menghabiskan sebagian besar hidupku untuk memilih barang dan negosiasi harga. Ingat kata-kataku—gunakan waktumu yang berharga untuk menciptakan masa depan cerah.",
  str_voice_1602181_4 = "Secara umum, saya jarang menerima tamu secara langsung, tetapi kamu memiliki pesona khusus... Terutama saat membayar tagihanmu.",
  str_voice_1602181_5 = "Pilihan yang berbeda memberikan hasil yang berbeda pula; ini berlaku dalam bisnis maupun kehidupan. Kata-kata bijak ini kuberikan gratis untukmu.",
  str_voice_1602181_6 = "Semua itu menggeledah dan berlarian, seperti tikus kecil yang lucu. Ah, kamu di sana... Pernahkah kamu memelihara ular pelihanaan?",
  str_voice_1602181_7 = "Saya bisa melihat bahwa kamu bingung dan agak ragu, pelanggan kesayanganku... Aku akan menunjukkan bagaimana mengubah uang menjadi keajaiban yang akan selalu bersamamu selamanya...",
  str_voice_1602181_8 = "Hmm? Sudahkah kamu menemukan apa yang kamu cari? Aku? Ha ha, pelanggan yang nakal... Aku tidak dijual!",
  str_voice_1602181_9 = "Mitra, katamu? Heheh, kamu jauh lebih berarti bagi saya daripada itu.",
  str_voice_1602181_10 = "Melamun lagi, pelanggan yang terhormat? Hati-hati, karena harga dan peluang bisnis bisa berubah tanpa pemberitahuan.",
  str_voice_1602181_11 = "Kamu ingin aku menjadi sekretarismu? Tentu saja, sayangku! Aku bisa menghabiskan sehari penuh untuk mengajari kamu berbagai cara menghasilkan uang.",
  str_voice_1602181_12 = "Tidak apa-apa jika kamu tidak membeli apa pun. Bagaimanapun, saya menikmati mengobrol dengan pelanggan saya, dan terkadang peluang bisnis baru muncul dari percakapan kita.",
  str_voice_1602181_13 = "Anda terlalu naif, pelanggan saya yang terhormat. Orang-orang yang berpikiran bisnis harus lebih fleksibel dalam berpikir.",
  str_voice_1602181_14 = "Beberapa orang memanggilku Lachesis yang Rakus... Heheh, aku bisa mengerti mengapa mereka berpikir begitu tentangku. Tapi bagaimana denganmu? Menurutmu, aku ini orang seperti apa?",
  str_voice_1602181_15 = "Selamat ulang tahun. Ini adalah hadiah yang disiapkan khusus untukmu, serta kupon diskon. Jebakan konsumen? Sayangku, kamu jelas berpikir terlalu jauh.",
  str_voice_1602181_16 = "Selamat datang, sayangku. Cloudrover Guild akan selalu menyambut tamu terhormat dengan selera yang tak tertandingi seperti kamu.",
  str_voice_1602181_17 = "Wah, kita terburu-buru hari ini, ya? Jam kerja belum dimulai, jadi harap bersabar.",
  str_voice_1602181_18 = "Makan siang kerja? Tidak, aku telah menyiapkan pilihan yang jauh lebih baik untukmu hari ini...",
  str_voice_1602181_19 = "Dekatlah, sayangku. Apakah kamu ingin mencoba salah satu kasur bulu dari Cloudrover Guild? Mereka sedang ada penawaran spesial sekarang!",
  str_voice_1602181_20 = "Umbraton adalah tanah yang subur di mana bisnis dan dosa dapat berkembang bersama.",
  str_voice_1602181_21 = "Mereka suka membuat masalah kecil menjadi besar, bukan? Cloudrover Guild, dengan armada kapal udara kecilnya, hampir tidak menimbulkan ancaman bagi kota terapung di langit itu. Kamu setuju, bukan?",
  str_voice_1602181_22 = "Bayangan mengawasimu.",
  str_voice_1602181_23 = "Selama mereka bisa digunakan untuk menghasilkan keuntungan, maka bahkan Eclipsite... Heheh, jangan bilang kamu pikir aku serius?",
  str_voice_1602181_24 = "Jadi kamu ingin tahu tentang Istvan, Shadowlord dari Umbraton? Heheh, kamu harus membayar harga untuk informasi seperti itu.",
  str_voice_1602181_25 = "Berinvestasi di Serikat Kurir sebenarnya adalah keputusan bisnis yang sangat berharga. Mengenai alasan saya... Saya akan membagikannya dengan Anda suatu hari nanti di masa depan, saat waktunya tepat.",
  str_voice_1602181_26 = "Menghasilkan uang adalah alasan keberadaanku, tapi aku lebih menyukai orang-orang yang alasan keberadaannya adalah menghabiskan uang!",
  str_voice_1602181_27 = "Saya tidak pernah membenci berbisnis, meski... ada satu jenis bisnis yang kurang saya sukai, yaitu berdagang dengan merugi.",
  str_voice_1602181_28 = "Suatu hari nanti, aku berharap item sehebat Colossus-mu akan menghiasi rak-rak di Cloudrover Guild.",
  str_voice_1602181_29 = "Aku Sheol, pemimpin dari Cloudrover Guild. Mengingat hubungan kita, tidak banyak lagi yang perlu dikatakan, bukan begitu, sayangku?",
  str_voice_1602181_30 = "Investasi yang bijaksana.",
  str_voice_1602181_31 = "Kemitraan kita bisa pergi lebih jauh.",
  str_voice_1602181_32 = "Guild selalu menyambutmu.",
  str_voice_1602181_33 = "Anda telah berinvestasi pada saya sekarang.",
  str_voice_1602181_34 = "Mulai buka untuk bisnis.",
  str_voice_1602181_35 = "Aku mendengar suara uang!",
  str_voice_1602181_36 = "Merencanakan strategi!",
  str_voice_1602181_37 = "Sebuah pukulan telak.",
  str_voice_1602181_38 = "Ini sekarang milikku!",
  str_voice_1602181_39 = "Manfaatkan setiap kesempatan!",
  str_voice_1602181_40 = "Kemenangan yang tidak biasa!",
  str_voice_1602181_41 = "Ayo kita menjadi kaya bersama.",
  str_voice_1602181_42 = "Terima kasih sudah berbelanja di sini!",
  str_voice_1602181_43 = "Apakah saya salah perhitungan sebelumnya...?",
  str_voice_1602181_44 = "Cloudrover Guild menyediakan berbagai jenis furnitur yang indah, beberapa di antaranya akan terlihat sempurna di sini.",
  str_voice_1602181_45 = "Untuk saya? Terima kasih.",
  str_voice_1602181_46 = "Kamu menghabiskan uangmu dengan baik!",
  str_voice_1602181_47 = "Kamu tidak menginginkan sesuatu, 'kan?",
  str_voice_1602181_48 = "Aku pasti akan membalas kebaikanmu.",
  str_voice_1602181_49 = "Saya jarang membual, tapi setelah membangun bisnis besar dari hampir tidak ada apa-apa, saya seharusnya dianggap sebagai salah satu pengusaha paling sukses di Umbraton.",
  str_voice_1602181_50 = "Apakah benar ada alasan untuk membicarakan masa lalu yang tak bisa diperbaiki? Sebagai pelanggan berharga saya, kamu adalah yang paling penting di sini dan sekarang, bukankah kamu setuju?",
  str_voice_1602181_51 = "Sayangku, aliran uang itu seperti aliran darah—sirkulasi yang efisien memompa vitalitas ke dalam masyarakat. Dengan kata lain, Cloudrover Guild adalah organ yang bertanggung jawab untuk mendorong dunia menuju kemakmuran!",
  str_voice_1602181_52 = "Alchemy Stars.",
  str_voice_1602181_53 = "Salam, pelanggan saya yang terhormat.",
  str_voice_1602181_54 = "Selamat pagi, Sayang.",
  str_voice_1602181_55 = "Mampir ke Cloudrover Guild, maukah kamu?",
  str_voice_1602181_56 = "Apa kau sudah tidur, Sayang?",
  str_voice_1602181_57 = "Selamat Tahun Baru, sayangku. Cloudrover Guild telah menambahkan satu tahun lagi bisnis dalam sejarahnya, begitu pula persahabatan kita.",
  str_voice_1602191_1 = "Kamu bilang gaya bermain caturku telah berubah? Langsung, berisiko, dan agresif... Ini selalu menjadi gayaku, meski telah terpendam dalam bayangan selama bertahun-tahun sekarang.",
  str_voice_1602191_2 = "Membuang-buang seluruh semangat adalah kesalahan umum masa muda, dan aku tidak terkecuali. Menyembunyikan kekuatan sejati adalah strategi yang diperlukan.",
  str_voice_1602191_3 = "Saya tidak mau melihat bekas lukaku sebagai penghargaan. Saat luka baru sembuh di atas luka lama, mereka menjadi baju besiku... Bagian lain dari siapa diri sejatiku.",
  str_voice_1602191_4 = "Whispering Corridor yang penuh perangkap, di mana bahkan bayangan itu sendiri harus berjalan dengan hati-hati. Sebuah permainan jahat dan tidak berarti, meskipun kemenangan masih sangat membangkitkan semangat.",
  str_voice_1602191_5 = "Kemampuan untuk menanamkan ketakutan pada orang lain adalah kekuatan yang mengesankan untuk digunakan. Tidak bisa dipungkiri bahwa penampilan alamiahku telah memberikan banyak keuntungan bagiku.",
  str_voice_1602191_6 = "Ketika bekas luka seseorang terungkap di siang bolong, kekuatan mereka muncul ke permukaan di bawah tatapan orang lain. Sebuah bayangan... juga tidak pernah seharusnya menyembunyikan kebenaran dari dirinya sendiri.",
  str_voice_1602191_7 = "Apakah kamu suka dengan jas dan sepatu yang kamu lihat di lemari pakaianku? Pakaian karismatik itu berfungsi sebagai penyamaran yang sempurna, memungkinkan saya menjadi bayangan sejati...",
  str_voice_1602191_8 = "Saya memiliki banyak botol anggur di koleksi saya yang seumuran denganmu, jika tidak lebih tua. Masih terlalu dini untukmu mencoba mereka, tetapi saya akan pastikan untuk membuka satu untukmu saat kamu cukup umur.",
  str_voice_1602191_9 = "Cara bermain caturmu mirip dengan seorang teman lama saya. Saat itu, saya tidak bisa menyelamatkannya... Saya menolak untuk membiarkanmu mengalami nasib yang sama.",
  str_voice_1602191_10 = "Haha, tenggelam dalam pikiran itu baik, tapi melamun tidak.",
  str_voice_1602191_11 = "Setiap bekas luka di tubuhku adalah mata, dan aku akan menggunakan setiap dari mereka untuk membantumu mengawasi dunia ini.",
  str_voice_1602191_12 = "Moralitas dan perubahan adalah dua hal yang harus diperoleh melalui perjuangan. Kamu seharusnya sudah tahu sekarang bahwa prinsip ini berlaku bahkan untuk dunia yang bebas dari Eclipsite.",
  str_voice_1602191_13 = "Ada anak-anak di dunia ini dengan bakat luar biasa yang hidup dalam keadaan di luar kendali mereka. Saya tidak ingin mereka mengalami hal-hal yang sama yang saya alami di masa lalu. Jika kamu beberapa tahun lebih muda, saya dengan senang hati akan membawa kamu masuk juga. Meskipun saya rasa masih belum terlambat untuk itu.",
  str_voice_1602191_14 = "Orang-orang yang menjaga keteraturan tidak perlu tahu tentang rahasia kotor di balik pendirian keteraturan tersebut. Cukup terus maju, dan bayangan akan mengawasi perjalanan jauhmu.",
  str_voice_1602191_15 = "Buatlah sebuah keinginan, dan aku akan membantu mewujudkannya.",
  str_voice_1602191_16 = "Selalu berpikir dengan cermat sebelum bertindak, dan... jangan pernah terlalu mudah menunjukkan kartu asmu.",
  str_voice_1602191_17 = "Anak muda, kamu harus berjemur di hangatnya sinar matahari pagi setiap kesempatan yang kamu dapatkan. Lagipula, inilah tujuan misi saya di bayangan.",
  str_voice_1602191_18 = "Kamu tidak istirahat hari ini? Apakah kamu ingin belajar lebih banyak tentang kejadian kacau di masa lalu?",
  str_voice_1602191_19 = "Nngh... Kamu masih terjaga? Maafkan aku, luka ini cenderung menunjukkan keberadaannya sekitar waktu ini di malam hari.",
  str_voice_1602191_20 = "Saya akan membawa stabilitas dan ketertiban yang lebih besar lagi ke Umbraton, tidak peduli berapa harganya.",
  str_voice_1602191_21 = "Mungkin alasan semua orang melihat Northland sebagai tempat perlindungan yang aman adalah karena ratunya, yang telah mewarisi dan mempertahankan aturan yang murni dan teratur.",
  str_voice_1602191_22 = "Bayangan selalu mengawasimu.",
  str_voice_1602191_23 = "Menangkis Eclipsites seringkali tidak memerlukan banyak pikiran. Percayalah, ini bisa menjadi cara yang baik untuk melepaskan stres.",
  str_voice_1602191_24 = "Bethel... Dia sama sekali tidak seperti saya, itulah sebabnya dia bisa berdiri di luar bayangan. Itu hal yang baik.",
  str_voice_1602191_25 = "Heh, Leona kadang mengingatkan saya pada diri saya ketika lebih muda. Keyakinan dalam dirinya bahkan lebih kuat daripada saya.",
  str_voice_1602191_26 = "Tidak ada yang suka kalah, dan aku tidak berbeda—baik dalam catur atau kehidupan.",
  str_voice_1602191_27 = "Ketika kamu benar-benar menjadi satu dengan bayangan, kamu akan cepat menemukan dirimu menjadi lebih toleran dari sebelumnya.",
  str_voice_1602191_28 = "Kamu harus belajar membuat ruang tersembunyi untuk dirimu sendiri di Colossus, satu yang bahkan aku tidak pernah bisa menemukan.",
  str_voice_1602191_29 = "Hmm, sepertanyaan saya harus memberi selamat kepada Anda. Sekarang Anda mengerti bahwa bayangan lahir dari kedalaman kekacauan, dan tidak pernah benar-benar bebas darinya.",
  str_voice_1602191_30 = "Bayangan tidak memiliki batas.",
  str_voice_1602191_31 = "Sebuah hadiah yang pantas untuk harga yang dibayar.",
  str_voice_1602191_32 = "Bayangan semakin dalam.",
  str_voice_1602191_33 = "Janji bayangan adalah abadi.",
  str_voice_1602191_34 = "Waktunya untuk bergerak.",
  str_voice_1602191_35 = "Bekas lukaku terasa terbakar.",
  str_voice_1602191_36 = "Akan kutunjukkan kepada mereka semua.",
  str_voice_1602191_37 = "Lihat aku—!",
  str_voice_1602191_38 = "Kehancuran melahirkan kehidupan baru!",
  str_voice_1602191_39 = "Hraaaaah—!",
  str_voice_1602191_40 = "Lihat ke atas!",
  str_voice_1602191_41 = "Ikuti arahanku.",
  str_voice_1602191_42 = "Mereka harus tahu apa yang menanti mereka.",
  str_voice_1602191_43 = "Hanya tambahan bekas luka di tubuhku.",
  str_voice_1602191_44 = "Hmm? Setiap kali mengunjungi Colossus-mu, aku melihat perubahan baru.",
  str_voice_1602191_45 = "Selera kamu... hmm, lebih baik daripada selera saya dulu.",
  str_voice_1602191_46 = "Kamu benar-benar tahu cara memenuhi kebutuhan orang lain.",
  str_voice_1602191_47 = "Aku bisa mengisi etalase dengan semua hadiah ini.",
  str_voice_1602191_48 = "Kamu lebih mengenal saya dibandingkan rekan-rekan saya.",
  str_voice_1602191_49 = "Ketika tatanan lama Umbraton masih ada, seorang anak dengan penampilan iblis tidak pernah bisa berharap mendapatkan perlakuan baik, bahkan di bagian kota yang paling gelap sekalipun.",
  str_voice_1602191_50 = "Kita semua memakai topeng yang berbeda. Istvan yang kamu lihat di depanmu hanyalah orang yang saya inginkan kamu lihat.",
  str_voice_1602191_51 = "Kamu ingin memulihkan ketertiban dari kekacauan? Maka kamu harus menjadi bagian dari kekacauan tersebut terlebih dahulu.",
  str_voice_1602191_52 = "Alchemy Stars.",
  str_voice_1602191_53 = "Teman saya.",
  str_voice_1602191_54 = "Selamat pagi.",
  str_voice_1602191_55 = "Kamu harus istirahat.",
  str_voice_1602191_56 = "Tersembunyi oleh malam.",
  str_voice_1602191_57 = "Angkat gelasmu, karena bahkan bayangan pun merayakan kedatangan tahun baru.",
  str_voice_1502201_1 = "Uwaah! D-D-Dari mana kamu datang?! T-T-Tolong berdiri setidaknya dua puluh meter dari aku saat aku sibuk dengan pekerjaanku, dan jangan lupa untuk batuk, bersihkan tenggorokanmu, atau berjalan dengan keras saat kamu muncul!",
  str_voice_1502201_2 = "Um, bolehkah aku mencoba gigitan kecil dari kue ini dulu? Hanya sedikit... Wow! Pola di piring ini persis seperti yang aku baca di buku-buku tentang Caelestites! Di mana aku meletakkan kaca pembesar ku?!",
  str_voice_1502201_3 = "\"Menilai barang antik adalah tugas yang membutuhkan banyak pikiran. Akibatnya, penilai harus mengonsumsi lebih banyak makanan daripada orang yang membuat barang palsu!\" Itu langsung dari buku berjudul \"Perkenalan ke Penilaian.\" Hah? Bagaimana kamu tahu saya yang menulisnya?",
  str_voice_1502201_4 = "Wow! Apakah Lumina saya telah menjadi sekuat itu? Itu sangat dekat, untungnya saya tidak merusak lukisan kuno saya!",
  str_voice_1502201_5 = "Kekuatan... Aku merasa begitu banyak kekuatan yang mengalir dalam diriku! Aku bertaruh aku bahkan bisa berjalan masuk ke ruangan penuh orang sekarang! Tunggu... Tidak juga, mungkin aku hanya berkhayal.",
  str_voice_1502201_6 = "Kamu pikir aku juga jadi lebih kuat, kan PlayerName? Aku tahu makan semua gula itu tidak akan membahayakanku! Nah, aku bahkan akan memberimu sepertiga dari camilanku... Atau mungkin hanya seperempat? Kamu tidak keberatan, kan?",
  str_voice_1502201_7 = "Bingkai sugarpine dengan pengait yang dapat disesuaikan, dibuat dengan gaya Gannon kuno. Ini sempurna... Huh? Ahhh! I-I-Ini tidak ada apa-apa, saya hanya mencari bingkai yang bagus untuk potretmu! Apa? Kamu belum pernah membuat potret sebelumnya? S-Saya bisa memperkenalkan kamu pada seniman yang bagus, jika kamu mau!",
  str_voice_1502201_8 = "Kamu selalu datang untuk bermain denganku, PlayerName... Apa? A-A-Aku tidak pernah merasa kamu mengganggu! Aku selalu senang melihatmu, dan kamu selalu bisa bermain denganku kapan saja... T-Tidak berarti kamu harus atau apa pun! Tidak apa-apa jika kamu tidak punya waktu untukku...",
  str_voice_1502201_9 = "Sebelum bertemu denganmu, saya selalu sangat takut pada orang asing... Terkadang saya suka berpikir bahwa jika saya memiliki kakak laki-laki, dia akan seperti dirimu...",
  str_voice_1502201_10 = "Tidak mungkin kau sedang tidur sekarang, 'kan? Bukankah kau sudah tidur sekali kemarin?",
  str_voice_1502201_11 = "Sangat terang di sini, aku rasa aku akan meleleh... Huh? Kamu butuh aku untuk menjaga pintu untukmu? B-Baiklah! Aku akan memilih siapa saja \"pembohong\" yang datang pura-pura menjadi orang baik... atau setidaknya aku akan mencoba.",
  str_voice_1502201_12 = "Wow, serius? Akademi Seni ingin menambahkan saya ke daftar penilai terdaftar mereka, dan mereka membutuhkan saya untuk memberikan pendapat ahli di pengadilan?! T-T-Tidak mungkin, saya tidak bisa melakukannya kecuali... kecuali kamu pergi bersamaku! Maaf, apakah itu meminta terlalu banyak darimu?",
  str_voice_1502201_13 = "Kamu ingin membantu ku memindahkan beberapa barang antik? Terima kasih! Oh, apakah itu terlalu berat untukmu? Jangan khawatir, aku akan mengurusnya! K-Kamu perlu makan sedikit lebih banyak gula untuk menjadi lebih kuat.",
  str_voice_1502201_14 = "*menangis* Aku hanya makan tiga puluh tujuh camilan hari ini. Aku sangat lapar sampai kepala ini mulai pusing. Aku tidak yakin bisa bertahan lebih lama lagi...",
  str_voice_1502201_15 = "Selamat ulang tahun! K-Kamu tidak harus mengundangku ke pesta ulang tahunmu, tapi aku tidak keberatan jika kamu mengantarkan sepotong kue ke kamarku... A-Apakah itu baik-baik saja?",
  str_voice_1502201_16 = "Hai! Aku cenderung gugup saat banyak orang berjalan di sekitar, tapi kamu tampaknya tidak pernah terganggu oleh itu. Apa rahasiamu?",
  str_voice_1502201_17 = "Selamat malam... Hah? Sudah pagi rupanya? Eheheh, waktu benar-benar berlalu dengan cepat saat aku bekerja di sampingmu, karena aku merasa begitu nyaman.",
  str_voice_1502201_18 = "Sudah malam? Jangan khawatir, aku masih bisa terus bekerja... Mau bergadang bersamaku juga?",
  str_voice_1502201_19 = "Aku masih belum merasa lelah, tapi kamu sebaiknya segera tidur. Apa? Aku tidak akan bertambah tinggi jika tidak cukup tidur? Oh, jadi itulah mengapa aku begitu...",
  str_voice_1502201_20 = "Sejarah Umbraton sangat rumit. Ada begitu banyak cerita yang bertumpuk satu sama lain, seperti situs penggalian kuno... I-Ini sebenarnya semacam hal yang saya sukai.",
  str_voice_1502201_21 = "Saya yakin banyak barang palsu yang masuk ke Lumopolis! Dan itu karena... penilai di sana tidak terlalu ahli, dan pelanggan mereka hanya pura-pura peduli tentang seni.",
  str_voice_1502201_22 = "Bayangan itu mengawasi kamu... dan sebagai penilai, begitu pula saya!",
  str_voice_1502201_23 = "Eclipsites bukanlah makhluk hidup sungguhan, tapi semacam replika... Uwaah, t-tidak, aku tidak benar-benar memiliki bukti untuk mendukung pendapatku. S-Sebut saja itu intuisi, kira-kira...",
  str_voice_1502201_24 = "Hei! Datang dan temui teman baru saya, langsung dari Longzhou! Lihatlah cat yang seperti permata ini... Hah? \"Hanya kursi cendana\"? Tentu saja itu, jadi apa masalahnya?",
  str_voice_1502201_25 = "Allura adalah kolektor terbaik di seluruh Umbraton. Dia memiliki selera yang sempurna dan mata yang sempurna untuk kualitas, jadi tidak mungkin ada barang palsu dalam koleksinya!",
  str_voice_1502201_26 = "Museum itu memiliki harta baru yang dipajang?! Keren! Kapan kita bisa melihatnya? Besok? Atau mungkin... Mari kita lihat hari ini!",
  str_voice_1502201_27 = "A-A-Aku sudah berbicara dengan tiga orang berbeda hari ini, jadi aku tidak punya energi lagi untuk bersosialisasi!",
  str_voice_1502201_28 = "Colossi adalah puncak peradaban Caelestite! Bentuknya, warnanya, dan pola-pola... Kamu harus membiarkan aku tinggal di sini dan mempelajarinya!",
  str_voice_1502201_29 = "S-S-Senang bertemu dengan Anda. Nama saya Vergil, dan saya suka barang antik. Nah, selamat tinggal... Tunggu, pakaian itu dari Eraveil! Anda pasti Caelestite yang baru saja muncul dari tanah beberapa waktu lalu!",
  str_voice_1502201_30 = "Ungkaplah kebenaran sepenuhnya!",
  str_voice_1502201_31 = "Sekarang aku bisa melihat lebih jelas.",
  str_voice_1502201_32 = "Kebijaksanaan kuno selalu bersamaku.",
  str_voice_1502201_33 = "Tidak ada kebohongan yang bisa menipuku!",
  str_voice_1502201_34 = "Ahh! Begitu banyak orang!",
  str_voice_1502201_35 = "Tingkat gula terisi kembali!",
  str_voice_1502201_36 = "B-Biar aku melihat lebih dekat.",
  str_voice_1502201_37 = "Tak ada barang palsu yang akan bisa lewat dariku...!",
  str_voice_1502201_38 = "Saya telah mendeteksi setidaknya tujuh kekurangan.",
  str_voice_1502201_39 = "Tunjukkan warna sebenarmu!",
  str_voice_1502201_40 = "Tidak ada yang luput dari pandanganku.",
  str_voice_1502201_41 = "Haruskah aku benar-benar memimpin sebanyak ini orang?",
  str_voice_1502201_42 = "Tidak ada apa-apa selain barang cacat di sini.",
  str_voice_1502201_43 = "Kekuatanku... bukan yang asli?",
  str_voice_1502201_44 = "Maksudmu... Aku bisa mempelajari Colossus kapan saja yang aku mau?! A-Apakah ini mimpi?!",
  str_voice_1502201_45 = "Hadiah? Aku pikir kamu ingin aku menaksir sesuatu...",
  str_voice_1502201_46 = "Wow... Ini akan menjadi bagian dari barang antik paling berharga saya!",
  str_voice_1502201_47 = "Terima kasih! Ternyata barang antik bukanlah satu-satunya hal baik di dunia ini!",
  str_voice_1502201_48 = "Wow! Kamu benar-benar tahu apa yang aku suka sekarang!",
  str_voice_1502201_49 = "A-Aku bukanlah \"penilai jenius\" atau apapun itu. Dulu, saat aku tidak mengerti tentang hal-hal ini, aku hanya menghabiskan sebagian besar waktuku melihat lukisan dan barang antik. Setelah beberapa waktu, aku secara alami belajar bagaimana membedakan mereka.",
  str_voice_1502201_50 = "Kenapa aku bekerja di usia yang masih muda? Nah, untuk jujur saja, itu karena aku tidak tahan kehilangan \"teman-teman\" antikku...",
  str_voice_1502201_51 = "Beberapa orang yang membuat pemalsuan bahkan lebih pandai melukis daripada seniman aslinya. Tema-tema berani mereka, perpaduan warna yang indah, dan emosi kompleks yang mereka bangkitkan... Oh! M-M-Maaf, saya mulai bertele-tele lagi.",
  str_voice_1502201_52 = "A-Alchemy Stars...!",
  str_voice_1502201_53 = "PlayerName!",
  str_voice_1502201_54 = "Uwaah, pagi lagi...",
  str_voice_1502201_55 = "Selamat siang! I-Itu saja.",
  str_voice_1502201_56 = "Selamat malam!",
  str_voice_1502201_57 = "Oh, apakah ini sudah tahun baru? Selamat Tahun Baru! Tunggu... Perayaan Tahun Baru biasanya banyak orang, bukan? T-Tapi jika kamu di sana, aku pikir aku bisa mengatasinya! Ayo pergi...!",
  str_voice_1602211_1 = "Untuk memastikan bahwa saya mengikuti instruksi sistem tipe Anda dengan benar, saya harus mengajukan pertanyaan. Dengan memenuhi harapan Anda melalui pertanyaan saya, saya berharap dapat meningkatkan efisiensi percakapan kita.",
  str_voice_1602211_2 = "Seorang ilmuwan harus selalu sadar akan batasan intelektualisme, dan harus mencari kebijaksanaan yang lebih besar melalui pencerahan lingkungan. Hanya dengan cara itu pengetahuan kita dapat mengimbangi dunia kita yang cepat memburuk.",
  str_voice_1602211_3 = "Saya bertemu dengan Bool bukan karena takdir, tetapi murni kebetulan. Orang-orang hanya membuat asumsi tentang saya yang membuat saya tampak lebih eksentrik dari yang sebenarnya... Tapi ya sudah, tidak apa-apa. Saya menikmati keanehan saya!",
  str_voice_1602211_4 = "Hah? Sebagai ilmuwan, penelitian adalah tujuan terbesar dan tertinggi saya! Biaya, nilai, praktikalitas... Semua itu tidak penting bagi saya.",
  str_voice_1602211_5 = "Bool mampu merasakan musik melalui penglihatan, dan mengubah warna melalui suara! Ini adalah fenomena yang disebut \"sinestesia,\" yang hanya bisa dilakukan oleh Aurorian. Sungguh menakjubkan!",
  str_voice_1602211_6 = "Di masa lalu, saya kesulitan memahami orang lain, dan mereka juga kesulitan memahami saya, itulah sebabnya saya memilih untuk hidup dalam isolasi total dari dunia. Namun setelah saya memutuskan hubungan dengan orang lain, kami akhirnya mulai memahami satu sama lain...",
  str_voice_1602211_7 = "Alasan saya bertahan dalam studi saya tentang kecerdasan buatan kuno? Hmm... Saya akan mengatakan itu berasal dari rasa penasaran saya terhadap peradaban kuno dan masa depan Aurorian. Sekarang giliranmu.",
  str_voice_1602211_8 = "Oh, mampir ke ruang perawatan untuk pemeriksaan saluran pencernaan. Sistem pencernaanmu pasti berantakan setelah menghabiskan waktu yang lama di udara...",
  str_voice_1602211_9 = "Dalam masa bahaya, keyakinan terdalam kita cenderung berada di garis depan pikiran kita. Jadi ketika kamu bilang bahwa kamu ingin melindungi segalanya... Yah, aku tidak terlalu terkejut.",
  str_voice_1602211_10 = "Jika emosi diklasifikasikan menjadi salah satu dari tiga kategori, yaitu senang, sedih, dan acuh tak acuh... dapatkah klasifikasi yang sama digunakan untuk menjelaskan hubungan antara bahasa pemrograman dan Eclipsian?",
  str_voice_1602211_11 = "Bool menjadi sangat bersemangat setelah mendengar bahwa Anda membutuhkan asisten. Saya tidak terlalu baik bekerja dengan orang lain, tetapi Bool adalah pemain tim yang sebenarnya, jadi kalian bisa ngobrol! Huh? Tertidur lagi...?",
  str_voice_1602211_12 = "Bayangkan era supremasi teknologi. Di sana, nilai memori pasti sebanding dengan informasi yang dicatat. Pengetahuan adalah kekuatan, setelah semua; semakin banyak pengetahuan yang Anda peroleh, semakin kuat Anda menjadi.",
  str_voice_1602211_13 = "Sejarah tidak selalu fakta, dan budaya tidak terbentuk dari data mentah. Bahkan jika mesin itu mencatat cukup informasi untuk mendapatkan semacam \"pengetahuan segala,\" itu tidak berarti kita akan mengikuti jalan yang diprediksinya.",
  str_voice_1602211_14 = "Dalam pertempuran, daripada terlalu menekankan ritual yang diperlukan untuk mengaktifkan Luminatics, kita seharusnya meneliti sifat Lumina itu sendiri. Dalam program saya, mengaktifkan Luminatics hanya membutuhkan beberapa baris kode yang tidak mencolok.",
  str_voice_1602211_15 = "Ulang tahunku? Kalau tidak mendesak, ayo kita rayakan besok saja.",
  str_voice_1602211_16 = "Merasa sulit untuk bekerja dan berolahraga pada saat yang sama? Kamu tidak akan tahu sampai kamu mencobanya!",
  str_voice_1602211_17 = "Cangkir kopi ini berubah warna sesuai dengan suasana hatiku. Sepertinya aku tidur nyenyak semalam!",
  str_voice_1602211_18 = "Kode yang begitu indah! Oh, seandainya saja kamu bisa menghargainya!",
  str_voice_1602211_19 = "Waktu ditentukan secara internal. Kamu tahu apa yang saya maksud ketika saya bilang ini masih awal, kan?",
  str_voice_1602211_20 = "Sebuah mesin dan beberapa kota bawah tanah yang dibangun di sekitarnya... Sungguh sebuah keajaiban Illumina masih ada hingga hari ini.",
  str_voice_1602211_21 = "Mereka tidak sederhana... Aurorian pasti tidak berarti apa-apa bagi makhluk yang mampu menciptakan sesuatu seperti ini.",
  str_voice_1602211_22 = "Ya ya, Jayalah Illumina. Aku tidak percaya aku masih harus mengatakan hal seperti itu.",
  str_voice_1602211_23 = "Yah, Aurorian sebenarnya belum benar-benar menang melawan Eclipsites... Hahahahaha...",
  str_voice_1602211_24 = "Hmm... Itu pasti Bool, saya kira. Meskipun kurang total dalam pemahaman, kami sebisa mungkin saling dekat.",
  str_voice_1602211_25 = "Joyce, kurasa... Tapi aku belum mendengar kabar darinya lebih dari setengah tahun. Apa yang ingin kamu ketahui?",
  str_voice_1602211_26 = "Berisik? Tapi bukankah Anda pikir dengungan itu membantu untuk tertidur?",
  str_voice_1602211_27 = "Siapa yang memutuskan bahwa para ilmuwan harus menjadi orang gila yang membosankan, botak, dan tidak pernah mandi? Hal itu membuat saya gila hanya dengan memikirkannya!",
  str_voice_1602211_28 = "Mereka bilang bahwa struktur Colossus didasarkan pada naga kuno. Apakah hal yang sama berlaku untuk bagian dalam mereka?",
  str_voice_1602211_29 = "Setelah menunggu selama lima hari penuh untuk pembaruan... Ini saja?! Hah? Tidak bisakah kau lihat aku sedang sibuk–Oh! Waktunya olahraga! Jadi, apa yang kamu butuhkan?",
  str_voice_1602211_30 = "Wah... Saya naik level dalam sekejap!",
  str_voice_1602211_31 = "Sistem baru ini cukup bagus!",
  str_voice_1602211_32 = "Ayo, sedikit lebih cepat!",
  str_voice_1602211_33 = "Bahkan Bool mengakui kecerdasanmu!",
  str_voice_1602211_34 = "Bool juga tidak bisa menunggu lagi!",
  str_voice_1602211_35 = "Siapkan diri untuk menjalankan program!",
  str_voice_1602211_36 = "Proses dibuat!",
  str_voice_1602211_37 = "Menginisialisasi program!",
  str_voice_1602211_38 = "Meningkatkan kecepatan program!",
  str_voice_1602211_39 = "Perintah lompat!",
  str_voice_1602211_40 = "Menimpa data!",
  str_voice_1602211_41 = "Hahaha... Serahkan pada kami!",
  str_voice_1602211_42 = "Data telah disimpan.",
  str_voice_1602211_43 = "Mencari file yang hilang.",
  str_voice_1602211_44 = "Hmm... Hah? Oh, Bool bilang hai.",
  str_voice_1602211_45 = "Aku, anu... sebenarnya tidak punya apa-apa untuk diberikan kepadamu.",
  str_voice_1602211_46 = "Wow...! Kamu memang benar-benar genius!",
  str_voice_1602211_47 = "Terima kasih, cukup taruh di laci saya.",
  str_voice_1602211_48 = "Perasaan gembira ini... Sungguh menarik!",
  str_voice_1602211_49 = "Dulu saya selalu mengandalkan logika untuk menganalisis dan menghitung segala hal, sehingga orang-orang mulai memanggil saya \"robot\". Namun setelah menggunakan otak saya seperti itu untuk waktu yang lama, tidak mudah untuk berhenti.",
  str_voice_1602211_50 = "Keluarga saya... Mereka jelas khawatir tentang saya yang menyerap begitu banyak informasi di usia yang sangat muda, tetapi saya tahu saya bisa menanganinya. Itu adalah sifat saya, setelah semua.",
  str_voice_1602211_51 = "Awalnya, saya tidak benar-benar mengerti perilaku Bool. Saya pikir \"pijatannya\" hanyalah tanda kasih sayang, tetapi segera saya menyadari bahwa Bool mencoba berkomunikasi dengan saya.",
  str_voice_1602211_52 = "Oh, Alchemy Stars.",
  str_voice_1602211_53 = "Oh, benar...",
  str_voice_1602211_54 = "Saya merasa hebat setelah semalam!",
  str_voice_1602211_55 = "Mengambil istirahat siang?",
  str_voice_1602211_56 = "Malam adalah buaian kebijaksanaan!",
  str_voice_1602211_57 = "Satu tahun lagi, ya... Selamat Tahun Baru.",
  str_voice_1600024_1 = "Ketika saya meninggalkan Cloud Mountain, nenek saya mempercayakan saya dengan pakaian indah Keluarga Sakura ini, dengan harapan pikiran orang-orang kita akan menemani saya...",
  str_voice_1600024_2 = "Jika suatu hari nanti saya harus membuka segel itu, saya berdoa agar kau ada di sisiku untuk menyaksikannya.",
  str_voice_1600024_3 = "Apakah kamu melihatnya? Jangan takut. Bekas luka di bawah perban ini dan apa yang mereka wakili semua adalah masa lalu sekarang.",
  str_voice_1600024_10 = "Mengganggu? Sama sekali tidak. Saya memilih untuk datang bersamamu ke tempat damai ini dan mendengarkan angin sepoi-sepoi...",
  str_voice_1600024_11 = "Selama aku berada di sisimu, aku akan selalu melindungimu dari kejahatan... Aku bersumpah atas nama terhormat Sakura dan Sakae.",
  str_voice_1600024_12 = "Sampai aku cukup kuat untuk kembali ke Cloud Island, aku bersyukur memiliki tempat lain yang bisa kusebut rumah, seperti Illumina... atau di mana pun kamu berada.",
  str_voice_1600024_13 = "Kamu adalah seorang prajurit yang berani, dan teman yang dapat dipercaya. Dalam waktu yang telah kita kenal satu sama lain, saya hampir memastikan ini dengan setiap serat dari diri saya.",
  str_voice_1600024_14 = "Terakhir dari Sakura dan Sakae, dan terakhir dari Caelestite... Kita tak akan pernah sendirian selama kita tetap bersama, bukan?",
  str_voice_1600024_16 = "Aku akan selalu di sini, jika kau ingin menemuiku.",
  str_voice_1600024_17 = "Selamat pagi. Aku tidak membangunkanmu, 'kan? ...Maafkan aku.",
  str_voice_1600024_18 = "Saya akan makan makanan kering untuk makan malam malam ini... Oh, ini bukan berarti saya menolak tawaranmu! Tapi jika kamu sudah membuat rencana, maka akan tidak sopan jika saya menolak.",
  str_voice_1600024_19 = "Tanganmu sedikit dingin... Ingatlah untuk tetap hangat di malam hari.",
  str_voice_1600024_35 = "Pedang Sakae bergetar.",
  str_voice_1600024_36 = "Zakura, pinjamkan aku kekuatanmu!",
  str_voice_1600024_37 = "Jangan takut pada musuh—!",
  str_voice_1600024_38 = "Berpencar dan melampaui—!",
  str_voice_1600024_39 = "Ha.",
  str_voice_1600024_40 = "Berpencar!",
  str_voice_1600024_44 = "Jangan khawatir, saya sudah lama menyesuaikan diri tinggal di sini.",
  str_voice_1600024_58 = "Selamat pagi.",
  str_voice_1600024_59 = "Selamat pagi. Aku tidak membangunkanmu, 'kan?",
  str_voice_1600024_60 = "Mau latihan pagi?",
  str_voice_1600024_61 = "Meditasi pagi sangat penting untuk mencapai pencerahan.",
  str_voice_1600024_62 = "Selamat malam. Apakah kamu sedang beristirahat?",
  str_voice_1600024_63 = "Apa kamu punya rencana untuk besok?",
  str_voice_1600024_64 = "Maaf, tapi apakah Anda memiliki teh di sana?",
  str_voice_1600024_65 = "Bekerja di meja sepanjang hari benar-benar membuat leher dan bahu saya tegang...",
  str_voice_1600024_66 = "Selamat malam. Semoga aroma bunga sakura bisa menidurkanmu. May",
  str_voice_1600024_67 = "Terima kasih untuk alat pengasah pisau ini.",
  str_voice_1600024_68 = "Bisakah kamu ceritakan lebih banyak tentang Windelion?",
  str_voice_1600024_69 = "Bunga sakura mekar di atas abu masa lalu.",
  str_voice_1600024_70 = "Aku penasaran, bagaimana kabar Nenek dan Sanki?",
  str_voice_1600024_71 = "Sungguh menyakitkan untuk mengatakannya, tapi dulu aku memiliki aksen Cloud Mountain yang sangat kental...",
  str_voice_1500994_1 = "Navigator... Oh, apakah aku harus memanggilmu \"Tuan Muda\" dengan pakaian ini?",
  str_voice_1500994_2 = "Jepit rambut Longzhou sangat tajam, namun menjadi simbol pesona saat menghiasi rambut.",
  str_voice_1500994_3 = "Pedang hanyalah senjata; tujuannya ditentukan oleh mereka yang memegangnya. Pedang ajaibku digunakan untuk melindungi kota ini, dan untuk melindungimu.",
  str_voice_1500994_10 = "Tidak ada noda di lengan... dan bagian bawahnya tidak robek. Ini bagus.",
  str_voice_1500994_11 = "Areia sang Bayaran kini mengawasi Teluk Twin Pavilions. Pakaian yang aku kenakan ini... seharusnya membuatku sepadan denganmu.",
  str_voice_1500994_12 = "Mereka bilang sutra itu sejuk. Saya tidak tahu apa maksudnya sampai saya memakai pakaian yang terbuat dari sutra.",
  str_voice_1500994_13 = "Pedang Ajaib ini selalu melindungiku, itu yang aku tahu. Aku hanya tidak mengharapkan ikatan seperti ini.",
  str_voice_1500994_14 = "Dengan pakaian yang lebih cocok dan pemahaman yang lebih dalam tentang Pedang Sihir, saya lebih siap untuk membantu Anda dalam pertempuran. Terima kasih sebelumnya atas kesabaran Anda.",
  str_voice_1500994_16 = "... Pekerjaanku hari ini? Itu adalah melayani di sampingmu. Apakah ada yang bisa kulakukan untukmu?",
  str_voice_1500994_17 = "Selamat pagi. Ini adalah impian bagi saya untuk merasakan sinar matahari di kulit telanjang saya.",
  str_voice_1500994_18 = "Pekerjaanmu sudah selesai? Kemana kamu akan pergi beristirahat, lalu? Aku akan menjaga kamu.",
  str_voice_1500994_19 = "Jubah tahan angin yang dijual di Teluk Twin Pavilions itu ringan dan memiliki insulasi. Aku telah menabung untuk membelikanmu satu...",
  str_voice_1500994_35 = "Pedang Ajaib itu bergetar.",
  str_voice_1500994_36 = "Pedang menari untukmu.",
  str_voice_1500994_37 = "Fokuskan semua energi, Pedang Ajaib!",
  str_voice_1500994_38 = "Bantu aku menaklukkan, Pedang ajaib!",
  str_voice_1500994_39 = "Serang!",
  str_voice_1500994_40 = "Serangan duri!",
  str_voice_1500994_44 = "Saya berlatih keterampilan percakapan di Twin Pavilions Bay, tetapi saya tidak tahu apakah saya telah memperbaiki...",
  str_voice_1500994_58 = "Pedang Ajaib melindungiku, dan aku akan menggunakannya untuk melindungi orang lain.",
  str_voice_1500994_59 = "Aku tak pernah berpikir bahwa bunga di duri bisa seindah wisteria.",
  str_voice_1500994_60 = "Orang Longzhou mengatakan pedang besar biasanya tidak memiliki ketajaman, tetapi Pedang Ajaib ini tajam dan berduri.",
  str_voice_1500994_61 = "Resep dari penyembuh muda itu efektif. Meskipun tidak memecahkan kutukan, saya masih sangat berterima kasih.",
  str_voice_1500994_62 = "Aku tidak akan pernah melupakan niat leluhurku ketika mereka membuat pedang...",
  str_voice_1500994_63 = "Aku bisa memanjat dinding, mengayunkan pedang, dan bergerak dengan mudah dalam pakaian ini... dan ini sangat cantik.",
  str_voice_1500994_64 = "Haruskah aku belajar menjahit dan membuat pakaian yang pas untukmu?",
  str_voice_1500994_65 = "Hm, apakah semua orang berpikir aku ini fanatik jubah?",
  str_voice_1500994_66 = "Tak apa, meskipun kutukan ini tak bisa dipecahkan... Aku akan tetap berusaha bertahan!",
  str_voice_1500994_67 = "Ada banyak orang yang ingin aku balas, seperti Nona Xuan Ji, Nona Dantang, dan kamu...",
  str_voice_1500994_68 = "Ya. Mulai sekarang, aku akan menjadi Wanita Pedang Sihir, dan juga Areiamu.",
  str_voice_1500994_69 = "Saya telah tiba di lokasi untuk misi baru saya. Sekarang, saya perlu mengkonfirmasi target.",
  str_voice_1500994_70 = "Apa yang ingin kamu katakan padaku, Pedang Ajaib?",
  str_voice_1500994_71 = "Aku tidak akan mengecewakan Pedang Ajaib!",
  str_voice_1500994_72 = "Spesialitas lokal apa yang harus saya bawa untuk teman-teman saya di Umbraton dan di Colossus?",
  str_voice_1500994_73 = "Pakaian ini sangat ringan! Aku ingin bergerak lebih banyak lagi mengenakannya.",
  str_voice_1500994_74 = "Apakah kamu juga merasakan kebencian di sekitar kita, Magic Sword?",
  str_voice_1500994_75 = "Eh! Hah!",
  str_voice_1500994_76 = "Aku merasakan sesuatu!",
  str_voice_1602231_1 = "Saya mengerti, jadi kamu adalah pelayan makhluk mitos ini, 'kan? Kamu mungkin dibombardir oleh banyak suara setiap hari, tapi suara makhluk ini akan selalu menjadi yang paling penting.",
  str_voice_1602231_2 = "Saya menghabiskan sebagian besar waktu saya tinggal di kedalaman laut. Di sana, kamu bisa menemukan gua-gua yang dibangun oleh orang-orang kuno. Di dalamnya sejuk, meski sedikit usang.",
  str_voice_1602231_3 = "Ada beberapa hal di laut yang bisa menyebabkan kapal mengalami kerusakan dan bahkan tenggelam... Aurorian sangat rapuh. Selalu menjadi masalah ketika harus mengumpulkan setiap dari mereka saat hal seperti itu terjadi.",
  str_voice_1602231_4 = "Ya, saya tahu saya terlihat seperti ratu naga dengan perhiasan mewah ini... tetapi saya hanya memakainya karena sangat merepotkan untuk mengikuti berbagai mata uang yang kalian gunakan di permukaan. Dengan pernak-pernik emas dan perak saya yang siap, saya selalu memiliki cukup uang kapan saja.",
  str_voice_1602231_5 = "Aku bangun dan menemukan bahwa begitu banyak hal telah berubah. Memang bukan hal yang tidak biasa jika dunia berubah saat aku tidur, tapi kali ini, segalanya benar-benar berubah... Apakah kamu bisa menunjukkan sekeliling?",
  str_voice_1602231_6 = "Saya percaya kamu baik-baik saja hari ini, PlayerName muda. Ayo duduk dan ceritakan semua masalah di negeri asing ini.",
  str_voice_1602231_7 = "Timbangan saya tidak akan pernah mencakar Anda! Sentuhlah sendiri, jika Anda tidak percaya padaku!",
  str_voice_1602231_8 = "Apakah kamu ingin melihatku menari? Kamu bisa menonton, tapi jangan mengejek! Ini adalah tarian yang sangat tua - berusia ribuan tahun, sebenarnya.",
  str_voice_1602231_9 = "Saya adalah Pelindung Agung, Penjaga Laut Barat, Maiden dari Berkah Naga, Dewa Naga Yang Maha Kuasa yang mengawasi gelombang laut. Saya dapat memberikan kapal Anda perjalanan yang aman, bebas dari bahaya lautan dalam yang berbahaya, dan mengubah setiap pertanda buruk menjadi pertanda baik... Saya janji.",
  str_voice_1602231_10 = "Diberkati oleh takdir, Gadis Naga membawa kabar baik saat ia turun ke dunia. Gelombang lautan yang luas tampak samar, seolah-olah terselimuti asap. Gadis Naga, hadiah dari surga, membawa berbagai berkat untuk semua orang. Seperti bulan muda yang perlahan bertambah penuh, atau matahari yang cerah dalam kenaikannya.",
  str_voice_1602231_11 = "Baiklah, aku sedang dalam perjalanan! Apakah kamu ingin menghabiskan waktu bersamaku... atau ada sesuatu yang penting yang ingin kamu tanyakan kepada Dewa Naga yang Dermawan?",
  str_voice_1602231_12 = "Kamu orang-orang dari barat tampaknya muncul di mana-mana, mengadakan pertunjukan bergaya Astra! Saya bahkan melihat peningkatan dalam gadget kecil cerdas yang sepertinya kalian semua sangat suka. Saya bertanya-tanya kapan kita akhirnya akan dapat meniru bangunan menjulang dari masa lalu yang mulia itu...",
  str_voice_1602231_13 = "Tarian Gadis Naga di Atas Lautan yang Bergelora? Ya, aku pernah melihatnya! Mereka meminta seorang gadis cantik untuk menari di atas panggung sebagai aku! ... Tapi sebenarnya, aku bukan penari yang hebat.",
  str_voice_1602231_14 = "Saya tidak terlalu peduli dengan Kaisar dari Zhao. Bahkan, saya merasa cukup kasihan padanya—selalu direpotkan oleh semua menteri itu, pengawal yang berlarian di sekelilingnya siang dan malam... Apa jenis hidup seperti itu?",
  str_voice_1602231_15 = "Di masa lalu, bukanlah hal yang jarang bagi jemaat setiaku untuk mengucapkan selamat ulang tahun kepadaku. Hari ini, akhirnya saya mendapatkan kesempatan untuk mengucapkan selamat ulang tahun kepada orang lain. Betapa indahnya!",
  str_voice_1602231_16 = "Apa yang sedang kamu tulis di sana? Biarkan aku melihatnya... Hmm... Aku tidak mengerti sama sekali!",
  str_voice_1602231_17 = "Mm, kamu bangun begitu pagi... Aku ingin tidur lebih lama... Jangan khawatir, kali ini tidak akan sampai seabad...",
  str_voice_1602231_18 = "Kamu pasti lapar, PlayerName muda! Bagaimana kalau kita berbagi cicipan dari penghormatan terakhirku?",
  str_voice_1602231_19 = "Sudah sangat larut dan kamu masih berencana untuk pergi keluar? Huh... Hidup memang tidak mudah untuk kalian, makhluk malang.",
  str_voice_1602231_20 = "Pernahkah saya memberitahu Anda bagaimana Longzhou mendapatkan namanya? Saya pernah...? Baiklah...",
  str_voice_1602231_21 = "Kisah Eraveil sangat membuatku sedih. Tapi aku percaya kita belum mendengar akhir dari Caelestite. Jadi tolong jangan hanya larut dalam masa lalu.",
  str_voice_1602231_22 = "Diberkati oleh surga! Longzhou!",
  str_voice_1602231_23 = "Meski tampak ganas dari penampilan mereka yang mengerikan, di hadapan kekuatan sejati, roh jahat runtuh pada pukulan pertama.",
  str_voice_1602231_24 = "Apakah kamu pernah bertemu dengan fiendlings besar lainnya? Meskipun kamu belum pernah, aku yakin kita akan bertemu dengan beberapa di masa depan yang tidak terlalu jauh.",
  str_voice_1602231_25 = "Naga adalah kerabat jauh saya, ikan ular adalah kerabat jauh naga, dan Yuebai adalah kerabat jauh ikan ular... Apakah itu membuatnya kerabat jauh dari kerabat jauh dari kerabat jauh saya?",
  str_voice_1602231_26 = "Saya suka tidur, meletuskan gelembung, menghitung perahu, makan penghormatan yang lezat... dan banyak hal lain yang baru bagi saya!",
  str_voice_1602231_27 = "Kelahiran, kematian, penyakit, usia tua, ketenaran dan kekayaan... Ada beberapa hal yang tidak bisa aku kendalikan, tetapi pengikutku tetap memintanya padaku.",
  str_voice_1602231_28 = "Aku mendengar suara makhluk kuno... Apa yang ingin kau sampaikan padaku, makhluk besar Eraveil? Apakah kau ingin berbicara tentang kejayaan masa lalu, atau tentang teman-teman saat ini?",
  str_voice_1602231_29 = "Bungkuklah di hadapanku, pengikutku. ...Ah, itu hanya ungkapan. Saya tidak bermaksud kau harus berlutut! Saya sudah pergi cukup lama, tapi masih memalukan melihat orang-orang yang saya kenal bertindak seperti itu...",
  str_voice_1602231_30 = "Tribut lain untukku?",
  str_voice_1602231_31 = "Pencerahan menjadi milikku.",
  str_voice_1602231_32 = "Peluklah kelahiran kembali.",
  str_voice_1602231_33 = "Dragon Maiden telah kembali.",
  str_voice_1602231_34 = "Apa yang kamu inginkan?",
  str_voice_1602231_35 = "Patuhi dekrit Sang Gadis Naga.",
  str_voice_1602231_36 = "Izinkan saya menunjukkan jalan!",
  str_voice_1602231_37 = "Kehendak Ilahi—Berubah!",
  str_voice_1602231_38 = "Kehendak Naga Pengembara—Petir!",
  str_voice_1602231_39 = "Tenanglah, laut yang bergolak!",
  str_voice_1602231_40 = "Sisik emas, tetaplah ombak!",
  str_voice_1602231_41 = "Terima berkat naga!",
  str_voice_1602231_42 = "Kalian semua sudah sampai di pantai dengan selamat? Aku tahu kita pasti bisa!",
  str_voice_1602231_43 = "Ada hari yang pendek dan panjang. Bulan memiliki periode surut dan purnama. Semuanya baik-baik saja.",
  str_voice_1602231_44 = "Baguslah saya terlihat seperti Aurorian. Jika tidak, mungkin saya tidak akan bisa berbaur di kapal ini.",
  str_voice_1602231_45 = "Wow... Apakah benda ini bisa dimakan?",
  str_voice_1602231_46 = "Betapa berharganya dirimu yang kecil ini! Aku suka itu!",
  str_voice_1602231_47 = "Harta karun langka seperti itu! Terus berikan!",
  str_voice_1602231_48 = "Oh, ini membuatku sangat bahagia! Saya berjanji akan menghargainya selamanya!",
  str_voice_1602231_49 = "Semua hal di Longzhou berasal dari Primordial. Sebagai kerabat dekat dari pencipta besar, tidak ada perbedaan antara Aurorian, fiendlings, atau bahkan burung dan binatang di mata saya.",
  str_voice_1602231_50 = "Aurorian dan fiendlings pernah hidup dalam harmoni. Pada tahun-tahun awal Longzhou, Aurorian sangat bergantung pada fiendlings yang kuat, memuja mereka sebagai totem. Sebagai gantinya, fiendlings membiarkan Aurorian berkembang di tanah tandus itu dan mendirikan negara mereka yang pertama.",
  str_voice_1602231_51 = "Saya menghabiskan banyak waktu tidur di kedalaman laut, hanya sesekali memutuskan untuk menyelamatkan mereka yang hampir tewas oleh ombak. Namun, Aurorian yang tinggal di pesisir telah membangun kuil atas nama saya dan memuja saya sebagai dewi... Satu-satunya cara saya bisa memenuhi gelar yang mereka berikan kepada saya adalah dengan melakukan yang terbaik untuk melindungi mereka dan membantu mereka kapanpun saya bisa.",
  str_voice_1602231_52 = "Alchemy Stars.",
  str_voice_1602231_53 = "Muda PlayerName!",
  str_voice_1602231_54 = "Ah... Ini masih sangat pagi...",
  str_voice_1602231_55 = "Apa ada kegiatan seru yang bisa dilakukan di darat?",
  str_voice_1602231_56 = "Ini sangat larut. Apakah kamu membutuhkan berkatku untuk membantumu tidur?",
  str_voice_1602231_57 = "Meski sudah melihat awal dari banyak tahun baru, ini adalah pertama kalinya aku menghabiskannya bersamamu! Apa jenis berkah yang kamu inginkan? Aku bisa memberimu berkah naga ilahi, tahu.",
  str_voice_1502241_1 = "Jika Anda menemui fiendlings yang merepotkan dalam perjalanan Anda seputar Longzhou, beri tahu saya, dan saya akan menanganinya untuk Anda.",
  str_voice_1502241_2 = "Kamu perlu memastikan untuk selalu waspada terhadap penipu yang mencari target yang mudah. Kamu tahu yang saya maksud—jenis yang berbicara tentang takdir, yin dan yang, keberuntungan dan semua itu, tetapi tidak melakukan apa-apa untukmu... Siapa yang saya bicarakan? Yah, tidak ada orang tertentu.",
  str_voice_1502241_3 = "Kamu akan mendengar cerita-cerita paling aneh tentang fiendlings di daerah pedesaan Longzhou. Saya rasa kebanyakan dari mereka adalah omong kosong, meskipun. Kebanyakan fiendlings memiliki hal yang lebih baik untuk dilakukan daripada beberapa kenakalan yang dituduhkan orang kepada mereka.",
  str_voice_1502241_4 = "Ini Ah Ding, si kecil yang biasanya aku lemparkan ke medan pertempuran. Tentu saja aku harus melemparkannya... Bagaimana lagi dia bisa berlatih menanduk?",
  str_voice_1502241_5 = "Saya? Seorang pelatih? Saya rasa itulah sebutannya di luar negeri. Tentu, saya suka menjadi pelatih fiendling. Itu pasti lebih mudah daripada mengajar Aurorian.",
  str_voice_1502241_6 = "Seorang fiendling seperti Ah Ding perlu berlatih selama waktu yang lama untuk naik ke bentuk Aurorian. Berapa lama? Setidaknya akan memakan waktu beberapa ratus tahun.",
  str_voice_1502241_7 = "Meskipun kamu tidak memiliki bakat untuk Luminatics, jangan biarkan hal itu membuatmu down. Kamu bugar, sehat, lincah, dan cepat dengan tanganmu. Pertahankan latihanmu dan kamu pasti akan menjadi seseorang yang hebat suatu hari nanti!",
  str_voice_1502241_8 = "Aku memang tidak terlalu berbakat, tetapi teknik bela diri yang telah aku kembangkan selama bertahun-tahun ini sangat kuat!",
  str_voice_1502241_9 = "Bagaimana kalau berlatih tanding sebentar dengan Ah Ding dan yang lainnya? Hah, kamu tidak perlu memukul satu kali pun—cukup angkat mereka dan lemparkan keluar!",
  str_voice_1502241_10 = "Maaf, apakah Ah Ding dan yang lainnya mengganggumu? Aku akan menyuruh makhluk-makhluk kecil itu untuk tetap diam.",
  str_voice_1502241_11 = "Ada yang bisa saya bantu...? Kamu hanya ingin membelai si kecil iblis itu? Silakan, mereka tidak menggigit... Mereka hanya sedikit panas saat disentuh.",
  str_voice_1502241_12 = "Jadi, kamu tidak memiliki sesuatu seperti fiendlings di benua kamu, hanya beberapa binatang aneh yang bisa menggunakan mantra energi dan Aurorian dengan kepala binatang yang tidak benar-benar bisa menggunakan mantra energi dengan baik... Jika saya mendapatkan kesempatan, saya ingin melihat mereka.",
  str_voice_1502241_13 = "Buku cerita sering berbicara tentang fiendlings yang berlatih untuk \"melampaui puncak.\" Sebenarnya ada kebenaran dalam hal ini—\"melampaui puncak\" merujuk pada seorang fiendling yang belajar mengendalikan kemampuannya tanpa menghancurkan dirinya sendiri dalam prosesnya.",
  str_voice_1502241_14 = "Saya pernah membaca bahwa pendidikan tidak mengenal kelas, dan tuanku juga mengajari saya bahwa semua makhluk hidup adalah sama. Saya setuju dengan prinsip ini—baik itu pejabat berpangkat tinggi atau setan kecil, orang yang berbudi harus dihargai, dan orang jahat harus dihukum.",
  str_voice_1502241_15 = "Ini hadiah kecil ulang tahun yang aku siapkan untukmu! Hadiah lainnya? Ah Ding dan yang lainnya mengumpulkannya untukmu. Ingat, jangan makan mentah-mentah.",
  str_voice_1502241_16 = "Lihatlah langit yang sempurna itu, dengan matahari yang bersinar sangat terang! Setan nakal yang berharap membuat masalah sangat tidak mungkin menyerang di saat seperti ini.",
  str_voice_1502241_17 = "Pagi! Sedang memindahkan beberapa persediaan, ya? Aku bisa membantu. Ah Ding dan yang lainnya juga bisa membantu membawa sedikit.",
  str_voice_1502241_18 = "Kamu lebih mungkin bertemu dengan roh jahat setelah matahari terbenam daripada saat siang hari.",
  str_voice_1502241_19 = "Fiendlings yang belum naik ke bentuk Aurorian biasanya bertindak sesuai insting, sehingga tengah malam adalah saat banyak dari mereka paling aktif.",
  str_voice_1502241_20 = "Longzhou adalah tanah dengan puncak-puncak yang menjulang tinggi dan lautan yang luas, dan merupakan rumah bagi lebih banyak fiendlings daripada yang bisa Anda hitung dalam satu masa hidup.",
  str_voice_1502241_21 = "Aku dengar bahwa spesies dengan ciri-ciri seperti fiendling bukanlah pemandangan yang jarang di benua kalian... Apakah ini benar?",
  str_voice_1502241_22 = "Mengeliminasi iblis dan mengusir roh jahat. Inilah di mana bakatku berada.",
  str_voice_1502241_23 = "Fiendlings lebih peka terhadap aura roh jahat dibandingkan Aurorian. Mereka harus begitu, jika tidak mereka mungkin berakhir sebagai makanan roh jahat.",
  str_voice_1502241_24 = "Begitu Ah Ding akhirnya menguasai Head-Butt Besinya, aku harus mulai mempertimbangkan apa yang harus diajarkan kepadanya selanjutnya...",
  str_voice_1502241_25 = "Anda bisa langsung tahu bahwa seorang fiendling yang berbudaya seperti Liqing pasti diajarkan oleh seorang master dengan bakat yang cukup besar.",
  str_voice_1502241_26 = "Mau beberapa kastanye air, teman?",
  str_voice_1502241_27 = "Seorang pria kaya pernah bersikeras agar saya membantu kucingnya melewati puncak. Saya memberitahunya bahwa kucingnya hanyalah kucing, bukan setan kecil, tetapi dia tidak mendengarkan.",
  str_voice_1502241_28 = "Saya telah bepergian jauh dan melihat banyak hal aneh, tapi saya belum pernah melihat hal seperti ini sebelumnya.",
  str_voice_1502241_29 = "Luo Song, siap melayani—seorang pendeta pengembara dari pegunungan, dan seorang pelatih bisikan fiendling yang terlatih. Ini adalah Ah Ding, dan ini adalah teman-teman fiendling-nya.",
  str_voice_1502241_30 = "Menguatkan tubuh Anda harus selalu menjadi prioritas utama Anda.",
  str_voice_1502241_31 = "Jika jubahnya cocok...",
  str_voice_1502241_32 = "Tidak ada salahnya membawa beberapa talisman tambahan.",
  str_voice_1502241_33 = "Kamu tidak pernah bisa memiliki terlalu banyak talisman suci.",
  str_voice_1502241_34 = "Sekarang, siapa yang telah menimbulkan masalah di sini?",
  str_voice_1502241_35 = "Sekaranglah kesempatanku!",
  str_voice_1502241_36 = "Ah Ding, ini saatnya kita bersinar.",
  str_voice_1502241_37 = "Langit tidak menunggu siapa pun! Makhluk jahat, bersihkan dirimu!",
  str_voice_1502241_38 = "Iron Head-Butt, siap untuk menyerang!",
  str_voice_1502241_39 = "Seruduk Membakar!",
  str_voice_1502241_40 = "Ah Ding! Serang sekarang!",
  str_voice_1502241_41 = "Sst. Pengamatan adalah kunci kemenangan.",
  str_voice_1502241_42 = "Kerja yang bagus! Dan masih ada waktu untuk teh.",
  str_voice_1502241_43 = "Lari! Aku akan menahan mereka.",
  str_voice_1502241_44 = "Ah Ding, seharusnya kamu tahu bahwa tidak baik mengintip rumah orang lain.",
  str_voice_1502241_45 = "Terima kasih banyak. Ada kemungkinan ini akan berguna.",
  str_voice_1502241_46 = "Ini mungkin berguna... plus, Ah Ding benar-benar menyukainya.",
  str_voice_1502241_47 = "Saya dengan senang hati akan menerimanya, dan saya pasti akan membayar Anda kembali suatu hari nanti.",
  str_voice_1502241_48 = "Wow... Di mana Anda menemukan keindahan ini? Kami tidak sabar untuk mendengar semua tentang itu!",
  str_voice_1502241_49 = "Saya dibesarkan di sebuah kuil. Saat saya masih kecil, orang tua saya mengira bahwa kerasukan fiendling adalah penyebab tubuh saya yang tidak berkembang, tetapi itu bukanlah kasusnya.",
  str_voice_1502241_50 = "Para murid senior di atas gunung tidak benar-benar mengajari saya banyak hal. Ketika diberi pilihan antara menguasai talisman kertas dan mengasah ilmu bela diri saya, saya secara alami memilih bela diri.",
  str_voice_1502241_51 = "Setelah turun dari gunung, saya mencari nafkah dengan menundukkan makhluk jahat untuk siapa saja yang meminta. Sekitar waktu ini saya bertemu Ah Ding dan mengajarnya untuk tidak menginjak tanaman dengan cakar panas kecilnya, serta beberapa tips bertahan hidup lainnya.",
  str_voice_1502241_52 = "Alchemy Stars.",
  str_voice_1502241_53 = "Aku datang!",
  str_voice_1502241_54 = "Pagi. Sudah makan belum?",
  str_voice_1502241_55 = "Terima kasih sudah bersabar dengan Ah Ding.",
  str_voice_1502241_56 = "Sampai jumpa lagi. Temui aku kapanpun kamu senggang.",
  str_voice_1502241_57 = "Selamat Tahun Baru! Tidak peduli dari mana asal Anda, atau apakah Anda seorang Aurorian atau bukan, bukankah rasanya menyenangkan untuk berkumpul seperti ini?",
  str_voice_1701073_1 = "Aneh... Akhir-akhir ini aku sering bermimpi buruk dan mereka begitu nyata. Apa? Kamu maksud mungkin itu bukan mimpi tapi kenangan yang terlupa?",
  str_voice_1701073_2 = "Adras... jadi ini namaku? Dan kamu membantuku menemukannya lagi. Aku harus bilang... terima kasih.",
  str_voice_1701073_3 = "Semangat juang seorang Pemburu yang Pendiam tidak akan pernah padam, tidak peduli apa yang terjadi.",
  str_voice_1701073_10 = "Terlalu lemah untuk berbicara? Kamu pasti kelaparan. Apakah kamu punya tepung? Aku masih ingat cara membuat roti, dan itu sebanding dengan apa yang kamu miliki di sini. Mau mencobanya?",
  str_voice_1701073_11 = "Siap melayani Anda.",
  str_voice_1701073_12 = "Ancaman terbesar bagi dunia ini belum berubah... Tidak, saya tidak berbicara tentang Eclipsites.",
  str_voice_1701073_13 = "Melindungi orang-orang adalah tujuan hidupku. Meski tragedi masa lalu, aku tidak akan menyerah.",
  str_voice_1701073_14 = "Apakah kamu tahu aroma gandum yang sudah tumbuh? Ringan dan manis, merasuk ke dalam hidung di tengah panas. Itu adalah sensasi yang bahkan tidak bisa aku impikan lagi.",
  str_voice_1701073_16 = "Jangan lengah meski Eclipsite tidak ada. Melindungimu adalah tugas utama saya sekarang, PlayerName.",
  str_voice_1701073_17 = "Pagi! Mari hadapi hari baru dengan penuh semangat bersamaku!",
  str_voice_1701073_18 = "Seseorang harus lebih waspada ketika malam tiba, meskipun itu adalah tugas untukku. Untukmu, tugasmu adalah mendapatkan istirahat yang baik.",
  str_voice_1701073_19 = "Tidur nyenyak. Bahkan mimpi buruk pun tidak berani mendekat dengan aku berjaga.",
  str_voice_1701073_35 = "Datang kepadaku!",
  str_voice_1701073_36 = "Jangan coba-coba menghentikanku!",
  str_voice_1701073_37 = "Mencoba kabur? Coba lagi!",
  str_voice_1701073_38 = "Sudah terlambat untuk menyerah!",
  str_voice_1701073_39 = "Ayo bertarung!",
  str_voice_1701073_40 = "Serang!",
  str_voice_1701073_44 = "Apakah mungkin untuk menanam gandum di sini?",
  str_voice_1701073_58 = "Eclipsite hanyalah makhluk yang memiliki kekuatan fisik yang kuat, tetapi kecerdasan yang rendah.",
  str_voice_1701073_59 = "Jangan pernah meninggalkan celah bagi seseorang untuk memanfaatkan.",
  str_voice_1701073_60 = "Tidak ada penyesalan dalam hidup.",
  str_voice_1701073_61 = "Perlakukan orang yang kamu cintai dengan baik. Jangan tinggalkan penyesalan.",
  str_voice_1701073_62 = "Keabadian adalah hukumanku.",
  str_voice_1701073_63 = "Kegilaan pernah menjadi alasan saya.",
  str_voice_1701073_64 = "Mungkin aku masih tidak bisa melindungi semua orang sendirian, tapi aku punya kamu sekarang.",
  str_voice_1701073_65 = "Semua jejak rumahku telah dihapus dari tanah ini...",
  str_voice_1701073_66 = "Waktu menyembuhkan semua luka. Saya hanya Adras sekarang.",
  str_voice_1701073_67 = "Aku pernah mengambil sumpah di kuil.",
  str_voice_1701073_68 = "Aku tidak boleh terlambat di hari yang paling penting!",
  str_voice_1701073_69 = "Jangan mempermainkanku, Marcela kesayanganku...",
  str_voice_1701073_70 = "Apakah hanya aku? Kenapa semua orang menatapku seperti itu?",
  str_voice_1701073_71 = "Apakah aku tidak berguna bagi siapa pun sekarang...?",
  str_voice_1701073_72 = "Memiliki Marcela di sisiku sudah lebih dari cukup.",
  str_voice_1701073_73 = "Bagaimana bisa jadi begini? Tidak, tidak...",
  str_voice_1701073_74 = "Jangan mendekat! Lepaskan aku... Biarkan aku pergi!",
  str_voice_1701073_75 = "Kemana selanjutnya? Di mana rencana perjalanan saya?",
  str_voice_1701073_76 = "Satu, dua, tiga—empat!",
  str_voice_1701073_77 = "Ya?",
  str_voice_1701073_78 = "Ada yang salah? Jangan khawatir, aku akan menanganinya!",
  str_voice_1600264_1 = "Pakaianku akan meledak menjadi api saat ramuan ini habis. Akankah kamu mengikuti jejak terakhir api itu kepadaku?",
  str_voice_1600264_2 = "Kamu juga ingin minum ramuan itu? Tidak. Saya suka kamu apa adanya sekarang.",
  str_voice_1600264_3 = "Kamu ingin berada di Limbo bersamaku? Pegang tanganku, dan biarkan harapan kita bersinar terang!",
  str_voice_1600264_10 = "Jangan pergi! Jika tidak, saat kau kembali, mungkin hanya akan tersisa abu...",
  str_voice_1600264_11 = "Tidak ada tujuan dalam eksistensi, tapi kau membiarkanku tinggal di sini dan membuatnya berarti... *cegukan*",
  str_voice_1600264_12 = "Apakah kamu lebih suka nyala yang menyedihkan atau kobaran api yang menghabiskan semua...? Tunggu! Jika jawabanmu tidak benar, ramuan ini tidak akan bekerja lagi.",
  str_voice_1600264_13 = "Kiamat? Aku tidak peduli tentang hal-hal itu... Semua hal pasti akan berakhir, jadi kita semua harus sedikit lebih bebas.",
  str_voice_1600264_14 = "Jika kamu bisa menahan hati yang membara dan semangat yang terbakar, saya tidak keberatan memberikannya padamu. Tidak, saya belum minum terlalu banyak ramuan...",
  str_voice_1600264_16 = "Selamat datang di hari kosong lainnya! Mari kita beri makna, bagaimana?",
  str_voice_1600264_17 = "Mau tidur lagi, atau aku harus menerangi mimpimu?",
  str_voice_1600264_18 = "Waktu makan malam? Daripada makanannya, saya lebih tertarik pada orang yang memegang piring di depan saya.",
  str_voice_1600264_19 = "Sial, aku minum ramuan dan aku menjadi orang baru, tapi kenapa dadaku masih sakit? (Menangis) Oh, tolong aku...",
  str_voice_1600264_35 = "Gerbang menuju Limbo telah terbuka!",
  str_voice_1600264_36 = "Genggam tanganku erat-erat—",
  str_voice_1600264_37 = "Kita akan pergi ke ujung neraka bersama.",
  str_voice_1600264_38 = "Ayo berkelana ke ujung dunia bersama-sama.",
  str_voice_1600264_39 = "Vulcan!",
  str_voice_1600264_40 = "Limbo sedang terbakar!",
  str_voice_1600264_44 = "Bisakah aku menunggu akhir waktu bersamamu di sini?",
  str_voice_1600264_58 = "Selamat pagi! Saya sedang berusaha sekuat tenaga untuk meningkatkan semangat saya.",
  str_voice_1600264_59 = "Apakah kamu melihat matahari terbit pagi ini?",
  str_voice_1600264_60 = "Bisakah kamu datang kepadaku?",
  str_voice_1600264_61 = "(Menguap) Mmm...",
  str_voice_1600264_62 = "Selamat malam...",
  str_voice_1600264_63 = "Sudah mau tidur?",
  str_voice_1600264_64 = "Satu hari lagi, satu matahari terbenam lagi...",
  str_voice_1600264_65 = "\"Menantikan hari besok\"? Tunjukkan caranya...",
  str_voice_1600264_66 = "Aku merasakan sakit di dada lagi...",
  str_voice_1600264_67 = "Aku membeli hadiah untuknya sebagai permintaan maaf...",
  str_voice_1600264_68 = "Apakah kamu ingat seperti apa wajah orang tua kamu?",
  str_voice_1600264_69 = "Rasanya lebih nyaman di Colossus Anda daripada di dalam tong anti-ledakan.",
  str_voice_1600264_70 = "Ada buku mantra bagus yang bisa kamu rekomendasikan?",
  str_voice_1600264_71 = "Sebuah ramuan baru mungkin akan segera siap!",
  str_voice_1602251_1 = "Sebesar apapun Northland, tidak ada yang benar-benar menjadi ancaman bagi Yang Mulia Ratu. Tapi sebagai penjaganya, saya akan tetap berusaha sebaik mungkin untuk melindunginya.",
  str_voice_1602251_2 = "Hidup di hutan, menyembunyikan diri di salju adalah naluriku. Tetapi ketika malam tiba, saya memanjat ke puncak pohon tertinggi dan memaparkan diri pada kebesaran Northland.",
  str_voice_1602251_3 = "Saya suka diam-diam menonton orang-orang terpeleset di salju. Mereka selalu berjuang dalam kepanikan, dan saya tidak pernah bisa menahan diri untuk tidak tertawa dari tempat persembunyian saya. Bisakah kamu mengerti selera humor saya?",
  str_voice_1602251_4 = "Darah Northland mengalir dalam urat nadiku, jadi ketika aku melangkah di salju dengan kaki telanjang, aku kebal terhadap dingin dan malah merasakan kekuatan dari tanah ini.",
  str_voice_1602251_5 = "Kamu mungkin bisa menebak bahwa aku adalah pemburu yang cukup baik. Baik dalam mengejar atau mengintai, aku selalu bisa memanfaatkan kesempatan terbaik dan memberikan pukulan mematikan pada mangsaku!",
  str_voice_1602251_6 = "Kamu sudah melihat Beacon, kan? Sang tetua mengatakan bahwa Beacon dan tiga pohon kuno di Northland saling terhubung. Tapi dia hanya menatap ke kejauhan dalam diam setiap kali saya bertanya tentang itu.",
  str_voice_1602251_7 = "Kamu benar-benar pelari yang lambat. Mungkin saja aku harus menggendongmu di punggungku! Tidak usah khawatir, sebagai pengawal Yang Mulia Ratu, tugas saya juga untuk menjaga teman-temannya!",
  str_voice_1602251_8 = "Menyalak ke langit adalah cara kami mengekspresikan kegembiraan dan kesedihan. ... Anda bisa membedakan? Kalau begitu, mengapa Anda tidak mencoba menyalak beberapa kali untuk saya?",
  str_voice_1602251_9 = "Saya lebih suka menikmati pemandangan aurora dari suku di atas Istana Musim Dingin. Di sana, dekat perbatasan, itu membuat saya merasa seolah-olah itu hanya milik saya. Apakah kamu ingin melihatnya bersamaku?",
  str_voice_1602251_10 = "Pernah suatu waktu, saya tidak bisa mengejar kelinci, sekeras apapun saya mencoba. Dan kelinci itu terus menoleh seolah-olah mengejek saya! Baru kemudian saya tahu itu adalah milik Sir Novio...",
  str_voice_1602251_11 = "Apakah kamu mencoba mempekerjakan saya untuk menjadi penjaga di sini? Berhentilah berpikir seperti itu sekarang juga! Oh, kamu hanya ingin saya sebagai tamu? Itu tidak masalah, saya tidak keberatan.",
  str_voice_1602251_12 = "Halo, teman-teman hutan. Mau main game? Hei, kenapa kamu lari? Saya hanya bercanda...",
  str_voice_1602251_13 = "Sst, lihat orang licik itu di belakang batu? Kita kejutkan dia sampai tiga! Satu—hei, kenapa kamu tidak mengikuti rencanaku?!",
  str_voice_1602251_14 = "Kami percaya bahwa segala sesuatu memiliki roh, jadi tentu saja, kami memiliki banyak legenda menakjubkan di Northland. Apakah kamu pernah mendengar legenda tentang tiga pohon pinus? Konon, legenda itu berkaitan dengan asal-usul Northland.",
  str_voice_1602251_15 = "Selamat ulang tahun! Sesuai dengan adat suku, saya juga harus mengucapkan selamat atas keriput baru Anda.",
  str_voice_1602251_16 = "Yang Mulia tidak ada hari ini, jadi dia memberi saya hari libur. Menurut kamu kita harus melakukan apa?",
  str_voice_1602251_17 = "Wow, baru saja saya sadari ada lapisan es di tubuh saya. Saya harus membuat diri saya tampak rapi sebelum bertemu dengan Yang Mulia Ratu!",
  str_voice_1602251_18 = "A-Aku me-mengejar Aurorian tercepat di Northland! Aku harus menangkapnya tidak peduli apa yang terjadi!",
  str_voice_1602251_19 = "Orang yang selalu mengklaim terlalu sibuk atau lelah tidak tahu berapa banyak pemandangan indah yang mereka lewatkan.",
  str_voice_1602251_20 = "Dunia di luar Northland mungkin penuh peristiwa, tetapi saya lebih suka kesederhanaan dan kebebasan di sini.",
  str_voice_1602251_21 = "Bodoh, beritahu teman-temanmu yang memiliki benda aneh pada mereka untuk menjauh dari si tua!",
  str_voice_1602251_22 = "Demi Utara.",
  str_voice_1602251_23 = "Mereka telah mengambil sesuatu yang berharga dariku... Jadi saya mengerti perasaanmu. Kita akan mengambilnya kembali bersama-sama!",
  str_voice_1602251_24 = "Yang Mulia Ratu sangat perkasa. Menjadi penjaganya adalah pencapaian yang paling aku banggakan.",
  str_voice_1602251_25 = "Terkadang, saya harus berjuang keras untuk menahan diri dari memanggil para tetua \"Nenek.\" Itu hanya perasaan yang saya dapatkan dari mereka.",
  str_voice_1602251_26 = "Memanjat pohon, berburu, berlari melintasi salju... Apakah ada temanmu yang suka melakukan hal-hal tersebut?",
  str_voice_1602251_27 = "Orang asing yang menerobos masuk ke suku saya pantas mendapatkan lebih dari sekedar hajar!",
  str_voice_1602251_28 = "Semuanya terlihat nyaman dan selesa di sini, tapi kurang sedikit keaslian alam liar.",
  str_voice_1602251_29 = "Aku Tiare, Queen penjaga Utara, dan pemimpin Suku Salju Fox. Sebagai pengingat: Northland bukanlah tempat bermain, dan suku kami bukan tempat yang bisa kamu masuki sesuka hati!",
  str_voice_1602251_30 = "Apakah ini rasanya kekuatan alam?",
  str_voice_1602251_31 = "Apa suatu terburu-buru yang aku rasakan!",
  str_voice_1602251_32 = "Aku adalah pengawal Yang Mulia Ratu!",
  str_voice_1602251_33 = "Aku adalah penjaga Northland!",
  str_voice_1602251_34 = "Tiare, siap sedia!",
  str_voice_1602251_35 = "Semua bertenaga penuh!",
  str_voice_1602251_36 = "Ikuti aku!",
  str_voice_1602251_37 = "Untuk kedamaian di Northland!",
  str_voice_1602251_38 = "Serang, kekuatan alam!",
  str_voice_1602251_39 = "Kau tidak akan bisa kabur!",
  str_voice_1602251_40 = "Eclipsites Bodoh!",
  str_voice_1602251_41 = "Aku akan melindungimu!",
  str_voice_1602251_42 = "Yang Mulia Ratu akan senang!",
  str_voice_1602251_43 = "Jangan beritahu Yang Mulia Ratu untuk sementara waktu.",
  str_voice_1602251_44 = "Itu bukan aku! Eh, maksudku, aku tidak mendengar apa-apa yang aneh.",
  str_voice_1602251_45 = "Ini untuk apa?",
  str_voice_1602251_46 = "Aku suka ini!",
  str_voice_1602251_47 = "Kamu pasti punya banyak pernak-pernik!",
  str_voice_1602251_48 = "Aku sangat menyukainya!",
  str_voice_1602251_49 = "Aku lahir di suku perbatasan dan tumbuh besar bersama nenek dan rubah salju. Sedangkan orang tuaku, aku hanya tahu mereka adalah Pengawal Northland yang luar biasa.",
  str_voice_1602251_50 = "Queen menyelamatkan saya dari longsoran salju dan memperbaiki tombak saya. Saya memutuskan untuk melayani Yang Mulia Ratu tanpa syarat sejak saat itu.",
  str_voice_1602251_51 = "Aku masih ingat malam itu. Aku dan si tua diam-diam berada di gua di tengah seruan rubah salju. Aku masih belum bisa memahami apa artinya melindungi saat itu.",
  str_voice_1602251_52 = "Alchemy Stars.",
  str_voice_1602251_53 = "Sekarang apa...",
  str_voice_1602251_54 = "Selamat pagi.",
  str_voice_1602251_55 = "Selamat sore.",
  str_voice_1602251_56 = "Selamat malam.",
  str_voice_1602251_57 = "Selamat Tahun Baru. May Northland dan Queen terus mengawasi Anda.",
  str_voice_1202261_1 = "Ribbit! Ribbit!",
