  str_voice_1202261_52 = "Ribbit! Ribbit!",
  str_voice_1202261_53 = "Ribbit! Ribbit!",
  str_voice_1202261_54 = "Ribbit! Ribbit!",
  str_voice_1202261_55 = "Ribbit! Ribbit!",
  str_voice_1202261_56 = "Ribbit! Ribbit!",
  str_voice_1202261_57 = "Ribbit! Ribbit!",
  str_voice_1601774_1 = "Heheh... Oh, tidak apa-apa. Aku hanya merasa senang setiap kali kamu di dekatku!",
  str_voice_1601774_2 = "Manager, Manager, Manager! Lebih baik kamu mulai terbiasa mendengar itu!",
  str_voice_1601774_3 = "Tahu kan, kadang aku sangat takut dengan kegelapan, tapi dengan kamu di sini, aku tidak takut apa-apa.",
  str_voice_1601774_10 = "Berkilau, berkilau, kamu adalah bintang paling terang yang ada!",
  str_voice_1601774_11 = "Berikut datang Goldie! Apakah kamu merindukanku, Manajer?",
  str_voice_1601774_12 = "Mau bermain rumah-rumahan? Aku akan menjadi ibu, dan kamu akan menjadi ayah. Masukkan Marshmallow ke dalam campuran dan—tada! Kita adalah keluarga beranggotakan tiga!",
  str_voice_1601774_13 = "Tunggu, jangan bergerak... Baiklah, tinggi, ukuran... Bolehkah aku membuat bantal berukuran nyata dari dirimu? Lalu aku akan selalu merasa hangat dan nyaman!",
  str_voice_1601774_14 = "Setelah lama mengenakan kostum, rasanya enak juga kadang-kadang memakai piama yang lembut dan empuk—terutama saat kamu melakukannya bersamaku!",
  str_voice_1601774_16 = "Siap memulai pekerjaan hari ini, PlayerName? Ups, seharusnya aku memanggilmu \"Manajer\" hari ini!",
  str_voice_1601774_17 = "*Huahh* Pagi, kamu tidak ingin tiduran bersamaku lagi?",
  str_voice_1601774_18 = "Kamu telah bekerja sangat keras. Ayo, saya punya hadiah untukmu!",
  str_voice_1601774_19 = "Hari sudah berakhir? Yuk, kita bermimpi indah bersama.",
  str_voice_1601774_35 = "Mari kita mulai konsernya!",
  str_voice_1601774_36 = "Halo, teman-teman mimpi!",
  str_voice_1601774_37 = "Biarkan saya melihat tanganmu!",
  str_voice_1601774_38 = "Bernyanyilah bersamaku!",
  str_voice_1601774_39 = "Oh––Asyik!",
  str_voice_1601774_40 = "Aku akan menghancurkanmu demi mimpi!",
  str_voice_1601774_44 = "Saya ingin mengadakan konser piama di sini. Apakah itu baik-baik saja, Manajer?",
  str_voice_1601774_58 = "Do-re-mi-fa-so-la-ti-do!",
  str_voice_1601774_59 = "Pagi, Manajer!",
  str_voice_1601774_60 = "Kamu akan terlambat jika tidak bangun sekarang, Manager!",
  str_voice_1601774_61 = "Pagi! Setiap hari adalah lembaran baru!",
  str_voice_1601774_62 = "Ingin aku menyanyikan lagu pengantar tidur untukmu?",
  str_voice_1601774_63 = "Apakah saya menjadi bintang di panggung hari ini?",
  str_voice_1601774_64 = "Marshmallow ingin tidur di sampingmu.",
  str_voice_1601774_65 = "Selamat malam, Manajer!",
  str_voice_1601774_66 = "Piama ini membuatku tanpa sadar mengantuk...",
  str_voice_1601774_67 = "Haha, apa pendapatmu tentang tarianku?",
  str_voice_1601774_68 = "Bahkan di rumah dengan piyama, kamu tidak boleh bermalas-malasan!",
  str_voice_1601774_69 = "Di mana kamu, Marshmallow?",
  str_voice_1601774_70 = "*batuk* Manajer, tenggorokanku...",
  str_voice_1601774_71 = "Apa pendapatmu tentang lagu baru saya?",
  str_voice_1602233_1 = "May seluruh keindahan dunia menari atas namamu, dan May semoga kepemimpinan bijakmu berkembang selama seribu tahun.",
  str_voice_1602233_2 = "Ketika berhubungan denganmu, aku akan bersedia mengabulkan bahkan permintaan yang sedikit manja, jika itu sesuatu yang benar-benar kamu inginkan.",
  str_voice_1602233_3 = "Makanan lezat yang menggugah selera, permainan yang begitu mengasyikkan. Di dunia yang penuh dengan kesenangan tanpa henti ini, mengapa ada yang memilih untuk hidup pahit sebagai dewa yang dipuja dalam cerita kuno itu?",
  str_voice_1602233_10 = "Tahan air, tahan dingin, melindungi dari panas... Perlindungan apa lagi yang bisa diberikan pada pakaian mereka? Hadiah langka seperti ini harus dihargai dan dirawat.",
  str_voice_1602233_11 = "Ah! Anginnya lembut, cahayanya hangat, dan dengan kamu di sini, semuanya sempurna! Ini adalah hari yang patut diingat, memang.",
  str_voice_1602233_12 = "Mari kita jadikan ini rahasia kita berdua. Janjikan padaku kamu akan hidup lama dan bergabung denganku dalam petualangan yang tak terhitung jumlahnya yang lebih menarik.",
  str_voice_1602233_13 = "Banyak yang berdoa dengan hati penuh kemarahan, kebodohan, dan keserakahan. Niat murni seperti milikmu benar-benar jarang ada.",
  str_voice_1602233_14 = "Baik itu rentang hidup seorang Aurorian atau fiendling, kita hanyalah debu dalam kosmos yang luas, tidak dapat dibedakan satu sama lain. Kita semua hanya menikmati momen singkat dalam pelukan dunia.",
  str_voice_1602233_16 = "Banyak yang berdoa padaku, tetapi kamu adalah yang pertama yang pernah berdoa untukku.",
  str_voice_1602233_17 = "Bagaimana cuaca hari ini? Jika kamu tidak suka, izinkan aku untuk menggantinya untukmu!",
  str_voice_1602233_18 = "Ah, konstelasi Longzhou... Bahkan ada satu di antara mereka yang bernama \"Chen.\"",
  str_voice_1602233_19 = "Kamu seharusnya tidak bergadang terlalu larut; itu buruk untuk kesehatanmu. Yah, sepertinya aku hanya harus memberkati kamu dengan kesehatan yang baik.",
  str_voice_1602233_35 = "Lihatlah, warna-warna yang cerah.",
  str_voice_1602233_36 = "Baiklah.",
  str_voice_1602233_37 = "Saat naga berkeliaran, seribu ombak melonjak.",
  str_voice_1602233_38 = "Dengan satu pikiran saja, bunga teratai muncul.",
  str_voice_1602233_39 = "Jelajahi dunia sesuai keinginanmu!",
  str_voice_1602233_40 = "Nikmati melodi tersebut.",
  str_voice_1602233_44 = "Kamu bukan pengikut, kamu adalah teman, 'kan?",
  str_voice_1602233_58 = "Pagi telah tiba! Lagi-lagi hari yang tenang.",
  str_voice_1602233_59 = "Maukah kamu bergabung denganku di luar?",
  str_voice_1602233_60 = "Sudah bangun, PlayerName?",
  str_voice_1602233_61 = "Aku masih mengantuk... Mungkin hubungi aku tahun depan...",
  str_voice_1602233_62 = "Malam adalah untuk mendengarkan debur ombak.",
  str_voice_1602233_63 = "Kamu tidak akan bisa tumbuh tinggi jika tidak tidur dengan baik.",
  str_voice_1602233_64 = "Tidur yang nyenyak, PlayerName. Sekarang, kamu tidak akan pernah lagi mengalami mimpi buruk.",
  str_voice_1602233_65 = "Apakah hari ini menyenangkan untukmu?",
  str_voice_1602233_66 = "Bangun bersama matahari dan istirahat saat senja adalah kebiasaan yang baik.",
  str_voice_1602233_67 = "Pastikan kamu memakai pita berwarna-warni yang telah aku berikan.",
  str_voice_1602233_68 = "Ada banyak festival di Longzhou... Mari kita rayakan bersama lain kali.",
  str_voice_1602233_69 = "Ajar aku bahasamu, PlayerName!",
  str_voice_1602233_70 = "Saya menerima persembahan yang belum pernah saya cicipi sebelumnya. Mau coba?",
  str_voice_1602233_71 = "Persembahan apa... tidak, hadiah apa yang kamu suka?",
  str_voice_1502281_1 = "\"Caelestite Terakhir\"... Judul yang keren! Ah, seandainya itu ideku...",
  str_voice_1502281_2 = "Claudius, Ethelred, Patroclus... Hmm, saya memang memiliki selera yang fantastis untuk nama. Oh? Bukankah biasa untuk memberi nama bom?",
  str_voice_1502281_3 = "\"Hidup itu tentang kecepatan dan manisnya rasa. Itulah sebabnya balapan sambil makan permen adalah inti dari hidup.\" Cukup keren, bukan?",
  str_voice_1502281_4 = "Hehe! Aku adalah pahlawan yang ditakdirkan untuk menyelamatkan Astra, dan setelah melepaskan \"Segel Malam Abadi\" dari tangan kananku, aku akan menjadi lebih kuat!",
  str_voice_1502281_5 = "Menjadi pahlawan, pada dasarnya tentang persahabatan, kerja keras, kemenangan, dan tentu saja, aspek paling penting—gula. Saya pikir saya cocok dengan semua ini dengan sempurna.",
  str_voice_1502281_6 = "\"Pada saat ini, tangan kananku menyala. Membakar, ia mengaum, memanggilku untuk...\" Bagian selanjutnya apa ya? Oh tidak, bagaimana bisa aku lupa kalimat keren seperti itu!?",
  str_voice_1502281_7 = "Kamu tidak terlalu buruk. Berikan sedikit usaha lagi, dan saya mungkin akan mempertimbangkan untuk membiarkan kamu bergabung dengan skuad prajurit saya!",
  str_voice_1502281_8 = "Aku mengakui kekuatanmu, Caelestite Terakhir. Mulai hari ini, kamu adalah anggota resmi dari skuadku, dan sebagai bagian dari ritual inisiasi, kamu harus berbagi permen lolipop itu denganku!",
  str_voice_1502281_9 = "Setelah semua ini berakhir, sudahkah kamu memikirkan apa yang akan kamu lakukan selanjutnya? Jika kamu belum merencanakan apa-apa, bagaimana kalau bergabung denganku... Oh tidak, sebaiknya aku tidak mengundang sial!",
  str_voice_1502281_10 = "Membosankan... Aku ingin balapan... Tidak, mungkin ini semua bagian dari ujian sejati seorang heroine... Aku tidak bisa lari sekarang.",
  str_voice_1502281_11 = "Hah? Kau mau aku tinggal di sini dan menunggu seperti gadis kecil yang baik? Jangan bercanda! Aku ingin balapan! Kau memaksa...? Kau terlalu menggantung, tapi terserah, aku akan tinggal denganmu sebentar, hanya sebentar saja, oke?",
  str_voice_1502281_12 = "Hmm, nasi toffee adalah kegagalan yang epik... Kombinasi itu terlalu aneh... Mungkin saya harus mencoba permen buah lain kali.",
  str_voice_1502281_13 = "Biarkan aku melihat... Bagaimana dengan permen karamel? Tidak, tidak—bagaimana kalau permen susu saja!?",
  str_voice_1502281_14 = "Kamu ingin tahu bagaimana makan permen begitu banyak tidak merusak gigi saya? Hahaha, itu karena saya adalah Sweet Reaper dari Rediesel Wrench! Saya tidak akan pernah mengabaikan kebersihan mulut saya!",
  str_voice_1502281_15 = "Selamat Ulang Tahun! Jadi, di mana kuenya? Yang penuh dengan krim dan stroberi!",
  str_voice_1502281_16 = "Hari ini, sama seperti kemarin, aku akan memberikan segalanya demi nasib dunia!",
  str_voice_1502281_17 = "Selamat pagi... Yaaaawn... Aku sangat mengantuk. Kamu tidak masalah jika aku tidur sebentar lagi, kan?",
  str_voice_1502281_18 = "Matahari... telah tenggelam, dan sekarang, orang-orang itu seharusnya mulai bergerak, bukan? Hah? Siapa mereka? Nah... itu tidak penting—ini adalah pertempuranku, jangan ikut campur!",
  str_voice_1502281_19 = "Selamat malam! Kamu ingin tahu kenapa aku tidak tidur? Karena aku sudah dewasa, dan aku bisa memutuskan jika aku ingin tidur lebih awal lagi!",
  str_voice_1502281_20 = "Aku tumbuh besar di Rediesel Wrench jadi aku bisa akrab dengan setiap orang, kecuali wanita itu... Hmph! Benar... setiap heroine butuh nemesis.",
  str_voice_1502281_21 = "Lumopolis? Ah... Tentu saja saya tahu itu! Saya mengalahkan naga jahat di sana dan menyelamatkan seorang tuan putri yang cantik!",
  str_voice_1502281_22 = "Jalani hidup sepenuhnya! Selalu ada waktu untuk permen!",
  str_voice_1502281_23 = "Jangan khawatir, aku akan melindungi semua orang! Lagipula, aku berhasil mengalahkan tiga Eclipsite saat aku baru berusia sembilan tahun.",
  str_voice_1502281_24 = "Azure... Jelas dia adalah anak buah dari penguasa jahat... Lebih cepat atau lambat, aku akan mengungkap wajah aslinya!",
  str_voice_1502281_25 = "Anak-anak di Rediesel Wrench semua adalah anak buahku.",
  str_voice_1502281_26 = "Melindungi permen di dunia adalah misi utama saya! Oh, permen nol kalori dan permen licorice TIDAK termasuk.",
  str_voice_1502281_27 = "Sesuatu yang tidak aku suka...? Kegagalan, kira-kira...? Tapi itu semua bagian dan parcel dari ujian seorang heroine!",
  str_voice_1502281_28 = "Aku sangat iri... Jadi, ini adalah senjata super kuno dari Caelestite Terakhir...",
  str_voice_1502281_29 = "Ah, dipandu oleh tangan takdir, akhirnya kita bertemu, penyelamat legendaris—terima kasih untuk segalanya. Ini, ambil beberapa permen!",
  str_voice_1502281_30 = "Hmm, ini terasa cukup bagus.",
  str_voice_1502281_31 = "Segel di tangan kananku...",
  str_voice_1502281_32 = "\"Segel Eternal Night,\" pinjamkan aku kekuatanmu...",
  str_voice_1502281_33 = "\"Seruan Malam Abadi\"—Tunjukkan sumbermu!",
  str_voice_1502281_34 = "Haruskah saya turun tangan?",
  str_voice_1502281_35 = "Toples permen hampir penuh!",
  str_voice_1502281_36 = "Mengirim mereka hadiah kecil?",
  str_voice_1502281_37 = "Cobalah gigitan dari buah persik!",
  str_voice_1502281_38 = "Manis sekali!",
  str_voice_1502281_39 = "Manis seperti madu!",
  str_voice_1502281_40 = "Manis seperti pie!",
  str_voice_1502281_41 = "Skuad Pejuang, bersiap bertarung!",
  str_voice_1502281_42 = "Nasibmu kalah dariku akan membuatku ditakdirkan untuk kalah dari seseorang yang lebih kuat!",
  str_voice_1502281_43 = "Tapi... ini hanya ujian dari takdir...",
  str_voice_1502281_44 = "Ke mana kisah pahlawan kita akan membawa kita selanjutnya?",
  str_voice_1502281_45 = "Terima kasih, mau permen?",
  str_voice_1502281_46 = "Kamu tahu aku butuh ini?",
  str_voice_1502281_47 = "Kita semua adalah sekutu skuad sekarang—tidak perlu terlalu formal!",
  str_voice_1502281_48 = "Kamu juga telah dipandu oleh takdir, Caelestite.",
  str_voice_1502281_49 = "Selama yang bisa saya ingat, Roy telah merawat saya. Bagi saya, dia seperti kepala desa bagi prajurit!",
  str_voice_1502281_50 = "Hmph, bukan bermaksud sombong, tapi aku cukup pandai mengemudi. Pertama kali aku mengendarai, aku bahkan berhasil mengalahkan tiga Eclipsite!",
  str_voice_1502281_51 = "Mereka selalu bilang bahwa penyihir... maksudku Azure, adalah pembalap yang luar biasa, tapi aku juga pernah menjuarai kejuaraan!",
  str_voice_1502281_52 = "Alchemy Stars!",
  str_voice_1502281_53 = "Hei!",
  str_voice_1502281_54 = "Selamat pagi! Fyuh!",
  str_voice_1502281_55 = "Sudah siang?",
  str_voice_1502281_56 = "Huff... Mengantuk.",
  str_voice_1502281_57 = "Selamat Tahun Baru! Apakah kamu memiliki resolusi Tahun Baru? Aku akan menceritakannya semua kepada tuan takdir!",
  str_voice_1500924_1 = "Aku tahu aku terlihat bagus dengan ini, tapi kau benar-benar tidak perlu menatapku seperti itu. Hah? Kau juga tidak perlu membelakangiku! Kamu, kamu seharusnya... berbalik...",
  str_voice_1500924_2 = "Mengapa saya selalu membawa Hunting Stone kemana-mana? Bukankah sudah jelas? Hunting Stone adalah bagian terpenting dari seluruh penampilan saya!",
  str_voice_1500924_3 = "Uhuk, uhuk... O-ho-ho! Inilah jenis kesepakatan yang bisa saya dukung! Percayalah padaku—rekan bisnismu pasti tidak ingin melewatkan investasi dari saya! Eh? Kapan kamu datang?! Saya tidak mengatakan apa-apa tadi, kamu pasti mendengar hal-hal!",
  str_voice_1500924_10 = "Mengapa kamu mengabaikanku? Katakan padaku, apakah kamu melakukan sesuatu yang akan membuatku marah, dan sekarang kamu mencoba menghindariku? Hah? Kamu hanya sibuk dengan pekerjaan? Lalu... Aku rasa kamu memang tidak punya waktu luang, ya?",
  str_voice_1500924_11 = "Hmph, karena kamu mengundangku dengan begitu baik, aku rasa aku tidak masalah untuk membantumu. Cukup beri tahu aku tugas apa yang sulit yang perlu aku selesaikan untukmu?",
  str_voice_1500924_12 = "Apakah saya ingin menyingkirkan Hunting Stone? Hunting Stone adalah benda kecil yang sangat keras kepala, jika saya tidak merawatnya, siapa lagi yang akan melakukannya?",
  str_voice_1500924_13 = "\"Jika Anda ingin berbisnis dengan orang-orang di luar sana, pertama-tama Anda perlu belajar bagaimana berpakaian dengan layak...\" Ini adalah aturan bisnis yang sangat penting. Anda belum pernah mendengarnya sebelumnya? Nah, sekarang Anda sudah tahu.",
  str_voice_1500924_14 = "Jangan berpikir kamu bisa bersembunyi dengan baik—saya sudah memperhatikanmu. Kamu adalah orang yang membantu saya keluar dari mimpi itu. Tapi jangan terlalu sombong... yah, saya rasa kamu tidak bisa menahan diri untuk sedikit bangga pada diri sendiri!",
  str_voice_1500924_16 = "Bersiap-siap untuk pergi, ya? Belum? Tidak mungkin. Oke, aku akan menunggumu.",
  str_voice_1500924_17 = "Selamat pagi. Saya ingin memastikan sesuatu... Tidak ada wortel di sarapan hari ini, bukan?",
  str_voice_1500924_18 = "Begitu banyak undangan makan malam... Kenapa kamu tidak pergi ke salah satunya? Hah...? Kamu ingin aku mengajakmu?",
  str_voice_1500924_19 = "Dunia tidak akan runtuh jika Anda melanggar beberapa aturan di sini dan di sana, tetapi Anda benar-benar harus beristirahat.",
  str_voice_1500924_35 = "Belum mulai?",
  str_voice_1500924_36 = "Bagaimana menurutmu?",
  str_voice_1500924_37 = "Rasakan duri-duri indahku!",
  str_voice_1500924_38 = "Jangan berjuang. Itu akan semakin menyakitkan.",
  str_voice_1500924_39 = "Ambil semuanya!",
  str_voice_1500924_40 = "Anda tidak bisa melarikan diri!",
  str_voice_1500924_44 = "Aku mulai menyukai tempat ini akhir-akhir ini. Itu persis yang dipikirkan oleh Hunting Stone, bukan aku!",
  str_voice_1500924_58 = "Mulai sekarang, aku akan hidup terhormat bersama Hunting Stone!",
  str_voice_1500924_59 = "Jika kamu memiliki waktu, bisakah kamu menemani saya ke Umbraton lagi?",
  str_voice_1500924_60 = "Ada yang bisa saya bantu untukmu? Saya tidak suka berhutang budi yang begitu besar.",
  str_voice_1500924_61 = "Saya akan mencoba mempertimbangkan pendapat Anda, tetapi makan wortel adalah hal yang tidak bisa ditawar.",
  str_voice_1500924_62 = "Pakaian ini sangat cocok dengan apa yang diinginkan ayah untuk saya, tetapi sekarang saya memakainya untuk diri saya sendiri.",
  str_voice_1500924_63 = "Apakah kota ini benar-benar belum ditemukan sebelumnya? Memang, sepertinya terserah saya untuk mengambil alih kendali.",
  str_voice_1500924_64 = "Selama tidak ada yang melihat, mungkin... mencicipi kerikil dari tanah tidak menjadi masalah, 'kan?",
  str_voice_1500924_65 = "Langsung bertarung tanpa bicara... Sungguh tidak masuk akal. Sekarang aku hanya merasa sedih tentang gaun baruku.",
  str_voice_1500924_66 = "Jika bukan karena bau aneh itu, hutan ini pasti akan sangat nikmat.",
  str_voice_1500924_67 = "Hunting Stone, kali ini, giliran saya yang mengejar jejakmu!",
  str_voice_1500924_68 = "Hmm? Haruskah saya mengajari Anda cara mematuhi aturan?",
  str_voice_1500924_69 = "Sekarang bukan waktunya untuk istirahat!",
  str_voice_1500924_70 = "Kenapa itu tidak ada di sini?",
  str_voice_1500924_71 = "Harta karun ditemukan!",
  str_voice_1602271_1 = "Santai, Eclipsite di sekitar kita tidak akan mengganggu. Lihat, Eagle Hunters Satu dan Dua sedang mengirim gangguan dari atas, dan Tiga juga sedang patroli.",
  str_voice_1602271_2 = "Caelestite Satu... Uh, maaf, PlayerName. Saya rasa saya belum terbiasa memanggilmu dengan namamu...",
  str_voice_1602271_3 = "Kamu ingin aku sedikit santai? Ini hanya kebiasaan. Jika kamu tidak suka, aku bisa meredamnya. Hmm, bukan itu yang kamu maksud?",
  str_voice_1602271_4 = "Jika saya tidak membuat kemajuan, itu hanya berarti saya belum berlatih cukup keras. Saya tidak seperti kamu, PlayerName—saya tidak lahir dengan kekuatan ini.",
  str_voice_1602271_5 = "Saya ingin bekerja keras dan terus meningkatkan algoritma Pemburu Elang sehingga mereka dapat memberikan keamanan yang lebih besar untuk tim saya...",
  str_voice_1602271_6 = "Aku berhasil, PlayerName! Oh, aku ingin memberitahu orang tuaku dan bibiku sekarang juga. Bukan untuk mengembalikan kehormatan keluarga kita, tapi hanya karena aku ingin berbagi kebahagiaanku dengan orang-orang yang paling kucintai terlebih dahulu.",
  str_voice_1602271_7 = "Ada pameran baru di Museum Militer Illumina yang ingin saya sempatkan waktu untuk melihatnya. Jadi, mau ikut? Saya tidak keberatan jika kamu ikut.",
  str_voice_1602271_8 = "Saya memiliki lencana Synergy ekstra yang bisa saya berikan kepada kamu. Ya, kamu memerlukan dua bagian untuk membuatnya utuh. Di mana setengah bagian lainnya? Saya telah menyimpannya.",
  str_voice_1602271_9 = "Ya, aku berjanji padamu. Setidaknya ketika aku di sisi kamu, aku tidak akan begitu tegang.",
  str_voice_1602271_10 = "Kamu tidak mengizinkanku berjaga atau beristirahat... Apakah kamu memanggilku ke sini karena ingin memberitahuku sesuatu?",
  str_voice_1602271_11 = "Ah, karena ini permintaanmu, kenapa tidak?",
  str_voice_1602271_12 = "Tentu saja kamu tidak bisa menemukan drone seperti Eagle Hunters di mana pun di Illumina, saya yang memodifikasinya sendiri. Ini bukan hal yang aneh, saya memang mengambil jurusan teknik mesin di akademi.",
  str_voice_1602271_13 = "Kamu terkadang mengingatkan saya pada adik perempuan saya. Hah? Saya tidak bermaksud buruk dengan itu. Meskipun dia delapan tahun lebih muda, dia sudah menunjukkan bakat yang hebat.",
  str_voice_1602271_14 = "Apa yang akan kulakukan jika tidak ada perang...? Itu adalah kemewahan bagi saya untuk membayangkan itu, PlayerName. Saya hanya ingin kita aman dan selamat sekarang ini.",
  str_voice_1602271_15 = "Aku punya kue yang sudah dipotong di sini, tapi aku tidak terlalu lapar... Kamu bisa memakannya.",
  str_voice_1602271_16 = "Sepertinya kamu juga sibuk, ya? Jika begitu, kamu tidak bisa menyuruhku untuk beristirahat lebih banyak.",
  str_voice_1602271_17 = "Kamu sudah bangun? Semoga latihan pagiku tidak mengganggumu. Tidak apa-apa, kamu bisa tidur lebih lama sedikit.",
  str_voice_1602271_18 = "Waktu makan malam? Terima kasih, cukup simpan satu gigitan untukku, aku tidak keberatan dengan rasanya.",
  str_voice_1602271_19 = "Tidak apa-apa. Aku sudah terbiasa begadang saat melakukan recons. Tapi kamu tidak boleh memaksakan diri, segera beristirahatlah.",
  str_voice_1602271_20 = "Kami akan pergi ke mana pun kami dibutuhkan. Saya percaya pada misi yang dipercayakan kepada Federasi Illumina. Tidak ada orang lain yang bisa melakukan apa yang kami lakukan.",
  str_voice_1602271_21 = "Northland? Adikku suka mitos dan dongeng Northland. Aku ingin membawanya ke sana jika aku mendapat kesempatan.",
  str_voice_1602271_22 = "Jayalah Illumina!",
  str_voice_1602271_23 = "Suatu hari, kita akan membasmi semua hal-hal gelap dan kotor itu...",
  str_voice_1602271_24 = "Ada yang bilang aku sedikit mirip dengan Commander Hiiro, tapi aku tahu itu hanya pujian. Aku hanya berharap aku tidak akan mengecewakan sang commander.",
  str_voice_1602271_25 = "Sst, jangan berisik... Bagaimana kamu tahu aku ingin mengelus ekor Komandan Philyshy?",
  str_voice_1602271_26 = "Siapa kucing kecil ini? May Aku... mengelus perut kecilmu yang lembut?",
  str_voice_1602271_27 = "Meski hanya simulasi pertempuran, aku tidak ingin kehilangan satu poin pun. Jadi jangan coba hentikan aku. Aku bisa terus melanjutkan.",
  str_voice_1602271_28 = "Melihat adalah percaya, dan aku melihat Colossus... tidak cocok untuk pengintaian diam-diam.",
  str_voice_1602271_29 = "Skuad Eagleeye, Kapten—Eagle Hunter Zero melapor! Hah? Apakah itu kamu... Caelestite One?",
  str_voice_1602271_30 = "Kerja keras dapat menutupi banyak kekurangan.",
  str_voice_1602271_31 = "Mata tajam seperti elang...",
  str_voice_1602271_32 = "Serang keras seperti cakar elang...",
  str_voice_1602271_33 = "Bergeraklah cepat seperti elang yang sedang memburu...",
  str_voice_1602271_34 = "Skuad Eagleeye, berkumpul!",
  str_voice_1602271_35 = "Pengintaian selesai!",
  str_voice_1602271_36 = "Menunggu perintah.",
  str_voice_1602271_37 = "Ini Waktu Elang!",
  str_voice_1602271_38 = "Serangan talon!",
  str_voice_1602271_39 = "Shh! Diam...",
  str_voice_1602271_40 = "Anda tidak bisa kabur sekarang.",
  str_voice_1602271_41 = "Siap, laksanakan.",
  str_voice_1602271_42 = "Ya, itu bagian dari pekerjaanku.",
  str_voice_1602271_43 = "Susun kembali dan coba lagi!",
  str_voice_1602271_44 = "Pemburu Elangku seharusnya tidak menakuti para Firefly ini, bukan?",
  str_voice_1602271_45 = "Demi aku?",
  str_voice_1602271_46 = "Baiklah. Terima kasih.",
  str_voice_1602271_47 = "Oh, kamu tidak perlu melakukannya.",
  str_voice_1602271_48 = "Aku memang menyukainya... Aku akan sangat menghargainya.",
  str_voice_1602271_49 = "Meski terlahir dalam \"Keluarga Pahlawan\" di Gannon akan membuatmu banyak diperhatikan, itu tidak memberimu keuntungan nyata.",
  str_voice_1602271_50 = "Anak-anak berbakat itu telah dipilih oleh akademi utama dan bahkan komite jauh sebelum saya. Tapi saya tidak bisa hanya bersembunyi di sudut dan tetap tidak berdamai.",
  str_voice_1602271_51 = "Alih-alih berlindung di laboratorium yang aman, aku lebih memilih bertempur di garis depan. Itulah sebabnya aku bergabung dengan Legiun ke-3. Ada masalah?",
  str_voice_1602271_52 = "Alchemy Stars.",
  str_voice_1602271_53 = "Lapor, Pak!",
  str_voice_1602271_54 = "Selamat pagi.",
  str_voice_1602271_55 = "Selamat sore.",
  str_voice_1602271_56 = "Selamat malam.",
  str_voice_1602271_57 = "Selamat Tahun Baru. Saya? Harapan saya hanya agar adik perempuan saya bisa bebas... dan untuk kamu, saya berharap kamu memiliki tahun baru yang bahagia dan aman.",
  str_voice_1602291_1 = "Aku... Aku suka bermain game. Setiap pemain baru mulai dari level yang sama, dan kamu selalu bisa mengulang jika hal-hal tidak berjalan sesuai keinginanmu.",
  str_voice_1602291_2 = "Aku tahu seharusnya aku tidak menggunakan kakiku untuk mengambil barang dari tanah... Tapi tanganku biasanya terlalu sibuk bermain game.",
  str_voice_1602291_3 = "Punggungku terasa begitu kaku... Andai saja aku menerima tas pijat dari Gronru lebih awal. Tunggu, kamu mau memijatku? Eh, aku rasa tidak perlu berbaring sih.",
  str_voice_1602291_4 = "Jenis game apa yang paling kamu sukai? Game strategi, game pertarungan, penembak, RPG, atau... Saya kebanyakan suka game klasik.",
  str_voice_1602291_5 = "Orang-orang di masa lalu menciptakan berbagai jenis video game yang mengejutkan, sulit untuk mengingat semuanya. Pasti sangat memuaskan untuk memiliki begitu banyak pilihan, meskipun tidak ada waktu untuk memainkan semuanya.",
  str_voice_1602291_6 = "Gronru pernah membahas tentang game realitas virtual. Jika game pernah mencapai titik itu, saya yakin mereka akan digunakan untuk banyak hal di luar gaming.",
  str_voice_1602291_7 = "Kamu ingin saya tunjukkan cara memainkan game ini? Yah, agak sulit untuk dijelaskan, jadi mari kita langsung mulai, dan saya akan mengajari kamu saat kita bermain.",
  str_voice_1602291_8 = "*menguap* Aku benar-benar berusaha keras untuk menyesuaikan diri dengan jam biologis kamu... Dengan cara itu, kita bisa memiliki lebih banyak waktu bersamaan selama siklus bangun kita, bukan?",
  str_voice_1602291_9 = "Dengan kamu sebagai bantalku, aku yakin bisa tidur nyenyak bahkan di malam hari!",
  str_voice_1602291_10 = "Hei—Aku benar-benar jauh dari permainanku sekarang! Jika kamu pernah ingin mengalahkanku, sekarang adalah kesempatanmu...",
  str_voice_1602291_11 = "Agak terlalu terang di sini, menurutmu tidak? Oh, baiklah... Aku akan biarkan lampu tetap menyala, agar mataku tidak terlalu lelah.",
  str_voice_1602291_12 = "Menjalankan toko itu sulit... Tapi untungnya tidak banyak gamer di Astra. Saya seharusnya bisa pensiun cukup awal.",
  str_voice_1602291_13 = "Saya baik-baik saja dengan bermain game, baik-baik saja dengan kompetisi... tetapi naik ke panggung untuk menerima penghargaan saya? Tentu saja tidak!",
  str_voice_1602291_14 = "Beberapa game lebih menyenangkan saat kamu memainkannya bersama orang lain. Itulah salah satu alasan mengapa saya selalu di arcade.",
  str_voice_1602291_15 = "Aku tahu kamu adalah tipe orang yang menggunakan tanggal ulang tahun aslimu untuk karakter dalam game... Selamat ulang tahun.",
  str_voice_1602291_16 = "*hoahm* Oh, itu kamu... ngh. 's okay, aku akan kembali tidur saat kamu pergi.",
  str_voice_1602291_17 = "Hmm? Terkejut melihatku bangun sepagi ini? Mungkin itu karena... Aku tidak pernah tidur.",
  str_voice_1602291_18 = "Sarapan masih belum siap? Tapi aku sudah bangun sejak tadi.",
  str_voice_1602291_19 = "... Oke, pergilah tidur. Apakah kamu perlu saya bangunkan di pagi hari?",
  str_voice_1602291_20 = "Umbraton sangat cocok untuk orang seperti saya, karena Lumopolis menutupi sebagian besar sinar matahari.",
  str_voice_1602291_21 = "Federasi Illumina tampaknya menyimpan banyak game lama sebagai bagian dari koleksi artefak kuno mereka... Tapi bagaimana saya bisa mendapatkan itu?",
  str_voice_1602291_22 = "Bayangan mengawasimu.",
  str_voice_1602291_23 = "Andai melawan Eclipsite itu seperti Tetrablox, jadi saya bisa mengumpulkan mereka dalam barisan dan menghapus mereka dengan blok yang tepat.",
  str_voice_1602291_24 = "Aku bukan tipe yang suka interaksi sosial. Aku hanya menjadi perbincangan ketika berbicara tentang game dengan Gronru.",
  str_voice_1602291_25 = "Aku ingin belajar beberapa teknik dari Odi, sehingga aku bisa menggali dan memperbaiki konsol game lama dengan sendirinya.",
  str_voice_1602291_26 = "Saya bisa bertahan hidup hanya dengan bermain game seumur hidup saya. Jika saya hanya bisa memilih satu game untuk dimainkan, itu haruslah Tetrablox.",
  str_voice_1602291_27 = "Jalanan ramai di siang bolong... Urgh, itu membuatku pusing.",
  str_voice_1602291_28 = "Aku berharap bisa berada di Rec Room dan bermain game sepanjang waktu, tapi orang-orang di sana terlalu banyak...",
  str_voice_1602291_29 = "Tanda seru telah muncul! Memuat Quest... Halo, nama saya Batia, dan saya adalah pemilik Arcade Hidden Fangs di Umbraton. Selamat datang di dunia game!",
  str_voice_1602291_30 = "Naik level!",
  str_voice_1602291_31 = "Ascension selesai!",
  str_voice_1602291_32 = "Saatnya mencari panggung untuk menguji kekuatan baru saya.",
  str_voice_1602291_33 = "Sekarang aku bisa menyelesaikan lebih banyak stage bersamamu.",
  str_voice_1602291_34 = "Saya, melawan Eclipsite? Serius?",
  str_voice_1602291_35 = "Seharusnya tumpukan itu cukup...",
  str_voice_1602291_36 = "Waktunya membersihkan papan!",
  str_voice_1602291_37 = "Pas seperti sarung tangan.",
  str_voice_1602291_38 = "Jangan tinggalkan ruang kosong.",
  str_voice_1602291_39 = "Daya tembak penuh!",
  str_voice_1602291_40 = "Kombo rantai!",
  str_voice_1602291_41 = "Mulai game.",
  str_voice_1602291_42 = "Wow, stage selesai.",
  str_voice_1602291_43 = "Aku hanya akan reset dan coba lagi.",
  str_voice_1602291_44 = "Ada permainan baru di Rec Room? ...Aku akan pergi memeriksanya nanti malam.",
  str_voice_1602291_45 = "Luangkan waktu Anda dan pilihlah hadiah yang tepat.",
  str_voice_1602291_46 = "Affinity naik. Pilihan yang bagus!",
  str_voice_1602291_47 = "Bendera terlihat...",
  str_voice_1602291_48 = "Sepertinya Anda telah menemukan strategi yang sempurna.",
  str_voice_1602291_49 = "Sebagai manusia setengah kelelawar, saya sangat tidak suka matahari, dan lengan serta kaki saya terlalu pendek untuk pekerjaan normal... Pada dasarnya, saya dilahirkan tidak berguna. Kurasa?",
  str_voice_1602291_50 = "Berkat video game, aku bertemu dengan Gronru. Aku sangat terkejut ketika dia memuji intuisi dan kecepatan reaksiku... Mungkin aku bukan hanya orang yang canggung dan bodoh?",
  str_voice_1602291_51 = "Berkat Gronru dan beberapa gamer lainnya, aku menyerah pada kehidupan NEET dan menumpahkan hatiku untuk menjalankan arcade ini. Semua pelangganku ternyata juga orang-orang yang baik.",
  str_voice_1602291_52 = "Selamat datang di Alchemy Stars.",
  str_voice_1602291_53 = "Halo?",
  str_voice_1602291_54 = "Selamat malam. *Huahh*",
  str_voice_1602291_55 = "Di mana petinya...",
  str_voice_1602291_56 = "Aku sudah bangun. Sunyi sekali.",
  str_voice_1602291_57 = "Selamat Tahun Baru! Jangan seperti saya dan menghabiskan Tahun Baru Eve bermain game... meski saya hanya menghabiskan waktu sambil menunggu kamu datang!",
  str_voice_1601533_1 = "Sinar matahari bukanlah pemandangan umum di Kota Gannon. Saya bekerja keras untuk mendorong perubahan lingkungan, menganjurkan hidup sehat, dan mendorong setiap orang untuk menantikan matahari terbit hanya dengan satu alasan... Agar kita tidak melupakan dari mana kita berasal.",
  str_voice_1601533_2 = "Saatnya latihan menari... Apa? Ini masalah etiket, jadi saya harus mempelajarinya. Memang, ini cukup menantang. Bahkan Wrath kesulitan mengimbangi saya.",
  str_voice_1601533_3 = "Hmm? Ini bukanlah pakaian yang tepat untuk perkelahian, tapi... heh, di mana ada kemauan, di situ ada jalan.",
  str_voice_1601533_10 = "Maaf membuatmu menunggu. Akhirnya aku selesai dengan agenda hari ini. Oi. Apakah kamu... tidur? Ha, nikmati kedamaian ini selama masih bisa.",
  str_voice_1601533_11 = "Baiklah, minggir... Aku yang bertanggung jawab sekarang!",
  str_voice_1601533_12 = "Ada masalah? Kamu bisa curhat padaku. Hah, keluhan yang telah aku dengar di Illumina, kamu tidak akan percaya. Dan teman, nah, mereka seharusnya berbagi perasaan mereka satu sama lain, bukan?",
  str_voice_1601533_13 = "Santai saja. Kau tak akan bisa membuat semua orang bahagia, jadi simpan kekuranganmu di belakang pikiranmu dan coba untuk membuat kemajuan besok. Lakukan dengan santai! Kau masih memiliki banyak hari esok di depanmu.",
  str_voice_1601533_14 = "Waktu berubah seperti pasang surutnya air laut, dan Illumina sedang mengarungi gelombang. Jangan khawatir, aku akan melalui badai ini dengan semua sekutuku.",
  str_voice_1601533_16 = "Meskipun siang hari, ingatlah untuk beristirahat. Pernah dengar pepatah, \"Semua kerja dan tanpa bermain membuat Navigator menjadi anak laki-laki yang membosankan\"?",
  str_voice_1601533_17 = "Selamat pagi. Ngomong-ngomong, meja ini sangat tidak nyaman. Tidak cocok untuk waktu kerja yang panjang seperti yang kamu lakukan. Saya sarankan kamu mendapatkan yang baru.",
  str_voice_1601533_18 = "Mau makan malam mewah di pesta Gannon City? Jangan mundur! Ini adalah makanan gourmet serius yang kita bicarakan.",
  str_voice_1601533_19 = "Pemandangan di sini benar-benar seperti surga. Aku bisa mengawasi malam yang panjang, menunggu fajar menyingsing.",
  str_voice_1601533_35 = "Hadapi aku!",
  str_voice_1601533_36 = "Hancurkan semua rantai!",
  str_voice_1601533_37 = "Hadapi kehancuranmu!",
  str_voice_1601533_38 = "Saya adalah penerangan Illumina!",
  str_voice_1601533_39 = "Ini fajar!",
  str_voice_1601533_40 = "Tusuk malam itu!",
  str_voice_1601533_44 = "Apa sebuah basis yang luhur. Mari kita istirahat disini, dan mandi dalam cahaya lembut langit.",
  str_voice_1601533_58 = "Kau bangun pagi! Sangat bagus. Apakah kamu pernah mempertimbangkan untuk bergabung dengan pasukan khusus Illumina?",
  str_voice_1601533_59 = "Pagi! Sudahkah kamu melihat ke luar? Matahari sedang bersinar, jadi jangan sembunyi di dalam rumah!",
  str_voice_1601533_60 = "Kamu sudah bangun? Jika kamu ingin menghadiri jamuan, sebaiknya mulai persiapan dari fajar.",
  str_voice_1601533_61 = "Apakah kamu sudah makan dengan baik? Makanan gourmet sangat sulit didapat.",
  str_voice_1601533_62 = "Ini adalah saat matahari bersinar paling terang. Aku berharap suatu hari Gannon juga bisa menikmati kemuliaannya.",
  str_voice_1601533_63 = "Orang pada umumnya tampaknya tidak suka membahas hal penting pada waktu ini, tapi aku benar-benar tidak keberatan.",
  str_voice_1601533_64 = "Menatap bintang-bintang, seseorang tidak bisa tidak terpesona oleh keindahan dunia.",
  str_voice_1601533_65 = "Istirahatlah. Jangan khawatirkan orang-orang yang peduli padamu.",
  str_voice_1601533_66 = "Saatnya jamuan makan ini berakhir. Mari kita ucapkan selamat tinggal pada malam yang tak terlupakan ini.",
  str_voice_1601533_67 = "Apakah kamu percaya bahwa suatu hari fajar akan merekah di tanah kita ini?",
  str_voice_1601533_68 = "Kita harus selalu berusaha mengejar bintang, daripada menghabiskan hidup kita terjebak di satu tempat.",
  str_voice_1601533_69 = "Untuk melangkah maju, seseorang harus terlebih dahulu membebaskan diri dari semua belenggu.",
  str_voice_1601533_70 = "Lebih sering tidak, aku menulis legenda sendiri dengan ujung tombakku.",
  str_voice_1601533_71 = "Illumina membutuhkan teman-teman–banyak dari mereka.",
  str_voice_1500424_1 = "Kau ingin tahu tentang masa laluku? Duduklah, aku punya banyak waktu. Ketika aku masih muda... bahkan aku sendiri berpikir aku adalah anak haram.",
  str_voice_1500424_2 = "Eclipsites ada di sini! Eclipsites ada di sini! Jangan cegah aku. Seseorang harus meniup terompet sesekali, atau kepuasan diri akan membunuh mereka!",
  str_voice_1500424_3 = "Pernahkah kamu mendengar tentang peluru yang diasah? Kami mengkilapkannya sampai maksimal dan memastikan mereka tetap dapat digunakan. Kami menyimpannya hanya untuk situasi paling genting...",
  str_voice_1500424_10 = "Lelah? Tidak apa-apa. Aku masih bisa berlari denganmu di punggungku. Jadi, ayo kita berangkat!",
  str_voice_1500424_11 = "Tidak bisa berfungsi tanpa pengawasan? Nah, beruntung bagi kamu, mengawasi adalah keahlian saya!",
  str_voice_1500424_12 = "Saya selalu percaya bahwa senapan lebih kuat daripada pedang. Lalu, mengapa saya menggunakan pedang? Itu cerita panjang. Katakanlah saja bahwa Petugas Pango telah menghabiskan banyak usaha untuk mengajari saya seni pedang.",
  str_voice_1500424_13 = "Mungkin bukan tempatku untuk mengatakannya, tetapi kamu harus menghargai orang-orang di sekitarmu. Jangan biarkan mereka yang telah membantumu pergi terlalu jauh. Dekatkan mereka, karena mereka adalah kawan-kawanmu.",
  str_voice_1500424_14 = "Mengapa aku memperlakukanmu secara khusus? Aku tahu seorang pahlawan ketika aku melihatnya. Aku tidak keberatan membela kamu ketika situasi menjadi sulit.",
  str_voice_1500424_16 = "Kamu pikir aku bisa mengemudikan Colossus atau apa? Oh, kamu tidak? Lalu apa yang kamu tunggu? Bawa kita ke Eclipsite sebelum kesabaranku habis!",
  str_voice_1500424_17 = "Masuk antrean, kau pemalas!",
  str_voice_1500424_18 = "Kami biasanya semua bergegas ke ruang makan pada saat ini. Jika kami mengendur seperti kamu, kami akan kelaparan.",
  str_voice_1500424_19 = "Tidur yang cukup menjamin prajurit dapat berfungsi dengan baik. Pergilah tidur. Aku akan tetap berjaga.",
  str_voice_1500424_35 = "Pedangku sudah terhunus!",
  str_voice_1500424_36 = "Tidak ada kompromi!",
  str_voice_1500424_37 = "Cangkang baja!",
  str_voice_1500424_38 = "Paduan tajam bulat!",
  str_voice_1500424_39 = "Hancurkan mereka!",
  str_voice_1500424_40 = "Tembak sesuka hati!",
  str_voice_1500424_44 = "Lelah? Ingin sedikit bersenang-senang?",
  str_voice_1500424_58 = "2nd Legion tidak pernah mundur!",
  str_voice_1500424_59 = "Mengikuti perintah adalah pekerjaanku. Sayangnya, aku tipe yang pemberontak.",
  str_voice_1500424_60 = "Terus maju! Kita tidak akan berhenti sampai semua Eclipsite dimusnahkan!",
  str_voice_1500424_61 = "Ayo lakukan simulasi militer.",
  str_voice_1500424_62 = "Remaja perempuan semua adalah monster.",
  str_voice_1500424_63 = "Tunjukkan pada mereka apa yang telah kamu buat!",
  str_voice_1500424_64 = "Tertidur secara tidak sengaja. Untungnya tidak ada yang melihatku.",
  str_voice_1500424_65 = "Aku bisa lebih cepat. Barton, kamu bisa melakukannya!",
  str_voice_1500424_66 = "Ah, menarik.",
  str_voice_1500424_67 = "Aku tidak mengira pria tua itu bisa fotogenik.",
  str_voice_1500424_68 = "Ikuti saya dan tunjukkan kepada mereka bagaimana cara Illuminans melakukannya!",
  str_voice_1500424_69 = "Sial, kamu yang mendapatkan sorotan kali ini...",
  str_voice_1500424_70 = "Reinhardt telah berubah. Mereka semua telah berubah... Ini telah menjadi terlalu rumit untuk ku pahami...",
  str_voice_1500424_71 = "Ini tidak ada apa-apanya. Aku bahkan belum menggunakan peluru tajam itu! Aku tidak bisa menyetujuinya...",
  str_voice_1601553_1 = "Kau ingin tahu tentang masa laluku? Duduklah, aku punya banyak waktu. Ketika aku masih muda... bahkan aku sendiri berpikir aku adalah anak haram.",
  str_voice_1601553_2 = "Eclipsites ada di sini! Eclipsites ada di sini! Jangan cegah aku. Seseorang harus meniup terompet sesekali, atau kepuasan diri akan membunuh mereka!",
  str_voice_1601553_3 = "Pernahkah kamu mendengar tentang peluru yang diasah? Kami mengkilapkannya sampai maksimal dan memastikan mereka tetap dapat digunakan. Kami menyimpannya hanya untuk situasi paling genting...",
  str_voice_1601553_10 = "Lelah? Tidak apa-apa. Aku masih bisa berlari denganmu di punggungku. Jadi, ayo kita berangkat!",
  str_voice_1601553_11 = "Tidak bisa berfungsi tanpa pengawasan? Nah, beruntung bagi kamu, mengawasi adalah keahlian saya!",
  str_voice_1601553_12 = "Saya selalu percaya bahwa senapan lebih kuat daripada pedang. Lalu, mengapa saya menggunakan pedang? Itu cerita panjang. Katakanlah saja bahwa Petugas Pango telah menghabiskan banyak usaha untuk mengajari saya seni pedang.",
  str_voice_1601553_13 = "Mungkin bukan tempatku untuk mengatakannya, tetapi kamu harus menghargai orang-orang di sekitarmu. Jangan biarkan mereka yang telah membantumu pergi terlalu jauh. Dekatkan mereka, karena mereka adalah kawan-kawanmu.",
  str_voice_1601553_14 = "Mengapa aku memperlakukanmu secara khusus? Aku tahu seorang pahlawan ketika aku melihatnya. Aku tidak keberatan membela kamu ketika situasi menjadi sulit.",
  str_voice_1601553_16 = "Kamu pikir aku bisa mengemudikan Colossus atau apa? Oh, kamu tidak? Lalu apa yang kamu tunggu? Bawa kita ke Eclipsite sebelum kesabaranku habis!",
  str_voice_1601553_17 = "Masuk antrean, kau pemalas!",
  str_voice_1601553_18 = "Kami biasanya semua bergegas ke ruang makan pada saat ini. Jika kami mengendur seperti kamu, kami akan kelaparan.",
  str_voice_1601553_19 = "Tidur yang cukup menjamin prajurit dapat berfungsi dengan baik. Pergilah tidur. Aku akan tetap berjaga.",
  str_voice_1601553_35 = "Pedangku sudah terhunus!",
  str_voice_1601553_36 = "Tidak ada kompromi!",
  str_voice_1601553_37 = "Cangkang baja!",
  str_voice_1601553_38 = "Paduan tajam bulat!",
  str_voice_1601553_39 = "Hancurkan mereka!",
  str_voice_1601553_40 = "Tembak sesuka hati!",
  str_voice_1601553_44 = "Lelah? Ingin sedikit bersenang-senang?",
  str_voice_1601553_58 = "2nd Legion tidak pernah mundur!",
  str_voice_1601553_59 = "Mengikuti perintah adalah pekerjaanku. Sayangnya, aku tipe yang pemberontak.",
  str_voice_1601553_60 = "Terus maju! Kita tidak akan berhenti sampai semua Eclipsite dimusnahkan!",
  str_voice_1601553_61 = "Ayo lakukan simulasi militer.",
  str_voice_1601553_62 = "Remaja perempuan semua adalah monster.",
  str_voice_1601553_63 = "Tunjukkan pada mereka apa yang telah kamu buat!",
  str_voice_1601553_64 = "Tertidur secara tidak sengaja. Untungnya tidak ada yang melihatku.",
  str_voice_1601553_65 = "Aku bisa lebih cepat. Barton, kamu bisa melakukannya!",
  str_voice_1601553_66 = "Ah, menarik.",
  str_voice_1601553_67 = "Aku tidak mengira pria tua itu bisa fotogenik.",
  str_voice_1601553_68 = "Ikuti saya dan tunjukkan kepada mereka bagaimana cara Illuminans melakukannya!",
  str_voice_1601553_69 = "Sial, kamu yang mendapatkan sorotan kali ini...",
  str_voice_1601553_70 = "Reinhardt telah berubah. Mereka semua telah berubah... Ini telah menjadi terlalu rumit untuk ku pahami...",
  str_voice_1601553_71 = "Ini tidak ada apa-apanya. Aku bahkan belum menggunakan peluru tajam itu! Aku tidak bisa menyetujuinya...",
  str_voice_1602301_1 = "Sari kehidupan ini melengkapi kehidupan. Ia memberikan tidur tanpa mimpi kepada para peminumnya dan menghentikan mereka yang menderita dari meratapi diri sendiri. Apakah kamu ingin mencobanya?",
  str_voice_1602301_2 = "Tidaklah menyenangkan berdiri dalam bayangan sambil menyaksikan Aurorian dan Eclipsite saling membunuh, tetapi terkadang itulah pelajaran dari Kebenaran. Kenapa, kau merindukannya?",
  str_voice_1602301_3 = "Orang-orang yang tidak mengerti saya cenderung mengklaim kata-kata saya mendalam, atau bahkan meragukan. Mereka menghindari saya, namun mengawasi saya... Saya yakin kamu tahu bagaimana rasanya.",
  str_voice_1602301_4 = "Pernahkah kamu mendengar frasa, \"Tubuh adalah penjara jiwa Aurorian\"? ...Hehe. Raut wajahmu mengatakan semuanya.",
  str_voice_1602301_5 = "Beberapa orang percaya bahwa melampaui diri sendiri untuk mendapatkan kekuatan yang lebih besar dari dunia, tetapi \"diri\" seseorang tidak begitu mudah untuk dilampaui, dan meninggalkan diri sendiri menyimpang dari apa yang ditetapkan oleh Truth.",
  str_voice_1602301_6 = "Kebencian dan perang hanyalah langkah ekstrem bagi orang rendah untuk mendapatkan kekuasaan. Mereka tidak tahu di mana Tuhan Kebenaran berada.",
  str_voice_1602301_7 = "Apakah Anda akan mengeluh tentang nasib ketika Anda dalam suasana hati yang sangat buruk? Mengapa tidak mengubah pola pikir Anda untuk percaya bahwa itu adalah takdir? Lalu ungkaplah kebenaran di baliknya dengan sukacita?",
  str_voice_1602301_8 = "Seringkali saya jelaskan kepada mereka bahwa mengembangkan persepsi bukanlah untuk memahami dunia, karena Truth menembus terlalu banyak dimensi. Kebenaran yang diperoleh dari pemahaman dunia bukanlah Truth.",
  str_voice_1602301_9 = "Kebenaran tertinggi tersembunyi dalam kedalaman emosi yang ekstrem. Aurorian yang dekat dengan Anda telah menunjukkan Kebenaran mereka. Saya menantikan perjalanan bersama Anda dengan penuh semangat.",
  str_voice_1602301_10 = "Kamu telah menatap. Apakah kamu tidak terbiasa melihatku seperti ini? Meskipun kamu membelakangiku, aku akan menganggap ekspresimu sebagai pujian.",
  str_voice_1602301_11 = "Meski Nation of Truth pernah mengalami keruntuhan sebelumnya, Dia tetap Dia. Dia ada di dalam setiap makhluk hidup untuk menunjukkan Truth. Meski Dia menemukan tempat kedatangan, Dia mengubah pikirannya ketika kamu lahir.",
  str_voice_1602301_12 = "Satu-satunya jalan untuk mendekati Truth adalah melalui pengetahuan. Ini membutuhkan individu untuk mengintegrasikan informasi yang diperoleh dengan pencerahan batin. Entitas yang berbeda mendapatkan pengetahuan yang berbeda, sehingga Truth mengadaptasi bentuk yang berbeda.",
  str_voice_1602301_13 = "Ada dunia di setiap Aurorian. Setiap orang sedang berada di dunia mereka sendiri saat ini, dan Tuhan Kebenaran berdiri di antara mereka, menguasai seluruh tanah.",
  str_voice_1602301_14 = "Tidur nyenyak sejati bukanlah milik mereka yang telah pergi, karena di Negara Kebenaran, bahkan kematian itu sendiri akan menghilang. Aku telah memandang semua dan menjadi acuh terhadap sifat fana dari kehidupan individu.",
  str_voice_1602301_15 = "Usia adalah peringatan yang paling tidak berharga. Tapi jika kamu mau, aku dengan tulus mengucapkan selamat ulang tahun untukmu.",
  str_voice_1602301_16 = "Apakah kamu membutuhkan bantuan saya? Hanya dengan harga yang kecil... Ah, ekspresimu selalu menarik seperti biasanya.",
  str_voice_1602301_17 = "Payung? Tidak, saya tidak membutuhkannya. Rambut dan kulit saya hanya bersinar lebih terang di bawah sinar matahari.",
  str_voice_1602301_18 = "Bulan malam ini cukup cantik, tetapi masih kalah dibandingkan dengan bulan darah di Varaki Town.",
  str_voice_1602301_19 = "Kitab Suci telah meramalkan kedatanganmu, hanya saja jauh lebih kemudian.",
  str_voice_1602301_20 = "Tuhan dari Truth telah datang untuk menjadi saksi atas Truth, dan semua orang yang berpegang pada Truth akan menyaksikan mukjizat.",
  str_voice_1602301_21 = "Menindas para penganut, namun pada saat yang sama ingin belajar tentang Truth dari mereka adalah lelucon terbesar bagi Truth.",
  str_voice_1602301_22 = "Semoga Truth memberkatimu.",
  str_voice_1602301_23 = "Eclipsite bukanlah murni jahat, sama seperti Aurorian bukanlah murni kebaikan. Mereka menjadi tersesat karena mereka tidak memiliki petunjuk dari Tuhan Kebenaran.",
  str_voice_1602301_24 = "Dengar, bertahan, rasakan cinta dan benci terhadap dunia, kemudian hancurkan masa lalu dan bangun kembali diri sendiri... Itulah bagaimana dia semakin dekat dengan Kebenaran, saya percaya.",
  str_voice_1602301_25 = "Setelah melihat kekuatan Nails, aku tahu dia memiliki potensi untuk menjadi seorang rasul. Sekarang, waktunya telah tiba.",
  str_voice_1602301_26 = "Hobi saya? Mengapa kamu tidak menggunakan kekuatanmu untuk menjalin kedekatan yang lebih baik dengan saya?",
  str_voice_1602301_27 = "Penindasan, kehidupan abadi, mengomel dan menggerutu... Seperti yang bisa kamu lihat, bukan aku sekarang ini yang mempertanyakan atau membenci mereka.",
  str_voice_1602301_28 = "Mengenai apakah Dia berada di Colossus... Jawabanku di masa lalu akan negatif.",
  str_voice_1602301_29 = "Karena kamu datang ke sini atas keinginanmu sendiri, naiklah ke Truth. Kemana ia akan pergi, itu terserah padaku. Bagi seseorang yang sering mencari Truth, kamu pasti penasaran tentangku, bukan?",
  str_voice_1602301_30 = "Apa kekuatan yang misterius namun luar biasa.",
  str_voice_1602301_31 = "Aku akan melampaui hidup dan mati!",
  str_voice_1602301_32 = "Aku akan melampaui waktu dan ruang!",
  str_voice_1602301_33 = "Keabadian ada di sini!",
  str_voice_1602301_34 = "Apakah kamu ingin melihat sesuatu yang berbeda?",
  str_voice_1602301_35 = "Ucapkan mantra-mantra bersamaku.",
  str_voice_1602301_36 = "Ini adalah apa yang telah ditanamkan dalam darahku.",
  str_voice_1602301_37 = "Calamity telah dirilis!",
  str_voice_1602301_38 = "Bangkitlah, roh darah!",
  str_voice_1602301_39 = "Dengarlah Truth!",
  str_voice_1602301_40 = "Akulah Truth!",
  str_voice_1602301_41 = "Menunggu kedatangan Tuhan.",
  str_voice_1602301_42 = "Apakah saya mengejutkan Anda?",
  str_voice_1602301_43 = "Ukir Kebenaran di tubuhku.",
  str_voice_1602301_44 = "Ya, kita akan mengadakan kongregasi untuk True Order di sini.",
  str_voice_1602301_45 = "Apakah kamu ingin mendengar Kebenaran bersamaku?",
  str_voice_1602301_46 = "Dia memiliki banyak pengikut, tetapi hanya satu di antaranya yang merupakan seorang Caelestite...",
  str_voice_1602301_47 = "Jangan bergerak... Dengar itu? Itu di dalam.",
  str_voice_1602301_48 = "Dibandingkan dengan buku tebal kuno dari asal yang tidak diketahui, saya lebih menyukai hadiahmu.",
  str_voice_1602301_49 = "Saya bisa mengerti mengapa para patriark menghindari garis keturunan Varaki, serta keinginan orang tua saya untuk mengakhiri hidup mereka. Itulah mengapa saya acuh tak acuh terhadap segala sesuatu di sekitar saya ketika saya mengalami kenaikan.",
  str_voice_1602301_50 = "Itu benar, saya melarikan diri dari kota bulan darah itu, bukan karena saya memiliki kekuatan untuk bergerak di siang hari, tetapi karena saya ingin mengalami sesuatu yang berbeda.",
  str_voice_1602301_51 = "Dahulu kala, aku mendengar wahyu dari Tuhan Kebenaran di makam leluhurku, dengan banyak omongan gila mereka juga menghancurkan pikiranku. Rasa sakit adalah insidental, tetapi mendekati Kebenaran adalah esensial.",
  str_voice_1602301_52 = "Alchemy Stars.",
  str_voice_1602301_53 = "Yah, mereka benar.",
  str_voice_1602301_54 = "Hari berlalu sebelum kamu menyadarinya...",
  str_voice_1602301_55 = "Waktu untuk membaca.",
  str_voice_1602301_56 = "Masuk sekarang?",
  str_voice_1602301_57 = "True Order menunggu kunjunganmu di tahun baru.",
  str_voice_1502321_1 = "Mentorku pernah bertanya apa yang telah aku sesali selama bertahun-tahun ini. Aku menjawab: \"Semua—Lahir. Eksis. Berbicara. Berpikir...\" Ini adalah pertama kalinya seseorang mendengarkan aku dalam waktu lama tanpa pergi.",
  str_voice_1502321_2 = "Aku tidak berani berharap akan penebusan... tetapi ketika Darah Langka mengental dan membentuk, dan murid-murid memuji kesucianku, aku sempat berpikir tentang \"keselamatan.\"",
  str_voice_1502321_3 = "\"Dimana kamu kalah, disini kamu menang. Dimana kamu bertobat, disini kamu diberkati.\" Dengan kata lain... Aku tidak melakukan apa-apa yang menjijikkan dan membosankan, dan aku bukan monster yang terlupakan...",
  str_voice_1502321_4 = "Rasa sakit yang aku lihat bukanlah nyata, karena ketika luka sembuh, aku masih terjebak dalam suasana kehilangan. Tapi jangan khawatir tentangku, aku kadang-kadang bahagia sekarang.",
  str_voice_1502321_5 = "Apakah kamu maksud \"Nails of Piety\"? Oh... Itu pasti berbeda. Lebih tajam, lebih elegan, dan aku bisa mengaku di lebih banyak kesempatan. Bagaimana kalau... Hah? Kamu maksud bersama-sama?",
  str_voice_1502321_6 = "Tepat ketika aku hampir kehabisan darah, aku menjadi hipotermia sejenak... Aku bilang pada diriku sendiri bahwa aku akhirnya tenggelam dalam tidur yang telah lama aku rindukan, tetapi mentorku menyelimutiku dengan kekudusannya...",
  str_voice_1502321_7 = "Murid-murid di sana mengatakan bahwa Tuhan Kebenaran adalah dewa yang menaburkan malam dan membuat semua rasa sakit hilang di siang hari. Saya mencoba memikirkannya seperti ini, seperti sebuah pengakuan...",
  str_voice_1502321_8 = "Setelah bergabung dengan True Order, aku cepat menemukan alasan untuk rasa sakit dan rasa bersalahku. Tapi akar dari pengakuan adalah rasa jijik... dan akar dari rasa jijik... kamu tidak ingin tahu...",
  str_voice_1502321_9 = "Rare Blood dingin dan menusuk, tetapi Sacred Blood seperti api pembakaran kehidupan baru. Ia membakarku, membimbingku, membiarkanku menyelamatkan orang lain seiring aku menyelamatkan diriku sendiri.",
  str_voice_1502321_10 = "Oh... Aku begitu terpesona dengan pakaian ini sampai-sampai aku lupa kamu ada di sana, maaf. Jadi, silakan mulai pengakuanmu. Aku akan mendengarkan dengan saksama.",
  str_voice_1502321_11 = "Aku tahu hari itu akan datang ketika aku menceritakan masa lalu penuh dosaku padamu. Nah, aku akan menatapmu langsung. Aku siap...",
  str_voice_1502321_12 = "Oh... Ini adalah luka-luka yang dibalut oleh murid-murid baik itu untukku. Mereka tidak menolakku, tapi berterima kasih atas pelayananku... Ya! Aku akan dengan senang hati menyesuaikannya!",
  str_voice_1502321_13 = "Saya tidak bersalah di mata The Truth! Ah... Meskipun dengan usaha terbaik saya, kamu masih bisa mendengar saya menyalahkan diri sendiri, bukan?",
  str_voice_1502321_14 = "Apa yang harus aku akui? Waktumu yang terbuang? Uangmu yang terbuang? Maaf. Aku seharusnya tidak mengatakan terlalu banyak...",
  str_voice_1502321_15 = "Memberkatimu. Aku berharap bisa mengaku bersamamu setiap tahun... tidak, setiap hari!",
  str_voice_1502321_16 = "Bisakah kamu membantu memeriksa apakah luka di punggungku sudah sembuh? Saya secara tidak sengaja terlalu dalam terakhir kali...",
  str_voice_1502321_17 = "Ini masih pagi... kamu murid Truth yang lebih taat daripada aku.",
  str_voice_1502321_18 = "Sekarang? Tentu saja. Menunjukkan luka seseorang kepada mereka yang mencari Kebenaran adalah apa yang seharusnya dilakukan oleh orang suci.",
  str_voice_1502321_19 = "Apakah tidur juga menghindarimu karena dosa-dosa di hatimu? Untungnya, aku memiliki banyak hal untuk aku akui padamu...",
  str_voice_1502321_20 = "Mereka tidak merasa kasihan atau menolakku, tetapi malah menantikan kedatangan Lord of Truth kepadaku.",
  str_voice_1502321_21 = "Bagaimanapun, aku tidak lagi berada di sana. Itu bukanlah cara seorang suci seharusnya berperilaku. Ini adalah kata-kata terakhirku untuk mereka...",
  str_voice_1502321_22 = "Semoga Truth memberkatimu!",
  str_voice_1502321_23 = "Apakah Eclipsite kadang-kadang juga merasakan sakit?",
  str_voice_1502321_24 = "Hanya karena Lady Victoria menerima dan membimbingku sehingga aku berhak menjadi seorang santa dari tuhan.",
  str_voice_1502321_25 = "Dia membaca diriku... mencari akar dosa dalam kata-kata pengakuanku... guruku dari Truth, mentor hidupku!",
  str_voice_1502321_26 = "Saat aku sekarat, aku mendengar suara Tuhan... meski itu hanya ilusi, aku akan mencarinya lagi.",
  str_voice_1502321_27 = "Baru-baru ini saja aku menyadari bahwa aku membenci diriku sendiri. Ah... terima kasih. Suatu hari nanti aku akan bisa menerima diriku sendiri.",
  str_voice_1502321_28 = "Maafkan saya, tetapi apakah tempat pengakuan dosa belum siap?",
  str_voice_1502321_29 = "Banyak orang telah melihat perubahan dalam diriku, tetapi kamu yang pertama bertanya apa yang telah aku alami... Pakaian suci ini adalah bukti pelukan Lord of Truth.",
  str_voice_1502321_30 = "Tuanku, maafkan aku sekali lagi...",
  str_voice_1502321_31 = "Apa yang kurang...?",
  str_voice_1502321_32 = "Aku akan selalu berterima kasih...",
  str_voice_1502321_33 = "Tuanku bilang aku tidak bersalah!",
  str_voice_1502321_34 = "Aku harus tidak mengotori pakaianku...",
  str_voice_1502321_35 = "Darah Suci itu akan segera mengental dan membentuk...",
  str_voice_1502321_36 = "Ini bukan kekuatanku...",
  str_voice_1502321_37 = "Aku akan bertanggung jawab untuk orang-orang berdosa!",
  str_voice_1502321_38 = "Akan kudengarkan pengakuan para korban!",
  str_voice_1502321_39 = "Tanpa rasa sakit...!",
  str_voice_1502321_40 = "Ada banyak lagi...!",
  str_voice_1502321_41 = "Aku akan menderita untukmu...",
  str_voice_1502321_42 = "Tuhan sekali lagi menghapus dosa-dosaku.",
  str_voice_1502321_43 = "Aku tidak layak disebut sebagai orang suci...",
  str_voice_1502321_44 = "Aku tidak lagi kotor... benar?",
  str_voice_1502321_45 = "Akan kuterima atas nama Lord...",
  str_voice_1502321_46 = "Bisakah aku benar-benar mengambilnya untuk diriku sendiri...?",
  str_voice_1502321_47 = "Kamu lebih pantas mendapatkannya daripada saya.",
  str_voice_1502321_48 = "Seharusnya aku memberi diriku beberapa penghargaan...",
  str_voice_1502321_49 = "Pengalaman itu membuatku menyadari bahwa sangat dangkal hanya mempertimbangkan rasa sakitku sendiri. Darah yang tercemar tidak akan hilang hanya karena aku mengaku, aku harus melakukan sesuatu dengannya...",
  str_voice_1502321_50 = "Terkadang aku merasa senang bisa hidup, tapi hanya sesekali... Tapi ketika aku memikirkan saudaraku yang memegang pedang pewaris dengan ekspresi kosong itu, aku hanya...",
  str_voice_1502321_51 = "Yang aku tahu hanyalah bahwa True Order adalah tempat bagi orang-orang aneh dan buangan... Tapi kemudian aku menemukan bahwa hanya orang-orang aneh inilah yang membawa alasan ke dunia luar.",
  str_voice_1502321_52 = "Alchemy Stars.",
  str_voice_1502321_53 = "Jika memungkinkan...",
  str_voice_1502321_54 = "Hari baru pengakuan dimulai.",
  str_voice_1502321_55 = "Aku punya hal lain untuk dikatakan.",
  str_voice_1502321_56 = "Apa kau sudah muak denganku...?",
  str_voice_1502321_57 = "Terima kasih tidak merasa lelah dengan saya selama setahun terakhir.",
  str_voice_1602311_1 = "PlayerName, simpan kepala semangka itu untuk dirimu sendiri, dan jangan pernah mencoba masuk ke kepala saya sambil berpura-pura menjadi Tuhan Kebenaran. Kamu tidak bisa menipu saya sekarang.",
  str_voice_1602311_2 = "Kamu teman dari Victoria? Jika begitu, saya tidak keberatan kamu memanggil saya \"Paman.\"",
  str_voice_1602311_3 = "Kamu yakin ini cara yang kamu inginkan? Maaf, tapi bagi saya, mengucapkan kata-kata tanpa berpikir adalah cara orang-orang barbar yang tidak beradab.",
  str_voice_1602311_4 = "Jalur menuju Kebenaran jauh lebih sederhana daripada yang kamu pikirkan, PlayerName. Kamu hanya perlu percaya pada kekuatan keyakinanmu.",
  str_voice_1602311_5 = "Setiap jiwa di dunia ini sangat diberkati oleh The Truth. Dengan menawarkan iman kita yang tak tergoyahkan kepada Tuhan dari Truth, kita bisa terhindar dari siksaan abadi.",
  str_voice_1602311_6 = "Suatu hari, kamu juga akan berbaring di sungai itu. Kemudian Kebenaran, seperti bintang yang paling terang di malam hari, akan menembusmu, merobekmu, membakarmu, membangunmu kembali... sampai kamu bukan lagi kamu dan menjadi kamu lagi.",
  str_voice_1602311_7 = "Saya sudah berkali-kali mengatakan kepada Nails untuk tidak mengumumkan saya sebagai mentornya. Lihat, sekarang kamu juga di sini... Hah? Kamu tidak mau saya menjadi mentormu? Kenapa, kamu pikir saya tidak cukup baik?",
  str_voice_1602311_8 = "Setiap orang memiliki jalannya sendiri menuju pencerahan, dan saya tidak pernah mengganggu. Tapi saya tidak ingin melihat kamu menyimpang terlalu jauh dari jalur itu. Kamu seharusnya cukup pintar untuk tahu apa yang saya maksud.",
  str_voice_1602311_9 = "Saya telah menyelesaikan tujuan saya sebagai anggota keluarga Varaki. Sekarang, gunakan kepalamu dan pikirkan siapa orang malang yang bisa saya bantu?",
  str_voice_1602311_10 = "Apakah kamu benar-benar sependiam kelinci? Itu sebenarnya menarik rasa penasaranku sekarang... Jadi, kamu tidak memiliki pertanyaan tentang Kebenaran dan realitas dunia untukku?",
  str_voice_1602311_11 = "Baiklah, aku melihat kamu sudah menyiapkan kamar kosong untukku. Jangan khawatir, aku tidak akan mengeluh karena merasa sempit.",
  str_voice_1602311_12 = "Tidak seperti kamu, aku tidak menyambut terlalu banyak orang di bentengku, tetapi jika kamu datang sendirian, aku akan mempertimbangkan dan setidaknya menyediakan peti mati yang layak untukmu.",
  str_voice_1602311_13 = "Truth ada di mana-mana. Di lumpur setelah badai, di halaman buku yang menguning, di dalam diri kamu dan saya... semua mengandung jejak Truth.",
  str_voice_1602311_14 = "Menghabiskan segalanya dan membunuh semua orang, namun tidak pernah bisa ditangkap. Apakah kamu tahu siapa \"buronan\" itu? Sangat sedikit yang bisa menjawab dengan benar, tetapi mungkin kamu adalah pengecualian...",
  str_voice_1602311_15 = "Saya percaya hari ini adalah hari ulang tahun seseorang. Tolong sampaikan kepada orang tersebut—Selamat Ulang Tahun.",
  str_voice_1602311_16 = "Saya memiliki alasan untuk percaya bahwa bahkan \"Lord of Truth\" akan bingung dengan ini... Apa sebenarnya yang sedang kamu lakukan hingga membuatmu sibuk seperti itu?",
  str_voice_1602311_17 = "Seseorang tampaknya belum pernah melihat sarapan yang lezat sebelumnya, aku lihat. Jangan hanya duduk di sana, kecuali jika kamu lebih suka supmu dingin.",
  str_voice_1602311_18 = "Akhirnya kamu memutuskan untuk menunjukkan dirimu? Yah, masih belum terlambat. Hari baru saja mulai terbuka.",
  str_voice_1602311_19 = "Apa yang salah? Tarik nafas dalam-dalam, kamu tidak masuk akal sekarang. Jadi, apakah kamu mencoba memberi tahu saya bahwa seseorang telah menjahilimu dalam mimpi kamu?",
  str_voice_1602311_20 = "True Order saat ini telah dengan tegas memulai perjalanan yang diberkati oleh The Truth.",
  str_voice_1602311_21 = "Domba sesat yang mengikuti tuhan palsu itu seharusnya hidup dalam kehidupan yang jauh lebih tidak diinginkan sekarang jika mereka tidak mengambil alih kota terapung itu.",
  str_voice_1602311_22 = "Semoga Truth memberkatimu.",
  str_voice_1602311_23 = "Bagaimana mungkin musuh dari Kebenaran bisa menjadi temanku?",
  str_voice_1602311_24 = "Saya bertanya-tanya apakah Victoria masih membenci saya seperti sebelumnya? Tidak, jangan masukkan hidungmu di mana-mana, PlayerName.",
  str_voice_1602311_25 = "Charon dan ayahnya memiliki hubungan yang tegang? Yah, itu sama sekali bukan berita baru.",
  str_voice_1602311_26 = "Maafkan aku, tapi aku lebih suka sendirian. Namun, jika kamu diam seperti kelinci, aku tidak keberatan berbagi ruangan denganmu.",
  str_voice_1602311_27 = "Di mana saja dengan kerumunan yang bising pasti penuh dengan penipuan, pengkhianatan, dan pertarungan... Berjanjilah padaku kamu tidak akan mendekati tempat seperti itu.",
  str_voice_1602311_28 = "Kamu sangat beruntung memiliki kastil yang bergerak. Juga jelas bahwa kamu telah berusaha keras untuk penampilannya.",
  str_voice_1602311_29 = "Selain membimbingmu tentang cara melawan godaan dan bisikan dosa dalam hidupmu, tidak ada yang bisa aku bantu. Tapi kamu masih mau mendekatiku meskipun faktanya begitu, aku lihat.",
  str_voice_1602311_30 = "Oh, Tuanku...",
  str_voice_1602311_31 = "Pencerahan adalah proses yang abadi.",
  str_voice_1602311_32 = "Bimbingan semakin jelas.",
  str_voice_1602311_33 = "Seolah-olah aku kembali ke sungai...",
  str_voice_1602311_34 = "Sini, biar kuperiksa.",
  str_voice_1602311_35 = "Pedang siap.",
  str_voice_1602311_36 = "Apakah kamu suka menunggu?",
  str_voice_1602311_37 = "Cahaya bulan darah!",
  str_voice_1602311_38 = "Biarkan mawar itu mekar!",
  str_voice_1602311_39 = "Mengalir...",
  str_voice_1602311_40 = "Tidur…",
  str_voice_1602311_41 = "Aku akan baik-baik saja.",
  str_voice_1602311_42 = "Seperti yang saya katakan, itu akan baik-baik saja.",
  str_voice_1602311_43 = "Cepat, ke belakangku!",
  str_voice_1602311_44 = "Apakah ini tempat kamu hidup dalam pengasingan selama tujuh belas tahun?",
  str_voice_1602311_45 = "Tidak heran semua orang ingin datang.",
  str_voice_1602311_46 = "Ini istimewa, bukan?",
  str_voice_1602311_47 = "Kamu pandai dalam menyenangkan orang.",
  str_voice_1602311_48 = "Kamu bisa menantikan apa yang mungkin kamu terima sebagai balasan.",
  str_voice_1602311_49 = "Varakis memiliki sejarah yang jauh lebih panjang daripada yang kamu pikirkan. Jika kamu tertarik, aku bisa menceritakan kehidupan setiap leluhur kepada kamu... Itu jika kamu tertarik.",
  str_voice_1602311_50 = "Saat itu, aku pikir aku sedang mengikuti The Truth, tapi bagi orang lain, aku hanya mengkhianati saudara-saudaraku.",
  str_voice_1602311_51 = "Aku mengunci diri di benteng di tepi jurang, hanya untuk menemukan kepuasan dan ketenangan yang tak terduga.",
  str_voice_1602311_52 = "Alchemy Stars.",
  str_voice_1602311_53 = "Ada orang yang mencariku?",
  str_voice_1602311_54 = "Mulai menjadi berisik.",
  str_voice_1602311_55 = "Sebuah sore yang malas...",
  str_voice_1602311_56 = "Mari kita lihat siapa yang sudah tidur siang?",
  str_voice_1602311_57 = "Setiap orang dapat menyambut tahun baru, sama seperti setiap orang dapat menyambut sungai dari The Truth.",
  str_voice_1602331_1 = "Terima kasih telah mengajak saya naik Colossus! Ini adalah pertama kalinya saya melihat kapal udara seperti ini; rasanya sangat petualangan!",
  str_voice_1602331_2 = "Apakah ada yang bisa saya lakukan untuk membantu Anda? Alkimia saya sangat sempurna untuk mengubah bahan-bahan biasa menjadi barang-barang yang berguna!",
  str_voice_1602331_3 = "Apakah kamu menerima permintaan pekerjaan yang menarik atau apa? Setiap orang tampak begitu bersemangat!",
  str_voice_1602331_4 = "Firefly sangat lucu! Kalau saja aku bisa menggunakan alkimia untuk menciptakan pembantu kecil yang imut seperti itu!",
  str_voice_1602331_5 = "Astra memiliki berbagai jenis material yang berguna! Saya tidak sabar untuk mengeksplorasi mereka untuk penelitian saya!",
  str_voice_1602331_6 = "Vice mengatakan \"alchemy\" adalah istilah kuno di dunia Anda, digunakan untuk menggambarkan praktik mistis yang luar biasa... Saya juga berharap untuk mempelajari lebih banyak pengetahuan dan teknik alkimia di masa depan.",
  str_voice_1602331_7 = "Apa kamu tahu cara memancing? Apa itu? Kamu benar-benar suka memancing?! Bagus, aku akan membuatkan kita sepasang joran pancing!",
  str_voice_1602331_8 = "Ceritakan tentang petualangan lainnya! Saya sangat ingin mendengar lebih banyak tentang mereka!",
  str_voice_1602331_9 = "Terima kasih, Navigator, atas semua bantuanmu selama kami berada di pulau dan di Colossus-mu... aku dan teman-temanku telah mengalami musim panas yang tak terlupakan!",
  str_voice_1602331_10 = "Tong!",
  str_voice_1602331_11 = "Heehee, selamat datang di Atelier kelas dunia milikku! Meskipun ini hanya pengaturan sementara, aku sudah membuat banyak barang berguna untuk kita. Lihat apakah ada yang bisa kamu gunakan!",
  str_voice_1602331_12 = "Saya baru saja bertukar bahan dengan beberapa teman Anda dari Rediesel Wrench. Mereka membawa berbagai macam barang yang tak terduga, seperti kadal kering dan bahkan kaktus!",
  str_voice_1602331_13 = "Tempat yang ingin saya kunjungi? Nah, jika saya punya kesempatan... Saya ingin melihat Lumopolis! Northland juga terdengar seperti pilihan yang bagus... Ahh, saya tidak bisa memutuskan!",
  str_voice_1602331_14 = "Banyak orang di dunia ini juga suka menjelajahi reruntuhan! Vice menceritakan tentang beberapa penjelajahannya sebelumnya; Saya merasa seperti kita bisa berbagi cerita selama berjam-jam!",
  str_voice_1602331_15 = "Selamat ulang tahun! Mengesankan, bukan? Teman-teman dan aku menyiapkan ini hanya untukmu, dan aku menggunakan alkimia untuk membuat semua barang yang diperlukan!",
  str_voice_1602331_16 = "Aku ingin meneliti material ini... Tapi di mana aku bisa menemukannya?",
  str_voice_1602331_17 = "Selamat pagi! Saya bersemangat dan siap untuk pergi kapan saja!",
  str_voice_1602331_18 = "Makan malamnya lezat, dan saya juga mendengar berbagai jenis cerita!",
  str_voice_1602331_19 = "Fiuh... Terima kasih telah membantu saya mengeksplorasi materi! Selamat malam...",
  str_voice_1602331_20 = "Petualangan musim panas baru lainnya untuk kehidupan biasa saya!",
  str_voice_1602331_21 = "Sudah diputuskan! Selanjutnya dalam daftarku adalah melihat aurora di Northland.",
  str_voice_1602331_22 = "Dalam bentuk termudahnya, alkimia adalah penjelajahan dan sintesis dari berbagai material!",
  str_voice_1602331_23 = "Tidak ada musuh yang terlalu berbahaya untuk menghentikan petualangan kita!",
  str_voice_1602331_24 = "Permainan seruling Klaudia luar biasa; kita harus membiarkannya menjadi tuan rumah konser lagi suatu hari nanti!",
  str_voice_1602331_25 = "Saya bertanya-tanya bagaimana keadaan Patty? Saya ingin memperkenalkannya kepada beberapa teman baru!",
  str_voice_1602331_26 = "Sebagai seorang alkemis, keinginan terbesarku adalah untuk memperoleh lebih banyak pengetahuan dan teknik!",
  str_voice_1602331_27 = "Jika ada orang yang memperlakukanmu dengan buruk, tidak ada salahnya untuk melawan!",
  str_voice_1602331_28 = "Terbang melintasi dunia di atas pesawat raksasa... Ini seperti dalam mimpi!",
  str_voice_1602331_29 = "Namaku Reisalin Stout, atau Ryza untuk singkatnya! Aku seorang alkemis pengembara, dan minatku termasuk mengunjungi dunia yang berbeda, menjelajahi reruntuhan, petualangan musim panas, dan terbang di atas Colossus ini!",
  str_voice_1602331_30 = "Aku masih bisa menjadi lebih kuat!",
  str_voice_1602331_31 = "Eksplorasi selesai!",
  str_voice_1602331_32 = "Sintesis berhasil!",
  str_voice_1602331_33 = "Baiklah, sudah selesai!",
  str_voice_1602331_34 = "Ambil langkah pertama dan pergi!",
  str_voice_1602331_35 = "Saatnya untuk serius!",
  str_voice_1602331_36 = "Berangkat!",
  str_voice_1602331_37 = "Ini adalah gerakan pamungkas saya!",
  str_voice_1602331_38 = "Kemenangan adalah milik kita! Grand Chariot!",
  str_voice_1602331_39 = "Serangan—",
  str_voice_1602331_40 = "Lihatlah kekuatan alkimia!",
  str_voice_1602331_41 = "Baiklah, ayo bersenang-senang!",
  str_voice_1602331_42 = "Ya! Kita berhasil—!",
  str_voice_1602331_43 = "Kurasa saya masih membutuhkan lebih banyak latihan...",
  str_voice_1602331_44 = "Saya bertanya-tanya apakah saya bisa membuat dekorasi ini menggunakan alkimia?",
  str_voice_1602331_45 = "Terima kasih! Saya baru saja mencari ini!",
  str_voice_1602331_46 = "Wow! Aku tidak sabar untuk menggunakan ini!",
  str_voice_1602331_47 = "Apa ini? Sungguh menyentuh...",
  str_voice_1602331_48 = "Tak menyangka aku akan menerima hadiah luar biasa hari ini!",
  str_voice_1602331_49 = "Tiga tahun lalu, aku tidak tahu apa-apa tentang alkimia. Aku hanya seorang gadis petani biasa yang mencari cara untuk bersenang-senang setiap hari.",
  str_voice_1602331_50 = "Heheh, ini bukan pertama kalinya aku berpetualang ke dunia lain... itulah sebabnya aku tidak terlalu terkejut dengan sebagian besar hal di sini!",
  str_voice_1602331_51 = "Selalu pegang teguh keinginanmu untuk berpetualang, dan jangan pernah lupakan teman-teman yang telah kamu temui sepanjang perjalanan.",
  str_voice_1602331_52 = "Alchemy Stars!",
  str_voice_1602331_53 = "Hei, awas kamu, ya!",
  str_voice_1602331_54 = "Selamat pagi!",
  str_voice_1602331_55 = "Huh? Sudah siang?!",
  str_voice_1602331_56 = "Dapatkan tidur malam yang nyenyak!",
  str_voice_1602331_57 = "Selamat Tahun Baru! Kita semua bersemangat untuk melihat petualangan apa yang telah disiapkan tahun ini untuk kita!",
  str_voice_1602341_1 = "Maaf, saya tidak mengganggu apa-apa, bukan? Maafkan saya, saya hanya ingin mengatakan betapa menakjubkannya melihat dunia dari atas Colossus Anda.",
  str_voice_1602341_2 = "Luar biasa! Sekarang, teman-teman dan aku akan memiliki lebih banyak petualangan untuk dikenang... semua berkat kamu.",
  str_voice_1602341_3 = "Seringkali aku mendengar musik indah mengalir melalui Colossus... Tunggu, kamu maksud aku juga bisa ikut serta?",
  str_voice_1602341_4 = "Nyonya Connolly sepertinya memiliki sesuatu untuk diberitahu kepada saya, yang sempurna karena saya ingin melihat instrumennya... Bagaimana saya harus mendekatinya though...",
  str_voice_1602341_5 = "Kamu ingin belajar cara berpikir seperti pedagang dariku agar kamu bisa memenuhi permintaan Nona Vice dan melindungi dirimu dari skema pemasaran Tuan Jomu? Hehe, senang rasanya kamu memiliki banyak kepercayaan padaku.",
  str_voice_1602341_6 = "Jangan ragu untuk menyerahkan pekerjaan pendukung apa pun padaku. Mungkin aku tidak seceria Ryza atau Patty, tetapi aku masih bisa menyelesaikan banyak hal dalam bidang keahlianku.",
  str_voice_1602341_7 = "Kamu tampak lelah; apakah kamu ingin beristirahat sebentar? Saya bisa menyediakan teh dan camilan, jika kamu tertarik.",
  str_voice_1602341_8 = "Kesulitan mengelola biaya misi Anda? Saya kebetulan memiliki beberapa pengalaman dalam hal seperti itu... Mungkin saya bisa membantu?",
  str_voice_1602341_9 = "Hari ini, saya belajar sejumlah resep Astra dari teman-teman kita di atas Colossus. Saya tidak sabar untuk mencoba mereka suatu hari nanti!",
  str_voice_1602341_10 = "Volume masuk... volume keluar... jumlah pesanan... Ah! Mohon maaf, saya tahu saya seharusnya tidak melakukan ini saat waktu libur saya.",
  str_voice_1602341_11 = "Terima kasih telah mempercayai saya. Selama kita masih di dunia Anda, izinkan saya untuk membantu Anda dengan keuangan Anda.",
  str_voice_1602341_12 = "Setelah mendiskusikan perencanaan perjalanan dan keamanan dengan Ms. Blanc, saya merasa seolah-olah telah belajar banyak hal. Apakah ini benar-benar bagaimana Aurorian hidup di dunia ini...?",
  str_voice_1602341_13 = "Kamu pikir aku memiliki potensi untuk menjadi pemimpin guild Umbraton? Betapa baiknya kamu mengatakannya... Tapi aku masih relatif baru di dunia bisnis, dan aku masih memiliki banyak hal yang harus dipelajari.",
  str_voice_1602341_14 = "Terima kasih atas kemurahan hati Anda, Navigator! Anda telah bekerja keras untuk memastikan keamanan dan kesenangan kami, dan kami telah membuat kenangan yang indah. Saya hanya berharap kami bisa membalas budi suatu hari nanti!",
  str_voice_1602341_15 = "Selamat ulang tahun, Navigator! Ryza dan Patty telah menyiapkan hadiah ini untukmu, tapi aku lah yang mengusulkan ide ini. Semoga kamu menyukainya!",
  str_voice_1602341_16 = "Kelihatannya kamu cukup sibuk hari ini... Apakah kamu ingin bantuan?",
  str_voice_1602341_17 = "Selamat pagi, Navigator! Aku membuatkanmu secangkir teh.",
  str_voice_1602341_18 = "Selamat datang kembali. Bagaimana kabarmu hari ini? Melihat sesuatu yang menarik?",
  str_voice_1602341_19 = "Sudah cukup larut untuk cerita, tapi masih ada hari esok. Selamat malam!",
  str_voice_1602341_20 = "Ibukota dunia saya adalah kota yang indah dan ramai, tetapi saya sering merindukan hari-hari petualangan saya berjemur di alam liar dengan Ryza.",
  str_voice_1602341_21 = "Banyak teman Aurorian kami yang menyarankan saya untuk mencoba bekerja di Umbraton untuk sementara waktu. Menurut kamu, apakah saya benar-benar memiliki apa yang dibutuhkan untuk berhasil di sana?",
  str_voice_1602341_22 = "Guild Valentz, siap melayani! ...Kurang lebih seperti itu, kamu kira?",
  str_voice_1602341_23 = "Meskipun ancaman dari monster-monster ini, orang-orang di dunia ini terus bertahan dan menjalani kehidupan yang penuh makna. Sungguh patut dihargai...",
  str_voice_1602341_24 = "Ryza selalu mengatakan bahwa dia tidak mengerti banyak hal di luar alkimia, tetapi saya tidak pernah kecewa selama dia berada di sisiku.",
  str_voice_1602341_25 = "Patty selalu khawatir bahwa dia tidak cukup sopan... Tapi menurutku, dia adalah seorang wanita bangsawan muda yang berperilaku baik.",
  str_voice_1602341_26 = "Berpetualang dengan Ryza... dan semua orang lainnya. Itu adalah harta terbesar yang bisa saya minta.",
  str_voice_1602341_27 = "Saya juga ingin berkontribusi, seperti setiap orang lainnya. Saya jauh lebih dewasa dari sebelumnya, jadi tolong, biarkan saya mengambil lebih banyak tanggung jawab.",
  str_voice_1602341_28 = "Ada sesuatu yang hampir ajaib tentang tempat ini... Tempat yang benar-benar nyaman di mana teman selalu diterima.",
  str_voice_1602341_29 = "Permisi, saya Klaudia Valentz. Astra benar-benar baru bagi saya. Saya sangat menghargai bimbingan Anda!",
  str_voice_1602341_30 = "Sepertinya saya telah sedikit membaik.",
  str_voice_1602341_31 = "Aku masih bisa bertarung!",
  str_voice_1602341_32 = "Saya harus melanjutkan latihan.",
  str_voice_1602341_33 = "Aku akan melindungimu.",
  str_voice_1602341_34 = "A-aku akan berusaha sebaik mungkin!",
  str_voice_1602341_35 = "Peri-peri, tuntun aku!",
  str_voice_1602341_36 = "Angin, pinjamkan aku kekuatanmu!",
  str_voice_1602341_37 = "Tidak bisa menghindari angin!",
  str_voice_1602341_38 = "Ini berakhir sekarang! White Requiem!",
  str_voice_1602341_39 = "Serang!",
  str_voice_1602341_40 = "Angin Puyuh!",
  str_voice_1602341_41 = "(Napas dalam-dalam) Aku pasti bisa!",
  str_voice_1602341_42 = "Kerja bagus, semuanya!",
  str_voice_1602341_43 = "Saya harus tetap tenang dan menyembuhkan yang terluka...",
  str_voice_1602341_44 = "Terima kasih telah menjadi tuan rumah yang menyenangkan. Saya juga telah menyiapkan beberapa minuman untuk semua orang...",
  str_voice_1602341_45 = "Terima kasih atas hadiahmu.",
  str_voice_1602341_46 = "Oh sayang, kau tak perlu repot-repot!",
  str_voice_1602341_47 = "A-Sebenarnya, aku juga punya sesuatu...",
  str_voice_1602341_48 = "Bisa... Bisa aku benar-benar memiliki ini? Oh, terima kasih!",
  str_voice_1602341_49 = "Saya lahir dalam keluarga pedagang keliling, jadi saya menghabiskan banyak masa kecil saya menemani ayah saya dalam perjalanannya. Akibatnya, saya jarang memiliki teman sebaya.",
  str_voice_1602341_50 = "Ryza dan teman-temannya menyelamatkan hidupku di hutan suatu hari. Kami telah menjadi teman sejak itu, menjalani berbagai jenis petualangan bersama-sama.",
  str_voice_1602341_51 = "Meskipun aku masih mengikuti jejak ayahku sebagai seorang pedagang, aku percaya pengalamanku dengan Ryza telah mengubahku dalam banyak cara yang berbeda.",
  str_voice_1602341_52 = "Alchemy Stars.",
  str_voice_1602341_53 = "Permisi...",
  str_voice_1602341_54 = "Selamat pagi!",
  str_voice_1602341_55 = "Ingin minum teh?",
  str_voice_1602341_56 = "Please get some rest.",
  str_voice_1602341_57 = "Tahun baru lagi. May petualangan fantastis kamu berlanjut ke masa depan, dan membawa lebih banyak kenangan indah untukmu.",
  str_voice_1502351_1 = "Jadi ini Colossus milikmu! Semua hal dari bentuk hingga strukturnya benar-benar menakjubkan... Aku tidak akan tersesat di dalamnya, bukan?",
  str_voice_1502351_2 = "Sudah diputuskan. Saya berencana untuk belajar etiket dari ksatria Lumopolis, serta kepemimpinan dari perwira Federasi Illumina.",
  str_voice_1502351_3 = "Um, saya tidak sepenuhnya yakin jenis permainan apa yang disukai oleh anak-anak Aurorian. Apakah tidak apa-apa jika saya bergabung dengan mereka?",
  str_voice_1502351_4 = "Ayah saya pernah menjadi ksatria yang luar biasa. Untuk menjaga kehormatannya dan kehormatan keluarga saya, saya harus terus berlatih.",
  str_voice_1502351_5 = "Ah, jadi kamu menyadari bahwa saya juga telah mengamati Lady Carleen? Itu karena saya ingin belajar sikap terhormatnya, dan membawa diri saya lebih dekat dengan diri ideal saya.",
  str_voice_1502351_6 = "Saya telah berpartisipasi dalam beberapa pertempuran tidak konvensional sejak kita tiba di duniamu. Semoga, pengalaman ini akan membimbing pedangku untuk melayani kamu dan Colossus-mu dengan baik.",
  str_voice_1502351_7 = "Ah, maaf telah membiarkanmu melihat sisi memalukan dariku. Aku akan pastikan untuk menenangkan diri di lain waktu.",
  str_voice_1502351_8 = "Kamu pikir keterampilan pedangku telah sangat meningkat? Terima kasih! Sepertinya latihan terakhirku tidak sia-sia.",
  str_voice_1502351_9 = "Kamu membuatku terkesan, Navigator. Setiap kali aku tidak tahu harus berbuat apa, kamu selalu ada untuk membantuku. Aku pasti akan membalas budi di lain waktu.",
  str_voice_1502351_10 = "... Kenapa kamu diam saja? Aku tahu. Kamu pikir aku membosankan, bukan? ...Tidak? Kamu yakin? Oke...",
  str_voice_1502351_11 = "Aku mengerti. Selama kita di sini, aku bersumpah untuk melindungimu sebagai ksatria yang setia dalam melayanimu.",
  str_voice_1502351_12 = "Dulu saya berpikir Blue Puni adalah monster yang sangat merepotkan, tetapi setelah melihat Eclipsite di dunia kalian, mereka tampak sangat jinak bagi saya sekarang.",
  str_voice_1502351_13 = "Salah satu teman Aurorian Anda menawarkan saya keanggotaan untuk apa yang tampaknya semacam klub baca. Dia tampak sangat ramah dan berpengetahuan, tetapi saya hampir tidak bisa memahami apa pun yang dia katakan.",
  str_voice_1502351_14 = "Kalau bukan karena Klaudia, pasti aku akan membuat banyak kesalahan pembelian yang memalukan di duniamu...",
  str_voice_1502351_15 = "Selamat ulang tahun! Bagaimana menurutmu tentang hadiahmu? Klaudia yang mencetuskan ide ini, dan Ryza yang merangkainya sebagian besar. Semoga, kontribusi saya tidak mengurangi kualitas keseluruhannya.",
  str_voice_1502351_16 = "Terima kasih telah mengundang saya untuk makan. Masakan Astra sangat beragam dan lezat.",
  str_voice_1502351_17 = "Selamat pagi. Kamu juga orang yang sangat tepat waktu, ya?",
  str_voice_1502351_18 = "Sudah semakin malam. Kecuali jika kamu berencana untuk berjaga malam ini, mungkin kita harus kembali ke Colossus?",
  str_voice_1502351_19 = "Hmm... Ah, Navigator! Kamu pulangnya malam! Biar aku bantu dengan persediaan ini.",
  str_voice_1502351_20 = "Tidak ada yang bisa membuatku lebih bahagia selain berkontribusi dengan cara ku sendiri.",
  str_voice_1502351_21 = "Arsitektur Lumopolis sangat megah, tetapi Lady Carleen membuat poin yang baik: untuk benar-benar memahami suatu domain, seseorang harus melihat lebih jauh dari penampilannya.",
  str_voice_1502351_22 = "Jika kamu mencoba menghentikanku, aku tidak akan menahan diri!",
  str_voice_1502351_23 = "Mereka adalah makhluk aneh, yang hanya membuatku bertanya: apakah Ryza akan mencoba menggunakannya sebagai bahan dalam alkimianya?",
  str_voice_1502351_24 = "Dunia ini penuh dengan berbagai jenis material baru! Dengan sedikit riset, Ryza mungkin bisa menciptakan beberapa bahan peledak luar biasa dari material tersebut.",
  str_voice_1502351_25 = "Ada seorang Aurorian di Colossus yang selalu membawa instrumen panjang ke mana pun dia pergi. Selalu menyenangkan melihat dia dan Klaudia saling menatap tanpa mengucapkan sepatah kata pun!",
  str_voice_1502351_26 = "Di masa lalu, saya mungkin akan mengatakan sesuatu seperti \"membawa kehormatan kepada ayah saya dan keluarga kami.\" Tapi sekarang, saya ingin mencari sesuatu yang lain.",
  str_voice_1502351_27 = "Ih, aku benci serangga! Aku tahu mereka tidak bisa menyakitiku, tapi hanya mendengar sayap mereka bergetar saja membuat rambutku merinding.",
  str_voice_1502351_28 = "Ini adalah ciptaan yang luar biasa dengan nilai praktis dan estetika.",
  str_voice_1502351_29 = "Senang bertemu denganmu. Namaku Patricia Abelheim, tapi kamu bisa memanggilku Patty. Meskipun keluargaku mungkin bukan yang paling terkemuka, aku memang berasal dari bangsawan dan memiliki beberapa keterampilan dengan pedang. Aku percaya bakatku bisa berguna untukmu.",
  str_voice_1502351_30 = "Hmm, aku telah menjadi lebih kuat.",
  str_voice_1502351_31 = "Aku akan menjadi lebih kuat lagi.",
  str_voice_1502351_32 = "Ini haruslah ritme petualangan.",
  str_voice_1502351_33 = "Saya akan menghargai semua pengalaman yang telah saya peroleh di sini.",
  str_voice_1502351_34 = "Lebih banyak pengalaman untuk diperoleh.",
  str_voice_1502351_35 = "Biar aku saja.",
  str_voice_1502351_36 = "Tidak ada jalan keluar!",
  str_voice_1502351_37 = "Enyahlah dalam keputusasaan!",
  str_voice_1502351_38 = "Rasakan ini! Keinginan Sempurna!",
  str_voice_1502351_39 = "Rasakan ini!",
  str_voice_1502351_40 = "Coba dan hentikan aku!",
  str_voice_1502351_41 = "Hm... Ini kehormatan saya!",
  str_voice_1502351_42 = "Tidak ada waktu untuk beristirahat dan merasa puas dengan pencapaianku.",
  str_voice_1502351_43 = "... Kita harus mundur untuk saat ini.",
  str_voice_1502351_44 = "Dekorasi ini tidak seperti di kampung halamanku, tetapi saya tetap menghargai keindahan mereka.",
  str_voice_1502351_45 = "Aku akan mengingat kemurahan hatimu. Terima kasih.",
  str_voice_1502351_46 = "Wow, apa ini...?",
  str_voice_1502351_47 = "Saya juga ingin melakukan lebih banyak untukmu.",
  str_voice_1502351_48 = "Aku tidak akan pernah melupakan momen ini!",
  str_voice_1502351_49 = "Aku adalah keturunan dari garis keturunan bangsawan. Meskipun aku adalah putri termuda di keluargaku, aku mengerti pentingnya kedudukan sosialku, serta statusku sebagai putri seorang tuan tanah.",
  str_voice_1502351_50 = "Aku harus berperilaku sesuai standar bangsawan, dan melakukan segala yang bisa aku lakukan untuk meringankan beban ayahku... Meski itu membawa kesedihan dan kesepian untukku.",
  str_voice_1502351_51 = "Ryza mengajari saya bagaimana cara hidup orang biasa, dan membantu saya memahami arti dari petualangan.",
  str_voice_1502351_52 = "Alchemy Stars.",
  str_voice_1502351_53 = "Maafkan saya—",
  str_voice_1502351_54 = "Ini sangat pagi.",
  str_voice_1502351_55 = "Bagus!",
  str_voice_1502351_56 = "Sudah sangat larut!",
  str_voice_1502351_57 = "May kamu mewujudkan semua tujuanmu tahun ini, dan menemukan yang baru untuk dikejar... Selamat Tahun Baru!",
  str_voice_1602333_1 = "Meskipun saya tumbuh besar dikelilingi oleh danau, keindahan laut yang luas adalah sesuatu yang tidak akan pernah saya bosan untuk dilihat!",
  str_voice_1602333_2 = "Navigatow, apakah kain ini tidak mewasakan sepewti Eldrocode? Oh, maf... Kamu mungkin bahkan tidak tahu apa itu...",
  str_voice_1602333_3 = "Ada begitu banyak hal menarik tentang lautan Astra! Sebagai contoh... Bulu babi di sini sebenarnya hidup di laut!",
  str_voice_1602333_10 = "Apa itu yang mengambang ke arah kita? Itu sebuah tong!",
  str_voice_1602333_11 = "\"Semakin terbuka baju besinya, semakin baik pertahanannya\"? A-Apakah benar begitu cara kerjanya di sini di Astra?!",
  str_voice_1602333_12 = "Fiuh! Itu menyenangkan, tapi sekarang aku benar-benar perlu mendinginkan diri! Ada yang bisa aku gunakan, Navigator?",
  str_voice_1602333_13 = "Ahh... Menghabiskan musim panas bersama teman-teman adalah yang terbaik!",
  str_voice_1602333_14 = "Bahahaha! Kamu benar-benar basah kuyup, Navigator! Untunglah kita memakai baju renang, kan... H-Hey! Serangan mendadak itu tidak adil!",
  str_voice_1602333_16 = "Laut memanggil kita untuk memulai petualangan baru!",
  str_voice_1602333_17 = "Pagi! Apakah kamu tidur dengan nyenyak? Embusan angin sejuk di Colossus hampir membuatku lupa bahwa di bawah sana adalah musim panas!",
  str_voice_1602333_18 = "Mau minuman yang enak dan menyegarkan? Ahh... Aku tidak punya bahan biasa, tapi rasanya masih enak!",
  str_voice_1602333_19 = "Hatchi! Di Colossus agak dingin ya malam hari? Oh, ini selimut untukku? Terima kasih!",
  str_voice_1602333_35 = "Waktunya bertualang!",
  str_voice_1602333_36 = "Ke laut!",
  str_voice_1602333_37 = "Musnahlah ke seberang laut!",
  str_voice_1602333_38 = "Aku tak akan kalah dari siapa pun musim panas ini!",
  str_voice_1602333_39 = "Bagaimana ini?!",
  str_voice_1602333_40 = "Lepas landas!",
  str_voice_1602333_44 = "Berlayar untuk petualangan musim panas yang menakjubkan lainnya!",
  str_voice_1602371_1 = "Kamu bisa main piano? Sempurna! Aku main conch! Yuk, kita main bersama kapan-kapan!",
  str_voice_1602371_2 = "... Di mana saya tadi? Oh, apakah kamu bisa memainkan alat musik? Mau belajar cara memainkan kerang dari saya?",
  str_voice_1602371_3 = "Mau membaca bersama? Aku tidak tahu banyak kata, jadi bisakah kamu membacakan untukku? Yay! Terima kasih!",
  str_voice_1602371_4 = "Kekuatanku adalah kekuatanmu! Cukup katakan saja!",
  str_voice_1602371_5 = "Melodi kerang membawa saya masuk ke dalam mimpi leluhur yang saya hormati. Gelembung-gelembung itu sebenarnya adalah tawanya—dia telah sangat membantu saya.",
  str_voice_1602371_6 = "PlayerName, kamu berbau seperti mimpi. Jangan takut, saya akan memainkan keong jika mereka menolak untuk menjauh dari kamu...",
  str_voice_1602371_7 = "Kamu sangat baik padaku... Itu benar, aku bisa merasakannya!",
  str_voice_1602371_8 = "Aku suka kamu! Hah? Mengapa kamu tersipu?",
  str_voice_1602371_9 = "Aku menyukaimu! Hah? Kenapa kau menoleh? Hmm... Aku merasa seperti melupakan sesuatu. Ah, terserah! Aku hanya menyukaimu!",
  str_voice_1602371_10 = "Apakah kamu sedang istirahat? Ingin mimpi indah? Saya bisa membantu kamu dengan itu.",
  str_voice_1602371_11 = "Baiklah! Beri tahu saya jika saya melupakan sesuatu!",
  str_voice_1602371_12 = "Aku telah belajar trik baru, PlayerName! Tunggu di sini sebentar, dan aku akan menunjukkannya padamu!",
  str_voice_1602371_13 = "Orang tuaku sedang tidur, dan aku hidup dalam mimpi mereka. Mereka akan datang bersama leluhurku untuk bermain denganku begitu aku juga tertidur.",
  str_voice_1602371_14 = "PlayerName, aku membantu lebih banyak orang hari ini. Lihat! Lihat saja bunga-bunga kecil merah ini yang mereka tinggalkan di bukuku... Hah? Kamu maksud... ini dari kemarin?",
  str_voice_1602371_15 = "Selamat ulang tahun! Saya bersyukur atas kelahiranmu, dan saya menyukaimu.",
  str_voice_1602371_16 = "Hei! Mau jalan bersama?",
  str_voice_1602371_17 = "Hai! Ada yang bisa saya bantu?",
  str_voice_1602371_18 = "Oh! Mau melihat bulan?",
  str_voice_1602371_19 = "Yawn... Aku merasa mengantuk. Jangan begadang, ya?",
  str_voice_1602371_20 = "Setiap orang di Harbour City sangat baik padaku, jadi aku akan berusaha sebaik mungkin untuk membantu kamu melindunginya, Elvis!",
  str_voice_1602371_21 = "Wanita dari True Order itu ingin mengungkap apa yang ada di luar gelembung, tetapi jika memecahkannya akan membangunkan setiap orang.",
  str_voice_1602371_22 = "Hanya ketika aku tertidur, dunia akan menyadari bahwa ini hanyalah mimpi.",
  str_voice_1602371_23 = "Gelembung ilusi sedikit berbintik-bintik. Para pemberontak itu mengalami mimpi buruk, dan mereka juga membuat orang lain mengalami mimpi buruk.",
  str_voice_1602371_24 = "Saya suka Connolly karena musiknya sangat manis di telinga.",
  str_voice_1602371_25 = "Saya suka Zeta karena dia selalu memberi saya permen setiap kali dia lewat. Hah? Kenapa saya ingat? Bodoh PlayerName, tentu saja karena saya lupa makan permen itu.",
  str_voice_1602371_26 = "Es kopi sangat lezat. Tidak bisa menahan diri untuk tidak minum terlalu banyak.",
  str_voice_1602371_27 = "Bagaimana cara saya menolak makanan pedas tanpa membuat orang lain tersinggung?",
  str_voice_1602371_28 = "Dalam mimpiku, leluhurku selalu membawaku terbang, tapi dia tidak memiliki banyak kamar seperti ini.",
  str_voice_1602371_29 = "Saya ingat kamu, PlayerName. Saya menulis tentangmu di buku catatanku. Kamu ingin melihatnya, katamu? Tidak boleh mengintip! Bahkan saya punya hak untuk menyimpan rahasia di sini dan di sana.",
  str_voice_1602371_30 = "Leluhurku memanggilku dalam mimpi.",
  str_voice_1602371_31 = "Masalah cepat berlalu.",
  str_voice_1602371_32 = "Takdir hanyalah gelembung dari leluhurku.",
  str_voice_1602371_33 = "Dunia mungkin adalah mimpiku.",
  str_voice_1602371_34 = "Saya bisa membantu.",
  str_voice_1602371_35 = "Ayo kita pergi!",
  str_voice_1602371_36 = "Leluhurku sedang bangkit.",
  str_voice_1602371_37 = "Ayo! Menyerang!",
  str_voice_1602371_38 = "Ayo pergi! Ini adalah final!",
  str_voice_1602371_39 = "Ritme gelembung.",
  str_voice_1602371_40 = "Cahaya gelembung.",
  str_voice_1602371_41 = "Aku akan melindungimu.",
  str_voice_1602371_42 = "Hehe! Syukurlah kau tidak terluka!",
  str_voice_1602371_43 = "Bantu aku, leluhur.",
  str_voice_1602371_44 = "Banyak sekali buku! Ada dongeng? Aku ingin membaca beberapa.",
  str_voice_1602371_45 = "Aku tidak akan melupakan kebaikanmu.",
  str_voice_1602371_46 = "Kamu adalah mimpi indahku.",
  str_voice_1602371_47 = "Terima kasih! Kamu membuatku malu!",
  str_voice_1602371_48 = "Aku suka! Ini membuat jantungku berdebar!",
  str_voice_1602371_49 = "Aku masih ingat bagaimana ibuku biasa mengambil tanganku dan menceritakan dongeng setiap malam. Saat perahu bergoyang dengan ombak, dia segera tertidur.",
  str_voice_1602371_50 = "Saya menemukan keong ini bersama ayahku. Saya baru saja mengambilnya ketika saya mendengar seseorang memanggil saya, dan saya bisa memainkannya secara insting. Itu membawa saya kepada leluhur saya dalam mimpi.",
  str_voice_1602371_51 = "Terkadang, saya bisa bertemu leluhur saya bahkan tanpa memainkan conch. Sepertinya sedang membimbing saya untuk memperbaiki mimpi yang sangat, sangat besar. Hah? Apa yang mungkin terjadi pada dunia jika semua orang bangun?",
  str_voice_1602371_52 = "Alchemy... Hmm... Oh! Bintang Alchemy!",
  str_voice_1602371_53 = "Gelembung!",
  str_voice_1602371_54 = "Matahari berkilau.",
  str_voice_1602371_55 = "Merasa malas.",
  str_voice_1602371_56 = "Apa kamu bermimpi?",
  str_voice_1602371_57 = "Hari ini adalah hari yang paling spesial dari semuanya! Aku memiliki banyak hadiah untukmu! Tolong habiskan hari ini bersamaku!",
  str_voice_1702361_1 = "Dahulu kala, kerajaan membutuhkan bintang untuk menghancurkan kegelapan, jadi kawan-kawan saya berani melangkah maju dan membakar diri mereka sendiri... Abu mereka tetap sebagai debu bintang, dan waktu tidak akan pernah menghapus jiwa-jiwa noble tersebut.",
  str_voice_1702361_2 = "Teman sejawat Caelestite kita yang lama, Ludweiss... Dia telah melakukan pengorbanan tertinggi untuk kita. Aku akan melanjutkan warisannya, meski aku satu-satunya yang mengingatnya.",
  str_voice_1702361_3 = "Friegson adalah anak yang tangguh. Seperti Adras, dia tidak pernah memiliki masa kecil yang bahagia dan bahkan tidak memiliki orang spesial untuk diingat. Jangan salahkan sikapnya, dia hanya lelah.",
  str_voice_1702361_4 = "Terima kasih, Caelestite. Kamu telah membantu semua penyesalan kami dan memungkinkan saya untuk memenuhi janji saya—untuk bersatu kembali dengan kawan-kawan saya.",
  str_voice_1702361_5 = "Aku tahu semua Caelestite itu ramah, dan aku benar-benar minta maaf karena telah meminta kalian bergabung dalam pertarungan kami. Aku bersumpah aku tidak akan pernah membiarkan kalian menjadi korban.",
  str_voice_1702361_6 = "Caelestite Terakhir... Betapa sedihnya julukan itu. Apakah kamu juga menunggu sendirian, berharap bertemu dengan teman-temanmu? Jangan tampak begitu sedih. Jika aku bisa bertemu kembali dengan kawan-kawanku, mungkin kamu juga bisa bertemu dengan jenismu. Mari kita bantu.",
  str_voice_1702361_7 = "Istirahatlah, rasakan angin kebebasan, dan dengarkan musik kehidupan.",
  str_voice_1702361_8 = "Demi nama Achilles, aku akan melindungimu.",
  str_voice_1702361_9 = "Dulu saya bisa menggunakan sihir, tetapi sekarang tubuh ini tidak lagi menerima berkat dari Lumina. Tidak masalah. Meskipun saya jatuh ke dalam jurang, saya masih bisa memanggil cahaya bintang untuk melawan takdir.",
  str_voice_1702361_10 = "Kekuatan yang mengelilingiku... Aku menyebutnya Star Power, karena sering berbisik padaku, menceritakan tentang adegan berbintang.",
  str_voice_1702361_11 = "Caelestite lain menemukanku setelah Ludweiss. Dia belum melihat cahaya harapan, seperti Ludweiss, tetapi sama-sama bertekad untuk membakar jiwanya. Mereka adalah pahlawan sejati, dan saya harus menyanyikan keberanian mereka.",
  str_voice_1702361_12 = "Orang-orang yang terobsesi dengan keuntungan atau kekuatan tidak pantas untuk menilai kita, apalagi mencatat cerita kita dengan pandangan sempit mereka!",
  str_voice_1702361_13 = "Kami akan tetap setia pada diri sendiri, menjaga dengan diam dan selalu melawan kejahatan. Begitu sudah berlangsung selama dua milenium, dan begitu pula akan berlangsung selama dua milenium lagi.",
  str_voice_1702361_14 = "Dulu aku tidak cukup berani, yang menyebabkan begitu banyak tragedi bagi kawan-kawanku. Tapi untungnya masih ada orang-orang yang mencintai kami, dan mereka telah meneruskan obor dan memungkinkan kami bertemu lagi. Aku sangat berhutang budi dan tidak bisa mengungkapkan betapa berterima kasihnya aku...",
  str_voice_1702361_15 = "Selamat ulang tahun. Aku mendapatkan Adras untuk mengajari aku cara membuat kue untukmu.",
  str_voice_1702361_16 = "Ada yang ingin kamu bagikan?",
  str_voice_1702361_17 = "Saya tidak pernah berpikir saya akan melihat matahari lagi.",
  str_voice_1702361_18 = "Ingin hangat di sekitar api unggun?",
  str_voice_1702361_19 = "Sudah larut. Hati-hati dengan suara-suara itu. Jangan sembarangan percaya pada suara-suara dalam kepalamu, terutama di malam hari.",
  str_voice_1702361_20 = "Silent Hunter adalah gelar yang kupikir sudah kubur. Ini mewakili banyak hal... kepahlawanan, pengorbanan, pengkhianatan, dan... harapan.",
  str_voice_1702361_21 = "Northland? Oh... Kerajaan itu kini hidup dalam cahaya kedamaian dan keberuntungan, dan itu sudah cukup.",
  str_voice_1702361_22 = "Kami adalah pengawas keadilan.",
  str_voice_1702361_23 = "Mereka bukan satu-satunya musuh kita, tetapi mereka adalah orang-orang yang hanya ingin saya arahkan pedang saya.",
  str_voice_1702361_24 = "Ludweiss suka mencatat, dan aku berjanji padanya aku akan melanjutkan semuanya. Saat ini, aku mencintai dunia atas nama dia.",
  str_voice_1702361_25 = "Jangan takut pada kawan-kawan saya. Turunkan senjatamu, mereka hanyalah seorang tukang roti, seorang gadis yang ceria, seorang penjaga yang gugup, dan seseorang yang haus akan kedamaian.",
  str_voice_1702361_26 = "Setiap orang hidup bahagia di sini, terima kasih.",
  str_voice_1702361_27 = "Buku-buku saat ini bahkan memuliakan penjahat. Saya tidak mengerti...",
  str_voice_1702361_28 = "Anda beruntung bisa melakukan perbuatan benar bersama teman-teman Anda.",
  str_voice_1702361_29 = "Caelestite... Ah, maafkan saya. Dahulu kala, kawan-kawan Caelestite kita yang mulia mengorbankan segalanya untuk kita. Sekarang saya akan melindungi yang terakhir dari jenis mereka.",
  str_voice_1702361_30 = "Kekgelapan yang kaya, ada di penggunaanku.",
  str_voice_1702361_31 = "Hati-hati, Caelestite.",
  str_voice_1702361_32 = "Banyak Star Power.",
  str_voice_1702361_33 = "Kekuatan yang meluap...",
  str_voice_1702361_34 = "Cahaya bintang gelap, meletus!",
  str_voice_1702361_35 = "Meteor yang tak kenal menyerah, lawan takdir!",
  str_voice_1702361_36 = "Habisi!",
  str_voice_1702361_37 = "Kematian untuk semua musuh!",
  str_voice_1702361_38 = "Sudah lama sejak terakhir kali saya dipanggil kapten.",
  str_voice_1702361_39 = "Semua tidak terluka, bukan?",
  str_voice_1702361_40 = "Lindungi Caelestite itu. Aku akan menutupi belakang!",
  str_voice_1702361_41 = "Salam. Aku sedang merekam informasi baru.",
  str_voice_1702361_42 = "Terima kasih, Caelestite.",
  str_voice_1702361_43 = "Tidak mengejutkan karena ini dari Caelestite yang bisa membaca pikiran.",
  str_voice_1702361_44 = "Aku akan mencatat kebaikanmu.",
  str_voice_1702361_45 = "Aku tidak punya apa-apa untuk dibalas... kecuali kamu ingin melihat catatanku?",
  str_voice_1702361_46 = "Dahulu kala, saya dikenal sebagai Tangan Raja. Saya bertindak dengan setia dan keyakinan dan berjuang tanpa henti untuk kerajaan. Sahabat dekat saya saat itu ada di takhta, dan dialah yang mendukung sifat saya yang tidak kompromi.",
  str_voice_1702361_47 = "Sejak kapan saya hanya ditinggalkan dengan teman-teman? Saya tidak tahu. Mungkin sikap saya yang tidak goyah membuat setiap orang melihat saya sebagai musuh, tetapi satu-satunya hal yang tidak bisa saya terima adalah pengkhianatan dari raja.",
  str_voice_1702361_48 = "Kemudian, aku memilih untuk menyegel kawan-kawanku, tetapi aku tidak mengharapkan harganya adalah pengorbanan temanku. Aku bersumpah untuk mengamankan masa depan untuk mereka, jadi aku harus tetap di masa lalu... Jangan bersedih, karena jika kamu melihatku sekarang, berarti aku sudah melintasi tahun-tahun itu.",
  str_voice_1702361_49 = "Alchemy Stars.",
  str_voice_1702361_50 = "Caelestite.",
  str_voice_1702361_51 = "Selamat pagi.",
  str_voice_1702361_52 = "Matahari sangat menyilaukan.",
  str_voice_1702361_53 = "Kamu juga harus istirahat.",
  str_voice_1702361_54 = "Di luar tahun-tahun masa lalu adalah masa depan yang baru. Pertahankan keyakinan bahwa lebih banyak hal baik akan terjadi.",
  str_voice_1602381_1 = "Saya masih belajar bagaimana mencari keseimbangan menjadi seorang Courier dan juga menjadi pembela keadilan.",
  str_voice_1602381_2 = "Tolong jangan ungkapkan rahasiaku kepada Tweety. Aku tidak ingin dia melihat sayap asliku sekarang.",
  str_voice_1602381_3 = "Star Crest pada kalung ini awalnya adalah talisman yang diberikan kepada klanku oleh Lord Achilles, tetapi sekarang telah menjadi simbol perlindungan kami. Saya tahu bahwa jenis kesetiaan buta ini mungkin tampak konyol bagi kamu, tetapi saya tidak bisa lebih bangga dengan warisan saya.",
  str_voice_1602381_4 = "Bilah terselip di antara bulu dan sayap tersembunyi di bawah jubah. Sama seperti penyamaranku, sejarah klan Longinus tajam dan dalam.",
  str_voice_1602381_5 = "Mungkin karena saya telah memainkan begitu banyak peran dan bertemu begitu banyak orang sehingga saya bisa akrab dengan hampir semua orang. Tapi jika diberi pilihan, saya akan selalu memilih mereka yang terasa seperti rumah.",
  str_voice_1602381_6 = "Suatu hari nanti, aku akan mengeluarkan pedang utamaku sendiri dari Star Crest.",
  str_voice_1602381_7 = "Untuk menjaga identitas kami tetap tersembunyi, klan Longinus tidak pernah tinggal di satu tempat terlalu lama, atau menjalin hubungan dekat dengan orang luar. Tapi karena kamu, aku sekarang bebas... Meski aku masih belum terbiasa.",
  str_voice_1602381_8 = "Kamu mau dengar apa? Tak mungkin! Itu hanya ketika aku mencoba menyembunyikan siapa diriku yang sebenarnya.... Kamu mau kembali menjadi orang asing?",
  str_voice_1602381_9 = "Hari kamu membebaskan saya dari kewajiban klan saya, saya membuat sumpah baru untuk diri saya sendiri. Saya bersumpah untuk menyaksikan jalur masa depanmu, dan melihat sejauh mana cahaya kamu mencapai.",
  str_voice_1602381_10 = "... Merasa lelah? Baiklah, saya rasa istirahat pada waktu yang wajar bukanlah pelanggaran perjanjian. Kerja bagus hari ini.",
  str_voice_1602381_11 = "Agar kita sama-sama paham—Kamu ingin saya mengawasi pekerjaanmu. Benar begitu?",
  str_voice_1602381_12 = "Kebaikan Lady Freya sungguh menakjubkan, bahkan bagi saya... Tampaknya saya masih memiliki banyak hal untuk dipelajari.",
  str_voice_1602381_13 = "Bulu gagak tidak sepenuhnya hitam. Jika kamu melihat dengan seksama, kamu bisa melihat warna yang tersembunyi di dalamnya... Ada apa? Bukankah membedakan cahaya dan warna adalah keahlianmu?",
  str_voice_1602381_14 = "Para Kesatria Bintang tampaknya merasa bersalah terhadap klan kami, tidak ada yang lebih dari Lord Achilles... Jika mungkin, tolong yakinkan mereka bahwa tidak perlu merasa menyesal, dan membantu mereka telah menjadi kehormatan terbesar kami.",
  str_voice_1602381_15 = "Selamat ulang tahun. Hmm? Jangan tampak begitu terkejut. Aku telah bersumpah untuk mengingat hari ini seumur hidupku, dan memberikanmu harapan terbaikku setiap tahunnya.",
  str_voice_1602381_16 = "Ingin mencoba lingkungan kerja yang benar-benar beragam?",
  str_voice_1602381_17 = "Kamu bangun pagi. Apakah kamu juga memiliki banyak pekerjaan yang harus dikerjakan?",
  str_voice_1602381_18 = "Bagus. Hanya agar kamu tahu, usaha kamu tidak luput dari perhatian.",
  str_voice_1602381_19 = "Saatnya burung gagak mengintai sekitarnya... Lebih baik jika kamu tidak bertanya. Selamat malam.",
  str_voice_1602381_20 = "Serikat Kurir mengetahui berbagai jenis intelijen tetapi tidak pernah mengintai informasi tersebut atau membocorkannya kepada siapa pun. Ini adalah tempat yang sempurna bagi saya untuk tetap tersembunyi.",
  str_voice_1602381_21 = "Jika bukan karena kontrol Shadowlord, seluruh Umbraton akan jatuh ke dalam kekacauan total. Lagipula, orang tanpa iman tidak berarti apa-apa. Umbraton harus berterima kasih kepadanya karena telah menanamkan rasa martabat di kota ini.",
  str_voice_1602381_22 = "Kami adalah penjaga rahasia yang paling setia.",
  str_voice_1602381_23 = "Makhluk berdarah dingin dari kegelapan itu sama sekali tidak memiliki emosi dan kesadaran diri. Sayangnya, pada intinya, mereka tidak berbeda dengan kita.",
  str_voice_1602381_24 = "Goldie dan saya tidak sama. Dia adalah burung penyanyi yang berkembang di bawah sinar matahari, sementara saya adalah burung gagak yang berburu di tengah malam. Kami hanya saling mengenal melalui pertemuan kebetulan di malam hari.",
  str_voice_1602381_25 = "Tweety benar-benar mencintai pekerjaannya sebagai kurir, dan kebahagiaannya hampir meluap-luap. Hanya melihatnya saja bisa mencerahkan hari siapa saja.",
  str_voice_1602381_26 = "Dengan hati-hati melukis pedang-pedang ini menjadi hitam, membiarkannya kering, menyembunyikannya di bulu-buluku... Aku merasa sangat santai.",
  str_voice_1602381_27 = "Mengapa Kleken sangat menikmati berbohong? Aku tak akan pernah mengerti pria itu.",
  str_voice_1602381_28 = "Embusan angin di Colossus terasa sangat enak. Aku bertanya-tanya... Apakah Mr. Czerny tertawa saat dia akhirnya bisa terbang ke langit?",
  str_voice_1602381_29 = "Jangan takut, Caelestite Terakhir. Mulai saat ini, kamu tidak akan pernah sendirian. Aku bersumpah untuk menjadi kekuatan pemandumu, sumber kekuatanmu. Dan ya, ini adalah sumpahku padamu.",
  str_voice_1602381_30 = "Sayapku menjadi lebih tajam.",
  str_voice_1602381_31 = "Untuk orang jahat, aku adalah kematian.",
  str_voice_1602381_32 = "Aku adalah gagak malam.",
  str_voice_1602381_33 = "Aku adalah penjaga keyakinan.",
  str_voice_1602381_34 = "Kawanan.",
  str_voice_1602381_35 = "Wahyu seribu tahun...",
  str_voice_1602381_36 = "Bimbingan telah tiba.",
  str_voice_1602381_37 = "Nasib klan Longinus ada di tangan kita!",
  str_voice_1602381_38 = "Ukirkan komet ini di jiwa Anda.",
  str_voice_1602381_39 = "Sayap hitam quietus.",
  str_voice_1602381_40 = "Kematian seketika.",
  str_voice_1602381_41 = "Aku tidak ditakdirkan untuk memimpin.",
  str_voice_1602381_42 = "Rahasianya telah disimpan.",
  str_voice_1602381_43 = "Terbang, kau bodoh.",
  str_voice_1602381_44 = "Ini adalah tempat yang bagus untuk istirahatkan sayapku.",
  str_voice_1602381_45 = "Terima kasih.",
  str_voice_1602381_46 = "Bagaimana kau tahu aku suka ini?",
  str_voice_1602381_47 = "Aku pasti akan membalas budi.",
  str_voice_1602381_48 = "Seperti biasa... Terima kasih.",
  str_voice_1602381_49 = "Saya sedang berlatih di bawah Queen Bethlehem ketika orang tua saya meninggal membela Umbraton, tetapi Yang Mulia Ratu menolak untuk membiarkan saya meninggalkan Northland untuk mencari mereka. Selain misi saya, hati saya penuh dengan kemarahan saat itu. Kemarahan terhadap Eclipsite, kemarahan terhadap Queen, dan kemarahan terhadap orang tua saya karena mengirim saya pergi...",
  str_voice_1602381_50 = "Untuk beberapa waktu, saya meragukan diri sendiri meski berjuang untuk melindungi rahasia Star Warriors. Dengan hilangnya Eraveil dan terputusnya ramalan, apa yang masih saya perjuangkan? Kebingungan itu... hanya memicu kemarahan yang lebih besar lagi.",
  str_voice_1602381_51 = "Beberapa orang mengklaim bahwa saya adalah pahlawan malam di Umbraton, tetapi itu jauh dari kebenaran. Tidak seperti Goldie, yang berjuang demi keadilan di malam hari, saya hanya melampiaskan kemarahan saya pada penjahat kota... Jika saya tidak berubah segera, saya mungkin akan mengembangkan selera untuk kekerasan jenis ini suatu hari nanti.",
  str_voice_1602381_52 = "Alchemy Stars.",
  str_voice_1602381_53 = "Halo.",
  str_voice_1602381_54 = "Hidupkan sedikit.",
  str_voice_1602381_55 = "Di sini panas sekali.",
  str_voice_1602381_56 = "Masih bangun?",
  str_voice_1602381_57 = "Dengan datangnya tahun baru, semoga kamu bisa lepas dari belenggu masa lalu dan bergerak menuju masa depan yang lebih baik.",
  str_voice_1602183_1 = "Segala sesuatu dalam hidup dapat dilihat dari berbagai perspektif. Pikirkanlah, meskipun saya akhirnya membuat seseorang kehilangan pekerjaan mereka, mereka mungkin akan mendapatkan pekerjaan yang lebih baik dan bos yang lebih baik juga—yaitu, saya.",
  str_voice_1602183_2 = "May Saya bertanya kenapa kamu menatapku, sayangku? Apa maksudmu, saya tampak jauh lebih muda sekarang? Wah, betapa lancarnya kata-kata pemuda ini... Kenapa tidak kamu mendekat sedikit dan lihat apakah saya benar-benar berubah sebanyak itu?",
  str_voice_1602183_3 = "Tak lama lagi kau akan mengenalku, Sayang, tak perlu buru-buru. Percayalah padaku, teruslah bekerja keras di sisiku dan kau akan mengetahuinya sebelum kau sadari.",
  str_voice_1602183_10 = "Fiuh... Hari yang sibuk! Aku benar-benar butuh mandi sekarang. Aku bilang, bebek karet, ahoy! Aku datang!",
  str_voice_1602183_11 = "Oh, sayang, selalu menyenangkan bertemu denganmu. Katakan, apakah ada hal lain yang ingin kamu pelajari tentang bisnis hari ini?",
  str_voice_1602183_12 = "Seorang pemimpin guild tidak kurang dari wajah yang ditunjukkannya kepada dunia! Tidak peduli apa yang mungkin sedang dipikirkan di dalam, seseorang harus selalu menunjukkan wajah yang baik kepada publik. Jadi, sayangku, berikan pendapat jujurmu—apa pendapatmu tentang parfum yang aku pakai hari ini?",
  str_voice_1602183_13 = "Dalam bisnis, sangat penting untuk menjaga sikap yang menghormati. Namun demikian, saya tidak akan ragu untuk mengambil tindakan jika ada yang menolak untuk mendengarkan alasan.",
  str_voice_1602183_14 = "Strategi bisnisku bukan tentang memeras setiap keuntungan sebanyak mungkin—tapi tentang mendapatkan keuntungan besar dari investasi kecil. Aku sama seperti kamu, sayang—kita berdua suka menciptakan keajaiban, dan kita pandai melakukannya.",
  str_voice_1602183_16 = "Hah, akhirnya kau ada di sini, sayangku! Bagaimana kalau aku mulai mengurus hartamu, ya?",
  str_voice_1602183_17 = "Oh sayangku, kamu sangat pagi hari ini—betapa rajinnya kamu. Ingat, sayang, kesabaran adalah sebuah kebajikan. Hal baik datang kepada mereka yang sabar.",
  str_voice_1602183_18 = "Waktu yang sempurna. Aku akan senang sekali mentraktir kamu makan malam. Menurutmu, apakah kamu akan memiliki waktu?",
  str_voice_1602183_19 = "Bergadang begitu malam hanya untuk menyambutku? Sayang, aku mulai meragukan motifmu.",
  str_voice_1602183_35 = "Bersiaplah untuk diakuisisi.",
  str_voice_1602183_36 = "Jangan ragu.",
  str_voice_1602183_37 = "Ambil ini—cap penolakan saya!",
  str_voice_1602183_38 = "Sekarang, jual jiwamu padaku!",
  str_voice_1602183_39 = "Waktunya membuka cabang baru!",
  str_voice_1602183_40 = "Pembelian yang sangat menyenangkan!",
  str_voice_1602183_44 = "Sayang, tidakkah menurutmu tempat ini mulai tampak lebih sesuai dengan gayaku?",
  str_voice_1602183_58 = "Guild Cloudrover sudah buka untuk bisnis.",
  str_voice_1602183_59 = "Bagaimana jika kamu melihat dunia bersamaku?",
  str_voice_1602183_60 = "Selamat pagi, Sayang!",
  str_voice_1602183_61 = "Aku meninggalkan hadiah di meja kerjamu.",
  str_voice_1602183_62 = "Kapal udara tidak sama seperti Colossus—terutama ketika matahari sedang bersinar.",
  str_voice_1602183_63 = "Oh tidak... Tidakkah kamu mengundangku masuk untuk duduk sebentar?",
  str_voice_1602183_64 = "Aku melihatmu di sana, di luar di geladak, berdiri di angin sepoi-sepoi. Apakah ada yang mengganggumu?",
  str_voice_1602183_65 = "Aku yakin kamu pasti gatal ingin memijatku, bukan, sayang?",
  str_voice_1602183_66 = "Malam ilahi apa ini.",
  str_voice_1602183_67 = "\"Tindakan lebih berbicara keras daripada kata-kata.\"",
  str_voice_1602183_68 = "Jika kamu ingin sukses di Umbraton, kredibilitas adalah segalanya.",
  str_voice_1602183_69 = "Investasikan di Cloudrover Guild—percayalah padaku, kamu tidak akan menyesal.",
  str_voice_1602183_70 = "Rebut momen ini—mungkin saja ini adalah momen yang akan mengubah hidup Anda.",
  str_voice_1602183_71 = "Peluang itu singkat— itulah sebabnya saya meraih setiap satu dari mereka dengan kedua tangan.",
  str_voice_1600014_1 = "Seperti yang saya katakan sebelumnya, gaun ini untuk tarian khusus, dan karena kamu kebetulan berdiri di sana... Saya bisa menunjukkannya kepada kamu, jika kamu mau? Tapi hanya agar kamu tahu, ini adalah tarian berdua.",
  str_voice_1600014_2 = "Oh, Nepolis, kapan kau akan bebas dari cermin dan kembali ke dunia kita? Aku merindukan melihat gaun kita berayun kesana kemari saat kita menari bersama...",
  str_voice_1600014_3 = "Bunga-bunga di sekitar Lake Mirror tampak begitu bersemangat seperti biasa, bahkan ketika saya tidak ada. Apakah ada orang yang merawatnya untuk saya?",
  str_voice_1600014_10 = "\"Apakah kamu ingat bunga putih yang indah itu? Mereka tumbuh bersama, berdampingan, akar mereka saling terjalin, berbagi sinar matahari dan hujan yang sama.\"",
  str_voice_1600014_11 = "Tolong jangan menatap cermin terlalu lama. Meski aku dan saudariku di sini, rahasia yang terkandung dalam artefak ini tidak boleh dianggap remeh.",
  str_voice_1600014_12 = "Adik perempuanku dan aku... Meskipun kami kembar, kami sama sekali tidak sama. Aku selalu yang pendiam dan murung... Itulah sebabnya aku sangat merindukannya.",
  str_voice_1600014_13 = "Saya dan adik perempuanku terhubung secara tak terpisahkan. Mulai dari jiwa dan kenangan kami hingga Luminatics kami, kami berbagi dalam semua berkat kami, tetapi kami juga sama-sama menderita dari kekosongan pemisahan kami.",
  str_voice_1600014_14 = "Kakakku sangat menyukaimu... Hah? Jangan bilang kamu lupa tentang bunga yang dia berikan padamu? Dan jika kamu penasaran bagaimana aku tahu itu, itu karena kakakku dan aku terhubung dalam hati dan pikiran.",
  str_voice_1600014_16 = "Tolong jangan khawatirkan aku, saya merasa cukup istirahat sekarang.",
  str_voice_1600014_17 = "Maaf, tapi jika aku tersesat di cermin lagi, aku butuh kamu untuk membangunkanku dan membuatku tetap terjaga.",
  str_voice_1600014_18 = "Sepertinya barusan aku mendengar adikku memanggilmu.",
  str_voice_1600014_19 = "Aku di sini untuk mengganggumu, jelas. Anggap saja ini pembalasan karena menggodaku tadi.",
  str_voice_1600014_35 = "Cermin Geminos, bersama selamanya.",
  str_voice_1600014_36 = "Nepolis, pinjamkan aku kekuatanmu—",
  str_voice_1600014_37 = "Bunga putih mekar di salju hitam!",
  str_voice_1600014_38 = "Sebuah janji yang dibuat di depan cermin.",
  str_voice_1600014_39 = "Seperti sebuah puisi...",
  str_voice_1600014_40 = "Seperti sebuah fabel...",
  str_voice_1600014_44 = "Narcissus putih, lili, hyacinth, lili dari lembah... Oh, dan jangan lupa dandelion ini.",
  str_voice_1600014_58 = "Dunia di dalam cermin ini berbahaya, tapi untungnya, kamu ada di sini.",
  str_voice_1600014_59 = "Saya rasa saya melihat sisi yang sangat berbeda dari sang Ratu di dalam dunia cermin... Apakah itu rahasia antara kalian berdua?",
  str_voice_1600014_60 = "Kamu benar, tidak masalah lagi apakah dia adalah saudara kandungku atau hanya manifestasi dari kekuatan cermin.",
  str_voice_1600014_61 = "Saya memiliki peran saya sendiri dalam melindungi Northland, jadi saya tidak akan pernah menyerahkan kekuatan cermin.",
  str_voice_1600014_62 = "Aku menganggap diriku sebagai penjaga Lake Mirror, tapi aku tak pernah menyadari bahwa danau itu telah melindungiku sepanjang waktu.",
  str_voice_1600014_63 = "Apa sebenarnya yang ada di dalam cermin?",
  str_voice_1600014_64 = "Apakah dunia mimpi akan berbeda dari dunia di dalam cermin?",
  str_voice_1600014_65 = "Saya hanya berharap gaunku tidak basah.",
  str_voice_1600014_66 = "Apakah ini Kristal Es? Atau mungkin Chromera?",
  str_voice_1600014_67 = "Itu benar. Nepolis dan aku... kami akan selalu bersama.",
  str_voice_1600014_68 = "Seorang gadis misterius dan cermin yang lebih misterius lagi... Siapa sebenarnya kamu di dunia ini?",
  str_voice_1600014_69 = "Tidak... Bukan ingatanku... Nepolis!!!",
  str_voice_1600014_70 = "Yang Mulia Ratu melindungi aku... Begitu juga dengan sisterku, Nepolis!",
  str_voice_1600014_71 = "Lake Mirror... Mari kita tulis akhir dari puisi kita sekali dan untuk selamanya.",
  str_voice_1602411_1 = "Tidak adil jika hanya saya yang memiliki hati mekanis. Kenapa saya tidak membuatkan satu untukmu juga? Percayalah, ini luar biasa!",
  str_voice_1602411_2 = "Zoom! Lihat sejauh mana pesawat kertas saya bisa terbang! Keren, 'kan? Saya yakin bahkan bisa mengejar Colossus milikmu!",
  str_voice_1602411_3 = "\"Berikan aku kebebasan, atau berikan aku kematian!\" Itu salah satu kutipan favoritku. Selamat datang!",
  str_voice_1602411_4 = "Mengapa kita tidak melakukan sesuatu yang tidak biasa? Mungkin kita harus mencuri sesuatu dari Illumina... Atau lebih baik lagi, menyelinap ke Lumopolis dan merusak patung mewah mereka!",
  str_voice_1602411_5 = "Tidak ada yang bisa memberitahuku apa yang harus dilakukan karena aku yang memberi perintah di sekitar sini! Yah... Tidak ada kecuali Lady Victoria, tentu saja. Dia pada dasarnya tahu segalanya.",
  str_voice_1602411_6 = "Selama jantungku masih berdetak dan tubuhku masih bergerak, aku tidak milik siapa pun!",
  str_voice_1602411_7 = "Guk! Hahaha, apakah aku menakutimu? Jangan khawatir, aku tidak menggigit... Setidaknya tidak tanpa alasan yang baik!",
  str_voice_1602411_8 = "Pikir kau bisa mengajariku cara mengemudikan Colossus? Kita bergerak terlalu lambat! Aku bisa mendorongnya melebihi batasnya! Tidak? Oh, ayo, aku pikir kita adalah teman!",
  str_voice_1602411_9 = "Biarkan saya memberi tahu Anda sebuah rahasia kecil: Anda adalah jenis teman yang sempurna bagi saya. Anda peduli tentang saya tanpa selalu mencampuri urusan saya, jadi... Terima kasih untuk segalanya.",
  str_voice_1602411_10 = "Aduh, aku akan mulai menumbuhkan karang dari betapa pengapnya di sini...",
  str_voice_1602411_11 = "Saya, membantu Anda? Anda yang bekerja untuk saya! Aku akan terus mengawasi Anda, jadi jangan bermalas-malasan!",
  str_voice_1602411_12 = "Benar, aku ini infiltrator terkenal Illumina, dan pencuri berisik Lumopolis! Silakan, nikmati kehadiran legenda hidup ini di depanmu! Aku bisa menanganinya!",
  str_voice_1602411_13 = "Loyalitas sangat penting dalam persahabatan, jadi jika kamu pernah membutuhkan bantuan, Petey dan saya akan selalu ada untukmu! Kamu juga merasakan hal yang sama, bukan? Bagus! Jadi, bisakah kamu meminjamkan sedikit uang? Saya ingin membeli sesuatu.",
  str_voice_1602411_14 = "Pepita Felice hanyalah nama yang saya gunakan untuk menakuti orang. Sungguh menakjubkan betapa lebih baik orang memperlakukan Anda ketika Anda memiliki nama belakang yang terdengar mulia. Bodoh, bukan?",
  str_voice_1602411_15 = "Selamat ulang tahun, selamat ulang tahun! Bagaimana? Kamu menyukainya?",
  str_voice_1602411_16 = "Anda di sini tepat pada waktunya untuk petualangan baru yang luar biasa!",
  str_voice_1602411_17 = "Selalu siap sehingga kamu tidak pernah melewatkan kesenangan apa pun!",
  str_voice_1602411_18 = "Makanan yang paling enak adalah jenis yang kamu bagikan dengan teman!",
  str_voice_1602411_19 = "Semua hal menyenangkan cenderung terjadi sekitar waktu ini.",
  str_voice_1602411_20 = "Truth tidak mengikat siapa pun, itulah sebabnya Lady Victoria membiarkanku melakukan apa pun yang aku inginkan.",
  str_voice_1602411_21 = "Anjing-anjing Lumopolis terus mengejarku, dan elang-elang Illumina sangat licik. Lebih baik aku tetap waspada.",
  str_voice_1602411_22 = "Aku adalah Pepita, cahaya kebebasan dan anak dari The Truth!",
  str_voice_1602411_23 = "Sejujurnya, aku tidak keberatan bermain dengan mereka jika semuanya seasyik Ursura.",
  str_voice_1602411_24 = "Lady Victoria memberiku kunci kebahagiaan. Dia mengenalku cukup baik, tetapi masih sedikit terlalu pendiam sendiri.",
  str_voice_1602411_25 = "Ursura sama gilanya seperti saya, itulah sebabnya kami menjadi teman yang baik!",
  str_voice_1602411_26 = "Ahhh! Kamu guys membuat minuman yang luar biasa di Colossus!",
  str_voice_1602411_27 = "Terlalu banyak petugas Illumina di sekitar sini, menurutmu? Aku hampir tidak bisa bernapas karena semua ketegangan!",
  str_voice_1602411_28 = "Aku akan menggunakan Colossus untuk meledakkan siapa saja yang menghalangi jalanku! Haha, hanya bercanda! Santai sedikit!",
  str_voice_1602411_29 = "Baik, mari kita selesaikan perkenalan. Nama saya Pepita, dan tidak, saya bukan \"gadis itu\" atau \"makhluk kecil itu,\" tetapi Pepita. Pepita sang Pejuang.",
  str_voice_1602411_30 = "Lebih cepat! Lebih cepat!",
  str_voice_1602411_31 = "Hatiku terbakar!",
  str_voice_1602411_32 = "Pukulan ini tak pernah berhenti!",
  str_voice_1602411_33 = "Aku adalah nyala api yang menari!",
  str_voice_1602411_34 = "Pepi...TA!",
  str_voice_1602411_35 = "Jantungku berdetak semakin cepat!",
  str_voice_1602411_36 = "Darahku mendidih!",
  str_voice_1602411_37 = "Mekar dengan bebas!",
  str_voice_1602411_38 = "Ayo kita bakar dunia ini!",
  str_voice_1602411_39 = "Terbakarlah jadi abu!",
  str_voice_1602411_40 = "Waktunya untuk grand final!",
  str_voice_1602411_41 = "Serahkan saja pada Pepita yang hebat!",
  str_voice_1602411_42 = "Lihat? Kesempurnaan yang kacau.",
  str_voice_1602411_43 = "Ayo, kita pergi dari sini!",
  str_voice_1602411_44 = "S-Sebenarnya, aku sedikit takut ketinggian... Cuma bercanda! Haha, aku berhasil mengejutkanmu, bukan? Ahh, kamu harus melihat ekspresi wajahmu!",
  str_voice_1602411_45 = "Hei, ini tidak setengah buruk!",
  str_voice_1602411_46 = "Aku sangat menyukai ini!",
  str_voice_1602411_47 = "Mencoba mengolesiku lagi?",
  str_voice_1602411_48 = "Bagus, sekarang aku harus memberimu sesuatu sebagai balasannya!",
  str_voice_1602411_49 = "Seperti setiap orang lain di Illumina, masa kecilku cukup keras. Ayahku... Ugh, aku benci memanggilnya seperti itu. Pokoknya, pengecut itu alasan ibuku meninggal, dan juga mengapa aku berakhir di lab.",
  str_voice_1602411_50 = "Komite mengganti jantungku dengan yang buatan untuk mengendalikanku, tetapi aku masih berhasil melarikan diri. Kemudian, aku bertemu Lady Victoria dan berpetualang melalui Dark Zone sendirian. Belisaria salah... Aku bukan cacat.",
  str_voice_1602411_51 = "Tidak peduli apa yang terjadi, aku tak akan pernah menundukkan kepala pada siapa pun! Suatu hari nanti, aku akan merebut kembali hatiku, dan memburu pria yang telah mengkhianatiku!",
  str_voice_1602411_52 = "Taraa! Alchemy Stars!",
  str_voice_1602411_53 = "Hei!",
  str_voice_1602411_54 = "Anda bangun pagi.",
  str_voice_1602411_55 = "Aku mau makan siang!",
  str_voice_1602411_56 = "Saatnya membuat masalah!",
  str_voice_1602411_57 = "Ayo adakan pesta dansa gila untuk merayakan tahun baru! Oh, hampir lupa: Selamat Tahun Baru!",
  str_voice_1701103_1 = "Petualangan dalam mimpi itu menarik, bukan? Ingatlah untuk membawaku bersamamu di petualangan berikutnya, tetapi bukan jika itu untuk salah satu Pemburu Silent lainnya. Mimpi mereka mungkin akan terlalu gelap.",
  str_voice_1701103_2 = "Baiklah, sebagai hadiah untuk persahabatan kita yang telah lama, aku akan mendengar pengakuanmu sekarang... Hah? Kenapa kamu masih berdiri di sana? Aku tidak selalu punya waktu luang, jadi mulailah mengaku!",
  str_voice_1701103_3 = "Berhenti! Aku sudah tahu apa yang akan kamu katakan, dan jawabannya adalah tidak: hanya karena aku adalah \"Suci Perempuan yang Diam\" bukan berarti aku harus tetap diam sepanjang waktu. Gelar tidak dimaksudkan untuk diambil secara harfiah, lho.",
  str_voice_1701103_10 = "Hmm? Ada apa dengan ekspresi kosong di wajahmu itu? Jangan bilang... apakah aura suci saya membuatmu terdiam kagum?",
  str_voice_1701103_11 = "Ah, jadi Navigator yang perkasa akhirnya mengakui kehebatanku, dan datang untuk mencari nasihat bijakku! Apa itu? Kamu hanya butuh bantuan dengan pekerjaanmu? Ugh... Sungguh mengecewakan.",
  str_voice_1701103_12 = "Meski Northland adalah tempat yang dingin dan tidak ramah, orang-orang di sana selalu berjuang melawan angin dan salju. Saya bangga berperan sebagai penyelamat bagi orang-orang yang kuat dan pekerja keras seperti itu.",
  str_voice_1701103_13 = "Kawan-kawan dan saya telah melalui semuanya: badai salju yang mengaum, badai yang mengamuk, dingin yang ekstrem, dan serangan Eclipsite yang tak terhitung jumlahnya. Kehebatan dari jenis kita tidak terletak pada berkat dari yang ilahi, tetapi pada api yang tak pernah padam yang membakar di hati kita.",
  str_voice_1701103_14 = "Selama generasi, para Santa yang Pendiam telah membakar hidup mereka demi membantu orang lain, itulah sebabnya mereka tidak pernah hidup terlalu lama. Dibandingkan dengan mereka, saya telah menjalani hidup yang panjang dan bahagia meskipun saya baru berusia sembilan belas tahun!",
  str_voice_1701103_16 = "Masih berkeliling pada jam seperti ini, ya? Sepertinya bahkan Navigator hebat pun kesulitan membuat rencana sendiri. Sebagai orang yang lebih pintar dan matang di sini, izinkan aku membantumu.",
  str_voice_1701103_17 = "Biarkan aku tetap di tempat tidur! Aku sudah melakukan tugas-tugas kesucianku, sekarang tinggalkan aku sendiri!",
  str_voice_1701103_18 = "Aku akan pergi makan dengan setiap orang. Mau bergabung dengan kami? Adras yang memasak hari ini, tahu kan!",
  str_voice_1701103_19 = "Mengapa kamu masih berkeliaran seperti ini? Apakah kamu ingin mendengar dongeng pengantar tidur? Jika iya, pergilah tanya Cynthia.",
  str_voice_1701103_35 = "Bersiaplah untuk ledakan.",
  str_voice_1701103_36 = "Izinkan saya untuk turut campur.",
  str_voice_1701103_37 = "Dibersihkan oleh guntur!",
  str_voice_1701103_38 = "Biarkan semua menjadi diam—!",
  str_voice_1701103_39 = "Tunggangi badai!",
  str_voice_1701103_40 = "Perintahkan guntur!",
  str_voice_1701103_44 = "Jadi ini rasanya damai... Luar biasa.",
  str_voice_1701103_58 = "Petir! Dan kemudian, kesunyian!",
  str_voice_1701103_59 = "Pesta?! Di mana?!",
  str_voice_1701103_60 = "Mmm, ini satu-satunya alasan mengapa saya repot-repot datang.",
  str_voice_1701103_61 = "Ingin latihan bertarung sedikit, Navigator? Aku berjanji akan menahan tinjuku jika kau juga melakukannya.",
  str_voice_1701103_62 = "Freya, tombak terhebat dari Silent Hunters, telah tiba!",
  str_voice_1701103_63 = "Freya yang Sempurna telah tiba!",
  str_voice_1701103_64 = "Hah? Ke mana semua orang pergi?",
  str_voice_1701103_65 = "Aduh... Apakah benar-benar sejauh itu? Aku akan membawa kuda jika aku tahu itu.",
  str_voice_1701103_66 = "Oh, apa ini? Kejutan kecil yang indah. Sang hebat Freya dengan rendah hati menerima hadiahmu."
}
return config
